window.__ALLSYN=[{"id": "pe:两+乱", "n": "两·乱脉", "o": "两·乱脉总属脉气逆乱失常，非具体脉象。其核心病机为客寒闭阻脉络，气血流行失序，脉气逆乱上犯，病位在血分络脉。原文以“两脉逆乱”概括，症见肋痛、咳甚、冷汗、背寒、足冷、转侧不利，治在通络补虚、散寒行血。下属散乱脉则属危候，主元气败绝、胃气竭绝与气血亏虚至极，多因", "c": "主寒闭络脉"}, {"id": "pe:两+伏", "n": "两·伏脉", "o": "伏脉总起来主阳气虚陷、阴寒内盛与邪闭气机，其病机核心为阳气不能布达、脉道潜伏。从所收段落看，伏脉可见于寒痢日久转变虚寒，两尺全伏，证属肾阳衰微、阴寒内盛；亦见于胎动下紫血，两尺脉伏，证属积冷下焦、寒凝肝脉、邪闭气机；又主转脬虚闭，两脉沉伏，为阳气虚陷、气机闭阻", "c": "主寒盛阳衰"}, {"id": "pe:两+促", "n": "两·促脉", "o": "促脉总起来主阳盛热结、气血瘀滞、虚火阳浮及邪火阴涸四类病机。其核心为阳热亢盛，或实热结聚，或瘀热内蓄，或虚阳浮越，或热极阴伤。实热与瘀滞常并见，如蓄血证脉促而痛处拒按；虚火阳浮则因阴亏于下，阳浮于上，脉促数而无力；邪火阴涸为热盛劫津之危候，脉促疾无伦。四类之间", "c": "主阳盛热结"}, {"id": "pe:两+动", "n": "两·动脉", "o": "两·动脉总起来主邪气搏结、气血壅滞，其病机核心为实邪结聚，脉道拘急而动摇。原文两关脉动，因产后洗浴感寒，污血内停，寒凝血瘀，搏结中焦，故动脉主邪结壅滞与寒凝血瘀。然动脉与尺寸虚无并见，又示下元虚衰，本虚标实。故动脉所主，以实邪结聚为主，兼见本虚，三者相互关联：", "c": "主邪结壅滞"}, {"id": "pc:两+和+平", "n": "两·和平脉", "o": "两·和平脉在此段中表现为两尺脉沉绝而他脉平和，总起来主胎气上逆、气血壅塞于上而致下焦脉气一时不通。其核心病机非胎死，亦非全身虚损，而是妊娠期气机逆乱、上下阻隔的实证。两类病机相互关联：胎气上冲心是病本，气血壅塞于上是病机关键，两尺脉沉绝则是壅塞导致下焦脉道不通", "c": "主胎气上逆"}, {"id": "pe:两+和", "n": "两·和脉", "o": "两·和脉总起来主病势趋于缓和而余邪未靖、阴阳尚未全复之机。其核心在于脉象虽见平和，但症情未全平，提示邪气渐退而正未全复，或余滞未清、营卫未和。具体而言，脉两手已和而烦动恍惚欲晕，主阴亏阳浮、虚阳上扰；脉两寸未和，主上焦心营肺卫余滞未清；右脉软滑而虚、左脉浮弦且", "c": "主邪退脉和"}, {"id": "pe:两+坚", "n": "两·坚脉", "o": "坚脉总起来主邪实内结或药力搏激之象，其病机可归纳为两类：一为湿热壅结下焦，脉见两尺坚搏，因酒色不节、湿热日聚，久则肾阳被遏；二为气机下陷、药力搏激之虚实夹杂证，脉见尺寸极沉而关脉坚弦，因误用推荡，大气下陷而药力与下陷之气相争。两类病机虽异，但均以“坚”为脉象特", "c": "主湿热壅结"}, {"id": "pc:两+大+动", "n": "两·大动脉", "o": "两·大动脉总起来主内风动扰与心肾气虚，其病机核心为本虚标实。动脉厥厥动摇，是风阳扰动之象，多见于内风暗动、经络未通之证；而脉虚大参伍不调、歇至，则反映心肾气虚、脉行无力。两者可同时出现，如案中脉虚大而参伍不调兼两寸歇至，断为心肾气虚，并无风邪六经形证，说明虚为", "c": "主内风"}, {"id": "pc:两+大+实+坚", "n": "两·大实坚脉", "o": "两·大实坚脉总起来主邪盛正衰、脉症相反之危候。其核心病机为正气虚而邪气实，瘀血内结，故脉道充盈坚急。具体而言，实大坚脉既反映邪气壅盛（如瘀血、积块），又提示正气亏虚（产后气血不足而脉失柔和），二者并存形成脉症相反，故预后不良。各类病机相互关联：正虚是基础，邪实", "c": "主邪实"}, {"id": "pc:两+大+弱", "n": "两·大弱脉", "o": "两·大弱脉总属虚证，主气血不足、大虚之候。其脉象大而弱，大则为虚，弱为气血不足；兼见两尺涩小，涩主血少，小主气虚。从脉位看，寸关候上中焦，尺候下焦，今上下皆见虚象，故断为气血不足、大虚之证。具体而言，寸关大弱主脾胃虚衰，中焦运化无力；尺部涩小主下焦精血亏耗。三", "c": "主气血不足"}, {"id": "pc:两+大+洪", "n": "两·大洪脉", "o": "两·大洪脉总以热盛为核心病机，洪大有力为热邪鼓动气血、脉道充盈之象。其病位有在上焦、在中焦、在表里之异：寸洪大主上焦热壅，关洪大主热瘴，六脉洪大主热毒弥漫。兼滑则痰火互结，兼数则热急，兼尺沉微则上盛下虚、阳亢阴微。诸类皆由热邪炽盛所致，或兼痰、兼虚、兼毒，然总", "c": "主热盛"}, {"id": "pc:两+大+浮+洪", "n": "两·大浮洪脉", "o": "两·大浮洪脉总属有余实证，主风邪、积热、痰火相互搏结为患。浮脉主风邪在表，洪脉主积热内盛，两关滑大有力主中焦痰热壅盛。风邪外闭，痰火内郁，怒气相加，遂致迫血上逆而咳血，喘急碍卧。四类病机相互关联：风邪为外因，引动内蕴之痰火；积热与痰热搏结中焦，气机壅塞；实热迫", "c": "主风邪在表"}, {"id": "pc:两+大+浮", "n": "两·大浮脉", "o": "两·大浮脉总属阳气浮越、气机上升之象，所主病机可归为三类：气火上逆、肝郁乘脾、虚阳外浮。其共同基础为浮大脉反映阳气不能潜藏，或阳亢上冲，或郁而化火上逆，或虚阳外越。三者虚实不同：气火上逆多实，肝郁乘脾为虚实夹杂，虚阳外浮属虚。浮大脉需结合部位与兼脉辨虚实，寸浮", "c": "主气火上逆"}, {"id": "pe:两+大", "n": "两·大脉", "o": "大脉总以邪气亢盛、脉道充盈为核心，但所主病机有寒热虚实之辨。其常见者，为热邪炽盛，气血鼓动，脉体宽大，见于温病气分、营分及脏腑积热。若大脉见于寸部，多主上焦邪实，或清邪中上，或郁热犯肺。兼滑兼弦，则主痰火壅盛，或肝阳化火上扰。见于关尺，则主冲气上逆，或热陷少阴", "c": "主热盛"}, {"id": "pc:两+大+虚", "n": "两·大虚脉", "o": "两·大虚脉总起来主正气亏虚，尤以气分不足、暑热伤气、心肾气虚及虚寒为要。其脉象虽大而按之虚软，故与实热壅盛之洪滑有力相鉴别。从所收四段看，虚大脉可单独出现，主气分不足或暑热伤气；亦可与弦大、洪滑并见，提示虚中夹实，如肝火亢盛兼气分不足、痰火壅盛而正虚。若虚大而", "c": "主暑热伤气"}, {"id": "pe:两+实", "n": "两·实脉", "o": "实脉总主邪气盛实，以实热壅盛为核心病机。其脉形洪大坚实，按之有力，为热邪内迫、气血涌盛之象。实脉所主，或为实热壅盛于上焦，如两寸甚实之牙疼、两寸实数之嗽热；或为胎孕气血壅盛，如两尺皆实之经闭似痨。各类之间，皆以“实”为共同特征，示邪盛或气血壅滞，非虚证。实热壅", "c": "主实热壅盛"}, {"id": "pc:两+小+弱", "n": "两·小弱脉", "o": "两·小弱脉总起来主正气亏虚，尤以津液元气俱伤为核心。其脉象小弱虚细，右脉小弱偏于元气亏虚，左脉虚数偏于阴液不足、虚热内扰。三者相互关联：过用克削为病因，津液元气俱伤为病机本质，虚热内扰为继发表现。小弱脉不主实邪，而主虚损，故原文见“克削过甚”后脉转小弱虚数，症", "c": "主津液元气亏虚"}, {"id": "pe:两+小", "n": "两·小脉", "o": "两·小脉总起来主虚，以正气亏虚、脉道不充为基本病机，具体可兼阳虚、虚损、寒饮、虚热、气逆等不同侧重。小脉形态为脉体细小，主阳微、血少、气弱，故凡阳气不足、气血两虚、津液耗伤者皆可见之。从原文看，小脉或见胃阳虚浊阴上干，或见少阴久虚，或见寒饮内结，或见阴虚内热，", "c": "主阳虚"}, {"id": "pe:两+平", "n": "两·平脉", "o": "两·平脉总起来主病势向愈、邪退正复之象，但须结合症舌辨其真伪。第2314段脉渐平见于高热减、疹色淡之后，为热退脉和之佳兆，然余热未清、肠腑燥结，故脉平而症未全消；第17891段两寸关脉如弦，虽近于平，实主邪热内郁、津伤风动，非真和平。可见平脉有吉有凶：一则标志", "c": "主热退脉和"}, {"id": "pc:两+弦+和", "n": "两·弦和脉", "o": "两关弦劲不和脉总属肝胃同病，以肝气横逆为核心，兼见胃络受伤、气火上逆及肝营虚损。弦劲为肝气失和之象，关部候肝胃，故脉见两关弦劲不和，提示肝气横逆犯胃，胃络受损，气火上逆则咳呛胁痛，失血后肝营自虚，而脉仍弦劲，示肝阴不足、气火未平。四类病机相互关联：肝气横逆为始", "c": "主肝气横逆"}, {"id": "pc:两+弦+坚", "n": "两·弦坚脉", "o": "两·弦坚脉在此案中总主气机下陷、药力搏激之虚实夹杂证。其脉象尺寸极沉，反映大气下陷、气不达外；关脉坚弦有力，则因误用二陈推荡，药力与下陷之气相争而搏激于关部。故其病机核心为虚陷为本、搏激为标，非实热内结。三类病机相互关联：气陷是基础，药力搏激是诱因，虚中夹实是", "c": "主气陷"}, {"id": "pc:两+弦+大", "n": "两·弦大脉", "o": "两·弦大脉总起来主肝火亢盛、暑热伤气、痰火壅盛及邪热内伏。弦大为肝火亢盛，虚大为暑热伤气，洪滑为痰火壅盛，弦大按之不足为邪热内伏。各段均见弦大，但兼脉不同，病机有异：左脉弦大主肝火，右脉虚大主暑热伤气，两关洪滑有力主痰火，两关弦大按之不足主邪热内伏。其共同点为", "c": "主肝火"}, {"id": "pc:两+弦+小", "n": "两·弦小脉", "o": "两·弦小脉总起来主气逆、疼痛、正虚，并涉及寒逆与肝胃不和。弦脉主气机郁滞、逆乱，故见气从脐下上冲、肝胃气痛；气逆搏结则痛，故弦亦主痛。小脉主正气不足，或肾阳式微，或脾土久亏，故见精神疲倦、虚浮。弦小并见，提示虚实夹杂：正虚为本，气逆为标，或寒邪上冲，或肝胃不和", "c": "主气逆"}, {"id": "pc:两+弦+微", "n": "两·弦微脉", "o": "两·弦微脉总起来主气郁、木旺与痰湿内阻。弦脉为气机郁滞或肝木偏旺之征，微弦则郁而不甚；兼滑则主痰湿，尤见于尺部提示下焦痰湿或肾气不和。原文服养胃丸不应，说明病机非单纯胃虚，而是肝脾气滞与痰湿内阻相互影响，久病不愈。三类病机中，气郁与木旺常相兼，痰湿又易阻滞气机", "c": "主气郁"}, {"id": "pc:两+弦+沉", "n": "两·弦沉脉", "o": "两·弦沉脉总起来主里、主肝郁气滞、主寒凝、主血滞。沉为里脉，示病位在里；弦为肝脉，主肝郁气滞与寒凝。二者相合，反映病在里而气机郁滞，常因肝郁气滞导致血行不畅，或寒凝肝脉、气血凝滞。原文'沉主里、主水，弦主肝郁气滞、寒凝'，结合癸涩迟滞、腹中㽲痛、带下等症，可知", "c": "主里"}, {"id": "pc:两+弦+浮", "n": "两·弦浮脉", "o": "两·弦浮脉总起来主邪在少阳、枢机不利之病机。浮为邪在表，弦为少阳主脉，二者相合，反映外邪客于少阳半表半里，正邪分争，故见寒热间日而作、头胀而痛、咳逆胸闷等症。其兼苔白厚者，又示湿浊内蕴，表邪与湿浊相合为患。下属数弦浮脉则进一步扩展为风阳内煽、燥伤肺津、液亏风动", "c": "主少阳邪郁"}, {"id": "pc:两+弦+涩", "n": "两·弦涩脉", "o": "弦涩脉总属气滞血瘀、虚实夹杂之候。弦为气机郁滞，涩为血行不畅，两脉合见，提示气血交病，气滞与血瘀互结。所主病机主要有四类：血瘀、气滞、虚损、络阻。血瘀与气滞常相因为病，气滞则血瘀，血瘀加重气滞；虚损多为本虚，如肾虚精亏、血虚不荣，常与瘀滞并存，形成本虚标实；络", "c": "主血瘀"}, {"id": "pc:两+弦+滑+沉", "n": "两·弦滑沉脉", "o": "两关沉滑带弦脉，总属肝胃同病、痰火内结之候。沉主里，提示病位在里；滑主痰，示痰浊内蕴；弦主肝郁，为肝气郁结、疏泄失常。三者相合，反映肝气郁于胃中，不得条达，进而化火炼津为痰，痰火纠结于中。其病机核心为肝郁气滞、痰火内结，涉及肝、胃两脏。四类病机相互关联：肝郁为", "c": "主肝郁"}, {"id": "pc:两+弦+滑", "n": "两·弦滑脉", "o": "弦滑脉总属气郁痰凝、虚实夹杂之象。弦主肝郁气逆，滑主痰湿内壅，二者相合，多主痰气交阻为患。其病机类别虽多，然核心在于肝郁与痰湿相互搏结：或痰湿内阻中焦，或肝气横逆犯胃，或痰火内扰心神，或风痰阻络，或痰气交阻而成噎膈，或疟病湿痰蕴结。各证之间常相互转化，如肝郁化", "c": "主痰湿内阻"}, {"id": "pc:两+弦+滑+虚", "n": "两·弦滑虚脉", "o": "两脉虚弦而滑，总属本虚标实、虚实夹杂之候。虚脉揭示产后真阴未复、气血不足之本虚；弦脉提示肝阳化风，滑脉提示脾湿化饮，二者为标实。三脉并见，说明在产后虚损基础上，肝风与脾湿交杂为患，故证情迭出、变幻无常。虚为病之本，风、湿为病之标，治当缓图，标本兼顾。", "c": "主虚"}, {"id": "pc:两+弦+硬", "n": "两·弦硬脉", "o": "弦硬脉总起来主阴血亏虚、气失柔和，以及肝郁化火、气逆亢盛两类病机。其脉象弦而硬，失去柔和之性，既可见于虚证，如脾虚气陷、久泻伤阴，阴亏不能涵阳，虚阳外露，胃气不柔；也可见于实证，如肝郁化火，气火亢盛，横逆犯胃。两者虽虚实不同，但共同点在于'硬'，反映脉气失和、", "c": "主阴虚阳浮"}, {"id": "pc:两+弦+紧", "n": "两·弦紧脉", "o": "两·弦紧脉总属寒邪与气机郁滞相合为患，主要见于瘴疟及寒束之证。弦为少阳之脉，主气机郁滞、枢机不利；紧为寒脉，主寒邪收引、凝滞气血。二者相合，揭示寒邪外束或内客，致少阳枢机不利、气机郁滞，正邪交争于半表半里，故原文以“弦而紧”为瘴疟之脉。其下属弦细紧脉更兼细象，", "c": "主瘴疟"}, {"id": "pc:两+弦+细+涩", "n": "两·弦细涩脉", "o": "两关弦细涩脉总属肝脾同病、虚实夹杂之候。弦主肝旺，细主不足，涩主湿滞，三脉合见，提示肝气偏亢而肝血不足，脾虚湿聚成痰，进而荣卫不利。其病机核心为肝旺脾湿、气血亏虚，形成本虚标实之局：肝旺与湿痰为实，细脉不足为虚，荣卫不利为气血失和之果。诸类之间相互关联，肝旺克", "c": "主肝旺"}, {"id": "pc:两+弦+细+紧", "n": "两·弦细紧脉", "o": "两·弦细紧脉总属阴寒内盛、痰饮阻滞、血虚夹杂之候。弦主痛主饮，细为血虚，紧为寒，三脉相合，揭示寒邪内盛、痰饮内停、气血不畅且阴血亏虚的复杂病机。原文患者中寒痰饮，产后十年不孕，下血胎脉不现，误服凉药后腹胀不食、冷痰上壅，脉更沉小，示寒饮内结、阳气衰微。弦细紧脉", "c": "主寒"}, {"id": "pc:两+弦+细", "n": "两·弦细脉", "o": "两·弦细脉总起来主肝旺脾虚、正虚邪恋、阴血不足、气滞血涩、暑湿郁遏及寒痰饮阻等病机。弦脉主肝旺、气郁、邪郁及饮痛，细脉主营血不足、阴伤及正虚，两脉相合，多示虚实夹杂、本虚标实之局。各段所主虽异，然其核心不离肝木偏亢与阴血亏虚并见，或兼脾虚湿滞、或兼邪郁少阳、或", "c": "主肝旺脾虚"}, {"id": "pc:两+弦+细+虚", "n": "两·弦细虚脉", "o": "两·弦细虚脉总起来主体虚受邪、正虚邪恋之证。其脉弦主邪郁少阳，两尺虚细主肾气亏虚，弦细虚并见则反映正虚邪恋、虚实夹杂的病机。原文以体虚受邪、寒热久羁、苔白腰痛为据，指出虚人外感，邪郁少阳而肾气不足，故治宜补中益气汤加减以扶正祛邪。三类病机相互关联：邪郁少阳为标", "c": "主邪郁少阳"}, {"id": "pe:两+弦", "n": "两·弦脉", "o": "两·弦脉总起来主肝郁气滞、木乘土位、痰饮内阻、虚中夹实、热郁风动及痛证。弦为肝脉，主气郁、木旺、筋病、痛证，故其核心病机在肝胆气机失调。各类之间相互关联：肝郁气滞为基本，气郁则木乘土位，克犯脾胃；气滞津凝则生痰饮；痰气郁久化热则热郁风动；病久正伤则虚中夹实；气", "c": "主肝郁气滞"}, {"id": "pc:两+弦+虚", "n": "两·弦虚脉", "o": "两·弦虚脉总起来主正虚邪恋、虚实夹杂之候。虚脉揭示气血营卫不足、脾肾亏虚之本，弦脉提示肝木偏旺或邪郁少阳之标。具体而言，或见脾土不足、肝木乘之，而致胸脘胀闷、寒热往来、先血后粪；或见肺肾俱虚、营卫两亏，而致久咳遗泄、劳瘵已成；或见产后真阴未复、肝风脾湿交杂。各", "c": "主脾虚肝乘"}, {"id": "pc:两+弦+长", "n": "两·弦长脉", "o": "两关脉弦长，总起来主肝胃阳亢、痰火内蕴之病机。弦为肝旺，长为阳热有余，两关候肝胃，故脉象直接反映肝阳与胃阳亢盛，气火有余。原文谓‘五火燔燎，而肝阳胃阳尤甚’，动怒抽掣为肝病，食辛香厚味即病至为胃病，说明肝胃火盛是核心病机。痰火根深由火盛炼液而成，三者相互关联：", "c": "主肝阳亢盛"}, {"id": "pc:两+弱+短", "n": "两·弱短脉", "o": "两寸弱短脉总以气虚为本，尤主上焦心肺元气不足。其脉短弱无力，寸部独显，故多责之肺气亏虚、心气不足。然气虚可生湿痰，可致虚热，可陷下焦，可乱神明，故兼脉不同而病机各异：兼关滑尺洪滑者，为湿痰下流；兼数而无力者，为气阴两虚、虚热内生；兼关弦尺洪滑者，为气虚血热下陷", "c": "主湿痰"}, {"id": "pc:两+弱+缓", "n": "两·弱缓脉", "o": "两关缓弱脉总主脾阳式微、中焦聚湿，兼尺脉动下垂主肾阴衰、固摄失司。其病机核心为脾肾同病、上下交损：上中焦因脾阳微而湿聚少运，下焦因肾阴衰而封藏失职。缓弱脉本身反映阳气不足与湿浊内阻，关部独显提示病位在脾胃；尺脉动而下垂则揭示肾阴亏虚、固摄无权。诸类病机相互关联", "c": "主脾阳微"}, {"id": "pe:两+弱", "n": "两·弱脉", "o": "弱脉总属虚象，以正气亏虚为核心，尤以气虚、血少为基础。其脉来软弱无力，反映脉道不充、鼓动无力。所主病机可归纳为：气虚（心肺元气不足、大气下陷）、血少（失血、精血亏虚）、肾虚（下元虚惫、封藏失职）、脾虚湿聚（脾阳式微、中焦不运），此四类为虚证之常。若弱脉兼滑、涩", "c": "主肾虚"}, {"id": "pc:两+弱+软", "n": "两·弱软脉", "o": "弱软脉总属虚象，以气血不足、心肺气虚为核心，可扩展至脾肾亏虚及虚中夹滞。其脉来软弱无力，多因气血耗伤、脉道不充，或久病胜气亏虚所致。寸部软弱尤主心肺气虚，常见气满汗出、不寐、食减；两手软弱无力则主气血两虚、脾肾亏虚，见吐血、血崩、腰痛、耳鸣、小溲不禁。若虚中夹", "c": "主气血两虚"}, {"id": "pc:两+微+伏", "n": "两·微伏脉", "o": "两·微伏脉在喉痹辨证中具有双重意义。浮洪而溢之脉主火盛，因寸候上焦，浮洪为君相二火独盛、热正络，故见喉痹及嗌干、嗌痛、喉肿、舌本强等症，原文以“火”一字括其因，并分君火势缓、相火势速。微而伏之脉则主阳衰，阳气衰微、伏匿不显，正不胜邪，故为死证。两类病机一实一虚", "c": "主火盛"}, {"id": "pc:两+微+弱", "n": "两·微弱脉", "o": "两·微弱脉总起来主正气虚衰，尤以胸中大气虚陷为核心。所举段落中，患者素日气虚、短气，劳力后寸脉微弱而尺有根，断为大气下陷、不能斡旋全身，故脉微弱既主气虚，又主气陷。二者相互关联：气虚为根本，气陷为气虚之甚，因虚致陷，陷则升举无力，故见四肢痿废、呼吸益短。脉象上", "c": "主气虚"}, {"id": "pc:两+微+涩", "n": "两·微涩脉", "o": "两·微涩脉总起来主阳气衰微、阴血滞涩之病机，其核心为阳衰阴逆与气血涩滞。微为阳气衰微，涩为阴血滞涩、阳气不运，故脉见微涩多提示阳气欲尽、浊阴冲逆之危候，如呕吐发呃下利、大便滑溏等；亦可因胃阳虚而浊阴上干，见呃逆气冲。此外，微涩与两寸独大并见时，又反映本虚标实、", "c": "主阳衰阴逆"}, {"id": "pe:两+微", "n": "两·微脉", "o": "微脉总属阳气衰微、正气亏虚之象。其脉来微弱如丝，按之欲绝，主阳气衰微、气血不足。所主病机主要有四：一为阳衰，阳气不能鼓动血脉，故脉微；二为虚损，气血阴阳亏虚，脉道不充；三为气陷，大气下陷、血脱气散，脉微而寸关独见；四为虚阳上浮，阳衰于下而虚阳外越，脉微与洪大而", "c": "主阳衰"}, {"id": "pe:两+急", "n": "两·急脉", "o": "两·急脉总起来主气机逆乱、郁火攻冲及寒热错杂之证。其核心病机为'急'，即脉势急迫，反映气逆、火亢或痛甚。具体而言：情志抑郁化火，肝阳上亢则左关急；气逆攻冲则呃逆呕吐；寒积冷痛则脉紧急；湿热壅阻、寒热互结则成关格危候；血脱气散、大气下陷则脉急而微。各类之间以'气", "c": "主肝郁化火"}, {"id": "pc:两+散+乱", "n": "两·散乱脉", "o": "散乱脉总属危候，主元气败绝、胃气竭绝与气血亏虚至极。其形成多因产后气血未复，复加食滞、怒气，吐泻交作，使元气暴脱，胃气衰败，脉气失根而散乱如解索。原文两段均描述同一病案：初诊脉皆软弱，为气血亏虚之常；后因食菱栗、激怒气，吐泻交作，脉转为散乱如解索状，神气惫而恍", "c": "主元气败绝"}, {"id": "pe:两+散", "n": "两·散脉", "o": "散脉总属虚候，主气血阴阳亏虚及元气败绝。其形成机理为气血亏虚，脉道失充，或阴阳衰败，脉气失根，故脉来浮散无根，至数不齐。所主病机主要有四类：气血大虚、阴阳欲脱、元气败绝、气阴两伤。其中气血大虚与阴阳欲脱常并见，多见于高年气血已亏、疮疡脓血大泄之后；元气败绝则见", "c": "主气血大虚"}, {"id": "pc:两+数+促", "n": "两·数促脉", "o": "两寸促数脉总起来主虚火、阴虚与阳浮三类病机，三者相互关联：根本在于胃阴亏虚，阴不制阳，导致虚阳浮越而上炎心肺，故寸部脉促数。促为阳脉，数主热，但此热非实火，乃虚热；患者形体日损、咳嗽吐痰、少纳胃衰，正是阴亏于下、阳浮于上的表现。因此，该脉所主以虚证为纲，虚火与", "c": "主虚火"}, {"id": "pc:两+数+大+洪", "n": "两·数大洪脉", "o": "两·数大洪脉总属阳热亢盛之象，所主病机以热为核心，可概括为热盛、毒热内陷、阴火旺、湿火入络四类。洪大主热盛气分，数主热急，二者相合，提示热邪炽盛、气血壅滞。实热证中，或为外毒内陷、正邪交争，或为湿火入络、热壅局部；虚热证中，则为阴亏火旺、相火妄动。四类病机虽虚", "c": "主毒热内陷"}, {"id": "pc:两+数+大", "n": "两·数大脉", "o": "两·数大脉总属邪热亢盛之象，所主病机以热盛、邪实、热陷惊闭为核心。数脉主热，大脉主邪盛，二者相合，提示热邪炽盛、气血壅滞、正气未衰。实热证中，或为暑湿热邪蕴结肠道，或为表里俱热、积蒸于里，或为食滞中焦、腑气不通，甚则邪入营分、热扰神明、动风惊闭。各段均见数大脉", "c": "主热盛"}, {"id": "pc:两+数+实", "n": "两·数实脉", "o": "两·数实脉总以实热壅盛、邪壅上焦为核心病机。数脉主热，实脉主邪盛，两寸候上焦心肺，故两寸实数并见，主上焦实热壅遏。原文见微热而嗽，且热发于夜，是热郁上焦，入夜阴气当降而热不降，故发夜热与嗽。实数并见，说明非虚热，乃实热为患。其下属更具体脉两·数洪实脉，总述以辨", "c": "主热盛"}, {"id": "pc:两+数+小", "n": "两·数小脉", "o": "两·数小脉总属阴虚内热、津伤化燥之候。小脉主营血不足，数脉主热，二者相合，多为阴血亏虚，虚热内生。原文见苔转微白、尖边尚红，呛咳音嘶，乃热灼肺津，金失濡润，故虑防涸阴。其病机核心为阴分不足，虚热扰灼，津液受损，甚则有涸竭之虞。两类病机相互关联：阴虚生内热，热灼", "c": "主阴虚内热"}, {"id": "pc:两+数+弦+浮", "n": "两·数弦浮脉", "o": "两·数弦浮脉总起来主风阳内煽、燥伤肺津、液亏风动三类病机。左脉浮弦且数，为风阳内煽之直接脉征；右脉软滑而虚，示燥伤肺津、治节不行；两脉合参，则见上下交虚、液亏风动之整体病机。三者相互关联：燥伤肺津为病之始，液亏则风阳易动，风阳内煽又进一步烁津耗液，形成恶性循环", "c": "主风阳内煽"}, {"id": "pc:两+数+弦+滑", "n": "两·数弦滑脉", "o": "两·数弦滑脉总属肝郁化火、痰火内扰之候。弦为肝郁，数主火盛，滑主痰郁，三脉相合，揭示木火体质或情志郁结之人，肝气易升，郁而化火，火挟痰浊上扰为患。其病机核心在“木火无制”：或风火挟痰上蒙清窍而眩冒心悸，或郁火挟痰上攻咽胸而气逆不利，或血虚风动而手足蠕动。诸类之", "c": "主肝郁化火"}, {"id": "pc:两+数+弦", "n": "两·数弦脉", "o": "两·数弦脉总以弦为肝气郁结、气机不畅，数为热盛火郁，故其主病机以肝胆气火为中心，旁及少阳、阴虚、痰湿、积郁及寒热错杂。诸类关系：弦数并见，最直接主少阳热郁与肝火风动，为邪郁少阳或木火偏亢之常；若阴液亏虚，则火不潜而见阴虚火旺，甚则阴竭阳亢而预后不良；若兼痰湿，", "c": "主少阳热郁"}, {"id": "pc:两+数+洪+实", "n": "两·数洪实脉", "o": "两关脉象总以辨瘴为核心，随邪之寒热虚实而变。洪大、数甚主热盛，为热瘴；弦紧主疟，为瘴疟；浮紧、浮缓主表，为外感轻证；洪数按之不实主阳浮阴闭，为热浮阴凝；沉微而弱主虚寒，为阳衰阴盛。诸类脉象虽异，皆围绕瘴邪为患，或热盛，或寒束，或表邪，或内闭，或虚寒，反映了瘴病", "c": "主热盛"}, {"id": "pc:两+数+洪", "n": "两·数洪脉", "o": "两·数洪脉总属阳热亢盛之象，所主病机以热为核心。洪为热盛，数为热急，二者相合，提示热邪炽盛、气血壅滞。其具体病机可概括为三类：一为热盛，表现为夜躁不寐、热盛烦渴、癍疹未透等气分热炽之征；二为阳明热结，时疫邪蕴阳明，见烦渴、昏谵不寐，脉洪数，为邪欲外发发癍之兆；", "c": "主热盛"}, {"id": "pc:两+数+浮+洪", "n": "两·数浮洪脉", "o": "两关脉浮洪近数，总属阳热亢盛之候。浮为热越于外，洪为热盛于内，数则热势急迫。其病机以热盛为核心，可兼痰热内扰，因热灼津液而致津伤。原文见寒热、躁渴、呕吐痰多、便闭、溺赤、夜梦不安，皆热盛之变。热盛则脉浮洪，痰热上扰则呕吐昏闷，津伤则渴甚便结。三者相互关联：热盛", "c": "主热盛"}, {"id": "pc:两+数+滑+洪", "n": "两·数滑洪脉", "o": "两·数滑洪脉总属痰火实热之象。洪为有余，滑主痰，数主热，寸脉候上焦，故其病机核心为痰火壅盛于胸膈。四类中，主痰、主热分述痰与热之偏盛，主痰火壅盛则合论痰热交结，主补塞致滞则点明误补后痰火愈滞之变。诸类相互关联：痰为热之载体，热为痰之动因，补塞则助痰碍气，使痰火", "c": "主痰"}, {"id": "pc:两+数+滑", "n": "两·数滑脉", "o": "两·数滑脉总主痰、湿、热邪内蕴，以实证为主。滑脉主痰湿积滞，数脉主热邪亢盛，合而常见湿热壅盛、痰热互结、痰积内停、热毒壅结等病机。原文18段中，湿热证多见于痢疾、痛痹、带下；痰热证多见于胃痛、喘嗽、胸中冲跳；痰积证强调痰积甚固、壅滞中焦；热毒证见便秘、面赤龈胀", "c": "主湿热"}, {"id": "pc:两+数+濡", "n": "两·数濡脉", "o": "两·数濡脉总以湿、热、虚三者交织为病机核心。濡主湿，数主热，合之则湿热内蕴，见于湿滞中焦、脾运失职之证；若数而无力，则又主元气虚馁、虚阳浮动，常见脾阳久虚、聚湿生痰。此外，濡数可主湿温病阴伤，因伏温熏蒸、阴液耗损；若兼滑数无力，则主痰热而气阴不足。四类病机相互", "c": "主湿热"}, {"id": "pc:两+数+细+沉", "n": "两·数细沉脉", "o": "两·数细沉脉总属邪陷正虚、闭窍伤阴之候。沉为邪陷于里，数为热郁不解，细为阴液耗伤，三者相合，反映暑症复发后寒药遏邪太过，虚邪内舍神明之室，热闭心包而阴液已耗。其病机以邪陷为始，热郁为因，阴伤为果，闭窍为急，四者相互交织：邪陷则热郁于内，热郁则阴伤，阴伤则窍闭。", "c": "主邪陷"}, {"id": "pc:两+数+细", "n": "两·数细脉", "o": "两·数细脉总属阴液亏虚、虚热内扰之候。细主阴血不足、脉道不充，数主虚火内炽，二者相合，反映阴虚为本、火旺为标的基本病机。所主病机可归为五类：阴虚火旺为总纲，肺肾阴亏、劳损虚怯、五志火灼、肾痹水衰为具体分证。肺肾阴亏侧重水亏火炎、金水两伤；劳损虚怯示久病阴耗、渐", "c": "主阴虚火旺"}, {"id": "pe:两+数", "n": "两·数脉", "o": "数脉总主热，为热邪鼓动血脉所致，其病机以热盛为核心，但兼脉与部位不同，所主有别。数而有力，多实热、火盛，如热蕴三焦、温邪入营、心火刑金、肝火亢盛、肺热壅盛、胃肠积热；数而兼滑，主痰湿、湿热、痰热互结；数而兼细或无力，主阴虚火旺、气阴不足；数见于尺部兼积块，主瘀", "c": "主热盛"}, {"id": "pc:两+数+虚", "n": "两·数虚脉", "o": "两·数虚脉总属正气亏虚、津液耗伤而兼虚热之候。其脉虚细小数，小弱无力，非实热实邪。原文因湿温误用攻下，克削过甚，致津液元气俱伤，故脉见虚数。虚为本，津伤为虚之具体，虚热为虚所生之变，三者相因：元气亏虚则脉小弱，津液耗伤则舌燥无津、手指蠕动，阴不制阳则虚数。故其", "c": "主虚"}, {"id": "pc:两+沉+伏", "n": "两·沉伏脉", "o": "两·沉伏脉总起来主阳气虚陷、气机闭阻之「虚闭」证。原文以「转脬虚闭，两脉沉伏」为据，指出沉伏之脉非实邪壅盛，乃阳气虚陷、气机闭阻于下，膀胱气化不行所致。其核心病机为虚与闭并存：阳气虚陷为本，气机闭阻为标，二者互为因果，形成虚闭之象。故治疗以温肾助阳、通利小便为", "c": "主阳虚气陷"}, {"id": "pc:两+沉+小", "n": "两·沉小脉", "o": "两·沉小脉总属阴寒内盛、阳气衰微之候。沉主里主寒，小主阳微，故其病机核心为寒饮内结与阳气衰微。原文中患者中寒痰饮，误服凉药后脉更沉小，伴腹胀不食、冷痰上壅，显系寒饮内结、阳气衰微；又见产后十年不孕、下血胎脉不现，脉弦细紧，细为血虚，紧为寒，弦主痛主饮，故兼血虚", "c": "主寒饮内结"}, {"id": "pc:两+沉+微+弱", "n": "两·沉微弱脉", "o": "两·沉微弱脉在抽样段落中仅见“沉微而弱”一象，原文直断为“虚寒”，故其总病机为阳气衰微、阴寒内盛。沉为里、为阴，微为阳衰，弱为气血不足，三象相合，反映正气虚馁而寒邪内侵。此脉与同段洪大、数甚、弦紧、浮紧、浮缓、洪数按之不实等脉并列，诸脉随邪之寒热虚实而异，而沉", "c": "主虚寒"}, {"id": "pc:两+沉+微", "n": "两·沉微脉", "o": "两·沉微脉总属阳气衰微、阴寒内盛，兼见气血不足。沉为里、为阴，微为阳衰，两尺候肾与命门、胞宫，故其病机核心在肾阳亏虚、阴寒内伏。抽样两段中，一者见形肥色淡紫、艰于育子，脉证合参为肾虚血亏、冲任失养，法当补血益气；一者以“两尺脉沉微”为用药指征，主六腑沉寒、回三", "c": "主肾虚血亏"}, {"id": "pc:两+沉+涩+结", "n": "两·沉涩结脉", "o": "两·沉涩结脉总起来主里、主气血虚滞、主邪气内结，尤多见于产后虚实夹杂之证。沉为里，涩为血少气滞，结为邪气内结，三脉合见，提示病位在里，正气已虚而邪气内结，属虚实夹杂之候。原文以产后气血虚为本，胎前伏邪内结为标，故脉沉涩兼结；误补则敛邪，脉更不舒，透邪散结则脉稍", "c": "主里邪内结"}, {"id": "pc:两+沉+紧", "n": "两·沉紧脉", "o": "沉紧脉总属寒邪为患，其病机核心为寒凝气滞、邪闭不通。沉主里，紧主寒主痛，坚搏有力示邪实。原文'沉紧主寒'为总纲，寒邪内盛则气血凝滞，不通则痛，故主痛；寒凝下焦，邪闭于内，脉气沉伏，故主邪闭；孕妇下焦冷极，胎失温养，故主胎伤。四类病机相互关联：寒为根本，痛、闭、", "c": "主寒"}, {"id": "pc:两+沉+结", "n": "两·沉结脉", "o": "两·沉结脉总起来主里、主寒凝气滞、主实邪内结，病位多偏下焦。沉为在里，结为气机阻滞、邪气聚结不散，二者合见，提示病邪在里而气血不通。原文以寒疝为例，见脐下上至心胀满攻痛、胁疼尤甚、呕吐烦懑，断为寒在下焦，脉两手沉结不调，正合寒实积于下焦、气血不通之机，故治以温", "c": "主寒凝气滞"}, {"id": "pe:两+沉", "n": "两·沉脉", "o": "两·沉脉总属里证，以病位在里为纲，然所主病机有虚实寒热之异。沉而无力多主里虚寒，如肾阳不足、下焦虚寒、气化不行；沉而气陷或闭阻，则主气机郁闭，如大气下陷、虚闭不通；沉兼暑湿郁遏，为邪阻阳气不伸，病位虽在表而脉见沉；沉取细数或浮大，又主肾虚火动、水衰火旺。诸类之", "c": "主里虚寒"}, {"id": "pc:两+沉+迟", "n": "两·沉迟脉", "o": "沉迟脉总属阴寒内盛、阳气衰微之象。沉主里，迟主寒，脉来沉迟，多因寒邪内侵或阳气虚衰，致气血运行迟缓。其所主病机主要有寒、痰饮、阳虚、血虚四类，四者常相互兼夹：寒邪内盛可凝津为痰饮，痰饮内阻又伤阳气，阳虚则寒凝更甚，久病及血则血虚寒凝。原文以‘中寒痰饮’为核心，", "c": "主寒"}, {"id": "pc:两+洪+实", "n": "两·洪实脉", "o": "洪实脉总属邪热亢盛、正气未衰之实热证。其脉形洪大而按之坚实，为热邪内迫、气血涌盛之象。原文以'脉象洪实者加生石膏一两'明示其主阳明实热，凭脉用药，清热为要。此脉与数洪实脉同属洪实一类，数洪实脉兼数，更偏热盛，甚则热瘴；而洪实脉单见，亦主实热，惟不专主瘴邪。要之", "c": "主实热"}, {"id": "pe:两+洪", "n": "两·洪脉", "o": "洪脉总属阳热亢盛之象，以热邪鼓动气血、脉道充盈为核心病机。其脉形洪大有力，主病多属有余实证。具体而言，洪脉主热盛，或热越于表，或热结阳明，或热急兼数；兼滑则主痰火壅盛、食积痰饮；兼浮则主风热在表、痰火积热；兼实则主阳明实热。此外，洪脉亦主阳气拂逆、热扰络脉，见", "c": "主热盛"}, {"id": "pc:两+浮+洪", "n": "两·浮洪脉", "o": "浮洪脉总属阳热亢盛之候，以热盛为核心病机。浮为热越于外，洪为热盛于内，故其主病多属有余实证。具体而言，浮洪主风热在表，风邪外闭引动内热；主痰火积热，痰热搏结中焦；主热盛津伤，热灼津液而致燥渴便结；主火盛喉痹，君相二火独盛上攻咽喉。四类病机相互关联：风邪为外因，", "c": "主痰火积热"}, {"id": "pc:两+浮+空", "n": "两·浮空脉", "o": "浮空脉总属虚证，以气虚为核心，并涉及内伤虚损、阴阳失调。其脉象浮取即得而中空无力，浮为气机浮越于外，空为正气不足于内，故非外感表邪，而是内伤虚损之征。从分部看，右寸虚主肺气不足，右关虚主中气不足，左寸虚主心气不足，左关虚主肝胆气弱，两尺虚主肾气不足，诸部皆虚，", "c": "主气虚"}, {"id": "pc:两+浮+紧", "n": "两·浮紧脉", "o": "浮紧脉总属表寒实证，以浮主表、紧主寒为纲。其病机核心为寒邪外束，卫阳被遏，气血紧张。所主三类：一为表寒，风寒袭表，脉气浮紧；二为寒痛，寒凝经脉，收引作痛；三为瘴疟，瘴毒夹寒，少阳受邪。三者皆不离“寒”与“表”，然表寒为总纲，寒痛为寒凝之变，瘴疟为寒邪兼夹瘴毒之", "c": "主表寒"}, {"id": "pc:两+浮+缓", "n": "两·浮缓脉", "o": "浮缓脉总以风邪伤表、营卫不和为基本病机，原文明言“脉浮缓者为伤风，其病轻”，浮主邪在肌表，缓主风性疏泄、营阴外泄，故为伤风表虚之轻证。然同一段落中，浮缓与洪大、数甚、弦紧、洪数不实、沉微而弱诸脉并列，说明浮缓并非仅主伤风，尚可随兼脉与病位不同而反映热盛兼表、疟", "c": "主风邪表证"}, {"id": "pe:两+浮", "n": "两·浮脉", "o": "浮脉总属阳气浮越、气机趋表之象，所主病机以表证为纲，兼及虚、风、热、气逆。浮而有力多主外感表邪，风寒风热随兼脉而异；浮而无力多主内伤正虚，劳倦伤中、气血不荣，或虚阳外浮；浮兼洪数主热盛，浮兼弦紧主风邪或寒痛；寸浮尺弱则主气逆于上、下元虚竭。诸类之间，以'浮'为", "c": "主表证"}, {"id": "pc:两+浮+虚", "n": "两·浮虚脉", "o": "两·浮虚脉总属正虚之象，其浮为风象之假，虚为内伤之真。所主病机以劳倦伤中、阳明不治为核心，进而导致气血不荣、营卫不和。浮虚脉虽见于外，实因内虚，故不可作风寒湿痹论治。三类病机相互关联：劳倦伤中为始因，阳明不治为关键，营卫不和为表现，总以补益阳明气血为法。", "c": "主内虚"}, {"id": "pc:两+涩+小", "n": "两·涩小脉", "o": "两·涩小脉总起来主虚证，以气血不足、大虚为核心。其脉象特征为寸关大而弱、尺涩而小，大弱主气虚，涩小主血少，寸关候上中焦、尺候下焦，上下皆见虚象，故断为气血不足、大虚之证。具体而言，寸关大而弱反映脾胃虚衰、中焦运化无力；两尺涩而小反映下焦精血亏耗、肾元虚衰。三类", "c": "主气血不足"}, {"id": "pc:两+涩+弱", "n": "两·涩弱脉", "o": "两脉涩弱，总属虚损之候，以肾虚为本，兼见气虚与血少滞涩。涩主血少滞涩，弱主气虚，二者合见，反映精血亏虚、阳气不足，脉道不充且鼓动无力。原文明确指出“此属肾虚，失于收纳，藏聚少司，病根在下”，故其核心病机为下元虚衰、肾失封藏。肾虚则精血不能充养筋骨，故见痿躄、左", "c": "主肾虚"}, {"id": "pc:两+涩+短", "n": "两·涩短脉", "o": "两寸脉短涩，总主气损血滞、心肺气虚寒之病机。短脉主气损，涩脉主血滞，两寸候心肺，故脉短涩反映心肺气血不足与郁滞。原文孀居忧伤肺，肺气郁结，心气不足，脏寒多泣，故见神情恍惚、悲泣、乱语。四类病机相互关联：气损与血滞并见，忧伤肺与脏寒同源，皆因情志所伤，心肺气虚，", "c": "主气损"}, {"id": "pc:两+涩+紧", "n": "两·涩紧脉", "o": "两尺涩紧脉总起来主寒凝血瘀，病位在下焦。紧脉主寒，涩脉主血瘀，两尺候肾与下焦，故脉象反映寒邪侵袭下焦、营血凝滞的病机。原文中患者经期饮冷，寒伤营血，血被冷水所凝，瘀血归于大肠，导致痢下黄黑、痛而急迫。三类病机相互关联：寒邪是病因，血瘀是结果，寒伤营血是二者结合", "c": "主寒"}, {"id": "pc:两+涩+缓", "n": "两·涩缓脉", "o": "两关脉缓涩，总主阳气不运与积滞血瘀。缓为阳气虚衰，旋运无力；涩为积滞血瘀，阻于中焦。二者相合，形成中阳不振、瘀浊内阻之病机，临床可见食入气阻、吐涎稍通、吐瘀浊胶黏等症，为噎膈反胃之典型脉象。此病多反复，因阳气虚而瘀滞难化，瘀滞又进一步伤阳，形成恶性循环。故治疗", "c": "主阳气不运"}, {"id": "pe:两+涩", "n": "两·涩脉", "o": "涩脉总主气血涩滞、脉道不充之病机，其核心为血少气滞、精血亏虚与瘀阻不通。从所收段落看，涩脉既可主虚，如血少精亏、气血两虚、肾虚失藏；又可主实，如气滞血瘀、寒凝血瘀、痰饮郁热；更可见虚实夹杂、阳衰阴逆之危候。各类之间以“气血涩滞、脉道不利”为共同基础：虚则脉道不", "c": "主血少精亏"}, {"id": "pc:两+滑+大+涩", "n": "两·滑大涩脉", "o": "两·滑大涩脉总起来主虚实夹杂之证，以血少血瘀、痰火壅盛、下元虚惫为三大病机要素。左涩主血少或血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。原文吐血后咳喘、泄泻、发热烦躁，前医滋阴则泻甚，保脾则火炽，正合上焦痰火未清、中焦脾弱、下元不足之虚实错杂格局。诸类", "c": "主血少血瘀"}, {"id": "pc:两+滑+大", "n": "两·滑大脉", "o": "两·滑大脉总起来主痰、火、气滞、食积等邪气壅盛于中上二焦，兼见下元不足或正气亏虚。滑主痰湿食积，大主热盛邪实，故其核心病机为痰火壅盛、气滞痰食内停。从原文看，滑大脉多见于寸关部，提示病位在中上焦，症见眼赤肿痛、呕吐眩晕、咳血喘急、胃脘疼痛、心痛彻背等。若尺部沉", "c": "主痰火壅盛"}, {"id": "pc:两+滑+弱", "n": "两·滑弱脉", "o": "两关滑而尺弱脉，总属虚实夹杂之候。滑主痰，关部候中焦，故两关滑主内风痰阻；弱主虚，尺部候肾，故尺弱主肝肾两虚。二者相合，揭示肝肾阴亏为本，虚风内动，挟痰阻络为标。血虚不能养筋，营虚则不仁，故见舌强肢麻、口眼㖞斜、溲多筋酸等症。治疗当益肾之阴，水壮则木涵，肝风自", "c": "主内风痰阻"}, {"id": "pc:两+滑+沉", "n": "两·滑沉脉", "o": "两·滑沉脉总起来主里实痰浊为患。沉主里，滑主痰，两脉俱沉滑，提示病位在里、痰浊内蕴，邪气壅实。其具体所主，可因痰浊所阻部位及兼脉不同而表现各异：痰浊上蒙清窍，则为痰厥头痛，见头痛经年、神气昏愦；痰浊内结肝胃，兼弦脉，则为肝胃同病、痰火内结。各类病机均以痰浊内盛", "c": "主痰"}, {"id": "pc:两+滑+洪", "n": "两·滑洪脉", "o": "两·滑洪脉总属实证、热证，以痰火壅盛、食积痰饮、实热积滞为核心病机，其脉象洪滑有力，主邪气壅盛、气血壅滞。若洪滑见于寸关而尺部沉弱，则形成上盛下虚之候，痰火壅于上而真阴亏于下，病势多危。尺部洪滑有力则主湿热壅遏下焦。此外，洪滑亦主瘀血痰火郁滞肺之气道，以及实热", "c": "主痰火壅盛"}, {"id": "pc:两+滑+浮", "n": "两·滑浮脉", "o": "两·滑浮脉总以浮脉主表、滑脉主痰湿为纲。其主病机有三：一为外邪袭表，浮脉应之，滑示兼痰湿，如风湿外乘；二为痰湿壅盛，滑脉主痰，浮示病位偏上，多见于寸关，症见咳嗽、胸痛、头痛；三为上盛下虚，寸浮滑而尺弱，上焦痰热壅盛，下元虚衰，症见头痛、腹痛。三者皆以浮滑为共同", "c": "主表证"}, {"id": "pc:两+滑+濡", "n": "两·滑濡脉", "o": "两·滑濡脉总以湿痰内蕴、脾失健运为主，兼见肝胆气火偏旺。右部濡滑直接主湿痰，因濡为湿、滑为痰，且右候脾，故又主脾湿；左部弦数则主肝胆气火。三者相互关联：肝胆气火偏旺可横逆克土，致脾运失健、湿痰内生；脾湿内蕴又加重气机壅滞，使肝火易亢。原文以“濡滑为湿痰”为眼目", "c": "主湿痰"}, {"id": "pe:两+滑", "n": "两·滑脉", "o": "滑脉总主痰湿水饮内蕴，为邪气壅盛之象。其基本病机为痰湿、水饮、湿热积滞，病位随寸关尺而异：寸滑主上焦痰饮，关滑主中焦痰湿，尺滑主下焦湿热。滑脉兼见他脉则病机扩展：兼数、洪、大主痰火湿热壅盛；兼弦主气郁痰凝；兼浮主外邪挟痰或上盛下虚；兼沉主里实痰浊；兼弱、濡主虚", "c": "主痰湿"}, {"id": "pc:两+滑+虚+软", "n": "两·滑虚软脉", "o": "两·滑虚软脉总起来主肺燥津伤、气阴两虚，兼风阳内煽。右脉软滑而虚，为肺伤于燥、治节不行、津液被烁之核心脉象；软虚并见，又示气阴两亏、上下交虚。左脉浮弦且数，则因辛甘温药致风阳内煽，为兼夹之变。三者相互关联：燥伤肺津为始因，津亏则气阴两虚，液亏则风阳易动；风阳内", "c": "主肺燥津伤"}, {"id": "pc:两+濡+软", "n": "两·濡软脉", "o": "濡软脉总属虚象，主气血不足、脾胃虚弱，亦主阳气不足、血寒凝滞。其脉象柔软无力，按之不足，反映正气亏虚，或寒邪内凝。所举两案，一为产后脾胃虚弱、气血不足，见濡软无力，治以健脾益气；一为产后血寒凝滞，两尺软濡，治当温通。二者虽表现不同，但皆以虚为本，或兼寒凝。故濡", "c": "主虚"}, {"id": "pe:两+牢", "n": "两·牢脉", "o": "牢脉总起来主阴虚阳浮、胃气不柔、脾虚气陷之证，而非实寒内结。其脉弦硬不柔，看似有力，实为阴血亏虚、不能涵阳，虚阳外露之象；或胃气失和、阴血不足而气失和降；或脾虚气陷、虚中夹瘀。原文两段均以'症属阴虚'为眼目，强调下部畏冷似寒而脉不沉迟，反见弦硬，故非真寒，不可", "c": "主阴虚阳浮"}, {"id": "pc:两+疾+促", "n": "两·疾促脉", "o": "两脉促疾，总属邪火燎原、阴津消涸之危候。促为阳盛搏急，疾为热极躁动，二脉相合，反映热邪亢盛、阴液耗伤之病机。热盛则脉促疾，热盛劫津则阴伤，阴伤筋脉失养则风动，风动神昏、手指牵引，诸症丛生。虽大便通、病热略减，然脉仍促疾无伦，是邪火未衰而阴津难复，故脉象不减则险", "c": "主险候"}, {"id": "pe:两+短", "n": "两·短脉", "o": "两寸短脉总以气机不畅为核心，或为气郁，或为气虚，或为痰湿、火邪阻滞气机所致。短脉主气病，寸部候心肺，故病位多在上焦。气郁者，胸阳不展，见胸膈胀痛、梅核气；气虚者，心肺不足，见体倦汗多、惊悸梦遗；痰阻者，痰气交结，见喉中梗梗、鼻塞头晕；湿滞者，湿阻上焦，见身重胸", "c": "主气虚"}, {"id": "pc:两+紧+急", "n": "两·紧急脉", "o": "两脉紧急脉总起来主寒积、气逆、湿热壅阻及关格危候。紧脉主痛、主寒积，因寒性收引，冷积胃腑则气机凝滞而痛；急脉主气逆攻冲，因气无下降之权，升逼之势致呃逆呕吐。患者素多酒色，湿热壅于膀胱，与冷积互结，前阻小便后塞大肠，形成寒热错杂、气机逆乱之关格极候。四类病机相互", "c": "主寒积"}, {"id": "pe:两+紧", "n": "两·紧脉", "o": "紧脉总属寒邪为患，其病机核心为寒性收引凝滞，气血不畅。所主病机可归纳为寒凝、疼痛、正虚邪结、寒湿、气逆寒积、表寒、邪闭及疟疾等类。其中寒凝为基本病机，因寒邪侵袭，气血凝滞，不通则痛，故紧脉多主痛；寒邪在表则脉浮紧，在里则脉沉紧，兼湿则细紧，兼瘀则涩紧，兼气郁则", "c": "主寒凝"}, {"id": "pc:两+细+小", "n": "两·细小脉", "o": "两·细小脉总主气血两虚、脉道不充。细为血虚，小为脉道不充，故凡失血、产后、霍乱吐泻后津气耗伤，或劳心过度、心脾两伤，皆可见两脉细小。其病机或为纯虚，如产后下血、脑失所养；或为虚中夹邪，如暑湿霍乱伤正后脉转细小；或为脏腑亏虚，如心脾两虚。三者皆以气血不足为本，或", "c": "主气血两虚"}, {"id": "pc:两+细+弱", "n": "两·细弱脉", "o": "两·细弱脉总起来主虚，以阳气衰微、气血不足为核心，具体可归纳为虚寒、脾肾阳虚、气血不足三类。其脉象细弱无力，轻取即得而沉取无力，反映正气亏虚，尤以脾肾两脏为著。原文两段均围绕八岁女童久痢白脓一案，脉见两尺细弱无力、脾脉更虚，断为脾肾阳虚、中焦有寒，五谷不化而下", "c": "主虚寒"}, {"id": "pc:两+细+微", "n": "两·细微脉", "o": "两·细微脉总属虚损之象，主气血阴阳不足，尤以脾肾肝亏虚为本。微细脉来微弱纤细，为脉道不充、阳气衰微之征。所主病机主要有三：一为虚损，因内伤劳倦、脾肾气弱，或阴亏泉竭，脉道失充；二为寒湿，因阳虚不能温煦，寒湿深著筋骨，脉道收引；三为阴阳失调，因虚而阴阳不相顺接，", "c": "主虚损"}, {"id": "pc:两+细+沉", "n": "两·细沉脉", "o": "两·细沉脉总属里虚之候，以沉候病位在里，细候气血阴精不足。其主病机可归为四类：一主肾虚，见两尺沉细，为肾阴或肾阳精血亏虚；二主脾虚寒湿，见两关沉细，为中阳不振、寒湿食积内阻；三主肝火犯肺，以左关弦数、右寸弦大滑兼两尺沉细，示肝火亢盛、上刑肺金；四主冲任失司，因", "c": "主肾虚"}, {"id": "pc:两+细+紧", "n": "两·细紧脉", "o": "两·细紧脉总属寒湿为患，以寒邪外束、湿浊内阻为核心病机。紧脉主寒，细脉主湿主虚，两脉相合，揭示寒湿困表、湿温初起及阳虚湿阻等证。原文见湿温初起，因劳役过度、渴饮凉茶、食冷物而病，症见头痛、肢节疼、身体沉重、胸满不食，脉紧细，两寸脉短，示寒湿困表，湿阻上焦，阳气", "c": "主寒湿"}, {"id": "pe:两+细", "n": "两·细脉", "o": "细脉总以虚为本，主气血阴精不足、脉道不充，故凡失血、久痢、劳倦、产后及脏腑亏虚者多见。其类别虽分气血两虚、阴血亏虚、阳气衰微、正虚邪恋、邪闭热深与脏气败绝，然核心皆不离“虚”：气血虚则脉细无力，阴血亏则脉细而劲，阳虚则细而耎弱，正虚夹邪则细兼涩滞，邪闭热深则细", "c": "主气血两虚"}, {"id": "pc:两+细+虚", "n": "两·细虚脉", "o": "两·细虚脉总起来主正气亏虚，尤以津液元气俱伤为核心。其脉虚细，小弱虚细皆主正虚，数则示虚热。原文因克削过甚，致津液元气俱伤，故见舌燥无津、手指蠕动、心悸不寐、面色黯淡等症。三类病机相互关联：正虚为根本，津伤为阴液耗损之具体表现，虚热为阴虚不制阳之继发结果，三者", "c": "主虚"}, {"id": "pc:两+细+软", "n": "两·细软脉", "o": "两·细软脉总属虚候，以气阴两虚为基础，进而可演变为虚阳不潜、阴血亏极，甚则阴阳离决。细主阴血不足，软主气弱不充，故脉细软首先反映气阴两伤；若兼数象，则虚阳上浮、不得潜藏，见咳痛酸软等症；若细软无根，则阴血耗竭、阳气无依，出现壮热昏沉、油汗等危候，终致阴阳离决。", "c": "主气阴两虚"}, {"id": "pe:两+芤", "n": "两·芤脉", "o": "芤脉总主血病，以血虚失血与瘀血内阻为两大纲。其脉中空如按葱管，外实中空，既反映血虚不充脉道，又提示瘀血阻滞、血不循常道。原文“脉芤是瘀血，胸中两胁必有块”明言瘀血结于胸胁，故必有块；而瘀血内阻常兼血虚，失血亦致芤。二者互为因果：瘀血不去则新血不生，血虚脉道不充", "c": "主瘀血"}, {"id": "pc:两+虚+弱", "n": "两·虚弱脉", "o": "两脉虚弱总属气血大亏、正气衰败之候。其脉象虚弱无力，反映脉道不充、气血亏耗，多见于失血过多或久病耗伤之人。本例患者素患血崩，下血成斗，气随血脱，故见心悸头晕、面色无华、奄奄一息，脉虚弱正合气血大亏、势将虚脱之危。虚脱乃气血大亏之进一步发展，二者密切相关，皆以脉", "c": "主气血大亏"}, {"id": "pc:两+虚+涩", "n": "两·虚涩脉", "o": "两脉虚涩总属正虚邪滞之候。虚为正气不足、气虚，涩为血少气滞、阴伤，故其核心病机为气血两虚。在此基础上，可因阴血暴亡而致虚阳外越，出现阴阳相离之危候；亦可因下焦浊气上逆，兼见右尺弦急，形成正虚浊逆之证。诸类之间以气血亏虚为本，阴伤、阳越、浊逆为标，虚实夹杂，病位", "c": "主阴血暴亡"}, {"id": "pc:两+虚+濡", "n": "两·虚濡脉", "o": "两脉虚濡总主脾胃元气大弱，兼有湿滞内蕴之机。虚脉主不足，濡脉主湿，合而示中焦气虚、运化失司，湿邪留滞。原文三处均以“脾胃元气大弱”释之，然又强调下痢多起于湿热，早补早敛易致受累，故虚濡脉所主非单纯虚证，而是正虚与湿滞并存、虚实夹杂之候。其病机核心为脾胃气虚为本", "c": "主正虚邪恋"}, {"id": "pc:两+虚+空", "n": "两·虚空脉", "o": "两·虚空脉在此段中并非单一脉象，而是统括舌音不清之多种脉候。其总病机以阴血亏虚、肾水枯涸为本，虚火上炎为标，兼见脾胃积热、心肝火旺之实。左脉空虚主阴血不足，两尺细数主肾水枯涸，右关洪滑主脾胃积热，左脉见数主心肝火旺。诸类之间，阴亏与火旺互为因果：肾水枯涸则虚火", "c": "主阴血亏虚"}, {"id": "pe:两+虚", "n": "两·虚脉", "o": "虚脉总主正气亏虚，包括气血不足、阳气衰微及脏腑功能减退。其基本特征为脉来虚耎无力，按之空豁。从所主病机看，虚脉可单独出现，主气血大虚、气虚阳衰，如高年发背脓血多、脾肾阳虚下痢、气虚眩晕诸部皆虚；亦可专见于尺部，主肾虚不摄，见内中风、喘逆等气逆上脱之证；又常见于", "c": "主气血大虚"}, {"id": "pe:两+软", "n": "两·软脉", "o": "软脉总属虚象，主正气亏虚，以阳气不振、气血不足为核心病机。其脉来柔软无力，按之不足，反映脉道不充或阳气失运。具体而言，软脉可主中阳亏虚、纳运失职，见中脘作痛、纳谷不化；主气血不足，见气满汗出、不寐、食减、吐血、血崩、腰痛、耳鸣；主脾胃虚弱，见产后纳差乏力；主气", "c": "主中阳亏虚"}, {"id": "pp:两关", "n": "两关", "o": "两关脉总主肝脾（胃）同病，以木土相争为核心。弦脉为肝气郁结、肝阳亢盛，木乘土位则脘痛胀满、呕吐噎膈；滑脉为痰湿内蕴，兼弦则痰气交阻，兼数则痰火；洪滑数有力为实热积滞壅盛中焦；涩、动、促为瘀血内阻，脉道不利；大而无力或弦虚为脾虚气弱，正气浮越；动脉或滑弱并见为内", "c": "主肝郁气滞"}, {"id": "ps:两关+动", "n": "两关·动脉", "o": "两关动脉总起来主邪气搏结与内风动摇，其病机核心为气血壅滞、风阳扰动。从所收三段看，动脉既可见于实邪结聚，如污血感寒、寒凝血瘀之喘证，又可见于内风暗动之麻木、屈伸不利，且常与虚象并见，形成虚中夹实之局。各类之间相互关联：邪结可致气血不通，久则化风；内风动摇亦多因", "c": "主邪结"}, {"id": "ps:两关+大", "n": "两关·大脉", "o": "两关脉大总属中焦脾胃及肝脾气机失常之象，其病机有虚实寒热之辨。实者多因痰火、热盛、气逆、邪伏，脉大有力，症见咳血、热瘴、奔豚、寒热膨胀等；虚者多因脾虚气弱，脉大而无力，症见痞闷、汗多、倦怠、晨泄；另有内风动扰，脉见厥厥动摇。诸类之中，痰火、热盛、气逆、邪伏均属", "c": "主痰火"}, {"id": "pc2:两关+弦+大", "n": "两关·弦大脉", "o": "两关弦大脉总起来主肝火、暑热、痰火及邪热内伏，属虚实夹杂之候。其形成多因劳心暴怒、暑热外逼或邪热内郁，致木火上升、痰火壅盛或胃土受伤。左关弦大主肝火亢盛，右脉虚大主暑热伤气，两关洪滑有力主痰火实热，而弦大按之不足则主邪热内伏、胃土失令。各类之间常相兼为病，如肝", "c": "主肝火"}, {"id": "pc2:两关+弦+滑", "n": "两关·弦滑脉", "o": "两关弦滑脉总主中焦肝胃病变，以气郁痰湿为基本病机。弦主气郁、肝郁，滑主痰湿、痰涎，两关候肝脾（胃），故其病机多围绕肝胃气机失调与痰湿内阻展开。四段中，或为痰湿内阻、胆胃不降（7561），或为肝火挟痰内扰（7717），或为胃阴枯槁、津枯痰凝（7773），或为肝郁", "c": "主痰湿内阻"}, {"id": "pc2:两关+弦+细", "n": "两关·弦细脉", "o": "两关弦细脉总以肝旺阴伤为基本病机，弦主肝木偏亢，细主营血不足或阴伤，两关候肝脾，故其病机多围绕肝脾关系展开。具体可分四类：一为肝旺，肝气横逆、风木偏亢；二为阴伤，营血亏耗、气结阴亏；三为肝脾不和，肝强脾弱、木郁土虚，气机壅滞而痰湿内阻；四为暑湿郁遏，邪热内扰而", "c": "主肝旺"}, {"id": "ps:两关+弦", "n": "两关·弦脉", "o": "两关弦脉总以肝木偏旺、木土相争为核心病机。关部候肝脾（胃），弦为肝气郁结、肝阳亢盛之象，故其主病多围绕肝气、肝阳、肝火与脾胃的相互作用展开。轻则肝郁气滞，木乘土位，见脘痛胀满；甚则肝阳犯胃，冲逆呕吐，久成噎膈；若挟痰火，则痰火内扰，或成噎膈重证；若肝火亢盛，则", "c": "主肝郁气滞"}, {"id": "ps:两关+数", "n": "两关·数脉", "o": "两关数脉总主中焦有热，因关部候脾胃肝胆，数脉主热，故热象多集中于中焦。具体而言，数而有力多实热，兼滑则湿热痰火，兼弦则肝火，兼滑弦则痰火，亦可见于惊气乱而化热。各证虽表现不同，但均以热为核心，或夹湿、夹痰、夹惊，病位多在脾胃肝胆。数脉与不同兼脉及症状相合，可辨", "c": "主湿热积滞"}, {"id": "ps:两关+洪", "n": "两关·洪脉", "o": "两关洪脉总起来主实热壅盛，兼及痰火、积滞、热盛津伤及热瘴阳浮等证。洪脉为阳热亢盛之象，两关候中焦肝脾，故其病机多围绕实热、痰火、积滞展开。如痰火上逆、实热壅盛、实热积滞，皆以洪滑有力为凭；浮洪近数，为热盛津伤、痰热内扰；洪大主热瘴，洪数不实为阳浮阴闭。诸类之间", "c": "主实热壅盛"}, {"id": "ps:两关+涩", "n": "两关·涩脉", "o": "两关涩脉总主气血瘀滞、积滞内阻及血少津亏。其病机要点在于脉道不利：或因瘀血内停，如呕血、便黑、腹中结块；或因积滞壅塞，如食入气阻、噎膈反胃；或因湿痰阻滞，如胸腹不舒、痰注成漏；或因血少津亏，如病久虚弱、肠道失润。四类之中，瘀血与积滞多属实证，湿痰为虚实夹杂，血", "c": "主瘀血"}, {"id": "pc2:两关+滑+洪", "n": "两关·滑洪脉", "o": "两关洪滑脉总起来主实热、痰火、积滞等有余之证，其核心病机为邪气壅盛，气血痰食搏结于中焦。洪为火盛，滑为痰壅，两关候脾胃与肝胆，故病位多在肝脾胃。痰火、实热、积滞、肝火四类相互关联：痰火可因肝火亢盛而升，实热可致积滞内结，积滞日久又可化火生痰。原文反复强调“洪滑", "c": "主痰火"}, {"id": "ps:两关+滑", "n": "两关·滑脉", "o": "两关滑脉总属痰湿、痰火、实热积滞及肝郁气逆等有余之候，其核心病机为痰湿内蕴，气机不畅。滑脉主痰，兼洪大数则为痰火或实热积滞，兼弦则为肝郁气逆、痰气交阻。然亦有虚中夹实者，如胃阴枯槁或肝肾两虚而见滑脉，乃津枯痰凝或虚风挟痰之象。各类之间以痰湿为共同基础，或化火、", "c": "主痰湿"}, {"id": "ps:两关+细", "n": "两关·细脉", "o": "两关细脉总以肝脾同病为核心，主肝旺、阴伤、脾虚湿滞、气机壅滞及邪热内扰。细为营血不足或阴伤，两关候肝脾，故细脉见于关部多示肝脾阴血亏虚；兼弦则肝木偏亢，兼涩则湿滞，兼不静则邪热内扰。诸类之间相互关联：肝旺可乘脾致脾虚湿滞，脾虚生湿又可郁遏肝木，气机壅滞贯穿其中", "c": "主肝旺"}, {"id": "pp:两寸", "n": "两寸", "o": "两寸脉总主上焦心肺病变，其病机以热、痰、虚为三大纲，兼见上盛下虚、气逆、邪实、郁滞等。寸候心肺，故凡火邪上炎、痰浊壅滞、元气不足，皆反映于两寸。热盛者脉多数、洪、大而有力；痰盛者脉多滑或洪滑；虚者脉多短、弱、软、细；上盛下虚者寸洪滑而尺沉弱；气逆者脉浮大或弦；", "c": "主热"}, {"id": "pc2:两寸+大+洪", "n": "两寸·大洪脉", "o": "两寸洪大脉总以热盛于上焦为核心病机，寸部候上焦，洪大为热盛气壅之象。其所主病机可归纳为四类：一为单纯上焦热盛，热壅胸膈、肺胃，症见颧红唇红、呕吐不纳、鼻渊头痛等；二为上热下寒，寸洪大而尺沉微，热壅于上而阳衰于下；三为痰热壅盛，洪大兼滑，痰火湿热搏结，迫血妄行；", "c": "主上焦热盛"}, {"id": "ps:两寸+大", "n": "两寸·大脉", "o": "两寸大脉总主上焦病机，以邪实热盛为多，虚证较少。其大而有力者，多主热盛、气火上逆、痰火壅盛或邪实于上，因寸候上焦，大则阳热有余、邪气壅盛，故见头眩呕吐、咳喘鼻渊、眼赤肿痛等。若大而兼滑，则痰火交阻；浮大则气火上升；洪大则热壅营分。若两寸大而两尺沉微，则属上盛下", "c": "主热盛"}, {"id": "ps:两寸+弦", "n": "两寸·弦脉", "o": "两寸·弦脉总起来主肝郁气逆、邪热内郁与痰郁三类病机。弦为肝脉，寸关候中上焦，故病位多在心胸、胃脘、胸膈。肝郁气逆者，气机不畅而上冲，见胸闷、晕眩、心惕；邪热内郁者，热耗津液、风动于内，见舌硬苔黑、火灼神昏；痰郁者，痰涎壅滞膈上，见胸胁痛、脉弦滑有力。三者皆与气", "c": "主肝郁气逆"}, {"id": "pc2:两寸+弱+短", "n": "两寸·弱短脉", "o": "两寸·弱短脉总属上焦心肺气虚，短主气损、弱主气虚，故凡寸部短弱，首责心肺元气不足。然其兼脉不同，所主病机遂异：兼关尺滑或洪滑者，为气虚不运、湿痰下流；兼关弦尺洪滑者，为气虚血热下陷；兼数而无力者，为气阴两虚、虚热外浮；兼关弦右关滑者，为神气不足、郁痰蒙蔽。诸类", "c": "主气虚"}, {"id": "ps:两寸+弱", "n": "两寸·弱脉", "o": "两寸弱脉总以虚为本，尤主上焦心肺气虚。寸候心肺，短弱、软弱、微弱皆元气不足之象，故见汗多、短气、心悸、胎动、痿废等症。然弱脉非独虚也，常兼他部脉象而呈虚实夹杂：兼关滑为虚中夹痰，兼尺洪滑为气虚下陷、湿热下注，兼关尺洪数为虚热上浮、阴火迫血。诸类皆以寸弱为枢，虚", "c": "主上焦气虚"}, {"id": "pc2:两寸+弱+软", "n": "两寸·弱软脉", "o": "两寸软弱脉总属气血不足、心肺气虚之象。寸部候心肺，脉来软弱无力，说明上焦正气亏虚，气血不能充盈脉道。所主病机以虚为本：或为气血两虚，或为心肺气虚，或为脾虚气陷。然虚中常夹实滞，如肝郁化火、痰凝、湿热下注等，形成虚中夹滞之复杂格局。原文反复强调“软弱示气血不足”", "c": "主气血不足"}, {"id": "pc2:两寸+数+弦", "n": "两寸·数弦脉", "o": "两寸·数弦脉总起来主邪郁少阳、热邪内盛及心气亏虚、阴虚火动。弦数为少阳邪郁与热象之征，见于外感传变；两寸短为心气大弱，余部滑数为阴虚火动，见于内伤梦遗。两类病机一外一内，外感以弦数为主，主少阳郁热；内伤以寸短与滑数并见，主心气弱而虚火动。数脉贯穿热象，弦脉主郁", "c": "主少阳邪郁"}, {"id": "pc2:两寸+数+滑", "n": "两寸·数滑脉", "o": "两寸数滑脉总起来主痰热为患，兼涉痰火、瘀血、食积、湿热及虚中夹实。滑为痰湿壅盛之象，数为热邪亢盛之征，两寸候上焦胸膈，故其核心病机为痰热结于胸中或上焦。然具体所主又有兼夹：或痰火郁于肺胆，或痰瘀互结胸膈，或痰热食积壅于中上而兼下元虚寒，或湿热蕴结肠道。诸类之间", "c": "主痰热"}, {"id": "ps:两寸+数", "n": "两寸·数脉", "o": "两寸数脉总以主热为纲，因寸部候心肺，故多反映上焦热象。具体可分五类：一为实热，如心火刑金、上焦实热壅遏；二为痰热，滑数相兼，痰火结于胸膈；三为虚火，数而兼虚、促数或虚大不调，属气阴亏虚、虚阳浮越；四为上热下寒，寸数而关尺无力或沉细，示上焦有热、中下焦虚寒；五为", "c": "主热"}, {"id": "ps:两寸+洪", "n": "两寸·洪脉", "o": "两寸洪脉总属上焦热盛之象，寸候心肺，洪为火盛，故主热。然具体病机有兼夹与虚实之别：纯洪大者主热盛，洪滑者主痰火，洪数者主火盛，洪大而尺沉微者主上盛下虚，洪大兼滑而见湿热症者主湿热壅盛。诸类以热盛为核心，痰火、湿热为兼邪，上盛下虚为虚实夹杂之变。洪脉见于两寸，病", "c": "主热盛"}, {"id": "ps:两寸+浮", "n": "两寸·浮脉", "o": "两寸浮脉总属上焦病变，以阳浮气逆为基本特征。寸候上焦，浮为阳脉，故凡气火上升、表邪外袭、痰浊壅塞、上盛下虚及虚损内伤，皆可见两寸浮。其类虽分五端，然核心病机在于“上焦气机不降、阳浮于上”：气火与痰浊为实邪上壅，表邪为外束，上盛下虚与虚损内伤则为本虚标实、阴阳不", "c": "主气火上逆"}, {"id": "pc2:两寸+滑+大", "n": "两寸·滑大脉", "o": "两寸滑大脉总以中上二焦痰、火、气、食壅盛为基本病机，其脉象滑主痰、大主实，见于寸关，故病位多在中上焦。然原文每与两尺沉微或沉弱并见，形成上盛下虚之格局，故其病机常非单纯实证，而是痰火气滞壅于上，兼下元不足或血虚于下。上述五类中，痰盛、火旺、气滞为邪实之象，血虚", "c": "主痰盛"}, {"id": "pc2:两寸+滑+洪", "n": "两寸·滑洪脉", "o": "两寸洪滑脉总属上焦痰火壅盛、阳火上浮之象。洪为火盛，滑为痰聚，寸部候上焦，故其核心病机为痰热壅于上焦，症见胸膈胀闷、呕逆、吐痰、吼喘、面赤、咳吐红痰等。若兼两尺微弱或沉微，则形成上盛下虚、亢上不下之候，甚则为溢脉，阳升无制、下无真阴相济，预后不良。痰火郁滞肺之", "c": "主痰热壅上"}, {"id": "pc2:两寸+滑+浮", "n": "两寸·滑浮脉", "o": "两寸浮滑脉总主上焦痰湿与表邪，兼及上盛下虚之候。浮为阳脉，主表、主上；滑为阴脉，主痰湿。寸部候上焦，故浮滑见于两寸，多提示痰湿壅阻上焦或风湿外袭肌表。若与尺弱并见，则形成上盛下虚之局，上焦痰热壅盛而致头痛、咳嗽，下元虚衰而见脐腹冷痛。三类病机相互关联：痰湿上壅", "c": "主痰湿上壅"}, {"id": "ps:两寸+滑", "n": "两寸·滑脉", "o": "两寸滑脉总主痰湿水饮为患，尤以痰浊壅滞上焦胸膈为核心病机。滑为痰涎内盛之象，寸候上焦，故寸滑多直接反映痰积胸膈、肺有宿痰。若滑而兼数或洪，则痰火交炽，壅于上焦；若寸滑而尺弱或沉微，则形成上盛下虚、亢上不下之候，痰火壅于上而元虚于下。此外，滑脉亦主水饮内停、湿热", "c": "主痰"}, {"id": "ps:两寸+短", "n": "两寸·短脉", "o": "两寸·短脉总主上焦心肺气虚，兼夹痰、湿、郁、热等邪。短脉为气损之象，寸部候心肺，故短脉独见于两寸，首责上焦元气不足，卫外不固、固摄无权，可见汗多、胎动下血、梦遗等症。然短脉常兼滑、弦、数、涩，提示气虚基础上兼有痰湿、气郁、郁火、血涩等病理因素。如寸短弱而关尺滑", "c": "主上焦气虚"}, {"id": "ps:两寸+细", "n": "两寸·细脉", "o": "两寸细脉总属正虚，以心肺气阴不足为核心。细为虚象，寸候上焦，故心肺气虚、阴血不足多见。其类有四：一为一般正虚，心肺气阴耗损；二为心脾两虚，劳心伤脾，气血不足；三为心肾不交，寸细尺濡，心神不宁；四为死候，寸细而关尺无神，正气败绝。四类皆以虚为本，轻者心肺气阴不足", "c": "主心脾两虚"}, {"id": "ps:两寸+软", "n": "两寸·软脉", "o": "两寸软脉总属心肺气虚、气血不足之象。寸部候心肺，脉软弱无力，直接反映上焦正气亏虚，故见气满、汗出、不寐等症；气血不足则脉道不充，软弱亦为气血两虚之征。然脉虽软弱而不数，说明热未炽盛，非实热之候；且患者常见虚中夹滞、肝郁痰凝等复杂病机，脉象示正虚为主，兼有郁滞。", "c": "主心肺气虚"}, {"id": "pp:两尺", "n": "两尺", "o": "两尺脉总主下焦肾与膀胱病机，以肾虚为核心，兼及寒热虚实。其病机可归纳为肾虚、虚寒、湿热、热盛火旺、阴虚火旺、寒凝血瘀、气结邪实、正虚邪恋八类。肾虚与虚寒多因尺脉无力，主阴阳精血亏虚或阳气衰微；湿热、热盛火旺、气结邪实多因尺脉有力，主邪热壅盛或气机壅滞；阴虚火旺", "c": "主肾虚"}, {"id": "pc2:两尺+大+洪", "n": "两尺·大洪脉", "o": "两尺大洪脉总起来主阳热亢盛、痰火壅滞及上盛下虚之证。其核心病机为热邪炽盛，或为热毒内陷，或为痰火上升，或兼肾阴不足而呈上盛下虚。洪大之象主热盛、主痰火，若兼数则热急，兼滑则痰壅。诸类之间，热毒炽盛与痰火壅盛均属实证、热证，可相互转化；上盛下虚则为本虚标实之候，", "c": "主热毒炽盛"}, {"id": "ps:两尺+大", "n": "两尺·大脉", "o": "两尺大脉总起来主病机以热盛为核心，但虚实有别。实者或因邪热亢盛于阴分，迫血妄行，如疟陷少阴之热盛动血；或因热毒炽盛、气血壅滞，如杨梅疮毒内陷之洪大数脉；或因痰火壅盛于上，如阳亢阴微之上盛下虚。虚者或因阴火太旺、水亏火炎，如尺脉洪数而中取不见；或因肾气不足、虚阳", "c": "主热盛动血"}, {"id": "ps:两尺+弱", "n": "两尺·弱脉", "o": "两尺弱脉总主下元虚损，以肾元亏虚为核心，涉及阳气衰微、阴液耗竭及下焦不固。各段中，弱脉或独见或兼他脉，皆提示肾气不足、根本已虚。如因吐血后咳喘泄泻，火刑肺金而脾胃已惫，尺弱示下元虚惫、元气下脱；久痢白脓，尺弱兼脾脉虚，为脾肾阳虚、寒邪内生；下血日久，尺弱主下焦", "c": "主下元虚惫"}, {"id": "ps:两尺+微", "n": "两尺·微脉", "o": "两尺微脉总主肾与命门虚衰，以阳气衰微为核心，兼及阴血不足。尺部候肾，微为阳衰，细为阴弱，故见两尺微细或沉微，多责之肾虚。肾阳不足，则阴寒内盛，寒湿著于筋骨，或沉寒内伏，故主寒湿。若下元虚极，虚阳不能内守，反浮于上，则见尺微而寸关洪大，主虚阳外越。四类之中，肾虚", "c": "主肾虚"}, {"id": "pc2:两尺+数+大+洪", "n": "两尺·数大洪脉", "o": "两尺数大洪脉总起来主热盛与火旺，但需分虚实。实者多为阳热实邪、热毒炽盛，如杨梅疮毒内陷，气血壅滞，脉洪大而数，症见喘咳、肛脱、阴囊红肿等，壮年正气尚能抗邪，故可治。虚者多为阴火太旺、水亏火炎，尺脉洪大且数而中取不见，相火妄动，症见下肢痛如站火中、申刻大哭等，治", "c": "主热毒炽盛"}, {"id": "pc2:两尺+数+细", "n": "两尺·数细脉", "o": "两尺细数脉总属肾阴亏虚、虚火内动之候。细为阴血不足，数为虚热内扰，两尺候肾，故其核心病机为肾水枯涸、真阴不足，虚火上炎。四段原文虽语境不同——舌音不清、肾虚劳伤、阴虚喘逆、肾痹——但均以“两尺细数”为肾阴亏虚之共同脉象。其中“主阴虚火旺”统括细数相兼之总机；“", "c": "主阴虚火旺"}, {"id": "ps:两尺+数", "n": "两尺·数脉", "o": "两尺数脉总属热象，但热有虚实之分。虚热多因肾阴亏虚、水不制火，脉多细数或数大无力，主真阴不足、相火妄动、遗泄火动；实热多因湿热、瘀热、痰火等邪壅下焦，脉多数而有力或兼濡、弦、洪大，主下焦湿热、瘀热壅结、痰火郁结。各类之间可相互转化，如阴虚火旺可兼湿热，瘀热可致", "c": "主肾阴亏虚"}, {"id": "ps:两尺+沉", "n": "两尺·沉脉", "o": "两尺沉脉总属里证，以肾虚为核心，涵盖肾阴、肾阳、精血亏虚及下焦虚寒。沉而细、微、绝多主肾虚，或为阴亏，或为阳衰，或为气血不足；沉而兼紧、弦、小则主虚寒内盛、痰饮寒凝。各段中，沉细主肾阴亏虚（2018、19957），沉微主肾气阴血不足或真阳衰微（15256、25", "c": "主肾虚"}, {"id": "ps:两尺+洪", "n": "两尺·洪脉", "o": "两尺洪脉总属火热实证，但具体病机有湿热、热毒、痰火、阴火、气结、相火之别。洪为热盛之象，尺候下焦，故病位多在下焦肾与膀胱。然有实热与虚火之异：湿热壅遏、热毒炽盛、痰火壅盛、相火偏旺多属实证；阴火水亏则属虚火；气结膀胱之洪盛乃因克伐太过、气机壅塞，非实热之洪。各", "c": "主下焦湿热"}, {"id": "ps:两尺+涩", "n": "两尺·涩脉", "o": "两尺涩脉总主下焦精血亏少与寒凝血瘀两类病机。涩脉以血少、血瘀为纲：一则精血亏虚，尺脉不充，见虚损、反胃、麻木等证，治当补肾填精、气血双补；二则寒邪客于下焦，血为寒凝，瘀阻大肠，见痢下黄黑、痛而急迫，治当温寒化瘀。二者一虚一实，虚者涩而小弱，实者紧而涩。虚证多因", "c": "主寒凝血瘀"}, {"id": "ps:两尺+滑", "n": "两尺·滑脉", "o": "两尺滑脉总属实证、热证，病位在下焦。其核心病机为湿热壅遏下焦，气机阻滞，故见少腹疼、小便赤涩、大腹胀满等症；湿热积滞日久，可致下焦不利、中焦气不通。滑脉亦主热盛，洪滑有力为实热之象，热郁于内可致四肢厥逆、渴思饮水。此外，两尺候下焦相火，洪滑有力主相火偏旺，相火", "c": "主湿热"}, {"id": "ps:两尺+紧", "n": "两尺·紧脉", "o": "两尺紧脉总主下焦病机，以寒凝、血瘀、疼痛、正虚邪结为要。紧脉主寒主痛，见于两尺则病位在下焦肾与腰臀。寒邪客于下焦，血被寒凝则瘀，瘀阻大肠则痢下黄黑而痛；寒湿凝滞，气血壅阻则臀痈坚硬肿痛；若紧而无力，则示下焦气血不足，邪毒凝滞，正虚不能托毒。四类病机相互关联：寒", "c": "主血瘀"}, {"id": "ps:两尺+细", "n": "两尺·细脉", "o": "两尺细脉总属肾与下焦虚损之象，以虚证为主，兼见虚实夹杂。细脉主气血不足、脉道不充，两尺候肾，故其核心病机为肾之阴阳精血亏虚。其中细数多主肾阴亏虚、虚火内动；细弱无力或沉细多主肾阳虚衰、虚寒内生；微细或虚细则主肝肾两虚、精血不足。若虚人受邪，则见弦而尺部虚细，为", "c": "主肾阴亏虚"}, {"id": "ps:两尺+虚", "n": "两尺·虚脉", "o": "两尺脉虚总属肾气亏虚、下焦不固，为根本不足之象。其病机可归为四类：一为肾虚不固，封藏失职；二为气虚，肾气不足；三为虚人外感，正虚邪恋；四为气逆上脱，肾不纳气。四类之间相互关联：肾虚不固与气虚同源而异名，均以尺虚为征；虚人外感因正虚而邪恋，气逆上脱由肾虚不摄而气", "c": "主气虚"}, {"id": "p:两", "n": "两部", "o": "两部脉所主病机广泛，总以热、虚、痰、气、瘀、湿热及上盛下虚为纲。热证脉多洪数滑大，虚证脉多细弱虚小，痰饮脉多弦滑，气滞脉多弦紧，血瘀脉多涩，湿热脉多濡数，上盛下虚则寸关实而尺弱。诸类常相兼为病，如痰热、湿热、气滞血瘀、虚中夹实等。脉象须结合部位与兼脉，如两寸主", "c": "主热"}, {"id": "r:中取", "n": "中取", "o": "中取脉所主病机，总以中焦脾胃为枢，兼涉整体虚实。其脉见于中部，或弦、或滑、或数、或虚、或洪大无伦，皆反映中焦气机之升降、痰湿之聚散、食积之阻滞、木火之亢害，以及正气之盛衰。大要可分虚实两端：虚者见软弱、濡缓、虚微、短促或中取不见，主脾胃气虚、肾水亏虚、亡阴阳越", "c": "主虚损"}, {"id": "rs:中取+动", "n": "中取·动脉", "o": "中取·动脉在古籍中多指经脉搏动之处，非单一病脉之象。其总病机以经脉之气为根本，动脉应手反映经气运行；进而通过寸口分候三焦，可察上中下三部病机；又为三部九候诊法之要，用以决死生、处百病、调虚实、除邪疾，故主虚实邪疾之辨；在痫病治疗中，动脉应手处为灸要穴，灸之通阳", "c": "主经脉之气"}, {"id": "rs:中取+弦", "n": "中取·弦脉", "o": "中取弦脉总起来主痰饮湿浊、疼痛、木火与气郁。其脉位在中部，关脉候脾胃，弦为气机郁滞、痰饮内阻之象，故见脘中拒按、隐隐作疼、筑筑而跳，为湿热痰浊交阻于胃，失下行为顺之常；弦又主痛，与拒按疼跳相应；弦为木象，主肝胆气旺，下虚上实之证中部弦必挟木火为患，木火刑金则喘", "c": "主痰饮湿浊"}, {"id": "rc:中取+数+弦+浮", "n": "中取·数弦浮脉", "o": "中取·数弦浮脉总以浮弦数为主，兼右软弱中部稍滑，反映外感与内伤相兼之病机。浮主风邪外袭，弦主疟邪内郁少阳，数主热邪内盛，三者合见，为外感风邪、疟痢并作、邪热内扰之象；右脉软弱中部稍滑，则示内伤饮食、脾虚食滞。诸类之间，外感风邪为诱因，疟痢为病所，热为邪郁之化，", "c": "主外感风邪"}, {"id": "c:动+乱", "n": "乱动脉", "o": "乱动脉总属实证，主风痰壅盛、气血逆乱。其脉来乱动如沸泉，非虚损之象。风痰内壅，气机闭塞，血随气逆，故脉道失和而乱动；外则昏乱颤汗、口噤腹满，甚则颠倒欲绝。原文以“下之则愈”证实邪去正安，脉即转平。可见乱动脉所主，以风痰实证为核心，气血逆乱为病机关键，二者相因，", "c": "主风痰"}, {"id": "c:数+乱", "n": "乱数脉", "o": "乱数脉总以脉数而乱为特征，所主病机涵盖热、虚、火扰、气血扰动四类。数象多主热，或为暑热，或为实火，或为变蒸体热；乱象则示正气溃散、胃气被扰或气血生长变动。诸类之间，热与虚常相兼，如暑热伤津耗气而正虚欲脱；实火急迫可扰胃气而脉乱；小儿变蒸则属生理性气血扰动，非病", "c": "主正虚"}, {"id": "e:乱", "n": "乱脉", "o": "乱脉所主病机广泛，总以脉气失序、阴阳乖乱为纲。其属病者，或为气血逆乱、瘀滞不通，或为邪热内陷、充斥三阳厥阴，或为痰瘀食积壅阻气机，或为客忤秽浊闭窍神乱；甚则正气溃散、胃气衰败、阴阳离决，多为危候。其属生理者，唯小儿变蒸，气血骤长，脉气暂乱，非病脉。诸类之间，实", "c": "主气血逆乱"}, {"id": "c:乱+代", "n": "代乱脉", "o": "代乱脉总主脏气衰微、脉气不续之病机，多见于霍乱吐痢之后。其核心为脾胃虚弱、阴阳清浊相干，致脉道不能接续而见代。据原文，代脉可分四类：脉来代者，脏气衰微；代而绝者，胃气将败，为危候；脉微迟而代者，阳气虚衰；脉代而大者，正气尚能抗邪，犹可疗。四类皆以虚为本，然有轻", "c": "主脏气衰微"}, {"id": "e:代", "n": "代脉", "o": "代脉总属脉气不相接续之象，其病机以虚为本，虚实夹杂。归纳其主病，首为脏气衰微、真元将绝，此为本脉最重之候，多见死证；次为气血虚衰、心气不足、阴血亏虚、肾气亏虚，皆属正虚，致脉道不充、脉行断续；又霍乱吐泻津气暴伤、胸中寒凝阳气不布，亦令脉代。然亦有因痰热壅阻、实", "c": "主脏气衰微"}, {"id": "c:伏+乱", "n": "伏乱脉", "o": "伏乱脉总起来主病机涉及寒热、气血偏颇及五脏病位。其脉象可兼数、迟、滑、涩、大、小、弦、坚等，故所主非单一。数疾主热，迟紧主寒；滑涩大小反映血气多少；长弦、小、下坚上虚、滑微浮、大坚等则分属肝、心、脾胃、肺、肾五脏病位。诸类之间以脉象兼夹为联系，寒热为病性，气血", "c": "主热"}, {"id": "c:伏+坚", "n": "伏坚脉", "o": "伏坚脉总起来主风邪致痉、邪郁深伏、筋脉强急之病机。其脉伏而坚，伏示邪气内郁深沉，坚示脉道坚劲失柔；结合‘直上下行’之象，反映风木劲急、筋脉拘挛。原文以痉病为例，强调‘六气莫不由风而伤人’，痉病现证皆风木刚强屈㑃之象，故伏坚脉所主以风邪为核心，邪郁为病机关键，筋", "c": "主风木劲急"}, {"id": "c:弦+滑+伏", "n": "伏弦滑脉", "o": "伏弦滑脉总属邪实内闭、痰热风阳交炽之候，非虚寒脱证。其“伏”非阳气衰微，乃邪热、气郁或肝阳贼肺致阳郁不达、脉道不利；“弦滑”则主痰热内盛、肝风煽痰、气逆痰升。三类病机各有侧重：热闭痰蒙者，因外感温散失治，热灼液成痰，痰热蒙蔽心包，证见昏厥不苏；气郁痰逆者，因惊", "c": "主热闭痰蒙"}, {"id": "c:微+伏", "n": "伏微脉", "o": "伏微脉总起来主邪闭气机与阳气衰微两端，并可兼见气血不足、积气初结及情志气结。其核心在“伏”：伏为脉道一时隐蔽，多因邪气内闭、气逆不通，或阳衰气脱不续。微则示阳衰或气血不足，故伏微并见，既可主痰浊、寒湿、暑秽等邪闭阳郁之实证，亦可主阳衰欲绝、正虚邪闭之危候。各类", "c": "主痰闭"}, {"id": "c:伏+急", "n": "伏急脉", "o": "伏急脉总属邪闭气机、阳气不达之危急脉象。所主病机主要有三类：一为秽恶温暑诸邪闭阻气机，蒙蔽清窍，见神昏、厥冷、脉伏；二为暑湿秽浊内闭，气血壅滞，见霍乱转筋、肢冷腹痛、目陷脉伏；三为阳气不达，因邪闭或湿浊内阻，阳气不能外达，故脉伏而肢冷。三者相互关联，总以邪闭为", "c": "主邪闭气机"}, {"id": "c:细+滑+微+伏+硬", "n": "伏滑微细硬脉", "o": "伏滑微细硬脉总起来主正虚邪实、虚实夹杂之候。其中伏滑主邪毒内结肠胃，劲硬主邪毒锢结深重，二者属邪实；微细主老人阴虚津枯，属正虚。四类病机相互关联：因阴虚津枯，肠道失润，邪毒易于结聚；邪毒锢结日久，又进一步耗伤阴津，形成正虚邪实之恶性循环。原文脉象揭示老人染疫，", "c": "主邪毒内结"}, {"id": "c:伏+牢", "n": "伏牢脉", "o": "伏牢脉总起来主邪热深伏于里、郁而内实之病机。其脉伏而牢、浮取不应，既示邪闭内实，又示火郁于内不得外达；合数脉则主阴虚内热。三者相互关联：阴虚为本，内热为标，热郁日久则邪闭内实，形成虚实夹杂、郁热深伏之局。故治疗上既需升阳散火以发越郁火，又需阴药收功以养阴血，更", "c": "主火郁"}, {"id": "c:伏+结", "n": "伏结脉", "o": "伏结脉总起来主气机郁闭与积滞内停，其形成多因惊气入于脏腑，导致气乱而郁，郁久成积。伏脉主气闭，结脉主积滞，二者并见，说明气机壅塞与有形积滞并存。原文右关伏结，右关候脾胃，惊气入脏，气机郁结于右胁，积久成形，故右胁有声如虾蟆。三类病机相互关联：惊气入脏是病因，气", "c": "主气机郁闭"}, {"id": "e:伏", "n": "伏脉", "o": "伏脉总属邪闭气壅、阳气不达之象，其病机有虚实寒热之殊。实者多因热邪深伏、寒邪凝滞、痰食瘀血水饮秽浊闭阻气机，或痛极气逆，脉道不通而伏，此即“热深厥深”“寒凝阳郁”之属；虚者多因阳气衰微、阳脱危候，或气血虚而经络壅滞，脉道失充而伏。各类之间，以“邪闭阳郁”为共同", "c": "主热深厥深"}, {"id": "c:促+乱", "n": "促乱脉", "o": "促乱脉总属正虚邪扰、气机乖戾之候。其脉促为阳为热，乱为气血失序、神明失主。所主病机主要有二：一为风阳扰神，因久病正虚，复感舟行热闷，鼓动风阳，扰乱神明，致神糊不语、烦躁不安；二为正虚邪扰，病久阴阳两弱，坎离不交，又遇外因引动，脉见促乱，饮食不进，预后堪忧。二者", "c": "主风阳扰神"}, {"id": "c:动+促", "n": "促动脉", "o": "促动脉总起来主病机为邪实阻滞与热邪内陷两类。其脉象特征为脉动加速中偶现龃龉，往来涩滞不畅，非如结代之歇止。一类因痰血郁于隧道，气血运行受阻，脉见促动而浊，主积痰肝风、痰瘀阻络，甚则痱中之机；另一类因外感之热内陷，促其跳动加速，脉见促急，主热邪内陷、表里俱热。二", "c": "主痰瘀阻络"}, {"id": "c:数+促", "n": "促数脉", "o": "促数脉总属阳热亢盛、气机急促之象，其病机以热为核心，然有虚实之分。实者或为外感风温、温邪内陷营分，或为食积化热、瘴疟热盛，或为瘀热内结，皆邪热壅遏、气血不畅所致；虚者或为阴虚火旺、虚阳浮越，或为营卫大衰、正气欲脱，乃阴不制阳、气机不续之候。各证虽异，然促数之脉", "c": "主阴虚火旺"}, {"id": "c:疾+促", "n": "促疾脉", "o": "促疾脉总起来主阳热亢盛、阴津消涸之证，其脉象促为阳盛搏急，疾为热极躁动，二者相合，反映邪火燎原而阴液耗伤。所主病机主要有四类：阳热亢盛、阴津消涸、虚劳阳亢、痰火内扰。其中阳热亢盛与阴津消涸常并见，如伏暑化燥案中邪火未衰而津液难复，脉促疾无伦，属险象；虚劳阳亢则", "c": "主阴津消涸"}, {"id": "c:数+促+短", "n": "促短数脉", "o": "促短数脉总属危重之象，主气竭、热迫、邪毒攻心及正虚邪陷。其脉短促并见，短为气竭，促为邪滞，数为热迫，三者相合，反映正气衰败、邪气亢盛、热毒内攻的复杂病机。原文两段均见于脚气病气上入腹、胸胁逆满、肩息、呕吐等危候，脉证相符则预后极差，故断为死脉。各类之间相互关联", "c": "主气竭"}, {"id": "c:细+促+坚", "n": "促细坚脉", "o": "促细坚脉总属正虚邪结、阴阳不相顺接之候。细主阴亏，坚主邪伏深入，促主阳结，三者相合，反映正虚于内而邪结于里，尤以阴亏阳结、邪伏厥阴为核心。原文‘平素积劳致虚，邪伏厥阴’点明虚与邪并存；‘神气索然、腹中动气、舌红嗌干、寒热日迟’为阴亏阳结、正虚邪伏之外候。因温清", "c": "主正虚邪结"}, {"id": "c:结+促", "n": "促结脉", "o": "促结脉总起来主邪郁气阻、积热内伏、气血损伤及欲解之兆。其核心病机为脉道不利、气血运行不畅：实邪（外邪、食积、酒积、积热）阻滞气机，或热郁气滞，或气血亏虚，均可使脉来促结不匀。各段中，促结脉或见于外感短气、食积腹痛，为邪阻气滞；或见于积热泄泻、酒积，为热郁气阻；", "c": "主邪郁气阻"}, {"id": "e:促", "n": "促脉", "o": "促脉总属阳盛气急、脉行数中一止之象，其病机以阳热亢盛为核心，然有虚实之辨。实者或为温邪内陷、食积化热、瘀血内结、痰气中阻，邪热壅遏、气血不畅而脉促；虚者或为阳虚寒厥、阴精亏虚、中气败散、脏气不续，阳欲伸而力不足，脉亦促。此外，情志激扰、气逆火动亦可致促。诸类之", "c": "主阳热亢盛"}, {"id": "s:偃刀", "n": "偃刀", "o": "偃刀脉总属真脏败脉，主胃气全无、脏气竭绝之危候。其脉坚劲如刀锋之仰，浮取坚硬、按之无根，刚劲少和，失却胃气柔缓之象。所主病机主要有四类：一为真脏死候，脉失柔和而断死；二为胃气败绝，与屋漏、雀啄等怪脉同属无胃气之象；三为经气不足，真元败竭、经气亏虚；四为气血壅滞", "c": "主真脏死候"}, {"id": "pe:六+乱", "n": "六·乱脉", "o": "六·乱脉总属脉来散乱无伦、失其常序，所主病机以虚、实、神乱为纲。虚者，气血耗散、元气不敛，虚阳外浮，脉数而无力，甚则元气欲脱；实者，风痰壅盛、邪热食瘀交结，气血逆乱，脉乱动如沸；虚实夹杂者，大虚之后正溃邪陷，脉洪大无绪，胃气将败；另有秽浊闭窍、神明失主，脉离乱", "c": "主虚热"}, {"id": "pe:六+代", "n": "六·代脉", "o": "代脉总起来主脏气衰微、真元将绝，亦可见于痰气中结、惊怒伤肝、热盛阴伤及邪盛正虚等证。其核心病机为脉气不相接续，故止有常数。然歇止之脉非皆主死，须脉证合参：若神气不甚衰、脉虽代而症见痰热惊怒，尚可治；若脉代而伴汗出如洗、喘不休、神气外越，则为阴阳离决之危候。散代", "c": "主脏气衰微"}, {"id": "pe:六+伏", "n": "六·伏脉", "o": "伏脉总属邪闭阳气、脉道潜伏之象，其核心病机为气机壅遏、阴阳升降不通。所主病机可归纳为邪闭气机、热深厥深、寒凝阳衰、气郁痰食、正虚邪伏五类。邪闭气机为总纲，涵盖食、痰、瘀、痧等实邪内阻；热深厥深与寒凝阳衰为两端，一为热邪深伏、阳郁不达，一为阴寒内盛、阳气衰微，皆", "c": "主邪闭气机"}, {"id": "pe:六+促", "n": "六·促脉", "o": "促脉总起来主阳盛热结、气机急促不宁之病机，其核心为热盛急迫或气机逆乱而脉行时一止。从所收段落看，促脉所主主要有四类：一为热盛，如阳明壮热、六脉洪数而促；二为痰气交结，如气口数盛而促、痰热中结；三为惊气乱，如忧恚惊怒后气机逆乱而促；四为肝风上扰，如壮火烁阴、肝风", "c": "主热盛"}, {"id": "pc:六+动+乱", "n": "六·动乱脉", "o": "动乱脉总属实证，主风痰壅盛、气血逆乱。其脉来乱动如沸泉，非虚候可比。风痰内壅，气机闭阻，血随气逆，故脉道不宁；痰浊上扰，蒙蔽清窍，则昏乱颤汗、口噤腹满；气血逆乱，筋脉失约，则手足乍屈乍伸。此脉以邪实为主，治当祛风涤痰、降气下逆，邪去则脉自平。两类病机相互关联：", "c": "主风痰"}, {"id": "pe:六+动", "n": "六·动脉", "o": "动脉总起来主气机失调、虚风内动、痰饮内结、邪实壅盛、气血暴脱及脏气衰败等多类病机。其核心在于“动”字：动而躁者多属气机逆乱或邪实壅盛；动而兼虚象者，或为虚风内动，或为气血暴脱；动而中止者，则为脏气衰败之危候。各类之间以气机失常为共同基础：气郁可致痰饮内结，痰饮", "c": "主气机失调"}, {"id": "pc:六+和+动", "n": "六·和动脉", "o": "六和动脉总起来主气机失调，以气郁、阳虚气浮、肝郁未彻为核心病机。其脉象以四动半至五动为和缓之象，但常兼弦、浮、细、数等形，反映胃气渐复而余邪未清、气机升降失常的病理状态。三类病机相互关联：气郁可致升降失常，进而影响阳气外越；阳虚气浮又常伴胃气未复；肝郁未彻则体", "c": "主气郁"}, {"id": "pc:六+和+平", "n": "六·和平脉", "o": "和平脉总起来主邪退正安、脾胃虚弱、气郁脾馁、肾经实热及脉症不符等病机。其核心特征是六部脉象调和，无偏亢之象，故多数情况下反映邪退正安或病情轻浅；但和平脉并非绝对无病，若重按不足或某部独异（如左关滑、右关弱、两尺有力），则提示脾胃虚弱、气郁脾馁或肾经实热等潜在病", "c": "主邪退正安"}, {"id": "pe:六+和", "n": "六·和脉", "o": "六·和脉总以“和”为名，然所主病机非止一端。其正面为邪退正复、胃气渐复之佳兆，脉由浮数弦劲转为和缓收敛，或六脉略和、又和一等，示病向愈；其侧面则脉虽和而软弱、虚细、微小，主气血不足、脾肾亏虚；更有脉和而中州涩弱无力，主土虚湿注；若六脉洪滑、弦劲、坚实，则又主湿", "c": "主邪退正复"}, {"id": "pc:六+大+坚", "n": "六·大坚脉", "o": "大坚脉总属邪盛实积之象。大主邪气盛，坚主实积内结，二者相合，提示实邪壅盛、正气未衰。所主病机以水湿壅盛、实邪积盛为核心，原文见肢体肿胀、烦满欲绝，脉证相合，治当逐水攻实。其下属大迟坚脉则兼迟象，主寒实内结，可见寒凝、食积之证。大坚脉与迟坚脉相较，一为水湿实热壅", "c": "主水湿壅盛"}, {"id": "pc:六+大+小", "n": "六·大小脉", "o": "大小脉总以脉形不匀、变动不居为特征，所主病机涵盖虫积、脾虚夹滞、邪祟、真阴不足四类。虫积与脾虚夹滞常相兼为患，脉大小不等反映气机紊乱、虚实错杂；邪祟则脉忽大忽小、忽沉忽浮，无定体可循，为神志受扰之象；真阴不足则见洪大有力，乃虚阳浮越之假象。四类之中，虫积、脾虚", "c": "主虫积"}, {"id": "pc:六+大+散", "n": "六·大散脉", "o": "大散脉总以散大无力为特征，主正气耗散、虚损不足之病机。其核心为元气外散、阳气不敛，故见脉体散大而按之无力。具体所主，一为气散阳亡，如大汗亡阳、中气虚寒；二为虚损不足，如气血亏虚、年高气弱；三为瘀血内结，散大中兼弦小长坚，属虚实夹杂；四为真火外越，尺脉浮大无根。", "c": "主气散阳亡"}, {"id": "pc:六+大+沉+洪", "n": "六·大沉洪脉", "o": "六脉大沉洪脉总起来主寒饮内伏、饮郁化热及水气泛溢之病机。其脉象以六脉弦紧为基，右脉沉取洪大为变，反映寒饮内停、卫阳被遏，进而饮郁化热、水气上溢的病理过程。弦紧主寒饮，沉取洪大主饮郁化热，沉脉又主水气，三者相互关联：寒饮内伏为病之本，饮郁化热为病之变，水气泛溢为", "c": "主寒饮"}, {"id": "pc:六+大+洪+小", "n": "六·大洪小脉", "o": "六脉洪大在此段中总属邪实壅盛、气血奋起之象，主要主痰饮、疝瘕积块、痹阻络脉三类病机。痰饮内盛、积块壅遏、络脉痹阻，皆致气血运行受阻，脉道充盈鼓动，故见洪大。三者相互夹杂，形成“痹症夹痰饮疝瘕”的复杂证候。然洪大脉亦具动态意义：治疗后脉由大变小，为邪退病减之佳兆", "c": "主痰饮"}, {"id": "pc:六+大+洪+急", "n": "六·大洪急脉", "o": "六脉洪大而急，总属虚损之脉，非实热亢盛。其核心病机为真元耗损、液络大亏，阴不制阳而虚阳外浮。洪大主热，急主弦劲，然此热为虚阳，此急为风动。阴亏于下，则水不荣木，肝阳化风，故见肢节挛搐动摇；血不归肝，则魂不守舍，故昼夜无眠；虚火上炎，则咽嗌结核、瘰疬不消。四类病", "c": "主真元耗损"}, {"id": "pc:六+大+洪+空", "n": "六·大洪空脉", "o": "六·大洪空脉总起来主虚阳外越、真寒假热、内虚寒盛之证。其脉象洪大而空，浮取无伦，沉取无根，是阳气浮散于外而内里虚寒的典型表现。原文所载身大热、口大渴、面赤娇红、四肢厥冷、舌黑滑胖等，皆属格阳戴阳、虚阳外越之候。洪大为空，非实热白虎证，乃内真寒外假热之象。三类病", "c": "主虚阳外越"}, {"id": "pc:六+大+洪+紧", "n": "六·大洪紧脉", "o": "六脉洪大紧盛总属邪实热盛之候。洪大主热盛，紧盛主气壅，合而示热毒炽盛、气血壅实。原文‘热已极矣’点明热毒为病机核心，热极则气机壅滞，气壅则水湿不化，故见通身浮肿；然血淋日久兼肿，非单纯热淋，乃痧毒内蕴、热极气壅、水湿不化所致。放痧筋、用解毒剂后肿痛俱消，继以补", "c": "主热毒炽盛"}, {"id": "pc:六+大+洪", "n": "六·大洪脉", "o": "洪大脉总起来主阳热亢盛、气血燔灼，为邪热充斥之象。其核心病机是热盛，可见于暑温、疫毒、阳明腑实等多种热证，脉多洪大有力，治当清解攻下。然洪大之脉亦有真假：若洪大而空、无伦、中取不见，则为虚阳外浮、真寒假热之危候，不可误作实热攻伐；若洪大而数、滑大浮散，则主痰热", "c": "主热盛"}, {"id": "pc:六+大+浮", "n": "六·大浮脉", "o": "六·大浮脉总起来主虚与虚阳浮越，兼及阴虚火旺、风湿在表。其脉浮大而按之豁然无力者，多属元气亏虚、中气不足，或虚阳外浮、真火不藏；若浮大而豁兼燥渴消瘦，则为阴虚火旺；若浮大或沉伏，则主风湿在表。各类之间，虚损与虚阳外浮常相兼见，阴虚火旺与格阳证需以兼症辨别，风湿", "c": "主虚损"}, {"id": "pc:六+大+浮+虚", "n": "六·大浮虚脉", "o": "六·大浮虚脉总属虚阳外浮、阴盛格阳之候。其脉浮大而虚豁无力，非实热之浮，乃真阴亏于下、虚阳浮于上所致。原文以“阴亏于下，而阳浮于上”为总纲，并见“六脉细微，全无热证”或“浮虚豁大，上热下寒而血衄不止”。故其所主病机，一为格阳证，二为虚阳外浮，三为阴亏于下，三者", "c": "主格阳"}, {"id": "pc:六+大+濡", "n": "六·大濡脉", "o": "六·大濡脉总以濡大无力为纲，主气津两伤、湿滞、气血不足，并可兼夹热伤肺气、败血化热等证。濡主湿，大而无力主气血不足，故其本在虚与湿；然虚中可夹燥、夹热、夹瘀，形成虚实夹杂之候。段3703热伤肺气、气津两伤，兼燥痰内滞；段6223、6518产后败血凝滞，湿滞气血", "c": "主热伤肺气"}, {"id": "pc:六+大+空", "n": "六·大空脉", "o": "大空脉总起来主虚，以阳气虚浮、阴血亏耗为病机核心。其脉象大而无力，按之空豁，浮取无伦，沉取无根，是正气不足、虚阳外浮或气脱不固的典型表现。所主病机可分四类：虚阳外越者，阳气浮散于外而内里虚寒，见真寒假热之候；气脱不固者，脾肾气脱、中气大虚，见脱证下利；阳虚火浮", "c": "主气脱不固"}, {"id": "pc:六+大+结", "n": "六·大结脉", "o": "六脉大结脉总属气机壅滞之实证。大脉主气壅，结脉主气滞，二者相合，反映气机郁结、壅塞不通之病机。其成因多由郁怒伤肝，复感外邪（如暑邪），致气机闭塞，升降失常，故见小便不通、气高而喘等症。此脉所主非虚，乃气滞气壅之实证，治当行气通闭。两类病机相互关联：气壅为气滞之", "c": "主气滞"}, {"id": "pc:六+大+缓", "n": "六·大缓脉", "o": "大缓脉总主湿邪为患，兼涉虚实。缓主湿，大主实或虚，力与软分虚实。实者湿痰壅盛，如经闭脂满、中风痰闭；虚者脾虚湿困，如大缓软脉之脾虚湿盛；寒湿下注者，湿兼寒而正虚；邪风中府者，湿痰内盛兼胃实。四类均以湿为核心，或从实化，或从虚化，或兼寒，或兼风，然皆不离脾湿不运", "c": "主脾湿痰盛"}, {"id": "pc:六+大+缓+软", "n": "六·大缓软脉", "o": "六脉缓大而软，总属脾虚湿盛之候。缓大非实，软示不足，故非邪实，乃正虚。脾主运化，脾虚则水湿不化，湿盛则肢体肿重、腹胀泄泻。脉象缓大而软，既反映脾虚不运，又提示湿邪内停。二者互为因果：脾虚生湿，湿盛困脾。治疗先止泻以治标，后补中以治本，佐以利湿，终获痊愈。故此类", "c": "主脾虚"}, {"id": "pe:六+大", "n": "六·大脉", "o": "大脉总以脉形宽大为主要特征，所主病机有虚实两端。实者，大而有力，主邪热亢盛、气血燔灼，或痰湿内蕴、热毒壅滞，如洪大、滑大之脉；虚者，大而无力，主气血亏虚、中阳不足，或虚阳外浮、真寒假热，如豁大、大而无力之脉。此外，大脉亦见于邪盛正伤、本虚标实之候，脉大示邪气盛", "c": "主热盛"}, {"id": "pc:六+大+虚", "n": "六·大虚脉", "o": "大虚脉总属虚证，以脉大而无力、按之无根为特征，主正气亏虚、虚阳外浮。其病机核心为气血阴阳不足，尤以脾肾亏虚为本。虚大之脉，或为虚阳外浮、阴盛格阳，或为气血亏虚、中气不足，或为脾肾衰败、根本欲脱，或为本虚标实、正虚邪恋，或为中虚寒盛、逼阳外越。各类之间相互关联：", "c": "主虚阳外浮"}, {"id": "pc:六+大+软", "n": "六·大软脉", "o": "大软脉总属正虚之候，以气血亏虚为根本，兼见虚热、湿盛、虚风等变。其脉体虽大而按之柔软无力，大非邪实壅盛，软为不足之象，故整体主虚不主实。从所收段落看，产后去血过多，气血亏虚、脉道不充，则脉软大而小数，虚热上扰而身热汗出、耳鸣头疼，血不养筋而手指颤振，甚则防其发", "c": "主气血亏虚"}, {"id": "pc:六+大+迟+坚", "n": "六·大迟坚脉", "o": "六脉坚大而迟，总属寒实内结之脉。坚大主实，迟主寒，故其病机以寒凝、食积、寒实内结为核心。三者相互关联：寒邪凝滞导致气机闭阻，进而食积内停，形成寒实内结之证。原文病者面黄肌瘦、月事不至、腹大如鼓，形似虚损，然脉象坚大而迟，提示实邪内结，非虚证可比，故补之增剧，当", "c": "主寒凝"}, {"id": "pc:六+实+坚", "n": "六·实坚脉", "o": "实坚脉总属邪实内结、正气未虚之候。其主病机主要有水饮内停、气郁痰阻、实邪内结及暴病邪实四类。水饮内停者，因水湿不化，壅盛于里，脉见坚实；气郁痰阻者，痰气交阻，胃失和降，脉亦坚实弹指；实邪内结者，多因饮食伤胃，有形实邪搏结，右关硬欲搏指；暴病邪实者，病起暴急，邪", "c": "主水饮内停"}, {"id": "pe:六+实", "n": "六·实脉", "o": "实脉总以按之有力、应指坚实为纲，主邪气盛实，正气未至大虚。其病机大致可分四端：一为实热壅盛，热结于里，脉多数而有力；二为里实积结，燥屎、痰食等有形之邪搏结肠胃；三为血虚火旺，阴血亏而相火妄行，脉见细数而右部微实，属虚中夹实；四为邪留正伤，久病羸弱而脉反实，示余", "c": "主实热"}, {"id": "pc:六+小+弱+急", "n": "六·小弱急脉", "o": "六脉小弱而急，总属虚实夹杂之候。小弱主阳气衰微，急主邪热内迫，二者并见，提示正虚邪实。原文病本伤暑，暑热耗气伤津，致阳微厥而脉小无力；暑热内逼，又见脉急。前医误作阴证，投阴药致腹满不省人事，孙兆以五苓、白虎解暑热而愈。可见此脉所主，以阳微为本、邪热为标，暑伤气", "c": "主阳微"}, {"id": "pe:六+小", "n": "六·小脉", "o": "小脉总起来主虚、主郁、主邪退，并可示阳微厥与亡阳危候。其核心病机为正气不足、脉道不充，故虚证居多，如气血两虚、阴阳俱损、阳气衰微；在此基础上可兼气机郁滞，形成沉小、涩小等脉，主里、主郁、主虚。小脉亦可见于邪退病减之际，如热病后脉小则病退，为邪衰正复之象。若阳微", "c": "主虚"}, {"id": "pe:六+平", "n": "六·平脉", "o": "六·平脉总起来主邪退正复、胃气未败、脏复阳潜及体质时令之常，亦可见于孕脉与郁火痰气之轻证。其核心在于脉来和缓流利、无病脉之象，示胃气犹存、正气渐复，故以脉平为邪退之验，以脉平辨胃气未败，以无病脉即平脉主脏复阳潜。然脉平非病愈，余邪未化、脉虽平而瘕胀痹痛未除，故", "c": "主邪退向愈"}, {"id": "pc:六+弦+促", "n": "六·弦促脉", "o": "六·弦促脉总起来主气机郁滞、惊扰气乱、痰气交阻之病机。弦脉主气郁与惊扰，促脉主气机急促不宁，二者相合，反映气郁而急、痰气交阻的病理状态。原文以交肠证为例，因惊致气乱，痰随气逆，清浊相干，便溺易位，脉见弦促，正是惊气乱、痰气交阻之象。四类病机中，气郁为弦脉之基，", "c": "主气郁"}, {"id": "pc:六+弦+大+平", "n": "六·弦大平脉", "o": "弦大平脉在此段中总主气郁、痰壅、食积与邪遏经络之病机。弦为气机郁滞之象，大为邪气壅盛之征，二者相合，反映实邪内结、气机不畅。原文以“弦大为气郁痰壅”为纲，兼见“六脉伏”，伏主邪遏经络、气血不行。许案因食积痰饮，续冒寒湿，抑遏经络，津液不通，痰饮升降为患，故脉见", "c": "主气郁痰壅"}, {"id": "pc:六+弦+大", "n": "六·弦大脉", "o": "六·弦大脉总起来主肝火亢盛、阳热炽盛、阴虚阳浮、气郁食阻、虚损阻滞及风湿拘急等病机。弦为肝旺、气郁、风湿拘急之象，大为火盛、邪盛、虚阳外浮之征。其类别之间，实热类（肝火、阳热）多因邪盛火亢，脉象有力；虚损类（阴虚阳浮、虚损阻滞）多因阴亏或气血不足，脉象虽大而按", "c": "主肝火亢盛"}, {"id": "pc:六+弦+弱", "n": "六·弦弱脉", "o": "弦弱脉总起来主中气虚弱、肝木乘脾、虚中夹滞及虚寒腹痛。其核心病机为虚与滞并存：弱脉主气虚，反映中气亏虚；弦脉主肝木、主痛，反映肝木乘脾、气机不畅。二者并见，说明因过服发散消导之剂损伤胃气，中气亏虚，木来乘土，故见胃脘当心而痛。弦弱相合，虚中夹滞，治当补而敛之，", "c": "主中气虚"}, {"id": "pc:六+弦+微+硬", "n": "六·弦微硬脉", "o": "六·弦微硬脉总起来主肝旺脾虚、虚热迫血之病机。其脉左弦微硬，右濡无力，六至，合而观之，为肝气横逆、脾气虚弱、内有虚热之复合脉象。肝旺则疏泄太过，横逆犯脾，故腹中作疼；脾虚则运化失职，气血生化不足，故饮食减少、身体羸弱、面目黄白无血色；脾不统血，加之虚热迫血，故", "c": "主肝旺"}, {"id": "pc:六+弦+急", "n": "六·弦急脉", "o": "弦急脉总起来主实邪为患，包括饮邪内结、肝郁气逆、热盛邪实及实邪壅滞。其脉象弦而急，弦主饮、主肝、主痛，急主邪盛病进。各段所示：饮邪内结者，水停气壅；肝郁气逆者，疏泄失常、血不归藏；热盛邪实者，邪热亢盛、病势急迫；实邪壅滞者，气逆上攻、痰浊胶结。四类均以邪实为核", "c": "主饮邪内结"}, {"id": "pc:六+弦+急+长", "n": "六·弦急长脉", "o": "六脉弦急长脉总起来主实邪壅滞、气逆上攻与痰浊胶结。弦长劲急为实邪内壅、气机亢逆之象，故见冷气满腹、大痛拥上；两畔细脉沸然如烂绵，则为痰浊胶结、脉道不利之征。三者相互关联：实邪壅滞为病之本，气逆上攻为病之势，痰浊胶结为病之形。原文断为胸膈臭痰，投滚痰丸取效，正说", "c": "主实邪壅滞"}, {"id": "pc:六+弦+沉+紧", "n": "六·弦沉紧脉", "o": "六·弦沉紧脉总属寒邪与饮邪为患，其病机核心为‘寒’与‘饮’相合，表里同病。沉脉主里，弦脉主饮，紧脉主寒，三脉相合，提示外有风寒束表，内有冷饮停聚，表里寒邪均未解除。原文以‘沉弦主饮，紧则为寒’为纲，具体见身疼头眩、手足冷麻为表寒；怔忡作呕、胸中嘈杂、昏厥逆冷为", "c": "主寒"}, {"id": "pc:六+弦+沉", "n": "六·弦沉脉", "o": "六·弦沉脉总起来主里实气郁、气机壅塞之证。沉为病位在里，弦为气郁、气逆、饮停、痛证，二象相合，提示邪气内阻、气机不得宣通。其具体病机可归为五类：气郁气逆、里实壅滞、寒饮内停、肝郁里虚、邪热内郁。诸类之间相互关联：气郁气逆为沉弦之基本病机，气机壅塞不通则成里实；", "c": "主气郁气逆"}, {"id": "pc:六+弦+洪+缓", "n": "六·弦洪缓脉", "o": "六·弦洪缓脉总起来主风热内陷、阳气不布、痰湿阻滞之病机。弦脉主风，洪脉主热，缓脉主湿，三脉相合，按之无力，反映风热之邪下陷阴中，阳气不能正常运行，同时痰湿内阻。风热内陷导致阳气不布，阳气不布又加重痰湿阻滞，三者相互影响。原文以麻木昼减夜甚、开目则麻退为特征，说", "c": "主风热内陷"}, {"id": "pc:六+弦+浮", "n": "六·弦浮脉", "o": "六·弦浮脉总以浮、弦二象合见为特征，主病机可归纳为郁、食积、热三类。浮为邪在表或气机浮越，弦为肝木郁滞、气机不畅，故浮弦首主郁怒伤肝、气机郁滞；若兼右关滑，则示中焦食积内停，气机壅塞；若兼数象，则示积热内蕴，热郁气分。三者常相兼为病，如郁怒致食积化热，形成郁、", "c": "主郁"}, {"id": "pc:六+弦+滑+大+浮", "n": "六·弦滑大浮脉", "o": "六·弦滑大浮脉总属风痰壅盛、阳热内扰之候。浮主风邪外袭，大主阳热亢盛，弦主肝风内动，滑主痰湿内蕴，四者相合，反映风、热、痰、湿交结为患。原文载“六脉浮大弦滑，右甚于左”，右属气分，右甚于左提示病位偏于气分，痰湿壅盛于上。患者身肥白，素多痰湿，春初风木当令，风邪", "c": "主风邪"}, {"id": "pc:六+弦+滑", "n": "六·弦滑脉", "o": "弦滑脉总起来主肝火、痰湿、湿热、痰热及气滞血瘀化热等实邪内蕴之证，其病机核心为“火（热）与痰（湿）交结”或“气滞血瘀化热”。弦主肝郁、肝火或气结，滑主痰湿、湿热或血聚，二者相合，多示实多虚少。具体而言，或肝火挟痰上扰清窍，或相火兼湿热下注，或痰热壅肺，或气滞血", "c": "主肝火挟痰"}, {"id": "pc:六+弦+濡", "n": "六·弦濡脉", "o": "弦濡脉总属本虚标实之候。其本为气血内亏，心劳过度，年高久病，脉道失充，故见濡软；其标为痰湿内滞、气机逆乱，湿阻气逆，故脉弦而濡。三者相互交织：虚则运化无力而生湿，湿滞则气机不降，气逆又耗伤气血。临证当辨虚实主次，治宜泄降化痰佐以扶正，标本兼顾。", "c": "主气逆"}, {"id": "pc:六+弦+濡+软", "n": "六·弦濡软脉", "o": "六·弦濡软脉总起来主本虚标实之证，以气血内亏为本，痰湿内恋、气机不降为标。原文'六脉濡弦带软'，濡软主湿、主虚，弦主气逆，三象并见，提示虚、湿、逆三者交织。其病机核心为心劳血衰、气血两亏，导致脉道软弱；同时痰湿未化，阻滞气机，故脉见濡软而弦。三者关系密切：气血", "c": "主湿痰"}, {"id": "pc:六+弦+紧", "n": "六·弦紧脉", "o": "六·弦紧脉总主寒凝、气郁、痛、饮、瘀、疟、郁热等病机。弦为气机郁滞、肝胆木旺，紧为寒凝收引、邪正相搏，二脉相合，反映寒邪与气滞搏结、络脉拘急不通之象。其核心为“郁”与“寒”：寒凝则气郁，气郁则血瘀、饮停、痛作；郁久又可化热，形成郁热内闭。各证常相互兼夹，如寒饮", "c": "主寒凝"}, {"id": "pc:六+弦+紧+长", "n": "六·弦紧长脉", "o": "六·弦紧长脉总属肝郁寒凝、气滞邪实之候。弦为肝郁，紧为寒痛，长为气滞邪实，三象相合，提示肝气郁结、寒邪凝滞、气机壅塞、实邪内盛。其病机核心在肝，肝郁日久则木克脾土，致阳明空虚、不食经闭；外犯太阳则周身疼；甚则肝风内动，闻声痉厥、终夜抽搐。四类病机相互关联：肝郁", "c": "主肝郁"}, {"id": "pc:六+弦+细+微", "n": "六·弦细微脉", "o": "六·弦细微脉总起来主气虚阳弱、气血亏虚及清阳不升。弦细微脉并见，非单独主某一脏，而是综合反映正气不足、阳气衰微、清阳不升之病机。其核心为虚，因虚致清阳不升，因虚而气血亏耗。弦为气机不畅或清阳不升之象，细为血虚，微为阳虚。三者相合，多见于年高气弱、误治伤正之证，", "c": "主气虚阳弱"}, {"id": "pc:六+弦+细+沉", "n": "六·弦细沉脉", "o": "六·弦细沉脉总起来主里虚、肝郁、水湿与阴寒内凝。沉主里、主水，弦主肝郁、主饮、主痛，细主阴血不足，三象合见，多示病位在里、正气不足而邪气内阻。其病机或为肝失疏泄、气机郁滞，或为里虚夹湿、水饮内停，或为阳微阴盛、寒湿内凝。诸类之间相互关联：肝郁可致水湿不化，里虚", "c": "主肝郁气滞"}, {"id": "pc:六+弦+细+涩+短", "n": "六·弦细涩短脉", "o": "六脉弦细短涩，总属虚中夹实、气血俱病之象。弦主饮，细主虚，短涩主血少气滞，四者相合，揭示饮邪内停、气血亏虚、血少气滞之病机。患者吐血三年不愈，兼痰饮咳嗽、五更出汗，乃阳络损伤，血上溢而久病阳欲亡。诸类之间，虚为本，饮为标，血少气滞为病理产物，阳络伤为出血之直接", "c": "主饮"}, {"id": "pc:六+弦+细+滑", "n": "六·弦细滑脉", "o": "六脉细弦带滑，总属虚实夹杂之候。细主血亏，弦主肝旺，滑主湿痰，三脉相合，揭示阴血不足为本，肝阳偏亢为标，痰湿内滞为兼。原文谓‘血亏肝旺，湿痰未泄’，正与此合。血亏则肝失濡养，肝旺则阳动风生，痰湿内蕴则气机不利，故见神志少安、舌燥等症。三类病机相互关联：血亏为肝", "c": "主血亏"}, {"id": "pc:六+弦+细+紧", "n": "六·弦细紧脉", "o": "六脉弦细紧脉总起来主阳虚寒凝、虚损劳伤，兼见肝郁、饮停、寒湿、瘕气等证。弦为气郁、为减，细为阴血不足、阳衰，紧为寒凝、为痛，三象合见，多示阳气亏虚、寒凝气滞、阴血不足之病机。各段所主虽有偏重，如劳伤吐血侧重虚损，瘕气侧重寒凝肝络，寒湿著痹侧重痹阻，厥阴头痛侧重", "c": "主阳虚寒凝"}, {"id": "pc:六+弦+细", "n": "六·弦细脉", "o": "弦细脉总起来主正气虚损与邪气内郁并存之病机。细为营血不足、阳气衰少，弦为气机拘急、木旺或寒饮内结，二者相合，多示虚中夹实、阴阳俱损。其类别虽分主虚损、主阳微、主寒湿、主饮邪、主肝木乘土、主湿中生热，然皆围绕'正虚邪郁'这一核心：虚损与阳微言其正气之衰，寒湿、饮", "c": "主虚损"}, {"id": "pc:六+弦+细+芤", "n": "六·弦细芤脉", "o": "弦细芤脉总属虚实夹杂之候，所主病机主要有三类：暑湿伤中、气阴两伤与虚寒阳衰。从原文看，暑月吐利发热，六脉弦细而芤，弦为暑湿郁遏气机，细为气弱，芤为津血骤伤，故主暑湿内侵、气阴耗伤；因患者气弱，继用补中益气汤倍参、耆，加麦、味，说明弦细芤脉亦反映气阴两伤之虚。又", "c": "主暑湿伤中"}, {"id": "pc:六+弦+细+软", "n": "六·弦细软脉", "o": "六·弦细软脉总起来主阳虚夹饮、虚劳不足之病机。弦为饮邪内动，细软为体质本弱、阳虚不充，三者相合，揭示阳气虚馁、饮邪内停之本质。其主病以阳虚为本，饮邪为标，虚劳为体质背景。阳虚无力化饮，饮邪上逆则咳、吐血；劳伤阳气，则脉细软而弱。故治疗以温阳化饮、劳者温之为法。", "c": "主阳虚"}, {"id": "pc:六+弦+细+迟+芤", "n": "六·弦细迟芤脉", "o": "六·弦细迟芤脉总属虚寒之候，其病机核心为阴寒内盛、阳衰血少、真阳虚极。弦细主阴寒内盛、脉道拘急；芤迟主阳衰血少、鼓动无力；按之欲绝则示真阳虚极。三者相互关联，阴寒内盛可致阳气衰微，阳衰血少又加重脉道不充，终至真阳虚极、脉微欲绝。此脉多见于寒邪直中少阴、阳气暴脱", "c": "主阴寒内盛"}, {"id": "pe:六+弦", "n": "六·弦脉", "o": "弦脉总属肝木之象，其病机核心为气机郁滞与木旺克土。因肝主疏泄，郁则气结，横逆则犯脾，故弦脉所主以肝郁气滞、木旺克土为基础。在此基础上，因兼邪不同而分化：兼寒则凝滞作痛，兼饮则水停气阻，疟邪客于少阳则脉弦为常。若正气亏虚，脉见弦细、虚软，则为虚损兼郁；若邪盛而胃", "c": "主肝郁气滞"}, {"id": "pc:六+弦+芤", "n": "六·弦芤脉", "o": "弦芤脉总属虚实夹杂之候，以肝旺为标、阴血亏虚为本。弦主肝气偏旺、气机郁滞，芤主阴血骤伤、脉道不充。二者并见，反映肝肾二亏、阴不制阳，虚火上炎，灼伤肺络则咳呛失血，肾亏则耳鸣少力。其病机核心为水亏木旺、本虚标实，肝旺与失血相互影响，阴亏愈甚则肝阳愈亢，肝阳上亢又", "c": "主肝旺"}, {"id": "pc:六+弦+虚", "n": "六·弦虚脉", "o": "六脉虚弦无力，总属气阴俱不足而虚火内动之候。虚脉主气阴两虚，无力示正气衰；弦脉主虚火内动，非实邪为患。气阴不足则脾失健运而食少痰多，虚火上扰则心神不宁而不寐。其病机核心为虚，虚火、脾肺不足皆由气阴亏虚所致。三者相互关联：气阴两虚为根本，虚火内动为标象，脾肺不足", "c": "主气阴两虚"}, {"id": "pc:六+弦+软", "n": "六·弦软脉", "o": "弦软脉总起来主虚证，以阳气不足、气血内亏为本，或兼痰湿、饮邪等标实。其脉象弦而软，弦非实弦，乃虚阳浮动或气机逆乱之象；软为无力，主虚、主湿。从所辖具体脉看，弦濡软脉侧重气血内亏、痰湿内恋；弦细软脉侧重阳虚夹饮、虚劳不足；抽样段落则直接指出阳不恋阴、阳虚失固。各", "c": "主阳虚"}, {"id": "pc:六+弦+迟", "n": "六·弦迟脉", "o": "六·弦迟脉总起来主阳虚、风动与痰饮。迟为阳虚之象，弦主风动，亦主痰饮。阳虚于内，虚风上旋，则脉弦迟而沉部有浮部无；痰浊内阻，气机不畅，则脉弦迟而见于六脉。三者关系密切：阳虚可生内风，阳虚亦可使痰湿不化，痰饮内阻又可引动肝风，故弦迟脉所主病机常相互兼夹，总以阳虚", "c": "主阳虚"}, {"id": "pc:六+弦+长", "n": "六·弦长脉", "o": "弦长脉总起来主气机郁滞、实邪内壅之候。弦为肝脉，主痛、主痰；长为气有余，主气滞邪实。故其病机以肝郁气滞为核心，进而可化火亢盛、气逆于上；实邪坚结、痰浊胶结、寒凝疼痛、湿郁气滞皆可致脉道壅滞而见弦长；外邪在阳明之表亦可见弦长。各类之间相互关联：肝郁气滞为基本病机", "c": "主实邪坚结"}, {"id": "pc:六+弱+和", "n": "六·弱和脉", "o": "六·弱和脉总起来主邪退正复、正气未复之候。其脉象以和缓为基础，兼见弱意，和则胃气未败、脉道不乖，弱则正气尚虚、气血未充。所抽样段落均见于病后，前有邪热或浮数、弦、沉涩等邪象，今邪渐去而脉转和弱，故属病后平脉，示病势平稳向愈。然弱为不足，虽为向愈之象，仍须防虚而", "c": "主邪退正复"}, {"id": "pc:六+弱+缓", "n": "六·弱缓脉", "o": "弱缓脉在此二段中实以弦大、洪大、七至之象呈现，总属阳热亢盛之脉，非虚弱迟缓之常义。其主病机以热盛为核心，分涉少阳、阳明，甚则三焦热邪充斥。原文虽见房事后腹痛水泻等似阴之症，然面赤唇燥、黄苔、烦躁口渴、脉数有力，断为春温阳症。误投理中则呕逆烦躁加剧，反证热邪为患", "c": "主热盛"}, {"id": "pe:六+弱", "n": "六·弱脉", "o": "弱脉总以虚为核心，主气血不足、阳气衰微。其脉形沉细软弱，举按无力，示脉道不充、鼓动乏力。所主病机虽分气血两虚、脾胃虚寒、阳虚气陷、虚中夹痰瘀、虚火劳伤五类，然皆以正虚为枢：气血虚则脉弱不旺，脾胃虚则化源告竭，阳虚则气陷不升，虚而夹痰瘀则弱中兼滑涩，虚而阳浮则弱", "c": "主气血两虚"}, {"id": "pc:六+弱+软", "n": "六·弱软脉", "o": "弱软脉总主虚证，以气虚、脾虚、肾虚及气血大虚为核心。其脉象软弱少力，软主虚，弱主气血不足，故凡见六脉软弱，多提示正气亏虚。从所收段落看，或为脾肺气虚之咳呛脾泄，或为脾虚不统血之痔血便频，或为肾元亏败之牙疳重症，或为气血大虚之脉如游丝。各类之间相互关联：气虚可累", "c": "主脾虚不统血"}, {"id": "pc:六+弱+迟", "n": "六·弱迟脉", "o": "六·弱迟脉总起来主阳虚气衰、肾阳亏虚之病机。迟为阳虚，弱为气衰，二者相合，反映阳气虚衰、气血不足。两尺尤甚，则病位在肾，肾阳亏虚，下焦失于温煦。阳虚不能温养腰膝，故见腰膝足肿、关节疼痛麻木，遇温暖即稍止。此属三阴经虚寒之恙，治宜温肾养肝活络。三类病机相互关联：", "c": "主阳虚"}, {"id": "pc:六+微+动", "n": "六·微动脉", "o": "微动脉总属气血暴脱之危候。其脉象微动无力、六脉不全，反映阴血骤失、气随血脱、脉道不充的核心病机。临床多见于大失血或久病耗伤，致气血将脱，出现精神昏愦、气息若无等症。此脉所主病机单一而危急，提示固脱止血为要。", "c": "主气血暴脱"}, {"id": "pc:六+微+小", "n": "六·微小脉", "o": "六·微小脉总起来主虚与正虚邪恋两类病机。微小脉为气血不足、鼓动无力之象，故主虚；在毒痢脓血等邪气留恋之证中，脉反微小且无寒热，说明正气已衰而邪未净，形成正虚邪恋。两类病机相互关联：虚是根本，邪恋是虚中夹实之变。结合下属沉微小脉所主虚、寒、脱，可知微小脉总以虚为", "c": "主虚"}, {"id": "pc:六+微+弱", "n": "六·微弱脉", "o": "六·微弱脉总起来主正气亏虚，以气虚、阳虚为根本，可累及心、脾、肾等多脏。脉微弱无力，轻则中气不足、脾虚不运，重则脾阳欲脱、大气下陷。其兼证或见心虚不能司血而衄血，或见阳虚火不归元而喉痹，或虚中夹实而见痰壅、腹胀。各段所主虽异，皆以正虚为枢：气虚则推动无力，阳虚", "c": "主气虚"}, {"id": "pc:六+微+洪", "n": "六·微洪脉", "o": "微洪脉总主热证，尤以肺经气分热为核心。微为热势未盛，洪为热邪鼓动，二者相合，提示热在气分而尚未炽盛。原文以骨蒸发热、肤如火燎、吐痰烦渴、烦躁引饮昼盛为据，李时珍用一味黄芩泻肺经气分火而愈，说明微洪脉所主之热，病位在肺，病性属气分。两类病机相互关联：肺热是具体病", "c": "主肺热"}, {"id": "pc:六+微+涩", "n": "六·微涩脉", "o": "微涩脉总起来主气血亏虚、血行滞涩及冲任虚损。脉微为气血不足之象，涩为血行不畅之征，二者相合，多见于虚中夹滞之证。原文'赤白带下，日久黄瘁，六脉微涩'，因带下日久，耗伤气血，冲任虚损，湿浊下注，故脉见微涩。气血亏虚则脉微，血行滞涩则脉涩，冲任虚损则带下不止，三者", "c": "主气血亏虚"}, {"id": "pc:六+微+濡", "n": "六·微濡脉", "o": "微濡脉总属虚候，以阳气虚馁为核心病机。其脉象细软无力、重按即无，反映正气亏虚、鼓动无力。所主病机主要有三：一为阳气虚衰，见足冷、便泻、唇黑舌白等虚寒症；二为虚阳上浮，因下元虚寒、虚阳外越，出现目赤、颐肿等假热之象；三为阴虚有热，脉见细数而无力，属阴损及阳、虚热", "c": "主阳虚"}, {"id": "pc:六+微+缓", "n": "六·微缓脉", "o": "微缓脉总起来主虚损，尤以阳气虚衰、胃气虚弱为核心。微脉主阳气衰微，缓脉主胃气虚弱，二者相合，反映正气不足、鼓动无力之病机。若兼迟脉，则阳不胜阴，元阳大虚之象更著。原文以微缓为有神之常，反衬疾乱变常之病机，说明微缓脉虽属虚象，但尚有胃气，非危候。各类之间相互关联", "c": "主虚损"}, {"id": "pc:六+微+缓+迟", "n": "六·微缓迟脉", "o": "六·微缓迟脉总起来主元阳大虚。迟脉主阳不胜阴，缓脉主胃气虚弱，微脉主阳气衰微，三者相合且“甚微”，则阳气虚衰、鼓动无力之象显著，故为元阳大虚之候。原文强调“纯以挽救阳气为主”，轻则人参理中汤，重则附子理中汤，不得杂一阴分之药，体现阳气衰微为病机核心。此脉所主病", "c": "主元阳大虚"}, {"id": "pe:六+微", "n": "六·微脉", "o": "微脉总属阳气衰微、气血亏少之候，其核心病机为阳衰不能鼓动血脉，故脉来微弱、若有若无。由此可衍生数端：阳气虚极则气随血脱，见失血脉微、势在将脱；阳虚不能温化则寒湿内停，见小便白浊、舌苔白滑、浊阴蟠踞；心阳虚则不能司血，血失所主而妄行，见衄血脉微；阳衰寒凝则脉道不", "c": "主阳气衰微"}, {"id": "pc:六+微+软", "n": "六·微软脉", "o": "微软脉总属虚候，以阳气虚衰、无力鼓动为根本。其主病机可分两端：一为虚阳上攻，因阳气虚浮于上，出现面肿、目赤、痰声等类似实热之象，但脉细软微、重按即无，恰是虚阳外越之据；二为虚寒内盛，因阳衰不能温煦，故便泻足冷，脉来微软无力。二者实为一体两面：阳气虚于下，或浮越", "c": "主虚阳上攻"}, {"id": "pc:六+散+乱", "n": "六·散乱脉", "o": "散乱脉总属虚证，主气血耗散、元气不敛。其核心病机为虚阳外浮与元气欲脱，多因大虚之后，气血不能内守，浮越于外，故脉来散乱无伦、数而无力。轻者仅为气血两虚、虚阳外浮，见发热、昏愦、虚浮等；重者则元气离散、将脱，见汗出如珠、角弓反张等危候。三类病机相互关联，均由虚而", "c": "主元气欲脱"}, {"id": "pc:六+散+代", "n": "六·散代脉", "o": "散代脉总起来主热盛、肝风、邪盛与真虚四类病机。其脉象或促而歇止，或洪大而散，皆以脉来散乱、歇止不匀为特征。热盛则脉促，热灼阴伤而歇止；肝风则风火相煽，脉促而症见瞤动眩晕；邪盛则脉洪大，然按之必虚；真虚则元气下陷，脉散而气不敛摄。四类之间，热盛与肝风常相兼为患，", "c": "主热盛"}, {"id": "pe:六+散", "n": "六·散脉", "o": "散脉总主气阴耗散，为脉道不收、气血涣散之象。其病机可分虚实两端：虚者多为气阴两伤、虚损日久，肺肾亏虚、气不收摄，故见脉散而无力，治宜生脉散益气敛阴，合六味或六君肺肾同调；实者多因邪热内结、少阳邪郁或阳火抑遏，热灼津伤、气机壅滞，脉见散而兼弦数、沉弦或伏，治当清", "c": "主气阴耗散"}, {"id": "pc:六+数+和", "n": "六·数和脉", "o": "六·数和脉总起来主热、虚、血滞及肾阴不足。数脉本主热，但此脉'些数而和'，数而未甚，热势不剧；兼见右寸弱，示肺气虚，故主虚；两尺沉涩，沉主里、涩主滞，示下焦血滞及肾阴不足。诸类之间，以热为始因，热邪伤阴耗气，致气阴两伤，阴虚血少则脉道涩滞，下焦郁滞未解。故数中", "c": "主热"}, {"id": "pc:六+数+坚", "n": "六·数坚脉", "o": "六·数坚脉总属实热为患，以坚为实、数为热为纲。其病机核心是实热内盛，气血壅实，脉道坚劲而数急。具体可分四端：一为实热内盛，脉象直接反映；二为肝火偏亢，因肝脉尤甚而突出；三为湿热下注，见于淋浊溺频茎疼；四为热迫血溢，见于血淋溺血。四类之间相互关联：实热为总纲，肝", "c": "主实热"}, {"id": "pc:六+数+大+沉", "n": "六·数大沉脉", "o": "六·数大沉脉总起来主里热炽盛、邪结阳明。沉主里，数主热，大主邪盛，三象相合，表明热邪内结于里，而非在表。原文所载‘但热不寒、少气烦冤、手足热、面赤口渴’等症，以及‘虽热已而六脉沉数大’的脉象，均指向阳明热盛之瘅疟（温疟）。因此，该脉所主病机可归纳为两类：一是里", "c": "主里热炽盛"}, {"id": "pc:六+数+大+洪", "n": "六·数大洪脉", "o": "六·数大洪脉总起来主热盛，但需分虚实。实者多因外感热邪或热毒内陷，热盛于经，充斥内外，脉见洪大而数，如阳明气分热盛、气血两燔、杨梅疮毒等，多伴高热、烦渴、欲冷饮、舌绛等实热证；虚者则因真阴不足，虚阳浮越，龙雷之火妄作，脉虽洪大而数，却按之无力，或伴真寒假热之象", "c": "主热盛"}, {"id": "pc:六+数+大+浮+洪", "n": "六·数大浮洪脉", "o": "六脉浮大洪数，总属虚阳浮越、虚火上炎之象，非实热实证。其脉虽洪数浮大，却按之无力，且多伴内真寒外假热或阴虚火旺之候。一类为气血暴损，孤阳外浮，脉见浮大洪数而证属真寒假热；另一类为足三阴虚损，虚火不敛，脉洪数不减，甚则虚火灼肺、血肉腐败而成肺痈。二者皆因虚致浮，", "c": "主虚阳外浮"}, {"id": "pc:六+数+大+浮", "n": "六·数大浮脉", "o": "数大浮脉总起来主热与虚阳浮越两端。其脉浮主表、大数主热，故外感风热、表邪夹内热者见之，如金氏妇案；若脉浮大洪数而按之无力，则属虚阳外浮、虚火上炎，非实热可攻。又浮数之脉减大半而敛，为邪退正复、病向愈之机。三类之中，外感与虚阳为病机之常，向愈为脉势转变之候，临证", "c": "主外感风热"}, {"id": "pc:六+数+大", "n": "六·数大脉", "o": "数大脉总起来主热盛与邪实，但须分虚实。实者多因外感热邪、热毒内陷或湿热内蕴，热盛于经，充斥内外，脉见数大有力，如肺肝蕴热、风邪热毒、阳明热盛、湿郁化热等，多伴高热、烦渴、咳血、面赤等实热证；虚者则因真阴不足或中气虚寒，虚阳浮越，脉虽数大却按之无力，如老人痢疾脉", "c": "主实热"}, {"id": "pc:六+数+弦+小", "n": "六·数弦小脉", "o": "六·数弦小脉总起来主肝经风热未净而阴分渐伤之证。弦主肝风内动，数主热邪未清，小主阴分不足，三者相合，反映肝风、热邪与阴伤并存的病机。原文见咳痰气急、肋痛、多梦话、舌苔黄厚、口燥不渴，正是风热扰肺、肝风内动、阴液渐耗之象。其下属数弦细小脉更兼细象，主肝郁化热、阴", "c": "主肝风"}, {"id": "pc:六+数+弦+微", "n": "六·数弦微脉", "o": "六·数弦微脉总起来主热与虚火交织之证。数主热，弦主肝，微弦示火象不剧。其病机主要有两类：一为阴血暴伤、阳失所附而化火上逆之血虚火旺；二为疟后邪衰未尽、脾肾两虚兼有余热之正虚邪恋。两者均以数脉主热、弦脉主肝为基础，但前者侧重阴亏火旺，后者侧重正虚邪恋。数弦微脉所", "c": "主血虚火旺"}, {"id": "pc:六+数+弦+沉+微", "n": "六·数弦沉微脉", "o": "六·数弦沉微脉总起来主阳热闭郁、热动肝风之证。其脉象由沉微与弦数复合而成：沉微反映阳气郁伏，因惊闭气窒、热闭于内，阳不外达；弦数反映热盛动风，因小儿纯阳之体，受热则肝风内动。三者相互关联：惊则气乱，闭则气窒，导致阳热郁伏；郁伏之热不得外泄，进而热甚动风；风动又", "c": "主阳郁热闭"}, {"id": "pc:六+数+弦+沉", "n": "六·数弦沉脉", "o": "六·数弦沉脉总起来主邪热内郁、里实气滞之证。沉主里，弦主痛主郁，数主热，三象复合，反映邪热深伏于里、气机壅滞不通。其具体病机可归为四类：里热壅盛、气机郁滞、邪陷少阴、阴阳易证。四者相互关联：疫毒未清，热邪内陷，则里热壅盛；热壅气机，则胸胁迸痛、二便俱秘；若阴精", "c": "主阴阳易证"}, {"id": "pc:六+数+弦+浮", "n": "六·数弦浮脉", "o": "六·数弦浮脉总以浮、弦、数三象合见为特征，主风温外感、表邪未解、热盛及邪郁经络。浮为邪在表，说明病位浅表；弦为风、为痛、为少阳木气之郁，反映风邪扰动及经络壅滞；数为热盛，提示热邪亢盛。三者相合，常见于春温初起，邪郁肌表，热壅经络之证，症见头项痛、身痛、喉痛、口", "c": "主表邪未解"}, {"id": "pc:六+数+弦+滑", "n": "六·数弦滑脉", "o": "六·数弦滑脉总起来主气滞血瘀、郁而化热之实邪内结。弦主气结，滑主血聚，数主热，三脉合见，反映气机郁滞、血行不畅、瘀血内停，日久郁而化热，形成实邪壅塞之证。原文项彦章治案中，以此脉断为‘气薄血室，实邪也’，并强调治血必先顺气，说明其病机核心在气滞导致血瘀，瘀热互", "c": "主气滞血瘀"}, {"id": "pc:六+数+弦+细+小", "n": "六·数弦细小脉", "o": "六·数弦细小脉总起来主肝郁化热、阴血不足之郁热证。弦主肝郁，细主阴血虚，数主有热，小则示脉道拘紧不畅，合而反映少阳枢机不利、肝郁化热、阴血耗伤之病机。原文寒势往来半年，头痛冷汗、咳嗽、腹痛泻，为肝木乘脾犯肺；无汗用逍遥散疏肝解郁，有汗用清骨散清虚热，正合弦细数", "c": "主肝郁"}, {"id": "pc:六+数+弦+细", "n": "六·数弦细脉", "o": "六·数弦细脉总起来主肝郁化热、阴血不足，兼涉虚火与下寒。弦主肝郁，细主阴血虚，数主有热，三者合见，反映肝胆气机不利、郁而化热、阴血耗伤之病机。其热多属虚热，或为下寒虚火上僭，或为肝胆血热伤及心脾。各段所主虽有偏重，如侧重下寒虚火，侧重阴血亏虚，侧重阴阳两虚，侧", "c": "主阴血虚"}, {"id": "pc:六+数+弦", "n": "六·数弦脉", "o": "六·数弦脉总以弦数并见为特征，弦主肝郁气逆，数主火热内炽，故其总病机为肝郁化火、火热内炽，常兼气逆、痰凝、风动、阴伤等。从所收55段看，弦数脉覆盖广泛：或主肝火亢盛、木火刑金，见厥晕、咳血；或主郁火内扰，见胃脘痛、心脾痛；或主风痰内动，防痫厥、类中；或主温邪、", "c": "主肝火"}, {"id": "pc:六+数+弱", "n": "六·数弱脉", "o": "数弱脉总起来主正气虚损、阴分亏耗，兼有虚热内扰之象。弱为根本，反映正气亏虚、脉道不充；数近六至非实热，乃阴亏不能制阳、虚热内生所致；弦细则示阴血不足、寒束脉道。原文以少年伤寒为例，身冷恶寒、舌苔淡白为表寒未解，然脉数弱弦细示阴分素亏、正虚不耐峻汗，故医者慎用麻", "c": "主虚损"}, {"id": "pc:六+数+微+弱", "n": "六·数微弱脉", "o": "六·数微弱脉总起来主正气虚损、大气下陷，兼有虚热或肝火横恣之象。微弱为根本，反映正气亏虚、升举无力；数脉则因虚而热，或肝火内动。三者相互关联：气虚下陷可致阴火不敛而数，肝气横恣又可加重正气耗伤。原文以少妇经闭、寒热往来、胁下疼、短气为例，示大气下陷为本，肝火横", "c": "主气虚下陷"}, {"id": "pc:六+数+微", "n": "六·数微脉", "o": "六·数微脉总起来主虚热交织之证，以正虚为本，热象为标。微脉主阳气衰微或正气不足，数脉主热，二者相合，多示虚而兼热。其病机大致可分五类：一为一般虚热，正虚而热不剧；二为正虚邪陷，胃气衰败之危候；三为下寒虚火，肾阳不足、虚火上浮；四为积热内蕴，因积滞化热而脉数；五", "c": "主正虚邪陷"}, {"id": "pc:六+数+急", "n": "六·数急脉", "o": "六·数急脉总起来主风火内炽、热盛为患。其脉来急迫而数，反映邪热亢盛、火势急迫，风火相煽则卒倒无知、牙关紧闭、面唇俱赤；热灼筋脉则筋弛身软如无骨；火升痰涌则胶痰满口、机窍闭阻；素积内火又为其发病之根。四类病机以热为核心：积热内蕴是病之本，风火内炽是病之发，痰火闭", "c": "主风火内炽"}, {"id": "pc:六+数+沉+实", "n": "六·数沉实脉", "o": "六脉沉数而实，总属里热邪结之脉。沉主里，数主热，实主邪结，三者相合，明确指向热邪内结阳明、里气不通之病机，故见不大便、汗不得除、舌苔微黄等症。然脉实虽示邪结可下，但患者老年下虚，又提示正虚邪实之候，不可轻下，恐伤正气。故本脉所主病机以里热结聚为核心，兼见正虚邪", "c": "主里热结"}, {"id": "pc:六+数+沉+洪", "n": "六·数沉洪脉", "o": "六·数沉洪脉总以沉、洪、数三象合见为纲，总起来主里热炽盛、风火相扇、络热壅盛一类病机。沉主病位在里，洪数主热势亢盛，故其热非表浅之热，而是深踞于里、壅于络脉之实热。原文一见六脉沉洪而数，即断为少阳络热、风火相扇、热势鸱张，前因误用峻补阳气，致热壅络脉，发为头目", "c": "主里热炽盛"}, {"id": "pc:六+数+沉+浮+洪", "n": "六·数沉浮洪脉", "o": "六·数沉浮洪脉总以洪数有力为纲，主实热壅盛、湿热疫毒及邪实非虚三类病机。洪数示热毒内蕴，浮沉有力示邪气盛实，非虚象；原文喉证见寒热如疟、疼痛、发闷极重，谓感邪太深、红痧之毒难透，脉与证合，故主实热壅盛。按语又指湿热疫毒纵贯三阳，脉洪数主湿热疫毒炽盛，浮沉并见示", "c": "主实热壅盛"}, {"id": "pc:六+数+沉+浮", "n": "六·数沉浮脉", "o": "六·数沉浮脉以数为主，兼不浮不沉之象，总主热郁于内、湿热阻滞及虚郁夹杂之病机。数脉主热，不浮不沉示邪不在表里，热郁三焦，气化不利；若兼湿邪，则湿热交蒸，苔见裛白灰黑；若兼正虚肝郁，则虚实夹杂，误治易危。各类之间相互关联：热郁为基本病机，湿热为常见兼夹，虚郁夹杂", "c": "主热郁"}, {"id": "pc:六+数+沉", "n": "六·数沉脉", "o": "六·数沉脉总以沉主里、数主热为纲，所主病机以里热为核心，涵盖实热结聚、阴虚火旺、瘀热内结、热郁厥深、寒郁化热、血枯肠燥及败象危候七类。其中里实热结与热郁厥深属邪盛有余，脉多沉数有力；阴虚火旺、血枯肠燥属正虚邪恋，脉多沉数而弱细；瘀热内结为有形之邪郁而化热；寒郁", "c": "主里热实结"}, {"id": "pc:六+数+沉+长", "n": "六·数沉长脉", "o": "六·数沉长脉总起来以“数、沉、长”三象为纲，所主病机围绕伤寒六经传变中的热与实展开。数主热，沉主里，长主邪实有余，故其核心为里热实证；然脉象兼浮兼弦兼洪，又分别主表寒、表风、阳明表实与半表半里之热。诸类之间以“热”为共同底色，以“表里深浅”为分界：浮紧、浮缓偏", "c": "主表寒"}, {"id": "pc:六+数+洪+促", "n": "六·数洪促脉", "o": "六·数洪促脉总起来主热盛急迫之证，尤以阳明经证为核心。洪脉主热盛，数脉主热炽，促脉主热盛急迫、脉行急促而时一止。三者相合，反映热邪鸱张、病势迅猛，如原文“有燎原之势”。其主病机可归纳为热盛、热急、阳明经热三类，彼此关联：热盛为根本，热急为病势，阳明为病位。临床", "c": "主热盛"}, {"id": "pc:六+数+洪+紧", "n": "六·数洪紧脉", "o": "六·数洪紧脉总起来主热盛邪实、表里俱病。洪数主热盛，紧主邪实壅结，三者相合，提示热邪亢盛而里有实结，且表里同病。原文虽通体似火证，但脐痛拒按、断为'阳中之阴'，说明热象虽盛而里有实滞，非纯热无滞。苦热芳香一剂热退，正针对洪数热盛与紧实壅结。三类病机相互关联：热", "c": "主热盛"}, {"id": "pc:六+数+洪", "n": "六·数洪脉", "o": "六·数洪脉总以热盛为核心，洪为脉体阔大、热盛气分，数为脉行急迫、邪热内炽，二者相合，主邪热亢盛之实证。然所主病机有层次之别：实热、湿热、热毒、痰火、瘀热多属邪实有余，脉多洪数有力，症见壮热、谵语、肿痛、出血等；虚火则脉洪数而按之无力，或见于久病、年高、阴亏之人", "c": "主实热"}, {"id": "pc:六+数+洪+长", "n": "六·数洪长脉", "o": "六·数洪长脉总属热盛邪实之象。数主热急，洪主热盛，长主邪气有余，三者相合，突出热毒壅盛、邪气亢盛之病机。所主病机主要有三类：一为热盛，二为邪气有余，三为阳明热证。其中热盛是核心，邪气有余强调正邪交争之剧烈，阳明热证则指明病位。各类之间相互关联：热盛则脉数洪，邪", "c": "主热盛"}, {"id": "pc:六+数+浮+洪", "n": "六·数浮洪脉", "o": "六·数浮洪脉总以浮、洪、数三象相合为纲，主热邪为患。浮为邪在表，洪为热盛，数为热急，三者相合，提示热邪炽盛，或表里俱热。从所附段落看，该脉主要见于热毒壅盛、气血壅滞之痈疡病证，如便痈红肿灼热、憎寒作热，脉与证合，故主热毒壅盛、表热及痈疡。其下属更具体脉中，数大", "c": "主热毒壅盛"}, {"id": "pc:六+数+浮+濡", "n": "六·数浮濡脉", "o": "六·数浮濡脉总起来主湿、热、虚阳外越及正虚邪陷。其脉象由濡、数、浮三象复合而成：濡主湿，数主热，浮主虚阳外越或邪在表。在所选两案中，均见于暑湿内陷、中阳式微之危候，故其病机核心为湿遏热伏、正虚邪陷。湿与热合，胶结难解；中阳不足，则虚阳浮越于外，形成浮脉；正虚无", "c": "主湿"}, {"id": "pc:六+数+浮+紧", "n": "六·数浮紧脉", "o": "六·数浮紧脉总起来主湿热痹阻、风邪夹湿与火热急迫。浮主表，紧主痛主闭，数主热，三脉相合，提示外有风邪，内有湿热，火性急迫，气血壅滞。原文以周痹（白虎厉节风）为例，症见遍身筋骨疼痛、肢节肿痛、痛处热如火燎，脉象正合湿热搏结、火性速暴之机。三类病机相互关联：风邪夹", "c": "主湿热痹阻"}, {"id": "pc:六+数+浮", "n": "六·数浮脉", "o": "六·数浮脉总以浮、数二象合参，浮主邪在表分或虚阳外浮，数主热盛或虚热内蒸，故所主病机以热为核心，而分表里虚实。其一为表热，外邪束表、热郁肌表，见发热恶寒、头痛身痛，脉浮数有力，治当解表；其二为阴虚内热，阴亏不敛、虚阳外浮，脉浮数无力，见骨痿、久病形脱、午后热甚", "c": "主表热"}, {"id": "pc:六+数+浮+软", "n": "六·数浮软脉", "o": "数浮软脉总属虚热之象，其核心病机为肾阴亏损、水不制火。数脉虽主热，但浮软无力则揭示热非实邪，乃阴亏于下、虚火浮越所致。原文阴虚喉痹一证，外见内热口渴、唇红颊赤、痰涎壅盛，似有实火，然脉象尺部无神或六脉数而浮软，恰说明病本在阴亏，火为虚火。三类病机相互关联：阴亏", "c": "主虚热"}, {"id": "pc:六+数+滑+大", "n": "六·数滑大脉", "o": "六·数滑大脉总属痰、热、风、虚交织之象。原文自释“滑大为痰，数为热，浮为风”，又谓湿生痰、痰生热、热生风，且因荒于色而真阴竭、脉浮。其核心病机为痰热内盛、风阳动越，兼真阴亏虚。体肥善饮多湿，湿聚成痰，痰郁化热，热盛生风，风痰热邪上扰经络，故见手指掉硬不舒、口角", "c": "主痰"}, {"id": "pc:六+数+滑+急+疾", "n": "六·数滑急疾脉", "o": "六·数滑急疾脉总属阳热实证，以火毒内炽为核心病机。滑主痰热内壅，数急疾主火势急迫，三者相合，反映痰、热、火毒交炽，充斥内外。原文所载纯阳无阴之证，见发热谵语、狂妄躁乱、大渴大烦、便秘溲赤，皆火毒炽盛、阳热有余之候。其病机可归纳为火毒炽盛、痰热内壅、阳热实证三类", "c": "主火毒炽盛"}, {"id": "pc:六+数+滑+洪", "n": "六·数滑洪脉", "o": "六·数滑洪脉总属痰热壅盛之候。洪为热盛，数为邪炽，滑主痰饮，三者相合，示痰热互结、壅阻气机。所主病机以热盛为根本，痰壅为病理产物，痰热互结则成险候；若热毒痰瘀壅肺，则发为肺痈；若病久正伤而邪未退，则成正虚邪盛。各类之间以热为核心，痰为依附，热盛则痰聚，痰聚则热", "c": "主热盛"}, {"id": "pc:六+数+滑+浮+洪", "n": "六·数滑浮洪脉", "o": "六脉浮洪滑数，总属实热痰瘀壅盛之候。浮为热邪在表，洪为热盛，滑为痰瘀，数为热象，四者相合，示热毒痰瘀互结。原文所载肺痈案，咳吐臭脓血、发热夜重、肌肉大瘦，脉大非虚，乃实热壅肺、化腐成痈之征。三类病机中，热盛为根本，痰瘀为病理产物，肺痈为病位与结局，三者层层相因", "c": "主热盛"}, {"id": "pc:六+数+滑", "n": "六·数滑脉", "o": "六·数滑脉总属痰、热、湿、火交结之候。滑主痰湿、血盛，数主热，二脉相合，以热为核心，痰湿为依附，故所主病机以湿热痰火为根本。若热迫血分，则血热妄行；若热结于里，则实热内结；若暑热动风，则暑风痰热；若病久正伤，则兼气虚血热。各类之间，热为共性，痰湿为病理产物，血", "c": "主湿热痰火"}, {"id": "pc:六+数+濡", "n": "六·数濡脉", "o": "六·数濡脉总起来主湿热、津伤、肝风及昏谵之变。其脉象由濡、数复合而成：濡主湿滞津伤，数主邪热未清。在所选温病案中，脉见濡数，伴舌红滑边腻津枯、斑疹未尽、肝风震气冲、神识昏语，乃湿热余邪未净，津液已伤，肝风未平，邪热有内陷心包之势。诸类病机以湿热为核心：湿与热合", "c": "主湿热"}, {"id": "pc:六+数+短", "n": "六·数短脉", "o": "六·数短脉总以数脉与短脉相合为象，数主热，短主气损，故其病机核心为虚热与气损，并可衍生他类。数短并见，多示正气不足而兼热象，如虚热、气损；若正虚邪滞，则见短数脉示正虚邪滞，进而可致积血中焦；若热盛伤阴，则兼真阴虚损。各类之间以虚为本，以热为标，虚热、气损为基础", "c": "主正虚邪滞"}, {"id": "pc:六+数+紧", "n": "六·数紧脉", "o": "六·数紧脉总起来主肝火挟痰、火痰上扰之证。紧脉主痰结、主肝火亢盛，数脉主火盛、主热象急迫，二者相合，提示火痰交炽、有升无降。原文两段均见头晕不寐、少寐头晕，断为肝火挟痰，防其类中或仆中，说明此脉所主以肝火亢盛、痰火互结、上扰清窍为核心。其下属数洪紧脉主热盛邪实", "c": "主肝火"}, {"id": "pc:六+数+细+微+紧", "n": "六·数细微紧脉", "o": "六·数细微紧脉总属正虚邪恋、元气不足兼外感风寒之候。其脉象由紧、数、微、细四者复合而成：紧数反映外邪与正气相争，微细则示元气亏虚、鼓动无力。二者并见，说明并非纯实热证，而是正不胜邪、元气不能托邪外达。原文以“六脉紧数微细，正不胜邪”概括其病机核心，并强调治当“", "c": "主正虚邪恋"}, {"id": "pc:六+数+细+沉", "n": "六·数细沉脉", "o": "六·数细沉脉总以沉细为阴分亏虚、数为内热为基本病机，故其核心所主为阴亏内热。在此基础上，因兼脉与部位不同而分化：或兼右关微弦、发散太过，则血虚火旺；或脾部尤甚、思虑伤脾，则脾虚失统而血不归经；若左关数甚、形神俱败，则非寻常虚劳，乃尸虫内蚀、耗伤气血之重候。四类", "c": "主阴亏内热"}, {"id": "pc:六+数+细+浮+动", "n": "六·数细浮动脉", "o": "六·数细浮动脉总起来主阳气虚浮、阴血不足、有热及胃气未复之病机。浮为阳气外越，细为阴血不足，数为有热，动脉则示肾间动气冲鼓不息，甚则奔豚。诸脉象相合，反映虚阳外浮、阴血亏虚、虚热内生、胃气未复的复杂局面。其中阳气虚浮为关键，阴血不足为其基础，热象可为虚热或阳复", "c": "主阳气外越"}, {"id": "pc:六+数+细+滑+软", "n": "六·数细滑软脉", "o": "六·数细滑软脉总属湿热内蕴、正虚邪恋之候。滑主湿浊，数主余热，细软为正气已伤，四者相合，提示湿浊未化、余热未清而正气已损。原文见身热不解、神糊谵语、舌绛、胸脘略舒，说明湿邪内蕴未清，热势渐退而正虚显露，恐邪陷转变。三类病机相互关联：湿热内蕴为病之本，正虚邪恋为", "c": "主湿热内蕴"}, {"id": "pc:六+数+细+硬", "n": "六·数细硬脉", "o": "六脉细数劲硬，总属邪热内盛、阴液耗伤而邪毒胶结之候。细主阴伤，数主热盛，劲硬有力主邪毒壅滞大肠。三者相合，揭示热毒胶结、阴伤液耗之病机，虽泄泻日久，脉不虚软，知非虚寒，乃‘大肠胶闭证’，邪毒仍在，故治以通因通用。", "c": "主热盛"}, {"id": "pc:六+数+细", "n": "六·数细脉", "o": "六·数细脉总以阴虚内热为核心，细主阴血不足、脉道不充，数主虚热或邪热内郁。其病机大致可分虚实两端：虚者或为气血两虚、阴阳并亏，或为阴虚火旺、火旺神扰；实者或为湿郁化热、瘀血内阻。然脉症合参，细数亦可见于虚寒内盛、格阳于外之假热，如重按无力或不见者，不可概作热证", "c": "主阴虚内热"}, {"id": "pc:六+数+细+软", "n": "六·数细软脉", "o": "六·数细软脉总属阴液亏虚、虚火内扰而气亦不足之候。细主阴亏，数主火旺，软主气虚与虚风。四类病机相互关联：阴液久亏则水不荣木，木失濡养而虚风内动；虚风游走，风化为火，风愈高火愈炽，形成阴亏火旺、虚风内动之局；同时软脉示气亦不足，故见气阴两虚。原文两段均以“扶阳敛", "c": "主阴亏火旺"}, {"id": "pc:六+数+缓", "n": "六·数缓脉", "o": "数缓脉在此段中主要反映热盛与气阴不足的病机。脉数逾六至，为热邪亢盛；不任重按，示气阴已伤。故其总病机为热盛气阴两伤。经清热养阴治疗后，脉数转缓，又成为热退阴复之征。可见数缓脉既主热盛，又主虚损，并可动态反映热退阴复的转归。三类病机相互关联：热盛为始动因素，气阴", "c": "主热盛"}, {"id": "pe:六+数", "n": "六·数脉", "o": "数脉总以‘热’为核心，脉行急迫、至数增多，所主病机涵盖实热、虚热、郁热、痰火、血热及阳浮诸类。实热者脉多数而有力，见于外感、阳明府实；虚热者数而无力或细数，源于气阴亏虚、阴虚内热；郁热者兼沉伏牢弦，热郁不得发越；痰火者兼滑，痰热内壅；血热者见于失血、胎热，热动", "c": "主热盛"}, {"id": "pc:六+数+虚+洪", "n": "六·数虚洪脉", "o": "六脉洪数而虚，总属虚阳外浮、真阴不足之候，非实火。其核心病机为肾经亏损，导致纳气归源、摄水归源功能失常，从而出现头晕、痰涌、麻痹、口渴等症。洪数为阳热之象，虚为不足，二者并见提示虚火上炎、阳气虚热。薛立斋以补中益气合六味丸治疗而愈，说明此脉所主为虚证，而非实热", "c": "主虚阳外浮"}, {"id": "pc:六+数+虚", "n": "六·数虚脉", "o": "六·数虚脉总以虚、数并见为特征，所主病机可归纳为虚热、阴虚阳浮、暑入阴分、痨瘵气阴两虚及热盛伤阴五类。其核心在于“虚”与“数”相合：虚为气液阴血不足，数为虚热或阳浮。虚数无力者，多属中虚液竭、阴不敛阳，虚火上浮；虚数不静者，侧重肾阴亏虚、水火不济；虚数而见于疟", "c": "主虚热"}, {"id": "pc:六+数+迟", "n": "六·数迟脉", "o": "数迟脉在本文段中主要围绕阳明病攻下宜忌展开。脉迟或不数不迟，反映热结而未炽、津伤未甚，故可下；脉数及六至，则主热盛阴伤，下之更伤津液，故禁下。可见数脉主热盛与阴伤两类病机，迟脉及不数之脉主邪结可下之机。数脉之禁下与迟脉之可下，实以热势轻重、津伤程度为枢，数脉所", "c": "主热盛"}, {"id": "pc:六+沉+伏", "n": "六·沉伏脉", "o": "六脉沉伏总属里证、闭证，其核心病机为邪闭阳气、脉道潜伏。沉主里，伏主闭，故凡寒邪、痰浊、实邪内结，或阳气衰微、阴寒内盛，皆可致阳气不能外达，脉沉伏不起。然沉伏有虚实之分：实者多因寒、痰、食、金等邪闭阻气机，脉沉伏而按之有力，如寒闭阳郁、痰气内闭、实邪内结；虚者", "c": "主寒闭阳郁"}, {"id": "pc:六+沉+实+伏", "n": "六·沉实伏脉", "o": "六脉沉伏而实，总属里实寒结之脉。沉伏主病位在里、阳气郁遏，实主邪气结聚。原文一案，壮年寒月入水、饥食冷粥，大寒直中下焦，燥矢内结，故腹大痛、面青黑，脉见沉伏而实。前医误下寒药，痛愈甚，说明寒实结滞非攻下可解，反伤正气。虞天民先温补艾灸，继以巴豆丸温下，脉象示寒", "c": "主里实寒结"}, {"id": "pc:六+沉+实", "n": "六·沉实脉", "o": "沉实脉总属里实证，以沉主里、实主邪盛为纲。其具体所主病机有三类：一为里实热结，燥结瘀热内蕴肠胃，见发热谵语、下痢腹痛、黄疸水肿等；二为寒实内结，大寒直中下焦，燥矢内结，脉沉伏而实，腹大痛面青黑；三为正虚邪实，老年下虚而热邪内结，脉沉数而实，虽示邪结可下，却不可", "c": "主里实热结"}, {"id": "pc:六+沉+小", "n": "六·沉小脉", "o": "六·沉小脉总起来主里、主虚、主郁，其病机核心为气机郁滞于内兼正气不足。沉主里，小主虚，故脉见沉小多示病位在里、正气已伤。从所收段落看，沉小脉所主病机可归纳为四类：气郁食阻、暑湿伤中、肝郁化火、气血郁滞。四者皆以“郁”为共同基础，或食积、或湿阻、或火郁、或血滞，", "c": "主气郁食阻"}, {"id": "pc:六+沉+弱", "n": "六·沉弱脉", "o": "沉弱脉总起来主虚证，以里虚、阳气不足为核心，兼及阴血亏耗。沉主里、弱主虚，故凡六脉沉弱少力，皆示正气内虚。其具体病机可分：虚损（气血津液俱竭）、阳虚（中土阳衰、命火衰微）、气陷（中虚气陷、清阳不升）、阴亏（下虚阴不足、肾阴竭）、阳衰（元气败绝、阳气衰微）、脾肾", "c": "主虚损"}, {"id": "pc:六+沉+微+小", "n": "六·沉微小脉", "o": "六·沉微小脉总起来主虚、寒、脱三类病机。沉小为里虚，主气血大亏；微为阳微，主阳气衰微；二者相合，多见于久病气血耗伤、阳气衰微欲脱之危候。原文两段均见吐血后脉沉小而微，伴手足厥逆、周身俱冷、昏晕欲绝，或误用寒凉致中寒阳困，皆属虚寒脱证。其病机核心为阳气衰微、气血", "c": "主气血大亏"}, {"id": "pc:六+沉+微+弱", "n": "六·沉微弱脉", "o": "六·沉微弱脉总起来主气阴两虚、阳气衰微、津亏液涸及虚热内扰之病机。其脉沉主里，微弱主气弱阳衰，兼细主阴伤，故为虚损之脉。原文所见咽喉微疼、口唇干裂、舌干而缩、心中热干、周身酸软无力、大便不行、小便短少赤涩等症，皆由气虚不能鼓动、阳弱不能温煦、阴血不足、津液亏耗", "c": "主气虚"}, {"id": "pc:六+沉+微", "n": "六·沉微脉", "o": "六脉沉微总属阳气衰微、阴寒内盛之候。沉主里、微主阳虚，故其核心病机为真火衰微、元阳不足。由此可衍生数端：阳虚不能温煦，则见火衰湿停、手足厥冷；阳虚不能鼓动血脉，则久病正乏、脉微欲绝；气随血脱，阳失依附，则暴吐下血而脉沉微；若虚阳浮越或痰浊壅盛，则本虚标实，右寸", "c": "主阳虚火衰"}, {"id": "pc:六+沉+洪", "n": "六·沉洪脉", "o": "沉洪脉总起来主病机复杂，涉及肝风、水饮、里热及寒饮化热等多类。其脉象沉主里、主水，洪主热、主假热，合而可见真热壅盛或假热外现。具体而言，沉洪无伦主肝风鸱张、气火升腾；沉洪主水饮内伏、水极似火；沉洪数主里热炽盛、络热壅盛；大沉洪则主寒饮内伏、饮郁化热。各类之间，", "c": "主肝风鸱张"}, {"id": "pc:六+沉+浮+伏", "n": "六·沉浮伏脉", "o": "六·沉浮伏脉在此段并非专论某脉主某病，而是借“沉伏浮盛”说明脉象有浅深表里之变。总起来看，该脉类所主病机以病位浅深为核心：浮盛主病位偏表、血气偏浅；沉伏主病位偏里、血气偏深。由此可推及血气运行之浅深失调，以及因体段上下、脏腑内外、形志苦乐、资禀厚薄不同而呈现的", "c": "主病位浅深"}, {"id": "pc:六+沉+浮", "n": "六·沉浮脉", "o": "沉浮脉总以脉位浅深言病机，浮沉之变反映邪气与血气之浅深表里。其主病机可归为四类：一主寒湿凝滞，脉沉细紧滑，寒湿搏结经脉；二主湿热疫毒，脉洪数浮沉有力，邪毒充斥三焦；三主沉寒痼疾，脉伏而牢硬，阴寒内结、阳气闭阻；四主病位浅深，浮沉示血气浅深失调。四类之中，前三类", "c": "主寒湿凝滞"}, {"id": "pc:六+沉+涩+伏+结", "n": "六·沉涩伏结脉", "o": "六·沉涩伏结脉总属虚实夹杂之候。沉伏为气血内滞、阳气不达，结涩为血虚津枯、脉道不利。三者相合，既主血虚津枯，又主气血内滞，并可兼见胃气虚。原文一案年五十余、体瘦、便燥、食少、腹痛，虞氏初作血虚治，以四物汤加润下之品；因胃气虚不能受速药，改以蜡匮备急丸缓达下焦。", "c": "主血虚津枯"}, {"id": "pc:六+沉+涩+小", "n": "六·沉涩小脉", "o": "六脉沉涩小脉总起来主里实热结、瘀滞中焦，兼夹酒热暑湿。沉主里，涩主瘀滞，小主脉道收引，数主热，右甚则病在脾胃。患者好酒，暑途得疾，酒热与暑湿互结，瘀滞中焦，形成上脘块痛，故脉见沉涩小数目右甚，按之不为弱，说明里实热结而非虚证。治疗用大承气汤加减，通腑泄热，活血", "c": "主里实热"}, {"id": "pc:六+沉+涩+短", "n": "六·沉涩短脉", "o": "沉涩短脉总属阴脉，其病机核心为阴寒内盛、气血虚滞。原文以浮沉长短滑涩分阴阳，明确沉、涩、短三者皆属阴，且以沉为太阴，提示病位在里。沉主里、主阴，涩主血少气滞，短主气损，三者相合，既可见于阴寒内盛之里实证，亦可见于气血不足、运行涩滞之虚证。各类病机之间相互关联：", "c": "主阴证"}, {"id": "pc:六+沉+涩+紧", "n": "六·沉涩紧脉", "o": "六脉沉紧而涩，总主里寒湿郁、气滞血瘀、脾肾阳虚。沉主里，紧主寒主痛，涩主气滞血瘀，三脉相合，揭示寒湿内郁、气机不畅之病机。原文案中面浮肢肿、腹胀胸闷、便溏尿少，乃风湿抑郁、食填太阴、脏寒生满，浊气逆上为䐜胀，清气下为泄泻，总由出纳之官应运不灵。久延则脾阴伤而及", "c": "主寒湿内郁"}, {"id": "pc:六+沉+涩", "n": "六·沉涩脉", "o": "沉涩脉总属阴脉，以沉主里、涩主滞为纲，所主病机可归为瘀血内阻、痰瘀互结、寒湿内郁、虚滞夹杂、里实热结五类。其共同基础是病位在里、气血运行不畅：涩为血少气滞，沉为病深在里，故凡里证见气血郁滞者多现此脉。五类之间，瘀血、痰瘀、热结属里实，寒湿内郁属里寒实或阳虚，虚", "c": "主瘀血内阻"}, {"id": "pc:六+沉+涩+长", "n": "六·沉涩长脉", "o": "沉涩长脉总属阴中兼阳之象。沉为阴脉，主里、主阴；涩为阴脉，主滞、主血少；长为阳脉，主气盛。三者相合，反映病机以阴寒内凝、气机郁滞为基础，兼有阳气不伸或气血不畅。原文以浮沉长短滑涩分阴阳，并谓沉涩短为阴、浮滑长为阳，沉涩长即一阴二阳之属，说明其病机非纯阴纯阳，而", "c": "主阴证"}, {"id": "pc:六+沉+濡", "n": "六·沉濡脉", "o": "沉濡脉总属阴亏不纳、气不归元之候。其脉沉而濡，沉为在里，濡为阴柔不足，合而示肾阴亏虚、摄纳无权。所主病机以阴虚不纳为核心，由此衍生虚喘上逆与虚热上浮：阴亏则气失所归，逆而上冲为喘；阴不制阳，虚热鼓动则脉数。原文一案，喘病反复，脉数兼沉濡，前医降气不效，反证非实", "c": "主阴虚不纳"}, {"id": "pc:六+沉+紧", "n": "六·沉紧脉", "o": "六·沉紧脉总主里寒为患，其病位在里，病性属寒，并可兼夹气滞、血瘀、痰食、秽浊等。沉主里，紧主寒主痛，故凡寒邪深伏于里、阳气被遏、气机闭阻者，皆可见沉紧之脉。从所辖具体脉看，沉紧而涩主寒湿郁滞、气滞血瘀；沉紧而滑主寒痰内盛；沉紧而弦主寒饮相合、表里同病。抽样段落", "c": "主里寒"}, {"id": "pc:六+沉+结", "n": "六·沉结脉", "o": "沉结脉总属里证，主气机郁滞、阴火内逆及虚损三类病机。沉为病在里，结为气行不畅，故其核心在于“郁滞”。原文论呃逆，指出实者脉沉而逆，为阴火挟木气上冲，火郁于里；虚者脉见虚软，沉结主气滞，乃胃弱阴气不足、气血运行无力而结滞；又沉结可兼见芤涩主阴血不足，沉滑有力主实", "c": "主气滞"}, {"id": "pc:六+沉+缓", "n": "六·沉缓脉", "o": "沉缓脉总起来主里湿、风湿与正虚。沉主里，缓主湿、主风，又缓而无力为虚。故其病机以湿邪内蕴为核心，或兼风邪为风湿，或兼正虚而胃气尚存。原文以沉缓主风湿毒，湿邪深伏下注；原文以沉而无力为缓，主老人气血虚而胃气未绝。三类之间，湿为共同基础，风与虚为兼夹，虚者病势缓图", "c": "主里湿"}, {"id": "pe:六+沉", "n": "六·沉脉", "o": "沉脉总属里证，以“举之不足、按之有余”为基本特征，主病在里、邪结于内或阳气不达。其具体所主，有虚实寒热之异：沉而有力主里实积滞；沉滞主寒凝血滞；沉弦紧主寒饮痰凝；沉数主里热郁结；沉微、沉绝主阳虚寒盛；沉而郁主气郁火郁。诸类之间，以“沉主里”为纲，有力为实、无力", "c": "主里实积滞"}, {"id": "pc:六+沉+虚", "n": "六·沉虚脉", "o": "沉虚脉总属里虚之候，以正气不足为核心。沉主病在里，虚主不足，二者相合，提示脏腑气血亏虚于内。从所举脱肛案看，其病机主要有二：一为中气不足、气虚下陷，升提无力而见脱肛不收；二为阴血亏虚，脉道不充，兼便血日久更耗阴血。二者常相兼为患，气虚不能生血摄血，血亏不能载气", "c": "主气虚下陷"}, {"id": "pc:六+沉+迟+伏", "n": "六·沉迟伏脉", "o": "沉迟伏脉总起来主里寒、饮邪深伏及脾阳不运。沉主里，迟主寒，伏主饮邪深伏，三者相合，说明寒邪在里，阳气被遏，水饮内停。原文'六脉沉迟而伏'，见于太阴脾经溢饮之证，因脾阳不运，水饮内停，故脉沉迟而伏。误用风药更伤阳气，饮邪下注而成痿废。各类之间相互关联：里寒为病机", "c": "主里寒"}, {"id": "pc:六+沉+迟", "n": "六·沉迟脉", "o": "六脉沉迟总属里寒阳虚之脉。沉主在里，迟主寒，合而观之，为阳气不振、阴寒内盛之象。其病机可归纳为：寒邪伏里、阳气亏虚、命门火衰、脏腑虚寒及真阳内竭五类。轻者寒邪困阻中焦，阳气被遏，见吐泻腹痛、四肢厥冷；重者阳气衰微，火不生土，水泉不藏，小便不禁、饮食不进；甚则真", "c": "主里寒"}, {"id": "pc:六+洪+缓", "n": "六·洪缓脉", "o": "洪缓脉总起来主湿郁为患，以湿邪壅盛、气机郁阻为核心病机。洪脉示湿邪壅盛、气机外浮，缓脉示湿性黏滞、脉道弛缓，二者相合，明确指向湿郁。若重按若牢，则示湿邪深着、胶结难解，非轻浅之湿。湿郁阻遏气机，则见憎寒壮热、肢节烦疼、满闷不食等症。三类病机相互关联：湿郁为总纲", "c": "主湿郁"}, {"id": "pe:六+洪", "n": "六·洪脉", "o": "洪脉总以热盛为核心，脉体阔大、来盛去衰，为阳热亢盛、气血燔灼之象。所主病机可分虚实两端：实者热邪充斥，或为实热毒盛，或为气分热盛，或湿热痰郁搏结，脉多洪盛有力；虚者至虚有盛候，虚阳外浮，脉洪而空软无根，甚则但洪无胃气而为危候。各段原文所示，洪脉主热之常，兼滑缓", "c": "主实热"}, {"id": "pc:六+洪+长+坚+硬", "n": "六·洪长坚硬脉", "o": "洪长坚硬脉总起来主阳热亢盛之证。其脉象洪大、弦大、七至，均反映热邪炽盛，充斥三焦。右洪大主阳明热炽，左弦大主少阳热盛，七至则热邪亢极。原文虽见房事后腹痛水泻，似阴症，但面赤唇燥、舌苔黄厚、烦躁口渴、脉洪数有力，实为春温阳症，误投理中则呕逆烦躁加剧，更证实热邪为", "c": "主热盛"}, {"id": "pc:六+浮+弱", "n": "六·浮弱脉", "o": "浮弱脉总主气虚、阳虚，尤以脾胃中气不足、气陷不升为核心。浮为气虚外浮，弱为阳气不足，右关尤甚则专责脾胃。三者相互关联：气虚为总纲，阳虚为气虚之甚，脾虚气陷为气虚在脾胃的具体表现。原文以'气虚非血虚'为断，症见食少、神减、面黄肌瘦、胸满，皆清阳不升、浊阴不降所致", "c": "主气虚"}, {"id": "pc:六+浮+洪", "n": "六·浮洪脉", "o": "浮洪脉总以浮、洪二象相合为纲，浮主邪在表或气逆于上，洪主热盛或火盛阳亢，故总起来主热邪为患，但具体病机有表里虚实之异。实热者，或热盛于气分，或热毒壅盛，或湿热内伏，或表里俱热，脉多浮洪有力；虚热者，气阴两虚、阳浮不摄，脉虽浮洪而重按空软。此外，浮洪亦主气逆火炎", "c": "主热盛"}, {"id": "pc:六+浮+涩", "n": "六·浮涩脉", "o": "浮涩脉由浮与涩相合而成。浮为阳脉，主表、主阳；涩为阴脉，主血少、主阴分不足。原文以浮、沉、长、短、滑、涩分阴阳，明言涩属阴，浮属阳，故浮涩脉总属阴阳相兼之脉，非独主一病。其病机要点有三：一为阴分不足，涩主阴血亏虚、脉道不利；二为阴阳相兼，浮阳与涩阴并见，示阴阳", "c": "主阴"}, {"id": "pc:六+浮+濡", "n": "六·浮濡脉", "o": "浮濡脉总起来主暑湿伤中、气虚阳浮及正虚邪陷三类病机。浮为邪在表或虚阳外越，濡为湿、为气虚，二象相合，既可见于外感暑湿、气机逆乱之实证，又因气虚不固而见汗出如油、气息促迫等虚象。其核心在于湿与虚并存：湿邪困阻中焦，气虚无力运化，暑热内逼则气机逆乱，中阳式微则虚阳", "c": "主暑湿伤中"}, {"id": "pc:六+浮+紧", "n": "六·浮紧脉", "o": "浮紧脉总起来主风寒外束、表邪壅滞之病机。浮主表，紧主寒主痛，二脉相合，提示邪客肌表、营卫郁遏、筋脉拘急。其具体所主，一为风寒表证，见恶寒无汗、头痛身痛；二为风邪袭表，见口噤、拘急、角弓反张；三为寒湿在表，见身体重痛、肢节烦疼；四为表邪壅滞，见身首拘急而痛。诸类", "c": "主风寒表证"}, {"id": "pc:六+浮+缓", "n": "六·浮缓脉", "o": "浮缓脉总主风邪伤卫之太阳表证。其脉浮主表，缓主风，风性开泄，卫气不固，故见有汗恶风。三则原文均以浮缓与浮紧对举，浮紧为寒伤营，浮缓为风伤卫，明确其病机为风邪袭表、营卫不和。所主病机可归为三类：风邪伤卫、表证、太阳经病，三者相互关联，风邪伤卫是核心，表证言病位，", "c": "主风邪伤卫"}, {"id": "pe:六+浮", "n": "六·浮脉", "o": "浮脉总以“举之有余、按之不足”为形，所主病机以表、风、虚、热为纲。其常主邪在肌表，浮缓为风、浮紧为寒，表邪内陷亦可致泻；又主风象，痰热生风、中风先兆可见浮而不敛；虚证中气虚阳浮、卫外不固亦见浮而无力；热郁阳明、热结膀胱可致浮而不显或身热脉浮。此外，浮为阳脉，与", "c": "主表邪"}, {"id": "pc:六+浮+虚", "n": "六·浮虚脉", "o": "浮虚脉总属虚候，其核心病机为正气亏虚、根本不同。从原文及下属脉总述看，浮虚脉所主主要有三：一为虚极欲脱，脉浮虚按之即无，伴汗出不止、神魂飞越，是元气外越之危象；二为虚阳外浮，真阴亏于下而阳浮于上，脉浮大虚豁，可见上热下寒或血衄；三为气阴两伤，因过汗耗气伤阴，脉", "c": "主虚极欲脱"}, {"id": "pc:六+浮+迟", "n": "六·浮迟脉", "o": "六·浮迟脉总起来主阳气外越、气血虚寒、脏气衰败，属虚极欲脱之危候。浮为阳气外浮，迟为气血虚寒，乍有乍无则根本已亏、脉气断续。三者相互关联：气血久枯导致虚寒内生，阳气无根而外越，终至脏气衰败、阴阳离决。此脉象多见于危重病证，预后不良。", "c": "主阳气外越"}, {"id": "pc:六+涩+小", "n": "六·涩小脉", "o": "涩小脉总起来主肝旺脾虚、痰饮内伏、营血不畅之证。其脉象以涩为主，涩为营血不畅、气机郁滞；小则脉道收引，示邪阻脉道。兼见濡软、沉弦等，反映脾虚湿困、肝木乘土、痰饮内停。各病机相互关联：肝气郁滞则木横克土，脾虚不运则湿浊内生，湿聚成痰成饮，痰饮阻滞又加重气滞血涩。", "c": "主肝旺乘土"}, {"id": "pc:六+涩+紧", "n": "六·涩紧脉", "o": "涩紧脉总主气虚阳弱、寒凝气滞、脾胃虚弱三类病机。涩为血少气滞，紧为寒凝收引，二者相合，多因阳气不足，寒从中生，气机阻滞所致。其病位重心在脾胃，因脾胃为气血生化之源，中阳虚弱则寒湿内生，气机不畅，脉道拘涩。三类之间相互关联：气虚阳弱为根本，寒凝气滞为标象，脾胃虚", "c": "主气虚阳弱"}, {"id": "pe:六+涩", "n": "六·涩脉", "o": "涩脉总主气机不畅、血行不利，其病机涵盖气滞、血瘀、津伤血少、痰饮、肺气不利及气虚阳弱诸类。从原文看，涩脉既可因实邪阻滞（气滞、痰饮、瘀血）致脉道不利，亦可因津血亏少、气虚阳弱而脉道不充。各证之间常相互兼夹：气滞可致血瘀，痰饮可阻气机，津伤血少可加重气滞，气虚阳", "c": "主气滞"}, {"id": "pc:六+涩+芤", "n": "六·涩芤脉", "o": "涩芤脉总主阴血不足、火逆上冲、痰热内盛及气滞四类病机。其核心在于胃土伤损，阴火挟木气上冲，导致呃逆。虚者阴血亏虚，脉见芤涩；实者火逆、痰热、气滞，脉兼数、滑大、沉结。诸类之间，虚为本，实为标，阴血不足可致火逆，火逆又可挟痰、滞气，相互交织，故涩芤脉所主病机以虚", "c": "主阴血不足"}, {"id": "pc:六+涩+迟", "n": "六·涩迟脉", "o": "六·涩迟脉总主寒凝气滞、食积内阻及邪伏壅塞之病机。迟脉主寒，涩脉主气滞血瘀、食积内阻，二者相合，多因寒邪外袭或久伏，阳气被遏，气血运行不畅；或食滞中焦，气机壅塞；或伏邪内蕴，枢机不利；或肺胃气壅，痰湿内停。各案虽表现不同，但核心均为实邪阻滞、气机不通，故脉来迟", "c": "主食滞中焦"}, {"id": "pc:六+滑+大+洪", "n": "六·滑大洪脉", "o": "滑大洪脉总起来主热、湿、痰及水亏火盛之候，其核心病机为热邪充斥、湿痰壅滞与阴虚火旺相互夹杂。洪大主热盛，滑主湿痰，二者相合多示湿热痰浊壅阻阳明，脉道充盈而现洪大滑利，如湿热痿证；若兼浮象，则又反映水亏火盛、虚火上炎，洪大虽为热势外扬之标，其本却在少阴水亏不能制", "c": "主湿热"}, {"id": "pc:六+滑+大+浮+洪", "n": "六·滑大浮洪脉", "o": "六脉浮洪滑大，总起来主水亏火盛、虚实夹杂之候。其脉象浮洪滑大，直接反映阳明热盛、火势外扬，故见烦热干渴、头痛牙疼等实热症；然其根本在于少阴水亏，不能制火，故脉虽洪大，实由阴虚火旺所致，并可见失血等火盛动血之症。三类病机相互关联：水亏为病之本，火盛为病之标，火盛", "c": "主水亏火盛"}, {"id": "pc:六+滑+大", "n": "六·滑大脉", "o": "滑大脉总以滑主痰湿、大主邪盛为纲，所主病机涵盖痰湿、热、风、虚及本虚标实。滑大有力多主痰湿、实热或痰热生风，如痰厥头痛、中风先兆、湿热下注等；滑大无力则主气虚、脾虚不运，如痢疾正虚、产后汗多等；若一部滑大而余部沉微，则为本虚标实，如齁喘肺中痰实而脾肾阳弱。诸类", "c": "主痰湿"}, {"id": "pc:六+滑+实", "n": "六·滑实脉", "o": "六·滑实脉总起来主实证、热证，以痰热壅盛、实热内结、土太过为核心。滑主痰盛，实主邪壅，数则为热，故滑实相兼多提示痰热或实热壅聚于内。其病位可在上焦心脑，见神明扰乱；可在里，见热深厥深之假寒；可在中焦脾胃，见土太过而四肢不举。三类病机均属邪气壅实，非虚证，故脉象", "c": "主痰热壅盛"}, {"id": "pc:六+滑+沉+紧", "n": "六·滑沉紧脉", "o": "六·滑沉紧脉总属寒痰内盛、里寒凝滞之候。沉主里，紧主寒，滑主痰，三者相合，揭示寒痰壅盛于里，阳气被阻，不能外达。其病机以寒痰为核心，里寒为病位，阳气不达为表现。原文见胃中大痛、昏卧不知人事、手足微温、身体软重，皆寒痰蒙蔽清阳所致。脉未回则寒邪犹在，温补反助其邪", "c": "主寒痰内盛"}, {"id": "pc:六+滑+沉", "n": "六·滑沉脉", "o": "沉滑脉总起来主里实痰浊积滞，兼及寒痰与阴阳相兼之候。沉主里，滑主痰主食主实，故其核心病机为里有形实邪结聚，包括热毒内盛、痰实壅盛、食积痰滞，三者皆属里实，或兼热或兼积，脉多沉滑有力或数大沉实。若沉滑兼紧，则转为寒痰内盛、里寒凝滞，属里实之寒化。又沉滑可与他脉相", "c": "主里实热"}, {"id": "pc:六+滑+沉+长", "n": "六·滑沉长脉", "o": "六·滑沉长脉总起来主阳热、阴阳相兼及痰湿积滞。原文以浮、滑、长为阳脉，故滑长主阳热；又以沉滑、沉滑而长、浮滑而长时一沉分属一阴一阳、一阴二阳、一阴三阳，说明滑沉长脉可反映阴阳相兼之机，非单纯阳脉；沉主里，滑主痰，长主积，故沉滑而长又主里实痰湿积滞。三类之间，阳", "c": "主阳热"}, {"id": "pc:六+滑+洪", "n": "六·滑洪脉", "o": "六·滑洪脉总属热盛痰湿壅阻之候。洪为热盛，滑主痰湿，二者相合，多示痰热互结、湿热壅盛或食积痰滞。所主病机以热为核心，痰湿为依附，或湿热搏结下焦，或痰热壅于上焦，或阳明热邪夹食，皆脉道充盈滑利。若病久正伤，则见虚中挟实、寒热错杂之象，如脉数近六至而不洪滑鼓指，或", "c": "主热盛"}, {"id": "pc:六+滑+浮", "n": "六·滑浮脉", "o": "六·滑浮脉总属阳脉，以浮、滑二象合见为特征。浮主表、主风、主上焦，滑主痰、主湿、主实，二者相合，总以风邪外袭、痰湿内壅为病机核心。其主病可归纳为四类：主风邪、主痰湿、主风痰、主上焦病。四类之间相互关联：风邪外袭常引动内痰，痰湿内盛易招致风邪，风痰相搏则上扰上焦", "c": "主痰湿"}, {"id": "pc:六+滑+浮+长", "n": "六·滑浮长脉", "o": "六·滑浮长脉总属阳脉，以浮、滑、长三象合见为特征。浮主表、滑主实、长主气盛，三者相合，总以阳气偏盛、邪实有余为病机核心。其主病约有三类：一主阳热亢盛，二主表实邪争，三主阴阳相兼之杂候。原文以浮滑长为阳，与沉涩短之阴相对，并推演一阴一阳、一阴二阳、一阴三阳等兼脉", "c": "主阳热"}, {"id": "pc:六+滑+缓", "n": "六·滑缓脉", "o": "六·滑缓脉总起来主气血充盈、血盛及湿热。滑主血盛，缓为胃气冲和或脾湿，故脉见缓滑多示阴血充盈、冲任流通，或湿热血滞、气不下行。各段均以'六脉缓滑'为据，或断天癸将至，或辨湿热血逆致衄。其类虽分血盛、湿热、气血充盈，实皆围绕血分与中焦，以缓滑为气血壅盛之象，非虚", "c": "主血盛"}, {"id": "pc:六+滑+缓+长", "n": "六·滑缓长脉", "o": "六·滑缓长脉总属平脉范畴，主气血充盛、脾胃健运，为体质强健之征。缓滑而长，三部俱见，示气血旺盛、中焦调和，故虽年届五十而天癸不衰，肌肤润泽。左寸关兼见弦数，则为肝郁化热之微兆，属兼夹之轻症，与多产、情志相关。三类之中，前二者为脉之本象，主生理之常；后者为兼见之", "c": "主气血充盛"}, {"id": "pe:六+滑", "n": "六·滑脉", "o": "滑脉总以痰湿、热盛、血盛为核心病机，其脉往来流利，如珠走盘，主实邪内壅。痰湿内蕴则脉滑，热邪炽盛则滑而数洪，血盛充脉则滑而缓。滑脉兼浮主风痰，兼沉主里实积滞，兼弦主肝火痰湿，兼数主痰热，兼洪主热盛痰壅，兼缓主湿热。各类病机之间，痰湿与热常相合为患，血盛与湿热亦", "c": "主痰湿"}, {"id": "pc:六+濡+弱", "n": "六·濡弱脉", "o": "濡弱脉总属正气亏虚之象，以气血不足、脾肺气虚为核心病机。其脉形细软无力，主脉道不充、鼓动乏力，故凡气血两虚、正气大虚者多见。由气虚而衍生诸症：脾失健运则大便作泻、胸膈不宽；肺气不足则痰多咳嗽；清阳不升则头眩晕、耳中壅塞；气虚卫外不固则汗大出，汗出更耗气阴。痰湿", "c": "主正气大虚"}, {"id": "pc:六+濡+缓", "n": "六·濡缓脉", "o": "濡缓脉总属气虚湿困、痰湿内停之象。其脉柔软而迟缓，既因气虚鼓动无力，又因湿邪困阻脉道。三者相互关联：气虚为根本，气虚不能运化水湿则湿困，湿聚成痰则痰湿内生。原文“气虚痰，面黄肌瘦，六脉濡缓”即示气虚、湿困、痰湿三者并存，而以气虚为本。故濡缓脉所主病机以气虚为核", "c": "主气虚"}, {"id": "pe:六+濡", "n": "六·濡脉", "o": "濡脉总属虚与湿并存之脉。其脉象软而浮细，主脉道松弛、鼓动无力，故首主气虚与湿困：气虚则运化失职，湿浊内生；湿邪弥漫，又耗伤气血。由此衍生气血两虚、脾肺不足，脉见濡弱、濡软。若虚阳外越，则见浮濡、微濡之假热；若阴亏不纳，则见沉濡之虚喘。虚中又可夹实，如坚积、痰湿", "c": "主湿"}, {"id": "pc:六+濡+软", "n": "六·濡软脉", "o": "濡软脉总起来主虚证与湿证，以气血不足、脾虚湿困为本，并可兼见肝旺乘脾、痰饮内伏等标实之象。从所收两段原文看，濡软脉的核心病机是正气亏虚，尤其是气血不足和脾虚，导致脉道松弛软弱；同时，脾虚运化失职，湿邪内困，亦使脉现濡软。若兼见沉弦，则提示肝旺乘脾、痰饮内伏，形", "c": "主脾虚湿困"}, {"id": "pe:六+疾", "n": "六·疾脉", "o": "疾脉总起来主热盛与虚阳外越两类病机。热盛者，邪热鼓动气血，脉行急迫，如原文'四至便作热'，疾脉更甚；虚阳外越者，阴寒内盛，阳气虚衰，格阳于外，脉见疾数，细疾脉总述详论之。二者一实一虚，实热者脉疾而有力，虚阳者脉疾而细弱。疾脉亦见于远行等生理状态，但作为病脉，主", "c": "主热"}, {"id": "pe:六+短", "n": "六·短脉", "o": "短脉总以气损为根本，脉道短缩而不及本位，反映正气不足、推动无力。其主病机以气虚、虚寒为核心，因气弱阳衰则脉短无力；若短而兼数，则虚热内生，或正虚邪滞，衍生积血、湿热等兼证。诸类之间以虚为本，以热为标，虚寒与虚热皆由气损所化，正虚邪滞则为虚中夹实。故短脉总主虚证", "c": "主气虚"}, {"id": "pe:六+空", "n": "六·空脉", "o": "空脉总起来主虚，以气血二气交虚为核心病机。其脉象中空如谷、按之无力，是正气亏耗、脉道不充的典型表现。所主病机可分三类：气血两虚者，因气血亏极而见脉空，伴满肠皆痛、遍体浮黄、少食无寐等症；虚脱危候者，因脉空而神衰，精神失守，有悠悠忽忽而脱之险；久饥气空者，因水谷", "c": "主气血两虚"}, {"id": "pc:六+紧+伏", "n": "六·紧伏脉", "o": "紧伏脉总起来主邪毒深伏、气机壅塞之实证。其紧象主痧毒郁闭、气机壅塞，伏象主邪深脉道不利、痰浊内闭，不匀则示气血运行失序。三者相互关联：痧毒郁闭可致气机壅塞，痰浊与痧毒互结则深伏脉道，闭阻心窍经络，发为痫证。原文以放痧去毒、滚痰丸逐痰降气而愈，印证紧伏脉所主为邪", "c": "主痧毒郁闭"}, {"id": "pe:六+紧", "n": "六·紧脉", "o": "紧脉总主寒、痛、饮、痰、积、郁及虚中挟实之证。其核心病机为寒邪收引、邪正相搏、气机壅塞，故脉见弦急如切绳。寒凝则气郁，气郁则血瘀、饮停、痰结、积成，痛由不通而生；郁久又可化热，形成郁热内闭。紧脉所主以实证为主，然兼细弱则示虚中挟实。各类之间相互关联：寒为根本，", "c": "主寒"}, {"id": "pc:六+细+小", "n": "六·细小脉", "o": "细小脉总主虚损，尤以气血两虚、阴血大伤为核心病机。细主血虚，小主气弱，故凡气血不足、阴血耗伤者多见。在此基础上，可兼夹瘀血、木乘等实邪：如小产后瘀血内停兼气血两伤，脉见细小；脾胃久亏而肝木乘土，亦见细小。此外，阴血大伤可致虚阳浮动，出现左关浮大等兼脉。各类病机", "c": "主阴血大伤"}, {"id": "pc:六+细+弱", "n": "六·细弱脉", "o": "六脉细弱脉总起来主气血大虚、正气不足之病机。细为血少，弱为气虚，故其核心为气血两虚。所主病机可分为五类：气血两虚见于痢疾、溃后等；元气未复见于霍乱后；正虚托毒无力见于牙痈；筋脉失养见于少腹结块；虚火寒水凌心见于舌黑虚候。各类之间均以虚为本，或为纯虚，或虚中夹实", "c": "主气血两虚"}, {"id": "pc:六+细+微+伏", "n": "六·细微伏脉", "o": "六·细微伏脉总属虚实夹杂之候，以气血不足为本、邪闭气机为标。微细主气血亏虚，伏主邪气内闭，二者并见，提示正虚与邪闭并存。所主病机主要有三类：一为气血不足，脉道不充；二为邪闭气机，阳气不达；三为痧毒深伏，络脉壅塞。三者相互关联：气血不足则抗邪无力，邪易内闭；邪闭", "c": "主气血不足"}, {"id": "pc:六+细+微", "n": "六·细微脉", "o": "六·细微脉总起来主虚，以阳气衰微、气血亏少为基本病机。微为阳衰，细为血少，脉道鼓动无力，故凡见六脉微细，多属正气不足之候。其具体所主，约分六类：阳气虚衰者，见冷汗肢厥、少阴中寒；气血两虚者，见关格呕血、胃弱便结；虚阳上浮者，见失血衄血而手足厥冷；真气衰败者，见", "c": "主阳气虚衰"}, {"id": "pc:六+细+沉+微+弱", "n": "六·细沉微弱脉", "o": "六·细沉微弱脉总起来主气虚、阳弱、寒凝三类病机。细沉微弱之脉，其形成机理在于气虚无力鼓动、阳弱不能温煦、寒凝阻滞气血，三者常相互影响：气虚日久可致阳弱，阳弱则寒凝内生，寒凝又加重气血不畅。原文以四君子汤治脾胃气虚为主，兼述胃寒气满、脾胃虚弱等证，涉及脉虚无力、", "c": "主气虚"}, {"id": "pc:六+细+沉+微", "n": "六·细沉微脉", "o": "六·细沉微脉总起来主阳虚、气虚、里寒三类病机，三者常相互影响：气虚日久可致阳弱，阳弱则寒凝内生，寒凝又加重气血不畅。原文两案均以六脉沉细而微为据，一为年高暑月下利致中气大虚、脾肾阳衰，一为附骨痈脓清稀、皮肤凉、呃逆，皆脉证俱寒之象。沉主里、细主虚、微主阳衰，合", "c": "主阳虚"}, {"id": "pc:六+细+沉+涩", "n": "六·细沉涩脉", "o": "六·细沉涩脉总起来主虚寒、寒湿内闭及气血不畅。沉主里，细主虚，涩主寒湿凝滞、气血不畅，三者相合，多示里虚寒湿、阳气不达之证。原文以‘六脉沉细而涩’辨为中寒湿而非中风，强调其与实邪中风之浮大弦滑迥异。寒湿内闭可致牙关紧、不能言、肢体瘫、神昏欲绝；虚寒内生则阳气不", "c": "主寒湿内闭"}, {"id": "pc:六+细+沉+疾", "n": "六·细沉疾脉", "o": "六·细沉疾脉总属阴证伤寒、寒盛阳衰之候。沉主里，细主虚，疾主寒盛格阳，三脉相合，反映阴寒内盛、阳气虚衰、虚阳外越之病机。其主病机可归纳为三类：一为阴寒内盛，见四肢逆冷、指甲面色青黑、腹疼；二为虚阳外越，见燥渴、虚汗不止、时狂言；三为里虚寒结，见心下胀满、结硬。", "c": "主阴寒内盛"}, {"id": "pc:六+细+沉", "n": "六·细沉脉", "o": "沉细脉总属里虚寒之象，以阳气衰微、气血不足为基本病机。沉主里、细主虚，合而观之，多因阳气不能鼓动血脉、阴血不能充盈脉道所致。其具体所主，或为阳虚寒盛，阴寒内盛而格阳外浮；或为气血两虚，元气内亏而脉道不充；或为中焦虚寒，脾胃阳弱而寒湿内困；或为水湿内停，阳虚不能", "c": "主阳虚寒盛"}, {"id": "pc:六+细+涩", "n": "六·细涩脉", "o": "六·细涩脉总起来主阴血亏虚、气滞血瘀，并可兼见脾肾虚败、肾虚不摄、正虚络痹及营亏痰凝等证。细为阴血不足，涩为血行不畅，二者相合，根本空虚而气血运行涩滞。各段所主虽异，然皆不离‘虚’与‘滞’两端：或阴血亏少而脉道不充，或气滞血瘀而脉行不畅，或脾肾虚败而胃气衰败，", "c": "主阴血亏虚"}, {"id": "pc:六+细+滑+微+伏+硬", "n": "六·细滑微伏硬脉", "o": "细滑微伏硬脉总起来主正虚邪实、虚实夹杂之候。其脉象由伏、滑、微、细、劲、硬复合而成：伏滑主邪毒内结肠胃，为实邪壅聚；微细主老人阴虚、津液枯竭，为正气亏虚；劲硬主邪毒锢结不解，气血阻滞。诸象并见，揭示正虚与邪实并存，虚者阴虚津枯，实者邪毒结聚，且邪毒因虚而锢结，", "c": "主邪毒内结"}, {"id": "pc:六+细+滑+沉+紧", "n": "六·细滑沉紧脉", "o": "六脉沉细紧滑，总属寒湿相搏、凝滞经脉之候。沉主里，细主虚，紧主寒，滑主痰湿，四者相合，揭示体虚而寒湿痰浊乘虚袭入，凝滞经脉，筋脉失柔，发为痓症。其病机以寒湿为核心，虚为发病基础，痰为兼夹，经脉凝滞为病位所在。紧滑有力说明邪实非纯虚，故温补不应，当以祛寒化湿、通", "c": "主寒湿"}, {"id": "pc:六+细+濡", "n": "六·细濡脉", "o": "六·细濡脉总主湿浊内蕴与气血亏虚，其病机可归为三类：一为湿浊蒙蔽，脉道不利而见濡细模糊；二为气血两虚，脉道不充而见细濡无力；三为元气大虚，根本亏败而见细濡无力伴脱证。三者常相互关联：湿浊内蕴可耗伤气血，气血亏虚又可加重湿浊不化，而元气大虚则为气血亏虚之极。原文", "c": "主湿浊"}, {"id": "pc:六+细+疾", "n": "六·细疾脉", "o": "六·细疾脉总属阴证伤寒、寒盛阳衰之候。细为阳衰，疾数为虚阳外越，二脉相合，反映阴寒内盛、阳气虚衰、虚阳外越之病机。其主病机主要有四类：一为阳衰，阳气虚衰不能鼓动血脉；二为虚阳外越，阴寒内盛格阳于外；三为寒盛格阳，阴寒内盛、虚阳浮越；四为寒痰满中，寒痰内盛蒙蔽清", "c": "主阳衰"}, {"id": "pc:六+细+紧", "n": "六·细紧脉", "o": "六·细紧脉总起来主虚中挟实之证，以积块内结与气血亏虚并见为特征。紧脉主积块内结、气机壅滞，细脉主气血不足、元气亏虚。二者合见，反映病机为虚实夹杂：实者积块内结、气机壅滞；虚者气血不足、元气亏虚。原文痞块症患儿肚大青筋外露为积块内结之实，消积破块药过服后饮食渐少", "c": "主积块内结"}, {"id": "pe:六+细", "n": "六·细脉", "o": "细脉总以虚为本，主气血两虚、阴血不足、阳气衰微，脉道不充为其共同特征。其具体所主，可因兼脉与程度不同而分：单纯细脉多主气血两亏、真元不调；细而微、沉、疾者，主阳虚寒盛、阴寒内盛或虚阳外越；细而欲脱者，主血脱气陷、格阳失守之危候；细而状如烂绵者，主痰浊内结；细兼", "c": "主气血两虚"}, {"id": "pc:六+细+虚", "n": "六·细虚脉", "o": "六·细虚脉总主气血亏虚、元气不足之病机。虚为阳气衰微，细为阴血亏少，脉道不充，故其核心为气血两虚。然随程度与兼症不同，可细分：轻者主气血大虚，见脉虚细无力；重者主元气衰微，见虚细欲绝或欲脱；兼脾胃症者主脾胃虚损；正虚而邪恋者主正虚邪恋；妊娠见之则主胎元不固。诸", "c": "主气血大虚"}, {"id": "pc:六+细+软", "n": "六·细软脉", "o": "细软脉总起来主虚，以气血两虚、脾肾虚损为核心，并可涉及阴阳两伤、虚寒、虚中夹湿滞及水不涵木等类。细为阴血不足、脉道不充，软为阳气不振、鼓动无力，故细软并见首先反映气血两虚；气血亏虚进一步累及脾肾，则见脾肾虚损；阴阳互根，久虚则阴阳两伤；阳虚生寒，则见虚寒之候；", "c": "主气血两虚"}, {"id": "pe:六+结", "n": "六·结脉", "o": "结脉总属气机阻滞、脉道不利之象，所主病机以实邪壅塞为核心，包括气滞、痰阻、寒滞及邪实内结等。原文五段中，或见六脉见结因郁怒气滞，或六脉俱结因痰寒塞滞经脉隧道，或结而有力因痰积胶固，均示气血痰食寒邪阻滞脉道，使脉气结而不畅。诸类之间相互关联：气滞可生痰，痰阻可加", "c": "主气滞"}, {"id": "pc:六+缓+和", "n": "六·缓和脉", "o": "缓和脉总起来主胃气调和、无病之常，以及病中胃气渐复之佳兆。其核心在于“和缓”为脾胃冲和之气的外现，故平人见之无病，病中见之向愈。然所附案例中，缓和脉亦见于湿热壅盛之血淋，此非缓和独主湿热，而是洪数脉中兼有和缓，提示热盛而胃气未败。故缓和脉所主病机可归纳为：一主", "c": "主无病"}, {"id": "pe:六+缓", "n": "六·缓脉", "o": "缓脉总以湿、虚、风、热、胃气和、血盛为六大病机。缓为胃气之象，其常义主脾胃冲和、无病之常；然兼见他脉则主病各异：兼沉、濡、大、洪者多主湿，湿性黏滞困阻脉道故缓；兼微、虚、迟、无力者主虚，阳气虚衰鼓动无力故缓；兼浮者主风邪伤卫；兼洪、数、滑、大而有力者主热盛，热", "c": "主湿"}, {"id": "pc:六+缓+迟", "n": "六·缓迟脉", "o": "缓迟脉总起来主阳气虚衰、湿遏阳郁之候。其核心病机为阳气不足，鼓动无力，脉行迟缓；或湿邪黏滞，困遏阳气，脉道不利。从具体脉象看，迟主阳不胜阴，缓主胃气虚弱，微缓迟相合则主元阳大虚。各类之间相互关联：湿遏阳气为外湿困阻，阳不胜阴为内寒偏盛，胃气虚弱为中焦气虚，元阳", "c": "主湿遏阳气"}, {"id": "pe:六+芤", "n": "六·芤脉", "o": "芤脉总主失血与血虚，其脉象中空，如按葱管，为脉道失充之征。凡崩漏、小产、经水淋漓等失血证，或久病血亏，皆可见芤。失血之后，阴血亏虚，脉道不充，故芤主血虚；血虚则气易上逆，肝气冲逆，故芤亦主气逆；若失血过多，阴损及阳，则见阴阳两虚。各病机之间以血虚失血为本，气逆", "c": "主失血"}, {"id": "pc:六+虚+实", "n": "六·虚实脉", "o": "虚实脉总以虚象为主，主正气亏虚，然虚中每夹邪实，或为邪陷欲脱，或为虚中夹实，或为正虚风动。其脉象多微细、虚软无力，甚则无伦次如虾游，反映气血不足、元气衰败。然虚脉亦可见假实之象，如瘀血内阻致脉细数无力，误补后脉虚变实；或虚而病形实，当辨虚实真假。各类之间，正虚", "c": "主正气虚衰"}, {"id": "pc:六+虚+小", "n": "六·虚小脉", "o": "虚小脉总主气血两虚、阴阳俱损。其脉形虚小乏力，为脉道不充、正气亏虚之象。两段原文均见六脉虚小乏力：一因大病久耗，气血未复；一因经水淋漓，去血过多，阴亏阳弱。虚小脉所主病机以气血两虚为基础，可兼失血阴亏与阳气衰弱。三者相互关联：气血久亏则阴血不足，阴损及阳则阳气", "c": "主气血两虚"}, {"id": "pc:六+虚+弱", "n": "六·虚弱脉", "o": "六脉虚弱脉总属正气不足、虚象为主。其主病机可归为三类：一主虚火，因正虚阳浮而现热象；二主正气不足，为气血阴阳亏虚之本质；三主劳伤，因劳损致虚。三者相互关联，虚火与劳伤皆以正气不足为基础，脉虚弱是辨识虚实、指导温补的关键。原文以口疮为例，强调脉虚弱者不可妄清，当", "c": "主虚火"}, {"id": "pc:六+虚+微", "n": "六·虚微脉", "o": "虚微脉总主正气大虚，包括元气虚弱、气血大虚、气阴两虚及津液内亡。其脉象虚微，反映人体精气营血亏耗，脏腑功能衰退。各段所主虽有侧重：或为元气虚弱、心神虚损，或为气血大虚、虚寒夹饮，或为气阴两虚、暑伤脾胃，或为津液内亡、化源不足，但均以正虚为根本。虚微脉提示病机以", "c": "主气阴两虚"}, {"id": "pc:六+虚+缓", "n": "六·虚缓脉", "o": "六·虚缓脉总以虚、缓两象合参，主正气不足、脉道无力之病机。其核心为脾土不及，因脾主四肢、主运化，虚缓脉见于六脉，提示中气虚弱、气血生化乏源，故主脾虚气弱；脾虚则水湿不运，湿邪内困，故兼主湿困；气血不足则脉道不充，故又主气血亏虚。三者相互关联：脾虚为根本，湿困为", "c": "主脾虚"}, {"id": "pe:六+虚", "n": "六·虚脉", "o": "虚脉总主正气不足，以气血两虚、阳气衰微为核心。其脉象按之空软无力，反映气不充脉、血不盈脉。因兼脉与程度不同，可分出数类：虚而无力主气血两虚；虚而迟微主阳虚寒盛；虚而浮数或空大主虚阳外浮；虚而涩弱主脾虚湿困；虚而兼邪脉主正虚邪恋；虚而数细主虚损痨瘵。各类之间以“", "c": "主气血两虚"}, {"id": "pc:六+虚+芤", "n": "六·虚芤脉", "o": "虚芤脉总主阴血亏虚、气血不足，兼见虚火内扰之病机。芤主失血，虚主神气不足，二者相合，反映血去脉空、气血未充。失血之后，阴血亏虚，水不制火，则虚火内生，故见潮热、烦热；若阴不潜阳，肝阳偏亢，则见胁痛。其病机以阴血亏虚为本，虚火、肝旺为标，虚实夹杂。两类脉象共同提", "c": "主失血"}, {"id": "pc:六+虚+软", "n": "六·虚软脉", "o": "虚软脉总属正气不足之象，以虚为本，软为无力之征。其主病机涵盖气虚、血虚、脾胃两伤、阳衰及中气下陷，诸类相互关联：脾胃为气血生化之源，脾胃伤则气血两虚，气虚日久则阳衰，中气不足则下陷。原文四段中，案63、15032、17372均见六脉虚软，分别对应脾胃气虚未复、", "c": "主气虚"}, {"id": "pc:六+虚+迟", "n": "六·虚迟脉", "o": "六·虚迟脉总起来主虚寒。虚脉主正气不足，迟脉主寒，二者相合，反映阳气虚弱、阴寒内盛之病机。原文所述饮食入胃胀而吐、吐出物极冷、小腹亦胀、背心怕冷而胀等症，皆中焦虚寒、运化失职之象，与脉象相应。此脉所主以虚寒为核心，虚为正气亏虚，寒为阴邪内盛，二者互为因果，形成", "c": "主虚寒"}, {"id": "pe:六+软", "n": "六·软脉", "o": "软脉总起来主虚，以正气不足、气血亏虚为根本，兼可主湿、主阳虚，并在特定情况下主阴分伏热。其脉象举之柔软无力，软为不足，故凡见软脉多提示虚证；下属细软、虚软、弱软、微软等脉总述均围绕气血、脾肾虚损展开，可见虚为软脉核心病机。然软脉非独主虚：脾虚运化失职则湿邪内困", "c": "主虚"}, {"id": "pe:六+迟", "n": "六·迟脉", "o": "迟脉总主寒与阳虚，其核心病机为阳气不足、阴寒内盛，鼓动无力，故脉行迟缓。从原文看，迟脉所主病机可归纳为寒、阳虚、虚寒、热结可下、水停、寒积等类。其中寒与阳虚为基本病机，虚寒为阳虚与寒合，水停为阳虚不能化水，寒积为寒与积结，热结可下则为迟脉在阳明病中的特殊表现，", "c": "主阳虚"}, {"id": "pe:六+长", "n": "六·长脉", "o": "长脉总起来主气有余、邪实壅盛之候。其脉象特点是脉体过于本位、往来有力，原文所谓“六脉俱长，三部九候往来有力，寸尺特盛”，属太过之脉。长而有力者，非虚脱之象，而是正气未衰、邪气壅盛之征。从所举医案看，富商惊悸遗泄、湿烂脓下，貌似虚损，然脉反长盛有力，王中阳断为湿", "c": "主邪实壅盛"}, {"id": "pe:六+革", "n": "六·革脉", "o": "革脉总属虚证，以浮取有余、按之不足、如按鼓皮为特征，主气血虚极、精血亏耗及血虚火旺。其脉形外强中空，反映正气内虚而虚阳外浮。各类病机相互关联：气血虚为本，精血亏耗为甚，血虚火旺为变，总不离虚。临床多见于失血、崩漏、亡血及久病精亏之人，为虚劳危候之一。", "c": "主虚"}, {"id": "p:六", "n": "六部", "o": "六部脉所主病机广泛，总以热、虚、郁、痰、寒、风、瘀为纲。热证多见数、洪、滑、大之脉，因热邪鼓动气血，脉行急迫；虚证多见虚、细、微、弱之脉，因气血阴阳亏虚，脉道不充；郁证多见弦、紧、涩之脉，因气机郁滞，脉道拘急；痰饮多见滑、弦之脉，因痰湿阻滞，脉道不利；寒证多见", "c": "主热"}, {"id": "pc:关+伏+结", "n": "关·伏结脉", "o": "关·伏结脉总起来主气机郁闭、积滞内停及惊气入脏之病机。伏脉主气机郁闭，结脉主积滞内停，二者并见于右关，反映脾胃气机壅塞、积滞成形。其病因多由惊气入于脏腑，惊则气乱，气乱则气机郁闭，积久成形，发为积病。故脉诀以右关伏结为积病之脉。三类病机相互关联：惊气入脏为始动", "c": "主气机郁闭"}, {"id": "pe:关+伏", "n": "关·伏脉", "o": "关·伏脉总起来主气机郁闭、邪实内结之病机，涵盖食积、寒饮、积滞、热积、痰气及阳郁气滞等多类证候。其共同特点是实邪壅塞中焦，阳气不能外达，脉气被遏而伏。食积气阻者，食填胸中，升降不通；寒饮内伏者，寒邪束饮，中脘凝塞；积滞内结者，惊气入脏，积久成形；邪实内闭者，热", "c": "主食积气阻"}, {"id": "pe:关+促", "n": "关·促脉", "o": "关·促脉总起来主阳盛热结、气血瘀滞、气机郁迫及食积内停等病机。促脉为脉来急促而时一止，其核心在于邪气内迫、气血壅滞，脉道不利。从所收段落看，阳盛热结与瘀血内蓄常相兼为患，如瘀热内结之蓄血证；气机郁迫则涉及肝郁气逆、胆府倒置等；食积气滞则见促结并现。各类之间以邪", "c": "主阳热内结"}, {"id": "pe:关+动", "n": "关·动脉", "o": "关·动脉总主邪气搏结、气血壅滞与脏腑功能失调，其病机可归纳为痰浊中焦、内风动跃、肝阳上冒、邪热扰心、寒凝血瘀五类。动脉以“厥厥动摇”为特征，动主搏击不定，关候中焦脾胃，故首责痰浊壅聚与脾虚木盛；若兼滑则痰湿，兼弦横则肝阳亢逆，兼摇摇有力则邪热扰心，兼尺寸虚无则", "c": "主痰浊中焦"}, {"id": "pc:关+和+平", "n": "关·和平脉", "o": "关脉和平本为无病之象，但在病脉中，关部出现洪滑、弦硬等异常，则主热盛、气逆、上盛下虚等病机。段19896关前洪滑主上焦热盛，合尺虚而为上盛下虚；段20505关脉弦硬主肝胆气逆与热盛；段20707右关脉平和则示邪退正复。可见关脉异常多与热、气逆、上下虚实相关，而", "c": "主热盛"}, {"id": "pe:关+和", "n": "关·和脉", "o": "关部和脉所主病机，总以脾胃气机为枢，涵盖邪退正复、正虚不足、湿热郁滞、肝郁气滞、阴虚火浮及阴阳偏盛六类。其脉象或和缓圆活，示胃气来复、邪退向愈；或无力细弱，示气血阴阳亏虚；或数滑弦硬，示湿热痰浊壅滞；或弦涩结，示肝郁气滞血瘀；或细数弦大，示阴虚火浮；或大而偏盛", "c": "主邪退正复"}, {"id": "pe:关+坚", "n": "关·坚脉", "o": "关·坚脉总起来主气机失常与痰浊壅塞两类病机，其具体脉象有坚而有力、坚弦、滑坚等不同。坚而有力、坚弦者，多因大气下陷、药力搏激，气机逆乱于中，尺寸极沉而关部独坚，症见心悸、痞塞、冷汗等，非实热内结；滑坚者，则为痰浊胶固，壅塞肺胃，气机不得宣通，症见喘咳、晕绝。二", "c": "主气陷药激"}, {"id": "pc:关+大+动", "n": "关·大动脉", "o": "关·大动脉在所选段落中均以“两关厥厥动摇”为特征，总属内风动扰之象。其病机核心为风阳不安，脉动摇不定即风性主动之征；而风动之根在于肝肾本虚，水不涵木，故原文以补肾生肝为治本。动脉减轻则内风暗熄，说明该脉主要反映内风之轻重进退，并提示本虚标实的病机本质。两类病机", "c": "主内风"}, {"id": "pc:关+大+实", "n": "关·大实脉", "o": "关·大实脉总起来主邪热壅盛、脾胃邪实。其脉象实大，实为邪气实，大主病势盛，故所主病机以邪实壅滞、热盛为主。原文两段均见关脉实大，一为土太过之脾胃邪实壅滞，一为胃火刑金之邪热壅盛，二者皆属邪实热盛范畴。其中，热盛为病机之性，邪实壅滞为病机之体，胃火刑金为邪热壅盛", "c": "主热盛"}, {"id": "pc:关+大+小", "n": "关·大小脉", "o": "关·大小脉总起来主阳气不潜、上盛下虚，兼及阴阳偏盛与气血郁滞。其典型脉象为寸关大而尺小，寸关大示阳气浮越于上，尺小示下焦阳虚不能潜藏，故见口干、上气不下、足冷不温，原文断为阳气不潜，治用阴中阳药引阳归宅。此外，脉大又为阴阳偏盛、气血留滞之象，如关格之脉人迎寸口", "c": "主阳气不潜"}, {"id": "pc:关+大+弱", "n": "关·大弱脉", "o": "关·大弱脉总属虚证，主气血不足、大虚之候。其脉大而弱，大则为虚，弱为气血不足；兼尺脉涩小，涩主血少，小主气虚。寸关候上中焦，尺候下焦，上下皆见虚象，故整体反映气血大虚。具体而言，关脉大弱侧重脾胃虚衰，运化无力；尺脉涩小侧重下焦精血亏耗。三者相互关联，脾胃虚衰可", "c": "主气血大虚"}, {"id": "pc:关+大+沉+伏", "n": "关·大沉伏脉", "o": "关·大沉伏脉总起来主痰、气、中焦壅塞，核心病机为痰气交阻、中焦壅塞。原文出自反胃痰气证，谓“寸关脉沉或伏而大”，并自注“沉伏主痰气壅滞，大主痰浊搏结”，又言“二脉皆示中焦壅塞、气痰交阻之机”。可见沉伏因痰气内壅、脉道不畅，大因痰浊搏结、邪实搏击，二者相合，反映", "c": "主痰"}, {"id": "pc:关+大+沉+浮+小", "n": "关·大沉浮小脉", "o": "关部大沉浮小脉（此段以浮大、滑大为主）总属阴阳虚实错杂之候，不可一概而论。其脉象虽见浮大、滑大，似为阳实，然原文反复申明须辨有力无力、有根无根。若浮大有力，主气实血虚；若大至四倍以上，则为关格真虚；若大而无力、重按全无，则属阴证假实。三类病机皆围绕“大”脉展开", "c": "主气实血虚"}, {"id": "pc:关+大+洪", "n": "关·大洪脉", "o": "关·大洪脉总起来主阳热亢盛、虚阳外浮、痰热内蕴及脉道变异等病机。洪大为热盛鼓动气血之象，故实热证多见，如肝火、心火、热瘴、肝火乘土；然洪大亦可见于虚阳外浮，如阳虚自汗、水亏火旺、胃气外浮，其脉多浮大无力或沉取滑；痰热交阻则洪大兼滑；反关脉洪大乃脉位变异，非病脉", "c": "主实热"}, {"id": "pc:关+大+浮+洪", "n": "关·大浮洪脉", "o": "关·大浮洪脉总起来主风邪在表、积热内盛、痰热中阻之证。浮脉主风邪外袭，洪脉主积热内盛，滑脉主痰，大脉主热，关脉主中焦，诸脉相合，反映风邪闭郁、痰火积热壅盛于中焦之病机。此脉虽大发热似惧，实为有余实证，非阴虚所致。各类病机相互关联：风邪外袭为诱因，痰火积热为素因", "c": "主风邪在表"}, {"id": "pc:关+大+浮+涩", "n": "关·大浮涩脉", "o": "关·大浮涩脉总起来主邪热壅盛、气机郁滞，兼有气血不足之虚实夹杂证。浮大主邪热壅盛于上，多见于肺胃；涩主气滞血少、郁结不通。二者并见，说明热郁于中而气机不畅，故见胸膈烦热、咳嗽等症。在发背灸法辨证中，浮大或涩脉又提示元气虚实不同，既有邪实又有正虚，治疗宜甘温托里", "c": "主热壅气滞"}, {"id": "pc:关+大+浮", "n": "关·大浮脉", "o": "关·大浮脉总起来主邪热壅盛、表邪未解、虚阳上越及阴阳偏盛等多类病机。浮大之脉，因热盛鼓动气血而主热盛，因外邪袭表而主表邪，因正气虚衰、虚阳浮越而主虚阳上越，因邪实正虚并见而主虚实夹杂，因阴阳偏盛、气血留滞而主关格。各类之间相互关联：热盛与表邪常相兼为病，虚阳上", "c": "主表邪"}, {"id": "pc:关+大+疾", "n": "关·大疾脉", "o": "关·大疾脉总起来主燥热内迫、阳动不潜，兼有阴液不足。右寸关搏而疾大，为阳明燥气鼓舞之征，燥热内迫则脉道鼓动急迫；阴液未充则阳易旋动，阳动不潜亦致脉疾大。三者相互关联：阴液不足为根本，燥热为诱因，阳动为病机关键，共同导致衄血复发。故其脉象反映燥热、阳动、阴虚的复", "c": "主燥热"}, {"id": "pc:关+大+空", "n": "关·大空脉", "o": "关·大空脉总属热盛津伤、阴血不足之候。其脉右寸关空大，主气分热盛而津液耗伤；左脉细小，主肝肾阴血不足。壮热微寒、舌绛渴饮为热炽气分之征，空大脉示热邪鼓动气血而津伤不能充脉；左细小则示阴血亏虚。故本脉所主病机以气分热盛为核心，兼见津伤与阴血不足，三者相互关联：热", "c": "主气分热盛"}, {"id": "pc:关+大+缓", "n": "关·大缓脉", "o": "关·大缓脉在古籍中主要出现于以人迎气口辨内外伤的语境。其脉象缓而大，既可主外感风邪，又可主内伤不足，关键在于脉位不同：见于人迎（左手）者为外伤，见于气口（右手）者为内伤。外感风邪时，风性疏泄故脉缓，邪客肌表故脉大；内伤饮食劳役时，脾胃受损、正气不足，气口脉亦现", "c": "主外感风邪"}, {"id": "pe:关+大", "n": "关·大脉", "o": "关·大脉总以邪实壅盛中焦为核心，兼及虚实两端。大脉主邪气盛，关候肝脾，故实邪壅滞、痰火湿热、肝郁化火、积块内结皆见关脉大而有力；然虚证亦可见大，如虚阳外浮、脾虚气弱、阴阳关格，其脉多浮大无力或豁大不任按。各类之间，实邪类以痰火湿热、肝郁、积块为主，彼此常相兼夹", "c": "主邪实壅盛"}, {"id": "pc:关+大+虚", "n": "关·大虚脉", "o": "关·大虚脉总属虚实夹杂之候，以虚为本，以实为标。虚大脉主气阴不足，为病之本，见于右关则脾虚气弱，见于六脉则气虚无力；弦大脉主肝火亢盛，为病之标，见于左关则肝郁化火；大脉兼洪滑则主痰火壅盛，为实热之标。三者相互交织：气阴亏虚，则津液不归正化，酿生痰饮湿浊；痰湿郁", "c": "主气阴两虚"}, {"id": "pc:关+大+长", "n": "关·大长脉", "o": "关·大长脉总以胃中积热、胃气有余为核心病机。右关候脾胃，脉体长大，为胃气充实有余之象；兼见浮洪、洪数，则示热盛于胃。胃热循经上炎，上朝于肺，肺受火刑，故见积热咳嗽。四类病机相互关联：胃气有余是基础，积热是核心，热盛是程度，肺受火刑是传变结果。脉症相因，皆从右关", "c": "主积热"}, {"id": "pe:关+实", "n": "关·实脉", "o": "关·实脉总起来主邪实壅盛于中焦，以脾胃为病位核心，兼涉肝胆。实脉主邪气实，关部候中焦，故凡有形实邪内结、气机壅滞者皆可见之。其具体所主，因兼脉不同而有所偏重：兼弦则肝木太过、气逆壅盛；兼滑则痰热实邪壅盛；兼大则邪热壅盛、脾胃邪实；兼数则食积化热、内结胃肠；兼沉", "c": "主肝实气逆"}, {"id": "pc:关+小+濡", "n": "关·小濡脉", "o": "关·小濡脉总属虚象，主阴亏阳弱、气血不足，兼有虚火内郁。其脉形小濡，为脉道不充、鼓动无力之征，反映正气亏虚。从原文看，右脉细耎无力主脾肺气虚，左寸涩主心血不足，关弦数主肝火内郁，尺濡小主肾阴亏虚。四类病机相互关联：素体阴亏阳弱为本，脾肺气虚、心血不足为气血之虚", "c": "主肾阴亏虚"}, {"id": "pe:关+小", "n": "关·小脉", "o": "关·小脉总以正虚为基本病机，尤以气血两亏、脾胃虚弱为核心。小为脉道不充，关候中焦，故凡细小、虚小、沉小、涩小、濡小等，皆示气血不足、脏腑亏虚；脾虚失运则湿浊内停，或化热、或兼痰，形成虚中夹实之候。其兼脉又揭示不同转归：兼弦数则肝郁化火，兼滑则痰凝气滞，兼芤则失", "c": "主虚"}, {"id": "pc:关+小+软", "n": "关·小软脉", "o": "关·小软脉总属虚候，以气虚、脾虚不运为核心病机。两段原文均见右关软小不疏，一者明言“软小为脾胃气虚”，伴中脘作疼、喜温恶寒、食后不疏即疼，显系脾胃虚寒、运化迟滞；一者与右寸软小、左尺濡小并见，断为“气火虚”，而关滑数又示痰火实，形成虚实夹杂之候。可见软小脉主正", "c": "主气虚"}, {"id": "pe:关+平", "n": "关·平脉", "o": "关脉总起来主热盛、气逆、上盛下虚、虚损及邪退正复等病机。关脉异常多与热、气相关：洪滑、弦硬、略旺等象主热盛，弦硬又主肝胆气逆；关前洪滑合尺虚则为上盛下虚；虚大无力或濡软主脾胃虚损；而关脉渐平或平和则示邪退正复。各类之间相互关联：热盛与气逆常相兼，气逆可致上盛下", "c": "主热盛"}, {"id": "pc:关+弦+伏", "n": "关·弦伏脉", "o": "关·弦伏脉总以积、寒、痛、阳郁为四大病机。弦主气机收引、经隧拘急，伏主邪气深结、阳气内闭。二者相合，反映寒邪或积块内结、气血凝滞不通之证。原文以寸、关、尺分候积之部位，又明言“弦紧，亦为积，为寒痹，为疝痛”，说明弦紧之象可主寒积、寒痹、疝痛；而“脉弦而伏者，腹", "c": "主积"}, {"id": "pc:关+弦+促", "n": "关·弦促脉", "o": "关·弦促脉总起来主肝郁气逆、阴亏火旺及木火刑金三类病机。弦为肝木强横，促为气机郁迫，故左关弦促主肝郁气逆；右部细数，细为阴亏，数为火旺，故主阴亏火旺；两者合见，木火刑金，肺痿将成，痰随气升，故主木火刑金。三类之间，肝郁气逆为始动，阴亏火旺为内在基础，木火刑金为", "c": "主肝郁气逆"}, {"id": "pc:关+弦+和+硬", "n": "关·弦和硬脉", "o": "关·弦和硬脉总起来主肝胆留邪与木气偏亢。左关候肝胆，脉见弦硬不和，既反映肝胆留邪未净，又显示木气刚劲失和、易乘肺胃。原文虽咳嗽大减、红痰已无，但痰色青黄、脉仍弦硬，说明邪未尽退，病机重点在肝胆，并涉及肺胃受乘之虞。两类病机相互关联：留邪为因，木亢为果，共同构成", "c": "主肝胆留邪"}, {"id": "pc:关+弦+和", "n": "关·弦和脉", "o": "关·弦和脉总起来主肝气横逆、气火上逆与肝阴不足三类病机。弦劲不和为肝气横逆之象，气火上逆则见咳呛胁痛、失血，而失血后肝营自虚，脉仍弦劲示肝阴不足、气火未平。三者相互关联：肝气横逆为始动因素，气火上逆为病理表现，肝阴不足为失血后的本质，共同构成肝胃络伤、气血逆乱", "c": "主肝气横逆"}, {"id": "pc:关+弦+坚", "n": "关·弦坚脉", "o": "关·弦坚脉在此段中总属气机逆乱、非实热内结之候。其核心病机为大气下陷兼药力搏激：尺寸极沉主气陷不达，关脉坚弦有力则因误用二陈推荡，药力搏激所致，故非实热内结。临床见心内动悸、痞塞短气，甚则全身一战、冷汗满额、心跳连次。两类病机相互关联：气陷为本，药毒搏激为标，", "c": "主气陷"}, {"id": "pc:关+弦+大", "n": "关·弦大脉", "o": "关脉弦大，总属肝郁气滞、邪实火盛之象，然有虚实之别。左关弦大多主肝郁化火、气滞实邪、痰热壅盛及湿热伤肝，以实证为主；右关弦大多主胆火乘脾、胃家之病，亦可见脾虚劳伤。若弦大按之不足，或右脉虚大，则属虚中夹实，如暑热伤气、真阴亏虚、邪热内伏。各类之间，以肝郁气滞为", "c": "主肝郁化火"}, {"id": "pc:关+弦+大+虚+缓", "n": "关·弦大虚缓脉", "o": "关·弦大虚缓脉总属阴虚劳怯之候。其脉象虽兼弦、大、虚、缓、数、软等不同，然核心病机为阴液亏虚，虚火内扰。脉小不劲示阴亏阳不亢；虚弦软数示虚火内扰、肺肾阴伤；弦大以数示心肝火旺而阴不制。诸类之间相互关联：阴虚为本，虚火为标，火旺又耗阴，形成恶性循环，终致劳嗽失血", "c": "主阴虚"}, {"id": "pc:关+弦+大+虚", "n": "关·弦大虚脉", "o": "关·弦大虚脉总属本虚标实、虚实夹杂之候。虚脉主气阴不足，为病之本；弦脉主饮邪与肝旺，大脉（关部独大）主中焦痰火壅盛，为病之标。三者相互交织：气阴亏虚，则津液不归正化，酿生痰饮；痰饮郁久化燥化火，火又劫夺阴津，形成恶性循环。故其病机核心为气阴两虚、痰火燥热内扰，", "c": "主气阴不足"}, {"id": "pc:关+弦+实", "n": "关·弦实脉", "o": "关·弦实脉总属肝木太过之候。其脉弦长本为肝之平脉，实而弦则为太过，主病在外，令人忘忽眩运；若兼沉急，则肝气逆而见胁支满、小便难、头痛眼眩等症。要之，弦实脉以肝实为核心，气机壅盛、疏泄失常为其病机关键，并可因兼脉不同而或见于外病，或表现为气逆。三类之中，肝实为根", "c": "主肝实"}, {"id": "pc:关+弦+小+促", "n": "关·弦小促脉", "o": "关·弦小促脉总起来主肝气上逆、阴伤、阳郁及正虚邪陷四类病机。弦为肝气，小为阴伤，促为阳郁，三者合见，反映湿温伏邪内陷少阴，引动冲气上击，犯胃冲肺，肃降无权，故气喘呃逆、身热不扬；同时右濡细、趺阳虚弦数、太谿似有似无，示正虚邪陷、神不守舍，郑声神糊，厥脱之变指顾", "c": "主肝气上逆"}, {"id": "pc:关+弦+小", "n": "关·弦小脉", "o": "关·弦小脉总起来主肝胃气逆与脾土久亏两类病机。弦为肝气郁滞，小为气机不畅或正虚，两关见小弦，提示肝气横逆、胃失和降，故见脐腹作痛、呕吐；又因产后脾土久亏，运化无力，水湿泛溢而面目小腿虚浮。两类病机相互关联：肝气郁滞可乘脾土，加重脾虚；脾虚湿盛又可阻滞气机，使肝", "c": "主肝胃气逆"}, {"id": "pc:关+弦+平+长", "n": "关·弦平长脉", "o": "关·弦平长脉总以肝木之常变立论。弦长为肝之平脉，软弱为常；若实而弦则肝气太过，病在外；虚而微则肝气不及，病在内；沉急则肝气逆乱。诸类皆从肝木太过、不及与逆乱分属，平脉为基准，实、虚、逆为病脉，共同概括肝病脉象之常变。", "c": ""}, {"id": "pc:关+弦+微+和", "n": "关·弦微和脉", "o": "关·弦微和脉总起来主肝木偏旺、肾水亏虚、脾湿痰聚，并涉及肝风火湿相煽之病机。其脉虽微弦，但整体冲和，示胃气未败，故病虽重而尚可无虞。三类病机相互关联：木旺水亏为根本，脾湿痰盛为中间环节，肝风火湿为标象，风火湿痰充斥三焦，流窜经络，发为眩晕、发热、遍体作痛及痈毒", "c": "主木旺水亏"}, {"id": "pc:关+弦+微", "n": "关·弦微脉", "o": "关·弦微脉总起来主肝郁阳衰、虚寒泄泻、疟邪内陷、胃气大虚等病机。弦为肝郁，微为阳衰，关候肝脾，尺候肾，故脉见弦微多责之肝脾肾阳虚，水湿不化，或伏邪内陷，胃气大虚。各案中，弦微脉或见于左手关尺，主肝经虚寒、脾肾阳弱之泄泻；或见于左关尺而右关弱，主少阳疟邪内陷、胃", "c": "主肝郁阳衰"}, {"id": "pc:关+弦+急", "n": "关·弦急脉", "o": "关·弦急脉总属肝木为病，以弦为肝脉、急为拘急气逆为基本特征。其所主病机可归为三类：一为风邪客于筋脉，因风成筋痹，脉见弦急而症见四肢游行作痛、指臂强难举；二为肝气太过、实而弦急，气逆上攻则眩运、头痛眼眩、胁支满，甚则恶言；三为肝火内炽，数弦急并见，火刑肺金则咳，", "c": "主风动筋急"}, {"id": "pc:关+弦+沉", "n": "关·弦沉脉", "o": "关·弦沉脉总起来主肝郁气滞、痰饮内伏、木旺乘土及水亏阳亢等病机，核心在于“沉弦为郁”。沉主里、主伏，弦主肝、主饮，故其病位多在里，涉及肝、脾、胃。各类之间相互关联：肝郁气逆可致木旺乘土，土虚则痰饮内生；痰气交阻又可形成积块；若水亏于下，则肝阳亢逆于上，形成本虚", "c": "主肝郁气逆"}, {"id": "pc:关+弦+浮+缓", "n": "关·弦浮缓脉", "o": "关·弦浮缓脉总起来主风邪犯胃、湿滞中焦、木乘土三类病机。右关候脾胃，浮主风邪在表，弦主风木乘土，缓主湿滞，三脉合见，提示风邪外袭、内犯胃腑，引动肝木乘脾，以致湿滞中焦。原文胃风因饮食讫乘风凉而致，症见胀满、食饮不下、形瘦腹大、恶风、头多汗、膈寒不通，正合风、湿", "c": "主风邪犯胃"}, {"id": "pc:关+弦+浮", "n": "关·弦浮脉", "o": "关部浮弦脉总起来主风邪、肝郁气滞、痰饮上逆、虚阳上浮及寒伤少阳等病机。浮主表、主风、主虚阳外浮，弦主肝、主风木、主气机劲急，二者相合，其病机核心在于风动气逆、木郁不达。各类之间相互关联：风邪外袭可引动肝风，肝郁气滞可化火生痰，痰饮上逆又常挟肝火，久病虚损则虚阳", "c": "主风邪"}, {"id": "pc:关+弦+涩+结", "n": "关·弦涩结脉", "o": "关·弦涩结脉总起来主肝脾气血郁滞、虚中夹实之病机。弦主肝郁，涩主血少，结为气滞血瘀，尺中倍弱为肾虚，四者相合，反映劳倦伤脾、郁怒伤肝，致肝脾气血两伤，邪气内结。其病机核心为“内伤重而外感轻”，即正虚为本，气滞血瘀为标。各类之间相互关联：肝郁气滞可致血行不畅而成", "c": "主肝郁气滞"}, {"id": "pc:关+弦+涩", "n": "关·弦涩脉", "o": "关·弦涩脉总起来主肝脾气血郁滞、虚中夹实之病机。弦主肝郁、肝燥、肝阳偏亢，涩主营血瘀滞或血虚不足，两关独弦则肝脾瘀结尤甚。其病机核心为血虚肝燥、气滞血瘀，正虚为本，邪实为标。各类之间相互关联：血虚则肝失濡养而肝燥，肝燥则疏泄失常而肝郁，肝郁气滞则血行不畅而血瘀", "c": "主血瘀"}, {"id": "pc:关+弦+滑+和", "n": "关·弦滑和脉", "o": "关部弦滑和脉总起来主气郁痰湿、肝胃不和之病机。弦脉主气机郁滞，滑脉主痰湿内蕴，二者相合，常见于肝气郁结、痰湿中阻之证。左寸关弦象反映肝郁，右关弦滑反映胃有痰湿，故脉象与肝胃同病相应。原文脉象稍退、柔和，症见胀满舒、能安谷，说明郁解湿化，从肝胃调和而效。三类病机", "c": "主气郁"}, {"id": "pc:关+弦+滑+大", "n": "关·弦滑大脉", "o": "关·弦滑大脉总起来主木郁痰凝、邪实壅聚之证。左关候肝，弦脉主肝木郁结，滑脉主痰浊凝滞，大脉主邪气实而壅聚。三者相合，反映肝气郁结、痰浊凝滞、气血壅聚的病理状态，常见于顽硬如岩的局部肿块（如中石疽）。木郁为气机不畅之因，痰凝为病理产物，邪实壅聚为局部表现，三者相", "c": "主木郁"}, {"id": "pc:关+弦+滑+沉", "n": "关·弦滑沉脉", "o": "关·弦滑沉脉总起来主肝郁痰火内结之里实证。其脉象由沉、滑、弦三象复合而成：沉主里，提示病位在里；滑主痰，提示痰浊内蕴；弦主肝郁，提示肝气郁滞。三者相合，反映肝气郁于胃中，不得条达，郁而化火，胃中津液被煅炼成痰，痰火纠结于中，形成里实痰火之证。原文明确‘沉主里，", "c": "主肝郁"}, {"id": "pc:关+弦+滑+浮", "n": "关·弦滑浮脉", "o": "关·弦滑浮脉总起来主痰实于上、微兼客热，并伴阴虚于下之候。其右寸关弦滑而浮，弦滑主痰实，浮主客热，反映上焦痰热壅盛；左关尺细软无神，主下焦阴虚。三类病机相互关联：痰实与客热多相兼为患，热灼津液又可加重阴虚，而阴虚于下则痰热易于上浮。原文强调“攻补皆难偏任”，正", "c": "主痰实"}, {"id": "pc:关+弦+滑+濡", "n": "关·弦滑濡脉", "o": "关·弦滑濡脉总起来主肝脾同病、湿痰内蕴兼正虚。濡主湿，弦主肝，滑主痰湿，三脉合见，提示湿留太阴、肝气不舒、痰湿内阻。本案疟久气阴两虚，正虚湿邪留恋，故脉象虚实夹杂。各病机相互关联：湿邪困脾，脾虚生痰，痰湿阻滞气机，肝失疏泄，故弦滑并见；久疟耗伤气阴，正虚难托，", "c": "主湿"}, {"id": "pc:关+弦+滑+紧", "n": "关·弦滑紧脉", "o": "右关弦滑紧脉总起来主胸阳不振、阴邪痹阻之胸痹病机。弦紧反映阳气不舒、阴寒内结，滑则主痰湿阴邪。三者相合，提示阴寒痰湿之邪痹阻胸膈，胸阳不得宣通，故见胸中常闷、饮食少进。其病机核心为“阳郁”与“阴结”，而“痰湿”为阴邪之具体形态，三者相互关联：阴寒痰湿结聚，导致", "c": "主阳郁"}, {"id": "pc:关+弦+滑", "n": "关·弦滑脉", "o": "关部弦滑脉总主痰湿、痰火、气郁痰阻、风痰上扰及肝胆余邪等病机，其核心为痰浊内蕴与气机郁滞。弦为气郁、肝旺，滑为痰涎，二者相合，反映痰与气、火、风等邪交结为患。痰湿阻滞者，脉多右关弦滑；痰火内扰者，脉多两关弦滑；气郁痰阻者，脉多弦滑有力；风痰上扰者，脉多左关独弦", "c": "主痰湿"}, {"id": "pc:关+弦+濡", "n": "关·弦濡脉", "o": "关·弦濡脉总起来主肝脾同病、湿邪内蕴兼正虚。弦主肝郁气盛，濡主脾虚湿困，两脉合见，提示肝失疏泄、脾运不健，湿暑伤中，气分有湿，血分有热。本案由疟变痢，缠绵日久，正虚邪恋，故脉象虚实夹杂。各病机相互关联：湿困脾土则脾虚生湿，湿阻气机则肝郁不舒，肝盛又易乘脾，形成", "c": "主脾虚湿困"}, {"id": "pc:关+弦+硬", "n": "关·弦硬脉", "o": "关·弦硬脉总起来主肝胆病机，以肝为核心，涉及热盛、气结、饮停、乘脾犯肺等。弦为肝脉，硬为气结或热灼筋急，故其病机多与肝胆相关。具体而言，弦硬可因肝火亢盛、相火上炎，热灼筋急而硬；亦可因气机壅塞、水饮内停，气结而硬；还可因肝郁气滞，乘脾犯胃，木气刚劲失和。各段原", "c": "主肝胆热盛"}, {"id": "pc:关+弦+紧", "n": "关·弦紧脉", "o": "关·弦紧脉总起来主风寒外袭、少阳疟疾、寒凝痛证、风动肝胆及食滞内伤等病机。弦为风、为痛、为少阳，紧主寒、主痛、主食滞，二脉相合，多提示寒邪或风邪为患，导致气机郁滞、筋脉拘急。各病机之间相互关联：风寒外袭可兼食滞，疟疾多涉少阳，寒凝可致痛证，风邪可中肝胆。其核心", "c": "主风寒表证"}, {"id": "pc:关+弦+细+涩", "n": "关·弦细涩脉", "o": "关·弦细涩脉总属虚实夹杂之候，以肝旺、脾湿、气血不足为基本病机。弦主肝旺，细主不足，涩主湿滞，三脉并见，反映肝气横逆、脾虚湿困、气血运行不畅。肝旺则疏泄失常，脾湿则运化失职，气血不足则荣卫不利，故临床可见胸腹不舒、腰髀作痛、痰注成漏等症。各类病机相互关联：肝旺", "c": "主肝旺"}, {"id": "pc:关+弦+细+滑+微", "n": "关·弦细滑微脉", "o": "此脉总起来主湿痰阻胃、肝火鼓动、阴血不足而致阴阳不交之不寐。脉细为阴血亏虚之基础，左关微弦示肝火偏动，右关带滑乃胃中湿痰所据。湿痰黏腻阻于胃府，使心肾水火相交之道路阻梗，阴阳不能相媾；而所蕴湿痰又借肝火鼓动，上扰心神。四类病机中，湿痰与肝火为病之标，阴血虚为病", "c": "主湿痰"}, {"id": "pc:关+弦+细+滑", "n": "关·弦细滑脉", "o": "关·弦细滑脉总起来主情志所伤、肝脾失调之病机。左脉弦细，为肝郁血少、情志怫郁之象；右关滑，为痰湿内滞、脾运不健之征。二者并见，反映肝气郁结与脾虚痰湿相互影响：肝郁则疏泄失职，脾运受困而痰湿内生；痰湿中阻，又加重气机郁滞。原文所载丧子哀恸、绝粒断浆，正为情志伤肝", "c": "主肝郁血少"}, {"id": "pc:关+弦+细", "n": "关·弦细脉", "o": "关·弦细脉总以肝郁为中心，兼涉脾、胃、肾等多脏。弦为肝木偏旺、气机郁滞之象，细为营血不足、阴液亏虚之征。二者并见，多示肝郁而兼阴血不足，或肝木乘脾犯胃，或肝火灼伤胃阴，或肾虚肝郁、水不涵木。其病机类别虽多，然核心在于肝郁与阴血亏虚并存，气机不畅与阴伤相互影响。", "c": "主肝郁气滞"}, {"id": "pc:关+弦+细+虚+涩+短", "n": "关·弦细虚涩短脉", "o": "关·弦细虚涩短脉总属虚实夹杂之候，以脾虚湿困、气血不足为本，气滞、肺气不足为标。关脉虚主脾胃虚弱，右脉弦细兼涩示血少气滞、脾虚湿困，寸脉短主肺气不足。诸脉并见，反映脾虚失运、湿邪内停，气血生化不足，进而气机阻滞、肺气不宣。临床见面黄、汗多、目赤、四肢沉重、减食", "c": "主脾虚湿困"}, {"id": "pc:关+弦+细+虚+涩", "n": "关·弦细虚涩脉", "o": "关·弦细虚涩脉总属虚实夹杂之候，以脾虚湿困、气血不足为本，气滞、肺气不足为标。关脉虚主脾胃虚弱，右脉弦细兼涩示血少气滞、脾虚湿困，寸脉短主肺气不足。诸脉并见，反映脾虚失运、湿邪内停，气血生化不足，进而气机阻滞、肺气不宣。临床见面黄、汗多、目赤、四肢沉重、减食、", "c": "主脾虚湿困"}, {"id": "pc:关+弦+结", "n": "关·弦结脉", "o": "关·弦结脉总起来主肝气郁结、肾阳衰微、虚中夹实之病机。弦主肝郁，结为气滞，左关弦结搏指反映厥阴肝气郁结、脉道不利；两尺微细欲绝则示少阴肾阳衰微、根本欲脱。二者并见，说明本虚标实：肾阳衰微为本，肝气郁结为标，龙雷之火上浮，故见齿舌喉闭、腹痛吐蛔、肉𥆧筋惕等少阴厥", "c": "主肝郁气结"}, {"id": "pc:关+弦+缓", "n": "关·弦缓脉", "o": "关·弦缓脉总起来主肝木火风未熄、风邪犯胃、湿滞中焦、木乘土四类病机。右关候脾胃，弦主肝木，缓主湿滞，浮主风邪。四类之间相互关联：风邪外袭可引动肝木，木旺则乘脾，脾运失健则湿滞中焦；而木火未熄又可流窜经络，上扰清窍。故本脉虽以关部弦缓为特征，但病机涉及肝、脾、胃", "c": "主木火未熄"}, {"id": "pe:关+弦", "n": "关·弦脉", "o": "关·弦脉总以肝木气机失调为核心，所主病机涵盖肝郁气滞、木乘土位、肝火郁热、痰饮湿浊、寒凝疝痛、疟邪少阳及虚中夹实七类。弦为肝脉，关候中焦肝胆脾胃，故凡气机劲急、木失柔和，脉即见弦。其中肝郁气滞为诸类之基：气郁日久可化火，火盛则刑金动血；木旺则乘土，致肝胃不和、", "c": "主肝郁气滞"}, {"id": "pc:关+弦+芤", "n": "关·弦芤脉", "o": "关·弦芤脉总起来主肝胃同病，以肝旺、血虚、痰积为核心病机。弦为肝旺，芤为血虚，滑大为胃有积痰，三者相合，反映肝失疏泄、胃积痰浊、血虚不能养肝的复杂病机。其病位在肝胃，病性属虚实夹杂：肝旺与痰积为实，血虚为虚。各病机之间相互影响：肝旺克脾犯胃，胃虚生痰，痰积又加", "c": "主肝旺"}, {"id": "pc:关+弦+虚", "n": "关·弦虚脉", "o": "关·弦虚脉总属本虚标实、虚实夹杂之候。虚主气阴不足，为病之本；弦主肝旺、饮邪或肝郁，为病之标。其病机主要涉及肝旺乘脾、肝阴不足、水火未济及气阴两虚四类。肝旺乘脾者，弦为肝木偏亢，虚为脾土不足，木乘土位，统血失职；肝阴不足者，虚弦为肝体失养，相火不静；水火未济者", "c": "主肝旺乘脾"}, {"id": "pc:关+弦+迟", "n": "关·弦迟脉", "o": "关·弦迟脉在口噤不语中，总起来主实邪内结与寒凝气滞两类病机。弦脉主气机紧张、痛证或邪阻，迟脉主寒或阳气不伸。原文“脉见迟弦，苦寒抑遏”明确指出寒凉过度抑遏阳气，导致寒凝气滞；而同段所述气食相凝、热结等实邪为患，亦可致脉道阻滞而见迟弦。因此，该脉所主病机以实邪内", "c": "主寒凝气滞"}, {"id": "pc:关+弦+长", "n": "关·弦长脉", "o": "关·弦长脉总以肝木之常变立论，弦长为肝之平脉，软弱为常；若实而弦则肝气太过，病在外；虚而微则肝气不及，病在内；沉急则肝气逆乱。其主病机可归纳为肝火、肝胃火盛、痰火、肝实、积、痛、脾虚肝郁、肝胆气逆等类。诸类皆从肝木太过、不及与逆乱分属，以平脉为基准，实、虚、逆", "c": "主肝胃火盛"}, {"id": "pc:关+弱+缓", "n": "关·弱缓脉", "o": "关·弱缓脉总属脾胃虚损之象，以脾阳式微、中焦湿聚为核心病机。关候脾胃，缓弱为脾胃本脉本病，直接反映脾胃气虚、纳运无力，故主不能食而肌肉削；阳虚则湿聚中焦，更碍运化，见心下懊𢙐、纳谷不易化。若病久及肾，兼尺脉动而下垂，则示肾阴衰、固摄失司，发为瘕泄，形成脾肾同病", "c": "主脾阳虚"}, {"id": "pe:关+弱", "n": "关·弱脉", "o": "关·弱脉总以虚为核心，主脾胃气虚、阳气衰微、气血不足，并可兼夹湿痰、伏热等标象。关部候脾胃，弱为鼓动无力，故首责中气不足、运化失职；脾虚则水湿内停、聚湿生痰，故兼主湿停痰饮；阳虚则阴寒内盛，故主虚寒。弱脉又示气血不充、里气不实，故主气血两虚、虚不任攻。然虚中可", "c": "主脾胃气虚"}, {"id": "pc:关+弱+软", "n": "关·弱软脉", "o": "关·弱软脉总起来主脾胃气虚，并常提示虚实夹杂。右关候脾胃，脉来软弱无力，是脾胃气弱、鼓动不足之征，故凡见右脉软弱，多责之中气已伤，运化无力。然软弱之象并非单纯虚证，原文中与左脉数而有力并见，症见发热、口渴、舌干、便下热不除，形成邪热内盛与脾胃气弱共存的局面，说", "c": "主脾胃气虚"}, {"id": "pc:关+弱+迟", "n": "关·弱迟脉", "o": "关·弱迟脉总属阳气不足、阴寒内盛之候。迟为阳不胜阴，弱为气衰无力，见于关尺，则中下二焦阳气式微，脾失健运、肾失温煦，水湿因而内停，故其主病以阳虚湿困为核心，兼见脾肺气虚、水湿内停。原文所载肤肿腹满、小溲稍多、形寒得汗、口干喜热饮、痰多咳嗽、谷食衰微、白苔转淡等", "c": "主阳虚湿困"}, {"id": "pc:关+微+弱", "n": "关·微弱脉", "o": "关·微弱脉总起来主虚，以气虚陷下、肝虚气弱、虚寒阳衰为核心，并可兼夹痰实、伏热等标象。其基本病机是正气不足、鼓动无力，故关前微弱多主胸中大气下陷，左关微弱多主肝虚不能疏泄，关部沉微弱则主虚寒阳衰。在此基础上，若关后重按似有力，则为虚中夹伏热；若关前反似滑实，则", "c": "主大气下陷"}, {"id": "pc:关+微+涩", "n": "关·微涩脉", "o": "关部微涩脉（含微细）总属虚实夹杂之象，以正虚为主，兼有邪实。微涩主肝血不足，微细主气虚，二者皆示气血亏虚；而弦数、洪长则主肝胆邪热与肠胃热盛。本段脉象揭示口眼㖞斜有邪实与正虚两端：邪实责之肝胆邪热、肠胃热盛，正虚责之肝血虚、脾气虚。微涩脉本身侧重于虚，但需结合", "c": "主肝血虚"}, {"id": "pc:关+微+紧", "n": "关·微紧脉", "o": "关·微紧脉总起来主中焦气机郁滞，兼见营血亏少、气机下陷之候。右关微紧直接反映中焦气郁，郁滞则当达；左细涩提示营血亏虚，脉道不利；而“少阳之气下陷于肝肾”说明气郁日久可致气机升降失常，清阳不升。三类病机相互关联：气郁为始动因素，郁久伤营则血亏，气机不达则下陷，形", "c": "主气郁"}, {"id": "pc:关+微+缓", "n": "关·微缓脉", "o": "关·微缓脉总属正虚，以气血两亏、虚寒为核心，并常兼夹实邪。微为阳气衰微，缓为胃气孱弱，故主虚损；虚寒内生则见下焦不固、奇经失摄。然虚处留邪，痰积湿热肝气可因元气不足而交阻，形成正虚邪恋、本虚标实之候。三类病机相互关联：气血两亏为根本，虚寒为阳虚之变，正虚邪恋为", "c": "主气血两亏"}, {"id": "pe:关+微", "n": "关·微脉", "o": "关·微脉总起来主虚，以气虚陷下、虚寒阳衰、气血两亏为核心，并可兼夹痰湿、郁热、气郁等标象。微为阳气衰微、鼓动无力，关候中焦脾胃，故关脉微多责之正气不足。其基本病机是气虚陷下，如右寸关微见如水上浮麻、左部不见，为大气下陷之危候；其次为虚寒阳衰，微缓、微弱多主下焦", "c": "主气虚陷下"}, {"id": "pe:关+急", "n": "关·急脉", "o": "关·急脉总起来主肝木为病与火盛气逆，兼及虚脱危候。其核心病机为肝气郁结、气逆急迫，因关候中焦肝胆，急为拘急气逆之象，故情志抑郁、肝阳上亢、肝火内炽皆可见左关急或弦急；火盛则数急，阳明伏热、胃火阴亏、瘀血虚热均可致关脉数急。肝木太过则乘脾侮金，下吸肾阴，故见肝阳", "c": "主肝郁气逆"}, {"id": "pe:关+散", "n": "关·散脉", "o": "关·散脉总属虚证，以心气涣散、鼓动无力为核心病机。脉散无神，首主心气虚，治以补益心脾；若兼数象，则转为心血不足，虚热内生，不可妄补心气。散而兼迟，提示肝肾阳虚、水中无火，当温补真阳；散而左关弱，则为肝血虚、木不生火，宜养血补肝。四类病机皆以虚为本，或气虚、或血", "c": "主心气虚"}, {"id": "pc:关+数+和", "n": "关·数和脉", "o": "关·数和脉总起来主热势渐缓、气机偏盛及下焦升发之病机。数脉主热，和脉示热势不亢，故热势渐缓；右关大示中焦气机偏盛；尺脉敛起上行示下焦气机升发。三者相互关联，反映邪热渐退、气机欲复之候，整体病机以热势缓和、气机失调为主，且不同部位脉象揭示三焦气机动态变化。", "c": "主热势渐缓"}, {"id": "pc:关+数+大+微+缓", "n": "关·数大微缓脉", "o": "关·数大微缓脉总起来主内外伤之辨，以人迎、气口分左右。其病机不外两端：一为外感风寒，属有余之证，邪客肌表，正气抗邪，脉见数大微缓，多见于左手人迎；二为内伤饮食及劳役不节，属不足之病，脾胃受损，运化失常，脉亦见数大微缓，多见于右手气口。三类之间以“正虚邪滞”为共", "c": "主外感风寒"}, {"id": "pc:关+数+大+浮", "n": "关·数大浮脉", "o": "关·数大浮脉总属热在表分、气机浮张之象。浮为邪在表，数为热盛，大为热势张扬，合见右寸关浮数，主外邪化热、病位偏表。然脉象动态变化更具意义：若浮数减大半而转敛，六部亦和而敛，则示邪热渐退、胃气收敛，为向愈之征。故本脉所主，一为热在表分之病机，一为邪退正复之转归，", "c": "主热在表"}, {"id": "pc:关+数+大+涩+急", "n": "关·数大涩急脉", "o": "关部数大涩急脉，总属内伤饮食、劳役不节所致脾胃病变。其脉数大主郁热邪盛，急主气机壅迫，涩主气滞血涩。原文以气口脉辨内伤，右寸气口脉大而数、急大而涩，正是饮食不节、劳役伤脾，谷气壅滞，郁而化热，气血运行不畅之征。三类病机相互关联：内伤饮食为病因，脾胃郁热为病性，", "c": "主内伤饮食"}, {"id": "pc:关+数+大", "n": "关·数大脉", "o": "关·数大脉总以邪热亢盛为纲，数主热、大主邪实，关候肝脾中焦，故其病机多围绕中焦热盛展开。具体而言，或为阳明热结、肝脾郁热之纯实热证；或为湿热内蕴、燥火伤津之热挟湿燥；或为积热壅盛、肠胃结滞之积热证；亦有阴分亏虚、阳气浮越之虚火证，以及邪踞表里之间之半表半里证。", "c": "主热盛"}, {"id": "pc:关+数+大+迟", "n": "关·数大迟脉", "o": "此关部数大迟脉，总起来主大气下陷兼伏热之证。其核心病机为胸中宗气亏虚下陷，导致心机跳动受病，脉来迟慢；虽兼伏气化热，但因大气陷而热力不能正常鼓动血脉，故脉不现数大而反迟。两类病机相互关联：大气下陷为本，热力失常为标，迟脉非单纯热力微弱所致，而是宗气陷与伏热并见", "c": "主大气下陷"}, {"id": "pc:关+数+实", "n": "关·数实脉", "o": "关·数实脉总以食积化热、内结胃肠为核心病机。数主热，实主结，关部候脾胃，故其脉象集中反映中焦食积与热结。原文“食下肠胃，脉必数实”直言积热内结；“右关滑大或沉实”示食积壅盛、气机内结；“实数主热”则点明实热属性。三类病机相互关联：食积为因，内结为枢，化热为果，", "c": "主积热内结"}, {"id": "pc:关+数+小+紧", "n": "关·数小紧脉", "o": "关·数小紧脉总起来主寒饮内结、气机郁滞、阳微阴弦之病机。其核心在于中焦寒饮搏结，气机紧束而迫急，故脉见小紧数。小紧主寒主饮，数主气郁而迫，关部候中焦，故病位在中焦。寒饮内停，胸阳不振，则寸脉沉；阴寒上乘，痹阻胸中，则见喘息咳唾、胸背痛、短气等症。三类病机相互关", "c": "主寒饮"}, {"id": "pc:关+数+小", "n": "关·数小脉", "o": "关·数小脉总以脾弱湿生、湿郁化热、肝郁气逆、阳虚寒凝为核心病机。数主热与气郁，小主湿阻气机不畅，关候中焦，故病位在脾胃肝。脾虚失运则湿浊内停，湿郁化热则脉数小、苔黄腻；肝气郁结化火则左关弦，木亢乘土则热潮起伏；真阳不运，寒湿凝聚则肿哕。诸类相互关联：脾弱为湿生", "c": "主湿郁化热"}, {"id": "pc:关+数+弦+和", "n": "关·数弦和脉", "o": "关·数弦和脉总起来主肝郁化火、饮邪内停、脾虚湿胜、肺失宣降之病机。左关弦数不和，弦为肝邪、饮邪，数主郁热，揭示肝郁化火与饮邪内停；右细濡涩，细濡为脾虚湿胜，揭示脾虚湿困。原文谓金郁失清肃、木郁失疏泄、土郁失升降，三焦气机郁滞，故脉象综合反映肝郁化火、脾虚湿困、", "c": "主肝郁化火"}, {"id": "pc:关+数+弦+大", "n": "关·数弦大脉", "o": "关·数弦大脉总起来主热盛邪实，兼有湿郁、火旺、阴伤之机。数主热，弦主湿郁或阳亢，大示邪盛，合而观之，其病机核心为热邪壅盛，但所在脏腑与兼挟不同。第一类湿热壅盛，偏于脾经伏热，湿邪下陷；第二类肝经火旺，偏于下焦肝肾火热内郁；第三类心肝阳扰，偏于上焦心肝火旺，阴亏", "c": "主湿热壅盛"}, {"id": "pc:关+数+弦+小", "n": "关·数弦小脉", "o": "关·数弦小脉总以肝郁气火、湿浊内盛、阳虚水泛为核心病机。弦主肝郁，数主火与热，小主气机不畅或湿阻，三者相合，提示肝气郁结化火、脾胃湿浊内盛、下元阳虚水泛的复合病机。原文右寸关小弦而数、左关尚弦、两尺微数，症见体肥多湿多痰、嗜酒伤阳、足跗浮肿渐及面部，说明本脉所", "c": "主肝郁气火"}, {"id": "pc:关+数+弦+弱", "n": "关·数弦弱脉", "o": "关·数弦弱脉总起来主虚实夹杂、热郁正虚之证。弱脉主虚，为肾阴亏虚或脾气不足；数脉主热，为邪热内蕴或阴虚内热；弦脉主郁，为气机郁滞或肝木乘脾。三者相合，常见阴虚内热、湿热内扰、土虚木乘等病机。具体而言，寸关弦数而尺弱，主肺肾阴亏、络有蕴热，发为痿躄；左关弦数而右", "c": "主虚"}, {"id": "pc:关+数+弦+急", "n": "关·数弦急脉", "o": "关·数弦急脉总主肝火内炽，兼及火邪上下交攻之病机。数主火，弦急为肝火亢盛之象，左关候肝，故脉见数弦急，首责肝火。肝火在里，上犯肺金则咳嗽，下泄肾气则梦遗，形成火刑肺金与火泄肾气两类子病机。失血后阴血已伤，火旺更灼，久延势必成劳，故又主劳损之渐。四类中，主肝火为", "c": "主肝火"}, {"id": "pc:关+数+弦+沉+涩", "n": "关·数弦沉涩脉", "o": "关·数弦沉涩脉总起来主血虚肝风暗动、胃有湿痰、金水两虚三类病机。其脉象复合，左手沉弦而涩数不调，反映肝郁血虚、风动于内；右关独缓滑，反映脾胃湿痰内蕴；尺寸俱弱，反映肺肾金水两虚。三类病机相互关联：血虚风动为本虚标实，湿痰中阻为标实，金水两虚为下焦不足，合而呈现", "c": "主血虚风动"}, {"id": "pc:关+数+弦+沉", "n": "关·数弦沉脉", "o": "关·数弦沉脉总起来主积气、积热、痰饮与脾虚四类病机，其中以积气、积热为核心。沉弦主气郁积结，数主热，故脉象首先反映肝气郁结、积热内蕴，症见两胁痛上壅至胸、发热、饮食不进；右手滑则兼痰饮内盛，痰气交阻；关脉濡弱又提示脾气不充，为本虚之兼。四类病机相互关联：积气与", "c": "主积气"}, {"id": "pc:关+数+弦+洪", "n": "关·数弦洪脉", "o": "关·数弦洪脉总属肝火血燥之病机。数主热，洪主火，弦属肝，三象合见，示肝火炽盛，灼伤阴血，血燥筋急。肝主筋，其华在爪，胆经循行颈侧臂外，故肝火血燥可致疣赘丛生、啮甲难禁、筋缩纵缩等症。治以清肝益荣、滋水涵木，正合脉象所示。两类病机中，肝火为因，血燥为果，火盛则血", "c": "主肝火"}, {"id": "pc:关+数+弦+浮", "n": "关·数弦浮脉", "o": "关·数弦浮脉总属肝经风火内动、气逆上升之象。左关候肝胆，浮为风邪未解或气火升浮，弦为肝木郁亢，数为郁热内盛。四段所论，或伤风不醒而风热郁肝，或女子月事不来而肝火升腾，或咳嗽痰血而木火刑金，或新产冲逆而犯中，皆以肝经气火少降多升为核心。风热郁肝为初起之因，肝火升", "c": "主肝火升腾"}, {"id": "pc:关+数+弦+滑", "n": "关·数弦滑脉", "o": "关·数弦滑脉总起来主肝郁化火与痰热内阻两类病机。弦脉主肝郁气滞，数脉主火热亢盛，滑脉主痰湿内蕴，三者相合，提示气郁、火盛、痰凝相互搏结。第一类因情志不遂，肝气逆郁，郁而化火，火挟痰上攻，病位偏于肝与胸咽；第二类因外邪入里化热，与痰饮相合，盘踞胸中，结于胃腑，病", "c": "主肝郁化火"}, {"id": "pc:关+数+弦+细+小", "n": "关·数弦细小脉", "o": "关·数弦细小脉总以肝郁阴亏火旺为核心病机。弦主肝郁，细小数主阴亏火旺，三者相合，提示肝气郁结、阴液亏虚、虚火内扰的复合病机。肝郁化火，下迫膀胱则溺痛尿血，外郁筋脉则手腕酸痛；火郁又因阴亏而难解。此脉所主非单纯实火或外疡，乃内伤杂病中肝郁阴亏、火郁筋脉之候，治当", "c": "主肝郁"}, {"id": "pc:关+数+弦+细", "n": "关·数弦细脉", "o": "关·数弦细脉总以肝郁阴亏火旺为核心病机。弦主肝郁，细主阴伤，数主火旺，三者相合，提示肝气郁结、阴液亏虚、虚火内扰的复合病机。所主病机可归为三类：一为肝火，因郁而化火，灼伤阴分；二为痰热，因火炼津液成痰，壅于肺胃；三为阴伤，因火郁日久耗阴。三者相互关联：肝火为始", "c": "主肝火"}, {"id": "pc:关+数+弦+结", "n": "关·数弦结脉", "o": "关·数弦结脉总起来主肝火内扰、血不安宁及营络不畅。弦为肝旺，数为火动，壅结示气火郁于中焦，三者相合，反映肝火偏亢、气火郁结之病机。肝火内扰，迫血妄行，则血不能安，发为崩漏屡发；火郁日久，营络不畅，故经阻而络瘀。此脉以肝火为核心，火动则血不安，火郁则络不畅，三者", "c": "主肝火"}, {"id": "pc:关+数+弦", "n": "关·数弦脉", "o": "关·数弦脉总以弦为肝郁气滞、数为热象为纲，关部候中焦肝胆脾胃，故所主病机围绕肝火、郁热、痰热、虚热、木乘土及湿热展开。其中肝火与郁热为实热之基，痰热为热与痰搏结，虚热为阴亏阳亢之变，木乘土为肝火横逆传脾，湿热为热与湿合郁于三焦。诸类或相兼为病，如痰热可兼肝火，", "c": "主肝火"}, {"id": "pc:关+数+弦+虚+小", "n": "关·数弦虚小脉", "o": "关·数弦虚小脉总属阴虚劳怯之候，其病机核心为阴液亏虚、虚火内扰。脉数、弦、虚、小并见，反映阴亏于下、火炎于上，肺肾阴伤而心肝火旺。诸类中，阴虚火旺为总纲，阴亏阳亢、虚火内扰、心肝火旺为其具体表现，彼此关联：阴亏则阳亢，虚火内扰则脉数，心肝火旺则弦大。原文所列'", "c": "主阴虚火旺"}, {"id": "pc:关+数+弦+虚", "n": "关·数弦虚脉", "o": "关·数弦虚脉总属本虚标实、虚实夹杂之候。数主热，弦主肝郁气结，虚主阴亏或气弱。其病机主要涉及肝火内郁、阴虚火旺、暑热壅肺及脾肺气虚四类。肝火与阴虚常相兼，如肝火素郁而肝体自伤，形成肝强脾肺弱之连锁；暑热壅肺则见滑数上溢，为实热壅盛；脾肺气虚则脉虚不任重按，为虚", "c": "主肝火"}, {"id": "pc:关+数+弦+虚+软", "n": "关·数弦虚软脉", "o": "关部数弦虚软脉，总属阴虚劳怯之候。其脉虚软而数，弦而不劲，反映阴液亏虚、虚火内扰的基本病机。具体而言，虚火内扰则脉数而软，阴不制阳则弦大而数；肺肾阴伤则脉小不劲，虚弦无力；劳嗽失血则是阴虚火旺进一步灼伤肺络的结果。三类病机相互关联：阴虚为本，火旺为标，肺肾阴伤", "c": "主阴虚火旺"}, {"id": "pc:关+数+微", "n": "关·数微脉", "o": "关·数微脉总起来主中焦郁热、食积化火及火邪犯中之病机。其脉象以关部数而微搏为主，数主热，微搏示热势不炽但持续；右关候中焦脾胃，故数微脉多反映中焦有热。若兼左脉浮弦，则为郁怒伤肝、气机不畅，肝郁化火犯中，或食积化热；若见于失血之后，则示火邪渐犯中州，有耗伤脾胃之", "c": "主郁怒食积"}, {"id": "pc:关+数+急", "n": "关·数急脉", "o": "关·数急脉总起来主热，尤以中焦火盛为核心，可涉及阳明伏热、胃火阴亏、肝火内炽及瘀血虚热等具体病机。数主热，急为火势迫促，关候中焦，故脉见数急多责之火盛。阳明伏热则右关数急，胃火阴亏则关脉数急，肝火内炽则左关数弦急，瘀血虚热则关脉数急而芤。各类之间相互关联：火盛", "c": "主阳明伏热"}, {"id": "pc:关+数+急+芤", "n": "关·数急芤脉", "o": "关·数急芤脉总起来主瘀血、血虚与热，三者相互关联。原文脉见芤而急数，兼弦数而涩，涩主血瘀，芤主血虚，急数主瘀热内迫。跌扑后左胁胀痛，瘀血内结而血虚，瘀久化热，故脉象数急而芤。治疗用抵当丸下黑血以逐瘀，后以四物汤调理以补血，体现瘀、虚、热并存的病机。因此，该脉所", "c": "主瘀血"}, {"id": "pc:关+数+沉+小+紧+迟", "n": "关·数沉小紧迟脉", "o": "关·数沉小紧迟脉总起来主寒饮内停、胸阳不振、阳郁不宣之病机。其脉象特征为寸脉沉而迟，关上小紧数，沉迟主里寒，紧主寒凝，数主阳郁。诸类病机相互关联：寒饮内停是根本，导致胸阳不振，进而阳气郁遏不宣，气机不利，发为胸痹喘息咳唾、胸背痛短气。临床需脉症合参，以温阳化饮", "c": "主寒饮内停"}, {"id": "pc:关+数+沉", "n": "关·数沉脉", "o": "关·数沉脉总起来主里热、痰饮、气郁、燥火及虚损五类病机，其中以里热积滞为核心。数脉主热，沉脉主里，关脉候中焦，故关部数沉首先反映热邪内积于里，或为阳明湿热，或为膏粱积热。热邪内蕴，灼津为痰，则兼痰饮内盛，脉见滑数；气机郁滞，郁而化热，则见沉弦而数；燥火伤津，三", "c": "主积热"}, {"id": "pc:关+数+洪+实", "n": "关·数洪实脉", "o": "关部数洪实脉总以辨瘴为核心，所主病机可归纳为热盛、阳浮阴闭、瘴疟、表证、虚寒五类。其中洪大、数甚直接主热盛，为瘴热典型；洪数按之不实主阳浮阴闭，属热浮阴凝之变；弦紧主瘴疟，为寒热交争之象；浮紧、浮缓主表证，示邪在肌表；沉微而弱主虚寒，为阳气衰微之候。诸类之间，", "c": "主热盛"}, {"id": "pc:关+数+洪", "n": "关·数洪脉", "o": "关·数洪脉总起来主阳热亢盛之证。洪为热盛，数为火急，故其核心病机为热盛，可燔灼三焦，分候脏腑则见肝胆、胃、肺、心、肾等火证。热盛进一步可致燥火伤津，见于三消；或灼伤阴血，形成肝火血燥；在瘴疟中，洪数主瘴热，兼弦紧主寒热交争，浮紧浮缓主表证，按之不实主阳浮阴闭，", "c": "主热盛"}, {"id": "pc:关+数+浮+洪", "n": "关·数浮洪脉", "o": "关部数浮洪脉总起来主阳热亢盛之证。浮洪为热邪外盛之象，数则热势急迫，故其核心病机为热盛。热盛可进一步导致痰热内扰，见呕吐痰多；亦可耗伤津液，见躁渴、便闭。三者以热盛为本，痰热、津伤为标，相互关联。原文虽未明确断证，但据脉症合参，该脉所主病机以热盛为主，兼夹痰热", "c": "主热盛"}, {"id": "pc:关+数+浮+硬", "n": "关·数浮硬脉", "o": "关·数浮硬脉总以气机壅滞、郁热内蕴、水湿不化为主要病机。浮为气失舒运、病位在表分，数为郁热，硬为气机壅滞不柔，三者相合，反映肺脾两经之气失于舒运。气滞则水湿不化，郁久则化热，故气滞、郁热、水湿三者相互关联：气滞为始动因素，郁热为气滞所化，水湿为气滞所生，共同导", "c": "主气滞"}, {"id": "pc:关+数+浮", "n": "关·数浮脉", "o": "关·数浮脉总属热在表分、气机浮张之象，但具体病机因兼脉及脉位而异。浮为邪在表，数为热盛，关脉候中焦，故其核心为热象，然有虚实表里之别。实者如风热表证、肝经风火、湿火下注、燥火伤津、湿热郁蒸，皆因外邪或内火郁蒸，脉象浮数有力；虚者如脾虚肺损，因脾土亏损、虚阳外浮", "c": "主风热表证"}, {"id": "pc:关+数+滑+微", "n": "关·数滑微脉", "o": "关·数滑微脉总起来主痰热内阻、气逆络痹、经气不通之病机。其脉象以关尺滑而微数为主，滑主痰，数主热，微数则热不甚炽；兼右寸溢为气逆不降，左弦带滑为肝郁痰凝、络脉痹阻。诸类之间相互关联：痰热内阻为病之本，痰阻阳明则经气不能流通输布，气逆不降则络脉痹阻，故见乳少汛愆", "c": "主痰热"}, {"id": "pc:关+数+滑", "n": "关·数滑脉", "o": "关·数滑脉总以痰热、湿热、积滞为核心病机，因滑主痰湿食积，数主热，关候中焦脾胃，故多主中焦痰热、湿热壅滞、肠胃积热及肝经郁火。其变证有二：一为虚中夹实，寸关滑数而尺部沉细，示上焦痰热实邪而下元虚寒；二为阴亏阳浮，关脉滑数而寸空大、尺浮大，示阴液亏耗、阳浮火动、", "c": "主痰热"}, {"id": "pc:关+数+细+大+沉+浮", "n": "关·数细大沉浮脉", "o": "关·数细大沉浮脉总属虚实夹杂、上下寒热错杂之候。其核心病机为虚阳浮越，即下焦元阳亏虚、不能潜藏，虚阳上浮而致上焦燥热。脉象上，沉细而数或浮大而数、按之无根，是戴阳证的典型表现；关前洪滑数主上焦燥热，两尺无力主下焦虚寒，二者并见反映上热下寒、本虚标实。原文特别强", "c": "主虚阳浮越"}, {"id": "pc:关+数+细+滑", "n": "关·数细滑脉", "o": "关·数细滑脉总起来主阴亏于下、痰热壅滞于中上二焦之证。其脉象由细、数、滑三要素复合而成：细主阴液亏虚，数主热邪内扰，关滑主痰湿壅滞。三者相合，提示素体阴亏，中焦痰湿为热所激，郁于心胸或胃中，致肺胃下降之权全失，出现脘中不舒、烦躁、恶心、错语、舌红苔黄腻等症。原", "c": "主痰湿"}, {"id": "pc:关+数+细", "n": "关·数细脉", "o": "关·数细脉总起来主阴液亏虚、虚热内扰，并可兼夹肝郁、燥火、胃虚等复杂病机。其脉象由细、数复合而成：细主阴血不足，数主热邪内扰。从所主脏腑看，左关细数主肝经血热，右关数主脾阴不足，两尺数主肾阴亏虚，故其核心为阴虚内热。在此基础上，若兼弦大则肝郁火旺，若兼洪燥则燥", "c": "主阴虚内热"}, {"id": "pe:关+数", "n": "关·数脉", "o": "关·数脉总以主热为纲，因关候中焦脾胃肝胆，数主热，故所主病机围绕中焦热盛展开。其类别包括实热、湿热痰积、肝郁化火、虚热、虚中夹实及热深厥深。实热为纯实无虚，湿热痰积为热与痰湿食积搏结，肝郁化火为热因郁致，虚热为阴亏阳浮，虚中夹实为实邪与正虚并存，热深厥深为热闭", "c": "主实热"}, {"id": "pc:关+数+虚", "n": "关·数虚脉", "o": "关·数虚脉总属本虚标实、虚实夹杂之候。数主热，虚主不足，合而观之，其热非实火，乃因虚致热。具体而言，脾土亏虚不能生金，肺气弱不能平木，遂致肝木偏强；肝强则易升火，火升又自伤肝体，形成土虚→肺弱→肝强→肝自伤的连锁病机。故脉见左关虚数、右寸虚小、关脉虚软。三类病", "c": "主虚火"}, {"id": "pc:关+数+迟", "n": "关·数迟脉", "o": "关·数迟脉总属大气下陷兼伏热之证。其核心病机为胸中宗气亏虚下陷，导致心机跳动受病而脉迟；虽兼伏气化热，但因大气陷而热力不能正常鼓动血脉，故脉不现数大而反迟。三类病机相互关联：大气下陷为本，伏热内郁为标，热力失常为中间环节。迟脉非单纯热力微弱，而是宗气下陷、热力", "c": "主大气下陷"}, {"id": "pc:关+沉+伏", "n": "关·沉伏脉", "o": "关部沉伏脉总起来主邪实内闭、脉道不畅之病机，可因热积深伏或痰气壅滞所致。热积者，热邪结于肠胃肝胆，阳气不达，脉反沉伏，按之劈劈应指，属实证；痰气者，痰浊与气交阻中焦，壅塞脉道，沉伏而或兼大，亦属邪实。二者虽病因不同，但均因实邪内闭、气血不畅而致沉伏，故沉伏非虚", "c": "主热积内伏"}, {"id": "pc:关+沉+实", "n": "关·沉实脉", "o": "关·沉实脉总属里实之候，以脾胃为病位核心。沉主病在里，实主邪实内结，右关候脾胃，故凡宿垢、积滞、痰浊、寒凝等有形实邪壅阻中焦，皆可见此脉。其具体所主，可因兼脉不同而有所偏重：兼滑者多主痰浊壅盛，兼小者多主积块、寒凝、症瘕。然其共性在于实邪内结、气机壅滞、胃府通", "c": "主里实积滞"}, {"id": "pc:关+沉+小+实", "n": "关·沉小实脉", "o": "关·沉小实脉总起来主里有形实邪内结，以积、寒凝、症瘕为核心病机。沉主病在里，小实主有形之邪结聚，故脉见沉小实，多提示积块内生。原文以弦紧分候积之部位，又言弦紧为积、为寒痹、为疝痛，说明寒凝气结是积证形成的重要病机；而弦伏主症瘕深痼，则示积结日久、阳气不通之重候", "c": "主积"}, {"id": "pc:关+沉+小", "n": "关·沉小脉", "o": "关·沉小脉总起来主气血两虚，兼有瘀滞。沉为脉道不充，小为气血不足，故脉见沉小，多提示气血两虚。原文以左关尺虚濡、右寸虚软，关脉沉小，断为气血两虚，经行愆期、痛甚经行、血中兼块，治以益气养营为主，佐调血通经。可见沉小脉所主病机以虚为本，因虚致瘀，虚中夹实。其下属", "c": "主气血两虚"}, {"id": "pc:关+沉+弱", "n": "关·沉弱脉", "o": "关·沉弱脉总起来主里虚寒证，核心病机为阳气衰微、肝气不足。沉主里、弱主虚，合而示正气内亏、阳不鼓动。原文以“沉微而弱”直释为“虚寒”，并与洪大数甚主热瘴、弦紧主瘴疟、浮紧主表实、浮缓主伤风、洪数按之不实为阳浮阴闭等脉对举，凸显其非实热、非表证、非阳浮，而是里虚", "c": "主虚寒"}, {"id": "pc:关+沉+微+弱", "n": "关·沉微弱脉", "o": "关部沉微弱脉，总起来主虚寒、阳衰、里证。原文仅一段，将“沉微而弱”明确释为“虚寒”，并与其他脉象对举：洪大数甚主热瘴，弦紧主瘴疟，浮紧主表实，浮缓主伤风，洪数按之不实为阳浮阴闭。沉微弱脉与这些实热、表证、阳浮之脉形成鲜明对比，其核心病机是阳气衰微、阴寒内盛，病", "c": "主虚寒"}, {"id": "pc:关+沉+微+缓", "n": "关·沉微缓脉", "o": "关·沉微缓脉总属虚寒，尤以下焦虚寒、奇经失固为核心。左关沉微缓，沉主里、微主阳虚、缓主寒，故主下焦虚寒；冲任督带不能固摄，则见经漏淋带不止，故主奇经失固。右部虚浮，为虚阳上浮，与下焦阴寒相对，形成上盛下虚之局。缓微又反映胃气孱惫，食减味少。四类病机相互关联：下", "c": "主下焦虚寒"}, {"id": "pc:关+沉+急", "n": "关·沉急脉", "o": "关·沉急脉总属肝木太过、气逆于里之候。原文以弦长为肝之平脉，实而弦为太过病在外，虚而微为不及病在内；沉急则从肝气逆立论，为肝实气逆之具体脉象。沉主气郁于里，急主气逆急迫，故其病机核心为肝气实而逆乱。由此衍生三类证候：气逆壅滞于胁则胁支满，疏泄失职则小便难，气逆", "c": "主肝实气逆"}, {"id": "pc:关+沉+浮", "n": "关·沉浮脉", "o": "关·沉浮脉在此段中主要反映结胸与脏结两类病机。寸口浮、关上沉，为热毒结聚心胸、气机壅塞之象，故主热毒结胸；脉大或浮大者，示热实内结，误下则死或为逆，故主热实禁下。若关上细小沉紧而饮食如故、小便利，则属阴寒凝结之脏结，主阳衰寒结。总起来说，该脉以关部沉浮异常为线", "c": "主热毒结胸"}, {"id": "pc:关+沉+涩", "n": "关·沉涩脉", "o": "关部沉涩脉总起来主里实郁滞之证，以气滞、血瘀、痰阻、郁结为核心。沉主病在里，涩主血行不畅、气机郁滞，二者相合，提示气血痰浊壅塞于内，病位多在肝、胆、脾、胃。从所收三段看，或见右关沉涩而断为污血在胃脘、气郁为痰；或见寸关沉涩而主痰气壅滞、中焦壅塞；或见左关沉涩而", "c": "主气滞血瘀"}, {"id": "pc:关+沉+紧+迟", "n": "关·沉紧迟脉", "o": "关部沉紧迟脉总属里寒阳虚之候。沉主里，迟主寒，紧主痛，三脉相合，反映寒邪内侵、阳气不足、气血凝滞的基本病机。其具体所主，一为胃中寒，见腹中胀满、身体拘急；二为阴盛阳虚，寸脉短少无力，见胸膈满闷、手足厥冷；三为寒凝致痛，紧脉主痛，寒性收引。三类之间以寒邪为共同病", "c": "主里寒"}, {"id": "pc:关+沉+缓", "n": "关·沉缓脉", "o": "关·沉缓脉在此段中主湿热内盛、实邪壅盛及肺气壅盛。沉主里，缓主湿，有力为实，合而示湿热实邪内蕴中焦。因饮食过度与霖雨之湿相合，湿热大盛，上攻于肺，致肺气壅盛而喘满；实邪阻滞，气机不通，故腹胀、二便涩滞。此脉虽缓，但沉而有力，非虚缓之比，总属邪实有余之候。其下属", "c": "主湿热内盛"}, {"id": "pe:关+沉", "n": "关·沉脉", "o": "关脉沉总属病位在里、气机郁滞之象，然其具体所主病机有虚实寒热之异。沉而有力，多主里实热结或水饮结聚，如结胸、阳明余火；沉而兼弦，主气郁湿阻；沉而无力，主大气下陷；沉紧主寒饮内结；沉涩主瘀血痰阻。诸类皆以沉脉为共同特征，反映邪结在里或气机内郁，但兼脉与力度不同，", "c": "主里实热结"}, {"id": "pc:关+沉+虚", "n": "关·沉虚脉", "o": "关·沉虚脉总属里虚气滞、积结内停之候。其脉沉主里，虚主气机不畅或正气不足，若兼弦紧则寒凝积结，兼伏则症结深痼。三类病机相互关联：积块内结为根本，寒凝为常见兼因，症结深痼为积之重危阶段。沉虚脉所主以积为核心，寒凝与深痼皆围绕积结展开，反映病位在里、病性属虚中夹实", "c": "主积"}, {"id": "pc:关+沉+迟", "n": "关·沉迟脉", "o": "关·沉迟脉总属里寒阳虚之候。沉主里，迟主寒，关部候中焦及肝胆，故其病机以寒邪内中、阳气虚衰为核心。具体而言，沉迟主里寒，寒中三阴；主阳虚，肝、肾及诸阳亏损；兼紧则寒凝收引而痛；见于寸部则胸阳不振、痰浊痹阻；久病则寒凝脉络、气血瘀滞而成疟母癥积。各类之间相互关联", "c": "主里寒"}, {"id": "pe:关+洪", "n": "关·洪脉", "o": "关·洪脉总以热盛为核心病机，然有虚实之分。实者多主阳热亢盛，燔灼三焦，见于肺火、胃热、肝火等；热盛进一步可伤津耗液，或迫血妄行，致衄血、咳血；兼滑则痰热内蕴，壅盛中焦。虚者则主阴虚火旺，虚阳外浮，脉多浮大无力或兼细数，见于水亏火旺、龙雷鼓动。各类病机以热为共同", "c": "主阴虚火旺"}, {"id": "pc:关+浮+促", "n": "关·浮促脉", "o": "关·浮促脉总主气逆上焦、胆府倒置之病机。左关候肝胆，浮促为气机上逆之象，独见于此而余部无恙，说明病位在胆。其成因多由大醉尽吐，上焦反复，致胆府倒置，气逆乱于上，故见视物倒植等症。此脉所主，以气逆为核心，胆府倒置为具体病位，内伤酒吐为病因，三者相互关联：酒吐伤中", "c": "主气逆"}, {"id": "pc:关+浮+动", "n": "关·浮动脉", "o": "关·浮动脉在古籍中主血虚阳浮与肝风内动两类病机。血去络伤，阴血亏虚，阳气失于依附而上浮，故脉动跃如浮；左关前属肝心部位，阳气化风，肝风内动，上扰清窍，故头中微晕。两类病机相互关联：血虚为本，阳浮为标，阳浮化风则成肝风内动。脉浮而动跃，既反映血虚阳浮，又提示肝风", "c": "主血虚阳浮"}, {"id": "pc:关+浮+洪", "n": "关·浮洪脉", "o": "关部浮洪脉总起来主热盛，但须分虚实与兼脉。浮为风邪在表，洪为积热内盛，关候中焦，故实者多主风热外袭、痰火积热壅盛中焦，甚则迫血上逆、耗伤津液；虚者则见于左尺浮洪无力之水亏火旺，或左寸浮洪之心火炎上。各类病机以'热'为共同核心：风热在表为热郁肌表，痰火积热为热与", "c": "主痰火积热"}, {"id": "pc:关+浮+涩", "n": "关·浮涩脉", "o": "关·浮涩脉总起来主邪退津伤、脾胃虚弱、气滞血少及虚实夹杂之证。浮为气机外达，涩为津液未充、脉道欠流利，故其核心病机在于中焦脾胃气机不畅而津血不足。从原文看，浮涩可出现在邪去津未复之际，如燥屎已下、郁结渐开而脉转浮涩、颜色轻和，属病势向安；亦可反映脾胃本虚、气血", "c": "主邪退津伤"}, {"id": "pc:关+浮+空", "n": "关·浮空脉", "o": "关·浮空脉总属虚证，以气虚为核心，兼涉内伤虚损与阴亏气弱。浮为气浮于外，空为内虚不实，故非表邪实滞。原文一者因努挣伤气、阴乘阳位而见寸脉浮空，关尺微细，属内伤虚损、阴阳失调；二者直述“浮则为气，空则为虚”，分列五脏气弱，总归气虚眩晕。三类相互关联：气虚为根本，", "c": "主气虚"}, {"id": "pc:关+浮+紧", "n": "关·浮紧脉", "o": "关·浮紧脉总以寒邪为患，其病机核心为寒邪外束、卫阳被遏。浮主病位在表，紧主寒性收引，故浮紧相合，首先主风寒表证，见恶寒发热、无汗身痛；若内有伏饮，寒邪外束则引动伏饮，发为寒邪束饮之喘咳；若寒邪伤及三阳，浮紧专主太阳表寒，与少阳、阳明之脉相鉴别；瘴疟初起，邪客肌", "c": "主风寒表证"}, {"id": "pc:关+浮+缓", "n": "关·浮缓脉", "o": "关·浮缓脉总起来主风邪为患，兼涉脾胃，病机以风邪外袭、内犯中焦为核心。浮主表邪，缓主风与湿，关候脾胃，故其病机多与风邪、湿邪相关。具体而言，浮缓脉可主风邪在表，如伤风轻证；可主风湿困脾，脾土不足而风湿交浸；可主风邪犯胃，胃风因乘风凉而致；若兼弦象，则主木乘土，", "c": "主风邪在表"}, {"id": "pe:关+浮", "n": "关·浮脉", "o": "关·浮脉总起来主风邪、热郁、虚阳浮越、气逆、表证及疮毒等病机。浮脉主表、主风、主阳热，关部候中焦肝胆脾胃，故关浮多反映风邪外袭、肝木劲急、中焦热郁气壅或虚阳上浮。各类之间相互关联：风邪外袭可引动肝风，肝郁气滞可化火生痰，痰热壅盛则关脉浮而气旺；热毒壅滞又可致疮", "c": "主风邪"}, {"id": "pc:关+浮+芤", "n": "关·浮芤脉", "o": "关部浮芤脉总属气血虚而兼有邪结之候。浮为气机上逆，芤为血虚失守，二者并见，提示气血亏虚、运行失序。然虚中夹实，原文明言'小肠痈毒内结'，故本脉所主病机以血虚、气逆为本，痈毒内结为标。产后转脬、小便不禁、精神倦怠、不思饮食等症，皆由气血虚衰、气机逆乱所致；而腹痛", "c": "主血虚"}, {"id": "pc:关+浮+虚", "n": "关·浮虚脉", "o": "关·浮虚脉总起来主阴阳偏盛、气血郁滞、气虚及阴阳离决危候。其核心病机为阴阳失调：浮为气虚，虚而大则阴阳偏盛，气血留滞，甚则关格不通。原文引《素问》《灵枢》以人迎、寸口脉大四倍分格与关，并大曰关格，皆言脉而不言证，强调脉象反映阴阳偏盛之极；又引《难经》溢覆及阳脉", "c": "主阴阳偏盛"}, {"id": "pc:关+涩+小", "n": "关·涩小脉", "o": "关·涩小脉总起来主虚，尤以气血不足、大虚之证为核心。原文以两寸关脉大而弱、两尺脉涩而小并见，断为气血不足；涩主血少，小主气虚，故涩小脉首先反映气血两虚。寸关候上中焦，关脉涩小兼弱，主脾胃虚衰、运化无力，故见反胃；尺候下焦，尺脉涩小主下焦精血亏耗、肾元不足。三类", "c": "主气血两虚"}, {"id": "pc:关+涩+弱", "n": "关·涩弱脉", "o": "关·涩弱脉总起来主虚，包括胃气虚、阴阳俱虚、里气不实，并可兼见虚热。其核心病机是正气不足，故凡见涩弱无力之脉，多属虚象，不可妄行攻下，以免重虚。各分类之间相互关联：虚为根本，虚热为虚中夹热，里气不实为虚在里，均强调正虚不耐攻伐。", "c": "主虚"}, {"id": "pc:关+涩+短", "n": "关·涩短脉", "o": "关·涩短脉在此段中并非单见，而是与虚、弦、数、濡耎等象并见，总属气阴两亏、虚火内动、阴阳未平之候。其病机可归为四类：右寸短涩主肺气不足，左关虚弦主肝阴亏虚，尺举数按不足及濡耎主肾水亏而虚火动，合而审之则总归阴阳未平。四类之间以“水少于火”为枢：肾水亏虚为根，肝", "c": "主肺气不足"}, {"id": "pc:关+涩+缓", "n": "关·涩缓脉", "o": "关·涩缓脉总起来主阳气不运、积滞血瘀，进而导致噎膈反胃之症。缓主阳气虚衰，旋运无力；涩主积滞血瘀，瘀浊内阻。二者相合，反映中阳不振、瘀浊内停的本虚标实病机。阳气不运为病之本，积滞血瘀为病之标，二者互为因果，致使食入气阻、吐涎吐瘀，形成噎膈反胃。此脉象与病症相应", "c": "主阳气不运"}, {"id": "pe:关+涩", "n": "关·涩脉", "o": "关·涩脉总起来主气血津液亏虚与瘀滞内阻，病位多在中焦脾胃、肝胆及冲任。其核心病机为血少津亏、气机不畅，脉道不充而运行涩滞。从所收段落看，涩脉既可主虚，如气血两虚、津亏气滞、冲任虚损、虚中夹热；又可主实，如血瘀痰阻、肝郁血瘀。虚与实常互为因果：血虚则脉道不充而涩", "c": "主血瘀痰阻"}, {"id": "pc:关+涩+迟", "n": "关·涩迟脉", "o": "关·涩迟脉在古籍中从肝木太过不及立论，总属肝病脉象。其主病机可归为三类：肝实、肝虚与气逆。肝实者，脉实而弦，病在外，症见忘忽眩运、胁痛喜怒；肝虚者，脉虚而微，病在内，症见胸胁胀满；气逆者，脉沉而急，症见胁支满、小便难、头痛眼眩。三者皆以肝之平脉弦长为参照，涩迟", "c": "主肝实"}, {"id": "pc:关+滑+动", "n": "关·滑动脉", "o": "关部滑动脉总主痰积、湿热、肝气交阻中焦，兼见气血两亏之本虚标实。滑主痰湿，动主搏击，右关候脾胃，脉独滑动如豆，故首责痰浊壅聚中焦，症见舌苔黄白而腻、中脘皮肉觉厚、手足筋脉动惕。痰积日久化热，湿热相合，与肝气互结，左关弦搏，左肋至脐下梗硬，乃肝气入络。然尺寸脉俱", "c": "主痰积"}, {"id": "pc:关+滑+坚", "n": "关·滑坚脉", "o": "关·滑坚脉总起来主痰浊胶固、壅塞气机之病机。其脉象滑而坚凝，几乎搏指，滑为痰象，坚凝为痰结，见于寸关之间，提示顽痰结于肺胃之管。肺主清道，胃主浊道，痰浊壅塞两道，气机不得宣通，故见喘咳、晕绝等症。此脉所主以痰结为核心，气壅为痰结所致之果，二者相互关联，共同构成", "c": "主痰结"}, {"id": "pc:关+滑+大+涩", "n": "关·滑大涩脉", "o": "关·滑大涩脉在本段中并非单一脉象，而是复合脉：左涩、右寸关滑大、两尺弱。总起来主虚实夹杂之证。具体而言，左涩主血少或血瘀，为吐血后阴血亏耗、离经之血留滞；右寸关滑大主痰火壅于中上焦，故咳嗽彻昼夜；两尺弱主下元虚惫，故泄泻、发热烦躁。四类病机相互关联：吐血致血虚", "c": "主血少血瘀"}, {"id": "pc:关+滑+大", "n": "关·滑大脉", "o": "关·滑大脉总以痰、火、食积、气滞等实邪壅盛于中焦为主，尤以痰火为核心。滑主痰饮，大主邪热，右关候脾胃，故脉见滑大有力多提示中焦痰火胶固、食积内停或气机壅滞。原文反复强调“中焦有痰，肝胆有火”“无痰不作晕”，症见眩晕、呕吐、咳喘、腹胀、眼赤肿痛等。若寸关滑大而尺", "c": "主痰"}, {"id": "pc:关+滑+实", "n": "关·滑实脉", "o": "关·滑实脉总起来主痰热实邪壅盛之病机。滑为痰饮之征，实为邪气盛之象，关部候中焦及关前心肺，故其病机核心在于痰浊实邪内壅。具体而言，一类为热痰上壅、杜塞心脑相通之路，致神明隔碍而发癫狂失心；另一类为痰浊实邪壅阻中焦脾胃，气机不畅而见胃脘痛、胸胁痛等症。两类病机虽", "c": "主热痰壅盛"}, {"id": "pc:关+滑+小", "n": "关·滑小脉", "o": "关·滑小脉在此案中总主痰凝气滞、寒闭肺气。滑为痰浊内蕴，小为气机郁滞，关候中焦，痰气交阻则胸脘闷、背板如缚；右寸浮紧示风寒闭肺，外寒引动痰浊，阻塞清道，故喘不能卧、声如抽风箱。三类病机相互关联：寒闭为诱因，痰凝为宿根，气滞为痰阻之果，共同构成外寒引动痰浊、肺气", "c": "主痰凝"}, {"id": "pc:关+滑+弱", "n": "关·滑弱脉", "o": "关·滑弱脉总起来主内风痰阻兼肝肾两虚之证。两关滑主痰，尺弱主虚，滑弱并见，提示痰浊内蕴与肝肾亏虚并存。其病机核心为肝肾阴虚，水不涵木，虚风内动，煽动痰浊，风痰阻络，以致舌强肢麻、口眼㖞斜；营血亏虚，筋脉失养，故见不仁不用。三类病机相互关联：肝肾两虚为本，虚风内", "c": "主风痰阻络"}, {"id": "pc:关+滑+微", "n": "关·滑微脉", "o": "关·滑微脉总起来主痰湿中阻、风木偏亢、胃失通降之病机，并可导致眩晕等症。滑脉主痰湿，微滑示湿痰不甚而胃欠通降；左关独弦为风木偏亢之征。痰湿中阻则胃气不降，胆气不能下行，肝脾升有余而胆胃降不足，升降失常，遂发眩晕。诸类之间相互关联：痰湿为病之根，胃失通降为痰湿所", "c": "主痰湿"}, {"id": "pc:关+滑+沉+实", "n": "关·滑沉实脉", "o": "关·滑沉实脉总属里实痰滞之候。沉主里，实主邪实内结，滑主痰饮壅盛，三者相合，提示痰浊实邪壅阻中焦，脾胃气机不畅。右关候脾胃，故病位在脾胃，症见胃脘痛、右胁痛交替发作，痛引背骨，胸痛彻背，夜间尤甚。其病机核心为痰浊内阻、气机壅滞、实邪结聚，三者相互影响：痰浊为有", "c": "主里实"}, {"id": "pc:关+滑+沉", "n": "关·滑沉脉", "o": "关脉沉滑总属里实之候，以右关候脾胃为核心，主痰、食、气、热等实邪内结中焦。沉主里，滑主痰主食，故痰浊内蕴、食积内停、气滞食凝、热结里实皆可见此脉，四者常相兼为患，只是兼脉与偏重不同。若兼弦象，则涉肝郁，成肝胃不和；若兼火风之象，则痰火风扰，上蒙清窍。诸类之间，", "c": "主食积内停"}, {"id": "pc:关+滑+洪", "n": "关·滑洪脉", "o": "关·滑洪脉总以实热痰浊壅盛为核心病机，洪为热盛，滑为痰聚，合而主痰热、食积、积滞等有余之证。其病位广泛，可在中焦脾胃、上焦心肺、肝胆及血海。痰热壅盛者，脉多洪滑有力，症见吐痰、胸胀、嘈杂、痰核；食积内停者，寸关洪滑而尺沉伏，症见倒饱、腹胀、泻而不畅；实热积滞者", "c": "主痰热壅盛"}, {"id": "pc:关+滑+浮", "n": "关·滑浮脉", "o": "关·滑浮脉总起来主表证、痰湿及痰热壅盛。浮主表，滑主痰，关部候中上焦，故其病机多与外邪袭表、痰湿内蕴相关。表证与痰湿常相兼为患，如风湿外乘兼痰湿内蕴；痰湿郁久又可化热，形成痰热壅盛之候，如温病结胸。三类病机相互关联：表邪不解可引动内痰，痰湿内阻易招外邪，痰热壅", "c": "主表证"}, {"id": "pc:关+滑+濡", "n": "关·滑濡脉", "o": "关·滑濡脉总起来主湿痰内蕴、脾虚湿困，兼涉蓄瘀与下焦气化不利。濡为湿象，滑为痰征，关部候脾胃，故其核心病机在湿痰困阻中焦、脾失健运。原文以寸关濡滑、尺部涩迟并见，说明湿痰蕴于中上而瘀滞寒凝在下，形成湿、痰、瘀互结，脾不能为胃行津液，膀胱气化无权之虚实夹杂证。四", "c": "主湿痰内蕴"}, {"id": "pc:关+滑+缓", "n": "关·滑缓脉", "o": "关部缓滑脉总以湿痰内蕴中焦为核心病机。缓为湿象，滑为痰征，右关候脾胃，故独见缓滑，直指胃有湿痰。然原文两段均将右关缓滑与左脉沉弦涩数不调、尺寸俱弱并见，构成湿痰中阻而兼血虚肝风暗动、肺肾金水两虚的复合病象。可见缓滑脉虽主湿痰，却非孤立之证，常作为中焦实邪的定位", "c": "主湿痰"}, {"id": "pe:关+滑", "n": "关·滑脉", "o": "关脉滑总主痰湿、痰热、食积、气郁痰阻、风痰、饮停及胃气尚存等病机，核心为痰浊内蕴中焦。滑为痰湿之征，关候脾胃，故凡痰湿食积停聚中焦，脉多滑；兼数则热，兼弦则气郁或风动，兼大有力则实邪壅盛，兼濡缓则饮停阳微。各类之间以痰湿为基础，或化热、或挟食、或兼气郁、或动风", "c": "主痰湿"}, {"id": "pc:关+濡+弱", "n": "关·濡弱脉", "o": "关·濡弱脉总以虚为核心，主要反映脾胃气虚。关部候脾胃，濡弱为气血不足、阳气式微之象，故首主脾虚。脾虚运化失职，则水湿内停，见小便频迫、足肿等症，故兼主湿停。湿聚生痰，上逆犯肺则咳嗽，故又关联痰饮。此外，濡弱脉提示里气不实、正气虚弱，凡见此类脉象，攻下之法当慎，", "c": "主脾虚"}, {"id": "pc:关+濡+紧", "n": "关·濡紧脉", "o": "关·濡紧脉总属正虚邪扰、里气不实之候。其濡为虚软，主气血阴阳不足；紧为拘急，主气机郁滞或虚热内扰。合见于关部，重点反映中焦胃气虚而兼热、里气不实，并涉及阴阳俱虚。原文以“忌下”为纲，列关脉弱、尺脉涩弱、脉虚、脉微、脉迟缓、虚细、浮、濡弱等，皆因正虚不可攻伐。诸", "c": "主虚"}, {"id": "pc:关+濡+缓", "n": "关·濡缓脉", "o": "关部濡缓脉总属寒湿气滞、脾运不健之候。其脉象濡缓，濡主湿，缓主气机弛缓，合而示湿邪内阻、气机不畅。原文明确指出'脉若濡缓，寒湿气滞'，并强调'脾运不健'，说明本脉所主以寒湿困脾、气机郁滞为核心。与弦数、弦滑等脉所主肝火、胃火、痰饮等热性、痰性病机相对，濡缓脉属", "c": "主寒湿"}, {"id": "pe:关+濡", "n": "关·濡脉", "o": "关部濡脉总以湿与虚为纲。濡为湿象，关候脾胃，故其核心病机在脾虚湿困，水湿不化，可兼寒、兼热、兼痰、兼瘀。若濡而数，则湿遏暑热，主湿温；濡而弱或软，则脾虚湿停，主中气不足；濡而小，则气血阴阳俱亏，主正虚；濡而弦，则肝脾同病，正虚湿恋；濡而紧或缓，则寒湿气滞，里气", "c": "主湿温"}, {"id": "pc:关+濡+软", "n": "关·濡软脉", "o": "关·濡软脉总起来主脾湿中阻，兼有脾虚。濡脉主湿，软脉主虚，右关候脾，故脉形濡软反映湿困中焦、脾失健运。水湿不化，上泛为涎，故见口吐涎沫、量多味难言。其病机核心为脾湿不化，非热非寒，故涎不酸不苦。此脉所主以湿浊内阻为主，虚为湿困之基础，二者相合，形成脾湿中阻之证", "c": "主脾湿中阻"}, {"id": "pe:关+短", "n": "关·短脉", "o": "关·短脉总属阳气不足、阴寒内盛之候。其核心病机为阳虚阴盛，寸脉短少力弱提示上焦阳气不能充达，关部短少则中焦阳气亦弱，故见胸膈满闷、腹中胀满、身体拘急、手足厥冷等症。短脉主气病，气机不畅则寒凝，与沉迟紧等脉并见，更确证胃中寒。两类病机相互关联：阳虚为根本，阴盛为", "c": "主阳虚阴盛"}, {"id": "pe:关+硬", "n": "关·硬脉", "o": "关·硬脉总起来主肝胆病机，以肝为核心，涉及肝旺、火盛、湿热及本虚标实。硬为气结或热灼筋急，弦硬多因肝火亢盛、相火上炎，热灼筋急而硬；亦可因气机壅塞、水饮内停，气结而硬；还可因肝郁气滞，乘脾犯胃。就所收段落而言，左关脉硬首先反映木旺，即肝气偏亢；与寸部浮急并见，", "c": "主肝旺"}, {"id": "pe:关+紧", "n": "关·紧脉", "o": "关·紧脉总以寒邪为患，兼涉气郁、饮停与正虚。紧脉主寒、主痛、主气机拘急，见于关部，多提示中焦或肝经寒凝气滞。其具体所主，可因兼脉不同而有所侧重：紧而弦者，主寒饮内结、肝脾不和，可见胁痛呕吐、腿痹不仁；紧而微者，主中焦气郁，兼营血亏少、气机下陷；紧而浮者，主寒邪", "c": "主寒痛"}, {"id": "pc:关+细+小+紧", "n": "关·细小紧脉", "o": "关·细小紧脉总属正虚寒结之象。小细主气血不足、脏气虚衰，沉紧主阴寒内盛、凝滞不通，合而观之，为脏气虚寒、阴寒内结之病机。原文以“关脉小细沉紧”为藏结主脉，并见“舌上白胎滑”，说明寒邪深结、阳气衰微。三类病机相互关联：脏寒为病之本，正虚为寒结之因，寒结为虚寒之果", "c": "主脏寒"}, {"id": "pc:关+细+小", "n": "关·细小脉", "o": "关·细小脉总属正虚之象，主气血不足、脏腑亏虚。其病机可随兼脉与部位而分：细小而虚耎者，主心脾两伤、气血亏虚；左关细小主肝经不足，左尺细小主肾经不足，皆示精血亏虚。若兼沉迟，则真阳不足，阳气不振；兼细数，则真阴不足，阴亏内热；兼沉紧，则为正虚寒结，脏气虚寒、阴寒", "c": "主虚"}, {"id": "pc:关+细+微", "n": "关·细微脉", "o": "关脉微细总主虚证，以气虚、阴亏及内伤虚损为核心。微细脉为气血不足、脉道不充之象，非实邪所致。原文两段均见关脉微细：一因努挣伤气、误下阴亏，见关尺微细，属脾肾气弱、下焦阴亏；一以右关微细别气虚，左脉微涩属肝血不足。可见微细主虚，或气虚，或阴亏，或气血两虚，总归内", "c": "主气虚"}, {"id": "pc:关+细+沉+浮+小+紧", "n": "关·细沉浮小紧脉", "o": "关脉细沉浮小紧，总属邪结于内、气机壅塞之候。其脉象复合，浮沉并见，提示病位有表里之兼，细紧小则示邪气收引凝结。所主病机主要有三：一为热毒结聚心胸，成结胸证，脉见寸口浮、关上沉；二为实邪内结，脉大或浮大，误下则逆；三为阴寒凝结，成脏结证，脉见细小沉紧。三者皆以'", "c": "主热毒结聚"}, {"id": "pc:关+细+沉+紧", "n": "关·细沉紧脉", "o": "关·细沉紧脉总属厥阴肝经虚寒凝滞、相火不藏之候。左关候肝，沉为病在里，细为阴血不足，紧为寒邪内束，三象合见，揭示下焦虚寒、肝经凝滞为本，虚阳上浮为标。其主病机可归为三类：一为寒凝，紧脉主寒邪收引，症见足冷如冰；二为虚寒，沉细示阴血不足、下焦虚寒，与紧脉并见，故", "c": "主寒凝"}, {"id": "pc:关+细+沉", "n": "关·细沉脉", "o": "关·细沉脉总属里虚不足、阳运无力之候。关候脾胃，沉为病在里，细为气血不足，故其本在脾胃中阳不振、气血亏虚。由此本虚，可衍生数类病机：一为虚寒，中阳不振而寒湿食积内阻；二为气陷，虚甚而胸中大气下陷、清阳不升；三为寒积，寒邪收引、积结在里，脉见沉细而紧；四为戴阳，", "c": "主虚寒"}, {"id": "pc:关+细+涩", "n": "关·细涩脉", "o": "关·细涩脉总属虚中夹滞之候，以阴血亏虚、气滞不畅、冲任虚损为基本病机。细主阴血不足，涩主血少气滞、脉道不利，二脉并见，反映营血亏虚而运行涩滞。关尺候肝肾冲任，涩细见于关尺，说明冲任血亏、脉道不充，故临床可见经停、腹中有形、腰酸带下等症。其病机以血虚为本，气滞为", "c": "主血虚"}, {"id": "pc:关+细+滑+濡", "n": "关·细滑濡脉", "o": "关·细滑濡脉总以痰湿为患，兼涉阴虚阳扰。细濡主阴湿弥漫于下，右关滑主痰水聚于胸中，合而示痰水内聚、阴湿上凌之机。痰水停于心下，则心阳浮越而虚悸；湿浊中阻，清阳不升，则昏晕不定；清津为阳气所炼，渐欲成痰，浊阻清位，则清浊相干。四类病机相互关联：痰水内聚为病之标，", "c": "主痰水内聚"}, {"id": "pc:关+细+滑", "n": "关·细滑脉", "o": "关·细滑脉总起来主肺气亏虚、痰湿内蕴、脾运不健之病机。细耎为肺气不足，滑为痰湿内停，右寸关候肺脾，故脉象反映肺脾同病。原文咳嗽十余月，昼轻夜重，内热喉痒，痰不易出，食饮如常，神识不倦，说明气阴耗伤而痰湿未化。前医作阴虚治不效，正因脉非细数，乃细耎兼滑，故宜清补", "c": "主肺气亏虚"}, {"id": "pe:关+细", "n": "关·细脉", "o": "关·细脉总以正虚为纲，主气血不足、阴液亏虚及脏腑虚弱。细脉为脉道不充之象，非实邪所致。其病机可因兼脉与部位不同而分：细而无力多主气虚，细而涩多主阴血亏虚兼气滞，细而沉多主里虚阳弱或虚寒，细而数多主阴虚内热。关脉候脾胃，右关细主脾肺气虚，左关细主肝血不足，尺部细", "c": "主气虚"}, {"id": "pc:关+细+虚", "n": "关·细虚脉", "o": "关·细虚脉总属正虚之象，以气阴不足、脾胃虚弱为基本病机。虚细并见，虚为阳气不足，细为阴血亏少，合而示气血阴阳俱损，尤以气阴两虚为要。其病位多在肺、脾、胃，可因虚而招邪，形成本虚标实之候，如肝风烁肺、胃气虚热。此外，虚细脉为里气不实之征，凡见此类脉象，攻下发汗皆", "c": "主气阴两虚"}, {"id": "pc:关+细+软", "n": "关·细软脉", "o": "关·细软脉总以虚为本，细主血少阴亏，软主气虚阳弱，右关候脾胃，故最常见脾虚气弱、中气不足。若左关尺细软而右寸关濡浮，则为阴虚于下、阳浮于上，属阴虚阳旺。若兼濡小兼数，则脾虚而阴亏有热，甚则中气下陷。若细软无力而反关弦紧，是气血本虚又为寒凉所遏，成正虚寒凝之候。", "c": "主阴虚阳浮"}, {"id": "pc:关+结+促", "n": "关·结促脉", "o": "关·结促脉在此段主要围绕食积腹痛展开，总属食积内停、气机壅塞之病机。促结脉是食填太仓、气阻脉道之直接反映，其本质为食积气滞；而滑大、沉实、数实、迟缓等兼脉，则提示食积可兼寒、兼热、兼气滞等不同转归。各类之间以食积为核心：食积阻滞气机则脉促结；积盛内结则滑大沉实", "c": "主食积"}, {"id": "pe:关+结", "n": "关·结脉", "o": "关结脉总起来主气机郁闭、积滞内停、湿热瘀结及本虚标实之病机。其基本特征为脉气结塞、关窍不通，故凡气血瘀阻、湿热蕴结、食积气滞、惊气入脏等致脉道不利者，皆可见结。各类之间以“结塞不通”为共同基础：湿热瘀结侧重血分瘀热，气机郁闭侧重气分壅塞，肝郁肾衰属虚中夹实，食", "c": "主湿热瘀结"}, {"id": "pc:关+缓+和", "n": "关·缓和脉", "o": "关·缓和脉在此案中主要表现为右关滑大有力，左脉和缓。总起来说，此脉主中焦痰、食、火邪实内结。滑主痰饮、主食积，大主火、主邪实，右关候脾胃，故滑大有力反映痰食胶固中焦、痰火内盛。四类病机相互关联：痰饮与食积胶结为病之根，痰火为病之象，邪实为脉之总括。左脉和缓则示", "c": "主痰饮"}, {"id": "pe:关+缓", "n": "关·缓脉", "o": "关·缓脉总属脾胃病变，以虚、湿、风、实为四大纲。缓为胃气之象，关候脾胃，故其主病多不离中焦。虚者，脾胃气虚、气血两亏、中阳不振，脉缓而弱、微、迟；湿者，寒湿、湿热、湿痰内蕴，脉缓而濡、沉、滑；风者，风邪外袭、内犯中焦，脉浮缓或大缓；实者，痰食火邪内结、积滞血瘀", "c": "主虚损"}, {"id": "pc:关+缓+迟", "n": "关·缓迟脉", "o": "关·缓迟脉总属脾胃虚寒、中阳不振，以关候脾胃，迟缓为阳衰阴盛、运化无力之征。其主病机可归三类：一为脾胃虚寒，见腹痛喜按、饮食不思、色现黑滞；二为里气不实，脉迟缓无力，禁下恐重虚；三为胃虚有热，关脉弱而热郁，不可大攻。三者皆以正虚为本，或寒或热为标，总不离胃气残", "c": "主脾胃虚寒"}, {"id": "pe:关+芤", "n": "关·芤脉", "o": "关部芤脉总主血虚失血，兼及痈脓内结与虚中夹实。芤脉中空，为血不足、脉道不充之象，故失血、血虚诸证多见。然原文又载关脉芤而伴胃脘块、少腹疙瘩者，为痈脓内结，热毒腐血成脓，血虚与邪实并存。此外，左关旺而芤、关脉芤而吐血、经水淋漓等，皆示血虚而兼燥热、火盛或气弱，属", "c": "主失血血虚"}, {"id": "pc:关+虚+实", "n": "关·虚实脉", "o": "关部虚实脉在此案中并非单一脉象，而是复合脉象的统称：关脉滑数主痰火实，寸尺软小濡小主气火虚，合而观之，总主虚实夹杂、痰火内壅兼气火不足之病机。其核心在于痰与火、气与虚的交互：气火虚则痰不易出，痰火实则气逆壅盛，二者互为因果。故临床见关滑数而寸尺无力者，当识为虚", "c": "主痰火实"}, {"id": "pc:关+虚+小", "n": "关·虚小脉", "o": "关·虚小脉总起来主气血两亏、失血及中焦虚损。其脉象虚小乏力，为气血不足之征；关部见芤，则专主失血。原文指出‘虚小为气血两亏，芤主失血，关候中焦’，因经水淋漓月余不止，去血过多，阴亏阳弱，故脉见虚小兼芤。三者相互关联：失血为直接病因，气血两亏为病机本质，中焦虚损", "c": "主气血两亏"}, {"id": "pc:关+虚+弱", "n": "关·虚弱脉", "o": "关·虚弱脉总以脾胃气虚为核心，脉来软弱无力，反映中气不足、鼓动无力。然其主病机非止一端：虚象主脾虚，实象主腑实，二者又可并见为虚实夹杂。原文'右关脉大，为腑实邪滞'与'右脉耎弱为虚'并提，说明虚弱脉可在邪实背景下出现，提示临证须凭脉辨虚实，治当顾护脾胃，不可过", "c": "主脾虚"}, {"id": "pc:关+虚+弱+软", "n": "关·虚弱软脉", "o": "关脉虚弱软，总以脾胃气虚为核心病机。右关候脾胃，脉来软弱无力，是脾胃气弱、鼓动不足之征。然此段又并见“右关脉大”，大主腑实邪壅，故软弱之象可出现在邪实背景下，形成虚实夹杂之局。虚象提示中气已伤，治当顾护脾胃，不可一味攻伐；实象则需行气通腑。二者相合，说明该脉所", "c": "主脾胃气虚"}, {"id": "pe:关+虚", "n": "关·虚脉", "o": "关·虚脉总以脾胃气虚为核心，因关部候中焦，虚脉主鼓动无力，故凡中气不足、运化失职者多现此脉。然其主病机非止一端：虚象可因气血两亏、失血而见虚小、虚芤；虚而兼弦、大、滑、数等实象，则形成本虚标实之虚实夹杂，或为肝旺乘脾，或为痰火内壅，或为积结内停。各类之间以'虚", "c": "主脾胃气虚"}, {"id": "pc:关+虚+芤", "n": "关·虚芤脉", "o": "关·虚芤脉总起来主血伤与热未成实两类病机。芤脉主血虚，虚脉主不足，合见于关部，提示血已伤而正气不足。原文以肠痈为例，指出“数而不热，关脉芤虚”，说明热邪未盛、未成实，而血已先伤。故其病机核心为血伤，兼有热未成实之象。两类病机相互关联：血伤则脉芤虚，热未成实则数", "c": "主血伤"}, {"id": "pc:关+虚+软", "n": "关·虚软脉", "o": "关·虚软脉总以脾胃气虚为核心，兼涉脾肺阳虚、肝火乘脾及虚实夹杂。右关候脾胃，脉来软弱无力，是中气不足、鼓动失职的直接征象；右寸关同见虚软，则脾肺阳气俱亏，温养无力。若虚软中兼见脉大，又提示腑实邪壅，形成本虚标实之虚实夹杂。左关虚数而右关虚软并见，则示肝火之标源", "c": "主脾肺阳虚"}, {"id": "pe:关+软", "n": "关·软脉", "o": "关·软脉总以虚为本，核心病机为脾胃气虚、中阳亏虚，因右关候脾胃，脉来软弱无力，是中气不足、鼓动失职之直接征象。在此基础上，软脉又主脾湿中阻，因濡软相兼，湿困中焦、脾失健运，故见口吐涎沫等症。此外，关软脉常提示虚实夹杂，软弱之象可与邪热内盛、腑实邪壅或痰火实邪并", "c": "主中阳亏虚"}, {"id": "pe:关+迟", "n": "关·迟脉", "o": "关·迟脉总属阳不胜阴、寒凝气滞之候，以关部候中焦脾胃及肝胆，迟主寒与阳气不伸。其病机可归纳为寒凝气滞、阳虚寒盛、脾胃虚寒、大气下陷及肝病虚实五类。寒凝气滞多因实邪阻滞或寒凉抑遏，脉见迟弦；阳虚寒盛则阳气式微，阴寒内盛，见形寒肤肿；脾胃虚寒以中阳不振、运化无力为", "c": "主寒凝气滞"}, {"id": "pe:关+长", "n": "关·长脉", "o": "关·长脉总以阳盛、气逆、痰阻、寒伤阳明为核心病机。长脉主阳气有余，关部候肝胃，故脉长关搏多责阳亢不潜、肝胃气逆，可致血溢遗精；右关滑长则痰气交阻阳明，见胸闷脘胀；若身热脉长右寸关独大，又为寒伤阳明之象。诸类或从阳盛立论，或从气逆、痰阻、寒伤分属，皆不离关部所候", "c": "主阳盛"}, {"id": "p:关", "n": "关部", "o": "关部脉总以候中焦肝胆脾胃为要，所主病机广泛，可归纳为肝郁气滞、热、痰湿、虚、积、气逆六类。弦脉为肝木失调之基，气郁可化火生热，热灼津液则生痰湿，痰热互结又可成积；木旺乘土，脾虚失运则见虚象；气机逆乱则见弦长、浮滑。诸类常相兼为病，如弦数主肝火，滑数主痰热，虚数", "c": "主肝郁气滞"}, {"id": "c:动+伏", "n": "动伏脉", "o": "动伏脉（此段实论紧脉）总起来主寒邪外束、气机郁滞之病机。原文以‘阴阳俱紧’为伤寒确征，强调紧脉之形成在于寒邪侵袭太阳外卫之阳，内陷与脉相并，寒性紧缩逼压脉道，使脉失于起伏，故指下跳动若有力而直穿而过，甚则左右弹指。其核心病机为寒凝气滞、脉道拘急，属表寒实证。两", "c": "主寒"}, {"id": "c:滑+和+动", "n": "动和滑脉", "o": "动和滑脉总起来主痰饮未净、气机渐平、胃气渐复与中焦渐通之病机。其脉以‘五动和利似滑’为特征，和利示胃气尚和，滑主痰湿未化；动气微、冲者缓反映气机郁滞渐解；鸠尾下宽畅、能进食则示中焦渐通、胃气来复。诸类之间相互关联：痰饮内停可碍气机，气郁又生痰湿，而胃气渐复则推", "c": "主痰饮未净"}, {"id": "c:和+动", "n": "动和脉", "o": "动和脉总起来主气机失调、肝脾不和及正气来复之病机。其脉以动、和为特征，动主惊、主气郁，和示胃气尚和。所主病机主要有五类：气郁、肝旺、阳浮、虚热、胃复。气郁与肝旺常相兼，弦为肝脉，气郁不舒则弦如条条，肝木偏旺则左关弦形；阳浮为肾间动气冲鼓，阳气虚浮，甚则奔豚；虚", "c": "主气郁"}, {"id": "c:小+动", "n": "动小脉", "o": "动小脉并非单一脉象，而是紧、促、动三脉并见的复合脉象。总起来看，其病机以寒凝气滞、阳热内结、惊痛交作为核心。紧脉主寒主痛，强调寒邪收引、气血凝滞；促脉主阳盛热结，突出热邪内结、气滞血瘀；动脉主惊主痛，反映气血冲动、惊痛交作。三者虽各有侧重，但均涉及气机失调、气", "c": "主寒痛"}, {"id": "c:弱+动", "n": "动弱脉", "o": "动弱脉总以弱脉为基，主气血不足、脾胃气虚，兼动则示神动或邪搏。其病机大致分虚实两端：虚者见脾胃气虚、气血两虚、惊悸神动、水湿不化；虚实夹杂者见正虚邪恋、寒热疝瘕。弱脉主正虚，动脉主气乱或邪争，故动弱并见多示虚中夹实、正虚邪恋。各段原文中，脉弱多伴脾胃纳运失司、", "c": "主脾胃气虚"}, {"id": "c:动+急", "n": "动急脉", "o": "动急脉总起来主两类病机：一为风热壅盛，邪灼筋脉，致头项脉络掣动紧急；二为元气虚极，正气亏虚，脉失柔和而反动急。前者属实证，风热外袭，热毒壅盛，筋脉拘急；后者属虚证，气虚日久，元气虚惫，脉象反常。两者虽虚实不同，但均以“急”为特征，反映筋脉失柔、拘急不舒之象。实", "c": "主风热壅盛"}, {"id": "c:数+动+散+乱", "n": "动数散乱脉", "o": "动数散乱脉总属危重死脉，主肾气绝、阴阳离散、根本败绝。其脉象特征为来如弹石、去如解索：来势坚劲急促，是肾气败绝、真脏脉见；去势动数散乱无次，是阴阳离散、脉无统纪。来坚去散并见，反映根本已败、胃气全无，故原文断为死候。三类病机相互关联，肾气绝则阴阳离散，阴阳离散", "c": "主肾气绝"}, {"id": "c:数+动", "n": "动数脉", "o": "动数脉总起来主阳动不宁、热扰血脉之病机，其核心在'动'与'数'：数为热，动为阳浮、为痛、为惊。然热有虚实之分，故其主病涵盖虚实两端。实者，热盛火结、风火相煽、火腑壅结，脉多动数有力；虚者，阴虚阳浮、肾精肝血内夺、中虚火浮，脉多动数而尺弱或右脉濡弱。阳动不已则化", "c": "主阴虚阳浮"}, {"id": "c:沉+动", "n": "动沉脉", "o": "沉动脉总起来主气机内敛与邪正相争之病机。其脉沉主里、主气机内收，动则示气血扰动或正气抗邪。从所主看，一类为气逆渐平、胃气复降之顺象，脉沉静而动气下移中脘；一类为里热未清、正气抗邪，见于数沉动脉，数主热、沉主里，生动之机示正邪相争；一类为血伤邪扰，见于沉细动脉，", "c": "主气逆渐平"}, {"id": "c:浮+动", "n": "动浮脉", "o": "动浮脉总起来主阳气浮动、虚阳上越之病机，涵盖血虚阳浮、痰气交滞、精虚阳扰、阳虚外越等类别。浮为阳气上浮，动为阳动不宁，二者相合，多因阴血亏虚、精血不足，或痰气交阻，致阳气失于潜藏而浮动。其证候或见血虚肝风上扰之头晕，或见痰气中阻之脘痞，或见精亏梦遗心悸，或见虚", "c": "主血虚阳浮"}, {"id": "c:涩+动", "n": "动涩脉", "o": "动涩脉总起来主热盛、温病伤津、风邪及气血不调之痹。其核心病机为热盛与气血失和：脉动躁数急，反映热邪亢盛，或为温病热盛伤津；若兼滑则阳盛风动；若兼涩则气有余而血不足，气血不调而痹阻。各类之间以热盛为共同背景，动躁为热之象，涩为血少之征，滑为阳盛之象，数躁并见则热", "c": "主热盛"}, {"id": "c:动+疾", "n": "动疾脉", "o": "动疾脉总起来主水气上逆、阳亢阴亏、风火内动及痿躄筋枯。其脉动疾急迫，既可见于水饮内停、水气搏击血脉上逆犯肺之实证，又可见于阳亢阴亏、阴不制阳、阳气浮动之虚证，以及风火内动、虚风上扰和阴液枯涸、筋骨失养之候。各类病机之间相互关联：水气上逆可致喘咳水肿；阳亢阴亏为", "c": "主水气上逆"}, {"id": "e:动", "n": "动脉", "o": "动脉总主阴阳相搏、气血乖乱之病机，其脉形如豆大、厥厥动摇，非平脉之象。归纳其要，约有三端：一为阳动不宁，或阳升风动而眩晕仆中，或虚阳上浮而冲逆喘促，或热盛动血而衄血崩漏；二为冲脉逆气，冲脉动则诸脉皆动，致经漏、呕逆、气从下焦上冲；三为惊痛气乱，阴阳相搏则惊惕不", "c": "主阳升风动"}, {"id": "c:动+芤", "n": "动芤脉", "o": "动芤脉由动脉与芤脉复合而成，总主精血亏虚、心神不宁及失血之证。芤脉中空，主精血耗伤、失血；动脉动摇，主惊悸、神驰。二者并见，多因真阴亏虚、心阳浮动，导致心肾不交、精关不固，常见遗精滑漏、怔忡惊悸；亦可因失血后血虚而现芤，血止则芤动渐消。各类病机相互关联：精血亏", "c": "主精血亏虚"}, {"id": "c:动+长", "n": "动长脉", "o": "动长脉总起来主相火偏炽、阴分失固，进而火动成损。其脉象要素中，动主惊动不安、神不宁，长主火气有余、气机亢盛，二者相合，反映内生相火妄动、阴不制阳的核心病机。由此可分出相火炽盛、阴分失固、惊动不安、火动成损四类，彼此递进：相火炽盛为始，阴分失固为果，惊动不安为神", "c": "主相火炽盛"}, {"id": "u:参差", "n": "参差脉", "o": "参差脉总属脉道失和、气血不调之象。其主病机可归纳为痰阻、虫积、火旺水亏、胃气不和四类。痰浊中阻则气机升降受阻，脉来扬抑不齐；虫扰中焦则气血逆乱，脉形参差；心火盛而肾水虚，五志过极，脉来三五不调；胃气不和，痰阻中焦，阳不入阴，亦见脉象不齐。四类之间相互关联：痰阻", "c": "主痰阻"}, {"id": "pc:双+大+紧", "n": "双·大紧脉", "o": "双·大紧脉总起来主寒实内结、寒饮凝结及寒郁化热之病机。其脉象以弦、紧、大、迟为特征，弦主饮主痛，紧主寒实，大示邪实，迟主寒。诸类之间相互关联：寒饮凝结心下，则脉双弦而迟，心下坚；寒实内结，则脉大而紧，阳中有阴，可下之；寒郁化热，则脉弦数，当下其寒。总属寒邪为患", "c": "主寒实内结"}, {"id": "pe:双+平", "n": "双·平脉", "o": "双·平脉在《金匮》饮病诸段中，总以水饮为病机核心，兼涉寒、虚。脉双弦主寒，偏弦主饮，脉沉滑主留饮，脉微、脉虚主阳虚，脉平则饮邪未甚。诸脉随饮停部位浅深及体质虚实而异，说明水饮为病脉无定象，当结合喘满、短气、咳唾引痛、身体疼重等症合参。其关系为：饮邪凝聚致脉弦，", "c": "主饮"}, {"id": "pc:双+弦+和", "n": "双·弦和脉", "o": "双弦脉总属肝郁气滞、气机失调之象，常兼本虚标实。所主病机以肝郁气滞为核心，进而导致气机升降失常，清浊紊乱；若兼脾肾亏虚、湿热内蕴，则双弦脉亦可见于虚实夹杂之证。原文以“脉之双弦已和”作为肝郁得舒、气机调和、腑气已调、脏已安适的转归标志，说明双弦脉主要反映肝郁气", "c": "主肝郁气滞"}, {"id": "pc:双+弦+沉+紧", "n": "双·弦沉紧脉", "o": "双·弦沉紧脉总起来主里寒、寒痰胶结及疟邪入里。沉主里，弦紧主寒，滑硬为寒痰胶结，故其病机核心为寒痰内结、里寒格拒。患者平素多痰胃冷，又餐水果，更服寒药，致疟邪全入于里，寒痰坚垒，故见呕逆滴水难下、舌苔全黑、疟反不发。三类病机相互关联：里寒为根本，寒痰胶结为病理", "c": "主里寒"}, {"id": "pc:双+弦+沉", "n": "双·弦沉脉", "o": "双·弦沉脉总起来主寒，以里寒内盛为核心，涵盖寒饮内结、寒凝心下、寒郁化热及寒实可下等具体病机。沉主里，弦主寒主饮，双弦强调寒邪深伏、脉气拘急。原文“寒脉沉弦，脉双弦者寒也”为总纲，其下诸段分别从寒饮、寒凝、寒郁化热、寒实等角度展开，均不离寒邪为患。各类之间相互", "c": "主寒"}, {"id": "pc:双+弦+浮", "n": "双·弦浮脉", "o": "双弦浮脉总属肝风内动、虚风相传之象。弦为肝脉，双弦则肝风偏盛；浮主虚风，故脉见双弦而浮，提示内风由肝而发，非外风所伤。其病机核心在于肝风内动，虚风自甚，进而乘克脾土，导致飧泄久不愈。三类病机相互关联：肝风内动是根本，虚风乘脾是传变途径，惊风致泻是最终结果。原文", "c": "主肝风内动"}, {"id": "pc:双+弦+疾+促", "n": "双·弦疾促脉", "o": "双·弦疾促脉总起来主肝阳亢盛、痰火内扰之证。弦为肝脉，疾促为阳热急迫，故主肝阳鼓舞直升；右滑数而溢，主痰热壅肺。二者相合，形成痰火内扰、肝阳上逆之病机。此脉多见于冬温挟痰阻肺，治节不伸，痰热壅盛，肝阳升腾，故见痰嗽气逆、额汗颧红、胸痞不饥、神情躁扰等症。三类病", "c": "主肝阳亢盛"}, {"id": "pc:双+弦+紧+硬", "n": "双·弦紧硬脉", "o": "双弦紧硬脉总起来主寒凝、肾虚与痛。紧硬为寒凝收引之象，弦主痛、主肾，两尺尤甚则病位在肾。本例因平素中寒，又食寒凉，致肾阳虚衰，寒凝气滞，故脉见双弦紧硬而两尺尤甚，症见脐旁动气、按之痛、下痢无度、小便难通。三类病机相互关联：寒凝为直接病机，肾虚为根本，痛为寒凝气", "c": "主寒凝"}, {"id": "pc:双+弦+紧", "n": "双·弦紧脉", "o": "双弦紧脉总主寒证，具体包括寒饮内盛、寒凝阳衰及一般寒证。弦主饮、紧主寒，双弦更示寒邪内盛，故其核心病机为寒。寒饮内停则见咳呕、痰清、不欲饮水；寒伤阳气则阳衰不运，见不能食而呕、背恶寒；寒凝气滞则痛。诸类之间，寒饮与寒凝阳衰互为因果，总以寒邪为纲，或兼饮、或兼虚", "c": "主寒饮"}, {"id": "pc:双+弦+细+紧", "n": "双·弦细紧脉", "o": "双弦细紧脉总主寒、虚、阳衰、痰凝诸病机。弦紧为寒凝气结，细为气血不足，弦则为减，故脉象总以寒凝阳衰为本，气血亏虚为标。寒凝则胃阳不开，阳衰则不能温运，气血不足则形体羸瘦、失精亡血，痰凝络脉则生瘰疬结核。诸类之间，寒凝与阳衰互为因果，虚损与痰凝皆由阳气不振、气血", "c": "主寒凝"}, {"id": "pc:双+弦+细", "n": "双·弦细脉", "o": "双弦细脉总主阴阳两虚、肝郁血虚，兼及寒凝阳衰、虚损痰凝。其核心病机为弦细并见：弦主肝郁气结或寒凝，细主阴血不足或阳衰。从原文看，5182段以阴阳俱虚为主，5685段以肝郁血虚为主；下属双弦细紧脉则扩展至寒凝阳衰、虚损痰凝。各类之间相互关联：阴阳两虚可致肝郁血虚", "c": "主阴阳两虚"}, {"id": "pe:双+弦", "n": "双·弦脉", "o": "双弦脉总以弦为肝脉、主饮主寒主痛为纲，两手俱弦则邪气偏盛、肝木失和。其病机大要有三：一为寒饮内停，阳气不运，饮邪结聚，见脘痛吐酸、喘咳痰多、口不渴；二为肝木偏旺，乘脾克胃，见胀痛呕哕、饮食不思，甚则木火刑金、痰火内扰；三为中虚寒损，弦则为减，虚弦相搏，见失精亡", "c": "主寒饮"}, {"id": "pc:双+弦+芤", "n": "双·弦芤脉", "o": "双·弦芤脉总起来主肝胃同病，以肝旺、血虚、痰积为核心病机。弦为肝旺，芤主血虚，滑大为胃有积痰，三者相合，反映肝失疏泄、胃伤痰积、气血失调的复杂格局。其病机关系为：肝旺则疏泄失常，木旺克土，胃气受伤；胃有积痰则中焦壅滞，气机不利；血虚则肝体失养，疏泄更乖。诸因交", "c": "主肝旺"}, {"id": "pc:双+弦+迟", "n": "双·弦迟脉", "o": "双弦迟脉总主寒饮内停、寒实内结及中寒里虚。弦脉主饮主痛，迟脉主寒，双弦并见则饮邪偏盛，迟则阳气不运，故其核心病机为寒与饮相合为患。寒饮阻遏中焦气机，则见脐以上连胃脘胀痛、心下鞕；寒实内结，则脉大而紧，阳中有阴，宜下之；中寒里虚，则清涕、善嚏、下痢。三类病机均以", "c": "主寒饮"}, {"id": "pe:双+微", "n": "双·微脉", "o": "双·微脉总属水饮为病，核心病机为寒饮内盛、阳气不足、水饮内停。双弦主寒饮偏盛，偏弦主饮聚一处，微脉主阳虚，沉滑主水饮内结，脉平则饮邪未甚。诸类相互关联：寒饮易伤阳，阳虚则饮不化，饮停又进一步损阳，形成寒、虚、饮交织之局。脉象随饮停部位浅深及体质虚实而异，故水饮", "c": "主寒饮"}, {"id": "pc:双+数+弦", "n": "双·数弦脉", "o": "双·数弦脉总属寒邪为患，兼见数象则示寒郁化热。其核心病机为寒，或寒饮内结，或寒凝心下，或寒实内结，或寒客胁下。弦脉主寒主痛，双弦则寒甚；数脉主热，弦数并见为寒郁化热之候；迟脉主寒，双弦而迟为寒凝局部；大而紧为寒实内结。诸类均以寒为基础，或兼气滞，或兼化热，或兼", "c": "主寒"}, {"id": "pc:双+数+滑", "n": "双·数滑脉", "o": "双·数滑脉总起来主痰热内壅、肝阳上亢之病机。其脉象由数、滑、弦、疾、促、溢复合而成：滑数主痰热，弦疾促主肝阳升动，溢为热盛气壅。原文一例，症见痰嗽气逆、额汗颧红、胸痞不饥、神情躁扰、苔色满布，系冬温挟痰阻肺，治节不伸，肝阳鼓舞直升。故其病机核心为痰热阻肺与肝阳", "c": "主痰热"}, {"id": "pe:双+数", "n": "双·数脉", "o": "数脉总起来主热，亦可见于寒证及寒热错杂之候。原文以“脉数而渴”属热，明示数脉主热之常；又引“脉双弦者，寒也”“脉弦紧，此寒也”，双弦、弦紧主寒，数脉与之并见，则为寒郁化热或寒热错杂。诸类之间，以热为常，以寒为变，寒热相兼则成错杂。故数脉所主病机，首在热盛，次及", "c": "主热"}, {"id": "pe:双+沉", "n": "双·沉脉", "o": "双·沉脉总起来主里证，以水饮内停为核心，兼涉寒与虚。沉主里，水饮内结则脉沉；弦主寒主饮，双弦为寒邪深伏，偏弦为饮聚一处；微或虚为阳气不足，多见于饮病日久或误下伤阳。诸类均围绕饮邪为患，随饮停部位浅深及正气盛衰而脉象有双弦、偏弦、沉滑、微等变化，说明水饮为病脉无", "c": "主水饮"}, {"id": "pc:双+滑+沉", "n": "双·滑沉脉", "o": "双·滑沉脉所主病机以水饮内停为核心，兼及寒、虚及饮聚偏处。沉滑直接主饮，因水饮内结、痰湿流动而脉沉滑；双弦主寒，因寒邪收引、阳虚寒生；脉微、脉虚主阳气不足，因饮病日久或误下伤阳；偏弦主饮聚一处，因饮邪偏聚局部、气机拘急。诸类均围绕饮邪为患，或寒饮相兼，或虚实夹", "c": "主饮"}, {"id": "pc:双+滑+紧", "n": "双·滑紧脉", "o": "双·滑紧脉总起来主寒痰胶结、里寒及疟邪入里。其脉象沉弦而紧，重按滑而硬，沉主里，弦紧主寒，滑硬为寒痰胶结。患者平素多痰胃冷，又餐水果，更服芩知寒药，致疟邪全入于里，寒痰格拒，故见呕逆滴水难下、舌苔全黑等症。此脉所主病机以寒痰坚垒为核心，里寒为病之基础，疟邪入里", "c": "主寒痰胶结"}, {"id": "pc:双+紧+硬", "n": "双·紧硬脉", "o": "双·紧硬脉总起来主寒凝、肾虚与痛。紧硬为寒凝收引之象，弦主痛、主肾，两尺尤甚则病位在肾。本例因平素中寒，又食寒凉，致肾阳虚衰，寒凝气滞，故脉见双弦紧硬而两尺尤甚，症见脐旁动气、按之痛、下痢无度、小便难通。三类病机相互关联：寒凝为直接病机，肾虚为根本，痛为寒凝气", "c": "主寒凝"}, {"id": "pe:双+紧", "n": "双·紧脉", "o": "双紧脉总主寒证，其核心病机为寒邪内盛、气机凝滞。紧脉主寒主痛，双紧则寒邪深入于里，无表有里，故见心下痞坚、疼痛等症。从具体脉象看，弦紧主寒饮内盛，滑紧主寒痰胶结，紧硬主寒凝肾虚，大紧主寒实内结，皆以寒为根本。寒饮、寒痰、寒实、寒凝阳衰等类之间相互关联：寒邪伤阳", "c": "主寒凝气滞"}, {"id": "pc:双+细+沉", "n": "双·细沉脉", "o": "双·细沉脉所主病机以水饮为核心，兼涉寒、虚。脉双弦主寒，偏弦主饮，弦为饮邪凝聚、气机拘急；沉滑或沉主水饮内停，因水饮内结、病位在里；脉微或虚主阳气不足，多见于大下后或久病正虚。诸脉随饮停部位浅深及正气盛衰而异，说明水饮为病脉无定象，当结合喘满、短气、悸、咳唾引", "c": "主饮"}, {"id": "pc:双+虚+微", "n": "双·虚微脉", "o": "双·虚微脉总属水饮为病，脉象随饮停部位浅深及体质虚实而异。其核心病机为寒饮内盛、阳气不足、水饮内停，并可因饮邪轻浅而脉象不显。双弦主寒饮偏盛，偏弦主饮聚一处，微脉主阳虚，沉滑主水饮内结，脉平则饮邪未甚。诸类之间相互关联：寒饮易伤阳，阳虚则饮停更甚；饮停日久可化", "c": "主寒饮"}, {"id": "p:双", "n": "双部", "o": "双弦脉总以弦为肝脉、主饮主寒主痛为纲，两手俱弦则邪气偏盛、肝木失和。其病机大要有六：一为寒饮内停，阳气不运，饮邪结聚；二为肝木偏旺，乘脾克胃，甚则木火刑金；三为中虚寒损，弦则为减，气血不足；四为疟邪伏于少阳三焦，枢机不利；五为痰湿积热，肝火痰热交阻；六为肝郁气", "c": "主寒饮"}, {"id": "pc:右+乱+碎", "n": "右·乱碎脉", "o": "右尺碎乱脉总起来主肝肾同病、风阳扰动之证。其核心病机为肾水不足、肝风内动，以致气血乖乱。原文明言「肝风上冒」与「乙癸同源，肾肝同病」，揭示碎乱脉以肝风为主、肾虚为本，风阳上冒为标。三类病机相互关联：肾水亏虚为发病基础，水不涵木则肝风内动；肝风扰动气血，则脉见碎", "c": "主肝风上冒"}, {"id": "pe:右+乱", "n": "右·乱脉", "o": "右·乱脉总起来主肾虚不固、元气欲脱，兼见虚阳上浮与失血危候。其核心病机为肾气不固、根本亏虚，因“尺中甚乱”直接反映肾失封藏；肾虚则虚阳浮越，故右脉虚大而乱；若素有失血，则肾家之血汹涌而出，脉乱更示元气欲脱。三类病机以肾虚不固为本，虚阳上浮为标，失血为常见危候，", "c": "主肾虚不固"}, {"id": "pc:右+伏+结", "n": "右·伏结脉", "o": "右伏结脉总起来主气机郁闭与积滞内停，其核心病机为惊气入脏、气乱成积。伏脉主气机郁闭，结脉主积滞内停，二者并见于右关，说明脾胃气机壅滞、积滞成形。原文所载右胁有声如虾蟆、常欲手按之，正是惊气入于脏腑、气乱积久成形之候。三类病机相互关联：惊气入脏为病因，气机郁闭为", "c": "主气机郁闭"}, {"id": "pe:右+伏", "n": "右·伏脉", "o": "右伏脉总属气机闭阻、阳气不布之象，所主病机可归纳为寒凝阳衰、肾虚火浮、虚中夹实、痰热内闭、痧毒闭阻、气陷热郁六类。其共同机理是邪阻或正虚导致脉气不能鼓动，故按之隐伏。寒凝阳衰者，伏为寒闭阳微；肾虚火浮者，伏为肾虚火不归原；虚中夹实者，伏为虚而络滞；痰热、痧毒内", "c": "主寒凝阳衰"}, {"id": "pe:右+促", "n": "右·促脉", "o": "右促脉总起来主热盛、邪陷、气壅、积滞、脾虚、阴亏阳亢、痰瘀风阻及湿热下陷等多类病机。其核心特征为脉来急促不匀，提示邪气壅遏、气机不畅或本虚标实。热盛与邪陷常相因果，热盛可致邪陷，邪陷又加重气壅；气壅积滞多因实邪内伏，脉道不利；脾虚中败则因中气衰而化源竭，促而少", "c": "主热盛邪陷"}, {"id": "pc:右+动+促", "n": "右·动促脉", "o": "右·动促脉总属痰浊、肝风、瘀血壅阻络脉之象。其脉往来如有阻滞，非单纯数促，乃痰血郁于隧道，气血不畅所致。痰浊内蕴则脉浊，肝风鼓动则脉动促不宁，痰血互结则往来涩滞。诸类病机相互交织，痰、风、瘀三者合而为患，上蒙清窍则神昏，旁阻经络则麻木，久则发为痱中之机。故其主", "c": "主痰浊"}, {"id": "pe:右+动", "n": "右·动脉", "o": "右·动脉所主病机，总以气机扰动为核心，兼涉虚、痰、郁、逆诸端。其脉见于右，右主气，故气热易升、虚阳上冒、冲脉震动皆能使动脉显象；劳倦伤脾、中气不足者，脉虽动而右大缓或虚数，是虚中夹动；痰浊壅聚中焦，则右关独滑动如豆；怒气郁结，则沉中带弦；病后余邪未清，则动脉虽", "c": "主虚劳"}, {"id": "pc:右+和+平", "n": "右·和平脉", "o": "右·和平脉在诸案中多作为对照或向愈之象出现，其本身平和提示右部（肺、脾胃）无显著邪实，但常反衬左脉异常而揭示病机。归纳所主病机，主要有木火内炽、痰热壅实、肝虚火郁、肝胃不和、热盛上冲、肝阳上亢、肝血亏虚七类。前两类以右脉异常为主，示痰热壅肺胃；后五类以左脉异常", "c": "主木火内炽"}, {"id": "pc:右+和+结+代", "n": "右·和结代脉", "o": "右·和结代脉在此段总起来主湿热壅盛兼邪阻脉道，并隐含气血虚衰之兼。结代本可主气血虚衰或邪阻脉道，此例因色带赤腻、湿热尚盛，故以邪阻为主，虚衰为兼。右脉结代“较和”仅示邪势稍退、脉气渐复，属暂时之象，不可因脉和而断向愈。三类关系：湿热壅盛为病机核心，邪阻脉道为结", "c": "主湿热壅盛"}, {"id": "pe:右+和", "n": "右·和脉", "o": "右·和脉在诸案中多作为对照或向愈之象，其本身平和提示右部（肺、脾胃）无显著邪实，但常反衬左脉异常而揭示病机。归纳所主病机，主要有痰热壅盛、热邪充斥、正气虚损、肝郁乘脾、湿热弥漫、正虚邪恋及向愈之象七类。前两类以右脉异常为主，示痰热或热盛；虚损类以右脉软弱为据，", "c": "主痰热"}, {"id": "pe:右+坚", "n": "右·坚脉", "o": "右·坚脉总属邪实内结、气机壅滞之候，其病机以实为主，或兼本虚。坚脉主邪气胶结、积气内停，右寸独坚多主寒热客肺、肺气壅遏；坚大之象则主积气在脏腑，如心痹、肾痹；右坚搏主上焦气分壅实，迫血上溢。若兼滑则痰浊胶固，兼涩则脾虚气滞，兼弱则阴虚火旺、本虚标实。各类病机之", "c": "主邪壅肺气"}, {"id": "pc:右+大+伏", "n": "右·大伏脉", "o": "右大伏脉总起来主气分邪实与肝郁血滞并见之证，属虚实夹杂、气血同病。右脉大，为气分邪气壅盛，正邪交争；左脉伏，为肝气郁结、血行滞涩。二者并见，说明病机非单一，既有气分实邪，又有肝郁血滞，且郁滞日久可化热伤津，故见便闭溺短、舌心滞黑。原文特别指出，虽四肢僵冷、舌黑", "c": "主气分邪实"}, {"id": "pc:右+大+坚", "n": "右·大坚脉", "o": "右大坚脉总起来主邪实内结、积气在脏腑。其脉象坚大，坚主积气内结，大主邪气壅盛，故凡见大坚脉，多提示邪气积聚于内，脏腑气机痹阻。从原文看，赤脉喘而坚主心痹积气，黑脉上坚而大主肾痹积气，均以坚大之象反映积气内结、脏腑痹阻。各类病机之间相互关联：积气为总纲，心痹、肾", "c": "主积气"}, {"id": "pc:右+大+实", "n": "右·大实脉", "o": "右·大实脉总起来主邪热壅盛与实邪阻滞。其脉象坚实宽大，多见于右关，反映脾胃邪实壅滞或胃火亢盛。实大兼数则热盛，兼洪则火亢，可波及肺、肾等脏，形成胃火刑金、肾火上炎等证。各类病机均以“实”为核心，或为热邪内盛，或为邪实壅滞，彼此关联，皆属实证、热证范畴，与虚大细", "c": "主热盛"}, {"id": "pc:右+大+小", "n": "右·大小脉", "o": "右·大小脉以左右脉象大小不等为特征，总主阴阳气血失调、邪正盛衰之病机。其核心在于左右脉所候脏腑不同：左候心肝肾，右候肺脾。左小右大多为营阴亏虚、邪热壅盛，或肾水亏而心阳亢，或下焦受邪而中上焦热壅，总属正虚邪陷、内虚邪盛之候；左大右小则多肝木偏亢、胃土不足，或阴", "c": "主邪热壅盛"}, {"id": "pc:右+大+小+芤+空", "n": "右·大小芤空脉", "o": "右·大小芤空脉总属阴血亏虚、暑热内陷之象。其脉空大芤小，既主平素积劳内虚、精血耗损，又主秋暑客邪深入脏阴、劫烁津液。虚与邪互为因果：内虚则暑邪易干，邪热又进一步劫阴，形成虚实夹杂之局。原文见寒热麻痹、腰痛冷汗、神迷烦躁，虑其热深劫阴而为痉厥，正合脉象所示。三类", "c": "主虚"}, {"id": "pc:右+大+平", "n": "右·大平脉", "o": "右·大平脉总起来主邪气偏盛于右部所候之脏腑，以肺、胃为主，兼及肝木乘土。其病机主要有三类：一为肺经热壅，右脉洪大，热邪痹阻肺经；二为新邪引动伏饮，右脉平而左大，提示新感未深陷，伏饮内动；三为肝木犯土，右脉弦大不平，木旺土虚，胃失冲和。三类之间相互关联：肺热可致", "c": "主肺热壅盛"}, {"id": "pc:右+大+弱", "n": "右·大弱脉", "o": "右大弱脉（右大左弱）总属阴阳乖违、上下不交之候。其右脉大主上部火升，左脉弱主下焦虚冷，二者并见，反映阳浮于上、阴寒于下，阴阳失于交通。所主病机可归为三类：一为火升于上，二为虚冷于下，三为阴阳乖违。三者实为一体：下焦虚冷，阴不敛阳，则虚阳上浮而为火升；火升于上，", "c": "主火升"}, {"id": "pc:右+大+沉+洪", "n": "右·大沉洪脉", "o": "右·大沉洪脉在此段中并非单独主病，而是与六脉弦紧并见，共同反映寒饮内伏、饮郁化热、溢饮水肿的病机。其核心为寒饮内伏：弦紧主寒主饮，卫阳被遏，故喘咳无汗、舌白滑、浮肿；右脉沉取洪大，则为饮邪郁久化热之象，然热象不著，仍以寒饮为本。三证相互关联：寒饮内伏是根本，饮", "c": "主寒饮内伏"}, {"id": "pc:右+大+沉+浮+小", "n": "右·大沉浮小脉", "o": "右·大沉浮小脉总以虚损为纲，兼夹疟邪与虚热。右脉浮濡无力主脾肺气虚，左脉沉小主阴血不足，数则虚热内扰；脾部弦洪为疟邪未净之象。诸脉象虽异，然皆因年高形弱、劳心劳力，正气先亏，疟邪乘袭，形成正虚邪恋之局。疟去脉转缓弱，更证实为邪退正虚。故其病机以虚为本，疟邪与虚", "c": "主虚"}, {"id": "pc:右+大+洪", "n": "右·大洪脉", "o": "右·大洪脉总以右部气分热盛为纲，然所主病机有实热、虚火、假象之异。实热者，或暑热燔肺，或肺热壅盛，或阳明热结夹滞，或热壅气滞，皆洪大有力，证见喘渴、咳痰如脓、便结、黄疸、经行不利等，治宜清暑、泻肺、通阳明、行气清热。虚火者，阴亏相火偏胜，左虚细右洪大，精浊并见", "c": "主暑热"}, {"id": "pc:右+大+洪+芤", "n": "右·大洪芤脉", "o": "右脉洪大芤，总主热盛津伤。洪大主热盛，芤主津伤，二者并见，为热盛耗伤阴津之候。原文温毒发斑，误用大汗大下，热邪未解而阴津已伤，故脉洪大芤甚，伴渴甚汗多。热盛为病之本，津伤为误治之果，二者相互影响，热盛则津伤，津伤则热更炽。故治疗当清热生津并举，化斑汤主之。", "c": "主热盛"}, {"id": "pc:右+大+浮+散", "n": "右·大浮散脉", "o": "右·大浮散脉，总以浮散不敛为特征，主正气耗散、气不归元之病机。其脉浮而大，散漫无根，反映脏气不能内守，故主虚、主气散；若与色相参而见逆象，则提示病势进展。原文虽为色脉相参总论，但「有诸内者形诸外」点明脉象乃脏气外露，浮散之脉正是内虚外散之征。三类病机相互关联：", "c": "主虚"}, {"id": "pc:右+大+浮+洪", "n": "右·大浮洪脉", "o": "右·大浮洪脉总属邪实热盛之候。其脉洪大而浮，既主邪气亢盛，又主热邪内炽，更因兼见神昏、瘛疭、肢厥而主邪陷内闭，且原文明言左脉洪大而浮示血分伏邪仍盛，故亦主伏邪深藏。四类病机相互关联：邪盛为总纲，热盛为邪盛之性，内闭为邪热内陷之变，伏邪为邪热深藏之根。脉象洪浮与", "c": "主邪盛"}, {"id": "pc:右+大+浮+涩", "n": "右·大浮涩脉", "o": "右·大浮涩脉总起来主邪热壅盛与气机郁滞相兼为患，并可反映元气虚实夹杂。浮大主邪热壅盛于上，多见于肺胃；涩主气滞血少、郁结不通。二者并见，说明热郁于中而气机不畅，故见胸膈烦热、咳嗽等症。在发背灸法辨治中，脉浮大或涩与脉实、脉浮、右关脉弱并列，提示元气虚实不同，治", "c": "主热壅气滞"}, {"id": "pc:右+大+浮+濡", "n": "右·大浮濡脉", "o": "右·大浮濡脉总以浮大而濡为象，主暑湿、气虚与虚阳上浮三类病机。浮大主邪郁气逆或虚阳外浮，濡主湿伤与气弱。暑湿侵脾，气机内闭，则脉浮大而濡，伴身热淹久、体软色黄；暑湿伤气，中阳不运，则气虚不能鼓脉，脉亦浮大而软；肾水亏虚，虚阳上浮，尺部右浮大而濡，则见头风肢麻。", "c": "主暑湿"}, {"id": "pc:右+大+浮", "n": "右·大浮脉", "o": "右·大浮脉总以浮大为主象，浮主表、主风，大主热、主虚。其病机大致分虚实两端：实者主风热在表、气分燥热、热盛邪实、风湿在表、表邪未解，多因外邪侵袭或热邪壅盛，脉见浮大有力，症见咳呛痰黄、喉干失音、潮热凉饮等；虚者主虚阳外浮，多因肺气不足、脾肾阳弱、气不归元，脉见", "c": "主风热在表"}, {"id": "pc:右+大+浮+软", "n": "右·大浮软脉", "o": "右·大浮软脉总属气虚湿盛之象，兼见血虚。浮软为气虚，大而无力示气分不足；湿性濡软，气虚运化失职则湿滞，故浮软大主气虚湿盛。然此脉常与左脉虚软小近快并见，提示下多亡阴、血虚湿滞，故又主血虚。三者相互关联：气虚为本，湿盛为标，血虚为果，且正虚不耐攻伐。临床见经水过", "c": "主气虚"}, {"id": "pc:右+大+涩", "n": "右·大涩脉", "o": "右·大涩脉总起来主木火升腾、胃逆不降与营血内耗相兼为患。右部候胃，大脉主邪热壅盛、木火升腾，涩脉主营血内耗、脉道不充。二者并见，说明少阳木火犯逆阳明，胃气不降，同时营血暗耗。其具体脉象如右大浮涩脉主邪热壅盛与气机郁滞相兼，右滑大涩脉主痰火壅盛与血少血瘀、下元虚", "c": "主木火胃逆"}, {"id": "pc:右+大+濡", "n": "右·大濡脉", "o": "右·大濡脉总以濡主湿、右大主邪盛或中虚为纲，所主病机可归为湿、气虚阳衰、肝风内动、积劳内伤、暑湿疟五类。濡脉本主湿伤与气弱，右大则示邪盛于气分或脾胃受困；若右濡而左大，则左大主肝风震动，右濡主阳明中虚，形成肝风与中虚并见之候；若大而濡软无力，又为胃阴亏虚、吐伤", "c": "主湿"}, {"id": "pc:右+大+濡+软", "n": "右·大濡软脉", "o": "右·大濡软脉总起来主胃阴亏虚、吐伤津燥、虚而无力。其脉大而濡软，大而无力，不任重按，为胃阴不足、虚而无力之象。原文频吐频渴、想吃甘甜、自汗恶风，乃频吐损伤胃阴，湿寒成燥，故脉转大而濡软。三类病机相互关联：吐伤胃津为起因，胃阴亏虚为本质，虚而无力为脉象反映，共同", "c": "主胃阴亏虚"}, {"id": "pc:右+大+疾", "n": "右·大疾脉", "o": "右大疾脉总起来主燥热内盛、阳动不潜与阴液亏虚。其脉象搏疾而大，见于右寸关，为阳明燥气鼓舞之征。因肺胃阴液未充，值天时燥气加临，阳易旋动，清窍失肃，故衄血复发。三者相互关联：阴亏为根本，燥热为诱因，阳动为病机之标。阴液不足则燥热易侵，燥热内迫则阳动不潜，阳动又进", "c": "主燥热"}, {"id": "pc:右+大+空", "n": "右·大空脉", "o": "右·大空脉总属虚候，以气分虚衰、不固不守为核心。其脉大而中空，非实热，乃气虚外浮、中气泄越之象。所主病机可归为六类：气虚不固、脾胃虚衰、营卫络虚、阴亏火旺、气热津伤、虚阳外浮。其中气虚不固与脾胃虚衰最为常见，多因劳伤内损、久病脾肾两亏所致；营卫络虚则见于失血、", "c": "主气虚不固"}, {"id": "pc:右+大+缓+散", "n": "右·大缓散脉", "o": "右·大缓散脉总属虚证，以气虚、脾胃虚、气血两虚为核心病机。脉大而缓散，重按无力，是正气不足、气不内守之象。其中散大主气虚外散，缓大无力主脾胃大虚，二者相合则气血俱虚。原文治以大补气血，佐以连柏丸清虚火，说明此脉虽见大缓散，实为虚候，非风药所宜。三类病机相互关联", "c": "主气虚外散"}, {"id": "pc:右+大+缓", "n": "右·大缓脉", "o": "右·大缓脉总起来主虚与邪壅两类病机，而以虚为多。大脉主劳、主虚，缓脉主脾虚湿滞，故右大缓脉首先反映劳倦伤脾、中气不足，进而气血两虚、脾胃大虚；若缓大无力、重按皆无，则为大虚之候。另一方面，大缓亦可见于胃阴伤而气机弛纵，或湿热痰火壅阻气分，此时大示邪壅、缓为湿象", "c": "主劳倦脾虚"}, {"id": "pe:右+大", "n": "右·大脉", "o": "右大脉总以气分病变为核心，右候肺脾胃，大主邪盛与虚浮。其病机可分虚实两端：实者主热盛、痰湿、气郁、邪实、胃热，脉多有力，症见热渴、痰壅、胀满、便结等；虚者主虚损，脉多无力或中空，症见气短、劳伤、失血、虚阳外浮等。诸类常相互兼夹，如热盛灼津可致虚，痰湿壅遏可兼气", "c": "主热盛"}, {"id": "pc:右+大+芤", "n": "右·大芤脉", "o": "右·大芤脉总起来主血脱阳浮、脾虚失统与虚中夹瘀三类病机，核心在于阴血亏虚而阳气浮越。大脉主虚阳外浮，芤脉主血脱中空，二者相合，反映血去而气无所附、阳浮于外的病理状态。原文小产后血大下，阴血暴脱，阳气失守，故脉豁大近芤；脾虚不能统血，血不归经，则崩下不止；血海瘀", "c": "主血脱阳浮"}, {"id": "pc:右+大+虚+空", "n": "右·大虚空脉", "o": "右·大虚空脉总属虚证，以阴血枯槁、阳气郁结为核心，进而导致胃气将败。其脉形大而空虚，非实热亢盛，乃阴血亏耗、脉道不充之征；兼细涩则阳气郁结、津血不充。原文见翻胃三月、粒米不存、面白神瘁、便燥，脉症合参已成膈症，胃气将败，预后不良。三类病机相互关联：阴血枯槁与阳", "c": "主阴血枯槁"}, {"id": "pc:右+大+虚", "n": "右·大虚脉", "o": "右·大虚脉总以虚大无力为特征，主气阴两虚、暑伤元气、脾虚湿积、虚中夹实、胃阴亏耗及气血亏虚等病机。其核心为“虚”与“大”并见：虚为气馁津亏，大为气浮不敛。右关候脾胃，故右关虚大多主脾虚湿积或胃阴亏耗；右寸虚大可见于肺气壅滞而兼阴虚火旺（如滑大搏指，但非典型虚大", "c": "主暑伤元气"}, {"id": "pc:右+大+软", "n": "右·大软脉", "o": "右·大软脉总属虚象，以气虚为核心，兼见湿滞及上盛下虚。右脉候肺脾，软大无力为脾肺气虚，运化失职则湿滞内生，故主气虚湿盛；若与左大并见，则左大示心肝阳浮，右软示脾肺气虚，形成上盛下虚之候。各病机相互关联：气虚为本，湿滞为标，上盛下虚为整体失衡之果。脉大而软，不任", "c": "主气虚"}, {"id": "pc:右+大+长", "n": "右·大长脉", "o": "右·大长脉总起来主邪实气壅、阳热亢盛之病机。其脉象大主邪热亢盛或气分邪盛，长主邪气有余、壅滞不散或阳亢火盛。所主病机主要有三类：一为气分邪盛，见于肺气不降、邪热上壅之喉痹咳呛；二为阳亢火盛，见于厥阳上燔、气火上升之咳血；三为胃中积热，见于胃热上蒸、肺受火刑之咳", "c": "主气分邪盛"}, {"id": "pe:右+实", "n": "右·实脉", "o": "右·实脉总起来主邪实壅盛于里，病位以阳明胃肠、中焦脾胃为核心，兼涉肺、肝、血络。实脉主邪结，右部候脾胃，故凡右脉实而有力，多提示有形实邪（燥屎、积滞、痰浊、湿热）与热邪相结，或气机壅滞不通。其具体病机可归为五类：里热实结、湿热壅滞、痰热结实、邪实正虚、三阳合病", "c": "主里热实结"}, {"id": "pc:右+小+促", "n": "右·小促脉", "o": "右小促脉总起来主阳气痹结、脾胃气弱与肝脾气血不通。其核心病机为阳气痹结，因阳气不通，气血痹阻，脉道拘急而见小促；脾胃气弱则运化失职，食入不运，胀满由生；肝脾气血不通则气滞血瘀，脘痛梗突、便血爪紫。三者相互关联：脾胃气弱可致阳气不展，阳气痹结又加重气血不通，气血", "c": "主阳气痹结"}, {"id": "pc:右+小+弱+缓", "n": "右·小弱缓脉", "o": "右·小弱缓脉总属虚候，以气虚为核心，兼见脾虚阳浮、气血两虚与阳陷虚泻。右脉洪缓无力，非热非实，乃脾胃气虚、虚阳外浮之假洪；左脉缓小而弱，为气血不足、脉道不充。缓为气弱，小弱为不足，无力为鼓动衰微，四类病机皆围绕正虚展开：脾虚则阳浮于外，气血虚则脉道失充，阳陷则", "c": "主气虚"}, {"id": "pc:右+小+弱", "n": "右·小弱脉", "o": "右·小弱脉总属正虚之候，以气血阴阳亏虚为核心，涵盖虚寒、津亏、暑伤、阳衰、脾肺气虚兼湿等类。小弱为不足之象，无力为鼓动衰微，故诸段皆围绕正虚展开：或阳虚寒凝，或津液元气耗伤，或暑热伤气，或阳气虚馁，或脾肺气虚兼湿。各类之间相互关联，虚寒与阳衰同源，津亏与暑伤皆", "c": "主气血虚寒"}, {"id": "pc:右+小+濡+缓", "n": "右·小濡缓脉", "o": "右·小濡缓脉总起来主脾虚湿滞、气血不足之候。濡主湿，缓主脾虚，小弱为气血亏虚，三者相合，反映中焦脾胃受损、湿浊内停、气血生化不足的病机格局。从原文看，患者久疟经截药符水攻伐，脾胃先伤，湿滞中焦则胸膈痞满、饮食少进；脾不统血则痔血；湿郁下焦则小便短赤；气虚湿恋、", "c": "主脾虚湿滞"}, {"id": "pc:右+小+濡", "n": "右·小濡脉", "o": "右·小濡脉总起来主脾虚湿滞、气血亏虚，兼及湿痰、暑湿、土虚木乘等病机。小为气虚，濡为湿滞，右脉候脾肺，故其核心为脾虚湿困、气血不足。各段原文或见劳倦伤脾、风湿外袭，或见暑湿伤气、痰湿内阻，或见土虚木乘、气不摄血，皆以正虚为本、湿滞为标。滑小濡脉偏于湿痰留恋，小", "c": "主脾虚湿滞"}, {"id": "pc:右+小+紧", "n": "右·小紧脉", "o": "右小紧脉总属脾胃虚寒，紧主寒、小主虚，右部候脾胃，故其核心病机为中焦虚寒。在此基础上，因土虚不能敛火，可致虚火上炎而见口舌碎痛；因阴寒内盛，逼阳外浮，可致虚阳外越而身微热。三者以脾胃虚寒为本，虚火、虚阳为标，形成上热下寒、本寒标热之局。原文以'右脉小紧'与'左", "c": "主脾胃虚寒"}, {"id": "pc:右+小+缓", "n": "右·小缓脉", "o": "右·小缓脉总起来主中焦脾胃虚弱、湿滞内停、气血不足之候。右脉候脾胃，缓为脾虚，小为气血不充，故其核心病机在正虚与湿滞两端。从所辖更具体脉看，小濡缓主脾虚湿滞、气血不足，小弱缓主气虚兼脾虚阳浮、气血两虚，皆围绕中焦虚损展开。就抽样段落而言，右脉由弦数转为缓小，既", "c": "主湿滞"}, {"id": "pe:右+小", "n": "右·小脉", "o": "右·小脉总以‘小主虚’为纲，所主病机以正气不足为核心，涵盖气虚、气血两虚、胃气衰败、脾虚湿困、湿郁气虚、虚阳上浮及正虚邪恋七类。右脉候肺脾，小则气分不足，故气虚、脾虚湿困、胃气衰败皆属正虚之直接体现；气血两虚则小与左脉细涩并见，示气血俱亏；虚阳上浮为阴伤于下、", "c": "主气虚"}, {"id": "pc:右+小+芤", "n": "右·小芤脉", "o": "右·小芤脉总起来主虚损，尤以阴血亏虚为基础，兼气分不足。其脉象小芤示血少阴伤，右脉空大示气亏不运，故气血并亏、积劳内虚是其根本。在此基础上，若秋暑客邪深入脏阴，则热深劫阴，形成暑伤阴分、热深劫阴之变，出现神迷心热烦躁、寒热麻痹、腰痛冷汗等症。各类病机中，虚劳内", "c": "主虚劳"}, {"id": "pc:右+小+软", "n": "右·小软脉", "o": "右·小软脉总属虚象，以正气不足为核心，尤以脾肺气虚、脾胃虚弱为主。软小无力，示气血阴阳亏虚，故主气虚、气血两虚、阴阳两虚；右关候脾胃，软小不疏，主脾虚湿困、运化迟滞；与左脉弦细并见，主肝胃不和、肝木犯土；与左脉弦大或数并见，主正虚邪恋、虚实夹杂。各类之间，以虚", "c": "主气虚"}, {"id": "pe:右+平", "n": "右·平脉", "o": "右·平脉总起来主右部所候脏腑（肺、脾胃、肾）的平和状态，但常作为对照或向愈之象出现。其病机类别包括：向愈之平静流利、痰热壅实之滑大有力、邪陷阴伤之数促转涩小、胃气外浮之虚大无力、肝病及胃之左搏右平、孕脉之右尺洪大。各类之间以右脉平和为基础，或反衬左脉异常揭示病", "c": "主向愈"}, {"id": "pc:右+弦+和", "n": "右·弦和脉", "o": "右·弦和脉总起来主湿邪内蕴、暑湿留恋及气机郁滞三类病机。弦为气机郁滞之象，湿性黏滞易阻气机，故湿邪内蕴常见弦脉；暑必夹湿，暑湿留恋则脉数而弦，湿去则暑自消；气机郁滞既是湿阻之果，亦为弦脉直接所主。原文以“右脉弦象稍和”为湿邪暗化、郁滞稍解之征，而“数象仍然”示", "c": "主湿邪内蕴"}, {"id": "pc:右+弦+大+平", "n": "右·弦大平脉", "o": "右脉弦大不平，总属木旺土虚、胃失冲和之候。弦为肝木之象，大主邪盛，右关候胃，故脉象直接反映肝木犯中宫、胃气不和。原文强调‘肝为刚脏，非柔不和’，‘弦大为木旺土虚之象’，说明此脉核心病机在肝胃不和、木乘土位。进一步，因‘肾不吸胃，胃关不健’，肾虚不能纳气归元，亦", "c": "主木旺土虚"}, {"id": "pc:右+弦+大+缓", "n": "右·弦大缓脉", "o": "右弦大缓脉总主湿热痰火壅阻气分。弦主气郁，大示邪壅，缓为湿象，三者相合，反映湿、热、痰、火交结，气机郁滞之病机。原文所述水谷之湿与时序湿热相合，壅阻气分，致久嗽声嘶、形瘦目黄，久成老年痰火咳嗽。其病机以湿热壅阻为基础，进而气郁化火生痰，痰火交阻，故脉象弦大而缓", "c": "主湿热壅阻"}, {"id": "pc:右+弦+大", "n": "右·弦大脉", "o": "右·弦大脉所主病机广泛，总以弦主饮、主郁、主肝风，大主热、主虚、主邪盛为纲。其核心可归纳为饮邪内停、胃阳虚衰、热盛壅遏、木乘土位、虚损不足、痰火交炽、疟邪伏留、风阳鼓动八类。诸类之间常相互兼夹：饮邪多因阳虚而聚，故饮与胃阳虚并见；木乘土可致中虚，虚损又可生痰饮", "c": "主饮邪"}, {"id": "pc:右+弦+大+芤", "n": "右·弦大芤脉", "o": "右·弦大芤脉总起来主肝逆气火、阴血亏虚、气逆血涌三类病机。弦为肝逆，洪大为气火亢盛，芤则阴血内亏、血不归络，三者相合，反映水不养肝、肝不藏血，气逆血上，冲犯阳明而致狂吐。其核心在于肝气上逆与阴血亏虚并存，气火亢盛为逆动之力，血虚不藏为失守之基，终致血随气涌、脉", "c": "主肝逆气火"}, {"id": "pc:右+弦+大+虚+空", "n": "右·弦大虚空脉", "o": "右·弦大虚空脉总属虚证，以阳气亏虚、劳伤内损为核心。其脉形弦大而空虚，非实热亢盛之象，乃阳气浮越于外、内里不足之征。所主病机可归为三类：一为阳虚劳伤，因积劳耗阳，肝脾失和，脉见弦大空虚；二为脾运不健，右脉虚软涩滞，湿滞内停，症见能食不运、便溏跗肿；三为脾肾阳虚", "c": "主阳虚劳伤"}, {"id": "pc:右+弦+大+虚", "n": "右·弦大虚脉", "o": "右·弦大虚脉总属虚证，以阳气亏虚、劳伤内损为核心。其脉形弦大而空虚，非实热亢盛之象，乃阳气浮越于外、内里不足之征。所主病机可归为四类：一为虚阳浮越，因阳气亏虚，浮越于外，脉见大而虚；二为肝旺脾虚，弦为肝强，虚大为脾气不足，肝脾失和；三为肾虚失血，尺脉乱为肾气不", "c": "主虚阳浮越"}, {"id": "pc:右+弦+大+软", "n": "右·弦大软脉", "o": "右弦大软脉总起来主肝脾不调、湿热内蕴、阴分不足之证。右脉软主脾虚湿困，左脉弦大主肝木偏旺，弦大见于阴薄之体又示阴分不足。脾虚生湿，肝旺乘脾，湿郁化热，形成肝脾不调、湿热内蕴的复杂病机。四类病机相互关联：脾虚为本，肝旺为标，阴亏为体，湿热为果。脉象右软左弦大，正", "c": "主脾虚湿困"}, {"id": "pc:右+弦+实", "n": "右·弦实脉", "o": "右·弦实脉总起来主邪实壅滞、气机不畅之证，以中焦脾胃、阳明肠腑为病变重心。弦主气滞、肝郁、痛证，实主邪结、里实，右部候脾胃，故弦实相合，提示湿热、积滞、痰浊等实邪与肝气交阻于中焦或肠腑。其具体病机可归为四类：湿热积滞、肝胃气滞、里实邪结、疟痢湿浊。四者相互关联", "c": "主湿热积滞"}, {"id": "pc:右+弦+小", "n": "右·弦小脉", "o": "右·弦小脉总起来主阳气衰少、痰饮内停、肝郁脾弱及虚损之候。小脉主正气不足或阳虚，弦脉主饮邪内停或肝气偏旺，右部见之则病位多在中焦脾胃与肝肺。四类病机相互关联：阳气衰少则水液化痰上泛，痰饮内停又致阳气痹塞；肝郁犯土则脾弱，久则成损怯；暴寒内入更伤阳气，加重痰饮。", "c": "主虚损"}, {"id": "pc:右+弦+平+硬", "n": "右·弦平硬脉", "o": "右·弦平硬脉总属脾胃衰败、中气竭绝之候，其核心病机为土德大残。右脉本候脾胃，今弦硬而不柔和，更见歇止，是胃气将绝、脾土生化无源之危象。然此脉非独脾胃自病，实与肝木偏亢密切相关：左脉弦硬固平，肝气横逆，乘虚犯土，形成土虚木贼之势。故其病机可归纳为三类：一为土德大", "c": "主土德大残"}, {"id": "pc:右+弦+弱", "n": "右·弦弱脉", "o": "右·弦弱脉总以正虚邪扰、土虚木乘为纲。右弱主中气、脾阳或营血不足，左弦主肝木偏亢、邪气留滞或痰饮内动。其病机大致可分脾虚肝乘、正虚邪恋、痰饮上泛、肝胃不和、肝血不足、阳虚湿郁数类，彼此常相兼夹：脾虚则肝易乘，正虚则邪易恋，痰饮因虚而上泛，肝胃因逆而不和，肝血虚", "c": "主脾虚肝乘"}, {"id": "pc:右+弦+微+急", "n": "右·弦微急脉", "o": "右·弦微急脉总起来主肝郁气滞、脏气失调、痛与寒凝收引。弦为肝之常脉，微急则气机郁滞而不甚，故以肝郁气滞为根本。原文强调「有诸内者形诸外」，脉随脏气变动而主不同病机，弦微急即脏气偏颇之外应，故主脏气失调。气郁则血行不畅，经脉拘急，不通则痛，故主痛；寒性收引，使脉", "c": "主肝郁气滞"}, {"id": "pc:右+弦+微", "n": "右·弦微脉", "o": "右·弦微脉总以脾虚为本，兼见肝木偏亢、痰饮浊积与气血郁滞。右脉候脾，微弦乃土虚木乘之象：脾阳不足则运化失职，水谷蕴蒸为痰饮；脾气虚衰则肝气下陷，浊积停阻；气血亏虚则络脉失养，兼见痛与郁滞。四类病机相互关联：脾虚为根，土虚则木乘，肝郁则气滞血瘀，痰饮浊积由运化失", "c": "主脾虚痰饮"}, {"id": "pc:右+弦+微+软", "n": "右·弦微软脉", "o": "右·弦微软脉总以虚为本，兼见肝木偏亢与痰湿内滞。右软主气分不足，或脾肾气弱、水湿不运，或气营交困、络脉失养；右微弦则土虚木乘，脾受克伐而运化失职；左微弦主肝郁血少，气郁化痰，痰入筋骨发为流痰。四类病机相互关联：气虚为根，土虚则木乘，肝郁则血少，气弱则痰湿流注，", "c": "主气虚"}, {"id": "pc:右+弦+急", "n": "右·弦急脉", "o": "右弦急脉总属气机郁滞、逆乱不平之候。弦为肝木之象，主气郁；急为气逆之势，亦主邪滞与痛。其病机以气滞为基础，可表现为气逆上冲、邪滞内阻、肝郁筋急及疼痛等。四类之间相互关联：气郁则气机不畅，甚则上逆为呃忒呕恶；气滞则津血不行，痰瘀邪滞内停；肝郁则筋脉拘急，不通则痛", "c": "主邪滞"}, {"id": "pc:右+弦+散", "n": "右·弦散脉", "o": "右弦散脉总起来主肝气未和、营卫不调与阴损气弱。弦为肝脉，散示气机不畅，右脉候气，故其病机以肝气失和为核心，进而影响营卫调和；营卫不调则易往来寒热；阴损已极、胃气不复则脉见软数而弦散。三者相互关联：肝气未和可致营卫不调，阴损气弱又使肝气失养，故临床当兼顾疏肝、调", "c": "主肝气未和"}, {"id": "pc:右+弦+沉+和", "n": "右·弦沉和脉", "o": "右·弦沉和脉总起来主风气腹痛之病机，以脉象分表里寒热。浮缓主风邪在表，沉弦主邪郁于里，迟主中焦虚寒。各类之间以表里为纲，风邪外袭与里气不和相互关联，虚寒则为本虚标实之变。临证凭脉之浮沉迟弦，分表里用药，体现了脉诊在风气腹痛辨治中的核心作用。", "c": "主风邪在表"}, {"id": "pc:右+弦+沉+小", "n": "右·弦沉小脉", "o": "右·弦沉小脉总起来主土被木乘、脾胃虚弱、肝郁阴亏之候。其脉象由弦、沉、小复合而成：沉小为肝阴不足，弦为肝气偏旺；右脉细软兼迟，又示脾土虚弱、阳气不运。合而观之，反映肝胃气病日久，脾胃受累于肝，运化失职，故有中满之虞。三类病机相互关联：脾虚阳弱为病之本，肝郁阴亏", "c": "主脾虚阳弱"}, {"id": "pc:右+弦+沉+涩", "n": "右·弦沉涩脉", "o": "右·弦沉涩脉总起来主气滞、血瘀、湿阻与冲任不调四类病机。沉弦为气郁于内，涩主血行滞涩，右脉候脾肺，故气滞、湿阻多现右关；涩与沉弦相合，则气滞血瘀、冲任受阻，见于经闭、带下、腹痛有症等妇科疾患。四类之间相互关联：气滞为始动因素，气不行则血不畅而成瘀，气不化则湿停", "c": "主气滞"}, {"id": "pc:右+弦+沉+硬", "n": "右·弦沉硬脉", "o": "右弦沉硬脉总属肝脾同病、虚实夹杂之候。其核心病机为肝郁血虚火旺、脾胃虚弱而木乘土位，并伴气机遏抑。弦硬沉主肝之实（火盛、气郁）与虚（血虚），弦而无力主脾土受戕。三者相互关联：肝血虚火盛则肝气郁结，木郁则横逆犯土，脾胃失运则土虚更受木乘，气机因之遏抑不舒。故本脉", "c": "主肝郁血虚火旺"}, {"id": "pc:右+弦+沉", "n": "右·弦沉脉", "o": "右弦沉脉（含左沉弦、右弦左沉等）总以肝郁气滞、气机升降失常为核心病机。弦为肝脉，主郁、主气逆；沉主里、主气滞，故沉弦并见多示肝气郁结、疏泄失职。由此可衍生数类：气郁不达则水液不化，聚为痰饮，或泛溢为浮肿；气逆不降则肾不纳气，发为喘急；气聚日久则成瘕；肝郁化火或", "c": "主肝郁气滞"}, {"id": "pc:右+弦+沉+虚", "n": "右·弦沉虚脉", "o": "右弦沉虚脉总主阳气损伤、中气劳伤、气机滞涩之证。其脉沉为阳陷，弦虚为劳伤中气、清阳不升，故核心病机为过劳伤阳、清浊失运。因阳气微弱不能流通，气机滞涩，但非有形之滞，温中丸不应即示此意。三类病机相互关联：阳伤气陷为根本，劳伤中气为成因，气滞非有形为结果，共同反映", "c": "主阳伤气陷"}, {"id": "pc:右+弦+沉+迟", "n": "右·弦沉迟脉", "o": "右·弦沉迟脉总起来主内寒肝郁、气血不足，并可兼见表邪未解。沉迟为寒，弦主肝郁，故内寒肝郁是其核心病机；沉而无力则主气血亏虚，左右脉俱沉无力尤显气血不足；若兼浮象，则提示外感表邪未解。三类病机可单独出现，亦可相兼为病，如内寒肝郁兼气血不足，或外感引发里虚寒郁。临", "c": "主内寒肝郁"}, {"id": "pc:右+弦+洪+实+硬", "n": "右·弦洪实硬脉", "o": "右部弦洪实硬脉总起来主肝胃不和、邪热内蕴之实证。其核心病机为外感伏邪化热入胃，肝木乘春令之旺侮克胃土，形成木乘土位、胃府蕴热之候。脉象虽言弦洪实硬，但具体现弦硬异常、按之甚实，说明胃土受肝木之化而失其本脉，故不现典型洪实。三类病机相互关联：邪热内蕴为发病之因，", "c": "主肝木乘土"}, {"id": "pc:右+弦+洪", "n": "右·弦洪脉", "o": "右·弦洪脉总起来主气火亢盛、阴血内亏、虚阳浮越之病机。弦为肝逆，洪为气火亢盛，二者相合，既可见于肝气逆乱、气逆血上冲犯阳明之狂吐，又可见于劳瘵足三阴亏损、虚热无火、无根之火浮于外之证。其病机核心在于阴血亏虚、元气不摄，导致虚火妄动、气逆血涌；或脾胃先损，火土太", "c": "主气逆血涌"}, {"id": "pc:右+弦+浮+涩", "n": "右·弦浮涩脉", "o": "右弦浮涩脉总起来主肝郁脾困、虚损胀满之病机。左弦为肝木拂郁，右浮涩为脾土自困、清浊混淆，二者相合，反映肝郁乘脾、气机壅塞之基本病机。其证始由脘痛贯胁，继则腹大高凸、纳食减少、二便艰涩，乃有年操持、萦虑太甚，致藏真日漓、府阳不运，胀势乃成。故脉象既主肝郁与脾困之", "c": "主肝郁"}, {"id": "pc:右+弦+浮+硬", "n": "右·弦浮硬脉", "o": "右·弦浮硬脉总起来主肝胆火盛上冲、阴虚阳亢、气血两虚及热痰中焦。弦主肝，硬主火盛，浮主上炎，故见肝胆之火上冲头目；浮弦硬而不任重按，为阴血亏虚、阳气外浮，肝阳上亢；脉弱而浮弦硬，伴经血不行，为气血两虚、冲脉不充；右脉沉滑，为热痰杜塞中焦。四类病机相互关联：肝胆", "c": "主肝胆火盛"}, {"id": "pc:右+弦+浮+缓", "n": "右·弦浮缓脉", "o": "右·弦浮缓脉总属阳虚气弱、脾胃不振，兼夹风邪为患。浮为阳气外浮或风邪在表，缓为阳气不足、脾阳不振，弦为虚风内动或气机不畅。三则原文均以右脉浮弦缓为据，或断为伤寒过汗亡阳之阳虚，或断为脾胃阳虚兼气机不畅，或断为风邪犯胃、木乘土位。其核心病机在于阳气虚馁，脾胃运化", "c": "主阳虚"}, {"id": "pc:右+弦+浮", "n": "右·弦浮脉", "o": "右弦浮脉总以浮主表、弦主郁为纲，所主病机可归为风邪外袭、少阳邪郁、痰饮内停、气滞血瘀、肝郁火升、脾虚湿困、湿热内蕴七类。浮弦并见，在外多责之风邪客表或少阳枢机不利；在内则因弦脉主痛、主饮、主气滞，故见痰饮、瘀滞、肝郁火升；右关浮弦又常兼脾虚湿困，若合数脉则湿热", "c": "主风邪外袭"}, {"id": "pc:右+弦+涩+小", "n": "右·弦涩小脉", "o": "右弦涩小脉总属阳气衰微、阴血不足、脾阳受困之候。其脉象由小、涩、弦三部分组成：小涩主阳微血少，弦主脾阳受困、气机不畅。三者相合，反映本虚标实之病机——阳气阴血亏虚为本，脾运失健、气机壅滞为标。原文见年高体弱、阳微肢冷、脘痞便溏，正合此脉。故临床见此脉，当温中醒", "c": "主阳微"}, {"id": "pc:右+弦+涩+弱", "n": "右·弦涩弱脉", "o": "右·弦涩弱脉总起来主本虚标实、气机升降失司之候。左弦涩为肝血郁滞，右弱为肺气不足，二者并见，反映肺气虚而宣发无力，肝血郁而木失条达，金不制木，木反乘金，致咳嗽、浮肿先见于身半以上，继以失血。其病机核心在于肺肾气虚、阳不下达，兼肝血郁滞，属本虚标实。各类之间相互", "c": "主肝郁血滞"}, {"id": "pc:右+弦+涩+濡", "n": "右·弦涩濡脉", "o": "右·弦涩濡脉总属脾虚湿滞、气血不足、土虚木乘之候。弦为肝木乘脾，濡为脾虚湿停，涩为营血亏少、气机不畅，三脉合见，反映脾胃虚弱、湿滞血少、气机升降失常的复杂病机。其核心在脾：脾阳不运则湿滞内生（濡），化源不足则营血亏虚（涩），土虚则木乘（弦），进而清阳不升、浊阴", "c": "主脾虚湿滞"}, {"id": "pc:右+弦+涩+紧+迟", "n": "右·弦涩紧迟脉", "o": "右弦涩紧迟脉总起来主寒凝、气滞、食积与痛证。其脉象弦紧主寒邪拘急、气逆作痛；迟涩主寒凝气滞、食滞内阻。原文新产半月，新寒外受，引动厥气上逆，食滞交阻中宫，胃气不得下降，故见胸脘痛大发、呕吐拒按、形寒怯冷、苔灰腻。四类病机相互关联：寒邪外袭为诱因，引动肝气上逆，", "c": "主寒凝"}, {"id": "pc:右+弦+涩+结", "n": "右·弦涩结脉", "o": "右·弦涩结脉总起来主肝脾气血郁滞、虚中夹实之病机。弦主肝郁，涩主血少，结为气滞血瘀，尺中倍弱为肾虚，诸象合参，反映劳倦伤脾、郁怒伤肝，肝脾气血两伤而邪气内结。其病机类别包括肝郁气滞、血少血瘀、脾虚劳倦、肾虚及虚中夹实，彼此关联：肝郁气滞与血少血瘀侧重气血郁滞之", "c": "主肝郁气滞"}, {"id": "pc:右+弦+涩", "n": "右·弦涩脉", "o": "右·弦涩脉总起来主‘虚中夹郁、滞中兼虚’之候。弦为气机紧张，主肝旺、气逆、饮邪、气火；涩为脉道不利，主血少、阴亏、气滞、血瘀、湿阻。二者并见，非纯实邪壅滞，多为阴血亏虚而气机郁滞，或气郁日久兼血行不畅。其类别虽分血虚气滞、肝旺犯胃、痰饮气阻、气火郁逆、瘀结癥瘕", "c": "主血虚气滞"}, {"id": "pc:右+弦+滑+和", "n": "右·弦滑和脉", "o": "右·弦滑和脉总起来主气郁、痰湿及肝胃不和。弦主气机郁滞，滑主痰湿内蕴，右关候脾胃，故弦滑并见右关，反映肝气郁结、痰湿中阻、肝胃失和之病机。原文脉象稍柔和，是郁滞稍解、痰湿渐化之征，症见胀满渐舒、略能安谷，说明脉象好转与症候相应。三类病机相互关联：气郁可生痰湿，", "c": "主气郁"}, {"id": "pc:右+弦+滑+大", "n": "右·弦滑大脉", "o": "右弦滑大脉总起来主肝胃火热壅盛、热侵营血之证。其脉象弦强滑大，弦强属肝火，滑大属胃热，二者并见，反映肝胃之火素盛，热邪充斥气分并侵及营血。原文见年少体瘦妇人初秋患霍乱转筋，舌绛目赤，大渴饮冷，脉左弦强而右滑大，以白虎汤加减清肝胃之火而愈。可见此脉所主病机以实热", "c": "主肝火素盛"}, {"id": "pc:右+弦+滑+小", "n": "右·弦滑小脉", "o": "右弦滑小脉总起来主肝胃不和、中阳不足、痰湿内停之候。其脉象由弦、滑、小复合而成：左弦示肝木偏旺，右小滑示中阳不足、痰湿内停。三者相互关联：中阳不足则运化失职，痰湿内生，痰湿中阻又致肝木犯胃，形成肝胃不和、虚实夹杂之局。原文“中阳不足，肝木犯胃”点明病本在虚，病", "c": "主肝胃不和"}, {"id": "pc:右+弦+滑+沉+小", "n": "右·弦滑沉小脉", "o": "右弦滑沉小脉总起来主痰饮内伏、正虚邪实之候。其脉象由沉、弦、小、滑四者复合而成：沉主里，示病位在里；弦主饮，滑主痰，示痰饮内盛；小示正虚，示正气不足。四者相合，反映痰饮内伏、温邪引动、正虚邪恋的复杂病机。右关带数，又专主脾胃痰热。各类病机之间相互关联：正虚（小", "c": "主痰饮"}, {"id": "pc:右+弦+滑+洪+硬", "n": "右·弦滑洪硬脉", "o": "右弦滑洪硬脉总属火盛阴亏、气血两亏、冲气上逆及阴虚水停之候。其脉虽名弦滑洪硬，但原文两段均强调脉见弦硬有力或弦硬而长，而非洪滑之象，故其病机核心为火盛灼阴、阴分亏虚，兼正气虚损不能拒邪。火盛阴亏则脉失柔润而弦硬，气血两亏则脉道失充而强硬，冲气上逆则右脉弦硬且长", "c": "主火盛阴亏"}, {"id": "pc:右+弦+滑+浮", "n": "右·弦滑浮脉", "o": "右寸关弦滑浮脉总起来主痰实于上、微兼客热，并常与下焦阴虚并见。弦滑主痰实，浮主客热，左关尺细软无神主阴虚于下。三类病机相互关联：痰实壅于上焦，客热犯于表或上焦，而阴虚于下则为本虚，形成上实下虚、虚实夹杂之候。原文强调攻补皆难偏任，故治疗需清化痰热兼滋下焦，浊药", "c": "主痰实"}, {"id": "pc:右+弦+滑+濡", "n": "右·弦滑濡脉", "o": "右·弦滑濡脉总起来主湿浊内盛、气机壅滞与正虚湿恋三类病机。其脉象由弦、滑、濡复合而成：濡主湿，滑主痰湿内盛，弦主气机壅滞或肝气不舒。右关候脾，濡滑示脾运失职、湿浊内停；弦示气机壅滞，或余毒蕴结。诸段原文均见湿浊为患，或兼气滞，或兼正虚。湿浊内盛者，见浮肿胀满、", "c": "主湿浊内盛"}, {"id": "pc:右+弦+滑+紧", "n": "右·弦滑紧脉", "o": "右·弦滑紧脉总属阳气郁遏、阴邪内结之候，以胸痹为其典型病机。弦紧主阳气不舒、阴寒内结，滑主痰湿阴邪，右关候胸膈脾胃，故脉象复合反映胸中阳气痹阻、阴寒痰湿凝结。三类病机中，“主阳郁”为病机之枢，阳气不舒则阴邪易于结聚；“主阴结”言阴寒凝结之性；“主痰湿”言痰湿阴", "c": "主阳郁"}, {"id": "pc:右+弦+滑+结", "n": "右·弦滑结脉", "o": "右·弦滑结脉总起来主肝火、痰壅、痰火交争及肾水不足。右脉弦滑搏结，以弦为肝火、滑为痰壅、搏结为痰火交争，三象合见，反映肝火亢盛、痰浊内壅、痰火互结之实邪壅滞；左脉但弦而小，则示肾水不足、不能涵木之虚象。诸类之间，肾水不足为本，水不涵木则肝木亢而生火，肝火乘肺则", "c": "主肝火"}, {"id": "pc:右+弦+滑", "n": "右·弦滑脉", "o": "右·弦滑脉总属痰湿内蕴、气机壅滞之象，以右候脾胃，滑主痰湿食积，弦主气滞、饮邪或肝木乘脾。其病机可归纳为痰湿、痰热、风痰、肝脾不调、疟邪痰湿、饮停气滞及积滞郁热等类。各段原文多围绕右脉候中焦脾胃，痰湿为共同基础，或兼热化、风动、气逆、食积，或兼肝木乘脾、疟邪留", "c": "主痰湿内蕴"}, {"id": "pc:右+弦+滑+虚+濡", "n": "右·弦滑虚濡脉", "o": "右·弦滑虚濡脉总起来主正虚邪恋、虚实夹杂之病机。其脉象由虚弦与濡滑复合而成：虚弦主气血阴阳亏虚，尤以少阴、气阴两亏为根；濡滑主痰湿蕴毒稽留，脾胃运化失职。四段原文均见于中发背疮疡后期，腐肉渐脱而脉象未和，示正气尚虚、湿毒未净。具体而言，虚弦可进一步分化为气血两", "c": "主湿"}, {"id": "pc:右+弦+滑+虚", "n": "右·弦滑虚脉", "o": "右·弦滑虚脉总起来主正虚邪恋、虚实夹杂之病机。其脉象由虚与弦滑复合而成：虚主气阴不足，为病之本；弦滑主痰浊内蕴、肝郁气逆，为病之标。原文见呛咳未除、头晕目暗、苔滑微灰、便结，示肺虚肝亢、痰浊上扰、痰滞津亏。三类病机相互关联：气阴两虚则运化无力，痰浊内生；痰浊壅", "c": "主气阴两虚"}, {"id": "pc:右+弦+濡+空", "n": "右·弦濡空脉", "o": "右弦濡空脉总属虚实夹杂、形神两伤之候。其脉象由弦、濡、空三象复合而成：弦主络血不宁，为血络失和、血不循经之标；空主形神两伤，为正气亏虚、形神失养之本；濡主气血耗损，为营血不足、脉道不充之由。三者相互关联，因气血耗损于内，形神失养，络血因之不宁，终致吐血频发。此", "c": "主络血不宁"}, {"id": "pc:右+弦+濡", "n": "右·弦濡脉", "o": "右·弦濡脉总以弦主肝郁、饮邪、气逆，濡主脾虚、湿困、阳弱为纲。其病机可归纳为脾虚湿困、饮邪内停、肝郁脾困、阳虚水泛、湿热内蕴、肝肺肾虚、胃虚痰逆七类。弦与濡并见，多示本虚标实、寒热错杂之候：或脾虚湿盛而肝木乘之，或阳虚饮逆而肺胃不降，或湿热内阻而气机壅滞。各证", "c": "主饮邪内停"}, {"id": "pc:右+弦+硬", "n": "右·弦硬脉", "o": "右·弦硬脉总起来主肝胃气郁、肝火冲逆、阴亏火旺、肝风内动、饮停气结及邪实正虚等病机。弦为肝气，硬为气郁坚结、脉失柔和，右脉候脾胃，故右弦硬多示肝木犯胃、胃气壅滞；若左右皆弦硬，则肝气恣横、冲气上逆，甚则血随气升、充塞脑部。弦硬又为阴亏之象，因阴血不足、筋脉失养", "c": "主肝胃气郁"}, {"id": "pc:右+弦+空", "n": "右·弦空脉", "o": "右·弦空脉总属虚实夹杂、肝脾不调之候。右脉候脾胃，空为正气不足，主脾胃气弱；弦为肝木偏旺，主气机郁滞。二者并见，反映肝旺乘土、脾虚不运，且常伴余邪未清，形成正虚邪恋之势。原文身凉额不热、舌苔腻白、烦渴渐减、正渐弱，正是暑湿未楚而正气渐伤之象。故本脉所主，以脾虚", "c": "主脾虚"}, {"id": "pc:右+弦+紧", "n": "右·弦紧脉", "o": "右·弦紧脉总起来主寒、主饮、主气滞、主痛、主邪郁少阳，并可兼见湿热痰浊与温疫化火。弦为气机郁滞、少阳主脉，紧为寒邪凝结、邪气壅实，二者相合，反映寒凝气滞、饮邪内伏、邪结在里之病机。从所收段落看，弦紧脉最多见于寒饮内停（5506、5514）与寒凝气滞（10440", "c": "主寒饮"}, {"id": "pc:右+弦+细+大", "n": "右·弦细大脉", "o": "右·弦细大脉总起来主虚实夹杂、肝脾不和及暑湿蕴结之证。其脉象由弦、细、大三象复合而成：弦主肝郁气逆，细主阴血不足或脾虚，大主邪气壅盛或病势鸱张。右部见大，多主气分邪实或脾病及肝；左部弦细，多主阴分受灼或肝木失柔。两段原文分别见下痢腹瘕、疟疾寒热，皆因土虚木贼或", "c": "主肝脾不和"}, {"id": "pc:右+弦+细+急+促", "n": "右·弦细急促脉", "o": "右·弦细急促脉总起来主阴液亏虚、木火内炽、湿浊内蕴之复合病机。其脉弦主木火，细促为阴亏火旺，濡滑主湿浊内蕴。阴液亏虚则不化气，气火内烁，热从内陷，湿浊蒸腾，故见胃糜舌腐。脉不耐重按，示正气已虚，邪热内陷，病势深重。三类病机相互交织：阴亏为本，木火为标，湿浊为兼", "c": "主阴亏火旺"}, {"id": "pc:右+弦+细+沉+伏", "n": "右·弦细沉伏脉", "o": "右弦细沉伏脉总起来主阳气衰微、浊阴内盛、积气结于肝络之病机。沉细弦伏四象相合，沉主里、细主虚、弦主阴凝、伏主气闭，故其核心为阳微阴盛，浊阴克伐阳气。由此根本病机，进而导致积气内结、肝络凝滞，原文所谓“脐右有积气”“久病在络”即是。三类之间以阳微阴盛为本，积气在", "c": "主阳微阴盛"}, {"id": "pc:右+弦+细+沉+小", "n": "右·弦细沉小脉", "o": "右·弦细沉小脉总起来主里虚邪郁、营虚邪陷之证。沉细小二脉并见，主里主虚主不足，反映正气内虚、营血亏弱；弦脉主邪郁，示邪气郁滞不散。三者相合，说明正虚而邪气内陷，郁闭不出。原文以“沉主里，细主虚，小主不足，弦主邪郁”为纲，结合头疼、齿痛、舌苔白腻、胸闷欲呕、二目", "c": "主里虚"}, {"id": "pc:右+弦+细+沉+紧", "n": "右·弦细沉紧脉", "o": "右·弦细沉紧脉总属寒、气滞、里虚、痰结与痛之复合病机。弦主气滞，紧主寒主痛，沉细主里虚，合而观之，其核心为寒邪内侵、气机郁滞、阳气不足、寒痰内结，以致不通则痛。原文15563以气滞兼寒痰为患，脉见弦细沉紧，症见腹痛块现、口吐冷痰；原文16189以寒邪深入、肝经", "c": "主气滞"}, {"id": "pc:右+弦+细+浮", "n": "右·弦细浮脉", "o": "右·弦细浮脉总起来主肝郁阴伤、火浮余邪及正虚邪陷之机。弦细为肝郁阴血不足，浮为余邪未尽、火性上炎，故常见胁脘掣痛、上引太阳等肝经症状；若浮数无根，则示正气已虚、邪热浮越，可致三阳合病或正虚邪陷之危候。各类之间，肝郁阴伤为本，火浮余邪为标，正虚邪陷为病进之变，总", "c": "主火浮余邪"}, {"id": "pc:右+弦+细+涩", "n": "右·弦细涩脉", "o": "右·弦细涩脉总属虚实夹杂之候，以肝郁脾虚、阴血亏虚为基本病机。弦主肝郁气滞，细主阴血不足，涩主血少瘀滞或湿滞。诸类中，肝郁气滞为始动因素，肝木横逆克脾，则脾虚湿困、胃络瘀滞；脾虚生化不足，则阴血亏虚，甚则虚风内动；气血瘀水互结，则成臌胀。各病机相互关联，形成肝", "c": "主肝郁气滞"}, {"id": "pc:右+弦+细+滑+大", "n": "右·弦细滑大脉", "o": "右·弦细滑大脉总起来主虚实夹杂之证。左脉弦细主心肾阴血不足，属虚；右脉滑大主痰涎壅盛，属实。二者并见，反映阴血亏虚与痰浊内盛同时存在，病位涉及心、肾、胆，症见神气模糊、夜不能寐、心忡、腰痛、舌苔黄垢。其病机核心为虚（阴血不足）与实（痰涎壅盛）相互交织，故治疗宜", "c": "主虚"}, {"id": "pc:右+弦+细+滑+微", "n": "右·弦细滑微脉", "o": "右·弦细滑微脉总起来主湿痰阻胃、肝火鼓动、阴血不足及阴阳不交之病机。其脉象复合，细主阴血虚，左关微弦主肝火，右关带滑主胃中湿痰。湿痰黏腻阻于胃府，阻碍坎离相交之路，致水火不能相媾；肝火借湿痰而鼓动，上扰心神；阴血不足则脉道不充。诸因交织，虚实夹杂，标本同病，最", "c": "主湿痰"}, {"id": "pc:右+弦+细+滑", "n": "右·弦细滑脉", "o": "右·弦细滑脉总起来主肝郁血少、痰湿内滞及血虚夹痰之病机。弦细主肝郁血少，情志怫郁，阴血不足；滑主痰湿内滞，脾运不健，痰浊内生。二者相合，常见肝脾失调、痰湿内阻之证，如寒热交作、呕哕、遍身疼；若血虚与痰浊并见，则致神识迟钝、盗汗等。各类之间相互关联：肝郁血少可致", "c": "主肝郁血少"}, {"id": "pc:右+弦+细+滑+虚", "n": "右·弦细滑虚脉", "o": "右·弦细滑虚脉总起来主痰饮与正虚，以痰饮偏盛于肺为核心病机，兼见虚象。弦主饮、滑主痰，右甚则痰饮壅肺，故喘嗽坐不能卧；虚弦细滑则示病久正虚，痰饮未化。两类病机相互关联，痰饮为标实，正虚为本虚，临证需权衡虚实，治痰饮不忘顾虚，补虚勿助痰壅。", "c": "主痰饮"}, {"id": "pc:右+弦+细+濡+紧", "n": "右·弦细濡紧脉", "o": "右弦细濡紧脉总起来主营血亏虚、宿瘀内阻、湿邪下注之复合病机。弦紧主瘀滞，濡细主血亏与湿困，诸脉相合，提示产后营血已亏，宿瘀未楚，挟湿下注膀胱，形成虚、瘀、湿互结之候。三类病机相互关联：血亏则脉道不充，瘀血内阻则气机不畅，湿邪困阻则宣化失司，共同导致腹痛、小溲淋", "c": "主瘀滞"}, {"id": "pc:右+弦+细+紧", "n": "右·弦细紧脉", "o": "右·弦细紧脉总起来主肝木郁结、营血亏虚、火动神怯之复合病机。弦紧主木郁气滞，细主营液内耗，关浮大主虚阳上扰、木火引动君火，寸濡则心营不足。诸类相互关联：肝郁日久化火，火动则耗伤营液，营虚则木失滋养而郁结更甚；营血亏少则胆气不足，神怯不安。原文症见烦扰不安、夜不", "c": "主木郁"}, {"id": "pc:右+弦+细", "n": "右·弦细脉", "o": "右·弦细脉总以弦、细二象合参为辨。弦主肝郁气滞、木贼土虚，亦主饮、主痛、主寒；细主阴血亏虚、湿滞脉道。右脉候气候脾，故右弦细多示肝木乘脾、脾虚气滞，或湿郁中焦；若左脉细弦，则偏于肝肾阴亏、肝失柔养。合而观之，此脉所主病机可归为七类：肝郁气滞、脾虚木贼、阴血亏虚", "c": "主肝郁气滞"}, {"id": "pc:右+弦+细+虚+涩+短", "n": "右·弦细虚涩短脉", "o": "右弦细虚涩短脉总主脾虚湿困、气血不足、肺气不足之候。其脉象复合，弦细涩主气滞血少，虚主正虚，短主气弱。诸类病机相互关联：脾虚湿困为中枢，脾失健运则气血生化不足，进而肺气亦虚；湿困又加重气滞，形成虚实夹杂之局。原文面黄、汗多、目赤、四肢沉重、减食、腹痛、咳嗽等症", "c": "主脾虚湿困"}, {"id": "pc:右+弦+细+虚+涩", "n": "右·弦细虚涩脉", "o": "右弦细虚涩脉总主脾虚湿困、气血不足、肺气不足之候。其脉象复合，弦细涩主气滞血少，虚主正虚，短主气弱。诸类病机相互关联：脾虚湿困为中枢，脾失健运则气血生化不足，进而肺气亦虚；湿困又加重气滞，形成虚实夹杂之局。原文面黄、汗多、目赤、四肢沉重、减食、腹中时时痛、咳嗽", "c": "主脾虚湿困"}, {"id": "pc:右+弦+细+虚", "n": "右·弦细虚脉", "o": "右·弦细虚脉总属正虚邪扰、虚实夹杂之候。其脉象由虚、细、弦复合而成：虚细主气阴两虚、阴血不足；弦主肝气偏旺、木乘土位。所主病机主要有三：一为气阴两虚，见咳嗽潮热、形怯；二为肝木犯土，见脘闷便泻；三为肝肾阴亏，见腰疼麻木、经闭。三者相互关联：气阴亏虚为病之本，肝", "c": "主气阴两虚"}, {"id": "pc:右+弦+细+迟+芤", "n": "右·弦细迟芤脉", "o": "右弦细迟芤脉总起来主暑邪内郁、阴血亏虚、邪盛正虚三类病机。弦主暑邪内郁，因暑热郁遏气机；细芤迟主阴血亏虚，因年高久病，阴血耗伤，脉道不充；弦细芤迟并见，则示邪盛正虚，暑邪内迫而气阴两伤。三者相互关联：暑邪内郁为病因，阴血亏虚为体质基础，邪盛正虚为误治后的病理状", "c": "主暑邪内郁"}, {"id": "pc:右+弦+缓", "n": "右·弦缓脉", "o": "右弦缓脉总起来主肝郁脾弱、湿滞痰阻、阳虚气弱、湿热痰火及邪正相争等病机。弦为肝木偏旺、气机郁滞之征，缓为脾土受克、湿滞不化之象，二者相合，基础病机在于肝木犯土、运化不健。在此基础上，若兼浮则阳虚气弱、风邪外犯；兼大则湿热痰火壅阻气分；兼数则虚阳偏亢或余邪未清，", "c": "主肝郁脾弱"}, {"id": "pc:右+弦+缓+迟", "n": "右·弦缓迟脉", "o": "右弦缓迟脉总起来主肝旺、湿滞、脾弱与血虚。左弦为肝气肝阳上升之征，右迟缓为湿滞未楚、脾胃运化无权之象；而营血本虚，肝失柔养，亦令脉弦。四类病机相互关联：肝旺克脾，脾弱生湿，湿滞又碍运化，久则营血亏虚。故本脉以肝旺脾弱、湿滞血虚为总纲，弦缓迟并见，提示痛势虽缓而", "c": "主肝旺"}, {"id": "pe:右+弦", "n": "右·弦脉", "o": "右弦脉总以肝木偏亢、气机郁滞为核心，右候脾胃，故常示木乘土位。其病机涵盖肝木乘土、饮邪内停、气郁气逆、肝火风阳、虚中夹实、疟邪少阳、寒凝痛证等类。弦为肝脉，主郁、主饮、主痛、主气逆；右脉候中焦，故右弦多反映肝脾不和、痰饮内阻、气机壅滞。诸类之间常相互兼夹：肝木", "c": "主肝木乘土"}, {"id": "pc:右+弦+芤", "n": "右·弦芤脉", "o": "右·弦芤脉总起来主气血亏极、阴阳不相维系、阳气外浮三类病机。弦为肝血不足，芤主失血，浮数无根乃阳气外浮，三者相合，反映气血亏极、阴阳不相维系之象。其核心在于阴血亏虚与阳气浮越并存，阴血亏虚为失守之根，阳气外浮为逆动之标，故见阳气上浮而面热、外越而身热，属虚劳中", "c": "主气血亏极"}, {"id": "pc:右+弦+虚+涩", "n": "右·弦虚涩脉", "o": "右弦虚涩脉总属脾虚肝郁、营卫不和之候。虚为脾胃气虚，弦为肝木郁滞，涩为营血运行不畅。三者相合，反映肝病日久，木郁土位，脾胃虚弱，气血生化不足，营卫二气失于流畅。其病机核心在脾虚肝郁，由此导致营卫不和而见寒热，肝病先厥后热。诸类之间，脾虚为本，肝郁为标，营卫涩滞", "c": "主脾虚肝郁"}, {"id": "pc:右+弦+虚", "n": "右·弦虚脉", "o": "右·弦虚脉总以右虚左弦为特征，右虚主脾胃中气不足，左弦主肝木偏旺或肝风内动。其病机核心为脾虚肝乘，即土虚木贼，涵盖脾虚肝乘、中虚肝风、脾虚湿滞、肝旺脾弱、气阴两虚、气虚痰湿、肝风犯胃等类。各类之间相互关联：脾虚为本，肝旺为标，湿滞、痰湿、风动皆由虚而生，气阴两", "c": "主脾虚肝乘"}, {"id": "pc:右+弦+软", "n": "右·弦软脉", "o": "右·弦软脉总以脾虚肝旺为核心，软主正气不足、湿邪内滞，弦主肝木偏亢、气机郁滞。其病机涵盖脾虚湿困、肝木乘土、胃津气虚、痰湿内阻、肝郁化火及下焦火衰数端。脾虚为根，土虚则木乘，肝郁化火则伤阴，湿聚成痰则阻络，下焦火衰则津不上承。诸类相互关联：气虚湿滞为共同基础，", "c": "主脾虚湿困"}, {"id": "pc:右+弦+迟", "n": "右·弦迟脉", "o": "右·弦迟脉总起来主阳气衰微、寒凝气滞，兼及肝木偏亢与寒凉抑遏。其核心病机为阳衰寒凝：迟主阳衰，弦主寒凝气滞，故见中下阳衰、运化失职之证。在此基础上，右迟可具体表现为中阳不足，阳虚失温则畏寒便溏、食减，水湿不化则浮肿腹胀；左弦则主肝木偏亢，肝失疏泄、筋脉不利而见", "c": "主阳衰寒凝"}, {"id": "pc:右+弦+长+硬", "n": "右·弦长硬脉", "o": "右·弦长硬脉总起来主气火亢盛、升降失常之病机。弦主肝，硬主亢盛，长主气火有余，故其核心为肝阳上亢、胃气上逆与冲气上冲，导致气血并走于上，发为脑充血、头疼、眩晕、肢痿等症。在此基础上，若兼阴分亏损，则火盛灼阴，脉见弦硬有力而非洪滑；若兼痰热内壅，则痰涎上泛、喉间", "c": "主肝阳上亢"}, {"id": "pc:右+弦+长", "n": "右·弦长脉", "o": "右·弦长脉总起来以肝木气机偏亢为核心，弦为肝象，长为气有余，故首主肝木亢盛。由此衍生数类：肝木亢逆则冲气、胃气上冲，见右脉弦长有力而呕逆吐衄；肝火炽盛则弦长兼硬数，见头疼、便燥；木火乘土则右关弦长而软弱，见木侮土、食停呕逆；肝风挟痰火则弦长上鱼际，见眩晕肢胀；", "c": "主肝木亢盛"}, {"id": "pc:右+弱+促", "n": "右·弱促脉", "o": "右·弱促脉总起来主阳伤津劫、里热未清、湿蕴未化及中虚谷少四类病机，四者相互关联而非孤立。其脉右促为里热未清、阳伤而躁之征，左弱示中气不足；目微黄、嗜酒、中虚谷少又示湿蕴与中虚。病起于辛温大汗，先伤卫阳胃津，阳伤则中虚，津劫则热留，中虚湿聚则蕴热，湿热相合又加重", "c": "主阳伤"}, {"id": "pc:右+弱+坚", "n": "右·弱坚脉", "o": "右·弱坚脉总属本虚标实、阴虚火旺而中土亦弱之候。左脉坚主木火偏旺、肝阳不潜，右脉弱主中气不足、营液久耗。其病机核心为阴液亏虚，不能制火，致肝火升腾，迫血上溢，故见失血嗽痰；火旺更耗营阴，中土虚弱则少食形羸。情志郁勃为发病诱因，郁而化火，加重阴虚火旺。诸类之间，", "c": "主阴虚火旺"}, {"id": "pc:右+弱+缓", "n": "右·弱缓脉", "o": "右·弱缓脉总属虚候，以脾胃气虚为核心，兼湿盛、气血不足、阳陷虚泻及虚阳外浮。右脉候脾，缓弱无力直接反映脾胃气虚、运化失职；脾虚则水湿内停，故脉濡缓而主湿盛；脾虚生化不足，则气血亏虚、脉道不充；清阳不升、中气下陷，则见虚泻、饮食物逆流；气虚阳弱，虚阳外浮，则见假", "c": "主脾虚"}, {"id": "pe:右+弱", "n": "右·弱脉", "o": "右·弱脉总以虚为主，尤以脾肺气虚、气血不足为核心。右寸弱主肺气虚，右关弱主脾虚，右尺弱主肾阳或命门火衰；弱而兼见他部弦、滑、数等，则成正虚邪恋、虚实夹杂之候。其具体病机可归为脾虚、肺气虚、气血两虚、正虚邪恋、虚风内动、胎元不固数类。诸类之间，虚为根本，或气虚，", "c": "主脾虚"}, {"id": "pc:右+弱+软", "n": "右·弱软脉", "o": "右·弱软脉总属虚象，以气虚、脾虚为核心，常兼他部脉象而呈复合病机。右寸软弱主肺气虚，右关软弱主脾虚湿盛，右尺弱主肾阳不足；若兼左脉弦长、弦细，则为肺虚肝旺、木行乘金；兼左脉细数，则为气阴两伤之上损；兼左脉数而有力或弦滑，则为正虚邪恋、虚实夹杂；兼左脉散乱，则为", "c": "主脾虚湿盛"}, {"id": "pc:右+微+弱+促", "n": "右·微弱促脉", "o": "右·微弱促脉总主阳伤津劫、里热未清、湿蕴未化及中虚谷少四类病机。其脉微弱为阳气大伤、胃津被劫之虚象，促为里热未清之征，目黄、嗜酒等症又示湿蕴与中虚。四者相互关联：辛温大汗先伤卫阳胃津，阳伤则中虚，津劫则热留，中虚湿聚则蕴热，湿与热合又加重里热，形成虚、热、湿、", "c": "主阳伤津劫"}, {"id": "pc:右+微+弱", "n": "右·微弱脉", "o": "右·微弱脉总主正气虚衰，以气虚、阳衰为核心，涉及脾肾虚寒、气血两虚、肝虚火郁及虚中夹实等类。脉微弱为阳气无力鼓动、气血不足之象，右关甚则脾虚，右尺甚则下焦虚寒；左微弱则肝虚火郁。诸类之间相互关联：气虚阳衰可致脾肾虚寒，气血两虚常与肝虚并见，正虚又易夹实邪。总以", "c": "主气虚阳衰"}, {"id": "pc:右+微+涩+小+短", "n": "右·微涩小短脉", "o": "右·微涩小短脉总属正气内衰、五脏虚损之候。其脉象以微涩小短为主，按之微弱短涩，举指或见虚滑，反映根本不足而虚阳外浮。所主病机可归为三类：一主脏虚，因沉小微弱短涩软濡俱为脏虚之脉；二主阳虚外浮，由举指滑、按之微示虚阳浮外而下元不固；三主气血不足，因微涩小短合见为", "c": "主脏虚"}, {"id": "pc:右+微+涩", "n": "右·微涩脉", "o": "右·微涩脉总起来主虚证，包括肺虚津枯、脾阳衰微及气血亏虚。微为阳虚、涩为血少，右部主肺脾，故右微涩多责之肺脾阳气阴血不足。三证虽异，皆属正虚：肺虚津枯则水竭金枯，脾阳衰微则中宫阳气欲寂，气血亏虚则肝血不足、气虚之别。其间可相互影响，如脾阳不足可致气血生化乏源，", "c": "主肺虚津枯"}, {"id": "pc:右+微+濡", "n": "右·微濡脉", "o": "右·微濡脉总起来主阳气虚馁、虚阳上浮及湿浊痰热三类病机。其核心在于阳气不足，脉道不充，故右脉细软无力，重按即无，伴便泻足冷等虚寒之象；虚阳上浮则见目赤肿痛等假热之症，然脉不实；若兼滑象，则又主湿浊痰热内蕴，表现为湿热困脾或下注。三者之间，阳虚为本，虚阳上浮为阳", "c": "主阳虚"}, {"id": "pc:右+微+紧", "n": "右·微紧脉", "o": "右·微紧脉总起来主中焦气机郁滞，兼涉营血亏虚与少阳之气下陷。右关微紧为气郁之象，紧而微者郁滞不甚；左细涩为营血亏少、脉道不利。原文“营分数亏，兼之少阳之气又下陷于肝肾”点明病机关键：营血亏虚为本，气机郁滞为标，少阳之气不升反陷，郁而化热，故见傍晚发热、手心热。", "c": "主气郁"}, {"id": "pc:右+微+结", "n": "右·微结脉", "o": "右·微结脉总起来主痰阻脉络兼正气略伤。结脉主痰块堵塞隧道，气血运行不畅；微脉示正气略伤。二者并见，反映痰饮内阻、正气渐损之病机。原文以伏暑夹痰饮为例，屡治热不退、痰不除，右脉微结，针后出紫血、咳老痰而愈，证实痰去则脉通。故本脉所主以痰阻为核心，正伤为兼，痰阻与", "c": "主痰阻"}, {"id": "pc:右+微+缓", "n": "右·微缓脉", "o": "右·微缓脉总起来主气血两亏、本虚标实之候。微为阳气衰微，缓为气血不足，尺寸俱见微缓，是久痢一载、气血耗伤之明证。然此脉非单纯虚象，原文揭示其病根在痰积、湿热、肝气交阻，因元气亏虚，不能运化痰湿、疏泄肝气，遂致痰积中焦、湿热内蕴、肝气入络，形成虚实夹杂之局。故微", "c": "主气血两亏"}, {"id": "pe:右+微", "n": "右·微脉", "o": "右微脉总属阳气衰微、正气不足之象，然其所主病机广泛，涉及多个脏腑及虚实夹杂之证。微脉本为气血鼓动无力，右寸候肺、右关候脾，故右微多主脾肺气虚、中阳衰微；若与阴血亏虚并见，则为阴阳两虚；若尺部沉伏而微，则主肾虚火不归原、虚阳浮游；若与实脉并见，则示正虚邪实、阴阳", "c": "主阳气虚衰"}, {"id": "pc:右+微+软", "n": "右·微软脉", "o": "右微软脉总以虚为核心，主气分不足、脾肾气弱，虚甚则阳气衰微，重按即无。虚阳上浮与内寒皆由虚所生：阳气不足，虚阳不能潜藏而上浮，故面肿目赤似热；阳虚生内寒，故便泻足冷。三者以虚为根，虚阳上浮与寒为虚之变，临证当舍症从脉，识假热真寒之机。", "c": "主虚"}, {"id": "pe:右+急", "n": "右·急脉", "o": "右急脉总起来主病机以虚、热、气逆、湿热、肝虚火动为主。虚证见脉急无力，为气血两虚、气随血脱；热证分数急脉之虚实，虚热与实热并见；气逆由弦急脉所示，气机郁滞、逆乱不平；湿热由缓急脉所致，湿郁气分、肝风内动；肝虚火动由细急脉所主，肝血不足、火动气逆。各类之间，急脉", "c": "主虚"}, {"id": "pc:右+散+乱", "n": "右·散乱脉", "o": "右·散乱脉总起来主正气涣散、根本亏竭，兼见胃气衰败、痰食内阻之正虚邪实危候。其脉象散乱无绪如解索，两尺绝无神气，是脏气衰败、神气将绝之兆；右寸关洪滑弹指如黄豆大，又示胃气衰败、痰食壅盛。诸类之间，以正气涣散、根本亏竭为本，胃气衰败、痰食内阻为标，标本并见，形成", "c": "主正气涣散"}, {"id": "pe:右+散", "n": "右·散脉", "o": "右散脉总起来主正气涣散、根本亏竭，以虚损为核心，兼及气机失调与正虚邪实。散脉本象为气散不敛，右部见散，多因劳倦忧思伤脾耗气，或湿困脾阳，致脾肺气虚、气阴两伤，故主虚损；其甚者正气涣散、根本亏竭，兼胃气衰败、痰食内阻，成正虚邪实危候。右弦散脉则侧重肝气失和、营卫", "c": "主阴损气弱"}, {"id": "pc:右+数+伏", "n": "右·数伏脉", "o": "右·数伏脉总起来主湿温重证，其病机核心为湿浊壅遏、热不得透。右脉数主热郁于气分，示郁热内蒸；左脉伏主湿遏营卫、邪阻不达，示湿邪闭阻。二者并见，反映湿与热合，壅遏气机，营卫不通。故临床见寒热、胸闷、腹痛、齿焦、舌白腻而厚、不食不便等症。三类病机相互关联：热郁气分", "c": "主热郁气分"}, {"id": "pc:右+数+促", "n": "右·数促脉", "o": "右·数促脉总起来主热盛、邪陷与气壅。数主热，促主急迫不匀，右寸候肺，故其核心为热盛壅肺、气机不畅。风温误表，邪热内陷，热盛而促数不调；热壅肺气，治节不行，则气机壅遏，脉来急促不匀。三者相互关联：热盛可致邪陷，邪陷又加重气壅，终成危候。下属数小促脉兼阴伤，数滑促", "c": "主热盛"}, {"id": "pc:右+数+大+小", "n": "右·数大小脉", "o": "右·数大小脉总起来主热、气滞血瘀、肝胃热盛与气血不足。数脉为共同特征，主热与气机急迫；右小左大或左小右大反映气血分布失衡：右小多气分不足，左大多血分壅滞，左小多肝血不足，右大多胃热壅盛。段以气滞血瘀为主，兼气血不足；段以肝胃热盛为主，兼气血不足。各类之间相互关", "c": "主热"}, {"id": "pc:右+数+大+微+缓", "n": "右·数大微缓脉", "o": "右·数大微缓脉总属内伤不足、虚中夹实之候。其脉见于右手气口，与左人迎相对，气口大于人迎即内伤饮食劳役之征。数大急者，谷气壅盛、积滞化热，或虚火内扰；微缓者，胃气未绝，尚能抗邪。三类病机相互关联：内伤饮食为根本，积滞化热为标象，虚中夹实为整体格局。故其主病以脾胃", "c": "主内伤饮食"}, {"id": "pc:右+数+大+洪+实", "n": "右·数大洪实脉", "o": "右·数大洪实脉总起来主暑热炽盛、邪壅气分，兼见痰热蒙蔽、阴阳逆乱及暑热内伏等病机。洪大数实为暑温邪热炽盛、阳明气分热实之典型脉象，正邪交争剧烈，故脉来有力。若兼模糊，则为痰热蒙蔽心包；若左右悬殊，则为阴阳逆乱；若伏暑似疟，则为暑热内伏。各类病机均以暑热炽盛为基", "c": "主暑热炽盛"}, {"id": "pc:右+数+大+洪+疾", "n": "右·数大洪疾脉", "o": "右·数大洪疾脉总属阳热亢盛之象。洪大为阳明热盛，数疾为邪热急迫，故其核心病机为实热内盛。具体而言，可因燥屎内结而见便坚黑、舌灰唇焦；可因燥火加临而致痿软，伤气伤血；可因湿温挟积而见渴喜热饮、寒热复作；亦可因肝胃同病，木乘土而脘痛经来。诸类之间，以实热为共同基础", "c": "主燥火"}, {"id": "pc:右+数+大+洪", "n": "右·数大洪脉", "o": "右·数大洪脉总属阳热亢盛之象，以洪大主阳明热盛、数主热急为核心。其具体所主病机主要有五类：一为阳明热盛，热邪上攻而见牙床肿痛、渴欲饮水；二为暑温热盛，暑热内燔气分而见壮热、面赤、汗出；三为热盛津伤，热邪耗气伤津而见口渴甚、脉芤；四为痰热内壅，滑数相兼，痰热交阻", "c": "主阳明热盛"}, {"id": "pc:右+数+大+浮", "n": "右·数大浮脉", "o": "右·数大浮脉总起来主热邪为患，以表热与气火郁勃为核心。浮主邪在肌表或气逆，大主热盛火炎，数主热，右部候脾肺，故其病机多从肌表与气分求之。若纯见浮大数，多属风热在表、卫气不宣，如壮热无汗、头胀烦疼；若兼弦象，则木旺克土、气火郁勃，虚实错杂。诸类之间，表热为邪在浅", "c": "主表热"}, {"id": "pc:右+数+大+涩+急", "n": "右·数大涩急脉", "o": "右·数大涩急脉总属内伤不足之候，以右手气口候脾胃，主饮食劳役所伤。其脉数大急涩，数主郁热，大主邪壅，急主气迫，涩主滞涩，合而示脾胃气壅、里热积滞之机。原文以人迎气口辨内外伤，右脉大于左为内伤，此脉独见于右，故非外感客邪，乃饮食不节、劳役过度致中焦壅滞、郁热内生", "c": "主内伤饮食"}, {"id": "pc:右+数+大+濡", "n": "右·数大濡脉", "o": "右·数大濡脉总起来主湿热秽浊壅盛于阳明募原、经腑同病之证。其脉象由三部分组成：濡主湿，数主热，右大主邪盛于阳明。三者相合，说明湿与热交蒸，邪势壅盛于阳明，且经邪未达、腑积未通，形成经腑同病之局。案中秽湿痹气触自口鼻，致寒热起伏、腹痛板硬、便泄似痢、腻哕恶、汗少", "c": "主湿热"}, {"id": "pc:右+数+大+空", "n": "右·数大空脉", "o": "右·数大空脉总起来主肺阴亏虚、虚热内扰，兼及阳明胃经湿热。右寸候肺，脉数而空大，数为有热，空大为阴气不足、脉道不充，故肺阴亏虚、虚热内扰是其核心病机。原文“肺虚则易招风”“阴气必虚”明示阴亏为本，虚热为标。然阳明胃经湿热薰蒸之气未清，虽以养阴为主，仍须兼理胃中", "c": "主肺阴亏虚"}, {"id": "pc:右+数+大", "n": "右·数大脉", "o": "右·数大脉总以热盛邪实为纲，数主热，大主邪盛，右脉候气分，故其核心病机为气分热盛。具体而言，右寸数大主肺热，右关数大主胃热，肺胃热壅最为常见；燥热伤肺、湿热内蕴、积热壅阻亦属热盛之变。然脉大而无力或数大无伦，则又主虚火，如阴虚火旺、虚阳上浮；若数大无力兼涩滞，", "c": "主热盛"}, {"id": "pc:右+数+大+虚", "n": "右·数大虚脉", "o": "右·数大虚脉总属虚损之候，以虚为本，以数为标。其数非实热，乃虚热或虚阳浮动；其大而无力，主劳伤气耗、中气不足；右脉候气，尤关脾胃。所主病机可归为虚热、劳伤气耗、虚阳浮越、胃阴受戕四类，彼此关联：劳伤气耗为根本，胃阴受戕则土不生金，虚热由内而生；若下元不摄，则虚", "c": "主虚热"}, {"id": "pc:右+数+大+软", "n": "右·数大软脉", "o": "右数大软脉总起来主气阴两虚、虚热内生，兼有瘀热互结之候。数大主热，软主气阴不足，故其核心病机为虚热，然虚热之中又含正虚邪实之机。原文见身大热不解、口干喜饮滚热汤、气急神倦、便泄数十次、恶露全无、腹膨鼻煽，合右脉数大而软、左脉弦紧而数，示瘀血内阻、虚阳外浮、阴伤", "c": "主虚热"}, {"id": "pc:右+数+实", "n": "右·数实脉", "o": "右·数实脉总起来主里热结聚、邪实壅盛之证，病位多在阳明胃肠。数主热，实主邪壅，右脉候气，故右数实多提示热邪与有形实邪（燥屎、食积、痰浊等）相结，腑气不通。其具体脉象可兼弦、兼滑，分别提示郁热内结、枢机不利或痰热结实。若与左脉微而无神并见，则示正虚邪实，攻下宜慎", "c": "主里热结聚"}, {"id": "pc:右+数+小+促", "n": "右·数小促脉", "o": "右·数小促脉总起来主热盛、邪陷营分与阴伤。数促为热盛急迫之象，见于暑温邪陷营分，热盛而促；若脉转涩小，则示下元阴亏，阴不化气。三类病机相互关联：热盛可致邪陷营分，热盛与邪陷又易耗伤阴液，故数促与涩小并见，反映邪陷与阴伤并见之复杂病机。", "c": "主热盛"}, {"id": "pc:右+数+小+弱", "n": "右·数小弱脉", "o": "右·数小弱脉总属虚损之候，以气血亏耗为本，虚热为标，兼夹脾虚湿郁。脉数而无力，非实热，乃阴血不足、虚火上炎；小弱散弱，为气血双亏。三者相互关联：气血亏耗则脾运不健，湿郁化热；虚热又耗气伤阴，加重亏虚。原文症见食后吐酸、结痰注胸、劳则头晕鼻衄、盗汗梦遗脚冷等，皆", "c": "主虚热"}, {"id": "pc:右+数+小", "n": "右·数小脉", "o": "右·数小脉总以‘小主虚，数主热’为纲，所主病机可归纳为虚热、肺胃阴虚、血虚火旺、暑湿郁热、邪恋正虚及胃热熏肺六类。其核心是阴血不足与邪热内扰并存，故脉形小而数。虚热类涵盖广泛，肺胃阴虚与血虚火旺分列脏腑与气血之偏；暑湿郁热与邪恋正虚侧重外邪未尽、正已受损；胃热", "c": "主虚热"}, {"id": "pc:右+数+弦+大+浮", "n": "右·数弦大浮脉", "o": "右·数弦大浮脉总起来主气火郁勃、木旺克土、虚实错杂之候。浮大弦数四象相合，浮主气逆，大主火盛，弦主郁滞与木旺，数主热，故其核心病机为气火郁勃、肝木亢盛。右脉候脾，弦大之象又直接反映木旺克土、脾土受戕。然原文更以寒来脉沉微似有似无对举，揭示同一患者脉象随寒热发作", "c": "主气火郁勃"}, {"id": "pc:右+数+弦+大", "n": "右·数弦大脉", "o": "右·数弦大脉总起来主气火郁勃、木旺克土、虚实错杂之候。数主热，弦主肝郁与气滞，大主阳化邪盛，右脉候脾，故核心病机为肝木亢盛、气火内郁，进而克伐脾土，致脾虚湿郁或阳明中虚。然原文亦揭示虚证：或下元虚怯、冲阳上逆，或心血亏、脾气弱而似数非真热。诸类之间，热与郁常相", "c": "主肝郁木旺"}, {"id": "pc:右+数+弦+实", "n": "右·数弦实脉", "o": "右·数弦实脉总起来主郁热内结、枢机不利之证。数脉主热，右实主阳明热结，左弦主少阳枢机不利，三者相合，提示热郁少阳、胆胃不和，气机上逆。原文服养阴药得效未愈，见嘈杂恍惚、胸上动气，治以苦寒清热、小柴胡汤和解枢机，脉证相应。各类病机相互关联：热郁为因，热结阳明与枢", "c": "主热"}, {"id": "pc:右+数+弦+小", "n": "右·数弦小脉", "o": "右·数弦小脉总以弦、数、小三象合参，主病机涉及肝郁、郁热、痰湿、阴虚、脾虚、肝火犯肺及疟邪等。弦主肝郁气滞，数主热，小主阴伤或湿阻。诸类之间常相互兼夹：肝郁化热则弦数并见；肝火犯肺则木火刑金；脾虚湿困则小弦带涩；阴虚火旺则小数；痰湿内盛则小弦而滑。总属本虚标实", "c": "主肝郁气滞"}, {"id": "pc:右+数+弦+弱", "n": "右·数弦弱脉", "o": "右·数弦弱脉总以右弱主脾虚中气不足，弦数主邪郁湿热，合而示土虚木乘、湿热内扰之吐泻。三类病机相互关联：土虚为本，木乘为标，湿热为邪郁之变，正虚与邪郁并存，故临床见吐痰泻利、四肢怠倦等虚实夹杂之候。", "c": "土虚木乘"}, {"id": "pc:右+数+弦+急", "n": "右·数弦急脉", "o": "右·数弦急脉总属肝火亢盛、气逆上冲、木火刑金之候。弦为肝木，数为火象，急为气逆之势，三者并见，示肝火内动，气逆上冲，木来乘金。其病机以肝火为本，气逆为标，木火刑金为果，故见鼻洪、咳嗽等症。与下属数弦洪急脉相较，彼兼洪紧，主阳热亢盛、邪结精耗；此则弦数急并见，侧", "c": "主肝火"}, {"id": "pc:右+数+弦+沉+涩", "n": "右·数弦沉涩脉", "o": "此脉总起来主血虚风动、湿痰内蕴与金水两虚三类病机。左手脉沉弦而涩数不调，突出肝血亏虚、虚风暗动；右关独缓滑，专主胃中湿痰；尺寸俱弱，则示肺肾两虚。三者虽分属不同脉位与脏腑，但相互关联：血虚风动可影响津液输布而生痰，湿痰中阻又可耗伤肺肾，金水两虚则加重肝血不足与", "c": "主血虚风动"}, {"id": "pc:右+数+弦+沉", "n": "右·数弦沉脉", "o": "右·数弦沉脉总起来主肝郁化火、湿热生痰与上盛下虚三类病机。沉为郁滞，弦主肝郁，数主化火，故首主肝郁化火；右脉滑疾，则示湿热生痰；厥阴火炎于上，上盛下耗，终致心肾两亏，故又主上盛下虚。三者相互关联：肝郁化火可灼津生痰，湿热痰浊中阻又可加重郁火，火炎于上则下耗心肾", "c": "主肝郁化火"}, {"id": "pc:右+数+弦+洪+急", "n": "右·数弦洪急脉", "o": "右·数弦洪急脉总属阳热亢盛、木火内动、邪结精耗之候。洪数主阳热有余，弦急主木火亢盛，紧主邪结，四者并见，示热盛火动、邪结于内，进而耗伤阴精，致阳精不升、阳络不固，出现失精吐红，先后天俱病。其病机以阳热为本，木火为标，邪结为兼，精血耗伤为果。诸类相互关联：阳热亢", "c": "主阳热"}, {"id": "pc:右+数+弦+浮", "n": "右·数弦浮脉", "o": "右·数弦浮脉总起来主风热外袭、风阳内动与燥伤肺津、虚实错杂之候。浮为邪在表、气逆，数为热，弦主风动与木旺郁滞，右寸独见则病位偏于上焦肺卫。三段原文所示：一为暑风新感，浮数示外邪化热、弦示风动；二为辛甘温燥致风阳内煽，左脉浮弦且数，见胁跳、胸痒、汗出、不眠；三为", "c": "主外感风热"}, {"id": "pc:右+数+弦+滑+微", "n": "右·数弦滑微脉", "o": "右·数弦滑微脉总主痰热内盛、肝风鸱张、热郁化火之病机。弦主热郁与肝风，滑主痰热，数主热盛，微则示正未大虚。三候相合，反映痰热内闭心包、肝风煽动、热势炽盛之危候。原文所载昏痉谵语、舌缩苔垢、六昼夜不交睫等症，皆由误治升散温补，致痰热胶结、风火相煽而成。脉象虽危，", "c": "主痰热"}, {"id": "pc:右+数+弦+滑+濡", "n": "右·数弦滑濡脉", "o": "右·数弦滑濡脉总起来主余温留恋、痰湿中阻与厥阳升腾三类病机。左弦数主少阳余温，兼厥阳升腾；右濡滑主痰湿阻于中焦。三者相互关联：余温留恋少阳阳明，引动厥阳升腾，而痰湿又阻于中焦，致阳明通降失司。故脉象弦数濡滑并见，反映温病后期余邪未清、痰湿内阻、肝阳升腾之复杂病", "c": "主余温留恋"}, {"id": "pc:右+数+弦+滑+紧", "n": "右·数弦滑紧脉", "o": "右·数弦滑紧脉总属温疫疠邪从内而发、化火充斥之候。其脉象复合，滑数主温疫化火、热壅三焦；弦紧主邪郁少阳、势张未透。二者相合，既示火邪炽盛蔓延内外，又示邪郁少阳不得外达，郁火相搏，有内窜心包、致神昏发痉之虞。三类病机以‘温疫化火’为根，‘邪郁少阳’为枢，‘火窜心", "c": "主温疫化火"}, {"id": "pc:右+数+弦+滑", "n": "右·数弦滑脉", "o": "右·数弦滑脉总属痰、热、风、湿、食积等邪气壅滞之象。数主热，滑主痰湿食积，弦主风、气滞或肝木乘脾，三脉相合，提示病机多端，但以痰热为核心，常兼风、湿、食积、邪滞。各段所主，或痰热阻肺，或风热痰郁，或湿热食积交阻中州，或邪滞交结，或肝阳痰火窜络，或脾虚湿壅，皆不", "c": "主痰热"}, {"id": "pc:右+数+弦+濡", "n": "右·数弦濡脉", "o": "右·数弦濡脉总起来主湿热痰浊、肝郁化火、阴血亏虚、内风煽动与温毒留恋五类病机。右濡数主湿与热合、痰湿内蕴；左弦数主肝郁化火、少阳枢机不利；数脉又主虚热，弦细为阴伤，故兼阴血亏虚；肝阳化风、冲气上升则见内风煽动；伏温时气客于少阳阳明，温毒留恋，亦见弦数濡之象。诸", "c": "主阴血亏虚"}, {"id": "pc:右+数+弦+紧", "n": "右·数弦紧脉", "o": "右·数弦紧脉总属邪郁化火、痰瘀湿热交结之候。数主热，弦紧主郁、主痛、主寒湿痰浊与瘀滞，故其病机以热为核心，兼夹郁、痰、湿、瘀。具体而言：或为湿热之邪内犯肝经、挟痰浊上升；或为肺阴内亏、郁火挟痰刑金；或为瘀血内阻、瘀热交结、正虚邪实；或为温疫疠邪化火充斥、邪郁少", "c": "主湿热痰浊"}, {"id": "pc:右+数+弦+细+滑", "n": "右·数弦细滑脉", "o": "右·数弦细滑脉总起来主肝阳化风、痰热内蕴与阴虚火旺三类病机。弦为肝阳易动，滑为烁液成痰，数为火盛，细为阴伤，四象合见，反映阴亏于下、阳亢于上、痰火窜扰的复杂格局。原文患者年五十，头晕、手足麻木挛曲、肿疼、便坚溲赤、口干舌绛、鼻衄、准头瘰磊，皆阴虚火盛、风自火出", "c": "主肝阳化风"}, {"id": "pc:右+数+弦+细+濡", "n": "右·数弦细濡脉", "o": "右·数弦细濡脉总起来主肝郁化火、脾虚湿热、阴血亏虚与痰湿内蕴。左弦细为肝郁阴伤，右濡数为脾虚有热、痰湿内蕴，数脉又主火旺。诸类相互关联：情怀抑郁致五志化火，木火刑金，灼伤阴血；木旺克土，脾虚失运，湿浊内蕴，郁而化热。故脉象弦、细、濡、数并见，反映肝郁化火、阴血", "c": "主肝郁化火"}, {"id": "pc:右+数+弦+细", "n": "右·数弦细脉", "o": "右·数弦细脉总属阴虚火旺、肝郁化火、痰热内蕴、脾虚湿滞、气液两竭与风阳上扰之候。其基本脉象为弦、细、数，弦主气郁肝旺，细主阴血亏少，数主火热内炽，三者相合，反映阴亏于下、火亢于上、气郁于中的复杂格局。若兼滑、濡，则痰湿内蕴、脾运失司；若兼虚、弱、空，则气液耗竭", "c": "主肝郁化火"}, {"id": "pc:右+数+弦+细+虚", "n": "右·数弦细虚脉", "o": "右·数弦细虚脉总属阴阳两损、虚阳上冒之候。其脉象由左弦细与右虚数复合而成：左弦细主肝肾阴虚、阳不潜藏；右虚数主脾肺气虚而虚阳浮越。二者相合，反映下焦阴亏不能上承，冲脉震动，诸脉俱逆，虚阳上冒，故见眩晕、盗汗、咳嗽气短、行走喘促等症。四类病机中，'主肝肾阴虚'与", "c": "主虚阳上冒"}, {"id": "pc:右+数+弦+细+软", "n": "右·数弦细软脉", "o": "右·数弦细软脉总起来主阴亏火郁、下焦阳衰、卫阳虚寒与阴阳不交数端。其脉弦细带数，弦为气郁，细为阴亏，数为火象，合示阴液不足而火热内郁，故虽背寒而实非真寒，乃丹溪所谓“恶寒非寒是火郁”。然右脉独弱，右候脾肾，弱为阳气不足，示下焦根柢衰微；卫阳出于下焦，根柢既衰则", "c": "主阴亏火郁"}, {"id": "pc:右+数+弦+结", "n": "右·数弦结脉", "o": "右关数弦结脉总起来主肝火内扰、营络瘀滞、血不安宁之病机。弦为肝旺，数为火动，壅结示气火郁于中焦，三者相合，反映肝经火盛、气火郁结、营络不畅的病理状态。肝火内扰，迫血妄行，加之营络先已不畅，火迫而络瘀，血不循经，故见崩漏屡发不止。此脉所主以肝火为核心，火动致瘀，", "c": "主肝火"}, {"id": "pc:右+数+弦+缓+和", "n": "右·数弦缓和脉", "o": "右·数弦缓和脉在原文中出现在进猪苓汤后，邪减痢减、唇肿齿垢消退之际，右脉由弦数转为缓和，故其总病机以邪退向愈为主，属佳兆。然须合参左脉：左脉细小无神，主真阴不足；关部带弦，主肝木偏旺。真阴亏虚不能涵养肝木，肝木顺乘土中，则见不思谷、干呕恶心。因此本脉所主，一为", "c": "主邪减向愈"}, {"id": "pc:右+数+弦+缓", "n": "右·数弦缓脉", "o": "右·数弦缓脉总起来主邪正相争、肝脾不调之病机。其核心为弦缓并见，弦主肝木偏旺，缓主脾土受克，故肝木犯土、运化不健是基础病机；兼数则示虚阳偏亢或余邪未清。具体而言，若脉由弦数转为缓和，为邪退向愈之佳兆；若弦缓兼数持续，则主真阴不足、肝阳偏亢，甚则内风动越。各类之", "c": "主邪退向愈"}, {"id": "pc:右+数+弦", "n": "右·数弦脉", "o": "右·数弦脉总以数主热、弦主气郁与肝风为纲，所主病机涵盖热邪、肝火、气郁、痰湿、风、虚、疟等多端。数脉为热之共性，或实热、或郁热、或虚热；弦脉为气机紧张之象，或肝火、或气郁、或风动。二者相合，常示热郁气分、肝火内炽、风热相搏、痰湿蕴热、气郁化火及虚中夹热等。各段", "c": "主热"}, {"id": "pc:右+数+弦+虚+和", "n": "右·数弦虚和脉", "o": "右·数弦虚和脉总起来主肝脾不和、湿滞内蕴与积劳内伤之虚实夹杂证。其脉象以弦为肝旺脾困，涩为湿阻血少，虚数为阴血不足而余湿未清，诸象相合，反映高年积劳、中气已虚，而湿邪困阻、肝脾失调之病机。各类之间相互关联：肝脾不和为病之本，湿滞为病之标，积劳内伤则贯穿始终，虚", "c": "主肝脾不和"}, {"id": "pc:右+数+弦+虚", "n": "右·数弦虚脉", "o": "右·数弦虚脉总起来主虚实夹杂、热郁与虚损并见之候。其脉象以数、弦、虚为纲：数主热，或为余热未清，或为暑热、腑实；弦主肝木偏旺或热郁肝胆；虚主营血不足、气血未复。三类病机常相兼为患：营血亏虚则肝木失养而偏旺，肝旺又生内热，故虚弦数并见；若外感暑热或阳明腑实，则数", "c": "主营血不足"}, {"id": "pc:右+数+弦+软", "n": "右·数弦软脉", "o": "右·数弦软脉总起来主虚火、阴亏、风动与气弱数端。其脉右软左弦数，右软为正气疲惫、中气不足，左弦数为肝经虚火内动。因虚生火，火甚劫阴，阴乏生风，故见发热热不大壮、惊惕抽掣、神倦嗜卧、舌干光有白糜点等症。虚火与阴亏互为因果，火旺则阴伤，阴伤则火愈亢；阴亏又致肝风内", "c": "主虚火"}, {"id": "pc:右+数+弦+长", "n": "右·数弦长脉", "o": "右·数弦长脉总起来主气郁、热盛、气有余、痰阻及血滞。其核心病机为恚怒伤肝，肝气郁结化热，气机壅盛，横逆犯肺，金不制木，反被木侮，致气凝痰阻于胃之上脘。弦主气郁，数主热，长主有余，涩主血滞，诸脉相合，反映气、热、痰、血相互搏结的实证。各病机之间关系密切：气郁为始", "c": "主气郁"}, {"id": "pc:右+数+弱+散", "n": "右·数弱散脉", "o": "右·数弱散脉总属虚损之候，以气血亏耗为本，虚热为标。脉数而无力，非实热，乃阴血不足、虚火上炎；散弱为气血亏耗，脉道不充。右脉候脾，散弱而数又主脾虚湿郁化热，痰湿内停。三者相互关联：气血亏耗则脾失健运，湿郁化热；虚热又耗气伤阴，加重亏虚。故本脉所主病机以虚为核心", "c": "主虚热"}, {"id": "pc:右+数+微", "n": "右·数微脉", "o": "右·数微脉总起来主虚、热、邪陷三类病机，核心为虚热相兼。数主热，微主虚，右部候脾肺，故其病机多围绕正虚与热扰展开。具体而言，虚阳浮热类以阴亏阳微、虚热内扰为特点，脉见微数而按久细少力；火邪犯中类以火热内盛、渐及中焦为特点，脉见数而右关微搏；正虚邪陷类以胃气衰败", "c": "主虚阳浮热"}, {"id": "pc:右+数+急", "n": "右·数急脉", "o": "右数急脉总起来主热，但须分虚实：一为阴液亏虚、虚热内扰，如劳损咳嗽、炙甘草汤证；二为阳明伏热，如右关数急而吐血；三为胃阳弱而虚热内扰，如干血劳证；四为肝火亢盛、气逆上冲，如数弦急脉之木火刑金。各类之间，数急为热之共性，而兼脉与部位定其虚实脏腑：左脉迟软、左弦劲", "c": "主阴液亏虚"}, {"id": "pc:右+数+沉+小", "n": "右·数沉小脉", "o": "右·数沉小脉总起来主虚、热、疟邪及正虚邪退。其脉沉小数为阴血不足、虚热内扰；浮濡无力为脾肺气虚；脾部弦洪为疟邪未净；疟后脉缓弱为邪退正虚。诸类以正虚为本，虚热、气虚为虚象，疟邪为标，邪退正虚为转归，体现虚实夹杂、标本缓急之机。", "c": "主虚热"}, {"id": "pc:右+数+沉+涩", "n": "右·数沉涩脉", "o": "右·数沉涩脉总起来主血瘕瘀结、气滞血瘀与瘀久化热三类病机。沉涩为瘀血内结、脉络阻滞之核心脉象，数则因瘀久化热，故数沉涩并见提示瘀热互结。原文以左数右沉涩断为血瘕症，症见脐下块坚如铁、经水久不止夹紫黑血块、胸腹胃脘皆痛、玉户肿、手足冷，皆瘀血成形、气血壅阻之征。", "c": "主血瘕瘀结"}, {"id": "pc:右+数+沉+紧", "n": "右·数沉紧脉", "o": "右·数沉紧脉总起来主寒凝血瘀、热郁于内兼清阳下陷之复合病机。沉主里，紧主寒，数主热，三象合见，提示寒邪与瘀血互结于里，郁而化热，热不得外达；同时左脉沉细欲无，反映正气虚馁、清阳下陷。原文因产后努力致上焦清阳下陷，又兼瘀血受寒，误服干姜热药，使寒热错杂、虚实并见", "c": "主寒凝血瘀"}, {"id": "pc:右+数+沉", "n": "右·数沉脉", "o": "右·数沉脉总以'沉主里、数主热'为纲，所主病机核心为里热内结。其脉位偏右，故多关涉阳明胃与气分；沉则病位在里，数则病性属热，合而示热邪结聚于里。具体而言：右关沉数多主阳明胃热、湿热流注；右脉沉数而实主里实便结；左脉沉数则热在血分，或为血分伏热，或热伤血络而致出", "c": "主里热积滞"}, {"id": "pc:右+数+洪", "n": "右·数洪脉", "o": "右·数洪脉总以热盛为核心，洪为热盛，数为热急，右脉候肺胃气分。所主病机涵盖肺胃热盛、痰饮积热、湿热壅盛、燥火热炽、郁火痰积、阴伤火旺、气分热盛、血分热盛等。各类之间相互关联：肺胃热盛可炼液为痰，形成痰饮积热；湿热壅盛多兼痰饮；燥火热炽易伤阴津，致阴伤火旺；郁火", "c": "主肺胃热盛"}, {"id": "pc:右+数+浮+小+濡", "n": "右·数浮小濡脉", "o": "右·数浮小濡脉总起来主气阴两伤、脾肺气虚、虚热内扰与暑湿未清。其脉浮小为正气不足、脉道不充，濡为阴伤湿滞，数为虚热或暑热，右脉尤不足则脾肺气虚更著。原文病疟日久，截药伤正，致脾肺气虚、暑湿未清、气阴耗伤，故脉象虚浮而数。四类病机相互关联：气阴两伤为根本，脾肺气", "c": "主气阴两伤"}, {"id": "pc:右+数+浮+弱", "n": "右·数浮弱脉", "o": "右·数浮弱脉总属虚中夹热、上浮下虚之象。其脉浮弱数，浮为气浮于上，弱为不足，数为有热，故所主病机以虚热为核心。具体而言，上部浮弱数主上焦气浮兼热，下部弱数主下元虚而热扰，二者合示上浮下虚、虚热内扰之格局。因虚热耗伤阴血，气血不充经络，故见偏废脚弱；虚风挟痰上扰", "c": "主虚热上浮"}, {"id": "pc:右+数+浮+硬", "n": "右·数浮硬脉", "o": "右·数浮硬脉总起来主气滞、郁热、水湿三类病机，核心在于肺脾两经之气失于舒运。浮为气失舒运、病位在表，数为郁热，硬为气机壅滞不柔。气滞则水湿不化，郁久则化热，三者相互因果：气滞为始动，水湿与郁热为继发。原文以疟后肤肿为例，右寸关候肺脾，脉见浮数而硬，正是肺脾气滞", "c": "主气滞"}, {"id": "pc:右+数+浮", "n": "右·数浮脉", "o": "右·数浮脉总以“浮主表、数主热”为纲，右脉候肺、脾、阳明气分，故其病机多围绕肺卫与气分展开。一类为外感风热或温燥袭肺，邪在卫表，肺失宣降，见咳嗽、咽痒、寒热、疹点不透；一类为燥热伤肺或肺胃热盛，热灼津液，见喉痒咳不爽、大渴多饮、舌红起刺；一类为阳明风热或肠胃积", "c": "主风热表证"}, {"id": "pc:右+数+浮+虚+洪", "n": "右·数浮虚洪脉", "o": "右脉数浮虚洪（含虚小散数）总属虚实夹杂之候。浮洪数主风热外扬、邪热内扰；虚豁散小主气阴两伤、脾虚气弱；数而虚豁又主虚火内动。诸脉相合，反映劳后入房感风，正气已虚而邪热未解，形成虚、风热、虚火、疟、痰相互交织的病机格局。其中虚为本，风热为标，虚火、疟、痰为虚实夹", "c": "主虚"}, {"id": "pc:右+数+涩+小", "n": "右·数涩小脉", "o": "右·数涩小脉总起来主气郁化热与阴亏燥热两类病机，并可兼涉肝胆火郁。数主热，涩主气滞或血少，小主津亏或阴不足，合而观之，或为气机郁滞、郁而化热、津液不畅，如案中情怀抑郁、脘胀呕涎、便艰不爽；或为阴亏血少、燥热内结，如案中咳嗽日久、便难口燥、肛结肿，极易成损。若兼", "c": "主气郁化热"}, {"id": "pc:右+数+涩", "n": "右·数涩脉", "o": "右·数涩脉总起来主痰瘀内阻、营热血少、肝火亢盛与肺气不降四类病机。数主热，涩主血瘀或血少，右脉候肺脾，故其核心为热郁血滞、痰瘀交阻。四类之中，痰瘀内阻与营热血少为基本病机：痰瘀阻络则涩数并见，营热未清、血行不畅亦见涩数。肝火亢盛与肺气不降为兼涉之变：痰瘀郁久化", "c": "主痰瘀内阻"}, {"id": "pc:右+数+滑+促", "n": "右·数滑促脉", "o": "右·数滑促脉总起来主湿热、痰饮等实邪壅闭三焦，气机阻滞之证。滑主湿痰，数主热，促主壅遏，三者相合，反映邪实内盛、气机不畅。原文脉滑数而左歇右促，更兼雀啄、解索，乍看极虚，实由湿热误补，漫无出路，充斥三焦，气机壅闭，痰饮凝滞。脉来屡变，皆痰阻气机之象。面黄头汗、", "c": "主湿热壅闭"}, {"id": "pc:右+数+滑+和", "n": "右·数滑和脉", "o": "右·数滑和脉总起来主痰热、燥热、气液亏虚及肝热内炽。其核心病机为肺胃痰热与燥热留恋，兼气液亏耗、肝热内炽。右脉候肺胃，滑数较和示痰热渐化而未尽，燥热未澈；气液素亏则脉虽和而数滑，形神衰弱；左脉弦数不靖反映肝热内炽，木火易炽。诸类之间，痰热、燥热为标，气液亏虚为", "c": "主痰热"}, {"id": "pc:右+数+滑+大+洪", "n": "右·数滑大洪脉", "o": "右·数滑大洪脉总起来主痰热内壅、热盛结胸之证。洪大主阳明热盛，滑数主痰热内壅，右手候肺胃，故脉象反映热痰壅阻中上二焦。三类病机相互关联：热盛为痰热之基础，痰热交阻又致结胸，形成热、痰、结三者递进关系。原文两段均见右手洪大滑数，症见呃忒、苔腻、便秘、痰多、心下拒", "c": "主热盛"}, {"id": "pc:右+数+滑+大", "n": "右·数滑大脉", "o": "右·数滑大脉总起来主热盛、痰热、邪实结聚及上实下虚之证。数主热，滑主痰，大主邪盛，右脉候肺胃气分，故脉象多反映中上二焦痰热壅阻、阳明热盛。热盛为痰热之基础，痰热交阻又致邪实结聚，形成热、痰、结递进关系；若兼按之虚而尺甚，则示下元虚损，成上实下虚、本虚标实之候。", "c": "主热盛"}, {"id": "pc:右+数+滑+实", "n": "右·数滑实脉", "o": "右·数滑实脉总起来主痰热邪实壅盛，病位在阳明。滑主痰，数主热，实主邪壅，三者相合，提示痰热结实内结，腑气不通。原文痰虽吐出而神昏、齿燥舌干，脉右滑数实，断为阳明痰热结实未去，宜再下之。三类病机相互关联：痰热是病邪性质，邪实壅滞是病机关键，阳明里实是病位所在，共", "c": "主痰热壅盛"}, {"id": "pc:右+数+滑+小", "n": "右·数滑小脉", "o": "右·数滑小脉总起来主热、痰湿、阴伤、气郁四类病机，四者常相兼为患。数脉主热，滑脉主痰湿，小脉主阴伤或气郁，合而观之，多示阴虚火旺、痰热内蕴、气机郁结之复合病机。原文诸案或感暑热，或肺胃痰热，或产后阴伤邪恋，或半产瘀热，皆以右脉候肺胃，反映热邪与痰湿交阻，兼有阴", "c": "主热"}, {"id": "pc:右+数+滑+微", "n": "右·数滑微脉", "o": "右·数滑微脉总主痰热内阻、气逆不降、络脉痹阻及经气不布之病机。滑数相合，为痰热内盛之核心；右寸溢，示气逆不降；弦滑并见，主络痹痰凝；关尺滑数，则痰阻阳明、经气不能流通输布。微脉示正未大虚，病以邪实为主。诸类之间，痰热为病本，气逆、络痹、经气不布皆由痰热胶结、阻", "c": "主痰热"}, {"id": "pc:右+数+滑+浮", "n": "右·数滑浮脉", "o": "右·数滑浮脉总起来主痰热壅盛、邪偏表分。浮主邪在表，滑主痰，数主热，三象相合，提示痰热内蕴而邪有外透之势。本案伏暑晚发，邪从膜原外腾，酿痰化热，蒙蔽肺胃，故脉见右浮滑而数。各类病机中，浮、滑、数分别对应表邪、痰、热，而痰热壅肺是三者综合之果。痰与热互结，壅阻肺", "c": "主表邪"}, {"id": "pc:右+数+滑+濡", "n": "右·数滑濡脉", "o": "右数滑濡脉总起来主湿热逗留、脾运失权与肾阴亏虚三类病机，以湿热黏腻熏蒸为核心。右脉候脾胃，濡主湿、滑主痰湿、数主热，三象合见，说明湿浊中阻、郁而化热，困遏中焦，故见胸痞、纳少、溲短赤浑浊、苔薄腻微黄；湿热逗留募原，三焦宣化失司，则缠绵难化。原文又言肾阴亏于未病", "c": "主湿热"}, {"id": "pc:右+数+滑", "n": "右·数滑脉", "o": "右·数滑脉总属痰热为患，以滑主痰湿食积、数主热，右脉候肺脾，故病机核心为痰热壅滞。其具体所主，可归纳为痰热壅肺、痰热中阻、痰热生风、痰热壅结、痰热伤阴、痰热动血六类。痰热壅肺者，病位在上焦，肺失清肃；痰热中阻者，病位在中焦，脾胃升降失司；痰热生风者，痰热引动肝", "c": "主痰热壅肺"}, {"id": "pc:右+数+濡", "n": "右·数濡脉", "o": "右·数濡脉总起来主湿热为患，兼及郁火痰积、热伤气阴、肺胃热炽与三焦湿热。濡主湿，数主热，右脉候脾胃肺，故其核心病机为湿与热合，郁蒸中上二焦。湿热内蕴，困遏脾运，则见胸痞、便溏、溲赤；湿热蒸腐肺络，则咳脓痰腥红；湿热弥漫三焦，则咳而腹满、跗肿。若湿郁化火，积痰生", "c": "主湿热"}, {"id": "pc:右+数+短", "n": "右·数短脉", "o": "右·数短脉总以热邪内陷、气机不畅为主，兼及阴分受伤。数脉主热，短脉主气机郁滞，右脉短数并见，反映热邪内陷少阴、少阳，气机不畅，故见寒热、气喘、脘闷等症。左脉细数则示热邪耗伤阴分。三类病机相互关联：热邪内陷为因，气机不畅为果，阴分受伤为热盛伤阴之转归。临证当以清", "c": "主热邪内陷"}, {"id": "pc:右+数+空", "n": "右·数空脉", "o": "右·数空脉总起来主肺阴亏虚、虚热内扰，兼及肺损络伤。右寸候肺，脉数主热，空为阴气不足、脉道不充，故肺阴亏虚为本，虚热为标。虚热灼肺，损伤肺络，则见咳呛痰血，形成肺损络伤之候。三类病机以肺阴亏虚为核心，虚热内扰为继发，肺损络伤为发展，层层相因，脉证相合，示肺脏已", "c": "主肺阴亏虚"}, {"id": "pc:右+数+紧", "n": "右·数紧脉", "o": "右·数紧脉总属外邪客表、正邪交争之候。紧主寒、主邪束，数主热、主正邪相争，二者相合，核心病机为寒邪外感或阳邪郁表。原文以“紧数”并见辨为寒邪外感，又驳斥仅凭右脉大主饮食之说，强调数脉左右皆可现，反映邪正交争的全身性反应。其下属数弦紧脉兼夹郁、痰、湿、瘀，数沉紧", "c": "主寒邪外感"}, {"id": "pc:右+数+细+大", "n": "右·数细大脉", "o": "右·数细大脉总起来主「阳明有余、少阴不足」之热证，核心在数主热、右大主阳明实、左细主少阴虚三端。数脉示热邪内蕴，右大示阳明络热有余而上攻，左细示少阴阴分亏虚而不济，三者合观，实为阳旺阴亏、上实下虚之候。原文以牙龈不肿而痛、右股痹痛属阳明络热非寒，正赖此脉断之：", "c": "主热"}, {"id": "pc:右+数+细+微+小", "n": "右·数细微小脉", "o": "右·数细微小脉总起来主阴伤、火郁、气壅三类病机，三者相互关联。脉细为阴亏，数为火郁，微小为气机不畅，合而示肺胃阴伤、虚火内郁、气火上壅之候。原文以右脉细小微数为征，说明喉中燥痒咳呛、痰黏难出、如有物阻，日发数次，由气上壅、火郁于脑门、清肃之令不降所致。阴伤是基", "c": "主阴伤"}, {"id": "pc:右+数+细+微+弱", "n": "右·数细微弱脉", "o": "右·数细微弱脉总起来主阴伤热炽、气衰与郁滞三类病机。其核心为火热劫烁肺胃、阴津大伤，故脉细数而微弱；细数主阴伤热炽，弱主气衰，弦主郁。三者相互关联：火热炽盛则伤阴耗气，阴伤气衰则气机不运而郁，郁又化热，形成虚实夹杂之局。原文以右脉细数微弱为阴伤热炽兼气衰之据，", "c": "主阴伤热炽"}, {"id": "pc:右+数+细+微", "n": "右·数细微脉", "o": "右·数细微脉总起来主气血两虚、脾肺气虚、虚热内扰与气郁不行四类病机，核心为虚。脉细为阴血不足，微为阳气衰微，数主虚热，右弱则脾肺之气尤亏。患者瘦弱久病，气血亏耗，脾肺气虚，运化无力，故饮食不进、走气疼痛；气虚不运则气机郁滞，发为胀痛抽痛；阴血不足、阳气衰微则虚", "c": "主气血两虚"}, {"id": "pc:右+数+细+沉", "n": "右·数细沉脉", "o": "右·数细沉脉总属阴血精液亏耗、虚热内扰之象。沉细为阴血不足，数为虚热内扰，合而主精虚劳伤。其病机可分五类：阴血亏耗为基，虚热内扰为标，进而胃阴败坏、肝火升腾，脾运失权，终致精虚劳伤。各段原文均围绕阴精亏虚、虚火内扰展开，侧重胃阴败、肝火亢、脾运衰之危候，则分左", "c": "主阴血亏耗"}, {"id": "pc:右+数+细+滑+小", "n": "右·数细滑小脉", "o": "右寸数细滑小脉总起来主肺脏病变，以伏火挟痰为核心，兼见阴伤气结。数脉主伏火，细脉主阴伤，滑脉主痰，小脉示气机郁结。四者相合，反映肺阴不足、伏火内炽、痰浊内蕴、气机郁结的复合病机。原文以右寸候肺，结合悲思、纳减、睡醒特甚等症，断为伏火挟痰，并指出惊恐可致气结成痹", "c": "主伏火"}, {"id": "pc:右+数+细", "n": "右·数细脉", "o": "右·数细脉总以“细为阴血不足，数为虚热内扰”为纲，所主病机可归纳为阴虚内热、精虚劳伤、血虚火旺、暑湿痰热、热陷动风、虚阳上攻、脾虚积热七类。其中阴虚、精虚、血虚三证以正虚为本，细数并见示阴精营血亏耗而虚火内生，病位有肝肾、肺脾、心肝之异；暑湿痰热与脾虚积热则虚", "c": "主阴虚内热"}, {"id": "pc:右+数+细+虚+小", "n": "右·数细虚小脉", "o": "右·数细虚小脉总属血虚劳伤之候。其脉以细、虚、小为主，示脉道不充、气血亏少；数脉为血虚不能配阳，虚热内扰；兼见芤涩，则血虚而滞，痹阻不行。原文分述左寸细数心血不生、左关细数肝血不荣、右脉细数脾虚血少、右脉芤涩阳明血结，皆围绕血虚展开。四类病机中，血虚为本，虚热", "c": "主血虚"}, {"id": "pc:右+数+细+虚+弱", "n": "右·数细虚弱脉", "o": "右·数细虚弱脉总起来主肾虚及脾肾亏损，以虚为本，细数虚弱为阴血不足、虚火内扰之象，迟软微弱为阳气亏虚、鼓动无力之征。其病机核心在肾中阴阳水火失调：左尺细数主真阴不足、虚火妄动；右尺迟软主命门火衰；两尺微弱则阴阳俱虚。劳瘵日久，足三阴亏损，虚热无火，火土太旺金水", "c": "主肾阴虚火旺"}, {"id": "pc:右+数+细+软", "n": "右·数细软脉", "o": "右·数细软脉总起来主虚火内扰、脾肾不足及三焦同病。其脉细软为虚，数为火象，合示阴液亏虚而虚火内生。虚火非上扰即下迫：上扰则耳鸣响闷，下迫则关门不固、梦泄；上热下热必及于中，致胃不能容、脾不能运，消化迟缓、大便不畅。右脉候脾肾，细软尤显虚象，故又主脾肾两虚，运化", "c": "主虚火"}, {"id": "pc:右+数+缓", "n": "右·数缓脉", "o": "右·数缓脉总起来主湿热郁阻、胃热渐退及气血未旺之病机。数脉主热，缓脉主湿，右部候气，故右数缓多示气分湿热郁滞，或胃热渐退而余邪未清。若兼左弦劲，则又反映肝郁血滞、气血未旺、八脉不和。各类之间相互关联：湿热痹阻为邪实之候，胃热渐退为邪衰之象，气血未旺为正虚之征，", "c": "主湿热痹阻"}, {"id": "pe:右+数", "n": "右·数脉", "o": "右数脉总以热为核心，右脉候肺、脾、阳明气分，数主热，故其病机多围绕肺胃气分展开。具体而言，右数主肺热、胃热，为实热壅盛之常见；若数而无力或兼细，则主虚热，为阴血不足、虚火内扰；兼滑、弦、糊等，则主痰热、湿热、气分热结；兼弦劲，则主肝火刑金。各类之间相互关联：实", "c": "主肺热"}, {"id": "pc:右+数+虚+小+散", "n": "右·数虚小散脉", "o": "右·数虚小散脉总起来主正气虚损、虚热内扰之证。其脉数主热，虚小散主气阴两伤、正气耗散。从原文看，患者劳后入房感风，正气已虚而邪热内扰，症见自汗、寒少热多、头眩耳鸣、四肢懒倦、手足麻、便溏、疟母、梦遗、呕吐多痰，皆脾虚气弱、虚火内动之象。各类病机相互关联：虚为根", "c": "主虚"}, {"id": "pc:右+数+虚+散", "n": "右·数虚散脉", "o": "右·数虚散脉总起来主正气虚损、虚热内扰之证。其脉数主热，虚散主正气耗散、气血不足。从原文看，患者年近六十，面色苍白，耳聋日久，溃脓不止，屡服祛风去热逐痰燥剂，更伤气血，故右脉虚散而数。然汪氏虑其乘舆远来脉未定，来早脉稍敛不及五至，说明数非实热，乃虚而失守、脉无", "c": "主虚热"}, {"id": "pc:右+数+虚", "n": "右·数虚脉", "o": "右·数虚脉总以虚为本、数为标，主正气亏虚而兼虚热内扰。其虚或为气阴两伤，或为脾胃虚弱，或为营液内耗，或为气血俱虚；其数则示虚热、余热或营热。各段所主虽异，然皆不离'虚数'二字：虚在气分则右脉虚，虚在营血则左脉数；虚在脾胃则右脉虚数，虚在肝肾则左脉虚数。虚热相合", "c": "主虚热"}, {"id": "pc:右+数+软", "n": "右·数软脉", "o": "右·数软脉总起来主气弱有热、营卫不和、湿热交蒸及阴损胃虚。其脉右候脾肾，软为正气不足、中气疲惫，数为有热之象，合示虚热内生、气阴两伤。所主诸类中，气弱有热为其根本，正虚则营卫失调而寒热往来；气弱运化失职，湿与热合则交蒸互郁；热久劫阴，阴损及胃，则舌糜、胃气不复", "c": "主气弱有热"}, {"id": "pc:右+数+迟", "n": "右·数迟脉", "o": "右·数迟脉在此段以数促为主，兼见涩小。总起来主暑温邪热深陷营分，热盛与阴伤并见。数促主热盛邪陷，涩小主下元阴亏。三者相互关联：邪热内陷则耗伤阴液，阴亏又致气化不利，故脉象由数促转涩小，反映邪陷与阴伤并存之病机。", "c": "主热盛"}, {"id": "pc:右+数+长", "n": "右·数长脉", "o": "右数长脉总起来主气分有余、热盛、气结痰凝及血热妄行。其核心病机为气机壅盛，郁而化热，热蒸痰凝，气血壅结。数主热，长主有余，右候气分，故气分热盛、气机郁滞为其根本。气有余则壅滞，热盛则灼津为痰，痰气交阻则结瘿；热迫血溢则衄。诸类病机相互关联，气有余为始动因素，热", "c": "主气有余"}, {"id": "pc:右+沉+伏", "n": "右·沉伏脉", "o": "右沉伏脉总主病机为邪阻气闭、阳气不达，或肾虚火不归元。其类别包括肾虚火浮、气闭、痰格、热积内伏及瘀血。肾虚火浮属虚，因尺脉沉伏、脉微无力，虚火浮游；气闭、痰格、热积内伏、瘀血属实，因邪阻脉道，气血不畅，脉沉伏不起。实者多兼滑大、弦数等象，虚者多兼微细。沉伏一脉", "c": "主肾虚火浮"}, {"id": "pc:右+沉+实", "n": "右·沉实脉", "o": "右·沉实脉总起来主里实邪结，病位多在脾胃、肠胃。沉为在里，实为邪盛，右部候脾胃，故其核心病机是里有形实邪壅积，包括宿垢内滞、暑湿壅积、肠胃实热及痰饮内结。四类之间以“邪实内结”为共同基础：宿垢与实热偏于胃肠燥结，暑湿偏于湿浊壅遏，痰饮偏于津液凝滞，然皆因实邪阻", "c": "主里实积滞"}, {"id": "pc:右+沉+小", "n": "右·沉小脉", "o": "右·沉小脉总以正虚为本，尤以脾胃气虚、中气不足为核心。沉主里、小主虚，右脉候脾肺，故凡右沉小者，多示脾阳不振、运化失职，或胃土久伤、中气大虚。在此基础上，常兼见他部脉象而现兼夹之机：兼左虚大或左关虚弦者，为肝木乘土、肝气内变；兼弦大者，为阳明积热内恋而木来乘土", "c": "主脾虚气滞"}, {"id": "pc:右+沉+弱+缓", "n": "右·沉弱缓脉", "o": "右·沉弱缓脉总属虚候，主气血亏虚、阳气不足。其沉弱缓者，为气虚阳弱，中气不运；浮软无力者，为血虚不充，脉道失盈；而脉变动无常、按之不应指者，乃气血俱虚、正气不守之极。三者相互关联：气虚则阳弱，阳弱则运化无力，气血生化不足；血虚则脉道不充，气失所附；久则气血两虚", "c": "主气虚阳弱"}, {"id": "pc:右+沉+弱", "n": "右·沉弱脉", "o": "右·沉弱脉总属虚候，以正气不足为核心，涵盖气虚、血虚、阳虚、脾虚肝侮及下虚阴伤等病机。沉弱无力，右手主气，故首主气虚；气虚日久，阳失温煦，则为阳虚；血虚脉道不充，亦见沉弱；脾虚气弱，肝木乘之，则见脾虚肝侮；沉取极弱，又主下焦阴伤。诸类相互关联：气虚则阳弱，阳弱", "c": "主血虚"}, {"id": "pc:右+沉+微", "n": "右·沉微脉", "o": "右·沉微脉总属阳气衰微、中气大虚之候，其病机核心为正气不能鼓动脉道。三则原文分别示阳衰寒战、中气大虚、气机阻塞：前者因阳气不能温煦而寒战，中者因脾肾气脱而中气大虚，后者因痧气壅滞而气机不宣。三者虽表现不同，然皆以沉微为共同脉象，反映阳气虚衰或气机内闭、不能外达", "c": "主阳衰寒战"}, {"id": "pc:右+沉+浮+小", "n": "右·沉浮小脉", "o": "右·沉浮小脉总以正虚邪恋为纲。脉小为正气已伤之共性，浮沉分邪之所在：左浮主风邪在表未解，右沉主脾肺气滞水停。三者相互关联：风邪外袭为始因，肺失宣降、脾失运化致气水交阻，而脉小示正气先亏，不能驱邪外出，形成正虚邪恋之局。故其病机可归纳为风邪外袭、脾肺气滞水停、正", "c": "主风邪外袭"}, {"id": "pc:右+沉+浮", "n": "右·沉浮脉", "o": "右·沉浮脉总起来主风邪外袭、肝胃郁热及阴阳气血失调。其脉浮者，主风邪在表，如风水初起；沉而弦硬滑实者，主肝胃郁热内蕴；而左右浮沉之变，又可辨阴阳气血之动与胎孕男女。诸类之间，风邪外袭为始因，可致胃中浸热；肝胃郁热则脉见弦硬滑实；阴阳气血之辨则统摄左右浮沉之机。", "c": "主风水"}, {"id": "pc:右+沉+涩", "n": "右·沉涩脉", "o": "右·沉涩脉总起来主血瘀、气滞、湿痰、虚损及瘀热五类病机。沉主里、主气郁，涩主血行滞涩，右脉候脾肺，故病位多在里、在脾胃。诸类之中，血瘀为核心，气滞为始动因素，气不行则血不畅，瘀血内结又可致湿痰壅阻、阴血亏虚；瘀久则化热，故兼数则成瘀热互结。虚损与湿痰多因正虚邪", "c": "主血瘀"}, {"id": "pc:右+沉+濡", "n": "右·沉濡脉", "o": "右沉濡脉总起来主湿浊内蕴、脾阳不运、气弱液耗、脾虚湿滞及气虚阳弱等病机。沉主里、主气机郁滞，濡主湿、主虚、主气弱液耗，故沉濡相合，多反映里虚夹湿、气弱液耗之候。四段中，或见湿浊困脾之疟疾，或见气痹液耗之关格，或见脾虚湿滞之积证，或见气虚阳弱之大气下陷，皆以右脉", "c": "主湿浊困脾"}, {"id": "pc:右+沉+紧", "n": "右·沉紧脉", "o": "右·沉紧脉总属里寒实证，以寒邪内侵、气机凝滞为核心。沉主里，紧主寒主痛，右脉候脾胃，故其病机多围绕中焦寒凝展开。具体而言，或寒与食积并结，或气郁食滞，或寒凝阳虚，或寒瘀互结郁而化热，或寒湿内伏。各类之间以寒邪为共同基础，但因兼邪不同（食、气、瘀、湿）及体质差异", "c": "主寒积中焦"}, {"id": "pc:右+沉+缓", "n": "右·沉缓脉", "o": "右·沉缓脉总属里虚寒湿之候。沉主里、缓主湿，右脉候脾，故其病机核心为阳气不足、中气亏虚，运化失司，水湿内停。若兼滑，则湿聚成痰饮，阴浊内盛；若无力，则中气馁弱，气血生化不足。三者相互关联：阳虚则湿滞，湿滞则生痰，中虚则湿愈不化。故右·沉缓脉所主，以虚寒为本，湿", "c": "主阳虚湿滞"}, {"id": "pe:右+沉", "n": "右·沉脉", "o": "右·沉脉总以'沉主里'为纲，所主病机可归为里热实结、气郁痰饮、虚陷不足、瘀血阻隔、寒痰痼结五类。沉脉位偏右，多关涉脾胃气分与肺气壅滞，故里热多结于阳明胃，痰饮食积多郁于中焦。诸类之间常相互转化：气郁痰饮久可化热而成里热实结；阳虚气陷可致气血亏虚、寒痰痼结；瘀血", "c": "主里热实结"}, {"id": "pc:右+沉+迟", "n": "右·沉迟脉", "o": "右·沉迟脉总起来主里寒、阳虚、脏寒，并可兼见寒凝肺闭与寒食积滞。沉主里、迟主寒，故其核心病机为寒邪在里、阳气不运。右脉候脾胃，右关沉迟多主寒中太阴、寒食内停；右寸沉迟则主肺受寒凝；若六脉沉迟微细无力，则属阳气衰微、真火不足，为虚寒之重候。各段所论，或偏寒湿内郁", "c": "主里寒"}, {"id": "pc:右+沉+长", "n": "右·沉长脉", "o": "右·沉长脉总起来主热盛与瘀热在里。右长主气分热盛，左沉主血分瘀滞，二者合见，示热邪由气分陷入血分，与血相结而成瘀热。其核心病机为瘀热在里，可致神气忽清忽乱如狂、舌痿饮冷、心烦热等症。三类病机中，热盛为因，血瘀为果，瘀热互结为总括，彼此关联：气分热盛不解，乘血室", "c": "主热盛"}, {"id": "pc:右+洪+实", "n": "右·洪实脉", "o": "右·洪实脉总起来主热盛邪实之病机，以阳明腑实为核心，兼涉热盛迫血、热盛气壅及伏气化热等。洪脉主热盛，实脉主邪结，二者相合，反映热邪深入于里，正气未衰，正邪交争剧烈。各段原文多围绕阳明热结、肝胆热盛、热迫血行、气壅上攻等展开，其病机本质均为热邪亢盛、邪实内结。各", "c": "主热盛"}, {"id": "pc:右+洪+紧", "n": "右·洪紧脉", "o": "右洪紧脉在此案中总主实火与邪结相合为患。洪为火盛，紧为邪结，二象并见，说明阳热亢盛而邪气壅结不解，属实证、热证。具体而言，火盛可炼液成痰，痰热上壅则成痰厥；邪结于局部则肿疼，结于经络则气血不通。原文又以左脉候肝，左部洪紧而断为肝火炽盛，提示洪紧可随部位不同而分", "c": "主火盛"}, {"id": "pc:右+洪+缓", "n": "右·洪缓脉", "o": "右·洪缓脉总以气虚为核心病机，尤主脾胃气虚、虚阳外浮。洪脉虽似有余，然无力则属不足，缓脉失神亦为虚象。此脉非实热，乃中气虚弱、鼓动无力，虚阳浮越于外所致。其类有三：一主气虚，二主虚阳外浮，三主脾胃不足，三者相互关联，皆因脾胃虚弱、中气不足，进而虚阳外浮，形成似", "c": "主气虚"}, {"id": "pe:右+洪", "n": "右·洪脉", "o": "右·洪脉总以热盛为核心，右部候肺胃气分，洪为阳盛火炎之象。所主病机涵盖肺胃热盛、痰饮积热、燥热伤肺、虚火上浮、血分热盛、阳明热盛及肺火衄血等类。其中肺胃热盛为基本病机，热盛可炼液成痰，形成痰饮积热；燥热伤肺多因秋燥灼津，右寸洪劲；虚火上浮则洪而无力或右寸独洪，", "c": "主肺胃热盛"}, {"id": "pc:右+洪+长", "n": "右·洪长脉", "o": "右洪长脉总属热盛邪实之象，主要反映阳明气分热炽。洪为热盛，长为气机亢奋，右部候肺与阳明，故右洪长多主阳明热盛。其具体病机包括：积酒生热、阳明实热、阳明疟疾，以及热盛伤阴。诸类之间以“热盛”为核心，酒热、疟热、阳明实热皆属热邪亢盛的不同来源或表现，而热盛日久必耗", "c": "主酒热内蕴"}, {"id": "pc:右+浮+小", "n": "右·浮小脉", "o": "右浮小脉总以正虚为纲，或气血两虚，或营卫两虚，或脾肺气弱，皆示正气不足、脉道不充。浮小无力，非实邪壅盛，乃虚而失守。若兼邪气，则成正虚邪恋之局，如相火挟外邪上炎；若虚阳躁动，则脉见虚散而数，似热非热。各类病机相互关联：气血两虚为基础，营卫两虚、脾肺气弱为具体表", "c": "主气血两虚"}, {"id": "pc:右+浮+小+芤", "n": "右·浮小芤脉", "o": "右·浮小芤脉总起来主气血并亏，尤以血虚为主。其脉象浮小芤，浮小示气血不足，芤为血少，右脉虚大无力则偏于气亏。原文见于新产之后，气血两亏，清窍失养而头痛。各类病机中，血虚与气亏是基础，气血并亏是二者相合的结果，三者相互关联，共同反映产后气血耗伤、脉道不充的病理状", "c": "主血虚"}, {"id": "pc:右+浮+弱", "n": "右·浮弱脉", "o": "右·浮弱脉总属虚证，以阳气虚为核心，兼涉血虚与表邪。浮为气浮于外，弱为正气不足，故见热或恶寒者，首责阳气虚，治宜补气；若浮弱兼数且发热而痛，则示邪在表，宜散之；若浮弱而热见于午前，或兼涩象，则又主血虚，宜补血。三类病机相互关联：阳气虚可致虚阳外浮而现浮弱，血虚", "c": "主阳气虚"}, {"id": "pc:右+浮+微", "n": "右·浮微脉", "o": "右浮微脉总属阳气虚浮、气血大虚之候。其脉浮而微，似有似无，按之不足，非外感表证，乃内伤虚损、阳气不能内守而外越所致。所主病机以阳气外脱为核心，兼见气血大虚与脾阳衰败。三者相互关联：忧劳、灸后气泄伤阳，阳气虚极则浮越外脱；阳损及气，气不生血，故气血大虚；中阳不足", "c": "主阳气外脱"}, {"id": "pc:右+浮+洪+结", "n": "右·浮洪结脉", "o": "右寸浮洪结脉，总起来主上焦热郁、气滞血瘀兼气血两伤之复合病机。浮洪为热郁于上，结为气滞血瘀，此二者反映邪实一面；余部沉细而软则为气血两伤，反映正虚一面。原文病案中，壮年患鼻齄，本多酒伤湿热，又久服苦寒驱风败血之剂，致‘虚其虚’之误：苦寒伤气耗血，风药燥胜伤血，", "c": "主热郁于上"}, {"id": "pc:右+浮+洪", "n": "右·浮洪脉", "o": "右·浮洪脉总起来主热盛，但具体病机有在气、在血、在经、在脏之异。浮为阳为表，洪为热盛，故其基本病机为热邪亢盛。然结合部位与兼脉，右脉浮洪多主上焦气分热盛，如咳痰吐血、阳明热未清；左脉浮洪则主血分肝经风火痰热，或心火炎、水亏火旺。若兼湿邪，则阳为湿遏，湿与热合，", "c": "主痰热"}, {"id": "pc:右+浮+涩+短", "n": "右·浮涩短脉", "o": "右·浮涩短脉总起来主虚、气滞、血瘀及脏气失调。浮为虚阳外浮或邪在表，涩主血少、血瘀、气滞，短主气损、气郁。原文以「有诸内者形诸外」为纲，强调色脉相参，脉随脏气变动而主不同病机。浮涩短脉提示脏气不足、气血虚少，兼有气机短缩与血行滞涩，甚则脏气失调。诸类之间相互关", "c": "主虚"}, {"id": "pc:右+浮+涩", "n": "右·浮涩脉", "o": "右浮涩脉总起来主虚损、气滞、津亏、脾困、热郁五类病机，其核心在于浮与涩相合所反映的正虚邪郁、气机不畅之态。浮为气机外达或虚阳外浮，涩为津血未充、脉道不利，故浮涩并见多示正气已伤而邪未尽去、气行不畅而津血不充。右关候脾胃，浮涩见于右关，则偏主脾土自困、津液未复，", "c": "主虚损"}, {"id": "pc:右+浮+濡", "n": "右·浮濡脉", "o": "右·浮濡脉总以气虚湿滞为基本病机，浮主气虚外浮或邪在表，濡主湿、主气虚。其具体所主，可归纳为三类：一为脾胃阳虚、湿浊不化，如案5、21、108；二为脾肺气虚，如案15085、15100、15174；三为气阴两伤，如案6、15076。此外，浮濡亦可见于外感暑湿袭", "c": "主气阴两伤"}, {"id": "pc:右+浮+空", "n": "右·浮空脉", "o": "右·浮空脉总属气虚，以浮为气浮、空为虚为纲。其病机核心是正气不足，尤以肺、脾、心、肝胆、肾诸脏气弱为具体表现，因六部脉虚各有所主。气虚则清阳不升，故主眩晕，并伴气短乏力。三类病机相互关联：气虚是根本，诸脏气弱是气虚在不同部位的体现，眩晕是气虚上荣不足的结果。脉", "c": "主气虚"}, {"id": "pc:右+浮+紧", "n": "右·浮紧脉", "o": "右浮紧脉总主外感寒邪为病，以浮主表、紧主寒，右脉候气分及肺胃，故其病机核心为寒邪束表、气分受寒。细分之，或寒伤营卫，或寒湿在表，或寒邪闭结，或表寒兼内伤痰食。诸类皆以浮紧为共同脉象，因兼脉与部位不同而病机有异：右寸浮紧多寒邪客肺，右关浮紧多肺胃寒邪或寒湿伤气，", "c": "主外感风寒"}, {"id": "pc:右+浮+缓", "n": "右·浮缓脉", "o": "右浮缓脉总以风、湿为患，兼涉脾土不足。浮主表、主风，缓主风、主湿，右脉候气主脾，故其病机核心为风邪外袭与湿邪内侵，二者常相合为病。风邪在表则卫表不和，见寒热、头疼；风湿困脾则运化失司，见不欲食、腹胀、便血；风邪犯胃则胃气上逆，见呕痛。若脾土素虚，则风湿更易交浸", "c": "主风邪在表"}, {"id": "pe:右+浮", "n": "右·浮脉", "o": "右浮脉总以浮主表、主风为纲，右脉候肺、脾、阳明气分，故其病机多围绕肺卫与气分展开。归纳其要：一为外感风邪或风热、风寒、风湿客表，脉多浮而兼数、紧、濡；二为风水或湿郁三焦，浮而兼弦滑；三为虚阳外浮，浮而无力或不敛，主气虚、阳虚、气阴两伤；四为三阳合病，浮弦实并见", "c": "主表感风"}, {"id": "pc:右+浮+芤", "n": "右·浮芤脉", "o": "右浮芤脉总起来主阴血亏虚、阳气外浮，并常与肝阳上亢并见。其脉象浮而芤，浮示阳气外浮，芤为血少，皆不任重按，一息六至，提示阴血不足、虚阳外越。原文见昏睡、发热、怔忡、便闭溺少，乃阴虚阳亢、热扰心神之候。三类病机中，阴血亏虚是基础，阳气外浮是阴不敛阳的结果，肝阳上", "c": "主阴血亏虚"}, {"id": "pc:右+浮+虚+缓", "n": "右·浮虚缓脉", "o": "右·浮虚缓脉总主阳气虚衰，尤以脾阳不足为核心。浮为阳气外浮，虚为鼓动无力，缓为阳气弛缓，三者相合，揭示阳虚气弱之本质。其具体病机可分三类：一为全身性阳虚，因过汗亡阳，失于温煦，见足冷恶寒；二为气虚，元气不足，形体失养，见消瘦倦卧；三为脾胃阳虚，中焦运化无力，虽", "c": "主阳虚"}, {"id": "pc:右+浮+虚", "n": "右·浮虚脉", "o": "右·浮虚脉总主气虚不固，以脾肺气虚为核心，兼及血虚、卫虚、土虚木乘。浮为气浮于外，虚为鼓动无力，故诸段皆见气不内守、正气不足之象。其类可分：气虚、脾肺虚、血虚、卫虚风动、土虚木乘。气虚为总纲，脾肺虚为病位所在，血虚为气不摄血之果，卫虚风动为表气不固之变，土虚木", "c": "主气虚"}, {"id": "pc:右+浮+软", "n": "右·浮软脉", "o": "右·浮软脉总属虚证，以气虚、血虚为基础，常兼湿盛。浮为气不内守，软为气弱不充，故主气虚；气虚日久，血亦不充，则主血虚。气虚运化失职，湿邪内滞，故又主湿盛。若阴亏阳浮，虚火上升，则见浮软而左弦大，主阴虚火旺。若胃气受伤，津液亏耗，则右浮软无力，主胃气受伤。诸类之", "c": "主气虚"}, {"id": "pc:右+涩+伏", "n": "右·涩伏脉", "o": "右·涩伏脉总属虚候，以五脏虚损为核心病机。其脉举指或滑，按之则沉小微弱短涩，反映虚阳浮于外而根本不足，故主脏虚、阳虚外浮及气衰三类。脏虚为总纲，涵盖肺脾肾等右部所候之脏；阳虚外浮为虚阳不敛之变；气衰则由脏虚所致，见肠鸣、足冷、食不入、语声破散等症。三者相互关联", "c": "主脏虚"}, {"id": "pc:右+涩+坚", "n": "右·涩坚脉", "o": "右涩坚脉总起来主脾虚血少、中焦气滞及劳伤中气虚。右涩为脾虚血少、中焦气滞，坚为气机壅滞，合之则中焦气困。原文虽言阴虚起见，但脉左坚右涩，右涩坚突出中焦为急，症见冲年形瘦、腹胀食减便溏、失血后日加孱弱，故断为劳伤中气虚。三类病机相互关联：脾虚血少与中焦气滞并存，", "c": "主脾虚血少"}, {"id": "pc:右+涩+小", "n": "右·涩小脉", "o": "右·涩小脉总起来主本虚标实、虚实夹杂之病机。涩主气滞血少，小主津亏阳微，右部候肺脾肾，故其病机涉及气、血、津、阳之虚，以及痰、热、郁之实。具体可分为四类：痰热阻肺者，因肝火挟痰蒸肺，气阴耗伤；阴亏邪陷者，暑温深陷营分，下元阴亏；气郁化热者，气机郁滞，郁而化热，", "c": "主痰热阻肺"}, {"id": "pc:右+涩+弱", "n": "右·涩弱脉", "o": "右·涩弱脉总起来主阴血亏耗、热在里及本虚标实之候。其基本病机为阴血不足，脉道不充，故见涩弱；若兼数象，则示热邪内伏，形成热在里而阴已伤之局。进一步，右涩弱与左弦涩并见，则反映本虚标实、气机升降失司：肺气虚而宣发无力，肝血郁而木失条达，金不制木，木反乘金，致咳嗽", "c": "主阴血亏耗"}, {"id": "pc:右+涩+濡", "n": "右·涩濡脉", "o": "右·涩濡脉总属脾虚湿滞、气血不足、土虚木乘之候。濡为脾虚湿停，涩为营血亏少、气机不畅，二者合见，反映脾胃虚弱、湿滞血少、气机升降失常的复杂病机。其核心在脾：脾阳不运则湿滞内生（濡），化源不足则营血亏虚（涩），土虚则木乘（弦）。四类病机中，脾虚湿滞为根本，气血亏", "c": "主脾虚湿滞"}, {"id": "pc:右+涩+短", "n": "右·涩短脉", "o": "右·涩短脉总起来主虚、气滞、血瘀及脏气失调。短主气损、气郁，涩主血少、血瘀、气滞，右寸候肺，故右寸短涩首先反映肺气不足、气机短缩；关虚小滑、尺举数按不足、左寸浮数、关虚弦、尺濡耎，合而审之为“水少于火，阴阳犹有未平”，即肾水亏而虚火动、肝阴亏虚。诸类之间以虚为", "c": "主肺气不足"}, {"id": "pc:右+涩+结", "n": "右·涩结脉", "o": "右·涩结脉总起来主气血郁滞、虚中夹实之病机。其脉象以涩示血少行滞，以结示气滞血瘀、脉气不续，合而反映气血结滞不通；若兼弦小，则又见肝郁脾弱、木郁土衰之象。原文论噎膈为神思之病，因七情内伤、名利酒色困扰，致五脏空虚、气无所主，食不能进，故其病机既见气血瘀滞之实，", "c": "主气血瘀滞"}, {"id": "pc:右+涩+缓", "n": "右·涩缓脉", "o": "右·涩缓脉总以湿滞、气虚、血少、郁滞、虚衰为五大病机。缓主湿、主气虚，涩主血少、主气滞，二者相合，多示湿邪内蕴、气血不足、气机郁滞之候。其病位重心在脾胃，涉及肝、肾。湿滞可致气机壅塞，气虚则运化无力而生湿，血少则脉道不充而涩，郁滞则气血不畅，久病则脾肾虚衰。诸", "c": "主湿滞"}, {"id": "pe:右+涩", "n": "右·涩脉", "o": "右涩脉总起来主气血滞涩、脉道不利之候，其病机涵盖血虚、气滞、血瘀、虚寒、痰湿、郁热及正虚邪恋等多类。涩为脉道不利，或由阴血亏少，或由气机郁滞，或由瘀血内停，或由痰湿壅阻，或由阳虚寒凝，或由热邪壅遏，皆可使气血运行不畅而见涩脉。各证之间常相互兼夹，如血虚气滞、瘀", "c": "主血虚"}, {"id": "pc:右+涩+芤", "n": "右·涩芤脉", "o": "右·涩芤脉总主血分虚滞之病机，以血虚为本，血瘀、血结为标，并可累及气营。芤为血虚脉道不充，涩为血少而滞，二者并见，提示血虚兼瘀。所主四类：血虚、血瘀、血结、气营并病，彼此关联。血虚则脉道空而芤，血少则行涩而滞；虚滞相因，久则血瘀，瘀结于阳明或阴分则为血结；血病", "c": "主血结"}, {"id": "pc:右+涩+软", "n": "右·涩软脉", "o": "右·涩软脉总起来主本虚标实之候，以正虚为本，气滞、湿滞为标。其脉象涩而软，软为虚，涩为滞，故所主病机主要包括气机郁滞、本元亏虚及湿滞内停三类。气滞多因邪阻，如伏暑晚发，气机不畅；本元亏虚则因久病或积劳伤阳，气血不足；湿滞则因脾肾阳虚，运化失职，水湿内停。三者相", "c": "主气滞"}, {"id": "pc:右+滑+动", "n": "右·滑动脉", "o": "右·滑动脉总以痰为核心病机，右关候脾胃，滑主痰湿，故其主病多归痰积、痰饮宿滞、痰热动火、痰走经络，并可兼见本虚标实。诸类之间以痰为纽带：痰积中焦则滑见于右关，兼宿滞则泄后脉仍滑；痰郁化火则滑而兼数，灼液成痰、火动风生；痰浊不化则走窜经络，致筋脉动惕；若久病正虚", "c": "主痰饮宿滞"}, {"id": "pc:右+滑+坚", "n": "右·滑坚脉", "o": "右·滑坚脉总属痰浊胶固、壅塞气机之候。其脉象滑而坚凝，几乎搏指，滑为痰象，坚凝为痰结，见于右寸关，知顽痰结于肺胃之管。肺为清道，胃为浊道，两道为痰所壅，故见喘咳、晕绝等症。此脉所主病机以痰结为核心，进而导致壅塞、喘咳，三者相互关联：痰结为病本，壅塞为病势，喘咳", "c": "主痰结"}, {"id": "pc:右+滑+大+沉+浮+涩+小", "n": "右·滑大沉浮涩小脉", "o": "此段总论色脉相参之理，非专论一脉之主病。其核心在「有诸内者形诸外」，故右之滑大沉浮涩小诸脉，总起来主五脏气机之变动与色脉相应之逆顺。滑大沉浮涩小各随脏气而现，非固定主一病；喘而坚、长而左右弹、上坚而大等，则示邪客气壅之具体病机。三类关系：脏气变动为总纲，色脉逆", "c": "主脏气变动"}, {"id": "pc:右+滑+大+洪", "n": "右·滑大洪脉", "o": "右·滑大洪脉总起来主痰火有余、热盛邪实之证。其脉象洪主热盛，滑主痰，大主邪实，右手候肺胃，故反映痰火壅盛于中上二焦。三类病机相互关联：热盛为痰火之基础，痰火交阻又致邪实壅盛，形成热、痰、实三者递进关系。原文见鼻衄、颈侧之疬，皆由痰火循经上扰所致。下属数滑大洪脉", "c": "主痰火"}, {"id": "pc:右+滑+大+涩", "n": "右·滑大涩脉", "o": "右滑大涩脉总起来主虚实夹杂之证，以痰火壅于中上焦、血少血瘀、下元虚惫、脾弱为主要病机。滑大主痰火实邪，涩主血少或血瘀，弱主下元虚，右关滑大兼脾弱。诸类之间相互关联：吐血后阴血亏耗而致血少血瘀，下元虚惫；脾弱运化失司，痰火内生，壅于中上焦；痰火与血虚、脾弱、下元", "c": "主痰火"}, {"id": "pc:右+滑+大", "n": "右·滑大脉", "o": "右滑大脉总以痰、热、实邪壅盛为核心病机。滑主痰湿、痰热、食积，大主邪气有余，右部候肺、脾、胃，故其病位多在中上焦。具体而言，滑大有力多主痰热壅盛或邪实内结；右关滑大常主食积、痰饮、胃热；右寸滑大主痰热壅肺；兼数则热盛，兼弦急则风热郁遏。若与虚象并见，如左细弱、", "c": "主痰湿内蕴"}, {"id": "pc:右+滑+大+虚", "n": "右·滑大虚脉", "o": "右·滑大虚脉总起来主痰热内蕴、虚火上炎、津液受伤。滑主痰，大主热，右脉候肺胃，故其核心病机为肺胃痰热未化，气机不流布，津液不行；然原文冠以‘虚火’，说明热非实火，乃虚火挟痰熏蒸胃口，故见口燥舌干欲饮，甚则口糜。三类病机相互关联：痰热是基础，虚火是痰热所化之变，", "c": "主痰热"}, {"id": "pc:右+滑+实", "n": "右·滑实脉", "o": "右·滑实脉总起来主痰、热、实邪壅盛于里，病位偏重肺胃。滑主痰饮，实主邪结，右部候肺胃，故其病机核心为痰热结实、气机壅滞。具体可分四类：痰热壅盛于肺胃，见咳嗽痰腥、脉滑大搏指；里实内结，见便燥苔黄、土太过；气滞痰凝，见口噤不语、痰饮食积；胃热上炎，见肠胃热、风束", "c": "主痰热壅盛"}, {"id": "pc:右+滑+小+濡", "n": "右·滑小濡脉", "o": "右·滑小濡脉总起来主湿痰内阻、正虚湿滞、痰火未净之病机。滑主痰，濡主湿，小主正虚，三脉相合，提示湿痰中阻而正气已伤、余邪未清之候。各段原文均见胸闷纳少、苔腻、神识渐清而精衰视异等症，反映湿痰、痰火与正虚并存。其中滑濡偏于湿痰留恋，小脉偏于阴分本亏、精衰正伤，滑", "c": "主湿痰"}, {"id": "pc:右+滑+小", "n": "右·滑小脉", "o": "右·滑小脉总起来主血热、虚热、痰凝气滞、痰湿内蕴等病机。滑脉主痰、主热，小脉主营血不足或正虚，合而观之，多示热与痰湿相兼、正气已伤之候。各段原文或见血热妄行兼外感，或见虚热内浮，或见风寒闭肺痰凝气滞，或见胃不和痰湿内蕴，皆以右脉候肺胃气分。四类病机中，血热与虚", "c": "主血热"}, {"id": "pc:右+滑+弱", "n": "右·滑弱脉", "o": "右·滑弱脉总起来主虚实夹杂之证，以正气不足为本，痰湿内蕴为标。弱脉主气血亏虚，尤以脾肺气虚为主；滑脉主痰湿内滞，可因部位不同而表现为痰热壅肺或湿滞脾胃。左脉浮滑侧重痰热壅肺，右脉弱而滑侧重脾虚湿滞。三类病机相互关联：正气不足则痰湿易生，痰湿内蕴又进一步耗伤气血", "c": "主痰热壅肺"}, {"id": "pc:右+滑+微+濡", "n": "右·滑微濡脉", "o": "右·滑微濡脉总主湿浊痰热为患。濡脉主湿，滑脉主痰，微滑示痰湿内蕴，三者相合，反映湿浊痰热交阻之病机。原文见'积湿蒸热，面目发黄，便溏纳少'，为湿热困脾；'左踹红肿'为湿热下注。故本脉所主以湿为核心，痰湿、湿热为变：湿邪困脾则濡，痰湿内蕴则微滑，湿热交蒸则发黄。", "c": "主湿"}, {"id": "pc:右+滑+微", "n": "右·滑微脉", "o": "右·滑微脉总以湿痰中阻、胃失和降为核心病机，兼见木亢升浮之变。右脉微滑主胃有湿痰，胃欠通降，痰湿内蕴而不甚；左关独弦为风木偏亢，因胃降不及则胆气不能下行，肝脾升有余而胆胃降不足，遂致眩晕。两类病机相互关联：痰湿中阻为病本，木亢升浮为标象，升降失调贯穿始终。微脉", "c": "主湿痰中阻"}, {"id": "pc:右+滑+沉+实", "n": "右·滑沉实脉", "o": "右关滑沉实脉，总起来主痰饮壅盛、邪实内结、气机不畅之病机。右关候脾胃，脉滑主痰饮，沉主里，实主邪实内结，三者相合，示痰浊内阻于脾胃，气机升降失司，邪实结聚于里。原文见右胁疼痛与胃脘痛交替发作，朝轻夜甚，痛时牵引背骨，胸痛彻背，食饮尚贪，知胃气未败，故用瓜蒌薤白", "c": "主痰饮"}, {"id": "pc:右+滑+沉+濡", "n": "右·滑沉濡脉", "o": "右·滑沉濡脉在古籍段落中并未单独论述其具体主病，而是置于色脉相参的总论框架下。该段核心思想是「有诸内者形诸外」，强调脉象是内脏病变的外在表现，需与五色相参以断病邪逆顺。右·滑沉濡脉由沉、濡、滑三象复合而成：沉主里，濡主虚或湿，滑主痰湿或食积，故其总病机倾向于里", "c": "主内病形外"}, {"id": "pc:右+滑+沉", "n": "右·滑沉脉", "o": "右滑沉脉总以'痰、食、气、饮'内结于里为核心病机。沉主里、滑主痰主食，右脉候气分与脾胃，故其主病多归中焦脾胃与肺气壅滞。具体而言，滑沉应痰浊、饮邪、食积、气郁，四者常相兼为患；痰食气郁久可化热，故兼数则主热结；若兼虚象或弦硬浮等，则示瘀痰阻络或风火痰交织之虚实", "c": "主痰浊"}, {"id": "pc:右+滑+洪+实", "n": "右·滑洪实脉", "o": "右·滑洪实脉总起来主热邪壅盛、里实内结之病机，尤以阳明府实为典型。洪脉主热盛，滑脉主气血涌沸，实脉主邪气实，数脉主热，四者相合，反映热邪深入于里，与燥屎相结，形成府实之证。原文见温热传里，面红气粗，舌苔白厚中心黄，大便干燥，小便短赤，脉一息五至强，皆热盛里实之", "c": "主热盛"}, {"id": "pc:右+滑+洪", "n": "右·滑洪脉", "o": "右·滑洪脉总属实证、热证，以痰热壅盛为核心病机。洪为阳盛火炎，滑为痰湿内聚，右部候肺、脾、胃，故其主病多集中在肺胃中上二焦。归纳其类：一主痰热壅盛，为最根本者，痰热可流滞血海、蒙蔽心窍、上灼清窍；二主实热积滞，洪滑有力示邪实内结，常见腑实便闭、癥块拒按；三主暑", "c": "主痰热壅盛"}, {"id": "pc:右+滑+浮", "n": "右·滑浮脉", "o": "右·滑浮脉总起来主痰湿壅肺、风邪犯表，兼及痰热内蕴、肺胃同病、脾虚湿困及正虚邪恋。浮主邪在表分或上焦，滑主痰湿内盛，右脉候肺胃，故痰湿阻肺、风邪袭表为基本病机。痰湿郁久可化热，形成痰热壅肺；肺病及胃，则肺胃同病；湿浊困脾，则脾虚湿困；若正气不足，则见正虚邪恋。", "c": "主痰湿壅肺"}, {"id": "pc:右+滑+涩", "n": "右·滑涩脉", "o": "右·滑涩脉总起来主虚实夹杂之证，以痰（湿、火）与血瘀、血少并见为核心。滑脉主痰积、痰湿、痰火及阳盛火动，属邪实一面；涩脉主血瘀、血少阴亏及脏虚，属正虚或血行不畅一面。二者相合，常见痰瘀互结、湿热壅盛、燥火内动而兼营血内枯或下元虚惫。各段所论，或偏痰积血瘀（如）", "c": "主痰积"}, {"id": "pc:右+滑+濡+散", "n": "右·滑濡散脉", "o": "右·滑濡散脉总起来主湿盛阳虚、痰湿壅中、湿热内酿。濡脉主湿盛阳虚，右滑主痰湿壅于中焦，二者相合，反映湿痰内蕴、阳气不足、湿热酿生之病机。原文以“阳虚积湿，体肥多痰，湿热内酿”概括，致大筋软短、小筋弛长而成痿躄。三类病机相互关联：阳虚生湿，湿聚成痰，痰湿郁久化热", "c": "主湿盛阳虚"}, {"id": "pc:右+滑+濡", "n": "右·滑濡脉", "o": "右·滑濡脉总起来主湿浊内蕴、脾虚湿困、湿热留恋、正虚湿恋、痰湿壅中及湿盛阳虚六类病机，以湿为核心，痰、热、虚为变。右脉候脾胃，濡主湿、滑主痰湿，故湿浊中阻、脾运失权为其基本病机；湿郁化热则成湿热留恋；湿痰壅盛则痰湿壅中；久病正伤则正虚湿恋；阳虚不能化湿则湿盛阳", "c": "主湿浊内蕴"}, {"id": "pc:右+滑+疾", "n": "右·滑疾脉", "o": "右滑疾脉总以痰湿为核心，兼夹热、虚、郁、风等不同病机。滑主痰湿，疾主热盛或气急，故单见滑疾多主痰湿化热，如积饮酿热、湿热生痰；若滑疾无力，则主气虚痰湿，脾虚不运；若兼沉弦而数，则主肝郁化火，火动痰生；若与左脉虚弦细涩并见，则主阴亏于下、痰湿阻于上，形成虚实夹杂", "c": "主痰湿化热"}, {"id": "pc:右+滑+紧", "n": "右·滑紧脉", "o": "右·滑紧脉总属寒邪与食积交阻之候，以感寒夹食、大腹疼痛为典型病机。紧脉主寒邪收引，滑脉主食积痰滞，右脉候中焦脾胃，故脉象复合反映寒凝气滞、食积内停。三类病机中，‘主寒凝’为病机之基，寒邪收引则气机不畅；‘主食积’言食滞中焦之性；‘主寒食交阻’则概括二者相合为病", "c": "主寒凝"}, {"id": "pc:右+滑+缓", "n": "右·滑缓脉", "o": "右·滑缓脉总主痰湿为患，尤以中焦脾胃为核心。滑主痰，缓主湿，右脉候肺胃，故其病机多归痰湿内蕴。具体而言，右关独缓滑者，主胃有湿痰，症见痰多、口中干腻、舌胎腻白；脉右缓滑而见喉痛漫肿、腐白不渴者，为风痰上侵肺胃；若兼迟而耎，则主痰湿内盛、胃阳不足，因胃阳素弱，水", "c": "主湿痰"}, {"id": "pc:右+滑+缓+迟", "n": "右·滑缓迟脉", "o": "右滑缓迟脉总主痰湿内盛、胃阳不足之证。其脉滑主痰，缓主湿，迟主寒，耎主虚，合而观之，以痰湿困阻中焦、胃阳素弱为核心病机。因胃阳不足，水谷不化，湿聚成痰，痰湿踞中，气机升降失司，故见缓滑迟之脉。痰湿久郁，肝木乘虚而亢，气阻血瘀，甚则温药助热，积温成热，反助风阳。", "c": "主湿盛痰聚"}, {"id": "pe:右+滑", "n": "右·滑脉", "o": "右滑脉总属痰湿内蕴，以右候肺脾，滑主痰湿食积，故其病机核心为痰湿壅滞中上二焦。痰湿可随体质与兼脉化热、化风、夹瘀、夹食，形成痰热、肝风痰、痰瘀、食积等兼夹证；亦可因阳微而饮停，或湿热交蒸。各类之间以痰湿为共同基础，兼脉（如数、弦、涩、大）提示病性转化与病位差异", "c": "主痰湿"}, {"id": "pc:右+滑+虚", "n": "右·滑虚脉", "o": "右·滑虚脉总起来主脾肾两虚、痰湿内停之病机。右脉候脾肺，虚滑为脾阳不运、湿痰内停；左脉虚弦为肾阴有亏、木失涵养。其核心在于脾虚失运，湿聚成痰，兼肾阴不足，肝木失养，属虚实夹杂之候。原文强调'素有湿痰，脾阳不运，肾阴有亏'，又因误用消痰、苦寒而致脾土日亏、腹痛不", "c": "主脾虚痰湿"}, {"id": "pc:右+滑+虚+软", "n": "右·滑虚软脉", "o": "右·滑虚软脉总起来主肺燥津伤、气阴两虚，兼风阳内动与痰嗽上逆。其脉软为气虚，滑为津液被烁，虚为阴亏，合而示肺伤于燥、治节不行，体质阴亏。原文'肺伤于燥'为病之本，燥伤肺津则治节失司，津液被烁则脉滑，气阴耗伤则脉软虚；又因辛甘温燥之品致风阳内煽，故兼左脉浮弦且数", "c": "主肺燥津伤"}, {"id": "pc:右+滑+软", "n": "右·滑软脉", "o": "右·滑软脉总起来主湿、痰、虚三端，以脾肺为中心。滑主湿盛痰凝，软主气虚阳弱，右脉候脾肺，故其病机多归脾虚失运、湿痰内蕴，或肺实痰壅、气逆不降。四段中，或纯为湿痰内蕴（案5），或脾虚湿盛水泛（案15627），或肺实痰壅兼肾虚（案2124），或虚中夹滞、肝脾不和（", "c": "主湿痰内蕴"}, {"id": "pc:右+濡+弱+缓", "n": "右·濡弱缓脉", "o": "右·濡弱缓脉总起来主脾虚湿盛，兼及气血不足与肾虚。濡脉主湿，弱脉主气虚，缓脉主脾虚，三者相合，以右脉候脾，故首要病机为脾胃气虚、湿邪内蕴。诸段原文多因误服毒药、伤食大泻或久坐劳伤，损伤脾胃，运化失职，湿浊内生，故见食少懒倦、不作肌肤、嗜卧懒语、喉中痰、小便不利", "c": "主脾虚湿盛"}, {"id": "pc:右+濡+弱", "n": "右·濡弱脉", "o": "右·濡弱脉总起来主脾胃气虚、湿邪内停，以右寸关候脾肺胃，濡主湿、弱主虚，故凡脾虚运化失职、胃阳不足、寒湿所伤者多见之。其具体病机可归为脾虚湿停、胃阳中虚、脾虚不摄血、气血两虚、肝脾两虚、木邪侮胃等类，总不离中土虚弱、湿浊内蕴，进而影响气血统摄与肝木条达。然须注", "c": "主脾虚湿停"}, {"id": "pc:右+濡+散", "n": "右·濡散脉", "o": "右·濡散脉总起来主虚损，以脾肺气虚、气阴两伤为核心，兼及湿困脾阳。濡脉本主湿盛阳虚，散脉主气散不敛，右部见濡散，多因劳倦、忧思、哭泣伤脾耗气，或湿邪困阻脾阳，致脾肺气虚、脉道不充。原文两段均见右脉濡散无力，一因素劳伤脾、湿困吐泻后气阴两伤，一因忧思伤脾、哭泣伤", "c": "主气虚"}, {"id": "pc:右+濡+空", "n": "右·濡空脉", "o": "右濡空脉总属虚实夹杂、形神两伤之候。其核心病机为肝胃络伤，而络伤之因在于情怀不舒、气郁化火，兼之肝血不足与胃气虚弱。右濡主胃气虚弱，左空主肝血不足，二者并见，示气血耗损于内，络脉失养；气郁则气滞络损，血不循经，故见右胁痛、呛痰血块。形瘦食减为脾胃虚弱之征。四类", "c": "主络伤"}, {"id": "pc:右+濡+缓", "n": "右·濡缓脉", "o": "右·濡缓脉总起来主湿滞、脾虚，并可兼见阴伤阳浮与寒湿。濡脉主湿、主阴伤，缓脉主脾虚、主阳气弛纵，右脉候脾，故首要病机为脾虚湿盛。诸段原文中，或见太阴湿淫、湿阻气化而小便不利；或见寒湿困阻、脾肾阳衰；或因误治耗阴，阳浮化风而不寐。各类之间以脾虚湿滞为核心：湿滞中", "c": "主湿滞"}, {"id": "pe:右+濡", "n": "右·濡脉", "o": "右濡脉总以气虚湿滞为纲，右部候脾肺，濡主湿、主气虚，故其核心病机为中焦气弱、湿浊内停。由此可衍生多类：脾胃虚寒者，中阳式微，脉道濡软；脾肺气虚者，土不生金，痰湿内蕴；湿痰留饮者，脾虚运化失职，饮邪上溢；肝脾不和者，脾虚湿困而肝木乘之，脉见右濡左弦；气血两虚者，", "c": "主气虚湿滞"}, {"id": "pc:右+濡+软", "n": "右·濡软脉", "o": "右濡软脉总起来主痰湿、脾虚、肾亏及营卫受阻。其核心病机为湿与虚：濡主湿，软主虚，右关候脾，故右濡软多责脾湿中阻、坤土不足；左濡则候肾亏。痰湿不运可熏蒸阳明，阻滞营卫，致寒热汗多；脾虚失统则吐红，肾亏不固则遗白。各类之间，脾虚生湿为痰湿之源，湿困又加重脾虚；脾虚", "c": "主痰湿"}, {"id": "pc:右+濡+迟", "n": "右·濡迟脉", "o": "右濡迟脉总主阳气衰微、寒湿内阻之病机。濡为气虚湿滞，迟为阳不胜阴，故其核心在于阳气不足、阴寒内盛。具体可分四类：一主阳虚，命火式微，阳陷入阴；二主寒湿，太阴少阴寒湿困阻，气化不行；三主气虚湿滞，中土受戕，清气不升；四主脾肾阳衰，八脉无气，阴寒内盛。四类相互关联", "c": "主阳虚"}, {"id": "pe:右+牢", "n": "右·牢脉", "o": "右牢脉总主中焦气机壅塞、积滞内结之病机。其形成多因气化凝郁，饮食停滞，久则入络致瘀，故牢脉所主以气滞、食积、血瘀为要。三者常相兼为患：气滞则食积不化，食积久则血瘀，瘀血又加重气滞，形成恶性循环。原文中右脉牢意伴中焦气化凝郁、饮食停滞，久病见瘀血凝滞，即示气、食", "c": "主气滞"}, {"id": "pc:右+疾+促", "n": "右·疾促脉", "o": "右·疾促脉在此案中总属阴亏阳亢、本虚标实之候。右脉虚细主阴气大亏，左脉促疾主阳气偏亢，二者并见，揭示‘阴气大亏，阳气偏亢’的核心病机。阴亏为本，阳亢为标，阳亢化火，上灼肺金则咳喘汗多，中乘脾土则便溏不食，下扰膀胱则溺痛频数。诸类病机以阴亏阳亢为枢，火烁肺金与木", "c": "主阳亢"}, {"id": "pe:右+疾", "n": "右·疾脉", "o": "右疾脉总起来主阳热亢盛、燥火内炽，兼及痰湿、气虚、阴亏等复杂病机。其核心为热盛与燥火，脉行急疾，见于右寸关，多责肺胃。因燥火伤气，故见肺热眩晕；痰湿内蕴，郁而化热，则见滑疾；若滑疾无力，又主气虚痰湿；若兼沉弦数，则主肝郁化火。此外，右疾促脉又主阴亏阳亢、本虚标", "c": "主燥火"}, {"id": "pe:右+短", "n": "右·短脉", "o": "右短脉总以气机短缩不利为核心，所主病机涉及气虚、气郁、湿郁、虚热、血瘀等多类。短脉主气损气郁，右脉候气，故右短脉首先反映正气不足或气机郁滞；气虚则脉道不充，气郁则脉道不畅，二者常相兼为病。湿郁困阻气机，虚热耗伤气阴，血瘀营络郁滞，皆可致脉道短缩。各病机之间相互", "c": "主气虚"}, {"id": "pe:右+空", "n": "右·空脉", "o": "右空脉总属虚候，以气分虚衰、不固不守为核心，脉大而中空，非实热，乃气虚外浮、中气泄越之象。所主病机可归为气虚不固、络脉空虚、虚中夹实、中虚木摇四类。气虚不固为根本，因劳伤内损、久病脾肾两亏，致营卫失序、偏寒偏热；络脉空虚为气虚不充于络，故见疼痛、肢软、舌强；虚", "c": "主络脉空虚"}, {"id": "pc:右+紧+缓", "n": "右·紧缓脉", "o": "右紧缓脉总起来主寒湿困脾、脾弱气陷，兼有湿郁化热之机。紧主寒主痛，缓主脾弱主湿，右脉紧缓并见，提示寒湿暴起，水气作泻，绕脐作痛；又因久泻伤脾，气虚下坠，湿郁化热。四类病机相互关联：寒湿为始因，脾弱为内因，疼痛为寒凝气滞之果，湿郁化热为久延之变。脉象与腹痛、泄泻", "c": "主寒湿"}, {"id": "pe:右+紧", "n": "右·紧脉", "o": "右紧脉总以寒邪为共同基础，右脉候脾胃气分，紧主寒主痛主邪结，故其病机围绕中焦寒凝展开。因兼脉与部位不同，或寒凝气滞而脘胀腹痛，或寒饮内停而咳逆不得息，或虚寒本证而见小紧、微紧、紧缓，或寒食交阻而大腹疼痛，或实热邪结而洪紧、沉紧有力，或外邪客表而数紧、浮紧。诸类", "c": "主寒凝气滞"}, {"id": "pc:右+细+促", "n": "右·细促脉", "o": "右·细促脉在此段中实指左右脉象：右脉弦大少冲和，左脉细促未静。总起来主中焦阳气不振与下焦阴不内守两类病机。右脉弦大少冲和，反映脾胃中阳不足、运化无力，故见谷进运迟、吞酸䐜胀；左脉细促未静，反映下焦阴不内守、相火不宁，故寐中欲遗精。两者相互影响：中阳不振则运化失", "c": "主中阳不振"}, {"id": "pc:右+细+大", "n": "右·细大脉", "o": "右·细大脉总起来主燥热伤阴、气分邪实与阴血亏虚三类病机。其脉象由细与大复合而成：细主阴血不足或阴分受灼，右大主气分邪实壅盛、燥热内逼。原文所载咳嗽失血、身热火胀、舌微黄等症，皆燥气内逼、肺络受损之候；治在气分则咳嗽减，继以清肝肃肺、和胃止血收功，说明右大侧重气", "c": "主燥热伤阴"}, {"id": "pc:右+细+小+弱+软", "n": "右·细小弱软脉", "o": "右·细小弱软脉总主气虚劳伤。其脉软弱细小或虚大无力，反映正气亏虚，鼓动无力。细分之：左脉细弱主肝肾气虚，右脉细软主脾肺气弱，此以部位分属脏腑。若弱而和缓，为胃气尚存，补之可生；若弱而带数，则虚热内生，补之难效。三类病机以气虚为本，虚热为变，可补与难补则据胃气与", "c": "主气虚"}, {"id": "pc:右+细+小", "n": "右·细小脉", "o": "右·细小脉总属虚象，主阴血亏虚、脾虚湿滞，并常兼邪恋、火旺等复杂病机。其基本含义为脉道不充，故主精血亏少、真阴不足；见于右部则多责脾虚，运化无力而湿滞。若久病正虚邪恋，则细小中兼弦数；若阴伤火旺，则左细小而右洪数；暑热伤阴者，细小与弦数并见；真阴不足、肝木犯土", "c": "主阴血亏虚"}, {"id": "pc:右+细+弱+缓", "n": "右·细弱缓脉", "o": "右·细弱缓脉总起来主脾虚、气血不足与湿滞。细弱为气血亏虚，缓为脾虚湿滞，右脉尤弱则脾虚尤甚。三者相互关联：脾虚为根本，脾失健运则气血生化不足，故脉细弱；脾虚不运，水湿内停，故脉缓；湿浊下流则小便白浊如油。此脉象不数不洪，非实火，故治宜甘温助脾、甘寒润燥，佐以化", "c": "主脾虚"}, {"id": "pc:右+细+弱", "n": "右·细弱脉", "o": "右·细弱脉总属虚损之象，以气血阴阳亏虚为共同基础。细分之，或主脾肾阳虚，命火式微，运化失职；或主气弱痰阻，本虚标实；或主阴亏虚风，挟痰上逆；或主血虚胃热，迫血上逆；或主肝郁脾虚，湿浊停阻。诸类之间，虚为根本，或阳虚，或阴亏，或气虚，或血虚，因虚致实，变生痰、湿", "c": "主气血阴阳亏虚"}, {"id": "pc:右+细+微+弱+迟", "n": "右·细微弱迟脉", "o": "右·细微弱迟脉在原文中作为鉴别诊断出现，其核心意义在于标示虚寒。原文通过'脉非微细迟弱'来排除虚寒，反证微细迟弱主虚寒。同时，右大主气分邪实，左伏主肝郁血滞，与微细迟弱形成对比。因此，该脉所主病机可归纳为三类：虚寒（本脉直接所主）、气分邪实（右大之鉴别）、肝郁", "c": "主气分邪实"}, {"id": "pc:右+细+微", "n": "右·细微脉", "o": "右·细微脉总起来主虚，以气虚为核心，尤重脾肺阳气不足。右脉候脾肺，细微为气血虚衰之象，故凡右细微者，多责之脾气虚衰、阳气虚馁。其具体病机可分六类：主气虚，为最基本者；主气血两虚，则阴阳俱亏；主虚寒，乃阳虚生寒；主虚阳上攻，为虚阳浮越之假热；主虚滞，因气虚不运而", "c": "主气虚"}, {"id": "pc:右+细+急", "n": "右·细急脉", "o": "右·细急脉总属肝虚火动、气逆血溢之候。细为肝血不足、脉道不充，急为肝火内动、火性劲急，二者并见，示肝体虚而肝用亢。肝火犯肺，气逆上冲，血随气溢，故见鼻衄、气逆、嚏甚。其病机以肝虚为本，火动为标，气逆血溢为变，虚、火、逆、溢四者相因，总归肝木失和、气血逆乱之机。", "c": "主肝虚火动"}, {"id": "pc:右+细+沉+涩", "n": "右·细沉涩脉", "o": "右·细沉涩脉总属阳气被湿所困、正虚邪恋之象。其脉沉主里、细主虚、涩主阳郁，合而示湿痰弥漫三焦，阳气不能旋转运行。原文以花甲命火衰、湿痰盛、复伤甘寒为背景，见发热不扬、便注下迫、汗出等症，脉右略大而混数不扬，断为‘正不胜邪’。故本脉所主病机可归为三类：湿遏阳困、", "c": "主湿遏阳困"}, {"id": "pc:右+细+沉+紧", "n": "右·细沉紧脉", "o": "右·细沉紧脉总属沉寒痼冷、脾阳不运之候。沉主里，细主虚，紧主寒主痛，三脉合见，提示寒邪深伏于里、阳气虚衰、气机凝滞。其核心病机为寒凝阳虚，因寒而痛，因虚而寒，因滞而胀。原文以胸脘刺痛、痛剧则胀、夜间更增、秋发冬甚、得温则减为特征，皆寒得温则缓、得寒则剧之象。四", "c": "主寒凝"}, {"id": "pc:右+细+沉", "n": "右·细沉脉", "o": "右脉沉细（或左脉沉细）总属里虚寒之象，沉主里、细主虚，合而示阳气不鼓、气血亏耗、阴寒内盛。其主病机可归为五类：阳虚寒盛、气血亏虚、里虚阴不足、肝郁气结、饮邪未净。诸类之间相互关联：阳虚寒盛可致气血生化不足而见气血亏虚；阴血亏耗则脉道不充，沉细更显；肝郁气滞则血", "c": "主阳虚寒盛"}, {"id": "pc:右+细+浮", "n": "右·细浮脉", "o": "右·细浮脉总起来主气血俱虚、中气不固之机。其脉浮软无力，按不应指，且变动无常，原文明言「脉不常，血气虚也」，故以虚为本。浮为气不内守、虚阳外浮，软细无力为血虚不充、中气不足。所主病机可归为三类：一为气血俱虚，二为中虚不运，三为气不内守。三者相互关联，气血虚则中", "c": "主气血虚"}, {"id": "pc:右+细+涩+空", "n": "右·细涩空脉", "o": "右·细涩空脉总起来主阴血亏虚、虚风内动。脉细主阴血不足，涩主血少，空为营阴亏虚，三者并见，反映心肾阴亏、肝木失养。阴血亏虚，不能涵养肝木，则风阳窃动，出现四肢麻木、形容不泽等症。其病机核心为阴血亏虚，虚风内动，治当乙癸同源，滋水涵木。两类病机相互关联，阴血亏虚", "c": "主阴血亏虚"}, {"id": "pc:右+细+涩", "n": "右·细涩脉", "o": "右·细涩脉总属阴血亏虚、血行不畅之候，其核心病机为阴血不足、脉道不充，涩滞不利。细主阴血亏少，涩主血少瘀滞，合而示血虚而兼瘀滞。所主病机主要有四类：一为阴血亏虚，见经停、汗多、内热及胸膺痛痹等；二为血瘀气滞，见胸膺痹痛、痰色瘀紫；三为虚火迫汗，见汗多如雨、内热", "c": "主血瘀气滞"}, {"id": "pc:右+细+涩+迟", "n": "右·细涩迟脉", "o": "右寸细涩迟脉总起来主寒、气滞与肺实。迟为寒，涩主气滞血少，细为虚，但本案因风寒郁肺、酸收太过，肺气壅塞，金实无声，故以寒凝气滞、肺实闭郁为核心。三类病机相互关联：寒邪外束导致肺气不宣，气滞则血行不畅而脉涩，肺气壅塞又加重气滞，形成金实无声之证。细脉虽示虚，但在", "c": "主寒"}, {"id": "pc:右+细+滑+弱", "n": "右·细滑弱脉", "o": "右·细滑弱脉总起来主脾虚湿滞，虚实夹杂之证。细弱脉主脾胃气虚，右脉弱更显脾虚；滑脉主湿滞内蕴。二者相合，说明病机以脾虚为本，湿滞为标。原文见面色萎黄、食少无味、大便不通、后重甚痛，前医误用承气峻下不效，反伤中气，正因脉弱非实。故本脉所主，非单纯虚证或实证，而是", "c": "主脾虚"}, {"id": "pc:右+细+滑+濡", "n": "右·细滑濡脉", "o": "右·细滑濡脉总起来主痰水内聚、阴湿弥漫、阳浮痰扰之病机。细濡为阴湿偏盛或阴津不足，右关滑专主痰水停聚。痰水聚于胸中，则阴湿弥漫于下，迫使心阳浮越于上，发为心下虚悸；或清津为阳气所炼，渐成痰浊，浊阻清位，导致昏晕不定。三类病机相互关联：痰水内聚是核心，阴湿弥漫是", "c": "主痰水内聚"}, {"id": "pc:右+细+滑", "n": "右·细滑脉", "o": "右·细滑脉总起来主痰湿内蕴、营血不足、正虚邪实及妊娠等病机。右滑主痰湿，左细主营血不足，二者并见常示正虚邪实，如心肾虚弱兼暑湿痰火；滑脉亦有妊娠之象。各类之间相互关联，痰湿与血虚可并存，正虚邪实为常见复合病机，妊娠需细辨。", "c": "主痰湿"}, {"id": "pc:右+细+濡", "n": "右·细濡脉", "o": "右·细濡脉总以虚、湿为纲，兼涉寒热、气滞、风阳。濡主湿、细主虚，右脉候脾肺，故其核心病机为脾虚湿滞、气血两虚。虚则易夹滞，湿郁可化热，故见虚中夹热；脾虚则肝木易乘，故见肝脾不和；肾虚则气化不利，湿滞下焦，故主肾虚癃闭；冲任虚寒，湿浊下坠，则见少腹坠痛。诸类之间", "c": "主脾虚湿滞"}, {"id": "pc:右+细+空", "n": "右·细空脉", "o": "右·细空脉总起来主精伤气散、阴血亏虚与邪滞气逆三类病机。脉细为阴血不足，空为气不摄固或营阴亏虚，二者并见，多示正虚之候。若兼色夺神夭、声嘶、咳汗，则属精伤于下、气不摄固之劳怯重病；若见麻痹、困倦、便溏黑，则偏于阴血亏虚、虚风内动。然虚中常夹实，右脉弦急则提示湿", "c": "主精伤气散"}, {"id": "pe:右+细", "n": "右·细脉", "o": "右·细脉总属虚象，以气血阴阳亏虚为共同基础，右脉候脾肺，故尤重脾肺气虚。细为脉道不充，主阴血亏少、气弱不充；兼数则虚热内扰，兼濡软则脾虚湿滞，兼弦则肝脾不和，兼滑数弦则正虚邪恋、痰热积滞。诸类之中，虚为根本：气虚则推动无力，血虚则脉道不充，阴虚则虚火内生，阳虚", "c": "主气虚"}, {"id": "pc:右+细+虚+小", "n": "右·细虚小脉", "o": "右·细虚小脉总属虚损之象，以脉道不充、气血亏少为共同基础。其主病机可归为三类：右部虚细耎小主脾虚气弱，为脾胃气虚、运化无力；左关沉弦小数主肝郁化火，为肝气郁结、郁火内扰；寸浮小空虚主心气不足，为心气亏虚、神不守舍。三者虽分属脾、肝、心，然相互关联：产后受惊伤神", "c": "主脾虚气弱"}, {"id": "pc:右+细+虚+涩+小", "n": "右·细虚涩小脉", "o": "右·细虚涩小脉总属虚涩之象，主阴血枯槁、阳气郁结、胃气将败、津血不充。其脉细小虚涩，细虚示阴血津液亏少，涩示血行艰涩、气机郁滞，右部又专候脾胃，故脉象集中反映脾胃气衰、阴血枯槁、阳气郁结之病机。原文以翻胃三月、粒米不存、纳食即吐、面白神瘁、便燥为主症，断为膈症", "c": "主阴血枯槁"}, {"id": "pc:右+细+虚", "n": "右·细虚脉", "o": "右·细虚脉总属正气亏虚之象，以气阴两虚、营血不足、脾胃气虚为核心，脉道不充故细而无力。虚细常兼数、弦、滑等，兼数则示虚热内扰或阴亏阳亢；兼弦则示肝木偏旺、乘犯脾土；兼滑数或洪大则示正虚而湿热、暑湿、相火等邪内蕴，形成虚实夹杂之候。各类病机相互关联：气阴亏虚为本", "c": "主气阴两虚"}, {"id": "pc:右+细+虚+软", "n": "右·细虚软脉", "o": "右·细虚软脉在此案中与左脉并见，总属虚实夹杂之候。细虚软主阴血亏虚，因产后痢久，肌消膝软，血分耗伤，脉道不充；右脉兼滑数，则主暑湿壅遏气分，伏暑为病，热邪未清。两类病机一虚一实，相互交织：阴血亏虚为本，暑湿壅遏为标，故脉象细软与滑数并现。治疗以养阴血、清暑湿并", "c": "主血虚阴亏"}, {"id": "pc:右+细+软", "n": "右·细软脉", "o": "右·细软脉总以脾虚气弱为核心病机。细为血少，软为气虚，右脉候脾肺，故细软并见主脾肺气弱、气血不足。脾虚则运化失职，湿浊内停，故主脾虚湿盛；胃气虚弱，受纳通降失司，故主胃气虚弱；脾虚不能化生气血，故主气血两虚。若兼左脉弦急，则肝木乘脾，故主肝木乘脾；若兼左关尺濡", "c": "主脾虚湿盛"}, {"id": "pc:右+细+软+迟", "n": "右·细软迟脉", "o": "右·细软迟脉总起来主脾土虚弱、阳气不运，并常兼肝木乘脾之机。细软为脾虚气血不足，迟为阳气不运，二者相合，揭示脾胃虚惫、运化失职的核心病机。在此基础上，若左脉沉小弦，则示肝阴不足、肝气偏旺，形成土被木乘之势。三类病机相互关联：脾虚与阳虚是基础，土被木乘是脾虚进一", "c": "主脾虚"}, {"id": "pc:右+细+迟", "n": "右·细迟脉", "o": "右·细迟脉总起来主寒凝气滞、中阳不足，并常参与寒热错杂之病机。迟为寒、为阳气不运，细为虚、为气血不足，右部候中焦，故脉象揭示中阳虚弱、寒湿内停，进而导致气机凝滞。原文「中脘痛连少腹，气滞寒停」即其典型表现。若与左脉弦数并见，则示寒热错杂、气机不畅。三类病机相互", "c": "主寒凝气滞"}, {"id": "pc:右+结+促", "n": "右·结促脉", "o": "右·结促脉总起来主积滞内结、气机壅阻之病机。其形成多因积热、酒热、食积等实邪内伏，导致气机不畅，脉道不利，故脉来促结不匀。从所收三段看，促结脉并非单独出现，常与沉数、洪数、滑大、沉实等脉并见，提示病性以实热积滞为主。各类之间相互关联：积热、酒热、食积为病之本，", "c": "主积热"}, {"id": "pe:右+结", "n": "右·结脉", "o": "右·结脉总起来主气机郁滞、脉道不利，其病机可归纳为气滞、饮结、积滞、痰阻及虚中夹实五类。结脉的基本特征是脉来迟缓而时有一止，主气结不续。从所收段落看，右结脉多与弦、伏、微、涩、促等脉并见，提示病性有实有虚，但以气机壅阻为核心。气滞则脉气不续，饮结支脉则气不流通", "c": "主气滞"}, {"id": "pc:右+缓+和", "n": "右·缓和脉", "o": "右·缓和脉总起来主痰火、积滞、热盛阴伤及元气欲脱四类病机。其核心在于右关脉象：滑大有力主痰火与食积，为实证、壅滞之候；左部数主热盛阴伤，为邪热耗液之象；右手鱼翔则示真元将竭、胃气衰败，属危候。四类之间，痰火与积滞常相兼为患，胶固中焦，久则化火伤阴；热盛阴伤进而", "c": "主痰火"}, {"id": "pc:右+缓+急", "n": "右·缓急脉", "o": "右缓急脉总属湿热郁蒸、气机失调之候。右缓为湿郁气分，左急为肝风内动，二者并见，反映湿浊阻遏气分、肝风内扰之病机。原文指出‘水谷酒腥湿热相并郁蒸，阻挠清气之游行’，致营卫循环失职、升降失司，故见忽热忽温、头中如裹、神识呆钝、肢节瘛痉、咳痰映红、便溏带血等症。四类", "c": "主湿热郁蒸"}, {"id": "pe:右+缓", "n": "右·缓脉", "o": "右缓脉总属湿困气分、脾胃不健之象，因右脉候气、候脾胃，缓主湿滞，故湿邪阻遏气机、脾运不健者多见右脉缓。然缓脉有常变之分：病中右缓而兼滞、兼软弱，多主湿阻、脾虚、食湿壅滞，甚则湿热入络、血虚风动；若病后右脉转缓而诸恙向安，则为胃气来复、向愈之征。诸类之间，以湿阻", "c": "主湿阻"}, {"id": "pe:右+芤", "n": "右·芤脉", "o": "右芤脉总属阴血亏虚、脉道不充之象，其核心病机为血虚失血与阴血亏耗。因失血或热盛伤津，脉道空虚，故见芤；若兼热盛，则芤而搏或洪大而数；若兼气分不足，则虚芤或虚滞；若血脱阳浮，则大芤或浮芤；若血虚兼瘀，则涩芤。各类之间以阴血亏虚为基础，或兼热盛伤津，或兼气分不足，", "c": "主血虚失血"}, {"id": "pc:右+虚+促", "n": "右·虚促脉", "o": "右·虚促脉总属本虚标实、痰热内扰之候。其脉象或见弦滑如珠，或见尺细而干，或见右大，皆提示真阴亏虚于下，痰热风阳扰于上。三类病机相互关联：阴亏火旺为发病之本，火旺搏液成痰，痰热内蕴又进一步耗伤阴液；若伏热在肺，则热壅气逆，脉见右大。故其主病以阴虚火旺、痰热内扰为", "c": "主阴亏火旺"}, {"id": "pc:右+虚+动", "n": "右·虚动脉", "o": "右·虚动脉此段所主，总为虚而阳亢、风热上扰之候。其脉右大，右部候气，大则阳气亢盛，然此大非实热壅盛之洪大，而是虚阳浮越、化风上逆之象，故原文既言“热升风动”，又强调“奇脉虚风阳动”“虚风内动”。可见其病机核心是虚与风热并存：正虚于下，阳亢化风于上，风热相煽，上", "c": "主热升风动"}, {"id": "pc:右+虚+实", "n": "右·虚实脉", "o": "右·虚实脉总以虚实夹杂、正虚邪恋为纲。其脉象或微数无伦次如虾游，或弦细芤迟，或软小濡小与滑数并见，皆提示正气亏虚而邪气内郁。所主病机主要有正虚邪陷、虚实夹杂、阴血亏虚、暑邪内郁四类。正虚邪陷为危重之候，多见于瘟疫、久病误治，脉失根本；虚实夹杂常见于痰火喘咳，气", "c": "主正虚邪陷"}, {"id": "pc:右+虚+小", "n": "右·虚小脉", "o": "右·虚小脉总属虚证，以中气不足、脾胃虚弱为核心，涉及气血阴阳亏虚及湿滞、疟母等兼夹。其脉象虚小，虚为不足，小为阴血亏少，右部候脾肺，故主中阳不振、脾虚湿滞、气血亏虚、脾土大亏。各类之间相互关联：中阳不振可致营卫失护，脾虚湿滞则运化无力，气血亏虚多因肝脾两伤，脾", "c": "主中阳不振"}, {"id": "pc:右+虚+小+软", "n": "右·虚小软脉", "o": "右·虚小软脉总属虚证，以气虚、血虚为本，兼夹湿滞与内热。其脉象虚软而小，虚为不足，软为湿滞，小为阴血亏少。从原文看，右脉浮软而大主气虚湿盛，左脉虚软而小近快主血虚有热；经水过多、白带时下、泄泻无时，则下多亡阴，血虚湿滞。诸类之间，气虚与血虚常相兼为病，湿滞与内", "c": "主气虚湿盛"}, {"id": "pc:右+虚+弱", "n": "右·虚弱脉", "o": "右·虚弱脉总以主虚为纲，尤重脾胃气虚，其脉软弱无力直接反映中气不足。然虚有部位与兼夹之异：右关大而软弱并见，主虚实夹杂；左尺虚弱细数主肾阴不足；右尺迟软主命门火衰；两尺微弱主阴阳两虚；久病见散乱解索、无神气则主正气涣散之危候。诸类皆以虚为本，或兼邪实，或分阴阳", "c": "主脾胃气虚"}, {"id": "pc:右+虚+弱+软", "n": "右·虚弱软脉", "o": "右·虚弱软脉总以主虚为纲，尤重脾胃气虚。其脉软弱无力，直接反映中气不足，故原文明言'右脉软弱为虚'。然脉象可兼见他部，如右关脉大主腑实，若与软弱并见，则示虚实夹杂之候，如疟痢并作初起，既有邪壅腑实，又见脾胃气虚。此时治法需权衡邪正，既用厚朴行气通腑，又须顾护中", "c": "主脾胃气虚"}, {"id": "pc:右+虚+微", "n": "右·虚微脉", "o": "右·虚微脉总属正虚之象，虚为不足，微为阳衰，合之则阴阳两亏、气血津液俱损。所主病机主要有三：一为阴阳两亏，多见于素体亏虚、误治伤正之危候；二为津液内亡，因热耗或误下致化源不足，脉道不充；三为寒邪内陷，正虚无力抗邪，寒邪深陷三阴。三者相互关联，总以虚为本，或兼寒", "c": "主阴阳两亏"}, {"id": "pc:右+虚+涩+小+濡", "n": "右·虚涩小濡脉", "o": "右·虚涩小濡脉总起来主气血两虚、血少行滞与脾虚湿困。虚小为气血不足，涩为血少行滞，濡为脾虚湿困，三者相合，反映气血亏虚、冲任失养，兼有脾虚湿滞之病机。原文以经行前后多少不定、缠绵不已、腰胯酸疼为候，服养阴止经剂即停，亦示阴血亏虚。诸类之间，气血两虚为本，血少行", "c": "主气血两虚"}, {"id": "pc:右+虚+涩", "n": "右·虚涩脉", "o": "右·虚涩脉总起来主虚、湿、郁、热四端，而以脾虚为本。虚涩并见，虚主气阳或阴血不足，涩主湿滞或血行不畅，故其核心病机为脾虚湿滞。若兼弦，则肝郁化热，木郁土位，成脾虚肝郁、肝脾积热之候；若兼软，则脾肾阳虚，湿浊内停，成阳虚湿停之证；若与微细并见，则气血两虚未复。诸", "c": "主脾虚湿滞"}, {"id": "pc:右+虚+涩+软", "n": "右·虚涩软脉", "o": "右·虚涩软脉总属虚损之候，以脾肾阳虚、运化失职为核心病机。虚软主阳气亏虚，涩滞主湿滞内停，二者相合，反映本虚标实之态：脾肾阳虚为本，湿浊内停为标。积劳伤阳，日久不复，则阳气式微，推动无力，故脉虚软而涩滞；脾失健运，水湿不化，则能食不能运、便溏跗肿。三类病机相互", "c": "主阳虚劳伤"}, {"id": "pc:右+虚+濡", "n": "右·虚濡脉", "o": "右·虚濡脉总起来主气阴两虚、湿邪内蕴之病机。虚脉主正气不足，或为暑热耗气，或为纵欲伤阴损阳；濡脉主湿邪黏滞，或为暑湿郁肺，或为阴阳两虚之濡软。两类病机虽一为外感暑湿伤气，一为内伤阴阳两虚，但均以虚为本、以濡为标，虚示正气亏耗，濡示湿滞或阴血不充。右部候气，右脉", "c": "主阴阳两虚"}, {"id": "pc:右+虚+空", "n": "右·虚空脉", "o": "右·虚空脉总属虚证，以气血阴阳亏虚为核心，兼及络脉空虚与命门火衰。其脉形空虚无力，非实热亢盛，乃阴血亏耗、阳气不足、脉道不充之征。所主病机主要有血虚、气虚、络脉空虚、命门火衰四类。血虚与气虚常并见，如产后去血过多、汗出不止，致气血大亏，左脉空虚、右脉小弱，虚热", "c": "主血虚"}, {"id": "pc:右+虚+缓", "n": "右·虚缓脉", "o": "右·虚缓脉总主脾虚、阳虚、气虚三类病机，三者相互关联，核心在于脾土不足。虚为鼓动无力，缓为阳气弛缓，右部候脾，故脉见虚缓，首责脾虚；脾为后天之本，气血生化之源，脾虚则气弱，故兼主气虚；气弱日久，阳气不振，故又主阳虚。原文以'六脉虚缓，土不及者'用六君子汤健脾益", "c": "主脾虚"}, {"id": "pe:右+虚", "n": "右·虚脉", "o": "右虚脉总属正虚，以气虚为核心，尤重脾肺。右寸候肺、右关候脾，故右脉虚多责脾肺气弱，运化失司。其病机大致可分六类：一为单纯气虚，见右寸关虚软无力；二为虚劳，或烦劳伤气，或情欲致损，脉大而虚；三为气阴两虚，虚大或虚数并见，多因暑热、久病耗伤气津；四为脾虚肝乘，右虚", "c": "主气虚"}, {"id": "pc:右+虚+芤", "n": "右·虚芤脉", "o": "右·虚芤脉总属气分不足、阴血亏耗之象。虚芤者，脉道不充，按之豁然，主津伤血少。其主病机有三：一为暑热伤气耗津，见右脉小弱而芤虚，烦渴喜冷饮；二为阴亏火旺，脉细数而右虚芤，见于鼻衄日久、阴气弥伤、阴火潜然之证；三为失血伤阴，因出血过多，阴血亏虚，脉道失充而现虚芤", "c": "主暑伤气分"}, {"id": "pc:右+虚+软", "n": "右·虚软脉", "o": "右·虚软脉总属虚证，以阳气虚、脾肺气虚为核心，兼见气阴两虚及虚中夹实、肝郁乘脾等变。虚软之象，虚为阳气不足或气阴亏虚，软为脉道弛缓无力，故主正虚。右脉候脾肺，虚软多责脾肺气弱，运化失司；久病及肾，则肺肾两亏；阴亏火旺，则气阴两伤。若虚中夹实，脉可兼涩、兼弦，示", "c": "主阳气虚"}, {"id": "pc:右+虚+迟", "n": "右·虚迟脉", "o": "右·虚迟脉在此段中主要反映暑温邪陷营分、热盛阴伤之病机。脉小数促主热盛邪陷，脉转涩小主下元阴亏，数促与涩小并见，提示邪热未透而阴液已伤，形成邪陷与阴伤并存的复杂局面。总起来说，此脉主热盛、阴伤、邪陷三类病机，三者相互关联：热盛为邪陷之因，阴伤为热盛之果，邪陷又", "c": "主热盛"}, {"id": "pc:右+软+和", "n": "右·软和脉", "o": "右·软和脉总起来主脾阴不足，并常与左脉濡细乏力并见而提示肝脾阴血两虚。右脉软和，右候脾，软和为脾阴亏虚之象，故主脾阴不足；左脉濡细乏力，左候肝，为肝血亏虚之征，故主肝血亏虚；二者并见，则主肝脾阴血两虚。原文以两足大指夜睡即麻属脾之隐白、肝之大敦，经事趱前甚至一", "c": "主脾阴不足"}, {"id": "pc:右+软+短", "n": "右·软短脉", "o": "右软短脉总属气虚与气郁并见，以气机不畅、营络郁滞为核心病机。软为气虚，短主气郁，右脉候气，故本脉反映正气不足而气机郁滞，营络不畅。在疹邪已透胸背的背景下，右脉软短提示气机不能畅达，营络郁滞，营热不透，故见烦渴热频、少寐、舌白、蛔厥、大便不解等症。气虚为气郁之根", "c": "主气虚"}, {"id": "pe:右+软", "n": "右·软脉", "o": "右软脉总属虚证，以正气不足为核心，尤以脾肺气虚、阳气亏虚为主。右脉候脾肺，软为脉道弛缓无力，故右软首先反映脾肺气弱、运化失司；久病及肾则阳气不足，阳虚水泛、肾关不固。若兼左脉弦细数，则肝阴不足、虚火内扰，或肝木乘脾，成肝脾不和；若兼他部洪大弦数，则正虚邪恋、虚", "c": "主气虚"}, {"id": "pc:右+软+迟", "n": "右·软迟脉", "o": "右·软迟脉总起来主虚，尤以阳虚火衰、阴血不足、脾土虚弱及阴阳两虚为核心。右尺迟软多责命门相火不足，左脉迟软则示阴血亏虚，右·细软迟脉又专主脾虚阳运不及。诸类之间相互关联：脾虚与阳虚是基础，久则阴血亦亏，终致阴阳两虚；阴虚不能制火，或阳虚不能内守，又可出现虚火浮", "c": "主阳虚火衰"}, {"id": "pe:右+迟", "n": "右·迟脉", "o": "右迟脉总以阳气衰微、阴寒内盛为基本病机。迟主阳不胜阴，右部候肺脾命门，故右迟多责中下阳衰、寒凝气滞。其具体所主，约分六类：一主阳虚寒凝，二主里寒积滞，三主气虚湿滞，四主阴血亏虚，五主热盛邪陷，六主寒热错杂。诸类之中，阳虚寒凝为根本，里寒积滞、气虚湿滞皆由此衍生", "c": "主阳虚寒凝"}, {"id": "pc:右+长+硬", "n": "右·长硬脉", "o": "右·长硬脉总起来主肝火亢盛、冲胃气逆，兼阴分亏损之病机。其脉长主气火有余，硬主亢盛，右部应肺胃与冲脉，故肝火挟冲胃之气上冲、血随气逆时，右脉多见长硬。若失血日久，真阴亏耗，火盛灼阴，则脉虽弦硬有力而兼数，此硬又为阴亏之象。要之，长硬脉以气火亢盛、升降失常为核心", "c": "主肝火冲逆"}, {"id": "pe:右+长", "n": "右·长脉", "o": "右·长脉总起来以气机有余、壅滞不散为核心，所主病机涉及气逆、积气、寒湿、阳明热及痰气交阻等多类。长脉主气有余，右部候肺与阳明，故气机上逆则呛血，气机壅滞则积气结聚，寒湿凝滞则脉长而弹指，邪在阳明则身热脉长，痰气交阻则脉滑而长。诸类之间，气机壅滞为共同基础：气逆", "c": "主气逆"}, {"id": "pe:右+革", "n": "右·革脉", "o": "右革脉总属虚寒水饮、本虚标实之候。革脉中空外急，如按鼓皮，中空主营血气虚、肺胃不足，外急主寒凝气滞、水饮壅塞。两段原文均见短气失音、喉中水鸡声、面浮色痿、心下痞硬，显系肺胃气虚，水饮内停上泛，气机壅塞。其病机以虚为本，以寒与水饮为标，形成本虚标实、攻补两难之局", "c": "主虚"}, {"id": "pp:右关", "n": "右关", "o": "右关脉总主中焦脾胃病变，其病机以脾胃为核心，涉及肝、肾等脏。归纳起来，主要分为痰湿、热、虚、肝木乘土、食积、风邪、火郁七类。痰湿与食积多因实邪壅滞，脉见滑、沉实；热与火郁多因热盛，脉见数、洪、弦数；虚证多因气血不足，脉见细软、濡弱；肝木乘土因肝旺犯脾，脉见弦；", "c": "主痰湿"}, {"id": "ps:右关+动", "n": "右关·动脉", "o": "右关动脉总主中焦脾胃痰浊壅聚、搏击不定之病机。其脉滑动如豆，滑主痰湿，动主搏击，故首主痰积中焦；痰浊不化，流窜经络，则主痰走经络；痰湿郁久化热，与湿热互结，则主湿热交阻；若兼左关弦搏，肝木气旺，则主肝气入络，气血郁结成梗；若尺寸脉俱微缓，泄痢日久，气血两亏，则", "c": "主痰走经络"}, {"id": "ps:右关+和", "n": "右关·和脉", "o": "右关脉候脾胃，其病机总以脾胃为中心，涉及肝、肾。弦主肝郁气滞，滑主痰湿内蕴，涩结主血少瘀滞，弱主脾虚劳倦，平和则胃热退而正复。诸类之间常相兼夹，如弦滑并见为肝胃不和、痰湿中阻；弦涩而结兼尺弱为肝脾气血两伤、虚中夹实。脉象变化可判断病势进退：弦象退、脉转柔和则郁", "c": "主肝郁气滞"}, {"id": "pc2:右关+大+洪", "n": "右关·大洪脉", "o": "右关大洪脉总以脾胃为本，所主病机不离虚实两端。其洪大有力或兼面赤肌热者，为心火乘脾、胃热内盛；其洪大无力或虚大者，多为脾胃久亏、胃气外浮之假象，可因虫积内扰、阳虚自汗等致虚阳不敛。原文反复以‘右关虚大无力’‘浮洪无力’‘缓而弱’对举，强调右关本脉当缓弱，洪大乃", "c": "主脾胃虚"}, {"id": "pc2:右关+大+浮", "n": "右关·大浮脉", "o": "右关大浮脉总属虚候，以脾胃气虚、阳虚为本，虚阳外浮为标。右关候脾胃，浮大无力多因中阳不足、气虚不敛，故主阳虚自汗、中气不足；若浮大无根，则为虚阳上越之危象。三类病机相互关联：中气不足日久则阳虚，阳虚不摄则虚阳上浮，总以正虚为核心，治当温补敛浮。", "c": "主阳虚"}, {"id": "ps:右关+大", "n": "右关·大脉", "o": "右关大脉总主中焦脾胃之病，以邪实壅盛为主，兼及虚实两端。其大而有力者，多主痰热、胃热、食积、腑实，如滑大主痰火，长大主胃热，沉实主食滞；其大而无力或豁大者，则主脾虚湿痰、脾虚劳伤，如虚大主脾虚不运，豁大主湿痰内壅。此外，弦大又主胆火乘脾、木旺克土。诸类之间，以", "c": "主痰热壅盛"}, {"id": "ps:右关+实", "n": "右关·实脉", "o": "右关实脉总属脾胃邪实内结之候。其脉沉实主宿垢内滞，实滑主痰饮壅盛，实大或沉数主邪实壅滞（土太过）。三者皆以右关候脾胃，实脉为邪气内盛、壅滞不通之象，或兼沉、兼滑、兼数，分别提示宿滞、痰饮、热壅等不同病邪性质。总以脾胃实证为纲，治当通降祛邪，如磨滞、涤痰、清泄等", "c": "主宿滞"}, {"id": "pc2:右关+弦+大", "n": "右关·弦大脉", "o": "右关弦大脉总起来主脾胃受病，以邪实气滞、木旺克土为核心。右关候脾胃，弦为肝胆之脉而主气机郁滞，大为邪盛之象，故弦大并见，提示邪气犯脾、气机壅滞。其病机可分三类：一为脾伤，邪盛伤脾，脾气损伤；二为木旺克土，胆火乘脾，木横犯土；三为胃病气滞，胃家受病，气机失调，水", "c": "主脾伤"}, {"id": "pc2:右关+弦+浮", "n": "右关·弦浮脉", "o": "右关浮弦脉总属脾胃气机失调、虚实夹杂之象。右关候脾胃，浮主中气外浮或风邪在表，弦主气机郁滞或风木劲急。其主病机可归为四类：脾虚气滞、风邪犯胃、阳虚自汗、寒伤少阳。脾虚气滞为本脏自病，中气不足而气机壅滞；风邪犯胃为外风乘土，风木劲急；阳虚自汗为气浮不敛，腠理不固", "c": "主脾虚气滞"}, {"id": "pc2:右关+弦+滑", "n": "右关·弦滑脉", "o": "右关弦滑脉总属中焦痰湿、肝旺乘土、湿热内蕴之象，并可累及上焦与下焦。右关候脾胃，滑主痰涎湿浊，弦主肝旺。痰湿壅聚于胃，则湿遏热蒸，发为湿热；肝木乘脾，则土衰木克；痰火相合，上蒙清窍，则舌强语謇，甚虑风痱；若肾本寒，肝挟肾邪，水聚上泛，则见胁痛发黄。诸类之间，以", "c": "主痰湿"}, {"id": "ps:右关+弦", "n": "右关·弦脉", "o": "右关弦脉总主肝木乘土、痰饮湿浊、热积火郁、气郁痛结、风邪内动及虚损不足六大类病机。右关候脾胃，弦为肝旺，故弦见于右关，首责木旺乘土、土衰失运，此为诸类之基础。在此基础上，若兼滑则痰湿内聚，兼数则热积火郁，兼紧或搏则气郁痛结，兼浮则风邪犯胃，兼细弱软涩则脾虚气血", "c": "主肝木乘土"}, {"id": "ps:右关+弱", "n": "右关·弱脉", "o": "右关·弱脉总主脾胃气虚、中气不足，以虚为本。右关候脾胃，弱脉主气虚推动无力，故凡右关弱，皆示脾胃中气虚弱，运化失职，可见不能食、肌肉削、小便不利等症。其病机有单纯中气不足者，有脾胃虚寒、元气不足者，亦有脾虚而兼他脏乘侮者。三者皆以脾胃虚弱为核心：单纯中气不足为", "c": "主中气不足"}, {"id": "pc2:右关+微+缓", "n": "右关·微缓脉", "o": "右关微缓脉总属本虚标实之候。微缓主气血两亏，为正虚之根；右关滑动主痰积、湿热壅滞中焦，为邪实之标；兼左关弦搏，肝气入络，形成痰积、湿热、肝气交阻而元气已弱之局。故其病机以虚为本，以痰、湿、热、气郁为标，攻补两难，治当择性味不猛者通化。", "c": "主气血两亏"}, {"id": "ps:右关+微", "n": "右关·微脉", "o": "右关微脉总起来主中焦脾胃病变，其病机涉及湿痰、气郁、阳复与火犯中州四类。右关候脾胃，微脉主气机不畅或阳气不足，故见微脉多与中焦功能失调相关。湿痰阻胃者，脉多微滑，因痰湿黏腻阻滞气机；气郁者，脉多微紧，因郁滞不畅；阳复者，脉见微续，为胃气渐回之佳兆；火犯中州者，", "c": "主湿痰"}, {"id": "pc2:右关+数+大", "n": "右关·数大脉", "o": "右关数大脉总以脾胃为病位，主湿热、积热与内伤不足三类病机。数主热，大主邪盛或积滞，右关候脾胃，故凡湿热内蕴、积热壅盛者，脉多见数大，治当清肠胃、通积滞。然内伤饮食劳役，脾胃受损，虚火内动，气口亦可见大而数、急大之脉，此属不足之病，虽脉似有余，实为虚象。三类之间", "c": "主湿热"}, {"id": "pc2:右关+数+弦", "n": "右关·数弦脉", "o": "右关·数弦脉总以火热郁结中焦为核心病机。右关候脾胃，弦主气郁、肝旺，数主热盛，故其主病多属火郁中焦、胃肠积热、肝热乘脾及湿热蕴结阳明。四类之间相互关联：火郁中焦可上炎为患，胃肠积热为实火内结，肝热乘脾为木火犯土，湿热蕴结则兼湿邪郁蒸。原文或单见右关弦数，或与左", "c": "主火郁中焦"}, {"id": "pc2:右关+数+滑", "n": "右关·数滑脉", "o": "右关数滑脉总属胃家实热痰湿之候。数主热，滑主痰湿，右关候脾胃，故其病机以湿热、痰实、积热三类为主。湿热者，偏于湿与热合流注经络；痰实者，偏于痰与热结聚胃家；积热者，偏于热与积滞壅塞肠胃。三者皆属实证、热证，病位在阳明胃与肠胃，可相互转化：湿郁化热则成湿热，痰热", "c": "主湿热"}, {"id": "ps:右关+数", "n": "右关·数脉", "o": "右关数脉总以主热为纲，因右关候脾胃，故其热多归于阳明胃肠。具体而言，实热壅盛者脉数有力，主热盛；湿热交蒸者脉数兼弦滑，主湿热；火郁中焦者脉数而弦搏，主火郁；积热内结者脉数大或滑数，主积热；风热外袭者脉浮数，主风热；痰热内阻者脉滑数，主痰热；而阴血亏虚、虚热内生", "c": "主热盛"}, {"id": "ps:右关+沉", "n": "右关·沉脉", "o": "右关沉脉总属里证，以脾胃为中心。沉主里，右关候脾胃，故所主病机多与脾胃相关。其兼脉不同，病性有别：沉而有力主里实热，沉滑主痰饮食积，沉实主宿垢内结，沉迟紧主寒积，沉而无力主内伤不足。各类之间，或为实邪内结，或为虚损，总不离脾胃升降失常、邪滞中焦。实者宜清降通磨", "c": "主里实热"}, {"id": "ps:右关+洪", "n": "右关·洪脉", "o": "右关洪脉总主痰热、实积、火盛、瘀血及邪盛诸病机。洪为热盛之象，滑主痰湿，数主火，大主邪盛，涩主瘀血。右关候脾胃，故洪滑多主中焦痰热壅盛、实积内结；兼数则火邪亢盛，兼涩则痰瘀互结；洪大有力则示邪气盛实、热势下迫。诸类之间以痰热为核心，实积、火盛、瘀血、邪盛皆可由", "c": "主痰热"}, {"id": "pc2:右关+浮+紧", "n": "右关·浮紧脉", "o": "右关浮紧脉总以寒邪与风邪为患，其病机可归为表寒、风寒、木克土三类。浮为邪在肌表或风邪外袭之象，紧为寒邪收引之征，故浮紧相合多主风寒表实。右关本候脾胃，若浮紧独见右关，则非单纯外感，常示风木之邪乘袭脾土，即“土受木贼”，可致吐泻等症。三类之间，表寒与风寒均属外邪", "c": "主表寒"}, {"id": "ps:右关+浮", "n": "右关·浮脉", "o": "右关浮脉总属脾胃病变，以浮为气机外达或邪在表之象。其主病机可归纳为风邪犯胃、脾虚湿盛、脾虚气滞、风热在表、津亏邪退及阳虚气浮六类。风邪与风热属外邪客表，浮而兼弦、紧、数；脾虚湿盛与气滞属内伤，浮而兼缓、弦，为土虚木贼或湿滞；津亏邪退为病后邪去津未复，浮涩而颜色", "c": "主风邪"}, {"id": "pc2:右关+滑+动", "n": "右关·滑动脉", "o": "右关滑动脉总属痰积中焦之象，滑主痰湿，动主搏击，故脉见滑动如豆，多伴舌苔黄白而腻、中脘皮肉觉厚等症。然痰积常与湿热相合，郁久化热，故又主湿热内蕴；痰阻气机，肝木失疏，左关弦搏，故兼主肝气旺而络脉结滞；病久泄痢，尺寸脉微缓，气血两亏，故又主正虚。四类病机以痰积为", "c": "主痰积"}, {"id": "pc2:右关+滑+大", "n": "右关·滑大脉", "o": "右关滑大脉总属中焦脾胃邪实有余之候，以痰、热、食积为其主要病机。滑主痰饮、食积，大主热盛、邪实，右关候脾胃，故脉象集中反映脾胃壅滞、痰热内结之实证。各类之间常相兼为患：痰与热合则为痰火，痰与食积并存则胶固难化，胃热炽盛又可迫血上冲。其病机核心为“邪实”，或痰浊", "c": "主痰"}, {"id": "pc2:右关+滑+沉", "n": "右关·滑沉脉", "o": "右关沉滑脉总属脾胃实邪内结之象。沉主里，滑主痰、食、气滞，右关候脾胃，故其病机核心为脾胃运化失司，实邪（痰浊、食积、气食相凝）内停，导致胃气不和。五类病机中，痰浊内蕴、食积内停、气食相凝、胃气不和、内伤饮食，皆围绕中焦脾胃，或为痰食互结，或为气食相凝，或为饮食", "c": "主痰浊内蕴"}, {"id": "pc2:右关+滑+洪", "n": "右关·滑洪脉", "o": "右关洪滑脉总属痰热壅盛、实邪内结之候。洪为热盛，滑为痰浊，右关候中焦脾胃，故其主病以中焦痰热为核心。四类病机相互关联：痰热壅滞中焦可致实积内结，痰热与瘀血相合则成瘀血痰积，痰火上扰心包则神昏乱语。原文八段中，或单见洪滑主痰热，或兼涩主瘀血，或兼数大主痰火扰神，", "c": "主痰热"}, {"id": "ps:右关+滑", "n": "右关·滑脉", "o": "右关滑脉总属痰湿食积为患，以中焦脾胃为核心。滑为痰湿内蕴之主脉，痰浊停聚则脉气往来流利；若兼数、兼大、兼洪，则为痰火相兼；兼沉、兼实、兼动，则主食积内停；兼弦则主饮邪或肝胃不和；兼湿热交蒸则见滑数有力。痰浊流窜经络，又可见滑动如豆。诸类之间，以痰为核心，或化火", "c": "主痰"}, {"id": "ps:右关+濡", "n": "右关·濡脉", "o": "右关濡脉总主湿、虚、痰、气逆四类病机。濡为湿象，右关候脾，故首主脾湿中阻；湿困则脾运不健，中气不足，故又主虚；湿聚不化则成痰，故兼滑主痰；痰湿中阻，气机升降失常，浊阴上逆，故主气逆。四者相互关联：湿为根本，虚为体质基础，痰为病理产物，气逆为病势演变。临证见右关", "c": "主湿"}, {"id": "ps:右关+紧", "n": "右关·紧脉", "o": "右关紧脉总主中焦气机壅滞、邪郁不通之病机。紧为有力之象，主邪气结聚，非独主寒。右关候脾胃，紧见于右关，多因气郁、食滞、寒凝或邪郁少阳，导致中焦气机不畅、升降失司。三类病机相互关联：气郁可致食滞，食滞可生阴寒，邪郁少阳亦常兼食滞，总以“郁”与“结”为关键。紧脉虽", "c": "主气郁"}, {"id": "ps:右关+细", "n": "右关·细脉", "o": "右关细脉总起来主脾胃虚弱、痰湿内滞及肝脾失调、阴阳不交等病机。右关候脾胃，细为血少、软为气虚，故右关细软无力主脾虚气弱、中气下陷；右关带滑或滑主痰湿内滞，痰水聚于胸中或湿痰阻胃。细脉常兼他部脉象：兼左关弦细为肝郁血少、肝木乘脾；兼细濡为阴津不足、阳气不布，清津", "c": "主脾虚"}, {"id": "ps:右关+缓", "n": "右关·缓脉", "o": "右关缓脉总起来主脾胃湿滞与本虚，兼涉风邪。缓为湿邪黏滞之象，右关候脾胃，故湿痰内蕴、脾虚湿盛、风邪犯胃、脾胃本虚皆可见缓脉。四类病机以湿为核心：湿痰偏实，脾虚湿盛虚实夹杂，风邪犯胃为风挟湿滞，脾胃本虚则缓而无力。其间可兼滑、浮、弦、弱等脉，提示痰、表风、木乘土", "c": "主湿痰"}, {"id": "ps:右关+虚", "n": "右关·虚脉", "o": "右关虚脉总属脾虚气弱，以中气不足为核心病机。脾主运化，虚则运化失职，水湿内停，故见湿滞；湿郁日久，可化热生虫，形成虫积；脾虚气血生化不足，则全身气虚。四类病机相互关联：脾虚为本，湿滞、虫积为标，气虚为果。临证需结合兼脉及症候，辨其虚实夹杂。", "c": "主脾虚"}, {"id": "ps:右关+软", "n": "右关·软脉", "o": "右关软脉总主脾胃虚弱，以气虚为本，兼见湿困、气陷、虚寒及肝木乘脾等变。软为气虚之象，右关候脾，故凡右关见软，首责脾土虚弱、中气不足。脾虚运化失职，水湿内停则见濡软而主脾湿；中气不足，升举无力则气陷于下；气虚及阳，温煦失职则成虚寒；脾虚易受肝木克伐，则见木乘土之", "c": "主脾湿"}, {"id": "pp:右寸", "n": "右寸", "o": "右寸脉总主肺病，其病机以肺为中心，涉及热、痰、表邪、虚损、气郁、虚阳浮越及肝木犯肺等多类。热邪壅肺则脉数洪大，痰饮内停则脉滑弦，表邪外袭则脉浮，虚损不足则脉弱软濡小空，气机郁滞则脉弦涩结，虚阳上浮则脉大而无力，肝木偏亢则脉弦。诸类之间常相兼夹，如痰热、气虚痰阻", "c": "主肺热"}, {"id": "ps:右寸+促", "n": "右寸·促脉", "o": "右寸促脉总主热盛、气机不调、温邪壅肺及误表危候。促为数中一止、脉来不匀，数主热盛，止主气机急促失调；右寸候肺，故其病位在肺。风温之邪郁于肺卫，误用温散，邪热壅肺，治节不行，则脉促数不调。热势愈盛，促数愈甚，气机愈乱，故见鼾睡、语言难出等危候。四类病机相互关联：", "c": "主误表危候"}, {"id": "pc2:右寸+大+洪", "n": "右寸·大洪脉", "o": "右寸·大洪脉总属热盛气壅之象，因右寸候肺，故多主肺系病机。其具体所主，约分六类：一为暑热壅肺，暑湿酒食搏结，熏蒸发黄；二为肺热痰壅，热灼津液为痰，甚则成痈；三为虚阳上浮，阳不潜藏，脉大而沉取滑；四为肺气虚，脉浮大无力，卫外不固；五为湿浊壅肺，湿性重浊，肺气壅滞", "c": "主暑热壅肺"}, {"id": "pc2:右寸+大+浮", "n": "右寸·大浮脉", "o": "右寸浮大脉总主肺脏病变，以肺气失于清肃、宣降失常为枢。其病机可分四类：一为燥伤肺津，气分燥而津液亏，脉浮大而喉干失音；二为风热壅肺，热邪在表在气，脉浮大而咳呛痰黄；三为肺气虚损，气不归元，脉浮大无力或重按即无；四为虚阳上越，根本空虚，脉浮大无根而喘急面肿。四类", "c": "主肺燥津亏"}, {"id": "ps:右寸+大", "n": "右寸·大脉", "o": "右寸大脉总主肺病，以邪实为主，兼有虚实两端。实者多因热、痰、燥、气逆、络痹等邪壅肺，脉见大而有力，如洪大、滑大、浮大带涩，对应肺热、痰饮、燥伤、气逆、络痹等类；虚者多因肺气虚损、虚阳浮越，脉见大而空、浮大无根，对应虚阳浮越类。各类之间常相兼为病，如痰热壅肺、燥", "c": "主肺热壅盛"}, {"id": "ps:右寸+小", "n": "右寸·小脉", "o": "右寸小脉总主痰湿、气火、虚损及脾弱。小脉为气血不足或邪阻之象，右寸候肺，肺主气，通调水道，故小脉多反映肺气不宣、痰湿内阻；又肺朝百脉，肝火犯肺、气火上升亦见小弦而数；久病肺金亏损，气阴两伤则见小涩或细数而小滑；脾为生痰之源，脾弱湿生，上贮于肺，故右寸关小脉亦主", "c": "主痰湿"}, {"id": "pc2:右寸+弦+浮", "n": "右寸·弦浮脉", "o": "右寸浮弦脉总起来主痰饮内停，兼有肺脾两虚。其核心病机为肺气虚不能通调水道，聚液为痰、积湿为饮，痰饮阻肺则咳喘有音；而痰饮生成之源又在脾虚不能散精归肺。故本脉所主以痰饮为标，以肺脾两虚为本，属本虚标实之候。三类病机相互关联：肺虚是痰饮停聚的直接原因，脾虚是生痰之", "c": "主痰饮"}, {"id": "ps:右寸+弦", "n": "右寸·弦脉", "o": "右寸弦脉总属肺病脉象，所主病机以痰饮、气郁为核心，兼及肝木犯肺、风邪外感、湿浊壅盛及虚中夹实。右寸候肺，弦为饮为郁为肝为风，故痰饮内停、气机郁滞最为常见；肝木偏旺则反侮肺金，风邪外袭则肺卫失宣，湿浊壅盛则上焦闭阻，皆可致右寸见弦。诸类之间常相互兼夹，如痰饮可兼", "c": "主痰饮"}, {"id": "ps:右寸+弱", "n": "右寸·弱脉", "o": "右寸·弱脉总起来主气虚，尤以肺气不足为核心，并涉及脾虚湿停、心脾两虚及五脏之虚。右寸候肺，弱为气衰不振，故肺气不足则气化不行、摄血无权；脾土为肺金之母，脾虚则湿停生痰，上犯于肺；肝木亢盛则乘金，右寸弱示肺虚受乘；劳心太过则心气不足，思虑伤脾则痰郁扰神；而五脏之", "c": "主气虚"}, {"id": "pc2:右寸+弱+软", "n": "右寸·弱软脉", "o": "右寸软弱脉总属肺气不足、脉道弛软之象，然所主病机非止一端。其本为气虚，肺主气，右寸候肺，软弱即气不振；气虚则血失统摄，故见崩漏；气虚则津液不布，痰火易生，故兼滑而主痰火；肺金不足，肝木易亢，弦长上鱼际而右寸软弱，则为木行乘金；下元不足，气不归根，尺弱而寸软，又", "c": "主气虚"}, {"id": "ps:右寸+微", "n": "右寸·微脉", "o": "右寸微脉总主肺气亏虚，并涉及气机失调及全身虚损。其核心病机为肺气不足，因右寸候肺，微脉主气衰，故见咳嗽、气怯等症。在此基础上，可兼见气逆不降（微而溢），或大气下陷（微如浮麻），甚则反映五脏虚损（按之微）及虚劳阴阳两亏（微兼虚软弦细）。各类之间以肺气虚为枢纽：肺", "c": "主肺气虚"}, {"id": "pc2:右寸+数+促", "n": "右寸·数促脉", "o": "右寸·数促脉总主热盛气壅、误表坏病之候。数主热，促主气机急促不匀，右寸属肺，故其核心病机为风温之邪壅肺、热盛气滞。三则原文皆载风温微感误用温散后，右寸脉促数不调，热虽渐退而脉象未和，反见促数尤甚，终致鼾睡、语言难出。可见此脉既主热盛，又主气壅，更主误表后邪热内", "c": "主热盛"}, {"id": "pc2:右寸+数+大", "n": "右寸·数大脉", "o": "右寸数大脉总以火热亢盛为基本病机，然有虚实之辨。数主热，大主邪盛，右寸候肺，故其病位多在肺，涉及肺胃、肝胆、心肾之火上炎。实者或为肺热壅盛、金被火刑，或为痰热内停、气火上逆，甚则迫血妄行；虚者则因阴分亏虚、阴不藏阳，虚火浮越于外，脉虽数大而不耐重按。诸类之间，", "c": "主热盛"}, {"id": "pc2:右寸+数+弦", "n": "右寸·数弦脉", "o": "右寸数弦脉总属肺经有热，兼肝木火旺。右寸候肺，数为火盛，弦为木旺，故其病机以热为核心，或为肺经实热壅盛，或为肝火犯肺、木火刑金，或为营液亏虚、虚火内扰。三者虽虚实不同，但均以火象为共同特征：实者多因暑热或肝郁化火，虚者多因汗多伤营、阴虚阳亢。脉象弦数并见，提示", "c": "主肺热"}, {"id": "pc2:右寸+数+洪", "n": "右寸·数洪脉", "o": "右寸洪数脉总以火热为纲，尤以肺经热壅为核心。右寸候肺，洪为火盛，数为热炽，故原文反复以'右寸洪数'诊为肺热、肺火，可致肩背痛、咳嗽、喘逆、身肿、小便不利等证。然火邪非独在肺，洪数亦为诸脏火盛之通象：他部兼见数、洪、实、大、弦，则分属心火、胃火、肝火、肾火、大肠", "c": "主肺热"}, {"id": "pc2:右寸+数+浮", "n": "右寸·数浮脉", "o": "右寸浮数脉总以肺系病变为核心，浮主表、主风，数主热，合而多主风热、燥火等外邪犯肺之实热证；然脉症合参，浮数亦可见于脾土亏损、虚阳外浮之虚火，以及湿火下注、相火不静之虚实夹杂证。各类之间，风热、燥火偏于外感实邪，虚火、湿火则涉内伤虚实。右寸候肺，故病位多在肺，但", "c": "主风热"}, {"id": "pc2:右寸+数+滑", "n": "右寸·数滑脉", "o": "右寸数滑脉总属痰热壅盛之象，因右寸候肺，故病位多在肺与中上二焦。其主病机可归为五类：一为痰热内蕴，二为暑热壅肺，三为酒积化热，四为风邪湿痰，五为虚实夹杂。前四类以邪实为主，或兼湿、兼风、兼酒积，然核心皆为热与痰交结；第五类则因正虚邪恋，滑数之中兼见濡软细小，提", "c": "主痰热"}, {"id": "ps:右寸+数", "n": "右寸·数脉", "o": "右寸数脉总主热，因右寸候肺，故其热多与肺相关。具体可分：肺经实热，见数而洪大；风热表证，见浮数；痰热内蕴，见滑数；虚热内生，见细数或空大；湿热郁蒸，见小数或濡数；气火犯肺，见弦数；热盛充斥，见促数或洪数。诸类之间，以“热”为共同基础，或兼表、兼痰、兼湿、兼虚、", "c": "主肺热"}, {"id": "ps:右寸+洪", "n": "右寸·洪脉", "o": "右寸洪脉总属热盛气壅，因右寸候肺，故以肺经实热、痰热、暑热、燥热为核心，洪而有力多实，洪滑多痰，洪数多火，洪劲多燥。其变证有二：一为虚阳上浮，脉洪大而沉取滑，非实热；二为兼见他部虚象，如左寸虚、右尺沉微，则成心肾不交。此外，洪滑兼弦可主气郁食积，洪大兼湿可主暑", "c": "主肺热"}, {"id": "pc2:右寸+浮+紧", "n": "右寸·浮紧脉", "o": "右寸浮紧脉总属外感风寒、邪束肺卫之候。右寸候肺，浮主邪在表，紧主寒邪，故其核心病机为风寒闭肺、表寒外束。四段中，或见喘咳胸闷，或见身热咳呛，或见肩背腋痛，皆因寒邪客肺、肺气失宣、经络凝滞所致；其兼关脉小滑者，为寒引痰浊；兼经水趱前，为寒郁营分。诸类均以“寒”与", "c": "主风寒闭肺"}, {"id": "ps:右寸+浮", "n": "右寸·浮脉", "o": "右寸浮脉总属肺卫气分受病，以邪在表、病位在上焦肺为基本特征。其具体所主，约分七类：风热表证、风寒闭肺、燥伤肺津、痰饮内停、虚阳外浮、气滞热郁、肺脾失运。前四类以邪实为主，浮脉随兼象不同而分风热、风寒、燥邪、痰饮；后三类以正虚或虚实夹杂为主，浮大无力、浮而不敛属", "c": "主风热表证"}, {"id": "ps:右寸+涩", "n": "右寸·涩脉", "o": "右寸涩脉总主气机郁滞、血行不畅，其病机可归纳为气滞血瘀、痰浊阻肺、肺气壅塞及虚损不足四类。右寸候肺，涩脉出现多与肺脏功能失调相关：实者因邪热、痰浊、风寒等壅阻肺气，致气滞血瘀、痰凝不通，表现为浮大带涩、弦涩或迟细而涩；虚者因久病肺金亏损、气血不足，脉道不充，表", "c": "主气滞血瘀"}, {"id": "pc2:右寸+滑+大", "n": "右寸·滑大脉", "o": "右寸·滑大脉总以痰、热、实、积为纲。滑主痰饮，大主实热，有力搏指为邪气壅实，右寸候肺，右关候脾，故其病机多归痰热壅肺、痰饮内结、气郁食积、上焦痰火等实证。诸类之间，痰与热常相兼，痰饮可因气郁食积而生，痰火可壅于肺而致咳喘，甚则震动胞系而堕胎。虽有一例兼两尺弱之", "c": "主痰饮"}, {"id": "pc2:右寸+滑+洪", "n": "右寸·滑洪脉", "o": "右寸滑洪脉总起来主痰热壅盛、气机壅滞之实证，尤以肺胃痰火、痰食积滞为核心。洪为阳盛火炎，滑为痰湿内蕴，右寸关候肺胃，故脉见洪滑多提示痰热胶结于中上焦。其具体病机可分三类：一为痰热壅肺，火性炎上，迫血灼津，见鼻塞、衄血、痰核；二为气郁食积化热，痰食壅阻中焦，见胸", "c": "主痰热壅肺"}, {"id": "ps:右寸+滑", "n": "右寸·滑脉", "o": "右寸滑脉总属肺经痰病，以痰湿、痰热、食积、气逆、郁痰、顽痰为常见病机。滑脉主痰，右寸候肺，故滑脉见于右寸多提示肺有痰浊。其兼脉不同，病机有别：滑而软者多痰湿；滑数或洪滑者多痰热；滑大有力者多食积；滑而上溢者多气逆；滑而兼郁象者多郁痰；坚凝而滑者多顽痰。各类之间", "c": "主痰湿"}, {"id": "ps:右寸+濡", "n": "右寸·濡脉", "o": "右寸濡脉总属虚证，以气虚、阳虚为本，湿停为标。其病机主要有三：一为脾虚湿停，因右寸关濡弱，脾失健运，湿邪下注，症见小水频迫、足肿、咳嗽；二为肺气虚，右寸濡细直接反映肺气不足，宣降失职；三为阳虚水泛，两尺无力、水火两亏，阳不潜藏，水湿泛滥，兼见便溏、遗泄、虚阳上", "c": "主脾虚湿停"}, {"id": "ps:右寸+空", "n": "右寸·空脉", "o": "右寸空脉总属虚候，以肺气虚阴亏为核心，兼涉气分热盛津伤、阴血不足及气虚浮越。右寸候肺，空大之脉按之不足，多因肺脏气阴亏虚、脉道不充；若兼数象，则虚热内扰；若热盛津伤，则脉大而空，如肺胃热炽；若气虚阳浮，则脉大无根，如脱证之象。诸类之间，以虚为本，或阴虚、或气虚", "c": "主肺虚"}, {"id": "ps:右寸+紧", "n": "右寸·紧脉", "o": "右寸紧脉总主风寒之邪犯肺，属外感表证范畴。其脉浮紧，浮主邪在表，紧主寒邪束表，右寸候肺，故为风寒闭肺之象。风寒外袭，肺气失宣，可致喘咳、胸痛、寒热无汗等症；寒性收引，津液凝滞，又可兼夹痰浊，形成痰凝气滞，阻塞清道。原文所载三则，或为风寒闭肺兼痰凝气滞，或为寒邪", "c": "主风寒闭肺"}, {"id": "ps:右寸+细", "n": "右寸·细脉", "o": "右寸细脉总属肺脏虚损，以肺气不足、阴液亏耗为基本病机。细为不足之象，右寸候肺，故凡肺气虚弱、肺阴亏虚者多见。若细而兼数，则示阴伤基础上虚热内生，或肺燥液干，或精虚三消，或肺热下遗大肠；若细数而兼小滑，则为痰火郁肺、伏火挟痰；若细而迟涩，则又主寒凝气滞、肺气壅塞", "c": "主肺气虚"}, {"id": "ps:右寸+虚", "n": "右寸·虚脉", "o": "右寸虚脉总属正气亏虚，以肺气不足为核心，兼及卫表不固、脾肺阳亏及营血不充。右寸候肺，肺主气、属卫、外合皮毛，故虚脉首责肺气亏虚，卫外失司则易感外风；肺气虚则卫表不固，虚浮之象尤为明显。肺病及脾，脾肺阳气同亏，则见虚软无力；营血不足，血虚生风，则虚浮与虚濡并见。", "c": "主卫表不固"}, {"id": "ps:右寸+软", "n": "右寸·软脉", "o": "右寸软脉总属肺气不足、气虚不振之象，然其兼脉不同，所主病机亦异。单纯软弱或极软弱者，多主气虚，甚则气虚不能摄血；软而兼滑者，主痰浊壅肺或痰火为患；软而见于平脉，则主肺肾虚损，属不足之候；软兼滑数弦等，又主虚实夹杂，肺虚而痰火实；若左脉弦长上鱼际而右寸软弱，则为", "c": "主气虚"}, {"id": "pp:右尺", "n": "右尺", "o": "右尺脉总属肾与命门、胞宫之候，其病机以虚为本，火象为标。虚者，命门火衰则脉迟软细弱，下焦气弱则脉细如丝，阴阳两虚则两尺微弱，三阴亏损则迟软并见；火象者，有实火、虚火、浮火之分：相火正隆则滑大有力，阴虚火旺则洪而无力，肾虚火不归原则沉伏不起。孕脉洪大有力为气血充", "c": "主命火衰微"}, {"id": "ps:右尺+大", "n": "右尺·大脉", "o": "右尺大脉总属火象，因右尺候命门相火与胞宫，脉体宽大有力或滑大洪大，皆阳气亢盛、气血壅盛所致。然有虚实之别：实火者，相火正隆，燥渴而滑大，可暂泻；虚火者，水亏火旺，浮洪无力，不可久伐；孕脉者，气血充盛，六脉平而右尺独大，为生理之常。三者皆以“大”为形，但兼象不同", "c": "主火盛"}, {"id": "ps:右尺+洪", "n": "右尺·洪脉", "o": "右尺洪脉总属火热亢盛之象，但须分虚实。实者多因阳火独狂，如阴虚火动、龙雷鼓动，或孕后气血壅盛，脉见洪大有力；虚者可见于水亏火旺，脉浮洪无力。所主病机以阴虚火旺、阳火亢盛及孕脉为主。三者皆与右尺所候肾与胞宫相关：阴虚火旺为虚火，阳火亢盛为实火，孕脉则为生理性气血", "c": "主阴虚火旺"}, {"id": "ps:右尺+细", "n": "右尺·细脉", "o": "右尺细脉总属虚证，主下焦元气亏虚。其类有三：一为命火衰微，火不生土而晨泄；二为下焦气弱，气化不行而便闭；三为膀胱气虚，水道不利而小便难。三者皆以右尺细为共同脉象，反映肾与膀胱阳气不足、气弱不充。细脉主虚，右尺候肾，故其病机核心为下焦阳气虚衰，或火衰，或气弱，或", "c": "主命火衰微"}, {"id": "ps:右尺+软", "n": "右尺·软脉", "o": "右尺软脉总属肾与命门虚损之象。其核心病机为命门相火不足，阳虚不能鼓动，故脉迟软；若兼细数，则阴亦不足，虚火妄动；若两尺俱弱，则阴阳两虚；劳瘵日久，三阴亏损，亦见右尺迟软。四类病机均以虚为本，火衰、阴亏、阴阳两虚、三阴亏损相互关联，总归肾元亏虚、水火失调。", "c": "主命门火衰"}, {"id": "pc2:右尺+软+迟", "n": "右尺·软迟脉", "o": "右尺软迟脉总属肾阳不足、命门火衰之象。右尺候命门相火，迟为阳不胜阴，软为气衰不鼓，故其核心病机为命门相火不足、阳虚不能温煦。由此可衍生三类相关病机：其一，火衰及阴，或与左尺虚弱并见，则成阴阳两虚；其二，阳虚不能制阴，虚阳浮越，则见虚热无火之劳瘵证；其三，命门火", "c": "主命门火衰"}, {"id": "ps:右尺+迟", "n": "右尺·迟脉", "o": "右尺迟脉总属肾阳不足、命门火衰之象。右尺候命门相火，脉来迟软或沉细数欲绝，皆因阳虚不能鼓动血脉所致。其病机核心为命门火衰，可单独出现，也可与左尺虚弱细数并见而呈阴阳两虚；若劳瘵日久，三阴亏损，则右尺迟软与虚火浮越之弦洪脉并见，形成阴亏阳浮、元气不摄的复杂局面。", "c": "主命门火衰"}, {"id": "p:右", "n": "右部", "o": "右部脉总以候肺、脾胃、气分为核心，所主病机可归纳为热、虚、痰湿、气滞、邪实、血瘀及向愈七类。热与邪实多因外邪或内火壅盛，脉见洪数滑大有力；虚与向愈则因正虚或病退，脉见虚小软缓无力；痰湿、气滞、血瘀多由内伤杂病，脉见滑濡弦涩。诸类常相互兼夹，如热盛灼津可兼虚，痰", "c": "主热"}, {"id": "c:和+促", "n": "和促脉", "o": "和促脉在此案中总主痰热交争、表里同病之机。浮主表，示胎毒未尽、邪发肌肤而为癍疹；弦主饮，示痰饮内蕴、肺气壅逆而为吼喘；促主热，示热邪内盛、鼓动气血。三者相合，反映痰热内蕴、外发肌肤、肺气壅逆的复杂病机。痰与热交结，表与里同病，故喘与疹并作。脉象浮弦而促，正是痰", "c": "主热"}, {"id": "c:弦+滑+和+动", "n": "和动弦滑脉", "o": "和动弦滑脉总起来主气机郁滞、饮邪内停与痰湿未化。其脉以‘和五动’为常至数，示胃气尚和，但兼见弦滑，则反映邪未全退。弦主气郁与饮停，滑主痰湿，三者常相兼为患，气郁可致津液不布而生痰饮，痰饮内停又加重气机郁滞。原文药后‘动气收、足膝温’示阳气渐复，而弦滑未去，说明", "c": "主气郁"}, {"id": "c:弦+和+平+硬", "n": "和平弦硬脉", "o": "和平弦硬脉总属虚实夹杂之象，以真阴亏虚、肝阳未柔为本，标热渐清为标。其脉虽较前和平，但弦硬之意未除，表明病势已减而根蒂未拔。所主病机主要有三：一为阴虚阳亢，阴不涵阳致肝阳偏亢；二为肝阳未柔，脉道失于柔和；三为标热渐清，火势已平而余根未除。三者相互关联：标热渐清", "c": "主阴虚阳亢"}, {"id": "c:和+平", "n": "和平脉", "o": "和平脉总起来主气血调和、邪退正复，为平人无病或病势向愈之象。其类别关系：首为常脉，三部同等、从容和缓，示阴阳和平；次为病中脉转和平，乃邪退正复之兆，多见于汗后、热退、痢减之际；若和平之中按之无力、稍弱不条，则主正气虚损，或为寒湿内滞、阳气不运；若一部平和而他部", "c": "主邪退正复"}, {"id": "c:弱+和", "n": "和弱脉", "o": "和弱脉总起来主邪退正复、胃气柔和而正气尚虚之候。其脉以“和”为胃气未败、脉道不乖，以“弱”为气血未充、正气不足。两段原文均见于病后，前有邪热、浮数、弦、沉涩等邪象渐去，今脉转和而少弱，故非邪盛病脉，而是邪退正未复之象。三类病机相互关联：邪退是前提，胃气和是向愈", "c": "主邪退正复"}, {"id": "c:滑+和", "n": "和滑脉", "o": "和滑脉总起来主痰饮内停、气机失和及邪退正虚三类病机。滑脉往来流利，主痰湿内蕴；兼弦势则气机郁滞，痰气交阻；若滑势已和而转软弱，则示邪热尽退、气血未复。三类之间，痰饮与气滞常相兼为患，气郁津凝生痰，痰阻加重气滞；而邪退正虚则为病后转归，滑去软现，提示当补养复正。", "c": "主痰饮内停"}, {"id": "c:和+结", "n": "和结脉", "o": "和结脉总主经脉不和、气血结滞之病机。其核心在于脉道失和，气血运行不畅，结聚为病。具体而言，可致外结如瘿瘤、痈肿，内结如症瘕、坚气，亦可因经脉不通而水湿停聚为肿。三类病机相互关联：经脉不和是基础，坚结内生是结聚成形之果，水湿停聚是脉道壅滞、气化不利之变。和结脉所", "c": "主经脉不和"}, {"id": "c:弦+缓+和+硬", "n": "和缓弦硬脉", "o": "和缓弦硬脉总起来主肝盛、脾伤、肺伤三类病机。弦为肝脉，肝盛则脉弦硬而不和缓，此其一；脉失和缓之脾土之气，是脾气受伤，此其二；肺金受伤不能镇肝，致肝木偏亢而脉弦，此其三。三者相互关联：肝盛侮脾，脾伤则土不培金，肺金亦伤；肺伤则金不制木，肝愈横逆。原文以“和缓为贵", "c": "主肝盛"}, {"id": "c:紧+缓+和", "n": "和缓紧脉", "o": "和缓紧脉（缓脉）总以“和缓不紧”为脉象特征，其病机归属有三：一为平人正脉，从容和缓、浮沉得中，无病可主；二为实热，脉缓而滑大有力，因邪热壅盛、气血充溢，故见烦热、口臭、腹满、痈疡、二便不利及温疟余热；三为虚寒，脉缓而迟细，因阳气虚衰、阴寒内凝，故见畏寒、气怯、", "c": "主平"}, {"id": "c:细+微+缓+和", "n": "和缓细微脉", "o": "和缓细微脉总起来主真阴亏损、精血衰少之虚证，尤以腰痛虚证为代表。其脉象由和缓与细微复合而成：和缓为胃气尚存之征，细微为精血衰少、真阴亏损之象。原文指出腰痛虚证十居八九，多因年衰、劳苦、酒色、七情忧郁所致，悉属真阴虚证，脉息和缓或见细微，并伴形色清白黎黑、行立不", "c": "主真阴虚"}, {"id": "c:缓+和", "n": "和缓脉", "o": "和缓脉总属脾胃之正脉，以从容和缓、有胃气为特征。其主病机以胃气来复、邪退正复为核心，凡病中脉由弦急数疾转为和缓，多示正气渐充、病势向愈；在平人则主气血调和、营卫流通。若见于胎漏，则主胎元未伤；见于危候，则主胃气未败、生机尚存。若和缓中兼见他部偏象，则主虚中夹热", "c": "主胃气来复"}, {"id": "c:虚+缓+和", "n": "和缓虚脉", "o": "和缓虚脉在此段中主要反映两种病机：一是气火渐平，为治疗后邪势减退、脉转和缓的向愈之象；二是上盛下虚，提示阴血未充、下元不足，清阳不升。二者一为病势缓解之征，一为虚损未复之候，共同说明该脉总属邪减正虚、上下失调之态，既可见于热病后期气火渐平，又可见于虚人下元不足", "c": "主气火渐平"}, {"id": "c:缓+软+和", "n": "和缓软脉", "o": "和缓软脉在原文中主要作为脉证顺逆的判断依据。其核心意义有二：一为不足之病的顺象，因虚证脉宜柔和缓弱，见和缓柔软则脉证相符，预后较佳；二为有余之病的逆象，因实证脉当有力有神，若反见柔软无力则脉证相反，属逆兆。可见该脉所主病机并非固定一病，而是取决于病性：在虚证中", "c": "主不足之顺"}, {"id": "e:和", "n": "和脉", "o": "和脉总以从容和缓、有胃气为纲，其主病机首在邪退正复与气血调和，为平人无病或病势向愈之象。然和脉非尽主吉，须辨兼象：兼软弱虚细者主正虚不足；兼弦涩劲者主气滞络瘀；兼滑数弦硬者主湿热痰火；若乍和而无胃气、兼雀啄解索者，则主胃气衰败、预后不良。各类之间以胃气存亡为枢", "c": "主邪退正复"}, {"id": "c:和+坚", "n": "坚和脉", "o": "坚和脉（坚劲不和）总属邪实气滞之象，以暑湿热邪内著、脾胃气机壅滞为核心病机。其脉坚劲不和，反映邪气壅盛而正气尚能抗争，气血运行不畅。所主病机可归纳为三类：邪实气滞、湿热内蕴、脾胃气困，三者相互关联，湿热为病因，气滞为病机关键，脾胃气困为病变重心。原文见舌心黄边", "c": "主邪实气滞"}, {"id": "c:大+坚", "n": "坚大脉", "o": "坚大脉总以「邪盛实积」为基本病机，坚主内结劲急，大主邪气亢盛。其主病约分两端：一为实邪壅盛，如风雨外袭、水气内停、积气结于脏腑、肾痹石水等，脉证相合，治当逐邪；二为正虚邪实之危候，久咳羸瘦而脉反坚大，形脉相反，胃气已败，故主死。此外，形充之人脉见坚大，为形气相", "c": "主邪盛实"}, {"id": "c:大+迟+坚", "n": "坚大迟脉", "o": "坚大迟脉总属寒实内结之候。坚大主实，迟主寒，二者相合，表明寒邪与实邪（食积、气滞、血凝）互结于内，非单纯虚证。原文以面黄肌瘦、月事不至、腹大如鼓、见食辄吐等似虚之症，误补反剧，而脉坚大迟揭示病本为寒凝食积、气凝血闭。三类病机相互关联：寒为因，实为果，食积、气凝", "c": "主寒实内结"}, {"id": "c:弦+大+实+坚", "n": "坚弦实大脉", "o": "坚弦实大脉总属邪实正盛之象。其脉坚、弦、实、大，四象并见，反映邪气亢盛而正气未衰，正邪交争剧烈。在癫病卒忤中，见此脉者生，因邪实可攻，正未虚败；若脉虚伏濡小，则正衰邪陷，主死。故本脉所主病机以邪实为主，兼涉癫病卒忤之特定病证，其预后判断关键在于正邪盛衰对比。", "c": "主邪实正盛"}, {"id": "c:弱+坚", "n": "坚弱脉", "o": "坚弱脉总属虚实夹杂、上盛下虚之候。左脉坚主木火偏旺、肝阳不潜，营液久耗而阴虚火旺；右脉弱主中气不足、脾运不健。二者并见，反映肝木过亢而克伐中土，情志郁勃化火，耗伤营液，致中土亦弱。临床多见于中年形瘦之人，春季木火升腾，迫血上溢而失血嗽痰，少食尩羸。总病机为阴虚", "c": "主阴虚火旺"}, {"id": "c:急+坚", "n": "坚急脉", "o": "坚急脉总属脉失和缓、劲急拘挛之象，所主病机以邪实与正虚两端为纲。一方面，坚急脉主邪实壅盛，如寒实内攻、积聚内结，正气尚能抗邪则脉应之劲急，故原文有'脉坚强急者生'之判；另一方面，坚急脉亦主正虚邪深，尤以小坚急脉为代表，脉小为正气衰少，坚急为邪气劲迫，二者并见反", "c": "主邪实正争"}, {"id": "c:数+促+坚", "n": "坚数促脉", "o": "坚数促脉总起来主水亏热升、虚火内迫之证。左脉候肝肾，坚为阴亏阳亢，数为热，促为热盛而气机急促，三者相合，示水不制火、龙相之火上炎。原文冬温咳嗽，水亏热升，热灼胃阴，秽浊上冲咽喉，故脉见坚数促。其病机核心为阴亏于下、热升于上，涉及肝肾龙相火炎与胃阴受伤两端，总属", "c": "主水亏热升"}, {"id": "c:数+坚", "n": "坚数脉", "o": "坚数脉总以“坚”示邪实或阴亏脉失柔润，“数”示热或虚火，合而主热与实结、阴虚火旺、肝阳亢盛、积结络瘀及寒凝阳伤等证。其核心为热与实或虚火相兼，病位多在肝肾，涉及气、血、络、积。各证之间可转化：实热久郁伤阴则转为阴虚火旺；肝阳亢盛可致络血上涌；积结络瘀郁久化热；", "c": "主热盛"}, {"id": "c:滑+坚", "n": "坚滑脉", "o": "坚滑脉总属痰湿、邪积、有形滞结聚之实证。滑主痰湿内盛，坚示有形之滞，实主邪气积滞，三者相合，反映痰湿与积滞浑结、气机壅塞之病机。所主病机可归为三类：一主痰结，痰浊胶固壅塞肺胃清浊之道；二主里实积滞，邪积内结、腹中横积；三主气壅，痰滞阻遏致气机升降失常。三者相互", "c": "主痰结"}, {"id": "c:结+坚", "n": "坚结脉", "o": "坚结脉总属经脉不和、气血结滞之候。其病机核心为“结”，即气血痰浊等结聚不通。据原文，坚结脉所主可分为外结与内积两类：外结者，经脉不和而病结于外，见瘿瘤、硬核、痈肿；内积者，经脉不和而病结于内，见症瘕坚气、腹中雷鸣。二者皆因经脉气血流通不畅，结聚成形，故脉见坚结", "c": "主外结"}, {"id": "e:坚", "n": "坚脉", "o": "坚脉所主病机，总以邪实内结为纲，然有虚实两端。实者，邪气壅盛，如湿热、火毒、瘀血、积气、寒凝等，壅聚于里，脉道充实坚劲，多见于暴病新病、形气壮盛者，可任攻逐。虚者，阴血亏虚，脉失濡养而拘急，或虚火内扰、阳亢不柔，坚脉非实邪，治当柔润滋养。此外，坚脉无胃气柔和之", "c": "主邪实壅盛"}, {"id": "c:虚+坚", "n": "坚虚脉", "o": "坚虚脉总属虚证范畴，以正虚为本，坚象为标。其主病机主要有四类：肾虚厥逆、脾胃虚弱、血虚气少、气虚阳衰。原文通过“脉大而坚病在肾”“脉下坚上虚病在脾胃”等论述，揭示坚虚脉与脏腑虚损的对应关系；又通过弦坚虚脉在头痛中的表现，说明坚虚脉可兼见弦、软、涩等象，反映不同", "c": "主肾虚厥逆"}, {"id": "c:长+坚", "n": "坚长脉", "o": "坚长脉总属邪实气盛之象，以“坚”示邪实内结，“长”示气机壅盛。其主病机主要有五类：实热壅盛、瘀血内结、气逆血溢、腰府损伤、脾虚气壅。各脏腑搏坚而长，皆示该脏邪实气盛，但具体病机因脏而异：胃、心多实热，肝、肺多瘀血与气逆血溢，肾主腰府损伤，脾则见气壅少气。坚长脉", "c": "主实热壅盛"}, {"id": "c:大+乱", "n": "大乱脉", "o": "大乱脉总起来主寒凝、痛证与气血壅阻。其核心病机为寒邪客于经脉，导致气血凝泣、收引不通。原文以脉泣、脉急、脉坚等特征，说明寒性收引、气血壅阻，故见卒然疼痛。三类病机相互关联：寒凝为因，气血壅阻为果，痛证为临床表现。大乱脉虽名‘乱’，但在此段中突出寒邪致乱，与下属", "c": "主寒凝"}, {"id": "c:大+伏", "n": "大伏脉", "o": "大伏脉总起来主邪气内郁、壅滞不通之病机，其象以伏为主，伏示气机郁闭、邪阻脉道；大则示邪气亢盛或郁而外发。所主病机主要有三类：气滞血郁、郁火内伏、痰浊壅盛。三者皆因实邪壅遏，致脉道沉伏，而大脉则反映邪势之盛或郁极将透。气滞血郁侧重肝郁血瘀，郁火内伏侧重火邪被遏，", "c": "主气滞血郁"}, {"id": "c:大+动", "n": "大动脉", "o": "大动脉总起来主病机以虚、风、寒、热、气逆为纲。其脉形大而动搏，或兼洪硬、细紧、虚大不调、厥厥动摇，皆提示阴阳失调、气血失和。虚阳浮越与心肾气虚同属虚证，前者为元海根微、阳不潜藏，后者为心肾气衰、脉行无力；内风动摇为水不涵木、风阳暗动；虚寒内结为阴血不足、寒凝脉", "c": "主虚阳浮越"}, {"id": "c:大+和+平", "n": "大和平脉", "o": "大和平脉总起来主正气未败、病势轻浅或向愈，但和平之中常藏病机。其主病机可分四类：邪退正复为向愈之兆；正虚邪陷为和平中见微弱有力，示邪陷正虚；水湿郁热为平和兼滑数，示湿郁微热；下焦不固为尺浮不实，示虚阳上冲。四类均以和平为底色，反映正气尚存，而兼脉揭示具体病机。", "c": "主邪退正复"}, {"id": "c:大+和", "n": "大和脉", "o": "大和脉总起来主正气未败而病机内藏，其大而和缓为底色，反映胃气尚存、病势未至深重，但和平之中常寓虚实寒热之变。所主病机主要有三：一为虚阳外浮，脉大无力不能敛摄，肾虚火升；二为里热伤阴，脉大身热，热自里发而阴精先亏，易致液涸风动；三为下焦虚寒，脉虽调和而阳气不足，", "c": "主虚阳外浮"}, {"id": "c:大+涩+坚", "n": "大坚涩脉", "o": "大坚涩脉总起来主胀病，其病机核心为邪盛、寒凝、气滞血瘀三者相合，导致营卫逆乱、气机壅塞于脏腑之外。脉大示邪气亢盛，坚示寒邪凝滞收引，涩示气滞血瘀、脉道不利。三者并见，说明胀病非单纯虚证，而是实邪结聚、气血运行受阻所致。原文指出胀在脏腑之外，排脏腑而郭胸胁，胀于", "c": "主邪盛"}, {"id": "c:大+小+平", "n": "大小平脉", "o": "大小平脉以“不大不小”与至数合度为核心，总起来主平与病两端。平脉者，呼吸定息五至，脉形适中，为气血调和、阴阳平衡之常；病脉者，至数增至一呼三至、一吸三至，超出常度，主阳热偏盛、正气受扰，属病始而非死候。三类之中，“主平”为常，“主热”为病之因，“主正虚受扰”为", "c": "主平"}, {"id": "c:数+大+小", "n": "大小数脉", "o": "大小数脉总起来主气机失调、气血逆乱、神志不宁及热盛正虚等病机。其核心在于脉象大小不匀、数急错杂，反映气血运行失常与脏腑功能紊乱。数脉主热、主气急，大小不均则示气血偏颇或逆乱。各类之间相互关联：气机失调可致血行不畅，进而气血逆乱；气血逆乱又常扰及心神，导致神志不", "c": "主气机失调"}, {"id": "c:大+涩+小", "n": "大小涩脉", "o": "大小涩脉总起来主气血瘀滞、脉道不利，核心病机为气机壅塞、血行不畅。其类可分三：一主气滞血瘀，涩示脉道不利，大小不一示气血壅塞；二主气机逆乱，厥逆之气乱于胸肠，升降失常；三主痛证，瘀滞不通则痛，故见胸肠剧痛。三者相互关联：气滞血瘀为病本，气机逆乱为病势，痛证为病", "c": "主气滞血瘀"}, {"id": "c:滑+大+沉+浮+涩+小", "n": "大小滑涩沉浮脉", "o": "大小滑涩沉浮六脉总起来主五脏气机变动与病邪逆顺。其核心在于「有诸内者形诸外」，脉象随脏气而变，故六脉首先反映五脏功能状态；进而通过脉色相参，判断病邪性质及预后吉凶。六脉对举又分虚实寒热表里：大、滑、浮多主有余或表，小、涩、沉多主不足或里。各类之间以脏气为根本，", "c": "主应脏气"}, {"id": "c:大+小", "n": "大小脉", "o": "大小脉总以脉体大小不匀、变动不居为特征，所主病机广泛。其核心在于气血阴阳失序：或为邪祟干犯、神气逆乱，脉无定体；或为虫积痰饮，气机交阻，脉乍大乍小；或为虚实夹杂、上盛下虚，左右寸尺大小偏倾；或为气机紊乱、正虚邪伏，脉来无常数。各类之间相互关联，如邪祟与痰饮均可", "c": "主邪祟"}, {"id": "c:数+大+小+迟", "n": "大小迟数脉", "o": "大小迟数脉在此段中并非直接论述病机，而是通过“诸虚寒证毕现”及“脉之大小迟数不足计”的讨论，反映其在虚寒重证中的表现及脉诊局限性。总起来说，该脉所主以虚寒重证为核心，同时提示脉象在复杂证候中可能不具决定性，需四诊合参。两类病机相互关联，虚寒重证是脉象出现的背景", "c": "主虚寒重证"}, {"id": "c:大+平", "n": "大平脉", "o": "大平脉总起来以脉形偏大而近于平和为底色，所主病机有常、有变。常者，如所示壮年气血盛满、脉大而平，为生理之常；变者，大主邪盛，平示正气未大伤，故常见邪热、痰饮、气郁等实邪为患而正尚能抗，如暑热深伏、饮邪内动、肺热壅盛。若大而重按无力，则又主正虚阳浮，如肝肾大虚、", "c": "主暑热痰热"}, {"id": "c:大+弱", "n": "大弱脉", "o": "大弱脉总以虚为本，然所主病机有气血两虚、气虚痰湿、热郁血虚及阴阳乖违数端。其脉象大而弱，大则示虚，弱为气衰，故虚证居多，如气血不足、心气虚弱、脾虚痰湿等。然虚中每夹实邪，如酒热内郁、痰湿内蕴，则脉见大弱而兼实涩或滑数，此乃正虚邪恋之候。又有上下阴阳乖违者，右大", "c": "主气血两虚"}, {"id": "c:弦+大+微", "n": "大微弦脉", "o": "大微弦脉总属虚损之候，以虚劳内伤、气血亏虚为根本。脉大为劳倦气虚、虚阳外浮，非邪实之象；微弦为土虚木乘、肝脾不和。三者相互关联：中气亏虚则气血不足，虚阳外浮而脉大；土虚则木乘，故见微弦。原文所载久患寒热、精遗自汗、能食神疲、肌肉渐瘦，正是虚劳中损、阴阳营卫失调", "c": "主虚劳"}, {"id": "c:数+大+微+迟", "n": "大微迟数脉", "o": "大微迟数脉总起来主呕吐之寒热虚实辨证。大数主热，微迟主寒，四脉合参，可辨胃虚、瘀滞、气逆、停痰等病机。其中胃虚与瘀滞常并见，如原文两寸关涩而弱，弱主胃虚，涩主瘀滞，胃虚有瘀则得食即吐。寒热错杂与气逆痰阻亦为呕吐常见病机，大微迟数脉可提示寒热属性及虚实夹杂。诸类", "c": "主胃虚"}, {"id": "c:大+沉+急", "n": "大急沉脉", "o": "大急沉脉总主寒凝气结、脉道拘急之疝瘕。其大急沉为寒邪深结、脉道拘急，见于肾肝则疝；搏滑急为痰热搏结之心疝；沉搏为寒凝气聚之肺疝；三阳急为瘕，三阴急为疝，急字统贯，明疝瘕皆由寒凝气结、脉道拘急而成。三类病机以寒凝气结为共同基础，痰热搏结为兼化之变，气聚搏结为瘕疝", "c": "主寒凝疝瘕"}, {"id": "c:大+急+疾", "n": "大急疾脉", "o": "大急疾脉在此段总主热病后阴血大耗、虚阳外扰、气弱之候。其形成始于热伤阴络，血大泻而阴分大亏；阴不制阳，虚阳外扰，故左脉大急疾；气随血耗，故右脉小微弱。四类病机中，热伤阴络为始因，阴血亏耗为直接结果，虚阳外扰与气弱为继发之变，彼此关联，共成血脱阴伤、通补兼施之证", "c": "主阴血亏耗"}, {"id": "c:大+急", "n": "大急脉", "o": "大急脉总起来主邪实壅盛、气机逆乱，兼涉虚阳外浮与正虚邪盛之变。其脉象以大（脉体宽大）与急（脉势急劲）并见为特征：大主邪盛或虚阳外浮，急主气逆、寒凝或风动。所主病机可归为五类：邪实气逆者，如肺痹痰气胶结；寒凝搏结者，如疝瘕寒凝气结；虚阳外浮者，如真元耗损、阴不制", "c": "主邪实气逆"}, {"id": "c:大+散+乱", "n": "大散乱脉", "o": "大散乱脉总主元气离散、邪盛正衰之危候。其脉大而散乱，大则邪气盛而正气衰，散为元气离散，阴阳不相维系，故见大热、气促、汗多、昏愦等症，法在不治。然散乱非绝脉，属虚而可挽，原文以脉之敛散判预后吉凶，补后脉转收敛、喘缓泻减，说明散大之脉主元气欲脱，但非绝对死候。三类", "c": "主元气离散"}, {"id": "c:数+大+微+缓", "n": "大数微缓脉", "o": "大数微缓脉总属虚实夹杂之候。其大数主邪气有余，微缓主正气不足。从人迎气口分部看：见于人迎（左寸）而大于气口者，为外感风寒，风邪伤卫则脉缓大，寒邪束表则浮紧洪大；见于气口（右寸）而大于人迎者，为内伤饮食劳役，谷气壅滞则脉大数急，脾虚气弱则脉微缓。故本脉所主，一为", "c": "主外感风寒"}, {"id": "c:数+弦+大+浮", "n": "大浮弦数脉", "o": "大浮弦数脉总起来主邪实热盛、气机郁滞之病机。浮主邪在表，弦主风邪或气郁，数主热，大主邪实。四者合见，多属外感温邪、风邪外袭，或内伤食积化热、肝脾不和、气火郁勃。各证虽异，然皆不离“邪实”与“热郁”两端：外感者，风热袭表，肺胃受病；内伤者，食滞、气郁化火，肝木乘", "c": "主食积化热"}, {"id": "c:滑+大+沉+小+实+急", "n": "大滑沉小急实脉", "o": "大滑沉小急实脉总起来主癫疾之病机，以脉之虚实判断邪正盛衰与预后。大滑为阳邪渐衰、气血尚和，故可自愈；沉小急实为邪深入阴、正气被遏，死不疗；小牢急为邪坚正败，亦不可治；脉虚为邪去正复，可疗；脉实为邪盛正绝，则死。各类之间以邪正关系为纲：大滑与虚脉示邪退正复或邪衰", "c": "主阳邪渐衰"}, {"id": "c:大+濡", "n": "大濡脉", "o": "大濡脉总以“大而濡软无力”为特征，主虚、主湿、主气阴两伤，亦可兼夹实邪。其“大”非实热亢盛，多为气虚阳浮或虚阳外越；“濡”主湿盛、津亏或气弱。故其病机核心为正气不足、湿浊内蕴，常见气虚湿滞、气阴两虚、中虚不摄；若兼左大右濡，则示肝风内动、阳明中虚；若右大偏盛，", "c": "主气虚湿滞"}, {"id": "c:大+濡+软", "n": "大濡软脉", "o": "大濡软脉总起来主虚证，以气虚、胃阴亏虚为本，兼夹痰湿为标。其脉象大而濡软无力，大而无力主虚，濡软主湿，故所主病机以虚为核心。从原文看，或见频吐伤胃阴、湿寒成燥之胃阴亏虚，或见肥白人眩晕之气虚痰湿，均属虚实夹杂之候。其中胃阴亏虚侧重津伤燥化，气虚痰湿侧重气弱湿停", "c": "主胃阴亏虚"}, {"id": "c:大+疾", "n": "大疾脉", "o": "大疾脉总起来主邪热亢盛与虚阳浮越两类截然不同的病机，并可反映正虚邪陷、风热痰火及燥热伤阴等复杂情况。实热证中，脉大为邪气壅盛，疾为热盛急迫，见于温病、伤寒热盛、阳明燥热等，正能抗邪则生，若兼细小难得则正虚邪陷，预后不良。虚证中，脉大而无力、疾而豁然，为虚阳外越", "c": "主热盛邪实"}, {"id": "c:大+硬", "n": "大硬脉", "o": "大硬脉总起来主邪正相搏、内伤外感并重及胃气衰败三类病机。其脉大主邪气盛或气化外越，硬主劲急失柔、邪正交争或胃气败绝。初病脉硬大者，为邪实与正气相搏，正气尚能敌邪；若温病见大硬兼洪，则示外感温热与内伤积滞并重；若久病或咳病见大硬，则为真脏脉见、胃气已绝之死候。三", "c": "主邪正相搏"}, {"id": "c:大+虚+空", "n": "大空虚脉", "o": "大空虚脉总属正虚之候，以阳气亏虚、阴血不足为核心，脉形虽大而中空无力，示脉道失充、气不内守。其所主病机可归为五类：阳气暴散者，脉大而空虚、汗出如雨，属脱证危候；气虚不运者，脉空大无力，为气虚不能运血，或正虚邪恋；阴血枯槁者，脉大空虚兼细涩，为津血不充、胃气将败", "c": "主阳气暴散"}, {"id": "c:大+紧+急", "n": "大紧急脉", "o": "大紧急脉总起来主阴寒内盛、虚阳外浮之格阳证。其脉象特征为大、紧、急：大因虚阳外浮，紧因寒邪内盛，急因阳气欲脱。原文以“渴甚面赤，扇扇不知凉，饮冰不知冷”等症，揭示内真寒外假热之病机，故以大紧急脉为凭，断为格阳，治以温中回阳。此脉虽仅一段，然其病机明确，即阴寒格", "c": "主格阳"}, {"id": "c:大+紧", "n": "大紧脉", "o": "大紧脉总以紧主寒、主痛、主气机壅遏，大主邪盛、主热、主实为纲，合而主寒实内结、热郁瘀滞、风邪劲急、痰涎壅塞、正虚邪恋及脾胃衰败等病机。其核心在于邪气亢盛与气机拘急并存：紧示寒凝、气结或风动，大示邪实、热盛或正抗。诸类之间，寒实与热郁为邪实两端，风邪、痰涎为邪结", "c": "主寒实内结"}, {"id": "c:大+结", "n": "大结脉", "o": "大结脉总起来主气机郁滞、火郁热极及热毒壅盛之证。其核心病机为气机壅遏，脉象大而结。大主气壅，结主气滞不行，故气郁、火郁、热毒等均可致气机闭塞，脉道不利而见大结。原文明确“六脉大且结，乃气滞也”，因郁怒伤肝，又感暑邪，气机闭塞，见小便不通、气高而喘，属气滞实证。", "c": "主气滞"}, {"id": "c:大+缓+和", "n": "大缓和脉", "o": "大缓和脉在此案中总属病势向愈之象，其核心病机为气化渐趋和平。脉由弦硬转为大见缓和，首先反映肝胃气逆渐平、冲气下降，为气机由逆乱转和顺之征；然脉虽缓和而病未全瘥，步履仍须用杖、心中间有发热，又示气血尚未全复、余热未尽。故本脉所主病机可归纳为三类：气逆渐平、气血未", "c": "主气逆渐平"}, {"id": "c:大+缓+平", "n": "大缓平脉", "o": "大缓平脉以和柔从容、胃气存为平，然其变异则主脾土之病。总起来看，此脉所主病机以脾为中心：平脉示无病，实盈数主脾病邪实，坚锐弱散主脾死胃竭，鸟喙不及主中虚九窍壅塞。四类之间以胃气存亡为枢：胃气存则平，邪实则病，胃气竭则死，中虚则不及。故大缓一脉，平病生死皆可察，", "c": ""}, {"id": "e:大", "n": "大脉", "o": "大脉总以脉体宽大为核心，所主病机有虚实两端。实者，大而有力，主邪盛热实，包括外感表邪、温邪内郁、痰火积热、食积壅滞、湿热壅盛、燥屎内结等，大示邪气亢盛、病势进展；虚者，大而无力或按之不实，主虚阳外浮、虚劳内损、气血阴阳亏虚、胃气衰败，大乃气不内守、虚阳浮越之象", "c": "主邪盛热实"}, {"id": "c:大+芤", "n": "大芤脉", "o": "大芤脉总起来主阴血亏虚、阳气浮越，兼夹邪热或瘀滞。其核心病机为血脱失养、气浮不敛，故见芤大之象。各类之间相互关联：失血与热盛常并见，热迫血行而致血脱；虚劳与气不摄血同属正虚，气不摄血可加重血脱；瘀血内阻则新血不归，血不循经而致失血。临证需脉证合参，辨其虚、热、", "c": "主失血"}, {"id": "c:大+浮+虚+濡", "n": "大虚浮濡脉", "o": "大虚浮濡脉总属虚象，其核心病机为气血虚衰、虚浮于外而固摄失职。脉大而虚，是大而无力、气血不足之征；浮而濡，是表虚不固、腠理疏松之象。三者相合，提示正气亏虚而虚阳浮越，卫外与内守功能皆失。原文以“大虚之象”统括，并从脉位分疏：寸部见之则卫气不敛而自汗，尺部见之则", "c": "主表虚不固"}, {"id": "c:大+软+短", "n": "大软短脉", "o": "大软短脉总起来主湿郁、中虚、痰郁及筋伤四类病机。其脉来甚慢即迟缓，为湿浊困阻、阳气不运之征；中虚则运化失职，痰湿内生，郁阻脉道；湿热不攘，伤及筋脉，则见大筋软短、小筋弛长。四类病机相互关联：中虚为根本，湿郁痰郁为标象，筋伤为湿热痰郁久羁之变。脉象软短迟缓，既反", "c": "主湿郁"}, {"id": "c:大+软", "n": "大软脉", "o": "大软脉总以“大”与“软”并见为特征，大主邪气有余或虚阳外浮，软主正气不足。其病机总属虚实夹杂，以虚为本。所主病机主要有五类：一为气虚，脾肺元气不足，脉大而软无力；二为虚阳浮越，津亏阳浮，脉大稍软；三为正虚邪恋，如疟后、产后、病后正亏而邪未净；四为湿浊内蕴，脾虚", "c": "主气虚"}, {"id": "c:大+迟", "n": "大迟脉", "o": "大迟脉总起来主寒、虚、实夹杂之病机，以迟主寒与阳虚、大主邪实或虚阳浮越为纲。其具体所主，或为寒实内结（坚大迟、迟紧大），或为阳虚寒饮风痰（弦大迟），或为虚阳浮散欲脱（虚大迟、浮大迟），或为瘀血内阻（微大迟），或为气机壅滞（暑湿寒邪案），或为大气下陷（迟脉非寒之", "c": "主气机壅滞"}, {"id": "c:实+坚", "n": "实坚脉", "o": "实坚脉总属邪实壅盛、正气未衰之象，其病机以“实”为核心。邪气包括水饮、痰浊、阳热、瘀血等，壅聚于里，脉道充实坚劲，故见实坚。此类脉多主暴病、新病，形气壮盛，可任攻逐苦寒。然实坚脉亦需参合胃气与形证：若脉实坚甚而失柔和，兼形气相失、色夭不泽、脉逆四时，则为胃气衰", "c": "主邪实壅盛"}, {"id": "c:大+实+坚+牢", "n": "实大坚牢脉", "o": "实大坚牢脉总属邪实阳盛之候，非虚证所宜。其脉象坚实有力，主邪实内结、肝风鸱张、阳火有余三类病机，三者相互关联：情志重伤，君相火动，阳火有余则内风震动，肝风鸱张则邪实内结，脉象实大坚牢为共同外征。原文强调“大非吉兆”，因邪实壅盛、火风交炽，误用辛温刚燥或苦寒直下", "c": "主邪实内结"}, {"id": "c:大+实+坚", "n": "实大坚脉", "o": "实大坚脉总属邪实阳盛之候，其脉象坚实有力，主邪实内结、阳火有余、肝风鸱张、正虚邪实及癫病卒忤等病机。邪实内结者，瘀血、痰积、外邪壅盛，脉道充盈而坚大；阳火有余者，君相火动，火盛脉实；肝风鸱张者，风火交炽，脉劲急坚牢；正虚邪实者，见于产后等正虚之体，脉症相反，预", "c": "主邪实内结"}, {"id": "c:数+大+实", "n": "实大数脉", "o": "实大数脉总属邪热亢盛、邪气壅实之象。数主热急，实主邪实，大主病进，三者相合，突出热邪炽盛、正气未衰、邪正剧争之病机。其所主涵盖气分热实、热毒壅盛、心经实热及湿热滞下等，皆以热实为共同基础。然兼脉与部位不同，病机有异：兼模糊者多痰热蒙蔽，兼滞下者多湿热内蕴。若津", "c": "主热盛"}, {"id": "c:弦+大+紧+实+牢", "n": "实大牢弦紧脉", "o": "实大牢弦紧脉总起来主气血充盛或邪实壅盛，其核心病机为“实”。在妊娠七八月出现此脉，示母气壮实、胎有所养，属生理性实脉，预后良好；若见于他病，则多主邪气实、气血壅滞，为病理性实脉。三类之间以“实”为纲：胎气壮实与气血充盛均属正气实，邪实壅盛属邪气实，需结合具体语", "c": "主胎气壮实"}, {"id": "c:大+实", "n": "实大脉", "o": "实大脉总起来主邪气壅盛、正气未衰之实证，以实主邪盛、大主病进为纲。其病机涵盖热盛、湿浊、积滞、瘀血等邪实壅滞，亦可见于阳火有余、胃火刑金等火热之候。在久病中，实大脉示邪盛而正未衰，脉证相符，故病久可治；若脉虚小则正衰难治。小儿病热见实大而缓，示胃气犹存，急则胃", "c": "主邪盛"}, {"id": "c:大+实+散", "n": "实散大脉", "o": "实散大脉总以邪实壅盛为纲，其脉象充实有力，主病机以实邪内结为核心。原文明确“实脉主邪实”“沉实主里实”，并指出二便秘涩由脾胃气滞、痰饮食积阻碍浊道所致，故实脉所主涵盖邪实、里实及气滞积阻三类。三者相互关联：邪实为总纲，里实言病位在里，气滞积阻则言具体病理因素。", "c": "主邪实"}, {"id": "c:涩+实", "n": "实涩脉", "o": "实涩脉总起来主邪实郁滞与瘀血内停两类病机。实脉主邪气结聚，涩脉主气滞血瘀，二者相合，提示实邪内结、气血涩滞之证。所举两段，一为阳明胃腑邪实郁滞发黄，一为瘀血阻络致右肋疼痛、肌肤锐减，均属邪实与血瘀相互搏结。实涩脉所主，以邪实内郁为基础，或兼气滞，或兼血瘀，总不", "c": "主邪实郁滞"}, {"id": "e:实", "n": "实脉", "o": "实脉总主邪气盛实、正气未衰之证，其核心病机为实邪壅盛，脉道充盈。所主涵盖热盛、里实积滞、毒瘀壅结、气机郁滞、湿热壅盛及邪盛可攻等类。诸类之间以“邪实”为纲：热盛则气血涌盛，积滞则壅塞不通，毒瘀则结聚脉络，气郁则壅滞气机，湿热则蕴结阻滞，而邪盛正未衰则脉实有力，", "c": "主热盛"}, {"id": "pe:寸+代", "n": "寸·代脉", "o": "寸·代脉在此段总主脉气断续、气血壅阻之病机，具体可分气壅、阳衰、邪闭、积逆四类。肺气壅闭则宣降失司，见喉痹、暴逆、咳喘不得卧；阳气衰微则脉气不至寸口而四逆；邪气闭阻则脉鼓不通，见暴心腹痛；积气上逆则疝积时发上冲心。四者皆以“代不至寸口”为共同脉象基础，然气壅、", "c": "主气壅"}, {"id": "pc:寸+伏+乱", "n": "寸·伏乱脉", "o": "寸·伏乱脉总以脉象兼夹判断病机，其核心在于伏乱之中兼见数、迟、滑、涩、大、小、弦、紧等象，从而分属寒热虚实及五脏病位。原文以“脉数在腑、脉迟在脏”分表里寒热，以长弦、小、下坚上虚、滑微浮、大坚分属肝、心、脾胃、肺、肾，又以滑涩大小辨气血多少。可见伏乱脉所主非单", "c": "主热"}, {"id": "pe:寸+伏", "n": "寸·伏脉", "o": "寸·伏脉总起来主病机可归纳为积滞内阻、寒极阳衰、痰饮内闭、气郁阳微、脏虚阳浮及寒热虚实兼夹六类。其核心在于脉道被遏或鼓动无力，致寸部脉气伏匿不显。积滞、痰饮、气郁属邪实壅塞，脉道不通而伏；寒极阳衰、脏虚阳浮属正虚不鼓，脉气无力而伏；伏乱脉则因兼象不同而分属寒热", "c": "主积滞内阻"}, {"id": "pe:寸+动", "n": "寸·动脉", "o": "寸·动脉所主病机广泛，总以气机躁动不安为纲，可归纳为虚实两端。实证方面，动脉主燥屎内结、肝阳上冒、肺气壅闭、脾胃络病之实，皆因邪阻或阳亢致气机壅遏而脉动；虚证方面，主肾虚冲逆、脏气衰绝，因阴亏阳浮或脏气败绝而脉动无根。此外，胃气常动为生理之动，非病脉。各类之间", "c": "主燥屎内结"}, {"id": "pe:寸+和", "n": "寸·和脉", "o": "寸·和脉总以'和'为眼目，主病机可归纳为邪退正复、脾胃健旺、正虚邪恋、虚热内扰四类。其核心在于脉象和缓或寸关颇和，反映气机调畅、胃气尚存。邪退正复与脾胃健旺属向愈之象，前者见于热病后期邪退正复，后者为平人常脉或病中胃气来复；正虚邪恋与虚热内扰则属病态，前者因正", "c": "主邪退正复"}, {"id": "pe:寸+坚", "n": "寸·坚脉", "o": "寸·坚脉总起来主邪实内结、气机壅塞之病机，其病位多在上焦及脏腑深处。坚脉为邪气实结、脉道坚劲之象，结合兼脉与部位，可细分六类：邪壅肺卫者，寒热客气包裹肺俞，郁而化热；痰浊结聚者，顽痰胶固，壅塞肺胃；心脉失常者，或心火亢盛，或心气不足，或胃气已绝之危候；虚实夹杂", "c": "主邪壅肺卫"}, {"id": "pc:寸+大+动", "n": "寸·大动脉", "o": "寸部大动脉在此段总以虚大为纲，主气衰与心肾两虚。脉虚大而参伍不调，是脉行无力、气血不续之象；两寸十数至一歇，更直接对应心掣肾病，说明歇至根于心肾气虚而非风邪。由此虚损进一步可致肾藏真阳不足，水气上泛，出现颈脉大动、尿如煤水，将成水蛊。三类病机以气虚为始，心肾两", "c": "主气虚"}, {"id": "pc:寸+大+坚", "n": "寸·大坚脉", "o": "寸·大坚脉总起来主邪实内结、血气壅盛之病机，其病位在肾。大脉示气血俱多，坚脉示病深牢固，二者相合，非正常之盛，乃实邪与气血相搏，脉道充盈而坚劲。原文以“脉大而坚……病在肾”明确定位，说明此脉所主非表非腑，而是肾之实邪内结。三类病机相互关联：肾实是病位所在，血气", "c": "主肾实"}, {"id": "pc:寸+大+实", "n": "寸·大实脉", "o": "寸·大实脉总属邪热亢盛、实火内壅之象。其脉形大而有力，来盛去盛，为太过之脉，主病在外。所主病机以实热为核心，可具体分属胃火、肺热及火刑金等。右关实大主胃火刑金，右寸洪数主肺热，尺数大主肾火，左关弦数主肝火，左寸洪数主心火，诸部实大洪数皆火热亢盛之征。大实脉与洪", "c": "主实热"}, {"id": "pc:寸+大+小", "n": "寸·大小脉", "o": "寸·大小脉所主病机，总以寸部脉象之大小偏颇为核心，反映上焦与下焦、气与血、邪与正的失衡。其常见者，一为痰饮内阻，脉乍大乍小，痰气交阻而现怪异；二为阳气不潜，寸关大而尺小，上盛下虚，虚阳浮越；三为风火在上，寸大尺小，风火壅盛而下元不足；四为气血多少，脉大血气俱多", "c": "主痰饮"}, {"id": "pc:寸+大+弱", "n": "寸·大弱脉", "o": "寸·大弱脉总起来主虚，尤以气血不足、大虚之证为核心。原文两寸关脉大而弱，大则为虚，弱为气血不足；两尺脉涩而小，涩主血少，小主气虚。寸关候上中焦，尺候下焦，今上下皆见虚象，故断为气血不足、大虚之证。其具体病机可分三类：一主气血大虚，脉大而弱为虚损之象；二主脾胃虚", "c": "主气血大虚"}, {"id": "pc:寸+大+沉+伏", "n": "寸·大沉伏脉", "o": "寸·大沉伏脉总起来主痰气壅滞、中焦壅塞之实证。其脉象沉伏而大，沉伏为气机郁闭、痰浊内停，大则示痰浊搏结、邪实壅盛。原文明确指出'沉伏主痰气壅滞，大主痰浊搏结'，并强调'二脉皆示中焦壅塞、气痰交阻之机'。各类病机之间相互关联：痰气壅滞是核心，气结不行是气机郁滞的", "c": "主痰气壅滞"}, {"id": "pc:寸+大+洪+紧+急", "n": "寸·大洪紧急脉", "o": "寸·大洪紧急脉总起来主实热壅盛、血气俱多之证。其脉象大、洪、紧、急并见，大主血气充盛，洪主热盛，紧急主邪实，故以实热为核心病机。原文以“脉数在腑”分表里，数、疾属热；又“脉大者血气俱多”，滑主多血少气，故本脉亦主血多气少、血气偏盛。扁鹊谓“脉大而洪，出于心”，", "c": "主热"}, {"id": "pc:寸+大+洪", "n": "寸·大洪脉", "o": "寸·大洪脉总以阳热亢盛、气火上壅为基本病机，因寸候上焦，故多主心肺胸膈之热。其具体所主，或为单纯热盛，或为痰火相搏，或为湿热壅蒸，或为火盛迫血，皆属有余之实证；亦有虚阳上浮、上热下寒之变，则因下元虚衰、阳不潜藏而致。各类之间，实热与痰火、湿热、迫血常相兼夹，总", "c": "主热盛"}, {"id": "pc:寸+大+浮+涩", "n": "寸·大浮涩脉", "o": "寸·大浮涩脉总起来主邪热壅盛、气机郁滞，兼及胃气衰败。浮大主邪热壅盛于上，涩主气滞血少、郁结不通，二者并见则热郁于中，肺胃受累。若脉来无胃气柔和之象，如屋漏、雀啄等怪脉，则属脏气衰败之危候。两类病机一实一虚：实者为热壅气滞，虚者为胃气衰败，前者多见于病机分析，", "c": "主热壅气滞"}, {"id": "pc:寸+大+浮+短", "n": "寸·大浮短脉", "o": "寸·大浮短脉在本文段中主要与怪脉、死脉并论，其总病机为胃气败绝、脏真耗竭所致的危重脉候。原文通过屋漏、雀啄、弹石、解索、虾游、鱼翔等脉象，描述脉来坚急散乱、绝止复来、无柔和之象，说明脉气已失胃气与荣卫常道，脏气将脱。三类病机相互关联：胃气败绝是基础，脏真耗竭是", "c": "主胃气败绝"}, {"id": "pc:寸+大+浮+紧", "n": "寸·大浮紧脉", "o": "寸·大浮紧脉总属心脉失常之象。心为五脏之尊，主血属火，其平脉为钩。大浮紧脉出现于寸部，既可因心火亢盛、外邪束表而见太过之象，表现为身热骨痛、口疮舌焦等表实热盛证；亦可因心气不足、虚阳浮越而见不足之象，表现为烦躁咳唾气泄等内虚证。三类病机以心火为中心，太过与不足", "c": "主心火太过"}, {"id": "pc:寸+大+浮", "n": "寸·大浮脉", "o": "寸部浮大脉总以“阳浮气盛”为基本象义，但所主病机有虚实寒热之异。实者，或为气火上升、肝阳上扰，或为风热犯肺、热壅气分，或为热毒结胸、邪实壅盛，或为宿食内停、胃气不降，皆因浮大为阳、为热、为实，寸候上焦，故病多在上、在表、在气分。虚者，或为虚阳外浮、根本空虚，或", "c": "主气火上升"}, {"id": "pc:寸+大+浮+长", "n": "寸·大浮长脉", "o": "寸·大浮长脉在本文段中实以怪脉、死脉之象呈现，总起来主胃气败绝、脏真外泄与死候。其核心在于脉失胃气柔和之常，或如屋漏之绝而止，或如雀啄之数疾顿来，或如弹石之辟辟急，皆属无胃气之脉。三类病机相互关联：胃气败绝是根本，脏真外泄是病机演变，死候是最终转归。原文以“脉", "c": "主胃气败绝"}, {"id": "pc:寸+大+涩", "n": "寸·大涩脉", "o": "寸·大涩脉总起来主气滞血瘀、风阳上亢与风痰上扰，属虚实夹杂之候。涩为血瘀气滞之基，寸口大则示阳浮气逆，二者相合，既可见经行胀痛之瘀滞，又可见晕眩心涎之风痰上扰。其病机核心在于气血郁滞、阳亢风动，瘀滞与风阳相互影响：气滞血瘀则津凝痰生，风阳上亢则挟痰上扰。与下属", "c": "主血瘀气滞"}, {"id": "pc:寸+大+疾", "n": "寸·大疾脉", "o": "寸·大疾脉总起来主燥热内盛、阳动不潜与阴液亏虚。右寸关搏而疾大，直接反映阳明燥气鼓舞，燥热内迫；燥热伤阴，肺胃阴液未充，则阳易旋动，清窍失肃，血热妄行而衄血复发。三类病机相互关联：燥热为标，阴亏为本，阳动为中间环节，共同构成阴虚燥热、阳动血溢的病理格局。脉象疾", "c": "主燥热"}, {"id": "pc:寸+大+空", "n": "寸·大空脉", "o": "寸·大空脉总属虚实夹杂之象，以虚为本，以热为标。其脉大而空，主脉道不充，故所主病机主要有三：一为热盛津伤，邪热亢盛，耗伤津液，脉道不充而现空大；二为气阴两虚，气分热盛而津伤，或肺气虚浮无根，兼肾气涣散、精血亏耗；三为虚阳浮越，阳气虚衰，虚阳上浮，脉大而空，按之", "c": "主热盛津伤"}, {"id": "pc:寸+大+紧", "n": "寸·大紧脉", "o": "寸·大紧脉总属上焦病机，以邪实为主，兼见正伤。其脉象大紧，主寒、主痰、主实邪壅滞，皆因邪客上焦，气机不利，脉道拘急而致。如胸中有寒、膈上有痰、胸上诸实，皆宜吐法。然亦有正伤邪浅之候，如脉微弱主夏月伤冷水，微浮主胸中有寒而邪浅正伤。各类病机之间，以实邪为纲，寒、", "c": "主寒"}, {"id": "pc:寸+大+缓", "n": "寸·大缓脉", "o": "寸·大缓脉在古籍中与怪脉并列，总起来主胃气败绝、脏气竭绝之死候。原文以屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉为例，皆无胃气柔和之象，说明脉失冲和，脏气不能自荣卫运行，故脉来如群鸟之聚、悬石之落，出筋之上藏筋之下，不可知也。脉病人不病而见此类脉者死，强调胃气已", "c": "主胃气败绝"}, {"id": "pe:寸+大", "n": "寸·大脉", "o": "寸·大脉总主上焦邪气壅盛或阳热有余，因寸候上焦心肺，大则邪盛或热壅。其病机大致分实、虚两端：实者或为热盛，或为邪实壅上，或为痰火气逆，或为疟邪郁于肺卫，皆寸大有力，病位在上、在表、在气分；虚者或为虚阳上浮，或为上盛下虚，或为血瘀阴枯，皆寸大而兼尺弱、按涩等，反", "c": "主热盛"}, {"id": "pc:寸+大+虚", "n": "寸·大虚脉", "o": "寸·大虚脉总主虚实夹杂之候。其大而有力者，多主痰热壅肺，如右寸滑大搏指，为病气侵胎；其大而无力者，多主心肾气虚，如脉虚大而参伍不调，为气衰脉行无力。两类虽同见大脉，但一实一虚，病机迥异。实者因痰热壅阻，虚者因气衰不运，临证当参合脉势与兼症，辨其虚实而治。", "c": "主痰热壅肺"}, {"id": "pc:寸+大+长", "n": "寸·大长脉", "o": "寸·大长脉总起来主气火有余、邪热亢盛、阳亢上逆及阴损及阳。其核心病机为厥阳上燔、气火上升，脉道充盈而见长大透寸。情志所动、春分阳升为诱因，热邪鼓动气血则脉大，阳亢上逆则脉长透寸。虽血止而脉仍长大，示厥阳未敛；食物不欲纳、寐中呻吟呓语，由至阴损及阳明，精气神不相", "c": "主气火有余"}, {"id": "pe:寸+实", "n": "寸·实脉", "o": "寸·实脉总起来主邪实壅盛于上焦，以实热为核心，兼及痰食、火刑金、热壅上焦及虚实夹杂。实脉为邪气盛、脉道壅实之象，寸部候心肺与上焦，故实脉见于寸，多主上焦实热壅盛，非虚火可比。其具体病机可分五类：实热壅盛者，火热亢盛于上；痰食壅阻者，滑实并见，痰热食积壅于上中二", "c": "主实热壅盛"}, {"id": "pc:寸+小+濡", "n": "寸·小濡脉", "o": "寸·小濡脉在此案中并非单见，而是与右细耎无力、左寸涩、关弦数并见，共同反映素体阴亏阳弱、相火上炎、水不养木的复杂病机。其总主病机以肾阴亏虚为核心，兼见脾肺气虚、心血不足、肝火内郁。尺脉濡小直接提示肾阴亏虚，为病之本；肾阴不足，水不养木，则肝火内郁，关脉弦数；木", "c": "主肾阴亏虚"}, {"id": "pc:寸+小+紧+实", "n": "寸·小紧实脉", "o": "寸·小紧实脉总起来主邪实内结、寒凝气壅而兼血少之病机。其“紧”应寒，“实”应邪盛，“小”应血少，三者相合，提示寒实内结、肾气实而血不足。原文以脉大而坚病在肾，扁鹊云小而紧，说明小紧实脉与肾实相关；又“脉小血少”“脉涩少血多气”示小脉主血少、紧实主气盛。故本脉所", "c": "主肾实"}, {"id": "pe:寸+小", "n": "寸·小脉", "o": "寸·小脉总以寸部脉体偏小为特征，所主病机可归纳为心阳不足、气血两虚、虚寒、阴虚火旺及痰浊内郁五类。其核心在于正气不足，或阳气虚弱鼓动无力，或阴血亏少脉道不充，故寸脉显小。虚寒类强调阳衰寒凝，阴虚类侧重阴亏火旺，二者一寒一热，然皆本于虚。痰浊内郁者，寸小为正气不", "c": "主心阳不足"}, {"id": "pc:寸+小+软", "n": "寸·小软脉", "o": "寸·小软脉总起来主气火虚而兼痰火实，属本虚标实之候。其脉形软小不疏、濡小无力，反映正气不足、气火俱虚，推动无力；而关部滑数又示痰火内蕴，虚实并见。故其病机可归为三类：一为气火虚，二为虚实夹杂，三为痰火内蕴。三者相互关联：气火虚为本，痰火实为标，虚不运痰则痰火愈", "c": "主气火虚"}, {"id": "pe:寸+平", "n": "寸·平脉", "o": "寸·平脉虽以平为名，但所抽样段落多示病脉，总起来主热、虚、火亢、气机失调及津伤。其中热与火亢常相兼，如左寸数疾为心火炽盛；虚则见软大或虚数，为气阴不足、虚阳外浮；气机失调见长、弦急，主气有余或木侮土；津伤则由邪热耗损，脉弦舌干。各类之间，热盛可致津伤，火亢必兼", "c": "主热"}, {"id": "pc:寸+弦+大", "n": "寸·弦大脉", "o": "寸·弦大脉总以弦、大二象合见为特征，主肝郁化火、肺热壅盛及阴亏火旺。弦为肝郁之象，大主阳热亢盛，寸口候心肺，故病位多在心肺肝。原文'脉弦右寸大'伴咽痛、呛咳、寒热不清、舌黄红，示肝郁化火，木火刑金，肺热壅盛，郁热未清，灼伤阴分，故宜防喉燥。三类病机相互关联：肝", "c": "主肝郁化火"}, {"id": "pc:寸+弦+大+虚+缓", "n": "寸·弦大虚缓脉", "o": "寸·弦大虚缓脉总属阴虚劳怯、咳嗽失血之候。其脉象虽见弦大，然必兼虚缓或软数，非实邪之弦。所主病机以阴虚为本，虚火为标：阴亏则脉道不充，故虚缓；虚火内扰，则脉数而弦大；肺肾阴伤，则脉小不劲。三类病机相互关联，阴虚火旺与虚火内扰常并存，肺肾阴伤为根本，总以阴精亏虚", "c": "主阴虚火旺"}, {"id": "pc:寸+弦+小", "n": "寸·弦小脉", "o": "寸·弦小脉总起来主痰积郁滞、气机不畅，兼见大肠不固之病机。其脉象弦小，弦主气郁，小主收引，反映气机郁滞、痰浊内阻；结合右寸滑、按之如黄豆大且鼓指，明确为积痰郁滞于肺。痰积上焦，肺失肃降，通调失职，则大肠之气不固，故见食后即大便。三类病机中，痰积为病之本，气郁为", "c": "主痰积"}, {"id": "pc:寸+弦+微", "n": "寸·弦微脉", "o": "寸·弦微脉总起来主上焦邪实而正气略伤之证，以寒、水、痰、气逆四类病机为主。微浮主寒邪在胸，微弱主水湿伤阳，紧不大主痰结膈上，微弦主气逆胸实，四者皆邪在上焦、病位偏表偏上，故张机并主以吐法。诸类之间，寒、水、痰、气逆可相兼为患，总因上焦阳气不布、邪实阻滞，脉见微", "c": "主寒饮"}, {"id": "pc:寸+弦+急", "n": "寸·弦急脉", "o": "寸·弦急脉总属气机郁滞、脏腑失调之象，其病机涉及多个层面。弦为肝脉，急主气迫，寸部见之，首先反映上焦气郁与火邪为患，如右寸弦急主气郁胸中、肺失宣降；左右寸口弦劲则为火乘金，灼伤肺阴。其次，弦急见于关部，为肝木横逆、侮脾犯土，导致食少体瘦。再者，左尺虚数提示肾水", "c": "主火乘金"}, {"id": "pc:寸+弦+急+长", "n": "寸·弦急长脉", "o": "寸·弦急长脉在此段中主要与死脉、怪脉并见，总属胃气败绝、脏气衰微之危候。弦急长本为有余之象，但若失柔和而兼屋漏、雀啄等怪脉，则非实热，而是真脏气露、胃气将绝之兆。原文强调‘脉病人不病’而见此类脉者死，说明脉象已脱离常度，反映脏腑功能衰竭、阴阳离决。三类病机相互", "c": "主胃气败绝"}, {"id": "pc:寸+弦+沉", "n": "寸·弦沉脉", "o": "寸·弦沉脉总起来主水亏阳亢与伏饮两类病机。沉为水亏、主伏，弦为肝阳亢逆、主饮，二者相合，既可因水亏营弱、龙雷之火并发而见肝阳上冒之厥证，又可因寒饮内伏、阳气阻绝而见上焦中脘凝塞之伏饮。两类病机虽一虚一实，但均以沉弦为共同脉象基础，反映了水液代谢失常与阳气不布的", "c": "主水亏阳亢"}, {"id": "pc:寸+弦+浮", "n": "寸·弦浮脉", "o": "寸·弦浮脉总主上焦痰饮、肺气上逆，兼涉风邪、疼痛气滞及上实下虚之候。浮为阳、主表、主上，弦为阴、主饮、主痛、主风，二脉相合，病位多在寸部（肺、心、上焦），病性多属本虚标实。其核心病机为痰饮聚于上焦，肺失宣降，故咳喘胸闷；若新感引动，则兼风邪在表；若气机阻滞，则", "c": "主痰饮"}, {"id": "pc:寸+弦+涩", "n": "寸·弦涩脉", "o": "右寸弦涩脉总起来主气郁、痰浊、饮邪与积滞，核心病机为痰热积滞壅阻肺胃、气机闭郁、肺气不宣。弦主气郁、饮邪与痛，涩主血行不畅、痰浊阻滞，二者并见，提示实邪内阻、气血壅滞。原文所述伏气暑湿夹积，病甚于里，腑受则泄，神识昏糊、不语、热势内炽、腹板硬拒按、咳嗽不扬而声", "c": "主气郁"}, {"id": "pc:寸+弦+滑+和", "n": "寸·弦滑和脉", "o": "寸·弦滑和脉总起来主气郁、痰湿及肝胃不和。弦主气机郁滞，滑主痰湿内蕴，二脉合见，多因肝气郁结、横逆犯胃，致脾胃运化失司，痰湿内生，形成肝胃不和、气滞痰阻之证。原文左寸关弦、右关弦滑，恰应肝郁与脾胃痰湿；弦象稍退、脉转柔和，则郁滞稍解、痰湿渐化，胀满渐舒。三类病", "c": "主气郁"}, {"id": "pc:寸+弦+滑+浮", "n": "寸·弦滑浮脉", "o": "寸·弦滑浮脉总起来主痰实于上、微兼客热，并常与阴虚于下并见。其弦滑主痰实，浮主客热，而左关尺细软无神又提示下元阴虚。三类病机相互关联：痰实壅上可致气机不利，客热外扰加重痰嗽喘逆，阴虚于下则根本不足，形成上实下虚、攻补难施之候。故临床见此脉象，需权衡痰、热、虚三", "c": "主痰实"}, {"id": "pc:寸+弦+滑", "n": "寸·弦滑脉", "o": "寸·弦滑脉总起来主痰、气、食、郁相互搏结于上中二焦的病机。弦为气机郁滞，滑为痰涎内蕴，二脉合见于寸部，提示病位偏上，多因肝气郁结、横逆犯胃，或寒温失调、饮食不节，致脾胃运化失司，痰湿食滞内生，气机不利，形成痰气交阻、肝胃不和之证。其具体表现可偏于痰积、气滞、痰", "c": "主痰积"}, {"id": "pc:寸+弦+紧", "n": "寸·弦紧脉", "o": "寸·弦紧脉总起来主风寒外客、疼痛、寒积内结及津亏内伤。弦主风、主痛，紧主寒，寸关见之，首为风寒客于肌肤，故见蒸蒸发热、盗汗；寒性收引，气血不通则痛；若沉紧，则寒邪内结，心下寒痛有积；若病久不愈，风寒化热伤津，则津液渐亏，转为内伤黄瘦。四类病机以风寒外袭为始，进", "c": "主风寒表证"}, {"id": "pc:寸+弦+细+大+洪", "n": "寸·弦细大洪脉", "o": "寸·弦细大洪脉总起来主中气虚、肝郁气结与痰滞机窍三类病机。前诊脉细弦而不洪大，与虚里跳动相应，主中气虚不能制木；服攻劫后右部脉转滑微大，寸脉依然细滞，说明肝郁气结，气郁则痰滞，痰踞机窍，阻神明、乱魂魄。三类之间相互关联：中气虚为本，不能制木则肝郁，肝郁气结则痰", "c": "主中气虚"}, {"id": "pc:寸+弦+细", "n": "寸·弦细脉", "o": "寸·弦细脉总起来主虚劳，以阴阳两亏为核心病机。其脉弦细乏力，反映肝血不足、脾肺气虚、肾阳衰微等多脏虚损。右寸微、关虚小、尺软如绵，示肺脾大亏、肾阳不足；左脉弦细乏力，示心肝久虚、肾阴不足。诸虚互见，导致咳嗽有汗、食减便溏、寒热交作、天癸未通等症。各类病机相互关", "c": "主虚劳"}, {"id": "pc:寸+弦+细+虚+涩+短", "n": "寸·弦细虚涩短脉", "o": "寸·弦细虚涩短脉总起来主肺气不足、气血虚少、脾虚湿困与气滞湿阻四类病机，核心为虚中夹滞、本虚标实。寸脉短直接主肺气不足，肺虚宣降失职则咳嗽；右脉弦细兼涩主血少气滞，细涩为血虚不充、流行不利；关脉虚主脾胃虚弱，脾虚失运则湿盛，故见四肢沉重、减食、腹中痛、面黄汗多", "c": "主肺气不足"}, {"id": "pc:寸+弦+细+虚+涩", "n": "寸·弦细虚涩脉", "o": "寸·弦细虚涩脉总起来主虚中夹滞、本虚标实之证。其核心病机为肺气不足、气血虚少、脾虚湿困与气滞湿阻四类。寸脉短直接主肺气不足，肺虚宣降失职则咳嗽；右脉弦细兼涩主血少气滞，细涩为血虚不充、流行不利；关脉虚主脾胃虚弱，脾虚失运则湿盛，故见四肢沉重、减食；弦细涩又应气", "c": "主肺气不足"}, {"id": "pe:寸+弦", "n": "寸·弦脉", "o": "寸·弦脉总属肝气为病，以气机郁滞为核心，兼涉火、痰、湿、虚、热诸端。弦为肝脉，寸口见弦，首主肝郁气结，情志不遂、气机不畅；郁久则化火，故主气郁化火，火性上炎而见寸口弦劲；肝木亢盛则乘脾侮肺，故主木乘土金；气郁津凝则痰饮湿阻，故主痰饮湿阻；若弦而兼细数虚弱，则主", "c": "主肝郁气结"}, {"id": "pc:寸+弦+芤", "n": "寸·弦芤脉", "o": "寸·弦芤脉总属阴虚兼肝郁之候，以阴血不足、肺阴亏虚为本，肝郁气滞为标。弦主肝郁，芤主阴血不足，寸口见芤尤关肺阴亏虚，三者相合，揭示阴虚肺燥、虚火上炎之病机。原文'脉弦寸口芤，呛咳咽痛，舌白尖赤'，症属阴虚，宜防喉燥，说明此脉虽主阴血亏虚，但兼有肝郁气滞，气郁化", "c": "主肝郁"}, {"id": "pc:寸+弦+虚", "n": "寸·弦虚脉", "o": "寸·弦虚脉总属虚证，以阴血不足、气阴两虚为基础，兼见虚火与痰湿。其核心病机为“水少于火，阴阳未平”，即肾水亏虚、肝阴不足，虚火内动；同时肺气不足、脾虚痰蕴，形成气阴两伤、虚痰内扰之候。各类之间相互关联：阴虚火旺为根本，气阴两虚为发展，虚痰内蕴为兼夹。脉象上，虚", "c": "主阴虚火旺"}, {"id": "pc:寸+弦+迟", "n": "寸·弦迟脉", "o": "寸·弦迟脉总属胸中实邪或寒饮停聚、阳气郁遏之候。弦主饮、主痛、主气机郁滞，迟主寒、主阻滞，寸部候胸中，故弦迟并见，多因实邪或寒饮结于胸膈，阻遏胸阳，使脉气不利、阳气不布。其所主病机可归为三类：胸中实邪阻滞、寒饮停聚胸膈、阳郁不布。三者相互关联，实邪与寒饮为病之", "c": "主胸中实邪"}, {"id": "pc:寸+弦+长", "n": "寸·弦长脉", "o": "寸·弦长脉总属肝木亢盛、气机逆上之象。弦为肝脉，长为气盛，见于寸部且直上鱼际，则肝木亢逆不下，形成‘亢而不下’之势。其病机类别主要有五：一为肝木亢逆，二为木乘金（肝木乘肺金），三为痰火内蕴（弦长兼滑），四为下元不足（上盛下虚，尺弱），五为肝病总属。各类之间相互", "c": "主肝木亢逆"}, {"id": "pc:寸+弱+动", "n": "寸·弱动脉", "o": "寸口弱动脉（以沉弱为主）总属虚证，主气血不足、阳气虚衰。其脉象沉而无力，反映正气内虚，脏腑功能减退。所主病机主要有三类：一为寒热，因虚而营卫失调；二为疝瘕，因气虚寒凝、气机不畅；三为腹痛，因虚寒内盛、脏腑失养。三者皆以虚为本，或兼寒、兼滞，但总不离乎正虚。弱脉", "c": "主寒热"}, {"id": "pc:寸+弱+急", "n": "寸·弱急脉", "o": "寸·弱急脉总起来主正虚邪亢、本虚标实之候。弱脉主气血亏虚，尤以肺肾并亏为著；急脉主肝木躁动，失于柔顺。二者相合，反映虚体而肝木偏亢，进而侮土，形成肺肾亏虚、肝脾不调之复杂病机。原文肛漏日久，阴耗阳伤，咳嗽恶寒、咽痛妨食、腹痛便溏，脉见尺寸弱而急，正虚与木亢并存", "c": "主虚"}, {"id": "pc:寸+弱+短", "n": "寸·弱短脉", "o": "寸·弱短脉总以寸部短弱为共同特征，核心病机是上焦心肺气虚。短主气损，弱主气虚，寸主上焦，故凡两寸或左寸短弱，皆提示心肺元气不足、神气不充。在此基础上，因兼脉不同而派生多类病机：兼关尺滑、洪滑者，为气虚不能运化，湿痰下流；兼关尺洪数、滑大者，为痰火湿热壅盛于中下", "c": "主上焦气虚"}, {"id": "pe:寸+弱", "n": "寸·弱脉", "o": "寸·弱脉总以寸部无力为特征，核心病机是上焦心肺气虚。弱主虚，寸候上焦，故凡寸弱皆提示心肺元气不足、神气不充。在此基础上，因兼脉及部位不同而派生多类病机：兼关尺滑大者，为气虚不运、痰食壅滞，成虚中夹实；兼尺强或寸强尺弱者，为下元虚而虚阳上浮，成上盛下虚；兼细涩者", "c": "主气虚"}, {"id": "pc:寸+弱+软", "n": "寸·弱软脉", "o": "寸·弱软脉总属正虚，以气虚、气血不足为核心，寸候心肺，软弱无力即上焦气衰血少。其主病机可分五类：主气虚、主气血两虚、主虚中夹实、主气不摄血、主上焦虚损。诸类皆以虚为本：气虚则血弱，故气血两虚并见；气虚不能摄血，则血热妄行而崩漏；上焦虚损则气满汗泄不寐；若兼他部", "c": "主虚中夹实"}, {"id": "pc:寸+微+伏", "n": "寸·微伏脉", "o": "寸·微伏脉总起来主气机郁滞与阳气衰微两类病机。微伏之象，一由情志忧思，气结不展，心脉不畅，属气郁实证之轻；一由阳气衰微，不能鼓动，伏匿不显，属阳衰危候。二者虽同见微伏，但一因郁遏，一因虚衰，病机虚实迥异。原文以忧思致病与死证对举，提示微伏脉须结合整体辨其虚实：", "c": "主气郁"}, {"id": "pc:寸+微+弱", "n": "寸·微弱脉", "o": "寸·微弱脉总起来主虚，兼及虚中夹邪。其核心病机为心肺气虚、胸中大气下陷，故见短气、四肢痿废；进而属五脏虚损，正气内衰；若兼迟则虚寒与气血不足，冲任空虚而绝子不产。另一方面，寸微弱亦可见于暑湿伤中、水行皮中，或寒痰邪实壅塞上焦、阳气被遏之胸中痞硬，此属虚中夹实、", "c": "主气虚下陷"}, {"id": "pc:寸+微+弱+迟", "n": "寸·微弱迟脉", "o": "寸·微弱迟脉总属虚寒与气血不足之象。迟脉主阳气不足，微弱主气血俱虚，寸部候上焦心肺，寸脉微弱则心肺气虚、气血生化无源。三者相合，反映阳气虚衰、气血亏虚、冲任空虚的整体病机。原文以此脉象断“绝子不产”，说明其病机核心在于虚寒与气血亏虚导致胞宫失养、生殖功能低下。", "c": "主虚寒"}, {"id": "pc:寸+微+涩+小+短", "n": "寸·微涩小短脉", "o": "寸·微涩小短脉总属虚候，主五脏虚衰、气血不足及阳虚外浮。其脉象轻取或滑，重按微涩小短，反映虚阳浮越于上而根本内亏。所主病机以脏虚为核心：微为气衰，涩为血少，小短为脉道不充，合而示正气内衰；举指滑而按之微，又示虚阳外浮、不能内守。三者相互关联：脏虚为根本，气血不", "c": "主脏虚"}, {"id": "pc:寸+微+涩", "n": "寸·微涩脉", "o": "寸·微涩脉总属气血不足、荣卫两虚之候，兼见阳虚寒乘与热郁血涩两类变局。微为阳气衰微、卫气不行，涩为荣血不足、脉道涩滞，故其本在气血两虚、荣卫俱弱。若阳虚较甚，阴寒上入阳中，则见洒淅恶寒；若兼上焦热盛，两寸独大，则热郁血涩，本虚标实，可见经闭、腹胀、消渴、便结等", "c": "主荣卫两虚"}, {"id": "pc:寸+微+缓", "n": "寸·微缓脉", "o": "寸·微缓脉总属气血两亏、元气虚弱之象。微为阳气衰微，缓为气血不足，寸尺俱见微缓，突出久病耗伤、正气亏虚的本质。在此三则医案中，微缓脉均出现于泄痢一载之后，提示气血双亏，元气无力运行，致使痰积、湿热、肝气等病邪胶结不解，形成本虚标实、攻补两难之局。因此，微缓脉所", "c": "主气血两亏"}, {"id": "pe:寸+微", "n": "寸·微脉", "o": "寸·微脉总起来主上焦阳气虚衰与气机失守，兼及寒痰实邪壅遏胸中。其核心病机为“微”象所反映的正气不足——或肺气亏虚、或神气浮散、或下焦阳衰饮逆、或荣卫两虚；然寸部独微又常与实邪阻遏相关，如寒痰壅胸之寸微浮、热结深伏之寸更微，皆因邪阻而脉道不利，非纯虚可比。各类之", "c": "主虚损"}, {"id": "pe:寸+急", "n": "寸·急脉", "o": "寸·急脉总起来主邪气亢盛、气机逆乱之病机，其核心为“急”象所反映的经气拘急、阳气张大或寒凝收引。具体而言，寸急可因外风上扰、痰壅上焦、肝阳上逆、气郁火乘、痰气寒痛等实邪为患，亦可因正虚邪亢、下元亏虚而现上实下虚之局，或下焦虚寒、筋脉拘急。各类病机之间相互关联：", "c": "主风邪上扰"}, {"id": "pe:寸+散", "n": "寸·散脉", "o": "寸·散脉总属虚证，以正气耗散、气不收敛为核心。其主病机可分四类：气阴两伤、心气虚浮、里虚气耗、虚实夹杂。气阴两伤多见于热病或劳倦色欲后邪退正伤，脉散而寸虚；心气虚浮由君火衰微、神不守舍所致，虚阳外浮；里虚气耗以沉散为征，示阴阳不相维系；虚实夹杂则在正虚气散基础", "c": "主气阴两伤"}, {"id": "pc:寸+数+促", "n": "寸·数促脉", "o": "寸部促数脉总属热盛，但具体病机有实热、虚火、热壅肺气及气机不调之别。数脉主热，促脉示脉来数中一止、节律不匀，故促数并见首先反映热邪亢盛。若见于右寸，因寸部候肺，多主风温等温邪壅肺、误汗劫津，热壅肺气而气机不调，甚则危候；若见于两寸而伴形体日损、咳嗽吐痰，则属虚", "c": "主虚火"}, {"id": "pc:寸+数+动", "n": "寸·数动脉", "o": "寸·数动脉总起来主阴虚阳浮，兼胃阴虚。其核心病机为真阴不足，不能自旺于本宫，阴不制阳，导致五志之阳升动无制，虚热内扰。动为阳浮不宁，数为热扰，合见于寸口，反映虚阳上浮、热扰心神之象。阳升无制则耗伤津液，胃阴受灼，故兼见胃阴虚。两类病机相互关联：阴虚为本，阳浮为", "c": "主阴虚阳浮"}, {"id": "pc:寸+数+和", "n": "寸·数和脉", "o": "寸·数和脉总以数象为纲，主热，然'和'字为眼目，示热势不剧而渐缓。其病机有三：一为邪热渐退，数而和缓，为向愈之兆；二为下焦气机升发，尺脉敛起上行，反映气机欲复；三为中焦气机偏盛，右关大，热郁于中。三者相互关联，总属热病过程中邪退正复、气机调整之候，非纯实热亢盛", "c": "主热势渐缓"}, {"id": "pc:寸+数+大+浮", "n": "寸·数大浮脉", "o": "寸·数大浮脉总主热邪为患，以数主热、大主盛、浮主表为基本脉理。其病机类别包括热盛、表热、气分热及热在上焦，四者相互关联：浮大数并见为热在经络表分；大数属气，示热在气分；寸部数大则热在上焦。原文又言'沉大而数，热已深入'，反衬浮大数主表热；'细数者血'，反衬大数", "c": "主热盛"}, {"id": "pc:寸+数+大+空", "n": "寸·数大空脉", "o": "寸·数大空脉总属肺阴亏虚、虚热内扰之象。右寸候肺，脉数主热，空大主阴气不足、脉道不充，故其核心病机为肺阴亏虚，虚热内生。然原文又指出兼有阳明胃经湿热薰蒸之气，此湿热可上扰及肺，与虚热并存。故本脉所主以肺阴亏虚为本，虚热为标，并可兼见胃中湿热。三类病机中，肺阴亏", "c": "主肺阴亏虚"}, {"id": "pc:寸+数+大", "n": "寸·数大脉", "o": "寸·数大脉总以数主热、大主盛、寸候上焦为基本脉理，总主热邪为患，但随兼脉与部位不同，可分见热盛、火盛伤阴、肺热壅盛、胃火刑金、三焦燥火及虚热内扰等类。数大并见，首先示火热亢盛，可涉气分、上焦及肺胃；火盛则耗阴，故又见火盛伤阴、阴虚火旺之机。右寸数大偏主肺热，寸", "c": "主热盛"}, {"id": "pc:寸+数+实", "n": "寸·数实脉", "o": "寸·数实脉总属上焦实热壅遏之候。数主热盛，实主邪壅，寸部候心肺，故其核心病机为热邪壅阻上焦、心肺气机失降。原文见两寸实数而微热而嗽，夜热尤甚，正因入夜阴气当降而热不降，热郁上焦所致。由此可衍三类：一为实热壅盛，非虚热可比；二为热郁不降，气机失于宣降；三为邪壅心", "c": "主上焦实热"}, {"id": "pc:寸+数+小+紧", "n": "寸·数小紧脉", "o": "寸·数小紧脉在《伤寒论》胸痹条文中，总属阳微阴弦、痰饮痹阻之候。其病机核心为胸阳不振、寒饮搏结、痰饮痹阻胸中。寸脉沉而起，主胸阳不足、饮邪内停；关脉小紧数，主中焦寒饮搏结、气机紧束而迫。三者相互关联：胸阳不振为病之本，寒饮搏结为病之标，痰饮痹阻为病之果。脉症合", "c": "主胸阳不振"}, {"id": "pc:寸+数+小", "n": "寸·数小脉", "o": "寸·数小脉总起来主本虚标实、虚实夹杂之病机。数主热，小主虚，故其核心为虚热并存。具体而言，左寸数小主肺虚有热，津伤成痿；右寸关小数主脾弱湿郁化热；左关弦为肝升太过、气火有余；右关数疾大弦滑主胃实痰热。各类之间相互关联：脾弱湿生为湿郁化热之源，肝升太过致气火交争", "c": "主肺虚有热"}, {"id": "pc:寸+数+弦+大", "n": "寸·数弦大脉", "o": "寸·数弦大脉总以数、弦、大三象合见为特征，主热、主心肝火旺、主阴亏火旺、主谋虑伤神。数脉主热，为基本脉象；弦大为心肝阳扰之征，左寸关候心肝，故弦大偏见于左寸关。诸类之间相互关联：谋虑伤神、过扰心阳可致心肝火旺；火旺耗阴，则成阴亏火旺；阴虚不能制阳，虚火内扰，又", "c": "主热"}, {"id": "pc:寸+数+弦+小", "n": "寸·数弦小脉", "o": "寸·数弦小脉总起来主本虚标实、湿浊与气火交争之病机。其脉象小弦而数，小主正虚，弦主气机郁滞与肝病，数主热与火。结合原文，体肥多湿多痰、嗜酒伤阳，阳虚气弱为本，脾不运行、湿浊灌塞为标，故脉小弦数反映脾胃湿浊尚盛；左关弦则肝家气火多升少降，为气火偏亢之象。三类病机", "c": "主湿浊"}, {"id": "pc:寸+数+弦+弱", "n": "寸·数弦弱脉", "o": "寸·数弦弱脉总起来主肺肾阴亏、络有蕴热之证。其脉象寸关弦数，尺部弱，弦数为热为阳亢，弱为阴亏，合而观之，乃阴液不足于下，火热蕴结于上。所主病机可归为三类：一为阴虚内热，二为筋脉失濡，三为肺热叶焦。三者相互关联：肾阴亏虚为本，导致肺热叶焦，肺热又灼伤阴津，加重阴", "c": "主阴虚内热"}, {"id": "pc:寸+数+弦+浮", "n": "寸·数弦浮脉", "o": "寸·数弦浮脉总主外感风邪、热郁上焦之证。浮为邪在表，弦主风，数为热，右寸独见则病位在肺卫上焦。三者相合，示新感外邪（风寒或暑风）引动，邪郁肌表，化热入里，风热搏结于上焦。原文“寒热三四日，头胀咳嗽，小溲赤”即外邪化热、肺失宣降之象。三类病机相互关联：外感风邪为", "c": "主外感风邪"}, {"id": "pc:寸+数+弦+细", "n": "寸·数弦细脉", "o": "寸·数弦细脉总起来主肝火、痰浊与阴伤相互纠结之病机。左脉弦细而数，反映肝家有火、阴分受灼；右脉寸关滑大，反映肺胃痰浊壅盛。三者关系密切：饮食阻滞于胃，郁而化火，火炼津液成痰，痰火纠结，外触风寒则上干于肺而咳。脉象左右分见，正合肝火与肺胃痰浊纠结不清之候。故其病", "c": "主肝火"}, {"id": "pc:寸+数+弦", "n": "寸·数弦脉", "o": "寸·数弦脉总以弦为肝郁气逆、数为热象为纲，所主病机可归纳为肝郁化火、少阳邪热、阴虚火旺、痰热壅肺、风暑郁热及虚阳浮越六类。其形成或由情志郁结化火，或由外邪传至少阳，或由阴液亏虚、相火偏亢，或由痰湿郁久化热，或由风暑相搏、郁热内扰，或由元气虚损、虚阳浮越。诸类之", "c": "主少阳邪热"}, {"id": "pc:寸+数+弦+虚+小", "n": "寸·数弦虚小脉", "o": "寸·数弦虚小脉总属阴虚劳怯之候，其病机核心为阴液亏虚、虚火内扰。脉数而弦，为虚火内动；虚小无力，为阴亏阳不亢；软数或弦大以数，则虚火扰于肺肾或心肝。三类病机相互关联：阴虚火旺为总纲，肺肾阴伤为具体病位，虚劳为病势转归。脉象虽兼数、弦、虚、小、软、大之不同，皆不", "c": "主阴虚火旺"}, {"id": "pc:寸+数+弦+虚", "n": "寸·数弦虚脉", "o": "寸·数弦虚脉总属热盛兼虚之候，其病机以热为核心，兼涉痰、郁、虚。数脉主热，弦脉主郁主肝胆，虚脉主不足。原文脉见右寸关滑数上溢、左手弦数，滑数为暑热壅肺、痰热内蕴，弦数为热郁肝胆，诸脉并见示热邪充斥肺肝气分，痰热交阻。若兼虚软、虚小，则又为阴虚火旺、肺肾阴伤之虚", "c": "主暑热壅肺"}, {"id": "pc:寸+数+弦+虚+软", "n": "寸·数弦虚软脉", "o": "寸·数弦虚软脉总属阴虚火旺、肺肾阴伤之候。其脉象以虚、弦、软、数并见为特征，虚为阴亏，弦为火旺，软为不足，数为热象。原文所举'脉小不劲''虚弦软数''左寸关弦大以数''脉来小数虚弦'等，皆围绕阴虚劳怯、咳嗽失血而言。三类病机相互关联：阴虚火旺为病机之根，肺肾阴", "c": "主阴虚火旺"}, {"id": "pc:寸+数+弦+软", "n": "寸·数弦软脉", "o": "寸·数弦软脉总属温邪为患，热壅上焦与气郁痰滞并存之候。其脉象以寸数、弦软并见为特征：寸数主热壅于上，热势鸱张；弦软主气郁痰滞，痰热互结。原文所举'脉来弦软而寸数''弦软主气郁痰滞，寸数主热壅于上''弦软为温邪挟痰、气机不畅，寸数主热壅上焦'等，皆围绕春温双传证", "c": "主热壅上焦"}, {"id": "pc:寸+数+微+紧", "n": "寸·数微紧脉", "o": "寸·数微紧脉总主热、虚、邪聚三类病机。数脉为热之共性，贯穿肺痿、肺痈诸证；虚为津液重亡、肺叶焦枯，见于肺痿；紧为邪聚血壅，微紧示邪聚未成脓，紧甚则肉腐成脓，见于肺痈。三者相互关联：热邪伤津则虚，热与风搏、气血稽留则紧，虚与紧皆以数脉为背景，共同反映肺脏风热内感", "c": "主热"}, {"id": "pc:寸+数+沉+小+紧+迟", "n": "寸·数沉小紧迟脉", "o": "寸·数沉小紧迟脉见于胸痹病，总属上焦阳气不振、寒饮内停、寒凝阳郁之证。寸脉沉迟，主里主寒，示胸阳不足、寒饮停聚；关上小紧数，紧主寒凝，数主阳郁，示寒饮阻遏、气机不利。三类病机相互关联：胸阳不振为根本，寒饮内停为病理产物，寒凝阳郁为气机表现，共同导致胸痹喘息咳唾", "c": "主寒饮内停"}, {"id": "pc:寸+数+沉", "n": "寸·数沉脉", "o": "寸·数沉脉总以数主热、沉主郁为纲，所主病机不离热郁与燥火。热郁于中焦则胃火滞而寸数大，燥火伤三焦则寸浮数、关洪数、尺沉数，甚则伤气脉大数、伤血脉细数。若见于左寸，则专主心痹，沉数为心痛心热，散大为失志失血。诸类皆以热为核心，或郁于中，或燥伤津，或扰于心，而沉数", "c": "主热郁于中"}, {"id": "pc:寸+数+洪", "n": "寸·数洪脉", "o": "寸·数洪脉总以火热亢盛为纲，洪为阳盛之象，数为热炽之征，合而主实热、火邪为患。其病位广泛，随寸关尺分部而异：右寸主肺热壅盛，左寸主心火亢盛，右关主胃火积热，两尺主肾火妄动；又可因热毒壅遏上焦而见温毒，燥火伤津而致三消，阳热乘金而发瘅疟。诸类之间，皆以火为枢机，", "c": "主肺热壅盛"}, {"id": "pc:寸+数+浮+硬", "n": "寸·数浮硬脉", "o": "寸·数浮硬脉总起来主气机壅滞、郁热内蕴与水湿不化，三者相互关联。浮为气失舒运、病位在表分，数为郁热，硬为气机壅滞不柔。原文右寸关浮数而硬，因疟后肺脾两经之气失于舒运，气滞则水湿不化而肤肿，气郁则热不得透而脉数。故其病机以气滞为核心，气滞导致郁热与水湿，三者并存", "c": "主气滞"}, {"id": "pc:寸+数+浮", "n": "寸·数浮脉", "o": "寸·数浮脉总以浮主表、数主热为纲，寸部候上焦，故其病机多聚焦于上焦热证。然具体所主，须结合兼脉、按力及分部合参。若浮数有力，多主风热在表或燥火伤上，症见发热、咽痛、咳嗽、龈肿等；若专见于寸而主肺，则为肺热痿软。若浮数兼尺涩，则热伤血络，下利脓血；若浮数按之无力", "c": "主风热在表"}, {"id": "pc:寸+数+滑+实", "n": "寸·数滑实脉", "o": "寸·数滑实脉总主宿食内停、邪实于中。数主热，滑主食，实主邪盛，故其核心病机为食积化热、胃气壅实。由此可衍生三类相关病机：一是胃气不降，食阻中焦而见痛、吐、不能食；二是寒热如疟，食积与正气相争而寒热交作；三是风寒头痛，寸脉紧示外寒与宿食相兼。四类均围绕“宿食内实", "c": "主宿食内实"}, {"id": "pc:寸+数+滑+微", "n": "寸·数滑微脉", "o": "寸·数滑微脉总起来主痰热内阻、气逆不降与络脉痹阻。滑数之象反映痰热胶结，寸溢反映气机上逆，弦滑反映痰凝络痹。三者相互关联：痰热为病之本，痰热内阻则气机不畅而气逆，气逆日久则血行不利而络痹，故临床可见经断乳少、胁痛、嗽痰带血等症。此脉以痰热为核心，气逆与络痹为痰", "c": "主痰热"}, {"id": "pc:寸+数+滑+洪", "n": "寸·数滑洪脉", "o": "寸部数滑洪脉总起来主痰火壅盛、实热内结之证。滑主痰，数主热，洪为有余，三脉合见于寸部，反映上焦胸膈痰火交阻、邪气壅实。原文两段均以两寸脉俱洪滑而数，断为湿痰凝滞、痰火内盛，症见胸胁作痛、夜分发热，且因补塞太重而迁延不愈，说明此脉所主非虚，乃实痰实火为患。三类病", "c": "主痰"}, {"id": "pc:寸+数+滑", "n": "寸·数滑脉", "o": "寸·数滑脉总以痰热为核心，滑主痰、数主热，寸部候上焦肺胃胸膈，故凡痰热壅阻上焦者多见此脉。然其兼见不同，所主病机亦分：单纯寸关滑数者，主痰热壅肺或痰热结胸；兼尺部无力、细小者，主阴亏于下、痰火浮于上；兼涩或左关尺涩者，主瘀血痰饮互结；右寸关滑数而左弦者，主酒积", "c": "主痰热"}, {"id": "pc:寸+数+濡", "n": "寸·数濡脉", "o": "寸·数濡脉在此案中总主真阳衰微、水湿泛滥、阴盛格阳之危候。寸部濡数，非实热，乃虚阳上浮之象；关尺迟弱，为肾阳衰微、阴寒内盛之征。其病机核心在于太阳之阳不行，少阴之阴亦伤，少火不能生土，水湿日积，浊阴凝聚，终致阴盛格阳。四类病机相互关联：真阳衰微为根本，水湿泛滥", "c": "主虚阳上浮"}, {"id": "pc:寸+数+疾", "n": "寸·数疾脉", "o": "寸·数疾脉总起来主心火亢盛、阴亏水不制火，兼感湿温之邪，甚则胃气衰败而见危候。左寸候心，数疾为热盛，故首主心火内亢；然火亢必耗阴，阴亏则水不制火，故见软大之脉，主阴亏火旺。若兼湿温，则数疾与软大并见，主湿温兼感。若数疾而绝止复来、散乱无根，则为无胃气之怪脉，主", "c": "主湿温兼感"}, {"id": "pc:寸+数+紧+实", "n": "寸·数紧实脉", "o": "寸·数紧实脉在此段中并非主实热常脉，而是与屋漏、雀啄、弹石、解索等怪脉并列，总属死脉范畴。其核心病机为胃气败绝、脏气衰败、真元离散：数疾示虚阳外越，紧实示脉失柔和，绝止复来示脏气不能接续。三者相互关联，皆因脾胃元气衰败，不能涵养脉道，致脉失冲和之象。原文强调“", "c": "主胃气败绝"}, {"id": "pc:寸+数+细+滑+小", "n": "寸·数细滑小脉", "o": "寸·数细滑小脉总以右寸肺系为病位，主伏火挟痰、阴伤气结之候。数主伏火，细主阴伤，滑主痰，小主气机郁滞。四者相合，反映肺中伏火内灼、痰浊阻滞、阴液受损、气机结滞的复合病机。原文以'右寸细数而小滑'断为伏火挟痰，又因悲哀属肺、惊恐气结，致升降失常、胃气日馁。故诸类", "c": "主肺伏火"}, {"id": "pc:寸+数+细+滑", "n": "寸·数细滑脉", "o": "寸·数细滑脉总主痰热内蕴、阴液受伤、邪郁气结之复合病机。数主热，滑主痰，细主阴伤，三者相合，反映热蒸灼液、湿蕴生痰、痰热郁于心胸而阴津已损的病理状态。原文以'细为阴伤，滑数为痰热'为纲，指出邪留恋不化，郁于心胸，湿蕴生痰，热蒸灼液，故见烦躁、恶心、错语，舌边乾", "c": "主痰热"}, {"id": "pc:寸+数+细", "n": "寸·数细脉", "o": "寸·数细脉总以“阴液亏虚、虚热内生”为纲。细主阴血津精不足，数主虚火躁动，二者相合，故所主病机多归阴虚火旺一类。然其兼见部位不同，病机重心亦异：左寸细数多责心阳浮越或心血虚火旺；右寸细数多主肺燥液干；右关细数主脾阴亏损；两尺细数主肾水枯竭。若兼弦大、钩洪，则火", "c": "主阴伤虚热"}, {"id": "pe:寸+数", "n": "寸·数脉", "o": "寸·数脉总以主热为纲，因寸候上焦，故热多偏于心肺、脾胃、胸膈。然具体病机须结合兼脉、按力及分部合参：数而有力多主实热，数而细弱多主阴虚火旺，数而兼滑主痰热，数而兼弦主肝郁化火，左寸独数主心火亢盛。又有寒热错杂如胃寒肠热、虚中夹实如尺沉细而寸关数者。诸类之间，实", "c": "主实热"}, {"id": "pc:寸+数+虚", "n": "寸·数虚脉", "o": "寸·数虚脉总属热盛兼虚之候，以热为核心，虚为津伤，涉及肺、胃两脏。数脉主热，虚脉主不足，故其基本病机为热邪伤津、肺虚有热。若虚小明显，则热在上焦，津液重亡，肺叶焦枯，发为肺痿；若兼右关独大独弦独滑，则阳明胃经湿生痰、痰生热，薰蒸于肺，为痰热壅肺、母病及子。热邪", "c": "主肺虚有热"}, {"id": "pc:寸+沉+伏", "n": "寸·沉伏脉", "o": "寸·沉伏脉总起来主痰实内闭、胸阳不布、气机郁闭之实证。其脉象沉伏，沉为气机郁闭，伏为邪实深伏，寸部候胸中，故反映胸中痰浊壅塞、阳气不得布散。原文'两手寸脉皆沉而伏，知胸中有痰实也'及'沉伏主痰实内闭，胸阳不布'，明确其病机核心为痰实内闭。痰实内闭导致胸阳不布，", "c": "主痰实内闭"}, {"id": "pc:寸+沉+坚", "n": "寸·沉坚脉", "o": "寸·沉坚脉总属里实内积之候。沉为病位在里，坚为邪气实结，二者相合，提示实邪深伏脏腑、气血凝滞不通。原文'寸口脉沉而坚者，病在中'一句，明确其病位不在表而在里，病性非虚而为实。与同段'浮而盛者病在外'相对，更显沉坚主内主实之定位。沉坚与沉紧、沉滑等脉同属沉类实脉", "c": "主里实"}, {"id": "pc:寸+沉+小+紧", "n": "寸·沉小紧脉", "o": "寸·沉小紧脉总属心脉病变，以沉小为里虚、紧为邪实，形成虚实夹杂之象。其主病机可归为四类：热盛、虚寒、痛证、惊悸。热盛者，火郁于内，紧束脉道；虚寒者，心阳不足，寒凝致紧；痛证者，寒滞血瘀，紧脉主痛；惊悸者，神受邪扰，紧急不安。四类之间，以心之气血失调为本，或从热", "c": "主热盛"}, {"id": "pc:寸+沉+小", "n": "寸·沉小脉", "o": "寸·沉小脉总属里虚之象，以阳气不足、阴寒内盛为核心病机。沉主里、小主虚，故其脉不见于表而见于里，不充于外而弱于内。原文从'浮数无力'之内阴虚，发展为'沉小'之阴候，揭示病机由阴虚向阳虚阴盛转化。沉小脉所主，一为里虚，涵盖阴阳气血之不足；二为阳虚阴盛，特指阳气衰", "c": "主阳虚阴盛"}, {"id": "pc:寸+沉+弱", "n": "寸·沉弱脉", "o": "寸·沉弱脉总属虚实夹杂之候，以正虚为本，邪结为标。沉主里、弱主虚，故首主气血不足，寸部尤显心肺气虚；虚寒内生则见寒热错杂、疝瘕腹痛；虚而运化无力，痰瘀凝滞，又成痰瘀互结之标实。三类病机相互关联：气血不足为根本，寒热疝瘕为虚寒之变，痰瘀互结为虚中夹实之果。临证当", "c": "主气血不足"}, {"id": "pc:寸+沉+微", "n": "寸·沉微脉", "o": "寸·沉微脉总起来主阳气衰微、气脱不固及饮停阳衰。沉为阳气不振、饮停于里，微为阳衰无力、气脱不固。原文六脉沉微示中气大虚、阳气衰微，兼右寸大而空、左尺迟细而芤，见脱证、下利不收，为脾肾气脱；寸沉尺微示饮停上焦、下焦阳衰，冲气挟饮上逆。两类病机均以阳虚为本：阳虚不", "c": "主阳虚气衰"}, {"id": "pc:寸+沉+散", "n": "寸·沉散脉", "o": "寸·沉散脉总属虚实夹杂、寒热错见之候。沉为在里，散为气散不收，合而示里虚气耗、阴阳不相维系。其主病机可归为四类：热邪内郁而气耗、气血亏虚而根本不足、里寒阳虚而气散、气滞血瘀而升降失调。四类之间以“正虚气散”为共同基础：热与寒为病性之偏，虚为体质之本，气滞血瘀为", "c": "主热"}, {"id": "pc:寸+沉+浮", "n": "寸·沉浮脉", "o": "寸·沉浮脉在结胸病中，总以热毒结聚心胸、气机壅塞为核心病机。寸口浮主热毒上炎或表邪未解，关上沉主气机内壅，浮沉并见反映热毒与气结聚不散，故按之痛而成结胸。若脉大而浮，为热实内结兼表邪未解，不可下；若关上细小沉紧，则转为阴寒凝结之脏结，属阳气衰微、寒凝内结。四类", "c": "主热毒结聚"}, {"id": "pc:寸+沉+涩", "n": "寸·沉涩脉", "o": "寸·沉涩脉总起来主气机郁滞、痰气交阻所致的中焦壅塞病机。沉主里、主气机内郁，涩主气滞不行，二者相合，反映气结于中焦，甚则痰浊与气滞相互搏结，导致中焦气机壅塞不通。原文在讨论翻胃时，将沉涩脉与气结、痰气交阻相联系，并指出“二脉皆示中焦壅塞、气痰交阻之机”。三类病", "c": "主气滞"}, {"id": "pc:寸+沉+濡", "n": "寸·沉濡脉", "o": "寸·沉濡脉在古籍中虽仅列一段，但该段以怪脉为主，强调无胃气柔和之象。总起来看，此脉所主病机以危重为主：一是胃气败绝，脉失柔和，如屋漏、雀啄等；二是脏气衰微，真脏脉见，脉病人不病者死；三是气血离决，脉气散乱不相连续。三类之间相互关联，胃气败绝为根本，脏气衰微为内", "c": "主胃气败绝"}, {"id": "pc:寸+沉+紧", "n": "寸·沉紧脉", "o": "寸·沉紧脉总属里寒实证，以沉主里、紧主寒主痛为纲。其核心病机为寒邪内盛、水寒相搏，可致水气内动、贲豚冲气；寒凝气滞则见心下寒痛、积邪内结；若兼迟、小等脉，则现阳虚寒盛或虚实夹杂之象。各类之间以寒邪为共同病因：纯实者见水寒内动与里寒积痛，兼虚者则成阳虚寒盛或虚实", "c": "主水寒内动"}, {"id": "pc:寸+沉+紧+迟", "n": "寸·沉紧迟脉", "o": "寸·沉紧迟脉总属里寒阳虚之象。沉主里，迟主寒，紧主痛，三者相合，反映寒邪在里、阳气不足、气机凝滞。其病机核心为胃中寒与阴盛阳虚：沉迟紧并见，为寒邪内盛；寸脉短少力弱，为阳虚不能上充。由此可致胸膈满闷、腹中胀满、身体拘急、手足厥冷等症。三类病机相互关联：里寒为病", "c": "主里寒"}, {"id": "pc:寸+沉+结", "n": "寸·沉结脉", "o": "寸·沉结脉在本段中主要反映肺气郁滞的病机。沉脉主里，结脉主气机阻滞，二者相合，说明邪郁于里、肺气不得宣畅。原文“脉沉而结，肺气𪱥郁”直接点明这一病机。该脉所主病机单一，即气郁，未见其他兼类。在整体脉象中，寸口脉大主肺气有伤，右关洪数主膏粱积热，寸数尺疾主肾火刑", "c": "主气郁"}, {"id": "pc:寸+沉+缓", "n": "寸·沉缓脉", "o": "寸·沉缓脉总起来主寒痰内阻、心阳不足及母子传变之病机。沉主里、缓主寒，左寸候心，脉见沉缓，说明寒痰内阻于里，心阳不温。原文以舌淡白、口唇先寒为佐证，指出阳明胃府久被寒痰所阻，累及于心，形成子病及母之势。三类病机相互关联：寒痰内阻是始动因素，心阳不足是继发结果，", "c": "主寒痰内阻"}, {"id": "pe:寸+沉", "n": "寸·沉脉", "o": "寸·沉脉总主里、主郁、主饮、主结，其病机可归纳为痰饮停聚、气机郁滞、阳虚水逆、寒实内结、里实可下及胸膈结聚数类。沉脉本主里，寸部应上焦胸膈，故凡痰饮、水气、寒邪、气郁结于胸中或上焦者，多致寸脉沉。诸类之间常相兼夹：痰饮可挟气郁，阳虚可致水逆，寒实可成内结，里实", "c": "主痰饮"}, {"id": "pc:寸+沉+迟", "n": "寸·沉迟脉", "o": "寸·沉迟脉总属里寒阳虚、阳郁不伸之象。沉主里，迟主寒，寸候上焦与心肺，故其病机核心为阳气衰微、寒邪内盛。具体而言，或为里寒阳虚，寒湿内停；或为寒凝肺闭，肺气壅塞；或为胸阳不振，痰浊痹阻；或阳郁不达，上热下寒，泻痢厥逆。诸类皆以阳虚寒凝为共同基础，但因寒邪所犯部", "c": "主里寒阳虚"}, {"id": "pc:寸+洪+实", "n": "寸·洪实脉", "o": "寸·洪实脉总起来主热盛气壅于上焦，兼下元不固。洪实为邪热亢盛、气机壅实之象，见于寸部，故热壅上焦，症见喘息迫促、烦躁不卧；两尺不实，则下焦虚馁，不能固摄，致虚阳上浮、热不下达，故便干溲赤。三类病机相互关联：上焦热盛气壅为标，下元不固为本，形成上实下虚之局。洪实", "c": "主热盛气壅"}, {"id": "pc:寸+洪+涩", "n": "寸·洪涩脉", "o": "寸·洪涩脉总起来主寒热错杂、气血壅滞、寒湿痹阻之病机。洪脉为热为壅，涩脉为寒为滞，二脉交替出现且迟数无定，反映寒热相搏、气血运行失畅。原文因冷酒致寒热错杂，寒湿痹阻经络，气血壅滞不通，故见腿疼筋缩、寸步难行。三类病机相互关联：寒热错杂是病因基础，寒湿痹阻是病理", "c": "主寒热错杂"}, {"id": "pe:寸+洪", "n": "寸·洪脉", "o": "寸洪脉总以火热亢盛为基本病机，因寸候上焦，故多主心肺胸膈之热。其具体所主，或为单纯肺热、心火，或为燥热伤津，或为虚阳上浮、上热下寒，或为寒热错杂、气血壅滞。实热与燥热多属有余之实证，虚阳上浮则因下元虚衰、阳不潜藏而致，寒热错杂则因寒热相搏、气血失畅。各类之间，", "c": "主肺热"}, {"id": "pc:寸+浮+微", "n": "寸·浮微脉", "o": "寸·浮微脉总起来主上焦胸膈病机，以寒痰实邪壅塞胸中、气机不得下降为核心。其脉寸部微浮，寸主上焦，浮示病位在上、邪有上越之势。所主病机可归为四类：寒痰壅胸、痰气阻遏、邪郁上焦、胸中实邪，四者相互关联，皆围绕胸中寒痰实邪阻滞、气逆不降展开。原文反复以「胸中痞硬」「", "c": "主寒痰壅胸"}, {"id": "pc:寸+浮+散", "n": "寸·浮散脉", "o": "寸·浮散脉总属虚证，以心气虚浮不敛为核心，兼及肝木不生火、肾阳亏虚、真阳无根。左寸浮散按之无神，直接反映心气不足、君火衰微、神不守舍；左关无力示木不生火，加重心气之虚；肝肾脉迟为水中无火，脉浮为真阳无根，皆根本亏虚、虚阳外浮之机。诸类相互关联，总由心气不足、根", "c": "主心气虚"}, {"id": "pc:寸+浮+洪+结", "n": "寸·浮洪结脉", "o": "寸·浮洪结脉总起来主上焦热郁、气滞血瘀，兼及气血两伤。浮洪为热郁于上，结为气滞血瘀，此二者反映邪实一面；余部沉细而软则为气血两伤，反映正虚一面。本脉象出现在壮年鼻齄患者，因久服苦寒驱风败血之剂，导致虚其虚之误。实邪与正虚并存，热郁、血瘀为病之标，气血两伤为病之", "c": "主热郁于上"}, {"id": "pc:寸+浮+洪", "n": "寸·浮洪脉", "o": "寸·浮洪脉总起来主上焦热盛与虚阳外浮两类病机。浮洪而溢者，为君相二火独盛，热正络，主喉痹等实火证；浮洪而无力者，或为阳虚自汗，或为水亏火旺，属虚阳上浮。若兼结脉，则热郁与血瘀并存，兼见气血两伤。各类之间，实火与虚火相对，热郁血瘀为邪实兼瘀，阳虚水亏为正虚阳浮，", "c": "主火盛"}, {"id": "pc:寸+浮+涩+短", "n": "寸·浮涩短脉", "o": "寸·浮涩短脉在本文中实以怪脉死脉为论，总起来主胃气败绝、脏气衰亡之死候。原文列屋漏、雀啄、弹石、解索、虾游、鱼翔等脉，皆无胃气柔和之象，其来即绝而止、数而疾绝止复顿来、辟辟急、动数而随散乱，均为真脏脉现、精气竭绝之征。三类病机相互关联：胃气败绝则脏气失养而衰亡", "c": "主胃气败绝"}, {"id": "pc:寸+浮+空", "n": "寸·浮空脉", "o": "寸·浮空脉总属虚证，以气虚为核心，兼涉内伤虚损。浮为气浮于外，空为内虚不实，故非表邪实滞。其病机一为气虚：诸部脉虚，分应肺、中、心、肝胆、肾气不足，致眩晕乏力；二为内伤虚损：努挣伤气，阴乘阳位而寒热，误治更伤阴液，关尺微细，下焦亏虚。二者相互关联，气虚为虚损之", "c": "主气虚"}, {"id": "pc:寸+浮+紧", "n": "寸·浮紧脉", "o": "寸·浮紧脉总属外感风寒、寒邪束表之象。浮主表，紧主寒主痛，寸部候上焦，故其病机核心为风寒之邪客于肌表或上焦，导致肺气失宣、经络凝滞。具体而言，可主风寒表证，见头疼、畏寒发热、骨节酸疼；可主寒邪闭肺，见喘咳胸闷、背板如缚；可主寒饮束表，见伏饮咳喘；亦可主寒凝疼痛", "c": "主风寒表证"}, {"id": "pc:寸+浮+缓", "n": "寸·浮缓脉", "o": "寸·浮缓脉总以浮主表、缓主风与湿为纲，所主病机不离风邪外袭、风湿困表，并可兼及肺胃受邪或脾虚湿热。浮为邪在肌表，缓为风性弛张或湿性黏滞，寸部候上焦肺胃，故浮缓见于寸，多提示风邪犯表、肺胃经气不利；若兼他部脉象，如趺阳紧数、尺浮小等，则示表邪兼夹里虚或湿热内蕴。", "c": "主表风"}, {"id": "pe:寸+浮", "n": "寸·浮脉", "o": "寸·浮脉总以“阳浮气盛、病位在上”为基本象义，寸候上焦，浮主表、主阳、主上越。所主病机可归纳为表邪、上焦热实、痰湿壅上、虚阳外浮、气逆上壅、脏结寒凝六类。其间有虚实寒热之异：实者多因外邪袭表、热结胸膈、痰湿壅肺、气逆上冲，脉多浮而有力，症见寒热、胸痛、咳逆、气", "c": "主表邪"}, {"id": "pc:寸+浮+芤", "n": "寸·浮芤脉", "o": "寸·浮芤脉总起来主气血两虚而兼痈毒内结之病机。浮为气机上逆，芤为血虚失守，寸关候中上二焦，故脉浮芤提示气血亏虚于中上二焦。然单纯气血虚不应见腹痛胀、小便失常等局部症状，原文明言“症系小肠痈”，可知虚象之中夹有痈毒内结。因此，浮芤脉所主病机可归纳为两类：一为气血", "c": "主气血两虚"}, {"id": "pc:寸+浮+虚", "n": "寸·浮虚脉", "o": "寸·浮虚脉总起来主卫气不固、营血不足，以及由此导致的风邪为患。其脉象虚浮，虚为卫气亏虚，浮为卫气浮表不固，故易召外风；同时营血不充，血热生风，形成内风。外风与内风相召，则见肤热痛痒、风疹随起。四类病机中，卫虚不固是脉象直接所主，营虚血热是内在基础，风邪外袭是外", "c": "主卫虚不固"}, {"id": "pc:寸+涩+伏", "n": "寸·涩伏脉", "o": "寸·涩伏脉总属虚候，以五脏虚衰、阳气不足为核心。其脉举指或滑而按之微，涩伏不起，反映虚阳浮于外而根本亏于内。所主病机主要有三：一为脏虚，正气内衰、根本不足；二为阳虚外浮，元阳亏虚而虚阳上浮；三为气衰不行，气机涩滞、宣降无力。三者相互关联：脏虚为根本，阳虚外浮为", "c": "主脏虚"}, {"id": "pc:寸+涩+小+弱", "n": "寸·涩小弱脉", "o": "寸·涩小弱脉总属气血两虚、心脉失养之候。涩主少血多气，小主血气俱少，弱主气弱，三者相合，突出一个“虚”字，以血少、气弱为核心。原文将“脉小血少”归于心，因寸部候心，故其病位多责之心。三类病机相互关联：血少则脉道不充而涩，气少则鼓动无力而小弱，心主血脉，气血不足", "c": "主血少"}, {"id": "pc:寸+涩+小", "n": "寸·涩小脉", "o": "寸·涩小脉总属虚候，以气血两虚、心脉失养为核心。涩主少血多气，小主血气俱少，弱主气弱，三者相合突出虚字。寸部候心，故病位多责之心。然虚中常夹实邪：右寸小涩主肺金久损，关部带滑为痰，左寸关弦为肝火，形成肝火挟痰蒸肺、痰热阻肺之证；久病及肾，尺脉涩小示下焦精血亏耗", "c": "主气血两虚"}, {"id": "pc:寸+涩+短", "n": "寸·涩短脉", "o": "寸·涩短脉总起来主心肺气虚、血行涩滞，并涉及情志伤肺、阴阳失调及危重死候。短主气损，涩主血滞，寸候心肺，故常见于忧伤肺脏、心肺气虚之证，症见神情恍惚、悲泣等；若兼虚弦、数而不足，则提示水少于火、阴阳未平；而浮涩短脉见怪脉死脉者，则属胃气败绝、脏气衰亡之危候。各", "c": "主血滞"}, {"id": "pe:寸+涩", "n": "寸·涩脉", "o": "寸·涩脉总主血少阴亏、气滞痰郁及郁损心脾。其核心病机为阴血亏少，脉道不充，往来艰涩，故原文多称“少血多气”“血少不荣”“脉络枯涩”。在此基础上，可因痰浊郁滞而气机不畅（痰阻气机），可因情志郁结而心脾损伤（郁损心阴），可因肺气痹阻而兼寒热（肺痹），亦可因下血多汗", "c": "主血少阴亏"}, {"id": "pc:寸+涩+芤", "n": "寸·涩芤脉", "o": "寸·涩芤脉在内伤胸痛辨证中主上部蓄血。芤为血虚失血之象，涩为血瘀气滞之征，二者相合，反映血虚与血瘀并存的病机，且病位偏于上部（胸膈）。原文“寸脉芤涩，上部蓄血”是直接依据。该脉所主病机单一，即上部蓄血，与滑大主痰、洪数主火、沉结主气滞等并列，共同构成内伤胸痛的", "c": "主蓄血"}, {"id": "pc:寸+涩+迟", "n": "寸·涩迟脉", "o": "寸·涩迟脉总起来主寒、虚、气滞与积邪四类病机，四者相互关联、层层相因。迟为寒之征，涩为气滞血少之象，寸候上焦胸肺，故其病位多在心肺。寒邪郁闭则气机壅滞，气滞日久则血行涩滞，血涩又加重气机不畅，形成寒凝气滞之复合病机；寒郁久则伤阳耗正，阳虚则寒更甚，虚与寒互为因", "c": "主寒"}, {"id": "pc:寸+滑+动", "n": "寸·滑动脉", "o": "寸·滑动脉总起来主痰积、妊娠、肝旺气结及气血两亏。滑主痰，动主痛，寸部候心肺，右关滑动多责痰积中焦，左寸动滑摇摆则为妊娠之兆。然脉象常兼见他部，如左关弦搏示肝木气旺、气结络阻，尺寸微缓示气血两亏。诸类之间，痰积、肝旺、妊娠均可致滑动，而气血亏虚则使脉兼微缓，形", "c": "主痰积"}, {"id": "pc:寸+滑+坚", "n": "寸·滑坚脉", "o": "寸·滑坚脉总起来主痰浊胶固、结聚壅塞之病机。其脉滑为痰象，坚凝为痰结，见于寸关之间，提示顽痰结于肺胃之管。肺主清道，胃主浊道，痰结壅阻，气机不得宣降，故见喘咳、晕绝等症。此脉所主以痰结为核心，气壅为痰结所致之果，二者相互关联，共同构成痰浊胶固、壅塞气道的病机整", "c": "主痰结"}, {"id": "pc:寸+滑+大+微", "n": "寸·滑大微脉", "o": "寸·滑大微脉总属本虚标实、痰气交阻之候。其核心病机为中气虚馁，不能制木，肝郁气结，进而气郁生痰，痰浊壅踞机窍，扰乱神明。滑主痰，大主邪盛，微主正虚，三者相合，提示虚中夹实、痰气互结。各类之间相互关联：中虚为发病之本，气郁为病机之枢，痰滞为病变之标。中虚则运化无", "c": "主痰"}, {"id": "pc:寸+滑+大+沉", "n": "寸·滑大沉脉", "o": "寸·滑大沉脉总起来主里实、水气、寒积、寒热疝瘕及实气搏结等病机。其核心在于沉主里、滑主气主痰湿、大主实，诸象相合，多反映邪实内结或气血逆乱之证。具体而言：沉大而滑主实气搏结，发为卒厥；沉滑主胸中水气；沉坚主里实；沉紧主寒积；沉弱主寒热疝瘕。各类之间以沉脉为共同", "c": "主实气搏结"}, {"id": "pc:寸+滑+大+涩", "n": "寸·滑大涩脉", "o": "寸·滑大涩脉总起来主虚实夹杂之证。左涩主血少或血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。原文吐血后咳喘、泄泻、发热烦躁，前医滋阴则泻甚，保脾则火炽，说明上焦痰火未清、中焦脾弱、下元不足同时存在。滑大偏实，涩弱偏虚，四类病机相互交织：痰火壅盛于上，脾弱", "c": "主血少血瘀"}, {"id": "pc:寸+滑+大", "n": "寸·滑大脉", "o": "寸·滑大脉总以痰、火、气、食壅盛于中上二焦为核心病机。滑主痰饮，大主实热，寸关候上中焦，故滑大有力多示痰火交阻、气滞食积，症见咳喘、呕吐、眩晕、胸痛、眼赤肿等。若兼两尺沉微或沉弱，则成上盛下虚之局，痰火壅于上而下元不足，常见于年高或久病者。各段所论，或偏痰、或", "c": "主痰"}, {"id": "pc:寸+滑+实", "n": "寸·滑实脉", "o": "寸·滑实脉总属邪实壅盛之候，以右寸候肺、寸候上焦与胃气，滑主食、实主邪盛，故其核心病机为实邪壅阻于上中二焦。具体可分两端：一为痰热壅肺，脉滑大搏指，肺气壅塞而咳，甚则震动胞系致胎不固，此邪实伤胎之变；二为食积化热、胃气壅实，脉数滑实，食阻中焦则痛、吐、不能食，", "c": "主痰热壅肺"}, {"id": "pc:寸+滑+小", "n": "寸·滑小脉", "o": "寸·滑小脉总起来主痰凝气滞与风寒闭肺两类病机。原文右寸浮紧主风寒闭肺，关脉小滑主痰凝气滞，二者相互为因：外寒引动痰浊，痰凝气滞又加重肺气壅塞，阻塞清道，发为喘不能卧、胸脘闷、背板如缚。故其病机核心为外寒与痰浊相合，肺气壅塞，气机不畅。两类病机一表一里，风寒为诱", "c": "主痰凝气滞"}, {"id": "pc:寸+滑+微", "n": "寸·滑微脉", "o": "寸·滑微脉总属上焦痰浊为患，兼见正虚或寒热错杂之机。滑主痰涎实邪，微主正虚或邪结不显，寸部候上焦胸中，故其病机核心为痰涎或实邪壅塞胸膈，阻滞气机。据原文，可因寒痰结胸而见胸痛、涎出、下利；可因实邪留饮而胸中痞硬、气上冲咽；亦可因中虚气郁、痰气交阻而成本虚标实之", "c": "主痰涎壅塞"}, {"id": "pc:寸+滑+急", "n": "寸·滑急脉", "o": "寸·滑急脉总起来主痰气壅盛、痛甚气逆与寒凝气滞之病机。滑脉主痰主气，急脉主痛主逆，二者相合，提示痰气交阻、气机逆乱，且多兼寒凝，导致剧痛。原文以‘心疝’为例，症见心腹大痛、伛偻不能仰、气不能息，正是痰气壅盛、寒凝气滞、痛甚气逆的综合表现。三类病机相互关联：痰气", "c": "主痰气壅盛"}, {"id": "pc:寸+滑+沉", "n": "寸·滑沉脉", "o": "寸·滑沉脉总起来主里实、痰水、寒积、寒热疝瘕及实气搏结等病机。其核心在于沉主里、滑主气主痰湿，诸象相合，多反映邪实内结或气血逆乱之证。具体而言：沉滑主胸中水气、痰邪闭肺；沉坚主里实；沉紧主寒积；沉弱主寒热疝瘕；沉大而滑主实气搏结。各类之间以‘沉’定病位在里，以", "c": "主里实"}, {"id": "pc:寸+滑+洪", "n": "寸·滑洪脉", "o": "寸·滑洪脉总属痰、火、食积等实邪壅盛之象，以寸关部尤为明显。洪为火盛，滑为痰聚，合而主痰热壅盛、食积痰饮、郁火痰结、瘀血痰火等有余之疾。其病位多在上中二焦，涉及肺、胃、肝、心等脏腑。若兼尺脉沉伏或微弱，则形成上盛下虚、亢上不下之候，提示实邪壅于上而正虚于下。各", "c": "主痰热壅盛"}, {"id": "pc:寸+滑+浮+疾", "n": "寸·滑浮疾脉", "o": "寸·滑浮疾脉总起来主阳热实证，兼有血多气少之倾向。其“滑”主血实、主痰湿，“浮”主表、主腑，“疾”主热、主数急。四类病机中，主热与主腑病相互关联，热邪在腑则脉数而浮滑；主血多气少源于滑脉本义，与热盛血壅相合；主肺病则因浮滑之象与肺位相合。诸类均以邪实为主，无明", "c": "主热"}, {"id": "pc:寸+滑+浮+紧", "n": "寸·滑浮紧脉", "o": "寸·滑浮紧脉在古籍中虽仅一段直接论述，但结合原文“脉滑者，多血少气”“脉滑而微浮，病在肺”“脉沉细滑疾者热”等，可归纳其总病机为血实气相对不足、病位在肺、兼主热证。滑脉以流利应指为特征，反映血分充实而气分不充，故首主血多气少；若兼浮，则病位在肺，肺主气而朝百脉", "c": "主血多气少"}, {"id": "pc:寸+滑+浮", "n": "寸·滑浮脉", "o": "寸·滑浮脉总以“上焦风痰”为核心病机。浮主风邪在表，滑主痰湿内蕴，寸部候上焦肺卫，故浮滑并见于寸，多主风邪挟痰湿壅阻上焦。其具体可分五类：风邪袭表、痰湿壅肺、风痰上扰、风湿在表、邪在上焦。前四类常相兼为患，风痰恋肺则咳逆音嘶，风痰上扰则头痛呕逆，风湿外束则身疼", "c": "主风邪袭表"}, {"id": "pc:寸+滑+涩", "n": "寸·滑涩脉", "o": "寸·滑涩脉总起来主虚实夹杂、本虚标实之证。滑为阳动，举指见滑提示虚阳浮越或痰火壅于上焦；涩为阴血不足或血行滞涩，按之微弱短涩则示正气内衰、五脏虚损。二者并见，说明上焦有浮阳或痰火之实象，而根本存在气血亏虚。各类病机相互关联：脏虚是根本，虚阳浮越是脏虚所致，血少", "c": "主脏虚"}, {"id": "pc:寸+滑+濡", "n": "寸·滑濡脉", "o": "寸·滑濡脉总起来主湿痰蕴于中上焦、蓄瘀留恋下焦，并由此导致膀胱气化无权、脾不散精的病机。其脉象寸关濡滑，濡主湿、滑主痰，故中上焦湿痰内蕴；尺部涩迟，涩主瘀、迟主寒，故下焦蓄瘀寒凝。原文以寸关尺分部合参，将湿痰、蓄瘀、气化失司三者联为一体：湿痰蕴于中上则津液不布", "c": "主湿痰"}, {"id": "pc:寸+滑+疾", "n": "寸·滑疾脉", "o": "寸·滑疾脉总起来主阳热实证，以热盛、血实、阳浮于外为核心病机。滑脉主血实、主痰湿，疾脉主热、主数急，二者相合，反映热邪内盛、气血涌盛之象。原文“尺脉偏滑疾，面赤如醉，外热则病”明确其主外热，面赤如醉为热邪外浮之征。结合滑脉本义，血实与热相搏，故兼主血实。三类病", "c": "主热"}, {"id": "pc:寸+滑+紧", "n": "寸·滑紧脉", "o": "寸·滑紧脉总以血实气相对不足为根本，兼涉肺脏病位、热证及气滞寒凝。滑脉主血多气少，紧脉主寒主痛，二者相合，寸部候肺，故病位多在肺；滑而兼浮则病在肺，滑疾则主热，紧则示寒凝气滞。诸类之间，血多气少为脉象基础，病在肺为定位，主热与主气滞寒凝为兼夹病机，可单独或相合", "c": "主血多气少"}, {"id": "pe:寸+滑", "n": "寸·滑脉", "o": "寸·滑脉总以痰湿水饮为核心病机，寸部候上焦肺胃胸膈，滑主痰饮内蕴，故凡痰湿、水饮、痰热、食积、风痰、郁痰等壅阻上中二焦者，多见此脉。其兼见不同，所主病机亦分：单纯滑或兼数有力者，主痰热、食积；兼浮者主风痰；兼尺弱或虚弦者主上盛下虚、阴亏痰火。滑脉亦可见于无病之", "c": "主痰湿"}, {"id": "pc:寸+滑+软", "n": "寸·滑软脉", "o": "寸·滑软脉总起来主肺中痰气壅实，并常与肾虚并见，形成肺实肾虚、虚实夹杂之候。右寸滑软直接反映肺实痰壅，气逆上升；左脉细涩则示肾虚气馁少液。二者合参，提示肺肾并衰、出纳无权，喘症在肺为实、在肾为虚。故本脉所主病机以痰气壅实为核心，兼及肺肾并衰与气馁少液，三者相互", "c": "主痰气壅实"}, {"id": "pc:寸+滑+迟", "n": "寸·滑迟脉", "o": "寸口滑迟脉总以脉象中和为无病之常，其兼见他脉则主多种病机。滑迟不浮不沉、不长不短，为气血调和之平脉；若脉见短、长、促上击，则分别主头痛、足胫痛、肩背痛，皆因脉形失常而气机壅滞或逆乱于上下。沉坚与浮盛对举，辨病位之在里在表；沉弱主正虚寒结之寒热疝瘕小腹痛；沉滑主", "c": "主无病"}, {"id": "pc:寸+濡+弱", "n": "寸·濡弱脉", "o": "寸·濡弱脉总起来主脾虚湿停，并可兼见痰证。其核心病机为脾阳不足，运化失职，湿邪内停。右寸关脉濡弱，右关候脾，右寸候肺，年过六十脾虚，故脉见濡弱。脾虚不能运化水湿，湿浊下注则小水频迫、出不禁、足有浮气；湿聚生痰，上逆犯肺则咳嗽。三类病机以脾虚为本，湿停为标，痰为", "c": "主脾虚"}, {"id": "pe:寸+濡", "n": "寸·濡脉", "o": "寸·濡脉总起来主虚与湿，并可涉及危重之候。其核心病机为气虚，尤以肺脾气虚为主，因濡脉无力，主气衰鼓动不足；脾虚运化失职则湿邪内停，故濡又主湿。若虚阳不潜，浮越于上，则见虚阳上浮之象，脉可兼数或浮大。若脉失胃气柔和，出现屋漏、雀啄等怪脉，则主胃气败绝、脏气衰微之", "c": "主气虚"}, {"id": "pe:寸+牢", "n": "寸·牢脉", "o": "寸·牢脉总属沉坚有力之脉，主邪气内结、阳气不达。所引段落虽以尺脉为主论下焦病，然寸牢与尺部脉象相参，可反映多种病机：下焦虚寒、客阳下焦、上热下寒、胃络损伤、外热壅盛、血行不利、虫积筋挛。诸类之间，以“下焦虚寒”为根本，阳虚则寒盛，寒盛则脉牢；虚寒于下，则阳浮于", "c": "主下焦虚寒"}, {"id": "pe:寸+短", "n": "寸·短脉", "o": "寸·短脉总以寸部脉体短小、不及本位为特征，核心病机是上焦气机不利、气血不能充达。短主气损、气郁，寸主上焦心肺，故凡寸短，皆提示上焦元气不足或气机壅遏。其具体所主，可因兼脉与病位不同而分：虚者主心肺气虚、心血不足；实者主气郁、痰湿、火郁；外感则主湿温困表。各类之", "c": "主气虚"}, {"id": "pe:寸+紧", "n": "寸·紧脉", "o": "寸·紧脉总以寒邪为纲，紧主寒主痛，寸候上焦，故其病机核心为寒邪客于上焦或表里，导致气机凝滞、脉道拘急。具体可分：风寒表证，寒邪束表，肺气失宣；寒凝疼痛，寒性收引，气血不通；里寒积结，寒邪内盛，水寒相搏或宿食内停；痰饮壅塞，寒痰阻于胸膈；阳虚气弱，正虚寒凝，虚实", "c": "主里寒积结"}, {"id": "pc:寸+紧+迟", "n": "寸·紧迟脉", "o": "寸·紧迟脉总属寒邪在里、阳气不足之候。紧为寒为痛，迟为寒为阳不胜阴，寸部候上焦心肺，故其病机核心在于寒凝气机与阳虚不充。四类之中，“主寒在脏”言病性属寒、病位在里；“主阳虚气弱”言正气不足、温运无力；“主痛主凝滞”言寒性收引、气血不通之症；“主里寒阳虚”则统合", "c": "主寒在脏"}, {"id": "pc:寸+细+小+紧+急", "n": "寸·细小紧急脉", "o": "寸·细小紧急脉总起来主血气不足、脏病寒凝及热郁。其脉细小，首主血少，因“脉小血少，病在心”“脉小血气俱少”，血虚脉道不充则细；其兼紧急，又主寒主痛，寒邪收引、气血凝滞则脉紧，且“脉迟在脏”提示病位在脏，脏病多寒；若兼滑疾，则“脉沉细滑疾者热”，为热郁伤阴、脉道", "c": "主血少"}, {"id": "pc:寸+细+小+紧", "n": "寸·细小紧脉", "o": "寸·细小紧脉总起来主正虚寒结、阳浮于上之病机。其脉细小，首主血气不足，脏气虚损；兼紧则主寒主痛，阴寒收引凝滞；沉紧更示寒结在里，结于脏腑。寸浮又示阳气浮越。诸类关系以虚为本，寒结为标：正虚则寒凝，寒凝则结聚，虚阳因之上浮。原文藏结脉即寸浮、关小细沉紧，正虚寒结", "c": "主虚"}, {"id": "pc:寸+细+小", "n": "寸·细小脉", "o": "寸·细小脉总起来主气血不足、心脾亏虚，并可见正虚寒结、阳浮于上，甚则胃气衰败。其基本病机为虚：细小为脉道不充，主血气亏少、脏气虚损，寸部候心肺，故多责之心肺气血不足；若兼关脉虚耎，则心脾两伤，劳心伤神、思虑伤脾，见胃中不舒、呕哕咳呛等症。若细小兼紧，则虚中夹寒", "c": "主气血虚"}, {"id": "pc:寸+细+弱", "n": "寸·细弱脉", "o": "寸·细弱脉总属虚候，以营血亏虚为核心病机。细主血少，弱主气衰，寸候心，心主血脉，故左寸细弱直接反映心血不足、营阴亏虚。在此基础上，可衍生两类关联病机：一是心神失养，因心血不足而神不守舍，见心悸、神志异常；二是肝风上扰，因营血亏虚，肝失濡养，虚风内动，上冒清窍，", "c": "主营血亏虚"}, {"id": "pc:寸+细+微+涩", "n": "寸·细微涩脉", "o": "寸·细微涩脉在古籍中与怪脉并论，总属危候。其核心病机为胃气败绝、脏真亏损、阴阳离决、气血耗散四类。胃气败绝则脉失柔和，现屋漏、雀啄等无胃气之象；脏真亏损则脉气不藏，如悬石出筋藏筋；阴阳离决则数疾与断绝并见，散乱无根；气血耗散则脉来散乱不整，如群鸟之聚。四类相互", "c": "主胃气败绝"}, {"id": "pc:寸+细+微", "n": "寸·细微脉", "o": "寸·细微脉总起来主虚损、血少、冷利及胃气败绝。其核心病机为正气亏虚，脉道不充，故见细微。具体而言，寸脉细微多因内伤虚损，气血不足，阴阳不相接续；或心血亏少，脉道空虚；或下焦阳虚，阴寒内盛而见冷利。若细微脉兼见怪脉如屋漏、雀啄等，则属胃气败绝、脏真亏损、阴阳离决", "c": "主虚损"}, {"id": "pc:寸+细+急", "n": "寸·细急脉", "o": "寸·细急脉在古籍中虽仅一段论述，但结合尺部所见，其病机主要围绕下焦虚寒与筋脉拘急。细为阴血不足或阳气衰微，急为寒凝收引或筋脉挛急。原文以尺部细急为核心，兼及细微、虚小、弱等脉象，总归下焦阳气虚衰、寒从中生，故见溏泄冷利、足胫寒、痿痹脚疼；寒凝筋脉则见筋挛痹不能", "c": "主寒泄"}, {"id": "pc:寸+细+沉+微", "n": "寸·细沉微脉", "o": "寸·细沉微脉在此段中实以怪脉死脉为论，总起来主胃气败绝、脏气衰亡之死候。原文通过屋漏、雀啄、弹石、解索、虾游、鱼翔等脉象描述，强调其共同特征为无胃气柔和之象，脉来或绝止不相联续，或数疾顿来，或坚急散乱，皆背离从容和缓之常。此类脉象出现，尤其「脉病人不病」时，提", "c": "主胃气败绝"}, {"id": "pc:寸+细+沉+浮+小+紧", "n": "寸·细沉浮小紧脉", "o": "寸·细沉浮小紧脉在此段中主要反映结胸与脏结两类病机。寸口浮、关上沉，为热毒结聚心胸、气机壅塞之结胸；关上细小沉紧，为阴寒凝结于脏之脏结。浮大之脉又提示表邪未解，误下则逆。细、沉、浮、小、紧诸象并见，说明病位有在表在里、在胸在脏之别，病性有热毒与阴寒之异。结胸属", "c": "主热毒结胸"}, {"id": "pc:寸+细+沉", "n": "寸·细沉脉", "o": "寸·细沉脉总起来主气血不足、阳气不布，其病机核心为虚。沉细之象反映脾胃气弱、血气偏虚，故可见悲伤少气、汗出臂废，甚则风邪乘虚中经而半身不随。若细沉而微，更兼怪脉死脉之变，则非寻常虚损，乃胃气败绝、脏气衰亡之危候。各类之间以虚为纽带：脾胃虚弱为气血虚少之源，气血", "c": "主气血虚"}, {"id": "pc:寸+细+涩", "n": "寸·细涩脉", "o": "寸·细涩脉总起来主虚、气滞、肺实及虚实夹杂。细为虚，涩主气滞血少，寸候肺与肾相关。原文左脉细涩，左候肾，结合‘在肾为虚’、‘气馁少液’，主肾虚少液；涩主气滞，脉道不畅，主气机壅滞；右寸滑软为痰气壅实，主肺实；肺肾并衰、出纳无权，则呈虚实夹杂。诸类相互关联：虚与", "c": "主虚"}, {"id": "pc:寸+细+涩+迟", "n": "寸·细涩迟脉", "o": "寸·细涩迟脉总起来主寒、虚、气滞及肺实。迟为寒，细为虚，涩主气滞血少，三者相合，提示寒邪郁闭、正气不足、气机壅滞。本案右寸候肺，风寒郁肺，酸收致肺金实而无声，脉象反映寒郁、虚滞、气塞的复合病机。诸类相互关联：寒邪郁肺致气滞，久则伤正，形成虚实夹杂、肺实不鸣之候", "c": "主寒"}, {"id": "pc:寸+细+滑+沉+疾", "n": "寸·细滑沉疾脉", "o": "寸·细滑沉疾脉总属热盛阴伤、气血失调之象。细主血少阴亏，滑主气盛痰湿，沉主病在里，疾主热炽，四者相合，多提示热郁于里、阴血受灼，或血少气多、虚火内扰。原文以“脉沉细滑疾者热”为纲，又论脉数在腑、脉迟在脏，及脉小血少病在心、脉滑多血少气等，说明此脉所主以热为核心", "c": "主热"}, {"id": "pc:寸+细+滑", "n": "寸·细滑脉", "o": "寸·细滑脉总主痰湿、热郁、血虚、气滞之复合病机。细为阴血不足，滑为痰湿内蕴，寸部候上焦心肺，故其病机多与痰热郁阻、阴液受伤相关。原文以'脉滑者，多血少气'为纲，指出滑脉主痰湿壅盛，气机被遏；又'脉沉细滑疾者热'，说明细滑兼数则为热灼阴伤。其下属数细滑脉更明确为", "c": "主痰湿"}, {"id": "pc:寸+细+濡", "n": "寸·细濡脉", "o": "寸·细濡脉总属虚象，以肺气虚、心阴弱、水火两亏为本，兼见木邪侮中与虚阳上浮。右寸濡细主肺气虚，左寸细小主心阴弱，两尺无力主肾之水火两亏，三焦俱虚；左关右关细弦则木邪乘土，为虚中夹实之标。诸虚之中，阴弱阳浮，虚阳不潜，生风郁热，故上见舌泡、耳堵鸣响，下见便溏、遗", "c": "主肺气虚"}, {"id": "pc:寸+细+紧", "n": "寸·细紧脉", "o": "寸·细紧脉总起来主正虚寒结、阳浮于上，兼及寒湿困表与湿浊壅滞。其脉细小，首主血气不足、脏气虚损；兼紧则主寒主痛，阴寒收引凝滞；沉紧更示寒结在里，结于脏腑；寸浮又示阳气浮越。诸类关系以虚为本，寒结为标：正虚则寒凝，寒凝则结聚，虚阳因之上浮。若湿温初起，寒湿困表，", "c": "主寒湿困表"}, {"id": "pe:寸+细", "n": "寸·细脉", "o": "寸·细脉总以‘虚’为纲，主气血阴阳亏虚、脉道不充。细为血少气衰之象，寸候心肺，故多责之心肺气血不足；在此基础上，因兼脉不同而衍生多类病机：细而数主阴虚火旺，细而涩主气滞血少，细而紧主正虚寒结，细而滑主痰湿内蕴，细而弦劲主虚阳浮越，细而微弱主胃气败绝。诸类之间以", "c": "主虚损"}, {"id": "pc:寸+细+虚", "n": "寸·细虚脉", "o": "寸·细虚脉在此段以右寸关虚细、左弦并见为特征，总起来主气阴两虚而兼肝风偏亢之候。右寸关候肺脾，虚细示肺脾气阴不足，肺失清润，故呛咳久累不已；左弦示肝风偏亢，肝风上扰，灼烁肺金，形成肝风烁肺、本虚标实之局。癸水始淡继紫，亦为肝风扰动、冲任不宁之征。四类病机中，气", "c": "主气阴两虚"}, {"id": "pc:寸+细+软", "n": "寸·细软脉", "o": "寸·细软脉在此案中主要反映心肾两虚，并作为虚损基础参与虚中夹痰火、肝阳易亢等复杂病机。细软脉本身主虚，寸候心、尺候肾，故左寸尺细软直接提示心肾阴血阳气不足；肾水亏虚不能滋养肝木，则肝阳易亢；水不制火，又兼烦劳五志化火炼液成痰，形成阳明痰火。因此，细软脉所主病机", "c": "主心肾两虚"}, {"id": "pe:寸+结", "n": "寸·结脉", "o": "寸·结脉总起来主气机阻滞、邪壅上焦之病机。结脉主气结，寸部候上焦，故凡气郁、火郁、寒痰等导致上焦气机不畅者，皆可见寸部结脉。所归纳三类中，气郁为基本病机，火郁气壅与寒痰壅塞为不同病因所致的气机阻滞，三者相互关联，均以气结不通为核心，或兼火、或兼寒痰，但总属邪壅", "c": "主气郁"}, {"id": "pc:寸+缓+和", "n": "寸·缓和脉", "o": "寸部缓和脉在古籍中主要被视作脾胃冲和之气的反映，属常脉范畴。原文以“脾胃属土脉宜和缓”为据，强调和缓脉象是脾胃功能健旺、气血调和的表现，而非病脉。因此，该脉所主病机可归纳为“主常脉”与“主脾胃健”两类，二者实为一体：和缓之象源于脾胃冲和之气，故见缓和即提示脾胃", "c": ""}, {"id": "pc:寸+缓+急", "n": "寸·缓急脉", "o": "寸·缓急脉以寸急尺缓为特征，总起来主上实下虚、阳气上逆、下元不足及内风鼓动。寸急反映阳气张大、厥阳变化，上逆而鼓动内风，上凭诸窍；尺缓反映下元亏虚，不能涵敛阳气。二者并见，形成上实下虚之局，即经云“上实下虚，为厥巅疾”。诸类病机相互关联：下元不足为本，阳气上逆", "c": "主上实下虚"}, {"id": "pe:寸+缓", "n": "寸·缓脉", "o": "寸·缓脉总起来主风、湿、虚、寒、积及胃气存亡等多类病机。缓脉本为胃气柔和之象，见于寸部，若脉形从容和缓而无他兼，则为脾胃健旺之常脉；若兼浮，则风邪外袭、风湿困表；兼沉，则寒痰内阻、湿困脾胃；兼微，则气血两亏、元气虚弱；兼急，则上实下虚、阳气上逆、内风鼓动；兼迟", "c": "主气血两虚"}, {"id": "pc:寸+缓+迟", "n": "寸·缓迟脉", "o": "寸·缓迟脉单看脉形为从容和缓而稍迟，本段以“滑而迟、不沉不浮、不长不短”定为无病之平脉，说明缓迟本身可属胃气调和之象。然脉必兼见他形方能主病：兼沉紧则寒凝积邪、心下时痛；兼沉滑则水气停胸、面目浮肿；兼沉弱则正虚邪结、寒热疝瘕而小腹痛。可见此脉总以“和缓为常、兼", "c": "主无病"}, {"id": "pe:寸+芤", "n": "寸·芤脉", "o": "寸·芤脉总属血虚失守、脉络损伤之象，其核心病机为失血与血虚。因寸口候上焦心肺，故芤脉见于寸部，多反映上焦血络受损或气血亏虚。从所涉段落看，芤脉可单独主失血，如咳血咯血；亦可与涩、弱、短并见而主气血两虚；兼弦则示阴虚火旺、肺燥喉痛；兼浮则示气血虚而痈毒内结；兼涩", "c": "主失血"}, {"id": "pc:寸+虚+坚", "n": "寸·虚坚脉", "o": "寸·虚坚脉总属虚实夹杂之象。其“虚”反映气血不足或脏腑功能减退，其“坚”提示气机郁滞或邪气内结。原文以寸部候上焦，结合“脉下坚上虚，病在脾胃”，可知该脉尤易见于脾胃升降失常、清阳不升而浊阴不降之证。同时，原文通过脉之迟数、滑涩、大小等对比，阐明脉象可辨气血盛衰", "c": "主脾胃病"}, {"id": "pc:寸+虚+实", "n": "寸·虚实脉", "o": "寸·虚实脉在此案中总主虚实夹杂之证，具体表现为气火虚与痰火实并见。右寸软小不疏、左尺濡小无力，主气火虚衰；关滑数，主痰火内实。虚者正气不足，实者痰火壅滞，二者互为因果，致喘咳有年、气逆痰壅难卧。三类病机中，气火虚为本，痰火实为标，虚实夹杂为总括。临床当分虚实缓", "c": "主气火虚"}, {"id": "pc:寸+虚+小", "n": "寸·虚小脉", "o": "寸·虚小脉在古籍中仅见于尺部论述，总属虚候，主下焦阳气虚衰、温煦失职。其脉象虚小，反映正气不足，尤以阳气亏虚为核心。因下焦阳虚，不能温养下肢，故见足胫寒、痿痹脚疼；阳气不布，经脉失养，则痿痹脚疼并见。此脉所主病机可归纳为下焦虚寒、阳气不足、经脉失养三类，三者相", "c": "主下焦虚寒"}, {"id": "pc:寸+虚+微", "n": "寸·虚微脉", "o": "寸·虚微脉总属心之气血阴阳亏虚、脉道不充之候。虚微脉来去俱衰、按之无力，寸部候心，故其病机核心为心之正气不足。然虚微之中亦有兼夹：若来盛去盛而见虚微兼数急，则为心火亢盛、热邪外扰，属太过之病；若来衰去衰而纯见虚微，则为心气不足、心血亏虚，属不足之病；若虚微至极", "c": "主心火亢盛"}, {"id": "pe:寸+虚", "n": "寸·虚脉", "o": "寸·虚脉总属正气不足之候，以气虚、血虚、阳虚为基础，并可兼夹虚火、痰湿、风动及邪实。其核心病机为脏腑气血阴阳亏虚，脉道不充，故脉来虚软无力。因虚处不同，兼象各异：虚而兼数者主虚火；虚而兼弦滑者主痰湿风动；虚而兼坚大者主虚实夹杂。各类之间以虚为本，或虚中夹实，或", "c": "主气虚"}, {"id": "pc:寸+虚+软", "n": "寸·虚软脉", "o": "寸·虚软脉总起来主虚证，具体分脾肺阳虚与肝肾阴弱两类。右寸关虚软无力，因右寸关候脾肺，虚软为阳气亏虚，故主脾肺阳虚；左关尺虚弦小数，因左关尺候肝肾，虚弦小数为阴弱阳浮，故主肝肾阴弱。二者虽分属不同脏腑，但均属虚损，且相互影响，如原文所虑补脾不利于肝肾、滋肾不利", "c": "主脾肺阳虚"}, {"id": "pe:寸+软", "n": "寸·软脉", "o": "寸·软脉总属正虚，以气虚、气血不足为核心，寸候心肺，软弱无力即上焦气衰血少。其主病机可归为六类：主气虚、主气血两虚、主虚中夹实、主痰气壅实、主上焦虚损、主气不摄血。诸类皆以虚为本：气虚则血弱，故气血两虚并见；气虚不能摄血，则血热妄行而崩漏；上焦虚损则气衰血少；", "c": "主气血两虚"}, {"id": "pe:寸+迟", "n": "寸·迟脉", "o": "寸·迟脉总主寒与虚，然其病机有虚实之辨。迟为寒象，在寸部则多关上焦阳气不足或寒邪凝滞。其一，虚寒内生，阳气衰微，如大下后寸脉沉迟、手足厥逆，或肝肾脉迟、水中无火，皆属脏气虚寒、阳失温煦。其二，实邪阻滞，气机不畅，如胸中寒痰结聚而脉迟、寸脉微滑，迟非虚寒，乃邪阻", "c": "主寒凝阳郁"}, {"id": "pc:寸+长+坚", "n": "寸·长坚脉", "o": "寸·长坚脉见于心部，总属心脉失常之象。其病机主要分三类：一为心火亢盛，因脉坚长太过，火炎外越，症见身热骨痛、口疮舌焦；二为心气不足，因脉虽坚长而按之衰微，心气内虚，症见烦躁咳唾气泄；三为心病危候，因脉坚搏失柔，如操带钩，提示胃气已绝。三类之间以脉之盛衰和胃气存", "c": "主心火亢盛"}, {"id": "pe:寸+长", "n": "寸·长脉", "o": "寸·长脉总起来主气机有余、邪热亢盛及阳亢上逆，其核心为脉道充盈而长，寸部尤为明显。具体而言，长脉主热盛，尺寸俱长示热邪弥漫三焦；寸长大长主气火有余、厥阳上燔；弦长主肝木亢逆，可乘肺金、挟痰火、兼下元不足；长坚主心火亢盛，亦可因心气不足而现假实之象，甚则坚搏失柔", "c": "主热盛"}, {"id": "p:寸", "n": "寸部", "o": "寸部脉总主上焦（心肺）病机，以热、痰、虚、郁、上盛下虚、寒、邪壅上焦七类为纲。热与痰多相兼，反映实邪壅盛；虚与郁常并见，提示正虚气滞；上盛下虚为上下不交之候；寒与邪壅多属外感或实阻。诸类之间可转化兼夹，如热灼津为痰、痰阻气生郁、久病由实转虚、虚阳上浮成上盛下虚", "c": "主热"}, {"id": "c:小+促", "n": "小促脉", "o": "小促脉总起来主正虚邪郁、阳郁痹结之候。其脉形小主气弱阴伤，促主气结、热郁或虚中夹滞，合而示正气不足而邪气郁遏。所主病机大致四类：一为阳气痹结、清阳不升，见脘痛胀满、四肢不暖；二为气血两虚、营卫俱损而虚中夹滞，多见于疟久正伤；三为热盛阴伤或痰火内郁，数促主热、小", "c": "主阳郁痹结"}, {"id": "c:小+和+平", "n": "小和平脉", "o": "小和平脉在此段实指小儿吐泻后脉见七至，表面为数脉之甚，然结合小儿生理特点及邪去证消，断为“和平之脉”。总起来说，此脉主邪气已尽、正气来复，属预后良好之象，而非热盛病脉。其核心在于辨脉须结合年龄、病程与证候：小儿脉数本为常态，吐泻后邪有出路，脉数反映生机来复，故", "c": "主邪尽正复"}, {"id": "c:小+急+坚", "n": "小坚急脉", "o": "小坚急脉总属正虚邪深、脉证相反之危候。其脉小为正气衰少，坚急为邪气劲迫或寒凝拘急，二者并见，反映虚体而见劲急之脉，失其和缓之常。所主病机主要有五：一为正虚邪深，见于久咳脱形发热等虚损危证；二为胃气败绝，真脏脉见，判癫疾、消瘅之死不治；三为气血瘀阻，心脉小坚急与", "c": "主正虚邪深"}, {"id": "c:小+坚", "n": "小坚脉", "o": "小坚脉总起来主正虚邪结、胃阴亏虚、暑邪内伏、气滞血瘀、胃气败绝及里实内结等病机。其脉象以“小”与“坚”为核心：小为正气衰少、阴血不足，坚为邪气内结、脉道拘急或虚火内搏。诸类之中，正虚邪结为总纲，贯穿各段；胃阴亏虚、暑邪内伏、气滞血瘀、里实内结分别为不同病位与邪", "c": "主正虚邪结"}, {"id": "c:小+实+坚", "n": "小实坚脉", "o": "小实坚脉总起来主病位在里、邪气内实，兼有气机不畅之机。其“小”示脉体收敛，气血不能充达；“实”“坚”示邪气结聚于内，非表非虚。原文以“沉而坚者，病在中”为据，说明此脉核心在里实内结；又“中手短者，曰头痛”，短则气病，提示小实坚中兼短象时，可因气机郁滞、清阳不升", "c": "主病在中"}, {"id": "c:小+紧+实", "n": "小实紧脉", "o": "小实紧脉总起来主肾实、寒凝与气血虚少三类病机。其脉小，提示气血偏少；实紧，提示邪气内结、脉道拘急。原文以“小而紧”属肾，说明此脉与肾关系密切，肾实寒凝为其主要方面；同时“脉小血少”“脉小血气俱少”又点出小脉主虚。三类之间，肾实与寒凝常相兼为病，寒邪客肾则脉紧实", "c": "主肾实"}, {"id": "c:小+实", "n": "小实脉", "o": "小实脉总起来主邪气内结、病位在里之实证，具体可归为里实、瘀血内阻与热结腑实三类。其脉象“小”示脉体收敛，气血不能充达，或积结深着；“实”示邪气结聚于内，非表非虚。原文以“小沉实主里实”明其病位在里，以“脉体反小而实”示热结于腑、燥实内成，以“绝小实”判瘀血内阻", "c": "主里实"}, {"id": "c:数+弦+小+动", "n": "小弦动数脉", "o": "小弦动数脉总起来主阴虚阳亢、内风旋动、热耗津液之病机。其脉小为阴血不足，弦动为风阳上扰，数为热象，合而示肝肾阴亏、虚阳化风、热伤津液。四类病机相互关联：阴虚为本，因虚而内风旋动，风阳升于上则下焦无气；热则真气泄越，更耗阴津，加重阴虚风动。故临床见头晕、目泪、足", "c": "主阴虚"}, {"id": "c:数+弦+小+促", "n": "小弦数促脉", "o": "小弦数促脉总属肝阳化风、火郁阳亢之候。弦为肝风，小为阴伤，数促为火郁，合而示肝阳挟内风上扰，木火戕胃，阳越汗出。其病机以肝风内动为核心，阳亢火郁为关键，阳越汗出为变，暴厥瘈痉为极。四类相互关联：肝风内动则阳亢火郁，火郁阳亢则阳越汗出，阳升无制则暴厥瘈痉。总因操", "c": "主肝风内动"}, {"id": "c:数+弦+滑+小", "n": "小弦滑数脉", "o": "小弦滑数脉总起来主阴虚正虚、邪郁、痰热内盛，并有热极生风之变。脉小为阴虚正虚，弦为邪郁，滑数为痰热。四者相合，反映正虚不能载邪外达，而痰热仍炽，形成正虚邪实、本虚标实之局。其中阴虚正虚为本，痰热邪郁为标，标实进一步可致热极生风、痉厥变幻。诸类病机相互关联，虚、", "c": "主阴虚正虚"}, {"id": "c:弦+小", "n": "小弦脉", "o": "小弦脉由小脉与弦脉复合而成，小主正气不足、阴血亏虚，弦主肝郁气滞、饮痛风动。合而观之，其总病机为本虚标实、虚实夹杂。本虚以气阴两虚、血虚、阳虚为主；标实以肝郁气滞、痰饮湿浊、虚热、疟邪、寒凝气逆为要。诸类之间，虚为本，实为标，虚可致实（如血虚肝旺、脾虚痰生），", "c": "主肝郁气滞"}, {"id": "c:弦+虚+小", "n": "小弦虚脉", "o": "小弦虚脉总属虚中挟实、本虚标实之象。小为阴血少，虚为不足，弦为气逆，三者并见，反映阴血亏虚为本，气逆动血为标。原文'脉小弦虚，久嗽，失血盈碗……此劳伤嗽血，宜养胃阴'，说明其病机核心为胃阴亏虚、气逆动血，属虚火迫血，非实火所致。阴血不足则脉小虚，气逆不降则脉弦", "c": "主阴血亏虚"}, {"id": "c:弦+小+软", "n": "小弦软脉", "o": "小弦软脉总起来主虚、郁、痰、寒的复合病机。其核心为正气不足（小软）与肝木失和（弦）并见，可因具体情境不同而有所偏重：产后营虚阳浮者，以营血亏虚、虚阳不敛为主；痰核渐消者，以气郁痰凝、正气略伤为主；沉弦小软者，则兼阳虚里寒、肝木乘脾、痰饮内聚。三类之间相互关联，", "c": "主营虚阳浮"}, {"id": "c:小+弱+急", "n": "小弱急脉", "o": "小弱急脉总起来主阳气衰微而邪热内迫之证，尤多见于暑伤气分。其脉小弱，为阳气虚微，无力鼓动；急则因邪热内郁，逼迫脉道。二者并见，形成虚实夹杂之象。原文强调“小弱为阳微，急为邪热内迫”，并指出病本伤暑，因误用阴药致阳微厥而腹满不省人事。故本脉所主病机可归纳为阳微、", "c": "主阳微"}, {"id": "c:数+小+弱", "n": "小弱数脉", "o": "小弱数脉总起来主虚热为患，以阴血亏耗、火旺动血为核心。数脉为热象之据，小弱非虚寒，乃血下夺或气血不足而脉道不充，故脉反小弱而数。其所主病机可归为四类：虚火、虚痰、气血亏耗、脾虚湿郁。四者相互关联：虚火为因，灼津炼液成痰则为虚痰；火亢耗气伤血则致气血亏耗；脾虚运", "c": "主虚火"}, {"id": "c:涩+小+弱", "n": "小弱涩脉", "o": "小弱涩脉总起来主气血亏虚，尤以血少气衰为核心。小主脉道不充，弱主气衰无力，涩主血行滞涩，三者相合，反映气血两亏、脉道失充之病机。原文“脉小血少”“脉涩者，少血多气”“脉小血气俱少”均指向血少与气虚；而“沉而弱”又兼主寒热疝瘕、少腹痛，为虚寒内结之变。各类之间以", "c": "主血少"}, {"id": "c:小+弱", "n": "小弱脉", "o": "小弱脉总以虚为主，脉体收敛为小，搏动无力为弱，皆气血不充、阳气衰微之象。其类虽多，然核心病机不外阳气虚衰与气血两虚：阳虚则不能温煦固摄，见冷汗肢冷、下痢欲脱；气虚则不能充脉运血，见神疲心悸、经阻便难。脾胃虚寒、卫阳不足皆阳气虚之具体分属；正虚邪郁、虚阳上浮则为", "c": "主阳气虚衰"}, {"id": "c:微+涩+小", "n": "小微涩脉", "o": "小微涩脉总起来主虚与滞，以正气不足、络脉涩滞为核心病机。其脉象小主气血亏虚，微主阳气衰微，涩主血行不畅，故既可见于五脏虚损、正气内衰之虚候，又可见于虚中夹滞、络脉失和之实证。各类之间相互关联：脏虚为根本，气血不足则络脉失养而涩滞，或致络脉失和而痛，或致冲任不固", "c": "主络脉失和"}, {"id": "c:小+急", "n": "小急脉", "o": "小急脉总起来主虚实夹杂、寒热错杂之病机，其核心在于脉小主正气不足，脉急主邪气劲迫或寒凝收引，二者并见，反映虚体受邪、脉失和缓之象。所主病机可归为寒凝痛积、营热迫血、痫瘛筋挛、正虚邪深、阳微邪热、痹阻偏枯六类。寒凝与营热为寒热两端，皆因急脉示邪迫脉道；痫瘛筋挛因", "c": "主寒凝痛积"}, {"id": "c:数+小+促", "n": "小数促脉", "o": "小数促脉总起来主热、虚、痰火及暑温邪陷等病机。数促主热，小主虚，合而常见热盛阴伤或痰火内郁之候。各段原文显示：或为壮年痰火郁于上焦，或为暑温深陷营分，或为阴虚火旺。其病机核心是热邪与虚损并存，或痰火交阻。各类之间相互关联：热盛可伤阴致虚，虚火又可炼液成痰，痰火", "c": "主热"}, {"id": "c:数+小+坚", "n": "小数坚脉", "o": "小数坚脉总起来主阴血不足、热郁气滞之证。脉小为阴血亏虚，数为有热，坚为脉道拘急，三者相合，提示阴亏于下而热结于内，非纯虚之候。其病机核心为下焦郁热、气机坠滞，常见肛坠胀等症。各类之间相互关联：阴血不足为虚之本，热为郁热之标，气滞络急为热郁之果，下焦郁热则是诸因", "c": "主阴血不足"}, {"id": "c:数+微+小", "n": "小数微脉", "o": "小数微脉总起来主虚损夹杂之候，以阴血亏虚为本，虚火、邪热为标，或兼阳气衰微、阴寒内盛。其核心病机为真阴不足、虚火内动，可致虚火动血而见吐血，或肺胃阴伤而见咳呛咽燥；若脉兼滑数，则转为阳虚阴盛、虚阳不藏；若兼数急，则示正虚邪热夹杂。各类之间以虚损为共同基础，或偏", "c": "主阴虚火旺"}, {"id": "c:数+小+急", "n": "小数急脉", "o": "小数急脉总属正虚邪盛、邪热内郁之候。数急主邪热亢盛，小主正气不足，二者相合，形成正虚不能敌邪、邪热郁而不达的复杂病机。其核心在于正虚邪陷，既有邪热内郁之实，又有正气亏虚之虚，病情多危重，易生变证。下属微小数急脉更具体地反映了虚损与邪盛夹杂，以正虚为主，兼见邪热", "c": "主邪热内郁"}, {"id": "c:数+小+疾", "n": "小数疾脉", "o": "小数疾脉总主阴血亏虚、邪火内伏，或热毒壅盛、实邪内结之病机。其脉小示阴不足，数疾示热与火亢，合而示虚火内炽或热毒壅盛。所主病机可分四类：一为阴亏火旺，虚阳上扰，见于童真阴未充而阳独升降；二为热毒壅盛，实邪内结，见于肺痈热毒未衰；三为阴血虚而邪火伏，见于便血阴伤", "c": "主阴亏火旺"}, {"id": "c:数+小", "n": "小数脉", "o": "小数脉总以“小”与“数”合参为纲：小主阴血不足、正气亏虚、脉道不充；数主热、火、郁蒸。故其总病机为虚中夹热，以阴血亏虚、虚热内扰为核心，并可兼见血虚有热、气阴两虚、正虚邪恋、虚火动风、湿热郁蒸、热毒壅结等复杂局面。诸类之间，阴虚内热是最基本、最常见的类型；血虚", "c": "主阴虚内热"}, {"id": "c:沉+小+实", "n": "小沉实脉", "o": "小沉实脉总属积邪内结、里实之候。其脉象沉为在里，小示积结深着，实主邪气内结，故总以“积”与“里实”为纲。原文列多种积聚脉象，小沉实与𫘝紧、浮牢、细䎡附骨等并列，皆主积邪内结；又谓“小沉实主里实”，与浮主表相对，明其病位在里。若兼弦紧，则寒积内结、气机收引，可见", "c": "主积"}, {"id": "c:沉+浮+小", "n": "小浮沉脉", "o": "小浮沉脉总以脉小兼左浮右沉为特征，所主病机围绕风邪、气水交阻与正虚展开。左浮主风邪在表未解，右沉主脾肺气滞水停，脉小示正气已伤。三者相互关联：风邪外袭为始，入里传脾则气滞水停，正虚不能抗邪则病势转危。故本脉总主风邪入脾、气水交阻、正虚邪恋之病机，属表里同病、虚", "c": "主风邪在表"}, {"id": "c:数+涩+小", "n": "小涩数脉", "o": "小涩数脉总主郁热、阴血虚、血瘀气滞、痰火互结及虚损五类病机。其核心为气郁化火与阴血亏少：数主热，或为郁火，或为虚热；小涩主阴血不足、脉道不充及血行滞涩。情志郁勃、五志过极，气郁化火，灼伤阴血，血行不畅则瘀滞；郁火炼液成痰，痰火互结，阻滞气机；久病则阴津暗伤，元", "c": "主郁热"}, {"id": "c:涩+小+结", "n": "小涩结脉", "o": "小涩结脉总主阴阳气血俱损、气机郁结之病机。小为阴液枯槁或阳衰，涩为血少络阻，结为气机郁滞。其核心为阴枯阳结，常见于噎膈反胃、关格等证。各类关系：阴枯阳结为根本，导致气滞血瘀、阳衰气闭；清阳不升与浊阴渐阻互为因果。原文强调“伤于无形”，情志偏胜致气血郁结，病情深", "c": "主阴枯阳结"}, {"id": "c:涩+小", "n": "小涩脉", "o": "小涩脉总主气血不足、脉道滞涩之病机，其核心为虚与滞并存。小脉主气虚血少，涩脉主血行不畅，二者相合，多示气血两虚而兼气滞血瘀、湿郁痰阻。从所主病机看，或偏虚，如气血虚、阳衰阴结、久病虚损；或偏滞，如气滞血瘀、湿郁痰阻；或虚实夹杂，如郁热血冒、肝旺脾虚。各段原文虽", "c": "主气血虚"}, {"id": "c:数+滑+小", "n": "小滑数脉", "o": "小滑数脉总起来主阴虚、痰湿、热邪相互夹杂之证，其病机核心为“虚中夹实”。脉小（细）主阴液亏虚、气血不足，为虚；脉滑主痰湿内蕴，脉数主热邪炽盛，二者为实。合而观之，常见阴虚火旺、痰热内扰之候，如肺胃痰热、肝火挟痰、产后阴伤邪热未清等。若痰热炽盛，灼伤阴液，可致热", "c": "主阴虚"}, {"id": "c:滑+小", "n": "小滑脉", "o": "小滑脉总属本虚标实、虚实夹杂之象。小主正气不足、阴血亏耗或阳虚，滑主痰湿、痰热、宿积或痰凝气滞。二者合参，常见于痰湿内蕴兼正虚、痰热内郁兼津伤、虚中挟实及痰凝气滞等证。其病机核心为正气已伤而痰湿（或痰热、食积）未化，虚为本、实为标。各段所主虽异，然皆不离‘小’", "c": "主痰湿"}, {"id": "c:涩+小+濡", "n": "小濡涩脉", "o": "小濡涩脉总属虚实夹杂之候，以阳气不足、气血亏虚为本，湿滞浊阴为标。小脉主阳气不足，濡脉主湿滞，涩脉主血少行滞，三脉相合，反映虚中夹湿、本虚标实之病机。所主病机主要有三类：阳虚湿滞、脾虚湿困、气血不足。其中阳虚湿滞侧重胃阳不旺、浊阴易聚；脾虚湿困侧重中焦失运、湿", "c": "主阳虚湿滞"}, {"id": "c:小+濡+缓", "n": "小濡缓脉", "o": "小濡缓脉总起来主虚、湿、风三端，以脾肾亏虚为本，湿滞与肝风为标。小为气血不足或肾气亏虚，濡主湿滞，缓主脾虚或虚风不主流动。四段原文中，或见肾纳失司、肝风震突之右痪舌喑，或见脾虚湿滞之疟久痞满，或兼温热客气之耳后暴肿，皆不离虚中夹湿、虚风内动之机。其脉缓而不数，", "c": "主肾虚肝风"}, {"id": "c:小+急+牢", "n": "小牢急脉", "o": "小牢急脉总起来主血气偏虚、风湿痹阻及偏枯之病机。其脉小示气血不足，牢急示血脉拘急不通，三者相合，反映正虚邪客、脉络痹阻之候。原文以风偏枯为例，说明血气偏虚则腠理开，风湿乘虚客于分腠，致血气凝涩不能润养，久则生气去而邪独留，发为偏枯。小牢急脉既提示气血虚损之本，", "c": "主气血虚"}, {"id": "c:小+疾", "n": "小疾脉", "o": "小疾脉总主正虚邪盛、热盛阴伤之病机。脉小示正气不足或阴血亏虚，脉疾示邪热亢盛。二者相合，或见于热盛伤阴、正不胜邪之温病危候，或见于咳而脱形身热之逆证，皆属正虚邪实、预后不良之象。其下属小数疾脉更具体地主阴血亏虚、邪火内伏，或热毒壅盛、实邪内结，可见小疾脉所主病", "c": "主正虚邪盛"}, {"id": "c:小+短", "n": "小短脉", "o": "小短脉总起来主阳气衰微、水湿泛滥、脾虚气损及湿热未清。其脉象短小，短主气损，小主虚，故见脾虚气弱；若脉按之不可得，沉伏难寻，则阳气衰微，不能外达，水湿泛滥为肿。两类病机相关：阳气衰微则水湿不化，水气太过又遏抑阳气；脾虚则运化失职，湿浊内停，久则湿热未清。故小短", "c": "主阳气衰微"}, {"id": "c:小+急+硬", "n": "小硬急脉", "o": "小硬急脉在《病源》咳病预后中为死脉，总属真脏脉见、胃气已绝之候。其脉象小而坚硬紧急，失柔和之胃气，反映邪盛正衰、生机将竭。所主病机可归为三类：一为胃气已绝，脉无胃气则死；二为邪盛正衰，正虚不能抗邪；三为寒饮内伏，寒性收引致脉拘急。三者相互关联，寒饮内伏可伤阳耗", "c": "主胃气已绝"}, {"id": "c:数+小+紧", "n": "小紧数脉", "o": "小紧数脉总起来主阴伤兼郁热、气郁血凝、内风阳越及痰饮痹阻。小为阴血亏少，紧主气郁血凝或内风升举，数因郁热内蒸或阳越。四段中，两段肝胃气痛见阴伤郁热阻络，一段眩晕遗泄见阴亏阳浮、内风升举，一段胸痹见寒饮搏结。各类之间以“阴伤”为共同基础，郁热、气郁、内风、痰饮多", "c": "主阴伤"}, {"id": "c:小+紧", "n": "小紧脉", "o": "小紧脉总起来主虚寒为基、阳浮为变之病机。小脉主营血虚少，紧脉主寒主痛，二者相合，多示中焦虚寒、气血不足。在此本虚寒之上，常因阴寒内盛而虚阳外越，出现身微热、口舌碎痛等上热下寒之象；若与左寸关搏指并见，则形成心肝阳亢于上、脾胃虚寒于中的寒热错杂证。故小紧脉所主，", "c": "主虚寒"}, {"id": "c:细+涩+小", "n": "小细涩脉", "o": "小细涩脉总属虚损之候，以阴血亏虚为根本，兼见气滞、阳衰、虚热等变。细主血少，涩主血行滞涩，小主脉道不充，故其核心病机为阴血枯槁、脉道失充。在此基础上，因气血互根，血虚则气衰，故见气血大虚；阴血不足则阳气失养而郁结，故见阳气郁结；阳虚不能温煦，则见虚寒阳衰；阴亏", "c": "主阴血亏虚"}, {"id": "c:细+小+紧", "n": "小细紧脉", "o": "小细紧脉总起来主正虚寒结之病机。其脉象由小、细、紧三部分组成：小细主气血虚少，紧主寒主痛。在藏结证中，寸脉浮示阳气浮越于上，关脉小细沉紧示脏气虚寒、阴寒内结、气血凝滞。诸象合参，反映正虚与寒结并存的复杂病机。各类之间相互关联：气血虚少是正虚的基础，脏寒内结是邪", "c": "主脏寒内结"}, {"id": "c:小+结", "n": "小结脉", "o": "小结脉总以脉体细小、脉气郁结为特征，所主病机涵盖脏腑形态异常与气血功能失调两大类。其一，以脉测脏腑，小结之象可反映小肠形质短小或小肠结滞，属禀赋与形态病机。其二，从气血阴阳论，小为阴液枯槁或阳衰，结为气机郁滞，故主阴阳气血俱损、气滞血瘀，常见于噎膈反胃、关格等", "c": "主小肠结"}, {"id": "c:滑+小+缓", "n": "小缓滑脉", "o": "小缓滑脉在新产情境下，总主胃气未败、气血虽去而尚能流利之生机。其“小”应血去，“缓”应胃和，“滑”应气血流利，三者相合，示产后正虚而脉有柔和之象，故主生。此脉所主病机可归为三类：胃气和调、气血流利、血去脉柔，三者相互关联，共同反映产后虽亡血而胃气未败、脉有胃神", "c": "主胃气和调"}, {"id": "c:小+缓", "n": "小缓脉", "o": "小缓脉总属正气不足而邪气不盛之象。小为阳气或正气亏虚，缓为湿滞不运或邪热内伏而非实盛。其主病机可归为五类：正虚邪轻、阳运湿浊、湿胜热伏、虚热内伏、精滑虚损。诸类皆以虚为本，或兼湿、兼热、兼伏邪，然邪势均不鸱张，故脉不鼓击、不数大。正虚邪轻为总纲，余四类为具体病", "c": "主正虚邪轻"}, {"id": "e:小", "n": "小脉", "o": "小脉总以脉道不充、正气不足为纲，所主病机以虚损为核心，涵盖气血阴阳亏虚、阳虚衰微，并可兼夹湿困、痰饮、邪陷等标实之候。其虚者，或为精血暗亏，或为阳气式微，或为脾胃虚衰，皆因脏腑功能衰退、精气血津液化生不足，致脉体收敛而小。其兼实者，多因正虚而湿浊痰饮内停，或正", "c": "主虚损"}, {"id": "c:小+芤", "n": "小芤脉", "o": "小芤脉总起来主气血两亏，尤以血虚为著，并常兼阴伤热劫、暑邪入脏。其脉小示气血不足于外，芤为中空专主血虚，故核心病机为血虚，常与气亏并见，形成气血两虚。若逢暑邪客邪，乘虚干脏阴，则热深劫阴，出现神迷心热烦躁、寒热麻痹等症，甚则痉厥。小芤脉所主诸类之间，血虚与气亏", "c": "主血虚"}, {"id": "c:涩+小+软", "n": "小软涩脉", "o": "小软涩脉总主气血不足、营血流行迟钝及八脉拥护无权。小软为气血亏虚之征，涩为营血运行涩滞之象，二者相合，反映气血两虚、营卫流行不畅，进而导致奇经八脉失于护养。原文以‘气血不足，营卫流行迟钝，八脉拥护无权’概括病机，三者相互关联：气血不足是根本，营血涩滞是运行表现", "c": "主气血不足"}, {"id": "c:小+缓+迟", "n": "小迟缓脉", "o": "小迟缓脉总起来主虚寒与阴阳失调之证，其核心病机为阳气不足、脾肾虚寒，或阳盛伤阴、阴液未复。小主虚，迟主寒，缓为不足，三象合见多示阳虚寒凝、中气衰败，故见卫阳不足、胃阳虚、脾肾阳虚不能固摄等；然脉虽缓小似虚寒，亦有阳盛伤阴、脉道不利之变，如缓小迟涩主奇恒痢危候；", "c": "主阳虚寒凝"}, {"id": "c:小+迟", "n": "小迟脉", "o": "小迟脉总属阳气不足、阴寒内盛之象，以虚寒为核心，兼涉寒凝、正虚、阳郁、蓄血等机转。小主阳气不充，迟主脏寒阳微，二象合见，首责脾肾阳虚、中焦虚寒，故下利、腹痛、呕吐、手足逆冷诸症丛生；寒性收引凝滞，气血不畅则痛、则疝；正虚不能抗邪，则营卫失调而疟、邪陷而危；若寒", "c": "主阳虚中寒"}, {"id": "pc:尺+乱+碎", "n": "尺·乱碎脉", "o": "尺·乱碎脉总起来主肝肾同病、肝风上冒之证。其脉碎乱搏指，脉道失其常度、至数不匀，既反映肾阴亏虚于下，又显示肝风内动于上。乙癸同源，肾水不足则肝木失涵，风阳扰动则气血乖乱，故脉见碎乱搏指。原文两段均断为“肝风上冒”“乙癸同源，肾肝同病”，并强调少阴之脉不至巅、惟", "c": "主肝风上冒"}, {"id": "pe:尺+乱", "n": "尺·乱脉", "o": "尺·乱脉总起来主肾虚不固、元气欲脱，兼见肝旺虚阳之证。其脉象以尺部乱而不整为核心特征，反映肾气亏虚、根本动摇，甚则元气欲脱、失血危候。原文‘尺中甚乱乃肾气不固’‘肾家之血汹涌而出’‘从尺脉乱识肾虚失血之危’均强调肾虚失固为关键病机。同时，脉象常兼左弦大右虚大，", "c": "主肾虚不固"}, {"id": "pe:尺+代", "n": "尺·代脉", "o": "尺·代脉在本文中主要体现为以脉象判断疾病吉凶，其核心病机在于邪正盛衰的对比。脉浮大沉小之变化，反映邪气外达与内陷、正气抗邪与衰败的不同态势。伤寒热盛脉浮大者生，沉小者死，示邪有外达之机则生；汗后脉沉小者生，浮大者死，示津伤后脉宜静敛。温病脉大疾者生，细小难得者", "c": "主邪盛正衰"}, {"id": "pe:尺+伏", "n": "尺·伏脉", "o": "尺·伏脉总起来主肾虚、阳气不足，并由此衍生火不归元、积滞内阻、寒盛阳衰及下焦冷闭等病机。其核心在于尺部候肾，沉伏为阳气不能鼓动、肾气亏虚之象。肾虚则火失潜藏，虚阳浮游，故见上下循环发热、足底热甚；阳气不足则脉微无力，与沉伏并见。若中焦食积痰浊胶结，气机壅塞，脉", "c": "主肾虚火浮"}, {"id": "pe:尺+促", "n": "尺·促脉", "o": "尺部促脉在古籍中仅见一段论述，其核心特征为“促上击”，即脉来急促、应指有力而上击。由此归纳，促脉总主阳邪上盛与气逆不降两类病机，二者实为一体：阳热之邪壅盛于上，鼓动气血奔迫，故脉促而击指；气机因邪热而逆乱，失于和降，故上冲为患。原文以肩背痛为症，正是阳邪上攻、", "c": "主阳邪上盛"}, {"id": "pe:尺+动", "n": "尺·动脉", "o": "尺动脉总起来主下焦病机，以肾虚为本，虚阳升动为标。其核心为肾阴亏虚、阴不敛阳，导致虚阳上浮、冲脉升动，故见尺动而寸静，伴失血、咳呛、气促等上实下虚之候。在此基础上，可兼见阳升气火、肝肾阴虚、肾虚冲逆等证；若兼滑、数、芤等脉，则分别主痰积湿热、热扰胎元、精亏神驰", "c": "主阳升气火"}, {"id": "pc:尺+动+芤", "n": "尺·动芤脉", "o": "尺·动芤脉总起来主心肾不交、精关不固之遗精。其病机核心为真阴亏虚、心阳浮动：尺芤反映下元精血耗伤，上动反映心神浮越。精亏则不能充长，神驰则精随神散，二者互为因果，终致精关不固而久遗滑漏。四类病机中，精亏与神驰为病之本，不固与心肾不交为病之果，彼此交织，形成'心", "c": "主精亏"}, {"id": "pc:尺+和+平", "n": "尺·和平脉", "o": "尺部和平脉总以尺脉异常为眼目，所主病机可归为三类：阳升气火、下焦壅塞、肾虚阴亏。阳升气火者，尺中微动或带数，关前动数，为五志动阳、冲脉上逆，血随咳呛上溢；下焦壅塞者，两尺沉绝而他脉平和，为胎上迫心、气血壅塞于上，下焦脉气一时不通；肾虚阴亏者，尺虚细涩而寸关大，", "c": "主阳升气火"}, {"id": "pe:尺+和", "n": "尺·和脉", "o": "尺·和脉总起来主气血渐充、应时生发之象，亦可见于气血亏虚、肾阴不足及气聚为胀。其脉象以弦滑流利、弦而和、迟弱、细濡为特征，弦滑应春生之气，迟弱主营气不足，细濡主阴阳两亏。各类之间，应时生发与气聚为胀属生理或气机一时之变，非邪实；气血亏虚与肾阴不足则属虚损，需温", "c": "主气血亏虚"}, {"id": "pe:尺+坚", "n": "尺·坚脉", "o": "尺·坚脉总以邪实内结为基本脉象，坚主牢实结聚，尺候肾与下焦，故病位在里。其所主病机可归为四类：里实积结为直接病机，见沉坚、横坚、实坚，主积块、疝瘕、少腹痛；阴虚湿热为坚中兼涩滑，阴亏失润而湿热下注，见淋浊痛；正虚邪陷为急坚、大坚，正虚无力抗邪，以浮大沉小判吉凶", "c": "主阴虚湿热"}, {"id": "pc:尺+大+坚", "n": "尺·大坚脉", "o": "尺·大坚脉总起来主正虚邪盛、重虚及阴竭阳浮三类病机，并关乎吉凶逆顺之判。其脉大主邪盛，急坚主正虚邪结，尺部候肾与下焦，故病位在里。原文以脉之浮大沉小判伤寒温病吉凶，强调正能抗邪则生，正虚邪盛则死；又论重虚，尺虚行步恇然，脉虚不象阴，滑生涩死；更指出阴竭阳浮者，", "c": "主邪盛"}, {"id": "pc:尺+大+实", "n": "尺·大实脉", "o": "尺·大实脉总以邪热壅盛、正气尚能抗邪为核心病机。其脉象大而坚实，既主实热内盛（如肾火上炎、胃火刑金），又主外感热病邪实正争之佳兆。然大实脉须结合病程与兼脉：新病热盛见之，为邪有外达之机，预后多良；若汗后、久病或与细小脉交替出现，则示正虚邪恋，甚至危候。三类病机", "c": "主热盛"}, {"id": "pc:尺+大+小", "n": "尺·大小脉", "o": "尺·大小脉以尺脉与寸关脉对比为特征，总属上盛下虚、阴阳不相维系之候。其核心病机可分四类：上盛下虚是脉象基础，寸关大而尺小直接反映上中焦壅盛、下焦不足；阳气不潜是上盛下虚的进一步发展，虚阳浮越于上而根虚于下；风火在上是寸大所主的具体病邪，风火壅盛于上而尺小示下元", "c": "主阳气不潜"}, {"id": "pc:尺+大+小+迟+长+短", "n": "尺·大小迟长短脉", "o": "尺部大小迟长短脉所主病机，总以脉与形性相应为吉、相失为凶，并据脉之浮大沉小判邪正盛衰与预后。其要义有四：一者形性相应，脉合体质则吉；二者邪实外达，伤寒热盛脉浮大主生；三者汗后正伤，脉宜沉小，浮大则凶；四者正虚邪陷，温病脉细小难得主死。四类之间，以邪正关系为纲：", "c": "主形性相应"}, {"id": "pc:尺+大+弱", "n": "尺·大弱脉", "o": "尺·大弱脉总以虚为纲，所主病机集中在气血不足、脾胃虚衰与下焦精血亏耗三类。原文以'两寸关脉大而弱'示上中焦气虚，'大则为虚，弱为气血不足'；以'两尺脉涩而小'示下焦血少气虚，'涩主血少，小主气虚'。寸关候上中焦、尺候下焦，上下皆见虚象，故断为气血不足、大虚之证", "c": "主气血两虚"}, {"id": "pc:尺+大+微+弱", "n": "尺·大微弱脉", "o": "尺·大微弱脉总以虚为纲，所主病机不离阴虚、气血亏虚与津伤三类。原文以'尺脉大或无力而渴'示肾阴亏虚、虚火浮越；以'脉大无力或微弱而渴'示气血两虚、脉道不充；又因气虚不能生津、脓血大泄而渴，知此脉亦主津液耗伤。三类之间相互关联：阴虚可致火旺灼津，气血虚则津液化生", "c": "主阴虚火旺"}, {"id": "pc:尺+大+急+坚", "n": "尺·大急坚脉", "o": "尺·大急坚脉总起来主正虚邪盛、重虚及阴竭阳浮三类病机。其脉大主邪盛，急坚主正虚邪结，尺部候肾与下焦，故病位在里。原文以脉之浮大沉小判伤寒温病吉凶，强调正能抗邪则生，正虚邪盛则死；又论重虚，尺虚行步恇然，脉虚不象阴，滑生涩死；更指出阴竭阳浮者死。三类病机相互关联", "c": "主正虚邪盛"}, {"id": "pc:尺+大+散", "n": "尺·大散脉", "o": "尺·大散脉总属虚候，以正气耗散、阴阳亏虚为纲。散大脉主中气虚寒、气不固摄；濡软脉主气血不足、脉道失充；尺脉浮大主真火外越、虚阳浮越；尺脉沉数主真阴内竭、虚热内生。四类病机皆从'虚'字着眼：中气虚寒与气血不足偏于中焦气分，真火外越与真阴内竭偏于下焦阴阳。散大、濡", "c": "主中气虚寒"}, {"id": "pc:尺+大+沉", "n": "尺·大沉脉", "o": "尺脉沉大，总属里证，以虚为本、郁热为标。沉主里、主气陷，大主虚阳不敛或火盛。其病机主要有三：一为脾虚气陷，中气不足，虚阳郁于下焦，见自汗足冷不能行动；二为下焦虚寒，虚阳不敛而脉反沉大，非实热之象；三为下焦湿热未清，兼脾胃气虚，见血淋、白浊、痛必有火。三者皆与脾", "c": "主脾虚气陷"}, {"id": "pc:尺+大+洪", "n": "尺·大洪脉", "o": "尺·大洪脉总属阳热亢盛之象，但所主病机因兼脉与部位而异。洪大而数者主热毒炽盛；洪大兼滑者主痰火壅盛；洪大有力独见于尺者，或为相火亢盛，或为胎孕气血充盛；洪大与沉微并见，则属上盛下虚、阳亢阴微；若尺涩而肺脉洪大无伦，又为水气上壅、下闭上壅之候。诸类之间，以热盛、", "c": "主热盛"}, {"id": "pc:尺+大+浮+涩", "n": "尺·大浮涩脉", "o": "尺·大浮涩脉在此段中实以怪脉死脉为论，总属胃气败绝、脏真耗竭之危候。其脉来如屋漏、雀啄、弹石、解索、虾游、鱼翔等，皆无胃气柔和之象，提示脏腑功能严重衰竭，阴阳将离。原文强调“脉病人不病”而见此类脉者死，说明脉象已失冲和，预后凶险。三类病机相互关联：胃气败绝为根", "c": "主胃气败绝"}, {"id": "pc:尺+大+浮+濡", "n": "尺·大浮濡脉", "o": "尺脉大浮濡，总属肾水亏虚、虚阳上浮之候。肾为坎水，虚则不能滋木，肝失濡养而风火妄动，外风引之，故头风时发、肢节酸麻。其脉浮大而濡，浮大为虚阳外浮，濡为虚软不敛，皆肾虚不能固摄之象。左脉弦细，为肝血不足、木失濡养之征。诸类病机以肾虚为本，阳浮为标，肝虚风动为 i", "c": "主肾虚阳浮"}, {"id": "pc:尺+大+浮+疾", "n": "尺·大浮疾脉", "o": "尺·大浮疾脉总属阳脉，以浮、大、疾数为其特征，主要反映阳热亢盛、邪正剧争之病机。其具体所主，须结合病程与兼脉分判：邪盛初期，脉大浮疾而正能抗邪，为顺为生；汗后津伤，脉反浮大疾数，为逆为死；若正虚邪陷，脉虽大浮疾而按之无根，或与他部沉小并见，则示阴阳离决。要之，", "c": "主阳盛"}, {"id": "pc:尺+大+浮+短", "n": "尺·大浮短脉", "o": "尺·大浮短脉在此段中实以怪脉群的形式出现，总起来主胃气败绝、脏气衰亡与死候。原文通过屋漏、雀啄、弹石、解索、虾游、鱼翔等脉象，强调其共同特征为无胃气柔和之象，脉来散乱无根、极端不和。这些脉象虽形态各异，但病机本质一致：胃气衰败则脉失冲和，脏气竭绝则脉无根柢，阴", "c": "主胃气败绝"}, {"id": "pc:尺+大+浮+空", "n": "尺·大浮空脉", "o": "尺部大浮空脉总属肾元亏虚、虚阳外浮之候。尺候肾，浮大为虚阳外浮，空为元海无根，真阳不能潜藏而上脱。原文一例，患者元阳素亏，忧怒后鼻塞咳嗽，误服散滞之品，遂致气促面赤、喉中痰响、卧不安枕，脉得尺部浮大而空，显系虚阳上奔、真阳上脱之象。三类病机——虚阳外浮、真阳上", "c": "主虚阳外浮"}, {"id": "pc:尺+大+浮+紧", "n": "尺·大浮紧脉", "o": "尺·大浮紧脉在此段中主要体现浮大与沉小的吉凶对比，其总病机围绕邪正盛衰：浮大脉在伤寒热盛时主邪实热盛、正气抗邪，为生候；但汗后见浮大则主正虚不敛、邪陷为凶。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪则死。故该脉所主病机可归为邪盛热实、正虚邪陷、正不", "c": "主邪盛热实"}, {"id": "pc:尺+大+浮", "n": "尺·大浮脉", "o": "尺脉浮大，总以肾虚阳浮为核心病机。浮大之象，非实热壅盛，乃肾气亏虚、真阳不能潜藏而外浮，故按之多无力或兼涩。其具体所主，一为肾虚阳浮，见足跟痛、气短等；二为痰饮内阻，因肾不化水，脉浮大按涩；三为真火外越，脉浮大无根，治宜引火归元；四为正虚邪实，见于伤寒温病，脉", "c": "主肾虚阳浮"}, {"id": "pc:尺+大+浮+软", "n": "尺·大浮软脉", "o": "尺部大浮软脉在《脉经》此段中，主要围绕伤寒温病过程中脉象浮大与沉小的吉凶判断展开。其总病机可归纳为三类：邪盛正抗、汗后正伤、正虚邪陷。浮大之脉在热盛时主邪有外达之机、正气尚能抗邪，为吉；但若汗后见浮大，则主正气外浮不敛、津伤阳越，为凶。沉小之脉在汗后主邪退正安", "c": "主邪盛正抗"}, {"id": "pc:尺+大+浮+长", "n": "尺·大浮长脉", "o": "尺部大浮长脉在古籍中与怪脉并列论述，总起来主胃气败绝、脏气衰竭之死候危症。其脉虽名大浮长，然原文所举屋漏、雀啄、弹石、解索、虾游、鱼翔等，皆无胃气柔和之象，或来即绝止不相联续，或数疾绝止复顿来，或辟辟急、动数散乱，皆真脏之气外露、脏气耗散之征。扁鹊以群鸟之聚、", "c": "主胃气败绝"}, {"id": "pc:尺+大+疾", "n": "尺·大疾脉", "o": "尺·大疾脉总属阳脉，以脉体大而搏动疾数为特征，总起来主阳热亢盛、邪正剧争之病机。其具体所主，须结合病程阶段、汗之有无及脉之根底分判：邪盛初期，正能抗邪，脉大疾为顺为生；阳热亢盛，脉大疾亦为热盛之征；若汗后津伤而脉反浮大疾数，则为逆为死；若大疾而按之无根，或与他", "c": "主邪盛正抗"}, {"id": "pc:尺+大+缓", "n": "尺·大缓脉", "o": "尺·大缓脉在古籍中主要关联两类病机：一是邪盛正衰的吉凶判断，二是胃气衰败的死脉辨识。原文通过脉象浮大沉小的对比，揭示邪正盛衰与预后转归的关系，如伤寒热盛脉浮大者生，汗后脉沉小者生，温病脉大疾者生，均强调正能抗邪则生；反之脉细小难得或沉小者死，示正不胜邪。同时，", "c": "主邪盛正衰"}, {"id": "pe:尺+大", "n": "尺·大脉", "o": "尺·大脉总以肾虚阳浮为核心，但所主病机因兼脉、力度及部位而异。大而无力或浮大无根，主肾虚阳浮、虚阳外越；大而有力或独大，主热盛动血、相火亢盛；大而浮中沉无力，主气血两虚、虚寒阳衰；关尺独大，主冲气上逆；右脉大垂尺泽，主胃阴不足；右大于左，主内伤劳倦；尺偏大如实", "c": "主肾虚阳浮"}, {"id": "pc:尺+大+虚", "n": "尺·大虚脉", "o": "尺·大虚脉总起来主肾虚、虚寒、虚火、阴竭及肝旺诸类病机，其核心在于“虚”与“大”并见，反映肾气不足、根本空乏，虚阳外浮或阴寒内盛。肾虚为诸类之基：肾气不固则脉大而虚；阳虚生寒则尺脉沉伏或虚大无根；阴虚火动则数大而虚；阴精枯竭则细疾或虚大而乱；肝旺则弦大而虚，木", "c": "主肾虚"}, {"id": "pc:尺+实+坚", "n": "尺·实坚脉", "o": "尺·实坚脉总属里实邪结之候。实主邪气盛实，坚主结聚不散，尺部候下焦，故其核心病机为里实积结。由此可分化四类：沉坚主病在中，横坚主胁腹积痛，是里实积聚的直接体现；尺部主下焦，实坚之邪结于下，可致寒热、疝瘕、少腹痛；坚搏之象亦示邪结深重。诸类均以实坚为纲，以邪结部", "c": "主里实积结"}, {"id": "pe:尺+实", "n": "尺·实脉", "o": "尺·实脉总起来主下焦邪实壅盛之证，以实为核心，病位偏里偏下。其具体所主涵盖胎孕、下焦实滞、里实积结、实热壅盛、痰湿土壅及正虚邪恋等类。胎孕为生理之实，非病邪；下焦实滞与里实积结多因燥屎、湿热、瘀血、积块搏结于下焦，气机壅阻而痛；实热壅盛则邪热与糟粕相结，或化火", "c": "主胎孕"}, {"id": "pc:尺+小+实+坚", "n": "尺·小实坚脉", "o": "尺·小实坚脉总属里实邪结之候。小示脉体收敛、病位较深，实坚示邪气盛实、结聚不散，故其核心病机为里实积结。由此可分化三类：一为沉坚主病在中，横坚主胁腹积痛，是里实积聚的直接体现；二为尺部主下焦，实坚之邪结于下，可致寒热、疝瘕、少腹痛；三为坚搏则气机逆乱，促击上冲", "c": "主里实积"}, {"id": "pc:尺+小+急+坚", "n": "尺·小急坚脉", "o": "尺·小急坚脉在原文中虽仅一段，然其论脉以浮大沉小判伤寒温病吉凶，实涵数类病机。总起来看，此脉所主以正虚邪陷为核心，兼及热盛邪实与汗后津伤。沉小、细小难得者，为正虚无力抗邪，故主正虚邪陷，多主死候；浮大、大疾者，为邪热亢盛而正能抗邪，故主热盛邪实，多主生候；已得", "c": "主正虚邪陷"}, {"id": "pc:尺+小+濡", "n": "尺·小濡脉", "o": "尺·小濡脉总属阴脉，主肾阴亏虚、下元不充，为先天禀质或久病耗损之象。其核心病机为坎水不足，不能济火涵木，以致相火偏旺，火灼津液，变生痰浊、咳血、瘰疬等症；同时阴亏日久，气亦不足，血亦亏虚，故兼见气弱血亏。各类病机以肾阴亏虚为本，相火偏旺为标，气弱血亏为兼，痰结", "c": "主肾阴亏虚"}, {"id": "pc:尺+小+疾", "n": "尺·小疾脉", "o": "尺·小疾脉总起来主正虚邪陷、热盛伤津及汗后正伤三类病机。其核心在于脉小疾而细小难得，反映正气虚衰、无力抗邪，或热邪炽盛而阴津耗竭。原文以伤寒温病为例，判脉之浮大沉小以决吉凶：伤寒热盛脉浮大者生，沉小者死，因浮大示邪有外达之机，沉小则邪陷正虚；温病脉大疾者生，细", "c": "主正虚邪陷"}, {"id": "pc:尺+小+缓+结", "n": "尺·小缓结脉", "o": "尺·小缓结脉总属正虚邪陷之危候。其脉小缓结，小主正虚，缓主脉道不充，结主气机阻滞。原文以脉之浮大沉小判伤寒温病吉凶，凡沉小、细小难得者多主死，示正虚不能抗邪。故本脉所主病机，一为正虚邪陷，二为汗后津伤，三为热盛正衰。三者皆以正虚为核心，或邪气内陷，或津液耗伤，", "c": "主正虚邪陷"}, {"id": "pe:尺+小", "n": "尺·小脉", "o": "尺·小脉总属虚象，以肾虚、虚损为纲。尺候肾与命门，小为不足，故凡尺脉独小、尤弱、虚小者，多主少阴久虚、肾命虚衰，或下焦虚寒、阳气不温。若兼他部虚象，则主气血亏虚、心肝脾肾俱损。在伤寒温病中，尺脉沉小、细小，为正虚邪陷之危候，预后凶险；然汗后脉沉小，则为津伤邪退", "c": "主肾虚"}, {"id": "pc:尺+小+软", "n": "尺·小软脉", "o": "尺·小软脉总起来主虚证，以脾肾两虚为核心，兼见肺虚及湿滞。脉软小乏力为气血未复，尺脉濡细为肾虚湿滞。原文喘止咳平、痰咸、食增，示病后脾肾两虚、肺金失养，水湿内停。诸类中，肾虚为本，脾虚为气血生化不足，肺虚为子盗母气，湿滞为肾虚水泛之标。四者相互关联：脾虚则肺金", "c": "主肾虚"}, {"id": "pe:尺+平", "n": "尺·平脉", "o": "尺部平脉总以尺脉异常为眼目，所主病机可归为肾虚火旺、孕脉气血盛、下焦壅塞、阳升气火四类。肾虚火旺者，尺脉洪滑，相火偏旺，灼肺动血；孕脉气血盛者，右尺洪大有力而六脉皆平，为胞宫气血充盛之常；下焦壅塞者，两尺沉绝而他脉平和，为气血壅塞于上、下焦脉气一时不通；阳升气", "c": "肾虚火旺"}, {"id": "pc:尺+弦+大", "n": "尺·弦大脉", "o": "尺·弦大脉总起来主肾虚为本、肝逆饮泛为标，兼见虚阳浮越与肝火内郁。弦为肝象，大为虚阳不敛或阳亢，尺部候肾与下焦，故其病机核心在肾虚失摄、肝气横逆。案15真阴亏而冲气上泛，属肾虚肝逆；案13698、14823肾亏饮泛，属肾虚不藏；虚阳浮越由正虚阳不附；数弦大则从", "c": "主肾虚肝逆"}, {"id": "pc:尺+弦+大+虚", "n": "尺·弦大虚脉", "o": "尺·弦大虚脉总起来主肝旺、虚阳浮越与肾虚不固，尤以肾虚失血、元气欲脱为危重。左弦大为肝旺，右虚大为虚阳不足，尺中甚乱则肾气不固，甚则房劳伤肾、元气欲脱。诸类之间相互关联：肝旺可致气机失调，虚阳因正虚而浮，肾虚不固则根本动摇，终致元气欲脱。临证须细心体察，区分水", "c": "主肝旺"}, {"id": "pc:尺+弦+实", "n": "尺·弦实脉", "o": "尺·弦实脉总起来主下焦实滞、气机壅阻之证。弦为气滞、为痛、为风，实为邪壅，尺部应下焦，故其核心病机是湿热瘀血搏结于下焦魄门，气机不畅而痛。原文一例内痔结粪疼痛夜甚，左弦尺弦实、右浮弦，正示下焦湿热瘀结为本、气滞疼痛为标，兼有风热上扰之象。诸类关系为：气滞与邪壅", "c": "主痛"}, {"id": "pc:尺+弦+微", "n": "尺·弦微脉", "o": "尺部弦微脉总起来主正虚邪伏、阳气衰微之病机。微脉主营气不足、阳气衰微，弦脉主邪郁、肝郁或寒饮内停。二者相合，多见于虚寒泄泻、虚疟等证，其核心为正气亏虚而邪气内陷。从所举两案看，一为年高久泻，脾肾阳弱，肝经虚寒，水湿不化；一为少阳疟邪内陷，胃气大虚，伏邪未透。虽", "c": "主虚寒"}, {"id": "pc:尺+弦+急", "n": "尺·弦急脉", "o": "尺·弦急脉总起来主邪盛正衰、津伤气逆及脏气衰绝之候。其病机核心在于脉失冲和，弦急为肝木偏亢或胃气败竭之象。各类之间相互关联：邪盛正衰与汗后津伤属外感病程中的逆候，反映正不胜邪；形性相违强调脉与体质不符，提示气血逆乱；脏气衰绝则为最终转归，见弦急长脉而无胃气，预", "c": "主邪盛正衰"}, {"id": "pc:尺+弦+急+长", "n": "尺·弦急长脉", "o": "尺·弦急长脉在古籍中归于死脉、怪脉之类，总起来主脏气衰绝、胃气败竭，预后凶险。其核心病机是脏腑真气耗散，胃气不能柔和脉道，故脉来弦急而长，失却冲和之象。原文以屋漏、雀啄、弹石、解索等怪脉为例，皆属无胃气之死脉，并强调『脉病人不病』见此类脉者死，说明脉象已脱离常", "c": "主脏气衰绝"}, {"id": "pc:尺+弦+沉", "n": "尺·弦沉脉", "o": "尺·弦沉脉总属水郁火逆、血水互结之候。尺部为水所居，沉主水气内伏，弦主饮邪结聚，故其核心病机为水饮内结；水饮不化，浸淫血分，则成血中之水；水郁日久，酿火随经上逆，则见火逆动血、衄血目晕。三类病机以水饮内结为根，血中之水为水饮入血之变，火逆动血为水郁化火之变，层", "c": "主水饮内结"}, {"id": "pc:尺+弦+洪", "n": "尺·弦洪脉", "o": "尺·弦洪脉总属肾阴亏虚、虚火浮越之象。弦为血少、为肝气不和，洪为火盛，见于尺部则根本不足而虚阳外浮。其病机主要有三：一为阴虚火旺，劳瘵足三阴亏损，无根之火浮于外，甚则血随火泛而衄吐血；二为肾虚有火，左尺浮洪，肾水不足而火旺，致小便疾速余沥、大便燥结；三为血少气", "c": "主阴虚火旺"}, {"id": "pc:尺+弦+浮", "n": "尺·弦浮脉", "o": "尺部弦浮脉在内伤自汗的语境中，主要提示两类病机：一是阳虚不固，自汗出而脉浮，属阳气虚浮；二是水亏火旺，左尺浮洪无力，为肾水不足、虚火上炎。二者皆以虚为本，浮脉为虚阳或虚火外浮之象，而非表邪。弦脉在此段未直接论及，然左关浮弦为挟风邪，可推知弦浮并见亦主风动或虚风", "c": "主阳虚自汗"}, {"id": "pc:尺+弦+涩+缓", "n": "尺·弦涩缓脉", "o": "尺·弦涩缓脉总起来主肾水亏乏、血液枯槁、肝木凌脾，进而成噎膈之证。其脉象以尺部浮而无根为根柢，示肾水亏虚；余部弦涩而缓，弦属肝木，涩为血少，缓为脾脉，合而观之，乃肝木凌脾、血液枯槁之候。肾水亏则不能涵木，肝木横逆则克伐脾土，脾失健运则气血生化乏源，血少则脉道涩", "c": "主肾水亏乏"}, {"id": "pc:尺+弦+涩", "n": "尺·弦涩脉", "o": "尺·弦涩脉总起来主下焦阴血亏虚、肝木失柔、阳升风动之病机，其核心为“下虚上实”。尺涩主营阴血少，弦主肝阳偏亢或肝燥，二者相合，反映肾水亏于下、肝木亢于上的格局。具体可分五类：阴血亏虚为其根本，肝阳上亢与肝燥风动为常见上实之象，冲脉不调为下焦气血失和之变，阴虚火", "c": "主肝阳上亢"}, {"id": "pc:尺+弦+滑", "n": "尺·弦滑脉", "o": "尺·弦滑脉总起来主气血流利、水湿痰浊、肝木乘土及肾寒水泛。弦为肝木之象，滑主水湿痰浊，尺部候肾与下焦。其病机有常有变：常者，如脉弦滑流利，为气血充盈、应时生发之象，非病脉；变者，如右关尺滑弦，为脾肾同病，肾寒水泛，肝木乘土，水湿痰浊内蕴，酿蒸发黄。各类之间，肝", "c": "主气血流利"}, {"id": "pc:尺+弦+细+涩", "n": "尺·弦细涩脉", "o": "尺·弦细涩脉总起来主精血亏虚、肝风内动、肾阴亏虚及营液不养之病机。其核心在于肾精亏于下、肝风亢于上，形成下虚上实之候。脉细主精血不足，弦主肝风内动，尺涩为肾精不足、血行不畅。两段原文均见“高年精血亏损”或“肝气化火劫烁阴津”，故精血亏虚为根本，肝风内动为标象，", "c": "主精血亏虚"}, {"id": "pc:尺+弦+细+紧", "n": "尺·弦细紧脉", "o": "尺部弦细紧脉总属阴寒内盛、痰饮阻滞兼血虚之候。紧主寒，弦主痛主饮，细主血虚，四类病机相互关联：寒邪内侵，阳气受遏，水饮不化，痰饮内结，阻滞气机则痛；久病产后，下血伤阴，血虚脉道不充则细。寒、饮、痛、血虚交织，形成本脉。原文中寒痰饮、误服凉药后脉更沉小，进一步印", "c": "主寒"}, {"id": "pc:尺+弦+细", "n": "尺·弦细脉", "o": "尺·弦细脉总起来主肾虚肝郁、精血亏虚、肝风内动及阳衰寒凝之病机。其核心在于肾精亏于下、肝木失于濡养，形成下虚上实或本虚标实之候。脉细主精血不足，尺部细尤显肾精亏虚；弦主肝郁气滞、风动或疼痛。三类病机相互关联：肾虚肝郁者，精血亏虚而肝气偏旺；肝虚风动者，水不涵木", "c": "主肾虚肝郁"}, {"id": "pc:尺+弦+细+虚", "n": "尺·弦细虚脉", "o": "尺·弦细虚脉总起来主正虚邪恋、虚实夹杂之证。其脉象由两部分构成：脉弦主邪郁少阳，为邪气留恋半表半里、气机郁滞之象；两尺虚细主肾气亏虚，为正气不足、精血亏乏之征。二者并见，说明患者体虚受邪，寒热久羁，正虚而邪不得速解，形成虚人外感之候。原文以“体虚受邪”为总纲，", "c": "主正虚邪恋"}, {"id": "pe:尺+弦", "n": "尺·弦脉", "o": "尺部弦脉总属肝木为病，而涉及肾与下焦。弦为肝脉，主气郁、主痛、主积、主寒。其病机大致可分：肝郁气结，寒凝痛积，肾虚水亏，虚寒泄利，血少枯槁，以及寒热错杂。弦而紧数，多主寒热；弦而涩缓，多主血少；弦而尺弱，多主肾虚；弦而细微，多主虚寒。诸类之间，以肝郁气结为枢，", "c": "主寒凝痛积"}, {"id": "pc:尺+弦+虚+濡", "n": "尺·弦虚濡脉", "o": "尺·弦虚濡脉总起来主肝、脾、肾三阴亏虚，兼夹湿痰为患。其病机核心在于脾虚运化失职，湿痰内蕴，故右脉浮小软滑；同时肝肾阴亏，水不涵木，精关不固，故左脉虚弦尺濡。脾虚生湿痰，肝肾亏虚则筋脉失养、精滑不固，三者相互影响，形成虚实夹杂之候。原文以异功散益气调脾祛湿痰，", "c": "主脾虚湿痰"}, {"id": "pc:尺+弦+虚", "n": "尺·弦虚脉", "o": "尺·弦虚脉总起来主本虚标实、虚实夹杂之候。其核心在肾虚不固：尺候肾，虚则封藏失职，精血亏乏，故遗精、腰酸、耳鸣；肾水亏则木失涵养，肝阳化风，故脉弦而见眩晕、呕吐欲仆，此为本虚标实之肝阳化风。肾阴不足，虚火内生，则尺举数按不足、濡耎而喉舌干燥，是为阴虚火旺。若弦", "c": "主肾虚不固"}, {"id": "pc:尺+弦+长", "n": "尺·弦长脉", "o": "尺·弦长脉总起来主病机以肾虚火旺、血少、肝气不和为主。其核心在于阴血亏虚与气机失调：弦为血少，尺脉浮洪为肾虚有火，肝脉弦而不长为肝气不和。三者相互关联，阴血不足可致肝气偏亢，肾火内扰又可耗伤阴血，形成虚实夹杂之候。下属尺·弦急长脉则属死脉、怪脉，主脏气衰绝、胃", "c": "主肾虚火旺"}, {"id": "pc:尺+弱+急", "n": "尺·弱急脉", "o": "尺·弱急脉总起来主正虚而肝木亢盛之候。弱脉主气血亏虚，急脉主肝木躁动，二者并见，提示肺肾并亏于下，肝阳偏亢于上，形成虚中夹实之局。其病机核心为肝木侮土：因下元亏虚，肝失濡养而躁急，横逆犯脾，故见腹痛、便溏；上则肺肾亏虚，故咳嗽、咽痛、恶寒。诸类之间以虚为本，以", "c": "主虚"}, {"id": "pe:尺+弱", "n": "尺·弱脉", "o": "尺·弱脉总属虚证，以肾虚为核心，涉及阴阳精血多个层面。弱脉示脉道不充、气血不足，尺部候肾，故首主肾阴亏虚与肾阳虚衰：阴亏则精血不足、虚风内动、水不济火；阳衰则命火式微、脾肾虚寒。其延伸病机包括阴阳两虚（阴不足而阳下陷）、气血虚（营气不足、血虚筋急）、虚阳上浮（", "c": "主肾虚"}, {"id": "pc:尺+弱+软", "n": "尺·弱软脉", "o": "尺·弱软脉总起来主虚，以肾阳亏虚、中气不足及脾肾火土并衰为核心。尺部软弱专候肾阳亏虚，封藏失固，气化无权，故小溲清长；寸关虚小或右软则示中气不足、脾土虚弱，中无砥柱之权；右软与尺弱并见，又主脾肾火土并衰，火不生土、土不制水。三类病机相互关联：肾阳亏虚可致火不生", "c": "主肾阳亏虚"}, {"id": "pc:尺+弱+迟", "n": "尺·弱迟脉", "o": "尺·弱迟脉总属阳气虚衰、营血不足之象。迟主阳虚，弱主气衰血少，尺部候肾，故其病机核心为肾阳亏虚与营气不足。肾阳不足则水湿不化，泛溢肌肤而为肿满，下趋膀胱则小溲变化；阳虚不能温煦，则形寒身热、得汗而退。营气不足则血少，脉道不充，故尺脉迟弱。脾阳根于肾阳，肾阳虚衰", "c": "主阳虚水湿"}, {"id": "pc:尺+微+小", "n": "尺·微小脉", "o": "尺部微小脉在《脉经》相关段落中，主要出现在伤寒、温病等外感热病的危重阶段。其总病机为正气虚衰、邪气内陷，具体可归纳为三类：正虚邪陷、津伤热陷、病危不治。原文以脉之浮大与沉小对比判吉凶：伤寒热盛脉浮大者生，沉小者死，因浮大示邪有外达之机，沉小则正虚不能抗邪；汗后", "c": "主正虚邪陷"}, {"id": "pc:尺+微+弱", "n": "尺·微弱脉", "o": "尺·微弱脉总属虚候，以阳气虚衰、正气不足为核心病机。其类可分四端：一主阳虚，尺候肾与下焦，微弱为肾阳不足、下元虚冷，故见虚寒积冷、小便不禁；二主气虚，微弱为正气亏虚，右尺尤甚则下焦气弱，脾虚不运可致便秘；三主正虚禁汗，微弱为无阳，弦微为虚，妄汗则亡阳伤津；四主", "c": "主阳虚"}, {"id": "pc:尺+微+洪", "n": "尺·微洪脉", "o": "尺·微洪脉在此段总起来主虚寒夹虚火、脾虚不摄之崩漏。其核心病机为下焦沉寒、中气已虚，虚阳外浮而现微洪，故脉虽洪而按之无力。各类关系：虚寒是病本，虚火是标象，脾虚不摄是崩漏的直接机制，崩漏是最终病果。四者相互关联：沉寒伤阳，中虚失摄，血海不固则崩漏；虚阳浮越则尺", "c": "主虚寒"}, {"id": "pc:尺+微+涩+弱", "n": "尺·微涩弱脉", "o": "尺·微涩弱脉总属虚候，主肾气衰败、真气不全及胎元不固。其脉象以微弱涩滞、按之无根为特征，与胎脉之微滑按之不绝形成对比。原文强调尺脉涩或微弱者，非胎脉之微滑不绝，乃真气不全、肾气衰败之象；若见于孕妇，则胎元不固，需大补保胎。三类病机相互关联：肾气衰败为根本，真气", "c": "主肾气衰败"}, {"id": "pc:尺+微+涩", "n": "尺·微涩脉", "o": "尺·微涩脉总属虚候，以微弱涩滞、按之无根为特征，主正气亏虚、气血不足及脏气衰败。其病机类别相互关联：阴血不足与荣卫两虚侧重气血亏虚，为微涩脉常见之虚象；肾气衰败与胎元不固则专指下焦元气虚衰及胎失所养，多见于尺部微涩弱；脏气衰绝则为虚之极，微涩细微无根，胃气败绝", "c": "主阴血不足"}, {"id": "pc:尺+微+缓", "n": "尺·微缓脉", "o": "尺部微缓脉在本案中总主气血两亏、正虚邪恋之候。三则原文均以'尺寸脉俱微缓'与'泄痢一载，气血两亏'并见，可知微缓为下焦元气虚衰、气血双损之象。然此虚非单纯之虚，乃痰积、湿热、肝气交阻日久，耗伤气血所致，故脉象又寓正虚邪恋、攻补两难之意。微主阳气衰微，缓主正气不", "c": "主气血两亏"}, {"id": "pe:尺+微", "n": "尺·微脉", "o": "尺·微脉总主阳气衰微、阴寒内盛之病机。其核心为下焦阳虚，故见尺部脉微；阳虚则阴寒内生，或虚阳上浮，或冲气上逆，或神气浮散，或气血俱虚。各段所论，或单见尺微，或寸口与尺并见，皆不离阳衰阴盛之本质。微为阳衰，弱为阴不足，濇为血少，伏为火不归元，诸脉相兼，则病机有偏", "c": "主阳虚阴盛"}, {"id": "pc:尺+微+迟", "n": "尺·微迟脉", "o": "尺·微迟脉总以血实内结、气机逆乱为核心病机。寸口脉微而迟，提示正气不足、气血运行无力；尺脉沉为血、滑为实，反映血实内结。实邪入络胸臆，阻滞气机，导致肺失宣降、心肝气机逆乱，出现喘息不能、色薄、厥逆不识人等症。两类病机相互关联：血实内结为病之本，气机逆乱为病之标", "c": "主血实内结"}, {"id": "pc:尺+急+坚", "n": "尺·急坚脉", "o": "尺·急坚脉总起来以正虚邪陷为核心，兼及热盛邪实与汗后津伤。其脉急坚主正虚邪结，尺部候肾与下焦，故病位在里。原文以浮大沉小判伤寒温病吉凶：浮大、大疾者，为邪热亢盛而正能抗邪，故主生；沉小、细小难得者，为正虚无力抗邪，故主死。已得汗后脉宜沉小静敛，反浮大则津伤阳浮", "c": "主正虚邪陷"}, {"id": "pe:尺+急", "n": "尺·急脉", "o": "尺急脉总起来主下焦病机，以正虚为本，急脉为标，形成虚实夹杂之候。其核心在于下元亏虚，或阳气上逆，或肝木亢盛，或寒凝收引，或邪结正伤。各类之间相互关联：下虚阳浮与虚中夹实均以正虚为基础，前者侧重阳气上逆，后者侧重肝木侮土；虚寒筋急突出寒凝收引；正虚邪陷与邪盛正衰", "c": "主下虚阳浮"}, {"id": "pc:尺+数+动", "n": "尺·数动脉", "o": "尺·数动脉总起来主热扰冲任、胎元不固之病机。数脉主热，尺部动脉主胎动不安，二者相合，反映热邪内动、冲任失调，胎元失固。原文以'形瘦。脉数尺动。不食恶心。证象恶阻。腰痛见红。为胎漏欲坠'为据，指出该脉象既见恶阻之热扰，又见漏红之胎危，故其病机核心为热与胎动不安相", "c": "主热"}, {"id": "pc:尺+数+坚+硬", "n": "尺·数坚硬脉", "o": "尺·数坚硬脉总属下焦实热之候。数脉主热，坚硬主实，左尺候下焦，故其核心病机为下焦火热内实。火热壅滞下焦，则见下痢肛门火热滞坠、小溲热痛；火实于下，挟热上冲，则肺胃之气不得下降，反致鼓激，发为呃忒。三类病机中，“主热”言其性，“主实”言其邪，“主火逆”言其势，三", "c": "主热"}, {"id": "pc:尺+数+大+洪", "n": "尺·数大洪脉", "o": "尺部数大洪脉总属阳热实邪为患，但具体病机有实热与虚火之分。其一为热毒炽盛，如杨梅疮毒内陷，六脉洪大而数，热毒壅滞气血，症见喘咳、肛脱疮满等；其二为阴火太旺，两尺洪大且数而中取不见，属水亏火炎、相火妄动，症见足痛如焚、定时哭闹。此外，洪大数脉亦反映邪正交争之象，", "c": "主热毒炽盛"}, {"id": "pc:尺+数+大", "n": "尺·数大脉", "o": "尺·数大脉总起来主热，但热有虚实之分。实热方面，可主肾火上炎、燥火伤津、积热内蕴及热盛邪实，脉象数大有力，多伴洪、弦、实等，为阳热亢盛之象；虚热方面，主虚阳外浮，脉数大而虚，乃阳气虚弱、阴精亏虚、虚火内动所致。各类之间，实热多因外邪或脏腑积热，虚热多因阳虚及阴", "c": "主虚阳外浮"}, {"id": "pc:尺+数+大+虚+空", "n": "尺·数大虚空脉", "o": "尺·数大虚空脉总起来主正虚邪实、寒热错杂之病机。数大主热，空虚主正虚，尺洪盛主少阴受邪，三者相合，反映热邪亢盛与正气亏虚并存，且病位涉及少阴肾经。此脉见于痢疾兼外感之复杂证候，内有湿热欲成痢，外有时令热邪相合，又因房劳骤寒乘少阴，致太少两感。各类病机相互关联：", "c": "主热"}, {"id": "pc:尺+数+大+虚", "n": "尺·数大虚脉", "o": "尺·数大虚脉总起来主阳气虚弱、阴精亏虚、虚火内动之病机。其脉象特征为尺部数大而虚，数大非实热，乃虚阳外浮、阴不敛阳所致；虚大无力，为阳气不能内守；尺数则反映阴精亏虚、虚火内动。三者相互关联：阳虚日久及阴，阴精亏耗，阴不敛阳，龙雷之火不藏，故脉见数大而虚。此脉多", "c": "主阳虚外浮"}, {"id": "pc:尺+数+实", "n": "尺·数实脉", "o": "尺·数实脉总起来主邪热内盛、积滞结实，属实证、热证，治当审脉攻邪。然其具体所指有别：常脉之数实，主邪盛可攻；若尺脉微弱，则属正虚禁汗下，从反面界定数实之实。更危重者，数紧实脉兼绝止散乱，与怪脉并列，为胃气败绝、脏气衰败之死候，已非单纯实热。三类之间，以邪盛为核", "c": "主邪盛"}, {"id": "pc:尺+数+小", "n": "尺·数小脉", "o": "尺·数小脉总属虚候，主下元虚竭、血室空虚、虚阳外浮及阴伤邪陷。其脉细小难寻，按之无力，反映肾精亏耗、阴血不足，脉道不充；右部软大无力为虚阳外浮，左关弦细为阴伤，尺部细小难寻为下元虚竭。诸类相互关联：下元虚竭与血室空虚为本，虚阳外浮与阴伤邪陷为标，皆因虚致变，故", "c": "主下元虚竭"}, {"id": "pc:尺+数+弦+大", "n": "尺·数弦大脉", "o": "尺·数弦大脉在古籍中仅见一例推论，其核心病机为肝经火热内郁。弦主肝，大主阳亢，数主热，尺部候肾与下焦，故脉象组合指向肝肾火旺。此脉所主病机单一，即肝火内郁，未见其他类别。总述：该脉总起来主肝火亢盛，病位在下焦肝肾，病性属热。弦大数为阳热之象，提示肝阳偏亢、火热", "c": "主肝火"}, {"id": "pc:尺+数+弦+弱", "n": "尺·数弦弱脉", "o": "尺·数弦弱脉总起来主肺肾阴亏、络有蕴热之痿躄。尺弱为肾阴亏虚，寸关弦数为肺热络蕴，二者合见，示阴虚为本、内热为标，肺热叶焦、肾阴不足，筋脉失濡，故两足痿软、不便步履。三类病机中，阴虚与内热互为因果，共成痿躄之由；痿躄为最终病果，非独立病机。此脉以虚为本、以热为", "c": "主阴虚"}, {"id": "pc:尺+数+弦+涩", "n": "尺·数弦涩脉", "o": "尺·数弦涩脉总属阴虚火旺、肝阳偏亢之候。其核心病机为肾阴亏耗，阴不制阳，导致肝阳偏亢与虚火内生。尺涩主营阴亏虚，数为阴虚内热，弦为肝阳上扰。三者相合，反映了下焦阴亏、木火失制的本虚标实格局。原文以「阴虚火盛」概括，故治疗拟滋水清肝，标本兼顾。此脉所主诸类病机相", "c": "主阴虚火旺"}, {"id": "pc:尺+数+弦+滑", "n": "尺·数弦滑脉", "o": "尺·数弦滑脉总属阴虚火盛、肝阳化风、痰火窜络之候。弦为肝阳易动，滑为烁液成痰，数为火盛，尺部候下焦，故其病机以肝热为始，热郁湿滞则湿浊下注；火盛灼阴则阴虚火旺；阴亏木旺则肝阳化风；风火相煽，灼液成痰，痰火流窜经络。诸类之间，肝热与湿浊下注常相兼为患，阴虚火盛为", "c": "主肝热"}, {"id": "pc:尺+数+弦+细+小", "n": "尺·数弦细小脉", "o": "尺部数弦细小脉总起来主肝郁化火、阴亏火旺之病机。弦主肝郁，细小数主阴亏火旺，二者相合，揭示肝气郁结、郁久化火、阴血亏虚、虚火内扰的复杂状态。肝郁化火可下迫膀胱致溺痛尿血，火郁筋脉致手腕酸痛；阴亏火旺则经水无定、虚火内生。三类病机中，肝郁为始动，阴亏火旺为本质，", "c": "主肝郁"}, {"id": "pc:尺+数+弦+细+滑", "n": "尺·数弦细滑脉", "o": "尺部脉见弦细滑数，总属阴虚火盛、肝阳化风、痰火窜络之候。弦为肝阳易动，滑为烁液成痰，数为火盛，细为阴伤。四者相合，揭示水亏木旺、火炽生风、灼液成痰、痰火流窜经络之病机链。其核心在阴虚为本，火盛为标，风动痰生为变。诸类之间，肝阳化风与火盛阴虚互为因果，痰窜经络与", "c": "主肝阳化风"}, {"id": "pc:尺+数+弦", "n": "尺·数弦脉", "o": "尺·数弦脉总起来主下焦热象，以肝火为核心，兼涉阴虚、痰火。弦主肝郁气滞，数主热，尺候下焦，故其基本病机为肝经火热或下焦郁热。具体分四类：实火者，肝阳暴升、木火炽盛，脉洪而有力；虚火者，肾阴亏耗、阴不制阳，脉弦数而弱或涩；痰火者，火盛灼液成痰，脉弦数兼滑；下焦热", "c": "主肝火"}, {"id": "pc:尺+数+弱", "n": "尺·数弱脉", "o": "尺·数弱脉总起来主下元亏虚、虚阳上浮、阴阳不相维系之病机。尺弱为肾阴亏虚、下元不摄，是病之本；数脉为虚热，因下虚而虚阳浮动，是病之标。二者合见，形成下虚上实、阴阳不相维系之局，故见气逆上升、厥逆若痉、神志模糊，甚则厥汗而脱。三类病机中，下元亏虚为本，虚阳上浮为", "c": "主下元亏虚"}, {"id": "pc:尺+数+散", "n": "尺·数散脉", "o": "尺·数散脉在古籍中虽仅此一段论述，但通过脉象与病证吉凶的对比，可归纳其主病机为邪盛正衰、热盛、津伤、正虚四类。总起来看，该脉所主病机核心在于邪正盛衰的消长关系：脉浮大或大疾多主邪热亢盛、正气尚能抗邪，为生机之象；脉沉小或细小则主正虚或津伤，正不胜邪，预后凶险。", "c": "主邪盛正衰"}, {"id": "pc:尺+数+沉", "n": "尺·数沉脉", "o": "尺脉沉数总属里热为患，沉主里，数主热，尺部应下焦，故其病机核心为热邪内蕴下焦或阴分。具体而言，或为实热结于膀胱、肠胃、三阳之里，或为热入血室、热陷血分，或为燥火伤津、三消下焦，或为真阴内竭、虚热内生。实热者脉多沉数有力，虚热者脉多沉细而数。各类之间以“热”为纲", "c": "主里热"}, {"id": "pc:尺+数+洪", "n": "尺·数洪脉", "o": "尺·数洪脉总属火热之象，但须分虚实。实者多因湿热下注或下焦实热壅盛，脉洪数有力，伴小便赤涩、脱肛肿痛等症；虚者多因肾阴亏虚、虚火上炎，脉洪数而按之无力，伴发热、口渴、形瘦等症；甚则真阴耗竭、虚阳外越，脉洪数无伦而按之微细若无，属戴阳危候。各证之间可相互转化，如", "c": "主肾虚火旺"}, {"id": "pc:尺+数+浮", "n": "尺·数浮脉", "o": "尺部浮数脉总起来主阴虚阳浮、燥火伤津及表热正虚三类病机。浮为阳脉，数主热，见于尺部而按之无力或无根，多因阴液亏虚，阳气失于潜藏而浮越，故主阴虚阳浮；若浮数见于寸部，或兼洪、沉、大、细数，则为燥火伤津，分主三焦燥热；浮数并见而按之有力，为表热，若兼无力或尺弱，则", "c": "主燥火伤津"}, {"id": "pc:尺+数+滑+微", "n": "尺·数滑微脉", "o": "尺部数滑微脉，总起来主痰热内阻、气逆络痹、经气不布之病机。其脉象以滑为主，兼见微数，滑为痰湿，数为热象，微数示热势不张而痰热胶结；关尺同见，则痰热阻于中下焦。右寸脉溢，气逆不降，津液不布，聚痰生热；左手弦滑，肝郁痰凝，络脉痹阻。痰热阻于阳明，冲脉隶于阳明，经气", "c": "主痰热"}, {"id": "pc:尺+数+滑", "n": "尺·数滑脉", "o": "尺·数滑脉总属肾与下焦病机，以肾阴亏虚、虚火内动为基础，兼见火实与虚阳外越之变。数主热，滑主阴液不足或痰湿，尺部候肾，故其病机围绕肾之阴阳虚实。肾水不足则虚热内生，脉见数滑；若火实于内，则脉沉实而数；若阴不敛阳，虚阳外越，则脉浮大而数。三类之间，肾水不足为根本", "c": "主肾水不足"}, {"id": "pc:尺+数+濡", "n": "尺·数濡脉", "o": "尺·数濡脉总起来主湿温阴伤、痰热气弱、下虚阳浮及外感风燥之证。其脉象由三部合参：濡主湿，数主热，尺软主下虚。本案冬温之候，外感袭于肺胃，故见数脉与身热咳呛；湿痰内蕴，气机上逆，故脉濡而痰鸣气升；下元虚衰，不能潜藏，故尺脉软而阳失潜藏。四类病机相互关联：下虚为根", "c": "主湿温阴伤"}, {"id": "pc:尺+数+濡+软", "n": "尺·数濡软脉", "o": "尺·数濡软脉总起来主下虚外感、湿热痰逆之证。其脉象由三部合参：濡主湿，数主热，尺软主下虚。本案冬温之候，外感袭于肺胃，故见数脉与身热咳呛；湿痰内蕴，气机上逆，故脉濡而痰鸣气升；下元虚衰，不能潜藏，故尺脉软而阳失潜藏。四类病机相互关联：下虚为本，外感为诱因，湿热", "c": "主下虚"}, {"id": "pc:尺+数+疾", "n": "尺·数疾脉", "o": "尺部数疾脉在此段中并非寻常热象，而是作为死脉之气出现。其总病机为胃气败绝、脏气竭尽、阴阳离决。原文以屋漏、雀啄、弹石、解索等怪脉为例，强调‘无胃气柔和之象’，脉来数疾而绝止复顿，或急疾散乱，皆属真脏脉外露。‘脉病人不病’而见此脉者死，说明数疾之象在此非实热，而", "c": "主胃气败绝"}, {"id": "pc:尺+数+紧+实", "n": "尺·数紧实脉", "o": "尺部数紧实脉在此段中并非单纯主热、主积之常脉，而是与屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉并列，作为'死脉之气'来论述。其核心病机是胃气败绝、脏气衰败、脉失柔和。原文以'脉病人不病'而见此类脉者死，突出其危重性：数紧实之中兼绝止、散乱、急疾无根，说明邪气虽盛", "c": "主胃气败绝"}, {"id": "pc:尺+数+紧", "n": "尺·数紧脉", "o": "尺·数紧脉总起来主寒热错杂、邪实内蕴之病机。数主热，紧主寒，二脉相合，多反映寒热相搏、脾胃受伤、谷气不消之证，尤以谷疸发黄为典型。其具体所主，可归纳为寒热错杂、谷疸发黄、脾伤食满、邪盛可攻数类；若数紧实脉兼见怪脉，则又主胃气败绝之危候。诸类之间，以寒热错杂为基", "c": "主谷疸发黄"}, {"id": "pc:尺+数+细+小+濡", "n": "尺·数细小濡脉", "o": "尺脉数细小濡，总属虚实夹杂之候，以湿热蕴结下焦、肝肾阴虚络损、气化不利三类病机为主。数主热，濡主湿，细小主阴伤，合见于尺部，说明下焦既有湿热壅遏，又有阴液亏耗，湿热灼伤阴络则尿血、茎中鲜血频滴；阴虚气化不利则小便涓滴难出、大便艰涩。三证相互关联：湿热久蕴必耗阴", "c": "主下焦湿热"}, {"id": "pc:尺+数+细", "n": "尺·数细脉", "o": "尺·数细脉总以“阴液亏虚、虚火内扰”为纲。细主阴血不足，数主虚热躁动，二者相合，故所主病机多归阴虚火旺一类。然其具体所主，又因脉位与兼象而异：两尺细数，专主肾水枯涸、真阴不足，或肾痹水衰火动；左寸细数，主心血虚而火扰；左关细数，主肝血不足有火；右关细数，主脾阴", "c": "主阴虚火旺"}, {"id": "pc:尺+数+细+虚+弱", "n": "尺·数细虚弱脉", "o": "尺部数细虚弱脉总主肾虚，以肾中阴阳水火之虚为纲。左尺虚弱细数，主肾阴不足、虚火内生；右尺迟软或沉细数欲绝，主命门相火衰微；两尺微弱，则阴阳俱虚。若虚火浮越，则见弦洪无根之脉，并伴劳瘵虚热、衄吐血等症。诸类之间，以肾虚为本，或偏阴虚火旺，或偏阳虚火衰，或阴阳两虚", "c": "主肾阴虚火旺"}, {"id": "pe:尺+数", "n": "尺·数脉", "o": "尺部数脉总以“热”为纲，然须分虚实。实者多因下焦实热、湿热壅盛或瘀热积结，脉数有力；虚者多因肾阴亏虚、虚火内扰，脉数而细或无力。相火妄动、阳升气火亦属虚火之变，甚则真阴耗竭、虚阳外越，脉数无伦而按之空虚，为危候。诸类之间，以阴虚火旺为本，实热、湿热、瘀热为标，", "c": "主阴虚火旺"}, {"id": "pc:尺+数+虚", "n": "尺·数虚脉", "o": "尺·数虚脉总起来主肾阴亏虚、虚火内动、阴不敛阳之病机。其脉象特征为尺部数而虚，数非实热，乃阴虚生内热、虚阳外浮所致；虚为肾阴不足、阳气不能内守。原文以上齿痛、午后尤甚为佐证，说明虚火上炎而非阳明实火。三类病机相互关联：肾阴亏虚为根本，阴虚则生内热，虚火循经上炎", "c": "主肾阴虚火旺"}, {"id": "pc:尺+数+软", "n": "尺·数软脉", "o": "尺·数软脉总起来主下元虚衰、虚火内扰、水火不交之证。其脉象由三部合参：软数为虚火内扰，尺虚濡为肾水亏乏。本案下消症得之肝郁波及心肾，致水火不交，肾水不能上承，心火难以下降，正合未济之卦。脉软数示火在水上，尺虚濡示下元虚竭，故证非轻候。三类病机相互关联：下虚为根", "c": "主虚火"}, {"id": "pc:尺+沉+伏", "n": "尺·沉伏脉", "o": "尺·沉伏脉总起来主肾虚、阳气不足，并由此衍生火不归元与正虚邪陷两类病机。其核心在于尺部候肾，沉伏为阳气不能鼓动、肾气亏虚之象。肾虚则火失潜藏，虚阳浮游，故见上下循环发热、足底热甚；阳气不足则脉微无力，与沉伏并见。在伤寒温病中，沉小伏细之脉又提示正气不足、邪气内", "c": "主肾虚"}, {"id": "pc:尺+沉+坚", "n": "尺·沉坚脉", "o": "尺部沉坚脉，总起来主里实、内积、病位在中之病机。其脉沉则示病不在表而在里，坚则示邪气结聚、非虚软之象，故与“浮而盛者病在外”相对，专主邪实于内。原文以“病在中”一语总括，又列沉而横主胁下积、腹中横积痛，可见沉坚与积块内结同属一类。三类之间实为一体：沉定病位，坚", "c": "主里实"}, {"id": "pc:尺+沉+实", "n": "尺·沉实脉", "o": "尺部沉实脉总属里实之象，沉主在里，实主有形邪结。其具体所主，一为下焦结粪，燥屎内停，脉沉实有力；二为肠胃实热，邪热与糟粕相结；三为火实内结，上部沉实而渴，治当泻火。三者皆以“实”为核心，或结于肠腑，或蕴于肠胃，或化火内实，病位偏里，性质属实。原文又特别强调与死", "c": "主里实结粪"}, {"id": "pc:尺+沉+小+实+急", "n": "尺·沉小实急脉", "o": "尺部沉小实急脉，总起来主邪盛正衰、脉证相反之危候。沉小为正气不足、邪气内陷之象，实急则示邪实内结或余邪未净。在伤寒热盛时，脉当浮大以应邪有外达之机，今反沉小实急，故主病进；汗后脉宜静敛，沉小为顺，实急则为变；温病大热脉当大疾，沉小实急则正不胜邪。三类病机均围绕", "c": "主邪盛正衰"}, {"id": "pc:尺+沉+小", "n": "尺·沉小脉", "o": "尺·沉小脉总属正虚阴盛之象，其病机可归为四类：阳虚阴盛、正虚邪陷、津伤脉静、正衰危候。沉小之脉，沉为在里，小为不足，故总主正气虚衰、阴寒内盛。然其吉凶迥异：若阳虚阴盛，温阳可复；若邪陷正虚，则为逆候；若汗后津伤而脉静，反为脉证相符之吉；若温病大热而脉细小难得，", "c": "主阳虚阴盛"}, {"id": "pc:尺+沉+弱", "n": "尺·沉弱脉", "o": "尺·沉弱脉总以肾气亏虚、气阴早衰为基本病机。沉为在里，弱为不足，尺部候肾，故凡尺见沉弱，多责之肾元亏虚、气阴耗损。肾水不足，不能涵木，则肝木失柔，或化风上旋，或弦象微露，故又主水亏木旺之机。若阳气式微，阴寒内盛，正虚邪凑，则可见寒热及疝瘕少腹痛之证。四类病机以", "c": "主肾气亏虚"}, {"id": "pc:尺+沉+微", "n": "尺·沉微脉", "o": "尺·沉微脉总属肾与命门阳气虚衰、阴血不足之候。沉为在里，微为阳衰气弱，尺部候肾与胞宫，故其病机核心为肾虚、阳衰，并可因阳虚不化水而兼寒饮内停。三类之间相互关联：肾气与阴血不足则冲任失养而艰于育子；真阳衰微则沉寒内伏、厥逆冲气；阳虚不能蒸化水液则饮停上逆。原文或", "c": "主肾虚"}, {"id": "pc:尺+沉+浮", "n": "尺·沉浮脉", "o": "尺部沉浮脉在此专指尺脉当沉反浮而无根，总属肾水亏乏、根本虚浮之候。因尺候肾，沉为常，浮而无根为反，故首主肾水亏乏；肾水亏则精血化源不足，脉道不充而涩，故主血少枯槁；水不涵木，肝木亢盛，弦脉显露，乘克脾土，缓脉相应，故主肝木凌脾；血液枯槁，津液不布，胸膈失润，久", "c": "主肾水亏乏"}, {"id": "pc:尺+沉+涩", "n": "尺·沉涩脉", "o": "尺部沉涩脉总属阴血津液枯竭、内伤虚损之候。沉主里，涩主血少津枯，合而示病在里、阴血耗损。其类有四：一主阴血枯竭，分候脏腑则心血枯、肝血竭、肾水虚、脾阴绝、胃汁干；二主精血内竭，见于女劳疸肾虚之根；三主气郁血滞，沉涩并见亦示阳气郁遏、血行滞涩；四主噎隔内伤，为内", "c": "主阴血枯竭"}, {"id": "pc:尺+沉+濡", "n": "尺·沉濡脉", "o": "尺·沉濡脉总起来主肾阴亏虚、水不涵木、阴亏火旺、脾弱生痰、痰浊蒙窍一类病机。沉濡见于左尺，为少阴水亏之本象；水不涵木则厥阳独亢，阴亏火旺则心肝之阴耗伤；脾弱不能运化，水谷之湿生痰，肝阳升动，挟痰上蒙清窍，遂致神机不灵、类癫类狂。诸类之间以肾阴亏虚为根，水不涵木", "c": "主水不涵木"}, {"id": "pc:尺+沉+紧", "n": "尺·沉紧脉", "o": "尺部沉紧脉总属里寒之象。沉主里，紧主寒主痛，尺候下焦，故其病机核心为寒邪内侵、阳气受困。具体而言，或寒凝下焦而见腰疼足蜷、胎动下血；或寒结气机而腹痛、脐下痛；或水寒相搏而发贲豚冲气；或阳虚阴盛而见手足逆冷、胸膈不达。四类病机皆以寒为因，以里为位，以痛、凝、逆、", "c": "主寒凝下焦"}, {"id": "pc:尺+沉+紧+迟", "n": "尺·沉紧迟脉", "o": "尺部沉紧迟脉总属里寒阳虚之候。沉主里，迟主寒，紧主痛，三脉相合，揭示寒邪内侵、阳气不足之病机。其核心为胃中寒，因脾胃为后天之本，寒邪直中或阳气素虚，均可致中焦寒凝。在此基础上，若寸脉短少无力，则进一步提示阴盛阳虚，上焦阳气不能充达，故见胸膈满闷、手足厥冷等症。", "c": "主里寒"}, {"id": "pc:尺+沉+结", "n": "尺·沉结脉", "o": "尺·沉结脉总属里实气滞之候。沉为里脉，结为气机阻滞之象，二者相合，主邪结在里、气机不畅。原文明确指出'尺脉沉结，怒气所伤'，说明其核心病机为情志所伤、气结于内。此脉虽仅一段论述，但可归纳为两类：一主气滞，因结脉主气机阻滞，怒气伤肝则气结；二主里实，因沉脉主里，", "c": "主气滞"}, {"id": "pe:尺+沉", "n": "尺·沉脉", "o": "尺部沉脉总以“主里”为纲，其病机可归为虚实两端。虚者，尺候肾与下焦，沉而无力多主肾阳亏虚、下焦虚寒，见腰背冷痛、小便虚闭、冲气上逆；虚中夹火者，则沉而火不息，为肾虚火郁。实者，沉而兼滑，主血实内结；沉而兼紧，主水寒内动；沉绝或沉微，可因气逆壅塞、下焦脉气一时不", "c": "主里虚寒"}, {"id": "pc:尺+沉+虚+涩", "n": "尺·沉虚涩脉", "o": "尺部沉虚涩脉总属阴血津液枯竭、内伤噎隔之候。沉主里，涩主血少津枯，虚则不足，合而示内伤日久、阴血耗损。原文以沉涩为内伤噎隔主脉，分候脏腑：左寸心血枯、左关肝血竭、尺肾水虚、右关脾阴绝、胃汁干而肠结，层层推演阴血枯竭之机。三类病机相互关联：阴血枯竭为根本，津亏肠", "c": "主阴血枯竭"}, {"id": "pc:尺+沉+迟", "n": "尺·沉迟脉", "o": "尺部沉迟脉总属里寒阳虚之候。沉主里，迟主寒，尺候下焦肾命，故其核心病机为阳气不足、阴寒内盛。由此可衍生数类：寒邪直中或真火亏虚则主里寒、主阳虚；寒凝气血不通则主寒痛；寒与痰饮搏结则主痰饮；寒凝日久成积则主积冷。诸类皆以'寒'与'虚'为纲，或虚寒并见，或寒实内结", "c": "主里寒"}, {"id": "pe:尺+洪", "n": "尺·洪脉", "o": "尺部洪脉总属阳热之象，因尺候下焦肾与膀胱，故所主病机多关乎下焦。然须分虚实：实者或为湿热壅盛、实热壅结，脉洪盛有力，伴小便赤涩、腹痛便热、痞块等症；虚者或为阴虚火旺、虚阳外浮，脉洪而按之无力，伴失血、发热、崩漏等症。又有气结膀胱而尺洪盛、余脉微细者，属阳浮气结", "c": "主湿热壅盛"}, {"id": "pc:尺+浮+洪", "n": "尺·浮洪脉", "o": "尺部浮洪脉总属肾水不足、虚火内动之象，其脉浮而洪大，按之无力，为阴亏阳浮之征。所主病机以肾虚火旺为核心，可兼见心火炎上。因肾水亏虚，不能上济心火，则左寸浮洪而心火炎；肾火内炽，气化失司，则小便疾速、大便燥结。诸类之间，水亏为本，火旺为标，心火与肾火相互影响，总", "c": "主水亏火旺"}, {"id": "pc:尺+浮+涩+短", "n": "尺·浮涩短脉", "o": "尺部浮涩短脉，总属危重之候。其浮者非表邪，乃脏真外泄、气血浮散；涩短者，营血亏少、元气衰微，脉道不利。结合原文所列屋漏、雀啄、弹石、解索等怪脉，皆无胃气柔和之象，故其核心病机为胃气败绝、脏真外泄、气血枯竭，终致病深危殆。四类之间，胃气败绝为根本，脏真外泄为病势", "c": "主胃气败绝"}, {"id": "pc:尺+浮+涩", "n": "尺·浮涩脉", "o": "尺·浮涩脉总属虚损危候，其核心病机为阴血枯竭、阳气浮越，进而胃气败绝、脏真外泄。浮脉非表邪，乃阳气外浮或脏真外泄；涩脉主阴血亏少、脉道不利。轻则气血虚损，重则阴竭阳浮，甚至胃气败绝、气血枯竭。各类之间由虚致损，由损致竭，层层深入：虚损为始，阴竭阳浮为剧，胃气败", "c": "主虚损"}, {"id": "pc:尺+浮+空", "n": "尺·浮空脉", "o": "尺·浮空脉总属虚候，以正气亏虚、阴阳失调为纲。浮为气浮于外，空为内虚不实，故其病机不外三端：一为气虚，诸部脉虚，脏腑气弱，常见眩晕、气短乏力；二为虚阳上浮，尺部浮大而空，肾元亏虚，真阳不能潜藏而上脱，可见气促面赤、痰响不安；三为阴阳不相顺接，浮空与微细并见，下", "c": "主气虚"}, {"id": "pc:尺+浮+紧", "n": "尺·浮紧脉", "o": "尺·浮紧脉总起来主病机以邪实为主，兼涉正虚。其核心为水饮内结与表邪寒束：尺部属水，水饮内结、酿火随经上逆则脉浮紧而衄；寒邪束表、营阴凝滞亦见浮紧。二者皆属邪实，且常致迫血上逆。在此基础上，浮紧脉又体现邪正盛衰对比：邪盛而正能抗邪则脉浮大有力为生候；若汗后正虚不", "c": "主水饮内结"}, {"id": "pc:尺+浮+缓", "n": "尺·浮缓脉", "o": "尺·浮缓脉总起来主风邪外袭、湿痹、脾伤湿热及肾气受损。浮脉主风，缓脉主湿，风与湿合，痹阻气血，郁而化热，则见脾色外现而发黄；若兼趺阳紧数，则脾胃湿热内蕴，谷气不消，发为谷疸；尺脉本沉而浮，又提示肾气受损。诸类病机相互关联：风邪外袭为始动因素，湿痹为病理基础，脾", "c": "主风邪外袭"}, {"id": "pe:尺+浮", "n": "尺·浮脉", "o": "尺·浮脉总以“下焦阴气不藏、虚阳外浮”为纲，然所主病机有虚实寒热之殊。其虚者，或肾水亏乏、真阳不潜，见足跟痛、气短、噎膈；或阴亏火旺，迫血上溢而衄血；甚则阴竭阳浮、阴阳离决，现循衣摸床、谵语等危候。其实者，或客阳在下焦、肾与膀胱热而小便难；或湿热郁蒸成沙淋；或", "c": "主肾虚阳浮"}, {"id": "pc:尺+涩+坚", "n": "尺·涩坚脉", "o": "尺·涩坚脉总起来主血实气虚、瘀血结瘕及邪实正虚之病机。涩主血少，坚主邪实，二者相合，既示血分实滞而气分不足，又示瘀血内结、久成结瘕，更寓邪实正虚、预后吉凶之辨。诸类之间，以血实气虚为基本病机，瘀血结瘕为血实气滞之久延转归，邪实正虚则统括脉证相逆之危候。临床见尺", "c": "主血实气虚"}, {"id": "pc:尺+涩+小+弱", "n": "尺·涩小弱脉", "o": "尺部涩小弱脉，总以虚为本，兼见滞象。小弱主气血不足，涩主血少气滞，尺部候下焦，故其病机核心为下焦气血虚弱。虚则气化无力，寒热错杂，可发寒热及疝瘕、少腹痛；虚而气血不充，脉道滞涩，又可致里虚夹积、腹中隐痛。三类病机以“虚”为共同基础：主寒热疝瘕言其虚寒夹杂之变，", "c": "主寒热疝瘕"}, {"id": "pc:尺+涩+小", "n": "尺·涩小脉", "o": "尺·涩小脉总以虚为根本，尤主下焦气血不足。小脉主气虚，涩脉主血少气滞，尺部候下焦，故其核心病机为下焦气血虚弱。虚则气化无力，可致寒热错杂、疝瘕、少腹痛；虚而脉道滞涩，又成里虚夹积、腹中隐痛。若兼肝旺脾虚痰饮，则见左尺小涩而六脉濡软沉弦，木乘土位。诸类以虚为共同", "c": "主虚"}, {"id": "pc:尺+涩+弱", "n": "尺·涩弱脉", "o": "尺·涩弱脉总属虚候，核心病机为下焦气血虚弱、里气不实，并可延伸至阴阳俱虚。其脉象以涩滞无力、按之无根为特征，与胎脉之微滑不绝形成对比。原文强调“尺脉涩弱无力者，不可下”，因下之则重虚，说明其本质为正虚。下属尺·微涩弱脉主肾气衰败、真气不全及胎元不固；尺·涩小弱", "c": "主下焦虚"}, {"id": "pc:尺+涩+短", "n": "尺·涩短脉", "o": "尺·涩短脉总属虚损之候，以气血亏少、元气衰微为基本病机。涩主脉道不利、营血亏少，短主气损、脉气不充，故见短涩则示肺气不足、肝阴亏虚、肾精不充等诸虚之象。若兼数象，则为水少于火、阴虚火旺，虚火内动。若脉来如屋漏、雀啄等怪脉，则非寻常虚损，乃胃气败绝、脏真外泄、气", "c": "主虚损"}, {"id": "pc:尺+涩+紧", "n": "尺·涩紧脉", "o": "尺·涩紧脉总起来主寒凝血瘀、寒伤营血之病机。紧脉主寒，涩脉主血瘀，尺部候肾与下焦，故两尺紧而涩，反映寒邪客于下焦，凝滞营血，血行不畅而成瘀。原文两段均围绕“寒伤荣”立论，前段明言“紧主寒，涩主血瘀”，因经期饮冷致血被冷水所凝，瘀血归于大肠，发为痢下黄黑、痛而急", "c": "主寒凝"}, {"id": "pc:尺+涩+缓", "n": "尺·涩缓脉", "o": "尺·涩缓脉总起来主肾水亏乏、血液枯槁、肝木凌脾，进而成噎膈之证。其脉象以尺部浮而无根为根柢，示肾水亏虚；余部弦涩而缓，弦属肝木，涩为血少，缓为脾脉，合而观之，乃肝木凌脾、血液枯槁之候。肾水亏则不能涵木，肝木横逆则克伐脾土，脾失健运则气血生化乏源，血少则脉涩，木", "c": "主肾虚水亏"}, {"id": "pe:尺+涩", "n": "尺·涩脉", "o": "尺部涩脉总主精血亏少、血行滞涩之病机，其核心为肾精不足与血瘀内阻两端。从所收段落看，尺涩可见于肾阴亏虚、精血不充（如胎元不成、麻症先补肾），亦可见于瘀血内停（死血脉必涩），还可因肾虚不固而兼痰饮（尺浮大按涩），因下焦阳虚而兼寒（尺涩细微、溏泄冷利），因阴血不足", "c": "主精血亏虚"}, {"id": "pc:尺+涩+芤", "n": "尺·涩芤脉", "o": "尺部涩芤脉总以血分病变为核心，主瘀血内结与血虚血滞两类病机。芤脉浮大中空，主血虚；涩脉往来涩滞，主血行不畅。二者并见于尺部，一则示阴血亏虚，脉道不充；二则示血行滞涩，瘀血内停。原文“尺脉芤涩，瘀血之诊”及“血结在阴，脉反芤涩”均强调芤涩相合为瘀血之征，且寓血虚", "c": "主瘀血"}, {"id": "pc:尺+涩+迟", "n": "尺·涩迟脉", "o": "尺·涩迟脉总起来主下焦虚寒、气血滞涩，并可导致冲脉为病与少阴经气上逆。迟为寒，涩为滞，尺部候下焦，故其核心病机为下焦阳气不足、气血运行不畅。虚寒与滞涩相互影响：寒凝则气血更滞，血滞则阳气不达，形成恶性循环。由此进一步引发冲脉失调和足少阴经气上逆，出现脐下痛剧、", "c": "主下焦虚寒"}, {"id": "pc:尺+滑+动", "n": "尺·滑动脉", "o": "尺部滑动脉总起来主痰积、湿热、肝气郁结，并常兼见本虚标实之候。滑脉主痰，动主痛，右关滑动多提示痰积中焦；若兼数则湿热内蕴；左关弦搏则肝木气旺，气结入络可成梗块。然原文又见尺寸脉微缓，泄痢日久，气血两亏，说明滑动脉所主之痰积湿热肝气，多建立在元气已虚的基础上，形", "c": "主痰积"}, {"id": "pc:尺+滑+坚", "n": "尺·滑坚脉", "o": "尺·滑坚脉总属里实坚积之脉，以沉坚为主，兼见滑象，主病在里、实邪内结。其类脉或沉弱主虚寒疝瘕，或沉横主积痛，或短主气虚头痛，或长主气逆足痛，或促主阳邪肩背痛，或浮盛主表邪。诸脉虽异，皆以脉象之长短、沉浮、坚弱、横促等辨病位之表里上下与病性之虚实寒热。滑坚脉本身", "c": "主里实坚积"}, {"id": "pc:尺+滑+大+沉+浮", "n": "尺·滑大沉浮脉", "o": "尺部滑大沉浮脉总主肾与膀胱虚冷、水液不摄之病机。其脉象虽异，或沉、或滑、或浮大，但核心在于阳气衰弱，不能约水，故见遗尿、小便不禁。沉为阴绝，微滑为阳虚水不摄，浮大为土克水之逆，诸脉皆示本虚标实、水液失约。三类病机相互关联：虚冷为根本，水不摄为直接表现，土克水逆", "c": "主虚冷"}, {"id": "pc:尺+滑+大+浮", "n": "尺·滑大浮脉", "o": "尺·滑大浮脉所主病机主要有三类：湿热下注、阳盛阴虚、阳虚水不摄。滑主湿浊痰热，浮大主阳热外浮，故见下焦湿热蕴结，气化不利，症见少腹痛满、尿痛、大便热；浮大滑属阳脉，沉之损小、浮之实大则为阳盛阴虚，阳热偏盛而阴液不足；而尺部滑大沉浮脉又总主肾与膀胱虚冷、水液不摄", "c": "主湿热下注"}, {"id": "pc:尺+滑+大+涩", "n": "尺·滑大涩脉", "o": "尺·滑大涩脉总起来主虚实夹杂之证。左涩主血少血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。三象并见，示上焦痰火未清、中焦脾弱、下元不足，属本虚标实、上下同病。其病机核心为吐血后阴血亏耗、瘀血内停，痰火壅于中上焦，下元虚惫，脾肾不足。各脉象相互关联：血少血", "c": "主血少血瘀"}, {"id": "pc:尺+滑+大", "n": "尺·滑大脉", "o": "尺·滑大脉总起来主痰火、湿热、相火亢盛及阳盛阴虚，并可兼见虚实夹杂之证。滑主痰湿，大主火盛，故其核心病机为火热痰湿壅盛，部位多在中上焦或下焦。右寸关滑大主痰火壅肺，右尺滑大主命门相火，尺部滑大浮主下焦湿热，浮大滑而沉小则示阳盛阴虚。若兼涩而两尺弱，则成虚实夹杂", "c": "主相火"}, {"id": "pc:尺+滑+实", "n": "尺·滑实脉", "o": "尺·滑实脉总属邪实壅盛之象，以实热、痰湿、土壅为核心病机。滑为阳脉，主痰饮、主热；实为邪气亢盛。二者相合，提示实邪内结，或热盛，或痰阻，或土壅。原文'右脉滑实，土太过'直接点明土壅之机，并以枳实丸消导；'痰注四肢'虽未言脉，但滑实为痰湿常见之脉；'伤寒热盛脉浮", "c": "主实热"}, {"id": "pc:尺+滑+小+弱", "n": "尺·滑小弱脉", "o": "尺·滑小弱脉总以“小弱”为特征，主正气不足、脉道不充。其病机可分三类：一为正虚邪陷，见于伤寒热盛而脉沉小、温病大热而脉细小，正不胜邪，预后凶险；二为津伤邪退，见于伤寒已得汗后脉沉小，为邪去正复、津气内敛之顺象；三为热盛正衰，温病无汗而脉细小难得，正衰不能抗邪。", "c": "主正虚邪陷"}, {"id": "pc:尺+滑+小", "n": "尺·滑小脉", "o": "尺·滑小脉总以脉形偏小为特征，主正气不足、脉道不充。其病机可分三类：一为正虚邪陷，见于伤寒热盛脉沉小、温病大热脉细小，正不胜邪，预后凶险；二为津伤邪退，见于伤寒汗后脉沉小，邪去正复、津气内敛之顺象；三为热盛正衰，温病无汗而脉细小，正虚邪盛，主危候。三类皆以脉小", "c": "主正虚邪陷"}, {"id": "pc:尺+滑+弱", "n": "尺·滑弱脉", "o": "尺·滑弱脉总以尺部弱、关部滑为特征，主本虚标实之证。其病机核心为肝肾两虚、虚风痰阻：尺弱反映肝肾阴血不足，关滑提示内风痰浊壅盛。虚风因虚而动，痰随风升，阻滞络脉，故见舌强肢麻、口眼㖞斜、溲多筋酸等症。三类病机相互关联：肝肾两虚为病之本，内风痰阻为病之标，虚风煽", "c": "主肝肾两虚"}, {"id": "pc:尺+滑+微", "n": "尺·滑微脉", "o": "尺·滑微脉总起来主胎孕、虚冷不摄与肾气衰败三类病机。其核心在于尺部候肾与下焦，微滑按之不绝者，为胎元内结、气血壅聚之常；微滑而无力或兼他象者，则多归膀胱虚冷、阳气衰弱，不能约水而遗尿；若尺脉不滑、按之无根或浮弱不任寻按，则又示肾气衰败、真气不全。三类之间以脉力", "c": "主胎孕"}, {"id": "pc:尺+滑+沉", "n": "尺·滑沉脉", "o": "尺部滑沉脉所主病机，总以尺部脉象变化反映下焦及整体病变。滑脉多主热、主虫积，沉滑并见则虫积内扰；而尺脉弱、细微、虚小则主下焦虚寒，阳气不足；尺弱寸强又主胃络损伤；尺涩主下血；尺细急主筋脉挛痹；至于怪脉则主脏气衰败之死候。各类之间，以虚实为纲：滑疾、沉滑偏实，主", "c": "主热"}, {"id": "pc:尺+滑+洪", "n": "尺·滑洪脉", "o": "尺·滑洪脉总起来主下焦实热之证，以湿热壅盛与相火偏旺为两大病机。洪滑有力为实热之脉，尺部候下焦，故病位在下焦。湿热壅盛者，热与湿合，阻滞气机，可见少腹疼、小便赤涩、渴饮、厥逆；相火偏旺者，下焦火盛，虽能多食，然非君火温煦，故寒饮留滞。二者皆属热盛于下，但一为湿", "c": "主湿热壅盛"}, {"id": "pc:尺+滑+浮+疾", "n": "尺·滑浮疾脉", "o": "尺·滑浮疾脉总起来主脾虚食积、痰食内壅、热与积滞相搏三类病机。其核心在于脾虚不运，宿食停滞，化生痰湿，郁而化热，形成虚中夹实、积热内蕴之候。浮为虚阳外浮，滑为痰食内壅，疾为热与积滞相搏，三脉合见，提示病位在脾胃，病性属虚实夹杂。三类之间相互关联：脾虚是根本，食", "c": "主脾虚食积"}, {"id": "pc:尺+滑+濡", "n": "尺·滑濡脉", "o": "尺·滑濡脉总以湿郁气虚为核心病机。濡脉主湿主虚，滑脉主痰湿，合而见于右脉，提示湿郁阻遏气机、气虚不运；尺脉小则反映肾气亦弱，心脉短、肝脉虚则心肝气血不足，故整体呈现二气亏虚、湿郁气滞之象。诸类病机相互关联：湿郁可加重气虚，气虚又生湿浊，气阴两虚则神倦、性燥多虑", "c": "主湿郁"}, {"id": "pc:尺+滑+疾", "n": "尺·滑疾脉", "o": "尺·滑疾脉总起来主热、客阳、下焦虚寒、胃络伤、下血、虫积、筋挛等多类病机，其核心在于尺部脉象反映下焦病变。滑疾之脉以热为主，热郁下焦则面赤如醉；浮则客阳下焦；弱、细微、虚小则下焦虚寒；寸强尺弱则胃络伤；涩则下血；沉滑则虫积；细急则筋挛。各类之间相互关联：热与客", "c": "主热"}, {"id": "pe:尺+滑", "n": "尺·滑脉", "o": "尺·滑脉总以尺部候下焦、滑主湿浊痰热为纲，所主病机可归为湿热积滞、胎孕、下焦虚寒、客阳外热、胃络伤下血、虫积筋挛及正虚邪陷七类。其常者，微滑按之不绝为胎元气血壅聚之象；其变者，滑而有力多湿热积滞下焦，滑疾偏浮为客阳外热，滑兼弱细微虚小则下焦虚寒、阳气不足，滑涩", "c": "主湿热积滞"}, {"id": "pc:尺+濡+弱+缓", "n": "尺·濡弱缓脉", "o": "尺·濡弱缓脉总起来主湿、气虚、肾虚及血少，以湿与气血不足为核心。濡缓主湿，弱主气虚，尺弱主肾虚，涩为血少，四者常相兼为病。其病机关键在于湿邪内蕴、气血亏虚、肾精不足，导致筋脉失养、肢体痿软。原文所载痿证，即因肺热叶焦、阳明土亏，湿重则筋缓痿软，热多则筋急作痛，", "c": "主湿"}, {"id": "pc:尺+濡+弱", "n": "尺·濡弱脉", "o": "尺·濡弱脉总起来主虚、湿、肾虚及血少，以正虚为核心，湿与血少为兼。濡主湿，弱主气虚，尺弱主肾虚，涩为血少，四者常相兼为病。其病机关键在于湿邪内蕴、气血亏虚、肾精不足，导致筋脉失养、肢体痿软。原文所载忌下诸脉，如尺脉涩弱无力、脉虚、虚细、濡弱等，皆因里气不实、正", "c": "主虚"}, {"id": "pc:尺+濡+紧", "n": "尺·濡紧脉", "o": "尺·濡紧脉总属正虚寒凝、里气不实之候。濡为虚象，紧为寒征，二者相合，提示正气不足而寒邪内结。原文虽仅列忌下诸脉，但濡紧脉见于尺部，与涩弱无力、虚细、濡弱等同属里气不实、正虚之列，故不可妄下。其病机核心在于虚与寒相兼：虚则下之重虚，寒则下之伤阳。三类病机相互关联", "c": "主正虚"}, {"id": "pe:尺+濡", "n": "尺·濡脉", "o": "尺·濡脉总起来主湿、虚、肾虚、寒及气化不利。濡脉本主湿主虚，见于尺部则病位在下焦，故以肾虚湿滞为核心。其病机类别之间相互关联：肾虚可致气化不利，水湿内停而见濡脉；湿郁日久可伤阳气，阳虚则寒生；气血不足与肾精亏虚又常相兼为病。原文以尺濡主小便难，体现肾与膀胱气化", "c": "主湿"}, {"id": "pc:尺+濡+软", "n": "尺·濡软脉", "o": "尺·濡软脉总起来主虚、湿、寒、下元不足之证。其脉象以濡软为纲，濡主湿，软主虚，尺候下焦，故病机多涉及脾虚湿困、气血不足、血寒凝滞及下虚阳浮。各类之间相互关联：脾虚湿困可致气血生化不足，气血不足又易感寒凝，下元虚衰则阳失潜藏，虚阳外浮。原文强调脾虚湿困兼肝旺痰饮", "c": "主脾虚湿困"}, {"id": "pe:尺+牢", "n": "尺·牢脉", "o": "尺·牢脉总属阳脉范畴，其病机以阳气偏盛或阴寒内实为核心，脉道充盈鼓动而见长牢之象。具体而言，浮取实大而长牢者，为阳盛阴虚，热盛伤阴；沉取实大而长牢者，为阴盛阳虚，阴寒内结。此外，尺脉虚小或弱而兼牢，主下焦虚寒，足胫寒、痿痹脚疼；尺脉涩而牢，主血行不利、下血多汗", "c": "主阳盛阴虚"}, {"id": "pe:尺+疾", "n": "尺·疾脉", "o": "尺·疾脉总起来主热盛、正虚邪陷、津伤火旺及胃气败绝等病机。疾脉以脉来急疾为特征，核心为热邪亢盛，气血运行加速；若兼脉体细小，则示正气虚衰、邪气内陷，或热盛伤津、阴亏火旺；若疾而散乱无根，则为胃气败绝之死候。各类之间，热盛为基本病机，正虚邪陷与津伤火旺多由热盛发", "c": "主热盛"}, {"id": "pe:尺+短", "n": "尺·短脉", "o": "尺·短脉总属虚损之候，以气虚、阳虚、气血两虚为基本病机。短主气损，脉气不充，故短而无力多主气虚，尤以肺气、心气不足为常见；寸脉短少力弱于关尺，则为阴盛阳虚、阳不上充，主阳虚寒盛；尺脉短小、心脉短、肝脉虚，示心气亏虚、肝血不足、肾气亦弱，属虚损；六部豁大浮中沉无", "c": "主气虚"}, {"id": "pe:尺+紧", "n": "尺·紧脉", "o": "尺部紧脉总主寒、痛、虚，其病机核心为寒邪凝滞与正气不足。紧脉主寒主痛，见于尺部则下焦寒凝，气血不通，故腹痛、便溏、脐下痛；若紧而无力或与微脉并见，则属虚寒，阳气衰微，阴寒内盛，甚则虚损多汗、阴盛阳衰。紧与数脉并见，则寒热错杂，多见于谷疸，脾胃寒热相搏，浊气下流", "c": "主寒痛"}, {"id": "pc:尺+细+坚+硬", "n": "尺·细坚硬脉", "o": "尺·细坚硬脉总起来主肾经湿毒蕴结、阴血不足、病根深伏。脉细为阴血亏虚之象，左尺坚硬鼓指则为湿毒深伏于肾、久郁化热、结聚不散之征。二者并见，示虚中夹实，非单纯虚证。原文以少阴之脉系舌本、循喉咙，说明肾中湿毒上攻可致喉间糜碎、舌下肿胀，与淋浊、横痃下疳等前症相应。", "c": "主湿毒蕴结"}, {"id": "pc:尺+细+小", "n": "尺·细小脉", "o": "尺部细小脉总属虚损之象，主阴血亏虚、肾阳虚衰、脾肾俱虚及正虚邪陷，亦可兼痰湿内阻。其脉形细小，示脉道不充、精气不足，故以虚证为纲。阴血亏虚则脉道失盈，肾阳虚衰则火不生土，脾肾俱虚则运化无权，正虚邪陷则无力抗邪。若兼弦滑，则为虚中夹痰湿，本虚标实。诸类之间，阴血", "c": "主阴血亏虚"}, {"id": "pc:尺+细+小+迟", "n": "尺·细小迟脉", "o": "尺·细小迟脉总起来主正虚邪陷、津伤液竭及热盛正衰之危候。原文以脉之浮大沉小判伤寒温病吉凶：伤寒热盛脉浮大者生，沉小者死，因热盛邪实，脉浮大则邪有外达之机；已得汗则脉沉小者生，浮大者死，因汗后津伤，脉宜静敛。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪", "c": "主正虚邪陷"}, {"id": "pc:尺+细+弱", "n": "尺·细弱脉", "o": "尺部细弱脉总属虚证，以肾虚为核心，涉及阴阳精血多个层面。细弱之象示脉道不充、气血不足，尺部候肾，故首主肾阴亏虚与肾阳虚衰：阴亏则精血不足、虚风内动、水不济火而失眠；阳衰则命火式微、脾肾虚寒而泄泻。各段原文或言“肾阴亏于下”，或言“命火衰微”，或言“阴液亏耗”，", "c": "主肾阴亏虚"}, {"id": "pc:尺+细+微+涩", "n": "尺·细微涩脉", "o": "尺部细微涩脉在此段中与屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉并论，总属无胃气柔和之象，主脏气衰绝、气血离散、脉病逆证。其核心病机是胃气败绝、生机将息，故原文断为死候。三类之间相互关联：脏气衰绝是根本，气血离散是脉象表现，脉病逆证是临床判断，共同指向危重预后。", "c": "主脏气衰绝"}, {"id": "pc:尺+细+微", "n": "尺·细微脉", "o": "尺·细微脉总起来主虚证，以肾阳虚衰、气血两虚为核心，兼及下焦虚寒、肝肾虚夹湿、正虚邪陷及脏气衰绝危候。微为阳虚气弱，细为血少脉道不充，尺部候肾与下焦，故脉见细微多示肾阳真火衰微、血气俱不足。其轻者见下焦虚寒、溏泄冷利；兼湿者成肝肾两虚、寒湿著骨；兼外邪或误治则", "c": "主肾阳虚衰"}, {"id": "pc:尺+细+急", "n": "尺·细急脉", "o": "尺·细急脉总属虚实夹杂之候，以虚寒为本，筋脉拘急为标。细主阴血不足，急主寒凝收引，故其核心病机为下焦虚寒、筋脉失养。原文所载尺脉细微之溏泄冷利、尺脉虚小之足胫寒痿痹，皆属虚寒范畴；而“尺细而急筋挛痹不能”则直接点明细急脉与筋脉挛痹的对应关系。此外，尺脉浮主客阳", "c": "主下焦虚寒"}, {"id": "pc:尺+细+沉+小", "n": "尺·细沉小脉", "o": "尺部细沉小脉在《伤寒论》类原文中，主要出现在伤寒温病的预后判断中。其总病机为正气虚衰、无力抗邪，或邪气内陷、正不胜邪。具体而言：伤寒热盛时见沉小，为邪实正虚、邪陷于里，主凶；汗后见沉小，为汗出津伤、脉证相符，主吉；温病大热而脉细小难得，为阴液耗竭、正气败绝，主", "c": "主正虚邪陷"}, {"id": "pc:尺+细+沉+微", "n": "尺·细沉微脉", "o": "尺部细沉微脉在此段中与怪脉并论，总属脏气衰绝、胃气败亡之危候。原文以屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉为象，皆无胃气柔和之象，且“脉病人不病”见之则死，说明其病机核心为脏气不能接续、胃气败亡。三类之间相互关联：脏气衰绝则脉失根本，胃气败亡则脉失柔和，二者", "c": "主脏气衰绝"}, {"id": "pc:尺+细+沉", "n": "尺·细沉脉", "o": "尺部沉细脉总以阳气亏虚、肾气不足为基本病机，沉细属阴，主里主虚。其可单独出现，示阳气早亏、肾气不足；亦可兼见他部脉象而呈本虚标实之候：兼寸关弦紧滑者，为风痰阻络、蒙蔽清窍；兼寸关弦涩者，为寒湿痹阻、营卫不通；兼寸关濡滑者，为气血两亏、痰湿内蕴。若沉细反见豁大或", "c": "主阳气亏虚"}, {"id": "pc:尺+细+浮+微", "n": "尺·细浮微脉", "o": "尺中细浮微脉总起来主肾虚夹外邪之证。尺部候肾，脉细为肾虚不足，浮为风雨外犯，微则示虚象明显。原文患者年高挛废，九夏而膝足寒冷如从水中出，久服祛风通络药及八味丸均不效，诊得尺中微浮而细，断为肾虚风雨所犯，授安肾丸补肾而愈。可见此脉以肾虚为本，外邪为标，浮与细并见", "c": "主肾虚"}, {"id": "pc:尺+细+涩", "n": "尺·细涩脉", "o": "尺·细涩脉总起来主精血亏虚、肾虚阴亏、虚阳上浮、冲任血亏及脏气衰绝等病机。其核心在于尺部候肾，细涩示精血亏少、脉道不充，故精血亏虚与肾虚阴亏为基本病机；阴亏则阳失潜藏，故见虚阳上浮，寸关大于平时；若病在冲任，则冲任血亏，经停腹块；若脉细微涩与怪脉并见，则为胃气", "c": "主精血亏虚"}, {"id": "pc:尺+细+濡", "n": "尺·细濡脉", "o": "尺·细濡脉总属虚损夹湿之象。细濡无力，主气血亏虚、阴阳两亏；尺部独显，则专责肾虚，兼湿滞下焦。段喘止咳平后脉软小乏力、尺濡细，为脾肾两虚、肺金失养，痰咸示肾虚水泛；段素体瘦弱、天癸逾期、白带频下，脉细焮尺濡，为阴阳两亏、冲任失养。两类病机相互关联：肾虚气化失司", "c": "主肾虚"}, {"id": "pc:尺+细+疾", "n": "尺·细疾脉", "o": "尺·细疾脉总属肾水干竭、虚火内炽之候。尺部候肾，细为阴精亏耗，疾为火势急迫，二者相合，揭示肾阴枯竭、水不制火的核心病机。此脉所主以“水竭火旺”为根本，火旺又加重水竭，形成恶性循环。与尺脉大而虚之肾气不足、搏而急之肾经火发相比，细疾脉侧重阴精亏极而火势急迫，属虚", "c": "主水竭火旺"}, {"id": "pe:尺+细", "n": "尺·细脉", "o": "尺部细脉总以虚为纲，细主脉道不充、阴血阳气不足，尺候肾与下焦，故所主病机多归肾虚、阴亏、阳衰、气虚诸类。其轻者见肾虚不固、阴液亏虚、阳虚内寒、气虚不运，皆本虚之候；其重者则阴竭阳衰，正虚邪陷，或气机阻绝，上下不通，症脉相反。各段原文或言“肾病何辞”，或言“下焦", "c": "主肾虚不固"}, {"id": "pc:尺+细+虚+涩", "n": "尺·细虚涩脉", "o": "尺·细虚涩脉总主肾虚阴亏、精血不足，兼虚阳上浮。尺部候肾，细涩示精血亏少、脉道不充，虚则肾气亦弱；寸关大于平时，是阴不制阳、虚阳外浮之征。原文从水火阴阳立论，指出阴精早泄、年四十阴气自半，使肾阴亏耗，阳失潜藏。故其病机以肾虚精亏为本，阴亏阳浮为标，二者相因：下", "c": "主肾虚精亏"}, {"id": "pc:尺+细+虚", "n": "尺·细虚脉", "o": "尺·细虚脉总起来主虚，以肾气亏虚、精血不足为本，可累及阳气与阴精，形成阴阳俱虚；虚而受邪则正虚邪恋，虚实夹杂；里气不实又为禁下之征。各段从不同侧面说明：虚细无神主阳虚，细涩主精血亏，虚大尺数主阴亏阳浮，弦细虚主虚人外感，涩弱无力主里虚禁下。诸类皆以正虚为核心，", "c": "主阳虚"}, {"id": "pc:尺+细+软", "n": "尺·细软脉", "o": "尺·细软脉总属虚损，尤以心肾两虚为核心。细为阴血亏少，软为阳气不足，见于左寸尺，则心肾水火不济，肾水不能滋养肝木、上济离火，故见背偻、胁痛、吐瘀等症。然此案细软与关部独弦、右三部洪滑并见，又提示虚中夹痰火，属本虚标实之候。故本脉所主病机可归为两类：一为心肾两虚", "c": "主心肾两虚"}, {"id": "pc:尺+缓+急", "n": "尺·缓急脉", "o": "尺·缓急脉在此段中表现为寸急尺缓，总起来主下元亏虚、阳气上逆之上实下虚证。尺缓为下元不足，寸急为阳气上逆，二者并见，形成上实下虚之病机。因烦劳引动，阳气张大，厥阳变化，内风鼓动，上凭诸窍，故见呕逆眩晕，即经云'上实下虚，为厥巅疾'。病本在下元亏虚，标为阳气上逆", "c": "主下元亏虚"}, {"id": "pe:尺+缓", "n": "尺·缓脉", "o": "尺部缓脉总起来主虚、湿、风及正虚邪恋之候，其病机核心在于下焦元气不足与脾胃功能失调。缓脉本主脾、主湿，见于尺部则多反映肾阳不足、脾虚湿滞，或气血两亏。具体而言，尺缓而虚主脾肾阳虚、湿滞内生；尺缓而微主气血双损、正虚邪恋；尺缓而涩主肾水亏乏、血液枯槁、肝木凌脾；", "c": "主肾虚水亏"}, {"id": "pc:尺+缓+迟", "n": "尺·缓迟脉", "o": "尺部缓迟脉总属里气不实、正气亏虚之候。其形成机理在于阳气不足，鼓动无力，或胃气虚弱，脉道弛缓，故见迟缓。原文以“里气不实”为眼目，将脉迟缓与尺脉涩弱无力、虚细、浮、濡弱等并列，皆视为禁下之脉，强调下之则重虚。由此可归纳为三类病机：一主里虚，因迟主阳不胜阴，缓主", "c": "主里虚"}, {"id": "pe:尺+芤", "n": "尺·芤脉", "o": "尺·芤脉总起来主下焦精血亏虚，并由此衍生出血虚、精亏、瘀血及心肾不交等病机。芤脉浮大中空，为血虚不能充脉之象，尺部候下焦，故首主血虚与精亏，此二者为病之本。精血既亏，脉道不充，血行滞涩，则可兼涩而致瘀血内结，此为本虚标实之变。若芤兼动，则下元精亏而心神浮越，心", "c": "主血虚"}, {"id": "pc:尺+虚+伏", "n": "尺·虚伏脉", "o": "尺·虚伏脉在原文中主要出现在伤寒温病的预后判断中，其总病机围绕邪正盛衰与津液存亡。脉之浮大沉小、大疾细小，皆反映邪气与正气的关系：脉浮大而见于伤寒热盛，为邪有外达之机，主生；脉沉小而见于热盛，为邪陷正衰，主死。汗后脉宜沉小，反浮大则津伤阳浮，主死。温病脉大疾为", "c": "主邪盛正衰"}, {"id": "pc:尺+虚+小", "n": "尺·虚小脉", "o": "尺·虚小脉总属虚候，以阳气不足、气血亏虚为根本。其主病机可分三类：一为下焦虚寒，因尺脉候下焦，虚小则阳气衰微，不能温煦下肢，故见足胫寒、痿痹脚疼；二为虚损危候，虚小脉见于伤寒温病热盛之时，示正气不能抗邪，脉证相反，预后凶险；三为胃络损伤，尺弱寸强，下焦阳虚而虚", "c": "主下焦虚寒"}, {"id": "pc:尺+虚+弱", "n": "尺·虚弱脉", "o": "尺部虚弱脉总属肾与督任亏虚，以精、阴、阳不足为核心。左尺虚弱多主肾精亏虚与真阴不足，可见遗精、足痿、虚热；右尺虚弱多主命门火衰，见迟软沉细；两尺俱弱则阴阳两虚。诸类之间，精亏为基，阴损及阳，阳衰及阴，终致阴阳两虚；督任交亏则是精亏不固、下元不纳的进一步表现。故", "c": "主阴阳两虚"}, {"id": "pc:尺+虚+微", "n": "尺·虚微脉", "o": "尺·虚微脉总起来主虚证，尤以肾气亏虚、里虚为要。虚为气血不足，微为阳气衰微，尺部候肾，故尺虚微多责之肾虚不藏与里虚。两类病机相互关联：肾虚不藏可致梦泄，里虚则禁汗，误汗更伤阴阳。临床见尺虚微，当以补虚固摄为要，忌妄汗伤正。", "c": "主肾虚不藏"}, {"id": "pc:尺+虚+濡", "n": "尺·虚濡脉", "o": "尺·虚濡脉总起来主肾水亏乏、下元虚竭，并常兼虚火内扰、水火不交之候。其核心病机为肾阴不足，水不涵火，以致心火难降、虚火浮越。原文以下消症为例，脉形软数而尺部虚濡，软数主虚火内扰，尺虚濡主肾水亏乏，二者相合，正合火在水上、未济之卦，故见口渴溲数、出如膏油。三类病", "c": "主肾虚水亏"}, {"id": "pc:尺+虚+空", "n": "尺·虚空脉", "o": "尺部虚空脉总属虚候，以肾命亏虚为本，涉及阴血不足与虚风内动。右尺弱主命门火衰，左脉空虚主阴血亏虚，两尺细数主肾水枯涸，络脉空虚则虚风易乘。诸类之间，命门火衰与肾水枯涸同属肾虚，一为阳虚，一为阴亏；阴血亏虚则脉络不充，虚风内动多因虚而风乘。故其病机以虚为核心，或", "c": "主命门火衰"}, {"id": "pc:尺+虚+缓", "n": "尺·虚缓脉", "o": "尺部虚缓脉，总属虚证，以脾肾阳气不足为核心。虚缓主虚，缓又主湿，故其病机一为脾胃气虚、土不及而湿滞内生，见四肢不举，治以六君子汤；二为尺脉虚缓兼沉迟，反映命门真火不足，不能温养，治以八味丸。两类均以虚为本，前者重在脾虚湿滞，后者重在肾阳虚衰，脾肾相关，虚缓脉提", "c": "主脾虚"}, {"id": "pe:尺+虚", "n": "尺·虚脉", "o": "尺·虚脉总主下元亏虚，以肾虚为核心，兼及气血阴阳不足。其病机可分虚实两端：虚者，尺脉虚主肾元不足、肾不纳气，进而阳气衰微而生虚寒，或气血亏虚而见诸脏气弱；实者，尺脉隐伏不见可因痰积食滞壅阻脉道，非真虚，须结合关脉沉滑、苔黄腻等症辨识。另有阴火太旺、水亏火炎，尺", "c": "主肾虚"}, {"id": "pc:尺+虚+软", "n": "尺·虚软脉", "o": "尺部虚软脉总属正虚邪恋之候。虚软为气血亏虚、脾肾两亏之本质，然虚处留邪，常兼湿热、瘀血等实邪。段15601以虚软示劳苦伤气、脾肾两亏，又见濡细小数，为下焦湿热蕴结、阴络受损；段15924以虚软示气血大亏，左尺独数，为产后瘀血凝滞、郁而化热。可见虚软脉虽主虚，但", "c": "主气血亏虚"}, {"id": "pc:尺+软+空", "n": "尺·软空脉", "o": "尺·软空脉总起来主阳气衰微、肾阳下竭、虚阳上浮及阳气外脱之证。其核心病机为下元虚惫，肾阳不能潜藏，导致虚阳上浮与外脱。软脉主阳气衰微，尺空主肾阳下竭，二者相合，既反映下元虚惫，又提示虚阳上浮，甚则阳气外脱。各类之间相互关联：阳衰为根本，肾竭为病位所在，虚阳浮为", "c": "主阳衰"}, {"id": "pe:尺+软", "n": "尺·软脉", "o": "尺·软脉总以虚为本，软主阳气不足、气血亏少，尺候下焦肾与命门，故其病机核心在肾元亏虚。然虚处每多兼夹：或阴亏火浮，软而弦数不静，迫血妄行；或阳虚内寒，软而弱迟，下焦冷、火不生土；或气血大亏，软小而空，痿痹足寒、虚阳外脱；或虚中夹邪，软而兼滑、涩、弦、数，湿热瘀", "c": "主阴虚火浮"}, {"id": "pc:尺+软+迟", "n": "尺·软迟脉", "o": "尺·软迟脉总属肾虚，以尺部候肾，脉软迟为不足之象。其主病机可分四类：左尺虚弱细数主肾阴不足，阴虚不能制火；右尺迟软主命门相火不足，阳虚不能鼓动；两尺微弱主阴阳俱虚；尺脉虚弱迟细又主三阴亏损，见于劳瘵虚热之证。四类皆以肾虚为本，或偏阴虚，或偏阳虚，或阴阳两虚，或", "c": "主肾阴虚"}, {"id": "pe:尺+迟", "n": "尺·迟脉", "o": "尺·迟脉总以阳虚寒盛为纲，兼涉里虚、痰饮、寒凝、肾虚诸类。迟主寒，尺候肾，故其核心病机为肾阳不足、阴寒内盛；阳虚则气化无力，水湿停聚而为痰饮，寒凝则气血滞涩而为痛为积；阳虚日久，营血亏虚，脉道不充，则见里虚不足；肾中精气亏耗，阴阳俱损，则成劳损之候。诸类之间以", "c": "主阳虚寒盛"}, {"id": "pc:尺+长+牢", "n": "尺·长牢脉", "o": "尺部长牢脉总属阳脉范畴，原文明确将“长”列为阳脉，与浮、大、数、动、滑同类。其病机核心在于阳气偏盛或阴寒内实，脉道充盈鼓动而见长牢之象。具体而言，若浮取实大而长牢，为阳盛阴虚，热盛伤阴；若沉取实大而长牢，为阴盛阳虚，阴寒内结而阳气不足。二者虽阴阳虚实不同，但均", "c": "主阳盛"}, {"id": "pe:尺+长", "n": "尺·长脉", "o": "尺·长脉总起来主气盛有余，其病机涵盖热盛、气逆、虚损及虚实夹杂等多类。长脉本为阳脉，主气治气盛，然过长或兼见他脉则病。热邪弥漫三焦则尺寸俱长，为实热；气逆于下则足胫痛；尺垂无力则为下元亏虚、阳浮血溢之虚损；长牢浮取为阳盛阴虚，沉取为阴盛阳虚；弦长则主肾虚火旺、", "c": "主热盛"}, {"id": "p:尺", "n": "尺部", "o": "尺部脉总属肾与下焦病变，其病机以肾虚为核心，兼及虚实寒热。虚证多见肾阴亏虚、肾阳虚衰、精血不足，脉多弱、细、虚、微、涩；虚阳浮越则脉浮大无力，为肾不封藏之象。实证则以火热、湿热壅结下焦为主，脉多洪数、滑大、坚搏；肝风内动、冲气上逆亦与肾虚相关，脉见弦、微、弱。", "c": "主肾虚"}, {"id": "s:屋漏", "n": "屋漏", "o": "屋漏脉总属无胃气之真脏死脉，其脉来如屋漏残滴，良久一滴，断续不匀，失去从容和缓之象。所主病机以胃气衰败为核心，进而涉及脾肾败绝、阴阳离决、真脏色现，最终皆归预后凶险。诸类之间层层递进：胃气衰败为根本，脾肾败绝为后天化源断绝，阴阳离决为气血耗散之极，真脏色现为脏", "c": "主胃气衰败"}, {"id": "pc:左+乱+碎", "n": "左·乱碎脉", "o": "左·乱碎脉总起来主肝肾同病，以肝风上冒为重心，肾阴亏虚为根源。其脉象碎乱搏指，脉道失其常度而搏指不宁，是风阳扰动、阴不涵阳之征。原文明言“肝风上冒”，又谓“乙癸同源，肾肝同病”，且以肝为重、肾次之，说明病机核心在肝风内动、上扰清窍，而肾阴亏虚则为其发病基础。三", "c": "主肝风上冒"}, {"id": "pe:左+乱", "n": "左·乱脉", "o": "左乱脉总起来主正气溃散、阴阳离决、气机逆乱之危候，其病机以肾虚失血、肝风上冒、正虚邪陷、寒热虚实错杂、元气欲脱为要。乱脉之象为脉道失序、搏指不宁，或碎乱、或散乱、或细乱、或伏乱，皆示根本动摇、枢机败乱。诸类之间，肾虚失血与元气欲脱同属根本竭乏，肝风上冒为阴不涵", "c": "主肾虚失血"}, {"id": "pc:左+伏+乱", "n": "左·伏乱脉", "o": "左·伏乱脉总起来主病机以寒热虚实为纲，兼及五脏定位。其脉象可数可迟，可滑可涩，可大可小，故所主非单一病邪。数、滑疾者主热；迟、紧者主寒；小、涩者主气血虚；滑、大者主气血实。又据兼脉分属五脏：长弦在肝，小血少在心，下坚上虚在脾胃，滑微浮在肺，大坚在肾。诸类之间，", "c": "主热"}, {"id": "pe:左+伏", "n": "左·伏脉", "o": "左伏脉总以邪阻气机、脉道不畅为基本病机，然所涉病因广泛，可归纳为气闭、痰食、血瘀、阳损、湿遏、痧毒及寒热虚实错杂数类。实邪方面，食痰壅塞、痧毒闭阻、湿浊遏热、气郁血滞，皆令脉气被遏而伏，多与滑、大、弦、数等脉并见，症见胸腹迷闷、呕吐昏厥、僵痹便闭等；虚损方面，", "c": "主痰食内阻"}, {"id": "pe:左+促", "n": "左·促脉", "o": "左促脉总属阳热急迫、气机不宁之候，其病机以热为核心，兼涉虚、郁、逆、痰、湿。数促主热盛，或实热壅滞，或阴亏火旺；弦促主肝郁气逆，木亢侮土；浮促主上焦气逆、胆府内伤；弱促主阳伤中虚，虚中夹实；结促主热郁气滞、积热内伏；疾促主阳热急迫、阴亏火旺。各类之间，实热与虚", "c": "主阴亏火旺"}, {"id": "pe:左+动", "n": "左·动脉", "o": "左动脉所主病机，总以“动”为象，然有虚实之别。实者多因阳升火动、郁结气滞、中焦壅滞、燥屎内结，脉动而有力，兼数、大、弦、涩、滑等，如六部动大而数、沉弦、沉涩应指。虚者多因冲脉气逆、虚损不固，脉动而无力，兼涩弱、虚数等，如左脉涩弱、左弦细右虚数。冲脉气逆为动脉核", "c": "主冲脉气逆"}, {"id": "pc:左+和+动", "n": "左·和动脉", "o": "左·和动脉总起来主正气偏弱而余热未清之证。其脉象以和中有活动之气为特点，兼弱则示气血不足，少数则示热象尚浅，往来明白则示胃气未败。故所主病机可归纳为虚、热、正虚邪恋三类。虚为本，热为标，正虚邪恋为虚实夹杂之态，三者相互关联，共同反映气血偏弱而余热未清、正气渐复", "c": "主虚"}, {"id": "pc:左+和+平", "n": "左·和平脉", "o": "左·和平脉总起来主正气渐复、病势趋缓之候，但常兼见他部脉象异常，揭示余邪未清或潜在病机。其核心在于左脉平和而右脉或他部见动、数、弦、滑、实等，说明病位多在右部或中下焦，病机以阳升气火、余热未清、虚怯、胃气不和、冲气上逆、痰热内壅、肝虚火郁、肝热血逆等为主。各类", "c": "主阳升气火"}, {"id": "pe:左+和", "n": "左·和脉", "o": "左·和脉总起来主正气渐复、病势趋缓，但常兼见他部脉象异常，揭示余邪未清或潜在病机。其核心在于左脉平和而右脉或他部见动、数、弦、滑、实等，说明病位多在右部或中下焦。所主病机可归纳为邪退正复、余邪未清、虚损不足、肝郁气滞、痰热壅盛、下焦郁热及胃气衰败七类。其中邪退", "c": "主邪退正复"}, {"id": "pe:左+坚", "n": "左·坚脉", "o": "左坚脉总属阴血亏虚、脉失柔润而拘急，或虚火内扰、阳亢不潜之象。其核心病机为“阴亏阳亢”，但随兼邪与病位不同而分化：纯虚者主阴虚阳亢、虚火动血、相火亢盛、肾阴不固；虚中夹实者主湿热下注、热结血分、络瘀郁热；古籍论积气内结亦见坚脉，属邪实壅滞之变。诸类之间，阴虚为", "c": "主阴虚阳亢"}, {"id": "pc:左+大+伏", "n": "左·大伏脉", "o": "左大伏脉（以右大左伏为特征）总起来主气分邪实与肝郁血滞相兼为病。右脉大反映气分邪气壅盛，左脉伏反映肝气郁结、血行不畅，二者并见，形成虚实夹杂之局。原文症见四肢僵痹、面青唇白、舌黑而滑、便闭溺短，似虚寒而脉非微细迟弱，似实热而无口渴痞满，故其病机核心在于气分邪实", "c": "主气分邪实"}, {"id": "pc:左+大+坚", "n": "左·大坚脉", "o": "左·大坚脉总起来主邪气亢实、积气内结及肝阳亢盛、风动气逆之候。大坚脉以“坚”示邪实内结，“大”示邪气亢盛，故其病机核心为实邪为患，非虚象。具体而言，大坚脉可主积气内结于脏腑，如心痹、肾痹等；左脉属肝，故左大坚脉尤主肝阳亢盛、风动于内，进而气机升逆、血随气上，导", "c": "主积气内结"}, {"id": "pc:左+大+实+坚+牢", "n": "左·大实坚牢脉", "o": "左·大实坚牢脉总起来主邪实内结、肝风鸱张、阳火有余，属实证、热证、动风之候。原文以情志重伤为因，君相火相应为机，初起如狂，医者误用辛温刚燥与苦寒直下，反助贼为虐，致左脉实大坚牢，大非吉兆。三类病机相互关联：阳火有余为病之本，邪实内结为病之形，肝风鸱张为病之动，", "c": "主邪实内结"}, {"id": "pc:左+大+实", "n": "左·大实脉", "o": "左·大实脉总以邪热壅盛为核心病机。实主邪盛，大主热，左脉候肝胆，故其主病多与肝胆火旺、风温上扰、上焦壅热相关。原文1271明言风温仍在上焦，清窍被蒙，实大之脉示温邪壅盛、肝胆之火上扰、气机升降失司；原文19361论心脉太过令人身热骨痛、口疮舌焦，亦属热盛之候。", "c": "主热"}, {"id": "pc:左+大+小", "n": "左·大小脉", "o": "左·大小脉总以左右脉象大小不等为特征，所主病机涉及虚损、邪热、肝胃不和、心肾不交及气血偏颇。左小右大多为营阴亏虚、邪热壅盛或肾水不足、心阳内亢；左大右小多属肝木偏亢、胃土不足，或阴不足而火扰、中气偏弱。各证之间相互关联：虚损可致邪陷，邪热可伤阴血，肝胃不和常兼", "c": "主虚损"}, {"id": "pc:左+大+小+芤+空", "n": "左·大小芤空脉", "o": "左大小芤空脉总属虚实夹杂之候，以阴血亏虚为本，暑热客邪为标。左脉小芤主平素积劳内虚，阴分不足；右脉空大主秋暑客邪，热深劫阴。二者相合，示正虚邪盛，热灼阴伤，故见寒热麻痹、腰痛冷汗、神迷心热烦躁，甚则虑其痉厥。其病机核心为“虚”与“热”交织：虚为积劳内伤，热为暑", "c": "主虚"}, {"id": "pc:左+大+平", "n": "左·大平脉", "o": "左·大平脉总起来主肝气偏亢、饮邪内动及病转厥阴之病机。左脉独大，左候肝，肝气偏亢则疏泄失司，伏饮内动，发为哮喘；肝郁气滞，误补致壅，则腹胀由生；右脉平而左脉大，示肺热已减而病转厥阴肝络。三类病机均以左大为核心，或为饮邪内动，或为肝郁气滞，或为病位传变，皆不离肝", "c": "主饮邪内动"}, {"id": "pc:左+大+弱+缓", "n": "左·大弱缓脉", "o": "左大弱缓脉总以气虚为本，兼见痰湿为标。弱缓大主气虚，右关滑主痰湿，二者相合，揭示脾虚气弱、运化失职、湿聚生痰之病机。痰湿中阻，中枢不运，则升降失司，胆木不降，肝阳上逆，变生耳聋等症。四类病机中，气虚为根本，痰湿为标象，脾虚生痰为中间环节，气痰阻络为最终病果，层", "c": "主气虚"}, {"id": "pc:左+大+弱", "n": "左·大弱脉", "o": "左大弱脉总以虚寒为本，尤以下焦阳气不足为核心。左弱直接主下焦虚冷，阳气衰微则温煦失职，故见冷彻骨中、形瘦日减；阳虚不能潜藏，则虚阳上浮，右大主上部火升，形成下寒上热、阴阳乖违之局。三者相互关联：虚寒为根本，阳浮为虚寒所致之标象，阴阳失调则是虚寒与阳浮并见的综合", "c": "主虚寒"}, {"id": "pc:左+大+急+疾", "n": "左·大急疾脉", "o": "左大急疾脉总属阴血大耗、虚阳外扰之候，兼见气弱，为血脱危象。其脉虽大急疾，非实热壅盛，乃阴血骤亏、阳失所附而浮越；右脉小微弱，又示气分不足。四类病机相互关联：阴血大耗为根，虚阳外扰为标，气弱为兼，血脱危候为全局判断。原文以热病血大泻、肌肤枯燥、脐旁动气、暑月难", "c": "主阴血大耗"}, {"id": "pc:左+大+散+乱", "n": "左·大散乱脉", "o": "左大散乱脉总属元气欲脱、邪盛正衰之危候。其脉大而散乱，大则邪气盛而正气衰，散为元气离散，阴阳不相维系。多见于产后触怒、泄泻昏愦、大热汗多、气促等症，法在不治。然散乱非绝脉，若及时温补固脱，脉转收敛，喘缓泻减，则属虚而可挽，非绝对死候。故本脉所主病机以元气离散为", "c": "主元气离散"}, {"id": "pc:左+大+散", "n": "左·大散脉", "o": "左大散脉总属虚候，以正气亏虚、气不内守为根本。散为气血涣散、元气离散，大为邪盛正衰或虚阳外浮。其主病机可归纳为：气血涣散、气血衰微、毒火伤阴耗气、元气欲脱、气机浮越、脾胃大虚。诸类之间以虚为共性：脾胃大虚则气血生化不足，进而气虚外散；毒火伤阴耗气可致气血两败；", "c": "主气血涣散"}, {"id": "pc:左+大+沉+浮+小", "n": "左·大沉浮小脉", "o": "左·大沉浮小脉在此案中总主虚与疟邪未净。患者年高形弱，劳心劳力，气血阴液亏耗，故左脉沉小、右脉浮濡无力，主虚；疟邪内扰，脾部弦洪，主疟。虚分阴虚与气虚：左脉沉小数主阴血不足、虚热内扰；右脉浮濡无力主脾肺气虚。疟邪未净则见弦洪，疟去后脉转缓弱，示邪退正虚。诸类相", "c": "主虚"}, {"id": "pc:左+大+洪+紧+急", "n": "左·大洪紧急脉", "o": "左·大洪紧急脉总起来主阳热亢盛、血气俱多之实证，病位涉及心、肾及腑。原文以“脉数在腑”定其热在阳分，以“脉大血气俱多”明其血气壅盛，又引扁鹊“脉大而洪，出于心”及“脉大而坚，病在肾”分属心肾。诸类之间，热在腑为总纲，血气俱多为脉象本质，病在心与病在肾为具体病位", "c": "主热在腑"}, {"id": "pc:左+大+洪", "n": "左·大洪脉", "o": "左·大洪脉总属阳热亢盛之象，主实证、热证，其病机涵盖热盛、肝火、痰火瘀热、阴亏火旺、积热及痧毒壅盛等。洪大脉为热邪炽盛、气血涌盛之征，多见于温疫、春温等外感热病，亦见于肝火、痰火、积热等内伤杂病。若洪大兼滑数，多主痰火瘀热；兼弦数，多主肝火；兼数大，主积热；若", "c": "主热盛"}, {"id": "pc:左+大+浮+散", "n": "左·大浮散脉", "o": "左·大浮散脉总属气机浮越、脏气失守之象。其脉大而浮散，既主正气亏虚、气不内守，又主气逆上浮、升降失常，并可因色脉相失而提示病邪逆顺之变。三类病机相互关联：虚为根本，气逆为变动，色脉相失为诊察要点。原文以“有诸内者形诸外”为纲，强调脉象随脏气变动而主不同病机，浮", "c": "主虚"}, {"id": "pc:左+大+浮+洪", "n": "左·大浮洪脉", "o": "左·大浮洪脉总属邪实亢盛之候，尤以血分伏邪为核心病机。其脉洪大而浮，既反映邪热亢盛于血分，又提示伏邪有外透之势；若兼神识昏愦、瘛疭肢厥，则示邪陷心包、内闭欲厥，为危重之兆。三类病机相互关联：邪盛为根本，血分伏邪为病位，内闭为邪盛深入之变。此脉总以祛邪护阴、搜逐", "c": "主邪盛"}, {"id": "pc:左+大+浮+濡", "n": "左·大浮濡脉", "o": "左·大浮濡脉总起来主肾虚阳浮、肝虚风动及虚风挟痰之病机。其核心在于肾水虚衰，不能涵木，导致肝血不足而内风妄动；虚阳上浮则尺脉浮大而濡，肝虚风动则左脉弦细。风动又可引动外风，致头风时发、肢节酸麻。三证相互关联：肾虚为本，肝虚风动为标，虚风挟痰为变。脉象浮大而濡与", "c": "主肾虚阳浮"}, {"id": "pc:左+大+浮+紧", "n": "左·大浮紧脉", "o": "左·大浮紧脉总起来主邪正交争、表里同病之候。其核心病机为实热与表寒：浮紧主表寒外束，大主邪盛，故见身热骨痛、口疮舌焦等实热壅盛之象；若来衰去衰，则又主心气不足、虚阳外浮之虚损。此外，脉大而坚搏急甚，提示病势进展，甚则危候。各类之间以'病在外'与'病在内'为纲：", "c": "主实热"}, {"id": "pc:左+大+浮", "n": "左·大浮脉", "o": "左·大浮脉总以浮大为主象，浮主表、大主热盛，故所主病机以表邪与热盛为核心。表邪包括外感风、寒、湿、暑等邪在表，如太阳风湿、阳明寒湿、表邪未散之嗽血、遗尿表邪等；热盛则见暑热充斥、风热内传、痰热生风。浮大又主风动，因热盛化风或虚风内动，如偏头风、痰热生风。此外，", "c": "主表邪"}, {"id": "pc:左+大+浮+虚", "n": "左·大浮虚脉", "o": "左大浮虚脉总起来主气郁痰阻、气血亏虚、心气不升三类病机。浮大虚甚为气虚阳浮、血亏之象；久取滞涩不匀，右沉涩细弱，寸沉欲绝，则示气郁生涎、痰阻胸中，心气不升，经脉壅遏。三者相互关联：气郁痰阻导致升降失司，进而气血亏虚，心气不升，心血不能自养。故本脉所主以气郁痰阻", "c": "主气郁痰阻"}, {"id": "pc:左+大+浮+软", "n": "左·大浮软脉", "o": "左·大浮软脉总起来主气虚湿盛、血虚有热，并可发展为气血俱亏、脾不统血。其脉象特征为浮软而大（右脉尤显）及虚软而小近快（左脉），浮软大主气虚湿盛，虚软小近快主血虚有热。三则医案均见经水不调、崩漏、带下、泄泻等症，病机核心为气虚湿滞与血虚有热并存，下多亡阴，血虚失", "c": "主气虚湿盛"}, {"id": "pc:左+大+涩", "n": "左·大涩脉", "o": "左·大涩脉总起来主液亏气滞之证。涩脉主营血亏少、津液不足，左大脉主肝气偏亢、气机不畅。二者合见，提示液亏为本、气滞为标，常见噎膈等症。原文'食入为噎'即因液亏胃失濡润，兼肝气偏亢而气滞。治疗先理气后润剂，标本兼顾。此脉所主病机以液亏为中心，气滞为伴随，二者相互", "c": "主液亏"}, {"id": "pc:左+大+濡", "n": "左·大濡脉", "o": "左·大濡脉总起来主肝风内动、中阳虚弱、湿阻气滞及肝脾不调之病机。左脉大主厥阴内风掀越，肝风震动；右脉濡主阳明中虚，气血不充，或脾运不健，湿邪内蕴。若左大右濡并见，多为肝风内动与阳明中虚并存，如老年暴中、舌强肢软；若濡而左较大，则侧重肝旺脾弱、湿阻气滞，见脘胀面", "c": "主肝风内动"}, {"id": "pc:左+大+牢", "n": "左·大牢脉", "o": "左大牢脉总主下焦寒凝、瘀血内蓄与疼痛。牢为寒为痛，大为邪盛，左脉候下焦血分，三者相合，揭示寒客下焦、血凝成瘀、瘀阻作痛的病机链条。三段落均围绕“下焦感寒停经，腹痛不止，血块时下”展开，脉症相符，治以温经散瘀。牢大脉所主之寒、瘀、痛并非孤立，寒为因，瘀为果，痛为", "c": "主寒凝"}, {"id": "pc:左+大+空", "n": "左·大空脉", "o": "左·大空脉总属虚损之象，以阴血亏虚、脉道不充为基本病机，其脉形阔大而按之不实，外强中干。由此可衍生数类：阴血亏虚为其本，虚阳浮越、肾水亏虚、肝风内动皆由阴亏阳亢所致；木亢土困为肝脾同病之变；正虚邪陷则为虚极危候。各段原文多强调“按之不实”“非实邪”，并与产后、", "c": "主阴血亏虚"}, {"id": "pc:左+大+紧", "n": "左·大紧脉", "o": "左·大紧脉总起来主邪正交争、实邪壅盛之候。紧主风邪劲急，大主邪盛，故其核心病机为风、热、湿邪交争，肝胆热郁生风，阳明湿浊不化。原文'左脉紧大'，伴统体作痛、口渴不清，反映风热湿邪搏结，肝胆郁热化风，湿浊内蕴。治以疏风分理，祛邪为先。各类病机相互关联：风邪劲急为", "c": "主风邪劲急"}, {"id": "pc:左+大+缓+散", "n": "左·大缓散脉", "o": "左·大缓散脉总属大虚之候，以气虚外散、脾胃大虚为核心病机。脉象散大而缓，重按无力，反映正气亏虚，气不内守而外散，同时脾胃虚弱，运化无力。三者相互关联：脾胃大虚导致气血生化不足，进而气虚外散，形成大虚证。原文治以参、芪、归、芍、白术等大补气血，佐连柏丸清余热，印", "c": "主气虚外散"}, {"id": "pc:左+大+缓", "n": "左·大缓脉", "o": "左大缓脉总属虚候，以气虚、脾胃大虚为核心，兼见血虚、痰湿、火旺等。脉象缓大无力，反映正气亏虚，气不内守。其下属大缓散脉主大虚，气虚外散、脾胃大虚；大弱缓脉主气虚兼痰湿。各段中，案3562为典型大虚证；案770为血虚络空、内风袭络；案14542为阴虚火旺兼伏痰；", "c": "主大虚"}, {"id": "pe:左+大", "n": "左·大脉", "o": "左·大脉总以左候肝心肾、大主邪盛与阳亢为纲，所主病机可归纳为肝阳亢盛、阴虚阳浮、邪热壅盛、虚中夹实、气血偏亢及元气欲脱六类。大脉本为气血涌盛之象，左部见之，首责肝阳升动、气火偏亢；若大而无力或兼弦细数涩，则阴亏于下、阳浮于上，或虚中夹实；若大而数、搏大有力，多", "c": "主肝阳亢盛"}, {"id": "pc:左+大+虚+空", "n": "左·大虚空脉", "o": "左·大虚空脉总属虚证，以阴血枯槁、阳气郁结、胃气衰败为核心病机。左脉大而空虚，非实热亢盛，乃阴血亏耗、脉道不充之象；右脉细小虚涩，为阳气郁结、津血不充。两脉合参，揭示阴血枯槁、阳气郁结、胃气将败之整体病机。原文见翻胃三月、粒米不存、面白神瘁、便燥，脉症合参已成", "c": "主阴血枯槁"}, {"id": "pc:左+大+虚", "n": "左·大虚脉", "o": "左·大虚脉总以虚大无力为纲，主气阴两虚、元气外浮，然兼弦、滑、坚、涩等象则虚实夹杂。其核心病机为正气亏虚，或为积劳元伤、气血两亏，或为暑热伤气、肝火亢盛，或为胃阴耗残、虚火挟浊，或为虚中夹实、痰火壅闭，或为积气内结、厥气上逆。诸类之间，虚为本，实为标：虚大无力", "c": "主气阴两虚"}, {"id": "pc:左+大+软", "n": "左·大软脉", "o": "左·大软脉总起来主气虚阳浮、脾虚湿困及下焦衰乏之候。左脉大主心肝阳浮不敛，右脉软主脾肺气虚不运，合而观之，为上盛下虚、心脾两亏之象。其病机核心在于中气不足、下元衰乏，导致阳气浮越于上，同时脾运失健、湿浊内困。原文见谷纳渐减、步履如蹈空，正是下焦衰乏、中气不足之", "c": "主气虚阳浮"}, {"id": "pe:左+实", "n": "左·实脉", "o": "左实脉总属实证、热证，以邪气壅盛、气血郁结为核心。其具体所主，或为湿热混处血络，或为肝木太过、气郁血结，或为邪热壅盛、痰气内阻，或为里实热结、蓄血坚积，或见正虚邪实、虚中夹实。诸类之间，实热壅盛为其根本，或兼湿、兼痰、兼气滞、兼血瘀，或兼正虚。左脉候肝胆与血，", "c": "主湿热入络"}, {"id": "pc:左+小+坚", "n": "左·小坚脉", "o": "左小坚脉总起来主虚中夹邪之候。小为不足，主阴血亏虚；坚劲为邪郁内搏，主暑热内伏、营卫失和。二者相合，形成阴血不足、暑热郁结的复合病机。原文'坚劲非纯实，乃虚中夹暑热郁结之象'，强调此脉虽见小、坚，但非纯虚或纯实，而是虚人感邪、正虚邪郁。其主病以虚为本，以暑热郁", "c": "主虚"}, {"id": "pc:左+小+弱+缓", "n": "左·小弱缓脉", "o": "左·小弱缓脉总主气虚，尤以气血不足、脾胃气虚为本。其脉小弱缓，为正气亏虚之象，非实邪所致。患者冬月感寒，前医发散伤阳，又用四物加柏知寒凉降下，致身热自汗、胸膈痞闷、便泻食少，皆气虚阳陷之变。左脉候血，小弱缓示血虚；右脉洪缓无力示脾胃气虚、虚阳外浮。故本脉所主病", "c": "主气虚"}, {"id": "pc:左+小+弱", "n": "左·小弱脉", "o": "左小弱脉总属正气亏虚之象，以气血不足、肝血亏虚为核心，兼及虚热、脾虚湿郁、气血交结及痰结肺底等复杂病机。小弱脉形细软无力，反映脉道不充、气血亏耗，故原文多谓'气血不足''血少''虚'。其兼证因虚致实：气血虚则脾运失健，湿郁化热；血虚则肝失濡养，气血交结而成胀；", "c": "主气血亏虚"}, {"id": "pc:左+小+濡+缓", "n": "左·小濡缓脉", "o": "左脉濡小而缓，总主脾虚湿滞、气血不足之证。濡主湿，缓主脾虚，小弱为气血亏虚。此脉多见于久病脾胃受损、湿邪内停之候。其病机核心为脾虚失运，湿滞中焦，进而导致气血生化不足，统血无权，湿郁下焦，营卫不和。各类病机相互关联：脾虚为本，湿滞为标，气血不足为果，脾不统血、", "c": "主脾虚湿滞"}, {"id": "pc:左+小+濡", "n": "左·小濡脉", "o": "左小濡脉总起来主阴血亏虚、湿滞、气火升浮、脾虚气血弱及肝肾亏虚五类病机。其核心特征是‘小’示不足，‘濡’主湿滞，故脉象本身反映正虚与湿恋并存。各段中，或侧重阴血耗伤而热升风旋，或侧重脾虚湿困而气血不足，或侧重肝肾亏虚而湿阻络脉，或侧重湿邪留恋而气机不利。各类之", "c": "主阴血亏虚"}, {"id": "pc:左+小+濡+软", "n": "左·小濡软脉", "o": "左小濡软脉总起来主湿、主气虚，并具体主暑湿伤气与湿阻气机。其核心病机为湿邪内蕴与气分不足相兼。患者素体丰肥，湿痰中虚，又冒暑贪凉，过啖寒凉，致暑伏湿阻；过服温热后，湿未化而气已伤。脉软小濡，软小示气虚，濡主湿，故为暑湿伤气之象；左脉沉细而弦，沉主里、细主虚、弦", "c": "主湿"}, {"id": "pc:左+小+紧+实", "n": "左·小紧实脉", "o": "左·小紧实脉总起来主邪实内结、寒凝气滞而兼血少之候。其“小”示脉道收敛、阴血不足或病位较深；“紧”主寒、主痛、主气机收引；“实”主邪气壅盛。三者相合，非单纯虚证，亦非单纯热证，而以寒实或邪实内阻为核心，并可兼见血少气盛之偏。原文以“小而紧”配肾，提示此脉与肾之", "c": "主肾实"}, {"id": "pc:左+小+缓+和", "n": "左·小缓和脉", "o": "左·小缓和脉总起来主邪退正复而余热未尽之病机。其脉象缓小而和，为气血渐复、脉道柔和之征，故主正气来复；然右关些数且有升动之气，又示中焦郁热未清、气机升动。两类病机相互关联：正复是邪退之果，余热是邪未尽之遗，故整体呈现疾病向愈过程中虚实夹杂、余邪未靖的状态。", "c": "主邪退正复"}, {"id": "pe:左+小", "n": "左·小脉", "o": "左小脉总属不足之象，以阴血精津亏虚、脉道不充为基本病机，故其总纲主虚。从24段看，单纯虚证可见阴血亏虚、精亏阳虚、气阴两伤；虚而兼邪则见虚中夹热、肝郁脾虚、痰瘀气滞。各类之间以“虚”为枢：阴血亏少则脉小，精血不足则左小不静，气阴耗伤则小兼数滞；虚处留邪，或化热", "c": "主阴血亏虚"}, {"id": "pc:左+小+芤", "n": "左·小芤脉", "o": "左·小芤脉总属虚候，以血虚为核心，兼见气亏。小为脉道细少，芤为中空失血，合之主阴血亏虚、脉道不充。其主病机主要有四：一主血虚，因失血或新产之后血少脉空；二主气亏，常与右脉空大无力并见，示气血两亏；三主暑热劫阴，秋暑客邪乘虚深入脏阴，热深劫阴，脉见小芤；四主清窍", "c": "主血虚"}, {"id": "pc:左+小+软", "n": "左·小软脉", "o": "左·小软脉总属虚证，以气血不足为核心，兼涉湿滞、虚热及脏腑同病。其脉软小，主营血亏虚、中气虚弱；左尺微弱尤显血虚，右脉浮软颇大则示气虚。虚而兼热，则见咳血声嘶、脉促中止；虚而兼湿，则见浮肿便溏、脉濡乏力。病久及脏，或肝脾同病，左脉虚弦、右脉软小；或胃气大虚，右", "c": "主血虚"}, {"id": "pe:左+平", "n": "左·平脉", "o": "左·平脉总起来主正气渐复、病势趋缓，但常非纯和之象，多兼见他部脉异常而揭示余邪未清或潜在病机。其核心在于左脉平和而右脉或他部见动、数、弦、滑、实等，说明病位多在右部或中下焦。所主病机可归为五类：向愈、余邪未清、虚损、火旺、气闭痰壅。向愈为正复邪退之佳兆；余邪未", "c": "主向愈"}, {"id": "pc:左+弦+促", "n": "左·弦促脉", "o": "左弦促脉总起来主肝木强横、气机郁迫，其病机核心在肝。弦为肝气，促为气急，合见则肝郁气逆、木亢侮土。由此可衍生四类：一为肝郁气逆，气火上冲，刑金灼肺；二为木亢侮土，克脾犯胃，中气受戕；三为虚中挟实，正虚邪陷，攻补两难；四为阴亏火旺，阴液耗伤，木火内炽。四类之间相", "c": "主肝郁气逆"}, {"id": "pc:左+弦+动", "n": "左·弦动脉", "o": "左弦动脉总属肝脾同病，以肝阴亏虚、肝阳不潜为核心，兼脾不输精。左脉候肝，弦动为肝阴不足、阳失所制而亢动之象；肝阴亏虚，又因脾失健运、不能输精上供所致。三者互为因果：脾虚不输精则肝阴亏，肝阴亏则阳不潜而亢动，亢动又耗阴。故其主病机可归纳为肝阴亏虚、肝阳不潜、脾不", "c": "主肝阴亏虚"}, {"id": "pc:左+弦+和+硬", "n": "左·弦和硬脉", "o": "左关弦和硬脉，总属肝胆病脉。弦为肝之主脉，硬则示气机刚劲失和、邪气留滞。此脉所主病机主要有二：一为肝胆留邪，二为木亢乘肺胃。二者相互关联，留邪是根本，木亢是病势。原文虽见咳嗽大减、红痰已无，但痰色青黄、左关弦硬不和，说明肝胆之邪未尽，木气仍偏亢，容易乘肺胃俞，", "c": "主肝胆留邪"}, {"id": "pc:左+弦+坚", "n": "左·弦坚脉", "o": "左弦坚脉总属肝木为病，以弦为肝之常脉，坚则示邪实或阴血内亏、络脉失柔。其病机核心在肝阳化风、肝郁气结，并可横逆脾胃，或夹伏温内闭。诸类之间，肝风与伏温常相合为患，郁结与木侮中土互为因果，皆由肝失疏泄、气机壅塞所致。脉坚搏指，非纯虚之象，多实中夹虚，故所主以肝风", "c": "主肝风"}, {"id": "pc:左+弦+大+坚", "n": "左·弦大坚脉", "o": "左弦大坚脉总属肝阳亢盛、风动于内之候。弦为肝之常脉，大坚则示邪气亢实，非虚象。其病机核心在肝风震动，因肝阳上亢，化风内扰，上则影响心神而致不安寐，中则横逆脾胃，使络脉不和、运化失职，故见不知饥、口流涎、右肢肿等症。此脉所主，以肝风为源，以脾胃络脉不和为流，二者", "c": "主肝风内动"}, {"id": "pc:左+弦+大+浮", "n": "左·弦大浮脉", "o": "左·弦大浮脉总属风热痰火为患，以浮弦大数为主，浮主风邪外袭，弦主肝气郁逆，大主热盛，数主急迫。其病机核心在风、热、痰、火四者交结，上壅清窍，涉及肝胃。原文两段均见耳鸣、鼻塞、痰多膈热，脉左浮弦大、右滑大俱数，断为胃中痰火上壅，热极生风。故本脉所主，一为风热上攻", "c": "主风热上壅"}, {"id": "pc:左+弦+大", "n": "左·弦大脉", "o": "左·弦大脉总以弦为肝郁气滞、大为邪实或阳亢为纲，所主病机可归纳为肝郁气滞、肝火亢盛、肝阳化风、痰火壅盛、热毒炽盛、邪留血分、阴虚阳亢及虚中夹实八类。弦脉主肝、主痛、主气郁，大脉主邪盛、主火亢、主虚阳外浮，左脉候肝，故弦大并见多反映肝胆气机失调、火盛阳亢，或邪实", "c": "主肝郁气滞"}, {"id": "pc:左+弦+大+芤", "n": "左·弦大芤脉", "o": "左弦大芤脉总主肝逆气亢、阴血亏虚、气火亢盛、血不归络之病机。弦为肝逆，大为气火亢盛，芤为阴血内亏、血不归络。四类相互关联：水不养肝则肝不藏血，阴血亏虚而气火偏亢，气逆血上，冲犯阳明，致狂吐之患。脉不安静、波涛不定，正示气逆血涌、血行失道之机。其本在阴血亏虚，其", "c": "主肝逆气亢"}, {"id": "pc:左+弦+大+虚+空", "n": "左·弦大虚空脉", "o": "左·弦大虚空脉总属虚证，以阳气亏虚、劳伤日久为核心病机。左脉弦大空虚，非实热亢盛，乃阳气浮越、脉道不充之象，主积劳伤阳；右脉虚软涩滞，主脾运不健、湿滞内停。两脉合参，揭示脾肾阳虚、肝脾失和、运化失职之整体病机。弦大空虚与虚软涩滞并见，虚中夹滞，故见能食不能运、", "c": "主阳虚劳伤"}, {"id": "pc:左+弦+大+虚+缓", "n": "左·弦大虚缓脉", "o": "左弦大虚缓脉总属阴虚劳怯、咳嗽失血之候。其脉象虽兼弦、大、虚、缓、数等不同，然核心病机为阴液亏虚、虚火内扰。脉小不劲者，阴亏而阳不亢；虚弦软数者，虚火内扰、肺肾阴伤；弦大以数者，心肝火旺而阴不制。三者皆从不同侧面反映阴虚火旺之本质：或偏肺肾阴伤，或偏心肝火旺，", "c": "主阴虚火旺"}, {"id": "pc:左+弦+大+虚", "n": "左·弦大虚脉", "o": "左弦大虚脉总属虚证，以肝旺脾虚、气血亏虚为核心，兼见虚阳上浮、肾虚失血及阴虚火旺。弦为肝旺，大为虚阳或虚象，虚为不足，三者相合，非实热亢盛，乃脉道不充、阳气浮越之候。各段或重在木亢土弱（），或重在虚阳上浮（），或从尺乱识肾虚失血（），或从虚缓数分阴虚火旺（下属", "c": "主肝旺脾虚"}, {"id": "pc:左+弦+大+软", "n": "左·弦大软脉", "o": "左弦大软脉总起来主肝旺阴薄、脾虚湿困、湿热内蕴之复合病机。左脉弦大反映肝木偏旺而阴分不足，右脉软反映脾虚湿困，两者合参则肝脾不调，湿热内生。四类病机相互关联：阴薄致肝旺，肝旺乘脾则脾虚，脾虚生湿，湿郁化热，形成虚实夹杂之候。原文强调‘阴薄之体，须速为清理’，提", "c": "主肝旺"}, {"id": "pc:左+弦+实", "n": "左·弦实脉", "o": "左弦实脉总起来主肝木太过、气郁血结之证，并可累及胃与下焦。弦为肝郁，实为邪壅，左关候肝，故其核心病机为肝气郁结、疏泄失常。气郁日久则血行不畅，形成血郁血结；肝气横逆，贯膈犯胃，则见肝木犯胃、胃气上逆；肝气太过，亢盛于外，则令人忘忽眩运、胁痛喜怒；若湿热瘀血壅结", "c": "主肝木犯胃"}, {"id": "pc:左+弦+小+促", "n": "左·弦小促脉", "o": "左弦小促脉总起来主肝气上逆、阴伤阳郁与正虚邪陷三类病机。弦为肝气，小为阴伤，促为阳郁，三象合见，反映湿温伏邪内陷少阴，引动冲气上击，犯胃冲肺，肃降无权，故气喘呃逆、身热不扬；同时阴液耗伤、阳气郁遏，正虚邪陷，神不守舍，故郑声神糊、时明时昧。右濡细、趺阳虚弦数、", "c": "主肝气上逆"}, {"id": "pc:左+弦+小+弱", "n": "左·弦小弱脉", "o": "左弦小弱脉在此案中总起来主肝血不足与暑湿弥漫气分，并用以鉴别非少阳疟症。左脉小弱反映肝血亏虚，脉道不充；右脉洪大反映暑邪由肺入胃，暑兼湿壅阻三焦气分。左脉不弦而小弱，既说明非少阳疟症，又提示暑湿弥漫气分之病机。三类病机相互关联：肝血不足为素体基础，暑湿弥漫为当", "c": "主肝血不足"}, {"id": "pc:左+弦+小", "n": "左·弦小脉", "o": "左·弦小脉总以肝郁脾虚为核心，弦主肝木郁滞、气逆，小主气虚、血少、阴亏。其病机可归纳为五类：肝郁气逆、脾虚湿困、虚中夹热、痰积气滞、气血瘀滞。各段原文多强调“左小弦主肝郁”“小为脾虚”，弦小并见常示木郁乘土、虚实夹杂。如噎膈由阴阳日衰、肝郁脾虚湿滞；胎前气逆冲", "c": "主肝郁气逆"}, {"id": "pc:左+弦+平+硬", "n": "左·弦平硬脉", "o": "左·弦平硬脉总起来主肝木偏亢、脾土衰败之病机。其核心在于弦硬之脉反映肝气刚劲，而右脉歇止则揭示脾胃中气竭绝，土德大残。三类病机相互关联：土德大残与中气衰竭实为脾胃衰败的不同表述，而肝木乘脾则是导致或加重土衰的关键因素。弦硬为肝旺之象，歇止为脾绝之兆，二者并见，", "c": "主土德大残"}, {"id": "pc:左+弦+平+长", "n": "左·弦平长脉", "o": "左弦平长脉总以肝木之常异为纲。弦长为肝之平脉，软弱冲和则无病；反此则分太过、不及与气逆。实而弦为太过，病在外，主肝实，见忘忽眩运、胁痛喜怒；虚而微为不及，病在内，主肝虚，见胸胁胀满；沉而急则肝气逆，主胁满、小便难、头痛眼眩、恶言。四类皆从肝木立论：平脉为常，实", "c": ""}, {"id": "pc:左+弦+弱", "n": "左·弦弱脉", "o": "左·弦弱脉总以左弦右弱（或左弱右弦）并见为特征，其病机核心是正虚与邪实并存。左弦多应肝气偏亢、肝木失柔，右弱多应脾胃气弱、中阳不足；反之左弱多应肝血亏虚或阳气不足，右弦多应邪气壅滞、痰湿内阻。故其主病可归纳为肝旺乘土、正虚邪恋、脾虚湿滞、肝血不足、痰饮上泛、阳", "c": "主肝旺乘土"}, {"id": "pc:左+弦+微+急", "n": "左·弦微急脉", "o": "左·弦微急脉总属肝气失调、气机郁滞之象。弦为肝之本脉，微急则示气郁不舒、筋脉拘急。其病机可归为四类：肝郁气滞为根本，气机不畅则郁；寒凝收引使脉道拘急；气血壅阻不通则发为痛证；而三者皆本于脏气失调，脉随脏气变动而显。原文强调「有诸内者形诸外」，脉与色相参以判逆顺", "c": "主肝郁气滞"}, {"id": "pc:左+弦+微+涩", "n": "左·弦微涩脉", "o": "左弦微涩脉总属阳虚寒凝、疝瘕内结之候。脉微涩为阳气衰少、血行不畅，左弦主少腹疝瘕。三者相互关联：阳气大伤则温煦失职，故见跗廉麻冷、畏风怕寒、神呆色衰；阳虚寒凝，气血涩滞，则少腹微满、睪丸日肿，发为疝瘕。其病机核心为阳虚为本，寒凝为标，疝瘕为果，属难愈之疾。", "c": "主阳虚"}, {"id": "pc:左+弦+微+硬", "n": "左·弦微硬脉", "o": "左弦微硬脉总属肝郁气逆、血虚火旺，兼木旺克土、脾胃受戕之候。其脉左部弦而微硬，弦主肝郁，硬为气郁化火伤阴，故主肝经气郁与血虚火盛；右部濡弱或重按无力，为木旺克土、脾胃虚弱之象。三类病机相互关联：肝郁气逆为始动因素，气郁化火伤阴则血虚火旺，木旺乘土则脾虚不运。病", "c": "主肝郁气逆"}, {"id": "pc:左+弦+微", "n": "左·弦微脉", "o": "左·弦微脉总属肝木为病，以肝郁气滞为核心，兼见虚损、痰饮、疟邪、痛证、疝瘕、血虚火旺等多类病机。弦主肝郁，微主阳衰或阴血不足，故其病机往往虚实夹杂。肝郁日久可化热伤阴，致血虚火旺；木旺克土，脾运失职，则痰饮湿浊内生；阳虚寒凝，气血涩滞，则发为疝瘕痛证；少阳受邪", "c": "主肝郁气滞"}, {"id": "pc:左+弦+微+软", "n": "左·弦微软脉", "o": "左弦微软脉总属内因虚损、气郁痰凝之候。其脉左微弦，主肝郁血少；右软，主气分不足。气郁则津凝为痰，痰入筋骨发为流痰；溃后气营交困，络脉失养，故患处肿木、手臂不能举动。诸类病机相互关联：气郁为痰凝之因，血少为络脉失养之由，气分不足则营血难复，终致气营交困。此脉不见", "c": "主气郁"}, {"id": "pc:左+弦+急", "n": "左·弦急脉", "o": "左弦急脉总以肝木为病变核心，所主病机可归纳为肝火、风动、气逆、郁滞及虚中夹实五类。弦为肝脉，急为气火亢盛或拘急之象，故木火旺令则肝火冲逆迫血；风邪客于筋脉则拘急成痹；气机逆乱则呃忒呕恶；肝郁邪滞则寒热反复、筋急溺痛；若与细软空细并见，则示阴血亏虚而邪滞未化，形", "c": "主肝火"}, {"id": "pc:左+弦+散", "n": "左·弦散脉", "o": "左·弦散脉总起来主肝气未和、营卫不调、阴损未复及气弱有热。弦为肝脉，不散示内风虽平而肝气未和；营卫未能调畅，最防往来寒热；阴损已极，舌糜不退，虑胃气不复；右脉软数，主气弱有热。诸类相互关联：肝气未和则营卫失畅，阴损气弱则虚热内生，故脉象弦而不散、软数并见，反映", "c": "主肝气未和"}, {"id": "pc:左+弦+沉+和", "n": "左·弦沉和脉", "o": "左弦沉和脉在风气腹痛之治中，总以脉之浮沉迟弦分表里用药。浮缓、浮脉主风邪在表，治宜祛风；沉弦主邪郁于里，治宜和里；迟脉主中焦虚寒，治宜温中。三类病机以风邪为核心，或偏表、或偏里、或兼虚寒，相互关联：风邪外袭可致表证，久则郁里，或伤中阳。临床凭脉辨表里虚实，分别", "c": "主风邪在表"}, {"id": "pc:左+弦+沉+小", "n": "左·弦沉小脉", "o": "左弦沉小脉总起来主里虚、肝郁、冲逆、木火及土虚诸类病机。沉小为里虚之基，弦为肝郁之象，二者相合，示正气内虚而肝气郁滞。肝郁日久，或化火冲胃而为木火，或挟冲脉上逆而为冲逆；木旺乘土，则脾土虚弱，运化失职。诸类之间以肝郁为中心：肝郁则冲逆、化火，木火又乘土，土虚则", "c": "主肝郁"}, {"id": "pc:左+弦+沉+微+硬", "n": "左·弦沉微硬脉", "o": "左弦沉微硬脉总属肝郁气结、血虚火旺，兼木旺克土、脾胃受戕之候。其脉左部沉弦微硬，沉主里，弦主肝，硬为气郁化火伤阴，故主肝经气郁与血虚火盛；右部弦而无力，为木旺克土、脾胃虚弱之象。病本在肝，标在脾胃，肝郁化火伤阴为本，木旺克土致脾胃不运为标。四类病机相互关联：肝", "c": "主肝郁气结"}, {"id": "pc:左+弦+沉+浮+紧", "n": "左·弦沉浮紧脉", "o": "左弦沉浮紧脉总属外寒引动内饮、饮邪上泛之候。浮弦主风饮上泛，沉紧主水寒内结，二者并见则示表里同病、外寒内饮相搏。其病机核心为风、寒、饮三者交结：风邪外袭则脉浮弦，寒饮内结则脉沉紧，饮邪迫肺则喘咳自汗，势甚凶危。三类病机相互关联，外风引动内饮是发病之由，风饮上泛", "c": "主风饮上泛"}, {"id": "pc:左+弦+沉+涩", "n": "左·弦沉涩脉", "o": "左·弦沉涩脉总起来主肝血瘀滞、气郁湿阻及冲任不调。左脉涩主肝血瘀滞，右脉沉弦主气郁湿阻，二者相合，气血不畅，湿瘀互结，影响冲任带脉，故见带注腹痛有症、中脘胀闷背掣。三类病机相互关联：肝血瘀滞与气郁湿阻为病因，冲任不调为结果，共同构成气血湿瘀交阻之候，治宜顺气利", "c": "肝血瘀滞"}, {"id": "pc:左+弦+沉+硬", "n": "左·弦沉硬脉", "o": "左·弦沉硬脉总属肝经病变，以肝郁气结、血虚火旺为本，兼木旺克土、脾胃受戕为标。其脉左部弦硬而沉，弦主肝、沉主里、硬为气郁化火伤阴，故首主肝气郁结与血虚火盛；右部弦而无力，为木旺克土、脾胃虚弱之象。病本在肝，标在脾胃，肝郁化火伤阴为本，木旺克土致脾胃不运为标。三", "c": "主肝郁气结"}, {"id": "pc:左+弦+沉", "n": "左·弦沉脉", "o": "左·弦沉脉总以沉、弦二象合见为特征，沉主里、主下焦，弦主郁、主饮、主肝木。其总病机为肝郁气滞、水饮内停，并可兼化火、兼痰、兼瘀、兼湿热积滞，或兼肾虚不纳。从所收42段看，单纯主饮者如饮泛咳呛、气喘；主郁者如腹胁虚胀、胸膈窒闷；郁久化火则见胁疼、便燥、头晕、厥证", "c": "主饮"}, {"id": "pc:左+弦+沉+虚", "n": "左·弦沉虚脉", "o": "左弦沉虚脉总属虚实夹杂之象，以阳气虚损为本，气机郁滞为标。沉为阳陷，弦虚为劳伤中气、清阳不升，故脉主过劳伤阳、清浊失运之病机。其核心在于阳气微弱不能流通，既非有形实滞，亦非单纯虚损，而是虚中夹滞。三类病机相互关联：阳伤气陷为病机之根，虚损为脉象之本，气滞为脉象", "c": "主阳伤气陷"}, {"id": "pc:左+弦+沉+迟", "n": "左·弦沉迟脉", "o": "左弦沉迟脉总属里证，以沉迟弦为基本脉象，主内寒肝郁；若沉而无力，则主气血不足；若兼浮，则提示外感表邪未解。三类病机可单独出现，亦可相兼为病。内寒肝郁为脉象直接对应之核心病机，气血不足为脉力强弱所反映的虚损病机，表邪未解则为兼浮之变。临证需结合脉力、兼脉及症状，", "c": "主内寒肝郁"}, {"id": "pc:左+弦+洪", "n": "左·弦洪脉", "o": "左弦洪脉总属肝木化火、热盛阴伤之候。弦为肝脉，洪为火热，故核心病机为肝火亢盛；火盛灼阴，则兼阴伤；木火刑金，灼津为痰，则痰热内蕴；火盛阳升，肝阳上僭，则气冲、面赤、不眠；若邪热内陷，郁结不达，则脉见洪数中带紧涩。诸类以肝火亢盛为始，进而导致阴虚阳浮、气逆血涌、", "c": "主肝火亢盛"}, {"id": "pc:左+弦+浮+涩", "n": "左·弦浮涩脉", "o": "左弦浮涩脉总主肝郁脾困、虚损胀满之病机。左弦为肝木怫郁，右浮涩为脾土自困、清浊混淆，二者相合，反映肝郁乘脾、气滞湿阻之候。其病始于情志不遂，肝气郁结，继而脾运失健，清浊不分，水湿内停，久则脏真日漓，腑阳不运，终成胀满。脉弦与涩并见，提示虚实夹杂：弦为气郁，涩为", "c": "主肝郁"}, {"id": "pc:左+弦+浮+硬", "n": "左·弦浮硬脉", "o": "左弦浮硬脉总起来主肝胆火盛、阴虚阳亢、气血两虚及热痰中焦四类病机。弦主肝，硬主火盛，浮主上炎，故首主肝胆之火挟热上冲；浮弦硬而不任重按，又为阴血亏虚、阳气外浮之象；脉弱而浮硬，兼经血不行、身体甚弱，则主气血两虚；右脉沉滑，舌苔黏腻，涎沫上溢，又示热痰杜塞中焦。", "c": "主肝胆火盛"}, {"id": "pc:左+弦+浮+缓", "n": "左·弦浮缓脉", "o": "左弦浮缓脉总属阳气虚衰、脾胃气弱之候。其脉浮而缓，浮为虚阳外浮，缓为阳气弛缓；兼弦则虚风内动、气机不畅。所主病机以阳虚为核心，涉及脾虚、气弱。阳虚不能温煦则足冷身寒，脾虚运化失职则能食易饥而消瘦，气弱鼓动无力则神色清减、久卧床枕。三者相互关联：阳虚为根本，脾虚", "c": "主阳虚"}, {"id": "pc:左+弦+浮", "n": "左·弦浮脉", "o": "左弦浮脉总以浮、弦二象为纲：浮主表、主阳浮，弦主肝木、主风、主痰饮、主痛。合而观之，其病机可归为外感风邪、肝胆郁火、痰饮湿浊、郁热血瘀、虚损劳伤及疟痢积滞六类。外感风邪者，浮弦应表，风邪伤卫；肝胆郁火者，弦为肝木，浮为阳升，风阳上扰或肝火升腾；痰饮湿浊者，弦主", "c": "主风邪外袭"}, {"id": "pc:左+弦+涩+小", "n": "左·弦涩小脉", "o": "左弦涩小脉总属阳气衰微、阴血亏少、气机不畅之候。其脉小涩为阳微血少，弦为脾阳受困、气机不畅，三象相合，反映太阴脾阳不振、气血不足、运化失司。所主病机以阳微血少为本，脾阳受困为标，气机不畅为兼，三者相互影响：阳微则血少，血少则脉涩，脾阳困则气滞而弦。原文见六旬有", "c": "主阳微血少"}, {"id": "pc:左+弦+涩+弱", "n": "左·弦涩弱脉", "o": "左弦涩弱脉总起来主肝血郁滞、肺气不足、气机失司及本虚标实之证。左脉弦涩，为肝血郁滞，血行不畅；右脉弱，为肺气不足，宣发无力。肺主出气，肾主纳气，气虚则阳不下达，金不制木，木反乘金，故见咳嗽、浮肿先于身半以上，继以失血。弦涩弱并见，反映本虚标实、气机升降失司，病", "c": "主肝血郁滞"}, {"id": "pc:左+弦+涩+濡", "n": "左·弦涩濡脉", "o": "左弦涩濡脉（此处实际为右濡左不弦而涩）总起来主脾虚湿滞、营血不足、气机不畅及气陷下痢之病机。右濡为脾虚湿滞，左涩为营血不足、气机不畅，二者相合，反映暑湿伤脾、气弱不化、冷物阻滞中焦、脾阳既虚不能达邪的病理状态。其核心在于脾阳虚弱，运化失职，湿滞中焦，气血生化不", "c": "主脾虚湿滞"}, {"id": "pc:左+弦+涩+紧+迟", "n": "左·弦涩紧迟脉", "o": "左弦涩紧迟脉总起来主寒凝气滞、气逆食滞交阻之实证。其脉象以紧迟涩为主，紧迟应寒，涩应气滞食积；左弦紧突出寒邪引动厥气上逆、肝脉拘急，右迟涩侧重寒凝气滞、食滞交阻中宫。三类病机相互关联：新寒外受为诱因，寒凝导致气滞，气滞则厥气上逆，食滞交阻中宫，胃气不得下降，故", "c": "主寒凝气滞"}, {"id": "pc:左+弦+涩", "n": "左·弦涩脉", "o": "左弦涩脉总以肝郁气滞与血少涩滞为基本病机。弦为肝气偏旺、气机郁滞，涩为血行不畅、阴血亏少。二者并见，多示气滞血瘀、血虚肝旺之候。其具体所主，约分七类：肝郁气滞、血虚阴亏、血瘀积滞、木火刑金、脾虚湿困、寒凝气滞、痰饮内停。诸类之间常相互兼夹：肝郁气滞可横逆犯胃而", "c": "主肝郁气滞"}, {"id": "pc:左+弦+滑+动", "n": "左·弦滑动脉", "o": "左弦滑动脉在此案中总主妊娠与热伤肺阴两类病机。弦滑流动为妊娠气血充盛、胎气搏结之常脉，故首主妊象；然同一脉象又见于气急脘痞咳嗽、形肉日瘦，是热气上乘迫肺、烁阴耗气之候，故兼主热与气逆。妊为生理之常，热为病理之变，二者并存，提示辨证须护胎与清热并重，清金平气而勿", "c": "主妊"}, {"id": "pc:左+弦+滑+和", "n": "左·弦滑和脉", "o": "左·弦滑和脉总属肝胃同病、气郁痰湿交阻之象。弦主气郁，滑主痰湿，二者并见，反映肝气郁滞、痰湿内蕴，病位重在肝胃。原文左寸关弦象稍退、右关弦滑稍柔和，是肝胃之气渐得调和、郁滞稍解、痰湿渐化之征，故胀满渐舒、略能安谷。三类病机相互关联：气郁可生痰湿，痰湿可碍气机，", "c": "主气郁"}, {"id": "pc:左+弦+滑+大", "n": "左·弦滑大脉", "o": "左弦滑大脉总起来主肝胃火盛与木郁痰凝两类病机。弦主肝郁，滑主痰，大主邪实，合而观之，或为肝火素盛、胃热壅盛之实热证，或为肝木郁结、痰浊凝滞之顽疾。前者脉弦强滑大，伴舌绛目赤、大渴饮冷，属火热侵营；后者脉左关弦大而滑，见顽硬如岩，属痰郁互结。两者皆以弦滑大为脉象", "c": "主肝火"}, {"id": "pc:左+弦+滑+小", "n": "左·弦滑小脉", "o": "左弦滑小脉总起来主肝胃不和、中虚痰滞之病机。左脉弦主肝木偏旺，右脉小滑主中阳不足、痰湿内停，合而示肝气犯胃、木土失调。其病机核心在于中阳不足，运化失司，痰湿内生，肝木乘虚横逆犯胃，胃失和降，故见晨起呕吐、得食尤甚、甚则脘痛彻背。四类病机相互关联：肝旺为标，中虚", "c": "主肝旺"}, {"id": "pc:左+弦+滑+洪+硬", "n": "左·弦滑洪硬脉", "o": "左·弦滑洪硬脉在此案中实际表现为弦硬而长、数近七至，故所主病机以热盛、阴虚、气血两亏及正虚邪恋为主。数脉主热，亦主阴虚；弦硬而长为气血两亏、邪热炽盛之征；正气虚损不能拒邪亦现数，故见正虚邪恋。诸类之间相互关联：邪热炽盛可耗伤阴液，致阴虚有热；热盛又可损气耗血，", "c": "主热盛"}, {"id": "pc:左+弦+滑+濡", "n": "左·弦滑濡脉", "o": "左·弦滑濡脉总起来主湿浊内盛、脾虚湿困、肝气不舒及正虚邪恋，属虚实夹杂之候。弦脉主肝气不舒或土虚木乘，滑脉主痰湿水聚，濡脉主湿困或气血两亏。四段原文均见湿浊为患，或从下受，或由脾虚不运，或疟久湿留，或疳积化肿，湿邪困阻气机，致肝失疏泄，木郁克土；久病则正气亏虚", "c": "主湿浊内盛"}, {"id": "pc:左+弦+滑", "n": "左·弦滑脉", "o": "左弦滑脉总以弦为肝气偏旺、气机不畅，滑为痰湿内蕴、痰食积滞为基本病机。弦见于左关，故病位多在肝胆，涉及气郁、风阳、疟邪；滑见于右脉，故病位多在脾肺，涉及痰湿、痰食、痰热。二者相合，常见肝郁痰凝、风痰阻络、肝脾不调、痰热郁结、疟兼痰湿、积滞痰食等证。各类之间以'", "c": "主肝郁气滞"}, {"id": "pc:左+弦+滑+虚+濡", "n": "左·弦滑虚濡脉", "o": "左弦滑虚濡脉总属正虚邪恋、虚实夹杂之候。左脉虚弦，主少阴阴阳两亏、气血不足，虚而兼弦，或为虚火上浮；右脉濡滑，主脾胃不健、湿浊痰毒留恋。四段原文皆见于中发背后期，腐肉渐脱而脉象未和，示正气已虚而湿毒未净。虚弦与濡滑并见，反映气阴两亏与脾虚湿恋并存，虚火易升而湿", "c": "主虚"}, {"id": "pc:左+弦+滑+软", "n": "左·弦滑软脉", "o": "左弦滑软脉总起来主湿痰未清、正气不足与肝郁气滞三类病机。滑主湿痰内蕴，软主中气虚弱，左弦主肝木郁滞。三者并见，反映痛痢之后邪未尽而正已伤、脾运未复而肝木乘土之复杂局面：湿痰滞留中焦故脉滑，脾气亏虚故脉软，肝气不调故左弦。其核心为虚实夹杂、木土不和，治当培土调气", "c": "主湿痰未清"}, {"id": "pc:左+弦+濡+空", "n": "左·弦濡空脉", "o": "左弦濡空脉总属虚中夹实、形神两伤之候。其核心病机为气血耗损、络血不宁：濡空主气血亏虚、形神失养，为病之本；弦主络脉拘急、血行失和，为病之标。三者相互影响，气血耗损则络脉不固，络血不宁又加重气血耗伤，形成形神两伤、吐血频发的病理循环。此脉多见于久病劳伤、经营耗神", "c": "主络血不宁"}, {"id": "pc:左+弦+濡", "n": "左·弦濡脉", "o": "左弦濡脉总以肝郁脾虚为核心，弦主肝气偏旺、气机郁滞，濡主脾虚湿困、营阴不足。其病机可归纳为肝郁气滞、脾虚湿困、饮邪内停、阳虚水泛、胃虚肝乘、营阴亏虚及肝肺虚损七类。弦与濡并见，反映肝木偏亢与脾土虚弱并存，木旺乘土、土虚生湿，湿聚成饮，饮遏阳气，久则及肾，致阳虚", "c": "主肝郁气滞"}, {"id": "pc:左+弦+牢", "n": "左·弦牢脉", "o": "左弦牢脉总属肝郁气滞、病深牢固之候。弦为气郁之常脉，牢为邪结深固之征，二者兼见，提示肝气郁结日久，气机壅滞深重。原文以左脉候肝，故知病位在肝；症见胸胁大痛，亦合肝郁气滞之机。此脉虽以气郁为主，但牢象示郁结顽固，非一般气滞可比。三类病机相互关联：气郁为始，深固为", "c": "主气郁"}, {"id": "pc:左+弦+疾+促", "n": "左·弦疾促脉", "o": "左弦疾促脉总属肝阳亢盛、痰火内扰之象。其脉弦主肝，疾促主阳热急迫，结合右滑数而溢，反映痰热壅肺、肝阳上逆的复合病机。原文所载冬温挟痰阻肺案，高年感邪，痰热内郁，引动肝阳直升，故脉见左弦疾而促。三类病机相互关联：冬温挟痰为病因，痰火内扰为病机核心，肝阳亢盛为脉象", "c": "主肝阳亢盛"}, {"id": "pc:左+弦+疾+坚", "n": "左·弦疾坚脉", "o": "左·弦疾坚脉总起来主气郁、热盛、痰热与邪结。弦主气机郁滞，疾主热盛，坚搏示邪结，滑数则主痰热。诸类相互关联：患者素体气滞多痰，痰热内蕴，复感疟邪，致气郁化火，热盛痰结，脉见弦疾坚搏。误治温补后，邪热鸱张，气机壅塞，痰热与郁火相合，邪结更深，故左脉尤坚搏。四类病", "c": "主气郁"}, {"id": "pc:左+弦+疾", "n": "左·弦疾脉", "o": "左·弦疾脉总起来主气郁、热盛、痰热、邪结及肝阳上逆等病机。弦主气机郁滞，疾主热盛，坚搏示邪结，滑数主痰热，促主阳热急迫。诸类相互关联：患者素体气滞多痰，痰热内蕴，复感疟邪或冬温，致气郁化火，热盛痰结，脉见弦疾坚搏或弦疾而促。误治温补后，邪热鸱张，气机壅塞，痰热", "c": "主气郁"}, {"id": "pc:左+弦+硬", "n": "左·弦硬脉", "o": "左弦硬脉总以肝木失柔、气火亢盛为基本病机，然其具体所主又有层次之分。弦硬而长、左右皆弦硬者，多主肝火亢盛、气逆上冲，甚则血随气升、脑充血、痫风；弦硬而重按不实或兼数者，多主阴血亏虚、肝火内扰；左弦硬而右细软、弦长者，多主肝木犯胃、胃气上逆；弦硬异常而见风象者，", "c": "主肝火亢盛"}, {"id": "pc:左+弦+空", "n": "左·弦空脉", "o": "左弦空脉总属虚中夹实、形神两伤之候。其核心病机为正气内虚而邪气壅滞：空脉主气血亏虚、形神失养，为病之本；弦脉主邪气壅滞、络脉拘急，为病之标。从所收两段看，或见痰湿混阻、邪热内蕴（案30），或见暑湿未楚、肝脾不调（案18045），皆正虚与邪实并存。下属左弦濡空脉", "c": "主正虚邪滞"}, {"id": "pc:左+弦+紧", "n": "左·弦紧脉", "o": "左弦紧脉总以弦为肝郁气结、紧为邪实拘急为纲，所主病机可归为肝郁火盛、寒凝痛实、饮邪未净、疟湿余邪、温疫火郁、风中经络、瘀血内蓄七类。其核心在于邪壅气滞、肝胆经气不利：弦紧并见，或化火刑金、或寒凝作痛、或饮停湿阻、或疫火鸱张、或风客经络、或瘀血内停，皆因实邪阻滞", "c": "主肝郁火盛"}, {"id": "pc:左+弦+紧+迟", "n": "左·弦紧迟脉", "o": "左弦紧迟脉总起来主寒凝气滞、阳气虚衰、瘀血内停之证。其脉象以弦紧迟为主，紧迟应寒，弦主气滞疼痛；左弦紧突出寒邪引动厥气上逆、肝脉拘急，右沉细无力侧重阳气虚衰。各类病机相互关联：寒邪外受或苦寒伤阳为诱因，寒凝导致气滞，气滞则血瘀，瘀滞下焦，膀胱宣化失司；阴寒内盛", "c": "主寒"}, {"id": "pc:左+弦+细+大", "n": "左·弦细大脉", "o": "左·弦细大脉总起来主邪实正伤、肝脾不和及暑湿蕴结之证。弦为肝升太过或肝木失柔，细为阴血不足或脾虚不运，大为邪气壅盛或气血壅滞。三者并见，提示正虚邪实、土虚木贼或湿热交蒸。具体而言，弦细与大同见，可因肝木乘脾、气血壅滞而见下痢、腹瘕攻撑；亦可因暑湿内蕴、阴分受灼", "c": "主肝脾不和"}, {"id": "pc:左+弦+细+小", "n": "左·弦细小脉", "o": "左弦细小脉总起来主正虚邪郁、虚实夹杂之候。弦主肝郁气滞，细主阴血亏虚，小主不足，三者相合，提示阴亏于内、肝郁于中，或兼湿热痰滞互阻。从所收两段看，以细小弦示少阴本亏、湿热痰滞互阻中焦、肝气横逆；以细小隐弦示少阴虚、厥阴寒热、太阴独实之三阴疟邪。故其病机可归纳为", "c": "主阴亏"}, {"id": "pc:左+弦+细+弱", "n": "左·弦细弱脉", "o": "左弦细弱脉总属虚实夹杂之象，以虚为主，兼有邪滞。细弱主营阴亏虚、脾虚气弱，为脉道失充之根本；弦为肝失滋养、气火不潜，亦主邪滞内蕴。合而观之，此脉反映肝脾两脏升降失司：肝阴不足则气火不潜，脾虚气弱则转输窒滞，以致湿热停顿、邪滞中焦。各病机之间相互关联：营阴亏虚与", "c": "主营阴亏虚"}, {"id": "pc:左+弦+细+微", "n": "左·弦细微脉", "o": "左弦细微脉总起来主肝郁、阴血不足、气虚及气血两虚之病机。左脉弦为肝郁，微细为阴血不足；右脉空若谷为气虚。左右合参，反映肝阴亏虚而脾气大衰，气血两虚，虚损甚重。各类之间，肝郁为气机不畅之因，阴血不足与气虚为虚损之基，气血两虚为合参之果，共同体现虚实夹杂、以虚为主", "c": "主肝郁"}, {"id": "pc:左+弦+细+急+促", "n": "左·弦细急促脉", "o": "左弦细急促脉总起来主木火亢盛、阴亏火旺，兼夹湿浊内蕴及正虚邪陷。弦主木火，细促为阴亏火旺，反映肝木化火、阴液亏虚、气火内烁的核心病机；右脉濡滑提示湿浊内蕴，木火夹浊蒸腾，形成复杂病机。脉不耐重按，示正气已虚，邪热内陷，病势深重。诸类之间相互关联：阴亏为本，木火", "c": "主木火"}, {"id": "pc:左+弦+细+沉+小", "n": "左·弦细沉小脉", "o": "左弦细沉小脉总起来主里、虚、邪郁，并综合为营虚邪陷之候。沉主里，细主虚，小主不足，弦主邪郁，四者相合，说明正气内虚而邪气内陷，病位在里，闭而未出。原文以“营弱卫强，阳邪内陷”为据，又值经断后得病，故营虚为本，邪陷为标，形成虚实夹杂之局。诸类之间，里与虚言其病位", "c": "主里"}, {"id": "pc:左+弦+细+沉+紧", "n": "左·弦细沉紧脉", "o": "左弦细沉紧脉总属寒、气滞、虚、痰、痛交织之候。弦主气滞，紧主寒主痛，沉细主里虚，合而观之，其核心病机为寒邪内侵、气机郁滞、里气亏虚，兼夹痰浊内结。第一段以气滞兼寒痰为患，痛块并见；第二段为寒邪直伤肝经，筋脉拘急。两段均见弦细沉紧，提示病位在里，涉及肝胃，性质属", "c": "主寒凝"}, {"id": "pc:左+弦+细+沉", "n": "左·弦细沉脉", "o": "左弦细沉脉总属里、虚、气滞、湿阻、痛、虫扰交织之候。沉主里，细主虚，弦主气滞主痛，左脉候肝，故其核心病机为肝血不足、气机郁滞，兼夹湿浊内阻或虫扰作痛。从原文看，或为暑湿伤气、湿阻气机，或为虫扰气滞、肝血不足，均以里虚为本，气滞湿阻为标，痛与虫为常见兼症。诸类之", "c": "主里虚"}, {"id": "pc:左+弦+细+浮", "n": "左·弦细浮脉", "o": "左弦细浮脉总起来主邪郁少阳、正虚邪浮及三阳合病三类病机。弦细浮数首先反映少阳邪郁未解，并因浮甚而涉及太阳；数而重按无根则揭示正气已虚、邪热浮越的本质。三阳合病是综合脉症得出的整体判断，涵盖太阳、少阳、阳明同病。三类之间相互关联：少阳邪郁为病起之由，正虚邪浮为病", "c": "主邪郁少阳"}, {"id": "pc:左+弦+细+涩", "n": "左·弦细涩脉", "o": "左弦细涩脉总起来主肝郁、血虚、阴亏、脾虚及精血内枯等病机。弦主肝气郁逆，细主阴血不足，涩主气血滞涩，三者相合，反映肝木失涵、气血不畅、阴血亏虚之象。各类之间相互关联：肝郁气滞可致湿浊下注；血虚木旺则冲任血少、肝木乘脾；阴虚风动由营虚水亏、肝木失涵发展而来；肝郁", "c": "主肝郁气滞"}, {"id": "pc:左+弦+细+滑+大", "n": "左·弦细滑大脉", "o": "左·弦细滑大脉总起来主虚实夹杂之证，具体包括心肾阴血不足与痰涎壅盛两方面。左脉弦细反映心肾阴血亏虚，右脉滑大反映痰涎壅盛，两者并见提示正虚邪实。其病机核心为心肾两虚、痰涎沃胆，故临床可见神气模糊、夜不能寐、心忡、腰痛、舌苔黄垢等症。治疗需权衡虚实，先清后补。各", "c": "主虚"}, {"id": "pc:左+弦+细+滑+微", "n": "左·弦细滑微脉", "o": "左弦细滑微脉总起来主阴血不足、肝火偏动、湿痰阻胃、阴阳不交之病机。细为阴血亏虚，左关微弦为肝火内动，右关带滑为胃中湿痰。三者相合，湿痰借肝火鼓动而阻梗胃府，使心肾水火相交之路不通，遂成阴阳不交之不寐。四类病机中，阴血不足为本，肝火偏动为动因，湿痰阻胃为关键，阴", "c": "主阴血不足"}, {"id": "pc:左+弦+细+滑", "n": "左·弦细滑脉", "o": "左·弦细滑脉总起来主肝郁血少、痰湿内滞及血虚夹痰之病机。弦细为肝郁血少、情志怫郁之象，滑为痰湿内滞之征。其病机核心为情志所伤、肝脾失调，导致肝气郁结、血少不荣，脾运不健、痰湿内生；或血虚与痰浊并见，形成正虚邪实之候。各类之间相互关联：肝郁血少可致脾运不健而生痰", "c": "主肝郁血少"}, {"id": "pc:左+弦+细+濡", "n": "左·弦细濡脉", "o": "左弦细濡脉总起来主肝郁血少、湿郁化热、肝阳偏亢、阴血暗耗四类病机。弦细为肝郁血少之本脉，濡为湿困之象；湿郁日久化热，则见苔黄滑、颜红汗出；肝郁化火伤阴，则致肝阳偏亢、阴血暗耗。四者相互关联：肝郁血少为始动因素，气滞湿阻则湿郁化热，热耗阴血则阴血暗耗，阴不涵阳则", "c": "肝郁血少"}, {"id": "pc:左+弦+细+硬", "n": "左·弦细硬脉", "o": "左弦细硬脉总起来主肝血虚、津液短少，并常与右脉濡沉同见而构成气血两亏兼停饮之证。其脉弦为肝病之象，细为血少，硬为津液不濡，故核心病机在阴血亏虚、津液短涩。然单见左脉尚不足以概全，需合右脉及症候，方知兼有湿痰留饮、中焦气化不足。三者关系：肝血虚与津液短互为因果，", "c": "主肝血虚"}, {"id": "pc:左+弦+细", "n": "左·弦细脉", "o": "左弦细脉总以肝郁阴血不足为基本病机，弦主肝郁气滞、肝阳偏亢或寒饮内停，细主阴血亏虚、正气不足。其可兼见肝阳上亢、虚风内动、脾虚木乘、湿热内蕴、疟邪伏郁、寒饮寒积等不同转归。各证之间相互关联：肝郁日久化火伤阴，则阴血亏虚、肝阳上亢，甚则虚风内动；肝木乘脾则脾虚不", "c": "主肝郁气滞"}, {"id": "pc:左+弦+细+虚", "n": "左·弦细虚脉", "o": "左弦细虚脉总属阴血亏虚、虚阳上浮、气不归元之候。其脉弦细而虚，弦为肝脉，细为脉道不充，虚为无力，示阴血亏虚、肝失柔养；虚而兼弦，又为虚阳不潜。若兼右尺寸数，则数主热，为阴亏气不潜纳、虚阳上浮。三者相互关联：阴血亏虚为本，虚阳上浮为标，气不归元为果。阴亏于下，则", "c": "主阴血亏虚"}, {"id": "pc:左+弦+细+软", "n": "左·弦细软脉", "o": "左弦细软脉总属虚中夹实之候，以正虚为本，邪滞为标。细软主阴分不充、脾阳不振，为肾阴亏虚与脾阳虚弱并见；弦象主肝火不潜，为虚阳浮越；软中带数主湿滞化热，为湿邪郁久化热。四类病机相互关联：肾阴不足则肝木失养而肝火不潜，脾阳不振则运化迟钝而湿滞内生，湿郁又可化热。故", "c": "主阴分不充"}, {"id": "pc:左+弦+结", "n": "左·弦结脉", "o": "左弦结脉总起来主肝郁气结与肾阳衰微并见之证。左关弦结搏指，为厥阴肝气郁结、脉道不利；两尺微细欲绝，为少阴肾阳衰微、根本欲脱。二者并见，提示下元虚衰、肝气郁结，进而导致虚阳上浮，出现齿舌喉闭、腹痛吐蛔、肉𥆧筋惕等症。其病机核心在于肾阳虚衰为本，肝郁气结为标，虚阳", "c": "主肝郁气结"}, {"id": "pc:左+弦+缓", "n": "左·弦缓脉", "o": "左弦缓脉总起来主肝郁气滞、肝阳渐平、气阴两亏及脾运无权等病机。其核心在于肝木偏亢与脾土受克：左弦主肝郁气滞或肝阳上亢，缓为胃气尚和或肝阳渐平之兆；右缓（或濡滑）主脾运失健、湿浊内停。若弦象略缓，则为肝阳渐平、病势向愈之佳兆；若兼气阴两亏，则虚火挟湿浊上浮。各段", "c": "主肝郁气滞"}, {"id": "pc:左+弦+缓+迟", "n": "左·弦缓迟脉", "o": "左弦缓迟脉总起来主肝旺、湿滞、脾虚、血虚四类病机。左弦主肝气肝阳上升，右迟缓主湿滞未楚、脾胃运化无权，而‘营血本虚’为发病之本。四者相互关联：营血本虚，肝失濡养，肝阳上亢则脉弦；肝旺乘脾，脾运失健，湿滞内停，则右脉迟缓；湿滞又进一步困阻脾胃，加重脾虚。故其病机", "c": "主肝旺"}, {"id": "pe:左+弦", "n": "左·弦脉", "o": "左弦脉总以肝木为病变核心，弦为肝脉，左关候肝，故其总病机为肝气郁滞、肝木偏亢。然随兼脉与脉位不同，可演化为多类：弦而兼数、滑、大者，多主肝火、痰火、风阳；弦而兼弱、细、虚、涩者，多主虚中夹实、阴血亏虚；弦而兼濡、沉者，多主饮邪内停、脾虚湿困；弦而兼紧者，多主寒", "c": "主肝郁气滞"}, {"id": "pc:左+弦+芤", "n": "左·弦芤脉", "o": "左弦芤脉总主肝逆气亢、阴血亏虚、痰积气滞、阴阳不维之病机。弦为肝旺气逆，芤为失血伤阴，二者相合，多示血去络伤、气逆里热之候。其具体病机有四：一为失血伤阴，咯血盈盆，胃络抽疼；二为肝旺气逆，木旺中伤，脘闷里热；三为痰积气滞，肝胃同病，脘痛不止；四为阴阳不维，气血", "c": "主失血伤阴"}, {"id": "pc:左+弦+虚+涩", "n": "左·弦虚涩脉", "o": "左弦虚涩脉总属肝病日久、脾胃虚弱、营卫失和之候。其脉象由右脉虚弦带涩与左脉小弦劲数组成，虚弦带涩主脾虚肝郁、营卫不畅；小弦劲数主肝阳偏亢、内风扰动。四类病机相互关联：肝郁脾虚为病之本，肝阳偏亢为郁久化热之变，营卫失畅为气血不调之由，厥热往来为寒热错杂之象。总以", "c": "主肝郁脾虚"}, {"id": "pc:左+弦+虚+濡", "n": "左·弦虚濡脉", "o": "左·弦虚濡脉总属正虚邪恋、虚实夹杂之候。其脉象由虚弦与濡滑并见构成：虚弦主少阴阴阳两亏、气血不足，或虚火上浮；濡滑主脾胃不健、湿浊痰毒留恋。所主病机可归为三类：一为脾虚湿痰内蕴，运化失职；二为肝肾阴亏，水不涵木，精关不固；三为正虚邪恋，气阴两亏而湿毒未净。三者", "c": "主脾虚湿痰"}, {"id": "pc:左+弦+虚", "n": "左·弦虚脉", "o": "左弦虚脉总属虚实夹杂之象，以虚为本、以弦为标。虚主阴血不足、气血两亏或中气虚弱；弦主肝木失柔、气机郁滞或风阳内动。其病机核心在肝，旁及脾、肾、心、肺。肝阴血虚则脉道失养而弦急，脾土虚弱则木易乘之，故常见肝郁气滞、脾虚木乘、虚风内动、虚火浮越等类；若兼痰湿内蕴，", "c": "主肝郁气滞"}, {"id": "pc:左+弦+软", "n": "左·弦软脉", "o": "左弦软脉总以弦为肝木偏旺、气机郁逆，软为正气不足或湿邪内滞为纲。其主病机可归纳为肝郁气逆、阴血亏虚、脾虚湿困、痰热内蕴、湿热下注及少阳阳明合病数类。弦与软并见，反映虚实夹杂之象：弦主肝旺、气郁、木火，软主正虚、湿滞、阴伤。各类之间常相互兼夹，如肝郁侮土则脾虚湿", "c": "主肝郁气逆"}, {"id": "pc:左+弦+迟", "n": "左·弦迟脉", "o": "左弦迟脉总属虚实夹杂之候，以阳虚寒盛为核心，兼见肝郁气滞、水湿内停及气血不足。迟脉主阳衰、主寒，弦脉主肝、主气滞、主痛。阳虚则寒生，寒凝则气滞，气滞则水湿不化，水湿泛滥则肿满；阳虚日久，气血生化不足，营血亏虚，肝失濡养，弦脉愈显。各病机相互关联：阳虚寒盛为发病", "c": "主阳虚寒盛"}, {"id": "pc:左+弦+长+硬", "n": "左·弦长硬脉", "o": "左弦长硬脉总主肝经气火亢盛、气血上逆之病机。其脉弦主肝，硬主亢盛，长主气火有余，故核心为肝火亢盛，进而引动气血上冲，发为脑充血、厥证、头疼眩晕等。肝火亢盛可横逆犯胃，致胃气不降、冲气上冲，故右脉亦弦硬而长；气火久亢则耗伤阴分，形成阴亏与火旺并见；若湿热蕴结肝胆", "c": "主肝火亢盛"}, {"id": "pc:左+弦+长", "n": "左·弦长脉", "o": "左弦长脉总以肝木为根，弦主肝、长主气有余，故其核心病机为肝木亢盛、气机郁逆。由此衍生数端：肝火炽盛则弦长有力或兼数，上冲为头痛吐衄，下迫为痢血；冲脉隶于阳明，冲胃气逆则右脉弦长，见呕吐、呃逆、胸满；若与右洪长并见，则肝热与阳明实热交炽；若直上鱼际兼滑，则风痰火", "c": "主肝木亢盛"}, {"id": "pc:左+弱+促", "n": "左·弱促脉", "o": "左·弱促脉总起来主阳伤、中虚、湿聚、湿热四类病机，以虚为本、以实为标。左弱主中气不足、阳气虚馁，属虚；右促主里热未清、湿蕴化热，属实。原文见嗜酒中虚、谷少湿聚，又因辛散太过致阳伤，故脉见左弱右促。四类中，中虚与阳伤同源，皆属正气不足；湿聚与湿热则由中虚不运、酒", "c": "主阳伤"}, {"id": "pc:左+弱+坚", "n": "左·弱坚脉", "o": "左·弱坚脉总起来主阴虚火旺而中土亦弱之证。左脉坚，主木火偏旺、肝阳不潜，营液久耗，阴不制阳；右脉弱，主中气不足，脾胃虚弱。两者并见，形成阴虚火旺与中气不足并存的复杂病机。木火升腾，迫血上溢，故见失血嗽痰；中土虚弱，纳运失职，故少食尩羸。形瘦阴亏，古语‘瘦人虑虚", "c": "主木火偏旺"}, {"id": "pc:左+弱+短", "n": "左·弱短脉", "o": "左·弱短脉总起来主虚中夹实、本虚标实之候。其核心病机为心之气血不足（左寸短弱），但单纯虚象少见，多与痰、瘀、湿热等实邪兼夹。从所附段落看，短弱脉常与关弦大、右寸关滑大、两尺洪大数并见，形成上焦心虚、中焦痰浊、肝经瘀血、下焦湿热的复合病机。各类之间以“虚”为背景", "c": "主心虚"}, {"id": "pc:左+弱+缓", "n": "左·弱缓脉", "o": "左·弱缓脉总以虚为本，核心为气虚阳弱，兼见血虚、肾虚、脾虚湿停及痰湿中阻等标象。弱主气衰无力，缓主阳弱不运，故首主气虚阳弱；气虚日久则血亦不足，左脉小涩示血少，左脉滑示血热。脾虚运化失职则湿浊内停，或聚湿生痰，痰湿中阻则升降失司。尺弱又主肾虚精亏，腰膝失充。诸", "c": "主脾虚湿停"}, {"id": "pe:左+弱", "n": "左·弱脉", "o": "左弱脉总属虚候，以正气不足、气血虚衰为共同基础。其主病机可归为五类：一主气虚，弱而无力，推动不及；二主血虚，左脉候血，弱为营血不充；三主阳虚，弱而兼迟、兼濡，或尺部尤弱，示阳气衰微；四主正虚邪恋，弱与弦、数、滑、搏并见，虚中夹实；五主脾虚湿困，弱而濡缓，右关独", "c": "主气虚"}, {"id": "pc:左+弱+软", "n": "左·弱软脉", "o": "左·弱软脉总起来主虚，以气血不足、脾胃虚弱为核心，并可兼见正虚邪恋、气阴两伤等复杂病机。软弱脉本身为虚象，软主气虚，弱主虚损，左脉软弱偏于阴血亏虚，右脉软弱偏于脾胃气弱。在疟疾、温热病中，软弱脉与弦数有力并见，提示正虚邪恋；在久咳上损中，与细数并见，提示气阴两", "c": "主气血亏虚"}, {"id": "pc:左+弱+迟", "n": "左·弱迟脉", "o": "左·弱迟脉在抽样段落中仅作为丹溪翁传记行文所带的脉名出现，原文主旨在于叙述其弃举子业、专攻医学的经过，并非专门论述脉诊，故可依据的脉象资料有限。就脉名本身而言，弱为脉势软弱无力，迟为至数迟慢，二者相合，总以正气不足、阳气衰微为纲。其病机大致可归为两类：一为虚寒", "c": "主虚寒"}, {"id": "pc:左+微+弱+促", "n": "左·微弱促脉", "o": "左·微弱促脉总起来主阳伤津劫、里热湿蕴之复合病机。左脉弱为卫阳大伤、胃津被劫，属虚；右脉促为里热未清、湿蕴化热，属实。原文因伏暑冒凉发疟，误用辛温大汗，致汗多伤阳、劫津，而湿蕴未化、里热未清，故脉见左弱右促。四类病机中，阳伤与津劫同源于汗多，互为因果；里热与湿", "c": "主阳伤"}, {"id": "pc:左+微+弱", "n": "左·微弱脉", "o": "左·微弱脉总属虚候，以正气不足、气血虚衰为共同基础。其主病机可归为五类：一主气虚，尤以胸中大气下陷为典型，脉多微弱而迟；二主阳虚，尺脉尤甚则下焦虚寒，脾肾阳衰；三主肝虚，左脉或左关微弱不起，肝气肝血虚弱，疏泄失职，相火郁于经络；四主正虚邪恋，脉虽微弱而根柢尚存", "c": "主气虚"}, {"id": "pc:左+微+涩+小+短", "n": "左·微涩小短脉", "o": "左·微涩小短脉总属虚候，主五脏虚损、正气内衰。其脉象轻取或有浮滑，重按则微涩短小，反映虚阳浮于外而根本不足；微主气衰，涩主血少，小短主脉道不充，故总以气血不足、脏气虚衰为病机核心。所分三类中，“主脏虚”为总纲，涵盖五脏虚损；“主阳虚外浮”言其虚阳外越之机；“主", "c": "主脏虚"}, {"id": "pc:左+微+涩", "n": "左·微涩脉", "o": "左·微涩脉总属阳气衰少、血行不畅之候，主要反映阳虚、血虚与寒凝三类病机。微脉主阳气衰少、脉道不充，涩脉主血行涩滞、气血不畅。左脉候肝，左微涩多责之肝血不足；若兼右涩，则脾阳亦痹，中宫阳气欲寂。阳虚则温煦失职，故见色悴、畏寒、食减、溏泄；阳虚寒凝，气血涩滞，则发", "c": "主阳虚"}, {"id": "pe:左+微", "n": "左·微脉", "o": "左微脉总属虚候，以正气不足、阳气衰微为共同基础。微脉主阳虚、气虚，故见脉微气微、中宫阳寂、胃气将败；左脉候心肝肾，微则阴血亦亏，故主阴阳两虚、血虚、肝虚。虚则邪易干，故兼数实洪大者主正虚邪实，兼滑浮者主痰湿内阻。各类之间以虚为本：阳虚、气虚为始，久则阴阳两虚、", "c": "主阳虚"}, {"id": "pc:左+微+迟", "n": "左·微迟脉", "o": "左微迟脉总属气血不足、阳气虚弱之象。微为血虚阳弱，迟为阳弱血少，左脉候血，故以血虚为核心，兼见阳虚。血虚不能荣养头目则头痛，不能濡润肠腑则便秘，血虚生风则风动。诸类病机以血虚为本，阳虚为兼，风动、肠燥为标。治疗当补血为主，血充则风息、腑气自行，体现治本之意。两", "c": "主血虚"}, {"id": "pc:左+急+促+短", "n": "左·急促短脉", "o": "左脉中部短促而急，总属虚损危候。其核心病机为气损、阴精耗散与虚阳躁动、上脱。短脉主气损，因下痢不止，正气耗伤，脉道不充；促急主虚阳躁动，因阴液下夺，阴不敛阳，虚阳上浮；阴精耗散则脉道失养，虚阳无制，进而飞越上脱。四类病机相互关联：气损与阴精耗散为虚损之本，虚阳", "c": "主气损"}, {"id": "pe:左+急", "n": "左·急脉", "o": "左急脉总以肝木为病变核心，所主病机可归纳为肝实气逆、肝火风动、湿热郁蒸、虚中夹实及痰气急痛五类。急脉本身主气火亢盛或拘急之象，与弦、缓、数、滑、沉等脉相合，则病机各有侧重：沉急主肝气郁滞、疏泄失常；弦急主肝火冲逆、风动拘急；缓急主湿热郁蒸、升降失司；数急主阴液", "c": "主肝实气逆"}, {"id": "pc:左+散+乱", "n": "左·散乱脉", "o": "左散乱脉总属元气欲脱、邪盛正衰之危候。其脉散乱无绪，如解索状，为正气涣散、神气将绝之兆；两尺绝无神气，则根本已竭。若兼右寸关洪滑弹指，又见痰食壅盛、胃气上逆，形成正虚邪实之局。散乱非绝脉，及时温补固脱，脉转收敛，则虚而可挽。", "c": "主正气涣散"}, {"id": "pe:左+散", "n": "左·散脉", "o": "左散脉总属正气散越、收摄无权之象，其病机以虚为本，兼见火、风、痰、邪等标象。虚类包括心气虚、肾虚、胃虚及气散血竭，皆因正气亏虚不能敛摄，故脉见散越无神；阴火内风类由虚阳浮越、肝阳亢动，散越中兼弦数；痰气闭类因痰壅气闭，脉见沉伏或滑大，气通则脉起；少阳邪郁类为邪", "c": "主虚（气散不敛）"}, {"id": "pc:左+数+伏", "n": "左·数伏脉", "o": "左数伏脉（以右数左伏为特征）总属湿温重证，主湿遏热郁。其病机核心为湿浊壅遏、热不得透：右脉数反映热郁气分，内蒸不得外达；左脉伏反映湿遏营卫，邪阻不达。二者相合，形成湿温证中湿与热交结、闭阻气机之候。临床见寒热、胸闷、腹痛、齿焦、舌白腻而厚、不食不便等，皆湿浊壅", "c": "主热郁"}, {"id": "pc:左+数+促+坚", "n": "左·数促坚脉", "o": "左·数促坚脉总属水亏热升、虚火上炎之候。左脉候肝肾，坚为阴亏阳亢，数为热，促为热盛气急，三象合见，示肾水不足、龙相之火内炽上炎。水亏则木失滋荣，火升则灼伤胃阴，故原文见冬温咳嗽、秽浊上冲咽喉。其病机核心为‘水不制火’，虚热内迫，累及胃阴。三类病机相互关联：水亏", "c": "主水亏热升"}, {"id": "pc:左+数+促", "n": "左·数促脉", "o": "左·数促脉总属热盛与邪阻之候，核心病机为热邪鼓动血脉、气机壅遏。数主热炽，促为阳盛热结或气急，左脉候营，故热郁营分则脉促数，斑疹不透，虑其内闭神昏。其变有二：一为水亏火升，阴亏阳亢，虚火上炎，见冬温咳嗽、秽浊上冲；二为湿热痰浊交阻，滑数促并见，气机壅闭，虽见虚", "c": "主热盛"}, {"id": "pc:左+数+动", "n": "左·数动脉", "o": "左·数动脉总起来主阳动、阴亏、虚火三类病机，核心在“阳动”与“阴虚”。数主热，动主阳动不宁，左脉候肝，故首要主肝阳亢动化风，见寒热、心悸、神魂散越等；若尺不附骨，则主肾精肝血内夺、弱阴不恋阳，冲阳上逆，见失血、咳呕、汗泄；若兼右小濡弱，则示气阴不足，阳动而气弱", "c": "主阳动化风"}, {"id": "pc:左+数+和", "n": "左·数和脉", "o": "左·数和脉总起来主热势渐缓、气机升发与中焦气盛三类病机。数脉主热，但兼和缓，故热势渐缓而非亢盛；尺脉敛起上行，反映下焦气机有升发之象；右关大则示中焦气机偏盛。三者相互关联：邪热渐退，气机欲复，故下焦升发、中焦偏盛。整体为邪热渐退、气机欲复之候，病机以热势缓和、", "c": "主热势渐缓"}, {"id": "pc:左+数+坚+硬", "n": "左·数坚硬脉", "o": "左·数坚硬脉总起来主热、实及下焦火盛。脉数主热，坚硬主实，左尺候下焦，故左尺数而坚硬，反映下焦火热壅实之病机。原文见下痢肛门火热滞坠、小溲热痛、苔白质红，乃下焦火挟热上冲，肺胃之气欲降不能，彼此鼓激，致呃忒又盛。三类病机相互关联：热为根本，实为邪壅之性，下焦火", "c": "主热"}, {"id": "pc:左+数+坚", "n": "左·数坚脉", "o": "左·数坚脉总起来主热、实与阴亏，核心病机为‘水不制火’与‘阳亢气逆’。数主热，坚主实、主阴亏脉失柔润，左脉候肝肾，故其病机多围绕肝肾阴亏、虚热内炽，或肝阳亢盛、气升血上，或实邪（瘀血、痰积、热邪）壅盛，或下焦火热壅实，或寒凝阳伤、阴液亏虚。各类之间相互关联：阴", "c": "主阴虚火旺"}, {"id": "pc:左+数+大+坚", "n": "左·数大坚脉", "o": "左数大坚脉总起来主肝阳亢盛、气升血上及用力致伤。左脉属肝，数大为阳亢，坚为气结，三者相合，反映肝气劲急、阳亢气逆之病机。因用力致伤，气机逆乱，血随气升而失血，故脉见数大而坚。其病机核心为肝阳亢盛、气机升逆，进而导致血随气上。治疗以静坐安养平气，用养肝阴和胃阳方", "c": "主肝阳亢盛"}, {"id": "pc:左+数+大+小", "n": "左·数大小脉", "o": "左·数大小脉总以数、大、小为象，所主病机可归纳为热、气滞、血虚、虚损四类。数脉主热，为热邪内盛或气机急促化热之征；大脉主壅滞，左大示血分壅滞、右大示胃热壅盛，故见气滞；小脉主不足，左小为肝血不足、右小为气分不足，故主血虚与虚损。四类之间相互关联：热邪可灼伤阴血", "c": "主热"}, {"id": "pc:左+数+大+急", "n": "左·数大急脉", "o": "左·数大急脉总起来主本虚标实、多脏同病之候。其脉象由数、大、急、代、涩复合而成：涩为肺之本脉，示肺气本虚；代为气不相接，主脾胃不足；大为洪大而数，主心火刑肺；急为弦急，主肝木挟心火刑肺金。四类病机相互关联：脾胃不足为气不相接之源，心火与肝火合而上刑肺金，肺气本", "c": "主脾胃不足"}, {"id": "pc:左+数+大+洪+实", "n": "左·数大洪实脉", "o": "左脉数大洪实，总属阳热邪盛之脉，然其独见于左而右脉阳微，故非单纯实热，而是邪壅于左、阴阳逆乱之候。原文以'伏暑似疟'言其病，暑热内伏，邪正交争，故脉洪大数实；然右脉阳微，气分不足，左右悬殊，故断为阴阳逆乱。此脉所主，以暑热炽盛为核心，邪壅于左为病位，阴阳逆乱为", "c": "主暑热炽盛"}, {"id": "pc:左+数+大+洪+疾", "n": "左·数大洪疾脉", "o": "左·数大洪疾脉总属燥火亢盛之象。洪大数疾为燥热鼓脉、火性急迫所致，其病机核心为燥火加临。因所伤部位不同，脉象左右有异：右脉洪数主燥伤气分，左脉洪数主燥伤于血。三类病机以燥火为总纲，气分、血分热为具体分属，共同构成燥热痿软之脉的完整病机。", "c": "主燥火"}, {"id": "pc:左+数+大+洪", "n": "左·数大洪脉", "o": "左·数大洪脉总属阳热邪盛之脉，以热盛为核心病机。数主热，大洪主邪热鼓脉、气血沸涌，故凡热邪炽盛、暑温、燥火等阳热之病，皆可见此脉。具体而言，热盛于气分则右脉洪大而数；暑温初起，暑热内盛、热邪偏重肺胃，亦见洪大数脉；燥火亢盛，伤及气分或血分，则脉数大洪疾；若左脉", "c": "主热盛"}, {"id": "pc:左+数+大+浮+空", "n": "左·数大浮空脉", "o": "左数大浮空脉（原文见左弦急、右洪滑数）总起来主阴虚火旺、暑热伤津与痰热内蕴三类病机。其脉象左弦急为木火上浮，右洪滑数为暑热挟痰，三者相互交织：阴虚血亏为本，木火升浮为标；酷暑外烁，耗伤津液，更兼伏痰内蕴，形成虚实夹杂、痰热互结之候。故脉象既见弦急之肝火，又见洪", "c": "主阴虚火旺"}, {"id": "pc:左+数+大", "n": "左·数大脉", "o": "左·数大脉总以数主热、大主邪盛或虚浮为纲，所主病机以热盛为核心，旁及肝郁化火、阴虚火旺、痰热互结、积热内结及虚中夹实。数大见于左脉，左候肝心，故多示肝胆气火偏亢、热邪内陷血室或风热内炽；若见于右脉或两关，则偏于肠胃积热、阳明燥热。然数大非尽实热，水亏火炎、痨虫", "c": "主热盛"}, {"id": "pc:左+数+大+软", "n": "左·数大软脉", "o": "左·数大软脉总属虚热、气阴不足、瘀热互结及正虚邪实之候。数大为热，软为气阴不足，故脉象本身即示虚热内扰、气阴两伤；若兼弦紧，则瘀滞内阻，热与瘀搏，形成瘀热互结。原文所见身大热、便泄、气急神倦、恶露全无、腹膨鼻煽，正是气阴耗伤、虚阳外浮、瘀血内阻交织之危候。四类", "c": "主虚热"}, {"id": "pc:左+数+实", "n": "左·数实脉", "o": "左·数实脉总起来主热邪壅盛、结聚为患之证。数脉主热，实脉主壅主结，左脉候血，右脉候气，故其病机可归纳为三类：一为热壅血络，见于暑疡疹块；二为里热结聚，见于便闭下证；三为正虚邪实，见于左微右实并见之危候。三者皆以热实为核心，或兼外邪郁表，或兼腑气不通，或兼正气亏", "c": "主热壅血络"}, {"id": "pc:左+数+小+坚", "n": "左·数小坚脉", "o": "左·数小坚脉总起来主阴血不足、热郁下焦、气机坠滞之证。其脉象由小、数、坚三部分组成：小主阴血亏虚，数主有热，坚主脉道拘急、气滞络不和。三者相合，形成阴亏热结于下、气机坠滞的复合病机。原文指出“非纯虚之候”，强调此脉虽见阴血不足，但兼有热郁气滞之实，故所主病机以", "c": "主阴血不足"}, {"id": "pc:左+数+小+弱", "n": "左·数小弱脉", "o": "左数小弱脉总属虚损之候，以气血亏耗为本，虚热为标，兼夹脾虚湿郁。脉数而无力，非实热，乃阴血不足、虚火上炎；小弱散弱，为气血亏耗之象。三者相互关联：气血亏耗则脾虚失运，湿郁化热，虚热又耗阴血，形成恶性循环。临床见症复杂，如食后吐酸、结痰注胸、劳则头晕鼻衄、盗汗梦", "c": "主虚热"}, {"id": "pc:左+数+小+急", "n": "左·数小急脉", "o": "左·数小急脉总起来主正虚邪郁、有内陷之变。其脉数急为邪热内郁，小为正气不足，合而示正虚不能敌邪；右脉模糊又示气分正虚，不能鼓动邪气外达。故本脉所主病机以邪热内郁、正气不足为基础，进而可致正虚邪陷。三者相互关联：邪热内郁为病邪一面，正气不足为体质一面，正虚邪陷为", "c": "主邪热内郁"}, {"id": "pc:左+数+小", "n": "左·数小脉", "o": "左·数小脉总以阴血亏虚、虚热内动为基本病机，数主热（多为虚火），小主不足，合而示阴亏于内、虚热上炎。其具体所主，或为肝经热盛迫血妄行，或为正虚邪郁、邪热内陷，或为气血亏耗之虚损，或为痰热壅肺之肺痿，或为疟后正虚邪恋。诸类之间，以阴虚内热为核心，热可灼血、可炼痰", "c": "主阴虚内热"}, {"id": "pc:左+数+平", "n": "左·数平脉", "o": "左·数平脉总属热邪未清而正气渐复之候。其脉数而平和，数主热，平示热势不剧，故以余热未清为主；左尺有生发之气，又示肾气渐复，正能胜邪。然右脉缓涩带长，兼见脾虚湿滞之象，说明热病之后，脾胃运化未复，湿滞内停。三类病机相互关联：余热未清为病之本，肾气渐复为向愈之机，", "c": "主余热未清"}, {"id": "pc:左+数+弦+和", "n": "左·数弦和脉", "o": "左·数弦和脉总起来主肝郁化火、饮邪内停、脾虚湿胜及肺失宣降四类病机。其核心在于肝郁化火，弦为肝邪，数主郁热，左关弦数不和是肝郁化火之明征。肝郁则木失疏泄，影响肺金宣降，金郁则失清肃之令，故咳呕并作；木郁犯土，脾运失健，湿邪内胜，故右脉细濡涩而便溏。饮邪内停亦因", "c": "主肝郁化火"}, {"id": "pc:左+数+弦+坚", "n": "左·数弦坚脉", "o": "左数弦坚脉总起来主实邪壅盛，具体包括瘀血、痰积、热邪等胶结为患。弦为痛为积，数为热，坚劲搏指示实邪壅盛。本例患者壮年原有湿热痰积，又因跌伤致旧瘀未净，新血不循，瘀痰热互结，壅阻络脉，故见左胁痛手不可近、小腹痛，脉象弦数坚劲搏指。四类病机中，瘀血与痰积为病之本，", "c": "主瘀血"}, {"id": "pc:左+数+弦+大+浮", "n": "左·数弦大浮脉", "o": "左·数弦大浮脉总属肝气亢逆、气火郁勃之象，以弦为肝郁，数为热急，浮大为气火升浮，四者相合，主气火内郁、木旺克土。其病机核心在肝脾失调：肝气郁而化火，火性急迫则脉数大；木旺乘土，脾运受戕则食少肌削；然病久正伤，阳气衰微，寒来脉转沉微，故又见虚实错杂。三类病机相互", "c": "主气火郁勃"}, {"id": "pc:左+数+弦+大", "n": "左·数弦大脉", "o": "左·数弦大脉总以弦为肝郁、数为热盛、大为邪实或虚浮为纲。其主病机可归为五类：肝郁化火、热毒蕴结、痰热互结、阴虚火旺、虚中夹实。弦为气机郁滞之象，数主热，大主邪盛或虚阳外浮，三者相合，多示肝胆气火偏亢，或热毒痰火交结，或阴亏虚火内炽，或虚人受邪、本虚标实。各证之", "c": "主肝郁化火"}, {"id": "pc:左+数+弦+实", "n": "左·数弦实脉", "o": "左·数弦实脉总起来主热郁少阳、胆胃不和之证。数脉主热，右实主阳明热结，左弦主少阳枢机不利，三者相合，反映热邪内郁、枢机不利、胆胃气逆的病机。原文服养阴药得效未愈，说明热郁未解，需苦寒清热、和解枢机，用小柴胡汤治阳维之会。各类之间相互关联：热为根本，少阳枢机不利", "c": "主热"}, {"id": "pc:左+数+弦+小+动", "n": "左·数弦小动脉", "o": "左数弦小动脉总属阴虚阳亢、内风旋动之候。其脉小为阴血不足，弦动为风阳上扰，数为热象，四类病机相互关联：阴虚为本，热为标，热耗津液则阴更虚；阴虚不制阳，则阳亢化风，风阳升于上而见头晕、目泪、舌刺，下焦无气而见足痿。故本脉以虚为本，以热、风、阳亢为标，标本相兼，总", "c": "主阴虚"}, {"id": "pc:左+数+弦+小", "n": "左·数弦小脉", "o": "左数弦小脉总属阴虚阳亢、内风旋动之候，以虚为本，以热、风、阳亢为标。其脉小为阴血不足，弦为肝郁气逆，数为热象，四类病机相互关联：阴虚不制阳则阳亢化风，风阳上扰清窍；肝郁久则化火，火旺伤阴则阴更虚；虚火内扰，炼液为痰，痰火互结。故本脉所主，涵盖阴虚火旺、肝郁化火", "c": "主阴虚火旺"}, {"id": "pc:左+数+弦+弱", "n": "左·数弦弱脉", "o": "左关弦数弱脉（以左关弦数、右弱为特征）总属虚实夹杂之候。弦数主邪郁湿热，弱主正虚，合而观之，其病机核心为土虚木乘、湿热内扰。左关弦数反映肝木亢盛、湿热郁结，右弱反映脾土受困、中气不足。三者相互关联：脾虚则肝木易乘，木乘又加重脾虚；湿热内蕴则进一步耗伤中气。故本", "c": "土虚木乘"}, {"id": "pc:左+数+弦+微", "n": "左·数弦微脉", "o": "左数弦微脉总属肝木为病，以肝郁化热、阴亏阳动为核心。弦主肝郁，数主热，微为阴血不足。肝郁日久化热，热迫气逆血瘀；肝阴亏虚，阳无所制而浮动，升多降少，阴不和阳。由此上灼肺金，津亏肺燥；横犯脾胃，脾虚湿蕴，升降失调。诸类病机相互关联：肝郁化热为始动，阴亏阳动为体质", "c": "主阴亏阳动"}, {"id": "pc:左+数+弦+急", "n": "左·数弦急脉", "o": "左·数弦急脉总起来主肝火亢盛及其变生诸证。数主火，弦急为肝火亢盛、气逆之势，故核心病机为肝火内炽。肝火上下交攻：上犯肺金则咳嗽、鼻洪，为木火刑金；下泄肾气则梦遗，为火扰精室；久延火盛耗阴，则势必成劳。四类中，主肝火为根本，木火刑金与下泄肾气为肝火上下分传之具体", "c": "主肝火"}, {"id": "pc:左+数+弦+沉", "n": "左·数弦沉脉", "o": "左·数弦沉脉总以沉、弦、数三象合见为特征，沉主里、弦主郁、数主热，故其总病机为郁热内结于里，涉及肝、胃、肠等脏腑。具体而言，或为肝气郁结化火，或为积气积热壅滞，或痰火相搏，或瘀血内停，或阴伤火升。各类之间相互关联：肝郁化火可横逆犯胃，灼津成痰，形成痰火；郁火久", "c": "主积热内结"}, {"id": "pc:左+数+弦+沉+虚", "n": "左·数弦沉虚脉", "o": "左·数弦沉虚脉总属虚实夹杂之象，以虚为本，以郁热为标。沉虚主正气内亏，弦主气机郁滞，数主热象内生。三者相合，常见于内伤杂病中阴虚气郁、虚热内扰之证。原文虽为丹溪翁传记行文所带，脉名非主旨，然就脉论脉，其病机可归为虚损、热、气郁三类：虚损为根本，气郁为枢机，热为", "c": "主虚损"}, {"id": "pc:左+数+弦+洪+涩", "n": "左·数弦洪涩脉", "o": "左数弦洪涩脉总属木火亢盛、阴伤血滞、肝阳上僭与正气溃败交织之候。弦洪数主肝木化火，火盛则上炎而僭越；涩主阴血耗伤、郁滞不行；上溢示肝阳升逆无制；右软滑大无神则胃气败绝。诸类相互关联：木火亢盛为病之始，火盛灼阴则阴伤血滞，阴不制阳则肝阳上僭，久病及中则胃气溃败。", "c": "主木火亢盛"}, {"id": "pc:左+数+弦+洪", "n": "左·数弦洪脉", "o": "左数弦洪脉总属肝木化火、热盛阴伤之候。弦为肝脉，洪数为火热，故其核心病机为肝火亢盛；火盛则灼阴，故兼阴伤；木火刑金，灼津为痰，则痰热内蕴；火盛阳升，肝阳上僭，则见气冲、面赤、不眠；若邪热内陷，郁结不达，则脉见洪数中带紧涩。诸类以肝火亢盛为始，火盛灼阴则阴伤，阴", "c": "主热盛阴伤"}, {"id": "pc:左+数+弦+浮", "n": "左·数弦浮脉", "o": "左浮弦数脉总属肝胆风火痰热为患，然有虚实之别。浮主阳浮或风邪，弦主肝木或疟邪，数主火盛或郁热。实者多因外感风热、少阳郁火、痰火内扰、肝阳化火，或疟痢交作，脉多浮弦数有力，症见寒热、眩晕、头痛、胸胁疼、痰多、下迫后重等；虚者则因阴亏液耗、虚阳外浮、风阳内煽，脉虽", "c": "主风热外袭"}, {"id": "pc:左+数+弦+滑+濡", "n": "左·数弦滑濡脉", "o": "左·数弦滑濡脉总起来主余温留恋、痰湿中阻及厥阳升腾。左脉弦数主少阳余温，右脉濡滑主痰湿内阻，弦数又示厥阳升腾。三者相互关联：余温未清，引动肝阳，兼夹痰湿阻于中焦，形成虚实夹杂之候。故治疗需清泄伏温，兼顾痰湿，避免滋阴留邪或燥湿伤阴。", "c": "主余温"}, {"id": "pc:左+数+弦+滑+紧", "n": "左·数弦滑紧脉", "o": "左数弦滑紧脉，总起来主温疫火郁之候。其脉象数、滑、弦、紧并见，反映邪火炽盛与郁结并存：滑数主温疫之邪化火，充斥内外，蔓延三焦，故见发热、丹赤、痧点、舌红；弦紧主邪势鸱张，郁于少阳，故见咽痛连颈肿。火郁相合，邪势正盛，有内窜心包、致神昏发痉之虞。三类病机中，温疫", "c": "主温疫化火"}, {"id": "pc:左+数+弦+滑", "n": "左·数弦滑脉", "o": "左·数弦滑脉总起来主痰火、湿热积滞、肝阳化风、温疫火郁及余温痰湿等病机。其核心在于弦、数、滑三象合见：弦主气滞、饮邪与肝阳，数主热与火盛，滑主痰湿与食积。诸类之间相互关联，常以火热为枢，或灼液成痰，或夹湿滞，或引动肝风，形成痰火、湿热、风火等复合病机。病位多涉", "c": "主痰火"}, {"id": "pc:左+数+弦+濡", "n": "左·数弦濡脉", "o": "左·数弦濡脉总起来主湿热痰浊、伏温化热、肝阳化风及阴血亏虚四类病机。左弦数主肝郁化热，右濡数主脾湿蕴热，合而示湿热痰浊内蕴，为诸证之基础。湿热久留，易引动伏温，化热外发，故见温毒、寒热等症。热盛伤阴，肝木失养，则肝阳化风，内风煽动；而阴血亏虚又使肝阳偏亢，风动", "c": "主湿热痰浊"}, {"id": "pc:左+数+弦+紧", "n": "左·数弦紧脉", "o": "左·数弦紧脉总起来主湿热痰浊、瘀热内阻及痛证。其脉象数、弦、紧并见，数主热，弦紧主痛、主寒湿痰浊、主瘀滞。两类病机常相兼为患：湿热内犯肝经，挟痰浊上升，则见少腹作痛、呕吐、苔浊腻；瘀血内阻，兼热交结，则见恶露全无、腹膨鼻煽。痛证则由气血壅滞而发，弦紧为痛之特征", "c": "主湿热痰浊"}, {"id": "pc:左+数+弦+细+促", "n": "左·数弦细促脉", "o": "左数弦细促脉总起来主阴液枯槁、邪热内遏与正气虚散三类病机，三者相互交织，形成危候。其核心在于温涩太过致伏邪无路可出，邪遏化热、湿遏化燥，进而伤阴劫津、化源告竭；阴液枯竭则脉细，虚热内扰则数促，气机紧张则弦；同时正气亦匮，右部虚散，故脉象示厥脱之变即在目前。三类", "c": "主阴液枯槁"}, {"id": "pc:左+数+弦+细+小", "n": "左·数弦细小脉", "o": "左关尺数弦细小脉，总起来主肝郁化火、阴亏火旺之病机。弦主肝郁，细小数主阴亏火旺，三者相合，提示肝气郁结、郁久化火、阴液亏耗的病理格局。其病机类别包括肝郁、阴亏火旺、火郁筋脉，三者相互关联：肝郁为始动因素，郁久化火则火旺，火旺伤阴则阴亏，阴亏又加重火旺，形成恶性", "c": "主肝郁"}, {"id": "pc:左+数+弦+细+滑", "n": "左·数弦细滑脉", "o": "左·数弦细滑脉总属肝阳化风、痰热内蕴、阴虚火旺之候。弦为肝阳易动，滑为烁液成痰，数为火盛，细为阴伤，四象合见，示本虚标实、风火痰交炽之病机。其核心在于肝阳偏亢，化火生风，灼液成痰，痰火窜扰经络，故见头晕、麻木、挛曲、肿疼、瘰磊等症；火盛伤阴，则便坚溲赤、口干舌", "c": "主肝阳化风"}, {"id": "pc:左+数+弦+细+濡", "n": "左·数弦细濡脉", "o": "左·数弦细濡脉总起来主肝郁化火、阴血亏虚、脾虚有热、痰湿内蕴。左脉弦细，弦主肝郁，细主阴伤，因情怀抑郁，五志化火，木火刑金，血液暗耗；右脉濡数，濡主脾虚湿困，数主有热，为脾虚有热、痰湿内蕴。四类病机相互关联：肝郁化火是始动因素，火盛伤阴致阴血亏虚；木火刑金，肺", "c": "主肝郁化火"}, {"id": "pc:左+数+弦+细", "n": "左·数弦细脉", "o": "左·数弦细脉总以阴虚火旺为基本病机，细主阴伤，数主热，弦主肝郁或风动。其可兼见血热妄行、肝郁化火、风动痰盛、虚损兼邪、湿热留恋等不同转归。各证之间相互关联：阴虚为本，火旺为标，火盛则动血、生风、灼津为痰；若兼外邪或湿浊，则成虚实夹杂之候。脉象虽以左关为主，但需", "c": "主阴虚火旺"}, {"id": "pc:左+数+弦+细+虚", "n": "左·数弦细虚脉", "o": "左数弦细虚脉总属阴阳两虚、虚阳上浮之候。其脉左弦细为肝肾阴虚、阳不潜藏，右虚数为脾肺气虚、虚阳浮越，合之则见阴阳两损、下焦阴不上承、上焦虚阳不降。根本在于肝肾根蒂不固，冲脉震动，诸脉俱逆，故见眩晕、盗汗、咳嗽喘促等症。此脉所主非实热、非单纯肝病，乃虚阳上冒、气", "c": "主阴虚阳浮"}, {"id": "pc:左+数+弦+缓+和", "n": "左·数弦缓和脉", "o": "左·数弦缓和脉总起来主真阴不足、肝木偏亢及邪减向愈三类病机。其核心在于真阴亏虚，脉道不充则左脉细小无神；阴不涵木则肝气偏亢，关部带弦，进而肝木犯土。同时，右脉弦数转为缓和，提示邪气渐退、正气来复，属佳兆。三类病机相互关联：真阴不足为根本，肝木偏亢为继发，邪减向", "c": "主真阴不足"}, {"id": "pc:左+数+弦+缓", "n": "左·数弦缓脉", "o": "左·数弦缓脉总起来主肝木偏亢、真阴不足、脾土受克及邪减向愈等病机。其核心在于肝阴不足、虚阳偏亢，故左脉数而弦；阴不涵木，肝木乘脾，则右脉弦缓，脾运不健；若邪气渐退，脉转缓和，则为向愈佳兆。各段所论，或侧重肝火渐平，或侧重真阴亏虚，或侧重木旺克土，或侧重内风日炽", "c": "主肝火渐平"}, {"id": "pc:左+数+弦", "n": "左·数弦脉", "o": "左·数弦脉总以弦为肝郁、数为热盛，左脉候肝胆，故其核心病机为肝经郁热化火。然随兼脉与脉位不同，可演化为多类：弦数有力而症见寒热、口苦者，主少阳郁热；弦数兼滑大、痰涎壅盛者，主痰火风动；弦数而阴亏液耗、舌红无津者，主阴虚火旺；弦数迫血妄行、咳血便血者，主热郁血分", "c": "主肝火郁热"}, {"id": "pc:左+数+弦+虚+和", "n": "左·数弦虚和脉", "o": "左数弦虚和脉总起来主肝脾不和、湿滞血少、虚数内伤及湿邪内困。其脉象以弦为主，兼见涩、虚、数、和等变化。弦为肝木之象，主肝脾不和，为病之本；涩主湿滞血少，数主热与湿郁，虚主不足，均为病之标。高年积劳，中气亏虚，阴血不足，是内伤之因；湿邪困于内，消磨失职，是外邪之", "c": "主肝脾不和"}, {"id": "pc:左+数+弦+虚+小", "n": "左·数弦虚小脉", "o": "左·数弦虚小脉总属阴虚劳怯之候，其病机核心为阴液亏虚、虚火内扰。脉数而弦，为火旺阴伤；虚小不劲，为阴亏阳不亢；软数虚弦，为虚火内扰、肺肾阴伤；弦大以数，为心肝火旺而阴不制。四类病机相互关联：阴虚为本，火旺为标，肺肾阴伤与心肝火旺皆由阴不制阳所致，虚劳失血则是阴", "c": "主阴虚火旺"}, {"id": "pc:左+数+弦+虚", "n": "左·数弦虚脉", "o": "左数弦虚脉总属虚实夹杂、本虚标实之候。其核心病机为阴血亏虚、虚火内扰，以虚、弦、数三象为纲：虚主营络内伤、阴液不足；弦主肝失所养、气机郁滞；数主虚火内升、热郁肝胆。由此可衍化为三类主要病机：一为阴虚火旺，阴亏为本、火旺为标，见于劳怯失血诸案；二为肝郁化火，肝气", "c": "主营络内伤"}, {"id": "pc:左+数+弦+虚+软", "n": "左·数弦虚软脉", "o": "左·数弦虚软脉总属阴虚劳怯之候。其脉象以虚、弦、软、数并见为特征：虚软示阴液亏耗，弦数示虚火内扰。所主病机可归为三类：一为阴虚火旺，二为肺肾阴伤，三为心肝火旺。三者相互关联：阴亏为本，火旺为标；肺肾阴伤则金水不能相生，水不涵木则肝火偏亢，心火亦失所制，故左寸关", "c": "主阴虚火旺"}, {"id": "pc:左+数+弦+软", "n": "左·数弦软脉", "o": "左·数弦软脉总属虚中夹实、本虚标热之候。其脉象以弦、数、软并见为特征：弦主肝郁，数主火、主热，软主阴伤、正虚。所主病机可归为四类：虚火内扰、阴液耗伤、肝郁化火、余热未清。四者相互关联：阴亏为本，火旺为标；肝郁化火则灼阴，阴伤又生虚火；热病后余邪未净，亦耗阴液。", "c": "主虚火"}, {"id": "pc:左+数+弦+长", "n": "左·数弦长脉", "o": "左·数弦长脉总起来主气郁、邪实有余、热盛、血滞及痰凝，核心病机为恚怒伤肝，肝气郁结化火，气火有余，进而气滞血瘀、痰凝阻络。弦主气郁，长主有余，数主热，涩主血滞，诸脉相合，揭示气郁为本，郁热为标，痰瘀为变。病位在肝，涉及肺胃，因肝气犯肺，金不及木，反侮肺金，气凝", "c": "主气郁"}, {"id": "pc:左+数+弱+散", "n": "左·数弱散脉", "o": "左数弱散脉总属虚损之候，以气血亏耗为本，虚热为标，兼脾虚湿郁。脉数无力非实热，乃阴血不足、虚火上炎；小弱散弱为气血亏耗，脉道不充。三者相互关联：气血亏耗则脾运不健，湿郁化热；阴血不足则虚热内生。故脉象数弱散并见，主虚损、虚热及脾虚湿郁，治当补益气血、健脾化湿、", "c": "主气血亏耗"}, {"id": "pc:左+数+微", "n": "左·数微脉", "o": "左·数微脉总属虚实夹杂之候，以热郁与阴血不足为核心。数主热，微主虚，合而常见郁热内蕴、虚火浮动、正虚邪陷及肝脾失调四类病机。郁热多因气机不畅、化火内蕴；虚火多由阴血亏虚、阳无所制；正虚邪陷见于里虚邪陷、胃气衰败之危候；肝脾失调则由肝郁乘脾、升降失司所致。四类之", "c": "主郁热"}, {"id": "pc:左+数+急", "n": "左·数急脉", "o": "左·数急脉总起来主虚性病机，以阴液亏虚、虚阳上浮为核心。数急虽似热象，但结合左脉沉缓或迟软，实为阴分受困、阴血不足，虚阳不能潜藏而浮越。其下属数弦急脉主肝火亢盛，数小急脉主正虚邪郁，数大急脉主本虚标实，均体现数急脉在虚损基础上兼夹他邪或他脏同病。各类之间以正虚", "c": "主虚阳上浮"}, {"id": "pc:左+数+沉+动", "n": "左·数沉动脉", "o": "左·数沉动脉总起来主里热未清、阴血略伤，兼正气尚能抗邪之候。数脉主热，沉脉主里，故数沉并见反映热郁于里；然沉中带有生动之机，说明正气未衰，尚能抗邪，形成正邪交争之势。右寸关数有泛发之气，提示热势尚有外扬之象；尺涩则示阴血不足或湿滞，因热邪内郁易耗阴血，故阴血略", "c": "主里热"}, {"id": "pc:左+数+沉+小", "n": "左·数沉小脉", "o": "左·数沉小脉总起来主阴血不足、虚热内扰，兼见气虚与疟邪未净。其脉沉小为阴血亏虚，数为虚热内动；右脉浮濡无力近数，为脾肺气虚；脾部弦洪，为疟邪未净。诸类之间，以阴虚内热为核心，气虚为兼，疟邪为标，正虚邪恋为转归。年逾六十形弱，劳心劳力，疟后见此脉，示虚实夹杂：阴", "c": "主阴虚内热"}, {"id": "pc:左+数+沉+涩", "n": "左·数沉涩脉", "o": "左数沉涩脉总起来主血瘀成癥、瘀久化热、气滞血瘀之病机。左脉数主血中有热，右脉沉涩主气滞血瘀，两脉合参，揭示瘀血内结、郁而化热、气机阻滞之复杂病机。原文以经水久不止夹紫黑血块、脐下块坚如铁、胸腹胃脘皆痛、玉户肿、手足冷为主症，断为血瘕症，非单纯虚寒崩漏。三类病机", "c": "主血瘀癥瘕"}, {"id": "pc:左+数+沉+紧", "n": "左·数沉紧脉", "o": "左·数沉紧脉总属虚实夹杂、寒热错杂之候。其左脉沉细欲无，主清阳下陷、正气虚馁；右脉沉紧而数，主瘀血受寒、热郁于内。三者相互关联：产后用力过度致清阳下陷为本虚，瘀血受寒为标实，误服热药更添热郁，形成虚、瘀、寒、热交织之局。脉象上，左脉细弱示正虚，右脉紧数示邪实，", "c": "主清阳下陷"}, {"id": "pc:左+数+沉", "n": "左·数沉脉", "o": "左数沉脉总以沉、数二象合见为特征，沉主里、主积、主郁，数主热，故其总病机为热郁于里。具体而言，可因热邪内结而主里热，因气机郁滞而主郁热，因积滞内伏而主积热，因热入血分而主血分热，因湿热下注而主下焦湿热，因痰火相搏而主痰火，因阴亏火旺而主阴虚火旺。各类之间相互关", "c": "主里热"}, {"id": "pc:左+数+洪+平", "n": "左·数洪平脉", "o": "左脉洪数，总属火热亢盛、毒邪蕴结、气机壅盛之象。火热内盛则脉洪数，毒邪外泄则脓水淋漓，气盛上下咸宜则脉趋平和。三者相互关联：热毒壅盛可致气机不利，气盛又助火热升腾。原文以洪数较平为佳兆，反映毒泄火降、气机调畅则脉和，但仍宜增不宜减，示余邪未清、气火未全平。故洪", "c": "主火热"}, {"id": "pc:左+数+洪", "n": "左·数洪脉", "o": "左·数洪脉总以热盛为核心，洪为火盛气浮，数为热急，故所主病机多归火热一类。然火热有虚实表里之辨：实者如温热外感、燥热、湿热、酒热、痧毒，洪数有力，随浮沉左右分表里气血脏腑；虚者如内伤胃虚、肾经虚热、阴伤火旺，洪数而失和缓，或与细脉并见，为虚阳浮越、真阴耗竭之象", "c": "主热盛"}, {"id": "pc:左+数+洪+芤", "n": "左·数洪芤脉", "o": "左·数洪芤脉总起来主虚中夹实、阴阳两伤而络瘀未净之病机。其脉坚搏，主肝络瘀滞、血不归经，为实邪内阻之象；洪数而芤，主阴伤阳浮，为阴液亏耗、阳气外浮之征。三者相互关联：因络瘀日久，血不归经，由阴经损及阳气，终致阴阳两伤；而瘀滞仍未净，故脉象既见坚搏之实，又见洪数", "c": "主络瘀血滞"}, {"id": "pc:左+数+浮+小+濡", "n": "左·数浮小濡脉", "o": "左·数浮小濡脉总属虚候，以气阴两伤为核心，兼涉虚热、脾肺气虚及暑湿未清。浮小为气虚阳浮，濡为阴伤湿滞，数为虚热内扰；右部尤不足，则脾肺之气亏甚。诸类相互关联：疟久截药伤正，致脾肺气虚，气不化津则阴伤，阴虚阳浮则生虚热，暑湿余邪留恋不去，故脉象浮小濡数并见。总言", "c": "主气阴两伤"}, {"id": "pc:左+数+浮+弱", "n": "左·数浮弱脉", "o": "左数浮弱脉总属虚中夹实、上盛下虚之候。浮弱数为上焦气浮兼热，下部弱数为下元虚而热扰，故其病机以虚热上浮为核心，兼见气血不充与虚风痰扰。三者相互关联：疮后阴血耗伤为本，虚热上浮为标，虚风挟痰上扰清窍、阻遏经络为变，故见耳鸣不闻、偏废脚弱、冲气动等症。脉象浮弱数并", "c": "主虚热上浮"}, {"id": "pc:左+数+浮", "n": "左·数浮脉", "o": "左·数浮脉总以浮主表、数主热为纲，所主病机以热邪为核心，涉及表热、湿热、风热、肝热风动、气分热、血分热及痰热等类。浮数并见，多示邪热在表或热邪有外达之势；若兼弦滑，则痰热风火交阻；若兼虚细，则热中夹虚。各类之间常相互转化：表热不解可入气分、血分，湿热可蕴蒸发黄", "c": "主表热"}, {"id": "pc:左+数+浮+芤", "n": "左·数浮芤脉", "o": "左数浮芤脉总主阴血亏虚、阴火动而气逆上升，兼夹风邪与痰患。芤为血虚之本，浮为气升或风邪，数为阴火或虚热。案8以阴血暴失、营络大空为核心，阴不维阳，阴火潜动，气随火升，兼痰喘肾亏；案8978以血虚招风为主，风袭经络，痰随气动。诸类中，血虚是基础，阴火动、气逆、风", "c": "主血虚"}, {"id": "pc:左+数+浮+虚+洪", "n": "左·数浮虚洪脉", "o": "左脉浮洪虚豁而数，总属正虚邪恋、虚实夹杂之候。浮洪为风热外扬，虚豁散数为气阴两伤，数主虚火内动。其病机核心为劳后入房感风，正气已虚而邪热内扰，脾虚气弱，痰湿内停，虚火挟痰，久疟成母。诸类之间相互关联：风热外袭为诱因，气阴两伤为根本，脾虚痰湿为病理产物，疟母积块", "c": "主风热"}, {"id": "pc:左+数+涩", "n": "左·数涩脉", "o": "左·数涩脉总起来主营血不足、营热未清与肝火不静三类病机。涩为营血不充，数为营热未清，左脉见涩数，说明营阴亏虚而热邪未净；若兼右脉弦数，则肝火不静，热灼营阴。三者相互关联：营血不足则肝失濡养，肝火易动；肝火内扰又耗营阴，营热难清。故其病机核心为营阴亏虚、热留营分", "c": "主营血不充"}, {"id": "pc:左+数+滑+促", "n": "左·数滑促脉", "o": "左·数滑促脉总属实证、热证，以湿热、痰浊、实热壅闭气机为核心病机。滑主痰湿，数主热，促主气机壅遏，三者相合，提示邪热与痰湿交阻，充斥三焦，气机不得宣通。原文虽见雀啄、解索等虚象，然结合面黄头汗、胸痞拒按、便溺涩臭等症，断为湿热误补、漫无出路所致，非真虚也。故本", "c": "主湿热壅闭"}, {"id": "pc:左+数+滑+和", "n": "左·数滑和脉", "o": "左·数滑和脉总起来主痰热、肝火、阴亏与燥热四类病机，核心为热与痰，兼夹阴虚。右脉滑数较和，主肺胃痰热渐化；左脉弦数不靖，主肝胆火旺、阴液亏耗。数脉主热，滑脉主痰，弦脉主肝，和缓示邪有退势。四类关系密切：阴液素亏则肝火易炽，肝火灼津则生痰燥，痰热留恋肺胃则输化失", "c": "主肝火"}, {"id": "pc:左+数+滑+大+小+濡", "n": "左·数滑大小濡脉", "o": "左·数滑大小濡脉总起来主热、痰、邪实与津亏。数主热，滑主痰，大主邪实，右部搏指为肺胃热炽；左部小濡为津亏之象。诸脉象并见，反映痰热蕴结、邪实壅盛而兼津液耗伤之病机。热与痰搏，火与痰激，故痰鸣有声；热灼津亏，故渴饮频作。邪实与津亏并存，提示病机复杂，实中夹虚。各", "c": "主热"}, {"id": "pc:左+数+滑+小", "n": "左·数滑小脉", "o": "左·数滑小脉总起来主阴血亏虚、热盛兼暑湿痰滞之证。其脉象由细数、小滑兼数复合而成，细为血少，数为热，小滑为暑湿痰滞。患者生育多而血液素亏，复感时令暑气，故见阴亏、热盛、暑湿内蕴，甚则虚风内动。各类病机相互关联：血虚与热盛并存，暑湿痰滞为标，虚风内动为阴亏热盛之", "c": "主血虚"}, {"id": "pc:左+数+滑+浮", "n": "左·数滑浮脉", "o": "左·数滑浮脉总属风热痰湿为患，以热为核心，兼挟风、痰、湿。浮主表主风，滑主痰主湿，数主热，三者相合，提示风热挟痰在表在络，热势方张，痰热内扰，有动风痉厥之虞；同时湿热下注，可见经水淋漓、大便黏滞。三类病机相互关联：风热挟痰为病之始，热盛动风为病之变，湿热下注为", "c": "主风热挟痰"}, {"id": "pc:左+数+滑", "n": "左·数滑脉", "o": "左·数滑脉总以痰热内蕴为基本病机，滑主痰、数主热，左脉应心肝、尺应肾，故其病机涉及多个脏腑。常见者：痰热壅肺，见咳嗽痰壅、喉音不清；肝郁化火，见气聚为瘕、脉弦疾坚搏；阴虚阳浮，见真水不足、火动风生；暑热壅肺，见耳聋口苦、胸次迷闷；燥火伤血，见喘逆、耗津灼液；肠", "c": "主痰热"}, {"id": "pc:左+数+滑+软", "n": "左·数滑软脉", "o": "左·数滑软脉总起来主正虚邪实、痰热内扰之证。滑主痰，数主热，软主虚，三象并见，提示痰热有余而正气已馁。具体而言，滑数反映痰热内盛，症见舌灰腻、口干咽燥、耳聋糊语、咳痰便闭；软则反映脏阴亏乏或营卫不足，故见寒热缠绵、正邪交争。两类病机相互交织：痰热灼阴则阴亏愈甚", "c": "主痰热"}, {"id": "pc:左+数+濡", "n": "左·数濡脉", "o": "左·数濡脉总起来主湿热蕴蒸、温邪化热、痰热内扰、郁火痰积、风邪湿热及阴伤湿滞六类病机。其核心为“濡主湿，数主热”，故湿热合邪贯穿诸证。湿热蕴蒸气分，漫布三焦，则见身热、白疹、溲赤；温邪夹湿，郁而化热，则见寒热、便溏、心烦；湿热久留，炼液成痰，痰热内扰心肝，则神", "c": "主湿热"}, {"id": "pc:左+数+疾", "n": "左·数疾脉", "o": "左·数疾脉总属热盛阳亢之象。数主热，疾主阳亢，左脉候心肝，故其病机重心在心肝火旺。具体而言，或为心火独炽，离火内亢而坎水不制；或为心肝阳亢，肝火戕胃、心火烁金；或火亢水亏，阴不制阳，虚阳外浮；甚则兼夹湿温，形成火亢水亏兼湿浊弥漫之复杂局面。诸类之间以火亢为共同", "c": "主心肝阳亢"}, {"id": "pc:左+数+短", "n": "左·数短脉", "o": "左·数短脉总属虚实夹杂之候，以气损为本，热扰为标。短脉主气机不畅或气损，数脉主热或虚热。其一为热邪内陷少阴、少阳，气机壅滞，阴分受伤，属实证或虚实夹杂；其二为去血过多，气无所附，气血两亏，虚阳浮动，属虚证。两类均见短数，但一偏热陷气滞，一偏气损虚热，实为同一脉", "c": "主热陷"}, {"id": "pc:左+数+紧", "n": "左·数紧脉", "o": "左数紧脉总起来主外感邪气，以寒邪外感、阳邪在表为核心病机。其脉象数、紧并见，数主热、主正邪交争，紧主寒、主收引，二者相合，反映外邪束表、阳气被郁而奋起抗邪之象。原文明确指出“脉见紧数，此寒邪外感也”，并强调数紧之脉左右皆然，非独左脉，驳斥了左大主风邪、右大主饮", "c": "主寒邪外感"}, {"id": "pc:左+数+细+大", "n": "左·数细大脉", "o": "左·数细大脉总起来主虚实夹杂之热证，以少阴阴亏为本、阳明络热为标。数脉主热，细脉主阴血不足，大脉主邪盛有余；左细示少阴不足，右大示阳明有余，故其病机核心为阴液亏虚、邪热内扰，形成虚与实并存的格局。原文「牙龈不肿而痛，脉数左细右大，阳明有余，少阴不足」明确将数、", "c": "主热"}, {"id": "pc:左+数+细+小", "n": "左·数细小脉", "o": "左·数细小脉总起来主阴亏虚火之病机。其核心在“细”“小”“数”三象相合：细主阴亏，小主虚，数主火，但此火非实火，而是阴血不足所生之虚火。原文以左脉细小兼数，断为心肝虚火上炎，法宜养阴以降火，说明本脉所主以心肝阴血亏虚为本、虚火上炎为标。三类病机相互关联：阴亏是", "c": "主阴亏"}, {"id": "pc:左+数+细+微+弱", "n": "左·数细微弱脉", "o": "左脉细弦而数、右脉细数微弱，总属虚实夹杂之候。细数主阴伤热炽，弦主郁，弱主气衰，故其病机以火热劫烁肺胃、阴津大伤为核心，兼有气机郁滞与正气虚弱。火热内炽则阴津受灼，气郁不达则邪热郁结，气衰则正虚无力托邪，三者相互影响，形成热炽、阴伤、气郁、气衰并见的复杂局面。", "c": "主阴伤热炽"}, {"id": "pc:左+数+细+沉+促", "n": "左·数细沉促脉", "o": "左·数细沉促脉总起来主热、虚、郁伏与气乱四类病机。数主热，细主虚，沉主郁伏，促与断续主气乱，四者常相兼为患。此脉见于风温初起即谵妄自汗，本为阳热内盛，然脉不浮洪而反沉细数促，说明热邪郁伏于里，阴血已伤，正气渐溃。原文更见左脉细乱、右脉断续，口开目闭、唇板舌焦、", "c": "主热"}, {"id": "pc:左+数+细+沉", "n": "左·数细沉脉", "o": "左·数细沉脉总起来主阴血亏耗、虚热内扰、精虚劳伤及胃阴败肝火亢等病机。沉细为阴血不足、脉道不充之象，数为虚热内扰之征，二者相合，多属虚损劳伤之候。原文以左右分属，左脉细数主肝肾精虚，右脉细数主肺脾液少；以数之有无判精亏程度，细而未数精亏未竭，细而兼数阴精已竭。", "c": "主阴血亏耗"}, {"id": "pc:左+数+细+滑+大", "n": "左·数细滑大脉", "o": "左·数细滑大脉总属虚实夹杂之象，以阴液亏虚、邪火内炽为本，兼夹痰热壅盛，终致正虚邪恋。细数主阴亏火旺，滑大主痰热邪盛，二者并见，说明虚与实同时存在。原文“气阴略立定，邪火又复上炎”“水不济火”点明阴亏是基础，邪火是动因；而“滑大为痰热壅盛”则示实邪壅阻。正虚不", "c": "主阴液亏虚"}, {"id": "pc:左+数+细", "n": "左·数细脉", "o": "左·数细脉总以阴虚火旺为基本病机，细主阴伤，数主热，左脉候肝肾，故多主肝肾阴亏、虚火内动。其可兼见血虚火旺、精血内损、风动阳亢、热盛阴伤、痰热内蕴及虚实夹杂等不同转归。各证之间相互关联：阴虚为本，火旺为标，火盛则动血、生风、灼津为痰；若兼外邪或湿浊，则成虚实夹", "c": "主阴虚火旺"}, {"id": "pc:左+数+细+虚+弱", "n": "左·数细虚弱脉", "o": "左·数细虚弱脉总属肾阴亏虚、虚火妄动之象。其脉细数虚弱，直接反映左肾真阴不足，阴虚不能制火，故虚火内生；若两尺微弱，则阴阳俱虚。所主病机以肾虚为基础，进而导致阴虚火旺，甚则成虚劳之证。三者相互关联：肾虚为根本，阴虚火旺为病机演变，虚劳为久病转归。原文强调‘左尺", "c": "主阴虚火旺"}, {"id": "pc:左+数+细+软", "n": "左·数细软脉", "o": "左·数细软脉总主虚火、阴伤、燥热及脾肾虚损。细软为阴血不足之基，数为虚火燥热之象，二者相合，虚火充斥三焦：上扰则耳鸣咽烂，下迫则梦泄，中及则脾胃失运。其病机核心为阴分素亏，虚火内生，或兼燥邪薄肺，源流两涸。诸类相互关联，虚火、燥热为标，阴伤、脾肾虚为本，总属本", "c": "主虚火"}, {"id": "pc:左+数+缓", "n": "左·数缓脉", "o": "左·数缓脉总起来主湿热内蕴、湿痹经络及湿浊蒙蔽清窍之病机。数脉主热郁，缓脉主湿滞，左脉候血分，右脉候气分，合而观之，为湿邪痹阻、郁而化热之象。其病机演变有三：一为湿热内蕴，见舌白发热、自汗、溺痛；二为湿痹经络，见皮肤骨节掣痛；三为湿浊上蒙清窍，虑神昏厥逆。三者", "c": "主湿热"}, {"id": "pe:左+数", "n": "左·数脉", "o": "左数脉总以热为核心，然热有虚实表里之分。实热者，脉数有力，多主心肝火盛、热陷血分、痰热互结、湿热郁蒸及风火相煽；虚热者，脉数无力或兼细虚，主阴血亏耗、虚火内动。郁热者，热因气郁而内伏，脉沉郁而数。诸类之间常相互转化：实热久羁可伤阴致虚，虚火内灼可生痰动风，郁热", "c": "主热盛"}, {"id": "pc:左+数+虚+小+散", "n": "左·数虚小散脉", "o": "左·数虚小散脉总起来主正气亏虚、邪热内扰之候。其脉象由数、虚、小、散复合而成：数主热，虚、小、散主虚，浮洪主风。原文一案因劳后入房感风，正气已虚而邪热内扰，症见疟作、自汗、寒少热多、头眩耳鸣、四肢懒倦、手足麻、便溏、疟母、梦遗、呕吐多痰，涉及虚、热、风、疟、痰", "c": "主虚"}, {"id": "pc:左+数+虚", "n": "左·数虚脉", "o": "左·数虚脉总以虚为本、以数为标，主正虚而兼热之病机。虚为正气不足，或阴血亏耗，或气分虚弱；数为有热，然此热多非实火，乃虚热、虚火或湿热郁蒸所致。其具体所主，可因左脉分部而异：左寸数虚主肺痿虚热，左关虚数主肝虚风动、虚火上炎，左脉虚数又主血虚、阴亏、正虚邪恋及湿", "c": "主虚热"}, {"id": "pc:左+数+软", "n": "左·数软脉", "o": "左·数软脉总属虚中夹实、本虚标热之候。数主热，软主虚，二者相合，提示正虚与邪热并存。其病机可归为四类：虚热内扰、营卫不和、气阴两伤、湿热内郁。四者相互关联：气阴亏虚为本，虚热、湿热为标；营卫不和常因正虚余热未清；湿热内郁又易耗伤气阴。临证需权衡虚实主次，兼顾标", "c": "主营卫不和"}, {"id": "pc:左+数+长", "n": "左·数长脉", "o": "左·数长脉总起来主热郁气壅、痰凝血结之证，核心病机为肝胆郁热、气血壅结。数脉主血分有热，长脉主气分有余，二者相合，揭示气郁为本、郁热为标、痰瘀为变的病机层次。气机郁滞日久化火，郁热循少阳阳明之络上攻颈项，灼津为痰，痰气交阻则结瘿；热迫血溢则时衄。故其主病以热、", "c": "主热"}, {"id": "pc:左+沉+伏", "n": "左·沉伏脉", "o": "左沉伏脉总起来主气机郁闭、痰浊格拒、表邪内遏及瘀血内停。其基本病机为邪阻气机，脉道不畅，故脉沉伏不起。各段中，沉伏脉多与滑大、弦滑等脉并见，提示痰、气、表邪等实邪为患。如左沉伏而右滑大，为痰格中焦、气闭下焦；初按沉伏为表邪郁闭；则从反面指出真瘀血当见沉伏。可见", "c": "主气闭"}, {"id": "pc:左+沉+坚", "n": "左·沉坚脉", "o": "左沉坚脉总起来主下焦阴伤、气机固结之证。其脉沉主病位在下焦，坚主脉道拘急，反映阴液亏虚、脉络失养而气机固结。原文久痢肛坠，温剂不受，正是阴伤不司收纳，而非寒湿内结。阴伤与气机固结相互影响：阴亏则脉道不柔而坚，气结则沉取更显。治疗当以甘酸柔缓养阴和络，不可再投温", "c": "主阴伤"}, {"id": "pc:左+沉+实", "n": "左·沉实脉", "o": "左沉实脉总属里实热结之候。沉为在里，实为邪盛，合而主里实壅滞。原文以右脉沉实主肠胃实热，两尺沉牢主蓄血，左尺沉数主膀胱结热，诸脉皆不离沉实牢数，说明伤寒腹胀由实热内结、气血壅滞而成。三类病机中，里实热为本，气滞胀满为果，蓄血坚积为实邪深入血分之变。沉实脉既主无", "c": "主里实热"}, {"id": "pc:左+沉+小+紧", "n": "左·沉小紧脉", "o": "左寸沉小紧脉总属心脉失常，以虚寒为本，兼见热盛、气泄、心痛等变。沉小为心气不足、阳气衰微之象，紧为寒凝气滞之征。原文以夏脉钩论心，来盛去盛为太过病在外，主热盛；来衰去衰为不足病在内，主虚寒与气泄。沉小紧脉合而观之，既反映心阳不足、寒邪内侵之虚寒本质，又可因寒凝", "c": "主热盛"}, {"id": "pc:左+沉+小", "n": "左·沉小脉", "o": "左·沉小脉总以里虚不足为基本病机，沉主里、小主虚，左脉候心肝肾三阴，故首主阴精亏虚。在此基础上，因兼脉不同而分化：兼紧则虚寒阳衰，兼弦则肝郁气逆，兼数则虚热内扰，兼濡涩则痰郁气滞，见于邪陷危候则正虚邪陷。诸类之间以正虚为本，或虚寒、或虚热、或气逆、或痰郁、或邪", "c": "主阴精亏虚"}, {"id": "pc:左+沉+弱+缓", "n": "左·沉弱缓脉", "o": "左·沉弱缓脉总属虚证，以气虚阳弱为核心，兼见血虚不充，进而气血俱虚、中气不固。沉弱缓三象并见，沉为阳气不升，弱为气衰无力，缓为阳弱不运，故首主气虚阳弱；右脉浮软无力、心肺脉浮虚按不应指，则示血虚不充；气血相互为用，气虚日久则血亦不足，血虚则气失所附，故见气血俱", "c": "主气虚阳弱"}, {"id": "pc:左+沉+弱", "n": "左·沉弱脉", "o": "左沉弱脉总属虚证，以气虚阳弱为核心，兼见血虚不充，进而气血俱虚、中气不固。沉为阳气不升，弱为气衰无力，故首主气虚阳弱；弱而无力，亦主阴血亏虚；气血相互为用，虚则俱虚，故常见气血两虚。若沉弱兼弦细、滑等象，则示本虚标实，或为痰瘀互结，或为中虚木乘、肝气犯胃；沉弱", "c": "主气血两虚"}, {"id": "pc:左+沉+微+缓", "n": "左·沉微缓脉", "o": "左关沉微缓脉总属虚寒，尤以下焦虚寒、奇经失固为核心。沉主里，微主阳虚，缓主寒，合而示下元虚衰、阳气不足。由此可致冲任督带不能固摄，发为经漏淋带不止；下焦阴寒内盛，虚阳不得潜藏，故右部虚浮，形成上热下寒、阳升于上而阴亏于下之局。同时，脉微缓亦反映胃气孱惫，食减味", "c": "主下焦虚寒"}, {"id": "pc:左+沉+微", "n": "左·沉微脉", "o": "左沉微脉总属阳气衰微、阴寒内盛之候。沉主里，微主阳虚，合而示阳气虚衰不能鼓动气血，故脉沉而微。其病机核心为阳衰，由此可衍生数端：一则阳衰不能温煦，寒战由内而生；二则下元虚寒，奇经失固，冲任督带不能固摄，发为经漏淋带；三则阳虚不能运化水湿，湿浊内阻，又困遏阳气，", "c": "主阳衰寒战"}, {"id": "pc:左+沉+急", "n": "左·沉急脉", "o": "左沉急脉总属肝木为病，以肝气逆、肝实太过为核心病机。沉主里、主气郁，急主拘急劲急，二者相合，反映肝气郁滞于内、疏泄失常、气机逆乱。其具体表现或为肝气上逆之头痛眼眩，或为肝实太过之胁下引痛、喜怒，或为气机郁滞之胁支满、小便难，甚则急甚而情志失常、恶言。诸类皆从肝", "c": "主肝气逆"}, {"id": "pc:左+沉+散", "n": "左·沉散脉", "o": "左沉散脉总起来主气血失调、脏腑失和之病机。其脉沉而散，沉则病在里、在脏，散则气不敛、血不充，故非表证所主。从原文看，脉之大小滑涩辨血气多少，数迟辨寒热表里，长弦、小、下坚上虚、滑微浮、大而坚分属五脏，说明沉散脉须合兼象定位定性：兼小涩者主血少气虚，兼滑大者主血", "c": "主气血偏颇"}, {"id": "pc:左+沉+浮+小", "n": "左·沉浮小脉", "o": "左·沉浮小脉总主风邪在表、脾肺气滞水停与正气已伤。左浮为风邪袭表，右沉为脾肺气滞水停，脉小示正气不足。三者相互关联：风邪外袭，肺失宣降，传之于脾，致气水交阻；正虚则邪易内陷，水湿不化，故见胀满、咳喘、溲短肢冷。此脉以浮沉并见、小脉为特征，反映表里同病、虚实夹杂", "c": "主风邪在表"}, {"id": "pc:左+沉+浮", "n": "左·沉浮脉", "o": "左·沉浮脉总起来主表里阴阳之辨，具体涉及风水、肝胃郁热及阴阳气血失调。浮脉主表，风邪袭表，水湿泛溢，故主风水；兼弦硬滑实，则主肝胃郁热。左右浮沉又分阴阳气血，用于辨胎孕男女。下属左·沉浮小脉则总主风邪在表、脾肺气滞水停与正气已伤，浮为风邪，沉为水停，小为正虚，", "c": "主风水"}, {"id": "pc:左+沉+涩+小", "n": "左·沉涩小脉", "o": "左脉沉涩小，总属虚实夹杂之候，以肝肾阴亏为本，气机不利为标，并见肝木犯胃之兼象。沉小主阴精亏虚，涩主阴血不足、气行不畅，弦则示肝旺制中。三者相合，反映阴亏于下、气滞于中、肝逆于上的病机格局。因阴亏而肝失柔养，肝旺则犯胃，胃气失和则气机更滞，故治疗既忌香燥破气，", "c": "主肝肾阴亏"}, {"id": "pc:左+沉+涩", "n": "左·沉涩脉", "o": "左沉涩脉总起来主瘀血内停、气滞血瘀、阴血亏虚、痰饮内伏、湿热瘀结及肝胆郁结等病机。沉为病在里，涩为血行不畅，左脉候血分，故其核心为血行瘀滞、气血不畅。瘀血内停为最基本病机，可兼气滞而呈气滞血瘀；瘀久化热则与湿热互结；阴血亏虚则脉道不充而涩；痰饮内伏、阳气不布亦", "c": "主瘀血内停"}, {"id": "pc:左+沉+濡", "n": "左·沉濡脉", "o": "左沉濡脉总属虚实夹杂之候，以虚、湿、滞为三大病机。沉为里位，濡为虚湿，故其主病以脏气内虚为本，尤以脾肾气虚阳弱为要；虚则水湿不化，气机郁滞，故兼主湿滞、气痹；湿聚成痰，痰阻脉道，则又主痰涎壅盛；脾虚湿滞，积滞内结，则主积；气虚阳弱，大气下陷，则主气陷。各类之间", "c": "主虚"}, {"id": "pc:左+沉+紧", "n": "左·沉紧脉", "o": "左沉紧脉总属里寒实证，以寒邪内凝、气血滞涩为核心病机。沉主里，紧主寒主痛，左脉候血候肝，故其病位多在厥阴肝经及下焦血分。所主病机包括寒凝、里实、水停、虚寒及寒热错杂五类：寒凝为基本病机，寒邪内束，气血不通；里实强调寒邪内伏，疼痛由生；水停则因寒水不化，泛溢为肿", "c": "主寒凝"}, {"id": "pc:左+沉+缓", "n": "左·沉缓脉", "o": "左沉缓脉总属里虚湿滞、寒痰内阻、阳虚湿滞、阴分受困及中气已馁等病机。沉主里，缓主湿或寒，合而示里虚有湿或寒，气机不畅。各段中，或兼寸大示虚阳外浮，或兼舌淡白示寒痰阻胃，或兼右滑示浊阴内盛，或兼数急示虚阳上浮，或兼无力示中气虚弱。其核心为里虚，湿、寒、痰、浊阴为", "c": "主里虚湿滞"}, {"id": "pe:左+沉", "n": "左·沉脉", "o": "左沉脉总以“沉主里”为纲，左候阳气、阴血与血分，故所主病机围绕里证展开。其一为里虚气陷，沉而无力，阳气不升；其二为郁滞，气机郁结，脉沉不畅；其三为水饮痰湿，饮浊内停，阳气不达；其四为血瘀，左脉候血，沉主瘀结；其五为阴血亏虚，沉细而涩，脉道不充；其六为内寒，沉迟", "c": "主里虚气陷"}, {"id": "pc:左+沉+迟", "n": "左·沉迟脉", "o": "左沉迟脉总属里虚寒证，核心病机为阳虚阴盛、寒凝气滞。沉主在里，迟主寒，脉沉迟反映阳气不能鼓动脉气外达，血行迟缓，故主阳虚寒凝。据原文，其具体可表现为三类：一是全身阳气虚衰、寒凝脉络，如督脉冷、疟母；二是分部位之脏腑虚寒，左关尺候肝肾虚寒，右三部候脾肺虚寒；三是", "c": "主阳虚寒凝"}, {"id": "pc:左+沉+长", "n": "左·沉长脉", "o": "左沉长脉总起来主瘀热在里，具体包括气分热盛与血分热瘀两个方面。右长主气分热盛，左沉主血分瘀滞，二者并见，说明热邪由气分内陷血分，与血相结，形成瘀热在里之证。瘀热内结下焦血分，上扰神明，则可出现神气忽清忽乱、蓄血如狂等危候。因此，本脉所主病机以瘀热在里为核心，气", "c": "主瘀热在里"}, {"id": "pc:左+洪+实", "n": "左·洪实脉", "o": "左·洪实脉总属实证、热证，以实热壅盛为核心病机。洪为热盛，实为邪结，故其脉主热盛、阳明腑实、热盛迫血、热盛气壅、肝热酒毒及伏气化热等。各类之间以实热为本，或热结阳明，或热迫血行，或热壅气机，或肝热酒毒交炽，或伏气化热外发，皆由热邪内炽、正气未衰所致。若兼气滞，", "c": "主热盛"}, {"id": "pc:左+洪+涩", "n": "左·洪涩脉", "o": "左寸洪涩脉总起来主寒热错杂、气血壅滞、寒湿阻络之病机。洪为热象，涩为寒湿凝滞，迟数无定反映寒热交替搏结。原文因好饮冷酒，酒性热燥而冷饮犯寒湿，寒热相搏，遂致腿疼筋缩、寸步不能行。脉象乍洪乍涩、迟数不定，正反映寒热错杂、气血壅滞之病机。三类病机相互关联：寒热相搏", "c": "主寒热错杂"}, {"id": "pc:左+洪+紧", "n": "左·洪紧脉", "o": "左洪紧脉总起来主火盛、邪结与痰厥。洪为火盛，紧为邪结，左脉候肝，故知肝火炽盛；疔毒生于左臂，外科失治致毒火内攻，热痰上壅，填塞胸臆，昏不知人，成痰厥之证。脉洪紧应其肿疼属实火，故用蓬砂涌吐痰涎，继以清火解毒、羚羊角清肝。三类病机相互关联：火盛为病之本，邪结为火", "c": "主火盛"}, {"id": "pc:左+洪+缓", "n": "左·洪缓脉", "o": "左·洪缓脉总起来主气虚、虚阳外浮及气血不足。洪缓无力非实热之洪，乃脾胃气虚、虚阳外越之象；左脉缓小而弱，为气血不足之征。患者形肥色淡紫，冬月感寒，前医发散伤阳，又用寒凉降下，致身热自汗、胸膈痞闷、便泻食少，右脉洪缓无力，左脉缓小而弱，皆气虚阳陷之候。洪缓无力与", "c": "主气虚"}, {"id": "pe:左+洪", "n": "左·洪脉", "o": "左洪脉总属阳热亢盛之象，主实证、热证，但须辨虚实。洪而有力，多主实热炽盛，可因部位不同而分脏腑气血：左洪主血分热盛，右洪主气分热盛，见于温病、阳明热盛、肝火、肺火等。洪而无力或洪数失和缓，则主虚火，如阴亏火旺、虚阳浮越、气血虚而热壅。洪兼滑主痰热，洪兼数主热盛", "c": "主热盛"}, {"id": "pc:左+洪+长+坚+硬", "n": "左·洪长坚硬脉", "o": "左·洪长坚硬脉总起来主阳热亢盛之证。其脉洪大搏指、七至，为热邪亢极之候，非虚寒可比。所主病机以热盛为核心，具体表现为春温阳症、三焦热炽。原文虽见房事后腹痛水泻肠鸣，似阴症，但面赤唇燥、舌苔黄厚、烦躁口渴、脉洪数有力，实为阳症，误投理中则呕逆烦躁加剧，反证其热。", "c": "主热盛"}, {"id": "pc:左+洪+长", "n": "左·洪长脉", "o": "左·洪长脉总起来主热盛邪实，尤其以阳明热盛、肝胆火旺及酒热内蕴为核心。洪长为热盛之脉，左部候肝胆，右部候脾胃，故左洪长多主肝火挟气血上冲，右洪长多主酒热或阳明热盛。四段中，或单见左洪长而主肝火冲脑，或右洪长而主酒热交炽，或左右皆洪长而主阳明热盛兼阴伤，或右洪长", "c": "主肝火冲脑"}, {"id": "pc:左+浮+促", "n": "左·浮促脉", "o": "左浮促脉在本案中总主上焦气逆、胆府内伤。浮为气浮于上，促为急促不宁，左关独见而余部无恙，故病位在肝胆，病机为酒吐后上焦反复、气逆致胆府倒置。其类别一为气逆上焦，二为内伤胆府，二者实为一体：气逆是病机之因，胆府倒置是病位之果。此脉不主外感实热，亦不主虚寒，而专示", "c": "主气逆上焦"}, {"id": "pc:左+浮+动", "n": "左·浮动脉", "o": "左浮动脉总主阳气浮越、肝风内动之病机。其脉动跃如浮，多因血虚阴亏，阳失所附，化风上扰，故见头眩、颧红、面热、心中热冲等症。具体可分四类：血虚阳浮者，因血去络伤，阳气上蒸；肝阳上亢者，气火升腾，迫血妄行；气阴两虚者，脉浮而濡，精神不支；虚阳外越者，两尺无根，数逾", "c": "主血虚阳浮"}, {"id": "pc:左+浮+小", "n": "左·浮小脉", "o": "左·浮小脉总属虚候，以气血两虚为核心，兼见阳气外脱、脾虚失运、血虚失荣等变。浮为阳气外浮不敛，小为脉道细少，无力为正气不足，故其主病机以虚为主。段右脉浮小无力、左脉沉弱无力，疟止食进后便闭，示气血两虚、肠失濡润；段左脉浮微似有似无、右脉浮小按之不足，灸后气泄、", "c": "主气血两虚"}, {"id": "pc:左+浮+小+芤", "n": "左·浮小芤脉", "o": "左浮小芤脉总属虚候，以血虚为核心，兼见气亏。浮为阳浮不敛，小为脉道细少，芤为中空失血，三者合参，主阴血亏虚、脉道不充。原文见于新产之后，与右脉虚大无力并见，明示气血两亏；血少不能上荣，则清窍失养而头痛。故其病机以血虚为主，气亏为伴，清窍失养为果，三者相互关联，", "c": "主血虚"}, {"id": "pc:左+浮+弱", "n": "左·浮弱脉", "o": "左浮弱脉总属正气不足、虚多实少之候。浮为阳气外浮或邪在表，弱为气血内虚，故其病机以虚为主，或虚中夹表。具体而言，浮弱而热恶寒者，主阳气虚，治宜补气；浮弱而发热疼痛者，主邪在表，治宜疏散；左脉浮弱小于右而热者，主血虚偏甚，用药当重血药。三类之间，阳气虚与血虚同属", "c": "主阳气虚"}, {"id": "pc:左+浮+微", "n": "左·浮微脉", "o": "左·浮微脉总起来主气虚痰阻、阳气外脱与湿热发黄三类病机。其脉象浮微，浮为阳气外浮或邪气在表，微为气血不足或阳气衰微。第一类因气虚痰湿内阻，营卫不利，脉见左寸微浮，属虚实夹杂；第二类因灸后气泄、脾阳衰败，阳气外脱，脉浮微似有似无，属虚证危候；第三类因肝胆湿热蕴结", "c": "主气虚痰阻"}, {"id": "pc:左+浮+散", "n": "左·浮散脉", "o": "左浮散脉总属气机浮越、脏气失守之象。其脉浮散无神，主要反映三类病机：一为心气虚浮不敛，神不守舍；二为虚阳外浮，真阳无根；三为脏气失守，气逆上浮。三者相互关联，虚为根本，气逆为变动，色脉相失为诊察要点。原文以“有诸内者形诸外”为纲，强调脉象随脏气而变，浮散脉多提", "c": "主心气虚"}, {"id": "pc:左+浮+洪", "n": "左·浮洪脉", "o": "左浮洪脉总属阳盛邪实之候，但具体病机有痰热、风火、湿热兼风、心火、水亏火旺等不同。浮为阳为表，洪为热盛，左脉候血候肝，故多与血分、肝经、心肾相关。痰热与风火常相兼为患，壅于经络则肢废痫作；湿热兼风则营卫不和、风水相搏；心火亢盛则自汗；水亏火旺则见小便余沥、便结", "c": "主痰热"}, {"id": "pc:左+浮+涩+短", "n": "左·浮涩短脉", "o": "左浮涩短脉总属气血失和、脏气不调之候。浮为气浮于外，涩为血行不畅，短为气机不伸，三者相合，提示病位偏表而内有气血郁滞，脏气应内守而反外浮。原文虽以色脉相参为纲，但浮涩短脉本身即反映脉与脏气变动不符，故其病机可归为气滞血瘀、脏气不和及色脉相逆三类。三者相互关联：", "c": "主气滞血瘀"}, {"id": "pc:左+浮+涩", "n": "左·浮涩脉", "o": "左浮涩脉总起来主肺肾两虚、气血失和及肝郁脾困等病机。浮脉主气浮于外，涩脉主血行不畅，二者相合，提示气机失调、血行郁滞，脏气应内守而反外浮。具体而言，浮涩并见可反映肺气虚浮不降、肾阴不足之肺肾两虚；亦可提示气血失和、气滞血瘀、脏气不和；若兼弦象，则示肝郁乘脾、气", "c": "主肺肾两虚"}, {"id": "pc:左+浮+濡", "n": "左·浮濡脉", "o": "左浮濡脉总起来主气虚、湿郁、虚损、气阴两伤及虚热等病机。浮濡无力为气虚之常脉，气浮于上，卫外不固，故见畏风、头晕；濡主湿，浮则湿郁肌表，气机不畅，故湿温初起脉见濡浮；若兼尺弱不任按，则为虚损，肾虚不固，脾肺气虚；若兼弦、散、微，则气阴两伤，脾肺耗散，虚散无根；", "c": "主气虚"}, {"id": "pc:左+浮+空", "n": "左·浮空脉", "o": "左浮空脉总属虚实夹杂之象，以虚为本，以浮为标。其病机主要有三：一为阴血亏虚，脉道不充而空；二为邪热外浮，虚热鼓动气血外浮；三为气虚，气不足则脉空，气浮于外则脉浮。三者可单独出现，亦可相兼为病。如温热病后期，阴血亏虚与邪热外浮并见；内伤杂病中，气虚可致浮空。临证", "c": "主阴血亏虚"}, {"id": "pc:左+浮+紧", "n": "左·浮紧脉", "o": "左浮紧脉总以‘表寒’为纲，浮主邪在表，紧主寒邪收引，故其核心病机为外感风寒、寒邪闭结。然因兼脉与分部不同，所主又有层次：单见浮紧多主新感表寒，治宜辛温解表；兼沉弦则寒邪束饮、饮伏于里，主寒饮内伏；见于左脉则寒伤血分，见于右脉则寒伤气分，示寒湿伤分；若暑温见浮紧", "c": "主外感风寒"}, {"id": "pc:左+浮+缓", "n": "左·浮缓脉", "o": "左浮缓脉总起来主风邪外袭与阳气虚衰两大类病机。一方面，浮缓为风邪伤卫、太阳表证之典型脉象，风性弛张，卫气不固，故脉浮而缓，治当祛风解表；另一方面，浮缓亦可见于阳虚气弱、脾阳不足之候，浮为虚阳外浮，缓为鼓动无力，若兼虚则阳虚气弱，兼弦则虚风内动。两类病机虽一实一", "c": "主风邪伤卫"}, {"id": "pe:左+浮", "n": "左·浮脉", "o": "左浮脉总以浮象为纲，所主病机可归为表邪、风木、热郁、虚阳外浮、痰湿、积滞六类。浮主表、主阳浮，故外感诸邪在表者脉多浮，风邪犯肝、木旺克土者左关独浮，热邪郁蒸、有外达之势者浮而兼数兼弦，虚损劳伤、阳不敛藏者浮而无力无神，湿痰内阻、肝火冲激者浮而兼小兼弦，积气内结", "c": "主表邪"}, {"id": "pc:左+浮+芤", "n": "左·浮芤脉", "o": "左浮芤脉总属阴血亏虚、阳气浮越之候。芤为血虚中空，浮为气升阳浮，二者相合，揭示阴血不足、阴不维阳的核心病机。由此可衍生四类病机：血虚失养、阳气外浮、肝阳上亢、热扰心神。血虚是基础，阳浮是血虚不能内守的结果；肝阳上亢因阴血亏虚不能涵木，气火上逆；热扰心神则由阴虚", "c": "主血虚"}, {"id": "pc:左+浮+虚+缓", "n": "左·浮虚缓脉", "o": "左浮虚缓脉总主阳虚气弱，尤以脾阳不足为核心。浮为阳气浮越，虚为阳气不足，缓为鼓动无力，三者合见，提示阳气虚衰、机能减退。其具体病机可分三类：一为阳虚，因过汗亡阳，失于温煦；二为气虚，推动无力，形体失养；三为脾弱，运化失职，气机不畅。三者相互关联，阳虚为根本，气", "c": "主阳虚"}, {"id": "pc:左+浮+虚", "n": "左·浮虚脉", "o": "左浮虚脉总属虚证，以气虚阳浮为核心，兼及血虚、脾肺不足、土虚木乘及气不摄血。浮为阳气外浮，虚为正气不足，故诸段皆见气血亏虚、中气不固之象。其病机演变：气虚则推动无力，血虚则脉道不充；脾肺气虚则运化失职，土虚则木乘，气不摄血则血溢。各段或偏于气阳浮越，或偏于血虚", "c": "主脾肺气虚"}, {"id": "pc:左+浮+软", "n": "左·浮软脉", "o": "左·浮软脉总起来主气血虚衰，尤以气虚、血虚及气血俱虚为核心。其脉象以浮软无力为主，兼见沉弱而缓、浮虚按不应指、变动无常等特征。原文明言「脉不常，血气虚也」，浮软无力为血虚不充，沉弱缓为气虚阳弱，脉无定准则示气血虚极、正气不守。三类病机相互关联：气虚与血虚常并见", "c": "主气虚"}, {"id": "pc:左+涩+伏", "n": "左·涩伏脉", "o": "左涩伏脉总起来主血瘀气滞、阳损劳伤及脏虚。涩主血滞，伏主邪闭气郁，左脉候血，故凡气机逆乱、血行不畅之实证，多见心下痛、呕吐、昏厥等；积劳损阳，阳气亏虚，推动无力，血滞不行，亦见涩伏，伴下血、不能食等虚损之象；若按之沉涩而伏，又为五脏虚衰、正气内衰之征。三类之间", "c": "主血瘀气滞"}, {"id": "pc:左+涩+和", "n": "左·涩和脉", "o": "左·涩和脉总以涩脉为基点，主血行不畅与血少两类病机。涩脉往来艰涩，既可因瘀血内阻、脉络不通，亦可因血少脉道不充、往来滞涩。原文咳血而左脉涩，正是瘀阻与血少并存之象；治后涩象渐和，则示瘀化血行、血络渐通，故咳血止而咳势大减。可见涩脉所主，不离血分：瘀与虚常相互影", "c": "主血瘀"}, {"id": "pc:左+涩+坚", "n": "左·涩坚脉", "o": "左·涩坚脉总属虚实夹杂之象，以阴虚阳浮与脾虚血少、中气困滞为核心。左坚主阴虚阳不潜降，右涩主脾虚血少、中焦气滞，二者并见，提示阴亏于下而阳浮于上，同时中焦脾胃已伤，气血生化不足。原文虽言‘阴虚起见’，但强调‘中焦为急’，说明此脉所主病机以中气困顿为急、阴虚阳浮", "c": "主阴虚阳浮"}, {"id": "pc:左+涩+小+弱", "n": "左·涩小弱脉", "o": "左·涩小弱脉总属气血虚少、脉道不充之象。原文以“脉涩者，少血多气”“脉小血气俱少”为据，涩主血少而气偏多，小弱主血气俱不足，三者合见，总以血虚气弱为本。其病机可分三层：一为血少，涩脉直接主之；二为气虚，小弱脉示气衰无力；三为因虚致滞，气血虚少则运行涩滞，形成气", "c": "主血少"}, {"id": "pc:左+涩+小+结", "n": "左·涩小结脉", "o": "左·涩小结脉总属阴液枯槁、气血痹涩、阳结不通之候，多见于高年衰老、情志内伤之噎膈反胃。其小为阴血不足，涩为津亏血滞，结为气机断续，三者相合，既示下焦阴液枯涸、肠中气痹，又示阴阳不相顺接而成“阴枯阳结”。原文以左小涩结与右弦大对举，右弦大主浊阴渐阻、清阳不升，左", "c": "主阴液枯槁"}, {"id": "pc:左+涩+小+软", "n": "左·涩小软脉", "o": "左·涩小软脉总属气血不足、营卫流行迟钝、八脉拥护无权之候。小软为气血亏虚，涩为营血运行滞涩，三者相合，反映气血两虚、推动无力、奇经失养。其病机核心在气血不足，进而导致营卫循行迟缓，终致八脉约束无权。三类病机层层相因：气血虚为本，营卫迟钝为过程，八脉无权为结果，", "c": "主气血不足"}, {"id": "pc:左+涩+弱", "n": "左·涩弱脉", "o": "左·涩弱脉总起来主阴血亏耗、肝肾精亏及虚中夹实之证。涩主血少，弱主脉道不充，故其本为阴血不足、精血亏虚。若见于外感伏气病中，则示热邪在里而阴伤日久，形成本虚标实之候；若见于内伤杂病，则主肝肾衰少、冲脉失摄、气逆上冲。下属弦涩弱脉兼肝血郁滞、肺气不足，涩小弱脉兼", "c": "主阴血亏耗"}, {"id": "pc:左+涩+濡", "n": "左·涩濡脉", "o": "左·涩濡脉总起来主气血两虚、湿滞痰郁、阳衰脾弱及肝虚肺郁等病机。濡为气虚湿滞，涩为血少脉道不利，二者相合，多示气血不足兼湿阻气滞。若兼弱脉，则阳衰脾弱、火不生土；若兼沉小，则肝阴不足、肺虚痰郁。各段所主虽侧重不同，但核心不离虚（气血、阳、肝肺之虚）与滞（湿、痰", "c": "主气血两虚"}, {"id": "pc:左+涩+结", "n": "左·涩结脉", "o": "左·涩结脉总属气血痹涩、阴液枯槁、阳结不通之候。涩为血滞津亏，结为气机断续，二者相合，既示气血瘀滞、脉道不利，又示阴血亏虚、津液枯涸，更可反映气机郁滞、情志内伤，甚则阴阳不相顺接而成阴枯阳结。四类病机相互关联：气血瘀滞与气机郁滞常相因为病，气滞则血瘀，血瘀则气", "c": "主气血瘀滞"}, {"id": "pc:左+涩+缓", "n": "左·涩缓脉", "o": "左·涩缓脉总属虚实夹杂之象，以虚为本，以郁、湿为标。缓主气虚，涩主血少，合而示气血阴阳之损，多见于久病劳倦内伤之体。然虚处留邪，气虚则运化无力，血少则脉道不利，遂生痰郁湿滞。故其主病机可分五类：虚损、血少、气弱为其本，郁滞、湿淫为其标。原文三段均见操持积劳、五", "c": "主虚损"}, {"id": "pe:左+涩", "n": "左·涩脉", "o": "左涩脉总以血少、血行不畅为基本病机，所主病机可归纳为血虚、血瘀、气滞、痰饮、虚寒、郁热、虚风七类。涩为脉道涩滞，血少则脉不充，血瘀则脉不利，故血虚与血瘀为其核心，二者常相因并存。气滞则血行不畅，痰饮阻滞气机，均可致涩；阳虚则血行无力，郁热则伤阴耗血，血虚则风动", "c": "主血虚"}, {"id": "pc:左+涩+芤", "n": "左·涩芤脉", "o": "左·涩芤脉总起来主血虚与血瘀并见之病机。芤脉中空，主营血虚少、脉道不充；涩脉滞涩，主血行瘀滞、脉络不畅。二者相合，既可因营血亏虚而脉络失养，出现筋挛掣痛（如1653段）；又可因瘀血内阻而血不循经，出现似虚实实之候（如4099、4100、4338段之胞络积血，2", "c": "主血虚"}, {"id": "pc:左+涩+迟", "n": "左·涩迟脉", "o": "左涩迟脉总属肝木为病，以肝气虚实、气机逆乱为核心。其脉见于左关，左关候肝，涩主血滞，迟主虚寒，合而观之，反映肝经气血运行不畅。原文以弦长为肝之平脉，实弦为太过病在外，虚微为不及病在内，沉急为肝气逆，诸脉皆从肝木太过不及立论。故涩迟脉所主病机可归为三类：肝实、肝", "c": "主肝实"}, {"id": "pc:左+滑+动", "n": "左·滑动脉", "o": "左滑动脉总主痰、食、火、胎及血虚气阻诸病机。滑为阳脉，主痰饮宿食，因湿浊内蕴、气机不利；弦滑而数则兼肝阳化火、烁液成痰，属阴虚火旺；左寸动滑摇摆为胎气内动、血聚养胎之妊娠常脉；滑而虚者又主血虚气弱、气阻血虚。各类之间，滑脉核心为实邪壅滞与气血充盛，痰食为实，火", "c": "主痰饮宿食"}, {"id": "pc:左+滑+和", "n": "左·滑和脉", "o": "左·滑和脉总起来主痰饮内停、气机不畅及痰气交阻三类病机，核心为痰与气。滑脉主痰，弦脉主气滞，和利示邪不盛、胃气尚和。痰饮内蕴可阻滞气机，气机不畅又可生痰，二者互为因果，终致痰气交阻，上扰胸膈。原文脉象和利中见滑、弦、动荡，正是痰气交阻之轻证，故仅觉胸膈不快。三", "c": "主痰饮"}, {"id": "pc:左+滑+大+沉+浮+涩+小", "n": "左·滑大沉浮涩小脉", "o": "左·滑大沉浮涩小脉在古籍中并非单一主病之脉，而是总论色脉相参时列举的脉象变化。其核心在于「有诸内者形诸外」，脉随五脏之气而变动，故滑大沉浮涩小可反映脏气之变动；同时须与五色相合，以断病邪之逆顺。脉与色顺则吉，逆则凶。因此，此脉所主病机主要围绕脏气变动、色脉相应", "c": "主脏气变动"}, {"id": "pc:左+滑+大+涩", "n": "左·滑大涩脉", "o": "左·滑大涩脉总起来主虚实夹杂之证。左涩主血少或血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。三部位脉象合参，提示上焦痰火未清、中焦脾弱、下元不足。原文吐血后咳喘、泄泻、发热烦躁，前医滋阴则泻甚、保脾则火炽，正因脉象虚实并见：痰火壅盛为实，血少血瘀与下元虚", "c": "主血少血瘀"}, {"id": "pc:左+滑+大", "n": "左·滑大脉", "o": "左·滑大脉总起来主痰、食、火、水等实邪内壅，亦可见于气虚、虚热等虚实夹杂之证。滑主痰饮、食积，大主邪实、火盛，故滑大有力多主痰火、痰饮、食积等里实证；若滑大而兼他部脉弱，则提示本虚标实，如气虚肝侮、气挟痰水、虚热外浮等。各证之间常相互转化，痰、食、火、水可相兼", "c": "主痰饮"}, {"id": "pc:左+滑+实", "n": "左·滑实脉", "o": "左·滑实脉总属实证、热证，以实热壅盛、痰气内阻为核心病机。其具体所主包括痰热内壅、肝胃郁热、痰凝气滞、痰饮食积四类。痰热内壅多因外感稽留，热灼津液成痰，痰热胶结于肺胃；肝胃郁热则由风束或气郁化火，热壅于胃与肝胆；痰凝气滞侧重痰与气互结，阻滞经络；痰饮食积则因中", "c": "主痰热内壅"}, {"id": "pc:左+滑+小+濡", "n": "左·滑小濡脉", "o": "左·滑小濡脉（此处实为左濡小、右濡滑并见）总起来主阴亏火升、湿痰中阻、营卫失和三端。濡小示阴分本亏，肝经气火易升；濡滑示湿痰中阻，胃失降和；濡脉又主湿恋络脉，致营卫失其常度。三者相互关联：阴亏为本，火升为标；湿痰中阻为实，营卫失和为湿阻之果。原文以‘阴分本亏，", "c": "主阴亏火升"}, {"id": "pc:左+滑+小", "n": "左·滑小脉", "o": "左·滑小脉总起来主虚、热、痰湿、少阳不和与胃不和诸端。滑主痰湿，小示虚象，数主热，弦主少阳。其病机以虚为本，痰湿为标，虚热与痰湿常相兼为患。虚则中气不足，运化失司，痰湿内生；痰湿中阻，胃失和降，则见呕恶、舌腻；少阳之邪未彻，则寒热起伏。各段原文所示，或虚热外浮", "c": "主虚热"}, {"id": "pc:左+滑+弱", "n": "左·滑弱脉", "o": "左·滑弱脉总起来主痰热壅肺、气血不足、脾虚湿痰及妊兼肺痈。左脉浮滑侧重痰热壅肺，右脉弱滑侧重气血不足与脾虚湿痰，弱滑并存示正虚痰恋。原文以左脉验妊兼肺痈，因右脉曾伤手腕难凭，故取左脉浮滑为痰热壅肺之据，右脉弱滑为脾虚湿痰之征。四类病机相互关联：痰热壅肺为标，气", "c": "主痰热壅肺"}, {"id": "pc:左+滑+微", "n": "左·滑微脉", "o": "左·滑微脉总起来主痰湿中阻、木亢升浮之病机。右脉微滑反映胃有湿痰、胃欠通降；左关独弦反映风木偏亢。二者相合，形成胃降不及、胆气不能下行，肝脾升有余而胆胃降不足的格局，遂致眩晕。各类病机之间具有因果关联：湿痰中阻为始动因素，导致胃失和降；胃降不及又使胆气不能下行", "c": "主湿痰"}, {"id": "pc:左+滑+急", "n": "左·滑急脉", "o": "左寸滑急脉总属痰气壅盛、寒凝气滞所致急痛之候，尤以心疝为典型。滑主痰气壅盛，急主痛甚气逆，二者相合，反映痰浊、寒邪与逆气交阻于心胸，导致气机不通、疼痛剧烈。四类病机相互关联：痰气壅盛为病理基础，寒凝气滞为诱发因素，痛甚气逆为急症表现，心疝急痛为具体病证。脉象应", "c": "主痰气壅盛"}, {"id": "pc:左+滑+沉+濡", "n": "左·滑沉濡脉", "o": "左·滑沉濡脉总属虚实夹杂之候，以虚、湿、滞为三大病机。沉为里位，濡为虚湿，滑为痰气壅滞，三者相合，提示脏气内虚、水湿不化、气机郁滞。原文虽为色脉相参总论，但强调「有诸内者形诸外」，脉象随脏气变动而主不同病机，故滑沉濡脉不可单执一因：其虚在脏气不足，其湿在运化失", "c": "主虚"}, {"id": "pc:左+滑+沉", "n": "左·滑沉脉", "o": "左·滑沉脉总属里实夹虚之候，以痰、滞、郁、虚为四大病机要素。沉主里，滑主痰、主滞，故其核心为痰浊内阻、气血郁滞；然多段原文兼见细弱、软、涩等虚象，提示虚中夹实。具体而言：右脉沉滑多主痰饮内停、气逆痰阻，见于中焦脾胃病变；左脉沉滑多主血分有滞、肝气内郁；若与瘀血", "c": "主痰饮"}, {"id": "pc:左+滑+洪+实", "n": "左·滑洪实脉", "o": "左·滑洪实脉总属实证、热证，以实热壅盛为核心病机。洪滑实主热邪内炽、气血涌沸，多见于阳明府实；若兼见结脉，则非虚而属肝气不舒、气机阻隔，为实热兼气滞之候。两类病机相互关联：实热为本，气滞为标，热盛可致气机不畅，气滞又加重热郁。故其脉总以清热通滞为治，与虚寒脉象", "c": "主实热"}, {"id": "pc:左+滑+洪", "n": "左·滑洪脉", "o": "左·滑洪脉总属实证、热证，以痰热壅盛为核心病机。洪为火盛，滑为痰聚，二者相合，主痰火交结、实热内蕴。其病位广泛，可在肺胃、肝胆、阳明腑，亦可涉及心经。具体而言，或为痰热壅肺胃而呕血、胸胀；或为实热积滞于中焦而便结、胁痛；或为阳明热盛充斥表里而壮热、发斑；或为肝", "c": "主实热积滞"}, {"id": "pc:左+滑+浮+疾", "n": "左·滑浮疾脉", "o": "左·滑浮疾脉总起来以阳热亢盛、血气偏盛为核心病机。其“滑”主血多气少、阳盛有余，“浮”主病位偏表或在上，“疾”主热盛急迫。原文既言“脉滑者，多血少气”，又言“脉沉细滑疾者热”，并指出“脉滑而微浮，病在肺”，说明本脉所主非一脏一证，而是以热象为主线，或热在腑，或", "c": "主热"}, {"id": "pc:左+滑+浮+紧", "n": "左·滑浮紧脉", "o": "左·滑浮紧脉在古籍中虽仅一段直接论述，但据原文可归纳其主病机为血多气少、肺病及热证三类。滑脉本象为往来流利，主血实气壅，故首主血多气少；滑而微浮则病位在肺，因浮主表、滑主血，肺合皮毛而主气，血壅气浮则病归于肺；滑而兼疾则热邪内盛，气血沸腾。三类之间以滑脉为共同", "c": "主血多气少"}, {"id": "pc:左+滑+浮", "n": "左·滑浮脉", "o": "左·滑浮脉总属痰、热、风、湿为患，以痰热壅肺为核心，兼涉表风与血分。浮主表主风，滑主痰主湿，左候肝与表，故其病机多端。四类中，痰热壅肺与风邪在表常相兼为病，风痰上扰肺络；血多气少为滑脉本象，示血实气壅；热盛动风则由浮滑兼数疾而化，热势急迫，痰热内扰。诸类相互关", "c": "主痰热壅肺"}, {"id": "pc:左+滑+涩", "n": "左·滑涩脉", "o": "左滑涩脉总起来主虚实夹杂、痰瘀互结之证。滑主痰涎内郁、阳盛痰火，涩主血少、血瘀、气机不畅。二者并见，提示痰浊、瘀血、气滞相互搏结，或营血内枯而痰火壅盛，形成上焦痰火、中焦痹阻、下元不足的复杂病机。各段所论，或偏痰郁气滞，或偏痰瘀互结，或偏血枯痰火，或偏血少阳盛", "c": "主痰郁气滞"}, {"id": "pc:左+滑+濡", "n": "左·滑濡脉", "o": "左滑濡脉总起来主湿浊内蕴、痰湿壅滞、脾虚湿困、阴亏火旺、肝胃不和及正虚邪恋，属虚实夹杂之候。滑脉主痰湿，濡脉主湿困或气血两亏，二者相合，提示湿浊为患贯穿始终，或从外受，或由脾虚不运，或久病湿留。湿邪困阻气机，致肝失疏泄，木郁克土，故见肝胃不和；湿浊久蕴，化热伤", "c": "主湿浊内蕴"}, {"id": "pc:左+滑+疾", "n": "左·滑疾脉", "o": "左·滑疾脉总起来以痰湿、热盛、气虚、阴亏为核心病机，常呈虚实夹杂。滑主痰湿、血多气少，疾主热盛急迫，故本脉可主痰湿化热、阳热亢盛；若滑疾无力，则主气虚痰湿；若与虚弦并见，则主阴亏痰湿。各段原文均围绕“滑主痰湿，疾主热盛”展开，兼见气虚、阴亏等虚象，说明本脉非单", "c": "主痰湿化热"}, {"id": "pc:左+滑+紧", "n": "左·滑紧脉", "o": "左·滑紧脉总起来主血多气少、肺病及热证三类病机。滑脉本象往来流利，主血实气壅，故首主血多气少，为气血偏倾之基础；滑而微浮则病位在肺，因浮主表、滑主血，肺合皮毛而主气，血壅气浮则病归于肺；滑而兼疾则热邪内盛，气血沸腾，紧亦主邪实壅遏，故兼主热证。三者相互关联：血", "c": "主血多气少"}, {"id": "pc:左+滑+缓", "n": "左·滑缓脉", "o": "左·滑缓脉总属痰湿内蕴、本虚标实之候。滑主痰，缓主湿，又主虚，故其病机以痰湿为核心，兼见脾肾气虚、胃阳不足。痰湿中阻，阳气不运，则气机壅滞，升降失常；土虚木乘，肝木克犯，则胁痛挛掣。诸类之间，以痰湿为标，虚为根本，阳弱饮阻、气机壅滞、肝木乘虚皆由痰湿与正虚相合", "c": "主痰湿"}, {"id": "pc:左+滑+缓+迟", "n": "左·滑缓迟脉", "o": "左滑缓迟脉总属痰湿内盛、胃阳不足、肝木乘虚之候。其脉左缓滑，右耎迟，缓滑主湿盛痰聚，耎迟主胃阳素弱，二者相合，揭示中阳不运、痰湿踞中之本。因胃阳素弱，肝木乘虚克犯，致气机壅滞，故见胁痛挛掣；痰湿久郁，温药误投，积温成热，反助风阳，消烁胃津，渐形瘦削；久则气阻血", "c": "主湿盛痰聚"}, {"id": "pe:左+滑", "n": "左·滑脉", "o": "左滑脉总以痰湿内蕴为基本病机，兼涉食积、血热、湿热、肝风、痰火及妊娠。滑为痰饮、食积之象，左脉候肝、候血，故左滑多主痰浊阻于中焦或蒙蔽心窍，亦主血分有热。若滑而有力、滑大、滑数、滑洪，则痰火交结、实热内壅；若左弦右滑，则肝风挟痰上扰；若滑而兼涩，则痰瘀互结；若", "c": "主痰"}, {"id": "pc:左+滑+虚", "n": "左·滑虚脉", "o": "左·滑虚脉总起来主脾肾两虚、湿痰内停之病机。右脉虚滑，重点在脾阳不运、湿痰内停；左脉虚弦，重点在肾阴亏虚、肝木失养。二者相合，形成脾肾同病、虚实夹杂之局：脾虚则湿痰内生，肾亏则肝木失养，痰湿与阴亏并见。原文因误用消痰、苦寒，更伤脾土，致腹痛不食、泻多白沫、畏寒", "c": "主脾虚湿痰"}, {"id": "pc:左+滑+虚+软", "n": "左·滑虚软脉", "o": "左·滑虚软脉总起来主肺燥津伤、风阳内煽与上下交虚三类病机。右脉软滑而虚，重点在肺伤于燥、治节不行，津液被烁；左脉浮弦且数，因辛甘温药致风阳内煽，风动液亏。二者相合，形成上焦肺津亏耗、下焦脾肾不足的上下交虚格局，兼夹痰湿未净与风阳内扰。三类病机相互关联：燥伤肺津", "c": "主肺燥津伤"}, {"id": "pc:左+滑+软", "n": "左·滑软脉", "o": "左·滑软脉总起来主痰湿内蕴与正气不足相兼之证，其病机核心为虚实夹杂。滑主痰湿、气壅，软主气虚、正弱，二者并见，提示痰湿滞留而正气已伤。具体可表现为痰气壅实于肺、正虚夹滞于肝脾、或肺肾并衰之上实下虚。各证虽侧重不同，但均不离痰湿与正虚两端：或痰壅为主而兼气弱，或", "c": "主痰气壅实"}, {"id": "pc:左+濡+弱+缓", "n": "左·濡弱缓脉", "o": "左濡弱缓脉总主湿、气虚、肾虚、血少四类病机，以虚为本、湿为标。濡缓主湿，湿邪困阻筋脉，致筋缓痿软；弱主气虚，气虚推动无力，肢体失养；尺弱主肾虚，肾精亏虚，腰膝失充；左脉小涩主血少，阴血不足，筋脉失濡。四者相互交织：肾虚则气化失司，湿浊内停；气虚则血行不畅，血少", "c": "主湿"}, {"id": "pc:左+濡+弱", "n": "左·濡弱脉", "o": "左·濡弱脉总以虚为本，湿为标，涉及气、血、脾、肾、肝诸脏。濡为湿滞、弱为气虚，故其主病首在气虚与湿滞，二者常相兼为患。左脉候血，濡弱细小又主血虚；关尺弱则主脾肾亏虚。左关候肝，左脉濡弱而右亦弱，示肝脾不调、营卫不和。若濡弱中兼见洪驶，则为虚火内扰、血分伏热之候", "c": "主血虚"}, {"id": "pc:左+濡+散", "n": "左·濡散脉", "o": "左·濡散脉总属虚损之象，主气阴两伤、肺气耗散、脾虚至极及肝郁。其脉浮濡无力，按之散乱，反映正气亏虚、脏腑功能衰败。具体而言，浮濡无力为气阴两伤之征；濡散为肺气耗散，肺主气，气耗则脉散；浮微为脾虚至极，脾为后天之本，虚极则脉微欲绝；弦为肝郁，因土虚木乘或湿阻气机", "c": "主气阴两伤"}, {"id": "pc:左+濡+空", "n": "左·濡空脉", "o": "左濡空脉总属虚证，以肝血不足、胃气虚弱为基本病机。左脉空主肝血亏虚，右脉濡主胃气虚弱，二者并见，反映肝胃两脏气血俱损。肝血虚则络脉失养，胃气虚则受纳无权，故见形瘦食减；络脉既虚，复因情怀不舒、气郁络滞，导致肝胃络伤，血不循经而见呛痰血块、右胁疼痛。其病机核心为", "c": "主肝血不足"}, {"id": "pc:左+濡+缓", "n": "左·濡缓脉", "o": "左濡缓脉总主湿、寒、虚三类病机，以湿为核心，寒、虚为兼。濡主湿，缓主气机弛缓或脾虚，故湿邪困阻、气化不利为其常；若兼迟则寒湿内盛，见于太阴、少阴；若见右脉则脾虚湿滞，左脉则肾虚寒湿。诸类相互关联：脾肾阳虚则寒湿内生，气虚不运则湿滞更甚，湿阻又加重气化失司。故临", "c": "主寒湿"}, {"id": "pe:左+濡", "n": "左·濡脉", "o": "左濡脉总以湿、虚为纲，主脾虚湿困、气血亏虚，兼及痰饮、湿热、阳虚水泛、风湿痹阻及肝郁脾虚等。濡为湿象，又主不足，故凡湿浊内停、气血不充、阳气式微者多见。其与弦并见，则肝郁脾虚、木旺乘土；与滑并见，则痰湿内蕴；与缓并见，则真阳衰微；与劲并见，则湿阻络瘀。诸类之间", "c": "主脾虚湿困"}, {"id": "pc:左+濡+软", "n": "左·濡软脉", "o": "左濡软脉总起来主脾肾两虚，兼夹湿邪。右软候脾，为坤土不足、运化无力；左濡候肾，为坎水亏虚、阴精不充。脾虚失统则上吐红，肾亏不固则下遗白。脾恶湿、肾恶燥，脾虚生湿，湿又困脾，故脉濡亦主湿。三类病机相互关联：脾虚与肾亏并见，湿邪贯穿其中，形成虚实夹杂之候。", "c": "主脾虚"}, {"id": "pc:左+濡+迟", "n": "左·濡迟脉", "o": "左·濡迟脉总主阳气衰微、寒湿内阻及气血亏虚。濡为湿象，迟为寒象，二者相合，多示阳气不振、阴寒内盛。其病机核心在脾肾阳虚：右脉濡迟偏太阴脾寒湿，左脉濡迟偏少阴肾寒湿，甚则命火式微、阳陷入阴。阳气不能温运，则寒湿内生，气化不行，故见小便不利、便溏纳少、腹痛足缓；阳", "c": "主寒湿"}, {"id": "pe:左+牢", "n": "左·牢脉", "o": "左牢脉总起来主邪气深结、病位牢固之候，其病机涵盖邪热深结、气化凝郁、寒凝瘀痛及肝郁深固四类。牢脉以“牢固”为特征，反映邪气胶结难解、病深入络，非表浅之疾。从原文看，牢脉可见于热病邪热深结，虽症减而脉未和；亦见于杂病中焦气化凝郁，久病入络；更因左脉候下焦血分与肝", "c": "主邪热深结"}, {"id": "pc:左+疾+促", "n": "左·疾促脉", "o": "左·疾促脉总属阳热急迫、阴亏火旺之象。其脉来急数而促，主阳气偏亢，然亢阳多由阴亏所致，故案中左脉促疾与右脉虚细并见，断为‘阴气大亏，阳气偏亢’。阳亢化火，火性炎上，灼烁肺金则咳喘汗多；肝阳上逆，木乘土位则便溏不食。四类病机相互关联：阴亏为本，阳亢为标，火旺为阳", "c": "主阳亢"}, {"id": "pe:左+疾", "n": "左·疾脉", "o": "左·疾脉总起来以阳热亢盛为核心，兼涉燥火、阴亏、痰湿、气郁等病机。疾脉主热盛急迫，左脉候心肝，故其病机重心多在心肝火旺。具体而言，或为燥火内盛，伤气伤血，致厥阴客胜、肺热眩晕；或为心火独炽、肝阳上亢，甚则火亢水亏、虚阳外浮；或为阴亏火旺，亢阳无制，灼肺乘脾；或", "c": "主燥火"}, {"id": "pe:左+短", "n": "左·短脉", "o": "左·短脉总起来主心之气血不足，兼夹痰湿、气滞、风热湿浊等实邪，形成本虚标实、虚实夹杂之候。短脉主气机不畅或气损，左寸候心，故短脉首责心血不足、心阳不振；然单纯虚象少见，多与关弦、右关滑、两尺弦大等并见，提示中焦痰湿、下焦风热湿浊或气机壅滞。各病机类别之间相互关", "c": "主心血不足"}, {"id": "pe:左+硬", "n": "左·硬脉", "o": "左·硬脉总起来主肝木亢盛、水亏木旺、心火湿热及湿热下注等病机。其核心为肝木失柔、气火亢盛，硬脉为木旺之象；水亏则木失濡养而亢盛，形成本虚标实；心火偏亢与湿热内蕴可下注肾与膀胱，导致小便淋痛等症。各类病机相互关联：肝木亢盛为基本，水亏木旺为其本虚，心火湿热与湿热", "c": "主肝木亢盛"}, {"id": "pe:左+空", "n": "左·空脉", "o": "左·空脉总属虚证，以阴血亏虚、脉道不充为核心病机。左脉候血，空为脉中空虚无力，故首主阴血亏少、精气内伤。由此衍生数类：阴血虚则阳失潜藏，虚阳上浮，见阳浮不潜；气不足则脉空，气浮于外则脉浮，见气虚不固；肝失濡养则虚风内动，见舌强肢软；正虚而邪气留恋，则成正虚邪恋", "c": "主阴血亏虚"}, {"id": "pc:左+紧+缓", "n": "左·紧缓脉", "o": "左紧缓脉总属寒湿困脾、脾虚气陷之候。紧脉主寒主痛，缓脉主脾弱，二者并见，反映寒湿暴起与脾运不健并存。寒湿内侵，水气作泻，阻滞气机则绕脐作痛；脾虚失运，久泻伤气，则气虚作坠。寒湿郁久又可化热，形成湿郁化热之象。故其病机以寒湿、疼痛、脾虚为基础，并可兼夹郁热，属本", "c": "主寒湿"}, {"id": "pe:左+紧", "n": "左·紧脉", "o": "左紧脉总以寒邪凝滞、气机拘急为纲，所主病机可归为寒凝、表寒、痛、饮邪、郁结、虚寒六类。紧脉主寒，寒性收引，故脉道拘急而紧；寒邪在表则浮紧，在里则沉紧，客于经脉则凝滞不通而痛，寒饮内停则紧兼弦，气郁不达则紧兼弦，虚寒内盛则紧兼数弱。各证虽异，总不离寒与郁二字，或", "c": "主寒凝"}, {"id": "pc:左+紧+迟", "n": "左·紧迟脉", "o": "左紧迟脉总起来主寒凝气滞、阳气虚衰、瘀血内停之证。其脉象以紧迟为主，紧迟应寒，弦主气滞疼痛；左弦紧突出寒邪引动厥气上逆、肝脉拘急，右沉细无力侧重阳气虚衰。各类病机相互关联：寒邪外受或苦寒伤阳为诱因，寒凝导致气滞，气滞则血瘀，瘀滞下焦，膀胱气化不利；阳虚则寒凝更", "c": "主寒在脏"}, {"id": "pc:左+细+乱", "n": "左·细乱脉", "o": "左·细乱脉总属危候，主正气溃散、阴阳离决、气机逆乱。细为阴血亏虚、正气不足，乱为脉道失序、邪气内陷，合而见之，乃正虚邪陷、枢机败乱之象。原文风温误汗误下半月，左脉细乱、右脉断续，更见口开目闭、唇板舌焦、不语失溲、头顶强直、手足拘挛，种种恶象皆成坏症，说明此脉非", "c": "主正虚邪陷"}, {"id": "pc:左+细+促", "n": "左·细促脉", "o": "左·细促脉在此案中总主下焦阴不内守、相火不宁，兼涉中阳未复。细为阴血不足，促为急迫不静，左脉候肝肾下焦，故细促未静首先反映阴液亏虚、不能固守，相火因而妄动，发为寐中遗精。同时，原文将左脉细促未静与右脉弦大少冲和、谷进运迟、吞酸䐜胀并观，说明中焦阳气不振、运化无", "c": "主阴不内守"}, {"id": "pc:左+细+坚+硬", "n": "左·细坚硬脉", "o": "左·细坚硬脉总起来主肾经湿毒蕴结、久郁化热，兼阴血不足。其脉细为阴血亏虚，左尺坚硬鼓指为湿毒深伏肾经、结聚不散、郁而化热之象。原文以‘湿毒深伏于肾’为病机核心，曾患淋浊、横痃下疳，虽愈而喉间糜碎、舌下肿胀，乃少阴肾脉循喉咙、系舌本，湿毒上攻所致。三类病机中，湿", "c": "主湿毒蕴结"}, {"id": "pc:左+细+坚", "n": "左·细坚脉", "o": "左·细坚脉总起来主阴血亏虚、肝阳上逆、湿毒蕴结及郁而化热。细为阴血不足，坚搏为阳亢或邪实。在肝阳上逆案中，细坚搏指示阴亏阳亢、血随气逆，症见失血、汗出；在肾经湿毒案中，左尺细坚硬鼓指示湿毒深伏肾经、结聚不散、郁而化热，兼阴血不足，症见喉间糜碎、舌下肿胀。两类病", "c": "主阴血亏虚"}, {"id": "pc:左+细+小+弱+软", "n": "左·细小弱软脉", "o": "左·细小弱软脉总主气虚劳伤。其脉象软弱细小或虚大无力，反映正气亏虚，鼓动无力。细分之，左脉细弱主肝肾气虚，右脉细软主脾肺气弱，故病位涉及肝、肾、脾、肺诸脏。若脉弱而和缓，为胃气尚存，补之可生；若弱而带数，则兼虚热，补之难效。三类病机以气虚为本，虚热为变，胃气存", "c": "主气虚"}, {"id": "pc:左+细+小+紧+急", "n": "左·细小紧急脉", "o": "左·细小紧急脉总起来主血气俱少、脏气虚寒之病机。其脉细小，主血少气弱，故原文有“脉小血少，病在心”之论；其脉紧急，主寒主痛，示寒邪收引或阳虚内寒；其脉兼迟，则病在脏，属里属寒。四类病机相互关联：血少则脉道不充而细小，气虚则推动无力而脉紧，脏虚则寒内生而脉迟紧，", "c": "主血少"}, {"id": "pc:左+细+小", "n": "左·细小脉", "o": "左脉细小总属不足之象，主阴血精津亏虚，其病机以虚为本。从所收14段看，或见于血崩后血舍空虚，或见于伏暑化火伤阴，或见于精浊梦遗精血内亏，或见于肝肾虚胀之肝经、肾经不足，皆以细小示脉道不充、阴血亏少。在此基础上，可兼见虚阳不能敛纳而上冲，如动气心悸；可兼真阴不足", "c": "主阴血亏虚"}, {"id": "pc:左+细+弱", "n": "左·细弱脉", "o": "左脉细弱总属虚证，以气阴两虚、血虚阴亏为基础，进而累及脾肾阳气，致脾肾阳虚；阴血亏虚，水不涵木，则虚风内动；阴不制阳，则虚阳上浮；正虚之处，易受邪侵，痰瘀阻络，形成本虚标实之候。各类病机相互关联，总以正虚为本，或兼标实，反映了左脉细弱在虚损、风动、阳浮及痰瘀等", "c": "主气阴两虚"}, {"id": "pc:左+细+微+弱+迟", "n": "左·细微弱迟脉", "o": "左·细微弱迟脉在原文中作为鉴别脉象出现，原文强调'脉非微细迟弱'以排除虚寒，并指出左伏主肝郁血滞。总起来看，此脉所主病机以肝郁血滞为核心，兼涉虚寒与实热之疑似鉴别。微细迟弱本主虚寒，但此案脉非微细迟弱，反见左伏，故虚寒非其正主；实热内结虽可致脉变，然左伏更偏郁", "c": "主肝郁血滞"}, {"id": "pc:左+细+微", "n": "左·细微脉", "o": "左·细微脉总主虚证，以肝肾阴阳两虚为核心，兼及阴血亏虚、气陷阳衰、元气欲脱及毒盛正虚。微为阳虚，细为阴弱，左候肝肾，故脉见细微多责之肝肾虚损。其轻者阴血不足、气陷阳衰，见久痢、咳喘、胁痛、头痛等；其重者元气欲脱，见汗出如洗、目上窜、脉按之即无；亦有毒盛正虚、脉", "c": "主肝肾阴阳两虚"}, {"id": "pc:左+细+沉+微", "n": "左·细沉微脉", "o": "左脉沉细阳微，总属阳气不振、湿浊内阻之候。沉为湿郁，细为脉道受阻，阳微为阳气式微，三者相合，揭示阳气虚衰不能运化水湿，湿浊内阻又进一步困遏阳气，形成恶性循环。湿浊困阳，气血运行不畅，故见症瘕痛发、舌苔厚白、面色淡黄而暗。此脉所主病机以阳虚湿阻为核心，湿浊、阳微", "c": "主湿浊内阻"}, {"id": "pc:左+细+沉+紧", "n": "左·细沉紧脉", "o": "左·细沉紧脉总属里虚寒凝、肝经病变。沉主里，细主阴血不足，紧主寒主痛，左关候肝，故其核心病机为寒邪内束厥阴肝经，兼下焦虚寒、阴血亏虚，以致相火不藏、虚阳上浮。原文见目赤如鸠、梦泄不禁、足冷如冰，即寒凝于下、虚阳上浮之候。三类病机相互关联：寒凝肝经为标，里虚不足", "c": "主寒凝肝经"}, {"id": "pc:左+细+沉", "n": "左·细沉脉", "o": "左脉沉细总属里证、虚证，以阳气不足、阴血亏虚为基本病机。沉主里，细主虚，左候阳气与阴血。其主病机可归纳为：阳虚气陷，鼓动无力；阴血亏虚，脉道不充；湿热蕴结，伤阴滞络；肝郁气结，血行不畅；痧毒深伏，气血亏虚；寒邪内陷，阳不外达。诸类之间，或虚或实，或寒或热，然皆", "c": "主阳虚气陷"}, {"id": "pc:左+细+浮", "n": "左·细浮脉", "o": "左·细浮脉总起来主气血俱虚、中气不固之病机。其脉象以浮软无力、沉弱而缓为特征，反映正气亏虚、气不内守的本质。具体而言，气虚则脉沉弱而缓，血虚则脉浮虚按不应指，气不内守则脉浮软无力，中气不固则脾脉轻按阁指重按不足且变动无常。四类病机相互关联：气血互根，气虚日久必", "c": "主气虚"}, {"id": "pc:左+细+涩+空", "n": "左·细涩空脉", "o": "左·细涩空脉总属阴血亏虚、肝失濡养、虚风内动之候。细主阴血不足，涩主血少，空为营阴亏虚，三脉并见，提示心肾阴亏为病之本。阴血亏虚，肝木失涵，进而风阳窃动，出现四肢麻木、形容不泽等症。三类病机以阴血亏虚为核心，肝失濡养为中间环节，虚风内动为发展结果，层层相因，治", "c": "主阴血亏虚"}, {"id": "pc:左+细+涩", "n": "左·细涩脉", "o": "左·细涩脉总以阴血亏虚、脉道涩滞为基本病机。细为血少脉道不充，涩为血行不畅，故其核心所主为血虚与血瘀，二者常相因并存。在此基础上，因阴血亏虚、阳无所附，可致虚阳上浮而成上实下虚；若气分亦弱，则成气血两衰、营卫失流行；若阴亏而火旺，则见血虚火旺、肝风内动；若兼右", "c": "主血虚"}, {"id": "pc:左+细+滑+沉+疾", "n": "左·细滑沉疾脉", "o": "左·细滑沉疾脉总起来以主热为核心，兼主气血偏颇与病在腑。沉细滑疾，疾数为热，滑为阳盛，沉细示热郁于里，故主里热或郁热；滑脉多血少气，细滑并见则血气分布不均，气分偏弱而血分偏盛；疾属数类，数脉在腑，故又主病在腑。三类之间以热为枢：热盛于腑则脉数疾，热郁于里则沉细", "c": "主热"}, {"id": "pc:左+细+滑", "n": "左·细滑脉", "o": "左细滑脉总起来主正虚邪实之候，以阴血不足为本，痰湿内蕴为标。细脉主血少、心肾亏虚，滑脉主痰湿、妊娠。四段原文中，或见阴血不足兼痰浊内蕴，或见营虚与胎孕并见，或见心肾虚弱兼暑湿痰火，或泛论滑脉多血少气。各类病机相互关联：血虚与痰湿常并存，形成虚实夹杂；滑脉既可主", "c": "主血虚"}, {"id": "pc:左+细+濡", "n": "左·细濡脉", "o": "左·细濡脉总起来主湿盛、脾虚、肝血虚、肝风乘脾及痰湿壅肺等病机。细濡为湿困与气血不足之象，左脉候肝，故多责之肝脾两脏。湿盛则气机壅滞，脾虚则运化无力，肝血虚则筋脉失养，肝风乘脾则见蠕动、胀闷，痰湿壅肺则咳喘胸满。各类之间相互关联：脾虚湿盛为常见基础，湿郁可化热", "c": "主湿盛"}, {"id": "pc:左+细+硬", "n": "左·细硬脉", "o": "左·细硬脉总起来主阴血亏虚、气血两亏及湿毒蕴结三类病机。其脉细为阴血不足，硬为津液短少、脉道失濡，故核心在阴血亏虚；若兼弦象，则为肝血虚而气血两亏；若左尺坚硬鼓指，则又主肾经湿毒深伏、郁而化热。三者关系：阴血亏虚为脉象基础，气血两亏为虚损之甚，湿毒蕴结为虚中夹", "c": "主阴血亏虚"}, {"id": "pc:左+细+空", "n": "左·细空脉", "o": "左·细空脉总属阴血亏虚、精气内伤之候，以正虚为核心。细主阴血不足，空主营阴亏虚或气不摄固，故其病机首在精血亏少、气阴两伤。因阴血亏虚，肝失濡养，可致虚风内动，见四肢麻木、形容不泽；因气不摄固，可致咳汗、声嘶、神夭。若虚中夹实，则细空与弦急并见，提示正虚邪滞、气", "c": "主精血亏虚"}, {"id": "pe:左+细", "n": "左·细脉", "o": "左细脉总以阴血亏虚为基本病机，因左脉候心肝肾，细主脉道不充，故凡精血、津液、营阴亏少者多见。其轻者仅阴血不足，重则气阴两虚、脾肾虚损；阴亏则阳无所附，可致虚火内扰或虚阳上浮；正虚之处易受邪侵，又常兼痰、湿、热、瘀而成本虚标实之候。各段所载，或纯虚，或虚中夹实，", "c": "主阴血亏虚"}, {"id": "pc:左+细+虚+涩+小", "n": "左·细虚涩小脉", "o": "左·细虚涩小脉总属阴阳气血俱虚、郁结不畅之象。左脉大空虚主阴血枯槁，右脉细小虚涩主阳气郁结、津血不充，二者合见，提示阴血亏耗与阳气郁结并存，进而导致胃气衰败、受纳无权，发为翻胃膈症。四类病机相互关联：阴血枯槁与阳气郁结为病之本，胃气将败为病之进，膈症难治为病之", "c": "主阴血枯槁"}, {"id": "pc:左+细+虚", "n": "左·细虚脉", "o": "左细虚脉总属正虚，以阴血亏虚为核心，兼涉气分不足，故可概为气阴两虚。虚细而数则阴亏生热，虚火内扰；虚细而右洪大则肾阴亏而相火亢；虚细而右弦滑则肝阴不足、肝风犯胃；虚细而右濡滑则脾虚湿痰内蕴。诸类皆以虚细为共同基础，或兼热、或兼火、或兼风、或兼湿痰，形成虚中夹实", "c": "主阴血亏虚"}, {"id": "pc:左+细+虚+软", "n": "左·细虚软脉", "o": "左细虚软脉，总属阴血亏虚之象。细为血少，软为阴虚，虚为不足，左脉候血，故主血虚阴亏。然脉象须四诊合参，此案左细软而右滑数，右脉滑数主暑热壅遏气分，故又主暑湿内伏。两类病机一虚一实，相互关联：阴血亏虚为本，暑湿内伏为标，本虚标实，故脉见左细软而右滑数。治疗上既需", "c": "主血虚阴亏"}, {"id": "pc:左+细+软", "n": "左·细软脉", "o": "左脉细软总属虚象，细为阴血不足，软为气衰无力，左脉候心肝肾，故其主病以阴血亏虚、气弱阳衰为核心。然细软非独主纯虚，常与他脉兼见而示虚中夹实：兼弦数则虚火痰扰，兼弦浮则脾虚外感，兼洪滑则虚中痰火，兼弦大则血分伏邪，兼浮则虚阳上扰，兼涩则阳虚水停，兼弦硬则胃气衰败", "c": "主阴虚"}, {"id": "pc:左+细+软+迟", "n": "左·细软迟脉", "o": "左·细软迟脉总起来主脾土虚弱、阳气不运，兼有肝木乘脾之机。细软为脾虚气弱之征，迟为阳气不运之象，二者相合，揭示中焦脾胃虚寒、运化无力；而左脉沉小弦又示肝阴不足、肝气偏旺，形成土被木乘之势。三类病机相互关联：脾虚为本，阳虚为脾虚之进一步发展，木乘土则是在脾虚基础", "c": "主脾虚"}, {"id": "pc:左+细+迟", "n": "左·细迟脉", "o": "左·细迟脉（含细软迟）总起来主脾土虚弱、阳气不运，兼有肝木乘脾及寒热错杂之机。细软迟为脾虚气弱、阳虚不运之征，左脉沉小弦又示肝阴不足、肝气偏旺，形成土被木乘之势。从抽样段落看，右迟细主中阳不足、寒湿内停；左弦数主气滞寒凝、寒热时作，兼感温邪则数。各类病机相互关", "c": "主寒湿内停"}, {"id": "pc:左+细+长", "n": "左·细长脉", "o": "左·细长脉总起来主元阳旺而阴分虚，兼有湿热郁于阳明。细为阴分之细，主阴血不足；长为寿命之长，示元阳旺盛；弦数主湿热内郁。三者相互关联：元阳旺则阴分自虚，阴虚又易生内热，湿热郁于阳明则见弦数。症见舌苔黄浊、气急喘促、心神恍惚、胁背胀逆，皆湿热上熏、中上二焦受累之", "c": "主湿热"}, {"id": "pc:左+结+促", "n": "左·结促脉", "o": "左结促脉总主热郁气滞、积热内伏之病机。结促脉为脉来促结不匀，反映邪热壅滞、气机不畅。所主病机主要有两类：一为积热内伏，热郁气阻，多见于积热泄泻，脉必沉数而促结；二为酒热内积，热邪壅滞，多见于酒积泻，脉见洪数或弦数，甚则促结。两者皆以热邪内蕴、气滞脉道为共同基础", "c": "主积热"}, {"id": "pe:左+结", "n": "左·结脉", "o": "左结脉总主气机郁滞、脉道不利之病机，其具体可因气滞、热郁、痰瘀互结、火郁上壅等所致。各段原文显示，结脉非独主虚，亦常见于实热、气郁、痰瘀等证。如左脉弦右脉结为肝郁气滞；脉洪滑甚实而结为阳明实热兼肝气不舒；左脉结疟母为痰瘀互结；左寸搏指为火郁上壅。下属涩结脉主气", "c": "主气滞"}, {"id": "pc:左+缓+和", "n": "左·缓和脉", "o": "左·缓和脉总起来主虚实夹杂之病机，以虚为主，兼夹痰火、食积。其脉象和缓，本为气血渐复、脉道柔和之征，故主正虚；然右关大数或滑大有力，又示中焦郁热、痰食内结，故兼夹实邪。虚者多为脾肾阳气偏弱、下元不足，实者多为痰火、食积。两类病机相互关联：正虚则运化无力，痰食易", "c": "主虚"}, {"id": "pc:左+缓+急", "n": "左·缓急脉", "o": "左·缓急脉总以湿热郁蒸、气机升降失司为核心病机。右缓主湿郁气分，左急主肝风内动，二者并见，反映湿热酒腥相并，阻挠清气游行，营卫循环不利，清浊升降悖逆。其症候群如头如裹、昏寐、瘛痉、咳痰映红、便溏带血等，皆由此派生。各病机类别相互关联：湿热郁蒸为根源，气分湿郁与", "c": "主湿热郁蒸"}, {"id": "pe:左+缓", "n": "左·缓脉", "o": "左缓脉总以湿滞与虚损为两大纲，兼见寒、热、风、痰等邪，形成虚实夹杂之候。缓脉本主湿，又主胃气尚和，故单独见缓多示湿邪留滞或正气未至大衰；若缓而无力，则主气虚阳弱、脾胃大虚、气血不足；若缓兼他脉，则示虚实夹杂，如缓而涩为血少气弱兼郁湿，缓而滑为痰湿内蕴兼脾肾气虚", "c": "主虚损"}, {"id": "pe:左+芤", "n": "左·芤脉", "o": "左芤脉总以血虚中空为基本脉象，所主病机以失血、血少为核心，可兼见血瘀、气亏、痰火、热盛、肝旺等。其类虽多，然皆围绕“血虚脉道不充”展开：纯虚者主血虚、气血两虚；虚中夹实者主血虚兼瘀、痰火灼伤、热盛津伤；脏腑偏亢者主肝旺血虚。各证或由失血直接致芤，或由邪热灼伤血", "c": "主血瘀"}, {"id": "pc:左+虚+坚", "n": "左·虚坚脉", "o": "左·虚坚脉总起来主脾胃病变、气血虚少与邪实内结三类病机。其脉象以下坚上虚为特征，下坚反映邪实内结，上虚反映气血不足，而关部候脾胃，故虚实夹杂于中焦最为突出。原文“脉下坚上虚，病在脾胃”是核心依据；同时“脉小血少”“脉涩少血多气”等说明虚象可主气血虚少；“脉大而", "c": "主脾胃病"}, {"id": "pc:左+虚+实", "n": "左·虚实脉", "o": "左·虚实脉总以虚中夹实、正虚邪陷为纲。其脉或微数无伦，或如虾游，皆因正气内亏，气血不能守卫，邪气乘虚内陷；微为阳微，数为邪热，故见阳微热郁；脉无伦次、失其根本，则胃气衰败，甚则正气欲脱。四类病机相互关联：正虚为根本，邪陷为标象，阳微热郁为虚实寒热错杂之态，胃气", "c": "主正虚邪陷"}, {"id": "pc:左+虚+小", "n": "左·虚小脉", "o": "左·虚小脉总属虚证，以阴血不足、脉道不充为核心，兼涉气虚、阳虚及湿滞。其主病机可归纳为血虚、阴虚血热、营卫不足、脾虚挟湿、肝虚血少、阴亏阳弱六类。诸类之间相互关联：血虚日久可生内热，形成阴虚血热；血虚及气，则营卫失护、中阳不振；脾虚运化无力则湿滞内停；肝虚血少", "c": "主阴虚血热"}, {"id": "pc:左+虚+小+软", "n": "左·虚小软脉", "o": "左·虚小软脉总属虚证，以血虚为核心，兼涉气虚湿盛与虚热。其脉虚软而小，主营血不足；近快则示血虚有热；同案右脉浮软大，又提示气虚湿盛。原文强调'下多亡阴，血虚湿滞'，经水过多、白带、泄泻等皆伤阴血，而湿滞内停又因脾虚气弱。三类病机相互关联：血虚为本，气虚湿盛为兼", "c": "主血虚"}, {"id": "pc:左+虚+弱", "n": "左·虚弱脉", "o": "左虚弱脉总属正虚之候，以气血阴阳亏虚为共同基础，具体可归为五类：一主气血虚，左弱应血虚、右弱应气虚，气血不足则头眩、麻木瘫痪；二主肾精亏，弱而入尺示督任交亏、精关不固，见遗泄、足痿、喘促；三主真阴真阳不足，左尺虚弱细数主肾阴亏，右尺迟软沉细主命火衰；四主正虚邪", "c": "主气血虚"}, {"id": "pc:左+虚+微", "n": "左·虚微脉", "o": "左·虚微脉总属正虚邪陷之候，以阴阳两亏为根本，寒邪内陷为标象，并可反映心之气血不足。虚微脉形细软无力，主正气虚衰，左部候心与肝肾，故其病机涉及阴阳双亏、寒邪乘虚内陷三阴，以及心气心血不足。三者相互关联：阴阳两亏是基础，正虚则寒邪易陷，而心之不足亦为虚损之一端。", "c": "主阴阳两亏"}, {"id": "pc:左+虚+涩+小+濡", "n": "左·虚涩小濡脉", "o": "左脉虚涩小濡，总属气血两虚、脾虚湿困之候。虚小主气血不足，涩主血少行滞，濡主脾虚湿困。三者相互关联：气血亏虚则脉道不充而见虚小，血少行滞则脉涩，脾虚湿困则脉濡。原文经行前后多少不定、腰胯酸疼、缠绵不已，皆气血两虚、冲任失养所致；服养阴止经剂即停，亦示阴血亏虚。", "c": "主气血两虚"}, {"id": "pc:左+虚+涩", "n": "左·虚涩脉", "o": "左·虚涩脉总属虚损之象，以精血亏虚为核心，兼及气弱、中下交损、胃弱血少及虚中夹滞。虚为不足，涩为血少滞涩，故其主病以阴血亏少、脉道不利为基本。若兼右缓大或细弱，则示中下交损、八脉全亏或气血两虚；若兼胃纳不旺，则示胃弱血少、化源不足；若涩滞明显，则虚中夹滞，可见", "c": "主中下交损"}, {"id": "pc:左+虚+涩+软", "n": "左·虚涩软脉", "o": "左·虚涩软脉总属虚损之象，以阳气亏虚为核心，兼夹湿滞与肝脾失和。左脉弦大空虚，主劳伤阳气、肝脾失和；右脉虚软涩滞，主脾虚湿滞。三者相互关联：阳气虚衰则脾运不健，湿滞内生；脾虚湿盛又加重肝脾失调。原文“积劳伤阳”“当作虚症”表明其病机本质为虚，以脾肾阳虚为本，湿", "c": "主阳虚"}, {"id": "pc:左+虚+濡", "n": "左·虚濡脉", "o": "左·虚濡脉总属正虚邪恋、虚实夹杂之候。其脉象以虚软无力兼濡滑为特征，所主病机可归为三类：一为气虚痰湿内蕴，因脾运不健、痰湿留络而脉见虚濡沉滑；二为阴阳两虚，因纵欲耗损、阴精阳气俱亏而脉见濡虚软小；三为正虚邪恋，因虚弦与濡滑并见，反映少阴亏虚而痰湿未净。三类之间", "c": "主气虚痰湿"}, {"id": "pc:左+虚+空", "n": "左·虚空脉", "o": "左·虚空脉总属虚证，以阴血亏虚为核心，兼及气血两亏、奇脉虚损与虚热不退。左脉候血，空虚为脉道不充、阴血不足之明征；细为血少，空为虚，得按痛缓亦属虚痛。若兼右脉细小无力，则气血大亏；若见八脉空虚昭然，则奇脉虚损；若热势未尽而左脉空虚，则血亏虚热难退。诸类皆以阴血", "c": "主阴血亏虚"}, {"id": "pe:左+虚", "n": "左·虚脉", "o": "左虚脉总以正虚为本，主气血阴阳亏耗，尤以阴血不足为核心。其虚而无力、细、芤者，主气血亏虚；虚馁、尺弱如绵者，主阴精亏虚；虚而弦劲者，主虚风内动；虚大、虚数、弦数上溢者，主虚火浮越；虚而兼弦、滑、涩、滞者，主虚实夹杂；左弦右濡者，主脾虚木乘。诸类之间，虚为共同基", "c": "主气血亏虚"}, {"id": "pc:左+虚+芤", "n": "左·虚芤脉", "o": "左虚芤脉总属气血两亏、阴阳俱损之象。虚脉主气虚，芤脉主血脱，二者并见，说明血崩日久，阴血暴失而气随血耗，形成气血双亏；进而阴亏阳弱，荣阴不守，卫阳不固，出现寒热兼厥。四类病机以血脱、气虚为基础，阴阳两亏为发展，寒热厥逆为变证，层层相因，总以正虚为本，亟宜扶阳济", "c": "主血脱"}, {"id": "pc:左+虚+软", "n": "左·虚软脉", "o": "左·虚软脉总属虚证，以气虚、血亏、阴虚为本，兼涉肝脾失和与虚中夹实。虚软为不足之象，左脉候血，右脉候气，故其主病以气血亏虚为核心：或脾肺气虚，运化无力；或气血大亏，正虚邪恋；或阴亏火炎，虚火上扰。虚软脉又常与弦细并见，示肝脾失和、木乘土位；与数、滑并见，则示虚", "c": "主气虚脾弱"}, {"id": "pc:左+软+和", "n": "左·软和脉", "o": "左·软和脉（含左脉濡细乏力）总起来主肝脾阴血亏虚。右脉软和主脾阴不足，左脉濡细乏力主肝血亏虚，二者合见则肝脾同病，阴血不足。原文虽见经事趱前、一月两至，似有热象，但脉呈软和濡细乏力，故断为虚象，谓「脉可凭耳」。可见软和脉所主以虚为主，非实非热，其病机核心为阴血", "c": "主脾阴不足"}, {"id": "pe:左+软", "n": "左·软脉", "o": "左软脉总以虚为核心，软主气虚、正虚，左脉候心肝肾，故多主阴血亏虚、气衰无力。然软脉非独主纯虚，常与弦、数、滑等兼见，反映虚实夹杂、正虚邪恋之机，如湿热积滞、肝郁脾虚、痰湿内蕴等。病后见软而静者，为邪退正虚、气血未复之象；久病见软，则示虚损已成，肺肾交困。要之，", "c": "主虚"}, {"id": "pc:左+软+迟", "n": "左·软迟脉", "o": "左·软迟脉总起来主虚损之证，以阴血不足、肾阴亏虚、命门火衰、阴阳两虚及脾虚阳弱为核心。软迟之象，非实邪壅滞，乃正气亏虚、脉道不充、阳气不运所致。诸类之间，阴血虚与肾阴虚同源而异位，前者泛言阴液亏少，后者专指左肾真阴不足；命门火衰则属阳虚一端，与肾阴虚相对；阴阳", "c": "主阴血虚"}, {"id": "pe:左+迟", "n": "左·迟脉", "o": "左迟脉总属阳虚寒凝、正气亏虚之候。迟主寒、主阳衰，左脉候肝肾阴血与阳气，故其病机以阳气不足为核心，或为全身阳气虚衰、寒凝脉络，或为脏腑虚寒（如肝肾命火式微、中气不足），或寒凝导致气滞血瘀、寒积夹瘀。诸类之间相互关联：阳虚则寒生，寒凝则气滞，气滞则血瘀；阳虚日久", "c": "主阳虚寒凝"}, {"id": "pc:左+长+坚", "n": "左·长坚脉", "o": "左寸长坚脉总属心火亢盛、邪热壅实之候。其脉体长而坚搏，挺直劲急，与《内经》夏脉“太过”之“来盛去亦盛”相应，主病在外而实热充斥，故见身热骨痛、口疮舌焦等症；若兼沉紧急甚，则热邪内结，脏腑气机壅滞，病虽在内而脉仍坚长，示实邪未衰。三类病机以心火亢盛为核心，热壅内", "c": "主心火亢盛"}, {"id": "pc:左+长+硬", "n": "左·长硬脉", "o": "左长硬脉总主肝经气火亢盛、气血上逆之病机。其脉弦主肝，硬主亢盛，长主气火有余，故核心为肝火亢盛。肝火炽盛则左脉弦长；肝火挟冲胃之气上冲，血随气升，则右脉长而兼硬，发为脑充血、厥证、头疼眩晕等。肝火横逆犯胃，胃气不降，冲气上冲，故右脉亦弦硬而长。气火久亢，耗伤阴", "c": "主肝火亢盛"}, {"id": "pe:左+长", "n": "左·长脉", "o": "左长脉总以气机有余、邪气壅盛为纲，其病机可归纳为寒凝积气、肝火亢盛、热盛邪实、瘀热在里、郁热痰结、阴虚阳旺六类。长脉主气有余，左部候肝胆血分，故其病多与肝经气血失调相关。寒凝积气者，长而紧弹，寒湿搏结肝经；肝火亢盛者，弦长坚硬，气火升逆；热盛邪实者，洪长有力，", "c": "主寒凝积气"}, {"id": "pp:左关", "n": "左关", "o": "左关脉总属肝胆病变，以肝气郁结为基础病机，贯穿虚实两端。实者，肝郁化火则脉数，木乘土位则弦而右弱，痰瘀互结则弦滑弦硬，风阳上扰则浮弦弦劲，寒凝气结则沉迟紧；虚者，阴血不足则弦细虚芤，正虚邪恋则弦而无力。诸类之间，气郁为始，火、痰、瘀、风、寒多由气郁所生，而肝虚", "c": "主肝郁气滞"}, {"id": "ps:左关+促", "n": "左关·促脉", "o": "左关促脉总属气机郁迫、阳郁不宣之象，其病机涉及气逆、阳郁、阴亏火旺及正虚邪陷四类。促脉以气机急促为特征，左关候肝胆，故多与肝气强横、气逆上击相关，如冲气犯胃冲肺、胆府倒置等；气郁日久则阳郁不达，身热不扬；若兼细数、尺弱，则示阴亏火旺，木火刑金；若兼小弱、太谿无", "c": "主气逆"}, {"id": "ps:左关+和", "n": "左关·和脉", "o": "左关和脉总起来主肝郁气滞、郁热内蕴、脾虚湿困、木邪乘土及气聚血凝等病机。左关属肝胆，脉见弦数或弦硬不和，反映肝气郁结、疏泄失常，郁久化火则见数；木气偏亢，易乘肺胃，故肝胆留邪容易犯肺胃；肝郁气聚则血凝，复挟木邪乘土，脾伤湿壅，故兼右细濡涩。诸类之间相互关联：肝", "c": "主肝郁"}, {"id": "pc2:左关+大+洪", "n": "左关·大洪脉", "o": "左关大洪脉总起来主肝胆实热亢盛，尤以肝火为核心。其脉象洪大，为阳热亢盛之征，左关候肝胆，故直接反映肝火炽盛。肝火循经上炎，可致齿痛连及太阳；肝火横逆，木火乘土，则见右脉弦数等脾受克之象。三类病机相互关联：肝火为根本，实热为脉象本质，木火乘土为肝火亢盛后的传变结", "c": "主肝火"}, {"id": "ps:左关+大", "n": "左关·大脉", "o": "左关大脉总属肝经病机，以邪实为主，兼有虚实夹杂。其大象多因肝火亢盛、气郁化火、痰瘀壅聚、湿热内蕴等实邪鼓动气血所致，故常兼弦、数、滑、洪等脉。然亦有阴亏阳浮、虚阳不敛之虚证，脉大而按之不摄。各类之间，实热与郁火常相兼，痰瘀与湿热多互结，虚阳则因实邪耗阴或素体亏", "c": "主肝火"}, {"id": "ps:左关+小", "n": "左关·小脉", "o": "左关小脉总属肝经不足、阴血亏虚，但兼脉不同则病机有别。小脉本身主肝经不足、阴伤，如段24888“左关细小，肝经不足”；兼弦则肝郁，兼促则阳郁，兼细数则阴亏火旺或真阴不足，兼沉迟则真阳不足。段440湿温伏邪内陷少阴，左关弦小而促，示肝气郁而阴伤阳郁，冲气上逆；段", "c": "主阴伤"}, {"id": "pc2:左关+弦+大", "n": "左关·弦大脉", "o": "左关弦大脉总属肝经病变，以邪实气郁为主，兼见虚实夹杂。弦为肝脉，大主邪盛，左关候肝，故其核心病机为肝气郁结、气机壅塞，进而化火、生湿、酿痰、致瘀。临床可见肝郁气滞、肝火亢盛、湿热壅滞、痰瘀互结、肝胃不和等实证，亦可见真阴亏虚、虚阳上逆之虚实夹杂证。诸类之间，气", "c": "主肝郁气滞"}, {"id": "pc2:左关+弦+浮", "n": "左关·弦浮脉", "o": "左关浮弦脉总起来主风邪与肝气不足，并可外见于中风。浮为风邪在表，弦主少阳厥阴风木，故浮弦相合，主风邪客于肝胆经络，如中风之脉左关浮弦，病在足厥阴、少阳；内伤自汗见左关浮弦，为挟风邪。又浮为不足，弦主肝病，故左关浮弦亦主肝气有损，属肝虚劳伤之脉。三类病机相互关联", "c": "主风邪"}, {"id": "pc2:左关+弦+滑", "n": "左关·弦滑脉", "o": "左关弦滑脉总属肝胆为病，以弦主风阳、气火，滑主痰涎、痰火为基本病机。其具体所主可分三类：一为风阳挟痰火上扰，症见头面疼痛；二为肝胆余邪未尽，脉带弦滑而余部和，属少阳生发之机未复；三为气火夹痰凝结少阳，发为马刀结核坚肿。三者皆以左关候肝、弦滑相合为凭，或偏于风火", "c": "主风阳痰火"}, {"id": "pc2:左关+弦+硬", "n": "左关·弦硬脉", "o": "左关弦硬脉总起来主肝经病变，以肝火亢盛、热郁化毒及气陷肝郁三类为主。弦硬为肝脉之象，左关候肝，弦主肝郁，硬主邪实。其病机或为肝火亢盛，相火上炎，灼伤血络而致吐血；或为热郁疮毒，伏气与疮毒俱发，热毒内蕴；或在危重气陷之时，肝失疏泄，气机失调而现弦硬。三类之间，肝", "c": "主肝火"}, {"id": "pc2:左关+弦+细", "n": "左关·弦细脉", "o": "左关弦细脉总以肝为核心，主肝血不足、肝气郁结，并常兼他脏病机。弦为肝脉，细为血少，故单见弦细多责肝血亏虚、筋脉失养；若气机不畅则兼肝郁。若细甚而见他部细数，则为水亏火浮，肝火偏亢；若兼右关微数，则湿郁化热。若细主脾虚、左关弦主肝郁，则成脾虚肝郁之候。诸类之间，", "c": "主肝血不足"}, {"id": "ps:左关+弦", "n": "左关·弦脉", "o": "左关弦脉总属肝病，以肝气郁结为基础病机，贯穿虚实两端。实者，肝郁化火则弦数，木乘土位则弦而右弱，痰瘀互结则弦滑弦硬，风阳上扰则弦劲浮数，寒凝气结则弦紧沉弦；虚者，阴血不足则弦细虚芤，正虚邪恋则弦而无力。诸类之间，气郁为始，火、痰、瘀、风、寒多由气郁所生，而虚证", "c": "主肝郁气滞"}, {"id": "ps:左关+弱", "n": "左关·弱脉", "o": "左关弱脉总属肝虚，以肝气肝血不足为核心。肝虚则疏泄无力，气机郁滞，故见腹痛、胁痛；虚则木不生火，可致心气虚；肝木不足，易被脾土所侮，形成土虚木乘之吐泻。弱脉亦反映整体气血不足，故凡左关独弱，多责之肝虚，治宜补肝养血、柔肝疏木。各类病机均围绕肝虚展开：肝虚为本，", "c": "主肝虚"}, {"id": "ps:左关+微", "n": "左关·微脉", "o": "左关微脉总起来主虚，尤以肝虚、下焦虚寒为核心，兼见湿痰、疟邪等复杂病机。其基本特征为脉力微弱，反映正气不足：左关候肝，微弱为肝气肝血亏虚，疏泄失职；沉微而缓则主下焦虚寒、奇经失固，见于崩漏淋带。在此基础上，微脉可兼弦、滑等象，形成复合病机：微弦主肝火偏动或伏邪", "c": "主虚寒"}, {"id": "pc2:左关+数+大", "n": "左关·数大脉", "o": "左关数大脉总以邪热亢盛为纲，尤重于肝与中焦。数主热，大主邪盛，左关候肝，故首主肝火内盛，木火之邪循经为患；关部又候肝脾，两关俱大数则肝脾郁热偏亢于中，热与积结则成肠胃积热，甚则腹痛便结。若脉见关部数大而下连尺部，又主邪居表里之间，为半表半里之热。然数大之中若寸", "c": "主肝火"}, {"id": "pc2:左关+数+弦+浮", "n": "左关·数弦浮脉", "o": "左关数弦浮脉总属肝胆风热、气火升腾之象。浮为风邪或气火升越，弦为肝郁木亢，数为郁热内盛。四段原文虽见症不同，或伤风不醒咳痰带血，或月事不来目干涩，或新产腹痛呕逆胸胀，或巅痛项强，其病机皆归肝经气火少降多升、风木化火、郁而上升，甚则木火刑金、冲逆犯胃。诸类之间以", "c": "主风热内扰"}, {"id": "pc2:左关+数+弦", "n": "左关·数弦脉", "o": "左关数弦脉总以弦为肝木主脉、数为热象，故总主肝经有热、肝胆火旺，为病机核心。在此基础上，兼浮大则涉胆经之热，兼沉滞、促止则示火郁气结，兼细涩虚弦则示肝血不足，兼滑则示痰热内蕴，兼极虚耎则示积劳阴亏之虚劳。诸类之间，肝火、胆热、郁结、痰热多属邪实，血虚、虚劳多属", "c": "主肝火"}, {"id": "pc2:左关+数+滑", "n": "左关·数滑脉", "o": "左关数滑脉总主痰热内蕴、肝阳化风，兼涉阴虚与湿热。数脉主热，滑脉主痰，左关候肝，故其核心病机为肝经痰热或肝阳灼液成痰。若脉数滑而虚耎，则示阴液素虚、痰热内扰，属本虚标实；若右关亦见数滑，则湿热流注阳明，壅滞经络。诸类之间，痰热为共同基础，肝阳化风、阴虚挟痰、湿", "c": "主痰热"}, {"id": "ps:左关+数", "n": "左关·数脉", "o": "左关数脉总以主热为纲，因左关候肝胆，故其热多与肝相关。细分之：实热者，或为肝火亢盛，或为郁热内蕴，或为湿热壅滞，或为痰热搏结，或为风火升腾，皆脉数有力；虚热者，为阴血亏虚、虚火上炎，脉数而虚耎；另有邪在半表半里，脉数大或独弦，示热郁少阳。诸类之间，实热可兼痰、", "c": "主肝火"}, {"id": "ps:左关+沉", "n": "左关·沉脉", "o": "左关沉脉总属肝经病脉，沉为病在里，主气机郁滞、寒凝阳衰、痰积及郁热诸候。其类别虽分肝郁气滞、虚寒阳衰、寒凝厥阴、痰积疟母、肝胆郁热、肝气太过六端，然皆围绕肝木之气血阴阳失调展开：气郁则沉弦，寒凝则沉迟紧，痰积则沉滑，郁热则沉数涩，阳衰则沉微缓，气逆则沉急。诸类", "c": "主肝郁气滞"}, {"id": "ps:左关+洪", "n": "左关·洪脉", "o": "左关洪脉总主肝胆阳热亢盛，但具体病机有实热、虚火及传脾之异。洪大为阳热之象，左关候肝胆，故首主肝火实热，如齿痛连太阳、肝火亢盛之诊；若洪而有力兼余部细数，则为阴亏火旺、龙雷鼓动之虚火，见于咳血等症；若洪大兼弦长数，则为肝火横逆、木火乘土。三类均以洪脉为阳热之征", "c": "主肝火实热"}, {"id": "ps:左关+浮", "n": "左关·浮脉", "o": "左关浮脉总属肝胆病变，以浮为升越、风动之象，弦数为兼夹。其主病机可归为五类：一主风邪客于肝胆，或风木之邪内动；二主肝阳上亢、气火升腾，风阳上扰；三主胆腑虚实病变，胆气逆乱；四主肝气受损，肝虚劳伤，气不内守；五主肝木犯中，木克土，肝胃不和。各类之间相互关联：风邪", "c": "主风邪"}, {"id": "ps:左关+滑", "n": "左关·滑脉", "o": "左关滑脉总属痰湿为患，因左关候肝，故多与肝经痰湿、痰浊相关。其病机类别主要有五：一为单纯痰湿内阻，如痰阻中焦、心肾不交；二为肝胆余邪未尽，脉见弦滑，示正虚邪恋；三为风阳挟痰火上扰，脉弦滑，症见头面疼痛；四为木郁痰凝，脉弦大而滑，发为坚肿；五为气火夹痰上升，脉弦", "c": "主痰湿"}, {"id": "ps:左关+硬", "n": "左关·硬脉", "o": "左关硬脉总属肝胆气机刚劲失和，其病机以肝木偏亢、火旺气逆为核心，但兼夹不同。一类为肝胆火旺、相火上炎，甚则迫血吐血；一类为热毒郁结，与疮毒伏气俱发；一类为木旺乘肺胃，留邪未净而克伐他脏；一类为气陷肝郁，虚中夹实、气机紊乱。诸类皆以弦硬为脉形特征，反映肝失柔和、", "c": "主肝胆火旺"}, {"id": "ps:左关+紧", "n": "左关·紧脉", "o": "左关紧脉总属肝经寒凝、寒饮或风邪为患。紧脉主寒、主痛、主风，左关候肝，故紧见于左关，多反映肝经为寒邪或风邪所束，或寒饮内结。三类病机各有侧重：寒凝肝经者，多兼沉细，症见足冷、目赤、梦泄，属虚寒凝滞、相火不藏；寒饮内结者，多与右关弦并见，症见胁痛、呕吐、腿痹，属", "c": "主寒凝肝经"}, {"id": "ps:左关+细", "n": "左关·细脉", "o": "左关细脉总属肝经阴血不足，然兼脉不同，病机各异。细而弦者，为肝血不足、筋脉失养，或肝郁化火；细而数者，为阴亏火旺、虚火浮越；细而沉紧者，为寒凝厥阴、下焦虚寒；细而右关带滑者，为湿痰阻胃、阴阳不交；细而左关弦、右关弱者，为脾虚肝郁。要之，细脉主阴血亏虚，左关候肝", "c": "主肝血不足"}, {"id": "ps:左关+虚", "n": "左关·虚脉", "o": "左关虚脉总属肝虚之象，然虚中每兼弦、数，故所主病机以肝阴不足、肝郁火旺为核心，并可波及脾肺而见气虚。四段中，虚弦主肝阴亏而相火不静；弦数而虚主肝郁火旺、火非实火；右寸关虚软示脾肺气虚、土虚金弱；左关独虚则直接主肝胆气弱。诸类之间，肝虚为本，火旺为标，脾肺气虚为", "c": "主肝阴不足"}, {"id": "ps:左关+迟", "n": "左关·迟脉", "o": "左关迟脉总属阳虚寒凝、肝阳不足之候，并可兼见肝气逆。其核心病机为阳气虚衰，阴寒内盛，因左关候肝，迟主阳衰，故首责肝阳不足，温煦失职则寒凝脉络，症见督脉冷、怔忡、疟母不消；若阳虚累及肾或全身，则见两尺沉迟或六脉沉迟，诸阳亏损，阳不化气则小便不利。此外，迟而兼沉急", "c": "主阳虚寒凝"}, {"id": "pp:左寸", "n": "左寸", "o": "左寸候心，故其脉所主病机以心为核心，兼涉肝、脾、肾诸脏。总起来看，左寸脉主病有虚实两端：实者多为心火亢盛、痰湿内蕴、郁热内结、血瘀阻滞、肝阳上亢及寒热错杂；虚者多为气血亏虚、心阳不振。各类之间常相互兼夹，如痰火并见、虚中夹实、寒热错杂等。数、洪、大、锐主火；滑", "c": "主心火亢盛"}, {"id": "ps:左寸+动", "n": "左寸·动脉", "o": "左寸动脉总起来主气机躁动、血行不畅之病机，具体可归纳为三类：一主燥屎内结、腑气不通，动为气机被阻而躁动，沉涩应指如有物为燥屎内结之征；二主妊娠胎动，胎气初结、血聚养胎，左寸候心，故见动滑摇摆；三主血虚气阻，女子经带胎产诸病多本于血虚气弱，气阻血行不畅亦可见动脉", "c": "主燥屎内结"}, {"id": "ps:左寸+和", "n": "左寸·和脉", "o": "左寸和脉总起来主气机调和与邪退向愈之候，其核心在于'和'字，示脉有冲和圆活之象，为胃气尚存、气机来复之征。然兼见数、弱等象时，又主虚实夹杂之病机：数而和主邪热渐退，数而无力主脾虚有热，尺弱主下元不足。此外，左寸和缓亦为心与命门相火之常脉，属脏腑冲和之生理状态。", "c": "主邪退气和"}, {"id": "pc2:左寸+大+洪", "n": "左寸·大洪脉", "o": "左寸大洪脉总属阳盛有余之象，主火、主痰、主瘀热，亦可因虚而见。其形成机理为阳热亢盛，气血壅涌，故脉形洪大。实者如痰火壅盛、瘀热内结，脉多洪大而数，兼滑，症见咯血、痞疼，为有余之候；心火炎上者，左寸浮洪，自汗出；虚者如水亏火旺，左尺浮洪无力，乃阴不制阳。各类之间", "c": "主痰火"}, {"id": "ps:左寸+大", "n": "左寸·大脉", "o": "左寸大脉总属心火亢盛之象，但须结合兼脉与证候分虚实。实者或为痰火瘀热壅盛，或为心火太过炎上，脉多洪大滑数，证见咯血、痞疼、身热口疮等有余之候；虚者或为心肝阳扰、阴亏火旺，脉多弦大而数，证见虚劳失血、咽疼嗽痰等不足之候。四类之中，痰火瘀热与心火太过偏实，心肝阳扰", "c": "主痰火瘀热"}, {"id": "ps:左寸+弦", "n": "左寸·弦脉", "o": "左寸·弦脉总属肝气失和、气机郁逆之象，因兼脉与部位不同而主病多端。弦为肝脉，左寸候心，故其病机核心在肝郁气逆与心火郁结。若弦而数、大，多主阴亏火旺、肝阳上亢；弦而滑、濡，多夹痰湿内蕴；弦出寸口，主肝郁气逆、相火内郁；沉弦而横，主水亏营弱、肝阳化风。诸类之间以气", "c": "主肝郁气逆"}, {"id": "pc2:左寸+弱+短", "n": "左寸·弱短脉", "o": "左寸弱短脉总属心气心血不足之象，因左寸候心，短弱为不足，故凡见左寸短弱，首责心虚。然脉象多兼见他部，故所主病机常非单一。若兼关弦大，则主肝经瘀血；兼右寸关滑大而数，则主上中二焦痰火；兼两尺洪大而数，则主下焦湿热。诸类之间，以心虚为本，痰、瘀、湿热为标，标本相兼", "c": "主心虚"}, {"id": "ps:左寸+弱", "n": "左寸·弱脉", "o": "左寸弱脉总属心之气血不足，然其主病常非单一，多与它部脉象合参而呈本虚标实之候。弱脉本身提示正气亏虚，尤以心血不足为核心；若兼关弦大、右寸关滑大，则主痰瘀互结或痰火壅盛；兼两尺洪大数，则主湿热下注；兼左关虚弦，则主营虚风动。诸类之间，虚为本，痰、瘀、湿、热、风为", "c": "主心血不足"}, {"id": "pc2:左寸+数+弦", "n": "左寸·数弦脉", "o": "左寸·数弦脉总起来主热与郁，具体可归为阴亏肝旺、风暑郁热、肝火刑肺三类。弦为肝脉，主肝阳旺、风与气郁；数为热，主阴液亏、火动。左寸关候心肺胸膈，故其病机多涉及肝、心、肺三脏。三类之间相互关联：阴亏肝旺是基础，阴液亏虚则肝阳易升，进而化火刑肺；风暑郁热是外邪与内", "c": "主阴亏肝旺"}, {"id": "pc2:左寸+数+疾", "n": "左寸·数疾脉", "o": "左寸数疾脉总起来主心火内亢、水亏不制，兼感湿温之邪。左寸候心，数疾为热盛，故主心火炽盛；然此火非实火，乃平昔曲运心机、阴亏火炽所致，故兼坎水不制、虚阳外浮之象。原文三则均见左寸数疾而余脉软大，舌尖独黑，苔腻黄，为火亢水亏兼湿温弥漫之候。心火内亢为其核心病机，水", "c": "主心火内亢"}, {"id": "pc2:左寸+数+细", "n": "左寸·数细脉", "o": "左寸细数脉总属阴血亏虚、虚火内扰之象。细为阴血不足，脉道不充；数为火动，虚热内扰。左寸候心与肺，故其病机多关乎心肺阴血亏虚，虚火亢盛。轻则津气耗亏、心血虚而神浮，或肺阴受损；重则心阳过扰、心火旺极，甚则肾阴枯竭、真火将灺，阴阳离决。各类之间以阴血亏虚为本，虚火", "c": "主阴血亏虚"}, {"id": "ps:左寸+数", "n": "左寸·数脉", "o": "左寸数脉总以主热为纲，因左寸候心，故热多归于心经，然其病机有虚实表里之异。实火者，脉数而搏指、独锐或洪大，主心火亢盛、血热妄行；虚火者，脉细数、数而小或数无伦，主心阴亏虚、虚火内扰，甚则肾水枯竭、心阳浮越。若兼弦象，则涉肝阳化风或郁热内结；兼滑象，则痰热内蕴；", "c": "主心火"}, {"id": "ps:左寸+沉", "n": "左寸·沉脉", "o": "左寸沉脉总起来主里、主郁、主虚、主寒、主热、主痰，病位多在心与胃，常涉及肝、脾、肾。其病机可归纳为热郁、虚损、寒痰、痰蔽、郁滞、水亏阳亢、心痹七类。热郁者，沉数并见，热郁于里不得上散，胃火滞而阴血受灼；虚损者，沉弱为主，气血不足，本虚标实，痰瘀互结；寒痰者，沉", "c": "主热郁"}, {"id": "ps:左寸+洪", "n": "左寸·洪脉", "o": "左寸洪脉总以主火为纲，然有实火、痰火、寒热错杂及虚火之异。洪为阳盛之脉，左寸候心，故首主心火亢盛，见洪大、洪数等象，多属有余之候。火盛灼津，痰热互结，则洪兼滑，主痰火壅盛、瘀热内结，如咯血、胸痞、嘈杂等症。若洪与涩并见，迟数不定，则为寒热错杂、气血壅滞，非单纯", "c": "主火盛"}, {"id": "ps:左寸+浮", "n": "左寸·浮脉", "o": "左寸浮脉总起来主病机以痰湿、热、虚、火旺为主。浮脉主表、主上，左寸候心与心包，故病位多在心肺上焦。痰湿内阻者，多因脾湿肝火冲激，累及心包，脉浮而兼弦数；热邪为患者，浮数并见，燥火郁于上焦；虚证者，浮散无神或浮大无力，为心气虚、阳虚外浮；火旺者，浮洪有力或无力，", "c": "主痰湿"}, {"id": "ps:左寸+涩", "n": "左寸·涩脉", "o": "左寸涩脉总主气血不畅、脉道阻滞之病机，具体可因痰阻气滞、寒热错杂或血少所致。痰阻者，多伴右寸滑、关尺弦小，症见胸膈满闷、食后即便；寒热错杂者，脉忽洪忽涩、迟数无定，症见腿疼筋缩；血少者，多伴右脉耎小无力、关弦尺濡，症见经水愆期、体瘦食少。三者虽异，皆以左寸涩为", "c": "主痰阻气滞"}, {"id": "pc2:左寸+滑+洪", "n": "左寸·滑洪脉", "o": "左寸洪滑脉总以火盛与痰聚为基本病机，洪主火，滑主痰，左寸候心，故多责之心火亢盛、痰热内扰。四段原文中，或单言火盛，或单言痰聚，或痰火互结，或兼脾虚，皆不离火与痰二字。火性炎上，痰性黏滞，二者相合则病势缠绵，症见不寐、头痛、嘈杂、胸胁胀痛等。其病位涉及心、肝、脾", "c": "主火盛"}, {"id": "ps:左寸+滑", "n": "左寸·滑脉", "o": "左寸滑脉总起来主痰、火、郁、妊娠及虚损。滑为痰象，洪滑或滑数多主痰火内蕴、心肝火盛；左寸关洪滑又主肝胆郁火、胃中胶痰，属有余之疾。左寸动滑摇摆则为妊娠胎动之征。此外，滑脉亦可见于血虚气弱、阴亏阳浮之虚证，如经带胎产诸病及肝肾阴亏、火动风生之候。各类之间，痰火、", "c": "主痰火"}, {"id": "ps:左寸+疾", "n": "左寸·疾脉", "o": "左寸疾脉总属心火内亢、水亏火浮之候，兼见湿温外感。其脉数疾，因左寸候心，数疾为离火内亢，多由平昔曲运心机、阴亏火炽所致；余脉软大，乃坎水不制、虚阳外浮，又为湿温之邪弥漫之象。三者相互关联：心火内亢为其本，水亏火浮为其势，湿温兼感为其标。火亢水亏，本已危殆，复感", "c": "主湿温兼感"}, {"id": "ps:左寸+短", "n": "左寸·短脉", "o": "左寸短脉总以心气（血）不足为基本病机，短脉主气血虚衰、脉道不充，左寸候心，故短弱首先反映心血不足、心阳不振。然所举诸案多非单纯虚证，常与关弦、右关滑、两尺洪大等并见，形成虚实夹杂之候：虚在心血心气，实在痰湿、瘀血、湿热、风热。短脉为心气不足之标志，弦滑洪大为痰", "c": "主心血不足"}, {"id": "ps:左寸+细", "n": "左寸·细脉", "o": "左寸细脉总属虚损之象，以阴血亏虚、气弱不充为基础，并可兼见虚火内扰、阴阳离决及肝风上冒等变证。细为脉道不充，主阴血不足或气虚无力推动，故见营虚、肺阴损、心血虚、小肠气弱等。若细而数，则阴亏火旺，虚火内扰，甚则真水下竭、心阳过扰，成阴阳离决之危候。细弱兼弦，又主", "c": "主阴血亏虚"}, {"id": "pp:左尺", "n": "左尺", "o": "左尺脉总属肾与下焦病机，以肾虚为本，虚火、实热、湿毒、饮邪、瘀血为标。其脉象虽多，然核心不离肾之阴阳亏虚与封藏失职：阴虚则细数、浮洪、虚火内扰；气虚则弱、沉弱、独大而封藏不固；若兼邪实，则沉数、洪数主下焦实热，坚硬鼓指主湿毒蕴结，弦大主肾虚饮泛，碎乱搏指主肝风", "c": "主肾阴虚火旺"}, {"id": "ps:左尺+坚", "n": "左尺·坚脉", "o": "左尺坚脉总属肾与下焦病机，以邪实内结为主，兼有虚实两端。段902为肾阴亏虚、虚火内灼，坚象因虚火内迫而现，属虚中夹实；段7810为下焦实热壅盛，坚而兼数，属纯实；段8048为湿毒深伏肾经、久郁化热，坚而鼓指，属邪结深痼。三者虽表现不同，但均以左尺坚为共同脉象，", "c": "主肾阴亏虚火"}, {"id": "ps:左尺+大", "n": "左尺·大脉", "o": "左尺大脉总属肾之病机，以虚为本、以实为标。其大非实热壅盛之洪大，乃肾气不固、虚阳下浮之象；或肾阳亏虚，水饮不化而泛溢；或肝火下汲，龙雷升动而灼阴。三者皆根于肾虚失藏，或兼饮邪，或兼火邪，然总以封藏失职、阳气不潜为核心。故左尺脉大，主肾虚不固、肾亏饮泛、火及肾阴", "c": "主肾虚不固"}, {"id": "ps:左尺+弦", "n": "左尺·弦脉", "o": "左尺弦脉总起来主应时生发、肾虚饮泛与寒饮内停三类病机。其一为常脉，立春前后左尺弦而滑利，乃春生之气应时而生，非病象；其二为病脉，因风邪久恋肺中、寒饮停留胃脘，肺伤及肾，肾亏不能主水，寒饮泛溢，故左尺脉弦而大。三类之中，应时生发属生理之弦，肾虚饮泛与寒饮内停属病", "c": "主应时生发"}, {"id": "ps:左尺+弱", "n": "左尺·弱脉", "o": "左尺弱脉总属肾虚之候，以肾阴亏虚、肾气不足为基本病机，并可兼见阴阳两虚、阴虚火旺及肾虚不寐等证。左尺候肾，弱为不足之象，故凡左尺独弱或沉弱、细弱无力，皆提示肾之真阴或元气亏虚。若弱而细数，则阴亏不能制火，虚火内生；若弱而兼右尺迟软或两尺微弱，则阴阳俱虚；若弱而", "c": "主肾阴虚"}, {"id": "ps:左尺+数", "n": "左尺·数脉", "o": "左尺数脉总属热象，但须分虚实。实热者，沉数、洪数或坚硬，主膀胱、肾经实火或龙火冲逆，如；虚热者，细数、虚数或数而无力，主肾阴亏虚、虚火妄动，如；若数而洪大无伦、失于和缓，则为真阴耗竭、虚阳外越之危候，如；另有瘀血郁而化热，脉见虚软而左尺独数，如。四类之中，阴虚", "c": "主肾阴虚火旺"}, {"id": "ps:左尺+沉", "n": "左尺·沉脉", "o": "左尺沉脉总属里证，以沉为在里为纲。其具体所主，随兼脉而异：沉数主里热，或膀胱结热、太阳里热；沉濡、沉弱主肾虚水亏、肾气不足；沉牢主蓄血，为瘀血坚积；沉涩、微弦主肝郁气滞，阴血滞涩、阳气郁遏。四类之中，里热与蓄血属实，肾虚水亏属虚，肝郁气滞属虚实夹杂。总因左尺候", "c": "主里热"}, {"id": "ps:左尺+洪", "n": "左尺·洪脉", "o": "左尺洪脉总属肾与下焦为病，以虚为本、以火为标。其常见病机有三：一为肾阴亏虚、虚火内扰，洪而无力或数，见小便赤涩、淋沥、大便燥结；二为虚阳外越，洪数无伦、失和缓，属真阴耗竭、子母俱败之危候；三为下焦湿热蕴结，洪数兼小便赤涩。三者以肾虚火旺为核心，虚火失制则阳浮外", "c": "主肾虚火旺"}, {"id": "ps:左尺+浮", "n": "左尺·浮脉", "o": "左尺浮脉总属肾与阴分病变，以虚为本、以火为标。其主病机可归为四类：阴虚火旺、湿热郁蒸、肾虚水亏、内伤衄血。四者皆根于肾阴不足或阴分受伤，致使虚火浮动或湿热郁蒸于外。阴虚火旺与肾虚水亏侧重虚火，湿热郁蒸兼夹实邪，内伤衄血则由虚火迫血而致。诸类之间相互关联，虚火可", "c": "主阴虚火旺"}, {"id": "ps:左尺+细", "n": "左尺·细脉", "o": "左尺细脉总属肾阴精血不足、脉道不充之象，其核心病机为肾虚，但兼象不同则所主有别。细而数者，主阴虚火旺，虚火内扰，可见不寐、劳瘵、肌热等；细弱无力者，主肾气亏虚、阴精不足，不能涵阳固摄；细而坚硬鼓指者，主肾经湿毒蕴结，久郁化热，结聚不散，属虚实夹杂；细数而虚弱并", "c": "主阴虚火旺"}, {"id": "ps:左尺+虚", "n": "左尺·虚脉", "o": "左尺虚脉总属肾虚，以真阴不足为核心，兼涉命火与脾胃。原文五段中，左尺虚弱或细数主左肾真阴亏虚，阴虚不能制火则虚热内生；右尺迟软主命门相火不足；两尺微弱则阴阳俱虚。若虚火浮越、劳瘵虚热，则见弦洪无根之火、衄吐血等，仍根于肾阴亏耗。若脾胃先损、三阴亏损，则脾肾同病", "c": "主肾阴虚"}, {"id": "pc2:左尺+软+迟", "n": "左尺·软迟脉", "o": "左尺软迟脉总属肾虚，以尺脉分候肾中阴阳水火。其核心病机为肾之真阴真阳不足：左尺虚弱细数主肾阴亏虚、虚火内生；右尺迟软主命门相火不足、阳虚不能鼓动；两尺微弱则阴阳俱虚。三者可单独出现，也可并见，反映肾中阴阳互损。进一步可致三阴亏损、虚热无火之劳瘵，出现虚热起伏、", "c": "主肾阴虚"}, {"id": "p:左", "n": "左部", "o": "左部脉总以肝心肾三脏为候，尤以肝木病变为核心。其病机可归纳为肝郁气滞、肝火风阳、阴血亏虚、虚中夹实、痰湿饮邪、邪热壅盛及疟邪内伏七类。弦脉为肝之主脉，故肝郁、肝火、疟邪皆以弦为基；细、小、涩、弱主阴血亏虚，为左脉不足之象；虚中夹实乃虚脉兼弦数滑等，反映正虚邪恋", "c": "主肝郁气滞"}, {"id": "c:数+微+和+平", "n": "平和微数脉", "o": "平和微数脉总起来主热势渐退而余热未尽，兼有下虚未复之象。其脉以平和为基，说明经治疗后上焦结滞已愈强半，气机顺适，灼热减、不渴，邪势大挫；而仍见微数，则提示余热尚存，未全清解。同时大便仍溏、服药后下一次，反映下焦脾胃虚弱未复。故本脉所主病机以余热未尽为核心，虚中", "c": "主余热未尽"}, {"id": "c:数+小+弱+平", "n": "平小弱数脉", "o": "平小弱数脉总起来主热邪伤及血分，尤以阴血亏耗、火旺动血为核心。数脉为热象之据，小弱非虚寒，乃血下夺而脉道不充，故脉反小弱而数。三类病机相互关联：热邪为因，血分受灼为位，血虚火旺为果。热伤血分则迫血妄行，下血如崩致阴血骤亏，脉道失充而小弱；然热未清，故数象仍在。", "c": "主热"}, {"id": "c:数+小+平", "n": "平小数脉", "o": "平小数脉总起来主暑邪渐退、余热未清而正气已虚之候。其脉象以平为邪退之象，小数则示余热未净、正虚未复。原文见神明已出、肢体更疲、言语无力、小寐妨食、舌色尖红、口时干燥，皆病渐退而正益虚之征。三类病机相互关联：暑邪为因，余热未清为邪恋之象，正气已虚为邪伤之果。热邪", "c": "主余热未清"}, {"id": "c:弦+大+平", "n": "平弦大脉", "o": "平弦大脉总起来主气机郁滞、痰饮壅盛、肝木犯土及邪遏经络等病机。其脉象弦而大，弦主郁、主肝、主痛，大主邪盛、主痰壅，故常见于气郁痰壅、木旺土虚之证。原文以弦大为气郁痰壅，兼见伏脉为邪遏经络、气血不行；以右关弦大不平为肝木犯中宫、胃失冲和，属木旺土虚。三类病机相互", "c": "主气郁痰壅"}, {"id": "c:弱+平", "n": "平弱脉", "o": "平弱脉在肺痿病中总主肺热叶焦、津液枯涸、气耗上虚之病机。其脉本由寸口脉数转化而来，因热在上焦，久咳伤肺，或汗吐下、消渴等重亡津液，致肺叶枯萎，气津两伤，故脉由数转弱。各类之间相互关联：肺热津伤为始动因素，津亏与气耗并存，终致上虚不能制下。平弱脉既反映正气亏虚（", "c": "主肺热津伤"}, {"id": "e:平", "n": "平脉", "o": "平脉总起来主气血调和、阴阳和平，为平人无病或病势向愈之象。其类别关系：首为常脉，应时和缓，示胃气未败；次为病中脉转和平，乃邪退正复之兆，多见于汗后、热退、痢减之际；若和平之中按之无力、缓弱不条，则主正气虚损，或为寒湿内滞、阳气不足；又有脉平而症未除者，或为邪热", "c": "主和平无病"}, {"id": "c:虚+平", "n": "平虚脉", "o": "平虚脉总起来主妊娠之常与血气和调。其脉平而虚，非病脉，乃“乳子法也”，反映阴阳匀平、气血无偏胜。原文以“阴搏阳别”释有子，谓血气和调、阳施阴化；又手少阴脉动甚，因心主血脉，血旺成胎；尺中肾脉按之不绝，因肾为胞门子户，胞脉盛以养胎；三部沉浮正等、按之无绝，亦阴阳", "c": "主妊娠"}, {"id": "c:弦+伏", "n": "弦伏脉", "o": "弦伏脉总属邪实内闭、气机收引之候。弦主寒、主饮、主积、主气滞，伏主邪深牢着、阳气郁遏。其病机可归纳为寒凝、饮停、积结、阳郁四类，四者常相兼为患：寒凝则气机收引，饮停则脉道拘急，积结则气血结聚，阳郁则脉伏不起。原文以“双弦者寒，偏弦者饮”明弦脉主寒饮，以“弦紧亦", "c": "主寒凝"}, {"id": "c:弦+促", "n": "弦促脉", "o": "弦促脉总起来主肝木偏旺、气机郁迫之候，其病机以肝郁气逆为核心，涉及木旺克土、木火刑金、惊气乱痰、阴亏风动及虚中挟实等多类。弦为肝脉，主气郁、木旺、惊扰；促主气机急促不宁，或郁而化火，或虚中挟实。诸类之间相互关联：肝气郁结则疏泄失常，气逆于上则刑金咳喘，横逆于中", "c": "主木旺克土"}, {"id": "c:弦+芤+促", "n": "弦促芤脉", "o": "弦促芤脉总起来主藏阴内虚、阳动气泄、肝郁血溢之证。弦主肝郁，促主阳升气泄，芤主阴血内虚，三脉合见，反映心、脾、肝三脏阴亏，阴不制阳，阳动气泄，血不循经而溢出上窍。其病机核心是“藏阴内虚，阳动乃溢”：阴血亏虚为本，肝郁气滞为诱因，阳升气泄为动力，最终导致上部出血", "c": "主肝郁"}, {"id": "c:弦+和+动", "n": "弦动和脉", "o": "弦动和脉总起来主心肝阳气失于潜藏、惊动浮越之病机。其脉弦属肝，动主惊，和脉示胃气尚和但邪未全退。惊怖动心则心阳浮越，肝阳失潜，故见眩旋惊惕；阳不潜藏，木不疏土，中焦失和，则脘闷纳减。四类病机相互关联：惊为诱因，肝阳上亢与阳失潜藏为关键，中焦不和为继发。总以阳气", "c": "主惊"}, {"id": "c:弦+动", "n": "弦动脉", "o": "弦动脉总起来主肝风内动、肝阳上亢、痰火内扰、气郁痰结、虚风上扰及热邪壅肺等病机。弦为肝脉，动主阳升风动，故其核心在肝木亢动、阳气不潜。各类之间相互关联：肝风内动与肝阳上亢常相兼为患，阳升风动则上实下虚；痰火内扰多因火甚逼动肝木，与肝风相合；气郁痰结则木邪贼脾，", "c": "主肝风内动"}, {"id": "c:弦+虚+动", "n": "弦动虚脉", "o": "弦动虚脉总起来主肝风内动与胃虚气伤，二者相互影响。弦动反映厥阴内风暗旋不熄，肝阳上亢，直上巅顶；虚则反映阳明脉衰，胃气虚馁，不能束筋骨利机关。胃虚则表疏，阳气泄越而汗出，气愈伤则阳愈动，形成恶性循环。此脉以虚为本，以弦动为标，属本虚标实之候，病位在肝胃，涉及卫", "c": "主肝风内动"}, {"id": "c:弦+和", "n": "弦和脉", "o": "弦和脉总起来主肝郁气滞、饮邪内停、肝胃不和、少阳疟邪、虚火上逆及暑湿内蕴等病机。弦为肝脉，主气机郁结与疼痛，故肝郁气滞为基础；肝旺克土则见肝胃不和，气逆络伤；肝失疏泄，水湿不化则饮邪内停；少阳枢机不利则疟邪留连；肝风虚火则上盛下虚；暑湿内蕴亦致气机不畅而脉弦。", "c": "主肝郁气滞"}, {"id": "c:数+弦+虚+和", "n": "弦和虚数脉", "o": "弦和虚数脉总起来主肝脾不和、湿滞内困与虚数内伤三类病机。弦脉为肝气偏旺、脾土受克，是病之本；涩脉主湿邪困阻中焦，消磨失职，是病之标；虚数脉则示高年积劳、阴血不足而余湿未清。三者相互关联：肝脾不和致湿浊内生，湿滞日久耗伤阴血，终成虚实夹杂之候。原文以左弦右涩为始", "c": "主肝脾不和"}, {"id": "c:弦+坚", "n": "弦坚脉", "o": "弦坚脉总属肝木刚劲太过之象，其病机核心为肝气亢逆与郁结。弦为肝木，坚则刚劲，故脉见弦坚者，多主肝阳亢盛、升发无制，或肝郁气结、横逆犯中。在此基础上，可因兼脉与病位不同而衍生数类：肝阳亢盛者，阳升无制，挟饮上逆则喘急难卧，化风夹温则偏中神昏；肝郁气结者，木侮脾胃", "c": "主肝阳亢盛"}, {"id": "c:弦+虚+坚", "n": "弦坚虚脉", "o": "弦坚虚脉在头痛脉证中，总属虚证与危候范畴。原文以“头痛多弦”为纲，指出弦为阴脉，邪束于外、阳郁于中而痛，但弦脉须兼见他脉以辨病因。其中弦坚主肾虚厥逆之真头痛，弦软主气虚，微涩主血虚，短涩主阳脱阴衰之危候。四类病机皆以虚为本：肾厥为肾阳虚衰、浊阴上逆；气虚为清阳", "c": "主肾厥"}, {"id": "c:弦+大+坚", "n": "弦大坚脉", "o": "弦大坚脉总属肝阳亢盛、内风震动之象，其病机核心为阳亢风动。弦为肝风，大坚为阳亢，故脉见弦大坚者，多主肝阳上亢、内风扰动。在此基础上，可衍生三类病机：一是肝风上扰巅顶，致头痛、惊惕、汗出；二是木火戕胃，致呕逆、不知饥、流涎；三是阳越于外，致面赤汗淋。此外，坚弦实", "c": "主肝阳亢盛"}, {"id": "c:弦+大+实", "n": "弦大实脉", "o": "弦大实脉总属邪实正盛之象，其脉坚、弦、实、大并见，反映邪气亢盛而正气未衰，正邪交争剧烈。所主病机以邪实为核心，具体可分四类：邪实壅盛、痰积内阻、湿热蕴结、气滞不行。四者相互关联：厚味多怒致湿热内生，湿热酿痰，痰积壅塞气机，气滞又加重痰湿，形成邪实壅盛之局。脉弦", "c": "主邪实"}, {"id": "c:弦+大+弱+散", "n": "弦大散弱脉", "o": "弦大散弱脉总起来主劳倦感寒、气耗血伤、燥热动血及肺痿倾向。弦大主邪盛肝急，散弱主气耗血伤，二者并见，反映正虚邪恋、气血耗散之机。其核心病机为劳倦感寒后误服燥热，致邪热动血、气随血耗，脉象散大不收。四类中，劳倦感寒为始因，气耗血伤为本质，燥热动血为变证，肺痿倾向", "c": "主劳倦感寒"}, {"id": "c:数+弦+滑+大", "n": "弦大数滑脉", "o": "弦大数滑脉总起来主痰积、火热与暑邪内伏，三者相互交织。弦主痰饮，滑主痰积，大数主火，故脉象反映痰积内蕴、火热亢盛，又因暑邪内伏，与胃中痰积互为患。原文以‘胃中痰积未清’为核心，兼见胃火上升鼻衄，说明痰积是基础，火热是痰郁所化，暑邪是外因诱发，共同构成痰热互结、", "c": "主痰积"}, {"id": "c:数+弦+大", "n": "弦大数脉", "o": "弦大数脉总属邪热炽盛、肝火亢盛之象，但须分虚实。弦为肝脉，主气郁、风动；大为邪盛或虚阳外张；数为热盛或病进。实者多见于肝火、热盛、风痰、湿热、热毒，脉来有力，症见壮热、烦躁、目赤、抽搐、肿痛等；虚者多见于阴虚火旺、虚阳上浮，脉虽弦大数而按之无力，症见形瘦、潮热", "c": "主肝火"}, {"id": "c:弦+大+空", "n": "弦大空脉", "o": "弦大空脉总起来主虚损之候，以阳气亏虚、阴血不足为本，兼有气火升动、肝脾失调之标。其脉形大而中空、弦而无力，大非实热，空非纯虚，乃阴虚阳浮、气火迫血之象。所主病机可归纳为阳亢阴亏、血虚失充、气火动血、虚损劳伤四类，四者相互关联：阴亏血虚则脉道不充而见空豁，阳气浮", "c": "主阳亢阴亏"}, {"id": "c:弦+大+虚+空", "n": "弦大空虚脉", "o": "弦大空虚脉总属虚损之候，以阳气亏虚、肝脾肾失调为核心。其脉形大而中空，弦而无力，反映阳气不足、脉道失充，兼有肝郁气滞之象。所主病机可归纳为劳伤阳虚、肝脾失和、脾肾阳虚、湿滞内停四类，四者相互关联：积劳伤阳为根本，阳气虚则肝失温养、脾失健运，进而肝脾不和；脾肾阳", "c": "主劳伤阳虚"}, {"id": "c:弦+大+紧", "n": "弦大紧脉", "o": "弦大紧脉（此段实际为弦紧而细）总起来主阴证，具体包括寒、虚及阴分受邪。弦紧主寒，细主虚，皆阴脉，故其病机核心为寒邪内侵与正气亏虚并存，病位在厥少二阴。原文通过脉象排除阳明、太阴等阳证，确认口臭多饥、下体酸痛、小便频数等症属阴证，且脉细紧示邪从中发，时疫之势未彰", "c": "主寒"}, {"id": "c:弦+细+大+弱", "n": "弦大细弱脉", "o": "弦大细弱脉在此段中并非同时并见，而是反映疾病由实转虚的动态过程。弦大主痰火风邪壅盛之实证，细弱主真水欲竭之虚证，二者先后转化，揭示实症转虚、阴虚火旺之病机。总起来说，该脉所主病机以痰火风实为始，以真水亏竭为本，虚火上亢为变，形成由实转虚、本虚标实的演变链条。临", "c": "主痰火风实"}, {"id": "c:弦+大+结", "n": "弦大结脉", "o": "弦大结脉总起来主气郁气滞、血瘀痰喘之证。其核心病机为气机郁结，因怒而致肝气不舒，脉见弦大；气滞日久则血行不畅，脉来时一结，并见面青爪黑、崩久不止等血瘀之象；气郁化火，炼液成痰，痰阻气逆则见气促痰喘，肺脉沉大有力。各病机之间相互关联：气郁为始动因素，气滞导致血瘀", "c": "主气郁"}, {"id": "c:弦+滑+大+缓", "n": "弦大缓滑脉", "o": "弦大缓滑脉总起来主痰热湿浊壅盛、结于阳明胃腑之实证。其脉弦主肝风，大主邪盛实热，缓滑主痰湿内蕴，四者相合，反映热、痰、湿、风交结为患，而以痰热秽浊胶结胃肠为核心病机。三则医案均见春温谵语发狂，连服清解大剂后反昏沉肢冷、遗溺不饮，似虚寒而实为凉药冰伏，热与秽浊互", "c": "主实热壅盛"}, {"id": "c:弦+大", "n": "弦大脉", "o": "弦大脉总以弦为肝郁气逆、大主邪盛或虚阳外浮为纲，所主病机广泛。其偏实者，多主肝火风动、邪盛热壅、痰饮内停、气逆络伤；偏虚者，多主虚阳外浮及虚中夹实。各类之间常相互兼夹，如肝火可挟痰饮，虚阳可兼痰浊，邪盛可致络伤，虚中每夹实邪。临证须结合脉之有力无力、兼脉及症候", "c": "主肝火风动"}, {"id": "c:弦+大+芤", "n": "弦大芤脉", "o": "弦大芤脉总起来主肝逆气火、阴血亏虚、气逆血涌之病机。弦为肝气逆，洪大为气火亢盛，芤为阴血内亏、血不归络。三者相合，反映水不养肝、肝不藏血，气逆血上，冲犯阳明，致有狂吐之患。脉不安静、波涛不定，正示气逆血涌、防其壅逆之机。各病机之间相互关联：肝逆气火为动因，阴血", "c": "主肝逆气火"}, {"id": "c:弦+大+虚", "n": "弦大虚脉", "o": "弦大虚脉总以虚为本，弦大为标。虚主气血阴阳亏虚，大為虚阳外浮或邪实，弦主肝旺、疼痛、饮邪。其病机多端：或纯虚，如失血、产后、劳伤致气血耗伤；或虚中夹实，如虚中夹瘀、痰热内壅、脾虚湿困；或虚极欲脱，如气散不收、心肾交亏。各证常相互兼夹，如肝旺乘脾、木扣金鸣、阴虚", "c": "主虚（气血阴阳亏虚）"}, {"id": "c:弦+大+迟", "n": "弦大迟脉", "o": "弦大迟脉总起来主寒饮、阳虚与风痰。迟为寒为阳虚，弦主饮主风痰，大示阳气不足而虚或阳升鼓动。三者相互关联：阳虚则寒饮内生，寒饮阻遏则气机壅塞，久则痰气郁勃、风阳升动。原文所载当脐腹痛、气塞胸中、嗳气不得语，以及癫痫痰气阻遏、机窍郁勃阳升等症，皆由此病机演变而来。", "c": "主寒饮"}, {"id": "c:弦+大+革", "n": "弦大革脉", "o": "弦大革脉总属虚证，以正气虚衰、脉失柔和为根本。其具体所主，一为虚劳亡血，二为妇人半产漏下，三为正气虚而脉失柔和。三者相互关联：虚劳亡血与半产漏下皆属精血亏耗，精血既亏，则脉道不充、气浮于外，故见弦大而革、失于柔和之象。弦大为虚阳外浮之征，革为中空之候，合而示正", "c": "主虚劳亡血"}, {"id": "c:弦+实", "n": "弦实脉", "o": "弦实脉总属邪实郁滞之象，以弦主郁、主痛、主肝，实主邪盛、主积结，合而示气机郁滞与实邪壅结并存。所主病机可归为湿热壅滞、肝郁气滞、血郁血结、邪实积滞、暑热内郁及肝实太过六类。其间以肝郁气滞为枢：肝气不疏则湿热、积滞、血瘀随之而生，故湿热、积滞、血结诸证多兼弦实；", "c": "主湿热壅滞"}, {"id": "c:弦+小+促", "n": "弦小促脉", "o": "弦小促脉总属本虚标实、正虚邪陷之候。弦主肝气冲逆，小主阴伤，促主阳郁火郁，三者相合，示肝气郁而冲逆，阴液亏而阳郁化火，正虚于内而邪陷于里。其病机以肝气冲逆为动，阴伤为本，阳郁为标，正虚邪陷为变。四类相互关联：阴伤则肝气失涵而冲逆，冲逆则气机壅遏而阳郁，阳郁化火", "c": "主肝气冲逆"}, {"id": "c:弦+小+急+坚", "n": "弦小坚急脉", "o": "弦小坚急脉总属正虚邪深、病久危候。其脉弦小为正气已损，坚急为邪气深入，二者并见，反映正虚邪结、脉证相反。原文以之与实大脉对举，判断瘅病久病之预后：实大者邪盛正未衰，可治；弦小坚急者正虚邪深，不可治。故本脉所主病机以正虚邪深为核心，进而提示病久危候，临床见此脉当", "c": "主正虚邪深"}, {"id": "c:弦+小+坚", "n": "弦小坚脉", "o": "弦小坚脉总起来主气滞血瘀、疼痛、郁热及正虚邪深。其脉弦主痛、主肝木，小坚为气结血滞，兼数则为郁热，故常见于心脾痛证屡发者，反映气滞血瘀、郁而化热之实象；若弦小坚急并见，则又示正气已损、邪气深入，属正虚邪结之危候。各类病机之间，气滞血瘀是核心，可致疼痛与郁热；而", "c": "主痛"}, {"id": "c:弦+小+弱", "n": "弦小弱脉", "o": "弦小弱脉在此案中并非单一主病，而是左右合参以辨病机。左脉不弦而小弱，主肝血不足，因劳碌悲伤而致；右脉洪大，主暑湿弥漫三焦气分。两者结合，说明病非少阳疟症，而是暑湿伤及气分，兼有肝血不足之虚实夹杂证。脉象的小弱与洪大并见，提示正虚与邪实并存，治疗需兼顾扶正与祛邪", "c": "主肝血不足"}, {"id": "c:数+弦+小", "n": "弦小数脉", "o": "弦小数脉总以弦、小、数三象合参，主病机复杂，常本虚标实、寒热错杂。弦主肝郁、气滞、风动、痰饮、痛；小主阴血不足、正气亏虚；数主热、火、郁蒸。故其核心病机为阴液亏虚、虚火内扰，肝风痰热交炽，湿热郁蒸，气滞血瘀，脾虚肝郁，以及邪恋正伤。诸类之间相互关联：阴虚火旺可", "c": "主阴虚火旺"}, {"id": "c:弦+涩+小", "n": "弦小涩脉", "o": "弦小涩脉总起来主气滞痰聚、阴血不足与脾阳受困三类病机。弦主郁怒气滞，小涩主阴血不足、血行不畅，三者相合，常见于郁怒伤肝、气滞痰聚日拥、清阳不展之噎膈，以及太阴脾阳受困、阳微血少之脘痞便难。其病机关系为：郁怒伤肝，气滞痰聚，化火伤阴，致阴血不足；久病及阳，脾阳受", "c": "主气滞痰聚"}, {"id": "c:弦+滑+小", "n": "弦小滑脉", "o": "弦小滑脉总属本虚标实、虚实夹杂之象。弦主肝风、肝郁、气逆或寒痛；小主正气不足、阴血亏耗或脾肾虚衰；滑主痰湿、湿浊、痰热或宿积，亦应妊娠之脉。三者合参，常见于风痰上扰、痰热内蕴、湿浊中阻、肝胃不和、胎元不固及宿积兼寒热等证。其病机核心为正气已虚而痰湿、湿浊、痰热", "c": "主风痰上扰"}, {"id": "c:弦+小+迟", "n": "弦小迟脉", "o": "弦小迟脉总起来主寒湿痰瘀凝结、营卫不从之证，以寒、湿、痰、瘀互结为核心，兼见痛、饮、虚等病机。弦主痛主饮，迟主寒，小主虚，三脉合见，提示寒邪凝滞、痰湿内阻、瘀血结聚，且正气不足。原文缩脚阴痰肿硬疼痛、皮色不变、苔薄腻，正是寒湿痰瘀凝结厥阴之络的典型表现。诸类之", "c": "主寒湿痰瘀"}, {"id": "c:弦+散+平", "n": "弦平散脉", "o": "弦平散脉在古籍中仅见一段论述，且非专论病机，而是借“脉弦服平胃散、脉缓服黄耆建中汤”说明用药须随脉象虚实而禁宜。由此可归纳其主病机有二：一为肝木乘脾，弦脉为肝旺之征，木亢则克土，故以平胃散运脾制木；二为脾虚，缓脉为脾弱之象，弦中兼缓，提示脾虚不运，故以黄耆建中", "c": "主肝木乘脾"}, {"id": "c:弦+平", "n": "弦平脉", "o": "弦平脉总起来主肝木为病，以弦为肝脉、平为病势稍减为基本特征。其病机涉及肝阳亢逆犯胃、肝火内燃灼阴、疟邪留恋少阳、肝木乘脾等类。诸类之间以肝为核心：肝阳亢逆则犯胃，肝火内燃则伤阴动血，肝气不平则疟邪乘少阳枢机，肝旺则乘脾土。弦平脉之“平”多示邪势稍缓而病根未拔，", "c": "主肝阳犯胃"}, {"id": "c:数+弦+弱", "n": "弦弱数脉", "o": "弦弱数脉总起来主本虚标实、虚实夹杂之证。弱脉主气血阴阳亏虚，为病之本；弦脉主肝旺气郁，数脉主热（实热或虚火），二者为病之标。弦与数相合多主肝郁化火、湿热内蕴或虚火内扰；弱与弦并见则主土虚木乘、肝脾不调。具体而言，弱象突出者主虚，弦象突出者主肝旺，数象突出者主热", "c": "主虚"}, {"id": "c:弦+弱", "n": "弦弱脉", "o": "弦弱脉总属虚实夹杂之象：弦主肝木偏亢、气滞、痰饮、痛证与邪郁，弱主气血不足、中阳亏虚、营血虚少。二者并见，多示正虚邪恋、土虚木乘、本虚标实。其病机大致可分肝旺乘土、正虚邪恋、虚寒腹痛、痰饮上泛、肝血不足、阳升气逆数类，彼此关联：肝旺乘土与阳升气逆均以肝木偏亢为", "c": "主肝旺乘土"}, {"id": "c:弦+微+和", "n": "弦微和脉", "o": "弦微和脉总以弦象与和缓并见为特征，主病机为邪气未尽而胃气渐复、肝木偏旺而水亏、痰湿内蕴及疟邪留恋。弦为气机郁滞、邪气未清之象，微和或冲和则反映胃气尚存、正气渐复。各段中，脉弦微和见于疟疾便泻后，示疟邪未尽、胃气渐复；关微弦见于木旺水亏、痰湿肝风之体，示肝木偏旺", "c": "主疟邪未尽"}, {"id": "c:弦+滑+微", "n": "弦微滑脉", "o": "弦微滑脉总起来主风、湿、痰、火相互搏结为患，其病机核心为风湿内郁与风阳上冒两类。弦脉主风、主饮、主肝，滑脉主湿、主痰、主火，微滑则示痰湿较轻或兼阴伤。两段所载，一为风湿袭脾，水湿泛溢而见足肿麻木；一为阴虚阳亢，风木升动、痰火内郁而致卒厥迷愦。二者虽病位有脾与肝", "c": "主风湿困脾"}, {"id": "c:弦+微+硬", "n": "弦微硬脉", "o": "弦微硬脉总起来主肝木偏旺、失于柔和之病机，核心在肝。弦为肝脉，硬为气郁化火、亢阳失柔或阴血亏虚、筋脉失养。其病机演变以肝郁气结为始：气郁日久则化火伤阴，致血虚火旺；阴血亏虚则肝阳失潜，成阴虚阳浮；肝木偏旺又易横逆克土，致脾虚木旺。四类中，肝郁气结是基础，血虚火", "c": "主阴虚阳浮"}, {"id": "c:弦+大+急", "n": "弦急大脉", "o": "弦急大脉总起来主邪盛正溃、胃气将绝之危候。弦急反映肝木劲张、邪势鸱张，大为正气外浮欲散，二者并见，提示邪气壅盛而正气溃散，常见于痢疾湿热壅结肠胃、噤口不纳等重证。其病机核心为邪盛与正虚并存，且以胃气衰败为关键，故列为死候。各类之间相互关联：邪盛导致正溃，正溃又", "c": "主邪盛"}, {"id": "c:弦+急", "n": "弦急脉", "o": "弦急脉总属肝木为病，以气机劲急、失于柔和为特征。弦为肝脉，急为气火亢盛或邪势迫急，故其病机以肝为核心，涉及气、火、风、痰、饮、瘀、虚等多端。情志郁怒则肝气横逆，气逆上冲而为郁为厥；肝火亢盛则迫血妄行，见吐衄崩漏；气滞血瘀、寒湿痰浊壅阻经络则作痛拘急；水饮风痰内", "c": "主肝郁气逆"}, {"id": "c:弦+散", "n": "弦散脉", "o": "弦散脉总起来主肝气失和、营卫不调、阴亏气弱与胃气不复数端。其脉以弦为肝木之征，散则示正气耗散、阴液亏虚；弦而不散者，肝气虽平而未和；兼软数者，气弱而虚热内生。诸类之间相互关联：肝气不和则疏泄失职，影响营卫调和；营卫不调又耗伤阴液，阴损及气则胃气难复。故本脉所主", "c": "主肝气未和"}, {"id": "c:数+弦+促", "n": "弦数促脉", "o": "弦数促脉总属火郁热盛、气机壅滞之候。弦为肝火、痰饮或木旺克土，数主热盛，促示火急气促或郁滞不畅。所主病机主要有四类：火盛气逆，迫血妄行，甚则喘脱；郁火内扰，土虚木乘；痰热内伏，暑邪交阻；风温外袭，温散劫津。四类之间相互关联：火盛气逆为极重之候，郁火内扰多兼脾虚", "c": "主火盛气逆"}, {"id": "c:数+弦+和", "n": "弦数和脉", "o": "弦数和脉总起来主肝郁化火、阴虚火旺、疟邪郁热、脾虚湿困及邪减向愈等病机。弦为肝郁，数为热，二脉相合，多示肝气郁结，郁而化火，火热内扰。若兼细数，则阴液亏耗，水不制火，肝阳上僭；若兼不和，则邪郁不达，常见于疟疾，湿郁化热；若兼细濡涩，则脾虚湿胜，肝木犯土。诸类之", "c": "主肝郁化火"}, {"id": "c:数+弦+坚", "n": "弦数坚脉", "o": "弦数坚脉总起来主实邪壅盛，包括瘀血、痰积、实热和疼痛。其脉象弦而数、坚劲搏指，反映邪气胶结、气血壅滞。弦为痛为积，数为热，坚劲搏指为实邪亢盛。各类病机相互关联：瘀血与痰积常互结，郁久化热，形成实热；实邪阻滞络脉，不通则痛。故治疗当攻下瘀痰，瘀去则热消痛止。此脉", "c": "主瘀血"}, {"id": "c:数+弦+大+和", "n": "弦数大和脉", "o": "弦数大脉总起来主肝郁化火、热伤血络、气血乖违。弦为肝郁，数为热，大为邪盛，三脉并见，示肝郁化火，热壅气滞，动营伤络，气血失和。原文‘嗜酒之体’‘过投辛燥热药’致‘动营壅腑’，鼻血腹胀，又进肾气丸后咳嗽失血失音，脉象弦数，气血乖远，大失冲和。可见弦数大脉以肝郁化", "c": "主肝郁化火"}, {"id": "c:数+弦+实", "n": "弦数实脉", "o": "弦数实脉总起来主邪实内盛、热壅气滞之证。数主热、主邪盛，实主邪实内结，弦主气滞、主痛、主经气不利，三象相合，反映热邪与实邪互结，气机壅滞，经气不舒。其具体病机可分为四类：热盛是核心，痰热、少阳郁热是热与痰、与枢机不利相合的具体表现，经气不利则是邪实壅阻经络的结", "c": "主热盛"}, {"id": "c:数+弦+平", "n": "弦数平脉", "o": "弦数平脉总起来主肝火渐退而心肾亏虚、痰浊内阻之病机。弦数本主肝经火热，脉较平说明肝火已减，但虚象更见，揭示心肾两亏为病本。心肾亏虚则遗泄连作，诸证纷沓；清升浊降不利则痰重、足痛步艰、耳鸣堵闷。三类病机相互关联：肝火渐退是邪气衰减，心肾亏虚是正气不足，痰重是升降", "c": "主肝火渐退"}, {"id": "c:数+弦+急", "n": "弦数急脉", "o": "弦数急脉总起来主邪热内盛、木火亢盛之实，并可见于湿热、肝火、暑风、木火刑金及脱营等证。弦主痛、主风动、主肝木，数主热、主火，急主气逆势迫，三者相合，反映邪热内炽、木火亢盛、气逆不通之病机。其类别之间，湿热阻络、肝火内炽、暑风外袭、木火刑金均属实证热证，而脱营则", "c": "主湿热"}, {"id": "c:数+弦+滑+濡", "n": "弦数濡滑脉", "o": "弦数濡滑脉总起来主余温留恋、痰湿中阻、厥阳升腾三类病机。左弦数主少阳余温，右濡滑主痰湿中阻，二者合见，说明温病后期余邪未清而痰湿内蕴，余温又可引动厥阳升腾。三类之间相互关联：余温留恋是病之本，痰湿中阻是病之标，厥阳升腾是余温与痰湿交互作用之变。原文以“滋阴则留", "c": "主余温留恋"}, {"id": "c:数+弦+濡", "n": "弦数濡脉", "o": "弦数濡脉总起来主湿热、痰热、虚热、肝郁、脾虚湿困、温毒及疟疾等多类病机。其核心在于弦主肝郁气滞，数主热，濡主湿，三者相合，常示湿热内蕴、痰热互结或虚热内生。从原文看，弦数偏于肝胆郁热，濡数偏于湿与热合，弦濡数并见则多属湿热壅遏、气机逆乱。各类之间相互关联：湿热", "c": "主湿热"}, {"id": "c:数+弦+疾", "n": "弦数疾脉", "o": "弦数疾脉总起来主邪热炽盛、郁结于内、阴液耗伤之病机。弦为邪郁，数疾为热极，三象并见，示邪热鸱张而郁结不散，热盛则阴伤，甚则内闭心包或引动肝风。其具体所主，可因邪之部位与兼症不同而有所偏重：或热陷营阴、内闭心包（如）；或邪热炽盛、阴液耗伤、肝风内动（如）；或疟邪", "c": "主热盛"}, {"id": "c:数+弦+结", "n": "弦数结脉", "o": "弦数结脉总起来主肝火内扰、营络瘀滞、血不归经之病机。弦为肝旺，数为火动，结示气火郁结，三者相合，说明肝火亢盛，气机壅滞，火迫血动而络瘀。其病机核心是肝火，火动则血不安，气结则络不畅，故临床可见崩漏屡发、经阻等症。三类病机相互关联：肝火是根源，火郁气结导致营络瘀", "c": "主肝火"}, {"id": "c:数+弦+缓+和", "n": "弦数缓和脉", "o": "弦数缓和脉在此段中并非单一主病，而是动态反映邪正消长与脏腑虚实。右脉弦数转为缓和，是邪气减半、胃气渐复的向愈之象，故主邪减向愈；左脉细小无神，则主真阴不足，为病本之虚；关部带弦，弦主肝，因真阴亏虚不能涵养肝木，肝木顺乘土中，故又主肝木犯土。三类病机相互关联：真", "c": "主邪减向愈"}, {"id": "c:数+弦+缓", "n": "弦数缓脉", "o": "弦数缓脉总以弦数为主，缓为兼象，所主病机涉及肝火、邪退、阴亏、木犯土及内风等多方面。弦数主肝火亢盛或热势留恋，缓则示火势渐退、胃气渐和，故脉由弦数转缓多为邪减向愈之佳兆。若兼左脉细小无神，则主真阴不足，阴亏不能涵养肝木，肝木顺乘中土，可见肝木犯土之机。若弦缓并", "c": "主邪减向愈"}, {"id": "c:数+弦", "n": "弦数脉", "o": "弦数脉总以弦为肝郁气滞、数为热象为基本脉理，所主病机广泛，可归纳为肝郁化火、肝胆湿热、痰热内蕴、阴虚火旺、风热外袭、瘀热互结、疟邪郁于少阳、积热内结等类。其中肝郁化火与阴虚火旺常互为因果，肝郁日久化火伤阴，阴虚火旺又致肝木偏亢；湿热、痰热、瘀热多由气郁化火、灼", "c": "主肝郁化火"}, {"id": "c:数+弦+滑+软", "n": "弦数软滑脉", "o": "弦数软滑脉总属痰湿内蕴、郁热化火、阴液亏虚、风阳内动之候。其核心病机为痰湿化热，本虚标实，涉及肺、肝、胃等多脏。弦主饮癖，数主热，软为虚（阴亏），滑主痰，四者相合，揭示痰湿壅塞、气机郁滞、久郁化热、热盛风动、阴液受灼之病机。各段原文均见痰湿、热盛、阴亏、风动相", "c": "主痰湿"}, {"id": "c:数+弦+微+洪", "n": "弦洪微数脉", "o": "弦洪微数脉在此段专指外感咳嗽邪甚之脉象，总属外感邪实、正气未虚之候。其病机核心为外邪犯肺、邪郁气机、寒热错杂：弦主气郁与寒，洪数主邪热与正邪交争，微数又示邪虽盛而正气尚未大虚。原文以‘素无积劳虚损而陡病’与内伤咳嗽之‘细数弦紧’对举，强调此脉随邪而变，非阴虚火", "c": "主外感邪盛"}, {"id": "c:数+弦+洪", "n": "弦洪数脉", "o": "弦洪数脉总属热盛邪实之候，以洪数主火热亢盛，弦主肝郁、风动、痰滞或痛。其病机可归纳为热盛、肝火、血热、痰火、风热、湿热、瘀热七类，彼此常相兼夹：热盛为共同基础，肝火易化风动，血热则迫血妄行，痰火每上攻清窍，风热多郁于筋脉，湿热常滞于肠胃，瘀热则搏结血分。原文诸", "c": "主热盛"}, {"id": "c:数+弦+洪+涩", "n": "弦洪涩数脉", "o": "弦洪涩数脉总起来主木火亢盛、阴伤血滞、肝阳上僭与正气溃败。弦洪数主木火亢盛，为病之标；涩主阴伤血滞，为热灼日久、阴液耗损之果；上溢示肝阳上僭，为木火挟痰上逆之势；而右脉软滑大无神，则示胃气已败、正气溃败，为病之本。四类病机相互交织：木火亢盛则灼阴耗血，阴伤血滞", "c": "主木火亢盛"}, {"id": "c:数+弦+滑+洪", "n": "弦洪滑数脉", "o": "弦洪滑数脉总起来主热盛、痰热、肝风及热迫营血。洪脉为热盛之标志，数脉主火，滑脉主痰，弦脉主肝风。四者相合，常见于温邪、暑湿等外感热病过程中，邪热炽盛，炼液为痰，痰热内壅，进而引动肝风，或热迫营血。各病机之间关系密切：热盛是基础，痰热由热灼津液而成，肝风因热极而", "c": "主痰热"}, {"id": "c:弦+洪+疾", "n": "弦洪疾脉", "o": "弦洪疾脉总起来主郁火内燔兼气血两亏之虚实夹杂证。其浮取弦洪疾驶，反映郁火亢盛、热势急迫，火郁上扰则头面赤肿、烦燥不眠；重按细软，则揭示高年气血根本虚衰。二者并见，说明此脉所主非单纯实火或纯虚，而是本虚标实、火郁于内而气血不足之候。临床当养血清火，不可仅从外疡论", "c": "主郁火"}, {"id": "c:弦+细+洪+小", "n": "弦洪细小脉", "o": "弦洪细小脉总起来主热毒壅盛而营血不足、毒陷于里之病机。弦洪为气火有余、热毒壅盛之象，细小为营血不足、毒陷于里之征。二者并见，说明毒盛而正伤，外有热毒壅盛，内兼血虚正伤，毒邪有内陷之势。三类病机相互关联：热毒壅盛为病之标，血虚正伤为病之本，毒陷于里为病之变。脉象", "c": "主热毒壅盛"}, {"id": "c:弦+洪+缓", "n": "弦洪缓脉", "o": "弦洪缓脉总起来主风热内陷、气机郁滞、湿热内蕴与脾虚湿困四类病机，且常相互兼夹。其脉象弦洪缓相合而按之无力，弦在其上，洪缓并见，提示风热之邪内陷阴分，阳气不得宣通，同时肝郁气滞、湿热内蕴，进而困阻脾胃，导致气机升降失常。原文所载麻木、肢节烦疼、身体沉重、胸满短气", "c": "主风热内陷"}, {"id": "c:弦+洪", "n": "弦洪脉", "o": "弦洪脉总属热盛邪实之候，以洪主火热亢盛，弦主肝郁、风动、痰滞或痛。其病机可归纳为热盛、肝火、血热、风火痰、虚火五类，彼此常相兼夹：热盛为共同基础，肝火易化风动，血热则迫血妄行，风火痰每上攻清窍或阻络，虚火则浮越于外。原文中弦洪刚甚、弦洪且大且数、左脉弦洪等，多", "c": "主热盛"}, {"id": "c:弦+洪+芤", "n": "弦洪芤脉", "o": "弦洪芤脉总起来主热亢阴虚、肝阳偏亢、迫血妄行之病机。其中洪脉主热盛，为邪热亢盛、气血涌盛之象；弦脉主肝阳亢逆，因肝阳偏亢、气火上升而脉气紧张；芤脉主阴血亏虚，因阴血耗损、脉道不充而中空。三脉并见，则示热盛与阴伤并存，即原文所谓‘热亢阴虚’、‘热实阴虚’。热盛可", "c": "主热亢阴虚"}, {"id": "c:弦+大+浮+短", "n": "弦浮大短脉", "o": "弦浮大短脉总属邪实壅盛、三阳合病之象。弦主少阳枢机不利，浮主邪郁肌表，大主阳明热盛，短气为气机壅滞之征。其病机核心为外邪侵袭、表里俱病，进而湿热郁蒸、气机壅滞。三类病机相互关联：少阳阳明合病为始，湿热郁蒸发黄为进展，气机壅滞贯穿始终。脉象未大坏者，提示正气尚存", "c": "主少阳阳明合病"}, {"id": "c:弦+浮+涩", "n": "弦浮涩脉", "o": "弦浮涩脉总起来主肝郁脾困、虚损胀满之病机。左弦为肝木怫郁，右浮涩为脾土自困、清浊混淆，三脉合见，反映肝郁乘脾、气机壅滞、清浊相干之候。其病机演变由肝郁始动，进而脾困失运，清浊混淆，胀势乃成；久则藏真日漓、府阳不运，转为虚损内伤。故本脉所主以肝郁、脾困、胀满、虚", "c": "主肝郁"}, {"id": "c:弦+涩+弱", "n": "弦涩弱脉", "o": "弦涩弱脉总属本虚标实、虚实夹杂之候。弱脉主气虚阳弱，为病之本；弦脉主痛、主饮，涩脉主血瘀湿滞，为病之标。左弦涩为肝血郁滞，右弱为肺气不足，示气机升降失司、金不制木；迟弱弦涩脉以阳虚为本，痛、饮、瘀滞为标；微弱弦涩脉则总主血虚，涉及肝脾亏虚。各类病机相互关联：阳", "c": "主气虚阳弱"}, {"id": "c:数+弦+涩", "n": "弦涩数脉", "o": "弦涩数脉总起来主气郁血滞、郁热内蕴之病机。弦主肝胆气郁，涩主血行滞涩，数主热象，三脉并见，提示气机郁结、血行不畅，郁而化热。其具体病机可因体质、病程不同而有所侧重：或为情志郁勃、肝郁化火，火动风升；或为瘀血内阻、瘀热互结；或为阴虚火旺、本虚标热；或为伏邪内发、", "c": "主瘀热互结"}, {"id": "c:弦+涩+结", "n": "弦涩结脉", "o": "弦涩结脉总属虚中夹实、气血郁滞之象。弦主肝郁，涩主血少，结为气滞血瘀，尺弱为肾虚，四者相合，反映肝脾两经气血两伤、邪气内结之病机。其核心在于“内伤重而外感轻”，因劳倦伤脾、郁怒伤肝，致肝脾气血亏虚，气虚推动无力，血少脉道不充，加之肝郁气滞，血行不畅，瘀血内结，", "c": "主肝郁气滞"}, {"id": "c:弦+涩+缓", "n": "弦涩缓脉", "o": "弦涩缓脉总起来主阴血亏少、气机郁滞、脾土受克之病机。其核心在于'弦'主肝木气郁，'涩'主血少行滞，'缓'主脾湿，三脉合见，提示肝木凌脾、血液枯槁，或气郁湿滞、渐入血分。若兼尺脉浮而无根，则进一步揭示肾水亏乏、根本已虚。诸类之间相互关联：肾水亏乏则肝木失养而亢逆", "c": "主气郁湿滞"}, {"id": "c:弦+涩", "n": "弦涩脉", "o": "弦涩脉总属气机郁滞与血行不畅相兼之象，其核心病机为气滞血瘀，但因兼脉及体质不同，可演化为多类。弦主气郁、肝旺、饮邪、痛证，涩主血少、湿滞、瘀结，二者相合，既可见于实证之痰饮积滞、寒湿痹阻、郁热瘀结，亦可见于虚证之阴血亏虚、虚风内动，以及虚实夹杂之肝郁乘脾。各类", "c": "主气滞血瘀"}, {"id": "c:弦+滑+动", "n": "弦滑动脉", "o": "弦滑动脉总起来主妊娠、热、气郁与痰湿。原文以‘左脉弦滑流动’断为妊象，因妊娠气血充盛、胎气搏结而脉见弦滑流动；然同一脉象又伴气急脘痞咳嗽、形肉日瘦，乃热气上乘迫肺、烁阴耗气之征，故脉亦主热。弦主气郁，滑主痰湿，气郁可致津液不布而生痰湿，痰湿内停又加重气机郁滞，", "c": "主妊"}, {"id": "c:弦+滑+和", "n": "弦滑和脉", "o": "弦滑和脉总起来主气机郁滞、痰湿内停及肝胃不和。弦主气郁，滑主痰湿，二者相兼，常因气郁津凝而生痰湿，痰湿内阻又加重气滞，形成恶性循环。原文脉象稍退、柔和，伴胀满舒、能安谷，说明郁解湿化，胃气渐和。三证相互关联，气郁为始动，痰湿为病理产物，肝胃不和为病位所在，治疗", "c": "主气郁"}, {"id": "c:弦+滑+大", "n": "弦滑大脉", "o": "弦滑大脉总起来主痰湿、热盛、肝风、伏邪及虚中夹实五类病机，其中痰湿与热盛为核心，常相兼为患。弦主痰饮、肝风与伏邪郁遏，滑主痰湿内蕴，大主热盛、邪实壅聚或中气虚弱。诸类之间关系密切：痰湿郁久化热则成痰热，肝风挟痰上扰则风痰阻络，伏邪内蕴每兼痰湿与热势鸱张，而虚体", "c": "主痰湿"}, {"id": "c:弦+滑+实", "n": "弦滑实脉", "o": "弦滑实脉总起来主邪热内传、腑实热结之证，兼涉痰热内壅与气机郁结。其脉弦主气机壅塞、热郁气结，滑主痰热内壅，实主邪气盛而正未虚。三者相合，多见于外感热病邪归阳明、燥实内结之候，如原文所载石芷卿患感，前医升散后热退复热，俟邪归于府，脉来弦滑而实，径用承气汤下之，下", "c": "主腑实热结"}, {"id": "c:弦+滑+平", "n": "弦滑平脉", "o": "弦滑平脉总起来主肝郁痰饮、气滞痰凝之实证，其脉象由弦与滑相合而成：弦主肝郁气滞，滑主痰饮内停，二者相兼，反映气机郁滞与痰浊内蕴相互为患。所抽样两段均明确以“弦滑为肝郁痰饮之脉”立论，并以脉象渐平作为肝气渐舒、痰饮渐化、邪退正复的判断依据，故其核心病机为肝郁痰饮", "c": "主肝郁痰饮"}, {"id": "c:数+弦+滑+微", "n": "弦滑微数脉", "o": "弦滑微数脉总起来主痰热内盛，兼有肝风、气郁及阴伤之变。弦主气郁、肝风，滑主痰，数主热，微数则示热盛而阴渐伤。各段所载，或痰热内闭心包而昏痉谵语，或肝风挟痰火上扰而目偏视、妄言，或气郁痰凝而寒热、偏左有形，或热盛伤阴而阴气渐伤。诸类之间，以痰热为核心，肝风、气郁", "c": "主痰热"}, {"id": "c:数+弦+滑+实", "n": "弦滑数实脉", "o": "弦滑数实脉总起来主实热壅盛、腑气不通，兼见虚中夹实、阴亏热恋之候。其脉弦主气机壅塞，滑主痰食积滞，数主热盛，实主邪实内结，四者相合，多见于热结阳明、腑实内闭之证，如原文所载渠女苔黄大渴、二便皆閟。然脉象亦可见于虚中夹实之候，如脉形虚大而热恋未净、阴亏不敛，或虚", "c": "主腑实热结"}, {"id": "c:数+弦+滑", "n": "弦滑数脉", "o": "弦滑数脉总起来主痰、热、气郁三者交结为患。弦主气滞、肝郁或肝火，滑主痰湿或痰饮，数主热或火，三象并见，故其核心病机为痰热内蕴、气机郁滞，进而可演变为湿热蕴蒸、肝火痰扰、疟邪郁于少阳、积热动血、阴虚火旺及气郁痰阻等证。各类之间以“痰热”为共同基础：湿热偏重者兼太", "c": "主痰热"}, {"id": "c:弦+细+滑+沉", "n": "弦滑沉细脉", "o": "弦滑沉细脉总起来主肝胆郁滞、痰饮内聚与里阳虚损三类病机，三者相互关联，形成本虚标实之证。弦滑主肝胆气郁、痰饮内聚，为病之标；沉细主阳虚于里，为病之本。原文以惊恐伤胆、抑郁动肝、思虑伤脾为起病之由，肝胆郁则气机不畅，脾阳不运则谷食不化变蒸为痰，痰饮袭于奇经、溢于", "c": "主肝胆郁"}, {"id": "c:弦+滑+大+洪", "n": "弦滑洪大脉", "o": "弦滑洪大脉总起来主痰湿、肝火、痰火及阳盛气浮之证。其脉象由弦、滑、洪大四象合参：弦主肝郁与痰饮，滑主痰湿，洪大主火盛与阳盛气浮。诸类病机相互关联，常相兼为患。如肝火郁于胃中，灼津为痰，则痰火互结；素嗜酒醴，湿热内蕴，则痰湿化热，流注经络。故本脉所主，总以痰、湿", "c": "主痰湿"}, {"id": "c:弦+滑+洪", "n": "弦滑洪脉", "o": "弦滑洪脉总起来主痰热内蕴、暑热炽盛及肝风痰火之证。其脉象由弦、滑、洪三象合参：弦主痰饮与肝郁，滑主痰湿，洪主热盛。三者相合，常见于痰湿内伏、郁而化热、痰热交蒸之候，或暑热内扰阳明、痰热蒙蔽心神之证。痰热为病机核心，热盛是基础，痰湿为病理产物，肝风为痰火煽动之变", "c": "主痰热内蕴"}, {"id": "c:弦+滑+涩", "n": "弦滑涩脉", "o": "弦滑涩脉总起来主肝郁脾困、湿浊夹瘀之证。弦脉主肝郁气滞，木旺乘脾；滑脉主湿浊内盛，壅阻中焦；涩脉主气血瘀滞，血行不畅。三者相合，反映肝木乘脾、湿浊盘踞、瘀血内阻的复合病机。其核心在于肝郁脾虚为本，湿浊与瘀血为标，标本兼见。弦滑示湿浊壅盛，涩示血行不畅，诸邪交阻", "c": "主肝郁乘脾"}, {"id": "c:弦+滑+空", "n": "弦滑空脉", "o": "弦滑空脉总起来主正虚邪恋、虚实夹杂之证。其弦滑反映风寒湿热等邪气未化，留滞于内；空象则揭示元气阳气内虚，正气不足。二者并见，说明邪气虽似有暗化之机，但正虚已显，形成虚中夹邪之局。三类病机相互关联：邪未化是病邪存在的前提，正内虚是体质基础，虚中夹邪则是二者交织的", "c": "主邪未化"}, {"id": "c:弦+细+滑+弱", "n": "弦滑细弱脉", "o": "弦滑细弱脉在此段中并非四脉同时并见，而是反映病机由实转虚的动态过程：前诊弦滑主痰火内盛之实，今转细弱主下元亏虚、邪退正伤之虚。总起来看，此脉所主以「下虚上实」为核心——上有痰火浊邪（弦滑之遗），下有肾元亏虚（细弱之现），而细弱为当前主要脉象，提示邪势已衰三舍、", "c": "主痰火内盛"}, {"id": "c:弦+滑+结", "n": "弦滑结脉", "o": "弦滑结脉总起来主肝火、痰壅、痰火交争及肾水不足之病机。右脉弦滑搏结，为肝火与痰浊交争之实证，火乘肺则吐血，痰遏脾胃则痫厥；左脉弦小，为肾水不足、不能涵木之虚象。四类病机中，肝火与痰壅是病邪之标，痰火交争为病势之剧，肾水不足为病本之虚。总属本虚标实、痰火内扰之候", "c": "主肝火"}, {"id": "c:弦+滑", "n": "弦滑脉", "o": "弦滑脉总起来主痰湿内蕴、气机郁滞，以痰浊为共同病理因素，弦主气郁、肝风或饮邪，滑主痰湿或痰热，二者相合，提示痰与气、热、风、食等交结为患。其病机大致可分六类：痰饮内停、气郁痰阻、痰热内蕴、肝风痰扰、疟邪痰滞及本虚标实。各类之间以“痰”为核心，或兼气滞，或兼热蕴", "c": "主痰饮内停"}, {"id": "c:弦+濡+弱", "n": "弦濡弱脉", "o": "弦濡弱脉总起来主肝郁脾虚、气血不足、湿邪内盛之证。其脉象由弦、濡、弱三象复合而成：弦主肝郁气滞，濡主湿盛，弱主气血亏虚。三类病机相互关联：肝郁可乘脾，致脾虚湿盛；脾虚日久则气血生化不足，形成气血两虚；湿邪内蕴又可化热或兼夹疟邪。从所举医案看，该脉多见于胁痛、泄", "c": "主肝郁乘脾"}, {"id": "c:弦+微+濡", "n": "弦濡微脉", "o": "弦濡微脉总起来主湿热内著、气滞湿阻、积滞中焦。弦主气滞，濡主湿盛，二者相合，反映湿邪与气滞交阻，进而形成湿热积滞。原文以'稚孩湿热内著，脉弦濡身微热，腹痛坚满，大便忽泻'为据，指出湿热积滞中焦、升降失司。三类病机相互关联：湿热内著是病之本，气滞湿阻为病之机，积", "c": "主湿热内著"}, {"id": "c:弦+牢", "n": "弦牢脉", "o": "弦牢脉总起来主气郁深固、痰实内壅之证。弦主气机郁滞，牢主病邪深结牢固，二者相合，提示气郁日久、病位深沉。本案左脉弦牢，候肝，知气郁于肝；右寸坚滑，候肺，知痰壅于肺。症见胸胁大痛、喘嗽不宁，正合肝郁气滞、痰阻肺络之病机。四类病机中，气郁为始因，病深牢固言其势，痰", "c": "主气郁"}, {"id": "c:弦+疾+促", "n": "弦疾促脉", "o": "弦疾促脉总起来主肝阳亢盛、痰火内扰，并可外感冬温挟痰而发。弦为肝脉，疾促示阳热急迫，故其核心病机为肝阳升动、痰火壅盛；右滑数而溢则专主痰热壅肺。三者相互关联：冬温挟痰阻肺，治节不伸，痰热内蕴则肝阳易亢，肝阳鼓舞直升又助痰火，形成痰热阻肺、肝阳上逆之候。故本脉虽", "c": "主肝阳亢盛"}, {"id": "c:弦+疾+坚", "n": "弦疾坚脉", "o": "弦疾坚脉总起来主气郁化火、痰热内结、邪势鸱张之实证。其形成多因平素饮食不节、气滞多痰，痰热内蕴，复感疟邪，或误投温补，致邪热深入，肝火亢盛，气机壅塞。脉象上，弦主气郁，疾主热盛，坚搏示邪结，三者相合，反映气郁、热盛、痰阻、邪结相互搏结的病理格局。各类病机之间关", "c": "主气郁"}, {"id": "c:弦+疾", "n": "弦疾脉", "o": "弦疾脉总起来主气郁热盛、痰热内结、邪热鸱张之实证。弦为气郁，疾为热盛，二者相合，反映气机壅塞与邪热炽盛并存。其形成多因平素饮食不节、气滞多痰，复感疟邪，或误投温补，致邪热深入，肝火亢盛，痰热与邪搏结。脉象上，弦主气郁，疾主热盛，坚搏示邪结，三者相互搏结，故见弦", "c": "主气郁热盛"}, {"id": "c:弦+涩+紧+短", "n": "弦短涩紧脉", "o": "弦短涩紧脉总属寒凝气滞、气血涩滞之候，主要主寒、主痛、主气血涩滞及气病。四者相互关联：寒邪凝滞为病因，导致气血运行不畅（涩、短），进而引发疼痛（弦、紧）。原文以寒痹为例，脉弦短涩而紧，痛连少腹，兼痰饮胃痛，正是寒凝气滞、气血涩滞的综合表现。各病机类别虽各有侧重", "c": "主寒凝"}, {"id": "c:弦+短", "n": "弦短脉", "o": "弦短脉在本段所主，总以肝郁气滞、水湿不运为核心，进而累及血分与脾运。脉弦为肝木乘脾之象，肝失疏泄则气机壅滞，脾不运湿则水谷之湿内停，故见溺短、黄肿、脘腹膨胀；气滞日久则血稽留少腹成瘕、脘中聚痞，形成气、水、血交结之肿胀重症。四类病机相互关联：肝郁乘脾为始动环节", "c": "主肝郁乘脾"}, {"id": "c:弦+和+硬", "n": "弦硬和脉", "o": "弦硬和脉总起来主肝盛、脾伤、肺伤、阴虚阳亢及肝胆留邪等病机。弦为肝脉，肝盛则脉弦硬而不和缓；脉失和缓之脾土之气，是脾气受伤；肺金受伤不能镇肝，致肝木偏亢而脉弦。三者相互关联：肝盛侮脾，脾伤则土不培金，肺金亦伤；肺伤则金不制木，肝愈横。若真阴亏虚，阴不涵阳，则肝", "c": "主肝盛"}, {"id": "c:弦+大+硬", "n": "弦硬大脉", "o": "弦硬大脉总起来主气机逆乱、根基不固之病机，以冲气上逆、真气外泄、肝风内动、肝阳上亢四类为主。其脉弦主肝与冲脉为病，硬主劲急失柔，大主气化外越或虚张。四类之间相互关联：冲气上逆与真气外泄常并见，为脾胃真气不固、冲脉逆气上干；肝风内动与肝阳上亢则属肝经病变，风阳鼓", "c": "主冲气上逆"}, {"id": "c:弦+平+硬", "n": "弦硬平脉", "o": "弦硬平脉总属虚实夹杂之象。其脉虽较前和平，但弦硬之意未除，表明病势已减而根蒂未拔。所主病机主要有三：一为脾土衰败，右脉歇止渐见，中气亦竭，胃气衰败；二为肝阳未柔，左脉弦硬固平，阴不涵阳致肝阳偏亢；三为虚实夹杂，弦硬与歇止并见，正虚邪恋。三者相互关联，以脾土衰败", "c": "主脾土衰败"}, {"id": "c:数+弦+微+硬", "n": "弦硬微数脉", "o": "弦硬微数脉总起来主血虚生热、心脾两虚之病机。弦硬为肝血不足、筋脉失养之象，微数主虚热内扰，二者相合，反映阴血亏虚、虚热内生。原文附案中少年怔忡不寐，脉见弦硬微数，断为心脾血液短少，心失所养则怔忡，神不守舍则不寐，龙眼肉补心脾、益气血而病除。三类病机相互关联：血", "c": "主血虚"}, {"id": "c:弦+急+硬", "n": "弦硬急脉", "o": "弦硬急脉总起来主虚气上逆。此脉虽弦硬急似有力，实非实热，而是下元虚损、中气衰惫，冲胃之气因虚上逆，致脉失柔和。其病机核心为虚，逆为标象，故见吐衄之证。临床当识其‘转似有力’之假象，勿作实热攻伐。", "c": "主虚气上逆"}, {"id": "c:弦+沉+硬", "n": "弦硬沉脉", "o": "弦硬沉脉总起来主肝经病变，以肝郁气结为核心，气郁化火伤阴则致血虚火旺，肝木亢盛则克伐脾土，形成木旺克土、脾胃虚弱之候。三类病机相互关联：肝郁气结为始动因素，气郁日久化火伤阴，故见血虚火旺；肝旺则乘脾，导致脾胃健运失职。原文左脉弦硬而沉，右脉弦而无力，正是肝病及", "c": "肝郁气结"}, {"id": "c:弦+浮+硬", "n": "弦硬浮脉", "o": "弦硬浮脉总起来主肝胆火盛、阴虚阳亢、气血两虚及热痰中焦等病机。其核心为肝火亢盛与阴血亏虚并存：弦主肝，硬主火，浮主上炎，故见火热上冲头目；若重按无力，则示阴血不足、阳气外浮，成阴虚阳亢之候。若见于体弱经闭者，又为气血两虚、冲脉不充之本虚标实。兼右脉沉滑、舌苔黏", "c": "主肝胆火盛"}, {"id": "c:弦+硬", "n": "弦硬脉", "o": "弦硬脉总起来主肝火亢盛、阴亏失柔、气逆上冲、胃气衰败、木乘土位及痰热瘀滞等病机。其核心在于“弦主肝，硬主劲急”，反映肝木刚劲失和、气机升降失常。肝火亢盛与阴亏失柔常互为因果：火盛灼阴，阴亏则木失濡养，脉更弦硬；气逆上冲多由肝火挟冲胃之气上逆，血随气升，甚则昏厥", "c": "主肝火亢盛"}, {"id": "c:弦+长+硬", "n": "弦硬长脉", "o": "弦硬长脉总起来主气机逆乱、火盛阴亏之证，以肝、胃、冲脉气火上逆为核心。其脉弦主肝，硬主劲急亢盛，长主气逆有余，故凡见弦硬而长，多示脏腑气化有升无降，气血随之上冲。具体而言，或为肝胆之火上冲，或为冲气挟胃气上逆，或为血随气升充塞脑部而成厥证，或为火盛灼阴、阴分亏", "c": "主肝火冲逆"}, {"id": "c:弦+濡+空", "n": "弦空濡脉", "o": "弦空濡脉总起来主络血不宁、形神两伤、气血耗损三类病机。右脉弦空，弦为络血不宁，空为形神两伤；左脉濡，濡为气血耗损。三者相互关联：长期经营耗伤气血，气血亏虚则形神失养，络脉不宁，血不循经而吐血频发。弦为病之标，空、濡为病之本，本虚标实，形神两伤，故脉象复合弦空濡", "c": "主络血不宁"}, {"id": "c:弦+紧+和", "n": "弦紧和脉", "o": "弦紧和脉总起来主正虚邪恋、阳气衰弱、痰湿稽留与肝胃气滞。其脉象以弦紧渐和或转和为核心特征，多出现在邪气渐退而正气未复的阶段。三则原文均见弦紧缓和之象，但兼尺部沉细者，侧重肾阳早亏、宗气不布，属阳气衰弱、正虚邪恋；兼苔腻、肢废者，侧重痰湿盘踞、藉阳始化；兼胸闷纳", "c": "主阳气衰弱"}, {"id": "c:弦+紧+实", "n": "弦紧实脉", "o": "弦紧实脉总起来主实证，具体包括气滞、寒凝、邪结三类病机。弦主厥阴气滞，紧主寒凝收引，实主邪结有形，三者相兼，反映寒凝气滞、结聚不散之候。原文'寒热之后，厥阴气滞，小腹痞痛，归于右偏，脉弦紧实者，宜疏'，说明此脉主邪实壅盛，治宜疏达行气散结。三类病机相互关联：气", "c": "主气滞"}, {"id": "c:弦+弱+紧", "n": "弦紧弱脉", "o": "弦紧弱脉在此二段中，实以弱脉为辨证核心。弦紧为伤寒表实寒凝之常脉，今脉不弦紧而弱，说明病机已非单纯表寒，而是津血不足、正气已虚。弱脉总主津血亏虚，故见口渴；若兼发热脉浮，则示表邪未罢而正虚，治当汗解，不可攻下；若误被火攻，则火邪内迫，津伤更甚，热扰神明而谵语。", "c": "主津血不足"}, {"id": "c:弦+紧+急", "n": "弦紧急脉", "o": "弦紧急脉总起来主邪实与正虚两类病机。其脉象弦紧劲急，既可见于实火毒结肠胃之实证，因火毒炽盛、邪势鸱张，脉应其势而劲急不为指挠；又可见于血虚风动之虚证，因劳倦伤血、疮后血虚，风寒乘虚而入，筋脉失养而挛急，脉见弦紧而急如真弦。两类病机虽一实一虚，但均以“急”为共同", "c": "主实火毒结"}, {"id": "c:数+弦+紧+疾", "n": "弦紧数疾脉", "o": "弦紧数疾脉总起来主邪毒炽盛、热结深重之候。弦紧主邪结，数疾主热盛，四象并见，示余毒蕴隆、邪热鸱张，属毒热壅盛、气机壅滞之病机。其症多见咽痛碍食、颐肿舌糜、牙关紧、痰嗽胁疼、溺赤管痛、便溏色酱等，皆邪毒炽盛、热结于内之征。此类脉象提示邪毒深重、正气难支，故预后不", "c": "主热盛"}, {"id": "c:数+弦+紧", "n": "弦紧数脉", "o": "弦紧数脉总以弦紧主寒、主痛、主饮、主气机凝滞，数主热、主郁火为基本框架。其病机可归纳为寒热错杂两端：或外寒束表而内热郁发，或饮邪、痰浊、湿积内结而郁而化热，或寒积内结而数非真热，或风热壅盛表里俱实，或瘀热交阻而正虚邪实，或寒邪久郁伏而不散。各类之间以“寒束”与", "c": "主寒束热郁"}, {"id": "c:弦+滑+沉+浮+涩+紧", "n": "弦紧浮滑沉涩脉", "o": "弦紧浮滑沉涩六脉，总属“残贼”之脉，各主邪气为病，能为诸脉作病。其病机可归纳为痛、寒、表、痰、里、血少六类，分别对应弦、紧、浮、滑、沉、涩。此六脉虽各有所主，但均反映邪气侵袭或气血失调，非正常脉象。临床见此类脉，提示病邪存在，需结合具体脉象辨析邪气性质与病位，", "c": "主痛"}, {"id": "c:弦+滑+紧", "n": "弦紧滑脉", "o": "弦紧滑脉总起来主痰饮、寒饮、阳郁阴结及痰湿阴邪为患。其脉象由弦、紧、滑三象复合而成：弦主饮、主痛、主气机郁滞；紧主寒、主收引；滑主痰湿。三者相合，提示寒邪与痰饮交结，阳气被遏，阴邪内盛。从所收段落看，或见脾肾阳虚、痰饮上泛之咳嗽气急，或见胸阳不舒、阴邪微结之胸", "c": "主痰饮"}, {"id": "c:弦+细+濡+紧", "n": "弦紧濡细脉", "o": "弦紧濡细脉总起来主营血亏虚、瘀血内阻与湿邪下注互结之病机。弦紧应指，为宿瘀内阻、气机不畅之征；濡细之象，既主营血亏虚，又主湿邪困阻。三者相合，示产后营血已亏，宿瘀未楚，挟湿下注膀胱，宣化失司，故见腹痛、小溲淋漓。各类之间相互关联：血亏为病之本，瘀滞与湿注为病之", "c": "主瘀滞"}, {"id": "c:弦+紧+硬", "n": "弦紧硬脉", "o": "弦紧硬脉总起来主寒凝、痛与肾虚寒。紧硬为寒邪收引凝滞之象，弦主痛、主肾，两尺尤甚则病位在肾。三者相互关联：寒凝收引导致气滞不通，不通则痛；寒邪伤及肾阳，肾阳虚衰则下焦虚寒，寒凝更甚。原文所载痢疾案，因平素中寒，又食寒凉，致肾阳虚衰，寒凝气滞，故脉双弦紧硬而两尺", "c": "主寒凝"}, {"id": "c:弦+细+微+紧", "n": "弦紧细微脉", "o": "弦紧细微脉总起来主积、主寒痛、主正虚邪结。其核心病机为寒邪与气血搏结，久积成块，兼有正气渐伤。弦紧主寒、主痛、主积，细微示正虚，细软附骨说明积块深伏。原文以“脉来细软附骨者，为积也”定积脉之形，又言“脉弦紧而细微者，症也”，故本脉所主以腹中积聚、症瘕、寒疝急痛", "c": "主积"}, {"id": "c:弦+紧", "n": "弦紧脉", "o": "弦紧脉总以寒、痛、气滞、饮积为核心，兼涉郁热、肝郁、外邪。弦为肝脉，主气郁、主饮、主痛；紧为寒脉，主寒、主痛、主结。二脉相合，脉道拘急，气血壅滞，故其主病首在寒凝气滞，不通则痛；进而寒饮痰湿内停、寒积内结成块、阳虚寒盛不运，皆属阴寒之变。然弦紧亦可见于郁热化火", "c": "主寒凝气滞"}, {"id": "c:弦+涩+紧+迟", "n": "弦紧迟涩脉", "o": "弦紧迟涩脉总起来主寒凝气滞、食积中阻之实证。左弦紧为寒邪引动厥气上逆、肝脉拘急；右迟涩为寒凝气滞、食滞交阻中宫。三类病机相互关联：外寒引动厥气上逆，气逆则食滞不化，食滞又加重气机壅塞，形成寒、气、食交阻之势。脉象弦紧迟涩并见，正是寒邪、气逆、食滞三者交织的反映", "c": "主寒凝气滞"}, {"id": "c:弦+紧+长", "n": "弦紧长脉", "o": "弦紧长脉总起来主肝郁寒凝、气滞邪实，本于肝病而累及他脏。弦主肝郁，紧主寒痛，长主气滞邪实，三象合见，提示肝气郁结、寒邪凝滞、气机壅塞、邪实有余。其病机核心在肝：肝郁日久，气机不畅，则脉弦；寒凝经脉，拘急疼痛，则脉紧；邪实内结，气滞不通，则脉长。肝病及脾，木克脾", "c": "主肝郁"}, {"id": "c:数+弦+细+促", "n": "弦细促数脉", "o": "弦细促数脉总属危候，主阴液枯槁、正气虚匮，兼邪郁化热、气逆神乱。其脉弦细为阴血津液枯竭、脉道失养；促数为邪热内郁、气逆不降；右部虚散为正气衰败、元气涣散。四类病机相互关联：温涩太过先致邪郁化热，热灼阴津则阴液枯槁，阴伤及气则正气虚匮，邪热内陷则气逆神乱。总因伏", "c": "主阴液枯槁"}, {"id": "c:弦+细+促", "n": "弦细促脉", "o": "弦细促脉总属虚实夹杂、正虚邪盛之危候。其核心病机为阴液枯竭、邪热内盛，二者互为因果：温燥太过先致邪郁化热，热灼阴津则阴液枯槁，阴伤及气则正气虚匮，终致正虚邪陷。弦细主阴血津液亏耗、脉道失养；促主热盛或气滞血瘀、郁而化热。三处原文均见舌绛大渴、小溲赤少、饮而不食", "c": "主阴液枯竭"}, {"id": "c:数+弦+细+小", "n": "弦细小数脉", "o": "弦细小数脉总起来主阴血亏虚、郁热内扰之证。其脉象要素中，细与小主阴血不足、荣卫两虚；数主有热，或为虚热，或为郁热；弦主肝郁、主疟、主邪郁、主痛。诸段所涉病机虽异，然多围绕阴虚与郁热两端：或阴亏火旺而见内热、淋痛、尿血；或肝郁化火而寒热、腹痛、溺痛；或邪郁半表半", "c": "主阴虚内热"}, {"id": "c:弦+细+微", "n": "弦细微脉", "o": "弦细微脉总起来主虚证，以阳气衰微、气血两虚为本，常兼寒凝、肝郁等标象。其核心病机为正气亏虚：微为阳气衰微，细为阴血不足，弦为气机郁滞或寒痛。各类之间相互关联：阳虚气弱可导致虚寒内盛，寒凝又伤阳；气血两虚则肝失濡养，肝郁乘土，进一步损伤中气。原文多述年高气弱、久", "c": "主阳虚气弱"}, {"id": "c:弦+细+微+迟", "n": "弦细微迟脉", "o": "弦细微迟脉总属阴寒内盛、阳气衰微、阴血亏少之候。弦主阴结，细主血少，迟微主阳气内衰，四者相合，揭示虚寒性便血的核心病机。其类虽分阳衰、血少、阴结、便血，实则相互关联：阳气内衰则阴寒内结，阴结日久则血行不畅而便血，便血日久则阴血更亏，形成虚寒性出血的恶性循环。原", "c": "主阳衰"}, {"id": "c:弦+细+急+促", "n": "弦细急促脉", "o": "弦细急促脉总起来主木火亢盛、阴亏火旺、湿浊内蕴及正虚邪陷之病机。弦主木火，细促为阴亏火旺，濡滑主湿浊，不耐重按示正虚邪陷。诸类相互关联：阴液亏虚则不化气，气火内烁，湿浊蒸腾，木火夹浊为患；久病正虚，邪热内陷，病势深重。此脉以阴亏火旺为本，木火湿浊为标，正虚邪陷", "c": "主木火"}, {"id": "c:弦+细+急", "n": "弦细急脉", "o": "弦细急脉总起来主肝郁化热、阴亏火旺、筋脉拘急及虚实夹杂之病机。弦主少阳、主肝、主木火，细为阴伤血虚，急示邪郁化热或筋脉拘急。诸类相互关联：阴液亏虚则不化气，木火内炽，郁热内迫，故见弦细急；血虚则筋脉失养，风邪客之，筋急挛缩；情志郁结则气机不畅，木郁克土，心脾内", "c": "主肝郁化热"}, {"id": "c:数+弦+细", "n": "弦细数脉", "o": "弦细数脉总起来主阴血亏虚、虚热内扰，兼有肝郁化火、风痰湿热等邪实。细为阴血不足，数为热，弦为肝木偏旺或气机郁结。三者相合，常见于阴虚内热、虚劳损证、肝郁化火、风火痰热、少阳不和、湿热郁结及疟邪久踞等病机。各类之间相互关联：阴虚内热与虚劳损证以正虚为主，肝郁化火", "c": "主阴虚内热"}, {"id": "c:弦+细+沉+微", "n": "弦细沉微脉", "o": "弦细沉微脉总属阳虚寒凝、气化不行之候。其脉弦主痛主寒凝，细为阳虚血少，沉微则阳气衰微、阴寒内盛，不足四至更示阳衰。三者相合，反映阳气虚衰、阴寒内盛、寒凝气滞、气化失司之病机。寒凝与阳虚互为因果：阳虚生内寒，寒凝更伤阳；气化不行则由阳虚寒凝所致，故小便凝滞不出、", "c": "主寒凝"}, {"id": "c:弦+细+沉+濡", "n": "弦细沉濡脉", "o": "弦细沉濡脉总属湿邪为患，主湿郁、湿蕴阳郁及湿浊弥漫。弦细主湿郁，强调湿邪阻滞气机，脉道拘急而细；沉濡主湿邪内蕴、阳气不宣，突出湿浊在里，阳气被遏；脉象模糊则示湿浊弥漫三焦，脉道不清。三者相互关联，共同反映湿温病中湿浊偏盛、三焦气机壅滞、阳气不宣之病机。原文以通", "c": "主湿郁"}, {"id": "c:弦+细+浮", "n": "弦细浮脉", "o": "弦细浮脉总属虚实夹杂、本虚标实之象。弦主肝郁气滞，细主阴血不足，浮主虚阳外浮或余邪未尽。合而观之，其核心病机为阴血亏虚、肝郁化火、虚阳上浮，或气虚气郁、寒凝阳浮。五段所涉，或肝火上浮兼饮邪内伏，或阴虚阳浮禁投白虎，或虚寒阳浮火不归原，或气虚气郁脾虚肝乘，或邪郁", "c": "主肝郁阴伤"}, {"id": "c:弦+细+浮+革", "n": "弦细浮革脉", "o": "弦细浮革脉总起来主虚寒之机，核心为下焦火不足、沉寒痼冷。脉弱虚大无力示阳气不足，弦细示寒凝肝脉、气血收引，浮革示虚寒外浮、阳气不固，三者常相兼见，反映阳虚内寒、寒凝气机、虚阳外浮的病理链条。原文以肉桂辛热下行、益火消阴为治，正对虚寒之机；同时列出弦细数脉作为阴", "c": "主阳虚寒凝"}, {"id": "c:弦+细+涩", "n": "弦细涩脉", "o": "弦细涩脉总属虚实夹杂之象：弦主肝郁气滞、风动或饮邪，细主阴血亏虚，涩主血少、湿滞或瘀结。合而观之，其核心病机为阴血亏虚为本，气滞、湿痰、瘀血、风动为标。诸类之间相互关联：阴血亏虚可致肝失濡养而肝郁气滞，气滞湿阻则痰饮内停，久则血瘀内结；阴虚阳亢则虚风内动；正虚", "c": "主阴血亏虚"}, {"id": "c:弦+细+虚+涩", "n": "弦细涩虚脉", "o": "弦细涩虚脉总起来主脾虚湿困、气血不足、气滞血瘀、肺气不宣之候。其脉象复合，寸短主肺气不足，右脉弦细涩主血少气滞、脾虚湿困，关虚主脾胃虚弱。诸类病机相互关联：脾虚湿盛为根本，湿困中焦则气血生化不足，气血不足则肺气不宣，气滞血瘀则腹痛时作。故其病机以脾虚湿困为核心", "c": "主脾虚湿困"}, {"id": "c:弦+细+滑+大", "n": "弦细滑大脉", "o": "弦细滑大脉总起来主虚实夹杂之证，以心肾阴血不足为本、痰涎壅盛为标。左脉弦细反映心肾两虚，右脉滑大反映痰涎沃胆，二者并见提示正虚与邪实共存。原文‘神气模糊，夜不能寐，心忡，腰痛，舌苔黄垢’诸症，皆痰涎沃胆、心肾两虚之候，故治疗宜先清后补。三类病机中，主虚与主痰分", "c": "主虚"}, {"id": "c:弦+细+滑", "n": "弦细滑脉", "o": "弦细滑脉总起来主肝旺、阴血虚、痰湿内蕴三类基本病机，并由此衍生肝胃不和、痰火、本虚标实等复合病机。弦应肝，主肝气偏亢、肝火上逆；细应阴血，主阴血亏耗；滑应痰湿，主痰浊内阻。三者合见，说明肝旺与阴血不足并存，痰湿内滞其间，形成本虚标实、虚实夹杂之局。若肝旺犯胃，", "c": "主阴血虚"}, {"id": "c:数+弦+细+濡", "n": "弦细濡数脉", "o": "弦细濡数脉总起来主阴虚火旺、肝郁化火、暑湿伤阴、脾虚有热及肺燥阴伤等病机。其脉象由弦、细、濡、数四象复合而成：细主阴血不足，数主热盛，弦主肝郁气滞或邪郁，濡主湿困或气虚。诸段原文显示，该脉多出现于情志郁结化火、温病伏暑伤阴、肺痨阴亏等病程中，病机核心为阴液耗伤", "c": "主肝郁化火"}, {"id": "c:弦+细+濡", "n": "弦细濡脉", "o": "弦细濡脉总起来主湿、虚、热、郁相互夹杂之病机，其中以湿邪为患为核心，虚与郁为常见兼夹。弦主气机郁滞或肝郁，细主阴血不足或湿性黏滞，濡主湿盛或气虚阳不伸。诸段原文显示，该脉多见于湿温初起、湿疟、暑湿内陷、气血两虚兼热、肝郁血少湿滞及产后瘀湿互结等证。各类之间关系", "c": "主湿"}, {"id": "c:弦+细+涩+短", "n": "弦细短涩脉", "o": "弦细短涩脉总起来主痰饮内停、气血虚少、气滞血涩及阳络损伤之候。其脉象复合，弦主饮，细主虚，短涩主血少气滞，四者相合，揭示饮邪久留、正气渐伤、气血运行不畅之病机。各病机相互关联：痰饮内停为病之标，久病耗伤气血，致血少气滞；气血不足，络脉失养，阳络损伤则血上溢；吐", "c": "主饮"}, {"id": "c:弦+细+紧", "n": "弦细紧脉", "o": "弦细紧脉总以寒凝气滞、阳虚血少为纲。弦主肝郁气滞，紧主寒主痛，细主血少阳衰，三象合见，多示寒邪内凝、气机壅塞、营血不足之病机。其具体所主，或为寒凝疼痛，或为虚寒阳衰，或为肝郁气滞，或为血虚痰饮，然总不离“寒”与“虚”两端。寒凝则气滞，气滞则痛；阳虚则寒生，血少", "c": "主寒凝"}, {"id": "c:弦+细+紧+软", "n": "弦细紧软脉", "o": "弦细紧软脉总起来主寒饮内盛与气血不足，并见中虚寒逆之机。弦紧主寒饮内盛，细软主气血不足，二者相合，提示本虚标实：脾虚中冷、气血亏虚为本，寒痰饮邪内盛为标。原文患者平素脾虚中冷夹痰饮，生产多胎气虚，霍乱大吐后中虚更甚，寒痰上涌，遂致昏沉、抽搐等类中风之候。故该脉", "c": "主寒饮"}, {"id": "c:弦+细", "n": "弦细脉", "o": "弦细脉总以肝郁气滞、阴血亏虚为基本病机，并由此衍生肝阳上亢、寒凝阳虚、痰饮内停、脾虚木乘、正虚邪恋等复合病机。弦为肝木之象，主气郁、主痛、主饮、主风；细为阴血不足，主虚、主寒。二者相合，多示本虚标实、虚实夹杂之候。诸类之间相互关联：阴血亏虚可致肝失柔养而肝郁气", "c": "主肝郁气滞"}, {"id": "c:弦+细+芤", "n": "弦细芤脉", "o": "弦细芤脉总起来主肝郁血瘀、阴血亏虚及暑伤气阴。弦主肝郁气滞，细主阴血不足或气血瘀滞，芤主失血络伤、津血骤伤。三者相合，提示病机多属本虚标实：或肝郁乘胃、痛久入络而气血瘀损；或失血之后络脉空虚、阴血亏耗；或暑湿伤中、气阴两伤。各证虽异，但均以阴血亏虚为基础，兼有", "c": "主肝郁血瘀"}, {"id": "c:弦+细+迟+芤", "n": "弦细芤迟脉", "o": "弦细芤迟脉总起来主气阴两伤、阳衰血少，并常兼邪气内郁。其形成机理：弦细主阴寒拘急或暑湿伤阴，芤迟主阳衰血少、津气不充、鼓动无力。所主病机大致可分四类：一为暑伤气阴，见于太阳中暍，暑热耗气伤津；二为阳衰血少，见于真阳虚极、阴寒内盛；三为邪盛正虚，见于暑邪内陷、误", "c": "主暑伤气阴"}, {"id": "c:数+弦+细+虚", "n": "弦细虚数脉", "o": "弦细虚数脉总属阴虚阳浮、气血两虚之候，以阴血亏虚为本，虚阳浮动为标。弦为肝郁阳亢，细为阴血不足，虚为气耗，数为虚热。五段所主，或肝肾阴虚、虚阳上冒，或气血两虚、虚热内生，或肝阳上越、风阳浮动，或阴虚灼液、痰热搏结，或内损虚火伏藏。诸类皆以阴亏为基础，阳浮为共性", "c": "主阴虚阳浮"}, {"id": "c:弦+细+虚+濡", "n": "弦细虚濡脉", "o": "弦细虚濡脉总起来主脾胃虚寒、肝血不足、虚风内动，并可见真寒假热之象。其脉弦细为肝血不足、木失柔养；虚濡为脾胃气弱、湿浊内停；至数迟则为寒。三者相合，反映脾胃虚寒为本，肝血亏虚、内风萌动为标，甚则虚阳外浮而现假热。原文以吐泻、偶痿废不能行步为慢脾风朕兆，周身灼热", "c": "主脾胃虚寒"}, {"id": "c:弦+细+虚", "n": "弦细虚脉", "o": "弦细虚脉总属虚中夹实、正虚邪郁之象。虚细主气血阴阳亏虚，弦主肝郁气滞、木旺风动。其病机可归纳为：气血两虚、阴血亏耗、肝郁气滞、土衰木旺、阴虚阳浮、血虚风动、正虚邪恋。诸类之间相互关联：虚为本，弦为标，虚细与弦并见，反映脏腑功能失调、气血失和。虚可致郁，郁可化风", "c": "主气血两虚"}, {"id": "c:数+弦+细+软", "n": "弦细软数脉", "o": "弦细软数脉总属虚实夹杂之象，以阴亏为本，郁热、阳浮、气滞为标。弦主肝郁气滞，细软主阴血不足，数主郁热内扰。其病机大致可分四类：一为阴亏火郁，阴不制阳而郁热内生；二为阳越风动，真阴亏于下，心阳浮于上，内风鸱张；三为气机失调，肝郁而肺胃肾之气升降失司；四为下焦根衰", "c": "主阴亏火郁"}, {"id": "c:弦+细+涩+软", "n": "弦细软涩脉", "o": "弦细软涩脉总属本虚标实、虚实夹杂之候。其脉弦为肝郁气逆，细软为阴血不足，涩为痰阻脉道，重按如无更提示正气内虚。三者相合，反映情志郁结、怒木直升，痰随气升堵塞华盖，致肺气不宣、治节不行，而阴血素亏为其根本。原文明言'非中暑虚脱'，强调脉道不利由痰气交阻所致，非纯", "c": "主肝郁气逆"}, {"id": "c:弦+细+滑+软", "n": "弦细软滑脉", "o": "弦细软滑脉总起来主“下虚上实”之候，即真阴亏于下、痰热阻于上。其脉由弦、细、软、滑四象复合而成：弦细主阴亏于下，软滑主痰热阻上。两段原文均出自同一医案，孟英明言“阴亏真于下，痰热阻于上耳”，可见此脉所主病机为下元亏虚与上焦痰热并存，属本虚标实、上下同病。阴亏为", "c": "主阴亏于下"}, {"id": "c:弦+细+软", "n": "弦细软脉", "o": "弦细软脉总属虚实夹杂之象：弦应肝木，主气郁、饮停、肝亢；细为阴血不足；软为气弱、湿滞。三象合见，总以正虚为本、郁滞为标。其主病机可归纳为虚（气阴两虚）、湿（暑湿内蕴）、肝郁（肝木偏亢）、饮（痰饮内停）、郁热（郁久化热）、脾虚（脾运不健）六类。诸类之间常相互兼夹", "c": "主虚（气阴两虚）"}, {"id": "c:弦+细+迟", "n": "弦细迟脉", "o": "弦细迟脉总起来主寒、虚、饮、风、气郁及痢疾等病机，核心为寒与虚，兼夹邪气。迟主寒，细主阳虚血少，弦主气机拘急、饮邪、风动或痛。三者合参，多示阳虚寒凝、营血不足，或寒饮内结、气机郁滞，或血虚风动、伏风内扰。各段中，寒入厥阴、霍乱、寒饮结胸等以寒为主；中虚气弱、营", "c": "主寒"}, {"id": "c:弦+细+平+长", "n": "弦细长平脉", "o": "弦细长平脉总以“弦细而长”为肝之常脉，主春季肝木平和之象。其病机分类皆以五行乘克为纲：若兼见他脏之脉，则示他脏乘肝。沉濡而滑为肾乘肝之虚邪，病轻易治；浮大而洪为心乘肝之实邪，病轻自愈；微涩而短为肺乘肝之贼邪，金克木而危重；大而缓为脾乘肝之微邪，病轻即瘥。诸类以", "c": "主肝平"}, {"id": "c:弦+细+长", "n": "弦细长脉", "o": "弦细长脉总起来主肝木之象，其病机可分为三类：一为肝火亢盛之实证，脉见有力而长，症见头疼、失眠、眩晕、便秘等；二为春令平脉，弦细长应春生之象，属无病之常脉；三为五行乘克之病机，以弦细长为肝之常脉，兼见他脏脉则示他脏乘肝，按虚实贼微判断轻重。三类之间，平脉为常，火", "c": "主肝火亢盛"}, {"id": "c:弦+结", "n": "弦结脉", "o": "弦结脉总起来主气机郁滞、血行不畅之病机，其核心为弦主肝郁、主痛、主饮，结主气滞、血瘀、积滞。四段原文分别从不同角度展现：瘀血内伏者，因久病入络，瘀阻脉道而结；气郁阳衰者，肝气郁结与肾阳衰微并见，属本虚标实；气血痹阻者，胆阳不舒、肝邪用事，气血冲突而脉行歇止；酒", "c": "主瘀血内伏"}, {"id": "c:弦+大+缓", "n": "弦缓大脉", "o": "弦缓大脉总起来主邪实壅盛、痰湿内蕴之证，以湿热痰火壅阻气分或脾胃阳困、湿郁不化为核心。弦主气郁、肝风或土虚木乘，大示邪壅或气虚，缓为湿象。四段中，或见湿热痰火久嗽，或见脾虚湿困泄泻，或见痰火内郁畏冷气逆，皆以痰湿为患，或兼热化，或兼脾虚。三类之间，湿热痰火与痰", "c": "主湿热痰火"}, {"id": "c:弦+滑+缓", "n": "弦缓滑脉", "o": "弦缓滑脉总起来主痰湿、痰热、风痰为患，其病机核心在于痰浊内蕴，或兼热结，或兼风动。弦主气滞、肝风，缓主湿，滑主痰，三脉相合，反映痰湿内停、气机不畅，甚则化热生风。从所涉段落看，其病机可分为三类：一为痰热内结，多见于外感热病过程中，痰热壅阻胸膈、腑气不通，证见便", "c": "主痰热内结"}, {"id": "c:弦+缓", "n": "弦缓脉", "o": "弦缓脉总属弦与缓并见之复合脉，其病机以痰湿内阻、脾虚湿困、肝郁气滞为核心，并可兼见虚风内动、虚中挟积及病退向愈之象。弦主气郁、主肝、主饮、主痛，缓主湿、主虚、主脾弱，二者相合，多示气机郁滞与湿浊内蕴并存，或肝木乘脾、土虚湿盛。若弦缓无力，则偏于气血大亏、脾虚湿", "c": "主痰湿内阻"}, {"id": "e:弦", "n": "弦脉", "o": "弦脉总属肝木之象，其病机以肝郁气滞为核心，兼涉木旺乘土、饮邪内停、肝火亢盛、虚损、痛证、疟邪郁于少阳及寒凝阳衰等多类。弦为肝脉，主气机郁滞，故情志不遂、气机不畅者脉多弦；肝木偏亢则乘克脾土，致呕吐、泄泻、不食；木火亢盛则刑金迫血，见咳喘吐血；肝失柔养、阴血亏虚", "c": "主肝郁气滞"}, {"id": "c:弦+虚+实", "n": "弦虚实脉", "o": "弦虚实脉总主虚证，尤以脾肾阳虚为本，兼见虚中夹实、虚寒内生之候。其脉虽或紧数、或真弦，似有实象，然必无力无神或中虚似实，故非真邪实。原文列形体薄弱、颜色清白、素禀阳衰、年衰脾弱等，皆阳气不足之体，忽患泻痢多因生冷饮食所伤，虚为本而实为标。三类病机中，虚寒与脾肾", "c": "主虚寒"}, {"id": "c:弦+滑+微+软", "n": "弦软微滑脉", "o": "弦软微滑脉总属本虚标实、虚实夹杂之候。其脉象由弦、软、滑三象复合而成：弦主肝郁气滞，软主脾弱或阴虚不敛，滑主痰湿内阻。三象相合，提示正气已伤而痰气壅滞为患。所主病机主要有三类：一为肝亢脾弱，痰湿热逗留，见惊惕、纳呆、口干腻；二为阴虚痰滞，痰气滞于厥阴，见肢痛转", "c": "主肝亢脾弱"}, {"id": "c:弦+滑+软", "n": "弦软滑脉", "o": "弦软滑脉由弦、软、滑三象复合而成，总属本虚标实、虚实夹杂之候。弦主肝郁气滞、饮邪内动；软主正气不足，或脾虚、或阴亏；滑主痰湿内蕴。三者相合，揭示气机郁滞、痰湿内阻而正气已伤的基本病机。所主病机可归纳为痰湿内蕴、脾虚饮停、肝郁气滞、正虚痰阻、痰热化火、阴虚痰滞六", "c": "主脾虚饮停"}, {"id": "c:弦+紧+迟", "n": "弦迟紧脉", "o": "弦迟紧脉总属阴寒内盛、气滞血凝之证。迟主寒，紧主痛，弦主气机郁滞，三脉相合，反映寒邪内侵、阳气受困、气血运行不畅的核心病机。其所主病机可归纳为寒、痛、阳虚、气滞、血寒五类，彼此关联：寒邪为致病之主因，寒性收引凝滞，导致气机郁滞；气滞则血行不畅，形成血寒凝滞；寒", "c": "主寒"}, {"id": "c:弦+细+弱+迟", "n": "弦迟细弱脉", "o": "弦迟细弱脉总起来主阳虚寒盛、寒饮内停及虚阳浮越之病机。弦主痛、主饮，迟主寒，细弱主虚，四象合参，反映阳气大虚、沉寒锢冷或寒饮内停，导致气化不利、脉道拘急而鼓动无力。其各类之间相互关联：寒凝与阳虚互为因果，阳虚则寒凝，寒凝更伤阳；寒饮停聚又进一步遏制阳气，迫使虚", "c": "主寒凝"}, {"id": "c:弦+缓+迟", "n": "弦迟缓脉", "o": "弦迟缓脉总起来主肝旺脾弱、湿滞未化而兼营血本虚之候。左弦主肝气肝阳上升，右迟缓主湿滞未楚、脾胃运化无权，弦缓并见说明痛势虽缓而肝旺脾弱、湿滞未化之兼未除；原文又明言营血本虚，故虚象亦寓其中。三类病机相互关联：肝旺可乘脾，脾弱则湿滞难化，化源不足则营血本虚，形成", "c": "主肝旺"}, {"id": "c:弦+迟", "n": "弦迟脉", "o": "弦迟脉总起来主寒、阳虚、饮、气郁、积、疟、风痰等病机，核心为寒与阳虚，兼夹邪气。迟脉主寒、主阳虚，弦脉主气机拘急、饮邪、风动、痛或积。二者合参，多示阳虚寒凝、寒饮内结、气机郁滞，或寒积内结、疟邪伏留、风痰内动。各段中，寒入厥阴、霍乱、寒饮结胸等以寒为主；中阳不", "c": "主寒"}, {"id": "c:弦+动+长", "n": "弦长动脉", "o": "弦长动脉在原文中特指“足厥阴肝痧”的脉象，总起来主肝经痧邪为患。其病机核心为邪扰肝经、血络受伤：弦为肝脉，长为气机壅滞，动为邪正交争，三者相合，既反映痧邪侵犯肝经，又提示血分受伤、气血扰动。与段落中其他痧脉（如芤而浮主肺痧、芤而数主心痧等）相比，弦长而动独应肝", "c": "主肝痧"}, {"id": "c:弦+和+长", "n": "弦长和脉", "o": "弦长和脉总起来主肝木亢盛、气机有余而克伐脾土之病机。其脉弦为肝旺，长为气有余，弦长不和则木旺土衰，肝脾失调，故见腹满、晨便、便后腹松等症。原文断为“木旺土衰无疑”，并指出“不但脾病，腑亦病矣”，说明该脉所主以肝旺乘脾为核心，涉及气有余、肝脾不和及腑病等多个方面", "c": "木旺土衰"}, {"id": "c:弦+平+长", "n": "弦长平脉", "o": "弦长平脉总以弦长为肝之常脉，主春季肝木平和之象。其病机围绕肝气之平、太过、不及与逆乱展开：弦长软弱为平；实弦为太过，病在外；虚微为不及，病在内；沉急为气逆。诸类皆从肝木立论，以脉象虚实急沉分判病机。若兼见他脏之脉，则按五行乘克推演，如沉濡而滑为肾乘肝虚邪，浮大", "c": "主肝平"}, {"id": "c:弦+急+长", "n": "弦长急脉", "o": "弦长急脉总属实证、气逆、痰壅与肝木有余之候。其脉弦长劲急有力，为实邪壅滞、气机逆乱之象，故主实邪壅滞、气逆上攻；若兼两畔细脉沸然如烂绵，则示痰浊胶结、脉道不利，主痰浊内结；在脏应肝，弦长而急为肝气实、木气本然之脉，主肝实木旺。四类病机相互关联：实邪壅滞为总纲，", "c": "主痰浊胶结"}, {"id": "c:数+弦+长", "n": "弦长数脉", "o": "弦长数脉总起来主肝木亢盛、气火有余之候，其病机核心为肝郁化火、阳亢动风。弦主气郁，长主有余，数主热，三者相合，反映肝气郁结、肝火亢盛、气火冲逆的病理状态。具体而言，肝郁气滞可横逆犯肺，致木火刑金；犯脾胃，致肝木乘土；化火生风，则气火冲逆，上扰清窍。若兼阴亏，则", "c": "主阴虚阳亢"}, {"id": "c:数+弦+浮+长", "n": "弦长浮数脉", "o": "弦长浮数脉总起来主外感兼内伤、正虚邪实之候。浮数主外邪化热，热入阳明；弦长主肝阳上逆，气机亢逆；按之有力而无洪滑之象，则揭示正气内虚、邪热壅盛。三者相互关联：外感引发内伤，肝阳上逆加重喘逆，正虚使邪热难以透达，故脉不洪滑。此脉象集中体现本虚标实、寒热错杂的病机", "c": "主外感化热"}, {"id": "c:弦+长", "n": "弦长脉", "o": "弦长脉总起来主肝木亢盛、气机逆乱，以肝胆气火、胃热冲逆为核心，兼涉痰火、疟邪、积气与虚中夹实。弦为肝脉，主气郁、主痛、主痰；长为气火有余、邪实壅盛。故其脉多见肝胆之火上冲、胃热壅盛、冲气上逆，三者常相兼为患，致气血随之上逆，发为眩晕、头痛、吐衄、噫气、狂证等。", "c": "主肝火气逆"}, {"id": "c:弦+革", "n": "弦革脉", "o": "弦革脉总属虚证，以正气虚衰、脉失柔和为根本。其具体所主，一为虚劳亡血，二为妇人半产漏下，三为虚阳外浮，四为阴阳离绝。虚劳亡血与半产漏下皆属精血亏耗，精血既亏则脉道不充、气浮于外，故见弦大而革、失于柔和之象；弦大为虚阳外浮之征，革脉则示正气虚而脉失柔和。若脉见弦", "c": "主虚劳亡血"}, {"id": "c:微+弱+促", "n": "弱促微脉", "o": "弱促微脉在此案中总主虚实夹杂之候。左弱主卫阳大伤、胃津劫干，属虚；右促主里热未清，属热；目黄、嗜酒中虚则示湿蕴化热。三者相互关联：辛温误汗先伤阳津，中虚谷少易聚湿蕴热，湿郁化热又致里热未清，故脉见弱促并现。总以阳伤津劫为本，湿热未清为标，不可骤补，当甘缓调治。", "c": "主阳伤津劫"}, {"id": "c:弱+促", "n": "弱促脉", "o": "弱促脉总主虚实夹杂之候，以阳伤津劫为本，湿热内蕴为标。左弱主卫阳大伤、胃津劫干，属虚；右促主里热未清，属湿热。原文'目微黄'、'嗜酒中虚谷少'示湿蕴化热，辛温误汗先伤阳津，中虚谷少易聚湿蕴热，湿郁化热又致里热未清，故脉见弱促并现。三类病机相互关联：虚为本质，湿", "c": "主虚（阳伤津劫）"}, {"id": "c:弱+实", "n": "弱实脉", "o": "弱实脉在此段中主要提示气虚与热实并存的复杂病机。弱脉本主气虚，但不可仅凭脉弱即断为虚寒，须合症辨之。原文患者素伤烟色，气虚脉弱，又外感实热内结，大便多日不通，烦热胀满，故脉虽弱而火甚实，形成虚实夹杂之候。治疗以调胃承气汤加参、赭石、天冬，攻补兼施而愈。可见弱实", "c": "主气虚"}, {"id": "c:小+弱+促", "n": "弱小促脉", "o": "弱小促脉总起来主气血两虚、营卫俱损而兼虚中夹滞。其脉形小弱，为气血不足、营卫两伤之本质；促为数而时止，示虚中夹滞，因疟久不止、辛散过投，正虚而邪滞未净。三者相互关联：气血两虚是基础，营卫俱损是具体表现，虚中夹滞是兼夹病机。故治疗用补中益气汤补益中气、升举清阳，", "c": "主气血两虚"}, {"id": "c:数+弦+微+弱", "n": "弱弦微数脉", "o": "弱弦微数脉总起来主气血虚少、肝旺与虚火相兼之证。弱微为气血不足之本，弦为肝旺之标，数为虚火之象。三者相互关联：气血虚少则肝失濡养而肝旺，肝旺又化火伤阴，虚火复耗气血，形成本虚标热、虚实夹杂之候。原文以“血质淡薄”“产后失调”为因，以面白、经迟、带下、偏头痛、耳", "c": "主气血虚"}, {"id": "c:弱+急", "n": "弱急脉", "o": "弱急脉总起来主正虚邪躁、虚实夹杂之证。弱脉主气血亏虚、阴阳两伤，急脉主肝木躁动、气机拂郁。二者并见，提示正气不足而邪气内扰，常见于久病耗伤、脏腑亏损而肝木偏亢之候。原文肛漏日久，阴耗阳伤，肺肾并亏，肝木侮土，脉来尺寸弱而急，正虚木亢，势入损门。故本脉以虚为本，", "c": "主虚"}, {"id": "c:滑+弱+散", "n": "弱散滑脉", "o": "弱散滑脉总起来主正虚邪恋、气血耗败，兼有虚热。弱散为气血耗败、正气涣散，似滑为腐脓痰浊未清，弱数示虚热。三者相合，反映疮疡久溃、形损正衰而余邪未净的病机。各类之间以正虚为核心：气血耗败是基础，正虚邪恋是正虚与余邪并存，虚热是正虚所生之热。脉象虽似滑而实非实热，", "c": "主气血耗败"}, {"id": "c:弱+散", "n": "弱散脉", "o": "弱散脉总属虚损之候，以正气亏耗、根本离散为核心。弱为气血衰微，散为根本离散、五脏真气将绝，故其主病以虚为纲。具体而言，或见气血衰微、肌肉大退、面色惨白；或见胃气虚弱、肠鸣滑泄、四肢肿满；或见根本离散、阴阳离决之死候；或见脾之真脏脉现、胃气竭尽。若兼数脉，则虚火", "c": "主气血衰微"}, {"id": "c:数+弱", "n": "弱数脉", "o": "弱数脉总以虚为本，数为其标。弱主气血阴阳亏虚，脉道不充；数虽主热，然与弱同见，多为虚热、阴火或虚阳浮越，非实火可下。其病机大致可分七类：虚热内扰为常见之标，气血两虚为根本，痰火内蕴示虚实夹杂，下虚上实示阴阳不相维系，正虚邪恋示虚体著邪，热毒痈肿示正虚热结，心疟", "c": "主虚热"}, {"id": "c:滑+弱", "n": "弱滑脉", "o": "弱滑脉总以弱示正气不足、滑示痰湿内阻为基本病机，其核心在于胃气尚存与痰湿内扰并存。弱而滑，脉道柔和流利，是胃气未败之象，故原文屡言“脉弱以滑，是有胃气，命曰易治”，预后较佳。然弱滑亦主具体病证：滑主痰，弱主虚，合见则痰湿内阻而正气已伤，可见脾阳虚弱、痰湿内阻；", "c": "主胃气存"}, {"id": "c:濡+弱+伏", "n": "弱濡伏脉", "o": "弱濡伏脉总起来主寒湿内盛、阳气被遏之证，尤以足太阴中寒为代表。弱脉示阳气虚馁，濡脉主湿邪困阻，伏脉为寒湿深遏、脉道不显，三者相合，反映内外寒湿交困、脾阳不振、阳气不能外达的病机。原文所述瓜果水寒与暴凉迅风为内外两因，舌白、渴不能饮、脘胀、微呕、无热、冷汗肢厥等", "c": "主寒湿内盛"}, {"id": "c:涩+濡+弱", "n": "弱濡涩脉", "o": "弱濡涩脉总属虚损之象，以气血大伤、络脉空乏为根本。弱主气衰，濡主阴血不足，涩主血少络空、脉道不利，三者相合，反映气血两虚、脏腑损伤非止一隅。在此虚损基础上，可致气机升降失常：上焦气逆不降，故见气伤上逆、呛逆、烟雾迷离熏灼喉底；下焦封藏不固，故里不肯收摄、肢节微", "c": "主气血虚"}, {"id": "c:大+弱+缓", "n": "弱缓大脉", "o": "弱缓大脉总主气虚挟痰。左脉弱缓大，弱为气衰，缓大为气虚无力鼓动，故主气虚；右关带滑，滑为痰湿内蕴，故主痰湿。二者相合，反映脾虚气弱、运化失职、湿聚成痰之病机。原文以“气虚挟痰”概括，并谓“脉症相符”。气虚为本，痰湿为标，脾虚生湿生痰，痰阻中枢，进而影响升降，变", "c": "主气虚"}, {"id": "e:弱", "n": "弱脉", "o": "弱脉总属虚象，以气血不足、阳气衰微为基本病机，脉道不充、鼓动无力故脉来软弱。所主病机可归纳为气血两虚、阳虚寒盛、正虚邪恋、虚中夹痰湿、虚热内扰及病后正复数类。其中气血两虚与阳虚寒盛为根本，贯穿诸类；正虚邪恋为虚而兼邪，虚中夹痰湿为虚而兼湿浊，虚热内扰为虚而兼热", "c": "主气血两虚"}, {"id": "s:弹石", "n": "弹石", "o": "弹石脉总属无胃气之真脏脉，主肾气绝、胃气亡、真脏脉见及死候，亦可主肾脉太过。其核心病机为胃气衰败、肾真独见，脉来坚劲如弹石，毫无柔和之象。各分类之间相互关联：肾绝则胃气亦亡，胃气亡则真脏脉见，真脏脉见则主死候；而肾太过为石多胃少之轻证，病在外，与死候之纯石无胃", "c": "主肾绝"}, {"id": "c:微+动", "n": "微动脉", "o": "微动脉在古籍中含义有二：一为脉象微动，二为穴位处细微搏动之定位语。作为脉象，微动可主妊娠，因气血充盛、冲任调和，少阴脉动；亦可主气血暴脱，因阴血骤失、气随血脱，脉道不充而微动无力。作为定位语，微动脉处施灸反映冲任虚损、气血耗伤之病机。总起来看，微动脉所主病机以", "c": "主妊娠"}, {"id": "c:微+缓+和", "n": "微和缓脉", "o": "微和缓脉总以“和缓”为胃气之象，其核心病机在于胃气的盛衰与邪正的进退。和缓脉本身并非独立病脉，而是判断胃气存亡及疾病预后的关键指征。若脉由和缓转为弦急，为邪气渐进、胃气受遏，病势加重；若由弦急转为和缓，或初急后缓，为胃气来复，病势向愈；若初缓后急，则胃气衰去，", "c": "主邪进病甚"}, {"id": "c:微+和", "n": "微和脉", "o": "微和脉总以和缓之象为特征，核心在于反映胃气盛衰与邪正进退。其主病机可归纳为三类：一为胃气渐复，见于病后脉转微和，示胃气来复、病势向愈；二为邪退正虚，见于急疾歇止脉后脉息微和，虽邪去而气血已伤，神思恍惚；三为邪恋正复，见于弦微和脉，弦为邪郁未清，微和为胃气尚存，", "c": "主胃气渐复"}, {"id": "c:数+大+微", "n": "微大数脉", "o": "微大数脉总起来主热与邪盛，兼及非典型病脉。大主邪盛，数主热，微数示热势未炽，微大示邪实未甚。原文脉大微数，心肝蕴热上亢，热壅络脉，防凝聚成疡，是热邪与邪盛并见；原文脉微大微数，无明显病态，不足以为病脉，提示此脉亦可为生理性偏颇。两类病机中，主热与主邪盛常相兼，", "c": "主热"}, {"id": "c:大+微", "n": "微大脉", "o": "微大脉总起来主正虚邪实、虚实夹杂之候。微为阳气不足或正气亏虚，大为邪气壅盛或虚阳外浮，二者相合，提示正虚与邪实并存。其具体所主，可归纳为邪热未清、正虚邪实、虚损劳伤、气血两虚、痰滞气郁、瘀血内阻、水气内停等类。各类之间相互关联：邪热未清者，微大示余邪留恋而正未", "c": "主邪热未清"}, {"id": "c:大+微+迟", "n": "微大迟脉", "o": "微大迟脉总起来主瘀血内阻、阳气不宣之病机。微为阳虚，大为邪实，迟为血行不畅，三脉合参，示正虚邪实、血行滞涩之候。其具体所主，以瘀血为核心，兼见阳虚、邪实、血行不畅等机转。瘀血内停，气机壅滞，故见胸满、唇痿舌青、口燥但欲漱水不欲咽、腹不满而自言满等症；阳虚则血行", "c": "主瘀血"}, {"id": "c:微+实", "n": "微实脉", "o": "微实脉总起来主虚中挟实、热结于里。此脉见于产后，微示正气已虚，实主邪热内结。原文所述恶露不尽、少腹坚痛、不大便、烦躁发热、日晡益甚、食则谵语等，皆热结膀胱、瘀热内实之候。脉微实正是产后正虚而邪热内结的反映，故治疗宜大承气汤攻其里实，热去则诸症自解。可见微实脉所", "c": "主里实热结"}, {"id": "c:微+小+弱", "n": "微小弱脉", "o": "微小弱脉总主阳气衰微，尤以脾阳不振为核心。其脉微小弱，直接反映阳气已衰，而脾为后天之本，阳气衰则脾运先困。长夏热泄气分，更伤脾胃之气，致不食不运、味变酸苦，此脾困之候。脾土既虚，肝木易乘，稍涉嗔怒则木乘土中，益加不安。故本脉所主病机可归纳为三类：阳气衰微、脾运", "c": "主阳虚"}, {"id": "c:数+微+小+急", "n": "微小数急脉", "o": "微小数急脉总属虚损与邪盛夹杂之候，以正虚为主，兼见邪热。微脉主阳气衰微，细脉主阴血亏虚，数急脉主邪热亢盛。四者相合，反映正气已虚而邪热未退，病情复杂。原文中'霍乱畏微迟'示阳衰危候，'颠狂忌虚细'示阴血亏虚，'风痹足痿偏嫌数急'示邪热深入。诸类之间，虚损为本，", "c": "主虚损难治"}, {"id": "c:数+滑+微+小", "n": "微小滑数脉", "o": "微小滑数脉总起来主阳虚阴盛、下焦不固、虚阳不藏之证。脉微小为阳气衰微、阴寒内盛之象，滑数则非实热，而是下焦不固、虚阳不藏所致。原文“上中下三部阳虚阴盛”点明病机根本为阳气虚衰、阴寒内盛，故虽见齿痛剧烈、恶热饮等似热之症，实为阳虚阴盛、虚阳浮越之假热。三类病机相", "c": "主阳虚阴盛"}, {"id": "c:微+小", "n": "微小脉", "o": "微小脉总属虚候，主阳气衰微、气血不足、精气亏耗。其类虽多，然皆以正虚为纲：或为体质阳虚，或为胃阳败绝，或为脾肾精竭，或为五脏消烁，或为泄痢正虚，或为热病阴竭。其间有可生可死之辨：脉微小而证相符、胃气尚存者生；若兼见实急、洪数、或热病阴竭阳亡者死。故微小脉虽主虚", "c": "主阳虚气弱"}, {"id": "c:微+小+迟", "n": "微小迟脉", "o": "微小迟脉总属阳气衰微之候。微为阳弱，小为气衰，迟为阳不胜阴，三象相合，反映阳气虚衰、推动无力。阳气不能温煦，则形色枯悴畏寒；不能腐熟水谷，则久食物不进，化源告竭；脾运失职，水湿停聚，久则成胀。原文断为“无阳”，强调阳气将败，预后不良。三类病机以阳衰为本，化源竭", "c": "主阳衰"}, {"id": "c:微+平", "n": "微平脉", "o": "微平脉总属虚候，主元气虚衰、中宫不振、营卫失调三类病机。其核心在于正气亏虚：元气不能复，则脉道不充而微；中宫脾胃虚弱，则纳少便溏；营卫不足则阴阳失和。三者相互关联，元气虚衰为根本，中宫不振为关键，营卫失调为表现。原文强调“脉微不宜攻邪，宜平中宫以扶脾胃”，说明", "c": "主元气虚衰"}, {"id": "c:弦+微+缓+和", "n": "微弦和缓脉", "o": "微弦和缓脉总以“和缓”为胃气之象，其病机核心在于胃气的盛衰与邪正的进退。和缓与弦急的相互转化，反映邪气渐进而胃气受遏，或胃气来复而病势向愈，或胃气衰去而病趋危重。四时平脉微兼弦、钩、毛、石而和缓，为有胃气之常；若脉无和缓而弦急独见，则为真脏脉，主死。故本脉所主", "c": "主邪进病甚"}, {"id": "c:弦+微+急", "n": "微弦急脉", "o": "微弦急脉在古籍中并非专主一病，而是作为脏气变动、病邪逆顺的外显征象。原文总论「有诸内者形诸外」，望五色以合五脏之脉，切五脉急大缓涩沉以合五脏之色，示脉随脏气而变。微弦急脉提示脏气失和、邪气扰动，其病机须结合色诊与症状相参，脉色顺则吉、逆则凶。三类病机相互关联：", "c": "主脏气变动"}, {"id": "c:弦+微+涩", "n": "微弦涩脉", "o": "微弦涩脉总起来主血虚、湿痰、湿热痰瘀及阳虚寒凝。其脉象微为脉力弱，主阳气衰少或气血不足；弦主气郁、湿痰或寒凝；涩主血少、血行不畅或瘀滞。三者相合，反映虚实夹杂之病机：或血虚兼湿痰阻滞，或湿热痰瘀互结，或阳虚寒凝兼血行不畅。各段原文均以微弦涩为共同脉象，但依据兼", "c": "主湿热痰瘀"}, {"id": "c:弦+微", "n": "微弦脉", "o": "微弦脉总以弦应肝木、主气机郁滞为纲，微则示病势不剧或正气不足。其病机大致可分虚实两端：实者肝郁气滞、痰饮湿滞、疟邪少阳、肝火风动、木盛侮土，皆以弦脉为肝木气结、饮邪内停、少阳不和之应；虚者虚寒阳弱、肝虚胃弱，则因微脉主阳气衰微、肝胃俱虚。弦与微相合，既可见于肝", "c": "主肝郁气滞"}, {"id": "c:大+微+弱", "n": "微弱大脉", "o": "微弱大脉总主正气不足，尤以气分虚、气血两虚为要。脉微弱为“无阳”之征，反映气分不足，故太阳病见脉微弱者不可发汗；若脉大无力或微弱而渴，则属气血两虚，治宜补气血。两类病机均以虚为本：气分不足侧重卫外与托邪无力，气血两虚侧重营血亏耗与津液不布。二者可相互转化，气虚", "c": "主气分不足"}, {"id": "c:弦+微+涩+弱", "n": "微弱弦涩脉", "o": "微弱弦涩脉总起来主血虚，并涉及肝脾亏虚。其脉象特征为脉力微弱、脉形弦细而往来涩滞，反映血少脉道不充、血行不畅。原文以“女人血虚者……脉息则微弱弦涩”立论，指出该脉是血虚之候的典型表现，并伴经期不准、色淡量少、行后腹痛喜按、困惫腰膝如折等症。分析进一步认为，微弱", "c": "主血虚"}, {"id": "c:弦+微+弱", "n": "微弱弦脉", "o": "微弱弦脉总起来主虚中夹实、本虚标实之证。微弱为气血阴阳不足之本，弦为肝旺、肝风、寒湿或气滞之标，涩则兼气滞血瘀。各类病机相互关联：气血虚少则肝失濡养而肝旺，肝旺化火伤阴，虚火复耗气血，形成虚火相兼；血虚脉道不充则血行涩滞，兼见气滞血瘀；中气虚弱则寒湿内侵，或虚", "c": "主虚"}, {"id": "c:数+微+弱", "n": "微弱数脉", "o": "微弱数脉总起来主正气虚弱、邪气渐衰或虚热内扰之候。微弱为气血不足、阳气衰微或暑热伤气之象，数为热，或为实热，或为虚热，或为阳气来复。诸段所示：暑热伤气阴者，脉微弱数而见呕泻身热；下利向愈者，脉微弱数为邪退正复；大气下陷者，脉微弱数而兼肝火横恣；虚阳外越者，脉微", "c": "主暑伤气阴"}, {"id": "c:沉+微+弱", "n": "微弱沉脉", "o": "微弱沉脉总属虚证，以阳气衰微为核心，兼及气阴两虚、寒盛、气陷等。沉主里，微弱主阳气虚衰、气血不足，故其病机多责之正气亏虚。具体而言，或为阳虚寒盛，见于寒痢、虚寒等，脉多兼迟；或为气阴两伤，见于伏邪为疟、内消等，正虚无力运邪外达；或为阳衰气陷，见于大气下陷、痘疮", "c": "主阳虚寒盛"}, {"id": "c:浮+微+弱+空", "n": "微弱浮空脉", "o": "微弱浮空脉总属正气虚衰、营卫不充之象，其核心病机为“内虚”。在伤寒、瘟疫等外感病中，此脉出现即提示正不胜邪，邪气易乘虚深入，形成内虚邪陷之证；同时因正气无力抗邪，病势多缠绵难解，治疗上最忌强攻发汗，以免更伤中气。三类病机相互关联：正虚是根本，邪陷是正虚所致之变", "c": "主正虚"}, {"id": "c:细+微+弱+急", "n": "微弱细急脉", "o": "微弱细急脉总起来主虚证，尤以阳气衰败为危候。原文以谵语郑声辨虚实，实邪谵语脉必强，洪滑有力；虚证郑声脉当微弱，若更见细急逆冷则阳气衰败，预后凶险。微弱主正气不足，细急主阳衰内竭，逆冷为阳衰外候。三类病机中，主虚证为常，主阳衰为危，主邪实兼虚为变。虚证脉微弱，阳", "c": "主虚证"}, {"id": "c:细+微+涩+弱", "n": "微弱细涩脉", "o": "微弱细涩脉总属虚候，主阳气虚衰与元气大虚。微为阳衰，弱为气弱，细为阴精不足，涩为血行不畅，四者相合，反映阳气虚衰、阴寒内盛，鼓动无力，故脉道不充、血行滞涩。原文以微弱细涩与浮大弦芤对举，明虚喘不可攻伐之戒，指出此脉为阴中之阳虚、元气大虚之候，若妄加消伐或苦寒攻", "c": "主阳虚"}, {"id": "c:细+微+弱", "n": "微弱细脉", "o": "微弱细脉总属正气虚衰之候，以阳气衰微、脾胃气钝为核心病机。微为阳衰，弱为气馁，细为血少，三象相合，反映阳气失于护卫、鼓运无力。其具体所主，一为阳气衰微，见形冷汗泄、寒栗汗出；二为脾胃气钝，见不饥少纳、脘腹常痞、泄气自舒；三为正虚非邪，舌明润、不喜饮汤，非邪结客", "c": "主阳气衰微"}, {"id": "c:微+弱", "n": "微弱脉", "o": "微弱脉总属虚候，以阳气衰微、气血不足为纲。微为无气，弱为血少，故其主病以正虚为核心：轻则气血两虚、中虚寒盛，见足软、短气、腹痛泄泻；重则阳气衰微欲脱，见汗出肢冷、脉微如无。阳虚于下者可致虚阳浮越，现面赤戴阳、阴躁似阳；气虚下陷者可致大气下陷，见喘促怔忡。暑湿伤", "c": "主阳气衰微"}, {"id": "c:虚+微+弱", "n": "微弱虚脉", "o": "微弱虚脉总属正虚，所主病机以阳气气馁、气血俱虚、虚邪为病为要。其脉微弱无力，为阳气不充、气血不足之征，故内伤虚损、病后正衰多见。然须与实邪致脉沉伏细涩者相鉴别：暴痛之极气为邪逆，脉道不行而沉伏异常，最似极虚，细察必有弦紧之意，乃邪实之脉；惟脉本微弱者方为虚邪。", "c": "主阳虚气馁"}, {"id": "c:微+濡+弱+迟", "n": "微弱迟濡脉", "o": "微弱迟濡脉总起来主阳气虚衰、湿寒内盛，尤以脾胃虚寒为核心。微、弱主阳气虚衰，迟主寒，濡主湿，四者合见，反映正气不足、寒湿内困之病机。其具体表现可归纳为阳虚、寒、湿、脾胃虚寒及气化不升五类，彼此关联：阳气虚衰则生寒，寒湿内盛则困阻脾胃，脾胃虚寒则健运失职，进而气", "c": "主阳虚"}, {"id": "c:微+弱+缓+迟", "n": "微弱迟缓脉", "o": "微弱迟缓脉总主阳气衰微、气血虚衰之证。其脉象微弱，为阳气无力鼓动；迟缓，为脉气壅滞或从容不迫。所主病机主要有二：一为阳衰寒饮，心阳薄弱，寒饮凌心，治宜温阳化饮；二为气血虚衰，多见于失血之后，脉证相符则生，若脉转急疾则预后不良。二者皆属虚候，但前者偏于阳虚寒盛，", "c": "主阳衰寒饮"}, {"id": "c:微+弱+迟", "n": "微弱迟脉", "o": "微弱迟脉总属虚寒之象，以阳气衰微、气血不足为核心病机。微为阳衰气弱，弱为气血俱虚，迟为阴寒内盛，三者相合，反映正气大虚、鼓动无力。其具体所主，一为阳虚气陷，胸中大气下陷，见短气、昏愦；二为虚寒失血，中气不能摄血，或命门火衰，血随二便脱出；三为寒饮内结，阳虚不能", "c": "主阳虚气陷"}, {"id": "c:沉+微+急", "n": "微急沉脉", "o": "微急沉脉总起来主肾阳虚寒、气逆上冲之病。其脉象由微、急、沉三部分组成：微主阳气不足，急主寒邪内迫与气逆躁动，沉主病在里、气郁于下。三者相合，反映下焦阳虚寒凝、肾气不足而气逆上冲的核心病机。在此基础上，可衍生出三类具体病机：一是肾虚气逆，因惊恐忧思伤肾，气积于肾", "c": "主肾虚气逆"}, {"id": "c:微+急", "n": "微急脉", "o": "微急脉总起来主阳气衰微、寒邪内迫、气机拘急之病机。微为正气不足或阳气衰微，急为寒凝收引、气结有形或邪气内迫，二者相合，多示虚中夹实、寒凝气滞之候。其具体所主，可归为寒凝阳衰、积气成形、脾虚气逆、肺寒热咳血、正虚邪恋、脏气失和六类。寒凝阳衰为基本病机，因阳衰则寒", "c": "主寒凝阳衰"}, {"id": "c:微+散", "n": "微散脉", "o": "微散脉总起来主气阴耗散、心气耗散及虚劳。微为阳气式微、心气不足，散为气阴耗散、固摄无力，二者相合，反映正气耗散不收之病机。各段中，段因暑热耗气伤阴而脉散微，属气阴耗散；段因操劳过度伤心血，心脉微散，致心脾肺俱虚，属心气耗散与虚劳。三类之间相互关联：气阴耗散可致", "c": "主气阴耗散"}, {"id": "c:数+微+散+代", "n": "微数代散脉", "o": "微数代散脉总起来主心气不足、虚热内扰、心神涣散及心肾不交之病机。微为心气不足，数为虚热内扰，代为心气断续，散为心神涣散，四者合见，反映心之气阴两虚、虚热内扰、神不守舍。肾脉虚细，为肾水亏虚，不能上潮心火，致坎离不交、水火未济。诸类病机相互关联：心气不足与虚热内", "c": "主心虚"}, {"id": "c:数+微+急", "n": "微数急脉", "o": "微数急脉总属正虚邪恋、阴虚内热之候。微脉主阳气衰微或正气不足，数急脉主邪热亢盛或里有热，二者相合，反映正气已虚而邪热未退，病情复杂。原文两段均强调'里有热'属阴虚，非关表邪，亦非湿热，故其病机核心为阴虚内热兼正虚。微数急脉所主病机可归纳为三类：一为阴虚内热，二", "c": "主阴虚内热"}, {"id": "c:数+微", "n": "微数脉", "o": "微数脉总以‘微主正虚、数主有热’为纲，所主病机以虚热为核心，兼及正虚邪恋、阳虚火浮、风热在表、热郁血瘀、阴阳两虚等类。微为正气不足或阳气衰微，数为虚热、邪热或火浮，二者相合，多示正虚而热扰，非实热亢盛之候。其虚热可因阴虚、气虚、阳衰而不同；正虚邪恋则见于外感余", "c": "主虚热"}, {"id": "c:数+微+软", "n": "微数软脉", "o": "微数软脉总属正虚之候，以阳气衰微、气弱为本，虚热与阴亏为标。微为阳衰，软为气弱，数虽主热，但微软并见则为虚性之数，非实火。原文见肢冷畏寒、汗出不已、舌全光，断为“一派虚象”，强调扶正为要。故其病机以阳衰气弱、表卫不固为主，虚性数热与阴液亏虚为兼。三者相互关联：", "c": "主阳衰气弱"}, {"id": "c:沉+微+迟", "n": "微沉迟脉", "o": "微沉迟脉总起来主阳气虚衰、阴寒内盛之候。微为阳虚，沉主里，迟主寒，三者相合，反映正气大虚、鼓动无力，阴寒内盛、温煦失职。其病位在里，以阳虚为本，寒盛为标，属虚寒重证。原文患者常年恶寒，盛夏需厚衣，脉微沉迟，投温补不效，终以气中而亡，说明此脉所主之虚寒非寻常可比", "c": "主阳虚"}, {"id": "c:微+洪", "n": "微洪脉", "o": "微洪脉总起来主热，但热有虚实之分。实热方面，主气分热盛与阳明经热：微洪为热邪鼓动，热势未盛，见于肺经气分热或邪初入阳明。虚热方面，主虚火扰动：脉洪而按之无力，为虚阳外浮，见于脾虚不摄、血海不固之崩漏。三类病机以热为核心，实热为邪热内蕴，虚火为阳气外浮，彼此关联", "c": "主气分热"}, {"id": "c:浮+微+散", "n": "微浮散脉", "o": "微浮散脉在古籍中仅见于四时平脉一段，与冬脉沉滑而实、季夏脉洪而迟并列，属秋令常脉。其核心意义不在主病，而在应秋气收敛、肺金清肃：微浮示肺气外达而不亢，散示秋气敷布而不聚，合为肺金当令、气机宣散有度之象。故归纳其“所主”当以应时平脉、肺气宣散为主，不宜径作虚脱论", "c": ""}, {"id": "c:浮+微+涩+短", "n": "微浮短涩脉", "o": "微浮短涩脉本为秋令肺金当旺之平脉，其象微浮应秋收、短涩应肺敛，故首列为主平脉。然同一部位若反见他脏之脉，则据五行生克判其病机与预后：浮大而洪为心火乘肺，火克金，属贼邪大逆，主危候；沉濡而滑为肾乘肺，子乘母，属实邪，主自愈；大而缓为脾乘肺，母归子，属虚邪，主病轻", "c": ""}, {"id": "c:细+浮+微", "n": "微浮细脉", "o": "微浮细脉总起来主肾虚夹外邪、虚寒内生之候。其核心病机在于肾精亏虚为本，风雨外犯为标，阳虚阴寒为兼。细为肾虚不足，微为阳气衰微，浮为外邪轻犯，三者并见，提示正虚邪恋、本虚标实。原文以尺脉微浮而细，断为肾虚风雨所犯，虽值盛夏而膝足寒冷如水中出，说明肾阳虚衰、寒从下", "c": "主肾虚"}, {"id": "c:浮+微", "n": "微浮脉", "o": "微浮脉总以浮示病位偏表偏上、微示正气不足或邪势轻浅为纲。其主病机可归为三类关系：一为邪郁上焦，寸脉微浮而胸中痞硬、气上冲，宜因势吐之；二为表邪轻浅，微浮而证轻，宜辛凉发散；三为正虚阳弱，浮微无根为元气外脱之危。此外，微浮亦见于阳气来复之向愈转归，以及痰气阻遏、", "c": "主邪郁上焦"}, {"id": "c:微+涩+疾", "n": "微涩疾脉", "o": "微涩疾脉总起来主癫疾，其病机以心气不足、血涩不荣为本，风邪急搏、热盛动风为标，兼及肾虚骨癫与湿浊内蕴。微涩主心气亏虚、血行涩滞，疾紧主风邪急搏、热盛动风，诸脉象可单独或相兼出现，反映癫疾虚实夹杂、多脏受累的特点。原文列五癫诊脉，以微涩为心癫之脉，紧疾为脾癫之脉", "c": "主心气不足"}, {"id": "c:微+涩+小+短", "n": "微涩短小脉", "o": "微涩短小脉总属虚候，主要反映五脏虚损、正气内衰。其脉象轻取或有滑象而重按微弱，提示虚阳浮于外而根本不足；沉取微涩短小，则为气血亏虚、脉道不充之征。原文以“举指而滑，按之而微”及“沉小微弱短涩软濡，俱为脏虚”为据，说明该脉所主病机以脏虚为核心，兼见阳虚外浮与气血", "c": "主脏虚"}, {"id": "c:微+涩+平+短", "n": "微涩短平脉", "o": "微涩短平脉总以肺金为枢，其常为秋令收敛之平脉，其变为四时相乘之邪脉。微涩短三象合看，微主气敛、涩主肃降、短主应秋，故首主肺之平调；若失其根底而浮虚按弱，则转为肺死脏之候。又因肺金易受他脏乘侮，原文以四脉辨邪：浮大而洪为心火克金之贼邪，大而缓为脾土归子之虚邪，沉", "c": "主肺平"}, {"id": "c:微+涩", "n": "微涩脉", "o": "微涩脉总主阳气衰微、阴血亏虚，气血俱不足之病机。微为阳虚气弱，涩为血少滞涩，二者相合，反映阴阳气血俱损。其类别虽多，然核心不离虚损：阳气虚衰则温煦无力，阴血亏虚则濡养不足，气血两虚则形神失养，营卫俱虚则三焦失仰，虚寒下利则阳衰阴盛，痹阻不仁则气血不荣，虚损难治", "c": "主阳气虚衰"}, {"id": "c:微+涩+缓+迟", "n": "微涩迟缓脉", "o": "微涩迟缓脉在《太平圣惠方》中主要出现于痈疽脓溃之后，总起来主邪气去而真气将复，为易愈之征。微涩示邪衰，迟缓示正复，故首主邪退正复。然同一段落以对比形式指出：若脉转沉细而直，则里虚欲变；若脉洪数，则真气虚而邪气实，预后凶险。可见微涩迟缓虽以正复为主，但须结合脉象", "c": "主邪退正复"}, {"id": "c:微+涩+长", "n": "微涩长脉", "o": "微涩长脉总起来主太阳中风邪退正复、病将向愈之机。其脉象由三部分组成：阳微示表邪已衰，阴涩示里气未和，长则示胃气渐复、气血充盈。三者合参，反映正胜邪却、胃气来复的动态转归。所归纳四类病机中，“主邪退向愈”为总纲，统摄表邪已衰、里气未和与胃气来复三个具体环节；表邪", "c": "主邪退向愈"}, {"id": "c:滑+微", "n": "微滑脉", "o": "微滑脉总以滑主痰湿、微示病势不剧或兼正虚为纲。其主病虽繁，约之可分虚实两端：实者痰湿、湿热、痰涎壅阻上焦或下趋大肠，甚则热迫血行、虫积腹热、疝瘕壅聚；虚者营血不足、阳气衰微而夹痰湿水液不化，或肾热髓枯而成骨痿。胎孕之微滑按之不绝，乃血聚养胎之常，与病脉不同。诸", "c": "主痰湿"}, {"id": "c:微+濡", "n": "微濡脉", "o": "微濡脉总起来主阳气虚衰、寒湿内盛，兼及五脏虚损。微为阳衰，濡为湿为弱，二者相合，轻则卫外不固而恶寒发热、阳不达末而厥逆，甚则虚阳扰心而烦；其本在于正气少、邪气多，故又主虚劳六极七伤。从下属具体脉看，濡微数脉兼热，濡微滑脉兼痰，弦濡微脉兼气滞积滞，均以微濡之虚寒", "c": "主阳虚寒盛"}, {"id": "c:沉+微+弱+短", "n": "微短沉弱脉", "o": "微短沉弱脉总属阴寒极盛、阳气衰微之候。其脉象微短沉弱，不应呼吸，反映阳气无力鼓动，阴寒内盛，甚则格阳于外。所主病机主要有三：一为阴寒极盛，二为阳气欲绝，三为寒盛格阳。三者相互关联，阴寒极盛可致阳气衰微，阳气衰微又可致格阳于外，形成内真寒外假热之复杂局面。原文案", "c": "主阴寒极盛"}, {"id": "c:微+涩+短", "n": "微短涩脉", "o": "微短涩脉总起来主气血亏虚、血少瘀滞及正虚瘀结之候。微为气弱，短涩为血少气滞，三象合见，反映正气不足与瘀血内结并存。原文妇人因家贫多劳、性急，耗伤气血，又致瘀血内结，出现经断、腹块、肿胀、食减、发热等症，脉微短涩，左尤甚，左主血，故血瘀偏著。其病机核心为正虚邪结", "c": "主气血两虚"}, {"id": "c:数+微+紧", "n": "微紧数脉", "o": "微紧数脉总起来主风热邪聚、正气不足之候，常见于肺痿、肺痈等病。数主热，紧主邪聚血壅，微主正虚。三者相合，提示风热之邪内侵，气血壅聚，而正气已伤。若脉数而虚，为津液重亡、肺叶焦枯之肺痿；数而实，为风热蕴结、气血稽留之肺痈。微紧而数者，邪聚未甚，脓未成；紧甚而数者", "c": "主热"}, {"id": "c:微+紧", "n": "微紧脉", "o": "微紧脉总起来主阳虚寒束、正虚邪结、阴盛阳衰及血虚寒凝四类病机。其脉象以微、紧复合为特征：微主阳气衰微、气血不足，紧主寒邪外束、邪气结聚、疼痛。从原文看，微紧脉既可因外寒闭表、阳气内弱而见于感寒发热、汗出头痛（如、），也可因正虚邪结而见于中焦郁滞、痧毒郁闭、鼠乳", "c": "主阳虚寒束"}, {"id": "c:细+微+伏", "n": "微细伏脉", "o": "微细伏脉总起来主邪闭气机与气血不足，并可见于暴病暴逆及久病将绝之候。其核心在“伏”：伏为脉道一时隐蔽不见，多因邪气内闭、气逆不通，或气脱不续，属暴病暴逆者，调气可复；而微细则示气血不足，若与伏并见，则邪闭之中已寓正虚。若积困延绵，脉由微细渐至隐伏，则非真伏，乃", "c": "主邪闭气机"}, {"id": "c:细+微+促", "n": "微细促脉", "o": "微细促脉总属阴阳并虚、衰脱之候。微细为阴阳俱虚、脉道不充；促为急促不匀、二气不相接续。二者相合，反映正气衰败、阴阳不相维系，故主阴阳并虚与衰脱两类病机。阴阳并虚为病之本，衰脱为病之急，二者互为因果：虚极则脱，脱则更虚。原文见鼾声呵欠、目瞑烦躁，正是阴阳并虚、衰", "c": "主阴阳并虚"}, {"id": "c:细+微+小", "n": "微细小脉", "o": "微细小脉总起来主阳气衰微、气血不足与阴伤火郁、气机壅滞两类病机。微者阳微，细者阴弱，小者气少，三象并见，首先反映正气亏虚：或为胃阳大衰、中焦虚寒，治当温理中阳；或为阴液不足、气血两亏。若兼数象，则于阴亏之中更见郁火内郁、气机壅滞，形成阴伤为本、火郁气壅为标的虚", "c": "主阳衰"}, {"id": "c:数+细+微", "n": "微细数脉", "o": "微细数脉总属正虚邪恋、阴阳气血俱损而兼热象之脉。微为阳气衰微，细为阴血不足，数虽主热，然与微细同见，则非实热，多为虚热、虚阳浮越或热邪内陷。其主病机可归纳为阴阳两虚、虚热内扰、正虚邪陷、阳脱危候、大气下陷、正虚郁热六类。各类之间以正虚为本，热象为标：阴阳两虚为", "c": "主阴阳两虚"}, {"id": "c:细+大+微+洪", "n": "微细洪大脉", "o": "微细洪大脉总属阴阳失调之候，以肾阴亏虚为本，虚阳上浮为标。微细沉细主阴液不足、脉道不充；洪大主阴虚不能制阳、虚阳外浮。二者可相互转化，反映阴阳互根关系。治疗以滋肾润肺、升发沉细之脉为法，使洪大渐平，恢复和平。此脉象核心在于阴虚阳浮、阴阳失衡，而非单纯实热或虚寒", "c": "主阴虚"}, {"id": "c:细+微+涩", "n": "微细涩脉", "o": "微细涩脉总属虚候，以气血两虚、阳气虚衰为核心病机。微主阳虚，细主血少，涩主血行不畅，三者相合，反映阳气虚衰、阴寒内盛，鼓动无力，脉道不充，血行滞涩。其主病机可归纳为气血两虚、阳虚阴寒、瘀滞及病危胃气绝四类。气血两虚与阳虚阴寒互为因果，因虚致滞则生瘀滞，久虚不复", "c": "主气血两虚"}, {"id": "c:细+微", "n": "微细脉", "o": "微细脉总属正气虚衰之脉，以阳气衰微、阴血不足为基本病机。微为阳衰，细为阴弱，合见则阴阳气血俱虚。其具体所主，或为阳衰阴盛之寒证，或为气血两虚之虚损，或为虚脱危候，或为虚寒内盛，或为虚阳浮越之假热，或为正虚邪恋之余邪未清，或为中阳困顿之脾胃虚寒。诸类之间，以正虚", "c": "主阳衰阴盛"}, {"id": "c:细+微+软", "n": "微细软脉", "o": "微细软脉总属虚证，主气营大亏。其脉象由微、细、软三象复合而成，分别对应阳气衰微、阴血不足、气营两亏，三者相互关联，共同反映气血阴阳俱虚之病机。原文以“脉微细软”为据，断为“气营大亏，非补不可”，强调虚证当补。微主阳衰，细主阴亏，软主气营两亏，三者从不同侧面揭示", "c": "主阳气衰微"}, {"id": "c:细+微+弱+迟", "n": "微细迟弱脉", "o": "微细迟弱脉总属虚寒之象，以阳气衰微、气血不足为核心病机。微细主气衰血少，迟弱主阳虚无力，四象相合，多责之脾肾阳虚、阴寒内盛。其具体所主，一为阳虚气衰，二为虚寒水停，三为气衰血少。三者相互关联：阳气虚衰则气不化水，水湿停聚而为水臌；阳虚日久，气血生化不足，则脉道", "c": "主阳虚气衰"}, {"id": "c:细+微+缓+迟", "n": "微细迟缓脉", "o": "微细迟缓脉在此段中总主燥热内伏、阳气不达之病机。其脉象微细迟缓，非虚寒之征，乃燥热深伏、阻滞阳气外达所致，故身反不热。脉愈迟弱，则燥热愈甚、病情愈重；若脉近洪数，则为鼠疫最轻之候。服药后脉起身热，为郁闭渐开、阳气来复之向愈佳兆。可见此脉既主燥热内伏之病机，又主", "c": "主燥热内伏"}, {"id": "c:微+结", "n": "微结脉", "o": "微结脉总属虚中夹滞之象。微为气血阴阳不足，结为脉气阻滞，故其病机以虚为本、以滞为标。所主病机主要有四类：虚中夹滞、阳微饮结、痰阻脉络、寒滞胞宫。四者皆不离虚与滞，但侧重不同：虚中夹滞泛指气血虚衰兼脉气不利；阳微饮结侧重阳气衰微、饮邪结聚；痰阻脉络侧重痰块堵塞隧", "c": "主虚中夹滞"}, {"id": "c:微+缓+伏", "n": "微缓伏脉", "o": "微缓伏脉总起来主积气初结之病。其脉象微而兼缓或急，微主病势尚浅，缓主湿滞气结，急主气结有形或寒凝气逆。原文以心脉微缓为伏梁、肝脉微急为肥气、肾脉微急为奔豚为例，说明不同脏腑积气初结时，脉象均可见微而兼缓急，但病位与病性有别。微脉贯穿诸证，提示积气未深；缓急则分", "c": "主积"}, {"id": "c:细+微+涩+濡+紧+缓", "n": "微缓涩紧细濡脉", "o": "微缓涩紧细濡脉总起来主寒、热、风、湿及虚损诸病机。原文以脚气与痿病并列，从脉象分述虚实寒湿之异：迟主寒，数主热，浮滑主风，濡细主湿，而微缓涩紧细濡则多见于痿病肺虚，示气血不足、经脉失养。各类之间，寒热风湿为外邪为病，虚实为内伤基础；微缓涩紧细濡诸脉或主湿滞，或", "c": "主寒"}, {"id": "c:微+缓", "n": "微缓脉", "o": "微缓脉总起来主正气不足与邪退正复两类病机，以虚为本。微为阳气衰微、卫气疏泄，缓为脾胃虚弱、胃气尚存。其主虚，涵盖气血阴阳亏虚、脾胃虚寒、胃气衰败，甚则本虚标实、攻补两难；其主实，则见于卫疏荣盛之血崩，及外感邪退正复之欲愈。各类之间以“虚”为枢：微缓并见，虚多实", "c": "主虚（气血阴阳）"}, {"id": "c:微+弱+缓+软", "n": "微缓软弱脉", "o": "微缓软弱脉总起来主久病正虚而胃气未绝之顺候。其核心病机为正气不足，但脾胃之气尚存，脉证相合，故为可治之象。原文以暴病脉浮洪数实为顺、久病脉微缓软弱为顺，说明不同病程阶段脉象顺逆有别。微缓软弱脉所主三类病机相互关联：久病正虚是其基础，胃气未绝是其关键，脉证相合是", "c": "主久病正虚"}, {"id": "c:微+缓+长", "n": "微缓长脉", "o": "微缓长脉总起来主脾病而胃气尚存、中气未败之候。微缓为脾虚有湿之常脉，缓主湿，微为阳气不足，故主脾虚湿困，症见饮食不消、腹胀、体重节痛、大便不利；长脉则示胃气尚存、病未深入，非邪气亢盛之弦急脉。二者相合，说明脾病虽见运化不健，但正气未竭，故原文断为‘可治’。三类", "c": "主脾虚湿"}, {"id": "e:微", "n": "微脉", "o": "微脉总属正气虚衰之脉，以阳气衰微、气血不足为基本病机。其主病虽繁，约之可分虚实两端：虚者阳气衰微、气血两虚、虚脱危候、虚寒内盛、虚阳浮越、虚风内动；实者正虚邪恋、虚实夹杂。微脉之象，轻则气血不足、中阳不振，重则阳气欲脱、阴阳离决。各证之间以‘虚’为纲，阳衰则寒", "c": "主阳衰"}, {"id": "c:微+芤", "n": "微芤脉", "o": "微芤脉总起来主失血，其病机核心为阳气衰而阴血脱。微脉主阳气虚衰，鼓动无力；芤脉主阴血脱失，脉道空虚。二者相合，提示血去络空、气血两伤之虚象，非实邪为患。因血脱则气亦衰，阳气不足则脉微，阴血亏耗则脉芤，故临床多见于失血之后，并伴络脉失养之隐痛。诸类病机以失血为总", "c": "主失血"}, {"id": "c:细+虚+微", "n": "微虚细脉", "o": "微虚细脉总属虚损，主阳气虚与阴血不足。微为阳气虚，虚细为阴血不足，故脉微虚细者，气血阴阳俱虚，禁吐下，恐虚其胃气。然脉随病机而变，伤寒不同阶段脉象有浮沉转能变化：邪在表脉浮，可汗；邪结在脏脉沉实，可下。微虚细脉出现，提示正气已虚，当随时形势救解，不可妄攻。各类", "c": "主阳气虚"}, {"id": "c:虚+微+软", "n": "微虚软脉", "o": "微虚软脉总属正气大虚、阳气衰微之候。其脉象由微、虚、软三象复合而成：微主阳衰，虚软主气血大亏，三者相合，反映气血阴阳俱虚，尤以阳气衰微为关键。在此基础上，虚阳失于依附而浮越于上，出现额汗头震、闻声惊惕、多语神烦等症，甚则二气脱离，危在旦夕。故本脉所主病机以阳衰", "c": "主阳衰"}, {"id": "c:微+迟", "n": "微迟脉", "o": "微迟脉总以阳气衰微、阴寒内盛为基本病机。微主阳衰，迟主阴盛，二者合见，反映脏腑虚寒、气血不足。其具体所主包括阳虚阴盛、虚寒泄痢、寒凝血脉、胃气衰败、血虚风动、肺气虚寒及正虚热结等。各证之间相互关联：阳虚阴盛为总纲，虚寒泄痢、寒凝血脉、胃气衰败、肺气虚寒皆属阳虚", "c": "主阳虚阴盛"}, {"id": "c:微+长", "n": "微长脉", "o": "微长脉总起来主邪退正复、病将向愈之候。其脉象由微、濇、长三部分组成：微示表邪已衰，濇示营血暂不畅，长示正气渐复、胃气来复。三者合参，反映太阴中风后邪气渐退、气血渐和的动态转归。所归纳四类病机中，'主邪退向愈'为总纲，统摄表邪已衰、营血不畅与正气渐复三个环节。微", "c": "主邪退向愈"}, {"id": "c:急+促", "n": "急促脉", "o": "急促脉总属危候，其病机核心为正气衰败与邪热鸱张，并可导致血气败乱、上热下寒。正气衰败则阴阳将脱，脉数而迫促；邪热鸱张则逼迫脉道，亦见急促。血气败乱则脉急促如喘，发为暴厥不语；上热下寒、水火不交则脉亦急促，发为昏眩。四类病机相互关联：正气衰败为根本，邪热鸱张为标", "c": "主正气衰败"}, {"id": "c:和+急", "n": "急和脉", "o": "急和脉总起来主正虚邪留、气阴两伤、暑热内伏之病机。脉急未和，为脉道失于柔和之象，多因热久呕多，伤阴耗气，正虚而余邪未清所致。其类别之间相互关联：暑热内伏为病因，气阴两伤为病机基础，正虚邪留为病势概括。脉急未和既反映邪热未清，又提示正气已伤，故治疗需辅正兼理余波", "c": "主正虚邪留"}, {"id": "c:大+急+坚", "n": "急大坚脉", "o": "急大坚脉总属邪盛而脉失柔和之象，其病机以邪实壅盛为核心，兼涉阳气衰微与胃气败绝。原文三段均见'寒气上攻'或'寒气暴上'，脉急大坚，示寒邪实邪亢盛，正气尚能抗邪则脉应之而急大坚。然其吉凶顺逆，全在兼脉与症候：兼滑则营卫尚通、胃气未败，主生；兼涩则气血凝滞、邪无出", "c": "主邪盛"}, {"id": "c:数+大+急", "n": "急大数脉", "o": "急大数脉总起来主内伤脏腑失调、虚实夹杂之病机。其脉象急为弦急，属肝木；大为洪大，属心火；数为热象；时一代而涩，则属脾胃气不相接、肺之本脉。四类病机相互关联：脾胃不足为内伤之本，饮食不时、寒温失所损伤胃脉，致气不相接而见代涩；脾胃一虚，则肝木易亢、心火易炎，肝木", "c": "主脾胃不足"}, {"id": "c:数+大+涩+急", "n": "急大涩数脉", "o": "急大涩数脉总起来主邪正交争、虚实夹杂之病机。其脉象急主拘紧，大主邪盛，涩主气滞血阻，数主热与邪争。原文以人迎气口分内外伤：人迎脉大为外伤，气口脉大为内伤。外感风寒者，急大涩数见于左寸人迎，为客邪有余之表实证；内伤饮食与劳役不节者，急大涩数见于右寸气口，为不足之", "c": "主外感风寒"}, {"id": "c:急+平", "n": "急平脉", "o": "急平脉总属正虚邪留、邪正交争之象。其脉急而不甚数，或兼虚象，反映正气已亏而邪气未解，寒热错杂，腠理空疏。各段所论，或为阴暑正虚邪留，或为质虚加感、寒热复作，皆以正虚为本，邪郁为标。急脉主邪正交争，虚急并见则示元亏未复；弦急则邪郁未解，正气受亏。诸类之间，正虚邪", "c": "主正虚邪留"}, {"id": "c:急+疾", "n": "急疾脉", "o": "急疾脉总属邪盛正危、气血急迫之象，其病机涵盖热盛、阴竭阳越、气血逆乱、痛寒及癫疾五类。热盛为急疾脉最常见之因，阳热急迫则脉来急疾有力；若热伤阴络、阴血暴脱，则阴不制阳、虚阳外越，脉急疾而歇止复来，属危候。气血逆乱者，脉急疾如狂风骤雨、气机断续，多见于胎气上逼或", "c": "主热盛"}, {"id": "e:急", "n": "急脉", "o": "急脉总以脉道拘紧不柔、劲急失和为特征，所主病机广泛。其核心为“拘急”：或由外寒收引、或由血虚失养、或由风动筋急、或由热盛势迫、或由气火亢逆、或由中虚气陷，皆可使筋脉拘挛而脉急。寒与热为两端：寒主收引凝滞，热主势迫交争；虚与实亦相对：血虚、中虚属正虚失养，气逆、", "c": "主寒收引"}, {"id": "c:浮+散+乱", "n": "散乱浮脉", "o": "散乱浮脉总属危重之候，主正气涣散、元气将脱、阴阳离决。其脉象散乱如水上浮麻，不分至数，浮而无根，反映根本动摇、气不归元。所主病机以虚脱为核心：元气将脱则脉散乱无根；阴阳离决则脉浮麻无绪；正气涣散则脉道不聚；肺肾气竭则喘促而脉散。四类相互关联，总由久病或温病后期", "c": "主元气将脱"}, {"id": "c:散+乱", "n": "散乱脉", "o": "散乱脉总属危候，主正气涣散、根本离决。其核心病机为元气耗散，或由久病虚衰，或由误治伤正，或由大吐大泻、产后血崩，致气散不收、脉道失序。在此基础上，可演化为阴阳离决、胃气败绝、气血耗散、虚阳外浮及心气耗散等具体类别。各段原文多伴“忽有忽无”“如解索状”“重按全无", "c": "主元气涣散"}, {"id": "c:散+代", "n": "散代脉", "o": "散代脉总属脉气不续、歇止不匀之象，所主病机以虚实夹杂为要。其偏实者，或为阳盛热结、壮火烁阴，脉见促急歇止；或热盛引动肝风，风火相煽。其偏虚者，或气阴两虚、脉气不敛，或真气衰惫、元气下陷，脉见歇止无力。四类之中，热盛与肝风多属邪实，气阴两虚与真气虚多属正虚，然临", "c": "主热盛"}, {"id": "c:大+缓+散", "n": "散大缓脉", "o": "散大缓脉总属大虚之候，以气虚外散、脾胃大虚为核心病机。散大主气虚外散，缓大无力主脾胃大虚，二者相合，反映气血亏虚、中焦运化失职。脾虚则痰湿内生，故兼见吐痰相续；清阳不升则头目昏眩而重；四肢失养则手足无力。此脉重按皆无力，非风邪外袭，若误投风药，必致正气更虚，至", "c": "主气虚外散"}, {"id": "c:大+散", "n": "散大脉", "o": "散大脉总属正气耗散、阳不内守之候，其核心病机为“散”与“大”并见，示气机不能收敛。具体可分：气散阳脱者，脉散大无伦，伴汗多喘喝、面赤戴阳，为亡阳危候；气血耗伤者，脉大而散弱，见于劳倦、失血、营阴亏虚；中气虚寒者，脉散大无力，主中气不足、摄纳无权；元气虚散兼瘀者", "c": "主气散阳脱"}, {"id": "c:小+散", "n": "散小脉", "o": "散小脉总属气散不收、气血耗散之候。其脉道不敛，浮散无根，反映正气耗散、气阴不固。所主病机以气散为核心，进而导致气血耗散、气化失司、水液不行。原文虽仅见小便不利一症，但以散脉点明气阴耗散、水道失调之机，生脉散益气敛阴正合此理。三类病机相互关联：气散为根本，气血耗", "c": "主气散"}, {"id": "c:数+弱+散", "n": "散弱数脉", "o": "散弱数脉总属虚损之候，以气血亏耗为本，虚热为标。左脉小弱而数、右脉散弱而数，俱近六至，数而无力，明示非实热而是虚热。气血亏耗则脉道不充，故见小弱散弱；阴血不足则虚火上炎，故脉数无力而见午后烦热、鼻衄、盗汗梦遗等症。脾虚湿郁化热，则食后吐酸、结痰注胸、食饭干恶难", "c": "主气血亏耗"}, {"id": "c:涩+散", "n": "散涩脉", "o": "散涩脉在原文中仅见于“太素之说”一段，其核心特征为“脉形散涩，至数模糊”，被归为“浊”脉。散者脉气不敛、涣散不收，涩者往来艰涩不畅，至数模糊则节律不清，三者共同反映脉气散乱不聚、清浊相干之病机。原文以此脉主“质浊脉浊”之候，具体涉及三类：一是脉气散乱，为浊脉之", "c": "主脉气散乱"}, {"id": "c:缓+散", "n": "散缓脉", "o": "散缓脉总属虚候，以气虚不敛、脾胃大虚为核心病机。散主气虚外散，缓主脾土本象而缓大无力，二者相合，反映气血亏虚、中焦运化失职。其具体脉象如散大缓脉侧重脾胃大虚、气虚外散，兼见痰湿内生、清阳不升；濡散缓脉则脾虚为本、湿滞为标，气虚不敛。此外，七情所伤，喜伤心则脉散", "c": "主七情气缓"}, {"id": "e:散", "n": "散脉", "o": "散脉总属正气涣散、根本离决之候，其核心病机为元气耗散、气不收摄。从所收段落看，散脉所主可归纳为气散阳脱、气阴两伤、血脱虚损、虚阳外浮、中气败绝、神气浮越六类。气散阳脱为急危之候，多见汗多喘喝、面赤戴阳，脉散大无伦；气阴两伤多见于暑热、久病，脉散而数或散弱，生脉", "c": "主气散阳脱"}, {"id": "c:虚+散", "n": "散虚脉", "o": "散虚脉总属正虚失守、气耗不收之候，其病机以气虚不固、虚阳浮越为核心，并可因误治而见虚寒戴阳。散脉之象，乃气耗于内，阳浮于外，脉道弛纵不收所致。所主病机虽有气耗、阳浮、戴阳之分，然皆不离“虚”与“散”二字：气耗不收为散脉之根本，虚阳浮越为气耗之发展，戴阳则为虚寒", "c": "主气耗不收"}, {"id": "c:数+伏", "n": "数伏脉", "o": "数伏脉总主热郁邪伏之病机。数脉主热，伏脉主邪郁深伏，二者相合，表明热邪郁于内而不得外达，或邪气闭阻而热蒸于内。具体而言，可因热郁气分、营卫不通而见；可因邪郁腠理、玄府不开而呈三阳表实；可因湿浊壅遏、热不得透而为湿温重证；可因风痰热浊交阻胆胃而致络气失宣；亦可因", "c": "主表实"}, {"id": "c:数+芤+促", "n": "数促芤脉", "o": "数促芤脉总起来主热、虚、失血伤阴及气逆四类病机，核心为劳损日久、下焦损伤、冲脉气逆所致阴损及阳、胃气将败之候。数促主热主虚，芤主失血伤阴，数促又为阳亢气逆。诸类相互交织：热与虚并见，因劳损数年、阴血大伤而阳热亢盛；气逆因冲脉震动、诸脉皆逆；失血伤阴则因大汗泄越", "c": "主热"}, {"id": "c:数+微+弱+动", "n": "数动微弱脉", "o": "数动微弱脉总属阴阳俱不足之虚证。其脉数动似热，微弱主虚，合而观之，乃虚家之象，根本在于气血阴阳亏虚。因虚致津液不足，故见大便难、腹中干、胃燥而烦；数动之热象仅为假象，与实热‘根本异源’。三类病机以‘主虚’为核心，‘主津亏’为虚之具体表现，‘主虚热假象’为脉象易", "c": "主虚"}, {"id": "c:数+动+疾", "n": "数动疾脉", "o": "数动疾脉总属阳亢阴亏、风火内动之象。其脉数主热，动主阳，疾主急，三象合见，反映阳气不能潜伏，阴液日就枯槁。所主病机主要有三：一为阳亢阴亏，阴不制阳，阳气浮动；二为风火内动，虚风上扰，火升眩晕；三为痿躄筋枯，阴液枯涸，筋骨失养。三者相互关联，阳亢阴亏为根本，风火", "c": "主阳亢阴亏"}, {"id": "c:数+缓+和", "n": "数和缓脉", "o": "数和缓脉总起来主邪正消长与脏腑虚实。其核心病机包括邪热渐退、阴虚火旺、痰热壅肺、真阴不足及肝木犯土。数势缓和多示邪热渐退、正气渐复，为向愈之象；急数则主阴虚火旺，虚热内扰；滑实弦长有力主痰热壅肺；左脉细小无神主真阴不足；关部带弦主肝木犯土。各类之间相互关联，反", "c": "主邪热渐退"}, {"id": "c:数+和", "n": "数和脉", "o": "数和脉总以‘数’为纲，主热为根本，然其兼象不同，所主病机有别。数而和缓者，多主邪热渐退、正气渐复，如等段所言‘脉数较和’‘脉数稍和’‘些数而和’，皆为热势渐缓之征；数而不和或沉而无力者，则主虚火、虚阳外浮，如所论阴津未充、虚阳未敛、几而无水；数而兼滑者，主痰滞", "c": "主热"}, {"id": "c:数+坚+硬", "n": "数坚硬脉", "o": "数坚硬脉总属热实之候，尤以下焦火盛为要。数脉主热，坚硬主实，二者相合，示邪热内盛、正气未衰之实证。原文左尺坚硬，左尺候肾，故病位偏于下焦，火邪亢盛，下迫肛门则火热滞坠，下注膀胱则小溲热痛；火热上冲，肺胃之气欲降不能，遂成呃忒。此脉所主，以热与实为纲，下焦火为核", "c": "主热"}, {"id": "c:数+大+坚", "n": "数大坚脉", "o": "数大坚脉，总属肝阳亢盛、气升血逆之候。左脉数大而坚，左属肝，数大为阳亢，坚为气结劲急，三者相合，揭示肝气劲急、阳亢化火、气机上升太过，血随气逆。其成因多由用力致伤，伤及肝气，气结化火，进而气升血上而失血。故本脉所主病机可归纳为肝阳亢盛、气升血逆、用力致伤三类，", "c": "主肝阳亢盛"}, {"id": "c:数+大+疾", "n": "数大疾脉", "o": "数大疾脉总属阴火虚阳上逆之象。其脉数主热，大主虚阳外浮，疾为阴火奔迫，三者相合，反映肾阴亏耗、阴火上炽、虚阳上浮的复杂病机。此脉虽见数疾似实热，实为虚火奔迫所致，故舌见碎红裂纹，病本在肾，他脏皆末。与洪大数疾脉之实热亢盛不同，数大疾脉更侧重于阴火虚阳的病理特点", "c": "主阴火虚阳"}, {"id": "c:数+大+虚+空", "n": "数大空虚脉", "o": "数大空虚脉总起来主正虚邪实、寒热错杂之复杂病机。数大主热，空虚主正气不足，尺脉洪盛示少阴受邪，三者并见，提示热邪内盛而正气已虚，且邪犯少阴。本案喻嘉言判为“两病凑于一时”：内有湿热欲成痢，又犯房劳骤寒乘少阴，形成太少两感、正虚邪实之局。故其病机涵盖热盛、正虚、", "c": "主热"}, {"id": "c:数+大", "n": "数大脉", "o": "数大脉总属邪热炽盛之象，数主热，大主邪盛，合而显热势鸱张。其病机涵盖实热、湿热、热毒、痰火、郁热等实热类，以及虚火浮越之虚热类，并可预示病进。实热类脉多有力，症见壮热烦渴；湿热类兼湿象，苔厚腻；热毒类局部红肿痛；痰火类兼痰象；郁热类因气郁化火；虚火类脉按之无力", "c": "主实热"}, {"id": "c:数+大+虚+小", "n": "数大虚小脉", "o": "数大虚小脉包括数大与虚小两种脉象，总起来主邪热与正虚两类病机。数大脉主邪热亢盛，虚小脉主正气不足。在病程中，脉由数大转为虚小无力，反映邪热虽减而正气亦虚，形成邪减正虚之候。原文强调此脉象变化为转危之兆，防神糊痉厥等变，提示正虚易致风动神浮。三类病机相互关联：邪", "c": "主邪热"}, {"id": "c:数+大+软", "n": "数大软脉", "o": "数大软脉总属正虚邪实、虚热与瘀滞并见之候。其数主热，大示邪盛，软为气阴不足，故单见则主气阴两虚、虚热内生；若与弦紧并见，则示瘀血内阻、瘀热交结，形成正虚邪实之危候。原文所载'右脉数大而软，左脉弦紧而数'，合参恶露全无、腹膨鼻煽、便泄气急等症，断为'瘀血内阻、虚", "c": "主虚热"}, {"id": "c:数+实", "n": "数实脉", "o": "数实脉总主实热壅盛、邪气壅结之证。数主热，实主邪盛，二者相合，提示热邪炽盛与邪气壅实并存。其具体病机可归纳为：实热壅盛于脏腑经络，如肺痈、丹毒、时毒；里热结聚于阳明，如燥结、便闭；痰食积滞与热交结，如食积腹痛；热郁血络，迫血妄行；热极生风，闭阻气机；热毒成痈，", "c": "主实热壅盛"}, {"id": "c:数+平", "n": "数平脉", "o": "数平脉总属热势渐退而余邪未清、正气未复之候。数脉本主热，今数象较平，说明火热已减，病势向愈，故其总病机以'热退未净'为核心。具体而言，或为余热未清，或为热势渐退，或为正虚未复，三者常相互关联：热退则数平，余热未尽则数未全平，热伤阴分则正虚难复。此外，数平脉可兼", "c": "主余热未清"}, {"id": "c:数+弦+虚+实", "n": "数弦实虚脉", "o": "数弦实虚脉总起来主邪实内盛、气滞热结，兼有正虚之象。数主热、主邪盛，弦主痛、主气滞，二者相合，反映热邪与气滞互结，营气阻滞，气聚成形，故见腹中痛胀、寒热往来等实象。然原文谓“恐从实变虚”，提示邪实日久耗伤正气，病机由实转虚，实中夹虚，预后堪虑。各类病机中，热与", "c": "主热"}, {"id": "c:数+弦+细+涩+弱", "n": "数弦涩细弱脉", "o": "数弦涩细弱脉总以数脉为纲，兼见弦、涩、细、弱等象。其总病机为寒热错杂、虚实并见，不可一概以热论。原文强调数脉有阴有阳：滑数、洪数多热，涩数、细数多寒；暴数多外邪，久数必虚损；又主痈疡。可见数脉所主，既有实热、外邪、痈疡等实性病机，又有虚寒、虚损等虚性病机。各类", "c": "主热"}, {"id": "c:数+弦+硬", "n": "数弦硬脉", "o": "数弦硬脉总起来主热盛、津伤、血虚、虚热之病机。数主热，弦硬为脉道失柔，可由实热炽盛、津液耗伤所致，如阳明热盛谵语之案；亦可由阴血亏虚、筋脉失养而生，如心脾血液短少之怔忡不寐。实热与虚热均可致数，弦硬则反映津血不足、脉失濡润。四类病机相互关联：热盛易伤津，津伤可", "c": "主热盛"}, {"id": "c:数+弱+缓", "n": "数弱缓脉", "o": "数弱缓脉总属脾虚气郁、郁热内扰之候，以脉数而弱为核心特征。数主郁热，弱主脾伤气弱，二者并见，反映忧思伤脾、气郁化热之病机。若经补脾散郁，脉转稍缓而健，则示胃气渐复、中气渐振、郁热渐退，为病势向愈之兆。三类病机相互关联：脾虚气郁为病本，郁热内扰为病标，中气渐复为", "c": "主脾虚气郁"}, {"id": "c:数+微+促", "n": "数微促脉", "o": "数微促脉总起来主热、火盛气逆、阴液亏耗及脏气不相接续。数为有热，促为脉来急迫而时一止，主火盛气逆、阴液亏耗。原文谓嗜饮伤肺、屡次见红、久咳不止，金水并亏，症入损门，数促之脉反映虚火内炽而脏气不相接续，故虽可苟安目前，难免颓败日后，属损证预后不良。各类之间相互关", "c": "主热"}, {"id": "c:数+弦+微", "n": "数微弦脉", "o": "数微弦脉总以数主热、弦主肝郁为纲，微弦示郁热不剧或正虚邪恋。所主病机可归为六类：肝郁化热、阴亏火旺、风热犯肝、热郁于肺、疟后邪恋、脾虚湿蕴。其间以肝为核心，肝郁化热与阴亏火旺常互为因果，肝阳上亢则刑金犯肺，风热外袭亦通于肝；疟后邪恋属正虚余热未清；脾虚湿蕴则土", "c": "主肝郁化热"}, {"id": "c:数+急+疾", "n": "数急疾脉", "o": "数急疾脉总属阳热急迫之象，其病机有实有虚，预后迥异。实者主火毒炽盛，脉来数急疾而有力，症见发热谵语、狂妄躁乱、大渴大烦、便秘溲赤，为痰热与火毒交炽、充斥内外之阳热实证，治当清火解毒、泻热存阴。虚者主阴竭阳越、胃气衰败，脉来数急疾而绝止复来，或如屋漏、雀啄，为脏", "c": "主火毒炽盛"}, {"id": "c:数+缓+急", "n": "数急缓脉", "o": "数急缓脉在此段中并非单一脉象，而是复诊时对脉象变化的描述：肺脉数急已缓，左关弦劲未舒。总起来看，此脉主热郁、肝旺、脾虚及筋惕四类病机。数急主肺中郁热，热势急迫；弦劲主肝木过旺，气郁化火；木旺侮土则脾虚不运，痰饮内生；脾虚肝旺、筋脉失养则见筋惕。四类之间相互关联", "c": "主热郁"}, {"id": "c:数+急", "n": "数急脉", "o": "数急脉总以热盛为其主，数主热，急主势迫，故凡实热、暑热、疫毒、风火痰热内盛者，脉多见数急。然热盛易伤阴，故又常见热盛阴伤之候；若正气大虚，虚阳浮越，或阴阳两竭，脉亦可见急数无伦，此为危候。此外，伤寒邪传里、邪客肠胃、风火痰热内闭，以及肝虚寒热错杂等，亦可出现数", "c": "主热盛"}, {"id": "c:数+散", "n": "数散脉", "o": "数散脉总属正虚失守、虚热内扰之候，其核心病机为气血亏虚、正气耗散，散而不敛是脉象关键，数则为虚而失守、脉无根蒂之暂象，非实热可比。所主病机可归纳为五类：虚损、虚热、精脱、邪热正散、表热。其中虚损为根本，气血亏耗则脉道不充而见散弱；虚热由虚而生，阴血不足则虚火上", "c": "主虚损"}, {"id": "c:数+沉+动", "n": "数沉动脉", "o": "数沉动脉总起来主里热未清、正气抗邪、阴血略伤之病机。数主热，沉主里，故脉数沉为里热内蕴；数沉中见生动之机，示正气尚能抗邪，为邪正相争之象；尺涩则示阴血不足或湿滞，乃热邪伤阴之征。三类病机相互关联：里热为病之本，正虚抗邪为病之转归，阴血不足为热伤之果。北政之年太", "c": "主里热"}, {"id": "c:数+沉+涩", "n": "数沉涩脉", "o": "数沉涩脉总起来主瘀血内结与阴虚火旺两类病机。沉主里，涩主血行不畅或阴亏血少，数主热或虚火。若瘀血内结，则沉涩为瘀阻，数因瘀久化热，见癥块坚痛、经血紫黑；若阴亏血少，则涩为血虚，数为虚火，见形瘦喉痛、虚火上炎。两者皆以沉涩为基础，数则示热象，但一为实瘀化热，一为", "c": "主瘀血内结"}, {"id": "c:数+滑+浮+空", "n": "数浮滑空脉", "o": "数浮滑空脉在此段中实以“数浮滑不空”与“空豁虚弦”对举，主实证痰热。数主热，浮主表，滑主痰，三脉合见，总归痰热壅盛于肺胃，属风温外感、痰火内蕴之实候。其脉“不空”是与虚证鉴别的关键：实者脉数浮滑不空，虚者脉空豁虚弦。故本脉所主病机以热、痰、表实、痰热壅盛四类为", "c": "主热"}, {"id": "c:数+浮+软", "n": "数浮软脉", "o": "数浮软脉总起来主虚热与正虚邪恋之证。其核心病机为阴亏火旺，数脉主热，浮软无力则非实火，乃肾阴亏损、水不制火之虚热。由此衍生三类相关病机：一是暑热挟虚，浮弦软数并见，暑热外扰而真阴内亏；二是疟邪未清，暑热化疟，邪恋伤阴；三是风邪上攻，浮软小数，高年气血不足而风邪", "c": "主阴虚火旺"}, {"id": "c:数+涩+小+结", "n": "数涩小结脉", "o": "数涩小结脉总主火郁、血瘀、气滞、痰火互结之复合病机，核心为五志过动、相火内寄肝胆，操持郁勃致木火劫烁。数主火动，涩主血滞络阻，小主阴伤，结主气机郁滞。四类病机相互关联：气郁化火为始，火灼络伤致瘀，瘀阻气机生痰，痰火瘀互结，故脉见数涩小结。原文强调‘非精血损怯’", "c": "主火郁"}, {"id": "c:数+滑+大+小+濡", "n": "数滑大小濡脉", "o": "数滑大小濡脉并见，总主热、痰、邪实与津亏。数主热，滑主痰，大主邪实，小濡主津亏。此脉象反映痰热蕴结、邪实壅盛而兼津液耗伤之病机。原文指出“蕴结之气分渐开，而霍霍痰鸣，肺胃之邪热尚炽，火与痰激”，说明痰与热搏结，邪实亢盛；右部搏指为肺胃热炽，左部小濡为热灼津亏。", "c": "主热"}, {"id": "c:数+实+牢", "n": "数牢实脉", "o": "数牢实脉总起来主火盛、邪结深痼与气逆上冲。数脉主火盛，牢实主邪结深痼，二者相合，反映火邪内盛、结聚深痼，并致气逆上冲。本案厥阳木火挟心胞之火上凌巅顶，火升气逆，故见心悸、项痛、头重眩晕、神志模糊、口涌血沫、四肢搐搦，溺则气降乃苏。脉证合参，病属痉厥重候，邪势鸱", "c": "主火盛"}, {"id": "c:数+弦+微+疾", "n": "数疾微弦脉", "o": "数疾微弦脉总起来主失血后营血大伤、脾阳不振、痰浊阻壅之虚实夹杂证。数疾为营血大伤、虚热内动之象，微弦示肝脾失调，右寸关锐快则反映痰浊阻壅。三者相互关联：营血大伤则阴不敛阳，虚热内生；脾阳不振则运化失职，痰浊因之阻壅；痰浊中阻又进一步影响脾运，形成恶性循环。原文", "c": "主血虚火旺"}, {"id": "c:数+疾", "n": "数疾脉", "o": "数疾脉总属阳热急迫之象，其病机以热盛为核心，然有虚实之别。实者邪热亢盛，如阳明腑实、温邪内陷，脉数疾有力；虚者阴伤阳亢，如失血、虚劳、产后，脉数疾而虚。热盛可灼阴，阴伤可生热，二者互为因果。气火失血乃热迫血妄行，虚劳损怯为阴亏日久成损，湿热蕴伏则虚中夹实。若脉", "c": "主热盛"}, {"id": "c:数+大+空", "n": "数空大脉", "o": "数空大脉由数、空、大三种脉象复合而成，总起来主热盛、阴伤、正虚邪盛及肺虚湿热等病机。数脉主热，大脉主邪盛，空大脉主阴气不足、脉道不充。数大与空大并见，既反映邪热内盛，又提示阴液已亏，形成正虚邪实、本虚标实之复杂格局。若见于右寸，则主肺阴亏虚、虚热内扰，兼阳明湿", "c": "主热盛"}, {"id": "c:数+弦+空", "n": "数空弦脉", "o": "数空弦脉总属邪热未清、阴液耗伤之候，其病机以热盛阴伤为核心。数主热，示邪热炽盛；空主阴亏，示真阴耗竭；弦主痰热内郁，示气机阻滞。三者相合，反映热邪留恋而阴精已伤，虚实夹杂。各段原文均见热象与阴伤并现，或兼痰热内郁。病机演变多由热邪炽盛，灼伤阴液，或汗下后阴伤而", "c": "主痰热"}, {"id": "c:数+细+大", "n": "数细大脉", "o": "数细大脉总起来主热盛与阴虚两类病机，并可呈现虚实夹杂之象。数脉主热，大脉主邪盛，细脉主阴亏。原文「脉数左细右大，阳明有余，少阴不足」表明：右大数为阳明络热有余，左细为少阴阴液不足。故其病机一为实热壅盛（阳明有余），二为阴液亏虚（少阴不足），二者常并见形成虚实夹", "c": "主热"}, {"id": "c:数+细+急", "n": "数细急脉", "o": "数细急脉总起来主虚火内炽、阴液亏耗、脏气不安之虚损证候。其核心病机为阴亏火旺，脉细为阴伤，数为虚火，急为脏气不安，三者相合，反映本虚标实、脏腑功能失调。此脉多见于虚损不复之候，如脾肺肾三脏并亏，脾失运化则生痰，肺失肃降则呛咳，肾失摄纳则气逆，诸症时轻时重。数细", "c": "主虚火"}, {"id": "c:数+缓", "n": "数缓脉", "o": "数缓脉总以数脉主热、缓脉主退为纲，所主病机涵盖实热、虚火、湿滞、郁火及邪退正复五类。数脉为热象，缓则示热势渐减或湿滞为患。实热者，数而有力，见于暑热内蕴、肠胃热结；虚火者，数而无力或细数，见于阴虚火旺、相火不潜；湿滞者，数缓并见而兼湿象，见于湿郁化热或寒湿下注", "c": "主热"}, {"id": "e:数", "n": "数脉", "o": "数脉总以主热为纲，然热有虚实、兼夹之异。实热者，脉数有力，见于外感温热、阳明热盛、热毒壅聚；虚热者，数而无力或细数，主阴血亏虚、虚火内扰；兼痰则滑数，兼湿则濡数，兼郁则弦数或滞数，兼血分则芤数或失血后数。诸类之间，实热可灼阴成虚，虚热可因郁火而炽，痰湿热毒常相", "c": "主热盛"}, {"id": "c:数+虚+动", "n": "数虚动脉", "o": "数虚动脉总属阴气大伤、阳气浮越之候。数脉主热，虚脉主不足，动脉主惊动，三者相合，非实热实火，乃阴精亏耗，不能涵阳，虚阳上浮，虚风内动。其病机核心为阴伤阳浮，进而导致虚风内动，出现头痛、筋惕等症。治疗以镇摄为法，镇摄浮阳，安定虚风。此脉所主，以虚为本，以浮为标，", "c": "主阴伤阳浮"}, {"id": "c:数+弦+迟", "n": "数迟弦脉", "o": "数迟弦脉在此段专指迟弦之象，总主痰饮蟠踞中焦、津液积聚胃口之病机。其脉不数，排除津液枯槁之阴吹；迟弦并见，揭示痰饮内阻、胃气不和。痰饮中阻则九窍不和，故见不寐、不食、不饥、不便、恶水等证。三类病机相互关联：痰饮为病本，津凝为病机关键，胃病为病变所在。治当峻通胃", "c": "主痰饮"}, {"id": "c:数+迟+疾", "n": "数迟疾脉", "o": "数迟疾脉在《三部九候论》中主要反映脉律败乱与形脉相失，总属危重死候。其核心病机为五脏已败、阴阳离绝：脉来乍数乍疏乍迟乍疾，是脉气败乱、阴阳不相维系的征象；形盛脉细或形瘦脉大，是形脉不称、气外浮无根；九候相失、上下左右不可数，是阴阳离绝。诸类之间相互关联，脉律败", "c": "主死候"}, {"id": "u:无力", "n": "无力脉", "o": "无力脉总主正气亏虚，包括气虚、血虚、阳虚及诸虚损。其脉象按之无力，示鼓动不足、脉道不充，故凡气血阴阳亏虚者皆可见之。从原文看，无力脉所主病机以虚为本，或为单纯气虚、血虚，或为气血两虚、脾肾两虚等虚损之候；甚则阳虚阴盛、正不胜邪，出现虚阳外浮、阴阳欲脱之危象。此", "c": "主气虚"}, {"id": "u:无根", "n": "无根脉", "o": "无根脉总属正气虚衰、根本动摇之象，其核心病机为阳气衰绝、阴血脱竭、虚火上浮、气散不敛、寒闭脉道及阴亏液涸。诸类或为阳气暴脱，或为阴血枯竭，或为虚阳浮越，或为气散不收，或为寒邪闭阻，或为阴液亏耗，皆致脉道不充或不通，故按之无根。其中阳气衰绝与寒闭脉道多急危，阴血", "c": "主阳气衰绝"}, {"id": "u:有力", "n": "有力脉", "o": "有力脉总属实证，主邪气盛而正气未衰。其病机以实热为核心，涵盖燥屎内结、痰热壅肺、积滞内停、余热未清及肝热血热等。各段原文均以“有力”示邪实，如“六脉有力有神”“按之搏指”“脉象仍有力”，皆反映脉道充盈鼓动、抗邪有力。实热可结于阳明成燥屎，壅于肺成痰热，滞于肠成", "c": "主实热"}, {"id": "u:模糊", "n": "模糊脉", "o": "模糊脉总属脉气不清、脉道不利之象，其病机核心在于邪壅脉道或正气不充，致使气血运行不畅、脉体模糊难辨。归纳其主病，主要有湿浊壅遏、阳虚湿困、痰浊阻窍、正虚邪陷、湿热秽浊五类。湿浊与湿热秽浊多属邪实壅遏，脉道被蒙；阳虚湿困与正虚邪陷则虚实夹杂，或阳微湿盛，或正虚邪", "c": "主湿浊壅遏"}, {"id": "u:欲绝", "n": "欲绝脉", "o": "欲绝脉总属危候，主阳气衰微、阴寒极盛、生机将息三类病机。其核心为阳气欲脱或阴寒内盛，致脉道鼓动无力而欲绝。第一类阳衰欲脱，见冷汗肢冰、虚阳浮越；第二类阴寒极盛，见厥逆唇青卵缩；第三类生机将息，凭脉判预后吉凶。三者相互关联：阳衰可致阴寒内盛，阴寒极盛又进一步耗伤", "c": "主阳衰欲脱"}, {"id": "u:歇止", "n": "歇止脉", "o": "歇止脉总属脉气不能接续之象，所主病机以正虚为本，邪郁为标。其类有六：正虚邪郁者，营卫不相续；阳气衰微者，阴寒内胜；气血大虚者，脉道不充；痰火壅滞者，脉失柔和；痧毒壅滞者，脉道时阻；脏气衰败者，生气大损。诸类之间，正虚贯穿始终：阳气衰微、气血大虚、脏气衰败皆正虚", "c": "主正虚邪郁"}, {"id": "c:大+沉+伏", "n": "沉伏大脉", "o": "沉伏大脉在原文中专论翻胃之痰气证，总起来主痰气壅滞、痰浊搏结所致的中焦壅塞。沉伏为气机郁闭、痰气内阻之象，大则示痰浊有形之邪搏结亢盛，二者相合，既反映痰气交阻、脉道沉伏，又揭示痰浊结聚、脉体宽大，共同指向中焦气机壅塞、升降失常的病机核心。三类之间层层递进：沉伏", "c": "主痰气壅滞"}, {"id": "c:沉+实+伏", "n": "沉伏实脉", "o": "沉伏实脉总属里实邪结之候。沉伏主病位在里、阳气被遏，实主邪气内结、搏指有力。其病机主要有二：一为寒结，寒邪直中下焦，燥矢内结，阳气不能外达，脉沉伏而实，伴腹大痛、面青黑等症；二为痰阻，痰浊壅塞气道，湿蕴热伏，脉伏而重按沉实搏指，伴脘闷、苔腻、欲呕等症。二者虽病", "c": "主寒结"}, {"id": "c:弦+沉+紧+伏", "n": "沉伏弦紧脉", "o": "沉伏弦紧脉总起来主血气内虚、外邪闭阻、寒凝收引、筋脉拘急之病机，多见于痉病。其核心在于‘血气内虚’为本，亡血筋失所营，外为风寒湿热之邪所中，邪闭于内则脉沉伏，寒凝收引则脉弦紧，筋脉失养而拘急，故见拘挛、反张强直等症。四类病机相互关联：气血内虚是发病基础，外邪闭", "c": "主气血内虚"}, {"id": "c:沉+浮+伏", "n": "沉伏浮脉", "o": "此段主旨不在论脉主病，而是借“六脉沉伏”“脉之沉伏浮盛”说明脉象有沉浮盛衰之变，以喻病有浅深表里之异。因此，沉伏浮脉所主病机并非具体病证，而在于提示病位浅深、表里层次及辨证求源的必要性。三类之间相互关联：脉象沉浮反映病位浅深，进而决定表里异治，而正确辨治又须问", "c": "主病位浅深"}, {"id": "c:沉+涩+弱+伏", "n": "沉伏涩弱脉", "o": "沉伏涩弱脉总起来主内伤气分、脾运不健之证。其脉沉主气病，沉极则伏，示气机郁滞深伏；涩弱久深，示气血不足而运行艰涩。结合原文，饮食内伤见气口急滑，劳倦内伤见脾脉大弱，均以沉伏涩弱为共同脉象。各类病机相互关联：气滞可因食伤而加重，脾虚可致气血不足，气血虚又使气行无", "c": "主气滞"}, {"id": "c:沉+涩+伏+结", "n": "沉伏结涩脉", "o": "沉伏结涩脉总起来主气血内滞、血虚津枯，兼及胃气虚。沉伏反映气血内滞、阳气不达，结涩反映血虚津枯、脉道不利，二者相合，提示虚实夹杂之候。原文患者年五十余、体瘦、便燥、食少、腹痛，虞氏作血虚治，用四物汤加减，说明此脉以血虚津枯为本，气血内滞为标。然药入即吐，又示胃", "c": "主血虚津枯"}, {"id": "c:沉+伏", "n": "沉伏脉", "o": "沉伏脉总属邪闭气壅、阳气不达之象。沉主在里，伏主邪闭，故其病机以实邪内闭为主，如寒痰、热郁、气郁、痰食、秽浊等壅塞气机，使脉道不利；亦可因痛极气逆而见。然邪闭日久或正气本虚，可致阳气衰微，如肾虚、真阳不固、阳气外脱，脉亦沉伏。此外，霍乱、痧证等秽浊之邪闭阻清浊", "c": "主邪闭气壅"}, {"id": "r:沉取", "n": "沉取", "o": "沉取脉所主病机广泛，总以辨虚实为纲。其核心在于通过重按脉象判断正气盛衰与邪气性质：沉取无力、虚豁、少神者主虚，包括气血阴阳亏虚；沉取数实有力者主热，为实热内结；沉取细数芤涩者主血虚火旺或瘀血；沉取弦滑者主痰饮；沉取弦涩者主郁滞；沉取数滑而无力者主正虚邪实。各类", "c": "主虚"}, {"id": "rs:沉取+伏", "n": "沉取·伏脉", "o": "伏脉总属沉脉之极，行于骨间，重按不见，必推筋至骨乃得。其主病机非一，总以邪郁气机、脉道不通为枢。实邪内闭者，或为积滞内凝，或为实热内郁，或为痰浊壅阻，或为郁热厥深，脉多伏而有力、沉实搏指；痛甚气结者，脉亦暴伏，乃气机一时结滞。诸类之间，皆因邪阻气机、阳气不能外", "c": "主积滞内凝"}, {"id": "rc:沉取+和+平", "n": "沉取·和平脉", "o": "沉取·和平脉总起来主病机复杂，既可见于无病之平脉，又可为多种病证之表现。其核心在于脉象虽和平，但重按或特定部位出现异常，提示病机。归纳其主病机，主要有大气下陷、胃热炽盛、肾经实热、上盛下虚、气分阻隔、热盛邪实、脾胃虚弱等七类。这些类别之间，或为虚证，或为实证，", "c": "主大气下陷"}, {"id": "rc:沉取+大+洪", "n": "沉取·大洪脉", "o": "沉取大洪脉总起来主虚实两端，以虚证为多。其核心病机是阳气浮越于外而内里虚寒或气血亏虚，故脉虽洪大，重按却无力、微细、如无甚至散乱，形成‘洪大为假、重按为真’的辨证关键。具体可分为虚阳外浮、气血两虚、虚阳夹痰、阳脱危候、气虚阳浮等类，皆属本虚标实或纯虚之候；仅阳", "c": "主虚阳外浮"}, {"id": "rc:沉取+大+浮", "n": "沉取·大浮脉", "o": "沉取·大浮脉总属虚多实少之候，其核心病机为正气虚馁、虚阳浮越。浮大之象似实，然重按无力、豁然中空或细涩无根，皆示根本空虚。所主三类：一为虚阳外浮，见于真阴虚极、肺肾伤损、气不归元；二为表虚感邪，见于劳倦中虚、误汗伤正、夹阴伤寒；三为气实血虚，乃仲景旧论，亦属真", "c": "主虚阳外浮"}, {"id": "rc:沉取+大+缓", "n": "沉取·大缓脉", "o": "沉取大缓脉总起来主虚，以气虚、脾胃大虚为核心，兼可虚中夹热。其脉象缓大而重按无力，是正气不足、中气外散之象，故原文断为大虚证，治以大补气血。右脉缓大不及左，更提示脾胃虚弱，运化无力。然虚证中若见微渴、大便数日一行，则非纯虚，而为虚中夹热，故震按、俞按提出连柏丸", "c": "主气虚"}, {"id": "rs:沉取+大", "n": "沉取·大脉", "o": "沉取大脉总以'大而重按无力'为辨证核心，主虚证为多，实热较少。其病机可归纳为虚阳外浮、气虚不摄、血虚阴亏、热盛伤阴、虚中夹痰及实热壅盛六类。前三类属正气亏虚、根本动摇，脉虽大而按之无力、中空或散乱，形成'大而似实、重按即虚'之象；热盛伤阴为邪热未清而气阴已伤，", "c": "主虚阳外浮"}, {"id": "rc:沉取+大+虚+洪", "n": "沉取·大虚洪脉", "o": "沉取·大虚洪脉总起来主两类病机：一为实热，一为虚热。实热者，脉洪大滑数、重按有力，主暑热内盛，如阳明热盛之白虎汤证；虚热者，脉洪大而虚、重按全无，主血虚发热或气血俱虚，因阴血亏虚、阳气浮越，证象白虎而脉不长实。两类脉象虽同见洪大，但以重按有力无力为辨：有力为实", "c": "主暑热内盛"}, {"id": "rc:沉取+大+虚", "n": "沉取·大虚脉", "o": "沉取大虚脉总起来主虚证，以正气亏虚、虚阳外浮为核心病机。其脉象特征为浮取或中取脉大，然重按无力、豁然中空，甚至重按全无。此类脉虽见大象，却非实热壅盛，而是因气虚、血虚、阴虚或阳虚，导致阳气不能内守而浮越于外，形成似实实虚之候。所主病机可归纳为四类：气虚不敛、血", "c": "主虚阳外浮"}, {"id": "rs:沉取+实", "n": "沉取·实脉", "o": "沉取实脉总起来主邪热亢盛，或邪实正虚之候。其脉象以重按有力为特征，但需结合兼脉及按之有力程度辨别。若实而兼数、洪、长，多主阳明热盛或少阳阳明合病；若实而重按无力或不实，则主邪实正虚，常见于热盛伤阴或气阴两伤；若弦硬而重按不实，主血亏气逆；若独大而数，主热泻。各", "c": "主热盛"}, {"id": "rc:沉取+弦+沉", "n": "沉取·弦沉脉", "o": "沉弦脉总属里证，以痰饮内停为核心病机，常兼寒、虚、水泛等。沉主里，弦主饮主痛主寒，故沉弦首先反映痰饮内停、气机失调；若重按少力，则提示里虚，尤以脾肾阳虚为著。痰饮久留，可致寒饮上逆，见咳逆、呕恶；阳虚不能化水，则水泛肌肤，见浮肿、溲少。各证常相互兼夹，形成本虚", "c": "主痰饮内停"}, {"id": "rc:沉取+弦+浮", "n": "沉取·弦浮脉", "o": "沉取弦浮脉总以浮弦为基本特征，所主病机广泛，核心在于气机失调与邪正交争。浮主表、主气浮，弦主肝郁、主痰饮、主痛，二者相合，既可反映外邪束表、少阳枢机不利，又可示肝郁气结、痰饮内停；若兼数或洪，则主热盛，常见于少阳阳明合病或表里俱热；若重按无力或空虚，则示正虚邪", "c": "主肝郁气结"}, {"id": "rc:沉取+弦+滑", "n": "沉取·弦滑脉", "o": "沉取弦滑脉总属痰热内郁、湿热积滞、血虚火旺及阴液亏虚之候。弦主气滞、痰饮或木火，滑主痰湿、痰热，两者相合，核心为痰热交结、气机不畅。然兼脉与脉力不同，所主有别：弦滑有力搏指，为湿热积滞壅结肠腑之实；弦滑重按空虚，为血虚胆火犯中；弦滑而尺弱或沉候少神，为热盛劫灼", "c": "主痰热内郁"}, {"id": "rc:沉取+弦+硬", "n": "沉取·弦硬脉", "o": "沉取弦硬脉总属肝木失柔、脉道拘急之象，所主病机可归纳为虚实两端。虚者，肝阴亏虚、血亏气耗，脉失濡养而弦硬，按之多不实；实者，肝火炽盛、冲胃气逆，火性急迫、气机壅逆而脉弦硬有力。临床常见虚实夹杂之候：或阴虚火旺，或虚损夹痰，或邪实正虚。各段原文多从'左脉弦硬'定", "c": "主肝阴亏虚"}, {"id": "rc:沉取+弦+细", "n": "沉取·弦细脉", "o": "沉取弦细脉总起来主病机以肝郁、湿滞、阴伤、寒凝为纲，兼涉热郁与正虚。弦为气机郁滞或寒凝，细为阴血不足或络脉不充，沉取则病位在里。其具体所主，或为湿郁化热，或为肝郁络滞，或为肝阳上亢，或为寒凝气血亏虚，或为暑热伤阴，或为少阳阳明合病，或为肺郁肾虚。诸类之间，总以", "c": "主湿郁化热"}, {"id": "rs:沉取+弦", "n": "沉取·弦脉", "o": "沉取弦脉总属里证，以气机失调为核心，涉及肝、胆、脾、胃等多脏。弦为气郁、饮邪、痛证、寒凝之象，沉取则病位在里。其主病机可归纳为气郁、肝胆热、痰饮、疟邪、虚损、寒凝六类。气郁为弦脉基本病机，肝失疏泄则气机不畅；气郁化火或湿热内蕴则成肝胆热；气滞津凝则生痰饮；疟邪", "c": "主气郁"}, {"id": "rc:沉取+弦+长", "n": "沉取·弦长脉", "o": "沉取·弦长脉总起来主邪实热盛、气机逆乱，兼及疟邪与虚损。其核心病机为弦主气郁、长主邪实有余，重按有力或甚实则示实热内结。具体而言，弦长脉主热盛，尤以阳明气分热盛及肝火有余为多；主气逆，以肝胃气逆、冲气上冲为要；主疟邪伏于少阳，常兼阳明热盛；主肝火浮动，或挟痰上", "c": "主热盛"}, {"id": "rs:沉取+弱", "n": "沉取·弱脉", "o": "弱脉总属正气不足，以虚为本，其形柔小如绵、按之不任。所主病机可归为气虚阳陷、营弱汗出、元气虚浮、正虚邪实及沉弱虚损五类。气虚阳陷者，大气不举，脉弱而兼弦，症见胸满咳喘、言语颤动；营弱汗出者，营阴不守，弱见于关后，伴自汗恶风；元气虚浮者，下焦虚衰，尺弱寸强、浮大", "c": "主气虚阳陷"}, {"id": "rc:沉取+微+弱", "n": "沉取·微弱脉", "o": "沉取微弱脉总属正气不足之象，以虚为本。其主病机可归为气虚阳衰、气血大虚、脏虚、虚寒及正虚邪恋五类。微弱无力、按之不任，为气阳亏虚、胸中大气下陷；年高久病见之，则为气血大虚、脏腑失养；华元化论脏虚亦以按之微弱为据；伤寒阴证虚阳外浮，脉来微弱无力，主虚寒而非实热；", "c": "主气虚阳衰"}, {"id": "rs:沉取+微", "n": "沉取·微脉", "o": "沉取微脉总属正气虚衰、阳气式微之象。其核心病机为阳气虚衰，鼓动无力，故脉沉而微。所主病机可归为三类：一主阳虚寒盛，寒邪直中，阳气不能温煦，见肢冷自汗、脉微苔白；二主中虚，中气素虚，因热受寒，腹痛喜按，脉微而弱；三主正气虚衰，气血阴阳亏虚，脉道不充，按之无力。三", "c": "主阳虚寒盛"}, {"id": "rs:沉取+散", "n": "沉取·散脉", "o": "沉取散脉总起来主气机耗散、气阴两伤，兼及热盛伤气与脉气不敛。其核心病机为暑热或热邪耗伤气阴，气虚不能鼓动，阴伤不能充盈，故重按脉散若无，非真脉绝。原文三段落分别从暑伤气阴、脉象定义、阳暑热证展开：暑月自汗神疲、烦渴溺短、四肢逆冷，脉虚散重按若无，为气阴两伤、阳", "c": "主气阴两伤"}, {"id": "rc:沉取+数+大", "n": "沉取·数大脉", "o": "沉取数大脉总起来主热盛与虚阳外浮两类病机，而虚阳外浮又可细分为阴虚阳浮与气虚阳越。数主热，大主邪盛或虚，关键在于重按有力无力：有力为实热，无力或虚散为虚阳外浮。实热者多因外感化火、脏腑积热，脉象数大而带弦或有力；虚阳外浮者多因阴亏、气虚或汗多亡阳，脉大而数，重", "c": "主热盛"}, {"id": "rc:沉取+数+弦+滑", "n": "沉取·数弦滑脉", "o": "沉取数弦滑脉总属痰热内蕴、热盛津伤之候。弦主痰饮、气滞或木火，滑主痰湿痰热，数主邪热，三者相合，提示痰热交结、气机不畅，甚则木火亢盛。然重按少力或尺濡细，又示热盛劫灼津液，阴分已亏。各段所主病机虽有偏重，但核心为痰热与阴伤并存：痰热内阻则气滞、木火易亢，热盛则", "c": "主痰热"}, {"id": "rc:沉取+数+弦", "n": "沉取·数弦脉", "o": "沉取数弦脉总属邪热内郁、肝胆火旺，兼见阴分亏虚之候。弦主肝胆气滞或木火，数主邪热，沉取则病位偏里。其病机主要有五：湿热郁蒸肝胆、实火内郁、虚阳浮越、邪炽阴伤、上盛下虚。各段所主虽偏重不同，但核心为热与虚并存：或湿热交蒸，或实火亢盛，或热盛劫阴而虚阳上浮，或下元", "c": "主湿热"}, {"id": "rc:沉取+数+沉", "n": "沉取·数沉脉", "o": "沉取数脉，总起来主里热与阴亏，并常兼夹痰饮、气郁，久则为劳损之候。沉主里，数主热，合之则阴液内亏、虚热伏于里分，故原文反复强调“其阴内亏，其热在里”。然此脉所主非单纯虚热一端：咳唾白痰、咳已三年而初无身热，是根在痰饮；脘腹时痛、痛则气满、得矢气则宽，病由肝郁而", "c": "主阴亏内热"}, {"id": "rc:沉取+数+浮", "n": "沉取·数浮脉", "o": "沉取·数浮脉总属虚阳外浮、阴不敛阳之象。其脉浮数，浮为阳浮于外，数为热，然沉取必无力、甚空或如无，故非实热。所主病机可分三类：一为阴虚阳浮，阴亏不能潜阳，虚热外浮；二为热盛阴竭，邪热炽盛而阴液将竭，脉虽浮数有力而重按甚空；三为虚阳外越，元气大虚，虚阳浮越，脉浮", "c": "主阴虚阳浮"}, {"id": "rc:沉取+数+细", "n": "沉取·数细脉", "o": "沉取数细脉总以细数为基础，细主阴血不足或脉道不利，数主热，然其病机有虚实寒热之辨。虚证方面，或为阴亏内热，或为阳气虚馁、虚阳上攻，或为正虚邪陷，甚则阴寒内盛、虚阳外越之真寒假热。实证方面，或为郁热化毒，或为食积湿热内结，或为热厥里实。其鉴别关键在于重按之力：重", "c": "主阴亏内热"}, {"id": "rs:沉取+数", "n": "沉取·数脉", "o": "沉取数脉总以数主热、沉主里为纲，所主病机可归纳为热盛、虚热、虚阳外浮、湿热痰火、火郁、正虚邪陷六类。数而有力多实热，数而无力多虚热；浮数沉取空为虚阳外越，数兼滑大为痰火湿热，数兼细弦为火郁，数而少力为正虚邪陷。诸类之间以“热”为共同基础，以脉力之有力无力、兼象", "c": "主热盛"}, {"id": "rc:沉取+沉+浮", "n": "沉取·沉浮脉", "o": "沉浮脉总以浮沉二象并见为特征，所主病机涉及表里、气机、疫毒及阴阳真假。其核心在于通过浮沉之象判断病位深浅与病性虚实：浮主表、主气浮于上，沉主里、主水在里，浮沉并见则提示表里同病或气机升降失常。在湿热疫毒炽盛时，洪数浮沉有力反映邪毒纵贯三阳；在阴阳辨证中，脉之有", "c": "主表里水病"}, {"id": "rc:沉取+沉+涩", "n": "沉取·沉涩脉", "o": "沉涩脉总起来主里、主血行不畅，其病机核心在于邪郁于里而脉道阻涩。从所收三段看，沉主病在里，涩主血滞，二者相合，既可因热郁于里、血行不畅而见沉涩似数，也可因血虚热郁、热深厥深而见沉涩稍大，还可因痼热郁结、脉道阻涩而见沉涩。三类病机虽表现不同，但共同点是里有郁热或", "c": "主里热郁滞"}, {"id": "rs:沉取+沉", "n": "沉取·沉脉", "o": "沉脉总属里证，以“轻手不见，重取乃得”为特征，主病广泛。其核心病机为邪郁于里、阳气不达，具体可归为里热积滞、水气内停、气郁痰湿、阳虚寒凝、血行不畅、阳郁厥逆等类。沉而有力多实，主热、积、水、痰、气郁；沉而无力多虚，主阳虚寒凝；沉兼涩主血滞，沉兼弦滑主痰饮气郁，", "c": "主里热积滞"}, {"id": "rs:沉取+洪", "n": "沉取·洪脉", "o": "沉取洪脉总以脉位沉而形洪大为特征，所主病机可归纳为虚、实及虚实夹杂三类。洪而重按无力者，多主虚阳外浮或气血亏虚，因阴血枯涸、气无所附，虚阳外越而脉显洪象，然重按无力是其关键；洪盛有力、沉取亦然者，主实热壅盛，邪热鼓动气血，脉道充盈，常见于外感热病、痘毒炽盛等；", "c": "主虚阳外浮"}, {"id": "rc:沉取+洪+长", "n": "沉取·洪长脉", "o": "沉取洪长脉总属热盛邪实之候，以脉体洪大而长、重按有力为特征。其病机核心为邪热炽盛，鼓动气血，脉道充盈延长。具体所主，一为胃热炽盛，气火上升，可致吐血；二为积酒生热，与肝热相并，上冲脑部；三为温病热在阳明，或兼少阳合病。三者虽病位有别，但皆以洪长为热盛之征。若重", "c": "主胃热"}, {"id": "rs:沉取+浮", "n": "沉取·浮脉", "o": "沉取浮脉总以浮象为纲，所主病机可归纳为表邪、虚阳、血虚、气机失调及邪正交争五类。浮而有力多主外邪束表或邪正交争，为实；浮而无力多主虚阳外浮或血虚阴亏，为虚。其核心在于通过浮脉的力度、兼象及沉取变化判断虚实：举之有余、按之不足为常，若重按有力则邪实，重按空豁则正", "c": "主表感邪"}, {"id": "rc:沉取+浮+虚", "n": "沉取·浮虚脉", "o": "沉取浮虚脉总属虚候，以气血亏虚、气不内守为核心。其沉取弱缓主气虚阳弱，浮软无力主血虚不充，浮虚按不应指则示气不内守、虚阳外浮；若见于暑热伤气，则为热伤气阴、气少浮越。四类病机相互关联：气虚则血亦不足，血虚则气失所附，气血俱虚则中气不固、脉变动无常；气不内守可致", "c": "主气虚"}, {"id": "rs:沉取+涩", "n": "沉取·涩脉", "o": "涩脉总主脉道阻滞、血行不畅，其病机有虚实寒热之异。实者瘀血内结、癥块梗阻，或郁热内伏、痼热阻脉，皆令脉气往来艰涩；虚者气虚推动无力，或血少不充脉道，亦见涩象。原文反复告诫“涩固多虚寒，亦有痼热为病者”，不可一见涩脉便作虚寒论。四类之中，瘀血与郁热属邪实阻滞，气", "c": "主瘀血内结"}, {"id": "rc:沉取+滑+洪", "n": "沉取·滑洪脉", "o": "沉取滑洪脉总属热盛痰壅、实积内结之象。洪为热盛，滑为痰湿，相合则主痰热实积。其病机类别虽多，然核心皆不离“热”与“实”：或痰热结于中焦胁下，或热入阳明腑实，或热迫血溢，或外感实热内盛，或肝胃热盛冲逆，或阳暑火盛伤气。各段原文多强调洪滑有力、重按实，示邪实热盛；", "c": "主痰热实积"}, {"id": "rs:沉取+滑", "n": "沉取·滑脉", "o": "沉取滑脉总属痰湿、饮停、积滞、脓血及虚痰之候。滑为脉往来流利，主痰湿内蕴，故凡痰饮、水湿、食积、脓血等有形之邪内阻，气机不畅，脉多见滑。其病机类别虽多，然核心不离“痰湿”与“积滞”：或痰湿弥漫，或饮停中焦，或食积内阻，或脓血壅聚，或脾虚痰湿。各段原文多强调滑脉", "c": "主痰湿"}, {"id": "rs:沉取+紧", "n": "沉取·紧脉", "o": "紧脉总属寒、痛、虚、滞相兼之脉。其形成基础为寒性收引，脉道拘急，故主寒、主痛；若紧而无力或重按不任，则主正虚，尤以阳虚气弱为多；寒凝气滞、血行不畅，又可见气滞血瘀、壅遏之象；邪正交争之际，脉气紧张亦现紧象。各病机之间相互关联：寒邪外束可致营卫不和、肺气郁闭，进", "c": "主寒"}, {"id": "rc:沉取+细+微", "n": "沉取·细微脉", "o": "沉取细微脉总起来主阳气虚衰、热郁于里及寒热错杂之证。其核心病机为正气虚极，脉道鼓动无力，故脉象微细。具体而言，微细欲绝多主阳虚欲脱；细数或微细而兼热象者，可因热郁于里，阳气不能外达；细软无力、重按即无者，多为虚阳上攻；微细而重按弦长，则主寒热错杂、厥阴枢机不利", "c": "主阳虚欲脱"}, {"id": "rc:沉取+细+滑+濡", "n": "沉取·细滑濡脉", "o": "沉取细滑濡脉，总起来主湿、热、虚、滞相互夹杂之病机。细濡主湿主虚，滑主热主经水将行，洪滑主热盛及冲任壅盛。诸段均见细濡近滑，两尺重按略洪而滑，提示湿遏热伏、血虚夹湿、冲任失调。虽不兼数，仍可主血热，因湿邪阻遏，热不外扬，故脉不数而病热。四类病机中，血热与湿滞互", "c": "主血热"}, {"id": "rs:沉取+细", "n": "沉取·细脉", "o": "沉取细脉总以脉道不充、气血不利为基，所主病机有虚实两端。虚证方面，细主阴血不足、正气衰少，如脉细如丝、细而不耐重按，多见于失血、久疟、痞块等阴伤正虚之候；实证方面，细主郁滞，邪结于里、气机不畅，脉道受阻而细，如食结中宫、热郁于里、寒中阳郁，重按多滑、长、有力。", "c": "主阴伤"}, {"id": "rs:沉取+芤", "n": "沉取·芤脉", "o": "沉取芤脉总以脉道中空、重按无力为特征，主病机围绕“血”与“气阴”之虚损及由此产生的瘀滞。其核心为失血、血虚，因血液骤失或亏少，脉道不充，故芤；血虚则气亦弱，故芤而无力。失血之后，离经之血留滞，可兼涩象而主瘀滞，此乃因虚致实。若暑热等邪耗伤气阴，脉亦虚软重按若无", "c": "主失血"}, {"id": "rs:沉取+虚", "n": "沉取·虚脉", "o": "沉取虚脉总属虚候，以正气亏虚、脉道不充为核心。其脉象虽可见浮、大、弦等，但重按无力或豁然中空，甚至全无，提示虚阳外浮或气血涣散。所主病机主要有五类：气虚阳弱、血虚阴亏、气不内守、血脱气耗、久病正虚。气虚则鼓动无力，血虚则脉道不充，阴虚则阳浮于外，久病则正气耗伤", "c": "主气虚阳弱"}, {"id": "c:沉+和", "n": "沉和脉", "o": "沉和脉总起来主里证，以里虚为基础，兼见痰饮与邪未退。沉主里，和示胃气尚存但谷气不足，故核心为里虚，尤以脾胃虚弱、中气受戕为主。在此基础上，若兼细滑则主痰饮未化；若动数未减则主邪气未全退。三者相互关联：里虚为根本，痰饮与邪恋为标象，脉虽似和而实未复，提示病机复杂", "c": "主里虚"}, {"id": "c:沉+结+坚", "n": "沉坚结脉", "o": "沉坚结脉总属里实积滞之候，以沉主里、坚主实、结主积滞为纲。其具体病机可归为三类：一为里实积滞，二为痰血互结，三为气郁神扰。三者相互关联：忧愤沉郁致气机郁结，气郁则津液不布、血行不畅，痰与血交积胸中，形成里实积滞，阻滞脉道而见沉坚结脉；积滞上扰神明，则见狂歌痛哭", "c": "主里实积滞"}, {"id": "c:沉+坚", "n": "沉坚脉", "o": "沉坚脉总属里实之候，以沉主里、坚主实为纲。其病机可归为四类：一为里实积滞，邪结于内，脉道阻滞；二为郁火内伏，肝郁化火，气机郁结不散；三为阴伤固结，阴液亏耗而气机固结；四为寒实水停，寒湿内盛，水气不化。四类虽寒热虚实有别，但均以'沉'定病位在里，以'坚'示邪气固", "c": "主里实积滞"}, {"id": "c:大+沉+坚", "n": "沉大坚脉", "o": "沉大坚脉总属里实寒证，以寒邪内实、水气内停、肾虚寒湿为核心病机。沉主里，大坚主寒实内结，紧亦主寒。原文所述肾脉沉大坚、浮大紧，伴手足骨肿厥、阴不兴、腰脊痛、少腹肿、心下有水气等，皆因寒湿乘虚入肾，阳气不达，水气内停所致。三类病机相互关联：寒实为根本，水气为病理", "c": "主寒实"}, {"id": "c:滑+大+沉", "n": "沉大滑脉", "o": "沉大滑脉总属实证、气血壅盛与逆乱之候。沉主实，滑主气，大示邪盛，三者相合，反映实气相搏、气血壅盛。其主病机主要有三：一为气血壅实，脉道充盈；二为卒厥危候，气血逆乱，入脏则死、入腑则愈；三为水气内停，水湿壅盛泛溢。三类之间以“实”为共同基础：气血壅实是基本病机，", "c": "主卒厥危候"}, {"id": "c:大+沉", "n": "沉大脉", "o": "沉大脉总属里实与虚候并见之象。沉主里，大主虚、主热、主郁张，故其病机涵盖虚陷、水停、气郁、湿热、积伏、邪伏、邪滞、热盛等多类。诸类之间，以“沉”定病位在里，以“大”别病性：大而无力多主虚陷、水虚，大而有力多主气郁、积伏、邪伏、邪滞、热盛；兼滞、兼数则偏湿热。虚", "c": "主虚陷"}, {"id": "c:数+沉+实", "n": "沉实数脉", "o": "沉实数脉总主里、热、实，核心病机为热邪内结、壅滞不通。沉主里，数主热，实主邪结，三者相合，提示邪热深结于里，气血壅滞。所主具体病机包括阳明里热燥结、瘀血郁而化热、肝经郁热火结、怫热郁结水肿、中风火郁内闭，以及阳复热结等。诸类虽表现各异，但均以'热郁在里、邪实壅", "c": "主里热壅结"}, {"id": "c:数+沉+洪+实", "n": "沉实洪数脉", "o": "沉实洪数脉总属热毒壅盛、邪实于里之阳热实证。沉主病位在里，实主邪气盛实，洪数主热邪炽盛，四者相合，揭示热毒内结、气血壅滞之病机。所主三类病机相互关联：热毒壅盛为病之本，邪实于里为病之位，阳热实证为病之性，三者从不同角度描述同一实热证候。原文强调‘诸痛痒疮疡，皆", "c": "主热毒壅盛"}, {"id": "c:沉+浮+洪+实", "n": "沉实浮洪脉", "o": "沉实浮洪脉在此段中并非单一主病，而是通过脉象的兼夹与部位变化反映不同病机。总起来看，其核心在于“不足”与“不和”：心血不足则脉弦而不洪，肝气不和则脉弦而不长，肾阴亏虚、虚火内动则左尺浮洪。三类病机相互关联，均以阴血亏虚为基础，导致气机失调、虚火内生。沉实浮洪之", "c": "主心血不足"}, {"id": "c:滑+沉+实", "n": "沉实滑脉", "o": "沉实滑脉总属里实之候，以沉主里、实主邪结、滑主痰热孕积为纲。其主病机可归为五类：里实、痰饮、热结、孕、水湿壅积。诸类之间，皆以'沉实'定病位在里、邪气壅盛，以'滑'别邪之性质——或为痰浊，或为热实，或为水谷壅积，或为胎孕。痰饮、热结、水湿壅积三者常相兼为患，如", "c": "主里实"}, {"id": "c:沉+实", "n": "沉实脉", "o": "沉实脉总主里、实、邪盛，核心病机为实邪内结、壅滞不通。沉主病位在里，实主邪气盛，二者相合，提示邪结于里而正气未虚。所主病机涵盖热结阳明、积滞内停、瘀热蓄血、水气壅盛、热毒内壅及气机郁结等，虽表现各异，然皆属里实之证。诸类之间以“实邪内结”为共同基础：热结可致腑", "c": "主里实热结"}, {"id": "c:弦+细+沉+小", "n": "沉小弦细脉", "o": "沉小弦细脉总起来主邪郁于里、正气不足、营卫不和及痰湿内闭。沉小为邪郁于里、正气不足；弦细为邪留少阳、阴分受扰，或营虚邪陷。两段原文均见身热、疼痛、胸闷等症，而脉沉小弦细，提示邪由表达里，营虚邪陷，闭而未出。其病机核心是正虚邪恋，表里同病，既有营卫不和，又有痰湿", "c": "主邪郁于里"}, {"id": "c:弦+沉+小", "n": "沉小弦脉", "o": "沉小弦脉总属里虚寒饮、气机逆乱之象。沉主里，小主阳微正虚，弦主饮、主痛、主肝风冲逆。其病机可归纳为阳虚饮停、痰火郁肺、肝郁气逆、冲脉上逆、寒邪伏结、土虚木乘六类。诸类之间，以正虚（阳气不足或肝阴亏虚）为本，以饮、痰、寒、火、气逆为标，标本相兼。阳虚则水寒不化，", "c": "主阳虚饮停"}, {"id": "c:沉+微+小", "n": "沉小微脉", "o": "沉小微脉总属里虚阳微之象。沉主里，小主虚，微主阳微，三者相合，提示正气亏虚、阳气衰微。其主病机可分四类：阳衰欲脱、气血大亏、寒邪困阳、邪轻正未伤。前两类为虚损至极，多见于久病吐血、暴吐昏晕等危候；第三类为寒邪困阻真阳，脉证相参当温中固脱；第四类为下痢预后判断，", "c": "主阳衰欲脱"}, {"id": "c:沉+小+实+急", "n": "沉小急实脉", "o": "沉小急实脉总属正虚邪实、脉证相逆之候。其脉象沉小为正气不足，急实为邪气亢盛，二者并见，提示正虚无力抗邪而邪气深入。所主病机可分五类：一为癫疾正虚邪实，沉小急实主不治；二为邪坚正败，小坚急、小牢急同属危候；三为伤寒热盛而脉反沉小，阳证见阴脉，主死；四为伤寒汗后脉", "c": "主正虚邪实"}, {"id": "c:沉+小+急+疾", "n": "沉小急疾脉", "o": "沉小急疾脉总属癫疾危重之候。其沉小反映心肾气阴不足、血涩不荣，急疾则示风邪急搏或肾脉急甚。二者相合，正虚邪盛，故原文断为“不可疗”。此脉所主病机可归纳为癫疾、风邪急搏、心气不足血涩、肾虚骨癫及死候五类。其中癫疾为总纲，风邪急搏与心肾虚损为病机两端，死候则提示预", "c": "主癫疾"}, {"id": "c:沉+小+急", "n": "沉小急脉", "o": "沉小急脉总属寒实内结、气血壅滞之候。沉主里，小主收引，急主痛，三者相合，提示寒邪深入脏腑，收引脉络，气血不通，故见疼痛、积块、疝气等症。原文两段均以疝气、腹痛为实例，脉得沉小而急，断为寒实而非寒虚，治用大热之剂逐寒积。其与沉微细软之虚寒脉象截然不同，强调实证、", "c": "主寒实内结"}, {"id": "c:数+沉+小+疾", "n": "沉小数疾脉", "o": "沉小数疾脉总主湿温邪在太阴、阳明，湿胜于热，湿蕴化热，余湿犹滞，邪郁不达之病机。沉小主湿郁于里、气机阻滞，数疾主热郁欲透，合而示湿与热合、郁而不达。其病位在太阴阳明，以湿为主，热为湿遏，故见日晡烦躁、口虽渴苔仍白腻、神识时糊等症。四类病机相互关联：湿郁是基础，", "c": "主湿郁"}, {"id": "c:数+沉+小", "n": "沉小数脉", "o": "沉小数脉总起来主里、虚、热三者相合之病机，以里虚有热为核心，具体可归为四类：主营中留热，热伏营分而营阴受损；主里虚热，阴血不足而虚热内扰；主湿郁化热，湿遏热伏、郁而不达；主正虚邪恋，正虚水湿不化而兼热象。各类之间相互关联：沉为病位在里，小为正气不足或营阴受损，", "c": "主里虚热"}, {"id": "c:沉+涩+小", "n": "沉小涩脉", "o": "沉小涩脉总起来主里虚夹瘀、正虚邪陷之证。沉主里，小主脉道收引或元气虚，涩主瘀滞或血少，合而示病位在里、气血不足兼瘀滞。其具体所主，可因兼脉与证候不同而分：若兼数而右甚，则主里实热夹瘀；若兼细小而阳衰，则主虚寒危候；若见于肠澼而身热，则主正虚邪陷之危；若兼弦而左", "c": "主里实热"}, {"id": "c:滑+沉+小", "n": "沉小滑脉", "o": "沉小滑脉总起来主里实痰凝气结，尤以胃中胶痰固结、肝火郁而不舒为核心病机。沉主里，小主气结，滑主痰，有力为实，四者相合，提示痰凝气滞于里，郁而化火，胃气不和。原文所载不寐一案，劳心思虑致气结痰凝于胃，夜间胃中如焚、烦躁不宁、饮食无味，诸医误作心血不足、心肾不交、", "c": "主痰凝气结"}, {"id": "c:沉+小+紧", "n": "沉小紧脉", "o": "沉小紧脉总起来主里寒、气郁、食积与热郁相互交结之病机。沉主里，紧主寒主痛，小主气郁，三者相合，提示寒邪与气、食交阻于里，结聚不散。其病位多在心下、中焦，症见心下聚气而痛、食不下、喜咽唾、手足热烦满、善忘不乐、喜太息等。寒凝气滞则痛，气郁不舒则太息、善忘，食积中", "c": "主寒痛"}, {"id": "c:沉+小+缓", "n": "沉小缓脉", "o": "沉小缓脉总属里虚寒证，以阳气不足、寒湿内阻为核心病机。沉主里，小主阳气受抑或式微，缓主寒湿或腑阳久伤。两类病机相互关联：寒湿内阻多因外寒引动内湿，困遏中阳；脾阳虚衰则因阳气久伤，运化无力，寒湿内生。前者偏实，后者偏虚，但均以阳气不振为根本，故治疗皆需温药以通阳", "c": "主寒湿内阻"}, {"id": "c:沉+小", "n": "沉小脉", "o": "沉小脉总属里虚之象，沉主病在里，小主正气不足。其所主病机以阳虚、气虚、血虚为本，以水饮、寒湿、痰浊、气郁为标。具体而言，阳气衰微则水饮内停，见水肿、喘咳、癃闭；虚寒内盛则脉沉小，见畏寒、厥冷、下利；正虚邪陷则脉沉小，见于温病、伤寒后期；气血虚损则脉道不充，见经", "c": "主阳虚水饮"}, {"id": "c:沉+小+迟", "n": "沉小迟脉", "o": "沉小迟脉总属阳虚气衰、阴寒内盛之象。沉主里、迟主寒、小主阳虚，三象合见，提示阳气衰微、气陷不升。其所主病机主要有三：一为阳虚中寒，阴寒内盛而见腹痛、呕吐、下利、手足逆冷；二为阳衰脱气，脾肾阳衰、气不归元，故疾行喘喝、腹满溏泄、食不消化；三为虚证而非劳，气馁精违", "c": "主阳虚中寒"}, {"id": "c:弦+沉+伏", "n": "沉弦伏脉", "o": "沉弦伏脉总起来主邪郁于里、气机闭阻之病机，具体可因热郁、痰浊、寒凝或阳衰阴盛而见。沉为在里，弦为气机紧张或阴凝，伏为气闭不出。若沉弦而缓，多属痰热内伏、肝热遏伏，缓非脾弱而是痰浊阻气；若沉伏弦紧，则多属血气内虚、外寒闭阻、寒凝收引，见于痉病；若沉细弦伏并见，则", "c": "主热郁"}, {"id": "c:弦+沉+和", "n": "沉弦和脉", "o": "沉弦和脉在原文中仅见于风气腹痛之治，与浮缓相对而言。沉主里，弦主郁、主痛，故沉弦总主邪郁于里、气机不畅之里实证。其核心病机为风气入里，与内气相搏，致里气郁滞而腹痛。原文'脉沉弦者和里'，明确以沉弦为里实之脉，治当调和里气。与浮缓主表、脉浮主风在表不同，沉弦标志", "c": "主里实"}, {"id": "c:弦+滑+沉+小", "n": "沉弦小滑脉", "o": "沉弦小滑脉总起来主痰饮内伏、痰火内扰，兼有正虚邪郁之机。沉主里，弦主饮，滑主痰，小示正气不足或邪郁，四者相合，提示痰饮或痰火内蕴于里，常因外感、劳倦、温邪或酒食引动而发病。各段原文均围绕痰饮、痰火展开：或外寒引动宿饮，或温邪酿痰化热，或疟后酒助火生痰，痰火内扰", "c": "主痰饮内伏"}, {"id": "c:弦+沉+小+软", "n": "沉弦小软脉", "o": "沉弦小软脉总起来主阳虚里寒、肝木乘脾、正气不足与痰饮内聚。沉主里、主阳虚，弦主肝木乘脾，小软示正气不足。本案年近花甲，中阳衰馁，肝木乘间横克脾胃，脾运失职，胃降无权，素胜痰饮，易聚难化，故见呕恶嗳满、寒热往来、杳不思纳、夜寐欠安。脉证合参，病在脾胃，后天生生之", "c": "主阳虚里寒"}, {"id": "c:弦+沉+微+硬", "n": "沉弦微硬脉", "o": "沉弦微硬脉总起来主肝郁气结、血虚火旺，并涉及木旺克土与脾胃虚弱。左脉沉弦微硬，沉主里、弦主肝、硬为气郁化火伤阴，故主肝经气郁而血虚火盛；右脉弦而无力，为木旺克土、脾胃受戕，故主脾虚不运。四类病机以肝为核心：肝郁气结为始，气郁化火伤阴则血虚火旺；肝旺乘脾则木旺克", "c": "主肝郁气结"}, {"id": "c:数+弦+沉", "n": "沉弦数脉", "o": "沉弦数脉总属里、郁、热三端交织之象：沉主病在里，弦主气郁、主痛、主肝，数主热、主火。合而观之，其核心病机为邪热郁结于里、气机壅滞不畅。因郁结之所在与兼邪不同，可分化出肝郁化火、里热积滞、痰火内郁、疟邪内郁、瘀热内结、阴虚火旺、风火相煽等类。诸类之间以“郁”与“", "c": "主肝郁化火"}, {"id": "c:弦+沉+涩", "n": "沉弦涩脉", "o": "沉弦涩脉总属里实或虚实夹杂之候，核心病机为气滞血瘀、脉道不利。沉主病在里，弦主气郁、肝旺、痛证，涩主血滞、精伤、湿阻。诸段所示，或为寒湿痰瘀深伏筋骨，或为肝郁乘土、气血壅滞，或为蓄血、症瘕、经闭等瘀血内结，或为精血亏虚兼气滞，或为湿郁气阻、水湿泛滥。各类之间常", "c": "主气滞血瘀"}, {"id": "c:数+弦+滑+沉", "n": "沉弦滑数脉", "o": "沉弦滑数脉总属里实热证，以痰、饮、风、热为核心病机。沉主里，弦主肝风或饮癖，滑主痰，数主热，四者相合，揭示痰饮内伏、肝风煽动、郁热内蕴之候。其病位在里，涉及肝、肺，常因痰湿壅塞、气机郁滞，久郁化热，或过投温补引动肝风，致痰乘风上，发为昏厥、抽搐；或痰热内壅，肺", "c": "主风痰上扰"}, {"id": "c:弦+滑+沉", "n": "沉弦滑脉", "o": "沉弦滑脉总属里实之候，以痰饮水湿内停、气机郁滞为基本病机。沉主病在里，弦主肝郁、饮癖、气滞，滑主痰湿，三脉相合，提示痰饮、湿浊、气郁交阻于内。其具体所主，可因兼邪与病位不同而分为痰饮内停、肝郁气滞、痰热内蕴、风湿痰阻络、肝阳挟痰上扰、气逆痰阻、积滞内结等类。诸", "c": "主痰饮内停"}, {"id": "c:弦+沉+紧", "n": "沉弦紧脉", "o": "沉弦紧脉总属阴寒内盛、阳气被遏之候。沉主里，弦主饮主痛主气郁，紧主寒主痛主结，三象合见，多因寒邪深踞于里，或寒积内结，或寒饮痰凝，或寒凝肝脉，致气机凝滞、脉道拘急。其病机以寒为核心，或兼积、兼饮、兼气滞，甚则阳虚无力鼓动。各段原文多从‘沉主里，弦主饮主痛，紧主", "c": "主里寒"}, {"id": "c:弦+细+沉+实", "n": "沉弦细实脉", "o": "沉弦细实脉总起来主里实积结、寒凝血瘀及痛证。沉主里，弦主痛，细实主积，重取如循刀责责然为积结内实之象。原文所载病案因寒湿入腹、瘀血内结，致小腹痛甚、坚硬不可近，脉象反映寒瘀结实之病机。三类病机相互关联：寒凝血瘀为因，里实积结为果，痛为突出表现。治疗以温下瘀血、", "c": "主里实积"}, {"id": "c:数+弦+细+沉", "n": "沉弦细数脉", "o": "沉弦细数脉总起来主阴血亏虚、热扰风动、久病正虚及阴阳不和。沉为邪郁于里，弦主肝风与气机不和，细为阴血亏耗，数为热扰。两段原文虽一为痉厥、一为温疟，但均见沉弦细数，提示病机本质为阴亏阳亢、虚风未息，或久疟正虚、阴阳两气不和。各类之间相互关联：阴亏血少则脉细，热扰", "c": "主阴亏阳亢"}, {"id": "c:弦+细+沉+迟", "n": "沉弦细迟脉", "o": "沉弦细迟脉总属虚寒夹实之象。沉主里，细主虚，迟主寒，弦主饮主痛主凝滞。四脉合见，总括阳气不足、寒湿内蕴、痰饮停聚、气血凝滞之病机。其核心为虚寒为本，实邪为标：或寒湿蕴蓄中宫，或胃气弱受冷而痰水内停，或久病正虚邪实。三类病机相互关联，均以中阳不振、寒饮内停为基础", "c": "主虚寒痰饮"}, {"id": "c:弦+沉+小+缓", "n": "沉弦缓小脉", "o": "沉弦缓小脉总属里虚寒证，尤以肝经虚寒为核心。沉主里，弦主肝，缓小主虚寒，四脉相合，揭示阳气不足、寒从内生之病机。其主病有三类：一为里寒内盛，见腹内久冷；二为肝经虚寒，肝阳不温；三为脾虚木乘，肝寒犯脾，木不疏土，致肠鸣泄痢，且补脾不应。三者相互关联，以肝寒为本，", "c": "主里寒"}, {"id": "c:弦+沉+缓", "n": "沉弦缓脉", "o": "沉弦缓脉总属里实邪伏、气机不畅之候。沉主里，弦主饮、主痛、主寒、主疟，缓主湿滞或痰浊阻气。四段所主虽异，然皆不离“邪伏于里、气机郁滞”之核心：或为饮停胁下，或为痰热内伏，或为疟邪伏于膜原，或为寒湿痹阻经络。其缓脉非皆主虚，亦可因痰浊湿滞阻遏脉道而致。各类之间，", "c": "主饮停胁下"}, {"id": "c:弦+沉", "n": "沉弦脉", "o": "沉弦脉总属里实或虚实夹杂之候，以水饮内停、气机郁滞为基本病机。沉主病在里、主水，弦主饮、主痛、主气郁、主肝，二脉相合，提示饮、痰、寒、气、积交阻于内。其具体所主，可因兼邪与病位不同而分为痰饮内停、气郁气逆、寒凝痛积、疟邪内郁、肝脾不和、血瘀络伤、虚损夹邪等类。", "c": "主痰饮内停"}, {"id": "c:弦+沉+虚", "n": "沉弦虚脉", "o": "沉弦虚脉总起来主虚劳内伤、阳气伤而气机滞之证。其核心病机为虚、阳伤、气滞三者交织：虚为气血不足或肾气亏虚，阳伤则清阳不升、浊阴不降，气滞则沉弦应之。从原文看，过劳阳伤、清气不主流行，虚劳夹寒、气化不利，肾虚腰痛、沉弦为虚，均体现虚为本、滞为标。各类之间：虚劳是", "c": "主虚劳"}, {"id": "c:数+弦+滑+沉+软", "n": "沉弦软滑数脉", "o": "沉弦软滑数脉总属痰饮内伏、郁热内蕴之候。沉主里，弦主饮癖，软滑为痰湿，数则郁而化热，四者相合，揭示痰湿内蕴、气机郁滞、久郁化热之病机。其核心在于痰饮内伏，病位在里，涉及肺气不展，治节不伸。痰湿壅塞，清阳升降之路受阻，故见发冷喘汗欲厥；郁热由痰湿郁遏而生，非实热", "c": "主里饮"}, {"id": "c:弦+滑+沉+软", "n": "沉弦软滑脉", "o": "沉弦软滑脉总属肝郁气结、郁热痰凝、痰湿内蕴之候。沉主里，弦主郁主饮，软滑主痰湿，四者相合，揭示气机郁滞、痰湿内阻、久郁化热之病机。其核心在于肝郁气结，郁则生热，温补凝痰，痰热互结，气机不畅。临床可见腹胀如痞、冲逆吐酸、肌肉渐消、苔黄腻、溲浑短等症。三类病机相互", "c": "主肝郁气结"}, {"id": "c:弦+沉+迟", "n": "沉弦迟脉", "o": "沉弦迟脉总属里寒阳虚、寒凝气滞之象。沉主里，迟主寒，弦主饮主痛主凝滞，三脉合见，总括阳气不足、寒从中生、水饮内停、气血凝滞之病机。其核心为虚寒为本、实邪为标：或阳气中气乏竭而邪伏不解，如牝疟；或脾肾阳虚、水湿泛滥而成肿胀；或寒邪入络、气血痹阻而为痹痛。四类病机", "c": "主里寒阳虚"}, {"id": "c:弦+沉+弱", "n": "沉弱弦脉", "o": "沉弱弦脉总属本虚标实之象，以虚、饮、肝逆、虫积为四大病机。沉弱主虚，反映阳气不足、胃气久伤或脾阳伤败；弦主饮、主肝逆，反映饮邪内伏、肝气横逆。虚与饮常相互关联，阳虚则饮停，饮为阴邪又伤阳，形成虚实夹杂；肝逆多挟痰饮上冲，致胃失和降；虫积则因脏虚而动，气机郁滞。", "c": "主肝逆"}, {"id": "c:沉+弱+缓", "n": "沉弱缓脉", "o": "沉弱缓脉总属虚候，以阳气不足、气血亏虚为基本病机。沉主里、弱主虚、缓主气衰，三象合见，反映脏腑功能低下、气血不充。其具体所主，一为气虚阳弱，二为脾肾不足，三为气血两虚，四为虚阳浮越。四类之间相互关联：气虚阳弱为总纲，脾肾不足为常见病位，气血两虚为病久转归，虚阳", "c": "主脾肾不足"}, {"id": "c:沉+弱", "n": "沉弱脉", "o": "沉弱脉总属里虚之象，沉主病在里，弱主正气不足，故其核心病机为阳气虚衰、气血亏虚。从所收43段看，沉弱脉所主以虚证为纲，可细分为阳虚、气虚、虚寒、气血两虚、肾虚等类，皆因正气不能鼓动脉道而致脉沉弱无力。其中阳虚失于温煦则生内寒，气虚推动无力则见气陷，气血两虚则脉", "c": "主阳虚"}, {"id": "c:沉+微+伏", "n": "沉微伏脉", "o": "沉微伏脉总起来主阳气被遏、阳衰不伸之病机。其脉沉主病在里，微为阳衰，伏为阳气被遏。三者并见，多因暑湿秽浊或寒湿内盛，阻遏阳气，不能鼓动脉道，故虽外有暑热，脉反沉伏。所主病机可归纳为阳郁、阳衰、寒湿内盛三类，三者相互关联：寒湿内盛为病因，阳郁为病机关键，阳衰为体", "c": "主阳郁"}, {"id": "c:数+弦+沉+微", "n": "沉微弦数脉", "o": "沉微弦数脉总起来主热闭于内、阳郁不达，兼动肝风之病机。沉微与弦数看似矛盾，实为同一病机之两面：热邪内闭，气机窒塞，阳气郁伏不能外达，故脉沉微；热盛则引动肝风，风动气升，故脉弦数。三者相互关联：惊则气乱，气乱则阳升阳伏，阳伏则沉微，阳升则弦数；热闭于内则阳不外达", "c": "主阳郁热闭"}, {"id": "c:弦+沉+微", "n": "沉微弦脉", "o": "沉微弦脉总起来主里积、肝郁与脾虚相互为患之病机。沉脉主里，弦脉主肝主痛主积，微弦则郁结不甚而正气略伤。从原文看，胃脘硬物杜塞数年，饮食减少不能下行，脉沉而微弦、右部尤甚，说明病位在里、在脾胃，病性为积滞内阻、肝气郁结、脾胃虚弱三者交织。沉主里积，弦主肝郁，右部", "c": "主里积"}, {"id": "c:数+沉+微", "n": "沉微数脉", "o": "沉微数脉总属里虚阳弱兼有虚热或邪热内郁之象，其病机以正虚为本，热扰为标。沉主里，微主阳虚或正虚，数主热，三者相合，提示病位在里，阳气不足，同时存在虚热躁动或邪热内结。具体可分三类：一为里实热结，热结在里而正气已伤，见舌黄便秘、心中躁；二为正虚邪扰，阳气衰微于内", "c": "主里实热结"}, {"id": "c:细+沉+微+迟", "n": "沉微细迟脉", "o": "沉微细迟脉总属阳气衰微、阴寒内盛之象。沉主里，微主阳衰，细主阴血不足，迟主寒，四者相合，反映阳气虚衰、阴寒内盛、气血不足的病理基础。在黄疸病中，此脉提示湿毒深陷、阳气衰微，属危候，故原文强调不宜下之。若脉由沉微细迟转为小浮出形小见、不甚沉微，则阳气渐复，病有转", "c": "主阳虚寒盛"}, {"id": "c:沉+微+缓", "n": "沉微缓脉", "o": "沉微缓脉总属虚寒，尤以下焦虚寒、奇经失固为核心病机。沉主病位在下，微为阳气衰微，缓为寒象，故脉见沉微缓，多主下元虚衰、虚寒内生。其下属具体脉象中，左关沉微缓突出下焦虚寒与奇经失固，右部虚浮则提示虚阳上浮，形成上盛下虚之局。同时，脉微缓兼食减味少，又反映胃气孱惫", "c": "主下焦虚寒"}, {"id": "c:沉+微", "n": "沉微脉", "o": "沉微脉总属阳气衰微、阴寒内盛之候。沉主里，微主阳衰，二者相合，反映正气虚衰、阳不胜阴的基本病机。其具体所主，或为阳衰阴盛之纯寒证，或为阴浊内凝之痞胀疝瘕，或为水湿泛滥之水肿，或为虚阳浮越之假热，或为大气下陷之气短痿废，或为血瘀热结之蓄血，或为正虚邪恋之久病。诸", "c": "主阳衰阴盛"}, {"id": "c:数+沉+急", "n": "沉急数脉", "o": "沉急数脉总起来主寒郁气逆、痰壅肺闭之证。沉主里、主寒郁于内，急数非尽属热，乃寒邪郁闭、气机急促之象。寒郁则津凝为痰，痰壅肺气则喉鸣喘促；寒凝气滞则腹满；表寒未解则鼻流清涕。四类病机相互关联：寒郁为始动因素，气逆为脉急数之直接反映，痰壅为寒郁津凝之产物，表寒里郁", "c": "主寒郁"}, {"id": "c:沉+急", "n": "沉急脉", "o": "沉急脉总属里实、气逆、寒凝、瘀阻之候。沉主病在里，急主拘急、疼痛、气逆，故其病机多端。归纳有四：一主肝郁气逆，肝经气血郁滞，脉道紧急，症见胁痛、目眩、头痛；二主寒凝积痛，寒邪深结脏腑，气血不通，发为积块、疝瘕、腰脊痛；三主瘀血内阻，跌堕瘀停，脉道不利，见少腹急", "c": "主肝郁气逆"}, {"id": "c:沉+散", "n": "沉散脉", "o": "沉散脉总起来主病机以热、寒、气血虚及脏腑失调为主。原文虽仅一段，但通过兼脉与脉象对比，揭示沉散脉可因热邪内蕴而见滑疾，因寒邪内侵而见迟紧，因气血亏虚而见小涩，并可随兼脉不同反映肝、心、脾胃、肺、肾等脏腑病变。各类之间相互关联：热与寒为邪气性质，气血虚为正虚基础", "c": "主热"}, {"id": "c:数+大+沉", "n": "沉数大脉", "o": "沉数大脉总起来主里热炽盛、邪盛于内。沉主病位在里，数主热，大主邪气盛，三者相合，突出热邪内结阳明、里热壅盛之病机。原文所载瘅疟（温疟）之症，但热不寒、面赤口渴、手足热、烦冤时呕，正是阳明热盛的表现，脉象与之相应。虽见少气，乃热伤气耗，非正气大虚，故脉仍沉数大而", "c": "主里热炽盛"}, {"id": "c:数+滑+沉+洪", "n": "沉数洪滑脉", "o": "沉数洪滑脉总属里实热盛之象。沉主病位在里，数主热，洪滑主邪实气血壅盛，四者相合，反映邪热内结、实邪壅盛于里的病机。原文以“里实者脉沉数洪滑”点明其与表实“浮洪滑大”相对，强调此脉为里实证之典型。所归纳三类病机——主里实、主热盛、主邪实壅盛——实为一体之不同侧面", "c": "主里实"}, {"id": "c:数+沉", "n": "沉数脉", "o": "沉数脉总属里热之象：沉主病在里，数主热，合而示热邪在里。其具体所主，因邪之性质、正气盛衰及兼脉不同而分化：实热内结者，热邪深结、壅滞不通，见沉数有力；郁热内伏者，热郁不得透达，见沉数而滞或兼弦；阴虚火旺者，阴亏于内、虚火内扰，见沉数无力或细；痰热积滞者，痰湿积", "c": "主里热内结"}, {"id": "c:数+沉+长", "n": "沉数长脉", "o": "沉数长脉总属里热实证，以“沉”定病位在里，“数”定病性为热，“长”示邪热亢盛、气血涌盛。所抽样段落中，该脉仅见于“阳明里症”，与浮紧、浮缓之太阳表证及弦长之阳明表证、洪数长之半表半里证相鉴别，突出其里热壅盛之本质。故本脉所主病机可归纳为里热与阳明里实两类，二者", "c": "主里热"}, {"id": "c:大+沉+洪", "n": "沉洪大脉", "o": "沉洪大脉在此案中总主寒饮内伏、饮郁化热、饮溢肌肤之病机。其脉沉取洪大，非单纯实热，乃饮邪郁闭、阳气不伸、郁而化热之象。六脉弦紧主寒饮内伏、卫阳被遏，右脉沉取洪大则示饮郁化热。舌白滑、喘咳无汗、浮肿，正合溢饮寒束饮溢之机。三类病机相互关联：寒饮内伏为根本，饮郁化", "c": "主寒饮"}, {"id": "c:数+沉+洪", "n": "沉洪数脉", "o": "沉洪数脉总属里实热证，以热盛于里为基本病机。沉主病位在里，洪数主热邪炽盛，三者相合，揭示热邪内蕴、气血壅盛之象。所归纳三类病机——主里热、主热结、主风火——相互关联：里热为基本病理，热结为热邪凝聚成结，风火为热盛引动风阳。原文中此脉见于少阳络热误补致风火相扇、", "c": "主里热"}, {"id": "c:沉+洪", "n": "沉洪脉", "o": "沉洪脉总属里实热证，以热邪壅盛于里为基本病机。沉主里，洪主热，二者相合，揭示热邪内蕴、气血壅盛。然其具体所主，又有层次之分：里热炽盛为其常，实热结聚为其变，风火升腾为其急；若水饮内停，郁而化热，或寒饮内伏，阳气不伸，郁而化热，则可见沉洪之假热真寒或饮郁化热之象", "c": "主里热"}, {"id": "c:沉+涩+伏", "n": "沉涩伏脉", "o": "沉涩伏脉总起来主气机郁滞、气闭为厥，兼及痰滞互阻与肝逆犯胃。其脉沉主气病，涩主气滞血涩，似伏则示气闭不通。原文两段均因郁怒伤肝，肝气横逆，气机壅塞，故见胸脘痛极、厥逆、牙关拘紧、四肢逆冷；气闭则脉沉涩似伏，气复返则苏。舌苔薄腻，提示痰滞互阻，胃失降和。四类病机", "c": "主气机郁滞"}, {"id": "c:沉+涩+小+短", "n": "沉涩短小脉", "o": "沉涩短小脉总起来主气郁、血瘀、元气虚及痰郁相互兼夹之证。沉主里，提示病位在里；涩主瘀，短小主元气虚，故该脉核心为里虚夹瘀。原文少妇因情志不遂，气郁胃口，久病入络，瘀血内结，又因勉强进食，郁而生痰，加之病久元气已虚，形成气郁、血瘀、痰郁与正虚并存的复杂病机。四类", "c": "主气郁"}, {"id": "c:沉+涩+短", "n": "沉涩短脉", "o": "沉涩短脉总属阴脉，以沉、涩、短三象相兼为特征。沉主病位在里，涩主血行瘀滞，短主气机郁滞或元气不足。原文以“沉涩短”为“一阳三阴”，强调阴多阳少，故其总病机为阴盛阳微、里虚夹瘀。具体而言，可因气机郁滞、血瘀内结而见气郁血瘀；可因久病元气亏虚、瘀血不去而成正虚夹瘀", "c": "主阴盛阳微"}, {"id": "c:细+沉+涩+小", "n": "沉涩细小脉", "o": "沉涩细小脉总属虚寒危候，主正气虚衰、邪气内陷。其沉主里、涩主血少、细小主气衰，合而示气血两虚、阳气衰微。在伤寒瘟疫中，身大热而见此脉、足冷者，为阳证见阴脉，正不胜邪，故“难治”。三类病机相互关联：正虚是根本，血少气衰为具体表现，阳衰寒厥为危重转归。此脉与洪大滑", "c": "主正虚邪陷"}, {"id": "c:细+沉+涩+软", "n": "沉涩细软脉", "o": "沉涩细软脉总起来主疟疾、正虚与湿滞。此脉见于疟疾论述中，原文虽非专论脉，但列脉细软、脉多微弱等，结合疟发渐早渐晏之辨，可知其核心病机为疟邪内伏、正气不足、湿滞气机。沉涩主邪伏湿滞，细软主气血亏虚，三者相互关联：疟邪伏于膜原，湿滞气机则脉沉涩；久疟伤正，气血不足", "c": "主疟"}, {"id": "c:沉+涩", "n": "沉涩脉", "o": "沉涩脉总属里证，以气血运行不畅为核心病机。沉主病在里，涩主血行迟滞、津伤或湿阻。其病机有虚实两端：实者多气滞血瘀、痰湿内阻、郁热内伏、寒湿痹阻、气逆不降，皆因邪阻脉道，气血壅滞；虚者多里虚精血亏耗，脉道不充而涩。各类之间常相互兼夹，如气滞血瘀可兼痰湿，郁热可兼", "c": "主气滞血瘀"}, {"id": "c:沉+虚+涩", "n": "沉涩虚脉", "o": "沉涩虚脉总属里虚之候，以阴血亏少、津液枯涸为核心病机。沉主病在里，涩主血少津枯，虚则无力。其具体所主，一为阴血枯竭，如内伤噎隔之五脏阴伤；二为虚寒内生，因阳气不足、温煦无力；三为血脉闭塞，因邪阻脉道、气血凝滞。三者相互关联：阴血亏虚可致脉道不充而涩，久则阳气亦", "c": "主血少津枯"}, {"id": "c:沉+涩+弱+软", "n": "沉涩软弱脉", "o": "沉涩软弱脉总起来主正气已伤、肝木横逆、气机升降失常之病机。沉为气陷，涩为营亏血滞，软弱为正气已伤，三脉合见，反映郁怒伤肝、肝营亏虚、气逆痰升、清浊升降失常的复杂证候。其核心在于肝木横逆，始则气逆上行而胸胁痛胀走窜，继则下克脾脏而脐下梗痛、二便不爽，终致清不能升", "c": "主气陷"}, {"id": "c:沉+涩+软", "n": "沉涩软脉", "o": "沉涩软脉总起来主虚寒、气血涩滞、正虚邪伏及肝郁气逆等病机。沉主里，涩主血少气滞，软为虚象，三脉合见，多反映正气已伤、气血涩滞、虚寒内盛之候。若兼细，则主疟邪内伏、湿滞气机、气血亏虚；若兼弱，则主郁怒伤肝、肝营亏虚、气逆痰升、清浊升降失常。各类病机相互关联：虚寒", "c": "主虚寒"}, {"id": "c:滑+沉+平", "n": "沉滑平脉", "o": "沉滑平脉总以沉应肾与冬令，滑为胃气之和，故为无病之常。其病机分三类：平脉示常，太过与不及示病，死脉示败绝。太过如弹石病在外，不及如解索病在内，病脉如引葛按之益坚；死脉如转索辟辟如弹石，为肾气绝之候。三类以胃气存亡为枢：有胃气则平，胃气失和则病，胃气竭则死。", "c": ""}, {"id": "c:数+滑+沉", "n": "沉滑数脉", "o": "沉滑数脉总属里实热证，以痰、热、积三者交结为核心病机。沉主病在里，滑主痰湿积滞，数主热邪亢盛，三脉合见，说明邪实内蕴、郁而化热。其具体所主，或为痰热内蕴，或为积滞内阻，或为湿热蕴结，或为热厥、伏热内闭，或为暑热挟滞，甚则正虚邪实。诸类之间，以‘痰热积滞’为共同", "c": "主痰热"}, {"id": "c:滑+大+沉+浮", "n": "沉滑浮大脉", "o": "沉滑浮大脉总属肾与膀胱虚冷、阳气衰弱、水液不摄之候。沉滑为下元虚冷、水寒内停之正脉，浮大则为虚阳外浮、气不固摄之变脉。三者相互关联：虚冷是病本，水不摄是病机表现，逆证是脉证相反的危重转归。原文以遗尿、小便不禁为主症，兼及少腹牢痛，皆因膀胱失约、肾气不固所致。脉", "c": "主虚冷"}, {"id": "c:滑+沉+疾", "n": "沉滑疾脉", "o": "沉滑疾脉总属里实热证，以痰湿内蕴、郁而化火为核心病机。沉主病位在里，滑主痰涎壅盛，疾主热盛火升，三者合见，提示痰湿郁久化热化火，壅滞中上二焦，肺胃气机不展。其病变常涉多个层面：痰湿阻肺则咳嗽气喘、胸中气急；痰火升腾则头面上火、头汗、潮热；湿热生风则麻木、跳动、", "c": "主痰湿内蕴"}, {"id": "c:滑+沉+伏+结", "n": "沉滑结伏脉", "o": "沉滑结伏脉总起来主里实热痰结滞之证。沉主里，滑主痰，数主热，结伏示邪气深结难解。三分类中，主里实积滞为总纲，强调病位在里、邪实结聚；主热痰内结突出病理因素为热与痰交结；主暑湿滞下则言具体病因与病证。三者相互关联：暑湿外受、温补助虐，酿成热痰，结伏于里，阻滞气机", "c": "主里实积滞"}, {"id": "c:滑+沉", "n": "沉滑脉", "o": "沉滑脉总属里实之候，以痰饮水湿、积滞、湿热、痰热、气滞、血滞等邪实内蕴为基本病机。沉主病在里，滑主痰湿、食积、实热，二脉相合，提示邪实结聚于内、气机壅滞。其具体所主，可因兼邪与病位不同而分为痰饮内停、水湿泛滥、积滞内结、湿热蕴蒸、痰热内闭、气滞痰阻、血滞痰瘀等", "c": "主痰饮"}, {"id": "c:滑+沉+迟", "n": "沉滑迟脉", "o": "沉滑迟脉总主肾气虚弱、阳气不足之里虚证。沉主病位在里，迟少主阳气衰少，滑非实热之滑，乃虚滑无力，合而示肾气亏虚、阳失温煦。原文以肾病色黑、气弱少气、耳聋腰痛失精、膝冷食减为证，脉症相应，故曰“为可治”。三类病机相互关联：肾虚为根本，阳虚为病机关键，里虚可治为转", "c": "主肾虚"}, {"id": "c:滑+沉+长", "n": "沉滑长脉", "o": "沉滑长脉总属阴阳相兼之脉，以沉为阴、滑长为阳，合为一阴二阳之象。其核心病机为阳多阴少、阳气偏盛，兼有阴阳相合为病之机。原文以浮沉长短滑涩分阴阳，沉滑长为“一阴二阳”，与“一阴一阳”沉滑、“一阴三阳”浮滑长相对，说明阳渐胜而阴渐少。故本脉所主，以阳盛为主，兼见阴", "c": "主阳盛"}, {"id": "c:弦+沉+濡", "n": "沉濡弦脉", "o": "沉濡弦脉总属湿浊内蕴、气机壅滞之象。沉主病在里，濡主湿滞，弦主饮邪或肝气不疏。其主病机主要有二：一为痰饮湿浊内伏，二为湿阻气滞、肝脾不调。两者均以湿浊为患，但前者侧重痰饮深伏络脉，后者侧重气机壅滞、肝脾不和。脉象沉濡弦反映了湿浊内蕴、阳气不宣、气机不畅的病理特", "c": "主痰饮湿浊"}, {"id": "c:沉+濡+弱", "n": "沉濡弱脉", "o": "沉濡弱脉总属虚损之候，以气虚阳衰为核心病机。沉主里，濡弱主气虚阳衰，三者相合，揭示阳气虚衰、运化无力之本质。阳气不足，一则不能温煦脾土，致脾虚中满，症见胸膈痞胀、饮食少、大便溏泻；二则不能化气行水，致水湿内停，症见手足浮肿、身重不能动止；三则清阳不升、浊阴不降", "c": "主气虚阳衰"}, {"id": "c:数+沉+濡", "n": "沉濡数脉", "o": "沉濡数脉总起来主湿遏热伏、暑湿内蕴之证，其病机核心为湿与热合、蕴结于里。沉主里，示邪在脏腑；濡主湿，示湿浊内蕴；数主热，示热邪亢盛。三者相合，反映湿浊与热邪交蒸于内，气机受阻，热不得透。从具体段落看，此脉可主湿热内蕴、暑湿充斥、气血并病、湿遏热伏、蒙蔽心包等，", "c": "主湿热内蕴"}, {"id": "c:滑+沉+濡+平", "n": "沉濡滑平脉", "o": "沉濡滑为冬肾当令之平脉，总主肾水得胃气之和，为无病之常。其脉以沉应冬令与肾位，濡滑为胃气与肾水相合，故为平脉。若反见他脉，则示他脏乘肾，依五行生克分五邪：肺乘肾为虚邪，肝乘肾为实邪，脾乘肾为贼邪，心乘肾为微邪。平脉示常，诸邪脉示变，常变之间以胃气存亡与生克顺逆", "c": ""}, {"id": "c:数+滑+沉+濡", "n": "沉濡滑数脉", "o": "沉濡滑数脉总起来主痰热积滞深踞于里、湿浊内蕴之证。四脉各有所主：沉主病在里，示痰积深踞；濡主湿，示湿浊内蕴；滑主痰，示痰涎壅盛；数主热，示邪火亢盛。四者相合，反映有形之痰积与无形之邪火相蒸于表里，充斥于上下，形成痰、湿、热、积交结之复杂病机。原文以‘一叶小舟行", "c": "主里实积滞"}, {"id": "c:滑+沉+濡", "n": "沉濡滑脉", "o": "沉濡滑脉总起来主里湿痰积，兼及常脉与变证。其核心病机为湿浊痰积阻于里，沉主里、濡主湿、滑主痰，三者相合，故见寒湿积滞、痰湿内蕴等证；若兼数则化热，成痰热积滞；若为冬令肾脉，则沉濡滑为胃气与肾水相合之平脉，示无病之常。各类之间以‘湿痰积’为共同基础：寒湿、痰湿、", "c": "主寒湿积滞"}, {"id": "c:沉+濡", "n": "沉濡脉", "o": "沉濡脉总起来主里虚、湿浊、气陷、阴亏火旺、痰浊、气痹液耗及积滞等多类病机。沉主里、濡主虚，故其核心为虚与湿，可表现为下焦虚寒、脾虚湿困、大气下陷、气弱液耗；虚久则阴亏火旺，水不涵木，厥阳独亢，挟痰浊上蒙清窍；湿浊内蕴又可化热生痰，痰涎壅盛则瘀阻脉道；脾虚湿滞日", "c": "主虚寒"}, {"id": "c:沉+濡+迟", "n": "沉濡迟脉", "o": "沉濡迟脉总主胸中大气下陷之剧。沉为气虚不升，濡为气弱不鼓，迟为阳运无力，三脉合见，反映大气虚陷、斡旋无权之核心病机。由此核心病机，可衍生五类具体病机：大气虚陷则心血循环无力，故脉沉濡迟；肺气呼吸将停，故努力呼气难上达；三焦失其统摄，故小便不禁；全身失其斡旋，故", "c": "主气虚下陷"}, {"id": "c:沉+牢", "n": "沉牢脉", "o": "沉牢脉总属里实坚结之象，主瘀血、积滞、顽痰等深痼有形之邪内结。沉主病在里，牢主坚积牢固，故凡气血痰食结聚深固、非轻剂可拔者多见此脉。三类病机虽异，然皆以“坚结”为共同特征：瘀血内结、积滞坚结、顽痰胶结，均属里实，非虚证可补。临证见沉牢脉，当细辨结聚之物，分别采", "c": "主瘀血内结"}, {"id": "c:沉+微+短", "n": "沉短微脉", "o": "沉短微脉总属阴寒内盛、阳气潜藏之象。其脉沉主里、短主气收、微主阳微，三者相合，反映寒水闭藏、气液不能外越的病理状态。所主病机可归为三类：一为寒凝，寒邪闭塞肤腠，气血收引；二为阳微，阳气衰微，鼓动无力；三为气收，气机收敛，气血内藏。三者相互关联：寒凝可致阳微，阳", "c": "主寒凝"}, {"id": "c:沉+短", "n": "沉短脉", "o": "沉短脉总属阴脉，以沉主里、短主气收为基本特征，总病机为阴寒内盛、阳气不运、气机收束。所主病机可归为寒湿、寒厥、阳微、气郁四类：寒湿郁痹阳明，则见咳呕、便溏；阴寒内盛，则四肢逆冷而为寒厥；阳不旋运、夜阴用事，则浊泛呕吐而阳微；气机郁滞、血行不畅，则成里虚夹瘀之气", "c": "主寒湿"}, {"id": "c:大+沉+紧", "n": "沉紧大脉", "o": "沉紧大脉总起来主寒邪外束、湿热痰积内郁、本虚标实之病机，多见于疝痛等肝经疾患。沉主里，紧主寒主痛，大示邪实或正虚。诸类关系：寒邪外束为诱因，湿热痰积死血内阻为病本，正气不足为转归，三者相合，形成本虚标实、寒热错杂之局。脉沉紧大而有力者偏邪实，大而豁无力者偏正虚", "c": "主寒痛"}, {"id": "c:滑+沉+小+紧", "n": "沉紧小滑脉", "o": "沉紧小滑脉总起来主里寒与气食交阻，进而形成积块。沉主里，紧主寒痛，小主气郁，滑主食积，四者相合，提示寒邪与气、食交阻于中焦，结聚成块。原文“脐之上下作痛，块结如石伏于脘底”正是寒凝气食、积块内结之象，故治以温中理气消食，服后痛缓块小。三类病机相互关联：里寒为因", "c": "主里寒"}, {"id": "c:弦+细+沉+紧", "n": "沉紧弦细脉", "o": "沉紧弦细脉总属阴寒内盛、阳气不足之候。沉主里，紧主寒，弦主气滞与痛，细主虚，四象相合，反映寒邪深伏、气机郁滞、痰饮内结、阳气亏虚的复杂病机。各段所主虽有偏重，但相互关联：寒凝可致气滞，气滞则津液不布而成痰饮；痰饮内停又进一步损伤阳气，形成里虚寒；寒邪深入肝经，", "c": "主气滞"}, {"id": "c:沉+微+紧+迟", "n": "沉紧微迟脉", "o": "沉紧微迟脉总起来主里实积痛、气血壅滞、正气受困之候。沉主里，紧主痛主积，微迟为气血壅滞、阳气不伸。原文肠痈案中，右腹肿痛如拳、右足不能伸直、寒热便闭，显系热毒壅结、肠痈成脓，脉沉紧为里实疼痛，微迟示正气受困。三类病机相互关联：里实积痛为病之本，气血壅滞为病之机", "c": "主里实积痛"}, {"id": "c:数+沉+紧", "n": "沉紧数脉", "o": "沉紧数脉总起来主里、主寒、主痛、主郁，并可兼热、兼虚、兼实积。沉主里、主阳郁，紧主寒凝气滞与疼痛，数在此非必为热，可因寒邪逼迫、阳气挣扎而见，亦可因热郁于内而现。故其病机大致分四类：寒凝气滞、阳郁热结、里实积结、正虚寒盛。四类之间，以沉紧为共同基础，数象之寒热", "c": "主寒凝气滞"}, {"id": "c:沉+涩+紧", "n": "沉紧涩脉", "o": "沉紧涩脉总主寒湿内郁、气滞血瘀之证，其病机核心为里寒湿盛、气机壅滞。沉主里，紧主寒主痛，涩主气滞血瘀，三者相合，反映寒湿困阻中焦，脾运失职，浊气逆上为胀，清气下为泻。久延则脾阴伤而及肾，致脾肾阳虚，水湿泛滥。故本脉所主病机以寒湿内郁为始，气滞血瘀为继，脾肾阳虚", "c": "主寒湿内郁"}, {"id": "c:数+滑+沉+紧", "n": "沉紧滑数脉", "o": "沉紧滑数脉总起来主里实热结，兼有水饮结聚之变。沉主里，紧主痛，滑数主热实，故凡热邪内陷、与有形实邪结于胸腹，见舌干而渴、日晡潮热、胀满痛不可近者，脉当沉紧滑数。若水饮结聚，则热象不显而脉转沉涩，然其病位仍在里，故沉紧滑数亦可提示水结之可能。两类病机均以里实为共", "c": "主里实热结"}, {"id": "c:滑+沉+紧", "n": "沉紧滑脉", "o": "沉紧滑脉总属里寒痰盛之象。沉主里，紧主寒，滑主痰，三者相合，提示寒邪与痰湿交阻于里，阳气被遏。所主病机主要有三类：一为寒痰内盛，蒙蔽清阳，见昏不知人、身体软重；二为里寒痛证，寒凝气机，见胃中大痛、痛厥；三为阳虚寒盛，阳气不达，见手足微温。三者相互关联，寒痰为标", "c": "主寒痰内盛"}, {"id": "c:沉+紧+疾", "n": "沉紧疾脉", "o": "沉紧疾脉总起来主积、寒凝、气结、里实，核心病机为寒凝气结、深伏成积。沉主里，紧主寒凝，疾主气结急迫，细而附骨主病位深伏、气血不足，诸因素相合，形成积块癖块。积为脏病，终不移，脉象沉紧疾附骨，示病深结聚。若诊见和缓，则胃气无恙，非癖块之脉，强调和缓脉可排除积证。", "c": "主积"}, {"id": "c:沉+紧+硬", "n": "沉紧硬脉", "o": "沉紧硬脉总起来主里实结聚、结胸热实之病机。沉主里，紧主实邪结聚，硬为有形实邪坚结之象。原文所述伤寒六七日，脉沉紧而心下硬痛，乃伤寒传里之实邪结于胸膈，不因误下而成结胸，属热实结聚之证。故本脉所主，以里实为纲，以热实结胸为具体病证，二者相互关联，共同反映邪气内结", "c": "主里实结聚"}, {"id": "c:沉+紧", "n": "沉紧脉", "o": "沉紧脉总属里寒实证，以寒邪深踞、气机凝滞为核心。沉主病在里，紧主寒主痛主结，二者相合，多示寒凝于里、阳气被遏。其具体所主，或为单纯里寒，或寒凝作痛，或寒与积、食、痰、血交阻，或水寒结聚，或寒凝血瘀，或寒湿困阻，甚则阳郁热结而见沉紧。各类之间以寒为共同基础，兼夹", "c": "主里寒"}, {"id": "c:细+沉+紧+伏", "n": "沉细伏紧脉", "o": "沉细伏紧脉总属阴脉，主里、主虚、主邪伏。其核心病机为五脏不和、毒蓄于内，发为阴证疮疽。与浮数洪紧之阳脉主六腑不和、毒发于外为痈相对，此脉提示毒邪深伏于里，不能外达，故初发甚微、无疮头、身不热而内燥，伴胸膈痞闷、饮食无味等症。沉细反映正气内虚，伏紧反映邪毒内结，", "c": "主五脏不和"}, {"id": "c:细+沉+动", "n": "沉细动脉", "o": "沉细动脉在原文中仅见于“足少阴肾痧”一条，其总病机为痧邪犯肾、血伤气扰。沉细为肾脉本象，示病位在足少阴；动而止不匀，示痧邪扰动气血、脉气不宁。原文以芤主血伤为辨痧总纲，故沉细动脉亦含血伤邪扰之义；动止不匀又反映气血失和、运行失序。三类病机相互关联：痧伤肾经为病", "c": "主痧伤肾经"}, {"id": "c:数+细+沉+小", "n": "沉细小数脉", "o": "沉细小数脉总起来主里虚有热、正虚邪恋之证。沉主里，细主虚，小主不足，数主热，四者相合，揭示病位在里、正气虚衰而兼有热象。从原文看，该脉见于夏月暴冷伤中、泄痢耗液之后，正虚水湿不化，通身浮肿，成冷下结。其病机核心是里虚有热，正虚邪恋，水湿内停。各类之间相互关联：", "c": "主里虚"}, {"id": "c:细+沉+小", "n": "沉细小脉", "o": "沉细小脉总起来主正气虚衰、邪气内陷，以虚为本，或兼湿、兼热、兼郁。其基本病机为沉主里、细小主气血不足，故凡见此脉，多示正虚不能抗邪。具体可分五类：正虚邪陷者，见于伤寒温病热盛而脉反沉小，为正不胜邪之危候；气血虚衰者，见于亡血失血或虚寒危候，脉道不充；里虚夹湿者", "c": "主正虚邪陷"}, {"id": "c:弦+细+沉+伏", "n": "沉细弦伏脉", "o": "沉细弦伏脉总起来主阳气衰微、浊阴内盛、络脉闭阻之病机。沉为在里，细为阳微，弦为阴凝，伏为气闭，四象合见，说明正气虚极而阴邪壅盛，尤以肝经阴络为病所。原文以“阳微之极，浊阴太甚克之”为纲领，指出积气、肝著咳逆皆由此派生：浊阴克伐阳气，气机不得宣通，久病入络，故见", "c": "主阳微阴盛"}, {"id": "c:弦+细+沉+促", "n": "沉细弦促脉", "o": "沉细弦促脉总起来主瘀血内阻、里虚、气滞与郁热。沉细主里虚，提示久痢正虚；弦主痛主瘀，促为气滞血瘀、郁而化热。四类病机相互关联：久痢正虚，气血不足，脉道不充则沉细；气虚推动无力，或情志不遂，则气滞血瘀；瘀血内停，气机不畅，郁而化热，故脉促。原文以瘀血痢为例，因饱", "c": "主瘀血内阻"}, {"id": "c:弦+细+沉+弱", "n": "沉细弦弱脉", "o": "沉细弦弱脉总属阴脉，主虚与饮两类病机。沉细弱主虚，反映阳气不足、气血亏虚；弦主饮，反映饮邪内伏。二者相合，说明饮为阴邪、阳气不足，本虚标实。原文强调‘最忌补阴，补阴必死’，因饮为阴邪，补阴则助阴碍阳，故当以温化饮邪为治。虚与饮相互关联，阳虚是饮停的基础，饮停又", "c": "主虚"}, {"id": "c:弦+细+沉", "n": "沉细弦脉", "o": "沉细弦脉总属正虚邪恋、寒凝气郁之象。沉主里、细主虚，弦主饮、主痛、主气郁。其病机可归纳为阳虚寒凝、虚损夹邪、痰饮内停、肝郁脾虚、阴亏阳亢、气滞血瘀六类。诸类之间常相互兼夹：阳虚寒凝可致痰饮内停，虚损夹邪多兼气滞血瘀，肝郁脾虚日久可化火伤阴而见阴亏阳亢。总以虚为", "c": "主阳虚寒凝"}, {"id": "c:细+沉+涩+弱", "n": "沉细弱涩脉", "o": "沉细弱涩脉总属阴寒凝滞、气血虚损之象。其脉沉主里，细弱主虚，涩主滞，合而示阴寒之邪凝滞于内，气血不足且运行不畅。原文以“阴滞于阳”概括其病机，与阳热之“浮洪弦数”相对，治当以热药温通。此脉又见于痈疽疮疡，因气血虚滞而肌肉难长、疮久未合，故中年后见虚弱脉象当予滋", "c": "主阴寒凝滞"}, {"id": "c:细+沉+弱", "n": "沉细弱脉", "o": "沉细弱脉总属里虚之脉，以正气亏虚为共同基础。沉主病在里，细主阴血不足，弱主气血两虚，故其核心病机为气血阴阳亏虚。具体而言，或为湿邪内困、阳气不伸，或为脾肾阳虚、脏寒内生，或为气血亏虚、正虚无力运邪，或为虚中夹实、正虚邪恋。各类之间以虚为本，湿、寒、痰等为标，标", "c": "主湿困阳虚"}, {"id": "c:细+沉+微+弱", "n": "沉细微弱脉", "o": "沉细微弱脉总属虚证，以气阴两虚、阳气衰微为核心。沉主里，细主阴血不足，微主阳气衰微，弱主气血两虚，故其病机多责之正气亏虚。具体而言，或为气阴两伤，见于伏邪为疟、内消等病，正虚无力运邪外达；或为阳衰气陷，见于大气下陷、痘疮阳气欲绝，脉多兼迟；或为脾胃气虚，运化无", "c": "主气阴两虚"}, {"id": "c:数+细+沉+微", "n": "沉细微数脉", "o": "沉细微数脉总属虚实夹杂之候，以精血亏虚、营液耗伤为本，伏火内扰为标。沉细主里虚，微为阳衰，数则示阴亏生热。三则医案均见肝肾或脾胃亏虚，精血营液不足，失于濡养，故见筋痿、拘挛、便涩、溺沥；虚火内灼，则便结、舌红少苔；若脾胃虚衰，则停饮聚上、肝木横逆。诸类病机相互", "c": "主精血亏虚"}, {"id": "c:细+沉+微", "n": "沉细微脉", "o": "沉细微脉总属阳气衰微、阴寒内盛之候。沉主里，细主虚，微主阳衰，三脉相合，反映正气虚衰、阳不胜阴的基本病机。其具体所主，或为阳虚寒盛，或为中气大虚，或为寒湿内盛，或为脏气虚衰而邪气内结，甚则阳脱危候，亦有肾虚热伏之变。诸类之间，以阳气虚衰为核心：寒盛、湿盛、邪结", "c": "主阳虚寒盛"}, {"id": "c:数+细+沉+促", "n": "沉细数促脉", "o": "沉细数促脉总属正虚邪郁、气机逆乱之候。其脉沉细为阴血阳气不足，数促为热邪内郁，断续细乱为正气溃散、升降失度。四类病机相互关联：热郁于内则阴伤，阴伤则正虚，正虚则气乱，气乱又加重热郁与阴伤，形成恶性循环。原文所载风温坏症，误汗误下后见沉细数促，正是热郁、阴伤、正", "c": "主热郁"}, {"id": "c:数+细+沉+弱", "n": "沉细数弱脉", "o": "沉细数弱脉总起来主阴虚内热与痰热内蕴两类病机。沉细为阴伤，数弱为虚热，故见口渴、手心热、喜暗处等阴虚内热之象；若痰热内结，阻滞气机，则脉可渐伏而妄语，形成痰热蒙蔽心窍之证。两者可并存，阴虚为本，痰热为标，痰热又可加重阴伤，故治疗需兼顾下痰与养阴。", "c": "主阴虚内热"}, {"id": "c:数+细+大+沉+浮", "n": "沉细数浮大脉", "o": "沉细数浮大脉总属虚实夹杂、阴阳格拒之象。沉细主阴寒内盛、阳气虚衰，数主虚阳躁动或热邪内扰，浮大主虚阳外浮无根。其病机核心在于下焦虚寒、元阳不足，虚阳不能潜藏而上浮，形成上焦燥热与下焦虚寒并存的戴阳证。原文明确指出，若脉沉细而数或浮大而数，断不可用通脉四逆汤，因", "c": "主虚阳浮越"}, {"id": "c:数+细+沉+涩", "n": "沉细数涩脉", "o": "沉细数涩脉总起来主血虚气郁、郁火内炽之病机。沉细为阴血不足，数主郁热内蒸，涩主气机郁滞、血行不畅。四者相合，反映血虚为本、气郁为枢、郁火为标、肝郁生虫为变。血虚则脉道不充，气郁则血行受阻，郁久化火则脉数，火郁生虫则见吐酸胸痛。诸类病机相互关联：血虚气郁为发病基", "c": "主血虚"}, {"id": "c:数+细+沉", "n": "沉细数脉", "o": "沉细数脉总属里虚有热之象：沉主病在里，细主阴血不足，数主热，合而多示阴液亏耗、虚热内扰，或邪热内陷、郁热不得透达。其具体所主，可因邪之性质与正气盛衰而异：若温邪伏营、暑热归心，则热陷营血、内闭心包；若暑入少阴，则劫烁肾阴；若寒湿痹阻，则阳虚湿痹而虚热内郁；若脾", "c": "主阴虚内热"}, {"id": "c:细+沉+浮+虚", "n": "沉细浮虚脉", "o": "沉细浮虚脉总主阳虚阴寒之证。沉细为阳气虚衰、寒凝脉道，浮虚无力为虚阳外浮而内真寒，二者皆以无力为共征，反映阳气不足、阴寒内盛之本质。所主病机可归为三类：阳虚寒凝、虚阳外浮、阴寒厥逆，三者相互关联，阳虚寒凝为基本病机，虚阳外浮为阳虚之变局，阴寒厥逆为阳虚寒盛之危", "c": "主阳虚寒凝"}, {"id": "c:细+沉+涩", "n": "沉细涩脉", "o": "沉细涩脉总主里虚、阴血不足、气血不畅，兼夹寒湿、湿热、痰瘀等邪。沉主病在里，细主阴血亏少，涩主血行迟滞、津伤或湿阻。其病机大致可分虚实两端：虚者见虚损劳伤、脾肾两亏、阴阳并弱；实者见寒湿内闭、湿遏热伏、气滞血瘀成积、痹痛、阳衰厥逆。各证常虚实夹杂，如虚损兼瘀、", "c": "主虚损"}, {"id": "c:细+滑+沉+疾", "n": "沉细滑疾脉", "o": "沉细滑疾脉总属里热炽盛、阴分受灼之候。沉细为阴脉，主病位在里、阴血不足；滑疾为阳脉，主痰火内盛、气机壅滞。四者合见，阴中伏阳，热郁于里而阴液已伤，故以“热”为核心病机。原文“脉沉细滑疾者热”一句直指其要，并与“脉数在腑”“脉滑多血少气”等条互参，可见其热多兼痰", "c": "主热"}, {"id": "c:细+滑+沉", "n": "沉细滑脉", "o": "沉细滑脉总属本虚标实之候，以里虚为基础，痰湿、积热、积气为标。沉主里，细主虚，滑主痰湿，三者合见，提示病位在里、正气不足而痰湿内壅。所主病机可归为六类：痰湿内阻、脾虚气弱、里热痰火、积聚内结、寒湿凝滞、肝胆郁滞。其中痰湿与脾虚常相因为病，脾虚不运则湿聚成痰；里", "c": "主痰湿"}, {"id": "c:细+沉+濡+软", "n": "沉细濡软脉", "o": "沉细濡软脉总属虚寒之象，主脾阳不运、痰饮内停、本质亏虚。沉主里，细濡软示阳气不振、气血不足。三证相互关联：脾阳亏虚为本，运化失职则津液凝滞酿痰，痰饮根深又进一步耗伤正气，形成本虚标实之局。脉象虚软不任猛剂，故治疗当以温药和之、疏理痰气，取减轻而不期霍愈。此脉所", "c": "主脾阳虚"}, {"id": "c:细+沉+疾", "n": "沉细疾脉", "o": "沉细疾脉总属阴阳失调、虚实夹杂之候。沉细主里、主虚、主阴亏，疾主热、主虚阳躁动。其病机有三类：一为阴液枯竭、虚阳外越之危候，如消渴躁热而脉沉细疾，属孤阳绝阴；二为阴寒内盛、格阳于外之阴证伤寒，见四肢逆冷、虚汗、狂言而脉沉细疾；三为里热炽盛、阴分受灼，热郁于里而", "c": "主阴竭阳浮"}, {"id": "c:细+沉+硬", "n": "沉细硬脉", "o": "沉细硬脉总起来主沉寒痼冷、气血虚衰、里实坚结三类病机。沉主里，细为气血虚，硬为寒凝坚结，三者相合，揭示虚寒为本、寒凝为标、里实为果的病理链条。原文产后气血交虚，积寒在腹，致胸腹胀满而坚、足冷过膝、咳喘不食，正是虚寒内盛、寒凝气机、坚结于里之象。三类病机中，气血", "c": "主寒凝"}, {"id": "c:数+细+沉+紧", "n": "沉细紧数脉", "o": "沉细紧数脉总起来主阴毒内结、寒盛阳衰之候。其沉细主里虚寒、阳气衰微；紧主寒凝气滞、疼痛；数在此非热，乃寒邪逼迫、阳气挣扎之象。三者相合，反映阴寒内盛、毒气攻心、阳气不达的病机。原文所载‘身重背强，腹中绞痛，咽喉不利，毒气攻心，心下坚强，短气不得息，呕逆，唇青面", "c": "主阴寒内盛"}, {"id": "c:细+滑+沉+紧", "n": "沉细紧滑脉", "o": "沉细紧滑脉总属寒、虚、痰湿相合之象。沉主里，细主虚，紧主寒，滑主痰湿，四者合见，多示里虚寒盛、痰湿内停之病机。所主病机主要有三类：一为寒湿凝滞经脉，如痓症身体强硬；二为少阴中寒、阳气不振，如但欲寐、恶寒足冷；三为痰饮内停，如胸背胀痛、呕吐不能食。三类之间相互关", "c": "主寒湿凝滞"}, {"id": "c:细+沉+紧", "n": "沉细紧脉", "o": "沉细紧脉总属里、虚、寒三象交织，以寒邪内盛、阳气虚衰为核心。沉主病在里，细主阴血不足或阳气虚，紧主寒主痛，三者相合，多示里寒证。其具体所主，或为单纯里寒，或为虚寒内生，或寒凝成积，或寒凝血瘀，或寒伤血络而气不摄血，甚则寒盛阳衰、少阴证全。各证虽表现不同，但病机", "c": "主里寒"}, {"id": "c:细+沉+缓", "n": "沉细缓脉", "o": "沉细缓脉总起来主湿邪内郁、阳气不伸，或脾虚湿困、运化失职，甚则阳虚寒盛、阴寒内停。其脉象要素中，沉主里、主湿着；细主虚、主湿滞；缓主湿、主脾弱。三者相合，核心病机为湿阻与阳（气）虚，且二者常互为因果：湿盛可困遏阳气，阳虚则湿浊不化。所涉段落中，或偏于湿邪内蕴（", "c": "主湿"}, {"id": "c:细+沉", "n": "沉细脉", "o": "沉细脉总属里虚之象：沉主病在里，细主正气不足、阴血亏少。其总病机以阳虚寒盛为核心，兼及虚损劳伤、湿浊内阻、饮邪内停、积滞内结、阴伤邪陷等。诸类之间常相互兼夹：阳虚寒盛可致湿浊不化、饮邪内停；虚损劳伤日久可累及阴阳，变生寒热；积滞内结多因正虚而邪留；阴伤邪陷则多", "c": "主阳虚寒盛"}, {"id": "c:细+沉+虚+迟", "n": "沉细虚迟脉", "o": "沉细虚迟脉总属里虚寒、气血不足之候。沉主里，细主虚，虚主气弱，迟主寒，四者相合，反映脾肾虚寒、气血两亏、阳运无力。其主病以虚寒、气血虚、脾虚内溃下脓血为主。诸类之间相互关联：虚寒为根本，气血虚为表现，脾虚内溃为具体病位与转归。原文以沉细虚迟与疾大而有热对举，辨", "c": "主虚寒"}, {"id": "c:细+沉+小+软", "n": "沉细软小脉", "o": "沉细软小脉总属虚损夹湿之象。沉细主里虚，软小主湿盛正衰，二者相合，揭示正虚与湿盛并存，尤以脾肾阳虚为本，水湿泛滥为标。原文‘湿鼓将成，脾肾攸关’点明病机关键：脾土不运则水湿浸淫，肾阳不足则气化失司，以致肢体漫肿、便溏腹胀。三类病机相互关联：里虚为湿盛之根，湿盛", "c": "主里虚"}, {"id": "c:细+沉+弱+软", "n": "沉细软弱脉", "o": "沉细软弱脉总属正虚邪恋之象。沉细主里、主阴血不足，软弱主正气无力，故其核心病机为正虚，尤以阴津亏耗为主。然此案中虚中夹实：热邪炼津为痰，痰热内蕴，故见咳嗽痰黏、喉有痰声。脉象'较昨稍起'示正气渐复、阴津渐回，但未全复，故脉仍软弱。三类病机相互关联：正虚为本，阴", "c": "主正虚"}, {"id": "c:细+沉+软", "n": "沉细软脉", "o": "沉细软脉总属正虚之象，以阴血亏虚、正气不足为基本病机。沉细主里、主阴血不足，软主正气无力，故凡见此脉，多提示气血阴津亏耗。在此基础上，可因虚致实、虚实夹杂，衍生出多种病机：阴虚不能制阳则虚热内扰，脉见躁疾或细数；阴不敛阳则虚阳外浮，脉浮大而空；脾阳不振则痰饮内", "c": "主阴血亏虚"}, {"id": "c:细+沉+缓+迟", "n": "沉细迟缓脉", "o": "沉细迟缓脉总起来主阳气衰微、阴寒内盛。沉细为阳气衰微，迟为脏寒，缓主中焦虚冷，三者相合，反映阳气不足、脏腑虚寒之病机。其具体可表现为中焦虚冷、阳虚寒盛，甚则阳气欲脱。原文见中脘胀痛、厥逆、汗多、食不喜进，脉沉细迟缓，乃阴寒内盛、阳气欲脱之危候。各类病机相互关联", "c": "主阳虚寒盛"}, {"id": "c:细+沉+迟", "n": "沉细迟脉", "o": "沉细迟脉总属里、虚、寒之象。沉主病在里，细主正气不足、阳虚阴盛，迟主寒凝气滞。其所主病机以阳虚寒盛为核心，可兼寒湿内阻、脾虚积寒、少阴阳衰、阴黄寒湿等。各段原文多从‘沉主里、迟主寒、细主虚’立论，或见于伤寒两感、少阴病，或见于霍乱、阴黄、久痢、水气重症，皆因阳", "c": "主阳虚寒盛"}, {"id": "c:沉+涩+结", "n": "沉结涩脉", "o": "沉结涩脉总起来主气血内滞、血虚津枯，兼及邪结与瘀血。沉主里，结为气滞，涩为血瘀或血少，三象相合，提示虚实夹杂之候。其病机类别包括血瘀络滞、邪结于里、血虚津枯、气血内滞。血瘀络滞与邪结于里偏实，多因郁怒、伏邪、产后虚而邪结所致；血虚津枯与气血内滞偏虚或虚实夹杂，", "c": "主血瘀络滞"}, {"id": "c:沉+结", "n": "沉结脉", "o": "沉结脉总属里实，以气血瘀滞、壅塞不通为核心病机。沉主病在里，结主气机阻滞或血行不畅，故其主病多归实证、积证。具体而言，若瘀热互结下焦，则主蓄血，见少腹硬满、如狂、小便自利；若寒凝气滞，则主寒实内结，见疝痛胀满、脉沉结不调；若情志所伤，则主气郁，见肺气郁、怒气伤", "c": "主蓄血"}, {"id": "c:滑+沉+缓", "n": "沉缓滑脉", "o": "沉缓滑脉总属里实，主寒湿痰滞内停。沉主里，缓主湿，滑主痰滞，三脉相合，提示寒湿痰浊内阻，气机不畅，营卫不和。原文见但寒不热、恶寒战栗、胸闷无汗、舌苔白腻，因贪凉饮冷、风寒外袭、冷滞内停而病。其病机核心为寒湿痰滞内蕴，导致营卫失调，发为疟疾。三类病机相互关联：寒", "c": "主寒湿内滞"}, {"id": "c:沉+缓", "n": "沉缓脉", "o": "沉缓脉总属里证、湿证，以湿滞阳气不运为核心。沉主在里，缓主湿、主虚，故其病机多围绕水湿内停、阳气受困展开。具体可分：寒湿内阻者，湿从寒化，阻遏气机；脾虚湿盛者，运化失职，水谷聚湿；阳虚气衰者，阳气不充，脉络不畅；湿热积滞者，湿郁化热，积垢内停；风湿毒邪者，湿毒", "c": "主寒湿内阻"}, {"id": "c:沉+缓+迟", "n": "沉缓迟脉", "o": "沉缓迟脉总起来主里、主寒、主湿、主阳虚。沉为病位在里，迟为寒象，缓主湿与虚，三象相合，反映寒湿内盛、阳气被困或里阳不足之病机。其下属沉细迟缓脉更偏阳气衰微、阴寒内盛，可见中脘胀痛、厥逆、汗多、食不喜进，甚则阳气欲脱；而本脉段则见遍身重痛、头晕、冷汗、咳嗽多涎、", "c": "主寒湿内盛"}, {"id": "e:沉", "n": "沉脉", "o": "沉脉总属里证，轻手不见、重取乃得，为阴脉，主病在里。其病机涵盖寒热虚实：或阳虚寒盛、水饮内停，或气郁邪闭、痰湿积滞，或里热郁结、伏邪内蕴，或气血虚损。各类之间常相互兼夹，如阳虚可致水饮不化，气郁可兼痰湿积滞，虚损日久可生内热。沉脉须结合兼脉与症候辨其虚实寒热：", "c": "主里寒阳虚"}, {"id": "c:弦+沉+芤", "n": "沉芤弦脉", "o": "沉芤弦脉总起来主里虚血少、气滞络伤、肝郁乘脾之病机。沉主病在里，芤主失血后阴血未复或中虚血少，弦主气机不畅、阳络未和或肝木乘脾。三者相合，多见于失血后络伤未复、余邪留滞，或肝郁乘脾、湿痰互结而脾阳不振、气血内虚之证。各类之间相互关联：里虚血少为病本，气滞络伤为", "c": "主里虚血少"}, {"id": "c:沉+芤", "n": "沉芤脉", "o": "沉芤脉总起来主里虚血少、气血郁滞及积邪内结之病机。沉主病在里，芤主失血后阴血未复或中虚血少。二者相合，多见于失血后络伤未复、余邪留滞，或血郁日久、阴血亏耗而兼郁滞之证。从所收段落看，丹溪论六郁，血郁脉沉而芤，明言血郁兼血虚；又论五积脉象，沉实、附骨主积，积久伤", "c": "主血虚"}, {"id": "c:沉+虚+小", "n": "沉虚小脉", "o": "沉虚小脉总属气血虚衰、脉道不充之象，尤以产后气血耗伤为核心病机。其脉沉主气弱，虚小主血少，故产后见此脉为脉证相应，示胃气未绝，预后良好。然同一脉象若见于实牢坚等邪盛证，则提示胃气败绝、瘀血内结，预后不良。各类病机相互关联：气血虚衰是基础，胃气未绝是转归关键，预", "c": "主气血虚"}, {"id": "c:细+沉+虚", "n": "沉虚细脉", "o": "沉虚细脉总属里虚正亏、邪陷难托之候。沉主里，示邪气内陷；虚细主气血阴阳俱亏，脉道不充。三者相合，反映正气大虚于内，无力抗邪托邪。所主病机可归为三类：里虚、脱象、邪陷正亏。里虚为基本病机，以气血阴阳俱亏为核心；邪陷正亏为里虚基础上邪气内陷、正难托邪的病理状态；脱", "c": "主里虚"}, {"id": "c:沉+虚", "n": "沉虚脉", "o": "沉虚脉总属里虚之候，以正气不足为核心病机。沉主病位在里，虚主正气亏虚，故凡脏腑气血阴阳不足、脉道不充者，皆可见沉虚之脉。其具体所主，可因虚损性质与病位不同而分为数类：一为里虚，乃基本病机，涵盖气血阴阳俱亏；二为气陷，因中气不足、升提无力而见脱肛等症；三为胃逆，", "c": "主里虚"}, {"id": "c:沉+软+结", "n": "沉软结脉", "o": "沉软结脉总属肝郁气结、郁热挟痰之候。沉主里，软主气机不畅，结示郁滞，合而观之，其病机核心为肝气郁结，气郁日久则生热，热灼津液则凝痰，痰热互结，阻滞中焦。原文脉沉弦而软滑，正是郁、热、痰三者交织之象。误用温补，更助热凝痰，致痞满日增、肌肉渐消。故本脉所主，以肝郁", "c": "主肝郁气结"}, {"id": "c:沉+软", "n": "沉软脉", "o": "沉软脉总起来主里、主虚，以正气不足为基本病机。沉主病位在里，软主正气无力，故凡见此脉，多提示里虚之候，尤以中焦虚寒、气血阴津亏耗为常见。原文赵显之洞泄寒中，两手脉沉而软，断为里虚，温补而愈，正示此脉不可妄下。在此基础上，沉软脉可因兼脉不同而衍生多类病机：兼涩则", "c": "主里虚"}, {"id": "c:沉+迟+伏", "n": "沉迟伏脉", "o": "沉迟伏脉总属阴寒内盛、阳气不振之候。沉主里，迟主寒，伏主邪深，三象相合，揭示寒邪深伏于里、阳气被遏或虚衰之病机。其具体所主，一为寒凝收引，气血不通而痛；二为饮邪内停，脾阳不运，水饮深伏；三为阳衰阴盛，火衰寒胜，见吐利逆冷等阴证。诸类之间，以寒为共同病因，以阳气", "c": "主寒凝"}, {"id": "c:数+沉+小+紧+迟", "n": "沉迟小紧数脉", "o": "沉迟小紧数脉总属寒饮内停、胸阳不振之病机。寸脉沉迟，主里主寒，反映上焦阳气不振，寒饮内停；关上小紧数，紧为寒凝，数为阳郁，乃寒饮阻遏胸阳，气机不利所致。两类病机相互关联：寒饮内停是病之本，阳郁寒凝是病之标，共同导致胸痹喘息咳唾、胸背痛短气等症。此脉象以寒饮为根", "c": "主寒饮内停"}, {"id": "c:弦+沉+紧+迟", "n": "沉迟弦紧脉", "o": "沉迟弦紧脉总属里寒实证，以寒邪深痼、阳气不运为核心病机。沉主里，迟主寒，弦紧为寒凝收引、气滞痛证之象。四类病机相互关联：里寒阳虚是基础，阳气不布则寒凝气滞，气滞不通则痛；寒饮内停、上逆为阳虚不能化饮之变；寒邪深入、气血凝滞则成里寒实结。临床可见气痛、腹中寒凉作", "c": "主寒饮上逆"}, {"id": "c:沉+微+弱+迟", "n": "沉迟微弱脉", "o": "沉迟微弱脉总属虚证，核心病机为胸中大气下陷、气虚阳弱。沉主病在里，迟主阳虚，微弱主气衰，三者相合，反映正气大虚、鼓动无力。其病位重在胸中，故关前或右部尤甚。大气下陷则气短不足以息、努力呼吸似喘，甚则气息将停、失语；气陷不摄则见吐血、自汗、怔忡、胸胁满闷等。诸类", "c": "主大气下陷"}, {"id": "c:沉+涩+迟", "n": "沉迟涩脉", "o": "沉迟涩脉总起来主里虚寒、血少、气滞血瘀及寒郁之病机。沉主里，迟主寒，涩主血少气滞，三脉相合，多示阳气不运、阴寒内盛、气血虚滞之候。各分类之间相互关联：虚寒与血少常并见，因阳气不运则血少难生；气滞血瘀多由寒郁所致，寒凝则气血滞涩；寒郁又可加重虚寒与血少。故临床见", "c": "主虚寒"}, {"id": "c:滑+沉+涩+迟+实+芤", "n": "沉迟滑实涩芤脉", "o": "沉迟滑实涩芤脉总起来主里实夹瘀、寒湿痰积与死血为患。沉迟滑实一类，以沉主里、迟主寒、滑主湿痰、实主邪盛，合示寒湿、积痰等实邪内蕴，阻滞经络，气血不达四末而见麻木；沉涩而芤一类，以涩主血滞、芤主血虚或瘀血，合示死血内停，兼有血虚。两类均属里证，一偏寒湿痰积之实，", "c": "主寒湿"}, {"id": "c:沉+紧+迟", "n": "沉迟紧脉", "o": "沉迟紧脉总属里寒实证，以寒邪深痼、阳气不运为核心病机。沉主里，迟主寒，紧主痛主寒凝收引。其具体所主，一为里寒，寒邪内结，症见便闭溲涩、腹满苔白；二为阳虚，阳气不充，症见手足厥冷、身体拘急；三为寒凝气滞，气机壅塞，症见腹中绞痛、胸膈痞满；四为寒湿秽浊内闭，邪闭气", "c": "主阳虚"}, {"id": "c:细+沉+弱+迟", "n": "沉迟细弱脉", "o": "沉迟细弱脉总主阳气衰微、气血亏虚，兼寒湿内侵之证。沉主里，迟主寒，细弱主正虚，四象合参，揭示邪实正虚、阴阳气血俱损之病机。其具体所主，或为寒湿深入肝肾膀胱、气血凝滞之流注；或为血崩日久、气血阴阳俱脱之虚损危候；或为大汗亡阳、胸中大气下陷之气陷证；或为肾气不上达", "c": "主寒湿"}, {"id": "c:沉+迟", "n": "沉迟脉", "o": "沉迟脉总属里、虚、寒之象。沉主病在里，迟主寒，合而主阳气不足、阴寒内盛。其所主病机以里寒阳虚为核心，可兼寒凝气滞、寒痰水饮、虚寒不足、寒积内结，以及津伤筋急之痉病。各段原文多从‘沉主里、迟主寒’立论，或见于伤寒少阴、霍乱、水肿、癃闭、胸痹、腹痛、虚劳等证。类与", "c": "主里寒阳虚"}, {"id": "c:弦+沉+长", "n": "沉长弦脉", "o": "沉长弦脉在原文中为肝之常脉，谓肝藏血藏魂而隶于下焦，脉当沉长而弦。然此段所论，实以脉之常变对比示病机：肝脉反浮濡、肺脉反沉数，是肺燥失相傅之权，金不制木，肝木无所畏制而飞扬上越，魂不能藏，名离魂。故沉长弦脉总起来主肝木之病，其核心病机为肝郁化火、肺燥失制、魂不", "c": "主肝郁化火"}, {"id": "c:洪+促", "n": "洪促脉", "o": "洪促脉总起来主热盛急迫之证。洪为热邪炽盛、脉道宽大，促为热盛内迫、脉行急促而时一止，二者相合，反映热邪鸱张、病势急迫。所主病机以热盛为核心：热盛则脉洪，热炽则脉促，热毒充斥则成瘟热重症，热炽气分则见大热大渴汗注。其下属洪数促、洪大促、浮洪促诸脉，虽兼数、兼大、", "c": "主热盛"}, {"id": "c:大+洪+促", "n": "洪大促脉", "o": "洪大促脉总起来主热盛气急。洪大脉为阳明热盛之典型，热邪炽盛于气分，鼓动气血，故脉形洪大；促脉则因热盛内迫，气机急促，脉来急迫。二者相合，既反映热邪炽盛，又提示气机因热而急。原文冬温误表后，身大热、大渴、汗出如浴、舌鲜红有刺，皆热炽于里、迫于气分之征，脉洪大而促", "c": "主热盛"}, {"id": "c:大+洪+和+平", "n": "洪大和平脉", "o": "洪大和平脉在此段中并非单一主病，而是动态反映阴虚阳浮与肾阴亏虚的病理状态。原文以'沉细微主肾阴亏虚、脉道不充'与'洪大乃阴虚阳浮之象'对举，说明脉象可由沉细转为洪大，洪大亦可渐臻和平。其核心病机为肾阴亏虚、脉道不充，阴不制阳则虚阳浮越，故见洪大；治以滋肾润肺、", "c": "主阴虚阳浮"}, {"id": "c:大+洪+实", "n": "洪大实脉", "o": "洪大实脉总属邪热亢盛、邪气壅实之象。洪主热盛，大主病进，实主邪结，三者相合，突出热邪炽盛、正气未衰、邪正剧争之病机。其所主涵盖里热结实、阳明热盛、火盛迫血、暑热内伏及邪盛正实等，皆以热实为共同基础。然兼脉与部位不同，病机有异：兼数则热急，兼滑则痰热，兼结则热壅", "c": "主里热结实"}, {"id": "c:大+洪+小", "n": "洪大小脉", "o": "洪大小脉在此段总以邪实壅盛、病势进退为核心。六脉洪大主痰饮疝瘕等实邪内盛，气血抗邪而脉形洪大；治疗后脉由大变小，为邪退佳兆，若脉复大则示余邪复炽、病势再进，故洪大脉既是邪盛之征，又是观察病势进退的指标。然脉平而瘕胀痹痛未除，说明久病在络，痰瘀深伏，非脉平即病愈", "c": "主邪盛"}, {"id": "c:数+弦+大+洪", "n": "洪大弦数脉", "o": "洪大弦数脉总起来主热毒炽盛、气血壅滞之实证。数脉主热，洪大示热盛，弦脉主痛、主肝经郁滞，四者相合，反映邪热亢盛、毒邪结聚、气血壅遏不通之病机。原文所载横痃一证，因淫毒下注肝经，热毒炽盛，气血壅滞，结聚成肿，故见脉洪大弦数，症见胀痛红肿、口中苦、舌苔黄。三类病机", "c": "主热毒炽盛"}, {"id": "c:弦+大+洪", "n": "洪大弦脉", "o": "洪大弦脉总起来主热盛、肝郁、痰湿、正虚四端，而热与郁为其核心。洪大主热盛与阳浮，弦主肝郁气滞与痰饮，二象相合，多反映火热内郁、肝气不舒之证；若兼滑则痰火互结，兼数则热毒壅滞，兼长则气逆上冲，兼虚豁大则阴亏阳浮或正虚邪恋。诸类病机常相兼为患：热盛可致肝郁化火，肝", "c": "主热盛火郁"}, {"id": "c:弦+大+虚+洪", "n": "洪大弦虚脉", "o": "洪大弦虚脉总起来主元气亏损、正不胜邪之病机。其脉象洪大似邪盛，然按之弦虚，实为元气不足、气机不和之征。原文见于疮疡元气亏损者，症见恶寒发热、肢体倦怠、饮食少思，或不能起发消散、生肌收敛，皆因正虚不能托毒外出。洪大为邪盛之假象，弦为气机不和，虚为元气亏损之本质，", "c": "主元气亏损"}, {"id": "c:弦+大+洪+长", "n": "洪大弦长脉", "o": "洪大弦长脉总起来主热盛气逆、气血上冲之大厥病机。其脉洪大示热盛，弦长示气逆，有力示邪实，三者相合，反映脏腑气血挟热上冲，血与气并走于上。热盛则气血沸涌，气逆则升而不降，上冲脑部，致充血、血管破裂或渗血，发为昏厥、手足痿废等大厥之证。此脉象与气虚微弱之痿废截然不", "c": "主热盛气逆"}, {"id": "c:大+洪+急+疾", "n": "洪大急疾脉", "o": "洪大急疾脉总属邪热炽盛、阴液耗竭、正不胜邪之危重脉象。其形成机理为热邪内陷，充斥脉道，故脉形洪大；热灼阴伤，阴不制阳，故脉势急疾；汗出而热不退，脉躁疾不为汗衰，是正虚邪盛、阴阳交争之死候。三类病机相互关联：热盛为始动因素，阴竭为热盛之果，正不胜邪为最终结局，共", "c": "主热盛"}, {"id": "c:大+洪+急", "n": "洪大急脉", "o": "洪大急脉总属真元耗损、液络大亏、阴不制阳、虚风内动之象。其脉形洪大，非实热壅盛，乃阴精亏虚、虚阳外浮；脉势急劲，非邪正交争，乃水不荣木、肝风内动。原文以'六脉洪大而急'伴真元损耗、液络大亏之因，及瘰疬、肢肿、挛搐等风动之症，明示此脉以虚为本、以风为标。三类病机", "c": "主真元耗损"}, {"id": "c:数+大+洪+实", "n": "洪大数实脉", "o": "洪大数实脉总属邪热亢盛、邪气壅实之象。洪主热盛，数主热急，实主邪实，大主病进，四者相合，突出热邪炽盛、正气未衰、邪正剧争之病机。其所主涵盖气分热实、热毒壅盛、暑热内伏及痰热蒙蔽心包等，皆以热实为共同基础。然兼脉与部位不同，病机有异：兼模糊者热蒸痰蒙，左右悬殊者", "c": "主邪实"}, {"id": "c:数+大+洪+疾", "n": "洪大数疾脉", "o": "洪大数疾脉总属邪热亢盛、急迫鼓脉之象。洪大为热盛气壅，数疾为邪热急迫，故其核心病机为实热。具体所主，一为阳明实热内结，燥屎内停；二为风温犯肺，邪热炽盛；三为燥火加临，伤及气血；四为肝胃同病，木乘土位。诸类之间，以实热为共同基础，或兼燥屎，或兼风温，或兼燥火，或", "c": "主风温犯肺"}, {"id": "c:数+大+洪", "n": "洪大数脉", "o": "洪大数脉总起来主热盛，但须分虚实。实热类包括阳明气分热盛、热毒炽盛、湿热痰火，脉多洪大数有力，症见大热、大渴、汗出、烦躁、肿痛、癍疹等，治宜清热泻火、解毒化湿。虚热类包括虚阳外浮、阴虚火旺、肝郁化火，脉多洪大数无力或兼弦急，症见虚火上炎、精血亏虚、郁怒伤肝等，", "c": "主阳明热盛"}, {"id": "c:大+浮+洪+紧", "n": "洪大浮紧脉", "o": "洪大浮紧脉总起来主寒束热盛、表里俱实之病机，多见于伤寒重证。其脉象由洪大与浮紧复合而成：洪大主里热炽盛，浮紧主外寒束表，二者并见，说明外寒闭表、里热郁蒸，形成表寒里热、表里俱实的实证格局。原文所载高热无汗、烦躁、时寒时热、头痛身痛等症，正是寒邪外束、热郁于里的", "c": "主热盛"}, {"id": "c:大+浮+虚+洪", "n": "洪大浮虚脉", "o": "洪大浮虚脉总主热盛而气津两伤之证。其脉洪大为热邪亢盛，浮虚为气伤无力，二者并见，示热盛于内而气津已耗。原文‘赤斑口燥、烦躁暑热’为暑热耗气伤津之典型，故脉虽洪大而按之无力。此脉所主，以热盛为本，气虚、津伤为标，三者相互关联：热盛为始动因素，热盛则伤气耗津，气津", "c": "主热盛"}, {"id": "c:大+洪+涩", "n": "洪大涩脉", "o": "洪大涩脉总起来主热盛、瘀滞及虚实夹杂。洪大主热盛气浮，涩主血行不畅、瘀滞，二者并见，多因热邪内蕴，灼血成瘀，或瘀热互结，气血不通。原文膈痛脉洪大而涩，先用清热行血之品痛止，是治其瘀热实证；后因劳倦忍饥痛大发，服二陈平胃等如刀割，知为虚，说明病机可由实转虚，形成", "c": "主热盛"}, {"id": "c:滑+大+洪+实", "n": "洪大滑实脉", "o": "洪大滑实脉总起来主邪盛正实、热郁交争之病机。其脉形洪大滑实有力，反映正气未虚而邪气亢盛，正邪交争激烈。具体而言，可因寒邪外束、热郁于内而见紧数洪滑；可因热邪炽盛、火盛躁甚而见洪大；可因热结阳明、腑气不通而见洪大滑实而便秘。诸类均以‘邪盛正实’为共同基础，热盛、", "c": "主邪盛正实"}, {"id": "c:数+滑+大+洪", "n": "洪大滑数脉", "o": "洪大滑数脉总起来主邪热亢盛，具体可归纳为暑热、痰热、胃热、湿热及一般邪热炽盛等类。洪大主阳明热盛，滑数主痰热或暑湿内蕴，故脉象多反映热邪与痰湿相搏之病机。各段原文中，或见疟疾暑热，或见痰热结胸，或见胃火呕吐，或见湿热挟痰，皆以洪大滑数为主脉，治多清解暑热、涤痰", "c": "主暑热"}, {"id": "c:大+洪+空+疾", "n": "洪大疾空脉", "o": "洪大疾空脉总起来主虚阳浮越、阴血亏耗之假热证。其脉象洪大躁疾而空，重按全无，为根本无根之象，非实火亢盛。原文通过舌象与脉象对比，指出“证有真假凭诸脉，脉有真假凭诸舌”，脉洪大躁疾而重按空豁，舌干燥焦黄而胖，说明热象为假，本质为阴血亏耗、阳气无根而浮越。三类病机", "c": "主虚阳浮越"}, {"id": "c:大+洪+疾", "n": "洪大疾脉", "o": "洪大疾脉总起来主邪热亢盛与虚阳浮越两类截然不同的病机。实热证中，洪大为热盛气壅，数疾为邪热急迫，可兼燥屎、风温、燥火、肝胃同病，甚则热灼阴伤、阴液耗竭，形成正虚邪盛之危候；癫疾脉中，洪大长疾又主风热痰火搏结，虚实夹杂。虚证中，洪大躁疾而空、重按全无，为阴血亏耗", "c": "主虚阳浮越"}, {"id": "c:大+洪+空", "n": "洪大空脉", "o": "洪大空脉总起来主虚阳浮越、阴血亏耗之假热证。其脉象洪大而中空，浮取无伦，沉取无根，为根本无根之象，非实火亢盛。所主病机主要有三类：一为虚阳浮越，阳气浮散于外而内里虚寒，见身热欲覆、面赤娇红、四肢厥冷；二为津枯液燥，邪热耗伤津液，气分热盛故脉洪，津亏不敛故中空，", "c": "主津枯液燥"}, {"id": "c:大+洪+紧+急", "n": "洪大紧急脉", "o": "洪大紧急脉总起来主实热、气血俱盛及肾病。原文以“脉数在腑”言热，以“脉大血气俱多”言气血充盛，又以“脉大而坚病在肾”言肾之病机。三类之间相互关联：实热可致气血涌盛而脉洪大紧急；气血俱盛则脉体充实而势急；肾主水藏精，脉大而坚紧亦反映肾实或肾气亢盛。总体而言，此脉", "c": "主实热"}, {"id": "c:大+洪+紧", "n": "洪大紧脉", "o": "洪大紧脉总以邪实热盛为主，兼涉气血壅实及痧毒内蕴。洪大主邪盛、气血涌盛，紧主热壅气急或寒束，合而多见实热亢盛、气血壅滞之证。原文'六脉洪大紧盛，热已极矣'点明其核心为热毒炽盛；兼见浮肿、血淋，则示热壅气滞、水湿不化，痧毒内蕴亦属此类。诸类之间相互关联：热盛可致", "c": "主热盛"}, {"id": "c:数+细+大+洪", "n": "洪大细数脉", "o": "洪大细数脉总起来主火盛与阴虚火旺两类病机。洪大脉主实火壅盛，细数脉主阴虚火旺，二者可并见或分见。原文强调“洪大脉主火盛，细数主阴虚火旺”，并以脉象细数与否辨别火盛是否伤阴及病位在心在肾。若脉洪大而不细数，则火盛未伤阴，病偏于心；若兼细数，则阴伤火旺，病涉于肾。", "c": "主火盛"}, {"id": "c:细+大+洪", "n": "洪大细脉", "o": "洪大细脉总起来主火盛与水衰火乘两类病机，并可反映金气将败的危候。洪大脉主火盛，火性炎上，气血壅盛，故脉来搏指；若兼见足少阴脉如烂绵，则为肾水衰少、水不制火，火乘金位，属本虚标实。火盛伤金，金气衰败，则洪大之脉可转为细弱如丝，提示预后不良。三类病机相互关联：火盛", "c": "主火盛"}, {"id": "c:大+洪+缓", "n": "洪大缓脉", "o": "洪大缓脉总主湿热内蕴，以洪大主热盛、缓主湿邪为纲。其病机核心为阳明热盛兼太阴湿阻，热蒸于里则见大渴大汗、身大热、谵语，湿阻于下则见足冷畏风；湿热壅于脾胃则见痞闷、食伤。诸类之间以湿热为纽带：阳明热盛为热之显，湿阻于下为湿之征，脾胃湿热为湿热交蒸之局部。脉无弦象", "c": "主湿热内蕴"}, {"id": "c:大+洪", "n": "洪大脉", "o": "洪大脉总起来主阳热亢盛、气血燔灼之象，但须分虚实。实热类包括阳明气分热盛、暑热炽盛、热毒内陷、湿热痰火、虫积等，脉多洪大有力，症见大热、大渴、汗出、烦躁、肿痛、癍疹等，治宜清热泻火、解毒化湿、杀虫消积。虚热类包括虚阳外浮、阴血亏虚、元气不足，脉多洪大无力或按之", "c": "主实热"}, {"id": "c:大+洪+芤", "n": "洪大芤脉", "o": "洪大芤脉总起来主热盛伤津、气阴两虚之证。洪大主热邪炽盛，芤主阴血津液耗伤，二者并见，多因热盛于外而阴伤于内，或汗下误治耗伤津液，或产后血虚阳浮、心气不固所致。其病机类别之间相互关联：热盛为始动因素，热盛则伤津，津伤则气阴不足，甚则虚阳浮越、心气不固。故临床可见", "c": "主热盛"}, {"id": "c:大+虚+洪+濡", "n": "洪大虚濡脉", "o": "洪大虚濡脉总起来主热盛伤津、气阴不足、湿热成痿之病机。洪大主热盛，虚濡主气阴亏虚，二者并见，提示热邪亢盛而气阴已伤，且兼湿阻。原文所载疟后过服热药，积火燔炽，消谷善饥，目昏足弱，肌肉虚肥，断为痿证，正是热盛伤津、湿阻成痿之典型。三类病机相互关联：热盛为因，气阴", "c": "主热盛"}, {"id": "c:大+虚+洪", "n": "洪大虚脉", "o": "洪大虚脉总起来主虚证与热证两类病机，以虚证为主。其核心特征是脉形洪大而按之虚软无力，甚至重按全无，此乃阴血亏虚、元气不足，阳无所附而浮越于外之象，故主血虚发热、元气亏损、阴亏阳浮等虚证，证似实热而实非热，误服白虎汤必死。若脉洪大而重按有力，或兼滑数，则为实热内", "c": "主血虚发热"}, {"id": "c:大+虚+洪+软", "n": "洪大虚软脉", "o": "洪大虚软脉总起来主气虚阳浮与脾肺不足，兼及妊娠血盛之滑象。原文前段脉甚滑按之不绝，为血盛养胎，故主孕；后段脉洪大按之虚软，洪大为气虚阳浮，虚软为脾肺不足，见气逆碍眠、嗽汗便溏遗溺、口渴不饥等症，属虚阳上浮、脾失健运。三类中，主孕为生理性血盛，与病理性虚软洪大不", "c": "主孕"}, {"id": "c:大+洪+长+疾", "n": "洪大长疾脉", "o": "洪大长疾脉在五癫诊脉中总属癫疾之脉，其病机以风热痰火搏结、心气不足、肾虚骨癫及病势危重为主。原文列洪大长、浮大附阴、牢疾皆癫，紧疾主风邪急搏，说明风热痰火内扰是核心病机；心脉微涩主心气不足、血涩不荣，提示虚实夹杂；肾急甚为骨癫，反映肾虚风入；脉搏大滑生，沉小急", "c": "主风热痰火"}, {"id": "c:大+洪+长", "n": "洪大长脉", "o": "洪大长脉总起来主阳气亢盛、气血涌盛之象，其病机有常有变。常者为四时平脉，应夏月火令或太阳之气，脉随节气而洪大长，非病脉。变者则分虚实：有力为实热，热盛于阳明或心火亢盛，气血充盈脉道；无力为血虚阳浮，阴血不足，阳气外浮，脉虽洪大而重按无力；亦有风阳上盛，血气虚而", "c": "主实热"}, {"id": "c:数+弦+洪+实", "n": "洪实弦数脉", "o": "洪实弦数脉总起来主热邪壅实、表里俱热之证。洪为热盛，实为邪实，弦主少阳郁热，数主热，四脉相合，提示热邪炽盛且与实邪相结，病位涉及少阳与阳明，表里同病。其核心病机为热盛邪实，可具体分为热盛、邪实、少阳郁热、表里俱热四类，彼此关联：热盛与邪实是基础，少阳郁热指明病", "c": "主热盛"}, {"id": "c:弦+洪+实+硬", "n": "洪实弦硬脉", "o": "洪实弦硬脉在此段中总主肝胃不和、木乘土位之病机。其脉右部弦硬异常，按之甚实，非洪实之象，乃因外感伏邪化热入胃，胃土受肝木乘春令之旺而侮克，故脉从肝木之化而现弦硬。三类病机相互关联：邪热内蕴为始因，胃府受病为病位，肝木乘土为病机关键。热蕴于胃，木旺克土，胃失和降", "c": "主肝木乘土"}, {"id": "c:数+滑+洪+实", "n": "洪实滑数脉", "o": "洪实滑数脉总属邪盛脉实，主实热、痰火、毒壅之证。洪为热盛，实为邪壅，滑为痰湿，数为热急，四脉相合，反映邪气壅盛、热毒痰火内结之病机。所主病机可归纳为实热壅盛、痰火内结、大实之证三类，三者相互关联：实热壅盛可炼液成痰，痰火内结又加重腑气不通，终致内外俱壅之大实证", "c": "主实热壅盛"}, {"id": "c:洪+实", "n": "洪实脉", "o": "洪实脉总属阳热实证，以“洪主热盛，实主邪实”为纲。其核心病机为实热内盛，可具体化为阳明腑实、热毒壅盛、积滞闭结、心火亢盛、脑充血及疟疾热盛等。各证虽表现不同，但均因热邪亢盛、正气未衰，气血涌盛而脉道充盈，故脉来洪实有力。其中阳明腑实与热毒壅盛最为常见，积滞闭结", "c": "主实热"}, {"id": "c:数+洪+弱", "n": "洪弱数脉", "o": "洪弱数脉总起来主热毒炽盛兼正气不足、毒邪内陷之病机。洪数主热毒壅盛，弱主正气亏虚，歇止主毒陷少阴、心气不续。三者并见，反映热毒炽盛而正气已伤，毒邪有内陷少阴之势，属正虚邪陷之危候。治疗当急顾阳明，清热凉血、扶正解毒，使邪退正复，则洪数减、歇止缓。", "c": "主热毒"}, {"id": "c:数+微+洪", "n": "洪微数脉", "o": "洪微数脉总起来主热盛与阳明腑实，并因热盛而致气机上逆。洪数为热盛之象，右部实而有力更确指阳明里实热结；热邪盘据阳明，逼迫胃气上逆，并肺气上逆，故见咳喘呕血。三类病机以热盛为核心，腑实为热结之甚，气逆为热盛所致之变，彼此关联，共同反映外感温病邪热内盛、正邪交争而", "c": "主热盛"}, {"id": "c:洪+急", "n": "洪急脉", "o": "洪急脉总起来主热盛、毒壅、热陷厥阴及虚风内动。洪为热盛，气血涌盛；急为邪迫，或毒气壅滞，或阴亏阳亢。实热证中，洪急主热毒炽盛、壅滞经脉；若兼数躁，则热盛伤阴，热陷厥阴，虚风内动；若洪大而急，则真元耗损、液络大亏，阴不制阳，虚风内动。各类之间，实热与虚风可相互转", "c": "主热盛"}, {"id": "c:洪+散+乱", "n": "洪散乱脉", "o": "洪散乱脉总属虚寒阳浮之危候。其脉洪大无伦，重取即散，洪大非实热，乃阴寒内盛、虚阳外越所致；散为里气虚寒，阳气无根。三者相互关联：虚寒为本，阳浮为标，霍乱为诱因与表现。此脉主寒霍乱吐泻大汗后，里气暴虚，阴寒内盛，逼阳外浮，故见脉洪散、面赤戴阳、腹胀如石等症。切不", "c": "主虚寒"}, {"id": "c:洪+散", "n": "洪散脉", "o": "洪散脉总属虚寒阳浮、正虚邪实之危候。其脉洪大无伦，重取即散，洪非实热，乃阴寒内盛、虚阳外越；散为里气虚寒，阳气无根。各类病机相互关联：虚寒为本，阳浮为标，气散为果。洪散乱脉主寒霍乱吐泻后里气暴虚、阴寒逼阳外浮；洪滑散脉主血虚有表无里或疮毒脓溃后正虚邪恋；洪数散", "c": "主阳浮"}, {"id": "c:数+洪+促", "n": "洪数促脉", "o": "洪数促脉总起来主热盛急迫之证。洪为阳明热盛，数为热炽，促为热盛急迫、脉行急促而时一止。三者相合，反映热邪鸱张，有燎原之势，常见壮热大汗、面赤、口渴、烦躁、鼻衄等症。此脉所主病机以热盛为核心，热盛则脉洪，热炽则脉数，热急迫则脉促，故洪数促脉主热盛急迫，非一般热证", "c": "主热盛"}, {"id": "c:数+洪+实", "n": "洪数实脉", "o": "洪数实脉总属邪热亢盛、邪气壅实之象。洪主热盛，数主热急，实主邪结，三者相合，突出热邪炽盛、正气未衰、邪正剧争之病机。其所主涵盖热盛、邪实、热毒壅盛、阳明腑实、木火亢盛、疟疾热盛及阳浮阴闭等，皆以热实为共同基础。热盛为病之本，邪实为病之果，热毒壅盛、阳明腑实、木", "c": "主热毒壅盛"}, {"id": "c:数+洪+平", "n": "洪数平脉", "o": "洪数平脉总属火热亢盛、气机壅实之象。洪为热盛气分，数为热迫急疾，合而主实热、毒蕴、气盛。原文一诊见脓水淋漓、小溲畅、面赤火升、痛势减，左脉洪数较前日平和，说明毒从外泄、火从下降、升降各司其职，气盛上下咸宜，属补托见效之佳兆。三类病机相互关联：火热为根本，毒蕴为", "c": "主火热"}, {"id": "c:数+弦+洪+急", "n": "洪数弦急脉", "o": "洪数弦急脉总起来主阳热亢盛、木火内动、邪结于内，并进而导致阴精亏耗、精血耗散。洪数主阳热有余，弦急主木火亢盛，紧主邪结，三者相合，反映邪热内盛、木火亢盛之实。然实热久羁，必伤阴精，原文所谓'阳精不升''阳络不固'，致失精吐红，先后天俱病，即由实转虚、阴亏阳亢之", "c": "主阳热亢盛"}, {"id": "c:数+洪+急", "n": "洪数急脉", "o": "洪数急脉总起来主阳热亢盛、阴亏阳亢，并可热中厥阴。洪主热盛，数主热，躁急主阴亏阳亢，三者相合，反映邪热内盛、阴液亏耗、孤阳外越之病机。原文暑疟后昏厥抽搐、身热烦躁，脉洪数躁急，乃热盛伤阴，热陷厥阴。洪数为阳热有余之实，躁急为阴亏阳亢之虚，实热与阴亏并存，故脉象", "c": "主热盛"}, {"id": "c:数+洪+散", "n": "洪数散脉", "o": "洪数散脉在疮疽辨证中总属邪热壅盛而正气涣散之候。洪数主热毒炽盛，粗散主气血耗散，二者相合，形成邪实正虚的复杂病机。原文以“脓溃后烦疼不除，脉洪数粗散者，为热毒未清而气血已散”为据，说明此脉既反映热毒未清之邪实，又揭示气血已散之正虚，故属难痊之象。三类病机相互关", "c": "主热毒壅盛"}, {"id": "c:数+沉+浮+洪", "n": "洪数浮沉脉", "o": "洪数浮沉脉总起来主实热壅盛、湿热疫毒及邪实壅结。洪数主热毒内蕴，浮沉有力示邪气盛实，非虚象。原文中此脉见于喉证初起，身如被杖、寒热如疟、发闷极重，反映湿热疫毒纵贯三阳，邪实壅结。三类病机相互关联：实热壅盛为基本病理，湿热疫毒为具体病因，邪实壅结为脉象本质。虽原", "c": "主实热壅盛"}, {"id": "c:数+虚+微+洪+涩", "n": "洪数涩微虚脉", "o": "洪数涩微虚脉总主病机为实热、虚损及痹证。洪数主实热壅盛，多见于五疸等湿热内蕴之证；涩微主虚损，示正气衰败、津血不足；浮涩而紧三脉并见则主风寒湿痹。三类病机中，洪数与涩微相对，一实一虚，反映邪盛与正衰的不同病理状态；而痹证之浮涩紧则属风寒湿杂至、邪阻经络之候。诸", "c": "主痹证"}, {"id": "c:数+洪+紧", "n": "洪数紧脉", "o": "洪数紧脉总起来主热盛邪实、表里俱病之证。洪脉主热盛，数脉主热，紧脉主邪实壅结，三脉相合，反映热邪亢盛而兼邪气壅滞，病位可在表里之间。原文'六脉洪数而紧'伴面赤身热、舌黄燥渴、便闭溺短，通体似火证，然只有当脐痛拒按，断为'阳中之阴，乃为真阴'，说明热象虽盛而里有", "c": "主热盛"}, {"id": "c:数+洪+缓", "n": "洪数缓脉", "o": "洪数缓脉总起来主湿热为患，以热为主，湿为兼夹。洪数主热盛，缓主湿邪，二者相合，反映热邪亢盛而湿邪未化，湿热交蒸之病机。原文中'洪数较缓'示壮热之势大减，伏温渐解，但胸闷泛恶、苔腻黄渐化，蕴湿犹留中焦，说明热势虽减而湿邪未清，脉仍数而缓，为湿热未清、气分余邪未净", "c": "主热"}, {"id": "c:数+洪", "n": "洪数脉", "o": "洪数脉总以热盛为核心病机，洪为热盛气分、脉道宽大，数为热急、邪热亢盛。其主病广泛，可归纳为实热、热毒、湿热、痰火、虚火、脓成及肝火风动等类。实热为共同基础，多见于阳明气分、温病、疫毒；热毒壅盛则见于疮疡痈疽、喉痛肠痈；湿热、痰火为热与湿痰相合，壅滞三焦；虚火则", "c": "主热盛"}, {"id": "c:数+洪+芤", "n": "洪数芤脉", "o": "洪数芤脉总起来主热盛阴伤、正虚邪恋之病机。洪数主热邪炽盛，芤主阴血不足或中虚血少，故脉象多反映热盛与阴伤并存、虚实夹杂之证。所主病机主要有四类：热盛、阴伤、瘀滞、正虚邪恋。热盛与阴伤常相兼为患，如暑热炽盛灼伤阴津；瘀滞则因肝络瘀阻，血不归经，日久阴阳两伤；正虚", "c": "主热盛"}, {"id": "c:数+虚+洪", "n": "洪数虚脉", "o": "洪数虚脉总起来主正气已虚而邪热内扰之候。其脉洪数为阳热之象，虚为不足，合而观之，非实火亢盛，乃虚阳外浮、真阴亏虚，或郁火内灼、暑热弥漫。所主病机可归纳为虚火、虚损、郁火、暑热、疟、痰六类：虚损为根本，因劳倦、入房、饥寒等致正气先亏；虚火由阴亏而生，内动为患，上", "c": "主虚火"}, {"id": "c:数+洪+实+长", "n": "洪数长实脉", "o": "洪数长实脉总起来主热盛、里实与疟疾。洪数为热，长实为邪气壅盛，合而示热邪亢盛、邪实内结之象。原文在疟疾脉象列举中，以此脉与浮脉（表）、沉实脉（里实）、细缓芤微脉（虚）对举，明确其主热盛。该脉所主三类病机相互关联：热盛为因，里实为邪结之果，疟疾为具体病证载体。热", "c": "主热盛"}, {"id": "c:沉+浮+微+洪+涩+小", "n": "洪浮沉微涩小脉", "o": "洪浮沉微涩小脉在原文中作为复合脉象出现，主要围绕暑、湿、伤寒等外感病证的脉证相应关系展开。洪浮主伤寒热病之顺脉，因热盛气血外涌；虚脉主暑伤气，因暑热耗气；缓细涩主湿伤血，因湿阻血滞；沉微涩小则主阳病见阴脉之逆证，提示正虚邪陷、预后凶险。诸类脉象虽异，但总以脉证", "c": "主热病顺脉"}, {"id": "c:洪+涩", "n": "洪涩脉", "o": "洪涩脉总起来主寒热错杂、气血壅滞、瘀热互结及虚实夹杂。洪脉主热盛气浮，涩脉主血行不畅、瘀滞，二者并见，多因热邪内蕴，灼血成瘀，或寒热相搏，气血不通。原文左寸忽洪忽涩、迟数无定，因冷酒寒热相搏致腿疼筋缩，示寒热错杂、气血壅滞；膈痛脉洪大而涩，先清热行血痛止，后因", "c": "主寒热错杂"}, {"id": "c:滑+大+洪", "n": "洪滑大脉", "o": "洪滑大脉总起来主热盛、痰湿、痰火及湿热等病机，其核心为邪热亢盛与痰湿相搏。洪大主热盛与阳盛气浮，滑主痰湿，大主邪实，故脉象多反映热邪与痰湿交结之候。具体而言，或为湿热下注、壅于阳明而致痿躄；或为痰火有余、循经上扰而见鼻衄、瘰疬；或为表里热盛、邪实正未虚之证；亦", "c": "主湿热"}, {"id": "c:滑+洪+实", "n": "洪滑实脉", "o": "洪滑实脉总属邪盛正实、热痰壅结之候。洪为热盛，滑为痰湿，实为邪壅，三象相合，反映邪气亢盛而正气未虚，正邪交争激烈。所主病机可归纳为实热壅盛、痰热内结、胃热上逆、热毒弥漫、疟疾痰热、阳明腑实、肝郁热激七类。其中实热壅盛为基本病机，痰热内结、胃热上逆、热毒弥漫、疟", "c": "主痰热内结"}, {"id": "c:滑+洪+小", "n": "洪滑小脉", "o": "洪滑小脉在此段中主要反映湿热壅盛、下焦气化不利之病机。洪为热盛，滑为湿聚，湿热内蕴下焦，阻滞气化，故见小水不通；湿无出路，郁于腰部，则腰痛由是而作。三者相互关联：湿热壅盛是病本，气化不利是病机关键，腰痛是外候。原文以脉洪滑与小便不通并见，断为湿热实证，治用大分", "c": "主湿热壅盛"}, {"id": "c:弦+滑+洪+硬", "n": "洪滑弦硬脉", "o": "洪滑弦硬脉总属虚实夹杂之候，以火盛阴亏为核心病机。其脉失洪滑之和柔而现弦硬，或弦硬而长，反映阴分亏虚、阳热亢盛，脉道失于濡润而刚劲。所主病机主要有四：火盛阴亏为根本，气血两亏为正气虚损之变，冲气上逆为阴亏肝胃气逆之标，阴虚水亏为肾阴不足、水液失调之果。四者相互", "c": "主火盛阴亏"}, {"id": "c:滑+浮+微+洪", "n": "洪滑微浮脉", "o": "洪滑微浮脉总属热邪为患，以里热壅盛为核心，兼表邪未解。洪滑主里热炽盛，热邪内传阳明、壅阻膀胱，致水热互结，故见小便涩热、周身悉肿；热盛灼津为痰，痰热上泛，则痰涎上泛、微兼喘息；微浮示热邪尚连表分，表证未罢。四类病机相互关联：里热壅盛是根本，水热互结、痰热上泛为", "c": "主里热壅盛"}, {"id": "c:滑+洪+散", "n": "洪滑散脉", "o": "洪滑散脉总属正虚邪实、预后多不良之脉。其核心病机为血虚有表无里，阴血亏虚不能内守，故脉浮散不敛；若见于疮毒脓溃之后，洪滑粗散而烦痛不除，则为正气虚而邪气实，正虚邪恋，故为难治；若肢体沉重而肺脉大，浮散无根，则示脏气将绝，主毙。三类病机相互关联：血虚为散脉之基础", "c": "主血虚"}, {"id": "c:数+滑+洪", "n": "洪滑数脉", "o": "洪滑数脉总起来主邪热亢盛，兼挟痰湿或瘀血。洪为阳明热盛、气血涌盛，数为邪热炽盛，滑主痰湿或瘀血内壅，三脉相合，反映热邪与痰湿、瘀血相搏之病机。具体而言，或主痰热壅盛于胸膈、经络，或主暑热湿痰内蕴，或主阳明气分热炽，或主湿热蕴结下焦，或主痰火扰神，或主热入血室、", "c": "主痰热壅盛"}, {"id": "c:滑+沉+洪", "n": "洪滑沉脉", "o": "洪滑沉脉总起来主里实邪盛、水饮内停之证。洪滑为邪气壅盛、气血鼓动之象，沉则示病位在里，二者相合，说明实邪结聚于里而非在表。从所附沉数洪滑脉的总述看，沉主里、数主热、洪滑主邪实气血壅盛，四者相合反映邪热内结、实邪壅盛于里；而本段“饮家眩冒，脉洪滑而沉”则具体落实", "c": "主饮邪内盛"}, {"id": "c:滑+浮+洪", "n": "洪滑浮脉", "o": "洪滑浮脉总主热盛邪实，以里热壅盛为核心，兼表邪未解。洪为热盛燔灼，滑为痰热内蕴，浮为热势趋表或表邪外束。其病机类别包括里热壅盛、表邪未解、痰热壅肺及热盛动血，四者相互关联：里热炽盛是根本，表邪未解为兼夹，痰热壅肺为热灼津液所生，热盛动血为热伤血络所致。原文诸案", "c": "主里热壅盛"}, {"id": "c:数+滑+洪+疾", "n": "洪滑疾数脉", "o": "洪滑疾数脉在痧证中主要主暑热、痧毒及湿热壅盛三类病机。洪为热盛，滑为湿滞，疾数为热急，四象合见，总以暑热内蕴、痧毒扰攘、湿热交蒸为核心。原文仅列伤暑之痧脉多洪滑疾数，然痧证脉与诸证不同，杂证兼痧其脉必变，病必凶暴，故该脉亦反映痧毒内盛、气血壅滞之共性。三类之间", "c": "主暑热"}, {"id": "c:滑+洪", "n": "洪滑脉", "o": "洪滑脉总起来主邪热亢盛，兼挟痰湿、积滞或血壅。洪为热盛，气血涌盛；滑为痰湿、食积或血瘀内壅，二脉相合，反映实热与有形之邪相搏之病机。其类别虽多，然核心皆不离‘热’与‘实’：热盛于阳明气分则见大热渴汗；痰热互结则胸闷咳喘；湿热交蒸则发黄溺赤；实积内阻则腹胀痛；热", "c": "主热盛"}, {"id": "c:滑+洪+长", "n": "洪滑长脉", "o": "洪滑长脉总起来主实热炽盛、气机壅盛之病机。洪为热盛，滑主痰热内壅，长则气分热炽、气火有余，重按有力更证实热内结。各类之间相互关联：实热炽盛可致气逆血溢，见吐血、衄血；热郁气壅则因外感束缚，内热不得发泄；火毒炽盛盘踞阳明，则见壅肿溃烂、腑实便结；痰热内壅上扰神明", "c": "主实热"}, {"id": "c:洪+疾", "n": "洪疾脉", "o": "洪疾脉总起来主邪热亢盛与虚阳浮越两类截然不同的病机，并可兼夹风热痰火及郁火气血虚等复杂情况。实热证中，洪为热盛气壅，疾为邪热急迫，可致躁烦，甚则热灼阴伤、阴液耗竭，形成正虚邪盛之危候；癫疾脉中洪大长疾又主风热痰火搏结，虚实夹杂。虚证中，洪大躁疾而空主虚阳浮越；", "c": "主热盛烦躁"}, {"id": "c:洪+空", "n": "洪空脉", "o": "洪空脉总起来主真阴枯涸、虚阳浮越之危候。其脉洪大而中空，非实火亢盛，乃阴精竭于内、阳气浮于外之象。所主病机主要有三：一为真阴枯涸，阴液耗竭则脉道空虚而洪大；二为心火自焚，阴亏火旺、火性疾速，故见暴病昏聩等症；三为虚阳浮越，阴不敛阳则阳气外脱，见自汗、遗溲等脱象", "c": "主真阴枯涸"}, {"id": "c:弦+洪+紧", "n": "洪紧弦脉", "o": "洪紧弦脉总起来主风热外郁、邪结血脉、阳热怫郁之证。洪脉为阳热盛，紧脉为邪气结聚，弦脉为风动，三者相合，反映风热之邪外郁肌表，客于血脉之上、皮肤之间，导致营卫不通，阳热怫郁在经。其典型证候为多怒、色赤、肿高结硬而痛，多见于疮疡初起。治疗宜发汗通营卫，使邪从表解，", "c": "主风热外郁"}, {"id": "c:洪+紧", "n": "洪紧脉", "o": "洪紧脉总起来主火盛邪结、热毒壅盛之证。洪为火盛，紧为邪结，二者相合，反映火热内盛而兼邪气结聚，气血壅滞不通。所主病机主要有三类：一为火盛，火热内盛则脉洪；二为邪结，邪气壅滞则脉紧；三为热毒壅盛，洪紧并见，热毒炽盛，气血壅滞，常见于疔毒肿痛等证。三类之间相互关联", "c": "主火盛"}, {"id": "c:洪+濡+缓", "n": "洪缓濡脉", "o": "洪缓濡脉总主热毒壅聚、湿滞营卫不利之疮疡，尤以痈肿浅表、热毒尚浅为特点。洪为热盛，缓为营卫不利，濡主湿滞，三脉合见，示热毒与湿邪相合，壅滞太阳经分，气血运行失畅，但未至大伤。原文以痈肿如碗、皮肉不变、按之不甚痛、微发寒热为据，断为尚可治之证，治以托里透邪、微汗", "c": "主热盛"}, {"id": "c:洪+缓", "n": "洪缓脉", "o": "洪缓脉总以洪主热盛、缓主湿滞为纲，所主病机以湿热为核心，兼及湿郁、脾虚火乘、气虚阳浮与热毒湿滞。诸类之间，湿热为最常见者，或外感长夏暑湿，或内伤脾经湿热，皆洪缓并见；湿郁则湿邪偏重，郁阻气机，脉洪缓而重按若牢；脾虚火乘与气虚阳浮则属虚证，脉虽洪缓而无力，为土虚", "c": "主湿热"}, {"id": "e:洪", "n": "洪脉", "o": "洪脉总属阳热亢盛、气血涌盛之象，其核心病机为热盛，但须分虚实表里。实热类包括阳明气分热盛、热毒壅盛、湿热交蒸、痰火内扰、肝火风动等，脉多洪而有力，症见大热、大渴、汗出、烦躁、肿痛、出血等，治宜清热泻火、解毒化湿、消痰平肝。虚火类则因阴血亏虚、阳无所附，或津气两", "c": "主实热"}, {"id": "c:洪+芤", "n": "洪芤脉", "o": "洪芤脉总起来主热盛伤津、气阴两虚及虚阳外浮之病机。洪脉主热邪炽盛、气血涌盛，为始动因素；热盛则灼伤津液，阴血耗损，脉道不充而见芤象，故洪芤并见多示热盛与阴伤并存。若热盛日久或误治汗下，耗气伤津，则成气阴两虚，甚则虚阳外浮，脉洪芤而见危候。各类病机相互关联：热盛", "c": "主气阴两虚"}, {"id": "c:洪+弱+软", "n": "洪软弱脉", "o": "洪软弱脉总主气分热盛与气阴两伤并见之候。洪为热盛于气分，软弱为气阴不足，二者相合，多见于热邪久羁、耗气伤阴，或失血日久、气随血脱之证。原文痔疾下血案中，燥令致便结痔发，下血日久，气阴两伤，虚阳浮越，故脉洪大而软，甚则脉如蛛丝。三类病机相互关联：热盛为始动因素，", "c": "主气分热盛"}, {"id": "c:洪+软", "n": "洪软脉", "o": "洪软脉总起来主气分热盛与气阴两伤并见之候，或阴阳并虚、虚风鼓动之证。洪为气浮于外或热盛于气分，软则中候无力，为气阴不足或阴阳并虚。二者相合，非实热之洪，乃虚阳浮越、虚风内动之象。三类病机相互关联：阴阳并虚为根本，虚风鼓动为变证，气阴两伤为常见转归。多见于热邪久", "c": "主阴阳并虚"}, {"id": "c:洪+迟", "n": "洪迟脉", "o": "洪迟脉在本段中仅见于“季夏脉洪而迟”，与秋脉微浮而散、冬脉沉滑而实并列，三者皆四时平脉，非病脉。因此，洪迟脉所主病机实为时令常脉，即长夏湿土、脾气温厚之应时脉象，而非病理表现。原文以季节气化解释脉象，洪应长夏湿土、脾气温厚，迟应湿性濡缓，故洪而迟为季夏平脉。下", "c": ""}, {"id": "c:洪+长+坚+硬", "n": "洪长坚硬脉", "o": "洪长坚硬脉总属阳热亢盛之候。其脉洪大搏指、七至，为热邪炽盛、充斥三焦之象。所主病机以热盛为核心，可具体分为阳明热炽、少阳热盛及春温阳症三类。三者相互关联：少阳热盛见左脉弦大，阳明热炽见右脉洪大，合而则为春温阳症之热邪弥漫三焦。原文虽见房事后腹痛水泻似阴症，但脉", "c": "主热盛"}, {"id": "c:洪+实+长", "n": "洪长实脉", "o": "洪长实脉总起来主热盛、邪实与阳明实热。洪脉主热盛，长脉主热炽气分，实脉主邪实，三者相合，反映热邪亢盛、邪实内结、气分热炽的病理状态。原文以目疾为例，因伏寒化热，热邪上攻，出现眼睑红肿、胬肉遮睛、耳聋鼻塞等症，脉见洪长甚实，左右皆然，断为阳明实热。各类病机相互关", "c": "主热盛"}, {"id": "c:数+洪+长", "n": "洪长数脉", "o": "洪长数脉总起来主热盛、邪实，多见于阳明热盛及疫毒壅盛之证。洪为热盛，数为热急，长主邪气有余，三脉相合，示热邪亢盛、邪实内结。所主病机中，热盛为因，邪实为果，二者常相互关联；阳明热盛为常见病位，疫毒为特殊病因。各段原文均以洪长数脉与高热、烦渴、红肿、谵语等热实证", "c": "主热盛"}, {"id": "c:洪+长", "n": "洪长脉", "o": "洪长脉总起来主阳气亢盛、气血涌盛之象，其病机有常有变。常者为四时平脉，应夏月火令或太阳之气，非病脉。变者以实热为主，尤多阳明实热，热盛于经或入腑，气血充盈脉道，故洪长有力；亦有伏气化热、热郁经络而痛者；若热盛伤阴，则洪长而重按欠实；肝火挟气血上冲脑部，则左部洪", "c": "主阳明实热"}, {"id": "c:浮+伏", "n": "浮伏脉", "o": "浮伏脉总起来主气机壅塞、闭阻不通之病机。其脉象上浮下伏，反映邪阻中焦、升降失司，阴阳不相顺接；紧伏、沉伏则示气闭较甚，气机收引郁闭；若郁久化热，则脉转沉数。三类病机相互关联：邪阻中焦为始动因素，导致气机壅塞而见紧伏、沉伏，气闭日久又可郁而化热。此脉所主重在气分", "c": "主气闭"}, {"id": "c:数+浮+促", "n": "浮促数脉", "o": "浮促数脉总起来主燥热为病，多与肺脏相关。其脉象浮、促、数并见，浮主邪在表或燥气外袭，促数主热盛或热迫气急。所主病机主要有三类：一是燥热伤肺，肺阴久伤又兼燥气加临，症见咳嗽失血、音烁咽干；二是表邪未解，燥气外袭而表证未罢，见寒热头痛喉疼；三是热盛燔灼，燥热内盛，", "c": "主燥热伤肺"}, {"id": "c:浮+促", "n": "浮促脉", "o": "浮促脉总起来主气机郁结与热邪为患，病位多偏于上、在表。其基本脉象浮主邪在表或气逆于上，促主气结势急或热迫急数。所主病机可归纳为气逆、热郁、燥热、热盛、气结五类。气逆者，气机上逆，如胆府倒置；热郁者，热邪怫郁，欲出未透；燥热者，燥伤肺阴或表邪未解；热盛者，热邪炽", "c": "主气逆"}, {"id": "c:数+浮+动", "n": "浮动数脉", "o": "浮动数脉总起来主风、热、虚、痛及阳动不宁之病机。浮为风、为虚阳上浮；数为热、为虚；动为痛、为阳动、为阴阳相搏。其证候谱较广：在外感病中，主太阳表邪未解、风热袭表，症见头痛发热、恶寒盗汗；若误下则热陷成结胸，或湿热郁蒸发黄。在内伤病中，主肝肾阴亏、水不涵木、肝风", "c": "主虚阳上浮"}, {"id": "r:浮取", "n": "浮取", "o": "浮取脉象所主病机广泛，总以正气盛衰与邪气性质为纲。其核心在于脉气浮越于外或浮取反应异常：虚证见浮取无力、濡弱、空豁，为气血阴阳不足；热证见浮取数、洪、滑，为热邪鼓动；痰湿证见浮取滑、濡、弦，为痰湿黏滞；风证见浮取弦、浮缓，为风性轻扬；气陷气郁见浮取不足、伏牢、", "c": "主虚（气血阴阳亏虚）"}, {"id": "rs:浮取+伏", "n": "浮取·伏脉", "o": "伏脉总属沉脉之极，其象深伏筋骨，重按不见，必推筋至骨乃得。所主病机以里、以阴、以闭为纲。其一，阴寒内盛，阳气深伏，脉气沉潜不出；其二，气血痰食积聚内结，脉道阻滞，故沉伏难显；其三，痛极气闭，气机逆乱，脉气一时伏藏；其四，久病阳衰，无力鼓脉，亦见沉伏。四类之中，", "c": "主沉寒痼冷"}, {"id": "rs:浮取+动", "n": "浮取·动脉", "o": "浮取·动脉总起来主虚风内动、痰瘀互结、气机逆乱、水饮内停等病机。其脉象特征为举之有余、按之不足，或机神荡动、按之似滑、举之和缓，或按之有力、举之似涩。这些病机多与中焦脾胃相关，虚风内动因阳气不藏，痰瘀互结因邪实内结，气机逆乱因升降失常，水饮内停因痰饮搏结。各类", "c": "主虚风内动"}, {"id": "rs:浮取+和", "n": "浮取·和脉", "o": "浮取和脉总以虚为本，兼见热、痰、阴阳错杂。其脉轻取微数、动软或滑大，重按则无或细弱，反映正气已馁、阴血亏虚，故主虚；数而无力、弦数上溢为热邪伤阴或肝阳上亢，故主热；滑大软滑为痰热内蕴，故主痰；而数软与细弱并见、寸动尺无，则示寒热错杂、阴阳不相顺接。诸类以虚为根", "c": "主虚"}, {"id": "rs:浮取+大", "n": "浮取·大脉", "o": "浮取大脉总以“大而无力”为辨，主虚证居多，尤以气虚、血虚、气血两虚及虚寒为核心。大而无力为气虚之确据，气虚不能摄血则崩，麻属气虚；血虚脉大如葱管，故大而软亦主血虚；气血俱虚则脉豁大而浮中沉无力，甚则虚寒内生。若大而兼弦浮，则夹风邪，为虚中夹实之标。另从脉学纲领", "c": "主气虚"}, {"id": "rc:浮取+弦+浮", "n": "浮取·弦浮脉", "o": "浮取弦脉总属气机郁滞、筋脉拘急之象，其病机涉及肝郁络瘀、痛证、痰饮、风邪在表、湿热内盛及血虚失血等多类。弦为肝之主脉，主气郁、主痛、主痰饮；浮取则示病位偏表或络脉，常与风邪、湿热相合。各段原文显示，浮弦可单独出现，如血虚风入；亦可兼见沉洪、芤等，如肝郁络瘀兼血", "c": "主肝郁络瘀"}, {"id": "rs:浮取+弦", "n": "浮取·弦脉", "o": "浮取弦脉总起来主气机郁滞、筋脉拘急，其病机涉及风邪在表、气虚阳衰、肝火犯肺及气郁筋急等多类。弦为肝之主脉，主气郁、主痛、主痰饮；浮取则示病位偏表或络脉，常与风邪、湿热相合。各段原文显示，浮弦可单独出现，如左脉举之略弦似有风邪；亦可兼见他脉，如左弦无力而右浮取有", "c": "主风邪"}, {"id": "rc:浮取+微+弱", "n": "浮取·微弱脉", "o": "浮取微弱脉总属虚象，然其兼见之脉与部位不同，所主病机亦异。其一为气虚下陷，脉微弱异常，大气不能包举肺脏，故咳喘、四肢无力；其二为肾阴亏虚、壮火食气，平时六脉微弱，病时左手弦大而坚，乃阴亏阳亢、虚火内炽；其三为痰壅膈上，右手浮缓、气口微滑，痰沫壅塞，侵及心主。三", "c": "主气虚下陷"}, {"id": "rs:浮取+微", "n": "浮取·微脉", "o": "浮取微脉总属虚象，其核心病机为气血不足、阳气衰微，脉来浮软无力，按之不足。然虚有轻重兼夹之异：轻者仅气血两虚、中阳不振；重者根本动摇、神气浮散，脉见寸盛尺微、忽有忽无。若虚中夹实，则兼脉不同而病机有别，如气虚下陷、阴亏火旺、痰壅气口等。此外，浮微脉形本身为诸虚", "c": "主气血两虚"}, {"id": "rs:浮取+散", "n": "浮取·散脉", "o": "散脉总属正气涣散、根本欲脱之象。其脉浮取涣漫不收，有边无中，按之无根，为虚极之候。所主病机主要有三：一为气衰，大气不能包固，如堤薄水漏；二为血失统摄，气不摄血而致出血；三为虚极，气血阴阳耗散。三者相互关联，气衰则血失统摄，血失统摄则进一步耗伤正气，终致虚极。散", "c": "主气衰"}, {"id": "rs:浮取+数", "n": "浮取·数脉", "o": "浮取·数脉总以主热为纲，然热有虚实浅深之异。其常见者，一为实热亢盛，脉数有力；二为阴虚内热，数而按之不足；三为火郁于内，数而兼伏、牢、细弦，浮取不应；四为热盛阴竭，数大而空；五为伏热内结，沉取有余。诸类皆以数脉为热象之共征，但兼脉与浮沉取象不同，提示病机有热盛", "c": "主热"}, {"id": "rs:浮取+沉", "n": "浮取·沉脉", "o": "沉脉总属里证，以“举之不足，按之有余”为基本特征，法地近筋骨，主病位在里。其病机以里实与里虚为两大纲：沉而有力主里实，如积滞内结、牢实内盛；沉而无力主里虚，如阳气衰微、气血不足。若沉极则为伏，主邪伏深结；沉兼牢实弦长，主阴寒内实、癥瘕积聚。诸类皆以沉取有力无力", "c": "主里实积滞"}, {"id": "rs:浮取+浮", "n": "浮取·浮脉", "o": "浮脉总属阳气浮越于外、病位偏表或正气不足之象。其核心特征为举之有余、按之不足，法天应皮毛。所主病机可归为虚实两端：虚者如中气虚、阴不足、气血两虚、失血，因正气亏虚，阳气不能内守而浮越，故脉浮而无力或芤；实者如外感风暑、表热、宿食胀满、狂躁，因邪气在表或气机壅滞", "c": "主虚"}, {"id": "rc:浮取+缓+迟", "n": "浮取·缓迟脉", "o": "浮取·缓迟脉在此案中总主暑湿内伏、燥矢在胃、气机不利之证。脉迟缓而浮取甚微，貌似虚寒，实为湿遏热伏、腑气壅滞、脉道不利所致。暑湿内伏则湿胜热伏，故脉不数而迟缓；燥矢在胃则腑气不通，机关不利，脉道壅滞；气机不利则脉来迟缓微弱。三者相互关联：暑湿内伏为病之本，燥矢", "c": "主暑湿内伏"}, {"id": "rs:浮取+虚", "n": "浮取·虚脉", "o": "浮取·虚脉总属正气不足、脉道不充之象，其病机以虚为本，但常兼夹实邪。从所收段落看，虚脉可主阳气衰弱，因阳气不能舒伸而伏匿于阴中，脉虽弦而按之虚；可主湿邪内盛，湿困阳气、泄利体重，脉见弦虚；可主阴血亏虚，阴血不足则脉道不充，按之细弱；亦可主痰热互结，痰热内蕴而正", "c": "主阳气衰弱"}, {"id": "c:浮+和", "n": "浮和脉", "o": "浮和脉总起来主表邪渐解而余邪未净，或正虚邪恋、水饮内停之证。其脉象浮而较和，说明外浮之势已缓，但浮象仍在，提示病位偏表或气机浮越。从所涉段落看，浮和脉可因表邪渐解而见，此时邪气虽减而未尽；亦可因水饮内停、气机不畅而兼弦象，反映湿无出路；还可因久病正虚、宿瘕不化", "c": "主表邪渐解"}, {"id": "c:大+浮+小", "n": "浮大小脉", "o": "浮大小脉在古籍中仅见此段，其核心含义并非独立主病，而是作为动态观察中的向愈指征。浮大之脉本可主邪盛、气浮于外，但若服药后由浮大渐减为小，则说明邪气衰退、正气渐复，脉象由亢盛转向和缓，故与“动数更迟”“初躁后静”同列为愈证。需注意，此脉所主病机须结合动态变化理解", "c": "主邪退向愈"}, {"id": "c:弦+滑+大+浮", "n": "浮大弦滑脉", "o": "浮大弦滑脉总起来主风、热、肝风、痰湿四类病机，且四者常相兼为患。浮主风邪外袭或风邪上扰，大主阳热亢盛，弦主肝风内动，滑主痰湿内蕴。此脉象多见于风痰壅盛、肝风挟痰上扰之证，如中风暴仆、口噤不语、喉如拽锯等。四类病机之间关系密切：风邪引动肝风，肝风挟痰湿上扰，痰湿", "c": "主风邪"}, {"id": "c:大+浮+散", "n": "浮大散脉", "o": "浮大散脉在古籍中主要作为夏季心火当令的平脉出现，其脉象浮大而散，反映心气充沛、阳气外达，属应时生理常脉。然此脉亦为心脉之基准，若失其和缓之象，或被他脏之脉乘袭，则主病机变化：一则心气败绝，现真脏死脉，主危候；二则他脏乘心，依五行生克分虚邪、实邪、贼邪、微邪，主", "c": ""}, {"id": "c:数+滑+大+浮+动", "n": "浮大数动滑脉", "o": "浮大数动滑脉总属阳脉，主阳热亢盛、气血鼓动之病机。其脉象浮、大、数、动、滑，皆阳性有余之征，故原文以「凡脉浮大数动滑，此名阳也」统括之。具体而言，浮主表，数主腑，大主动滑主阳热炽盛、气血壅遏。诸脉相合，既可见于伤寒表证之发热恶寒身痛，亦可因阳热壅遏、血气不通而", "c": "主阳热"}, {"id": "c:数+大+浮", "n": "浮大数脉", "o": "浮大数脉总主热邪为患，以浮主表、大主热盛、数主热躁，三者相合，热象显著。其病机涵盖表热、里热、热毒、热在经络，以及虚阳外浮和正复邪退等。表热者邪在肌表，里热者热盛于内，热毒者燔灼营血，热在经络者病位浅深不同；虚阳外浮者脉虽浮大数而按之无力，为真虚假实；正复邪退", "c": "主表热"}, {"id": "c:数+大+浮+洪", "n": "浮大洪数脉", "o": "浮大洪数脉总起来主热，但须分虚实。实者多为痰热壅盛，如案中太阴经积痰，脉浮大洪数，痰热壅肺，肺失肃降；虚者或为虚阳外浮，如产后气血暴损，孤阳外越，内真寒外假热，脉浮大洪数；或为虚火上炎，如年高足三阴虚损，虚火不敛，脉洪数不减或洪大浮数按之无力。三类之间，实热与", "c": "主痰热壅盛"}, {"id": "c:大+浮+洪+长", "n": "浮大洪长脉", "o": "浮大洪长脉总起来主风邪外盛、阳热亢盛、气血涌盛及木亢金郁之病机。其脉浮大，主邪盛于外；洪长，主阳热有余、气血涌盛。诸类相互关联：风邪外袭可引动阳热，阳热亢盛则气血涌盛，气血涌盛又致木火亢盛而金气受抑。原文强调'中风发三秋，脉浮大而洪长'，秋令本应收敛，脉反浮大", "c": "主风邪外盛"}, {"id": "c:大+浮+涩", "n": "浮大涩脉", "o": "浮大涩脉总起来主邪热壅盛、气滞血少、气血俱损及元气虚实夹杂之病机。浮大主邪热或气血外浮，涩主气滞血少、郁结不通。二者并见，既可因热壅气滞而见于肺胃热郁之证，也可因气血俱损、虚火上浮而见于疮疡不敛等虚证。在灸法辨证中，浮大涩脉提示元气虚实不同，需结合右关脉弱等判", "c": "主热壅气滞"}, {"id": "c:数+滑+大+浮+紧+实", "n": "浮大滑实紧数脉", "o": "浮大滑实紧数脉总起来主内实热盛、湿热毒邪壅滞之病机，尤以发黄如金色为典型。其脉象中，浮为热蒸于外，大滑为气血沸涌，实数为邪热内实，紧为湿毒壅滞。诸脉并见，反映热盛于内、湿毒交蒸、气血壅滞的复杂病机。所分四类——内实热盛、湿热发黄、酒客胃热、湿毒内蕴——实为同一", "c": "主内实热盛"}, {"id": "c:数+滑+大+浮", "n": "浮大滑数脉", "o": "浮大滑数脉总属阳脉，其核心病机为阳热亢盛、气血鼓动。原文张景岳以「浮大滑数之类皆阳也」与「沉微细涩之类皆阴也」对举，将脉之阴阳统摄病机，为医道纲领。拆分而言，浮主表、数主热、大主阳盛、滑主阳热壅遏，四者相合，既可主阳证之总纲，又可具体主热证、表证与实证。四类病", "c": "主阳证"}, {"id": "c:大+浮+濡+缓", "n": "浮大濡缓脉", "o": "浮大濡缓脉总起来主脾胃气败、阳气浮越、脏气衰微。其脉浮大无力、濡缓无神，为脾胃气败、阳气浮越之象；时而歇止，则示脏气衰微、脉气不续。患者年七十，五更洞泄日久，昏迷不醒、手足痿废、溲便不禁、面目黑气弥漫，皆脾肾阳衰、元气欲脱之候。三类病机相互关联：脾胃气败为根本", "c": "主脾胃气败"}, {"id": "c:大+浮+濡", "n": "浮大濡脉", "o": "浮大濡脉总起来主虚、湿、浮阳三类病机，而又有平脉之常。浮大似有余，濡则示不足，故其核心为正气亏虚而虚阳浮越：或肝肾阴亏、精不摄而虚风上浮，或气血虚衰、卫外不固而虚阳外越，甚则脾胃气败、脏气衰微、元气欲脱。濡又主湿，故暑湿困脾、中阳不运，或疟邪湿恋、中虚邪争，亦", "c": "主虚阳浮越"}, {"id": "c:大+浮+疾", "n": "浮大疾脉", "o": "浮大疾脉总属阳脉，主阳盛邪实、正气抗邪之候。其脉浮为病位偏表或阳气外浮，大为邪气壅盛或正邪交争，疾（数）为热盛或风邪急搏。三类病机相互关联：阳盛是其根本，邪实正抗是阳盛在伤寒温病中的具体表现，癫疾风搏则是阳盛风热挟痰上扰的变证。原文以浮大疾为阳脉，强调“阳病见", "c": "主阳盛"}, {"id": "c:大+浮+短", "n": "浮大短脉", "o": "浮大短脉总起来主邪实壅盛、气机壅滞，兼及湿热郁蒸与气血亏虚。其核心病机为外邪侵袭、表里俱病，浮主邪郁肌表，大主阳明热盛，短主气机壅滞。阳明脉至浮大而短本为应时之常脉，但病时则示邪实壅盛、三阳合病。弦浮大短脉总述强调少阳阳明合病为始，湿热郁蒸发黄为进展，气机壅滞", "c": "主邪实壅盛"}, {"id": "c:大+浮+空", "n": "浮大空脉", "o": "浮大空脉总属大虚之候，以虚阳外浮、阴血亏竭为核心。其类有三：一为阴虚阳浮，阴不制阳，虚阳上越；二为虚阳上脱，下元虚衰，阳无所附，甚至阴阳将脱；三为气虚虚热，脾肺气虚，虚热上浮。三者皆以正虚为本，或阴亏，或阳衰，或气虚，而浮大空脉为共同表现。各段虽病因不同，或失", "c": "主阴虚阳浮"}, {"id": "c:大+浮+紧", "n": "浮大紧脉", "o": "浮大紧脉总起来主外邪束表、邪正交争之病机，以寒邪闭表、风毒袭表为基础，进而可化热动血、表里俱实，甚则邪盛正衰而预后不良。浮主表，紧主寒，大主邪盛，三象合见，说明邪气在表而盛，正气奋起抗邪。其具体所主，轻则太阳表寒、风毒在表，重则表寒里热、表里俱实，或热迫血妄行", "c": "主表寒"}, {"id": "c:细+大+浮+微+涩+小", "n": "浮大细小微涩脉", "o": "浮大细小微涩脉在此段中主要主虚损、阴虚火旺、精浊下泄及形脱危候。微涩而弱见于遗精白浊，示肾气不固、气血不足；芤濡洪数示阴虚火旺，与微涩同属虚火范畴；三消脉浮大者生，示阳气尚能外达，而细小微涩则形脱可惊，为津枯形瘦之危候。诸类皆以虚为本，或气血亏虚，或阴精耗损，", "c": "主虚损"}, {"id": "c:大+浮+缓", "n": "浮大缓脉", "o": "浮大缓脉总起来主气虚、风邪、阴寒虚阳、湿热及脾病本脉数类。其核心在“缓”字：缓为脾虚气弱之常，浮大则示虚阳外浮或风邪在表。若浮大无力、按之无神，多主气虚下陷或阴寒内盛、虚阳外越；若浮大有力而缓，多主风邪外袭或湿热内蕴。诸类之间，以气虚为本，风邪、湿热为标，阴寒", "c": "主气虚"}, {"id": "c:大+浮", "n": "浮大脉", "o": "浮大脉总以“浮主表、主虚，大主邪盛、主热”为纲。其病机大致可分两端：一为邪实，包括外感表邪风热、阳热亢盛、痰饮壅盛及宿食实邪可下，脉多浮大有力，见于新感、肺胀、三阳合病、宿食下利等；二为正虚，包括虚阳外浮与气实血虚，脉多浮大无力或按之豁然，见于劳倦内伤、产后、", "c": "主表邪风热"}, {"id": "c:大+浮+芤", "n": "浮大芤脉", "o": "浮大芤脉总起来主热盛津伤、气阴两伤，或虚寒精血亏虚、虚阳外浮之证。其脉象由浮、大、芤三部分组成：浮主邪在表或热盛，大主热盛或虚阳外浮，芤主津血亏虚。在温病过程中，浮大芤脉多因热邪亢盛，耗伤津液，甚则气阴两伤，如原文所述“热盛津伤”“阴液大伤”等；若脉见散大，则", "c": "主热盛"}, {"id": "c:大+浮+迟+芤", "n": "浮大芤迟脉", "o": "浮大芤迟脉总起来主虚寒夹精血亏虚、虚阳外浮之证。原文辨虚劳两途，明确仲景所论虚劳属“虚寒之症”，其脉浮大芤迟：迟为寒，浮大芤为精血虚而阳浮。三类病机相互关联：精血亏虚是基础，虚寒内盛是病性，阳浮是虚寒与精血虚共同导致的脉象表现。精血虚则脉道不充而芤，虚寒则脉行", "c": "主虚寒"}, {"id": "c:大+浮+虚", "n": "浮大虚脉", "o": "浮大虚脉总属正虚邪盛、虚阳外浮之候。其脉浮为邪在表或阳气外浮，大为热盛或气血虚张，虚为正气不足、按之无力。所主病机可归纳为：正虚邪盛、虚阳外浮、气散血耗、气郁痰阻、心神飞越、虚寒内盛。诸类之间，正虚是共同基础，或兼邪热、或兼痰郁、或兼虚寒，而虚阳外浮为关键病机", "c": "主正虚邪盛"}, {"id": "c:大+浮+迟", "n": "浮大迟脉", "o": "浮大迟脉总起来主气血大虚、虚寒内盛、虚阳外浮之证。浮大非实热，乃气血浮越于外而中气不足；迟为阳气衰微、虚寒内盛。三者相互关联：气血亏虚是基础，虚寒内盛是病性，虚阳外浮是气血虚与虚寒共同导致的脉象表现。原文见妊妇精神困顿、自汗不止、舌苔灰白、下血水甚多、胎寂不动", "c": "主气血虚浮"}, {"id": "c:大+浮+长", "n": "浮大长脉", "o": "浮大长脉总起来主邪实壅盛、积块内结，尤以脾积为典型，兼可主风热外盛、阳热亢盛及下元虚损。其脉浮主邪在表或外候，大主邪实壅盛，长主气有余或积气成形，故整体反映实邪壅滞、气血亢奋之病机。然脉象须结合兼脉与部位：两尺按之软则示下元虚，不可峻攻；若浮大洪长并见，则主风", "c": "主积"}, {"id": "c:浮+实", "n": "浮实脉", "o": "浮实脉总起来主邪实于表、正气未衰之病机。其脉浮主病位在表，实主邪气盛实，故凡风热外袭、水气泛溢而兼表实，或咳嗽等外感病中邪在表而胃气未败者，皆可见之。上述三类中，“主风热在表”与“主水气实邪”侧重具体邪气性质，一为风热，一为水湿，但均以浮实为共同脉象，反映邪实", "c": "主风热在表"}, {"id": "c:浮+实+芤", "n": "浮实芤脉", "o": "浮实芤脉（此处实为浮芤不实之脉）总起来主阴血亏虚、气浮于外之病机。其脉浮而不实，似芤非芤而不硬，或两尺无根，至数微数，反映阴血亏于内，虚阳浮于外。具体而言，阴血亏虚则不能化液生汗，故多热；气浮于外则失血未甚而脉浮芤；下焦亏虚则两尺尤虚，固摄无权；阴虚内热则脉数", "c": "主阴虚血虚"}, {"id": "c:浮+小+促", "n": "浮小促脉", "o": "浮小促脉总起来主气分在上结阻、表里不通之病机。浮主表，提示病位在上在表；小主气弱，反映正气不足；促主气结，表明气机郁结。三者相合，说明气分虚弱而郁结于上，导致肺气不降，水湿不行，中下不通，出现喘胀、二便不爽、呼息不利等症。其病机核心是气结上焦、表里失宣，治当开", "c": "主表"}, {"id": "c:浮+小+弱", "n": "浮小弱脉", "o": "浮小弱脉总起来主风邪外入、心气不足、痰热蒙心三类病机，三者相互关联。浮脉主风邪外袭，小弱主心气内虚，风邪乘虚入心，蕴热蒸痰，蒙蔽心神，故见神呆语乱、哭笑不常等症。原文凭脉断为‘心风’，正是风、虚、痰热交织之候。三类中，风邪为外因，心气不足为内因，痰热蒙心为病理", "c": "主风邪外入"}, {"id": "c:浮+小+急", "n": "浮小急脉", "o": "浮小急脉总起来主气血内滞、邪结脉道、经气不足及真元败竭。其脉象浮而小急，浮为气之外浮，小急为邪结脉道、气血内滞之征；若兼见数急无伦，则又反映经气亏虚、真元败竭。各类病机之间相互关联：气血内滞与邪结脉道常并见，导致偏枯；而经气不足与真元败竭则为久病重候，预后多不", "c": "主气血内滞"}, {"id": "c:数+浮+小", "n": "浮小数脉", "o": "浮小数脉总起来主表邪留恋、风热犯肺、正虚邪恋、风火相搏及气阴两伤等病机。浮为邪在表或气虚外浮，数为热，小为邪郁或阴血不足。各段所主虽有偏重，但多围绕外邪与正虚交织：或表邪未尽而余热未清，或风热上攻肺胃，或正虚邪恋、风火相搏，或气阴两伤、虚热内扰。其共同特点是浮", "c": "主表邪未尽"}, {"id": "c:大+沉+浮+小", "n": "浮小沉大脉", "o": "浮小沉大脉总以浮取小、沉取大为核心特征，所主病机围绕'积、郁、虚、实'展开。其沉大有力者，主宿积伏于下焦、气聚不行；若兼湿热内遏，则为阴中伏阳，阳郁于阴分。其浮小沉大而见于久病正伤者，又主虚中夹实，正虚而积未去。与之相对的浮大沉小脉，则主表里同病或阳虚欲脱，浮", "c": "主积伏下焦"}, {"id": "c:数+沉+浮+小", "n": "浮小沉数脉", "o": "浮小沉数脉在此案中并非沉数，而是浮小而不沉数，按之少有力。总起来主邪已外达、正气渐复、胃气渐旺之病机。浮主邪在表，小主正气未充，按之少有力主胃气渐振。三者相互关联：邪从表解则脉浮，正气未充则脉小，胃气渐复则按之有力。此脉象示疾病向愈之机，故治疗以健脾益气、清热", "c": "主邪在表"}, {"id": "c:滑+浮+小", "n": "浮小滑脉", "o": "浮小滑脉总主正虚邪结之候。浮小为气虚，滑为痰热壅结，二者相合，提示正气不足而痰热等邪气壅聚。本例患者年逾五十，形肥色紫，颈项少阳痈肿如碗，脉见浮小滑，正是气虚无力托邪、痰热壅结局部之象。其病机核心为虚实夹杂：虚在气虚，实在痰热壅结。三者相互关联，气虚为本，痰热", "c": "主气虚"}, {"id": "c:数+浮+小+濡", "n": "浮小濡数脉", "o": "浮小濡数脉总属虚多实少之候，核心病机为气阴两伤、虚热内扰，兼脾肺气虚与暑湿未清。浮为气虚外浮或邪恋表分，小濡为阴血不足、脉道不充，数为虚热鼓动。右脉尤不足，突出脾肺气虚；病疟日久、截药伤正，使气阴耗伤，暑湿余邪未净。四类病机相互关联：气阴两伤为根本，脾肺气虚加", "c": "主气阴两伤"}, {"id": "c:浮+小+濡+缓", "n": "浮小濡缓脉", "o": "浮小濡缓脉总起来主脾虚气弱、劳倦伤中，其核心病机为脾气亏虚、中气不足。浮为虚，小濡缓为脾虚气弱，故脉象浮小而濡缓。原文所载患者年逾五十，过劳怠倦、烦闷恶食，正合东垣劳倦伤脾之论，治以补中益气或清暑益气而愈。此外，该脉若见浮沉各得其位、大小不逾其矩，则为和平有子", "c": "主脾虚气弱"}, {"id": "c:浮+小+濡", "n": "浮小濡脉", "o": "浮小濡脉总属虚证，核心病机为阳气虚馁、中气亏虚。浮为气虚外浮，小濡为脉道不充、气血不足，按之不足尤显中气亏虚。原文载患者形瘦色白而脆，得遍身虫行奇疾，乃汗多亡阳、气虚不能温煦肌肤之象，非实邪为患。其下属浮小濡数脉主气阴两伤、虚热内扰；浮小濡缓脉主脾虚气弱、劳倦", "c": "主气虚"}, {"id": "c:细+浮+小", "n": "浮小细脉", "o": "浮小细脉总起来主外邪未解而气血已伤，或郁火内伏而外显假寒。浮脉主表，小细主气血不足，故浮小细并见，多示正虚邪恋之候。若兼风寒湿痹，则外邪未祛而正已伤；若沉按坚搏，则又为郁火内伏、不得宣越之象。两类病机一为外邪伤正，一为内火郁伏，看似相反，实则均以浮小细为共同脉", "c": "主外邪正伤"}, {"id": "c:浮+小+缓", "n": "浮小缓脉", "o": "浮小缓脉总起来主气阴两虚、心脾两伤之病机。浮为虚，小为气弱，缓为脾虚，按之虚豁更示正气不足。其核心在于暑热耗气伤阴与劳倦伤脾耗中，二者常相兼为患。暑热伤心，则神不守舍；劳倦伤脾，则意不宁谧。心脾俱伤，故见身热汗出、昏懵语乱。脉象浮小缓而虚豁，既非实热，亦非纯虚", "c": "主暑伤气阴"}, {"id": "c:浮+小", "n": "浮小脉", "o": "浮小脉总以浮取小而无力为特征，浮主表、主虚阳外浮，小主不足、主阴血亏少。其病机大要有三：一为外邪在表而正气略弱，邪未深入，治宜轻疏；二为气血阴阳亏虚，脉道不充，浮小无力，治宜补益；三为虚阳外越或正虚邪恋，虚实夹杂，脉多浮小无根或按之不足，预后多险。各类之间常相", "c": "主表邪未解"}, {"id": "c:浮+小+芤", "n": "浮小芤脉", "o": "浮小芤脉总起来主气血两亏，尤以血少为著。其脉浮小，示气血不足于外；芤为中空，专主血虚。原文见于新产之后，气血并亏，左脉浮小而芤，明言血少，与右脉虚大无力之气亏并见，故其病机核心为气血两虚，清窍失养。三类之间，血虚与气亏互为因果，气血并亏则清窍失养，头痛由生。此", "c": "主血虚"}, {"id": "c:浮+小+软", "n": "浮小软脉", "o": "浮小软脉总起来主正虚邪恋之候。浮脉主风邪外袭，小软脉主气血不足，故其核心病机为正气亏虚、风邪客表。在此基础上，若兼弦滑，则风火痰升，可发为类中；若产后气血未复而冒风感寒，则正虚邪轻，宜清疏。各类之间，正虚为本，风邪为标，痰与类中为风邪引动之变。因正虚而邪易袭，", "c": "主正虚"}, {"id": "c:弦+大+浮", "n": "浮弦大脉", "o": "浮弦大脉总起来主风、热、痰、湿等邪气壅盛，兼涉表里上下。浮主邪在表，弦主少阳、风动或气机郁滞，大主邪盛或虚阳上浮。其病机类别虽多，但可归纳为三类关系：一是外邪客表，如少阳感风、三阳合病，脉浮弦大示邪盛于表，治当和解或发汗；二是风热痰火上壅，如风热上壅清窍、湿热", "c": "主风热上壅"}, {"id": "c:数+弦+浮+小", "n": "浮弦小数脉", "o": "浮弦小数脉总起来主暑风湿热久郁、传入厥阴、肝风犯肺、阴分不足之病机。浮为表，提示表热未清；弦主肝，示肝风内动；小为阴不足，数为热，合示阴亏内热。四类病机相互关联：初起暑风湿热留恋表分，久则传入厥阴，肝风上逆犯肺，咳嗽失红；久病伤阴，阴不足而虚热内生，故脉小数。", "c": "主表热未清"}, {"id": "c:弦+浮+小", "n": "浮弦小脉", "o": "浮弦小脉总起来主风木乘土、正虚气滞之病机。浮为表、为风，弦主肝木、主气滞，小主正虚。两案中，飧泄案脉浮弦而小，断为风木乘土、脾虚不运，证见完谷不化、腹痛；中满案脉浮小而弦、按之无力，断为气虚不运、气机壅滞，证见中满朝宽暮急。两类病机相互关联：风木乘土与气虚气滞", "c": "主风木乘土"}, {"id": "c:数+弦+浮", "n": "浮弦数脉", "o": "浮弦数脉总以浮主表、弦主风、数主热为基本脉理，所主病机可归纳为外感与内伤两大类。外感方面，或风热在表，或疟痢兼感，或风痰壅肺，皆邪郁肌表、肺卫失宣；内伤方面，或少阳痰火，或肝阳化火，或阴虚阳越，或虚风内动，皆肝木偏亢、火升风动，或阴亏液耗、虚阳上浮。各类之间常", "c": "主风热在表"}, {"id": "c:弦+沉+浮+涩", "n": "浮弦沉涩脉", "o": "浮弦沉涩脉总起来主风、湿、瘀相互搏结之病机。浮弦为风动之象，沉涩为湿滞血瘀之征，二者并见，说明外风引动内湿，湿浊与瘀血相结，形成湿瘀互结之候。原文产妇新产，气血未复，湿浊内蕴，瘀血未净，风动于上，故见发搐、气喘、面黑、口臭等症。丹溪断为受湿，治以化湿行瘀，下瘀", "c": "主风"}, {"id": "c:弦+沉+浮+紧", "n": "浮弦沉紧脉", "o": "浮弦沉紧脉总起来主外寒引动内饮、饮邪迫肺之证。浮弦为风饮上泛之象，沉紧为水寒内结之征，二者并见，反映外有风邪引动，内有水寒结聚，形成外寒内饮相合为病。原文痰饮喘咳、自汗而势甚凶危，正是外寒引动内饮、饮邪迫肺之机。紧脉主寒主痛，沉紧示饮结于里，故治以小青龙加杏仁", "c": "主风饮上泛"}, {"id": "c:弦+滑+浮+洪", "n": "浮弦洪滑脉", "o": "浮弦洪滑脉总属邪热痰风交炽之象，其病机核心为外邪引动内风，痰热壅盛。浮主表邪外袭，弦主肝风内动，洪主热盛燔灼，滑主痰浊内蕴。四者相合，常见于外感暑热、温补助热、肝风煽痰、痰热内闭之证，如类中昏瞀、遗溺痰升、汗多面赤等。各病机之间相互关联：表邪入里化热，热盛炼液", "c": "主热盛"}, {"id": "c:数+弦+滑+浮", "n": "浮弦滑数脉", "o": "浮弦滑数脉总起来主风、热、痰、火交争为患，其病机核心为邪实内蕴，或兼外感引动。浮为风邪在表，弦主痰饮与风动，滑主痰湿内盛，数主热邪亢盛，四者相合，常见于外感风热、暑热挟痰、痰火内扰及风劳骨蒸等证。从所收三段看，或见风邪外袭、痰热交争于上焦，或见暑热痰浊壅阻气分", "c": "主暑热挟痰"}, {"id": "c:弦+滑+浮", "n": "浮弦滑脉", "o": "浮弦滑脉总属外邪、痰饮、风阳相互搏结之象。浮主表、主风，弦主饮、主肝风、主痛，滑主痰湿、主食积，三脉相合，多示外邪引动内饮，或风痰上扰，或风邪夹食，或阴虚痰实。其病机核心为'邪实壅阻'，或外寒内饮，或风温引动宿饮，或风阳挟痰上逆，或风暑夹食，或妊娠感风。各段虽", "c": "主外邪束表"}, {"id": "c:弦+细+浮+弱", "n": "浮弦细弱脉", "o": "浮弦细弱脉总起来主气虚、气郁与气血两虚，并见脾虚肝乘之机。浮为气虚外浮，弦为气郁不舒，细弱为气血两虚，三者在同一患者身上复合出现，反映虚、郁、滞交织的复杂病机。其核心在于中气亏虚，运化失职，以致气机升降乖违；肝木乘虚而犯脾土，故见气壅腹痛、吐黑水、嗳气不食等症", "c": "主气虚"}, {"id": "c:弦+浮+缓", "n": "浮弦缓脉", "o": "浮弦缓脉总属阳虚气弱，兼夹风邪与湿滞。其核心病机为阳气不足、脾阳亏虚，浮虚缓主阳虚鼓动无力，浮弦缓主脾胃阳虚兼气机不畅；阳虚则卫外不固，易感风邪，风木乘土则脉见弦象；脾阳不振，运化失职，湿滞内停则脉缓。三者相互关联：阳虚为本，风邪、湿滞为标，标本相兼。原文所载", "c": "主阳虚"}, {"id": "c:弦+浮", "n": "浮弦脉", "o": "浮弦脉总属风邪为患，兼涉表里虚实。浮主表、主风、主虚阳外浮；弦主风、主饮、主痛、主气滞。其病机可归纳为外感风邪、少阳不和、痰饮内停、肝风内动、气滞血瘀、虚阳外浮六类。外感风邪与少阳不和多属表证、实证，风邪客表或郁于少阳，脉多浮弦有力；痰饮内停与气滞血瘀多属里实", "c": "主外感风邪"}, {"id": "c:弦+浮+芤", "n": "浮弦芤脉", "o": "浮弦芤脉总起来主正虚邪恋、阴亏风动之候。其脉象由浮、弦、芤三部分组成：浮弦为热邪未敛、肝风内动之象，芤则示阴血大亏、脉道失充。三者并见，说明久病阴伤已极，又卒中暑热，形成阴液涸竭而阳热鸱张的复杂局面。具体而言，芤主阴血亏虚，为病之本；浮弦主热邪未敛与肝风内动，", "c": "主阴血亏虚"}, {"id": "c:弦+大+浮+虚", "n": "浮弦虚大脉", "o": "浮弦虚大脉总起来主气血虚寒、正气不足而虚阳外浮之证，多见于心腹痛之虚痛候。其浮为阳气外浮，弦主痛与气机不畅，虚大为气血亏虚，三者相合，反映本虚标实、虚寒内盛而虚阳外越之病机。各类之间相互关联：气血虚寒是根本，虚阳外浮为虚寒所致之脉象表现，痛证为虚寒凝滞、经脉失", "c": "主虚寒"}, {"id": "c:数+弦+浮+软", "n": "浮弦软数脉", "o": "浮弦软数脉总起来主暑热挟虚、疟邪未清之证。其脉浮弦为暑热扰于外，软数为真阴亏于内，尺中甚弱示肾阴素虚。三证相互关联：暑热外扰，化疟未清，久则伤阴，真阴亏虚，故脉象浮弦软数并见。原文以‘暑热挟虚’概括，既言暑热之邪未清，又言真阴之虚，疟为暑热所化，虚为邪热所伤，", "c": "主暑热"}, {"id": "c:数+浮+弱", "n": "浮弱数脉", "o": "浮弱数脉总主虚热上浮、气血不充、虚风痰扰三类病机。浮为气浮于上，弱为不足，数为有热，三部合参，上部浮弱数而下部弱数，示上焦虚热浮动、下元亏虚。疮后阴血耗伤，气血不充，经络失养，故偏废脚弱；虚风挟痰上扰清窍，则耳鸣不闻、冲气动。三类之间，虚为本，热为标，风痰为变", "c": "主虚热上浮"}, {"id": "c:浮+涩+弱", "n": "浮弱涩脉", "o": "浮弱涩脉总主虚损，以气血阴阳亏虚、精血不足为核心。浮为气虚外浮，弱为气血不足、久病体虚，涩为精血亏少、脉道不利。四类病机中，主虚劳概括久病气血阴阳未复之总候；主气血虚侧重气虚血弱之一般表现；主精亏无子与主失精梦交则专指肾精虚冷、生殖之精亏乏及失精梦交等具体病证", "c": "主虚劳"}, {"id": "c:浮+弱", "n": "浮弱脉", "o": "浮弱脉总以'浮为虚阳外浮或邪在表，弱为正气不足'为纲，所主病机可归为表虚中风、气虚阳浮、虚劳欲脱、酒疸正虚、血虚受风、气阴两虚六类。其中表虚中风与气虚阳浮最为常见，前者为外感风邪、营卫不和，后者为内伤气虚、虚阳外越，二者皆以'弱'示正虚、'浮'示病势趋外。虚劳", "c": "主表虚中风"}, {"id": "c:浮+微+弱", "n": "浮微弱脉", "o": "浮微弱脉总起来主正气虚衰，营卫不充。其核心病机为内虚，因正虚而变生他证：一则正不胜邪，邪气乘虚内陷，形成内虚邪陷之证；二则虚阳不能内守，浮越于外，见虚阳外浮之象；三则素体虚弱，易感外邪，成正虚感寒之候。各类病机相互关联，正虚是根本，邪陷、虚阳外浮、感寒均为正虚", "c": "主正虚"}, {"id": "c:数+浮+微", "n": "浮微数脉", "o": "浮微数脉总起来主表热、虚热、气阴两伤、肺胃热盛及喉证燥热等病机。浮为邪在表或虚阳外越，数为有热或虚热，微为邪气不盛或正气衰微。其病机可归纳为两类：一为邪热在表或肺胃，如外感表邪未解、水热互结、肺胃热盛、喉证燥热，此时浮数为主，微示热势不剧；二为正气虚衰而虚热内", "c": "主表热"}, {"id": "c:浮+微+涩", "n": "浮微涩脉", "o": "浮微涩脉总属阴血亏虚、气随血耗之候。浮为气虚外浮，微为阳衰，涩为血少行滞，三者相合，核心病机为亡血、汗出及金疮失血。原文两条均以'寸口脉浮微而涩，法当亡血，若汗出'为纲，并补充无汗而身有疮、刀斧所伤亡血者亦见此脉，说明其主病以血虚津伤为本。此外，该脉兼搏坚而长", "c": "主亡血"}, {"id": "c:滑+浮+微", "n": "浮微滑脉", "o": "浮微滑脉总属外感风温引动伏热之候，其病机以表邪未解、痰热内蕴、里热内结、伏气化热四类为主。浮脉主表，说明外感风温之邪尚在卫表；滑脉主痰热，反映热灼津液、痰热上泛；右关重按甚实，提示里有伏热结聚；而‘伏气化热内动’则点明伏热为病本。四类病机相互关联：伏热内蕴是根", "c": "主表邪未解"}, {"id": "c:浮+虚+微+缓", "n": "浮微缓虚脉", "o": "浮微缓虚脉总主五脏虚损、正气衰少。浮为气浮于外而内虚，微为阳气衰微，缓为气血弛缓不足，虚为精血不充。原文“脉浮微缓皆为虚”“脉微濡相薄为五劳”明示其虚损本质。所主病机可归为虚损、劳伤及六极（气、血、筋、骨、肌极）。诸类皆以虚为核心：劳伤为虚之因，六极为虚之果，", "c": "主虚损"}, {"id": "c:细+浮+微+散", "n": "浮散细微脉", "o": "浮散细微脉总属气血虚脱之象，因浮为气浮不敛，散为气散不收，细微为气血衰少，故其核心病机为气血虚脱。然产后内伤喘之证，虚中每夹恶露不行，或热壅、或寒凝，致瘀血阻滞、气机不利。原文以脉象指导治法：脉见浮散细微，先以芎归汤养血、独参汤补气固脱；若恶露不行，则急行恶露", "c": "主气血虚脱"}, {"id": "c:浮+散", "n": "浮散脉", "o": "浮散脉总以浮、散二象为纲，浮主气浮于外，散主气不内守、脉道不聚。其所主病机以虚为主，可归纳为虚阳外越、气血亏虚、元气欲脱、神志浮越四类，皆因正气不足、阳不敛阴、气不归元所致；其中元气欲脱最危，虚阳外越与气血亏虚常见于内伤杂病及产后、疮疡溃后，神志浮越则偏于情志", "c": "主虚阳外越"}, {"id": "c:数+浮+散", "n": "浮数散脉", "o": "浮数散脉总以浮、数、散三象合参，主邪在肌表、热郁于外之病机。浮主表，数主热，散主邪未结聚，故其核心为表热实证。原文“脉浮数者散之”直接点明治则，与“沉实者下之”对举，强调表里辨证。由此可衍生三类：一为单纯表邪，治宜疏散；二为表热，数脉所寓；三为表里俱实，浮数与", "c": "主表邪"}, {"id": "c:数+浮+洪+紧", "n": "浮数洪紧脉", "o": "浮数洪紧脉总属阳脉，主阳热壅盛、六腑不和、热胜血壅之痈疽。其脉浮主病位在表，数主热，洪主热盛，紧主邪壅，合而示阳热之邪郁于肌表、壅于血分。原文以之与沉细伏紧之阴脉对举：浮数洪紧者，毒发于外而为痈，属六腑不和，症见肿焮作痛、身热烦渴、饮食如常，其势虽急，投凉剂多", "c": "主阳热痈疽"}, {"id": "c:数+浮+涩", "n": "浮数涩脉", "o": "浮数涩脉总起来主表邪、气血虚与虚损危候三类病机。浮数主邪在表，涩主气血虚，三者相合，提示外邪客表而正气已虚，或纯属虚损、虚阳浮越。原文强调“浮数邪在表，涩为气血虚”，并指出因气血虚、饮食少而大便不行，非热结，误下则致危。三类病机相互关联：表邪为诱因，气血虚为根", "c": "主表邪"}, {"id": "c:数+浮+涩+短", "n": "浮数短涩脉", "o": "浮数短涩脉总起来主虚损危候，其核心病机为阴伤于内、阳浮于外，甚则阴阳离决。浮数似热，然短涩并见、两寸极小，非实热可知，乃血少气衰、心肺不足之象。劳役忧思、饮食失节致阴亏于下，虚阳浮越于上，故见燥热、盗汗而脉反短涩。三类病机相互关联：虚损为根本，阳浮为虚损之发展", "c": "主虚损"}, {"id": "c:数+浮+硬", "n": "浮数硬脉", "o": "浮数硬脉总起来主气机壅滞、郁热内蕴、水湿不化之证，其病位多在肺脾两经。浮为气失舒运、病位在表，数为郁热，硬为气机壅滞不柔，三者相合，揭示气滞为关键，郁热与水停为继发。气滞则肺失宣降、脾失健运，水湿不化而肤肿；气郁日久则化热，故脉数。三类病机以气滞水停为核心，郁", "c": "主气滞水停"}, {"id": "c:数+浮+空", "n": "浮数空脉", "o": "浮数空脉总属虚损之候，以阴血亏虚为本，虚火、气耗、血脱为标。浮为虚阳外浮，数为虚热，空为血少脉道不充，尺部独减尤显肾阴亏虚。其病机核心在于脾肾阴虚、心脾气馁，导致水不制火、血失统司，进而血滑气脱、脉络不固。三类病机相互交织：阴虚火旺为虚热之因，脾不统血为出血之", "c": "主阴虚火旺"}, {"id": "c:数+细+浮+涩", "n": "浮数细涩脉", "o": "浮数细涩脉总起来主瘀热内阻、肾水竭绝与肝虚风动三类病机。浮数属阳热扰气，细涩为血菀成瘀，二者相合，反映热扰血瘀、清浊升降失常之暴厥；瘀热内阻日久，耗伤真阴，则肾水竭绝，虚阳浮越；肝血瘀聚，肝阴暗耗，筋脉失养，则肝虚风动。三类病机相互关联：瘀热内阻为始动因素，肾", "c": "主瘀热内阻"}, {"id": "c:数+浮", "n": "浮数脉", "o": "浮数脉总以浮主表、主风、主虚阳外浮，数主热、主虚火为纲，所主病机以热为核心，兼涉风、虚、毒、湿、郁。其类别之间，表热与风热多相兼，为外邪袭表、郁而化热之浅层；里热为热盛于内而浮越于外；虚火为阴亏阳浮、按之无力之虚热；热毒为热壅营血、局部结聚；风湿为风热与湿交蒸", "c": "主表热"}, {"id": "c:数+浮+芤", "n": "浮数芤脉", "o": "浮数芤脉总属阴血亏虚、阴火内动、气逆上升之候，兼夹风邪与痰喘。芤主血虚或失血，数主阴火虚热，浮主气升或风邪。诸类病机相互关联：阴血暴失则阴不维阳，气随火升；虚火动血，更伤营络；若兼外风，则血虚招风；若素患痰喘，则肺肾亏虚，气不纳降。总以正虚为本，火、气、风、痰", "c": "主血虚"}, {"id": "c:数+沉+浮", "n": "浮沉数脉", "o": "浮沉数脉总起来主热郁与邪热为患，其病机核心在“数”主热，而“浮沉”定表里浅深。若脉不浮不沉而数，则热郁三焦气分，或为湿温时疫初起邪郁气分，或为风温乘虚内陷、热扰胃肠；若脉浮不沉而数，则邪在表而热盛，多见于湿温时疫初起；若脉沉数不浮，则邪已离表入里，热炽阳明。四", "c": "主热郁三焦"}, {"id": "c:数+滑+沉+浮", "n": "浮沉滑数脉", "o": "浮沉滑数脉总起来主风热外感、痰热壅盛及表里兼病。浮主表，沉主里，数主热，滑主痰热，四者相合可辨病位之表里与病性之痰热。原文以斑疹为例，指出脉浮身热有表证者散风邪，浮数者祛风清热，沉滑无表证者清火，浮沉俱滑数者表里双解。可见浮沉定表里，滑数定痰热，诸脉兼见则提示", "c": "主表证"}, {"id": "c:沉+浮", "n": "浮沉脉", "o": "浮沉脉总以辨表里、测浅深为纲，兼以有力无力定虚实、参以兼脉别寒热痰湿。浮主表、主风、主病位浅，沉主里、主水、主病位深；浮沉俱见可测表里同病、虚实错杂。其主病机涵盖表里病位、虚实盛衰、痰湿水饮、寒热错杂、气血失调及妊娠胎脉。诸类之间，表里浅深为经，虚实寒热为纬：", "c": "主表里病位"}, {"id": "c:数+沉+浮+迟", "n": "浮沉迟数脉", "o": "浮沉迟数四脉为脉诊提纲，总括表里寒热虚实之辨。浮脉主表，有力为邪搏，无力为虚；沉脉主里，沉健主积滞，沉弦主气病，沉迟有力主疼痛；迟脉主寒，数脉主热，迟数相兼可辨疟之寒热、胃之冷温。四脉虽简，却能统摄外感内伤诸多病机：浮以候表，沉以候里，迟以候寒，数以候热，再参", "c": "主表邪"}, {"id": "c:浮+洪+促", "n": "浮洪促脉", "o": "浮洪促脉总起来主热盛，包括外感温邪内炽和少阳枢机不利化热。浮洪为热盛于外，促为热迫急数，故脉浮洪促主要反映热邪炽盛、病势急迫。从原文看，初诊脉弦数主少阳枢机不利，热郁少阳；后脉转浮洪而促，伴大热大渴、舌鲜红，示温邪内炽，热盛于外。两类均属热证，但前者偏少阳郁热", "c": "主热盛"}, {"id": "c:大+浮+洪", "n": "浮洪大脉", "o": "浮洪大脉总起来主热盛邪实，但须分表里虚实。浮主邪在表，洪大主热盛，故常见风热痰火壅盛、表里俱实、阳热亢盛之实证；若洪大而浮、按之无力，则又主虚阳外浮、热盛伤津之虚证或虚实夹杂证。各段所论，实证多因外邪闭郁、痰火积热或伤寒阳盛，脉证相应，故易治；虚证多因气血亏损", "c": "主风热痰火"}, {"id": "c:数+弦+浮+洪", "n": "浮洪弦数脉", "o": "浮洪弦数脉总属阳热实邪为患，其基本病机为热盛邪实。浮主邪在表或阳热外浮，洪数主里热炽盛，弦主实、主痛、主郁。三段落虽具体所指不同，但皆围绕阳热实邪：或表寒外束、里热内结而表里俱实；或阳热之邪郁于阴分，热胜血而发痈疽；或丹痧邪热欲透，脉当见浮弦洪数，若反软数模糊", "c": "主表里俱实"}, {"id": "c:弦+浮+虚+洪", "n": "浮洪弦虚脉", "o": "浮洪弦虚脉总属大虚之候，以虚为根本。浮洪为虚阳外越，非实热；弦为气逆，因虚而气机上逆；虚为不足，血气已衰。三者相合，常见于年高劳伤、酒伤气血、胃气衰败之噎膈反胃等症。其病机核心是虚，虚阳外越、气逆、瘀血夹虚皆由虚所致。原文强调此脉非热非痰，误用凉药则助阴伤阳，", "c": "主大虚"}, {"id": "c:数+浮+洪+实", "n": "浮洪数实脉", "o": "浮洪数实脉总属邪气亢盛、实热有余之象。其脉浮主表，洪主热盛，数主热，实主邪实，四者相合，反映正邪交争剧烈、邪实而正气未衰的病理状态。在暴病中，此脉为顺，提示新病邪实热盛，脉证相符，正气尚能抗邪；在久病中，此脉为逆，提示正虚邪恋或虚阳外越，病情危重。因此，本脉所", "c": "主实热"}, {"id": "c:数+浮+洪", "n": "浮洪数脉", "o": "浮洪数脉总属阳热之象，浮主邪在表或热越于外，洪主热盛，数主热急。其主病机以热为核心，可概括为表热、热毒壅盛、气血两燔、风热痰壅、肝风热盛及虚阳外浮数类。表热者邪在肌表，热势未深；热毒壅盛者热毒蕴结，局部红肿灼热；气血两燔者热毒深入气血，燔灼营血；风热痰壅者外风", "c": "主表热"}, {"id": "c:滑+大+浮+洪", "n": "浮洪滑大脉", "o": "浮洪滑大脉总主热盛邪实，然有表里虚实之别。浮主表，洪滑大主热，故见表实热盛者，脉浮洪滑大，伴壮热无汗、面赤唇紫；若阳明热盛，火势外扬，则见烦热干渴、头痛牙疼、失血等。然此脉亦可见于水亏火旺之虚实夹杂证，脉虽洪大，实由少阴不足、虚火上炎所致。三类病机中，表实热盛", "c": "主表实热盛"}, {"id": "c:数+滑+浮+洪", "n": "浮洪滑数脉", "o": "浮洪滑数脉总主热盛、痰瘀互结及肺痈实热之证。浮为热邪在表，洪为热盛，滑为痰瘀，数为热象，四脉相合，示热毒痰瘀壅聚。原文两段均见咳吐臭脓血、发热昼轻夜重、肌肉大瘦，脉浮而洪滑且数，断为酿酒伤肺、怒气触之，瘀血浊痰滞于肺之气窍，久郁化脓成肺痈。此脉大非呕血虚证，乃", "c": "主热盛"}, {"id": "c:浮+洪+结", "n": "浮洪结脉", "o": "浮洪结脉在此案中并非单一主病，而是复合脉象，反映上焦热郁、气滞血瘀与气血两伤并存的复杂病机。右寸浮洪带结，主热郁于上、气滞血瘀，为鼻齄、胸膈不利之直接脉应；余部沉细而软，主气血两伤，为久服苦寒驱风败血之剂所致虚损。三类病机相互关联：苦寒伤气伤血，致气血两伤，气", "c": "主热郁于上"}, {"id": "c:浮+洪", "n": "浮洪脉", "o": "浮洪脉总以‘浮主邪在表或热越于外，洪主热盛气张’为纲，故其核心病机为热盛。然热有表里虚实之辨：表热者邪在肌表，热势未深；里热者阳明气分热炽，或热入三焦；痰热、风热、湿热虫积则热与邪结，壅遏于内；虚阳外浮者，阴不敛阳，脉虽浮洪而按之不鼓，属假热真虚；若浮洪见于汗", "c": "主热盛"}, {"id": "c:数+浮+虚+洪", "n": "浮洪虚数脉", "o": "浮洪虚数脉总起来主正气已虚而邪热内扰之候。其脉浮洪为风热外扬，虚豁散数为气阴两伤，数则主热。所主病机可归纳为虚、风热、虚火、疟、痰五类：虚为根本，因劳后入房感风，正气先亏；风热为外邪，乘虚内扰；虚火由阴亏而生，内动为患；疟为邪蕴少阳，久成疟母；痰由脾虚湿聚，随", "c": "主虚"}, {"id": "c:浮+虚+洪", "n": "浮洪虚脉", "o": "浮洪虚脉总属虚证，以正气不足为根本。浮洪非实热，乃虚阳外浮之象；虚为血气已衰，无力鼓动。其兼弦则气逆，兼数则虚火或风热，兼洪大则暑热伤津，兼疟则正虚邪恋。各类病机皆以虚为核心：虚阳外越、气逆、虚火、风热、暑热伤津、疟疾，或由虚所致，或虚中夹邪。原文强调此脉非热", "c": "主虚阳外浮"}, {"id": "c:浮+洪+长", "n": "浮洪长脉", "o": "浮洪长脉总起来主阳热亢盛、邪在表或表里同病之机。洪为热盛，长为气分热炽，浮为邪在表，三者相合，多示外邪束表而里热炽盛，或阳明热盛而太阳未罢，或上焦郁热为风寒所束。诸类相互关联：表邪不解可入里化热，里热炽盛又常外显浮象；郁热与表邪相搏则疼痛；若见于夏季，则为时令", "c": "主热盛"}, {"id": "c:浮+涩+短", "n": "浮涩短脉", "o": "浮涩短脉总起来以肺金之象为根基：浮应肺位至高，涩短应肺气收敛，故首为秋令肺金平脉。然同一脉象因兼脉、兼症与色脉相参之异，可主多类病机。其一为常，即肺平脉；其二为肺燥失制，金不制木而肝越离魂；其三为虚损危候，阴伤阳浮、血少气衰，浮数短涩并见两寸极小；其四为脏气衰", "c": "主肺燥肝越"}, {"id": "c:浮+涩+紧", "n": "浮涩紧脉", "o": "浮涩紧脉总主风寒湿三气杂合之痹病。浮为风，涩为湿，紧为寒，三脉并见，乃三邪杂合之征。若邪有偏胜，则审脉之浮多、涩多、紧多以别行痹、痛痹、著痹。故其病机核心为风寒湿杂合痹阻，各类之间相互兼夹，不可截然分开。浮、涩、紧分别对应风、湿、寒，三脉合见则痹病已成，偏胜则", "c": "主风"}, {"id": "c:浮+涩", "n": "浮涩脉", "o": "浮涩脉总以浮为阳、为表、为虚，涩为阴、为血少、为滞涩，合而主风邪在表、脾约津亏、胃反脾伤、虚劳血少、正虚邪滞、燥伤津亏等病机。其核心在于浮示气机外达或虚阳上浮，涩示血行不畅或津液不足，二者相合多示表里同病、虚实夹杂。诸类中，风邪在表与风湿腰痛属外邪滞涩；脾约、", "c": "主风邪在表"}, {"id": "c:弦+滑+浮+紧", "n": "浮滑弦紧脉", "o": "浮滑弦紧脉总起来主外寒引动内风、风火交煽、气阻痰凝之证。浮紧为外寒束表，滑为痰湿内蕴，弦为肝风内动，四者相合，提示病机复杂，非单一邪气为患。其核心在于外寒触发内风，风火相煽，痰湿随气上逆，形成上重下轻、头眩呕酸之候。各类病机之间相互关联：外寒为诱因，痰湿为体质", "c": "主外寒"}, {"id": "c:数+滑+浮", "n": "浮滑数脉", "o": "浮滑数脉总以浮主表、滑主痰湿、数主热为纲，所主病机以表邪未罢、里热炽盛为核心，常相兼为患。表邪未尽则浮，痰湿内蕴则滑，热邪亢盛则数，三者并见多示表里同病、痰热交蒸。其具体类别或偏表（表邪未罢、风水化热），或偏里（阳明热盛、痰热壅肺、温邪挟湿滞），或涉热盛动风之", "c": "主表邪未罢"}, {"id": "c:滑+浮+疾", "n": "浮滑疾脉", "o": "浮滑疾脉总起来主脾虚食积、热与积滞相搏、痰食内壅及气血失调。其核心病机为滑疾相合，示痰食积滞与热邪相搏；浮则示虚阳外浮或病位偏表。诸类之间相互关联：脾虚不运则食积内停，积滞化热则脉见疾；痰食内壅则气机不畅，久则气血失调。故浮滑疾脉虽以脾虚食积为主，亦可见于热积", "c": "主脾虚食积"}, {"id": "c:滑+浮+短", "n": "浮滑短脉", "o": "浮滑短脉在蛊毒病中总主毒邪壅盛、偏表而兼痰湿壅滞。原文以蜴蜥蛊“其脉浮滑而短”为例，与蛇蛊“洪壮”对举，说明蛊毒种类不同脉象各异，但皆属毒邪为患。浮主毒邪偏表，滑主痰湿，短主气机壅滞，三者相合，反映毒邪夹痰湿壅阻表分、经脉不畅之病机。故其主病可归为毒盛、表毒、", "c": "主毒盛"}, {"id": "c:滑+浮+空", "n": "浮滑空脉", "o": "浮滑空脉在此段中实以'数浮滑不空'与'空豁虚弦'对举，主实证痰热。其核心病机为痰热壅盛于肺胃，属风温外感、痰火内蕴之实候。数主热，浮主表，滑主痰，三脉合见，总归痰热壅盛于肺胃，不得降化。其脉'不空'是与虚证鉴别的关键：实者脉数浮滑不空，虚者脉空豁虚弦。故本脉所", "c": "主痰热壅盛"}, {"id": "c:滑+浮", "n": "浮滑脉", "o": "浮滑脉总以浮主表、主风，滑主痰、主湿、主热为纲，所主病机以表邪与痰湿（或痰热）相合为核心。浮为阳脉，示邪在表分或病位偏上；滑为阴中之阳，示痰湿内壅或热邪入里。二者并见，多示外邪引动内痰、表里同病，或风痰上扰、痰热互结。具体而言，或偏表而主外寒束表、湿痰内蕴；或", "c": "主表邪兼痰湿"}, {"id": "c:数+滑+浮+芤", "n": "浮滑芤数脉", "o": "浮滑芤数脉并见，总属正虚邪实、错综复杂之候。浮滑主新邪袭肺胃，为外感新风、痰热内蕴；芤主阴分大伤、失血伤阴；数主肝火内炽、火盛动血；又兼蓄瘀留恋，血不归经。四类病机相互交织：阴血亏虚为本，肝火内炽为标，新邪外袭引动木火，蓄瘀留恋更伤血络，终致血不归经、邪不外达", "c": "主新邪袭肺"}, {"id": "c:滑+浮+芤", "n": "浮滑芤脉", "o": "浮滑芤脉总属正虚邪实、错综复杂之候。浮主外邪袭肺，滑主痰湿内盛，芤主阴血受伤，三者相合，提示外感新风引动痰热，兼有阴血亏虚、络伤血动之机。其病机类别包括外邪痰热、阴血受伤、肝火动血及瘀热互结，彼此交织：阴血亏虚为本，肝火内炽为标，新邪外袭引动木火，痰热壅肺，蓄", "c": "主外邪痰热"}, {"id": "c:滑+浮+长", "n": "浮滑长脉", "o": "浮滑长脉总属阳脉，主阳热有余、表里俱病之候。其病机可归纳为三类：一为表邪未尽，浮象突出，邪在肌表；二为阳明里热壅盛，滑长并见，右关有力，热邪内蕴；三为阳气偏盛，三阳脉合，正气抗邪有力。此外，浮滑长可与他脉兼夹，形成一阴三阳、一阴二阳等组合，反映阴阳多少与病情兼", "c": "主表邪"}, {"id": "c:弦+浮+濡", "n": "浮濡弦脉", "o": "浮濡弦脉总起来主暑湿郁表、疟邪客于少阳之证。浮为在表，示外邪侵袭；濡为湿滞，示湿邪困阻；弦主疟，示疟邪客于少阳；驶即数，主热，示暑热内盛。四者相合，反映暑湿外袭、疟邪未解、热郁于表的病机。各脉象并非孤立，浮与濡合示表湿，弦与数合示疟热，共同构成暑湿疟邪交织的复", "c": "主表"}, {"id": "c:数+沉+浮+濡", "n": "浮濡沉数脉", "o": "浮濡沉数脉总起来主湿热合邪、表里俱病，尤以湿热浸淫筋脉所致痿软为典型。其脉象由濡、数、浮、沉四要素复合而成：濡主湿，数主热，浮主表，沉主里，故浮濡沉数并见，既揭示湿与热合，又表明表里皆热。三分类中，‘主湿热’为病性总纲，‘主表里俱热’为病位分布，‘主湿热痿软’", "c": "主湿热"}, {"id": "c:滑+浮+濡", "n": "浮濡滑脉", "o": "浮濡滑脉总属虚实夹杂之象。浮主邪在表，濡主气虚湿滞，滑主痰湿或瘀血内蕴。合而观之，其病机核心为正气亏虚（气虚、营卫俱虚）基础上，兼有湿浊、痰浊、瘀血等病理产物内蕴，并常伴外邪束表。案495新产营卫俱虚，宿瘀留恋下焦，风寒包热于肺，脉浮濡带滑，呈虚实夹杂、瘀与邪", "c": "主气虚湿滞"}, {"id": "c:细+浮+小+濡", "n": "浮濡细小脉", "o": "浮濡细小脉总起来主外风引动内湿食滞、气血不充之证。浮脉主外风袭表，为风邪搏结于外；濡细主湿食内阻、气血不充，为湿滞食积于内。三者相合，反映外有风邪、内有湿食交阻、气血不足的复合病机。外风与内湿食相互引动，脾胃升降失司，气机不畅，故见身微热、舌苔白、腹痛水泻。各", "c": "外风袭表"}, {"id": "c:浮+濡+弱+缓", "n": "浮濡缓弱脉", "o": "浮濡缓弱脉总主气虚湿滞、脾胃不足、气血两虚之候。浮濡为气虚湿滞，缓弱为脾胃不足、气血两虚，四脉合见，提示内伤虚损，非外感风邪。其核心病机为脾胃虚弱，气血生化不足，气虚无力运化，湿浊内滞，肌肤经络失养，清阳不升。三者相互关联：脾胃不足为根源，气血两虚为结果，气虚", "c": "主气虚湿滞"}, {"id": "c:浮+濡+缓", "n": "浮濡缓脉", "o": "浮濡缓脉总以气虚为本，兼涉表虚、脾肺气虚、脾虚湿困、肾虚水泛及劳倦伤酒等。浮为气虚外浮或表虚不固，濡为气弱不敛、湿滞，缓而无力为脾胃中虚、运化不及。诸段多因形肥、年逾四十、劳倦、酒色而发，症见精神倦、饮食少、自汗、痰嗽、水肿、疟、瘛疭等，汪石山多断为气虚，非阴", "c": "主气虚"}, {"id": "c:浮+濡", "n": "浮濡脉", "o": "浮濡脉总以虚为本、以湿为标，浮为气浮于外或邪在表，濡为湿滞、气弱不敛。其主病机可归纳为气虚、湿滞、表证、脾虚湿困、肾虚水泛、虚火/虚阳上浮、暑湿/湿热七类。诸类之间常相兼夹：气虚则卫外不固而易感外邪，故气虚与表证并见；脾虚运化失职则湿困中焦，故脾虚湿困与湿滞相", "c": "主气虚"}, {"id": "c:滑+浮+牢", "n": "浮牢滑脉", "o": "浮牢滑脉总起来主邪实内结、气机壅闭之实证，尤以关格为典型。其脉象浮牢相兼，示邪气坚结于外；滑直并见，示气机壅实于内。原文论关格由阴阳气不和、营卫不通，阴阳俱盛不得相营，致气痞结腹内胀满，二便俱不通。三类病机相互关联：邪结为因，气壅为果，关格为具体病证。浮牢主邪", "c": "主关格"}, {"id": "c:浮+牢", "n": "浮牢脉", "o": "浮牢脉总起来主邪实内结、气机壅闭之实证。其脉浮而牢，浮示邪气偏表或浮越，牢示坚结内着，合而主积邪内结、寒实坚结及气机壅闭三类病机。原文论积聚脉象，浮而牢为积病脉之一，贲豚由寒邪留结、脏气传变而成；又论关格由阴阳气不和、营卫不通，阴阳俱盛不得相营，致气痞结腹内胀", "c": "主积邪内结"}, {"id": "c:大+沉+浮+短", "n": "浮短沉大脉", "o": "浮短沉大脉总起来主气郁、血瘀、痰喘、血虚四类病机，核心在于气郁。因怒致气机郁滞，肝脉弦大时一结，肺脉沉大有力，脾胃沉涩，两尺沉而无力，显示气郁为本，进而气滞血瘀，症见面青爪黑、崩漏不止；气郁化火，炼液成痰，痰喘气促；久崩去血极多，气血亏虚，羸瘦食少。四类之间以", "c": "主气郁"}, {"id": "c:浮+短", "n": "浮短脉", "o": "浮短脉总起来以浮为邪在表、短为气不足与脉道不利为基本特征，所主病机可归纳为四类：正虚邪盛、气机壅滞、肺金平脉、毒邪痰湿。其中正虚邪盛为浮短脉最核心的病机，如中风脉浮短多凶，示气血难续；气机壅滞则见于浮大短、浮滑短等兼脉，反映邪实壅盛或毒邪夹痰湿阻滞；肺金平脉为", "c": "主正虚邪盛"}, {"id": "c:弦+浮+空", "n": "浮空弦脉", "o": "浮空弦脉总属虚实夹杂之候。浮脉主邪在表，弦脉主邪实壅滞，空脉按之中空主元气亏虚。故其病机一为邪实壅肺，二为元气虚衰。二者看似相反，实可并见：邪气壅盛于肺，久则耗伤元气，形成邪实正虚之局。原文辨实喘与虚喘，实喘脉浮洪，虚喘脉微弱，浮空弦脉兼具浮弦与空象，提示邪实", "c": "主邪实"}, {"id": "c:浮+空", "n": "浮空脉", "o": "浮空脉总属虚候，以正虚为本，浮为气浮于外，空为脉道不充。其病机主要有四：一为气虚，诸部脉虚，脏腑气弱；二为阴血亏虚，脉道失充，多见于下焦阴亏或热病伤阴；三为虚阳外浮，阴不制阳，阳无所附，可见虚性寒热或温病邪热外浮；四为邪实正虚，痰热、表邪壅盛而元气已衰，脉兼弦", "c": "主气虚"}, {"id": "c:浮+小+紧", "n": "浮紧小脉", "o": "浮紧小脉总起来主表寒实证，并提示表里同病及误下变证。浮主表，紧主寒，小脉在此段未明确论及，但结合原文，浮紧为风寒束表、卫阳被遏之象。在阳明中风背景下，脉浮紧说明表邪未解，里有热象，属表里同病；此时若误下，则表邪内陷，气机壅滞，出现腹满、小便难等变证。因此，浮紧", "c": "主表寒"}, {"id": "c:弦+浮+紧", "n": "浮紧弦脉", "o": "浮紧弦脉总起来主外寒引动内饮、寒伤少阴、阳浮戴阳之证。浮紧为寒邪束表，弦为水饮内停或寒入少阴。两类病机常相兼为患：外寒束表则肺气不宣，水湿泛滥而为风水相搏；寒邪乘虚直入少阴，则逼水中之火飞越于上，成戴阳重症。其核心在于寒邪为患，或兼水饮，或兼虚阳浮越，病位涉及", "c": "主外寒束表"}, {"id": "c:数+浮+紧", "n": "浮紧数脉", "o": "浮紧数脉总属表邪、热壅、寒束相兼之脉。浮主病位在表，紧主寒主痛主闭，数主热主邪正相争，三象合见，总以表里同病、寒热错杂为枢。其所主病机，或为单纯表邪未解（如太阳伤寒），或为湿热挟滞壅于肠胃、肌肤、筋骨，或为寒热交织、表盛里虚，或为邪壅气血而痛，或为痰痧闭阻心窍", "c": "主表邪"}, {"id": "c:滑+浮+紧", "n": "浮紧滑脉", "o": "浮紧滑脉总起来主外寒束表、痰饮内搏，以及表寒里饮、痰热壅肺等复杂病机。浮紧为寒邪外束肌表，卫阳被遏；滑为痰湿内蕴，或痰浊瘀滞。三者相合，提示外寒引动内饮，表闭与里饮同病，症见寒热无汗、咳嗽气喘、难于平卧、痰秽如脓等。若兼胃有蕴热，则痰热交结，壅塞肺叶，发为肺痈", "c": "主痰饮内搏"}, {"id": "c:细+浮+紧", "n": "浮紧细脉", "o": "浮紧细脉总起来主外感风寒、表邪郁闭，兼见正气不足或里虚寒盛之病机。浮主表，紧主寒，细主正虚或寒邪收束，三象合参，提示寒邪束表而营卫郁滞，且常兼气血不足或阳气不振。其具体所主，一为太阳正伤寒，寒邪闭表，无汗烦躁；二为产后正虚感寒，表里皆邪，里冷益深；三为疮疡兼表", "c": "主表寒"}, {"id": "c:浮+紧", "n": "浮紧脉", "o": "浮紧脉总属风寒外束、表实之象。浮主邪在肌表，紧主寒邪收引，二者相合，反映风寒袭表、卫阳被遏、营阴凝滞的基本病机。其具体所主，约分七类：一为风寒表实，见恶寒发热无汗身痛；二为风水相搏，风激水溢而浮肿；三为外风袭表，如破伤风、风邪中络；四为寒凝气滞，寒邪收引致气机", "c": "主风寒表实"}, {"id": "c:细+沉+浮+小+紧", "n": "浮细小沉紧脉", "o": "浮细小沉紧脉在此段总起来主邪结于里、气机壅塞之病机，具体分三类：一为热毒结聚心胸之结胸，脉见寸浮关沉，属热实内结；二为表邪未解，脉浮而大，误下则逆；三为阴寒凝结之脏结，脉见关上细小沉紧，属阳虚寒结。三类虽寒热虚实不同，但共同反映邪气结聚、气机不通之本质。浮脉主", "c": "主热毒结胸"}, {"id": "c:数+弦+细+浮", "n": "浮细弦数脉", "o": "浮细弦数脉总属虚实夹杂之象，以阴血不足为本，肝火内郁为标。浮细主阴血亏虚，脉道不充；弦数主肝火内郁，火热鼓动。二者相合，反映肾阴亏虚、肝阳偏旺、虚火内扰的病机，即“肾虚肝旺”。此脉既非单纯气虚（如脉软无力、变动不常），亦非实火亢盛，而是阴亏火旺、本虚标实。四类", "c": "主阴血不足"}, {"id": "c:细+浮+弱", "n": "浮细弱脉", "o": "浮细弱脉总属虚象，以气血两虚、血衰为核心，兼见表虚不固、虚风外扰与下焦亏虚。浮为气虚外浮或虚阳上浮，细弱为阴血衰少、脉道不充，故非表实而主虚。其病机层次：下焦肾肝精血亏虚为血衰之根；气血不足则卫外不固，形成表虚之证；血虚不荣、虚风乘袭，又见虚风外扰之标。原文下", "c": "主气血两虚"}, {"id": "c:数+细+浮+动", "n": "浮细数动脉", "o": "浮细数动脉总起来主阳气虚浮、阴血不足、有热及胃气未复之病机。浮为阳气外越，细为阴血不足，数为有热，动为肾间动气冲鼓。诸类相互关联：阳气虚浮则不能内守，阴血不足则脉道不充，热邪内扰则脉数，胃气未复则气血生化乏源，脉色不润。原文以温药后动气收、脉数乃寒气将散阳气来", "c": "主阳气外越"}, {"id": "c:数+细+浮", "n": "浮细数脉", "o": "浮细数脉总起来主阴血不足、虚热内扰，兼有外邪未解或虚阳外浮之病机。细为阴血亏虚、脉道不充，数为有热，浮为邪在表或虚阳外越。三者相合，非单纯表证或实热，而是正虚邪恋、虚热交织之候。原文三段分别见微热而脉浮细数、大渴大汗而脉不浮而细数、温病多日脉浮数而细，均示阴分", "c": "主虚热内扰"}, {"id": "c:细+滑+浮", "n": "浮细滑脉", "o": "浮细滑脉在古籍中仅见一段论述，其核心主病为“伤饮”。浮脉主邪在表或在上，提示饮邪初伤、病位偏浅；细脉主饮湿内蕴、脉道受抑；滑脉主饮邪流溢、气血尚充。三象合参，反映饮邪初伤人体，尚未深入沉结，故脉象仍带浮滑。此脉所主病机较为单一，以饮邪伤中为主，未见其他病机类别", "c": "主饮"}, {"id": "c:细+浮+结", "n": "浮细结脉", "o": "浮细结脉总起来主阴虚火动、气血涩滞、虚阳外浮。浮为虚阳外浮，细为阴血不足，结为气血涩滞，三者相合，反映阴血亏虚、阳气失守、脉道不利的复杂病机。原文两段均治年五十余形瘦黑理疏者，因劳欲伤及心肾，阴虚火动，故见腹痛午后愈甚；止脉疏密可辨热之进退，痛甚时止脉疏因热动", "c": "主阴虚火动"}, {"id": "c:细+浮+弱+缓", "n": "浮细缓弱脉", "o": "浮细缓弱脉总属虚象，以血衰为核心，兼见虚风外扰与下焦亏虚。浮缓无力非表实，乃气血不足、卫外不固而虚风乘袭；细弱按之无力为阴血衰少、脉道不充；尺脉尤甚则下焦肾肝精血亏虚。三者相互关联：血衰为本，虚风为标，下焦亏虚为血衰之根。原文两段均断“病属血衰”，以四物汤加味", "c": "主血衰"}, {"id": "c:细+浮", "n": "浮细脉", "o": "浮细脉总属正虚邪恋、本虚标实之候。浮为气虚外浮、虚阳上越或表邪未尽，细为阴血亏少、脉道不充，二者相合，以虚为本。其所主病机可归为五类：一主气血阴阳亏虚，为浮细之基础；二主虚阳外浮，乃阴不敛阳、阳气失守之变；三主表虚邪恋，为外邪未解而正已伤；四主肝郁化火，因虚而", "c": "主虚（气血阴阳亏虚）"}, {"id": "c:浮+结", "n": "浮结脉", "o": "浮结脉总起来主虚损、气血涩滞、阴虚火动及热郁上焦等病机。浮为虚阳外浮，结为气血涩滞，二者相合，既可因正气虚衰而见，又可因阴血亏虚、阳气失守而致，还可因热郁于上、气滞血瘀而成。各类病机之间相互关联：虚损可致气血涩滞，阴虚火动可伴虚阳外浮，热郁上焦可兼气滞血瘀。浮", "c": "主虚损"}, {"id": "c:数+浮+小+缓", "n": "浮缓小数脉", "o": "浮缓小数脉总起来主风火相搏、表热内蕴兼正气不足之病机。浮为风，数为火，缓小示风火相搏而正气不足，故其病机核心为风火为患，或上攻头面清窍，或外袭肌表而兼里热。两类病机相互关联：风火在表可循经上攻，形成头胀、齿痛、耳聋等症；而缓小之象又提示正气不足，抗邪无力，故病", "c": "主风火"}, {"id": "c:浮+弱+缓", "n": "浮缓弱脉", "o": "浮缓弱脉总属虚象，以肾虚为本，气血不足为基，虚阳外越为标。浮缓非表实，乃气血不足、卫外不固；弱脉主虚，两尺尤甚则肾虚精亏。原文肾虚寒极生热，面赤倦怠，渴热昏闷，脉浮缓弱，断为虚阳外越之假热，非真热。故其病机核心为肾虚寒盛、气血亏虚，虚阳浮越于外。三类相互关联：", "c": "主肾虚"}, {"id": "c:数+浮+缓", "n": "浮缓数脉", "o": "浮缓数脉总起来主风邪为患，兼有冷、热、虚之不同。浮为风，缓为风性弛纵或正气不足，数则为热。浮缓不数主风冷，沉缓主风邪内伏，左关浮弦主风入肝胆，右关浮缓主风伤肠胃，而浮缓小数则主风火相搏、表热内蕴兼正气不足。诸类病机皆以风邪为核心，或兼冷、或兼热、或兼虚，或内伏", "c": "主风冷"}, {"id": "c:滑+浮+缓", "n": "浮缓滑脉", "o": "浮缓滑脉总起来主风邪在表、营卫不和、痰湿内蕴及气阳两虚。浮为风邪袭表，缓为营卫失调、卫阳不固，滑为痰湿内停。三者相合，反映外有风邪乘虚而入，内有脾肺气虚、痰湿内蕴之病机。其核心在于劳力伤阳，卫外失护，风邪入于肺俞，致营卫不和；脾肺气虚则痰湿内生，故脉见浮缓而滑", "c": "主风邪在表"}, {"id": "c:浮+紧+缓", "n": "浮缓紧脉", "o": "浮缓紧脉总属太阳表证脉象，以浮为纲，缓紧为目。浮缓主中风表虚，亦主温病表郁；浮紧主伤寒表实，亦主寒邪束表。四类病机均围绕外邪袭表、营卫失调，区别在于风、寒、温邪性质及表之虚实。浮缓与浮紧可相互转化或兼见，反映病邪性质与体质反应。", "c": "主中风"}, {"id": "c:浮+缓", "n": "浮缓脉", "o": "浮缓脉总以浮为邪在表或气虚外浮，缓为风、湿、脾虚之象。其主病机可归纳为风邪伤卫、风湿郁表、太阴湿困、气虚脾弱、虚阳上浮、湿滞中焦及疟疾等类。风邪伤卫者，营卫不和，见有汗恶风；风湿郁表者，湿性黏滞，身重发热；太阴湿困者，脾土湿郁，可发黄或转阳明；气虚脾弱者，中气", "c": "主风邪伤卫"}, {"id": "c:浮+弱+缓+迟", "n": "浮缓迟弱脉", "o": "浮缓迟弱脉总起来主胃气虚弱、阳气不足、津液不布所致的阴结证。浮缓侧重胃气虚弱，迟弱侧重阳气不足、津液不布，四者相合，反映中焦虚寒、运化无力、大肠传送失职。其病机核心为虚寒内结，而非实热壅滞。原文患者胸腹胀痛、大解不通，却身无寒热、口不作渴、舌无苔积，且服枳桔香", "c": "主胃气虚弱"}, {"id": "c:浮+缓+实+长", "n": "浮缓长实脉", "o": "浮缓长实脉总起来主邪在阳明肌表及风寒外客之病机。其脉浮主表，缓主风或肌表疏松，长实主邪气盛实。从所收两段原文看，以脉辨头痛所属经络，明确浮缓长实为邪在阳明肌表，症见自汗发热恶寒；引东垣论头痛，列浮缓长实脉，示风寒外客所致头痛。两类病机均属外感表证范畴，一者侧重", "c": "主邪在阳明"}, {"id": "e:浮", "n": "浮脉", "o": "浮脉总属阳脉，其基本病机为邪在表分或阳气浮越于外。归纳其要，约分七类：主表证为浮脉最直接之义，外邪袭表，卫阳浮盛，脉应之浮；主风邪与主表证相兼，风性轻扬，善行数变，浮为风象；主热者，热盛气张或郁热外达，脉浮有力；主水气者，水湿泛溢或饮邪上迫，脉浮示病位偏表偏上", "c": "主表证"}, {"id": "c:大+浮+虚+濡+芤", "n": "浮芤濡虚大脉", "o": "浮芤濡虚大脉总属虚脉，主气血虚衰、血脱及肺脾肾气虚。其脉浮而大，按之芤濡无力，为气血不足、血脱气浮之象。原文以“沉迟微芤皆气血虚衰之象”统括之，并指出“脉浮而芤濡虚大、迟缓无力……皆虚而不足”，可用人参补益。李月池更以面白面青、黄或黧悴为肺脾肾气不足之症，与此", "c": "主气血虚衰"}, {"id": "c:浮+芤", "n": "浮芤脉", "o": "浮芤脉总以浮为阳热或气浮，芤为阴血津液亏伤为基本病机，二者相合，多示热盛伤津、血络受损或阴虚阳浮之候。所主病机可归为五类：津亏血伤、热盛胃实、肺络损伤、痧毒犯经、阴虚阳浮。其中津亏血伤是核心，贯穿诸段；热盛胃实侧重阳热与阴伤相搏，胃燥津竭；肺络损伤与痧毒犯经均", "c": "主津亏血伤"}, {"id": "c:弦+浮+虚+缓", "n": "浮虚弦缓脉", "o": "浮虚弦缓脉总属阳虚，尤以脾阳不足、阳气外浮为要。浮虚为阳虚外浮，弦缓为阳气不足、脾土失温，故脉缓无力主阳虚。原文参症两足时冷、身多畏寒，皆阳虚之验；易饥善食乃脾胃阳虚无以运化、借谷气自救；汗多则亡阳，更致阳虚外浮。诸类均以阳虚为根本，脾阳不足为常见病位，汗多亡", "c": "主阳虚"}, {"id": "c:数+浮+虚", "n": "浮虚数脉", "o": "浮虚数脉总起来主正虚邪陷、余热未清之候。其脉浮为邪未尽解，虚为正气已伤，数为余热未清，三者合观，乃肺胃温邪乘虚陷入阴经，湿热无形之邪变作有形之滞。所主病机可归纳为虚、热、邪陷、湿热滞四类：虚为根本，因正气先亏而邪易内陷；热为病势，余热未清而见数脉及口渴、肛热；", "c": "主虚"}, {"id": "c:浮+虚+涩", "n": "浮虚涩脉", "o": "浮虚涩脉总主风湿表虚、阳弱湿滞之证。浮为风邪在表，虚为阳气不足，涩为湿滞血行不畅，三者相合，反映风、湿、虚交织于肌表经络。其核心病机为风湿相搏而表阳已虚，故见身体疼烦、不能自转侧、不呕不渴、汗出恶风等症。三类病机相互关联：风邪在表故浮，卫阳不足故虚，湿阻血滞故", "c": "主风湿在表"}, {"id": "c:大+浮+虚+弱+缓", "n": "浮虚缓弱大脉", "o": "浮虚缓弱大脉总属虚候，主气不内守、脾阳大伤、虚阳浮越及久病虚损。其脉浮而虚，为气浮不敛；缓而弱，为脾阳衰微；虽大而不甚大，非邪实之洪大，乃虚阳外浮之象。诸类相互关联：久劳久疟耗伤脾肾，脾阳大伤则运化失职，气虚不守则浮越于外，终致虚阳上浮、气不归元。原文以脉不弦", "c": "主气虚不守"}, {"id": "c:浮+虚+缓", "n": "浮虚缓脉", "o": "浮虚缓脉总属阳气虚衰、正气不足，以阳虚气弱为核心病机。浮为虚阳外浮或气浮于外，虚为鼓动无力、精血不充，缓为阳气弛缓、气血不足。三类病机相互关联：阳虚为根本，脾阳不足为阳虚之具体脏腑表现，正虚邪恋则为阳虚气弱、久病正溃之危重转归。原文三案均见浮虚缓脉，或伴弦象，", "c": "主阳虚"}, {"id": "c:浮+虚", "n": "浮虚脉", "o": "浮虚脉总以'浮'示病位偏表或虚阳外浮，'虚'示正气不足为核心，总主正虚感邪、气血亏虚、阳虚水湿、虚阳浮越及虚热上浮诸类病机。其浮为风邪在表或虚阳外越之象，虚为营卫气血不足之本质，故常见于表虚感风、劳倦伤中、产后脱血、脾虚木乘等证。各类之间以'正虚'为共同基础：", "c": "主表虚风邪"}, {"id": "c:大+浮+软", "n": "浮软大脉", "o": "浮软大脉总起来主气虚湿盛、血虚有热，并可反映正虚邪实之危候及脾不统血。其核心病机为气虚无力运化，湿浊内停，故脉浮软而大；若兼左脉虚软小近驶，则示血虚有热。在危重病中，浮软大脉又常与沉细虚小对举，用以判断正气尚存、邪有外达之机，如伤寒热盛、水病胀闭见浮大软者生；", "c": "主气虚湿盛"}, {"id": "c:数+浮+小+软", "n": "浮软小数脉", "o": "浮软小数脉总起来主风邪上攻、正虚邪恋之候。浮脉主风邪外袭，软小脉主高年气血不足，数脉主邪郁化热，三者相合，反映正虚与邪恋并存的病机格局。其中风邪上攻为标，气血不足为本，邪郁化热为风邪留恋之变。四类病机相互关联：因正虚而邪易袭，因邪袭而郁化热，因正虚而邪难速去，", "c": "主风邪上攻"}, {"id": "c:浮+软+散", "n": "浮软散脉", "o": "浮软散脉总起来主神志浮越、精气不敛之病机。其脉浮为气浮于外，软散为神志涣散、精气不能内守。原文虽见精泄不禁、自汗头眩、虚极寒热等虚象，但王氏明确指出“非虚也，亦非房室过度”，而是心有所慕、欲想不遂，致神不归、志不宁。故三类病机相互关联：神志浮越是根本，精气不敛", "c": "主神志浮越"}, {"id": "c:浮+软", "n": "浮软脉", "o": "浮软脉总以虚为本，主气虚、血虚、虚火浮越，兼主风暑湿邪在表及正虚邪恋。其脉浮而软，浮为气浮于外，软为无力，故首主气血亏虚、中气不固；虚甚则阳浮，虚火上升，迫血上溢，故又主虚火。若外邪侵袭，风暑挟湿，营卫失和，脉亦浮软，此为表邪兼湿；若正虚而邪恋，脉浮软无力，则", "c": "主气虚"}, {"id": "c:浮+濡+迟", "n": "浮迟濡脉", "o": "浮迟濡脉总主表虚、阳弱、湿滞，核心病机为脾胃本虚、痰湿内滞兼表气不固。浮为表虚，卫外不固则汗多；迟为阳弱，阳气不足则神倦；濡为湿滞，脾虚不运则痰湿内生。三者相合，反映热退邪余之际，正气未能骤复，脾胃虚弱，痰湿留恋，表虚不固。此脉以虚为本，湿为标，阳弱与表虚并见", "c": "主表虚"}, {"id": "c:浮+迟", "n": "浮迟脉", "o": "浮迟脉总以浮为虚、为表、为阳浮，迟为寒、为虚、为劳为纲。其主病机可归为虚劳、表寒、里寒、虚极欲脱、中风、寒疝风冷、消渴七类。虚劳与消渴侧重营卫气血不足，浮为卫气虚，迟为营气竭；表寒与中风侧重风寒袭表，浮为邪在表，迟为寒凝经脉，正气尚存；里寒与寒疝风冷侧重阴寒内", "c": "主虚劳"}, {"id": "c:浮+长", "n": "浮长脉", "o": "浮长脉总起来主邪实壅盛、阳热亢盛及风邪痰火之病机。浮为邪在表或外候，长为气有余或热盛，故脉浮长多示实邪壅滞、气血亢奋。其具体所主，一为风邪袭表引动痰火，见温病初得作喘；二为阳热亢盛，表里同病，如阳明证脉长而数；三为邪实壅盛、积块内结，尤以脾积为典型。三类之间相", "c": "主风邪痰火"}, {"id": "c:浮+革", "n": "浮革脉", "o": "浮革脉总属虚寒之象，其形成多因误下伤正、中阳不足，致虚阳外浮而内里虚寒，脉道失充。所主病机主要有三：一为虚寒，因革脉中空、浮取即得，示内寒外浮，原文“当温之”可证；二为血虚寒凝，革脉外急中空，为血虚寒客、脉道不充，见肠鸣、当归四逆汤证；三为误下致虚，下利后强下", "c": "主虚寒"}, {"id": "u:涌", "n": "涌脉", "o": "涌脉总起来主邪气上涌、气血痰浊逆乱之病机。其脉来涌涌，或为痰瘀交阻、败血随痰上逆，或为表寒里痰互结、肺气上逆，或为邪气亢盛、正气不能约束而脉无胃气。三类病机均以‘涌’为象，但成因不同：痰血上壅者，本于脾胃大虚，痰瘀互结；表寒里痰者，新寒引动旧痰，表里同病；邪盛", "c": "主痰血上壅"}, {"id": "c:涩+伏", "n": "涩伏脉", "o": "涩伏脉总起来主气机郁滞、气闭不通，兼及血瘀、阳损与脏虚。其脉涩主血滞，伏主气闭，左脉候血，故常见于郁怒伤肝、气机壅塞之证，症见胸脘痛极、昏厥、四肢逆冷；气闭则脉沉涩似伏，气复返则苏。若积劳损阳，阳气亏虚，血行瘀滞，亦见涩伏，伴下瘀血不止、舌白不食，预后难治。此", "c": "主气郁血滞"}, {"id": "c:涩+和", "n": "涩和脉", "o": "涩和脉总起来主血行涩滞、营血亏虚及痰瘀互结之病机，核心为阴血不足与邪滞内阻并存。其主病以瘀血、血虚为根本，痰滞、肝郁为标象。涩脉本主血少或血瘀，兼弦则示肝郁，兼痰则示痰阻。各段原文中，涩象渐和均示瘀滞渐化、血行渐畅，为向愈之兆；涩象未净则示邪恋未解。故涩和脉所", "c": "主瘀血"}, {"id": "c:涩+坚", "n": "涩坚脉", "o": "涩坚脉总起来主邪实与正虚相兼之病机，核心为气血壅滞、脉道不利。涩主血少、气滞、血瘀，坚主邪实、寒凝、收引，故其病机涉及血实气虚、中焦虚滞、邪结中焦、表邪深入及胀病实邪等多类。各段原文显示，涩坚脉既可因血实气滞而见腹痛逆满、结瘕，又可因脾虚血少、中焦气滞而见腹胀", "c": "主血实气虚"}, {"id": "c:大+涩", "n": "涩大脉", "o": "涩大脉总起来主病机以血虚液亏、气滞血瘀为基础，兼涉热盛瘀滞、寒凝气滞、胃逆血耗及虚实夹杂等多类。涩主血少、气滞、瘀阻，大主邪实、气浮或虚阳外越，二者并见，既可因阴血亏虚、脉道不充而见血虚液亏，也可因气血壅塞、瘀热互结而见气滞血瘀或热盛瘀滞；寒邪内盛、血凝脉阻则", "c": "主血虚液亏"}, {"id": "c:滑+涩+弱", "n": "涩弱滑脉", "o": "涩弱滑脉总属虚中夹实之象。涩主血少行滞，弱主气虚不充，滑主湿痰水饮。三脉并见，提示气血两虚为本，湿滞水停为标。产后气血亏耗，脾虚运化无力，水湿内停，故见便泻、跗浮、苔滑；胃气未复则嘈杂少谷。虚象与湿滞并存，治当分利水湿兼顾扶正。", "c": "主气血两虚"}, {"id": "c:涩+弱", "n": "涩弱脉", "o": "涩弱脉总主虚损，以气血两虚、阴血亏耗为核心，兼及肝肾虚损、阳虚寒凝，并可因虚致瘀、因虚禁下。涩主血少行滞，弱主气虚，合见则正气不足、脉道不充。各段所主虽有气血、阴血、肝肾、瘀血、寒凝之异，然皆不离“虚”字：或气血两伤不能充养，或阴血耗损脉道涩滞，或肝肾精血不足", "c": "主气血两虚"}, {"id": "c:微+涩+弱", "n": "涩微弱脉", "o": "涩微弱脉总起来主虚候，以阳气虚衰、元气大虚为核心，涉及肾气衰败、气血虚衰及胎元不固。其脉象微为阳衰，弱为气弱，涩为血行不畅，合而示鼓动无力、脉道不充。在尺部见之，按之无根，则肾气衰败，胎失所养，故主胎元不固；与微滑不绝之胎脉对举，更显真气不全。各类之间以虚为纲", "c": "主胎元不固"}, {"id": "c:数+涩+弱", "n": "涩数弱脉", "o": "涩数弱脉总属虚实夹杂之象，以气血两虚为本，兼见虚热、瘀热及肝木乘脾。涩主血少行滞，弱主气虚，数主虚热内扰，三者相合，反映产后气血大伤、虚热内生、瘀血留滞、肝脾失调的复杂病机。各证类之间相互关联：气血两虚是基础，虚热由血虚而生，瘀热因血室空虚留瘀随热而入，肝木乘", "c": "主气血两虚"}, {"id": "c:数+涩", "n": "涩数脉", "o": "涩数脉总起来主'阴血亏虚兼郁热'之病机，其核心为涩主血少、精伤、气滞、血瘀、痰湿阻络，数主热，包括虚热、郁热、湿热、瘀热及虚阳浮动。各类之间常相互转化或兼夹：血虚阴亏可致阴虚火旺，虚火灼津又可成瘀成痰；气郁血滞可化郁热，郁热日久则伤阴耗血；湿热痰浊内蕴可阻碍气", "c": "主血虚阴亏"}, {"id": "c:数+弦+沉+涩", "n": "涩沉弦数脉", "o": "涩沉弦数脉总起来主气郁血滞、伏热内蕴，兼见血虚风动、湿痰、金水两虚等复杂病机。其核心在于'郁'与'滞'：沉弦主气郁，涩主血滞，数主伏热，三者相合，多因情志抑郁致气机不宣，暑邪内伏，血为邪踞而不流行，故见胁腹梗塞、凛寒发热等症。若兼见涩数不调，则示血虚肝风暗动；", "c": "主伏热"}, {"id": "c:滑+大+涩", "n": "涩滑大脉", "o": "涩滑大脉并见，总属虚实夹杂、上盛下虚之候。左涩主血少血瘀，为失血后阴亏与瘀滞并存；右寸关滑大主痰火壅于中上焦，为标实之象；两尺弱主下元虚惫，为本虚之根。三象合参，揭示上焦痰火未清、中焦脾弱、下元不足的复杂病机。其关系为：下元虚惫为本，痰火壅盛为标，血少血瘀为失", "c": "主血少血瘀"}, {"id": "c:涩+疾", "n": "涩疾脉", "o": "涩疾脉在古籍中仅见于“人为百药所中伤”一段，其核心病机为邪毒内扰、血行不畅。脉涩主血行涩滞，脉疾主邪毒急迫，二者相合，反映毒邪入中、气血受扰而正气尚能抗邪的病理状态，故原文断为“生”。此脉所主以邪实为主，兼有血行不利，与微细脉所主正虚邪陷形成鲜明对比，提示临证", "c": "主邪毒内扰"}, {"id": "c:细+涩+空", "n": "涩空细脉", "o": "涩空细脉总属阴血亏虚、肝木失养、虚风内动之候。涩主血少，空为营阴亏虚，细主阴血不足，三者并见，反映心肾阴亏为病之本。阴血不足，肝木失涵，则筋脉失养而四肢麻木；阴虚不能制阳，则风阳窃动。三类病机以阴血亏虚为核心，肝木失养为中间环节，虚风内动为标象，相互关联，治当", "c": "主阴血亏虚"}, {"id": "e:涩", "n": "涩脉", "o": "涩脉总主气血运行不畅，其病机有虚实两端。虚者精血亏虚、阳气衰微，脉道不充而涩；实者气滞血瘀、湿痰郁热，脉道受阻而涩。上述七类中，精血亏虚、阳虚寒凝属虚，气滞血瘀、湿滞痰阻、郁热内结属实，虚风内动、正虚邪恋属虚实夹杂。各类之间常相互转化兼夹：精血亏虚可致脉道涩滞", "c": "主精血亏虚"}, {"id": "c:滑+动", "n": "滑动脉", "o": "滑动脉总主痰、食、热、胎及虚郁等病机，其核心为实邪壅滞与气血充盛。滑脉往来流利，应指圆滑，主痰饮内蕴、宿食停滞，此二者为实邪阻滞气机，脉气壅盛而滑；痰热相搏则滑而兼数，痰郁心胆则滑而兼动弦。妊娠血聚养胎，冲任充盛，脉亦滑动摇摆，为生理之滑。若滑而按之不实，则属", "c": "主痰积"}, {"id": "c:滑+缓+和", "n": "滑和缓脉", "o": "滑脉总以往来流利、如盘走珠为特征，主气实血壅之候。其病机类别主要有痰食内积、内热亢盛、妊娠气血充盛、营卫充实（平人）及邪热壅盛。痰食与内热常相兼为患，皆因实邪壅滞气血；妊娠与营卫充实属生理性滑脉，为气血充盛之象；而过于滑大则提示邪热壅盛。各类之间以‘气实血壅’", "c": "主痰食"}, {"id": "c:滑+大+小", "n": "滑大小脉", "o": "滑大小脉总以滑象为主，兼见大小不均，主病机集中在胃腑。滑为阳脉，主热、主痰、主动，故其核心病机为胃中积热与虫动吐逆；大小不均示邪气壅滞、气机逆乱，故见吐逆、多饮、注利等症。若兼浮大则风邪在胃，兼紧滑则蛔动，兼实坚则中焦实热伏结。诸类之间以胃热为共同基础，热盛则", "c": "主胃热积热"}, {"id": "c:滑+大+平", "n": "滑大平脉", "o": "滑大平脉在此段中总起来主痰湿内蕴、邪势尚盛，并示转机之象。滑脉主痰湿，大脉主邪盛，二者相合，反映痰湿与邪气交结为患。然二诊时脉滑大稍平，说明经升泄之法后，陷里之邪略得升散，脾之清气稍得升举，痰湿与邪势均较前减轻，故脉象转和，为疾病向愈之转机。三类病机相互关联：", "c": "主痰湿"}, {"id": "c:数+滑+大", "n": "滑大数脉", "o": "滑大数脉总起来主痰热、邪热炽盛，兼涉湿热壅阻、风痰热及上实下虚等病机。滑为痰湿，数为热，大为邪盛，三者相合，核心病机是痰热内盛、邪热炽张。具体而言，或痰热壅肺胃，或湿热阻气机，或痰热生风，或邪热内闭，或上焦痰实而下元亏虚。各段原文多从滑、数、大分别释义，再合而", "c": "主痰热"}, {"id": "c:滑+大", "n": "滑大脉", "o": "滑大脉总以痰湿壅盛、邪气盛实为基本病机。滑主痰湿食积，大主邪盛热实，二者相合，多主实证、热证、痰证。具体而言，或痰湿内阻，或痰热壅盛，或食积停滞，或实热内炽，或风痰上扰；若兼尺脉沉弱，则为上实下虚；若滑大无力，则属正虚邪盛。各类之间常相互兼夹，如痰湿可化热成痰", "c": "主痰湿"}, {"id": "c:滑+大+虚", "n": "滑大虚脉", "o": "滑大虚脉总起来主痰热内蕴、虚火上炎，兼津液亏耗。其滑主痰，大主热，虚主不足，三者相合，提示痰热未清而阴津已伤，形成虚实夹杂之候。原文中右脉候肺胃，痰热阻滞气机，津液不布，故见口燥舌干；虚火挟痰熏蒸胃口，恐发口糜。各类病机相互关联：痰热为标，虚火为因，津亏为果，", "c": "主痰"}, {"id": "c:滑+实+坚", "n": "滑实坚脉", "o": "滑实坚脉总属痰湿、邪积、有形滞结聚之实证。滑主痰湿内盛，实主邪气积滞，坚示有形之滞，三者相合，反映痰湿与积滞浑结、表里之邪无出路、气机壅塞之病机。原文案中伏邪发疟，表邪传里与肠胃积滞浑结，涩止后邪无出路，挟痰气内蒸，遂见腹满时肿、形浮气逆、便下痰沫，脉象滑实而", "c": "主痰湿"}, {"id": "c:数+滑+实", "n": "滑实数脉", "o": "滑实数脉总起来主邪实热盛、痰湿食积壅结之证。滑为痰湿食积，数主热，实为邪气壅盛，三象合见，提示实热与痰湿食积交结为患。其具体所主，或为痰热内盛，或为湿热交蒸，或为里实热结，或为食痰积滞，或为热毒壅盛，虽表现多样，然皆不离“邪实”与“热盛”两端。痰、湿、食、毒等", "c": "主痰热"}, {"id": "c:滑+紧+实", "n": "滑实紧脉", "o": "滑实紧脉总起来主邪实内盛，以里热燥结为核心。滑主痰热内壅，实主邪气壅盛，紧主痛主实，三象相合，反映热邪与燥屎搏结于阳明之腑，气机壅滞，不通则痛。其具体病机包括里热炽盛、燥实内结、疼痛以及邪实正损。里热炽盛是基础，燥实内结是病位所在，疼痛为燥实阻滞气机之必然表现", "c": "主里热炽盛"}, {"id": "c:滑+实", "n": "滑实脉", "o": "滑实脉总起来主邪实壅盛之证，以痰湿、实热、食积为核心。滑为痰湿食积，实为邪气壅盛，二者相合，提示实邪结聚、正气未衰。其具体所主，或为痰湿壅盛，或为实热内结，或为食积停滞，或为腑实可下，或为痰热扰心，或为湿热壅滞，虽表现多样，然皆不离“邪实”一端。此外，若滑实而", "c": "主痰湿壅盛"}, {"id": "c:细+滑+虚+实", "n": "滑实虚细脉", "o": "滑实虚细脉在小儿脉诊中总以辨虚实为纲。原文强调小儿病情虽难测，但“辨明表里寒热虚实六者则易治”，而脉息之虚实尤为关键。滑实与虚细对举，实者主邪气壅盛，如外感风寒、内伤饮食、惊风痰热等；虚者主正气不足，如吐泻伤津、疳痫耗气、气血两虚等。两类病机相互对照，实为邪实", "c": "主实"}, {"id": "c:滑+虚+实", "n": "滑实虚脉", "o": "滑实虚脉总起来主邪实与正虚两类病机，以辨虚实为纲。滑实脉主邪气壅盛，包括胃火、痰滞、外感、食积、惊风痰热等，其脉象滑主痰滞、实主邪盛，形气不虚则证实为有余之邪；虚细脉主正气不足，如吐泻伤津、疳痫耗气、气血两虚等。原文强调小儿病情虽难测，但辨明表里寒热虚实六者则", "c": "主胃火"}, {"id": "c:滑+小+弱", "n": "滑小弱脉", "o": "滑小弱脉总起来主正气未脱、胃气未败之顺候，多见于血证及外感热病过程中。其脉象滑而小弱，滑示气血尚有流动之机，小弱示脉不张而胃气未败，故虽病而正未大伤。在吐血、衄血中，滑小弱与实大对举，实大主邪热壅盛、正气随脱之死候，滑小弱则主血出而正未脱之生候；在伤寒、温病中", "c": "主血证顺候"}, {"id": "c:滑+大+微", "n": "滑微大脉", "o": "滑微大脉总属虚实夹杂之候，以痰滞、气郁、中虚为三大病机。其形成源于中气虚弱，运化失职，痰湿内蕴；复因肝郁气结，气机不畅，痰随气滞，壅阻机窍。脉滑主痰，微大示痰浊壅滞而形不显，兼见寸脉细滞，为气郁之征。三者相互影响：中虚为痰滞之本，气郁为痰滞之因，痰滞又加重气郁", "c": "主痰滞"}, {"id": "c:数+滑+微", "n": "滑微数脉", "o": "滑微数脉总起来主痰热内蕴，兼有正虚、积滞、络痹之变。滑主痰，数主热，微则示热势不炽或正气不足。四段所载，或体虚有痰、痰热内扰，治须虚实兼顾；或邪势渐去而湿热未清，兼偏左瘕积阻滞；或痰阻阳明、经气不能流通输布，致络痹气逆。诸类之间，以痰热为核心：痰热内蕴则气机不", "c": "主虚痰"}, {"id": "c:滑+急", "n": "滑急脉", "o": "滑急脉总起来主痰气壅盛、寒凝气结、郁热结聚所致的疝瘕急痛。滑主痰气，急主痛甚气逆或脉道拘急，二者相合，反映邪气壅阻、气机逆乱、脉络拘急之病机。其具体类别中，主疝瘕急痛为总纲，痰气壅盛、寒凝气结、郁热结聚为不同病因下的具体表现：寒凝则脉道拘急而痛，痰气则壅塞气逆", "c": "主疝瘕急痛"}, {"id": "c:数+滑+促", "n": "滑数促脉", "o": "滑数促脉总起来主痰、热、气促及壅闭实证。滑主痰，数主热，促为热盛气促、脉行急迫，三者相合，多示痰热内盛、气机壅闭。从原文看，或见伏邪晚发、热伤津液、肝风鸱张之痉厥神昏，或见湿热误补、充斥三焦、痰饮凝滞之胸痞拒按，皆属痰热壅闭之实证。其脉虽偶见歇促、雀啄、解索等", "c": "主痰"}, {"id": "c:数+滑+和", "n": "滑数和脉", "o": "滑数和脉总起来主痰热、燥火、阴亏火旺及余邪留恋四类病机，核心为肺胃痰热渐化而余焰未清，兼肝阴亏耗、木火易炽。右脉滑数较和，右候肺胃，滑主痰、数主热，示痰热渐退而未净；左脉弦数不靖，左候肝胆，示阴液素亏、肝热内炽。四类之中，痰热与燥火偏于标实，阴亏火旺偏于本虚，", "c": "主余邪留恋"}, {"id": "c:数+滑+平", "n": "滑数平脉", "o": "滑数平脉总属痰热为患，以滑主痰、数主热，合为痰热内蕴之象。其病机要点有三：一为痰热壅盛，二为气分热盛，三为痰热渐化、病势向愈。原文“脉之滑数较平”既点明当前痰热渐化、气分热势已减，又通过“胃口渐开，夜能安卧，头痛已痊”“哮喘未作，惟早间稍有咳嗽，气不舒畅”等症", "c": "主痰热"}, {"id": "c:数+弦+滑+紧", "n": "滑数弦紧脉", "o": "滑数弦紧脉总主温疫毒邪化火，充斥内外，蔓延三焦。右脉滑数主火盛痰热，左脉弦紧主邪郁少阳。二者相合，反映疫毒炽盛，邪势鸱张，火邪充斥表里三焦，故见发热咽痛、丹痧连片、颈肿舌红等症。其病机核心为火毒壅盛，兼少阳郁滞，属邪实正盛阶段，需防热毒内陷致神昏发痉。", "c": "主火盛"}, {"id": "c:数+滑+虚+微", "n": "滑数微虚脉", "o": "滑数微虚脉总起来主郁怒伤肝、木旺土衰、痰热内蕴之病机。其脉象由滑、数、微、虚四象复合而成：滑数主痰热，微虚主脾虚，兼见肝脉沉弦有力，则主郁怒伤肝、肝气横逆。四类病机相互关联：郁怒伤肝为始因，肝气横逆则木旺克土，导致脾虚；脾虚运化失职，则生痰湿；痰湿郁久化热，形", "c": "主郁怒伤肝"}, {"id": "c:数+滑+急+疾", "n": "滑数急疾脉", "o": "滑数急疾脉总属火毒内炽、阳热实证。其脉象由滑、数、急、疾复合而成：滑主痰热内壅，数急疾主火势急迫，故全脉反映痰热与火毒交炽、充斥内外之病机。原文列纯阳无阴之证，见发热谵语、狂妄躁乱、大渴大烦、便秘溲赤，断为火毒内炽，脉症相合。三类病机中，火毒炽盛为直接主病，痰", "c": "主火毒炽盛"}, {"id": "c:数+滑+大+洪+长", "n": "滑数洪大长脉", "o": "滑数洪大长脉总起来主热盛、心火亢盛及阳气外浮三类病机。原文以夏月为例，阐明一身之气随四时五运六气兴衰，夏月心火生而热，故脉见滑数洪大而长，伴烦热多渴，绝非寒象。滑数主热邪内盛，洪大而长主心火亢盛、阳气外浮，三者相互关联：热盛为病机基础，心火亢盛为具体脏腑定位，", "c": "主热盛"}, {"id": "c:数+滑+空", "n": "滑数空脉", "o": "滑数空脉总起来主痰火内盛与阴精亏耗并见的复杂病机，其核心为火盛水亏、本虚标实。滑数主痰火，空主阴亏，二者复合反映邪热鸱张而根本已伤。所主病机可归为四类：主痰火、主阴亏、主火盛水亏、主正虚邪盛。其中痰火与阴亏是基础病理要素，火盛水亏是二者相互作用的病机概括，正虚", "c": "主阴亏"}, {"id": "c:数+细+滑+弱", "n": "滑数细弱脉", "o": "滑数细弱脉在此案中并非同时并见，而是病程中脉象由滑数转为细弱，反映病机由实转虚、由气入血的动态过程。总起来看，此脉所主病机以湿热实邪为始，以血液耗残、正气转虚为变，进而导致肝木失柔、虚风内动，终成邪未尽而正已伤之虚实夹杂证。滑数主湿热积滞壅盛于气分，为病之标；", "c": "主湿热实邪"}, {"id": "c:数+细+滑+软", "n": "滑数细软脉", "o": "滑数细软脉总属湿热未清、正气已伤、邪有内陷之势的复合脉象。滑主湿浊内蕴，数主余热未清，细软主正气已伤，三者并见，反映湿、热、虚三者交织，而以湿热内蕴为病机核心。因正虚不能胜邪，热邪易扰心神，故见神糊谵语、舌绛，有邪陷心包之虞。三类病机相互关联：湿热内蕴为病之本", "c": "主湿热内蕴"}, {"id": "c:数+滑", "n": "滑数脉", "o": "滑数脉总以痰、热为核心病机，滑主痰湿、食积，数主热邪，二者相合，反映痰热内蕴、湿热交蒸、积滞化热等实热证候。其具体所主，或痰热壅肺，或湿热阻中，或食积化热，或热盛闭窍，或阴虚挟痰，或妊娠胎火，或暑热痰湿。各类之间以'痰热'为共同基础，常相互兼夹：痰热可兼湿、兼", "c": "主痰热"}, {"id": "c:数+滑+虚+软", "n": "滑数虚软脉", "o": "滑数虚软脉总起来主湿热痰浊壅阻而正气已伤、气机升降不调之证。滑主湿痰，数主热，二者相合提示湿热痰浊内蕴；按之虚软则示正气不足，多因湿热久羁或误治损伤中气所致。三者相互关联：湿热痰浊壅阻气机，导致升降失调，进而耗伤正气；正气不足又使湿热难以化散，形成虚实夹杂之局", "c": "主湿热痰浊"}, {"id": "c:数+滑+长", "n": "滑数长脉", "o": "滑数长脉总起来主邪实壅滞，以痰湿、热邪、邪实有余为核心。滑主痰湿壅滞，数主热，长主邪气有余、壅滞不散，三者相合，反映痰热实邪壅盛，阻滞经脉，营气不从。原文两段均见经闭五载而饮食起居如故，无骨蒸痰嗽，非血枯可比，手指肿胀色紫、鼻衄、遍身疮疡，皆营气不从、逆于肉里", "c": "主痰湿"}, {"id": "c:滑+大+浮", "n": "滑浮大脉", "o": "滑浮大脉总起来主痰饮、湿热、阳热、风痰及虚阳外浮等病机，其核心在于滑主痰湿、浮主上焦或外浮、大主邪实或阳盛。各段所示：浮大而滑主痰饮上逆；尺脉滑浮大主湿热下注；浮大滑数属阳脉，主阳热亢盛；浮大弦滑主风痰壅盛；浮洪滑大主热盛邪实；沉滑浮大则主虚阳外浮。可见同一脉", "c": "主痰饮上逆"}, {"id": "c:滑+涩", "n": "滑涩脉", "o": "滑涩脉并见，总主痰、瘀、虚、火相互夹杂之病机。滑为痰涎内郁、阳盛痰火，涩为气机不畅、血少精亏、瘀血内阻。二者相合，常见痰郁气滞、痰瘀互结、痰火阳盛、血少精亏等证，亦可反映脏虚根本不足及气血通塞之穷通。各证之间常相互转化：痰郁日久可致血瘀，痰火内盛易伤阴血，血少", "c": "主痰郁气滞"}, {"id": "c:滑+疾", "n": "滑疾脉", "o": "滑疾脉总以滑主痰湿、食积，疾主热盛、风火为基本病机，故其主病多属痰、湿、热、风相互搏结之实证，或虚实夹杂之候。具体而言，滑疾脉可主痰湿化热、湿热郁结、里实热结、妊娠血盛、风痰袭络、虚中夹痰及外热等类。各类之间以'痰湿'与'热'为核心，或兼风、兼虚、兼食积，随兼", "c": "主痰湿"}, {"id": "c:滑+短", "n": "滑短脉", "o": "滑短脉总主痰湿、燥滞、热郁与气机壅滞相互搏结之病机。滑为痰湿内壅，短为气机不畅，二者相合，反映实邪阻滞、气机不利的病理状态。从原文看，劳病见滑短，伴体热心寒、咳嗽、口干眼涩、骨痿短气，其根本在于肠胃燥滞、营卫不能开发、玄府闭塞、热郁内余，故滑短脉所主以燥滞热郁", "c": "主热郁"}, {"id": "c:细+滑+涩", "n": "滑细涩脉", "o": "滑细涩脉总起来主痰湿内阻、阴血不足、气滞血瘀及肝木犯土之虚实夹杂证。滑主痰湿，细主阴血虚，涩主气滞血瘀，三脉合见提示痰湿、血虚、气滞并存，病机复杂。原文述肝气扰及中宫，木旺土虚，金受火克，咳呛痰沫，脘痞嗳气，乃肝郁化火刑金、脾虚生湿酿痰、气血运行不畅之候，故脉", "c": "主痰湿"}, {"id": "e:滑", "n": "滑脉", "o": "滑脉总以痰湿内蕴为核心病机，兼主热、积滞、风、虚及妊娠。其脉象流利圆滑，因痰湿、食积、热邪等有形之邪内壅，气血运行滑利所致。痰湿为滑脉最常见之因，痰湿郁久可化热，形成痰热；食积内停亦令脉滑；风邪挟痰则脉滑而风象显；虚证见滑多因正气不足而痰湿未化，属虚实夹杂；妊", "c": "主痰湿"}, {"id": "c:滑+长", "n": "滑长脉", "o": "滑长脉总起来主邪实有余、阳热壅盛，以痰、热、气逆为核心。滑主痰涎或痰热内壅，长主气机郁逆或阳热亢盛、邪势有余，二者相合，多反映实邪壅滞、气分热盛之候。具体而言，滑长脉可主痰涎壅盛、气逆不降，如痰喘痞塞；可主热盛痰壅，如疟疾阳明气分热盛挟痰；可主阳毒火炽，如壮热", "c": "主痰涎壅盛"}, {"id": "c:濡+伏", "n": "濡伏脉", "o": "濡伏脉总起来主湿邪内蕴、暑湿深伏及邪恋不解之病机。濡脉主湿，湿浊内阻则清阳不升，故见头蒙、舌垢；暑湿薰蒸则发热朝缓夕剧，邪深恋伏则需一候解达。伏脉示湿邪深遏、阳气被遏，脉道不显。诸类之间，湿为根本，暑湿为湿与暑合，邪伏为湿浊深恋之转归，共同反映湿邪困阻、阳气不", "c": "主湿"}, {"id": "c:濡+和", "n": "濡和脉", "o": "濡和脉总起来主湿邪为患及脾胃气弱。其核心病机为湿滞中焦、脾胃失司，表现为便泄腹痛、妨谷等症；亦可反映胃气薄弱，脉来濡静柔和，虽见肝旺胃薄之症而脉气尚和。若濡而兼数，则主湿热交蒸，尤以暑湿、湿浊内蕴、三焦气机阻滞为要。各类之间以湿邪为共同基础：湿滞脾胃为基本病机", "c": "主湿滞脾胃"}, {"id": "c:细+大+濡+软", "n": "濡大细软脉", "o": "濡大细软脉总起来主气虚痰湿，属虚实夹杂之候。其脉象濡软无力主气虚，大而无力主痰湿内停，细软亦为气弱之征。原文以肥白人眩晕为例，指出脉濡大或细软者属气虚痰湿，治当补气化痰。与滑大有力之实痰实火脉相对，此脉无实火之象，而以虚为本、痰为标，故所主病机以气虚为主，痰湿", "c": "主气虚"}, {"id": "c:弦+小+濡", "n": "濡小弦脉", "o": "濡小弦脉总起来主湿、虚、郁三端，以湿阻气滞、脾虚肝郁为核心病机。濡脉主湿邪内蕴，小脉主正气不足，弦脉主肝气不疏或气滞，三者相合，多示正虚湿滞、肝脾不调之候。各段所论，或偏湿阻，或偏脾虚，或偏肝郁，或湿滞与正虚并见，甚则兼湿热、阳虚寒湿，然皆不离湿、虚、郁相互夹", "c": "主湿阻"}, {"id": "c:数+小+濡", "n": "濡小数脉", "o": "濡小数脉总属虚多实少之候，核心病机为气阴两伤、虚热内扰，并可兼见痰湿未净、脾阳下陷及肺络损伤等。濡为湿、为虚，小为阴血不足、脉道不充，数为虚热鼓动，三者相合，提示正虚为本、热象为标。原文诸案或见肺阴暗伤、痰热未楚，或见三阴亏耗、脾胃生气受戕，或见痈溃日久、少阴", "c": "主气阴两伤"}, {"id": "c:滑+小+濡", "n": "濡小滑脉", "o": "濡小滑脉总起来主脾虚湿盛、正虚邪恋之候。濡脉主湿，小脉主正虚，滑脉主湿浊痰火。四段中，或见脾弱水湿泛滥、浊气上干，或见湿浊留恋募原、脾胃运化无权，或见阴分本亏而湿痰中阻，或见正气已伤而痰火余邪未清。其共同病机为虚实夹杂：正虚以脾弱、阴亏为主，邪实以湿浊、痰火为", "c": "主脾虚湿盛"}, {"id": "c:小+濡", "n": "濡小脉", "o": "濡小脉由濡脉与小脉复合而成，总主正气亏虚、湿邪内蕴之病机。其“小”主不足，示气血阴阳亏虚、阳气微弱；“濡”主湿、主虚，示湿邪内停、脉道弛缓。二者相合，常见于气虚阳微、营血亏耗、脾虚湿困、暑湿疟邪、正虚邪恋及虚损劳怯等证。各类之间相互关联：气虚阳微可致湿滞不化，", "c": "主气虚阳微"}, {"id": "c:弦+涩+濡", "n": "濡弦涩脉", "o": "濡弦涩脉总主脾胃气虚、湿滞血少、肝郁气滞及虚损奇脉之病机。濡为气血不足、脾虚湿滞，弦为肝气不柔、木郁土中，涩为血行不畅、气滞络瘀。三脉兼见，多因脾胃先伤，气血生化不足，湿浊内停，土不培木，肝邪郁滞，久则累及奇经，精血亏虚。各段所示：或暑湿伤脾、疟痢后脾阳不运；", "c": "主脾胃气虚湿滞"}, {"id": "c:弦+滑+濡", "n": "濡弦滑脉", "o": "濡弦滑脉总起来主湿浊痰阻、气机壅滞、正虚邪恋三类病机，而尤以湿痰为核心。濡主湿、主气虚，滑主痰、主水聚，弦主气滞、主肝旺，三脉合见，说明湿浊痰饮内蕴，气机升降失常，或兼肝木犯脾、风阳扰动。其病位多在脾、肝、肺、肾，病性多属本虚标实、虚实夹杂。各段原文所示，或湿", "c": "主湿浊内盛"}, {"id": "c:弦+濡", "n": "濡弦脉", "o": "濡弦脉总起来主湿、主肝郁脾虚、主饮、主疟、主虚、主湿热等多类病机。其核心在于濡脉主湿、主虚，弦脉主气滞、主饮、主疟、主肝木偏旺，二者相合，常示湿邪内蕴与气机失调并存，或本虚标实之候。从原文看，濡弦并见多归因于湿阻气滞，进而累及肝脾，致肝郁脾虚、疏运失司；湿聚成", "c": "主湿"}, {"id": "c:弦+濡+软", "n": "濡弦软脉", "o": "濡弦软脉总起来主正虚邪恋、本虚标实之证。其脉象以濡软为主，反映气血亏虚、肝肾内虚，或痰湿内恋；兼见弦象，则主气逆不降、寒邪乘袭、肝邪上犯。两类病机相互交织：一则气血内亏，痰湿未化，气机不降；二则肝肾内虚，寒邪乘袭，肝邪上犯，中阳亦虚。虚为本，邪为标，虚处留邪，", "c": "主气血亏虚"}, {"id": "c:濡+弱", "n": "濡弱脉", "o": "濡弱脉总属虚象，以气虚、阳虚为本，兼湿、痰、热为标。其脉濡主湿滞，弱主气衰，合见则正气亏虚而湿浊内停。所主病机涵盖气虚、阳虚、湿滞、痰饮、气血两虚、虚风内动及虚中夹热等类。诸类之间，以脾肾气虚阳虚为核心，脾虚运化失职则湿浊内停，湿聚成痰，痰湿郁久可化热；气血生", "c": "主气虚"}, {"id": "c:细+虚+濡+弱", "n": "濡弱虚细脉", "o": "濡弱虚细脉总起来主气血两虚与肝脾郁损。其脉象濡弱无力、虚细不足，反映正气亏虚，气血不能充盈脉道。在具体病证中，常因情志郁怒伤肝、思虑伤脾，导致肝脾气机郁结，血行不畅，久则化腐成痈，耗伤气血，形成虚实夹杂之候。原文乳疽案中，脉证相应，见脓水交流、形瘦色黄、言语低", "c": "主气血两虚"}, {"id": "c:数+微+濡", "n": "濡微数脉", "o": "濡微数脉总起来主湿、热、气虚阳弱，且多相兼为病。濡主湿，微主气虚阳弱，数主热，三象合见，反映正虚湿郁化热、本虚标实之机。所主病机主要有五类：主湿、主气虚阳弱、主热、主正虚邪恋、主湿热伤络。其中湿、热、气虚可单独出现，但更多是湿热兼气虚的复合病机，如高年气阴亏而", "c": "主湿"}, {"id": "c:滑+微+濡", "n": "濡微滑脉", "o": "濡微滑脉总起来主湿浊痰热内蕴，兼有正气不足。其核心病机为湿，滑为痰，微主虚，三者相合，提示湿浊痰热交阻而正气已伤。从所涉段落看，或为痰浊弥漫胸中、阳气被遏，或为湿热郁阻大肠、病久邪深，或为湿热困脾、内外皆病，均以湿浊为基础，或兼痰、或兼热、或兼虚，形成本虚标实", "c": "主湿浊"}, {"id": "c:濡+缓+散", "n": "濡散缓脉", "o": "濡散缓脉总主脾虚湿滞、中气不足之证。濡为湿邪内蕴，散为气虚不敛，缓为脾土本象，三脉并见，提示脾气虚弱、湿浊留连。此案年逾六十，自用利药攻下，病减而後重滞下未除，是攻利伤脾、中气已虚，湿滞未尽。故濡散缓脉所主病机以脾虚为本，湿滞为标，气虚不敛为关键。三者相互关联", "c": "主湿"}, {"id": "c:濡+散", "n": "濡散脉", "o": "濡散脉总主虚与湿，以气虚不敛、湿滞内蕴为核心。其脉濡为湿盛，散为气虚，二者相合，多示脾肺气虚、湿浊留连。具体而言，或偏于湿滞，或偏于气虚，或脾虚为本，或寒湿伤中，或气阴两伤，然总不离虚、湿二字。各段所载，有因攻利伤脾而脉见濡散缓，有因劳伤脾肺而右脉濡散，有因寒", "c": "主气虚"}, {"id": "c:数+濡+和", "n": "濡数和脉", "o": "濡数脉总起来主湿热为患，尤以暑湿、湿浊内蕴、三焦气机阻滞为核心。濡为湿象，数为热象，二者相合，说明湿与热交蒸于内，非单纯寒湿或纯热之候。从所收两段看，脉濡数皆见于暑湿或暑湿热混蒸之证，伴发热、呕恶、舌垢、舌苔腻、便利或便泄腹痛等，病机重点在湿热弥漫三焦、气化不", "c": "主湿热"}, {"id": "c:数+大+濡", "n": "濡数大脉", "o": "濡数大脉总起来主湿热秽浊壅阻募原、邪盛阳明、经腑同病。濡为湿象，数为热征，右大为邪盛于阳明，三者相合，提示湿热秽浊之邪从口鼻而入，痹阻募原，进而壅盛于阳明，致经邪未达、腑积未通。临床可见寒热起伏、腹痛板硬、便泄似痢、舌苔淡黄而厚、腻哕恶、汗少头胀等症。三类病机", "c": "主湿热"}, {"id": "c:数+濡+实", "n": "濡数实脉", "o": "濡数实脉总起来主湿热食积交阻肠道之实证，以痢下赤白、腹痛、舌苔灰黄而干为特征。其中濡主湿滞，数主热，实主积滞内阻，三象相合，揭示湿、热、积三者搏结为患。原文强调‘暴则为实宜通’，脉实示邪实急，故先治其实，以分消湿滞。三类病机相互关联：湿热为病因，积滞为病理产物", "c": "主湿热"}, {"id": "c:数+浮+濡", "n": "濡数浮脉", "o": "濡数浮脉总属虚实夹杂之候，以湿、热、虚三者交织为纲。濡主湿，数主热，浮主表或虚阳外浮，故其病机涵盖暑湿外袭、湿热内陷、气阴两虚及正虚邪恋四类。暑湿外袭者，多因清阳素虚，湿郁化热，脉浮濡数而舌苔黄腻；湿热内陷者，因中阳式微，湿浊蒙蔽，脉见濡数而浮，伴神识昏迷、热", "c": "主暑湿"}, {"id": "c:数+濡+缓", "n": "濡数缓脉", "o": "濡数缓脉总起来主湿、热、虚三者夹杂，以余湿未净、余热留恋、胃气渐复、气阴两伤为核心病机。其中濡主湿浊内蕴，数主热邪未清，缓则有两面：既示胃气渐复、太阴健运之佳象，又因合见濡数而反映气阴两伤、神不安舍。四类病机相互关联：湿与热留恋中焦，酿成痰浊，胃气呆顿，进而耗", "c": "主湿"}, {"id": "c:数+濡", "n": "濡数脉", "o": "濡数脉总以湿与热合为基本病机，濡主湿、数主热，二者相兼，故所主病机以湿热为核心，可涵盖暑湿、痰热、积滞、血热、虚热及正虚邪恋等多类。从原文看，湿热可弥漫三焦、蕴蒸阳明、阻于募原、注于下焦，表现为湿温、暑温、痢疾、淋证等；湿热郁久可化燥酿痰，痰热交阻则见郁火痰积", "c": "主湿热"}, {"id": "c:洪+濡", "n": "濡洪脉", "o": "濡洪脉在样本中仅见一段，其病机核心为气分大伤、邪热入营。濡主气分虚损，洪为热盛之象，但原文脉象濡中不洪，说明虽有大出血，热势未至洪盛，正气尚存。故其总病机为气分大伤、邪热入营，逼血妄行，属虚实夹杂之危候。两类病机相互关联：气分大伤为虚，邪热入营为实，虚中夹实，", "c": "主气分大伤"}, {"id": "c:数+涩+濡", "n": "濡涩数脉", "o": "濡涩数脉总起来主湿、瘀、热、虚交杂之病机。濡主湿滞与气虚，涩主血瘀与血少，数主热蒸，三象合见则提示湿、瘀、热互结，或兼阴血亏虚。所主三类病机各有侧重：瘀热互结者，数象明显，湿瘀热交阻阳明，症见昏乱、腹痛便黑；阴亏湿郁者，不数而热未炽，阴亏为本、湿郁为标，症见咳", "c": "主瘀热互结"}, {"id": "c:涩+濡", "n": "濡涩脉", "o": "濡涩脉总属虚实夹杂之象，以正虚为本、湿滞血涩为标。濡脉主湿、主气虚、主阴液不足，涩脉主血瘀、主血少、主气滞，二者并见，多示气血两虚或阴液亏耗，兼夹湿浊、痰瘀阻滞。其病机可归纳为湿滞、气虚、血瘀、虚中夹滞、阴液亏虚、阳衰湿阻、痰郁风动等类，各证常相互兼夹，如气虚", "c": "主湿滞"}, {"id": "c:滑+濡+散", "n": "濡滑散脉", "o": "濡滑散脉总主湿痰内盛、阳虚不化之病机。濡脉主湿盛阳虚，滑脉主痰湿壅滞，二者相合，示湿痰交阻、阳气不足。此段脉濡右滑，具体反映湿盛阳虚、痰湿壅中、湿热内酿，进而导致筋脉失养而成痿躄。各类病机相互关联：阳虚为湿盛之本，湿盛则生痰，痰湿久郁则酿热，湿热浸淫筋脉则致痿", "c": "主湿盛阳虚"}, {"id": "c:数+滑+濡", "n": "濡滑数脉", "o": "濡滑数脉总属湿热痰热交阻之象，以濡主湿、滑主痰、数主热为基本病机。其具体所主，或为湿热漫布三焦，或为痰热胶阻肺络，或为湿热积滞内蕴，或兼阴液已伤、正气亏虚。各类之间常相互兼夹：湿热郁久可化燥酿痰，痰热内盛易伤阴耗液，积滞与湿热互结又常损及正气。故临床见濡滑数脉", "c": "主湿热"}, {"id": "c:滑+濡", "n": "濡滑脉", "o": "濡滑脉总属湿痰为患，以濡主湿、主气虚，滑主痰、主湿浊为基本病机。其具体所主，或为湿浊内蕴，或为痰湿壅盛，或为气虚湿困，或为湿热交阻，或为痰湿蒙窍，或为湿阻络脉，或为湿遏阳气。各类之间常相互兼夹：湿浊内蕴可聚而成痰，痰湿壅盛易阻遏气机，气虚则运化无力而湿痰更甚，", "c": "主湿浊内蕴"}, {"id": "c:大+濡+空", "n": "濡空大脉", "o": "濡空大脉总起来主营血亏虚、虚寒及湿滞。其脉象濡而空大，濡为湿滞而虚，空大则营血亏虚、脉道不充。三者相互关联：营血亏虚则脉道不充，虚寒内生则络脉失养，湿滞阻络则脉气濡软。原文“营络虚冷”点明虚寒与血虚并存，而“濡为湿滞而虚”又揭示湿滞之因。故本脉以虚为本，兼夹湿", "c": "主营血亏虚"}, {"id": "c:濡+软+空", "n": "濡空软脉", "o": "濡空软脉总起来主阴血亏虚为本、湿痰内伏为标之虚实夹杂证。其脉象以空软示营阴不足、脉道不充，以濡示湿滞痰阻，二者相合，正应产后阴亏、冬温挟痰内伏之病机。四类之中，阴血亏虚为脉象根本，湿滞痰伏为邪实所在，营卫失谐为表里不和之征，虚中夹实为整体格局。诸类相互关联：阴", "c": "主阴血亏虚"}, {"id": "c:濡+紧", "n": "濡紧脉", "o": "濡紧脉总起来主阳气虚衰、寒邪内盛，兼及营卫不和与表里俱虚。濡为卫气微、阳气不足之象，紧为荣中寒、寒邪收引之征。二者相合，外则卫阳虚而风邪袭，内则营中寒而胃气冷，故见发热恶寒、微呕心烦；若误治发汗，则亡阳烦躁、心下痞坚，表里俱虚。其下属濡细紧脉更兼湿困与营血亏虚", "c": "主卫阳虚"}, {"id": "c:数+细+小+濡", "n": "濡细小数脉", "o": "濡细小数脉总起来主下焦湿热蕴结、阴络受损，兼见肝肾阴虚、气化不利之机。濡细主湿、主虚，小数主热，合而见于尺部，则湿、热、虚三者交织于下焦。原文以尿血涓滴、茎中鲜血频滴、小便疼刺难出、大便难解为主症，明言尺脉濡细小数主下焦湿热蕴结、阴络受损；又述肝肾阴虚、湿热下", "c": "主下焦湿热"}, {"id": "c:数+细+濡", "n": "濡细数脉", "o": "濡细数脉总起来主虚、湿、热三者交织为病。细主阴血不足，濡主湿困或气虚，数主热盛或虚热，三象合见，多示本虚标实、湿郁化热之机。其具体所主，可归纳为阴虚火旺、湿热蕴结、痰热内蕴、气阴两虚及热乘血室五类。阴虚火旺以阴亏为本、虚热为标；湿热蕴结以湿阻热蒸、气机受困为要", "c": "主阴虚火旺"}, {"id": "c:数+细+虚+濡", "n": "濡细数虚脉", "o": "濡细数虚脉总属虚象，以中气久虚、真阴亏损为根本。濡主气虚，细主阴亏，数主虚热，三象合见，示气阴两虚、虚热内生之候。中气虚弱则运化无力，纳谷运迟；胃虚气逆则客气上逆，噫嗳频作；真阴亏损则脉道不充而细，虚阳浮动而数。四类病机以“虚”为纲：气虚、阴亏为本，虚热为标，", "c": "主气虚"}, {"id": "c:细+涩+濡", "n": "濡细涩脉", "o": "濡细涩脉总属虚中夹实、阴阳气血俱损之象。濡主脾阳不足、水湿不化；细主阴血亏少；涩主血少气滞、脉道不利。三者相合，常见脾肾阳衰、阴阳两亏，或血虚气滞、湿阻络瘀，甚则虚火妄动、上盛下虚。各段所主病机虽有偏重，但均不离正虚邪恋、本虚标实之总纲。其虚以阴血亏少、脾肾阳", "c": "主阴阳两亏"}, {"id": "c:细+濡+紧", "n": "濡细紧脉", "o": "濡细紧脉总起来主寒湿困阻、阳气不足与营血亏虚，兼及瘀血内阻。濡细为湿困阳虚、营血不足之象，紧为寒邪收引。原文见寒中太阴，脉濡细带紧，证胸腹不宽、便行无表证；病进则脉转弦紧，为寒入厥阴，见呕哕腹痛、身热下利。下属脉总述又言弦紧濡细主营血亏虚、瘀血内阻与湿邪下注互", "c": "主寒中太阴"}, {"id": "c:细+濡", "n": "濡细脉", "o": "濡细脉总主虚损，以气血阴阳亏虚为本，兼夹湿、痰、热等邪。濡为阳气衰微、湿滞不运，细为阴血不足、脉道不充，二者相合，多示正虚邪恋、虚实夹杂。其病机可归纳为虚损、湿滞、脾虚、痰饮、湿热、气陷六类，彼此关联：虚损为根本，脾虚生湿，湿聚成痰，痰湿郁久化热，气虚日久下陷", "c": "主虚损"}, {"id": "c:弦+濡+缓", "n": "濡缓弦脉", "o": "濡缓弦脉总起来主脾虚湿困、气机郁滞、清阳不升之病机。濡缓为脾虚湿困、运化无力之象，弦为气机郁滞不舒，二者并见，说明脾元大伤、健运无力，湿浊内停而肝郁乘脾。脾虚湿困则腹膨胀、面浮跗肿、肌肤痿黄；气机郁滞则脘中不舒、胀满难鸣；清阳不升则四肢清厥、头脑旋运。三类病机", "c": "主脾虚湿困"}, {"id": "c:濡+弱+缓", "n": "濡缓弱脉", "o": "濡缓弱脉总起来主脾虚湿盛、阳气不足、气血两虚，并可兼见肾虚不固、虚中夹热、湿郁生痰等病机。其核心在于脾胃气虚，运化失职，湿浊内停，故脉象濡缓而弱。脾虚日久，则气血生化不足，阳气衰微，进而累及肾脏，固摄无权；湿郁不化，则聚湿生痰，或郁而化热，形成虚中夹热之候。各", "c": "主脾虚湿盛"}, {"id": "c:滑+微+濡+缓", "n": "濡缓微滑脉", "o": "濡缓微滑脉总起来主痰湿内盛、肝阳上亢。其中濡缓主湿，滑主痰，微滑更显痰湿黏滞；而痰湿中阻，肝阳易挟痰上腾，形成本虚标实之候。原文苔白厚腻、头痛眩晕，正是痰湿与肝阳相合为病。故其病机以痰湿为核心，肝阳上亢为继发，二者相互影响，治当熄肝化痰，标本兼顾。", "c": "主痰湿"}, {"id": "c:涩+濡+缓", "n": "濡缓涩脉", "o": "濡缓涩脉总起来主湿困中焦、胃气不和、气机不畅，兼涉寒热交争。濡缓为湿浊内蕴、脾胃气机弛缓之象，涩则示气机郁滞不畅，三者相合，反映湿痰困阻中焦、胃失和降之病机。原文以'五窍不和，都属胃病'概括，寒热从四末交会中宫，胃当其冲，故见脘痞、食无味、便泻等症。脉由虚数转", "c": "主湿困中焦"}, {"id": "c:濡+缓", "n": "濡缓脉", "o": "濡缓脉总以脾虚湿盛为核心病机。濡为湿象，缓为脾虚气弱，合之则脾胃气虚、运化失职、湿浊内停。脾虚日久，气血生化不足，则见气虚阳微、气血亏虚；湿郁不化，则聚湿生痰、湿阻气滞，甚则寒湿内盛、湿痿络痹。诸类之间以“脾虚”为本、“湿盛”为标，虚与湿互为因果：脾虚生湿，湿", "c": "主脾虚湿盛"}, {"id": "c:虚+濡+缓", "n": "濡缓虚脉", "o": "濡缓虚脉总起来主湿、主脾虚、主中气大虚、主痰湿内停，核心病机为阳明（脾胃）虚弱，痰湿内扰。脉濡缓为湿象，缓而无力为脾虚，虚而按之不足为中气大虚，三者相合，反映脾虚湿盛、中气不足之候。形肥色白、酒中受辱、情志伤中，致脾运失司，湿浊内生，痰湿内停，虚风上扰，发为心", "c": "主湿"}, {"id": "e:濡", "n": "濡脉", "o": "濡脉总主湿、主虚，以湿邪内蕴与正气亏虚为两大纲。其脉象软弱弛缓，湿性黏滞则脉道不敛，气虚阳微则脉道无力，故所主病机多围绕湿与虚展开。湿邪可弥漫三焦、困阻脾土、聚而成痰、郁而化热，故见主湿、主脾虚湿盛、主痰饮、主湿热等类；正气亏虚可因阳气衰微、气血不足、阴血亏耗", "c": "主湿"}, {"id": "c:濡+芤", "n": "濡芤脉", "o": "濡芤脉总属虚实夹杂之象，以气血亏虚为本，湿浊内蕴为标。濡脉主湿滞，因湿困脉道而现浮软；芤脉主血虚，因阴血不足而见中空。二者并见，提示气血大亏，且湿浊留恋，多因久病耗伤，脾胃虚弱，水湿不化，肝木乘脾所致。原文案中恙久脘痛、呕酸、积饮、腹胀、舌黄腻，正是湿滞血虚、", "c": "主湿滞"}, {"id": "c:数+濡+软", "n": "濡软数脉", "o": "濡软数脉总起来主正虚邪恋、虚实夹杂之候。濡软为正气亏虚、脉道不充，或为湿邪内蕴；数为余热未清或虚热内生。四段原文虽病种不同，或湿温后期、或肺燥咳呛、或冬温下虚外感、或崩漏日久，但共同病机为正气已伤而余邪未净，或虚火内扰。其中正虚湿恋与阴血亏虚火旺侧重气阴两伤、", "c": "主正虚湿恋"}, {"id": "c:滑+濡+软", "n": "濡软滑脉", "o": "濡软滑脉总属湿浊内盛、脾运失健之象。濡软主脾虚湿盛，滑主水湿痰饮内停，二者相合，既示脾虚不运、湿邪内生，又示水湿痰饮壅盛。其病机可因脾虚生湿、水湿泛滥而见浮肿喘逆（如肺脾两亏、肺病及肾）；亦可因湿热内蕴、脾土不能转旋而见胀满便泄、苔腻口甜（如湿热内蕴、肝木暗动", "c": "主脾虚湿盛"}, {"id": "c:濡+软", "n": "濡软脉", "o": "濡软脉总以“濡主湿、软主虚”为纲，主脾虚湿盛、气血不足，兼及痰饮、水湿、湿热、血寒等。其核心病机为正气亏虚而湿邪内蕴，故多见于脾胃虚弱、运化失职之证，如泄泻、痞胀、呕吐、水肿、带下等。湿性黏滞，易与他邪兼夹：兼风则浮缓，兼寒则沉紧或迟，兼热则沉数，兼郁则沉涩，", "c": "主脾虚湿盛"}, {"id": "c:濡+迟", "n": "濡迟脉", "o": "濡迟脉总以寒湿内蕴、阳气虚衰为核心病机。濡主湿，迟主寒，二者相合，反映寒湿困阻、阳气不运之象。其具体所主，可因兼脉与部位而异：兼浮则表虚湿滞，兼沉则大气下陷，兼数则邪伏热结，兼虚则中阳不足。然究其根本，总不离阳虚与湿滞两端：阳虚则寒生，湿滞则气机不利，故脉来迟", "c": "主寒湿内蕴"}, {"id": "c:大+牢", "n": "牢大脉", "o": "牢大脉总起来主邪实内结之实证，以寒凝、瘀血、火壅痰滞为主要病机。牢主寒主痛、坚积内着，大主邪盛有余，左脉候下焦血分，故见下焦感寒、瘀血内蓄之腹痛、血块，脉象牢大与症相符，治宜温通散瘀；若牢数大并见，则主阳火有余、火壅痰滞，治当苦降。跌仆金疮瘀血腹胀而脉牢大者，", "c": "主寒凝血瘀"}, {"id": "c:实+牢", "n": "牢实脉", "o": "牢实脉总起来主邪实内结、坚积深痼，其病机核心为邪气壅盛、结聚不散。具体而言，牢实脉可主邪实内结，如癫狂脉实牢为邪实内结、正气尚充；可主瘀热固结，如吐血后脉牢实为瘀热固结、正不胜邪；数牢实相合则主火盛、邪结深痼与气逆上冲，反映火邪内盛、结聚深痼并致气逆；在正虚邪", "c": "主邪实内结"}, {"id": "c:急+牢", "n": "牢急脉", "o": "牢急脉总起来主寒实内结、积邪内聚及血气偏虚、风湿痹阻之病机。牢脉主寒主实，急脉示拘急，合而示寒实内结、血脉拘急。原文列积聚脉象，浮而牢、小沉实等皆主积，贲豚为肾积，由寒邪留结、脏气传变所致，脉紧牢主寒实。小牢急脉则主血气偏虚、风湿痹阻及偏枯，脉小示气血不足，牢", "c": "主积"}, {"id": "c:数+大+牢", "n": "牢数大脉", "o": "牢数大脉总起来主阳火有余、火壅痰滞之实证。牢为邪实内结，数为热盛，大为火亢，三象合见，提示火邪炽盛、壅结于内，且多兼痰浊。原文以“阳盛并于上则狂”明其火性炎上，以“小肠火腑，非苦不降，痰亦因之而降”示其火壅痰滞、腑气不降。故本脉所主，以实火为核心，火盛则痰生，", "c": "主阳火有余"}, {"id": "c:涩+牢", "n": "牢涩脉", "o": "牢涩脉总起来主邪实内结、热盛急迫之病机，尤以府实坚结为核心。其脉象坚牢滞涩，反映有形实邪（如燥屎、瘀血）结聚于腑，气机阻滞不通。同时，牢涩常与弦数驶并见，提示热邪亢盛、急迫内迫。在病程中，若误治伤阴，则形成阴伤邪锢、虚实夹杂之候。三类病机相互关联：热盛可致府实", "c": "主热盛"}, {"id": "c:疾+牢", "n": "牢疾脉", "o": "牢疾脉总属癫疾之脉，其病机以风邪急搏、心气不足血涩、肾虚骨癫、痰热内扰、瘀血阻络为主。原文列五癫诊脉，牢疾与紧疾、微涩、洪大、浮大等并见，皆主癫疾。牢疾脉象沉实急迫，既反映风邪、痰热、瘀血等实邪内结，又可见于心肾亏虚、血涩不荣之虚证，故其病机虚实夹杂。诸类之间", "c": "主风邪急搏"}, {"id": "c:结+牢", "n": "牢结脉", "o": "牢结脉在疟母中总主邪与痰食瘀血深结于里、积块形成之病机。牢脉主坚积，结脉主气血凝滞，二者共同反映积块牢固、气血不畅；沉弦主疟邪未散，沉滑主痰结，沉实主食积，沉涩主血结，诸脉皆从沉部取，说明病位在里，邪气深结。各类病机相互关联：疟邪久踞是始动因素，导致气血凝滞，", "c": "主坚积"}, {"id": "e:牢", "n": "牢脉", "o": "牢脉总起来主邪实内结、坚积深痼之证，其核心特征为病邪深结牢固、非轻剂可拔。从所主病机看，牢脉既可主寒凝积痛、瘀血积滞、痰气郁结等有形实邪内结，又可主火郁热结、疟积癥瘕等郁热深伏或积块形成之候；同时，牢脉坚强亦可见于阴血亏虚、虚阳外露之虚实夹杂证。各类病机之间相", "c": "主邪实内结"}, {"id": "c:长+牢", "n": "牢长脉", "o": "牢长脉总属阳脉范畴，原文明确将“长”列为阳脉之一，与浮、大、数、动、滑同属。其核心病机在于反映阴阳虚实之偏颇：浮取实大而沉取损小，主阳盛阴虚；沉取实大而浮取损小，主阴盛阳虚。牢长脉以长而实大为特征，故偏于阳盛一端，但结合浮沉取法可辨虚实所在。此外，原文强调阳病", "c": "主阳盛"}, {"id": "c:散+疾", "n": "疾散脉", "o": "疾散脉总属阴阳离决、虚阳浮越之危候。其脉来疾速而散乱，非实热之数，乃阳气浮躁、涣散不收之象。所主病机主要有四：一为阴盛格阳，阴寒内盛逼阳外越；二为阴竭阳浮，阴血骤亏阳失所附；三为虚阳上越，阳气虚衰浮越于上；四为危候，示阴阳将脱、灯火将灭。四类相互关联，阴盛或阴", "c": "主阴盛格阳"}, {"id": "e:疾", "n": "疾脉", "o": "疾脉总属阳热急迫之象，其核心病机为热盛，然有虚实之别。实者邪热亢盛，如阳明腑实、温邪内陷、痰火内扰，脉疾而有力；虚者阴伤阳亢，如失血、虚劳、产后，脉疾而虚。热盛可灼阴，阴伤可生热，二者互为因果。燥热伤津、气机急迫亦见躁疾；中气大衰、升降失度则脉疾徐不常；阴阳离", "c": "主热盛"}, {"id": "c:急+促+短", "n": "短促急脉", "o": "短促急脉总属虚实夹杂、阴阳离决之危候。其核心病机为下痢亡阴、虚阳飞越。短脉主气损，因气不足则脉道不充；促急主虚阳躁动，因阴不敛阳则阳亢不安；阴精耗散则脉道失濡而短，虚阳上脱则脉促急迫。四类病机相互关联：气损为始，阴精耗散为渐，虚阳躁动为象，虚阳上脱为终，形成阴", "c": "主气损"}, {"id": "c:促+短", "n": "短促脉", "o": "短促脉总属虚实夹杂、阴阳离决之危候，其核心病机为气损、痰阻、虚阳躁动及热毒邪陷。短脉主气损，因气不足则脉道不充；促急主虚阳躁动，因阴不敛阳则阳亢不安；数主热迫，促为邪滞。各段所见，或为痰湿阻遏肺气之短促，或为下痢亡阴、虚阳飞越之短促急，或为脚气热毒内攻之促短数", "c": "主气损"}, {"id": "c:小+迟+短", "n": "短小迟脉", "o": "短小迟脉总起来主寒、主痛、主疝，三者相互关联。寒为根本，寒性收引凝滞，导致气血运行不畅，脉道拘急而现短小迟；寒凝气机不通则痛，故寒盛则痛；寒邪聚于下焦肝脉，则发为㿗疝，见小腹连卵肿急绞痛。原文指出“寒则脉当短小而迟”，又言“紧脉主痛，急为病甚”，说明短小迟脉虽", "c": "主寒"}, {"id": "c:弦+细+虚+涩+短", "n": "短弦细涩虚脉", "o": "短弦细涩虚脉总起来主脾虚湿困、气血不足、肺气不宣、气滞血瘀之候。其脉象复合，寸短主肺气不足，右脉弦细涩主血少气滞、脾虚湿困，关虚主脾胃虚弱。诸类病机相互关联：脾虚湿盛为根本，湿困中焦则气血生化不足，气血不足则肺气不宣，气滞血瘀则腹痛时作。原文见面黄、汗多、目赤", "c": "主脾虚湿困"}, {"id": "c:弱+短", "n": "短弱脉", "o": "短弱脉总起来主正气亏虚，尤以心肺上焦元气不足为核心，同时常兼夹痰、湿、热、瘀、火等标实之邪。其基本病机为“本虚标实”：寸部短弱多示心肺气虚或心血不足，关尺滑、洪、弦、数则分别提示痰湿、湿热、瘀血、虚火等兼邪。各段原文中，短弱脉或单独主气虚、血虚，或与滑洪弦数并", "c": "主气虚"}, {"id": "c:微+短", "n": "短微脉", "o": "短微脉总起来主气血亏虚、心气不足、五脏空虚及阴阳衰乱之候。其脉短主气不足、气机收敛，微主阳虚、鼓动无力，二者合见，反映正气亏虚、精神失守的病理状态。原文以'脉短而微'论邪哭魂魄不安，明确指出其为'血气少、心气虚之征'，并由此推及心气虚则畏怯、合目欲眠、梦远行而", "c": "主气血亏虚"}, {"id": "c:数+短", "n": "短数脉", "o": "短数脉总属虚实夹杂之象，短主气病、气郁、气损，数主热盛、虚热、烦心。其所主病机主要有热盛、气郁、气虚、虚热、正虚邪滞及血证六类。热盛者，数脉为热，短示气壅，热邪内迫；气郁者，短脉主气机不畅，兼数则热壅；气虚者，短为气不足，数兼虚热；虚热者，正虚而热扰；正虚邪滞", "c": "主热盛"}, {"id": "c:涩+短", "n": "短涩脉", "o": "短涩脉总属气血虚衰、脉道不充之象。短为气弱，气不充脉；涩为营虚，血不濡脉。其病机可归纳为：气虚阳衰、血少营虚、痰湿内蕴、燥伤津液、气滞血瘀、肺伤气损、忧思脏寒。诸类之间，以气血虚衰为本，或兼痰湿、燥邪、瘀滞等实邪，形成虚实夹杂之候。如阳虚多湿多痰则短涩无神；燥", "c": "主气虚阳衰"}, {"id": "c:数+虚+涩+短", "n": "短涩虚数脉", "o": "短涩虚数脉总属虚损之象，以气阴两虚、虚热内扰为核心。短主气虚，涩主阴亏血少，虚数主阴液内亏、虚热内扰。四者相合，反映气阴两伤、虚热内生之病机。本例八十五岁郁勃之体，厥阳司升，阴液内亏，秋燥将至，易伤肺金，故预进清金益胃，恐延肺痿。各分类之间相互关联：气虚推动无", "c": "主气虚"}, {"id": "c:涩+迟+短", "n": "短涩迟脉", "o": "短涩迟脉总起来主气结、血滞、寒凝相互搏结之病机，尤以燥金敛结、寒凝成坚为核心。短主气机郁结，涩主血行滞涩，迟主寒邪凝滞，三脉合见，示气血寒邪交结，日久成坚。原文以“金气之所结”“燥金敛结”概括，强调非单纯热实，故大承气屡下不通，反伤中气。四类病机中，气结、血滞", "c": "主气结"}, {"id": "c:结+短", "n": "短结脉", "o": "短结脉总属气机郁结、脉道不畅之象。其核心病机为气结，多因情志内伤、脏气失调所致，尤与思伤脾、脾气郁结关系密切。原文以七情九气伤脏为纲，短脉独见于思伤脾，说明短结脉主要反映气机壅滞、脉气不伸的病理状态。气结则脉短，情志伤则脏气乱，脾病则运化失司，三者相互关联：情", "c": "主气结"}, {"id": "e:短", "n": "短脉", "o": "短脉总属气病，以气虚为本，脉道不能满部，故“短则气病”。其主病机可归纳为气虚、阳虚寒盛、气血两虚、气郁痰阻、湿郁气滞及正虚邪陷六类。气虚为短脉之基本病机，气弱无力鼓脉则短；阳虚寒盛者，阳气暴衰，阴寒独盛，脉道缩而不充；气血两虚者，短兼涩弱，营血亏乏，脉道不盈；", "c": "主气虚"}, {"id": "c:迟+短", "n": "短迟脉", "o": "短迟脉总起来主寒邪为患，以寒凝、疼痛、疝病为核心病机。寒性收引凝滞，致脉道拘急而短、气血运行迟滞而迟，故短迟脉为寒证之典型脉象。寒凝气机不通则痛，痛甚则脉紧急，故短迟脉又主痛；寒邪聚于下焦肝脉，则发为㿗疝，见少腹控卵肿急绞痛。三类病机相互关联，均以寒为根本，短", "c": "主寒凝"}, {"id": "c:和+硬", "n": "硬和脉", "o": "硬和脉总起来主肝盛、脾伤、肺伤、阴虚阳亢及肝胆留邪等病机。弦为肝脉，肝盛则脉弦硬而不和缓；脉失和缓之脾土之气，是脾气受伤；肺金受伤不能镇肝，致肝木偏亢而脉弦。三者相互关联：肝盛侮脾，脾伤则土不培金，肺金亦伤；肺伤则金不制木，肝愈横。若真阴耗伤，不能涵木，则风阳", "c": "主肝盛"}, {"id": "c:滑+硬", "n": "硬滑脉", "o": "硬滑脉总起来主热盛津伤、真阴亏损之病机。其脉象有力而硬，有力为实，硬为热盛津伤、脉道失柔，非滑脉之流利。原文以白虎加人参汤所主之证为例，指出热入阳明，邪火炽盛，伤及津液，甚则真阴亏损，故脉见硬而有力，时作谵语。误投大剂白虎汤后脉搏转数，数主热盛，谵语更甚，说明", "c": "主热盛"}, {"id": "e:硬", "n": "硬脉", "o": "硬脉总起来主肝火亢盛、阴亏失柔、气逆上冲、邪实郁结、寒凝痛证及胃气衰败等病机。其核心在于脉道劲急失柔，反映脏腑气机刚劲不和。肝火亢盛与阴亏失柔常互为因果：火盛灼阴，阴亏则木失濡养，脉更弦硬；气逆上冲多由肝火挟冲胃之气上逆，故长硬并见。邪实郁结与寒凝痛证属实证，", "c": "主肝火亢盛"}, {"id": "c:乱+碎", "n": "碎乱脉", "o": "碎乱脉总起来主肝肾同病、肝风上冒之证。其脉道失其常度、搏指不宁，核心病机为肾阴亏虚于下，肝风扰动于上，乙癸同源，母子同病。原文两段均以尺脉碎乱搏指为据，断为“肝风上冒”“肾肝同病”，并强调少阴之脉不至巅、惟厥阴能至，故以肝为重、肾次之。由此衍生出三类相关病机：", "c": "主肝风上冒"}, {"id": "e:碎", "n": "碎脉", "o": "碎脉总起来主阳气衰微、阴寒内盛之病机，其脉形破碎不整、乍有乍无，反映脉气欲绝或脉道不利。原文以‘六脉俱无，乍有则甚细’为据，断为阳虚阴盛，从脉舍证用温阳而脉渐出，可见碎脉核心在阳气不能鼓动血脉。在此基础上，碎脉又可因阴盛格阳而见外假热之象，如面赤谵语口碎；亦可", "c": "主阳虚"}, {"id": "c:数+空+促", "n": "空促数脉", "o": "空促数脉总起来主热盛阴伤、营血暴脱之病机。其脉空软为血脱脉虚之象，促数为热邪未清之征，二者并见，反映热邪未解而营阴已伤、血脱于下的复杂局面。原文所述冬温失于清解，误服辛热温燥，致崩血一阵，脉见空软促数，苔黑舌绛，足冷息微，正是热盛、阴伤、血脱交织之候。三类病机", "c": "主热盛"}, {"id": "c:动+空", "n": "空动脉", "o": "空动脉总属虚候，以脉道不充、按之微涩为特征。其主病机有三：一为气血俱虚，营卫络脉空乏；二为虚风内动，风由虚生，非实邪可比；三为神不守舍，心营失养而神识昏瞀。三者相互关联：气血虚为根本，虚则络脉空动，进而虚风内动、扰及心神，故见咳血、抽搐、癫狂等症。原文强调“络", "c": "主气血虚"}, {"id": "c:大+小+芤+空", "n": "空大小芤脉", "o": "空大小芤脉总属阴血亏虚、暑热内侵之候。其脉象空大无力或细小如芤，皆因平素积劳内虚，精血暗耗，脉道不充；又逢秋暑客邪，直干脏阴，热深劫阴，故见寒热麻痹、腰痛冷汗、神迷心热烦躁等症。四类病机中，“主虚”为发病之本，“主暑热”为外邪之因，“主邪干脏阴”言邪正交争之所", "c": "主虚"}, {"id": "c:数+滑+大+空", "n": "空大滑数脉", "o": "空大滑数脉总起来主正虚邪盛、痰热内盛、阴伤液耗之危重病机。其脉象由空大与滑数两组相反脉象复合而成：空大主阴伤正虚，为病久五脏之阴皆伤、正气亏虚之本质；滑数主痰热内盛，为痰热鸱张、蒙蔽心营之标象。二者并见，反映正虚邪盛、本虚标实之复杂格局。在此伏邪案中，痰热蒙蔽", "c": "主阴伤正虚"}, {"id": "c:大+空", "n": "空大脉", "o": "空大脉总属虚候，以脉大而中空、按之不实为特征，主正气亏虚、阴阳失守。其病机可归纳为气虚阳浮、阴血亏虚、脾胃虚衰、虚风内动、正虚邪恋及脱证危候六类。气虚阳浮为基本病机，气不内守则脉道松弛而空大；阴血亏虚则脉失充盈，虚阳上浮；脾胃虚衰则右脉空大，中气不运；虚风内动", "c": "主气虚阳浮"}, {"id": "c:实+空", "n": "空实脉", "o": "空实脉（本案表现为芤涩并见）总起来主血虚兼瘀、络脉不和之病机。其脉中空边实，中空为芤，主血虚失充；来往不利为涩，主瘀血内阻。二者相合，形成血虚与瘀血并存的虚实夹杂证。血虚则诸经失养，瘀阻则胃络震动，故见络脉不和。治疗上不可堵截，宜用和络之法，使血行而不伤正。三", "c": "主血虚"}, {"id": "c:弦+涩+空", "n": "空弦涩脉", "o": "空弦涩脉总起来主胃气将绝、血枯津竭之危候。空脉反映胃气衰败、脉道空虚，为病之本；弦脉示肝木乘虚犯土，加重胃气上逆而呕吐；涩脉示血少枯滞，津亏肠燥而便结。三者相合，见于'胃脘枯槁至于结肠'、'形瘦见骨，色萎不泽'之膈症晚期，说明胃气已败、肝木乘之、血枯津竭，属虚", "c": "主胃气衰败"}, {"id": "c:弦+空", "n": "空弦脉", "o": "空弦脉总属虚实夹杂之象，以虚为本，以实为标。空主血虚、阴伤、元气不足，弦主气机郁滞、肝木偏旺或邪气壅结。故其主病机可归纳为：主肝病、主虚损、主虚中夹实、主痰湿、主瘀滞、主肝脾不调。各类之间相互关联：肝病与肝脾不调均以弦为定位，空示中虚；虚损为根本，虚中夹实为总", "c": "主肝病"}, {"id": "c:数+大+浮+空", "n": "空数浮大脉", "o": "空数浮大脉（此案实为左弦急、右洪滑数）总起来主阴虚火旺、痰热内盛与暑热伤津三类病机。患者产后阴血亏虚，木火上浮，故左脉弦急；酷暑外烁，津液大耗，痰热内蕴，故右脉洪滑数。三者相互交织：阴虚为本，火旺为标；暑热外袭，引动内痰；痰热又进一步耗伤津液。脉象洪滑数主痰热", "c": "主阴虚火旺"}, {"id": "c:数+弦+浮+空", "n": "空数浮弦脉", "o": "空数浮弦脉在此案中总属暑湿伤气、阴液耗伤而暑热未清之候。初起脉微弱为暑湿本象，示气机受困；病延日久，脉转数而未空，反映暑热未清、阴液已伤，然胃气未绝。四类病机相互关联：暑湿伤气为始因，暑热未清为病进，阴液耗伤为结果，而胃气未绝为转机之关键。脉象由弱转数，提示邪", "c": "主暑湿伤气"}, {"id": "c:数+空", "n": "空数脉", "o": "空数脉总主虚损与热象并存之病机。空为脉道不充，主气血阴阳亏虚；数为热，然此热多为虚热或邪热。二者相合，常见于虚损、虚热、正虚邪恋、阴液告涸及元气败散等证。其虚以阴血亏虚、精气两虚为主，其热或为虚火浮动，或为邪热内蒸。诸类之间相互关联：虚损为根本，虚热由虚而生，", "c": "主虚损"}, {"id": "c:濡+空", "n": "空濡脉", "o": "空濡脉总起来主血虚、气郁络伤与胃弱三类病机。左空为肝血不足，右濡为胃气虚弱，二者并见，示肝胃络脉失养。原文“右胁先痛，继以呛痰血块”及“情怀不舒之郁”点明气郁为诱因，气滞则络伤，血不循经而外溢；形瘦食减又示脾胃虚弱，运化不及。故其病机以血虚为本，气郁为标，胃弱", "c": "主血虚"}, {"id": "e:空", "n": "空脉", "o": "空脉总属虚候，以脉道不充、按之不实为特征，主正气亏虚、阴阳失守。其核心病机为‘虚’，涵盖气血精津液诸般耗损及脏腑、奇经、络脉失充。虚则易受邪，故常兼风、寒、痰、湿、疟等邪，形成虚中夹邪之候；阴血亏虚又可化燥生风，致虚风内动；气虚不敛或阴不恋阳，则虚阳上浮，成下", "c": "主虚损"}, {"id": "c:虚+空", "n": "空虚脉", "o": "空虚脉总主正气亏虚，涵盖气血精津液诸般耗损及脏腑、奇经、络脉失充。其核心病机为'虚'：或为全身性虚损，或为奇经八脉空虚，或为局部络脉不荣。虚则易受邪，故常兼风、寒、痰、湿、疟等邪，形成虚中夹邪之候；阴血亏虚又可化燥生风，致虚风内动。诸类之间以虚为本，或纯虚无邪", "c": "主虚损"}, {"id": "c:数+软+空+促", "n": "空软促数脉", "o": "空软促数脉总起来主热盛阴伤、营血暴脱之病机。其脉空软为血脱脉虚之象，促数为热邪未清之征，二者并见，反映热邪未解而营阴已伤、血脱于下的复杂局面。原文所述冬温失于清解，误服辛热温燥，致崩血一阵，脉见空软促数，苔黑舌绛，足冷息微，正是热盛、阴伤、血脱三者交织之危候。", "c": "主血脱"}, {"id": "u:窒塞", "n": "窒塞脉", "o": "窒塞脉总属脉气不畅之象，所主病机以气机壅滞为核心，可因虚、因实、因虚实夹杂而致。虚者如阳虚气滞、阴虚邪闭、气虚阳浮、虚中夹瘀，皆因正气不足、推动无力或虚阳浮越，使脉道不利；实者如湿热壅滞、邪闭气机、毒火内蕴，皆因邪气阻滞、气机闭塞，使脉气不达。各类之间常相互转", "c": "主阳虚气滞"}, {"id": "c:紧+伏", "n": "紧伏脉", "o": "紧伏脉总属邪深闭阻、气机壅塞之候。紧主寒、主痛、主气结，伏主邪深伏于里、脉道不利，二象相合，集中反映实邪内闭、气血不通的核心病机。其主病可归为五类：一主气闭，气机壅塞、阴阳不相顺接而仆倒；二主寒痛，寒凝经脉、气血不通而身痛；三主痧毒，痧毒郁闭、气血运行失序；四", "c": "主气闭"}, {"id": "c:紧+和", "n": "紧和脉", "o": "紧和脉总起来主寒凝水湿、阳气渐复、正虚邪恋与血痹痹阻四类病机。紧脉本主寒主水，寒水凝聚则脉道收引而紧，故见遍体浮肿、腹痛等症；紧转和缓则示阳气来复、寒凝渐散，为病退之兆；脉微涩而紧，微为虚、紧为邪，主阳气阴血俱虚而风寒湿邪痹阻，属正虚邪恋、本虚标实；紧见于关上", "c": "主阳气渐复"}, {"id": "c:数+紧+实", "n": "紧实数脉", "o": "紧实数脉在此段中并非寻常数实之脉，而是与屋漏、雀啄、弹石、解索、虾游、鱼翔等怪脉并列，总属无胃气柔和之象的死脉范畴。其总病机为胃气败绝、脏真外泄，脉来坚急数疾而绝止复顿，或散乱无根，反映脏腑精气衰败、阴阳离决。三类病机相互关联：胃气败绝是根本，脏真外泄是表现，", "c": "主胃气败绝"}, {"id": "c:细+紧+实", "n": "紧实细脉", "o": "紧实细脉总起来主邪气内结而正气未散之候。其脉象紧实反映邪实内结，细象则示收敛之机尚存，故虽病重而脉未散越，预后多生。与浮大脉之邪张正脱、大而止脉之失血脉断形成鲜明对比，说明紧实细脉所主病机关键在于邪实与收敛并存，非正气外越或虚脱之象。临床见此脉，当知邪虽盛而正", "c": "主邪结可生"}, {"id": "c:紧+实+结", "n": "紧实结脉", "o": "紧实结脉总属寒饮食积搏结成形之实邪内聚，其核心病机为“癖结”。紧脉主寒凝，实脉主邪结，二者相合，反映水饮停聚不散，复与饮食相搏，结于胁下，形成癖结。癖结阻滞气机，故可见胁下弦起、胀痛、喘息短气等症。四类病机中，寒凝与邪结是脉象形成的直接依据，癖结是病名诊断，气", "c": "主寒凝"}, {"id": "c:紧+实", "n": "紧实脉", "o": "紧实脉总起来主邪实内盛，以寒凝、痰积、实结为核心，兼及热郁与瘀阻。紧脉主寒主痛，实脉主邪结，二者相合，反映寒邪、痰浊、燥屎等实邪内结，气机壅滞，脉道拘急而充实。原文'脉紧实痰积'及'脉坚实不大便者，为实邪内结'是直接依据；若兼数则热郁，兼涩则瘀阻，均属邪实壅盛", "c": "主寒凝"}, {"id": "c:紧+平", "n": "紧平脉", "o": "紧平脉在肾脉中，总以紧而和缓为平，紧而失和为病。其病机可分虚实两端：太过则紧而弹石，病在外，为邪盛；不及则紧而解索，病在内，为正衰。若紧而益坚如引葛，是水湿内停之肾水；若紧硬辟辟如弹石，则是胃气已绝之死脉。诸类以肾气为本，平脉为常，太过、不及为变，肾水为病，死", "c": "主肾平"}, {"id": "c:弦+紧+实+牢", "n": "紧弦实牢脉", "o": "紧弦实牢脉总起来主实，包括正气充盛与邪实壅盛两方面。其脉象紧弦实牢，反映脉道充盈、气血壅滞或邪气搏结。具体而言，若见于妊娠后期，则为母气壮实、胎有所养之生理性实脉；若见于他病，则多主邪实壅盛，如风邪急搏、痰气壅滞等，可致癫疾发作。各类病机之间以“实”为纲：气血", "c": "主风邪急搏"}, {"id": "c:涩+紧+急", "n": "紧急涩脉", "o": "紧急涩脉在痈疽辨证中总属气血壅滞、脉道不利之象。其病机可分三类：一为阳热之邪郁于阴分，热胜血而脉浮洪弦数兼涩，主热毒壅滞；二为阴寒凝滞阳气，脉沉细弱涩，主寒凝血脉；三为气血虚损，脉见虚弱而涩，主正虚邪恋。三者皆以“涩”为共同特征，反映气血运行不畅或脉道不充，而", "c": "主热胜血"}, {"id": "c:紧+急", "n": "紧急脉", "o": "紧急脉总起来主寒、痛、拘急，其核心病机为邪气收引或筋脉失养而致拘挛紧急。紧主寒主痛，急主拘急气逆，二者相合，既见于外寒束表、寒积内痛之实证，也见于气逆攻冲、积结关格之危候；又可因阴血亏耗、筋脉失濡而见，属虚风内动；或由燥热伤筋、湿邪搏脉、风急寒凝、风痰闭阻等所", "c": "主寒痛拘急"}, {"id": "c:数+弦+涩+紧", "n": "紧数弦涩脉", "o": "紧数弦涩脉在原文中作为妇人‘不堪’之脉出现，总主气血失调、冲任失和，具体可析为气火偏亢与血少气滞两端。紧数主气火偏亢，弦涩主血少气滞，二者相合，则气血不调、冲任不盛，非孕育之佳兆。原文以‘求子先察母质’为论，列此脉为基址之忌，强调妇人以静厚重苍为贵，而紧数弦涩", "c": "主气火偏亢"}, {"id": "c:数+细+微+紧", "n": "紧数微细脉", "o": "紧数微细脉总起来主正虚感邪、元气不足而外受风寒之候。其脉象复合：紧数反映外邪束表、邪正相争；微细反映元气亏虚、鼓动无力。二者并见，说明并非单纯实热或单纯虚证，而是正不胜邪、元气不能托邪外达。原文以此脉象提示‘必须培助元气，兼之解散’，若但知散邪不顾根本，则元气", "c": "主正虚感邪"}, {"id": "c:数+大+洪+紧", "n": "紧数洪大脉", "o": "紧数洪大脉总以邪实热盛为主，兼涉虚损危候。紧主寒束，数主热，洪大主邪盛，四者相合，多见于外感表邪实、里热亢盛及产后兼杂实邪之证。然同一脉象，若见于新产亡血伤津，则紧数为寒郁虚热，洪大为邪盛，反映血虚津伤、筋脉失养；若洪大紧数甚而正气不支，又主邪盛正危。故其病机", "c": "主表邪实"}, {"id": "c:数+滑+洪+紧", "n": "紧数洪滑脉", "o": "紧数洪滑脉总起来主瘟疫初起、寒束热盛、邪实正实之证。紧主寒邪外束，数主热，洪滑主邪盛正实，四脉合见，反映表寒里热、邪气亢盛而正气不虚的病机。原文以此脉与'弱数'对举分虚实：紧数洪滑而证无虚者，宜祛邪解表、清火解毒；若洪大而热躁甚为火盛，洪大滑实而便秘为热结阳明", "c": "主寒束"}, {"id": "c:数+紧", "n": "紧数脉", "o": "紧数脉总以紧主寒、主痛、主积滞，数主热、主郁火为基本框架，所主病机可归纳为外感表实、寒热错杂、积滞内阻、郁热化火、疟邪伏少阳、毒邪壅滞及虚中夹实七类。其核心在于寒与热、表与里、实与虚的交争：紧为寒邪收引、气机凝滞，数为热邪亢盛、正邪相争，二者并见，或为外寒束表", "c": "主外感表实"}, {"id": "c:涩+紧", "n": "紧涩脉", "o": "紧涩脉总起来主寒凝、血瘀、气滞、正虚诸端，其核心病机为寒邪凝滞、气血不畅。紧主寒主痛，涩主血瘀气滞，二者相合，多示寒凝血瘀、气机壅塞之证。从所主病机看，或为寒伤营血、瘀阻下焦，或为寒湿内郁、脾运失职，或为本虚标实、气滞血涩，或为气血壅滞、脉道不利，或为风寒湿杂", "c": "主寒凝血瘀"}, {"id": "c:滑+紧", "n": "紧滑脉", "o": "紧滑脉总以紧主寒（或热结收引）、滑主痰食实邪为纲，所主病机涵盖寒痰壅盛、寒食交阻、胃实脾伤、蛔动吐逆及热结闭癃数类。其核心在于实邪（寒、痰、食、虫、热）与正气相搏，致气机壅滞。诸类之间，寒痰与寒食常相兼为患，皆因寒邪收引、痰食内停；胃实脾伤侧重脾胃本脏实强相攻", "c": "主寒痰壅盛"}, {"id": "c:紧+牢", "n": "紧牢脉", "o": "紧牢脉总主积、寒、痛、泄痢，其核心病机为寒邪搏于脏腑、气血凝滞成形。紧为寒束，牢为深着，二脉相合，示寒凝深结、积滞内着。原文以积为阴气五脏所生，聚为阳气六腑所成，皆由寒气搏于脏腑、与阴阳气相击，故心腹痛。紧牢脉既主横积结痛，又主泄痢，并可凭脉位脉形辨积之部位。", "c": "主积"}, {"id": "c:紧+疾", "n": "紧疾脉", "o": "紧疾脉总起来主寒盛、阳虚、积结与风癫，核心病机为寒邪急迫、正邪相争。紧主寒凝收引，疾主邪正相争急迫，二者相合，多示寒盛阳伤、气结急迫之候。若兼细，则阳虚寒盛，甚则虚阳外越；若兼沉，则寒凝气结、深伏成积；若见于癫疾，则风邪急搏。各类之间以寒与急迫为共同要素：寒盛", "c": "主寒盛"}, {"id": "c:紧+硬", "n": "紧硬脉", "o": "紧硬脉总起来主寒凝、痛与肾虚寒。紧硬为寒邪收引凝滞之象，弦主痛、主肾，两尺尤甚则病位在肾。三者相互关联：寒凝收引导致气滞不通，不通则痛；寒邪伤及肾阳，肾阳虚衰则下焦虚寒，寒凝更甚。原文所载痢疾案，因平素中寒，又食寒凉，致肾阳虚衰，寒凝气滞，故脉双弦紧硬而两尺尤", "c": "主寒凝"}, {"id": "c:细+微+紧", "n": "紧细微脉", "o": "紧细微脉总起来主燥金收敛、正虚邪结与正虚感邪三类病机。其脉象以紧、细、微复合为特征：紧主收敛、主寒、主痛、主积；细主津液不足、正气渐伤；微主阳气衰微、鼓动无力。从原文看，紧细微脉既可应秋燥金之气，表现为皮肤皴揭启裂，反映燥邪伤津、腠理闭密；又可主积与寒痛，因寒", "c": "主燥金收敛"}, {"id": "c:弱+紧+缓", "n": "紧缓弱脉", "o": "紧缓弱脉在此段中并非单一脉象，而是弦急、不甚紧、时缓弱并见，总起来主肝经风火夹脾虚之本虚标实证。弦急主肝火亢盛、风热上攻，为标实；缓弱主脾虚不运、正气困乏，为本虚；不甚紧则示风火之势不专，虚象已显。三类病机相互关联：肝火风热上扰致耳根肿痛脓血，脾虚气弱致食少体", "c": "主肝火风热"}, {"id": "e:紧", "n": "紧脉", "o": "紧脉总以主寒、主痛为核心，其病机本质为寒邪收引、气机凝滞，脉道拘急。然紧脉所主广泛，可因兼脉与病位不同而分属多类：浮紧主表实风寒；沉紧主里寒实或水饮内停；弦紧主寒凝气滞、饮积；细紧、迟紧主虚寒；紧数主寒热错杂或郁热；紧滑主痰食实邪；大紧主邪盛壅遏。诸类之间，寒", "c": "主寒"}, {"id": "c:紧+芤", "n": "紧芤脉", "o": "紧芤脉总主寒虚相搏、胃气失和之病机。紧为寒，芤为虚，二者相合，提示寒邪内客而胃气已虚，中焦升降之枢机不利。其病机可归纳为三类：一为寒邪内盛，二为胃气亏虚，三为胃气上逆。三者相互关联：寒邪伤中则胃气益虚，胃虚则寒邪更易内侵，寒虚相搏，胃失和降，故见吐、噎、谷不得", "c": "主寒"}, {"id": "c:细+乱", "n": "细乱脉", "o": "细乱脉总属正虚邪陷、气机逆乱之危候。其脉细为阴血亏耗，乱为正气溃散、清浊升降失度，兼数促则阳邪郁伏，兼断续则脉气不续。所主病机以正虚为本，邪陷为标：阴亏阳亢则虚热内扰，气机逆乱则升降乖违，甚则脏腑真气不续而成坏症危候。四类之间由虚致乱、由乱致危，层层递进，反映", "c": "主正虚邪陷"}, {"id": "c:细+实+伏", "n": "细伏实脉", "o": "细伏实脉总起来主邪实内闭、气逆脉道不行之证，尤以暴痛为典型。其脉虽沉伏细涩，貌似极虚，但细察必有梗梗然弦紧之意，为寒邪阻遏阳气、气为邪逆所致，故属实证而非虚候。原文强调脉忽细伏者多实邪，脉本微弱者方为虚邪，示人暴痛脉伏不可误认虚脱，当辨形气。两类病机实为一体：", "c": "主实邪"}, {"id": "c:细+伏", "n": "细伏脉", "o": "细伏脉总起来主邪闭气机与气血不足，其核心在“伏”：伏为脉道一时隐蔽不见，多因邪气内闭、气逆不通，或气脱不续。细则示气血不足、脉道不充。细伏并见，或为湿遏热伏、暑湿内蕴，阳气被遏而脉道不利；或为寒邪痧秽格拒中枢，阳郁不达；或为血脱气陷、正虚邪陷，阴阳将竭；或为邪", "c": "主湿遏热伏"}, {"id": "c:细+促", "n": "细促脉", "o": "细促脉总属虚损之象，以阴精亏虚为本，阳气不相接续为标。细主阴血精液不足，促主阳气躁动或虚火内迫，二者并见，提示根本已虚而虚热、虚阳不宁。其病机可归为六类：阴精亏虚、阳气欲绝、虚火炎上、中气败散、冲气上逆、营卫失和。诸类之间，阴精亏虚是共同基础；阳气欲绝与中气败", "c": "主阴精亏虚"}, {"id": "c:细+动", "n": "细动脉", "o": "细动脉总起来主阴亏阳扰、冲气上逆与血伤邪扰三类病机。其脉象以细为阴液不足、动为阳气或邪气扰动不宁为共同特征。第一类阴亏阳扰为基本病机，细示肝肾阴亏于下，动示阳气扰动无制于上，可见咳呛、咽痛等症；第二类冲气上逆由阴亏不能镇纳冲脉、收摄失司所致，咳呛呕吐涎沫是其明", "c": "主阴亏阳扰"}, {"id": "c:细+坚+硬", "n": "细坚硬脉", "o": "细坚硬脉总起来主肾经湿毒蕴结、阴血不足、病根深伏之候。脉细为阴血亏虚，左尺坚硬鼓指为湿毒久郁化热、结聚不散，二者相合，形成虚中夹实、本虚标实之象。湿毒深伏于肾，循少阴经脉上攻，故见喉间糜碎、舌下肿胀；前症淋浊、横痃下疳虽愈，而病根未除，脉象仍显坚硬鼓指。三类病", "c": "主湿毒蕴结"}, {"id": "c:细+坚", "n": "细坚脉", "o": "细坚脉总以阴血不足为本，兼见邪实内结之象。其脉细主阴血亏虚，坚主邪气固结、脉道不柔。所主病机主要有五：一为阴血不足，脉失濡养；二为肝阳上逆，阴亏阳亢，血随气逆；三为瘀血内停，营血不足而络脉不柔，瘀血未净；四为正虚邪结，阴阳不相顺接，邪伏深入；五为湿毒蕴结，本虚", "c": "主阴血不足"}, {"id": "c:细+大", "n": "细大脉", "o": "细大脉总起来主虚实夹杂之证，以正虚为本、邪实为标。细脉主阴血不足、气弱或阴分亏虚，大脉主邪气壅盛，如燥热、火盛、痰湿、暑湿等。各类病机虽侧重不同，但多围绕‘正虚邪实’展开：或阴伤而燥热内逼，或阴亏而温邪内陷，或火盛而水衰火乘，或热盛而阴液不足，或气虚而痰湿内停", "c": "主阴伤燥热"}, {"id": "c:细+大+小", "n": "细小大脉", "o": "细小大脉在此段中主正虚邪陷与邪伏深沉两类病机。脉细小不大，总因正气衰微，无力抗邪，致温邪不从表达，直陷厥少，邪伏深沉。正虚与邪陷互为因果：正虚则邪易内陷，邪陷又进一步耗伤正气。原文‘险如朝露’示其危重，脉细小正是正气无力托邪外出之征，故临床见此脉多属正不胜邪之", "c": "主正虚邪陷"}, {"id": "c:弦+细+小", "n": "细小弦脉", "o": "细小弦脉总起来主阴血亏虚、肝郁风动，并常兼夹邪恋、湿热痰滞及疟邪等。其脉象要素中，细小主阴血不足、营卫两虚、正气亏弱；弦主肝郁、风木、邪郁、疟与痛。诸段所涉病机虽异，多围绕正虚与邪郁两端：或阴亏而肝气横逆、风木乘土；或正虚而暑湿热余邪羁留三阴；或阴亏而湿热痰滞", "c": "主阴血亏虚"}, {"id": "c:数+细+微+小", "n": "细小微数脉", "o": "细小微数脉总主肺胃阴伤、虚火内郁、气机壅滞之候。细为阴亏，数为火郁，微小为气不畅，三者相合，反映阴液不足为本，郁火与气壅为标。原文以右脉细小微数为征，断喉中燥痒咳呛、痰不易出、如有物阻，由气上壅、火郁脑门、清肃不降所致。阴伤则失润，火郁则生燥，气壅则痰阻，互为", "c": "主阴伤"}, {"id": "c:数+细+小", "n": "细小数脉", "o": "细小数脉总以阴血亏虚、虚热内扰为基本病机。细主阴伤，小主脉道不充或气弱，数主有热，合而多示虚热，亦可兼实邪。诸类中，阴虚内热、气阴两虚、虚火动血、中虚伏热皆以虚为本、热为标，或偏阴亏，或偏气虚，或虚火灼络；痰热内闭、正虚邪恋则虚中挟实，或痰热弥漫，或水湿内停；", "c": "主阴虚内热"}, {"id": "c:数+细+虚+小", "n": "细小数虚脉", "o": "细小数虚脉总属虚损之象，以阴血亏虚为本，虚热内扰为标。细主阴伤，虚主气弱，小主脉道不充，数主虚热。四段原文分别从阴虚内热、气阴两虚、肺虚肾亏、血虚劳伤立论，皆不离“虚”与“热”二字。其热为虚热，非实火；其虚或偏阴血，或偏气阴，或涉肺肾，或及心肝脾。诸类之间相互", "c": "主阴虚内热"}, {"id": "c:细+滑+沉+小", "n": "细小沉滑脉", "o": "细小沉滑脉总起来主湿浊壅滞、痰湿内阻之里实证。细为湿滞，沉主里，滑主痰湿，三象合参，提示湿浊痰饮壅滞于里，气机不通。原文所载脚气一证，体肥身长，素有脚气，发则腿膝胀痛、呕吐痰涎、胸脘闭闷，牵连腰痛，正是湿浊壅滞、痰湿内阻之象。脚气古称壅疾，最虑上冲，冲则虚阳上", "c": "主湿滞"}, {"id": "c:细+涩+小+弱", "n": "细小涩弱脉", "o": "细小涩弱脉总起来主气血大虚，尤多见于产后。细主血少，涩主血行滞涩，弱主气衰，小主脉道不充，四者相合，反映气血两亏、脉道失充之病机。原文以产后为例，指出“无得令虚，当大补气血为先”，并强调“一切病多是血虚”，故细涩弱脉为气血大虚之常脉。同时，产后血晕可因虚火载血", "c": "主气血大虚"}, {"id": "c:数+细+涩+小", "n": "细小涩数脉", "o": "细小涩数脉总属虚损之候，以阴血亏少为根本，兼见血行不畅与虚热内扰。其病位涉及心、脾、肝、肾四脏，核心病机为心脾之亏、肝肾内损，导致阴血匮乏、脉道不充（细小）、血行滞涩（涩）、虚热内生（数）。诸类病机相互关联：阴血亏少是基础，血行不畅为阴血虚之继发，虚热内扰为阴", "c": "主阴血亏少"}, {"id": "c:数+细+滑+小", "n": "细小滑数脉", "o": "细小滑数脉总属虚实夹杂之候。细主阴虚，小主气弱，二者为虚；滑主痰，数主火，二者为实。合而观之，其病机核心为“虚弱之中，兼有痰火”，即阴亏气弱为本，痰火内扰为标。虚处在于阴液耗伤与正气不足，实处在于痰湿与火邪交结。临床可见面红、咳嗽、烦热、气短、便燥、筋惕肉𥆧等", "c": "主阴虚火旺"}, {"id": "c:细+滑+小", "n": "细小滑脉", "o": "细小滑脉总起来主本虚标实、虚实夹杂之候。细主阴血亏虚，小主正气不足，二者为虚；滑主痰湿，为实。合而观之，其病机核心为气血不足为本，湿痰内阻为标。原文脉来细耎小滑，痛痹复发，右腿膝壅滞不能下行，正是湿痰阻络、气血不畅之象。各类之间，主气血不足言其虚，主湿痰阻络言", "c": "主湿痰阻络"}, {"id": "c:细+小+紧+急", "n": "细小紧急脉", "o": "细小紧急脉总起来主血气不足、寒热错杂及肾之病变。其“细小”反映血气俱少，心主血脉，血少则脉道不充，故主血虚；其“紧急”可因热邪内郁、脉道拘急，或寒性收引、脉道挛缩，故寒热皆可见。原文以脉小主血少、脉沉细滑疾主热、脉迟紧主寒、小而紧病在肾，说明此脉非单一病机，而", "c": "主血少"}, {"id": "c:细+小", "n": "细小脉", "o": "细小脉总以“虚”为纲，细主阴血不足，小主气虚，合而示气血阴阳亏虚、脉道不充。其核心病机为气血两虚与阴血亏虚，多见于久病、失血、劳损、吐泻之后。在此基础上，因虚而寒、因虚而饮、因虚而湿，故又主阳虚寒盛及虚寒夹饮；正虚不能抗邪则余邪留恋，故主正虚邪恋；虚而兼痰、湿", "c": "主气血两虚"}, {"id": "c:细+虚+涩+小", "n": "细小虚涩脉", "o": "细小虚涩脉总主虚损，尤以阴血枯槁、阳气郁结、胃气将败为要。细为血少，涩为血枯，虚为不足，故主阴血枯槁；涩又主气滞，阳气郁结不行，故主阳气郁结；脉细小虚涩，胃气衰败，故主胃气将败。三者相互关联：阴血枯槁则阳气失养而郁结，阳气郁结则胃气不降，久则胃气将败，形成膈症", "c": "主阴血枯槁"}, {"id": "c:细+小+软", "n": "细小软脉", "o": "细小软脉总属虚象，主正气不足、气血阴阳亏虚，兼夹湿邪为患。其脉细小为脉道不充，软为无力，故总以虚为本。具体而言，或主正虚未复，见于病后脉未复常；或主气血两虚，脉软弱细小如绵；或主阴津不足，脉濡细而软；或主虚损夹湿，脉沉细软小，脾肾阳虚、水湿泛滥；或主暑湿中停，", "c": "主正虚"}, {"id": "c:细+小+迟+和", "n": "细小迟和脉", "o": "细小迟和脉总起来主营卫不和、营虚卫气不充，并涉及伏邪夹新寒致疟。其核心病机是营卫失调：细为营虚，迟为卫气不充，二者相合则营卫不相和谐，阳气不达，故见寒重热轻之疟。原文以“卫气不与营和”为总纲，说明此脉非邪盛实脉，而是正虚邪恋、营卫失和之象。各类之间相互关联：营", "c": "主营卫不和"}, {"id": "c:细+小+迟", "n": "细小迟脉", "o": "细小迟脉总起来主营卫不和、正虚邪恋。细为营虚，迟为卫气不充，二者相合则营卫失调，阳气不达，故见寒重热轻之疟。此脉非邪盛实脉，而是正虚邪恋之象。在伤寒温病中，脉沉小或细小难得多主正虚不能抗邪，邪气内陷，预后不良；汗后脉沉小则示津伤而脉静，为顺。各类病机相互关联：", "c": "主营卫失和"}, {"id": "c:细+平", "n": "细平脉", "o": "细平脉在此段中主要体现为“青细为平”的平脉，但结合脉色合参，其相关脉象主病机可归纳为寒实、平脉、痫候、热四类。青大脉主寒实，因大则邪实、青则寒；青细脉为平，因细而柔和、色青应春；鱼际脉黑主痫，赤主热，皆以脉色合参辨病性。细脉本身主虚，但在此特定语境下，青细为小", "c": "主寒实"}, {"id": "c:弦+细+大", "n": "细弦大脉", "o": "细弦大脉总起来主虚实夹杂之证，以正虚为本、邪实为标。细弦多主阴血不足、中气虚或肝木失柔，大则主邪气壅盛，如风火、痰湿、暑湿等。三类具体脉象（弦大细弱、细弦洪大、弦细滑大）均体现由实转虚或虚中夹实的动态过程：或痰火风实为始、真水亏竭为本，或中气虚为本、肝郁痰滞为", "c": "主风火亢盛"}, {"id": "c:弦+细+弱", "n": "细弦弱脉", "o": "细弦弱脉总属阴脉，以虚为本，兼见弦象所主之郁、饮、痛、风等。细弱主气血阴阳亏虚，弦主气郁、饮邪、寒痛及肝风阳浮。诸段所主病机可归纳为虚、饮、寒、气郁、阳浮风动、湿热痰火六类。其中虚为根本，或为营血大亏，或为气阳虚寒，或为脾虚气弱；弦则因虚而郁、因虚而饮停、因虚", "c": "主虚"}, {"id": "c:数+弦+细+微", "n": "细弦微数脉", "o": "细弦微数脉总属虚实夹杂之候，以阴血亏虚为本，肝旺风动、虚热内扰为标，并可兼夹湿热或湿邪留恋。细主阴亏，弦主肝旺，微数主虚热或湿热未清，诸象合参，反映正虚邪恋、本虚标实之病机。各段所主虽有偏重，或重在厥阴头痛，或重在肝火烁阴，或重在肝风上旋，或重在湿热未清，或重", "c": "主阴血亏虚"}, {"id": "c:弦+细+滑+微", "n": "细弦微滑脉", "o": "细弦微滑脉总起来主肝郁、痰浊、阴伤、湿热、阳痹等病机，其核心为虚实夹杂、郁痰互结。细主阴血不足，弦主肝郁气滞，滑主痰湿内阻，微滑则痰浊较轻。三段原文虽病位不同，或胸膈、或精窍、或胃府，但均见肝郁化火、痰湿阻遏、阴液亏耗之象。肝郁可生火，火灼阴伤；痰湿可阻气机，", "c": "主痰浊"}, {"id": "c:数+弦+细+缓", "n": "细弦数缓脉", "o": "细弦数缓脉总以细弦数为主，缓为兼象。细主阴伤，弦主肝旺气逆，数主火动，三者相合，总归阴虚火旺、肺肾阴伤、冲阳偏亢之病机。原文“肺肾阴伤不复”点明病本在阴亏，“冲阳稍平”示火势虽减而未清，故脉仍细弦数；而“稍缓”一象，乃数势略退、胃气渐和之征，主病势向缓而非病愈", "c": "主阴虚火旺"}, {"id": "c:弦+细+大+洪", "n": "细弦洪大脉", "o": "细弦洪大脉在此案中并非同时并见，而是前后对比：前诊脉细弦而不洪大，与虚里跳动相应，主中气虚不能制木；服攻劫后右部转滑微大、寸脉细滞，主肝郁气结、痰滞机窍。总起来看，此脉所主病机以中气虚为本，肝郁气结为标，痰滞机窍为变。中气虚则木旺风动，魂神不安；气郁则痰生，痰", "c": "主中气虚"}, {"id": "c:弦+细+缓", "n": "细弦缓脉", "o": "细弦缓脉总以细弦为主，缓为兼象。细主阴伤、湿滞，弦主痛、主肝旺气逆、主木克土，缓主湿滞、主胃气尚存或渐和。合而观之，其病机主要涉及痛证、湿滞、血瘀、阴伤胃和及木克土等几类。原文三案中，疝痛案以细弦缓按涩断为血病，示痛、湿滞、血瘀并存；伏暑泄泻案以细弦缓示暑湿内", "c": "主血瘀"}, {"id": "c:数+细+弱", "n": "细弱数脉", "o": "细弱数脉总以虚为本，数为其标。细弱主气血阴阳亏虚，脉道不充；数虽主热，然与细弱同见，多为虚热、阴火或虚阳浮越，非实火可下。其病机大致可分五类：气血两虚为根本，虚热内扰为常见之标，脾胃虚寒示中阳不振，肾虚不摄示下元亏虚、阴火上逆，正虚邪凑则见于内伤兼外感之变。五", "c": "主气血两虚"}, {"id": "c:细+滑+弱", "n": "细弱滑脉", "o": "细弱滑脉总起来主虚实夹杂之证，以正虚为本、邪滞为标。细弱主脾胃气虚、气血不足，甚则下元亏虚、肝血亏耗；滑主湿滞内蕴，或兼数则为湿热积滞。诸类之间相互关联：脾虚不运则湿滞内生，湿滞久蕴可化热成积；气血亏虚则肝木失柔，虚风内动；而邪滞未去又进一步耗伤正气。故其病机", "c": "主脾虚湿滞"}, {"id": "c:细+弱+缓", "n": "细弱缓脉", "o": "细弱缓脉总属虚象，以气血不足、脾胃虚弱为核心。细弱主气血两虚、脉道不充，缓主脾虚湿滞、病势尚缓。其具体所主，一为气血两虚，二为脾虚湿滞，三为胆虚痰扰，四为阴血不足、阳不交阴。各类之间相互关联：气血虚为共同基础，脾虚则气血生化不足，湿滞又碍脾运；胆虚痰扰与阴血不", "c": "主气血两虚"}, {"id": "c:细+弱", "n": "细弱脉", "o": "细弱脉总以虚为本，细主阴血不足、脉道不充，弱主阳气衰微、鼓动无力，合而示气血阴阳亏虚。其病机大致可分六类：气血两虚为最常见之根本，阴虚精亏示真阴耗损，阳虚寒盛示元阳衰微，脾胃虚弱示中焦化源不足，虚风痰浊示阴亏于下而风痰上扰，正虚邪恋示正气不足、无力托邪。六类之", "c": "主气血两虚"}, {"id": "c:数+细+浮+微", "n": "细微浮数脉", "o": "细微浮数脉总起来主气阴两伤、虚阳外越、虚热内扰之病机。细为阴血不足，微为正气衰微，浮为虚阳外越，数为虚热，四者并见，非表非实热，实为脾胃虚损、气阴两亏、虚阳浮越之候。其核心在于误治苦寒，损伤脾胃，气阴耗伤，阴不敛阳，虚阳外浮，虚热内生。三类病机相互关联：气阴两", "c": "主气阴两伤"}, {"id": "c:细+滑+微", "n": "细微滑脉", "o": "细微滑脉总起来主虚实夹杂之候，以虚为本，以痰湿为标，并可主妊娠。细主阴血不足，微主阳气衰微，滑主痰湿内阻，微滑则痰浊较轻。原文一例产后经闭、形瘦面紫、呕吐声哑、手指挛拳，脉细微近滑而尺脉不绝，断为妊娠恶阻，说明此脉既可见于气血亏虚、痰湿中阻之杂病，又可为妊娠之", "c": "主妊娠"}, {"id": "c:细+急", "n": "细急脉", "o": "细急脉总起来主肝虚火动、阴血亏耗、筋脉拘急及脾肾虚损之病机。细为阴血不足、脉道不充，急为火性劲急或筋脉拘急，故其核心为阴亏火旺、本虚标实。各类之间相互关联：肝血虚则木火内动，火性劲急而脉急；肝木乘脾，耗肾水而克脾土，则脾肾虚损；阴血虚少，筋脉失养，风邪客之，则", "c": "主肝虚火动"}, {"id": "c:数+细+促", "n": "细数促脉", "o": "细数促脉总属阴精亏耗、虚热内炽、气逆不续之候，以“细”为阴血精津不足，“数”为热邪内扰，“促”为气逆不续或热盛阴伤、脉道急迫。其核心病机为肝肾精血内耗、阴亏热炽，进而冲脉气逆、根本先拨，或正虚邪郁、气机逆乱，甚则火旺灼络而血溢。各类之间相互关联：精血内耗则阴亏", "c": "主精血内耗"}, {"id": "c:数+细+实", "n": "细数实脉", "o": "细数实脉总主暑热为病，兼涉虚与血伤。细数者，数为热，暑为热邪，故主暑热；暑热伤气，脉宜虚，故数又主虚；若脉不虚而反实，则为热药伤血，邪实非正实。三段病机相互关联：暑热为因，伤气为虚，热伤血为变。细数实脉既可见于暑病本虚标热之常，又可见于热药误治后热伤血分之变，", "c": "主暑热"}, {"id": "c:数+弦+细+滑", "n": "细数弦滑脉", "o": "细数弦滑脉总起来主痰湿、火盛与阴亏相互夹杂之病机。其脉象由细、数、弦、滑四象复合而成：细主阴分不足，数主火盛，弦主肝气郁滞或肝阳易动，滑主痰涎内蕴。故其病机核心为阴亏火盛，灼津成痰，痰火内蕴，肝气不化。各类之间相互关联：痰湿内蕴可因寒湿困阻肝脾，气机窒塞，痰浊", "c": "主痰湿内蕴"}, {"id": "c:数+细+微+弱", "n": "细数微弱脉", "o": "细数微弱脉总属虚实夹杂之候，以阴伤热炽为核心，兼见气衰与气郁。细数主阴液亏虚、火热内炽，为火热劫烁肺胃、阴津大伤之象；弱主气衰，示正气不足；弦主郁，示气机郁滞。三者相互交织：火热炽盛则伤阴耗气，阴伤气衰则脉细弱，气机郁滞则脉弦。原文'左脉细弦而数，右脉细数微弱", "c": "主阴伤热炽"}, {"id": "c:数+细+浮+微+濡", "n": "细数微浮濡脉", "o": "细数微浮濡脉总起来主元阳欲脱、虚阳外越，兼有湿虚之象。其核心病机为误治清散太过，真阳受损，阴伤阳浮，虚阳外越，故脉见细数微浮而濡。细数为阴伤阳浮，微浮为虚阳外越，濡为湿为虚，诸脉并见，非热非表，实为元阳摇摇欲脱之候，犹火垂垂欲灭。三类病机中，阳脱为急为重，虚阳", "c": "主阳脱"}, {"id": "c:数+细+滑+微", "n": "细数微滑脉", "o": "细数微滑脉总起来主阴伤火旺、痰湿内聚，并可累及肺损。细为阴液亏虚，数为火热内盛，滑为痰湿凝聚，微则示病势尚存出入之机。两段原文均见于久咳或寒热不净之候，痰湿郁久化热，热邪伤阴，阴伤又生内热，形成痰、热、虚三者交织之局。案一久咳损肺，阴阳二气有偏，气即为火，液即", "c": "主阴伤"}, {"id": "c:数+细+急+促", "n": "细数急促脉", "o": "细数急促脉总起来主阴伤火旺，兼涉湿热痰浊与络损血溢。其核心病机为阴液亏虚、虚火内炽，脉细为阴伤，数为热，急促为火势急迫。在此本虚标实基础上，可因湿热久滞、痰浊内蕴而兼右关弦滑；火旺灼伤血络，则见吐血，形成络损血溢之变。三者相互关联：阴伤火旺为根本，湿热痰浊为兼", "c": "主阴伤火旺"}, {"id": "c:数+细+涩", "n": "细数涩脉", "o": "细数涩脉总起来主阴血亏虚、郁热内炽、血瘀气滞、痰火郁结、虚风内动及本虚标实诸类病机。其核心为阴血不足（细）、血行不畅（涩）、虚热或郁热内生（数）三者相合。阴血亏虚为发病基础，脉道不充则细，血行滞涩则涩；阴虚不制阳，或气郁、血瘀、痰凝日久，皆可化热，故数。热郁可", "c": "主阴血亏虚"}, {"id": "c:数+细+滑+大", "n": "细数滑大脉", "o": "细数滑大脉总属虚实夹杂之象。细数主阴液亏虚、邪火内炽，滑大主痰热壅盛。四类病机相互关联：阴液亏虚则水不济火，邪火内炽则灼阴生痰，痰热壅盛又进一步耗伤气阴，形成正虚邪恋之势。原文“气阴略立定，邪火又复上炎”点明正虚与邪火并存，脉见细数中兼滑大，提示正不敌邪，病情", "c": "主阴液亏虚"}, {"id": "c:数+细+涩+短", "n": "细数短涩脉", "o": "细数短涩脉总起来主痰火郁结、津伤气滞，并可据此判断胃气存亡。其脉细主阴伤，数主热，短涩主气滞痰凝，合而反映痰火内壅、津液耗伤、气机不畅之病机。原文所载噎食案中，患者呕痰、烦热、便秘，显系痰火为患；又经汗下，津伤气滞更甚。然脉得流利平和，则示胃气未败，病尚可治。", "c": "主痰火郁结"}, {"id": "c:数+细+硬", "n": "细数硬脉", "o": "细数硬脉总起来主邪毒壅盛、热结阴伤之证。其脉细为阴液耗伤，数为热邪亢盛，劲硬沉取有力为邪毒胶结、壅滞不通。三者相互关联：热毒炽盛则伤阴，阴伤则脉细；邪毒与糟粕相结，壅滞大肠，气血不畅，故脉劲硬有力。此脉虽见于泄泻日久，然脉不虚软，反见劲硬，提示非虚寒而属邪实，", "c": "主热盛"}, {"id": "c:数+细", "n": "细数脉", "o": "细数脉总属阴血亏虚、虚热内扰之象，以虚为本，以数为标。细主阴血不足、脉道不充，数主热，合而多示阴液亏耗、虚火内动。其具体所主，可因正气盛衰与邪气性质而异：若纯属内伤，则见阴虚内热、虚劳损怯、血虚火旺；若虚中夹实，则见正虚邪恋、痰热湿郁；若阴亏阳浮，则见阳浮气逆", "c": "主阴虚内热"}, {"id": "c:数+细+芤", "n": "细数芤脉", "o": "细数芤脉总起来主阴血亏虚、热邪内扰之证，其病机核心为‘虚’与‘热’并存。细脉主阴亏正虚，芤脉主失血伤阴，数脉主热，三脉合见则揭示阴血耗伤而热邪未清，或虚火内扰。从所收四段看，或为邪热留恋而营阴已亏（），或为暑邪深入而阴分久亏（），或为阴精耗损、虚火内扰之虚损劳", "c": "主热"}, {"id": "c:弦+细+沉+硬", "n": "细沉弦硬脉", "o": "细沉弦硬脉总起来主湿热蕴结下焦、气机壅滞，兼有阴伤。脉细为阴液亏虚之象，沉候弦硬为湿热结聚膀胱、气机壅滞之征。原文小溲淋痛、闭癃不爽甚至涓滴不通，正是湿热蕴结膀胱、气化不行所致，恐致癃闭。三类病机中，湿热蕴结是核心，气机壅滞为其直接结果，阴伤则为湿热久蕴所伤，", "c": "主湿热蕴结"}, {"id": "c:细+沉+濡", "n": "细沉濡脉", "o": "细沉濡脉总属湿邪为患与里虚寒湿之象。细主营血不足或虚损，沉主病在里，濡主湿滞。三者相合，多示湿邪内蕴、阳气不宣，或气血暗衰、寒湿伏于经络。其病机可归纳为湿滞、里虚、寒湿及虚实夹杂四类：湿滞为标，里虚为本，寒湿为邪，虚实夹杂为常见格局。湿邪阻滞气机则脉细濡，阳气", "c": "主湿滞"}, {"id": "c:细+涩+和", "n": "细涩和脉", "o": "细涩和脉总起来主阴血亏耗、湿滞不畅、邪郁液亏及瘀血未尽等病机，其核心为阴液营血不足与邪滞内阻并存。细脉主阴血虚，涩脉主血行涩滞、湿阻或瘀血，二者相兼，多示正虚邪恋、虚实夹杂之候。各分类之间相互关联：阴血亏耗为根本，湿滞、邪郁、瘀血为标象，而脉象较和则反映营液渐", "c": "主阴血亏耗"}, {"id": "c:细+涩", "n": "细涩脉", "o": "细涩脉总主阴血亏虚为本，兼夹气滞、血瘀、痰湿、寒凝、湿热、肝郁风动等标象。细为血少脉道不充，涩为血行不畅、气机涩滞，故其核心病机为阴血亏虚、脉道不利。诸类之间相互关联：阴血亏虚可致脉道不充而涩，气滞血瘀、痰湿内阻、寒凝血瘀、湿热壅遏等实邪又可加重气血不畅；虚损", "c": "主阴血亏虚"}, {"id": "c:数+细+滑", "n": "细滑数脉", "o": "细滑数脉总属虚实夹杂之象，以阴液亏虚为本，痰湿热邪为标。细主阴血不足，滑主痰湿内蕴，数主热邪亢盛，三象并见提示正虚邪恋、本虚标实。其病机可归纳为五类：阴液亏虚是共同基础；痰湿内蕴与热邪亢盛常相合为患，形成痰热或湿热；肝火痰热为常见具体病机，多见于木火刑金、肝阳", "c": "主阴液亏虚"}, {"id": "c:细+滑", "n": "细滑脉", "o": "细滑脉由细与滑复合而成，细主阴血、气、津液之不足，滑主痰、湿、热、瘀及孕脉之血盛。故其总病机为虚实夹杂、本虚标实：虚以阴血亏虚、气虚、津伤为基础，实以痰湿内蕴为核心，并可化热成痰热、湿热，或兼肝旺、瘀血阻络。各段原文反复出现'细为阴血不足，滑为痰浊内蕴'、'正", "c": "主阴血亏虚"}, {"id": "c:细+濡+弱", "n": "细濡弱脉", "o": "细濡弱脉总起来主气血两虚，兼夹湿、热等邪，形成虚实夹杂之候。其脉象细濡弱无力，反映正气亏虚，气血不能充盈脉道；而右关独觉弦滑，又示湿滞中焦、热蕴肠腑。故其病机以虚为本，以湿、热为标，虚中夹实。各分类之间相互关联：气血虚为根本，湿滞与热蕴为病邪，虚实夹杂为综合表", "c": "主气血虚"}, {"id": "c:数+细+微+濡", "n": "细濡微数脉", "o": "细濡微数脉总起来主气虚、湿阻、内热，且多相兼为病。细主虚，濡主湿，数主热，微则示虚象不显或兼湿。原文以'气虚伤湿热'概括其病机核心，并见于痿痹、眩晕等症。四类病机中，虚、湿、热可单独出现，但更多是湿热兼气虚的复合病机，反映本虚标实、湿郁化热之态。脉不浮弦非风，", "c": "主虚"}, {"id": "c:细+滑+濡", "n": "细濡滑脉", "o": "细濡滑脉总以细濡为本、滑为标，主正虚夹湿、痰、热之候。细濡示气阴不足、血虚或湿滞，滑示痰湿、热邪或经水壅盛。其病机大致可分五类：痰湿内蕴、气阴两虚、血虚湿滞、湿遏热伏、表虚湿滞。诸类之间常相互兼夹，如气阴两虚可兼痰湿，血虚可夹湿滞，表虚可激内热。脉象虽细濡而滑", "c": "主痰湿内蕴"}, {"id": "c:细+濡+缓", "n": "细濡缓脉", "o": "细濡缓脉总起来主阳气不足、卫气空疏、阳微阴盛之证。细为阳气虚衰，濡缓主卫外不固与阴寒内盛，三者相合，反映人体阳气不振、卫外无力、阴寒内生的病理状态。原文以‘清阳不振，卫气空疏’为总纲，具体表现为头胀畏风、汗泄、鼻涕、食入欲便等阳气无力升举之症，腹胀则为阳微阴盛", "c": "主阳虚"}, {"id": "c:细+濡+软", "n": "细濡软脉", "o": "细濡软脉总属虚象，主气血不足、脾肺俱虚、气虚湿滞。细为阴血少，濡软为气虚湿滞，三候相合，示正气亏虚、脉道不充、鼓动无力。原文以久咳汗出、呕涎、凛寒为例，说明三焦气海空虚、卫外不固，脾肺俱虚，痰湿内生。其病机以虚为本，湿滞为标，虚实夹杂而以虚为主。与实痰实火之滑", "c": "主气血不足"}, {"id": "c:细+疾+硬", "n": "细疾硬脉", "o": "细疾硬脉总起来主阴寒内盛、格阳于外之病机。细为阴寒内盛，气血被抑；疾为阳格于外，虚阳外越；硬为寒凝脉道，拘急收引。三者并见，反映阴寒极盛于内，逼迫虚阳浮越于外，形成阴盛格阳之危候。原文以寒湿脚气上冲为例，见脉细疾而硬，断为阴甚格阳，格拒不入，故见阴躁不能卧、呕", "c": "主阴寒内盛"}, {"id": "c:细+疾", "n": "细疾脉", "o": "细疾脉总属阴阳失调、虚实夹杂之候。细主阴伤、阳虚，疾主热、主虚阳躁动。其病机主要有四类：一为阴伤阳浮，见于热病后期或肾水干竭，阴不制阳，虚阳外越；二为阴盛格阳，阴寒内盛，逼迫虚阳浮越于外，形成危候；三为寒痰壅盛，阳虚寒凝，痰浊内阻，邪正相争；四为肾水枯竭，阴精", "c": "主阴伤阳浮"}, {"id": "c:弦+细+硬", "n": "细硬弦脉", "o": "细硬弦脉总起来主肝郁血滞、阴伤津涸、胃气衰败及虚兼停饮四类病机。其脉细为阴血不足，硬为津液枯竭或胃气衰败，弦为肝郁气滞或疟邪未透。四类之中，肝郁血滞多见于内伤杂病，因情志不遂而致肝脾两亏；阴伤津涸与胃气衰败多见于温病或疟疾误治，津液劫夺，真脏脉现，预后不良；虚", "c": "主肝郁血滞"}, {"id": "c:细+硬", "n": "细硬脉", "o": "细硬脉总起来主阴血亏虚、邪毒蕴结与寒凝气滞三大类病机。其脉细为阴血不足或气血两亏，硬为脉道失濡、津液枯竭或寒凝拘急，二者相合，多呈虚中夹实、本虚标实之象。具体而言，或主肝肾阴亏、气血两亏；或主湿毒、热毒、疟邪等邪毒壅结，胶结不通；或主肝郁血滞、沉寒痼冷、阴寒格", "c": "主阴血亏虚"}, {"id": "c:数+细+空", "n": "细空数脉", "o": "细空数脉总属虚损之候，以阴虚为核心，虚热、津亏、形神衰败为其演变。细为阴亏，空为脉道不充、阴血衰少，数为虚热内扰，三者相合，揭示阴液亏耗、虚火内生、津血不足、正气渐损的病机链条。原文“冲年阴虚，疟后不复，咳呛痰稠，形神皆夺”正是阴虚火动、津液耗伤、虚损已成之象", "c": "主阴虚"}, {"id": "c:细+空", "n": "细空脉", "o": "细空脉总属虚候，以阴血亏虚、精血衰少为基本病机。细主阴血不足，空主脉道不充、气不摄固，故见精伤于下、气耗于上之劳怯重病。若兼弦急，则虚中夹实，阴血亏而湿痰瘀血内滞，气机逆乱；若兼数，则阴虚火旺，虚热内生，津血耗损。各类之间以正虚为本，或气不固，或夹实邪，或化虚", "c": "主精血亏虚"}, {"id": "c:细+虚+空", "n": "细空虚脉", "o": "细空虚脉总属虚中夹实之候。其虚在少阴，阴血不足，脉道不充，故脉细而空虚；其实在中焦，伏饮内停，阻滞气机，故见嗽逆呕恶。虚为病之本，饮为病之标，二者相互影响：少阴空虚则脾运不健，易生饮邪；伏饮内阻则气血生化乏源，更伤少阴。原文虽言‘脉细虽属少阴空虚’，但更强调‘", "c": "主虚"}, {"id": "c:细+紧+伏", "n": "细紧伏脉", "o": "细紧伏脉总属阴寒内盛、阳气被遏之候。细主阳虚，紧主寒痛，伏主邪深伏于里，三象相合，集中反映寒邪深入、阳气不伸的核心病机。其主病可归为四类：一主寒痛，因寒凝经脉、气血不通而身痛如刮；二主阳虚，因素体阳弱、脉道不充而脉细；三主寒邪深伏，因寒邪内侵、阳气不能外达而脉", "c": "主寒痛"}, {"id": "c:数+弦+细+紧", "n": "细紧弦数脉", "o": "细紧弦数脉总属虚实夹杂、本虚标实之象。细主阴伤，紧主痛主痰，弦主肝主气逆，数主热，四象合参，主要揭示两类病机：一为痰凝肝胆、化热生风，多见于痫证等痰热动风之疾；二为阴亏火旺、气逆血溢，多见于失血后正虚邪盛之危候。两类均以阴伤为本、痰热为标，但前者侧重痰凝化风，", "c": "主痰凝化热生风"}, {"id": "c:数+细+紧", "n": "细紧数脉", "o": "细紧数脉总属正虚邪盛、本虚标实之候。细主阴伤血少，紧主邪结寒凝，数主热或虚性亢奋。三者合参，揭示元气已亏而邪气深入之病机。其具体所主，一为正虚邪盛，病深日久，精神殆尽；二为阴伤热结，阴液耗伤而邪热内结；三为胃气衰败，饮食不进，化源告竭。三类均以正虚为本、邪盛为", "c": "主正虚邪盛"}, {"id": "c:数+细+浮+紧", "n": "细紧浮数脉", "o": "细紧浮数脉总起来主寒热错杂、气血壅滞之病机。细紧主寒束血滞、毒蓄收束，浮数主热迫血溢、热毒内蒸，四象合参，寒热交织，气血壅滞。其具体所主，一为肺伤气壅，因两寒相感、情志化火，肺气伤而血随气逆；二为毒蓄内热，疮毒蓄内而外显表热。两类均以寒热错杂为共同基础，肺伤偏", "c": "主肺伤气壅"}, {"id": "c:数+细+浮+紧+芤", "n": "细紧浮数芤脉", "o": "此段以肺脉为纲，浮而毛为平脉，浮毛短涩为肺脉正象，应秋金轻虚之常。其病机总以肺气失和为核心：太过则中央坚、两头虚，气壅于上而胸满背痛；不及则短涩无力，气弱不降而喘咳上气见血。原文又言虚实寒热皆使人喘嗽，说明肺为娇脏，外养皮毛、内荣肠胃，脉象随邪之虚实寒热而变，", "c": "主肺气太过"}, {"id": "c:细+滑+紧", "n": "细紧滑脉", "o": "细紧滑脉总属虚、寒、痰饮相合之象。细主虚，紧主寒，滑主痰饮，三者合见，多示脾胃虚寒、痰饮内停之病机。原文以“细为虚，紧为寒，滑为痰饮”为纲，症见头眩呕吐、畏寒抱火、手足麻木、饮食减少，断为脾胃虚寒痰饮证，并排除血病（“若血病则涩矣”）。三类病机相互关联：虚为根", "c": "主虚"}, {"id": "c:细+紧+疾", "n": "细紧疾脉", "o": "细紧疾脉总属阳虚寒盛、邪正相争之候。细主阳虚，紧主寒邪，疾主邪正相争，三者相合，多见于素体虚弱、寒邪内侵、厥阴受病之证，如原文之寒战发热、胁痛牵引、干呕胸胀。若失治或误汗，则阳气外越，脉可变数大无伦、重取近散，转为汗多亡阳之危候。故本脉所主，以阳虚寒盛为本，邪", "c": "主阳虚寒盛"}, {"id": "c:细+紧", "n": "细紧脉", "o": "细紧脉总以寒、虚为纲。细主阳气虚衰、阴血不足，紧主寒邪内盛、疼痛积结，二者相合，多示虚寒内盛、寒凝气滞之病机。其具体所主，或为寒凝气滞，或为阳虚寒盛，或为虚寒夹积，或为寒凝厥阴，或为寒伤血络，甚则寒盛阳衰、阴阳格拒。各证虽表现不同，然总不离“寒”与“虚”两端：", "c": "主寒凝气滞"}, {"id": "c:弦+细+结", "n": "细结弦脉", "o": "细结弦脉总属本虚标实、虚实夹杂之候。细主阴虚，揭示病后阴精亏耗之本；结主痰阻气滞，弦主风动，二者反映痰浊内阻、肝风内动之标。三者相合，表明阴虚为本，风痰为标，阳气化风挟痰上旋，闭塞清窍，形成内风挟痰闭塞虚窍之证。脉象与舌强不能言、痰声如锯、眩晕肢麻等症相符，体", "c": "主阴虚"}, {"id": "c:细+缓", "n": "细缓脉", "o": "细缓脉总以虚与湿为纲。细主阴血不足、脉道不充，缓主脾虚湿滞、病势尚缓。三案所示：案1脾虚作泻、经闭虚劳，脉细缓不涩不数，真阴未伤，病机重点在脾虚湿滞、血源不足；案2湿热生虫，阴液已虚，脉细缓，缓非虚寒乃湿热蕴结、正气渐耗；案7遗精止、内热盗汗退，脉细缓，示肾阴", "c": "主脾虚湿滞"}, {"id": "c:细+微+缓+芤", "n": "细缓芤微脉", "o": "细缓芤微脉总属虚象，主正气亏虚。细主血少，缓主气弱，芤主失血，微主阳衰，四脉相合，反映气血阴阳俱不足。在疟疾辨证中，此脉与浮（表）、洪数（热）、沉实（里实）相对，提示疟邪已伤正气，或为内伤疟之脉。其核心病机为虚，可因失血、耗气、阳衰所致，亦可见于疟病后期正虚。", "c": "主虚"}, {"id": "e:细", "n": "细脉", "o": "细脉总以虚为本，主气血阴阳亏虚、脉道不充。其核心病机为气血两虚与阴血亏虚，多见于久病、失血、劳损之后。因虚而寒，故主阳虚寒盛；因虚而运化失职，故主脾虚湿困；正虚不能抗邪，故主正虚邪恋；虚极则阴阳离决，故主虚脱危候；虚而兼夹痰湿瘀热，故主虚中夹实。诸类之间，气血", "c": "主气血两虚"}, {"id": "c:细+虚+弱", "n": "细虚弱脉", "o": "细虚弱脉总属虚损，以正气亏虚为根本。细为血少，虚为气亏，弱为阳衰，三象相合，主气血阴阳俱不足。其病机大致可分三类：一主气血两虚，营卫不充，见体虚易感、面色枯槁、崩后神疲不寐；二主营卫俱虚，阳不外卫、营不内充，故恶寒发热并作；三主阳衰气脱，若兼沉小迟，则阳气衰微", "c": "主气血两虚"}, {"id": "c:细+虚+软", "n": "细虚软脉", "o": "细虚软脉总属不足之候，主气血阴阳亏虚，尤以气血两虚、阴血亏少为核心。细主血少，虚主气衰，软主不足，故凡脉见细虚软者，多提示正气亏弱、营血不足。在此基础上，可因虚致变：或为奇脉空虚、冲气上逆（如案7755），或为肺虚不能制木、虚火上冲（如案7506），或为虚损末", "c": "主气血两虚"}, {"id": "c:弦+细+洪+软", "n": "细软弦洪脉", "o": "细软弦洪脉并非单一脉象，而是细、软、弦、洪等脉的合称，其总病机以虚实寒热错杂为纲。洪大、实大、浮洪主热实，示邪热亢盛而正能抗邪；沉细、虚细、微迟主虚损，示气血阴阳亏虚；浮濡、缓滑主湿滞，示湿邪困阻而正未大伤；沉牢、短涩、数急主邪闭，示邪气壅滞、气血不畅；浮洪、", "c": "主热实"}, {"id": "c:细+弱+软", "n": "细软弱脉", "o": "细软弱脉总属正虚，以气阴两虚为核心，兼见阳气升动不息、摄纳无权之象。脉细主阴血不足，软弱主正气无力，故虚象明显；而两寸动数则示阳气不潜、升动无制，形成上盛下虚之局。原文见痰中夹红、寐汗、纳后饥𩠎、体动气冲等症，皆由气阴亏耗、下元不摄、阳气上逆所致。三类病机相互", "c": "主气阴两虚"}, {"id": "c:数+细+软", "n": "细软数脉", "o": "细软数脉总属虚象，以阴血亏虚为本，虚火、郁热为标。细主阴伤，软主气虚，数主热，三者并见，反映正虚而热扰的复合病机。其具体所主，约分五类：一为虚火内扰，火性上炎下迫，充斥三焦；二为阴亏火旺，水不制火，虚热内生；三为虚风内动，阴亏火旺，风火相煽而致搐动；四为邪郁伤", "c": "主虚火"}, {"id": "c:细+涩+软", "n": "细软涩脉", "o": "细软涩脉总起来主气血亏虚、中阳式微与气滞血涩。细为营血不足，软为气馁不充，涩为血行滞涩，三者相合，反映气血两亏、脉道不利。原文所载气冲失血、寐欲遗精、纳谷不运、神思日倦，以及呕吐清水、痛则欲绝，皆因操持太过、心脾两伤、中阳式微、上下失交所致。其核心病机为虚中夹", "c": "主气血亏虚"}, {"id": "c:细+滑+软", "n": "细软滑脉", "o": "细软滑脉总属本虚标实、虚实夹杂之象。细软主正虚，包括气血阴阳亏虚及脏腑功能减弱；滑主痰湿、湿浊或宿食内蕴。四段原文虽具体病机有气血两亏、湿热未清、下虚上实、肝郁夹湿、宿食停阻等不同，但均以正虚为基础，痰湿、湿浊或食滞为标，且常伴气机不畅、脾运不健。各病机类别相", "c": "主痰湿内蕴"}, {"id": "c:细+缓+软", "n": "细软缓脉", "o": "细软缓脉总主血虚脾弱、筋脉失养之痿。其脉细软为血虚，缓为脾虚，二者相合，反映气血生化不足、筋脉失于濡养。原文以过汗亡血释筋急痛，以细流浅濑喻血虚壅肿，又言脾胃太虚、呕逆少食，复加灸砭耗血伤筋，皆归于此。三类病机相互关联：血虚与脾虚互为因果，脾虚则生化乏源而血愈", "c": "主血虚"}, {"id": "c:细+软", "n": "细软脉", "o": "细软脉总属正虚之象，以气血两虚、阴阳两伤为本，细主阴血不足，软主阳气衰弱，合见则气血阴阳俱虚。其具体病机可归纳为六类：气血两虚、脾肾阳虚、湿郁气滞、虚风内动、虚中夹实、阴阳两伤。其中气血两虚与阴阳两伤为纯虚之候，脾肾阳虚为虚寒之变，湿郁气滞为虚中夹湿，虚风内动", "c": "主气血两虚"}, {"id": "c:细+软+迟", "n": "细软迟脉", "o": "细软迟脉总主脾土虚弱、阳气不运，并常兼肝木乘土之机。细软为脾虚气血不足，迟为阳气不运，故右脉见之，主脾胃虚寒、运化失职。然此案左脉沉小弦，示肝阴不足而肝气偏旺，合之素有肝胃气、胀痛兼呕，则土虚木乘、肝胃不和之病机昭然。三类病机相互关联：脾虚为本，阳运不健为虚寒", "c": "主脾虚"}, {"id": "c:细+缓+迟", "n": "细迟缓脉", "o": "细迟缓脉总起来主虚损与寒伏两类病机。细主血少阴亏，迟主阳运不及，缓主中气虚弱，故其常主气血两衰、中气不足；若兼沉细，则阳气衰微、阴寒内盛，甚则阳气欲脱；若兼微细，则可为燥热深伏、阳气不达之假寒真热证。各类之间以虚为本，或见气血亏虚，或见中阳不振，或见阳衰寒盛，", "c": "主气血两衰"}, {"id": "c:细+长", "n": "细长脉", "o": "细长脉总起来主元阳旺而阴分虚，兼有湿热郁于阳明。其病机以阴分虚为本，元阳旺为长脉之象，湿热为兼邪。原文以左脉细长、右关弦数并见，细为阴分不足，长为元阳偏旺，弦数为湿热郁于阳明。症见舌苔黄浊、气急喘促、心神恍惚、胁背胀逆，皆湿热上熏、中上二焦受累之象。三类病机相", "c": "主湿热"}, {"id": "c:动+结+代", "n": "结代动脉", "o": "结代动脉总属虚证，主血脉虚衰、脉道不利及心气不足。其核心病机为营血亏虚，脉道失充失润，血流涩滞，故脉来结代；血虚不能养心，心气不足，则见心动悸、汗出而闷。原文以「脉结代」「脉道泣涩」「心动悸」「汗出而闷」并述，并以地黄脂液荣养筋骸血络为治，说明结代脉所主以阴血", "c": "主血脉虚衰"}, {"id": "c:和+结+代", "n": "结代和脉", "o": "结代脉总主气血虚衰与邪阻脉道两类病机。虚者，气血不足，脉道不充，搏动不能接续；实者，痰瘀湿热等邪壅滞，脉气受阻，亦现结代。二者常相兼为患。此段中右脉结代较和，示邪势稍退、脉气渐复，但原文强调色犹带赤腻、湿热尚盛，故脉象缓和仅为暂时之象，病机仍以湿热壅盛为主，不", "c": "主气血虚衰"}, {"id": "c:实+结+代", "n": "结代实脉", "o": "结代实脉总起来主实热壅遏之证。此脉虽见结代，但非单纯气血虚衰所致，而是阳明实热内结，壅遏脉道，使气血运行不利而现代象。原文脉洪而不实、舌苔白微黄、大便数日未行，说明热盛而未成实，热结气阻，脉道不畅。治疗若单用炙甘草汤补虚，恐难奏功，宜白虎加人参汤清透实热，热退", "c": "主实热壅遏"}, {"id": "c:结+代", "n": "结代脉", "o": "结代脉总属脉气不相接续之象，其病机以虚为本、虚实夹杂。结脉止无定数，多因气血凝滞、脉道偶阻，病较轻；代脉止有定数、不能自还，多因脏腑之气内亏、不能外达，病较重。归纳其主病，首为气血虚衰、心气不足、阴血亏虚、肾气亏虚，此四类皆属正虚，致脉道不充、鼓动无力，故仲景", "c": "主气血虚衰"}, {"id": "c:实+结", "n": "结实脉", "o": "结实脉总起来主邪气结聚、脉道不通之实证，其病机核心为“结”与“实”。从所收段落看，结实脉可因实热内结、壅遏脉道而现，如结代实脉之阳明实热；可因寒凝水饮与饮食搏结成形而现，如紧实结脉之癖结；亦可因瘀血阻滞、络脉结聚而现，如冲脉为病之七疝瘕聚。此外，结实脉虽以实邪", "c": "主实热内结"}, {"id": "c:涩+结", "n": "结涩脉", "o": "结涩脉总主气机郁滞、血行不畅，其病机有虚实两端。实者多为气滞血瘀、痰饮阻滞、积阻不通，如痢症之痛、噎膈之痰阻；虚者多为血亏阳伤、七情郁结，如失血日久、龙雷不宁、神思致病。各段原文所示，结涩脉核心在于气血结滞，或兼痰、兼瘀、兼虚，然总不离气机不畅、脉道不利。实者", "c": "主气滞血瘀"}, {"id": "e:结", "n": "结脉", "o": "结脉总属脉气不相接续之象，其病机以气血痰食等阻滞脉道为主，兼有正虚不续。归纳其主病，一为气滞，气机壅塞则脉结；二为痰饮，痰饮结聚阻遏脉道；三为血瘀，瘀血内停脉行不畅；四为正虚，气血亏虚脉气不继；五为邪结，外邪痰食毒气结于胸中或经络；六为寒凝，阴寒内盛凝滞气血；", "c": "主气滞"}, {"id": "c:迟+结", "n": "结迟脉", "o": "结迟脉总起来主寒、虚及寒虚相搏所致的中焦胃气不通之病机。原文以吐家为例，见“阳紧阴数”知寒热相搏，紧主寒、芤主虚，寒虚相搏则“脉为阴结而迟”，胃气不通而噎；趺阳脉微涩则胃气虚寒、下利吐逆、谷不得入。可见结迟脉的核心病机是寒邪与虚气相合，凝滞中焦，致胃气壅塞、升", "c": "主寒"}, {"id": "c:滑+大+缓", "n": "缓大滑脉", "o": "缓大滑脉总起来主痰热湿浊壅盛、气机壅塞之实证。其脉缓主湿，大主热盛气壅，滑主痰涎内蕴，三者相合，反映湿、热、痰浊交结为患，而以痰热秽浊壅阻中焦、气机失降为核心病机。原文见体素丰、苔黄腻、脘下拒按、寒热大作、茎缩溲闭、气喘大汗、眩晕不支，皆痰热湿浊壅阻气机之象，", "c": "主痰热壅盛"}, {"id": "c:大+缓", "n": "缓大脉", "o": "缓大脉总以“缓”为脾虚湿滞之常，“大”为邪盛或虚阳外浮之象。其主病机可归纳为脾虚气弱、湿、虚风内动、湿热、痰湿壅盛、虚中夹热及胃气尚存数类。核心在缓大无力多主脾虚气弱或虚风内动，缓大有力多主湿、湿热或痰湿壅盛；虚中夹热为虚而兼热之变，胃气尚存则为平脉或预后佳象", "c": "主脾虚气弱"}, {"id": "c:大+缓+软", "n": "缓大软脉", "o": "缓大软脉总属脾虚湿盛之候。脉缓大而软，缓大非实，软示不足，为虚中夹湿之象。其病机核心在于脾虚失运，水湿内停。脾虚则运化无权，故脉软而不足；湿盛则脉道弛缓，故脉缓大。二者互为因果，脾虚生湿，湿盛困脾。原文以泄泻伤脾立论，见腹胀泄泻、肢体肿重，治先止泻后补中，终以", "c": "主脾虚"}, {"id": "c:大+缓+长", "n": "缓大长脉", "o": "缓大长脉总起来主湿土纵缓之气，并可见于气衰血亏。其基本病机为湿性濡缓，故脉象从容宽大而长，为太阴湿土当令之常脉；若在病中见之，则因大长而不能内守，反映气衰血亏，如肌肤甲错等外候。各类之间以湿土纵缓为核心：时令之湿土当令与燥湿异用均言其常，而气衰血亏则言其变。常", "c": "主气衰血亏"}, {"id": "c:小+缓+和", "n": "缓小和脉", "o": "缓小和脉总起来主邪退正复而余热未尽之病机。其脉象以缓小和缓为基，反映气血渐复、脉道柔和，是正气来复之象；然右关些数、有升动之气，又揭示中焦郁热未清、气机升动。故本脉所主，以正复为主，兼有余热，属病后向愈而余邪未靖之候。两类病机相互关联：正复则脉缓和，余热则关数", "c": "主邪退正复"}, {"id": "c:小+弱+缓", "n": "缓小弱脉", "o": "缓小弱脉总起来主湿邪、阳虚与气虚。缓脉主湿邪凝滞，湿性黏滞重着，困遏阳气，故脉来弛缓；小弱脉主阳气不足，阳虚不能温养四末，故脉小弱。湿邪与阳虚常相兼为患，如湿温病中湿邪凝遏阳气，脉见小弱而缓。气虚则推动无力，脉道不充，故脉缓小弱，如脾胃气虚、气血不足之证。三类", "c": "主湿邪"}, {"id": "c:小+缓+结", "n": "缓小结脉", "o": "缓小结脉总以“缓”为胃气尚存之象，“小结”为邪滞正伤之征，故其病机以脾胃虚实为核心。四段中，泄注、泄痢、水谷痢均见“脉缓时小结者生”，强调缓为脾脉、胃气未败，小结示邪滞而正未大伤，属邪滞正伤、脾虚湿盛之轻证，预后良好；若脉转为浮大数，则正脱邪盛，主死。另伤寒、", "c": "主胃气存"}, {"id": "c:涩+小+缓+迟", "n": "缓小迟涩脉", "o": "缓小迟涩脉总属阳盛伤阴、脉道不利之候。其脉虽缓小似虚寒，实由阳气偏盛、阴血受伤所致。阳热亢盛，灼伤阴血，则脉小迟涩；阳气旁溢，脉气弛缓，则兼缓象。此脉主奇恒痢等危重证候，见血温身热者预后凶险。四类病机相互关联：阳盛伤阴为根本，阴血亏耗、脉道不利为具体表现，急下", "c": "主阳盛伤阴"}, {"id": "c:缓+平", "n": "缓平脉", "o": "缓平脉总起来以胃气和缓为平，然其主病机随兼脉与脉势而异。若缓而和柔从容，为胃气存、无病之平；若缓而兼强硬弦急，则主心脾受病、水虚木燥、木火载血上行；若缓小迟涩，则主阳气偏盛、阴血亏耗，见于奇恒痢等危证；若缓而坚锐弱散或鸟喙不及，则主脾死胃竭或中虚九窍壅塞。四类", "c": "主心脾受病"}, {"id": "c:弦+弱+缓", "n": "缓弱弦脉", "o": "缓弱弦脉总起来主脾胃气虚、肝木偏旺，进而形成木火乘土之病机。缓弱反映中焦脾胃虚弱，弦脉反映肝木偏亢，二者并见则土虚木贼，肝火乘虚犯胃。原文两段均以'缓弱为脾胃气虚，颇弦为肝木偏旺'为据，断为'木火乘土之病'，并见痫证晨发、目视异色而仆等症。三类病机中，脾胃气虚", "c": "主脾胃气虚"}, {"id": "c:弱+缓", "n": "缓弱脉", "o": "缓弱脉总起来主脾胃气虚、阳气不足，以脾虚为核心。缓为脾土本脉，弱为阳气衰微、气血不足，故其病机多归中焦虚损。脾阳虚衰则运化失职，湿浊内停，发为脘痛胀满、呕涎纳呆；脾虚日久则气血生化不足，见气血两虚、经脉失养；中气亏虚则统摄无权，血溢脉外而呕血；中阳不振则胃气壅", "c": "主脾阳虚"}, {"id": "c:虚+弱+缓", "n": "缓弱虚脉", "o": "缓弱虚脉总属正虚之象，主气血亏虚、骨髓枯竭，并提示正虚邪陷之危候。所举段落中，妇人温病瘥后血脉未和，复因交接受邪成阴易病，脉见缓弱，说明气血已伤、骨髓失充，正气无力抗邪，故见身体重、气力转少、著床不能动摇等症。三类病机相互关联：气血虚为根本，骨髓竭为深重表现，", "c": "主血气虚"}, {"id": "c:弦+微+缓", "n": "缓微弦脉", "o": "缓微弦脉总以缓为胃气之本、微弦为肝木之象，其病机核心在于中气盛衰与肝脾失调。缓而重按少力者，主中气不足、阳明脉弱；微弦不去者，主肝风未靖或肝木乘脾。若缓中带弦而见土虚木贼，则肝脾疏运失司，日久可致血质衃败。四类病机相互关联：中气不足则肝木易乘，肝风未靖与肝脾不", "c": "主中气不足"}, {"id": "c:滑+微+缓", "n": "缓微滑脉", "o": "缓微滑脉总起来主胎孕与血热不固。缓为胃气尚和、平人之常，示正气未大伤；微滑为胎孕之象，又主血分有热。两段原文均见经停漏下、起居如平人，脉缓微滑，断为胎漏。其病机以胎孕为本，血热不固为标，二者相合，故宜和阴泄热、参以调气。若兼濡缓，则又主痰湿内盛、肝阳上亢，然此", "c": "主胎孕"}, {"id": "c:缓+急", "n": "缓急脉", "o": "缓急脉总起来主病机复杂，涉及上实下虚、湿热郁蒸、胎动不安及正虚邪留四类。其核心在于脉象缓急不调，反映气机升降失司、阴阳失衡。寸急尺缓主上实下虚，厥阳变化、内风鼓动；右缓左急主湿热郁蒸，湿郁气分、肝风内动；缓急不调主胎动不安，胎系震损、气机失和；弦急主正虚邪留，", "c": "主上实下虚"}, {"id": "c:弦+虚+洪+缓+空", "n": "缓洪弦空虚脉", "o": "缓洪弦空虚脉总起来主脾虚湿盛、湿热壅盛、中气不足与肝急气滞。缓为脾土本象，洪弦主湿热壅盛，按之空虚则中气不足。诸类相互关联：脾虚湿盛为病之本，湿热壅盛为标，中气不足贯穿始终，肝急气滞为脾虚木乘之变。原文见太阴阳明腹痛、大便常泄或秘、下鲜红血、胁下急缩，脉缓而洪", "c": "主脾虚湿盛"}, {"id": "c:涩+缓", "n": "缓涩脉", "o": "缓涩脉总属气血两虚、湿滞气郁之象。缓为气虚不运或湿邪留滞，涩为血少滞涩或气机不畅，二者相合，多示正虚与邪滞并存。其主病机可归为四类：气血两虚、湿滞气郁、痰瘀积滞、虚中夹实。四类之间相互关联：气血虚则运行无力，易生湿滞痰瘀；湿滞痰瘀久留，又耗伤气血，形成虚中夹实", "c": "主气血两虚"}, {"id": "c:数+滑+缓", "n": "缓滑数脉", "o": "缓滑数脉总起来主痰湿与热相合为患，其病机核心为痰湿内蕴、湿热痰滞，或痰火痹结。缓主湿滞，滑主痰湿，数主热。若脉缓滑不数，则热势不炽或已退，而痰湿仍盛；若脉滑数，则痰火痹结。各段均围绕痰湿与热的不同程度展开：或湿温之邪郁于血分，或湿热痰滞阻于肺胃，或痰火痹结经络", "c": "主痰湿内蕴"}, {"id": "c:滑+紧+缓", "n": "缓滑紧脉", "o": "缓滑紧脉在产后发热的辨证中，主要用以鉴别火证与表寒。其脉象特征为缓滑而不紧，表明内无寒邪紧束，而是火热内盛、气血壅盛。原文指出“凡属太过，皆能生火”，火盛于内则见潮热、烦渴喜冷、便实尿赤等症，脉缓滑正是里热壅盛之征，而非表寒之象。因此，该脉所主病机为火热内盛，", "c": "主火热内盛"}, {"id": "c:滑+缓", "n": "缓滑脉", "o": "缓滑脉总以痰湿内蕴为核心病机，缓主湿、主脾虚、主气机迟滞，滑主痰、主食积、主气血充盛。其主病涵盖痰湿困脾、痰气凝滞、湿痰疟痢、风痰上扰等实证，亦可见于虚中挟痰及妊娠气血充盛之生理状态。各类之间以“痰湿”为纽带：脾虚湿困为生痰之源，痰气凝滞为痰阻气机之变，湿痰疟", "c": "主痰湿内蕴"}, {"id": "c:滑+缓+迟", "n": "缓滑迟脉", "o": "缓滑迟脉总主痰湿内盛、胃阳素弱、肝风乘脾、积热伤津之机。缓滑为湿盛痰聚，耎迟为胃阳不足，左缓滑映肝木乘虚，久则痰湿化热、风阳内动、胃津受灼。四类病机相互关联：胃阳弱则湿痰生，痰湿盛则肝木乘，温药误投则积热伤津，形成痰、湿、虚、热交织之候。脉象缓滑迟并见，正映痰", "c": "主湿痰"}, {"id": "c:滑+缓+长", "n": "缓滑长脉", "o": "缓滑长脉总起来主气血充盛、脾胃健运，属平脉范畴，非病脉。其缓为胃气之和，滑为营血之充，长为气机之畅，三者相合，反映后天脾胃健运、气血生化有源，故虽年五十而天癸不衰、肌肤润泽。原文所载左寸关带弦数，仅为肝郁化热之微兆，与多产、微带相关，属兼见之象，不改变全脉平顺", "c": "主气血充盛"}, {"id": "c:濡+缓+软", "n": "缓濡软脉", "o": "缓濡软脉总属虚证，以阳气虚、气虚为核心病机，尤与肺脏虚损密切相关。脉缓为阳气弛缓，濡软为鼓动无力，故主阳气不足、气虚不充。原文以肺虚腹胀为例，明言“肺阳不足，脉缓濡软”，并指出与肺阴虚之“虚细数”、气散之“散”脉相鉴别，强调此脉为阳气虚而非阴亏。三类病机相互关", "c": "主阳虚"}, {"id": "c:数+紧+缓+动", "n": "缓紧动数脉", "o": "缓紧动数脉在此段专指温病初起之脉象，其核心病机为温邪犯肺、风火相煽、热盛伤津。脉不缓不紧，排除中风伤寒；动数并见，主风火内动；两寸独大，主火克肺金；尺肤热、身热自汗、口渴、午后热甚，皆热盛之候。四类病机相互关联：温病为总纲，风火为动数之因，热盛为动数之果，火克", "c": "主温病"}, {"id": "c:紧+缓", "n": "缓紧脉", "o": "缓紧脉总属寒湿困阻、脾虚不运之象，兼见表证、实热、虚寒及肝风脾虚等复杂病机。紧主寒主痛，缓主湿滞脾弱，二者相合，多反映寒湿凝滞、气血壅遏或脾虚气陷。浮缓紧主外邪袭表，营卫失调；缓滑紧主里热壅盛；缓而迟细主虚寒；紧缓弱主肝风脾虚。各类之间以寒湿、脾虚为核心，表证", "c": "主寒湿"}, {"id": "c:细+涩+缓", "n": "缓细涩脉", "o": "缓细涩脉总起来主暑湿伤及气血之病机。暑为阳邪，性热而散，易耗元气，故脉虚；湿为阴邪，其性黏滞，与血相近，伤于血分则血行滞涩，故脉缓细涩。三类病机相互关联：暑伤气分则气虚，湿伤血分则血滞且虚，而暑湿合邪又使气血同病。因此，该脉象既反映湿滞血分的直接征象（缓细涩）", "c": "主湿伤血"}, {"id": "c:缓+结", "n": "缓结脉", "o": "缓结脉总以‘缓’为胃气尚存之象，‘结’（止）为邪滞或阳气不伸之征，故其病机以寒湿痰凝、阳气不伸及脾虚湿盛、正伤邪滞为核心。缓结脉非凶脉，两尺有神则肾气未绝，预后多良；若误用苦寒克伐，反伤中阳，致变证丛生。缓小结脉更偏脾虚湿盛、邪滞正伤之轻证，以缓为脾脉、胃气未", "c": "主寒湿痰凝"}, {"id": "e:缓", "n": "缓脉", "o": "缓脉所主病机广泛，总以“湿”与“虚”为纲。缓为脾土本脉，从容和缓、有胃气者为平脉，病中见之多示胃气未败、邪退正复，预后良好。若缓而无力，多主脾虚气弱，运化失职，湿浊内停；缓而迟细，多主虚寒，阳气不足；缓而滑大有力，多主实热或痰湿壅盛；缓而兼浮，多主风邪伤卫、营", "c": "主湿"}, {"id": "c:缓+芤", "n": "缓芤脉", "o": "缓芤脉总起来主肝胃血泛狂溢之后，胃气尚存而阴血已伤、气火未平之病机。缓为胃气尚存，说明脾胃之气未绝，病虽重而生机犹在；芤为失血中空，直接反映血去阴伤、脉道空虚。二者并见，提示出血之后，正气未至溃败，但阴血已亏，气火未平，阳络受伤。其病机核心是失血伤阴、气火上逆", "c": "主失血"}, {"id": "c:涩+缓+软", "n": "缓软涩脉", "o": "缓软涩脉总主阳气式微、胃气不足、血少气滞及寒饮伤中。缓为胃气不足，软主阳气式微，涩则血少气滞，三者相合，反映中阳受损、运化失司、痰饮内停之病机。原文见胃脘不爽欲嗳、夜来腹胀、吐痰酸水、口鼻吸冷，皆中阳不振、寒饮内停、胃气上逆之候。诸类病机相互关联：阳气虚衰则胃", "c": "主阳虚"}, {"id": "c:缓+长", "n": "缓长脉", "o": "缓长脉总起来主湿土纵缓之气，并涉及风邪入阳明、气血充盛及脾虚湿困等病机。其基本特征为脉道从容宽大而长，核心在于湿性濡缓，故为太阴湿土当令之常脉；若在病中见之，则因大长不能内守，反映气衰血亏。具体而言，缓大长脉主湿土纵缓，兼见气衰血亏；缓滑长脉主气血充盛、脾胃健", "c": "主风入阳明"}, {"id": "u:肿", "n": "肿脉", "o": "肿脉所主病机，总以邪气壅盛、气血郁遏为纲，然有虚实顺逆之辨。邪壅、毒聚属实证，脉多搏指有力，如大头瘟之脉怪而搏指、痈毒之脉部交会，皆邪实壅遏之象；真脏、证脉违属虚败，脉多散漫无根或细软欲绝，如左寸如钩、六脉如丝，为真气散漫或正不胜邪之候。四类之中，邪壅与毒聚相", "c": "主毒聚"}, {"id": "u:脉闭", "n": "脉闭脉", "o": "脉闭脉总属邪闭脉道、气血不通之候，非虚证。其主病机有三：一为阳衰，元阳衰微、命门火绝，阳气不能鼓动血脉；二为毒闭，传染毒菌充塞心脏，心阳痹阻、心脏麻痹；三为痰闭，顽痰壅塞经络，气血不通。三者虽病因不同，然皆致脉道闭阻，故见六脉皆闭、重按不见。阳衰者属正虚至极，", "c": "主阳衰"}, {"id": "c:微+紧+动+芤", "n": "芤动微紧脉", "o": "芤动微紧脉总起来主虚劳失精、阴阳两虚、虚阳不潜之病机。其核心为精血亏虚、阳气扰动、阴阳失交。各类病机相互关联：失精梦交是精血亏虚、虚阳扰动的直接表现；虚寒精亏是精血不足、阳气不能温养所致；阴阳两虚是失精日久、阴损及阳的必然转归；亡阳惊狂是虚阳外越、神不守舍的变", "c": "主失精梦交"}, {"id": "c:大+涩+芤", "n": "芤大涩脉", "o": "芤大涩脉总主瘀血内壅、新血不荣之证。其脉象芤为血虚，涩为血滞，大示邪实，三者相合，反映瘀血阻滞脉道、新血难以化生之病机。原文以“瘀血致壅”为起点，久嗽成劳、骨痿不起，进而肝著成痈，皆由瘀滞不化所致。脉象动态变化——先芤大而涩，瘀血外泄后纯然芤——更证实瘀血为病", "c": "主瘀血内壅"}, {"id": "c:滑+大+实+芤", "n": "芤大滑实脉", "o": "芤大滑实脉总起来主血伤而痧毒内犯之病机。原文以芤为诸痧脉之共同基础，芤主血伤，说明痧毒伤血是基本病理；在此之上，兼见浮、数、弦长动、大滑实、沉细动止不匀等不同形态，分别对应肺、心、肝、脾、肾等脏腑经络，体现痧毒侵犯不同经络的定位。其中“芤大而滑实”专指足太阴脾", "c": "主血伤"}, {"id": "c:数+弦+芤", "n": "芤弦数脉", "o": "芤弦数脉总起来主阴虚火旺、血热妄行、木火刑金及真阴亏虚之病机。芤为阴血亏耗或失血之征，弦主肝火亢盛或木火偏旺，数主火热内炽或君相火炽，三脉合见，核心在于阴分素亏而火势内炽，火逼血行，络伤血溢。各类之间相互关联：阴虚火旺为病之本，火旺则血热妄行，木火亢盛则刑克肺", "c": "主阴虚火旺"}, {"id": "c:弦+芤", "n": "芤弦脉", "o": "芤弦脉总起来主阴血亏虚而肝木偏亢、气机不和之病机。芤为血去脉空、阴血亏耗之征，弦为肝旺气逆、络脉拘急之象，二者并见，核心在于阴血已伤而木火犹炽，虚实夹杂。其所主病机可归纳为失血阴亏、阴虚火旺、肝旺气逆、络伤血溢、虚寒血脱、正虚邪滞、肝胃同病等类。诸类之间相互关", "c": "主失血阴亏"}, {"id": "c:弦+虚+迟+芤", "n": "芤弦虚迟脉", "o": "芤弦虚迟四脉合见，总起来主暑湿蒸郁、气机不畅而兼血虚木郁之候。芤主失血，弦主木郁，虚迟可因湿阻而非纯虚，四者相合，貌似阳虚，实为暑湿内蕴、郁蒸气血所致。原文特别强调“脉之芤弦虚迟尚未足为凭”，须结合胸闷、能食、溺黄三症，方能识破暑湿蒸郁之本质。各类病机之间，暑", "c": "主失血"}, {"id": "c:弱+芤", "n": "芤弱脉", "o": "芤弱脉总主气血精亏、虚风内动之候。芤为阴血不足、脉道不充，弱为阳气虚馁、鼓动无力，二者相合，提示气血两虚为基本病机。在此基础上，若劳心耗阴，则阴不制阳而阳升风动，见痰多眩晕；若肾真内怯、精血亏虚，则下元虚惫，肝风易动而发痫厥，或男子精气衰薄而不育。故其病机以虚", "c": "主肾精亏虚"}, {"id": "c:数+急+芤", "n": "芤急数脉", "o": "芤急数脉总起来主瘀血、血虚与热，三者相互关联。原文脉见左手寸尺弦数而涩，关脉芤而急数，右三部数而虚，弦数主热，涩主血瘀，芤主血虚，急数主瘀热内迫。跌扑后左胁胀痛，明是死血证，瘀血内结而血虚，瘀久化热，故脉象呈现芤急数。治疗用抵当丸下黑血，后以四物汤调理，体现瘀", "c": "主瘀血"}, {"id": "c:数+芤+疾", "n": "芤数疾脉", "o": "芤数疾脉总起来主阴虚络热、气火上炎之失血证。芤脉主失血，数疾脉主热，二者相合，揭示阴血亏虚、热邪内盛之病机。阴虚不能制阳，则虚火内生；气火升腾，迫血妄行，故见失血；阳升于上则背热、血溢，阳不达下则足冷。舌剥苔黄、溲赤皆为热象。四类病机中，失血为直接表现，热为病", "c": "主失血"}, {"id": "c:数+芤", "n": "芤数脉", "o": "芤数脉总起来主阴血亏虚与火热内炽并见之病机。芤脉中空，为失血、阴伤、津亏之征；数脉主热，为实火或虚热之象。二者相合，核心是阴分已亏而火势未清，或热盛灼伤阴血。其具体所主，约分八类：失血阴伤为其本，阴虚火旺、热盛伤津、血热妄行、肝火刑金、阴虚阳越皆由阴亏火旺衍生", "c": "主失血阴伤"}, {"id": "c:数+弦+虚+芤", "n": "芤数虚弦脉", "o": "芤数虚弦脉总主阴血亏耗、气陷虚热之候。芤为失血之象，数主虚热，虚弦为肝脾气陷，四者相合，反映失血日久、阴血下夺、中气下陷、虚热内生、虚风内动之复杂病机。各脉象之间相互关联：失血致阴血亏耗，阴亏则虚热生而脉数，气随血陷则脉虚弦，故失血为因，虚热、气陷、阴亏为果，", "c": "主失血"}, {"id": "c:数+涩+芤", "n": "芤涩数脉", "o": "芤涩数脉总起来主阴血亏虚、血行滞涩、虚热内生之虚劳重候。芤主阴血亏虚、脉道失充，涩示血行滞涩、阴络暗伤，数则虚热内生，三者相合，反映虚劳病中阴血耗损、络伤血渗、虚热内扰的复杂病机。其根本在于脾气虚失统领，血不归经而渗入肠间，日久阴络暗伤，营血亏耗，虚热由生。各", "c": "主阴血亏虚"}, {"id": "c:涩+芤", "n": "芤涩脉", "o": "芤涩脉由芤与涩复合而成，总主血分病机，以血虚、血瘀及其相兼为核心。芤脉浮大中空，主营血虚而脉道不充；涩脉往来滞涩，主血行不畅、脉络瘀滞。二者并见，或偏于虚，或偏于瘀，或虚瘀夹杂。其主血虚者，见产后喘、血虚劳伤、心阴亏耗；主血瘀者，见癥块腹痛、心胞积血、蓄血、上", "c": "主血虚"}, {"id": "c:滑+芤", "n": "芤滑脉", "o": "芤滑脉总属虚中夹实之候，以阴血亏虚为本，痰涎或血伤为标。芤主心血本虚、脉道不充，滑主痰涎内盛或血分受伤。三段原文中，两段论心悸，皆因惊恐伤及心血，经年不愈，痰涎乘虚袭入心包，故脉芤带滑，治当养心安神兼化痰；一段论痧证伤血，痧毒伤及血分，血络受伤而兼痰浊，脉亦芤", "c": "主心血虚"}, {"id": "c:细+芤", "n": "芤细脉", "o": "芤细脉总起来主失血与营阴亏虚，其核心病机为‘血去络伤、阴血不足’。芤脉中空，主失血伤络；细脉如线，主营阴亏少。二者相合，多见于崩漏、失血之后，或老年营阴不摄、内络已损之证。原文明确以‘芤主失血’‘细主营阴亏少’并提，且指出‘向有失血，内络已损’，说明失血与阴亏", "c": "主失血"}, {"id": "e:芤", "n": "芤脉", "o": "芤脉总以'中空'为象，核心病机是阴血亏虚、脉道不充。其主病虽以失血血虚为最直接，然失血之后，或阴精耗损，或气随血耗，或热盛灼津，或瘀血内积，或正虚邪恋，皆可致脉道空虚而见芤。故芤脉所主，实以血虚阴伤为轴心，向外兼涉气分、热邪、瘀血、正虚邪恋等多重病机。诸类之间", "c": "主失血血虚"}, {"id": "c:虚+芤", "n": "芤虚脉", "o": "芤虚脉总以'中空不足'为象，主病机核心为阴血亏虚与气血两伤。芤主血脱，虚主气弱，二者相合，最常见于失血之后，如吐血、衄血、崩漏、瘀流失血，血去脉空则芤，气随血耗则虚。其延伸病机有三：一为阴血亏虚，脉道不充，可见心悸、咳呛、潮热；二为气随血耗，气血两虚，甚则血脱", "c": "主失血血脱"}, {"id": "c:虚+代", "n": "虚代脉", "o": "虚代脉总属元气衰微、气血亏竭之候。其脉止而不还、有常数如更代，非元气大虚不至此。所主病机涵盖气衰、血竭、中虚及胎元不固四类：气衰则脉行无力不能接续；血竭则脉道不充而欲脱不续；中虚则推动无力而止歇有定；胎元不固则血聚养胎而脉见虚代。四者皆以虚为本，或气虚、或血亏", "c": "主气衰"}, {"id": "c:虚+伏", "n": "虚伏脉", "o": "虚伏脉总起来主正气虚弱而邪气未张或邪气锢结之候，其病机关键在于正邪进退。虚为正气不足，伏为邪气内匿或脉气不显。若虚而宁伏匿，则胃气尚能自守，邪不鸱张，主生；若虚伏而兼坚强，或热盛脉反沉小、汗后脉反浮大，则正不胜邪，主死。各类之间以正虚为基础，或邪退而安，或邪盛", "c": "主正虚邪退"}, {"id": "c:虚+促", "n": "虚促脉", "o": "虚促脉总属虚损危候，主阴阳并亏、虚阳浮动、脏气衰败，亦可兼夹痰热、伏热等实邪。其基本病机为正气大伤，阴不敛阳，虚阳上浮，或脏气衰败，真元欲脱。虚为阴阳气血俱不足，促为热盛阴伤、脉道不利，或为脏气衰败、真元欲脱之象。各类之间相互关联：病久阴阳并亏是根本，虚阳浮动", "c": "主热盛阴伤"}, {"id": "c:虚+动", "n": "虚动脉", "o": "虚动脉总起来主虚中夹动之候，以虚为本，以动为标。其虚或为营络亏损、或为阴精亏耗、或为奇经虚损；其动或为虚风内动、或为虚阳上浮、或为冲脉动血。四类病机相互关联：营络亏损日久则阴伤阳浮，阴伤阳浮又可化风内动；奇经虚损则冲任失司而血下。总属本虚标实、阴阳失守之象，治", "c": "主虚风内动"}, {"id": "c:大+虚+散", "n": "虚大散脉", "o": "虚大散脉总属虚候，主气阴两伤、元气欲脱。其脉虚大无根、欲散不收，为阴液亏极、脉道失充，元气将脱、虚阳浮越之象。原文于加减复脉汤中加人参，益气固脱、生津复脉，正针对气阴两伤、虚阳欲散之病机。两类病机相互关联：阴液亏极可致元气无所依附而欲脱，元气耗散又加重阴液不守", "c": "主气阴两伤"}, {"id": "c:数+大+虚", "n": "虚大数脉", "o": "虚大数脉总属虚中夹火之象：虚为正气不足或阴亏，大为气浮火亢，数为热。其病机以虚火为核心，或为肾水不足、相火上炎，或为思虑过度、厥阴火动，或为虚阳外浮、下元不摄，或为气阴两伤、脾肺虚热，或为痰火乘虚扰心，甚则阴亏火旺而成劳瘵、肺痿。诸类之间，虚为本、火为标，大数", "c": "主虚火"}, {"id": "c:大+虚+涩", "n": "虚大涩脉", "o": "虚大涩脉在暑气呕吐中总主暑邪为病，其病机涵盖伤气、挟湿、化火三端。虚大而涩为气津两伤之本脉；沉细为暑湿内阻，气机不畅；沉数为暑热内郁；躁疾为暑火亢盛；脉伏为暑湿闭遏、阳气不伸。诸脉皆由暑邪所致，或伤气耗津，或挟湿阻遏，或化火亢盛，反映了暑邪致病多兼夹、易伤气津", "c": "主气津两伤"}, {"id": "c:大+虚+濡", "n": "虚大濡脉", "o": "虚大濡脉总属虚象，核心病机为气血亏虚、气浮不敛。虚大主气浮于外、血虚脉道不充，濡主气虚不敛、卫外不固。原文见便血日久、胃弱不食、面时火起、合目身麻不寐，断为气随血下而虚，卫气行阴不能周阳，正合东垣补气升阳和中汤证。其下属洪大虚濡脉兼热盛伤津、湿热成痿；大虚浮濡", "c": "主气虚"}, {"id": "c:大+虚", "n": "虚大脉", "o": "虚大脉总以虚为本，大而无力为关键特征，所主病机涵盖气血阴阳亏虚、虚阳外浮、虚中夹实、虚极欲脱及虚热等类。其核心为正气不足，脉道不充，虚阳浮越而显大。各类之间常相互兼夹：气血亏虚可致阴亏阳浮，虚中夹实多见于正虚邪恋，虚极欲脱为虚之甚，虚热则由虚而生。临证须结合兼", "c": "主气血亏虚"}, {"id": "c:大+虚+芤", "n": "虚大芤脉", "o": "虚大芤脉总属气阴两伤、血脉不充之象。其脉形大而无力，中候空虚，既因正气不足而脉道松弛，又因阴血亏虚而脉道失充，故虚、大、芤三象并见。所主病机以气阴两伤为核心，常继发于热盛伤津之后，或见于素体亏虚、血脉不充之人。三类病机相互关联：热盛伤津为成因，气阴两伤为病机关", "c": "主气阴两伤"}, {"id": "c:大+虚+迟", "n": "虚大迟脉", "o": "虚大迟脉总属阳气虚衰、浮散欲脱之候。虚大主阳气浮散于外，迟主阳衰于内，二者相合，揭示阳气既虚且浮，根本动摇。其核心病机为误汗亡阳，阳气外越，进而导致膀胱气化不行，出现小便难出、少腹胀满等症。三类病机相互关联：亡阳为病之本，阳衰为亡阳之因，气化不行为阳衰之果。脉", "c": "主亡阳"}, {"id": "c:虚+小+实", "n": "虚实小脉", "o": "虚实小脉总以辨心与小肠之虚实寒热为纲。虚脉主心气不足、神动惊跳，实脉主心火有余、洪满鼓指；又据寒热分属，热应脏（心）、寒应腑（小肠）。三类病机相互关联：虚与实是脉象总纲，寒热是病性分属，脏腑是病位所在。虚证多寒或气虚，实证多热或火盛，而惊跳与洪满分别对应虚实施", "c": "主心虚神动"}, {"id": "c:虚+弱+实", "n": "虚实弱脉", "o": "虚实弱脉在此段专用于辨寒热真假。脉之虚弱与强实，是判断真寒假热与真热假寒的关键依据：脉虚弱无力者，多为阴寒内盛、虚阳外浮之真寒假热；脉强实有力者，多为阳热内郁、格阴于外之真热假寒。二者虽外症相似，然脉之虚实迥异，故临证当以脉之虚实强弱为主，不被假象所惑。三类病", "c": "辨真寒假热"}, {"id": "c:弦+虚+紧+实", "n": "虚实紧弦脉", "o": "虚实紧弦脉在崩中漏下中，总主虚寒、热、紧弦三类病机。虚寒者，脉虚多寒，阳气不足，阴寒内盛；热者，脉数无疮，热迫血行；紧弦者，寒凝气滞，脉道拘急。三者或单独出现，或相兼为病，反映崩漏虚实寒热错杂之候。原文以“脉阴阳虚实紧弦”概括，提示临证需循因索治，辨其寒热虚实", "c": "主虚寒"}, {"id": "c:虚+实", "n": "虚实脉", "o": "虚实脉并非单一脉形，而是以脉之有力无力、按之坚软为纲，统括诸脉所反映的正邪盛衰关系。总起来看，其病机核心在于“邪气盛则实，精气夺则虚”。脉虚者，或为元气自虚、气血衰少，或为阴亏火旺、血虚气弱；脉实者，或为邪热内盛、痰火壅滞，或为宿食瘀血内结。然临床更多见虚实夹", "c": "主虚"}, {"id": "c:数+虚+小+散", "n": "虚小散数脉", "o": "虚小散数脉总属正气已虚、邪热内扰之候，以气阴两伤为根本，虚火内动为关键。其脉虚小示气血不足，散为气不收敛，数为阴亏内热，三者相合，反映正虚与邪热并存之病机。具体而言，虚小散数脉可主气阴两虚，因劳倦入房耗伤气阴；虚火内动，阴虚阳亢而梦遗、自汗；风热外扬，因感风而", "c": "主气阴两虚"}, {"id": "c:数+虚+小", "n": "虚小数脉", "o": "虚小数脉总属虚损之象，以正气亏虚为本，虚热内扰为标。虚小主气血阴阳不足，数主虚热或余火。其病机或偏脾虚湿盛，或偏阴虚内热，或正虚邪恋，或气血亏而余火未尽，皆不离“虚”与“热”二字。虚损可致虚热，虚热又耗气阴，正虚易恋邪，湿盛可壅遏气机。诸类相互关联，总以本虚标", "c": "主虚损"}, {"id": "c:虚+小", "n": "虚小脉", "o": "虚小脉总属正虚不足之象，虚为正气衰弱，小为脉道不充。其主病机以虚为核心，涵盖气血两虚、脾胃虚弱、肝肾亏虚、肾阳虚衰等，皆因脏腑功能衰退、精气血津液化生不足或耗伤过度，致脉道不充。若虚小见于邪盛之际，则为邪盛正虚之重候；若见于危重病中，则示正气衰败之危候。各类之", "c": "主气血两虚"}, {"id": "c:弦+虚+和", "n": "虚弦和脉", "o": "虚弦和脉总起来主肝脾同病、虚实夹杂之候。其脉象以虚、弦、涩、大并见为特征：虚为元气不足，弦为肝胆阳郁，涩主血少气滞，大则中州壅塞。三类别中，脾虚湿滞为病之标，因过服寒凉、脾胃窒塞、升降失司所致；肝郁气滞为病之本，肝气偏旺、木不疏土，与脾虚互为因果；虚实夹杂则概", "c": "主脾虚湿滞"}, {"id": "c:数+弦+虚+小", "n": "虚弦小数脉", "o": "虚弦小数脉总属虚中挟实、本虚标实之象。虚为气阴不足或阴亏本质，弦为肝风内动或虚阳浮动，小数为虚热内扰。四类病机相互关联：气阴两虚可致虚风内动，阴亏于下则虚阳上浮，虚热内扰又常与阴虚风动并存。总以阴血亏虚为本，风、热、阳浮为标，多见于素体虚弱、热病伤阴或阴虚劳怯", "c": "主气阴两虚"}, {"id": "c:弦+虚+弱", "n": "虚弦弱脉", "o": "虚弦弱脉总属正虚邪动之候，以阴血亏虚为本，虚风内动为标，津亏肠燥为变。虚、弱二象主气阴与血分不足，弦象主肝木失养、阳不能潜而化风。年高阴亏，八脉空虚，阳失所潜，游行于上，则见汗出头晕；风耗津液，肠道失润，则便秘弩挣。三者相因：虚为风之本，风为虚之动，津亏为风虚", "c": "主虚风"}, {"id": "c:弦+虚+急", "n": "虚弦急脉", "o": "虚弦急脉总属虚实夹杂之候，以虚为本，以风火为标。虚为阴虚，阴精亏虚，脉道不充；弦劲急为肝风内动，风火相煽。三者相互关联：阴虚则火炽，火炽则风动，风动则脉弦急。原文见孕妇子痫，头痛呕吐、神迷肢掣、目吊口噤，脉虚弦劲急，正是阴虚火炽、经脉空疏、精不养神、柔不养筋之", "c": "主阴虚"}, {"id": "c:数+弦+虚", "n": "虚弦数脉", "o": "虚弦数脉总属正虚邪恋、虚实夹杂之候。虚为正气不足，或气弱，或阴亏，或营血耗损；弦为肝郁气滞，或木失涵养，或痰瘀阻络；数为有热，多为虚热内生，或郁热、湿热、燥热内扰。诸类之间相互关联：正虚为本，虚则肝失濡养而弦，阴虚则生内热而数；肝郁化火则耗阴，痰湿瘀血久郁则化", "c": "主正虚"}, {"id": "c:数+弦+沉+虚", "n": "虚弦沉数脉", "o": "虚弦沉数脉总起来主虚实夹杂之证，以虚、惊、热、痰滞四类病机为核心。虚为气馁，惊为神扰，热为郁热内停，痰滞为饮停中脘，四者相互交织：因大劳致虚，因惊致弦，因饮停化热而沉数。原文治以补虚清热、导去痰滞，正合此脉机。虚与惊常并见（虚弦），热与痰滞多相因（沉数），故临", "c": "主虚"}, {"id": "c:弦+浮+虚", "n": "虚弦浮脉", "o": "虚弦浮脉总属本虚标实之候，以气血虚为根本，风邪外袭为标，兼肝旺气逆。虚脉示气血不足，浮脉示风邪在表，弦脉示肝旺气逆。三者相合，多见于年高气血已衰、虚人外感风邪之证，如腰痛、形瘦骨立、食少神疲等。其病机核心是正虚不能托邪，血虚无以流通脉络，故虚为本、风为标、肝旺", "c": "主气血虚"}, {"id": "c:弦+虚+涩", "n": "虚弦涩脉", "o": "虚弦涩脉总属本虚标实、虚实夹杂之候。虚为气血阴阳亏虚，弦主气机郁滞或肝木失和，涩主精血亏少或血行滞涩。三类病机相互关联：虚为根本，可致气滞、精亏；气滞又可加重精血不布；肝郁乘脾则肝脾不和；肾虚水泛则痰气上逆。临床多见于久病耗伤、情志所伤或漏下不止者，病位涉肝、", "c": "主虚"}, {"id": "c:弦+滑+虚", "n": "虚弦滑脉", "o": "虚弦滑脉总主正虚夹风痰之候，以虚为本，以弦滑为标。虚脉主气阴亏虚、气血不足或脾土虚弱，为病之根本；弦脉主肝风内动、肝阳偏亢或肝木乘脾，为风动之象；滑脉主痰湿壅盛、痰浊内蕴或郁痰内扰，为痰盛之征。三者相合，常见于高年气阴两亏、产后真阴未复、素体丰肥气虚等患者，因", "c": "主肝旺"}, {"id": "c:弦+滑+虚+濡", "n": "虚弦濡滑脉", "o": "虚弦濡滑脉总主正虚邪恋、虚实夹杂之候。左脉虚弦，主少阴阴阳两亏、气血气阴不足，虚而兼弦，示阴不制阳、虚火易升；右脉濡滑，主脾胃不健、运化失职，湿浊痰湿稽留。四段原文均见中发背腐肉渐脱而脉象未和，胃纳不旺，说明正气尚虚、湿毒未净。其病机以虚为本，以湿浊、虚火为标", "c": "主湿浊"}, {"id": "c:弦+虚+濡", "n": "虚弦濡脉", "o": "虚弦濡脉总主正虚邪恋、虚实夹杂之候，具体可归为脾虚湿痰、肝肾阴亏、正虚邪恋三类。右脉浮小软滑主脾虚湿痰内蕴，左脉虚弦尺濡主肝肾阴亏、精关不固，而虚弦濡并见又示正虚湿恋、病关足三阴。三者相互关联：脾虚生湿为邪恋之源，肝肾阴亏为正虚之本，正虚与湿浊痰邪胶结则成虚实", "c": "主脾虚湿痰"}, {"id": "c:弦+虚+软+空", "n": "虚弦空软脉", "o": "虚弦空软脉总属正虚邪恋、本虚标实之候。其脉象由虚、弦、空、软四象复合而成：虚主正气亏虚，弦主肝木偏旺，空软主阴血枯竭与胃气衰败。四者相互交织，形成久病羸弱、肝木乘脾、土败木贼之病机格局。虚与空软反映正气阴血之耗伤，弦反映肝旺之邪实，然此邪实乃因虚致实，本质仍以", "c": "主正虚"}, {"id": "c:弦+细+虚+弱", "n": "虚弦细弱脉", "o": "虚弦细弱脉总属阴血亏虚、阳浮风动之候。虚、细、弱三象主阴血亏乏，弦象主阳不能潜、肝风内动。三者相合，反映素体阴亏、新产血去之后，八脉空虚，阳失所潜而游行于上。其见证错杂：咳嗽寒热、齿衄、善怒不眠、四肢牵掣、汗出等，皆阴亏阳浮、风阳上扰之象，非外感表邪，亦非瘀血", "c": "主阴血亏虚"}, {"id": "c:弦+细+虚+急", "n": "虚弦细急脉", "o": "虚弦细急脉总属虚实夹杂之候，以虚为本，以郁为标。虚细主心脾内亏，气血不足；弦急主情志抑郁，气机郁结。二者相合，则见肝木郁而乘脾，木郁克土，脾失健运，故成心脾郁结、虚实互见之病机。此脉非膈证之脉，实为情志内伤、心脾郁结之典型表现。三类病机相互关联：虚为郁之基础，", "c": "主虚"}, {"id": "c:弦+细+滑+虚", "n": "虚弦细滑脉", "o": "虚弦细滑脉总起来主本虚标实之证，以阴液亏虚为本，痰热内壅为标。虚细反映少阴阴血不足，弦滑提示痰饮热邪内停，二者并见，形成阴虚挟痰、虚实夹杂之病机。各段原文中，或见喘嗽不能卧、进参汤反助痰，或见脘痛晕厥、胸闷气逆，皆因阴亏于下、痰热壅于上所致。三类病机中，主阴虚", "c": "主阴虚"}, {"id": "c:弦+大+虚+缓", "n": "虚弦缓大脉", "o": "虚弦缓大脉总属虚证，以气血不足、中气虚弱为本，兼见肝木乘脾、虚阳外浮及虚风内动。虚为气血亏虚，弦为肝木偏旺，缓大为中气不足、虚阳或虚风浮动。诸段所示，或久嗽形瘦、气短自汗，或凛寒乍热、心悸耳鸣，或阴虚劳怯、咳嗽失血，皆因虚致变。其病机以虚为核心，肝木乘脾、虚阳", "c": "主肝木乘脾"}, {"id": "c:弦+虚", "n": "虚弦脉", "o": "虚弦脉总以虚为本，以弦为标，主正虚而兼肝旺、木乘、邪恋之候。虚为气血阴阳亏虚，弦为肝郁气滞、肝风内动或痰饮瘀阻。其病机类别虽多，然相互关联：虚则肝失濡养而弦，弦则木旺乘土，土虚又生湿痰，虚火内扰则风动。故临床可见纯虚、虚中夹实、虚极欲脱等不同层次，总属本虚标实", "c": "主虚"}, {"id": "c:数+弦+虚+软", "n": "虚弦软数脉", "o": "虚弦软数脉总起来主阴血亏虚、阳升无液、冲气上逆及虚火内扰之证。其脉象由虚、弦、软、数四象复合而成：虚为阴血不足，软为气弱，弦为肝阳上亢，数为虚热。四者相合，反映真阴亏虚、阳无所附、冲气上逆、虚火内扰的病机本质。各段原文均见舌光赤无苔、头疼口燥、寝汗减餐、奄奄而", "c": "主阳升无液"}, {"id": "c:弦+滑+虚+软", "n": "虚弦软滑脉", "o": "虚弦软滑脉总属虚实夹杂之候，以正虚为本、痰阻气壅为标。虚软主体气素亏、脾肾不足，弦滑主痰饮内停、肝郁气滞或风阳内动。五段所主，或脾虚痰饮，或肾虚痰热，或痰凝气滞，或阴亏风阳挟痰，皆不离正虚与痰阻两端。其关系为：虚软定其本虚之脏（脾、肾、阴血），弦滑定其标实之邪", "c": "主脾虚"}, {"id": "c:虚+弱+急", "n": "虚弱急脉", "o": "虚弱急脉在此段中实为多种积聚脉象的统称，总起来主积邪内结。其脉象包括𫘝紧、浮牢、小沉实、细䎡附骨等，分别对应寒实、里实、积深着骨等不同病机。诸脉皆因积块内结、气血受阻而现，故以“主积”为总纲。各类之间相互关联：寒实与里实侧重邪实性质，积深着骨侧重病位深浅，共同", "c": "主积"}, {"id": "c:细+虚+微+弱", "n": "虚弱细微脉", "o": "虚弱细微脉总属虚损，主气血阴阳俱不足。其脉虚为气不足，弱为血不充，细微为阴阳俱损，故内伤虚损之渐多见。因卫外之阳不固、营阴不能内守，故喜盗汗；若兼沉小迟，则阳气衰微、气不归元，为脱气，见喘喝、逆寒、腹满溏泄等症。原文又辨析虚与劳之别：虚者气馁精违，脉必小；劳者", "c": "主气血阴阳俱虚"}, {"id": "c:数+细+虚+弱", "n": "虚弱细数脉", "o": "虚弱细数脉总属虚损，以正气亏虚为根本。虚细弱主气血阴阳不足，数脉在此非实热，多为阴虚不能制火之虚火，或营分余邪未清之正虚邪恋。其病位多在肝脾肾，尤以肾之真阴真阳亏虚为核心：左尺虚弱细数主肾阴不足、虚火妄动；右尺迟软或沉细数欲绝主命门火衰；两尺微弱则阴阳俱虚。久", "c": "主阴虚火旺"}, {"id": "c:虚+弱", "n": "虚弱脉", "o": "虚弱脉总主正气不足，以气血阴阳亏虚为根本。虚为脉道不充，弱为鼓动无力，故凡气血两虚、阳虚火衰、阴虚火旺皆可见之。其兼见他脉则病机有偏：兼数主虚火，兼弦主木克土，兼滑主正虚邪恋，兼散乱则主虚脱危候。各类之间以'正虚'为纲，或虚而兼寒（阳虚），或虚而兼热（阴虚火旺", "c": "主气血两虚"}, {"id": "c:数+虚+微", "n": "虚微数脉", "o": "虚微数脉总属正虚为主、兼夹邪热之候。虚与微并见，反映正气亏虚，或为营阴不足，或为脾肾两虚，或为久病正伤；数则示热，但因虚微相兼，热势多不亢盛，属虚热、伏热或余热未清。其具体所主，一为虚损，气血亏耗而脉体无力；二为妊娠，虚损之中犹见滑象，胎元尚存；三为虚热内扰，", "c": "主虚损"}, {"id": "c:虚+微+涩+短", "n": "虚微短涩脉", "o": "虚微短涩脉总起来主气血亏虚、血少瘀滞及正虚瘀结之候。虚微为气血不足，短涩为血少瘀滞，二者相合，反映正虚与瘀结并存。原文妇人因家贫多劳、性急，耗伤气血，又致瘀血内结，出现经断、腹块、肿胀、食减、发热等症，脉虚微短涩，左尤甚，左主血，故血瘀偏著。三类病机相互关联：", "c": "主气血亏虚"}, {"id": "c:虚+微", "n": "虚微脉", "o": "虚微脉总属正虚之象，以阳气虚衰、气血大虚为核心，兼及气阴两虚、津液亡失、肾虚不固等虚损病机。其脉虚为不足、微为阳衰，鼓动无力，故主诸虚。然虚微之脉亦可见于正虚邪恋、虚寒夹饮等虚实夹杂之证，如疟久脉虚微中见弦、新产虚微兼沉弦饮邪。各类之间以虚为本，或纯虚，或虚中", "c": "主阳气虚衰"}, {"id": "c:虚+急", "n": "虚急脉", "o": "虚急脉总起来主虚中夹实、正虚邪恋之病机。虚为气阴不足或元亏未复，急为邪热内迫、寒凝收引或邪正交争。各类之间相互关联：暑伤气阴与正虚邪恋均属外感诱发、气阴耗伤；肾虚寒疝为下焦虚寒、寒凝收引；阴虚风动为阴虚火炽、肝风内动；积邪内结为积块内结、气血受阻。诸类皆以虚为", "c": "主暑伤气阴"}, {"id": "c:数+虚+散", "n": "虚散数脉", "o": "虚散数脉总属正虚失守、虚热内扰之候。其核心病机为气血亏虚、正气耗散，虚散不敛是脉象关键，数为虚而失守、脉无根蒂之暂象，非实热可比。四类病机相互关联：气血虚为根本，虚热由虚而生，正虚邪恋示虚实夹杂，虚阳躁动为虚极之变。原文两段均强调“恐乘舆远来，脉未定耳”，来早", "c": "主气血虚"}, {"id": "c:数+虚+促", "n": "虚数促脉", "o": "虚数促脉总属虚损危候，主阴阳并亏、虚阳浮动、脏气衰败。虚为阴阳气血俱不足，数为阴不敛阳而虚阳上浮，促为脏气衰败、真元欲脱之象。三者相互关联：病久阴阳并亏是根本，虚阳浮动为阴虚阳越之标，脏气衰败则因虚致危，层层递进。原文脉证俱危，强调肾不纳、肺不降、浮阳上越、自", "c": "主阴阳并亏"}, {"id": "c:数+虚+疾", "n": "虚数疾脉", "o": "虚数疾脉总属阴亏火旺、虚实夹杂之象。虚为阴液不足，脉道不充；数疾为虚火亢盛，鼓动血脉。其核心病机为肺肾阴虚，阴不制阳，虚火上炎。由此可致失血复发、潮热盗汗、呛逆嗌干等症，久则入损。四类病机相互关联：阴虚为本，虚火为标，火迫血溢则失血，阴损及阳则成损候。脉象虚数", "c": "主阴虚"}, {"id": "c:数+虚+空", "n": "虚数空脉", "o": "虚数空脉总起来主正虚邪实、寒热错杂之病机，以正虚为本，热邪为标。虚为三阴内亏、精血不足，数为阴虚生内热或邪热未清，空则脉道不充、阴精耗损之甚。具体可分为三类：一为阴虚内热，见于三阴俱亏、虚热上浮之证；二为气阴两伤，见于下后邪热未清而气阴已伤；三为正虚邪实，见于", "c": "主阴虚内热"}, {"id": "c:数+虚", "n": "虚数脉", "o": "虚数脉总属正虚而热浮之候，以虚为本、数为标。虚者，或气弱，或阴亏，或营血耗损，或脾肾双亏；数者，或虚热内生，或余热未清，或虚阳外浮，或郁热、湿热、燥热内扰。其病机类别虽多，然总不离“正虚”与“热象”两端：阴血亏虚则虚火内生，气阴两伤则余热未净，久病虚劳则阴损及", "c": "主虚热"}, {"id": "c:虚+洪", "n": "虚洪脉", "o": "虚洪脉总起来主正气已虚而邪热内扰之候，以虚为本，以热为标。其脉洪为阳热之象，虚为不足，合而观之，非实火亢盛，乃虚阳外浮、真阴亏虚，或郁火内灼、暑热弥漫。所主病机可归纳为虚火、虚损、热盛阴虚、暑热伤津、疟、痰六类：虚损为根本，因劳倦、入房、饥寒等致正气先亏；虚火", "c": "主虚火"}, {"id": "c:数+大+浮+虚", "n": "虚浮大数脉", "o": "虚浮大数脉总起来主正虚邪盛、津伤热炽之危候。其虚为正气不足，浮大数为邪热外张，数主热，浮主表，大主热盛，合而观之，乃正虚不能御邪，邪热亢盛，劫烁津液，常见于春温两感、肾水素亏之体。各类病机相互关联：正虚是基础，邪热是病势，津伤是结果，两感是病位与病性之综合。虚", "c": "主正虚"}, {"id": "c:浮+虚+紧", "n": "虚浮紧脉", "o": "虚浮紧脉在瘟疫初起中，总主邪盛正实、寒束热盛之病机。紧主寒邪外束，数主热邪内郁，洪滑主邪气盛而正气实，故脉象紧数洪滑并见，反映瘟疫初起表里俱实、寒热错杂之候。原文以脉之洪滑实与弱数分虚实，决定清下补泻，可见此脉主要提示邪实为主，治当祛邪。三类病机相互关联：寒束", "c": "主寒束"}, {"id": "c:虚+涩+小", "n": "虚涩小脉", "o": "虚涩小脉总主气血两虚，以气弱、血少、血燥为核心病机。虚为气弱，涩为血少，小为气血不足，三脉合见，提示气血俱亏之候。气弱则推动无力，血少则肠道失润，故见大便甚结、欲解不能；气血不足则肠胃不滋，疼痛虽减而食饮渐增，示本虚未复。原文强调“气弱血燥，肠胃不滋”，并告诫", "c": "主气弱"}, {"id": "c:虚+涩+弱", "n": "虚涩弱脉", "o": "虚涩弱脉总起来主阳气大衰、气血不足之病机。虚脉主阳气虚衰，弱脉主阳气不足，涩脉主血少气滞，三者相合，反映阳气大衰、气血俱虚、气滞血涩的复杂状态。具体而言，阳气大衰则不能温煦，故见鼻冷肢冷、肌腠麻木、面乏淖泽；脾肾阳虚则火不暖土，故见谷食不纳、大便有不化之形；血", "c": "主阳虚"}, {"id": "c:虚+涩+小+濡", "n": "虚涩濡小脉", "o": "虚涩濡小脉总属气血不足、脾虚湿困之候。虚小主气血两虚，涩主血少行滞，濡主脾虚湿困，四脉相合，反映气血亏虚为本、湿滞为标。原文以经行前后多少不定、缠绵不已、腰胯酸疼为症，服养阴止经剂即停，示阴血亏虚；法宜气血并调，切中病机。三类病机相互关联：气血两虚则脉道不充而", "c": "主气血两虚"}, {"id": "c:虚+涩", "n": "虚涩脉", "o": "虚涩脉总以虚、涩两象合论，虚主正气不足、气血亏虚，涩主血少气滞、脉络不畅。其总病机为气血两虚而兼郁滞，正虚为本，滞涩为标。所主范围较广：或纯见气血两虚、中下交损、八脉全亏；或虚中夹滞，见血虚络痹、营虚气痹、郁热气滞；或虚极而变，见阴血暴亡、虚阳外越；或虚而兼邪", "c": "主气血两虚"}, {"id": "c:数+滑+虚", "n": "虚滑数脉", "o": "虚滑数脉总起来主正虚邪恋、虚中夹实之证。其‘虚’为气阴两伤、肝肾式微或脾虚失运；‘滑数’为湿热痰浊或痰火内蕴。二者相合，形成正虚与邪实并存之局：或湿热伏邪留恋阳明而气阴已伤（），或久病羸弱、阴不交阳而痰火内迷（），或郁怒伤肝、木旺土衰而痰热内蕴（滑数虚软脉总述", "c": "主气阴两伤"}, {"id": "c:滑+虚", "n": "虚滑脉", "o": "虚滑脉总以‘虚’为本、‘滑’为标，主正虚夹痰湿之候。虚脉反映气血阴阳亏虚，滑脉主痰湿内蕴，二者相合，形成虚实夹杂之局。具体而言，虚可责之脾肺肾肝等脏气亏虚，滑可因痰湿、湿浊、精浊等内停。各类病机相互关联：正虚则津液不布，聚湿生痰；痰湿内阻，又耗伤气阴，加重正虚", "c": "主正虚"}, {"id": "c:数+虚+小+濡", "n": "虚濡小数脉", "o": "虚濡小数脉总起来主正虚不足、阴亏内热之病机。虚濡为不足之象，主肝肾亏虚及心荣不足；小数主阴亏内热。三者相互关联：肝肾阴亏则疏泄闭藏失职，虚热内扰则见晡热溲赤；心荣不足则血脉不充，加重虚濡之象。原文以梦泄、腰疼、晡热、溲赤为例，说明该脉所主病机以肝肾亏虚为本，阴", "c": "主肝肾亏虚"}, {"id": "c:弦+虚+濡+实", "n": "虚濡弦实脉", "o": "虚濡弦实脉在此段总主阳气受伤、血内溢而偏于阳分不足之证。其脉虚濡而不弦实，虚濡示阳气亏虚，不弦实排除实热迫血；血色淡红、面黄兼白、浮肿眩悸、肢酸力乏皆为阳伤失摄之候。所归纳三类病机——阳伤、血溢、虚浮——实为一体：阳伤为本，血溢与虚浮为标。阳伤则气不摄血而血内", "c": "主阳伤"}, {"id": "c:虚+濡", "n": "虚濡脉", "o": "虚濡脉总以“虚”为正气不足、“濡”为湿滞柔缓为纲，所主病机可归为气虚湿滞、脾胃元气大弱、精亏不固、气血亏虚、湿热伤脾、暑湿郁肺及正虚邪恋数类。其核心在正虚与湿滞并存：虚涉气、血、精、阴，濡涉湿、痰、暑、热。诸类之间，脾胃元气大弱为常见根基，气虚湿滞为总象；精亏", "c": "主气虚湿滞"}, {"id": "c:虚+濡+弱+迟", "n": "虚濡迟弱脉", "o": "虚濡迟弱脉总起来主中阳不足、胃气虚寒，核心病机为阳气衰微、胃中无火。虚濡为气弱，迟弱为阳衰，四脉合见，反映中焦阳气虚馁，腐熟无力，饮食停滞胃口，胃气因凉而不降，逆而吐衄。各类病机之间具有因果关系：中阳不足为根本，导致胃气虚寒；胃气虚寒则腐熟失职，饮食停滞；饮食", "c": "主中阳不足"}, {"id": "c:虚+濡+迟", "n": "虚濡迟脉", "o": "虚濡迟脉总起来主中阳不足、胃气虚寒，核心病机为阳气衰微、胃中无火。虚濡为气弱，迟为阳衰，四脉合见，反映中焦阳气虚馁，腐熟无力，饮食停滞胃口，胃气因凉而不降，逆而吐衄。各类病机之间具有因果关系：中阳不足为根本，导致胃气虚寒；胃气虚寒则腐熟无力，饮食停滞；胃气因寒", "c": "主中阳不足"}, {"id": "c:虚+涩+紧", "n": "虚紧涩脉", "o": "虚紧涩脉总起来主本虚标实、气滞血涩之证。虚脉揭示脾胃气伤、正气不足之本；紧脉提示气机壅滞、升降失常之标；涩脉反映血行不畅、脉道不利之兼症。三者相合，常见于忧思过度、情志所伤致脾胃气结、气血失和之候，症见心腹胀满、喘促烦闷、肠鸣漉漉、二便不利等。其病机核心为虚中", "c": "主虚"}, {"id": "c:虚+紧", "n": "虚紧脉", "o": "虚紧脉总起来主正虚寒凝、本虚标实之证。虚脉揭示正气不足、禀弱或中气不振、元阳受损之本；紧脉提示寒邪内伏或气机结聚之标。两者相合，常见于素体虚弱、久坐伤脾或忧思气结之人，症见半身麻木不遂、胀满上冲、饮食不下等。其病机核心为虚中夹实：正虚则寒邪沉匿，气凝则胀满上冲", "c": "主虚寒"}, {"id": "c:细+虚+小", "n": "虚细小脉", "o": "虚细小脉总以虚损为纲，其脉虚为不足、细为血少、小为脉道不充，故所主病机不离气血阴阳之亏。细分之：一主血虚，亡血失血见之脉证相应则生；二主气虚，脾虚气弱、胃气衰败多见；三主虚损，或心气不足，或脾虚气弱，总由正气不能充脉；四主郁火，虚细之中兼见弦数，为阴血不足、肝", "c": "主虚损"}, {"id": "c:数+细+虚+碎", "n": "虚细数碎脉", "o": "虚细数碎脉总属营阴亏虚、虚涩生热、枯涩血瘀之候。其脉虚细为营阴不充，数为虚涩生热，碎则示枯涩之机。三者相互关联：营阴亏虚为本，因虚而涩，因涩而热，因热而更伤阴血，形成虚、涩、热、瘀交织之局。原文指出'癸水停阻'而'内热不腹痛'，'病虽初起，而根蒂颇深'，说明此", "c": "主营阴亏虚"}, {"id": "c:数+细+虚", "n": "虚细数脉", "o": "虚细数脉总以虚为本、以数为标，主阴血亏虚、虚火内扰之证。虚细为脉道不充，阴血不足；数为阴不制阳，虚热内生。其病机可归为五类：阴血亏虚是基础，虚火内扰为标象，气阴两虚为发展，虚劳损怯为久延之果，正虚邪恋为兼夹之变。诸类之间，阴亏与虚火互为因果，气阴两虚由阴损及气", "c": "主阴血亏虚"}, {"id": "c:细+沉+虚+小", "n": "虚细沉小脉", "o": "虚细沉小脉总属气血虚衰、脉道不充之象，尤以亡血失血为核心病机。其脉虚细主血虚，沉小主气弱，故金疮出血太多见此脉为脉证相应，预后良好。然同一脉象若见于瘀血内阻之证，则提示正气已衰，无力抗邪，脉与病机不符，预后不良。原文汇集《内经》《金匮》《脉经》论金疮跌仆之脉，", "c": "主亡血"}, {"id": "c:弦+细+滑+沉+虚", "n": "虚细沉弦滑脉", "o": "虚细沉弦滑脉总起来主阴液不足而阳明燥热内盛之证。其脉虚细为少阴阴血亏虚，沉分弦滑为阳明燥热有余，二者并见，形成“土燥水涸”之病机。原文以“阳明有余，少阴不足”概括，症见肌肤消瘦、两腓发热、面色青黄隐黑气，虽似虚寒而实为无形之热内伤。三类病机中，阴虚与阳明热为分", "c": "主阴虚"}, {"id": "c:细+虚+涩", "n": "虚细涩脉", "o": "虚细涩脉总主虚损，以阴血亏虚、气血两虚为根本，兼见阳气郁结、胃气衰败及虚阳上浮等变证。虚为气弱，细为血少，涩为血行不畅，三象复合，故总归虚损。阴血枯槁则脉道不充，气血不足则鼓动无力；血少气滞，阳气郁结不行，故涩象兼见气滞；久病药误，胃气衰败，脉见细小虚涩，有脱", "c": "主阴血亏虚"}, {"id": "c:细+滑+虚", "n": "虚细滑脉", "o": "虚细滑脉总起来主本虚标实之证，以气血亏虚为本，痰湿内阻为标。虚细反映正气不足、气血两亏，滑脉提示痰湿内停。二者并见，形成虚中挟实、虚实夹杂之病机。各段原文中，或见胸闷脘胀、气紧，或见心窝下起梗如指粗，或见便滑、癸来涩滞，皆因正虚于内，痰湿凝滞，气机不畅所致。虚", "c": "主虚"}, {"id": "c:细+虚", "n": "虚细脉", "o": "虚细脉总以虚为本，主气血阴阳亏虚，脉道不充。其虚可涉气、血、阴、阳，病位可在心、脾、肾、肝。虚细无力多主气血两虚或阳气衰微；细而兼数多主阴亏虚火；虚细而弦多主虚中夹实、肝郁风动；虚细见于久病、疮疡后期多主正虚邪恋。各类之间相互关联：气血两虚为基本病机，阴血亏虚", "c": "主气血两虚"}, {"id": "c:虚+缓", "n": "虚缓脉", "o": "虚缓脉总属正气不足之象，以虚为根本，缓为兼征。虚主阳气虚衰、气血亏虚、中气大虚；缓主湿滞、脾运不健、病势弛缓。合而观之，其病机可归为三类核心：一为气虚阳弱，涉及胃阳虚、脾肾两虚、中气下陷，见形寒浮肿、脱肛、气逆等；二为脾虚湿盛、痰气凝滞，因脾运失司而湿浊内生，", "c": "主气虚"}, {"id": "e:虚", "n": "虚脉", "o": "虚脉总以正气亏虚为纲，涵盖气血阴阳诸般不足。其脉象按之无力、脉道不充，故凡虚劳、久病、产后、失血、暑热伤气等见虚脉，皆示正虚。具体而言，虚脉所主病机可分六类：一主气血阴阳亏虚，为虚脉之基本；二主气虚阳衰，鼓动无力；三主虚热或暑热伤气，虚而兼热；四主虚中夹邪，正", "c": "主气血阴阳亏虚"}, {"id": "c:弦+虚+芤", "n": "虚芤弦脉", "o": "虚芤弦脉总起来主正气阴血亏伤、阳明生气受戕、络脉不和而虚风内动之候。虚芤主气阴两伤，弦主木郁络阻、虚风内动。原文便血虽止，但饮啖式微、少寐神疲、眩晕盗汗，脉虚芤弦，示正气已伤，汗脱堪虞。三类病机相互关联：气阴亏伤为根本，络脉不和为局部表现，虚风内动为进一步发展", "c": "主气阴两伤"}, {"id": "c:数+虚+芤", "n": "虚芤数脉", "o": "虚芤数脉总主阴血亏耗、阳亢虚热、冲任不固之候。虚脉主气阴不足，芤脉主失血伤阴，数脉主阳亢有热，三者相合，揭示失血伤阴为因，阴亏则阳越亢而虚热生，热势转甚又耗阴血，形成恶性循环；年逾五旬，冲任不固，八脉交损，经行则水愈亏而阳愈亢，故见腰楚怯弱、热势转甚等症。其病", "c": "主阴血亏虚"}, {"id": "c:虚+迟+芤", "n": "虚芤迟脉", "o": "虚芤迟脉总起来主精血亏耗、阳气虚衰、阴阳两虚及虚劳失精之病机。虚为正气不足，芤为血少，迟为阳衰，三者合见，反映精血阳气俱虚，故原文以'极虚芤迟'主清谷亡血失精。其下属芤弦虚迟脉合见时，则主暑湿蒸郁、气机不畅而兼血虚木郁之候，此时虚迟可因湿阻而非纯虚，须结合胸闷", "c": "主精血亏耗"}, {"id": "c:虚+小+软", "n": "虚软小脉", "o": "虚软小脉总属虚证，以血虚、气虚为本，兼夹湿滞与虚热。左脉虚软小近快，主血虚有热；右脉浮软大，主气虚湿盛。两段原文均强调“下多亡阴，血虚湿滞”，又指出病本在气虚湿滞，非纯血虚。可见虚软小脉所主病机以虚为核心：血虚失养则脉虚软小，气虚湿盛则脉浮软大，血虚阴亏、虚热", "c": "主血虚"}, {"id": "c:弦+虚+软", "n": "虚软弦脉", "o": "虚软弦脉总属正虚为本、气郁络滞为标之候。虚软主营血不足、正气亏虚，弦主肝木气陷、气机郁滞。两段所主，或营血亏虚而肝气下陷、营络窒滞，或营津久耗而气郁不舒、痰浊内阻，皆不离正虚与气郁两端。虚软定其本虚之所在，弦定其气机郁滞之标象。虚软与弦相互交织，形成正虚邪恋、", "c": "主营血不足"}, {"id": "c:弦+滑+虚+微+软", "n": "虚软微弦滑脉", "o": "虚软微弦滑脉总属虚实夹杂之候，以正虚为本、痰阻气壅为标。虚软主体气素亏，阳气不足；弦滑主痰阻清阳，气机壅塞。三者相合，提示痰热内阻而正气已伤，脉象鼓指无力，恰如原文所云‘虚软为体气素亏，弦滑为痰阻清阳，气壅塞故脉更无力’。此脉多见于素体亏虚、复感外邪或痰食内停", "c": "主痰阻"}, {"id": "c:数+虚+微+软", "n": "虚软微数脉", "o": "虚软微数脉总属正虚邪轻之候。虚软为营阴亏虚，微数为热扰之象，合而观之，主营阴不足、虚热内扰。其具体病机有四：一为营阴亏虚，脉虚软直接反映营血不足；二为暑热内扰，微数示热，但因虚软并见，热势不重；三为伏热阻络，微数主伏热，兼弦细则热阻隧络；四为妊娠气血不足，虚微", "c": "主营阴亏虚"}, {"id": "c:数+虚+软", "n": "虚软数脉", "o": "虚软数脉总属正虚为主、虚热内扰之候。虚软反映正气亏虚，或为气虚，或为营阴不足；数脉非实热，多为虚阳浮动、虚火内扰，或蕴热未清。其病机可归纳为四类：一为气虚不足，气弱不敛而似数；二为正虚邪恋，虚处受邪、蕴热内阻；三为阴血亏虚、虚火外浮，心阳过扰；四为火亢水亏，与", "c": "主气虚"}, {"id": "c:虚+涩+软", "n": "虚软涩脉", "o": "虚软涩脉总属虚实夹杂之象，以虚为本，以滞为标。虚软主气血阴阳亏虚，涩主气滞、湿停、血少。所主病机主要有四类：阳虚湿滞、气血亏虚、气滞血瘀、肝脾不和。其中阳虚湿滞与气血亏虚为虚证本质，气滞血瘀与肝脾不和为因虚致滞之标。案5021以脾肾阳虚、湿滞内停为主，案138", "c": "主阳虚湿滞"}, {"id": "c:虚+软", "n": "虚软脉", "o": "虚软脉总以“虚”为纲，软为脉道弛缓无力，主正气不足、气血阴阳亏虚。其病机大致可分：阳气虚衰，鼓动无力；气血两虚，脉道不充；脾胃虚弱，运化失健；肺肾两亏，气水失调；中气下陷，清阳不升；虚阳浮越，真寒假热；以及虚中夹邪，正虚邪恋。诸类之间，以阳气虚衰与气血两虚为根", "c": "主阳气虚衰"}, {"id": "c:虚+小+软+迟", "n": "虚软迟小脉", "o": "虚软迟小脉总属阳气不足、阴寒内盛之候。虚软主阳气亏虚，迟小主阴寒内盛，二者相合，揭示脾阳不运、水湿泛滥之病机。原文以“虚软为阳气不足，迟小为阴寒内盛”为纲，症见水肿、腹胀、溲少，故断为脾阳不运。三类病机相互关联：阳虚为根本，阴寒为病性，水湿为病理产物，共同构成", "c": "主阳虚"}, {"id": "c:虚+软+迟", "n": "虚软迟脉", "o": "虚软迟脉总属阳气不足、阴寒内盛之候。虚软主阳气亏虚，迟主阴寒内盛，二者相合，揭示脾阳不运、中焦虚寒之病机。原文以“脉不长不数”排除实热，口甜喜唾、不思饮食、胃中隐痛，皆脾虚中寒之征。三类病机相互关联：阳虚为根本，中寒为病性，脾虚为病位，总以温运脾阳为治。", "c": "主阳虚"}, {"id": "c:虚+迟", "n": "虚迟脉", "o": "虚迟脉总属正气亏虚、阳气衰微之候，以虚、迟两象合见为特征。虚主气血阴阳不足，迟主阳衰内寒，故其核心病机为虚寒与虚损。具体而言，虚迟脉所主涵盖：中阳不足、脾胃虚寒，运化失职；劳役内伤、营卫不和，渐成虚损；气血两亏、冲任不固，带下腰疼；阳衰寒盛、饮邪内停，翻胃吐冷", "c": "主虚寒"}, {"id": "s:虾游", "n": "虾游", "o": "虾游脉总属无胃气之死脉，其象冉冉而起、寻复退没、不知所在，来去无根，忽有忽无，静中忽一跃。总起来主胃气败绝、真阴耗竭、阳气浮散、命门将绝及正气欲脱等危候。诸类之间相互关联：胃气败绝为根本，胃气一亡则真脏脉见；真阴耗竭与阳气浮散常并存，阴竭则阳无所附，阳浮则阴不", "c": "主胃气败绝"}, {"id": "s:解索", "n": "解索", "o": "解索脉总属无胃气之真脏脉，其象散乱无绪、按之无根，主脏气衰败、元气涣散，为危重死候。所主病机以正气虚脱为本：或真脏气绝，或元气涣散，或胃气衰败，皆脉失冲和、根本将竭之象。其兼见数而无力者，为虚阳外浮；兼见滑数洪滑等，则为正虚邪实、痰食湿热壅闭。诸类之间，总以虚", "c": "主真脏气绝"}, {"id": "s:转豆", "n": "转豆", "o": "转豆脉总属真脏死脉，主胃气竭绝、脏气败绝，尤以心绝为直接对应。其脉来短促坚硬、旋转如豆、躁疾无从容之态，失去胃气柔和之象，故原文断为'死'。各类病机相互关联：胃气竭绝是根本，脏气败绝是整体后果，心绝则是具体脏腑定位。三者层层递进，共同说明转豆脉为危重病候、预后", "c": "主胃气竭绝"}, {"id": "c:软+和", "n": "软和脉", "o": "软和脉总起来主虚、主平、主虚寒三类病机。其核心在于「软」为柔和之象，既可属平脉之常，亦可为不足之虚脉。在平脉层面，原文谓「脉软则和」，脉得咸味滋养而和缓，属正常脉象。在虚证层面，右脉软和主脾阴不足，左脉濡细乏力主肝血亏虚，软和脉与濡细并见，共显肝脾阴血亏虚之机", "c": "主虚（脾阴不足）"}, {"id": "c:大+涩+软", "n": "软大涩脉", "o": "软大涩脉总属虚实夹杂之候，以气虚湿盛为本，湿阻血瘀为标，终致气化失司。软大主气虚而湿邪内盛，涩主湿阻血瘀、脉道不利，二者相合，提示正虚与邪实并存。原文陕客案中，体丰善啖、恣饮不禁，酒湿乘虚袭入髓窍，胞痹日久，溲从谷道点滴而渗，中有结块，皆湿浊瘀阻、气化失司之象", "c": "主气虚湿盛"}, {"id": "c:大+软+空", "n": "软大空脉", "o": "软大空脉总属虚候，以气血阴阳虚损、不相维系为根本。其脉象软大而中空，软大主气虚，空主血脱，合而示气血两虚；然虚甚则阳无所附，浮越于外，阴不内守，故又见阳气外越、阴不敛阳之机。四类病机相互关联：气虚血脱为脉象直接所主，阳浮与阴不敛阳则由虚损进一步发展而来，形成阴", "c": "主气虚"}, {"id": "c:细+大+软", "n": "软大细脉", "o": "软大细脉总起来主气虚痰湿，属虚实夹杂之候。其脉象软而无力主气虚，大而无力主痰湿内停，细软亦为气弱之征。原文以肥白人眩晕为例，指出脉软大或细软者属气虚痰湿，治当补气化痰，与滑大有力之实痰实火脉相对。此脉无实火之象，而以虚为本、痰为标，故所主病机以气虚为核心，痰湿", "c": "主气虚"}, {"id": "c:数+小+软", "n": "软小数脉", "o": "软小数脉总起来主正虚邪恋、湿热内蕴之候。软脉主正气不足、湿邪困阻，小脉主阴分受耗、脉道不畅，数脉主热邪内蒸或虚热内扰。四类病机相互关联：阴虚火旺为本虚标热之变，正虚邪恋为邪恋伤正之态，湿热氤氲为湿遏热伏之象，气营两伤为病久耗损之果。总以正虚为本，邪热为标，湿邪", "c": "主阴虚火旺"}, {"id": "c:细+小+濡+软", "n": "软小濡细脉", "o": "软小濡细脉总属虚象，主气血未复、阴津不足及病后虚损。其脉软小者，为气血亏虚、脉道不充；濡细者，为阴津耗伤、脉体失濡。原文见于大病之后，诸症虽平而脉未复常，精神疲、耳鸣，显系邪退正伤、气血阴阳俱损之候。三类病机相互关联：气血未复与阴津不足并存，共成病后虚损之整体", "c": "主气血未复"}, {"id": "c:小+濡+软", "n": "软小濡脉", "o": "软小濡脉总属虚实夹杂之象，以湿、虚、暑湿伤气为三大病机。濡主湿，软小主气血亏虚，故脉象软小而濡，既反映湿邪内阻，又提示正气不足。原文所载病例，患者素体丰肥，湿痰中虚，又冒暑贪凉，过服温热，致暑伏湿阻，暑湿伤气，故脉见软小濡，左脉沉细而弦。软小为气血亏虚、脉道不", "c": "主湿"}, {"id": "c:小+软", "n": "软小脉", "o": "软小脉总属正虚之象，以气血不足、脾胃虚弱为核心。其脉道不充故小，脉势无力故软，凡见软小，多示正气亏虚。然所主病机因兼脉与部位而异：右关软小主脾胃气虚，左脉弦细并见主肝脾同病，与濡细、濡数并见主气阴两虚，与弦大、滑数并见则成正虚邪恋，若见于体丰痰盛之人又主虚风挟", "c": "主气血两虚"}, {"id": "c:弦+大+软", "n": "软弦大脉", "o": "软弦大脉总起来主肝脾不调、湿热内蕴、阴分不足之复合病机。其脉象左右分候：右软为脾虚湿困，左弦大为肝木偏旺、阴分不足。弦大见于阴薄之体，是肝旺乘脾、湿热未清之象；软脉又主湿，故湿热内蕴亦为关键。四类病机相互关联：脾虚湿困为湿热内蕴之基础，肝旺阴亏为肝脾不调之根源", "c": "主肝旺阴亏"}, {"id": "c:数+弦+微+软", "n": "软弦微数脉", "o": "软弦微数脉总属虚实夹杂之象，以虚为本，以风热为标。软脉主正气不足或阴营亏虚，弦脉主肝风内动或木失柔和，微数主虚热内扰或风热外扬。四类病机中，虚热、营亏、肝风多属内伤，源于阴血亏虚、肝肾失调，虚热与肝风常相兼为患；风湿热则属外感余邪，风与湿合，熏蒸清窍。诸类之间", "c": "主虚热"}, {"id": "c:数+弦+软", "n": "软弦数脉", "o": "软弦数脉总属虚实夹杂、本虚标实之象。软为正气不足或湿郁，弦主气机郁滞或肝木偏亢，数示热象。合而观之，其病机核心为阴液亏虚、虚火内炽，或湿热郁久化火，或肝郁化火，或虚风内动，或正虚邪恋，或痰热内蕴。诸类之间常相互转化：阴虚火旺可致虚风内动；湿热郁火可兼痰热内蕴；", "c": "主阴虚火旺"}, {"id": "c:弦+软", "n": "软弦脉", "o": "软弦脉总属虚实夹杂、本虚标实之象。软为正气不足、气弱湿滞或阴血亏虚，弦为肝木偏亢、气机郁滞、饮停或风动。合而观之，其核心病机以正虚为本、郁滞为标：虚在气、阴、血、脾、肾，实在肝郁、痰饮、湿浊、郁热、虚风。各类之间常相互转化：脾虚湿盛可致饮停，肝郁化火可致郁热，", "c": "主虚（气阴两虚）"}, {"id": "c:滑+弱+软", "n": "软弱滑脉", "o": "软弱滑脉在此案中并非单一脉象，而是复合脉，总起来主脾虚湿盛、痰湿食积内蕴，兼有郁热与脾肾阳虚。其核心病机为脾气虚弱，运化失职，饮食不消，湿浊内停，聚为痰湿食积，阻滞气机，郁而化热，故两寸关见滑数；久病及肾，阳气不足，故两尺沉微。滑数主痰湿食积与郁热，沉微主脾肾", "c": "主痰湿食积"}, {"id": "c:细+小+弱+软", "n": "软弱细小脉", "o": "软弱细小脉总属虚证，主气血两虚、气虚劳伤。其脉象软弱无力、细小如绵，反映正气不足，脉道不充。具体而言，左脉细弱主肝肾气虚，右脉细软主脾肺气弱；尺脉如绵提示气血两虚。若弱而和缓，为胃气尚存，补之可生；弱而带数，则虚热内生，补之难效。此外，正虚之处易容邪气，如原文", "c": "主气血两虚"}, {"id": "c:弱+软", "n": "软弱脉", "o": "软弱脉总属虚象，以气血不足、阳气不振为基本病机，脉道失充、鼓动无力故脉来软弱。其主病虽繁，约分六类：气血两虚为总纲，脾虚湿困、阳虚阴损、脏腑亏虚皆虚损之具体表现；气虚不摄为虚而失固之变；虚中夹邪则为正虚邪恋之兼证。各类之间相互关联：气血虚可致脏腑亏，脏腑虚可生", "c": "主气血两虚"}, {"id": "c:虚+弱+软", "n": "软弱虚脉", "o": "软弱虚脉总属虚象，尤以脾胃气虚为核心。原文“右脉软弱为虚”直接点明其主虚，且右关候脾胃，故软弱脉多反映中气不足、脾胃虚弱。在疟痢并作等复杂病证中，软弱脉可与实象并见，形成虚实夹杂之局，如右关大主腑实，右脉软弱主虚，治疗需攻补兼施。因此，软弱虚脉所主病机以虚为主", "c": "主脾胃气虚"}, {"id": "c:弦+微+软", "n": "软微弦脉", "o": "软微弦脉总属虚实夹杂之象，以虚为本，以郁为标。软脉主正气不足、气虚湿困，微弦主气机郁滞、肝木偏亢。归纳其病机主要有四类：一为气虚湿困，湿郁痰滞，见腹中不舒、便溏头蒙；二为脾虚木乘，土虚肝亢，见足肿神疲、胃呆畏寒；三为气郁痰滞，痰气窒塞，发为流痰、络脉失养；四为", "c": "主脾虚木乘"}, {"id": "c:微+软", "n": "软微脉", "o": "软微脉总属虚证，以阳气衰微、气弱为本，或兼阴血不足、气营两亏，或虚阳上浮，或正虚感邪。其脉象由微、软复合而成，微主阳衰，软主气弱，故总以正虚为核心。各类病机之间相互关联：阳衰气弱可进一步导致气营大亏；阳气虚衰，虚阳失于依附则上攻；正气虚馁，卫外不固则易感外邪。", "c": "主阳衰气弱"}, {"id": "c:软+散", "n": "软散脉", "o": "软散脉总起来主气实血虚、心火散漫及神志浮越、精气不敛之病机。其脉软散，反映脉道失于敛束与充盈，或由气机壅实而血分不足，或由心火亢盛散越，或由神志浮越、精气不能内守。各病机之间相互关联：气实血虚可致心火散漫，心火散漫又可扰动神志，而神志浮越、精气不敛则进一步加重", "c": "主气实血虚"}, {"id": "c:数+软+平", "n": "软数平脉", "o": "软数平脉总属虚实夹杂之象，以气阴虚、脾肾不足为本，以风湿化热为标。软脉主气阴亏虚，数脉主虚热内生，右关欠调则脾运不健，此三者构成病本；而眩晕为风、便溏为湿，风湿合化，虚热自生，又见腰胯跳痛、鸣而作堵等标症。故其病机可归纳为：本虚（气阴虚、脾肾不足、脾运不健）与", "c": "主气阴虚"}, {"id": "c:数+软+空", "n": "软数空脉", "o": "软数空脉总起来主阴虚火旺与正虚邪盛两类病机。脉软为阴虚，数为火旺，空为精血不足，故见水亏火旺、阴液耗伤之证；若数而空软并见，数主热，空软主正气虚衰，则反映邪热未清而正气已虚，正虚不能胜邪之局。两者均以空软为本，数脉为标，提示虚中夹实、本虚标实之候，临床须权衡虚", "c": "主阴虚火旺"}, {"id": "c:数+软", "n": "软数脉", "o": "软数脉总以虚热为纲，软主正气不足或阴液亏虚，数主有热，合而多见虚热内扰之候。其病机大致可分：虚热、气阴两虚、阴虚火旺、痰热湿郁、脾虚湿滞、正虚邪恋、虚风内动。诸类之间常相互转化：气虚及阴则气阴两虚；阴亏火旺可致虚风内动；脾虚湿滞郁久化热则成湿郁痰热；正虚邪恋日", "c": "主虚热"}, {"id": "c:数+软+长", "n": "软数长脉", "o": "软数长脉总起来主湿热火升之实证，非虚损之候。其脉软为湿，数为热，长为有余，合而示湿热内蕴、火热升腾。具体可表现为湿热壅盛、劳力火升，或湿火下注而成带下等症。原文两案皆以猪肚丸清湿火取效，并反复告诫‘软数而长亦非虚’，‘脉不主虚，不可误’。故本脉所主病机以湿热、", "c": "主湿热"}, {"id": "c:涩+软", "n": "软涩脉", "o": "软涩脉总属虚实夹杂之候，以虚为本，以滞为标。软为气虚不充、阳气式微或湿邪内盛，涩为血少气滞、脉道不利。所主病机可归纳为虚、滞、热、湿、郁、暑六类：虚为气血阴阳亏虚，滞为气滞血瘀，热为热伏于内，湿为湿阻气机，郁为肝郁气逆，暑为暑湿外侵。诸类之间，虚为根本，因虚而", "c": "主热伏"}, {"id": "c:数+滑+微+软", "n": "软滑微数脉", "o": "软滑微数脉总起来主阴亏、痰饮、内热三者交织为病。软脉主阴液亏虚，滑脉主痰饮内盛，微数脉主阴虚内热，三者相合，正合“阴亏痰热”之病机。原文三段落均见于产后发热案，患者素体阴亏，新产血去则阴愈亏，阴虚生内热故脉数而微；痰饮内盛故脉滑；阴亏脉道不充故脉软。痰热内蕴则", "c": "主阴亏"}, {"id": "c:滑+微+软+长", "n": "软滑微长脉", "o": "软滑微长脉总起来主痰热内蕴、热伏阳明，兼示气机尚存。软滑为痰热之征，微长则反映正气未绝、气机尚能舒展，故非虚劳之脉。三者相互关联：痰热内蕴是病机核心，热伏阳明是病位所在，气机尚存则提示病属实证或虚实夹杂，而非纯虚。临床见脉软滑微长，伴暮热、鼻衄、溲浑、苔淡黄不", "c": "主痰热内蕴"}, {"id": "c:数+滑+软", "n": "软滑数脉", "o": "软滑数脉总以痰热为纲，兼见湿、暑、虚、火之变。滑主痰，数主热，二者相合为痰热内蕴之基本脉象；软则示正气不足或阴液亏乏，故本脉多属邪实正虚、虚实夹杂之候。其类可分：痰热内扰，症见讝语烦懊、咳嗽痰白；湿热内蕴，症见肛痔溲闭、苔腻腹胀；暑湿痰热交阻，见于盛暑患疟、神", "c": "主湿热"}, {"id": "c:滑+软+疾", "n": "软滑疾脉", "o": "软滑疾脉总起来主痰、风、热、虚四者杂合为病，属本虚标实之候。其脉软滑，为脾湿蒸痰、痰浊内蕴之象，兼示精气内虚；时带劲疾，则为风邪内动、热势鼓激之征。原文断为痰与风杂合、内热与外寒杂合之症，因膏粱蕴热，久蒸脾湿为痰，痰阻窍隧，卫气不周，外风易入；又房帏不节，精气", "c": "主痰湿内蕴"}, {"id": "c:滑+软", "n": "软滑脉", "o": "软滑脉总以痰湿内蕴、正气不足为纲。滑主痰，软主虚（气虚、湿盛或阴伤），故本脉多属虚实夹杂之候。其类可分：痰湿内蕴，症见咳嗽痰多、胸痞呕恶；气虚正伤，症见神疲昏倦、语言错乱；阴液亏虚，症见阴伤浊泛、虚多实少；脾虚湿盛，症见浮肿、二便不畅；正虚疟邪，疟久正虚而痰湿", "c": "主痰湿内蕴"}, {"id": "c:滑+虚+软", "n": "软滑虚脉", "o": "软滑虚脉总属正虚与痰浊并存之候，以虚为本、痰为标。其虚多责之肺脾气阴不足，故见软而虚；滑则主痰浊内蕴，或为燥伤津液、痰浊内生。若兼弦数，则示风阳内动，多因辛温误治而致。四类病机相互关联：正虚则津液不布，聚而为痰；痰浊内阻，又耗伤气阴；阴虚风动，风阳挟痰上扰。故", "c": "主虚"}, {"id": "c:软+短", "n": "软短脉", "o": "软短脉总起来主气机郁滞与虚损两类病机，具体涉及气郁、气虚、肝血不足、脾虚湿热四类。软为气虚，短主气郁，故脉软短首先反映气虚推动无力、气机郁滞之候，如疹邪透发而营络郁滞；又因金燥木枯、肝血不足，筋急牵引而脉道失养，或脾虚湿热不攘，筋脉软短，肌肉不仁，发为口眼㖞斜", "c": "主气郁"}, {"id": "c:软+空", "n": "软空脉", "o": "软空脉总起来主阳气衰微、下元虚竭，以及由此导致的虚阳外越和正虚邪闭之证。其脉象以软为阳气无力鼓动，以空为肾精下竭、脉道不充，尺部空豁尤为下元虚惫之明证。从原文“脉软尺空”与“面赤戴阳、肢冷自汗”并见来看，软空脉所主病机以阳气衰微、肾阳下竭为本，虚阳外越为标，而", "c": "主阳衰"}, {"id": "c:缓+软", "n": "软缓脉", "o": "软缓脉总起来主虚，尤以气虚、脾虚为核心，兼夹湿邪、血虚、阳虚等。其脉象柔软弛缓，反映正气不足、鼓动无力，故虚证见之为顺，实证见之为逆。各类病机之间相互关联：气虚与脾虚互为因果，脾虚生湿，湿盛困脾；湿邪外袭可致痿痹；血虚与脾虚亦相互影响，气血生化不足则筋脉失养；", "c": "主气虚"}, {"id": "e:软", "n": "软脉", "o": "软脉总以'虚'为纲，主正气不足、气血阴阳亏虚，脉道弛缓无力为其核心特征。所主病机虽繁，约分六类：气虚阳弱为基本，气血两虚为脉道失充之由，脾虚湿困为虚而兼湿之变，虚中夹邪为正虚邪恋之兼证，虚风内动为阴血亏虚之变，虚阳浮越为阳衰不守之候。各类之间相互关联：气虚阳弱", "c": "主气虚阳弱"}, {"id": "c:软+迟+和", "n": "迟和软脉", "o": "迟和软脉总主虚寒，以迟为寒、软为虚，合而反映中气虚弱、寒邪内生的病机。具体而言，其主病机可分三类：一为中气虚弱之虚寒，见不能多食，治宜温中健脾；二为寒伤太阴之寒盛阳衰，见腹冷如冰，治宜温阳散寒；三为寒积实滞之寒实内结，虽脉迟软而证属实滞，治宜攻下。三类之间以虚", "c": "主虚寒"}, {"id": "c:迟+坚", "n": "迟坚脉", "o": "迟坚脉总起来主寒实内结与痈脓未成两类病机。迟主寒，坚主实，二者相合，表明寒邪与实邪（食积、气滞、血凝）互结于内，非单纯虚证。在肠痈病中，脉迟坚提示热未蒸腐、脓未成，可与脉数对举判断脓成与否。两类病机相互关联：寒实内结为病本，痈脓未成为病势阶段，均以坚大迟脉为凭", "c": "主寒实内结"}, {"id": "c:大+小+迟+长+短", "n": "迟大小长短脉", "o": "迟大小长短脉所主病机，总以脉与形性相应为吉、不相应为凶为纲。具体可分四类：形性相应为常度；伤寒热盛脉浮大主邪实外达；汗后脉沉小主正伤而宜静敛；温病脉细小难得主正虚邪陷。四类之间，以‘相应’为吉凶判断核心：脉与体质、病期相符则生，反之则死。迟大小长短之象，须结合", "c": "主形性相应"}, {"id": "c:小+弱+迟", "n": "迟小弱脉", "o": "迟小弱脉总属虚寒之象，主阳气不足、阴寒内盛。其脉迟为寒，小弱为虚，合而观之，反映机体阳气衰微，尤以脾胃阳虚为核心。原文以“脉迟小弱皆不可用”苦寒之黄芩为戒，强调虚寒者误用苦寒则更伤脾胃阳气，故此类脉所主病机以虚寒、脾胃阳虚为主。两类病机相互关联，虚寒为总纲，脾", "c": "主虚寒"}, {"id": "c:涩+小+迟", "n": "迟小涩脉", "o": "迟小涩脉总属脉道不利、气血运行迟缓之候，所主病机可归为三类：一为阳伤湿结，因中虚嗜酒、湿浊内聚，寒湿浊阴鸠聚为痛；二为湿阻阳郁，湿邪黏滞困阻气机，脉道不充而涩滞；三为阳盛伤阴，阳热亢盛灼伤阴血，脉小迟涩而兼缓象，见于奇恒痢等危重证。三者虽病因有寒湿、湿热、阳热", "c": "主阳伤湿结"}, {"id": "c:弦+滑+迟", "n": "迟弦滑脉", "o": "迟弦滑脉总起来主气机壅滞、木郁克土、痰食内停之病机。迟为气机壅滞，弦主木郁克土，滑为水谷壅闭成痰，三脉并见，反映思郁结而气陷于土，脾不升胃不降，致水谷之海壅闭，不通则痛。三类病机相互关联：气滞为始动因素，木郁克土为关键环节，痰食壅闭为病理产物，共同构成木郁土壅", "c": "主气滞"}, {"id": "c:弦+涩+弱+迟", "n": "迟弱弦涩脉", "o": "迟弱弦涩脉总属虚实夹杂之候，以阳虚为本，痛、饮、瘀滞为标。迟弱反映阳气虚衰，温运无力；弦为痛为饮，提示气机不畅、饮邪内停；涩为血瘀湿滞，表明久病入络、湿瘀互结。三者相合，常见于久痛阳虚、湿饮瘀血交阻之证。各病机之间相互关联：阳虚则运化失职，湿饮内停，久痛入络则", "c": "主阳虚"}, {"id": "c:弱+迟", "n": "迟弱脉", "o": "迟弱脉总属虚寒之象，以阳气不足、气血亏虚为基本病机。迟主阳虚寒盛，弱主气衰血少，二者相合，多主虚寒、营卫俱虚、中虚痰湿、大气下陷及气血亏虚等证。各段原文显示，迟弱脉可见于肾阳亏虚、脾肾虚寒、营卫俱虚、中虚痰湿内盛、胸中大气下陷、气血不足脑失所养等多种病机，其共", "c": "主阳虚寒盛"}, {"id": "c:微+涩+迟", "n": "迟微涩脉", "o": "迟微涩脉总起来主虚寒之证，尤以胃虚寒呕为核心。迟主寒、主阳气不振，微涩主气血虚少、脉道不畅，三者相合，反映阳气虚弱、寒从中生、气血不足之病机。原文以呕吐为例，脉迟而微涩者属胃虚寒，症见恶食、恶寒、朝食暮吐；与脉洪大而数之胃中郁热积滞形成鲜明对比，判然两途。故迟", "c": "主虚寒"}, {"id": "c:数+大+迟", "n": "迟数大脉", "o": "迟数大脉总起来主寒热虚实及气机升降失常。数脉主热，迟脉主寒，此为常理；然迟脉亦可因大气下陷而现，非独寒也。大脉主邪盛或虚阳外浮，与迟数合参，可辨寒热错杂、虚实夹杂之证。诸脉所主，以寒热为纲，兼顾气陷、虚损等病机。各类之间相互关联：热盛则数，寒盛则迟，气陷则迟而", "c": "主热"}, {"id": "c:数+迟", "n": "迟数脉", "o": "迟数脉总以辨寒热为纲，迟主寒、数主热是其常理。然临床所见，迟脉亦可因大气下陷而现，非独寒也；数脉多主热盛，热盛易伤阴，故数脉又常示热盛阴伤。迟数并见或乍迟乍数，则反映寒热错杂、虚实夹杂，如气陷兼伏热、虚损而火升。若脉来乍数乍疏乍迟乍疾，则为脉律败乱、阴阳离绝之", "c": "主寒热"}, {"id": "c:洪+迟+实", "n": "迟洪实脉", "o": "迟洪实脉在此段中并非单一脉象，而是对迟、洪实、数等脉的辨析。总起来看，洪实有力主里实热结，为承气汤可下之证；脉数主热盛阴伤，须先治其数；脉无力则主正虚，下之易致虚脱。三类病机相互关联：里实热结可致洪实，热盛伤阴则脉数，正虚不足则脉无力。临床须辨脉之有力无力及至", "c": "主里实热结"}, {"id": "c:浮+弱+迟", "n": "迟浮弱脉", "o": "迟浮弱脉总起来主表虚里寒、脾虚湿郁及中虚气逆之病机。浮弱为表虚，迟为里寒，合之示表虚里寒，故见恶风寒、手足温；若误下伤中，脾虚运化失职，湿郁发黄，则见不能食、胁下满痛、面目及身黄、小便难；中虚气逆，则见饮水而呕、食谷者哕。三类病机以里虚为核心：表虚里寒为初始病", "c": "主表虚里寒"}, {"id": "c:涩+迟", "n": "迟涩脉", "o": "迟涩脉总由阳气不运、气血滞涩而成。迟主寒、主阳虚、主气机凝滞；涩主血少、主气滞、主瘀阻。合而观之，其病机可归纳为寒凝气滞、阳虚不运、湿滞痰阻、食积内停、血瘀内蓄、气血亏虚、邪伏膜原七类。其中寒凝、阳虚、湿滞、食积多因阳气被遏或不足，导致气机不畅、脉道不利；血瘀", "c": "主寒凝气滞"}, {"id": "c:滑+迟", "n": "迟滑脉", "o": "迟滑脉总以迟主阳弱、寒滞或实阻，滑主痰湿、宿食或实热，合而主痰饮、虚寒、积实三类病机。其常者为中虚寒痰、痰饮内停，因阳气不足，痰湿不化，脉道失温而迟，痰湿内盛而滑，多见于咳嗽失血、脘痛呕吐等证。其变者为内实积滞、寒实内结，因实邪壅遏，气血不畅，脉迟非虚，滑主实", "c": "主中虚寒痰"}, {"id": "c:数+濡+迟", "n": "迟濡数脉", "o": "迟濡数脉总起来主邪伏不达、热传血室、湿浊内蕴、气机壅塞之复杂病机。其中“迟”主邪阻气机、脉道不利；“濡”主湿浊内蕴；“数”主热郁化火。三者并见，说明邪气伏藏不达，热邪传入血室，与血相结形成痞块，同时湿浊内阻，气机壅塞，故见脘腹膨胀、小溲不利、气粗吸短等症。病涉", "c": "主邪阻气机"}, {"id": "c:迟+疾", "n": "迟疾脉", "o": "迟疾脉在此段总起来主营卫失调、阴阳升降失常及风寒外中三类病机。其核心在于脉来迟数不匀，反映营卫运行失度、阴阳升降乖逆。营卫迟数不谐是基础，进而导致阳不降、阴不升的气机紊乱；若外邪乘虚而入，风寒中于营卫，则阴阳相争，寒栗相搏而发为疟。三者相互关联：营卫失调为内在", "c": "主营卫失调"}, {"id": "c:迟+空", "n": "迟空脉", "o": "迟空脉总属阳气虚衰、脉道不充之象。迟主阳微，空主脉道空虚，二者相合，反映中下焦阳气虚弱，温运失职。阳气不足则水湿不化，暑湿等外邪易内困，形成阳虚湿困之证。临床可见体倦、肤黄、足软、舌白等症。其病机以阳虚为本，湿困为标，虚实夹杂。治疗当以扶阳为主，兼以理湿，使阳", "c": "主阳虚"}, {"id": "c:大+紧+迟", "n": "迟紧大脉", "o": "迟紧大脉总起来主寒实内结、邪实壅盛之病机。迟主寒，紧主寒凝劲急，大示邪实壅盛，三脉相合，多属寒邪为患而正气未虚。其具体所主，或为寒邪外束、肺气闭郁（如案2寒客会厌致卒然无音），或为寒实内结心下（如“紧大而迟者，必心下坚”），或为阳中有阴、寒实可下之证（如“脉大", "c": "主寒凝"}, {"id": "c:紧+迟+急", "n": "迟紧急脉", "o": "迟紧急脉总起来主寒凝、阳虚、饮停之病机。迟主阳虚寒凝，紧主寒实内结，里急示寒饮停聚、气机壅塞。三者相互关联：阳虚为寒凝之根，寒凝又致饮停，饮停更伤阳气，形成表虚里寒、寒饮内结之候。原文表解后复中，恶寒胸结，舌苔厚白，脉迟紧里急，正是寒邪内陷、阳气不振、寒饮停聚", "c": "主寒凝"}, {"id": "c:紧+迟", "n": "迟紧脉", "o": "迟紧脉总属寒、瘀、痛之象。迟主阳微、寒凝，紧主寒束、痛、实，二脉相合，多示寒邪内盛、气血凝滞。其所主病机可归为五类：寒凝、瘀血、痈脓未成、寒痛、阳衰。其中寒凝为基本病机，寒凝则血滞成瘀，瘀血内停则作痛，寒瘀交阻则痈脓未成；阳衰则为寒凝之甚。诸类相互关联：寒凝可", "c": "主寒凝"}, {"id": "c:细+迟+伏", "n": "迟细伏脉", "o": "迟细伏脉总起来主正虚，包括阴血不足与阳虚寒盛，并可导致毒邪内陷。脉沉细而耎，沉主里，细耎为阴血不足，正虚毒陷，故见疽形平塌、溃脓无多、不痛楚之阴证；继则脉迟细欲伏，迟细为阳虚，欲伏为阳气欲脱，伴面青肢冷、呕恶频频，乃阴寒内盛、阳气衰微之候。三类病机相互关联：阴", "c": "主阴血不足"}, {"id": "c:细+微+迟", "n": "迟细微脉", "o": "迟细微脉总起来主虚寒之证，以阳气衰微、阴寒内盛为核心病机。迟主寒，细主虚，微主阳气衰微，三脉合见，反映气血不足、脏腑虚寒。其具体所主包括气血虚寒、脾胃虚寒、寒痰结胸、阴寒内盛等，各证之间相互关联：气血虚寒为基本病机，脾胃虚寒为常见脏腑定位，寒痰结胸为寒凝痰阻之", "c": "主虚寒"}, {"id": "c:细+涩+迟", "n": "迟细涩脉", "o": "迟细涩脉总起来主寒凝、气滞、血瘀与虚损相兼为病。迟主阳郁或阳衰，细主气少血虚，涩主气机壅滞或血瘀。三者相合，多示寒邪凝结、阳气不宣，或气机闭郁、肺金实而无声，或血虚兼瘀、血不归经。各案虽病位不同，或在心胸，或在肺金，或在肝血，但共同病机为寒、虚、滞、瘀交织，导", "c": "主寒凝阳郁"}, {"id": "c:细+迟", "n": "迟细脉", "o": "迟细脉总属虚寒之象，以阳气不足、阴寒内盛为核心。迟主寒、主阳虚，细主虚、主血少，二者合见，多示气血虚寒、脏腑阳衰。其具体所主，或为阳虚寒盛，或为气血虚损，或为寒积内结，或为寒湿痹阻，或兼痰瘀互结，或见真寒假热，或阴亏阳逆。诸类之间，以虚寒为共同基础，而兼夹邪气", "c": "主阳虚寒盛"}, {"id": "c:小+缓+迟+促", "n": "迟缓小促脉", "o": "迟缓小促脉总起来主脾肾虚寒、中气衰败、寒湿下注之证。其中‘迟缓’侧重虚寒本质，‘小促’侧重中气衰惫、脉行不畅，二者合见则揭示病本在中气衰败、脾肾阳虚，寒湿因而下注。原文两段均以右膝肿痛而色不赤、食少辄呕为伴症，并强调‘和养中气为要’，说明此脉所主以中气衰败为核", "c": "主虚寒"}, {"id": "c:微+缓+迟", "n": "迟缓微脉", "o": "迟缓微脉总起来主阳气衰微、气血虚衰之证，其脉象迟缓为脉气壅滞或从容不迫，微为阳气无力鼓动。所主病机主要有五类：一为元阳大虚，治宜挽救阳气；二为阳衰寒饮，心阳薄弱，寒饮凌心；三为气血虚衰，多见于失血之后；四为燥热内伏，阻滞阳气外达，身反不热；五为邪退正复，见于痈", "c": "主元阳大虚"}, {"id": "c:涩+缓+迟", "n": "迟缓涩脉", "o": "迟缓涩脉总属阳微血少、湿滞脉道之候，其病机可归纳为脾阳虚、营血耗、湿动中焦、阳盛伤阴及邪退正复五类。前两类常并见于久痢，脾阳失运则脉迟缓，营血耗伤则脉涩，湿动中焦更助缓象，三者相互关联，共成虚实夹杂之局。阳盛伤阴一类，脉虽缓小迟涩似虚寒，实由阳热灼阴、脉道不利", "c": "主脾阳虚"}, {"id": "c:缓+迟", "n": "迟缓脉", "o": "迟缓脉总以迟主寒、缓主虚为纲，然所主病机非止一端。其常者，阳气不足、脾肾虚寒，或湿浊内凝、痰饮壅滞，或营卫虚而亡血中风，皆以虚寒为本、滞涩为标。其变者，邪气内伏、燥矢在胃、暑湿痰热壅遏气机，脉道不利而反见迟缓，此非虚寒，乃邪深壅遏之象，最易眩人。又有缓迟相合、", "c": "主虚寒"}, {"id": "e:迟", "n": "迟脉", "o": "迟脉总以阳气不足、阴寒内盛为基本病机，脉行迟慢是其共同特征。然所主非止一端：寒邪外客或内踞，凝滞气机，脉道不利而迟，此为'主寒'；阳气虚衰，推动无力，此为'主阳虚'；阳虚与寒盛并存，则为'主虚寒'。寒湿痰饮内停，遏阻气机，脉亦迟，此为'主寒湿痰饮'；寒凝气滞，", "c": "主寒"}, {"id": "c:迟+芤", "n": "迟芤脉", "o": "迟芤脉总起来主阳虚失血、下元虚寒及气血两虚之病机。迟脉主阳虚，芤脉主失血，两尺不堪重按提示下元虚寒。本例下血二年，阴损及阳，气不摄血，故见夜间下血、腹疼、不寐，服温补下元药稍轻，终致身体羸弱。三类病机相互关联：下元虚寒为根本，阳虚不能摄血导致失血，久失血则气血", "c": "主阳虚失血"}, {"id": "c:细+虚+迟", "n": "迟虚细脉", "o": "迟虚细脉总属阳气虚弱、气血不足之候，其核心病机为虚寒与气血亏虚。迟主阳虚内寒，虚细主气血两亏，三者相合，反映正气内虚、阳运无力。在此基础上，若兼外邪内伏，则形成本虚邪伏之证，如本案哮喘五年、风寒蕴伏肺底，脉迟虚细即示正虚邪伏。三类病机相互关联：阳虚与气血虚为根", "c": "主阳虚"}, {"id": "c:软+迟", "n": "迟软脉", "o": "迟软脉总属虚象，以阳气衰微、气虚无力为基本病机。迟主阳衰、主寒、主运迟，软主气虚、主正弱，二者相合，轻则气虚阳弱、健运迂迟，重则阳气欲脱、内闭外脱。其类可分：主阳虚，见四末渐冷、神昏肢冷；主气虚，见便秘、小溲多、肩臂酸麻；主虚寒，见畏寒、不食不便、苔灰腻；主阴", "c": "主阳虚"}, {"id": "s:釜沸", "n": "釜沸", "o": "釜沸脉总属真脏脉，主胃气已绝、阳气暴脱、阴阳离决之危候。其脉来如釜中沸水，无根无绪，失去胃气之柔和，故非寻常病脉。原文见于少阴病下利脉微而暴出之时，与雀啄脉并见，主死。三类病机相互关联：胃气绝则脉无胃气，阳气暴脱则虚阳外越，阴阳离决则脉象浮沸无根，皆属预后不良", "c": "主胃气绝"}, {"id": "c:数+大+长", "n": "长大数脉", "o": "长大数脉总起来主邪热亢盛之证。其脉长大数躁，长主气有余，大主邪盛，数主热，躁主热极，诸象相合，反映热邪炽盛，正气未衰，正邪交争剧烈。原文载服热药益甚而见此脉，断为阳明热炽，宜大剂白虎，有下证佐承气，可知此脉所主以实热为核心，尤以阳明经腑热盛为典型。两类病机中，", "c": "主热盛"}, {"id": "c:大+长", "n": "长大脉", "o": "长大脉总起来主邪实壅盛、气机壅滞之象，以长主气有余、大主邪盛为核心。其病机有常有变：常者为湿土当令之缓大长脉，从容宽大而长，非病脉；变者则分虚实。实者或为邪热亢盛，气血涌盛，见于阳明热炽、胃热上蒸、厥阳上燔；或为积块内结，积气成形，脉大而长且搏指；或为气分壅实", "c": "主邪热壅盛"}, {"id": "c:大+实+长", "n": "长实大脉", "o": "长实大脉总属邪实壅盛之象，以阳明内实、燥热内结为核心病机。其脉长主气机壅滞，实主邪气盛，大主热势张，三者相合，反映邪热与燥屎相搏结于阳明，腑气不通。由此可致腑实可下之证，亦因腑气不降而见胃气上逆之呃逆。三分类中，“主邪热内结”为病机本质，“主腑实可下”为治疗指", "c": "主邪热内结"}, {"id": "c:实+长", "n": "长实脉", "o": "长实脉总起来主邪实壅盛、热盛及阳明实热，其核心病机为邪热内结、气机壅滞。脉长主气机壅滞，实主邪气盛，大主热势张，三者相合，反映邪热与燥屎相搏结于阳明，腑气不通，可致腑实可下之证及胃气上逆之呃逆。洪长实脉则侧重热盛、邪实与阳明实热，因热邪亢盛、气分热炽，可上攻而", "c": ""}, {"id": "c:小+长", "n": "长小脉", "o": "长小脉在古籍中仅见此一段，且原文“脉长强”之“脉”实连属穴名，非脉象，故其脉学依据有限，须结合所主诸穴互参。总起来看，本脉以小儿惊痫为核心，兼及风动抽搐、吐泄、惊恐失精、腹满食少诸候。其病机根本在于小儿神气未充、风痰易扰，肝风内动则惊痫瘛疭、反视口噤；风痰扰中", "c": "主惊痫"}, {"id": "c:弱+长", "n": "长弱脉", "o": "长弱脉总以“长长而弱，来疏去穊”为象，首主脾之平脉，体现脾土柔和、胃气冲和之常。其“长”示胃气充盈，“弱”示脾土不刚，故又主胃气调和之生理状态。然原文以至数分平、病、死，若至数失常（三至以上），则长弱之象转为胃气衰败、病深危重之征，故兼主病深。三类关系以平脉为", "c": ""}, {"id": "c:数+长", "n": "长数脉", "o": "长数脉总起来主邪热亢盛、邪实有余之证。长为气有余、邪气壅滞不散，数为热，二者相合，以实热为核心，非虚损之候。其具体所主，可因兼脉与病位不同而分：兼大而躁者，主邪热亢盛、阳明热炽；兼洪者，主热盛邪实、疫毒壅盛；兼弦者，主肝木亢盛、气火冲逆；兼滑者，主痰热实邪壅滞", "c": "主湿热"}, {"id": "c:沉+涩+长", "n": "长沉涩脉", "o": "长沉涩脉由长、沉、涩三象复合而成。原文以浮沉长短滑涩分阴阳，长属阳，沉涩属阴，故列为一阳二阴之脉，主阳多阴少、阴阳兼夹之病机。长脉示阳气有余或气机伸展，沉脉示病位在里，涩脉示血行不畅或阴寒凝滞。三象合观，总以阳气偏胜而阴分受遏、阳郁阴凝、阴阳错杂为要。其病机非", "c": "主阳多阴少"}, {"id": "c:沉+长", "n": "长沉脉", "o": "长沉脉总属沉取见长之复合脉，其总病机以里实、阳盛、热瘀为主，兼及肝郁。右长左沉示气分热盛而血分瘀滞，为瘀热在里；沉数长主里热壅盛；长沉涩为一阳二阴，主阳盛阴遏；沉滑长为阳多阴少；沉长弦则关乎肝郁魂越。诸类之间，或为热邪内陷血分，或为里热亢盛，或为阳气偏胜而阴受", "c": "主瘀热在里"}, {"id": "c:细+大+长+短", "n": "长短细大脉", "o": "长短细大四脉总括气机畅促与正邪盛衰。长脉气畅为平，短脉气促为病，细脉正虚气少，大脉邪盛病进。四者从不同维度反映病机：长短辨气之通塞，细大辨正邪之强弱。长与短相对，细与大相对，共同揭示气机运行状态与正邪斗争态势。其中长脉属平，余三者皆主病，短、细偏于气机不利与正", "c": "主气畅"}, {"id": "c:长+短", "n": "长短脉", "o": "长短脉在原文中与弦脉并列，明确指出“三脉不在四部设”，即不隶属于浮沉迟数四纲分类体系。浮沉迟数分别统摄表里寒热之脉，而长短脉不在此框架内，说明其所主病机不能简单归入表里寒热虚实之单一维度。长脉主气机有余、亢盛或邪实壅滞，短脉主气机不足、郁滞或痰食内阻，二者均反", "c": "主气机失调"}, {"id": "c:长+硬", "n": "长硬脉", "o": "长硬脉总起来主气机逆乱、火盛阴亏之证，以肝、胃、冲脉气火上逆为核心。其脉长主气逆有余，硬主劲急亢盛，故凡见长硬，多示脏腑气化有升无降，气血随之上冲。就所主病机而言，可分四端：一为肝火炽盛，火性上炎而脉道劲急；二为冲胃之气上逆，气逆不降而脉见长硬；三为血随气升，", "c": "主肝火上逆"}, {"id": "e:长", "n": "长脉", "o": "长脉总起来主气机充畅、阳气有余，其病机有常有变。常者为胃气充盛之平脉，长而和缓，主气治无病；变者以气盛阳亢为核心，或为热盛阳明、气血涌盛，或为肝郁气逆、阳升不降，或为寒湿积气搏结、脉道劲急，或为胃气壅滞、痰气交阻，或为邪实壅盛、正气抗邪。诸类之间，总以“气”为", "c": "主气盛阳亢"}, {"id": "s:雀啄", "n": "雀啄", "o": "雀啄脉总属无胃气之真脏死脉，其来三五不调、止而复作，如雀啄食，核心病机为胃气败绝、元气虚脱、阴竭阳越、脏气衰绝，预后多凶。然亦有一类因气机壅闭、脉道阻隔而现雀啄之象者，如湿热误补、情志不遂致气分阻隔，脉虽似雀啄而重按有力，非纯虚候。诸类之中，胃气败绝为根本，元", "c": "主胃气败绝"}, {"id": "e:革", "n": "革脉", "o": "革脉总主虚寒相搏、气血虚极、阴阳离绝之候。其脉外急中空，如按鼓皮，为病脉中之险脉。各类病机相互关联：虚寒相搏为基本病机，因阳气虚衰，阴寒内盛，气血不充，脉道失养而外强中空；气血虚极则精血亏耗，脉道空虚，气无所附；亡阳危候则阳气浮越欲脱，脉失根柢；阴阳离绝则气血", "c": "主虚寒相搏"}, {"id": "s:鱼翔", "n": "鱼翔", "o": "鱼翔脉总属危候死脉，其核心病机为元气将绝、胃气衰败、阴阳离决，本质是脏腑真气败绝、真脏脉见。各段原文多强调'脉无胃气''真藏脉见''形脉俱败'，故其主病以虚脱竭绝为主。然亦有因邪热炽盛、阴液涸竭而致脉见鱼翔者，如许自堂孙案，热盛阴伤、元气欲溃，脉数而鱼翔，说明", "c": "主元气将绝"}];